MultiLanguageQuestData['de'][28076] = {title = "Abenteurer gesucht: Der Norden Düsterbruchs", objective = "Sprecht mit dem Druiden der Kralle.König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich in den nördlichen Teil Düsterbruchs östlich der Mondfederfeste zu reisen!\n\nKönig Gordok und seine wachsende Armee der Oger der Gordok stellen in der Gegend die größte und mächtigste Bedrohung für uns dar! Falls Ihr interessiert seid, begebt Euch in den Norden Düsterbruchs und sprecht mit dem Druiden der Kralle, der bereits zur Erkundung vorgeschickt wurde.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich in den nördlichen Teil Düsterbruchs östlich der Mondfederfeste zu reisen!\n\nKönig Gordok und seine wachsende Armee der Oger der Gordok stellen in der Gegend die größte und mächtigste Bedrohung für uns dar! Falls Ihr interessiert seid, begebt Euch in den Norden Düsterbruchs und sprecht mit dem Druiden der Kralle, der bereits zur Erkundung vorgeschickt wurde.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28077] = {title = "Abenteurer gesucht: Der Norden Düsterbruchs", objective = "Sprecht mit dem Oger der Steinbrecher.Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich in den nördlichen Teil Düsterbruchs östlich der Mondfederfeste zu reisen!\n\nKönig Gordok und seine wachsende Armee der Oger der Gordok stellen in der Gegend die größte und mächtigste Bedrohung für uns dar! Falls Ihr interessiert seid, begebt Euch in den Norden Düsterbruchs und sprecht mit dem Oger der Steinbrecher, der bereits zur Erkundung vorgeschickt wurde.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich in den nördlichen Teil Düsterbruchs östlich der Mondfederfeste zu reisen!\n\nKönig Gordok und seine wachsende Armee der Oger der Gordok stellen in der Gegend die größte und mächtigste Bedrohung für uns dar! Falls Ihr interessiert seid, begebt Euch in den Norden Düsterbruchs und sprecht mit dem Oger der Steinbrecher, der bereits zur Erkundung vorgeschickt wurde.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28078] = {title = "Abenteurer gesucht: Haupttor von Stratholme", objective = "Sprecht mit Kreuzzugskommandant Eligor Morgenbringer.Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Haupttor von Stratholme nördlich vom Pestwald zu reisen!\n\nDer Schreckenslord Balnazzar hat Kreuzfahrer des scharlachroten Kreuzzugs getötet und sie als Auferstandende wiederbelebt! Falls Ihr interessiert seid, begebt Euch zum Haupttor und sprecht mit Kreuzzugskommandant Eligor Morgenbringer, dem Anführer einer Einheit des Argentumkreuzzugs zur Rückeroberung Stratholmes durch seine rechtmäßigen Besitzer.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Haupttor von Stratholme nördlich vom Pestwald zu reisen!\n\nDer Schreckenslord Balnazzar hat Kreuzfahrer des scharlachroten Kreuzzugs getötet und sie als Auferstandende wiederbelebt! Falls Ihr interessiert seid, begebt Euch zum Haupttor und sprecht mit Kreuzzugskommandant Eligor Morgenbringer, dem Anführer einer Einheit des Argentumkreuzzugs zur Rückeroberung Stratholmes durch seine rechtmäßigen Besitzer.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28079] = {title = "Abenteurer gesucht: Haupttor von Stratholme", objective = "Sprecht mit Kreuzzugskommandant Eligor Morgenbringer.König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Haupttor von Stratholme nördlich vom Pestwald zu reisen!\n\nDer Schreckenslord Balnazzar hat Kreuzfahrer des scharlachroten Kreuzzugs getötet und sie als Auferstandende wiederbelebt! Falls Ihr interessiert seid, begebt Euch zum Haupttor und sprecht mit Kreuzzugskommandant Eligor Morgenbringer, dem Anführer einer Einheit des Argentumkreuzzugs zur Rückeroberung Stratholmes durch seine rechtmäßigen Besitzer.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Haupttor von Stratholme nördlich vom Pestwald zu reisen!\n\nDer Schreckenslord Balnazzar hat Kreuzfahrer des scharlachroten Kreuzzugs getötet und sie als Auferstandende wiederbelebt! Falls Ihr interessiert seid, begebt Euch zum Haupttor und sprecht mit Kreuzzugskommandant Eligor Morgenbringer, dem Anführer einer Einheit des Argentumkreuzzugs zur Rückeroberung Stratholmes durch seine rechtmäßigen Besitzer.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28080] = {title = "Abenteurer gesucht: Dienstbotentor von Stratholme", objective = "Sprecht mit Kreuzzugskommandant Eligor Morgenbringer.König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Dienstbotentor von Stratholme nordwestlich des Nordpassturms zu reisen!\n\nBaron Aurius Totenschwur, ehemaliger Paladin der Silbernen Hand und kürzlich wiederbelebter Sohn von niemand Geringerem als Baron Totenschwur selbst, führt nun die restlichen Streitmächte der Geißel an! Falls Ihr interessiert seid, begebt Euch zum Haupttor und sprecht mit Kreuzzugskommandant Eligor Morgenbringer, dem Anführer einer Einheit des Argentumkreuzzugs zur Rückeroberung Stratholmes durch seine rechtmäßigen Besitzer.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich zum Dienstbotentor von Stratholme nordwestlich des Nordpassturms zu reisen!\n\nBaron Aurius Totenschwur, ehemaliger Paladin der Silbernen Hand und kürzlich wiederbelebter Sohn von niemand Geringerem als Baron Totenschwur selbst, führt nun die restlichen Streitmächte der Geißel an! Falls Ihr interessiert seid, begebt Euch zum Haupttor und sprecht mit Kreuzzugskommandant Eligor Morgenbringer, dem Anführer einer Einheit des Argentumkreuzzugs zur Rückeroberung Stratholmes durch seine rechtmäßigen Besitzer.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28081] = {title = "Abenteurer gesucht: Dienstbotentor von Stratholme", objective = "Sprecht mit Kreuzzugskommandant Eligor Morgenbringer.Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Dienstbotentor von Stratholme, nordwestlich des Nordpassturms zu reisen!\n\nBaron Aurius Totenschwur, ehemaliger Paladin der Silbernen Hand und kürzlich wiederbelebter Sohn von niemand Geringerem als Baron Totenschwur selbst, führt nun die restlichen Streitmächte der Geißel an! Falls Ihr interessiert seid, begebt Euch zum Haupttor und sprecht mit Kreuzzugskommandant Eligor Morgenbringer, dem Anführer einer Einheit des Argentumkreuzzugs zur Rückeroberung Stratholmes durch seine rechtmäßigen Besitzer.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich zum Dienstbotentor von Stratholme, nordwestlich des Nordpassturms zu reisen!\n\nBaron Aurius Totenschwur, ehemaliger Paladin der Silbernen Hand und kürzlich wiederbelebter Sohn von niemand Geringerem als Baron Totenschwur selbst, führt nun die restlichen Streitmächte der Geißel an! Falls Ihr interessiert seid, begebt Euch zum Haupttor und sprecht mit Kreuzzugskommandant Eligor Morgenbringer, dem Anführer einer Einheit des Argentumkreuzzugs zur Rückeroberung Stratholmes durch seine rechtmäßigen Besitzer.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28082] = {title = "Abenteurer gesucht: Scholomance", objective = "Sprecht mit Weldon Barov.", description = "König Varian Wrynn fordert alle tauglichen Abenteurer auf, unverzüglich nach Scholomance östlich von Andorhal zu reisen!\n\nRas Frostraunen und Dunkelmeister Gandling sind noch immer damit beschäftigt, mächtige Zauberer für die Geißel auszubilden! Falls Ihr interessiert seid, begebt Euch nach Scholomance und sprecht mit Weldon Barov, dem letzten lebenden Sohn der Barovfamilie und rechtmäßiger Erbe der umliegenden Ländereien.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28083] = {title = "Abenteurer gesucht: Scholomance", objective = "Sprecht mit Alexi Barov.Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich nach Scholomance östlich von Andorhal zu reisen!\n\nRas Frostraunen und Dunkelmeister Gandling sind noch immer damit beschäftigt, mächtige Zauberer für die Geißel auszubilden! Falls Ihr interessiert seid, begebt Euch nach Scholomance und sprecht mit Alexi Barov, einem der letzten Erben des Reichtums der Barovfamilie und unser Kontakt in der dunklen Schule.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Der Kriegshäuptling fordert alle tauglichen Abenteurer auf, unverzüglich nach Scholomance östlich von Andorhal zu reisen!\n\nRas Frostraunen und Dunkelmeister Gandling sind noch immer damit beschäftigt, mächtige Zauberer für die Geißel auszubilden! Falls Ihr interessiert seid, begebt Euch nach Scholomance und sprecht mit Alexi Barov, einem der letzten Erben des Reichtums der Barovfamilie und unser Kontakt in der dunklen Schule.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28084] = {title = "Die Macht der Krom'gar", objective = "Ihr habt jetzt Zugang zum Vorratslager der Krom'gar, <Name>! Für ein geringes Entgelt verkaufe ich Euch Kampfausrüstung, die Euch beim Vernichten Eurer Feinde dienlich sein wird! Es hängt von Eurem Rang in der Armee ab, welche Waren ich Euch verkaufen kann. Besucht mein Geschäft, wann immer Ihr einen neuen Rang erhaltet.\n\nLOK'TAR OGAR!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28085] = {title = "Ärger in Steilhang", objective = "Sprecht mit Pao'ka Bergrausch in Steilhang in Tausend Nadeln.", description = "Vielen Dank für Eure Hilfe, <Name>. Ihr solltet Euch mit Pao'ka Bergrausch in Steilhang unterhalten, südlich von hier.\n\nVielleicht weiß er, wo sich die Ältestengreisin befindet?", progress = nil, completion = "Ich weiß nichts von Magatha, der Ältestengreisin. Ich weiß aber, dass der Schattenhammer den Steilhang zerstört.\n\nKönnt Ihr mir dabei helfen, sie aufzuhalten, &lt;Klasse&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28086] = {title = "Befreit die Wyverlinge!", objective = "Befreit 12 Steilhangwyverlinge.", description = "Die Fallensteller arbeiten daran, alle jungen Windreiter zusammenzutrommeln. <Name>, könnt Ihr Euch der Sache annehmen und die Wyverlinge befreien?", progress = nil, completion = "Sie sind so wertvoll. Eines Tages werden sie auch stark sein, aber bis dahin müssen sie beschützt werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28087] = {title = "Tod allen Fallenstellern!", objective = "Sammelt 8 Netze der Fallensteller.", description = "Für die dreckigen Fallensteller der Schattenhämmer haben wir nur eines übrig: den Tod!\n\nBringt mir ihre Netze, <Name>.", progress = "Welcher Wahnsinn kann jemanden dazu bringen, so grauenvolle Taten zu vollbringen?", completion = "Ab dem heutigen Tage werden keine Fallen mehr hier zu finden sein!", rewards = "Schnelle BergstiefelHelm des FallenstellersPao'kas GürtelFallenstellerschlägerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28088] = {title = "Die Freilassung von Klingenherz", objective = "Befreit Klingenherz von allen Ketten, die ihn festhalten.", description = "Der Schattenhammer hält das Alphamännchen von Steilhang fest. Ihr müsst Euch nach Osten begeben und Klingenherz befreien, bevor das Rudel seinen Anführer verliert.", progress = "Ihr müsst Klingenherz befreien, bevor sie ihn in ihr böses Lager verfrachten!", completion = "Der große Klingenherz ist eine majestätische Kreatur. Er hat mir von seiner Dankbarkeit und Wertschätzung für Euch berichtet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28089] = {title = "Auf Befehl des Kriegshäuptlings: Das Vorgebirge des Hügellands!", objective = "Meldet Euch bei Hochexekutorin Darthalia am Südwachttor im Vorgebirge des Hügellands.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Hochexekutorin Darthalia am Südwachttor im Vorgebirge des Hügellands zu melden. Die Kriegsmaschinerie der Verlassenen bewegt sich immer weiter vorwärts und sichert Lordaeron für die Horde!\n\nUm das Südwachttor zu erreichen, müsst Ihr der Straße in Richtung Süden durch den Silberwald folgen und die östliche Abzweigung nehmen, die ins Vorgebirge des Hügellands führt.\n\nVorwärts, <Bruder/Schwester>! Das Schicksal ruft!", progress = nil, completion = "Ich habe mich schon gefragt, wann die Verstärkung eintreffen würde. Macht Euch bereit, &lt;Name&gt;. Zeit, etwas Gerechtigkeit walten zu lassen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28090] = {title = "Wertvolle Waren", objective = "Bergt einen Torstein der Zwielichtkarawane. Die Speerwächter sollten Schlüssel bei sich tragen, die Euch Zugang zu den Truhen mit den Torsteinen verschaffen.", description = "Die Tore weiter unten im Canyon sind geschlossen. Wir haben ausgekundschaftet, dass es eine Art Stein gibt, den sie in Kisten in ihren Karawanen mitführen, und zum Öffnen der Tore benutzen.\n\nGeht dort hinunter und durchsucht die Leichen der Wachen nach einem Truhenschlüssel. Wenn Ihr ihn findet, benutzt ihn bei einer der großen Truhen auf den Karawanenwagen und bringt den Torstein zu mir zurück.", progress = "Wisst Ihr, wir könnten die Tore wahrscheinlich einfach aufsprengen, aber wie wir unseren Sprengmeister kennen, sollten wir das Risiko lieber nicht eingehen.", completion = "Gut gemacht!\n\nSieht nicht nach etwas Besonderem aus, oder?", rewards = "Helm des beständigen HassesBrustquetschende GamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28091] = {title = "Leichte Aufgabe", objective = "Tötet 8 Zwielichtspeerwärter.", description = "Der Hinterhalt ging problemlos vonstatten. Die meisten Wachen sind tot, aber einige sitzen immer noch bei den Wagen fest.\n\nIhr könnt sie genau im Westen in dem Canyon unter uns sehen. Geht dorthin und erledigt sie, damit wir diesen Angriff ins Rollen bringen können.", progress = nil, completion = "Ausgezeichnet. Jetzt können wir unsere Bodentruppen in Richtung Grim Batol in Bewegung setzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28092] = {title = "Wenn der Schlüssel passt", objective = "Führt die Goblinschwadron zu dem geschlossenen Tor des Drachenmals.\n\nWenn Ihr die Goblinschwadron verliert, kehrt zu Kriegsfürst Krogg zurück, damit Ihr neue Truppen zugeteilt bekommt.", description = "Die Wyrms haben den Kampf bereits in den Himmel über Grim Batol getragen. Jetzt ist es an uns, unsere Leute auf dem Boden dorthin zu bewegen und die Tore zu sichern.\n\nIhr sollt wissen, was auf dem Spiel steht, <Klasse>. Grim Batol ist die Quelle der Verstärkung für den Schattenhammer im ganzen Hochland. Wenn wir das hier nicht unterbinden, werden wir die Kämpfe, die vor uns liegen, nicht gewinnen können.\n\nIch schicke die Goblinschwadron mit Euch. Erreicht das Tor im Südosten und öffnet es. Flick sollte weitere Anweisungen für Euch haben, wie es ab da weiter geht.", progress = "Bleibt in Bewegung. Wir müssen das Tor öffnen.", completion = "Es klappt doch immer wieder aufs Neue.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28093] = {title = "Vordringen", objective = "Führt die Goblinschwadron am nördlichen Tor des Drachenmals vorbei zum Eingang von Grim Batol.\n\nWenn Ihr die Goblinschwadron verliert, kehrt zu Kriegsfürst Krogg zurück, damit Ihr neue Truppen zugeteilt bekommt.", description = "Bis jetzt war das gute Arbeit. Wir sollten den Eingang zu Grim Batol direkt hinter dem nächsten Tor finden.\n\nIch habe Befehle, den Eingang zu sichern und der Verstärkung den Weg zu verstellen, während der Rest unserer Leute durch den Pfad, den wir durch den Canyon freigemacht haben, vorwärts drängt. Ich glaube, wir werden es bald geschafft haben, vielleicht kann ich Ticker dann ein wenig mehr Spaß gönnen.\n\nMachen wir uns auf den Weg hinunter in den Canyon im Südwesten - wir sollten das nächste Tor recht schnell finden.", progress = "Willkommen, <Volk>.", completion = "Das Tor ist frei. Sobald Eure Leute den Canyon durchquert haben, werden wir mit Euren Anführern über den nächsten Schritt sprechen.", rewards = "TorbrechertreterHandschuhe des StaffelführersUmhang der wackeren FührungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28094] = {title = "Den Weg ebnen", objective = "Tötet 30 Kultisten des Schattenhammers entlang der Wyrmbiege, während Ihr Euch zum Eingang von Grim Batol durchkämpft.", description = "Meine Befehle lauten, Euch nach Süden durch die Tore des Drachenmals zum Eingang von Grim Batol zu begleiten. Wir sollen einen Weg freimachen, damit der Rest der Männer uns folgen und den Eingang sichern kann.\n\nÜbersetzung: Tötet alles, das sich bewegt und schämt Euch nicht, wenn Ihr Spaß dabei habt.\n\nDie Jungs werden langsam unruhig. Auf geht's.", progress = nil, completion = "Es sieht beinahe leicht aus.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28096] = {title = "Beamtenmikado", objective = "Gebt 3 Quests aus.", description = "Wer sich zuerst bewegt, hat verloren, <mein Lieber/meine Liebe>. Nur so kann man es als hochrangiger Offizier der Verlassenen zu etwas bringen. Ja, das hier ist in der Tat das gute Leben und Ihr werdet es leben!\n\nIch möchte, dass Ihr diese Befehle nehmt und sie an die kleinen Anfänger ausgebt, die hier vorbeikommen und nach Arbeit suchen. Wem Ihr was gebt, ist Euch überlassen.\n\nWenn Ihr bereit seid, steigt auf mein braves Skelettross auf - damit man Euch nicht übersieht - und fangt an, das Leben zu leben! Was bedeutet, einfach hier herumzustehen und zu warten.", progress = "Na, wie ist der \"Schreibtischjob\" so?", completion = "Na, wie war's? So, wie Ihr es Euch immer vorgestellt hattet? Aufregend, nicht wahr?\n\nNein?\n\n&lt;Darthalia seufzt.&gt;\n\nIch sehe, dass Ihr ein wahrer Held seid. Ihr braucht Action. Ich denke, ein \"Schreibtischjob\" ist nichts für Euch.", rewards = "Kuh-Kuh-HandschuheSchulterstücke des QuestgebersTragbarer SchreibtischIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28097] = {title = "Die Tore von Grim Batol", objective = "Sprecht mit Kriegsfürst Krogg in der Wyrmbiege.", description = "Krogg hat den Angriff begonnen, um durch den Canyon zu drängen. Er ist kurz hinter dem Tor im Südosten.\n\nIch werde die Schwadron zusammenrufen, damit wir uns dem Angriff anschließen. Wir treffen Euch dort unten.", progress = nil, completion = "Der Canyon ist gut geschützt, aber die Ablenkung, die die Drachen liefern, dürfte reichen, damit wir durchbrechen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28098] = {title = "Der Himmelsmeister der Schatten", objective = "Fliegt mit Klingenherz nach Zwielichthorst und bekämpft Schattenhimmelsmeister Richtofen.", description = "Richtofen der Schattenhimmelsmeister befindet sich oben und über Zwielichthorst südöstlich von hier. Es ist egal, was wir hier unten tun - wenn wir ihn nicht ausschalten, wird alle Hoffnung für Steilhang verloren sein.\n\nKlingenherz ist zwar zu schwer verletzt, um Euch im Kampf zu helfen, aber er kann Euch zum Horst fliegen. Der Rest liegt dann bei Euch, <Name>.\n\nIch wünsche Euch viel Glück.", progress = nil, completion = "Die Wyverlinge haben das gemacht? Sie müssen Euch sehr schätzen, dafür dass Ihr sie befreit habt.\n\nIch danke Euch, &lt;Name&gt;. Ihr habt den Steilhang gerettet!", rewards = "WyverlingdauengamaschenKlingenherzens GabeHose des HimmelsmeistersBrustplatte des WyvernbeschützersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28099] = {title = "Rasha'krak", objective = "Beschafft Rasha'kraks Armschienen der Bindung.", description = "Nach den Informationen, die Ihr geliefert habt, denke ich, dass einer der Handlanger des \"Erzherzogs\" seinen Blick bereits auf die Thoriumspitze gerichtet hat.\n\nSein Name ist Rasha'krak und er patrouilliert entlang der Lavaseen südlich von uns. Er sieht so aus wie die latenten Feuerelementare, die in der Nähe wüten. Es gibt aber einen kleinen Unterschied: die Armschienen der Bindung, die er an seinen Handgelenken trägt.\n\nFindet ihn und bringt mir diese Armschienen, <Name>. Ich brauche einen Beweis dafür, dass wir uns in Gefahr befinden, bevor wir uns auf Kriege mit den Elementaren einlassen.", progress = "Ich werde nicht gegen Elementare kämpfen, bis wir bewiesen haben, dass sie eine Bedrohung für uns sind.", completion = "Leider ist es so, wie ich vermutet hatte. Diese Armschienen tragen die unauslöschlichen Zeichen des Feuerlords und seiner Handlanger.\n\nAlso gut. Da sich weder Streitkräfte der Horde noch der Allianz in der Nähe dieser gottverlassenen Schlucht befinden, bleibt es an der Thoriumbruderschaft hängen, diesen Erzherzog aufzuhalten, bevor er noch mehr Böses verbreitet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28100] = {title = "Ein sprechendes Totem", objective = "Sprecht mit dem Totem von Ruumbo in der Nähe des Lagers der Totenwaldfelle.", description = "Das Furbolgdorf im Süden ist die Heimat der Totenwaldfelle, die Todfeinde der Holzschlundfeste sind. Sie sind verderbt und widerwärtig, wie so vieles andere. Die Fäulnis des Waldes hat sie in den Wahnsinn getrieben.\n\nNun ist allerdings etwas Außergewöhnliches in der Nähe des Lagers geschehen. Reisende, die hier vorbeikamen, haben gesagt, dass das Totem an der Straße zu ihnen gesprochen hat.\n\nIch habe noch nie etwas gehört, wenn ich mich ihm genähert habe. Vielleicht spricht es mit Euch, <Name>? Vielleicht könnt Ihr für mich herausfinden, was dort vor sich geht.", progress = nil, completion = "Ihr da... ja, Ihr! Ich habe Euch, &lt;Volk&gt;, als meinen Champion erwählt! Ihr werdet die Arbeit von Ruumbo verrichten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28101] = {title = "Mathias' Befehl", objective = "Sprecht mit Meister Mathias Shaw am Drachenmalpass.", description = "Die Ereignisse in letzter Zeit machen es noch offensichtlicher, dass es zur Absicherung unseres Volkes nicht ausreicht, hier einfach nur auszuharren und sporadische Angriffe auf Grim Batol auszuführen - geschweige denn, dass wir Grim Batol zurückerobern könnten. Wir müssen aggressiver sein und sie mitten ins Herz treffen.\n\nIch habe zugestimmt, Eurem Kommandanten Drachen zur Unterstützung zu senden. Sie hatten ohnehin schon über einem Plan gebrütet, wie man auf Grim Batol losschlagen kann, also solltet Ihr Eure Aufmerksamkeit zunächst einmal darauf konzentrieren.\n\nIhr solltet Mathias Shaw am Drachenmalpass im Canyon südlich unter uns finden.", progress = nil, completion = "Die roten Drachen sind bereit, zu helfen! Das war sicher nicht leicht. Die Allianz dankt Euch.\n\nAls die Drachen sich mit uns in Verbindung setzten, hatten wir bereits einen Plan ausgearbeitet, eine Zwielichtkarawane aus dem Hinterhalt heraus anzugreifen. Jetzt helfen sie uns, deren Rückzug zu unterbinden.\n\nDer Kampf tobt noch immer. Ihr könnt auf jeden Fall helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28102] = {title = "Bekämpft die Macht", objective = "Tötet 8 Jadefeuerschurken oder Jadefeuerschattenpirscher in den Ruinen von Constellas.", description = "Es ist Zeit für den entscheidenden Schlag gegen die Jadefeuer!\n\nWenn Ihr bereit seid, durch ihre verderbte Barriere zu brechen und ihrem Anführer den Kampf anzusagen, würde ich Euch auch darum bitten, uns gegen die niederen Satyrn zu unterstützen. Unsere Druiden kämpfen erbittert, aber Eure Stärke könnte helfen, die Schlacht zu unseren Gunsten zu wenden.\n\nZeigt den Jadefeuersatyrn, dass Ihre Macht nicht länger die Vorherrschaft über diese Lande hat!", progress = nil, completion = "Einige der verbliebenen Satyrn sind in die Tiefen der Wälder geflohen, aber sie haben schwere Verluste erlitten. Gute Arbeit, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28103] = {title = "Leichte Aufgabe", objective = "Tötet 8 Zwielichtspeerwärter.", description = "Der Hinterhalt ging problemlos vonstatten. Die meisten Wachen sind tot, aber einige sitzen immer noch bei den Wagen fest.\n\nGeht dorthin und erledigt sie, damit wir diesen Angriff ins Rollen bringen können.", progress = nil, completion = "Ausgezeichnet. Jetzt können wir unsere Bodentruppen in Richtung Grim Batol in Bewegung setzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28104] = {title = "Wertvolle Waren", objective = "Bergt einen Torstein der Zwielichtkarawane. Die Speerwächter sollten Schlüssel bei sich tragen, die Euch Zugang zu den Truhen mit den Torsteinen verschaffen.", description = "Die Tore weiter unten im Canyon sind geschlossen. Wir haben ausgekundschaftet, dass es eine Art Stein gibt, den sie in Kisten in ihren Karawanen mitführen, und zum Öffnen der Tore benutzen.\n\nGeht dort hinunter und durchsucht die Leichen der Wachen nach einem Truhenschlüssel. Wenn Ihr ihn findet, benutzt ihn bei einer der großen Truhen auf den Karawanenwagen und bringt den Torstein zu mir zurück.", progress = "Sie sind ein wenig zu selbstbewusst geworden. Das scheint zunehmend der Grund für den Untergang der mächtigsten Armeen zu sein.", completion = "Gut gemacht!\n\nSieht nicht nach etwas Besonderem aus, oder?", rewards = "TorwächterhelmSpeerdurchbohrte GamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28105] = {title = "Kavem der Gefühllose", objective = "Beschafft den Schlüssel aus Neferset von Kavem dem Gefühllosen.", description = "Kavem war schon grausam genug, bevor die Neferset sich Todesschwinge verschrieben haben. Sein Vergnügen, anderen Schmerzen zuzufügen, grenzt inzwischen an Wahnsinn.\n\nEr hat jetzt die Schlüssel für unsere Fesseln.\n\nEr haust in dem Gebäude neben uns zu meiner Rechten.\n\nFindet ihn und nehmt seinen Schlüssel an Euch. Zögert nicht und erweist ihm keine Gnade. Er würde Euch die Kehle aufschlitzen und sich nichts dabei denken.", progress = "Ihr seid wieder da. Habt Ihr den Schlüssel?", completion = "Ausgezeichnet, &lt;Name&gt;. Bald werden wir hier herauskommen.", rewards = "Kavems zugeschnittener BrustschutzHandwickel des SchlüsseldiebesLanggewehr mit PerlmuttschaftIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28106] = {title = "Die Tore von Grim Batol (NICHT LÖSCHEN. NICHT ALS VERALTET FLAGGEN)", objective = "Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28107] = {title = "Den Weg ebnen", objective = "Tötet 30 Kultisten des Schattenhammers entlang der Wyrmbiege, während Ihr Euch zum Eingang von Grim Batol durchkämpft.", description = "Meine Befehle lauten, Euch nach Süden durch die Tore des Drachenmals zum Eingang von Grim Batol zu begleiten. Wir sollen einen Weg freimachen, damit der Rest der Männer uns folgen und den Eingang sichern kann.\n\nÜbersetzung: Tötet alles, was sich bewegt und schämt Euch nicht, wenn Ihr Spaß dabei habt.\n\nDie Jungs werden langsam unruhig. Auf geht's.", progress = nil, completion = "Es sieht beinahe leicht aus.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28108] = {title = "Wenn der Schlüssel passt", objective = "Führt die Schwadron aus Hochstade zu dem geschlossenen Tor des Drachenmals.\n\nWenn Ihr Eure Schwadron verliert, kehrt zu Meister Mathias Shaw zurück, damit Ihr neue Truppen zugeteilt bekommt.", description = "Die Wyrms haben den Kampf bereits in den Himmel über Grim Batol getragen. Jetzt ist es an uns, unsere Leute auf dem Boden dorthin zu bewegen und die Tore zu sichern.\n\nIch will, dass Ihr wisst, was auf dem Spiel steht, <Klasse>. Grim Batol ist die Quelle der Verstärkung für den Schattenhammer im ganzen Hochland. Wenn wir sie hier nicht aufhalten, werden wir die Kämpfe, die vor uns liegen, nicht gewinnen können.\n\nIch schicke eine Schwadron aus Hochstade mit Euch. Erreicht das Tor im Südosten und öffnet es. Euer Hauptmann sollte weitere Anweisungen für Euch haben, wie es ab da weiter geht.", progress = "Bleibt in Bewegung. Wir müssen das Tor öffnen.", completion = "Wie eine gut geölte Kriegsmaschine.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28109] = {title = "Vordringen", objective = "Führt Eure Schwadron an dem nördlichen Tor des Drachenmals vorbei zum Eingang von Grim Batol.\n\nWenn Ihr die Schwadron verliert, kehrt zu Meister Mathias Shaw zurück, damit Ihr neue Truppen zugeteilt bekommt.", description = "Bis jetzt war das gute Arbeit.\n\nWir sollten den Eingang zu Grim Batol direkt hinter dem nächsten Tor finden. Ich habe Befehle, den Eingang zu sichern und der Verstärkung den Weg zu verstellen, während der Rest unserer Leute durch den Pfad, den wir durch den Canyon freigemacht haben, vorwärts drängt.\n\nMachen wir uns auf den Weg hinunter in den Canyon im Südwesten - wir sollten das nächste Tor recht schnell finden.", progress = "Willkommen, <Volk>.", completion = "Das Tor ist frei! Sobald Eure Leute durch den Canyon hindurch sind, werden wir mit Euren Anführern über den nächsten Schritt sprechen.", rewards = "Stampfer des KommandantenTorzerschmetternde StulpenUmhang der großen FührungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28111] = {title = "Ärger am Azurschacht", objective = "Meldet Euch bei Hauptmann Keyton am Azurschacht im Vorgebirge des Hügellands.", description = "Die Produktivität unserer Spinnenfarm am Azurschacht hat einen Stillstand erreicht. Hauptmann Keyton hat uns darum gebeten, sofort Hilfe zu schicken. Keyton behauptet, dass die Minenspinnen sich weigern, Befehlen zu gehorchen, und durchdrehen. Außerdem plündert eine Gruppe Küstenmurlocs unsere Vorräte. Könnt Ihr dort hinuntergehen und den Sachen nachgehen? Helft Keyton und dem Spinnenhändler, <Name>.\n\nIhr findet den Azurschacht im Südosten in der Nähe der Küste.", progress = nil, completion = "Wir stecken ein wenig in der Klemme, &lt;Klasse&gt;. Die Spinnen von Sarus werden ein wenig dreist, weil wir sie seit Tagen nicht füttern konnten. Wenn wir fortgehen, werden die Murlocs unseren Außenposten übernehmen! Schlimmer noch, Aufseher Stillwasser drüben an den Schlickfeldern verlangt, dass wir ihm noch mehr Menschen schicken! Er ist unersättlich! Wir brauchen Hilfe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28112] = {title = "Flucht aus der Verlorenen Stadt", objective = "Befreit Prinz Nadun und sprecht mit König Phaoris in Ramkahen in Uldum.", description = "Alles ist bereit! Löst meine Ketten und befreit Eure Freunde.\n\nWir müssen uns beeilen, bevor der Neferset-Abschaum bemerkt, dass wir etwas vorhaben!\n\nWenn wir es schaffen, begebt Euch zu meinem Bruder, König Phaoris, für eine Belohnung.", progress = nil, completion = "Es stimmt also? Ein Außenstehender hat Prinz Nadun vor den Neferset gerettet? \n\nWir stehen wirklich in Eurer Schuld, Fremder.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFürstliche BelohnungEhrenabzeichen von Ramkahen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28113] = {title = "Das Unzerstörbare zerstören", objective = "Tötet Xavathras.", description = "Mit der Klaue sind wir bereit, die Verteidigung der Jadefeuersatyrn zu durchbrechen.\n\nBegebt Euch in die Ruinen im Nordwesten. Hinter der Frontlinie der Satyrn werdet Ihr einen engen Pfad finden, der zu ihrem verderbten Mondbrunnen führt. Eine riesige Wand aus dämonischen Flammen blockiert den Pfad, aber die Klaue des Tichondrius sollte sie bannen können.\n\nHinter der Barriere findet Ihr den Anführer dieser Streitkräfte, Xavathras, der den verderbten Mondbrunnen bewacht. Tötet ihn, sobald Ihr das Hindernis überwunden habt!", progress = nil, completion = "Seht Ihr, was man mit ein bisschen Zusammenarbeit erreichen kann?\n\nIch werde dafür sorgen, dass die Klaue Leuten übergeben wird, die genug Verantwortungsbewusstsein haben, um so etwas aufzubewahren... das heißt, sofern sie nicht zerstört werden kann.", rewards = "Delaris' HandschuheFingerlose Handschuhe des ÖffnensZauberbrecherhelmDämonenzermalmerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28114] = {title = "Großartige Ernte", objective = "Sammelt 60 Krabblereier ein.", description = "Genau südöstlich vom Südwachttor findet Ihr unsere Operation zur Zähmung von Spinnen. Im Laufe der Jahre haben wir eine enge Verbindung zu Spinnen des Hügellandes aufgebaut und haben es geschafft, die hübschen kleinen Tierchen zu zähmen und zu züchten. Jetzt sind die Spinnen für uns normale Haustiere und Nutztiere für den Kampf! Es sind so vielseitige Kreaturen!\n\nIhr müsst für mich auf die Felder im Südosten gehen und vorsichtig Eier einsammeln, die in Bären ausgebrütet werden. Liefert die Ernte bei Sarus an der Mine ab.", progress = "Habt Ihr meine Ernte mitgebracht?", completion = "Wunderbar! Nun müssen diese Eier nur noch in eine hübsche, dunkle Nische innerhalb der Mine gelegt werden und dann kann das Wunder des Lebens geschehen!", rewards = "Mantel des SpinnenführersBärenbalgwesteKriechende StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28115] = {title = "Den Zenit überschritten", objective = "Tötet 8 infizierte Bären.", description = "Bären sind seelenlose Tiere, die auf diese Welt gesetzt wurden, um uns zu quälen. Nur dem Einfallsreichtum der Verlassenen haben wir es zu verdanken, dass wir einen Weg gefunden haben, um die Bären nutzbar zu machen, damit sie einem Zweck dienen! Wir benutzen die Bären auf unserer Spinnenfarm als lebendige Nährquellen für die Eier. Unsere Spinnen legen ihre Eier in das Fleisch der Bären und die Eier ernähren sich von dem Fleisch und dem Blut der Tiere.\n\nNachdem sie ihren Zweck erfüllt haben, müssen die Monster eingeschläfert werden. Reist nach Südosten und tötet die infizierten Bären, die ihren Lebenszenit überschritten haben.", progress = nil, completion = "Die Bärengötter sind grausame Herren. Sie werden diese Welt weiterhin bis ans Ende aller Tage mit Bären bevölkern. Es ist unser Recht als zivilisierte Menschen, uns diese Plagegeister zunutze zu machen - zum Nutzen aller!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28116] = {title = "Klageveilchen", objective = "Sammelt 8 Klageveilchen.", description = "Wir müssen uns sorgfältig vorbereiten, bevor wir Jaedenar angreifen. Die Magie der Hexenmeister und Dämonen in Jaedenar ist stark und wir werden unsere eigenen Schutzzauber benötigen, bevor wir hineingehen.\n\nWir benötigen nur noch eine letzte Zutat: Klageveilchen, die in den Hügeln nordwestlich des feindlichen Lagers wachsen.\n\nSammelt die Klageveilchen und trefft Euch dann mit meinem Feldassistenten. Er wird Euch sagen, was als Nächstes zu tun ist.", progress = "Habt Ihr die Klageveilchen schon finden können, <Name>? Wir brauchen sie so schnell es geht.", completion = "Wunderbar. Greta hat eine weise Entscheidung getroffen, als sie Euch gebeten hat, diese Aufgabe zu übernehmen. Ich werde die Kräuter umgehend verarbeiten...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28117] = {title = "Die Tiefen säubern", objective = "Ihr habt den Auftrag, 9 Geister beliebigen Typs in den Verfluchten Tiefen gleich östlich der Baradinfestung zu töten.", description = "Wie schön, Euch zu sehen, <Name>. Jetzt da wir Tol Barad eingenommen haben, fängt die Schlacht erst an.\n\nGleich östlich von hier haben wir einen Zellenblock entdeckt, den Ihr ausräumen müsst. Er steckt zum Bersten voll mit Geistern, die seit Ewigkeiten dort eingesperrt sind.\n\nBeseitigt so viele wie möglich und meldet Euch dann bei mir.", progress = nil, completion = "Ihr seid lebendig davongekommen? Ihr seid stärker als ich es bin, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28118] = {title = "Der gefangene Erzmagier", objective = "Ihr müsst Erzmagier Galus töten und mit seinem Stab aus den Verfluchten Tiefen östlich der Baradinfestung zurückkehren.", description = "Seit wir auf Tol Barad gelandet sind, versuchen wir, den Zellenblock in den Verfluchten Tiefen auszuräumen. Jedes Mal, wenn wir uns nähern, taucht dieser Erzmagier auf und drängt uns zurück.\n\nJetzt, da wir die Insel eingenommen haben, ist es an der Zeit, es noch einmal zu versuchen. Begebt Euch dorthin und bringt mir seinen Stab zum Beweis, dass Ihr den Auftrag erledigt habt.", progress = "Konntet Ihr den Erzmagier beseitigen?", completion = "Galus ist tot? Fantastische Arbeit, &lt;Name&gt;. Jetzt können wir die Putzkolonne dort hinunterschicken und den Zellenblock für neue Gefangene vorbereiten.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28119] = {title = "Reinheit aus Verderbnis", objective = "Füllt die leere Feldflasche mit Wasser aus dem verderbten Mondbrunnen im Zentrum von Jaedenar.", description = "Die Blumen, die Ihr mir gebracht habt, waren die Hauptzutat.\n\nSchutzbarrieren umgeben die Schattenfeste und werden von dämonischen Kohlenpfannen aufrechterhalten. Wenn wir den Schattenrat aus dem Teufelswald vertreiben wollen, müssen diese Kohlenpfannen erlöschen.\n\nDiese Phiole enthält Klageveilchen und die Magie der Wildnis. Füllt sie am verderbten Mondbrunnen im Zentrum von Jaedenar und kehrt zu mir zurück.", progress = "Habt ihr das Wasser aus dem verderbten Mondbrunnen?", completion = "Das reicht vollkommen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28120] = {title = "Aus der Vergangenheit lernen", objective = "Man hat Euch gebeten, vier verstaubte Gefängistagebücher aus den Verfluchten Tiefen östlich der Baradinfestung zu bergen.", description = "Jetzt, da wir auf dieser elenden Insel endlich Fuß gefasst haben, können wir Untersuchungen beginnen, wie sie in diesen Zustand geraten ist. Einige unserer Truppen haben Tagebücher am Eingang zum Zellblock östlich von hier in den Verfluchten Tiefen entdeckt.\n\nDiese Tagebücher sind für unsere ältesten Schreiber im Basislager von besonderem Interesse. Ihr müsst vier von den Tagebüchern finden und so schnell Ihr könnt zu mir zurückbringen.\n\n<Name>, seid vorsichtig dort unten, da wimmelt es nur so vor Untoten.", progress = "Konntet Ihr die Tagebücher bergen? Berichten zufolge wurden sie sowohl innerhalb, als aus auch außerhalb der Zellen dort unten gesehen.", completion = "Diese Tagebücher sind in ausgezeichnetem Zustand, &lt;Name&gt;. Wir werden sofort anfangen, sie zu entschlüsseln. Nur die Zeit wird zeigen, welche Geheimnisse sie bergen.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28121] = {title = "Streitkräfte von Jaedenar", objective = "Tötet 12 Soldaten von Jaedenar.", description = "Der Schattenrat hält die Verderbnis dieser Lande aufrecht. Bei Jaedenar im Nordwesten verehren sie die Dämonen der Brennenden Legion und arbeiten daran, den Weg für die Rückkehr ihrer Herren in diese Welt vorzubereiten.\n\nDas Gebiet wird von Hunden, Wächtern, Adepten und Kultisten von Jaedenar patrouilliert - Schlägern, die die Augen für die noch boshafteren Streitkräfte unter ihnen offenhalten. Sie werden die ersten sein, die sterben, damit diese Wälder nicht länger leiden müssen.", progress = nil, completion = "Gut, &lt;Name&gt;! Jetzt, da ihre Zahlen zurückgehen, können wir bald unseren Angriff auf ihre Truppen tief in der Schattenfeste starten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28122] = {title = "Ein riesiges Problem", objective = "Ihr wurdet beauftragt, Problim zu töten, einen Riesenettin, der die Wege von Tol Barad unsicher macht.", description = "Endlich haben wir diesen gottverdammten Fels eingenommen und dann treibt so ein riesiger Ettin hier sein Unwesen und schaltet unsere Wachpatrouillen aus!\n\n<Name>, trommelt ein paar Verbündete zusammen und erledigt den Ettin. Wir können nicht zulassen, dass die Bestie hier alles verwüstet.\n\nSeid auf der Hut, von der Front wird gemeldet, dass er mit einem riesigen Baum bewaffnet ist. Und er hat keine Skrupel, ihn einzusetzen.", progress = nil, completion = "Ihr habt ihn tatsächlich getötet?! Ich kann es kaum glauben!", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28123] = {title = "Die Dämonenkette", objective = "Bringt die Dämonenkette an Euch.", description = "Narkrall hat mir das Geheimnis seines Einflusses über die Drachen in dieser Gegend verraten. Ich dachte, die Dämonenkette wäre ein Mythos, aber er hatte sie die ganze Zeit.\n\nUnd jetzt ist der Narr dabei, sie zu verlieren.\n\nSein Leben bedeutet mir nichts, aber die Drachenmalorcs können es sich nicht leisten, das Artefakt zu verlieren. Folgt ihm nach Norden zu Donnermar. In der Stadt wird Chaos herrschen, also könnt Ihr vielleicht unbemerkt landen. Kehrt mit der Dämonenkette zu mir zurück, selbst, wenn Ihr sie Narkralls Leiche entreißen müsst.\n\nFindet das Artefakt, <Name>.", progress = "Habt Ihr sie? Ja? Das Schicksal Drachenmals hängt von der Dämonenkette ab.", completion = "&lt;Zaela nimmt die blutbespritzte Kette und wickelt sie um ihre Hand und ihr Handgelenk.&gt;\n\nWenn die Geschichten wahr sind, &lt;Name&gt;, war es diese Kette, an der Todesschwinge einst die Dämonenseele angebunden hatte, die nach seinem Befehl erschaffen worden war, um die anderen Drachenschwärme unter seine Kontrolle zu bringen. Die Dämonenseele wurde bereits vor langer Zeit zerstört, aber vielleicht enthält dieser Klumpen Elementiumerz noch Reste dieser Kraft...\n\nIhr habt heute Großes geleistet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28124] = {title = "Weiter zum Bollwerk", objective = "Sprecht mit Lakota Windweise am Schattenbollwerk in Tausend Nadeln.", description = "<Name>, als sich die Wyverlinge um den Himmelsmeister gekümmert haben, kam Lakota Windweise vorbei. Sie sagte mir, sie möchte Euch am Schattenbollwerk treffen, östlich von hier.\n\nIch glaube, Magatha Grimmtotem wird dort festgehalten.", progress = nil, completion = "Ich bin froh, dass Ihr kommen konntet.\n\nKümmert Euch nicht um mein Aussehen. Es schien weise, meine Kleidung entsprechend anzupassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28125] = {title = "Was zum Anziehen", objective = "Sammelt 10 Teile Schattenhammerrüstungen.", description = "Ich habe eine Idee, wie wir Euch in die Nähe der Anführer bekommen können, ohne dass man Euch gleich tötet. Zuerst braucht Ihr aber etwas zum Anziehen.\n\nIch schlage vor, dass Ihr von dort vorne eine ihrer Rüstungen schnappt.", progress = "Wie viele Rüstungsteile konntet Ihr finden?\n\nFür Eure nächste Aufgabe solltet Ihr wirklich gut verkleidet sein.", completion = "&lt;Lakota sieht über den Zustand der Rüstung besorgt aus, besonders über die vielen Blutflecken.&gt;\n\nIhr habt auch wirklich sorgfältig geschaut, &lt;Name&gt;? Naja, das wird reichen müssen.", rewards = "Lakotas StreitkolbenGut gehämmerter SchildBlutbefleckter ZwielichtgürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28126] = {title = "Die Flammen des Schutzes ersticken", objective = "Benutzt das gereinigte Wasser aus dem Mondbrunnen, um die vier Kohlenpfannen des Schutzes in der Schattenfeste zu löschen.", description = "Die Kohlenpfannen sind überall in der Schattenfeste verteilt.\n\nBetretet den Tunneleingang zur Schattenfeste und folgt den unterirdischen Korridoren. Löscht jede einzelne Flamme der Kohlenpfannen und der Schutz, den der Rat eingerichtet hat, wird für mindestens eine Weile zusammenbrechen.", progress = nil, completion = "Jetzt, da die Kohlenpfannen gelöscht sind, können die Druiden des Smaragdkreises die Schattenfeste betreten und die restlichen Kultisten beseitigen. Mit der Zeit kann dieser Ort vielleicht wieder als der Grabhügel genutzt werden, der er einst war.\n\nIhr habt meinen Dank, &lt;Name&gt;. Bitte, nehmt diese Belohnung an.", rewards = "Gürtel des verlorenen GrabhügelsJadegrüne SchiftungSchulterstücke des SanktumsAuf Euch wartet eine dieser Belohnungen:\n\nSmaragdkugel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28127] = {title = "Brecht sie aus", objective = "Rettet 5 Bollwerkgefangene von den Zwielichtkerkermeistern.", description = "Magatha ist nicht die einzige Gefangene des Schattenhammers.\n\nWährend Ihr in ihrem Lager im Süden seid, solltet Ihr so vielen wie möglich beim Ausbruch helfen.", progress = nil, completion = "Ihr gebt so viel, ohne etwas zurückzuverlangen.\n\nDie Bevölkerung von Tausend Nadeln ist dankbar, und ich bin es auch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28128] = {title = "Der innere Kreis", objective = "Tötet 12 Verteidiger in der Schattenfeste.", description = "Jetzt, da ihre äußeren Wächter fort sind, sind die höheren Mitglieder des Schattenrates dran.\n\nTief in den verderbten Grabhügeln findet Ihr mächtige Hexenmeister, Jäger, Vollstrecker, Dunkelwirker und Legionäre von Jaedenar.\n\nSie müssen besiegt werden, wenn diese Lande gerettet werden sollen!", progress = nil, completion = "Die Säuberung der Schattenfeste wird lange dauern und viel Anstrengung erfordern, aber ohne Euren Sieg gegen den Schattenrat, wäre sie überhaupt nicht möglich. Danke, &lt;Name&gt;.", rewards = "Streitkolben der SchattenfesteMondbogenAuf Euch wartet eine dieser Belohnungen:\n\nGeläutertes Amulett von Jaedenar\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28129] = {title = "Der Dämonenprinz", objective = "Tötet Prinz Xavalis.", description = "Die Jadefeuersatyrn, die so viel vom Teufelswald überrannt haben, arbeiten direkt mit dem Schattenrat zusammen.\n\nDiese Satyrn sind direkt dem uralten und mächtigen Prinz Xavalis unterstellt. Einige sagen, er ist der Sohn von Xavius, dem ersten Satyr, und von Sargeras höchstpersönlich gesegnet. \n\nEgal, welchen Ursprungs er ist, er muss sterben, wenn wir die Satyrn der Jadefeuerregion zerschlagen und unsere Grabhügel zurückerobern wollen. Begebt Euch tief in die Schattenfeste und tötet ihn. Gewährt ihm keine Gnade, denn auch er wird Euch keine gewähren.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28130] = {title = "Nicht die freundlichste Stadt", objective = "Kommandant Marcus Johnson hat Euch gebeten, 14 Dorfbewohner in Rostberg zu töten. Rostberg befindet sich nördlich des Basislagers auf der rechten Seite.", description = "Seid Ihr schon oben in Rostberg gewesen, <Name>? Ich schlage vor, dass Ihr eine scharfe Klinge bei Euch tragt, wenn Ihr in die Richtung geht.\n\nDie Bewohner dieser Stadt sehen ganz in Ordnung aus, aber da geht irgendwas Verdächtiges vor. Wir haben Berichte erhalten, dass sie unsere Soldaten vorne und hinten wegfangen. Wir haben allmählich die Nase voll davon, deshalb müsst Ihr für uns dorthin gehen und ein bisschen aufräumen.\n\nErledigt so viele von ihnen wie Ihr könnt, und meldet Euch dann wieder bei mir, wenn Ihr fertig seid.", progress = nil, completion = "Ich habe Euch ja gesagt, dass das Dorf voller Irrer ist. Aber Ihr habt gut dort aufgeräumt, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28131] = {title = "Doppelte Versuchung", objective = "Tötet Moora und Salia.", description = "Moora und Salia sind die persönlichen Dienerinnen von Schattenlord Fel'dan. Lasst Euch nicht von ihnen in die Irre führen!\n\nDiese widerwärtigen Sukkuben benutzen Listen und finstere Magie, um Sterbliche tief in die Schattenfeste zu locken. Diejenigen, die in ihre Fänge geraten, erhalten eine Gehirnwäsche oder werden von Fel'dan seinen dämonischen Herren geopfert.\n\nDie beiden kämpfen wie aus einem Guss und sind unzertrennlich, was sie zu einer erheblichen Bedrohung macht. Geht tiefer in die Schattenfeste und tötet sie.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28132] = {title = "Effiziente Ausgrabungen", objective = "Bringt 'Effiziente Ausgrabungen' zu Bellok Leuchtklinge in Schnottz' Landeplatz.\n\nBereitgestellter Gegenstand: \n", description = "Dieses Handbuch beschreibt absonderliche Theorien, wie man große Arbeitergruppen wirksam einteilt, wenn sie mit gewaltigen Ausgrabungsprojekten beschäftigt sind.\n\nNachdem Ihr den Inhalt überflogen habt, wird Euch klar, dass der Verfasser des Buchs die Person sein muss, die für die übermäßig aggressiven Plünderer hier verantwortlich ist.\n\nEine Karte auf der Rückseite des Umschlags zeigt, dass der Verfasser einen Bunker in der südwestlichen Region von Uldum besitzt.\n\nVielleicht wäre es angebracht, sich einmal vorzustellen.", progress = nil, completion = "Sieh mal an, es ist eines von Schnottz' Pamphleten.\n\nIch werde das mal an mich nehmen, wenn Ihr nichts dagegen habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28133] = {title = "Unbändige Wut", objective = "Reist zum Rachen und sprecht mit Zaela. Tötet Torth.", description = "Narkralls Drache Torth hat den vergeblichen Angriff auf Donnermar überlebt und jetzt ist die Kreatur von ihrem früheren Herrn befreit.\n\nTorth will sich an dem Drachenmalklan rächen und hat die Blutschlucht bereits einmal bombardiert. Er wird solange wiederkommen, bis wir ihn endgültig aufgespießt haben. Es wird Zeit, dass wir die Dämonenkette einsetzen.\n\nTorths altes Nest ist eine kleine Höhle in den Hügeln westlich von hier. Dort haben wir ein kleines Lager names \"Der Rachen\" aufgeschlagen.\n\nTrefft mich am Rachen und wir werden Torth erledigen.", progress = nil, completion = "Einmal frei von der Kette, starb Torth lieber, als sich noch einmal unterwerfen zu lassen. Ich bewundere die Kreatur. Ich werde aus seiner Haut einen Rüstungssatz herstellen lassen.\n\nSo viel weiß ich jetzt: Der Drachenmalklan kann allein nichts ausrichten, wenn die Allianz sich hinter die Wildhämmer stellt. Narkrall hat das bewiesen. Und Ihr habt die Macht der Horde immer wieder unter Beweis gestellt.\n\nIch werde unsere Drachengeschwader neu aufbauen und außerhalb der Bastion des Zwielichts Position beziehen. Ihr solltet weiterhin hier im Rachen und anderswo im Hochland aushelfen.", rewards = "Streitkolben des SchlundesKlaräugiger TaillenschutzStulpen des DrachenzornsBastionsäubernde GamaschenStab des TorthtötersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28134] = {title = "Bevorstehende Vergeltung", objective = "Sprecht mit Nomarch Teneth an den Tahretgründen, mit Sonnenpriester Asaris am Siegel des Sonnenkönigs und mit Asaq in Mar'at.", description = "Jetzt, da Ihr angemessen belohnt worden seid, kann ich hoffentlich offen mit Euch sprechen.\n\nIhr habt meinem Königreich einen großen Gefallen erwiesen, aber Ihr habt auch einen zerbrechlichen Friedensprozess aus dem Gleichgewicht gebracht.\n\nIch habe versucht, die Freilassung meines Bruders auf rein diplomatischem Wege zu erreichen, um Blutvergießen zu vermeiden.\n\nJetzt wird der Feind sicherlich zurückschlagen wollen.\n\nSprecht mit Nomarch Teneth an den Tahretgründen im Osten, mit Sonnenpriester Asaris am Siegel des Sonnenkönigs im Norden und mit Asaq in Mar'at im Westen. Findet heraus, wann der Feind zuschlagen wird.", progress = "Ihr seid zurückgekehrt, <Name>. Habt Ihr die Aufgabe, um die ich Euch gebeten hatte, erfüllt?", completion = "Orsis! Natürlich!\n\nWie konnte ich das übersehen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28135] = {title = "Al'Akirs Rache", objective = "Sprecht mit Prinz Nadun am Handelsposten Arsad außerhalb von Mar'at in Uldum.", description = "Hört zu, <Name>. Orsis wurde nicht von einem natürlichen Sandsturm getroffen. Das waren die Helfer von Al'Akir.\n\nDer Elementarlord der Luft ist fest mit Todesschwinge verbündet und es war nur eine Frage der Zeit, bevor er seine Untergebenen auf meine Leute hetzte.\n\nOrsis wurde als Warnung für uns angegriffen. Wir müssen uns beeilen und unseren Brüdern jede erdenkliche Hilfe anbieten.\n\nTrefft Euch mit Nadun am Handelsposten Arsad außerhalb von Mar'at. Ich werde Vorbereitungen treffen, damit wir uns um die Versprengten und Verwundeten kümmern können.", progress = nil, completion = "Seht Ihr, was Todesschwinges Helfer angerichtet haben? Das große Orsis ist jetzt beinahe vollkommen von Sand bedeckt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28136] = {title = "Hinter Euch!", objective = "Ermordet Chiffrenmeister Deethuk, Kommandant Luntenschnell und Elementarist Starion.", description = "Die drei Anführer des Schattenbollwerks sind mächtig und Ihr solltet sie nicht unterschätzen, <Name>. Glücklicherweise seht Ihr mit Eurer Verkleidung aus wie ein Schattenhammerkultist.\n\nTragt Eure Verkleidung und sprecht mit Chiffrenmeister Deethuk, Kommandant Luntenschnell und Elementarist Starion getrennt voneinander. Wartet, bis sie Euch den Rücken zuwenden und führt Euren Angriff dann schnell aus!", progress = nil, completion = "Jetzt, da die drei ausgeschaltet sind, sollten die vereinten Streitkräfte Freinwindpostens mit dem Rest der Kultisten hier alleine fertig werden können.", rewards = "Starions PartoffelnManschetten des ChiffrenmeistersLuntenschnells HandschuheBollwerk der AnführerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28137] = {title = "Lehrt einen hungrigen Mann das Fischen... oder das Stehlen", objective = "Ihr müsst 22 Rostbergseebarsche aus Rostberg stehlen. Die Fische befinden sich an Fäden aufgehängt auf Ständern bei den Docks im hinteren Teil des Dorfes. Rostberg befindet sich nördlich des Basislagers auf der rechten Seite.", description = "Rostberg. Dieser Ort ist für uns Fluch und Segen, <Name>. Ich habe keine Ahnung, wo die Banditen so gut Fischen gelernt haben, aber ich habe jetzt keine Zeit, mir darüber Sorgen zu machen.\n\nIhr müsst Euch dort hinunter begeben und so viele Ihrer Fischvorräte stehlen, wie möglich. Wir leben von Küchenabfällen, seit wir die Insel zurückerobert haben und dies ist die beste Gelegenheit für uns, an vernünftige Essensvorräte zu kommen.\n\nAchtet auf die Verstohlenen dort oben, Berichten zufolge befinden sie sich hauptsächlich innerhalb der Stadtmauern.", progress = "Ist Euch der Überfall gelungen und habt Ihr uns Fisch besorgt?", completion = "Diese Fische sind genau das, was wir brauchen, &lt;Name&gt;. Sie werden die Truppen ernähren und in guter Verfassung halten und das ist unser wichtigstes Anliegen. Ihr habt Euch wirklich für uns eingesetzt.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28138] = {title = "Menschenbefall", objective = "Nehmt 8 Menschen des Hügellands gefangen.", description = "Diese Mine war einst das Herzstück des Bergbaus der Allianz im Hügelland. Jetzt dient sie als Brutstätte für unsere getreuen Spinnen, obwohl die Menschen sie immer noch in gewisser Weise besetzt halten.\n\n<Keyton grinst.>\n\nAber lasst uns zum Geschäft kommen! Aufseher Stillwasser hat um weitere Arbeiter für die Schlickfelder gebeten. Ich möchte, dass Ihr die Mine mit diesen Fußfesseln betretet und Menschen des Hügellands für die Arbeit auf den Feldern gefangennehmt.\n\nHolt sie aus ihrer Netzlähmung und schlagt sie, bis sie sich ergeben, bevor Ihr ihnen die Fußfesseln anlegt.", progress = nil, completion = "Die sind genau richtig. Ich frage mich, was der Aufseher mit ihnen vorhat. Das Letzte, was ich gehört habe, war, dass die Schlickfelder von furchtbaren Dingen überrannt worden sind.", rewards = "OffiziersarmbänderSklaventreibergamaschenFesselnde KettenDer folgende Zauber wird auf euch gewirkt:\n\nDespawn All Summons\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28139] = {title = "Der Code des Chiffrenmeisters", objective = "Erhaltet den Code des Chiffrenmeisters.", description = "<Name>, Magatha wird mit speziell verschlüsselten Fesseln festgehalten. Wir können sie nur befreien, wenn wir den Code besorgen können.\n\nChiffrenmeister Deethuk am Schattenbollwerk südöstlich von hier hat eine Chiffriermaschine. Die Codes sind darin gespeichert.\n\nBesorgt sie!", progress = "Habt Ihr den Code, um die Fesseln der Ältestengreisin lösen zu können?", completion = "Gut. Jetzt gibt es nur noch eine Sache, um die wir uns kümmern müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28140] = {title = "Die Ältestengreisin", objective = "Deaktiviert das Steuergerät für Magathas Fesseln.", description = "Ihr habt den Code. Jetzt müsst Ihr nur noch in den südlichen Teil des Bollwerks und die Ältestengreisin befreien.\n\nViel Erfolg, <Name>. Ich danke Euch für alles, was Ihr bisher für uns getan habt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28141] = {title = "Relikte des Sonnenkönigs", objective = "Beschafft 4 Relikte des Sonnenkönigs.", description = "Das Siegel des Sonnenkönigs dient als Verteidigungsmechanismus für Ramkahen.\n\nAls die Barriere um Uldum fiel, sahen wir, wie die Vorhut der Wüstenläufer aus Tanaris unsere Grenzen überschritt.\n\nSie griffen diese heilige Stätte auf ihrem Weg in den Westen an und raubten die Relikte, die ihr einst ihre Macht verliehen.\n\nHolt die Relikte für uns zurück. Ohne sie sind wir machtlos und können uns nicht gegen ihre Angriffe aus der Wüste verteidigen.", progress = "Hattet Ihr Erfolg?", completion = "Danke. Die Gerüchte, die ich über Euch gehört habe, erweisen sich doch als wahr.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28142] = {title = "In die Ödnis", objective = "Sprecht mit Magatha Grimmtotem in Schattenödnis in Tausend Nadeln.", description = "Magatha hat gesagt, sie werde Euch außerhalb von Schattenödnis östlich von hier treffen.", progress = nil, completion = "Ihr habt lange gebraucht. Meint Ihr, wir sind zum Spaß hier?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28143] = {title = "In die Ödnis", objective = "Sprecht mit Magatha Grimmtotem in Schattenödnis in Tausend Nadeln.Ihr solltet die Ältestengreisin nicht warten lassen.\n\nSie sagte, dass sie Euch außerhalb der Anhöhung von Schattenödnis östlich von hier treffen wird.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ihr solltet die Ältestengreisin nicht warten lassen.\n\nSie sagte, dass sie Euch außerhalb der Anhöhung von Schattenödnis östlich von hier treffen wird.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28144] = {title = "Diebische kleine Monster!", objective = "Bergt 6 \"Vorräte\" des Lagers der Verlassenen.", description = "Das lange Stück Küste direkt südlich unseres Standortes, das sich von Westen nach Osten erstreckt, ist bekannt als der Weststrand. Entlang des Weststrands findet Ihr zwei Dinge: Murlocs und gestohlene \"Vorräte\".\n\n<Keyton streckt seine Hände in die Luft und macht das Zeichen für Anführungsstriche mit seinen Fingern.>\n\nDiese verdammten diebischen Murlocs haben hinter unserem Rücken zugeschlagen und unsere \"Vorräte\" gestohlen.\n\nSarus und ich können diesen Posten nicht verlassen. Ihr müsst für uns zum Weststrand gehen und diese \"Vorräte\" wiederbeschaffen!", progress = "Bringt unsere \"Vorräte\" zurück, <Name>!", completion = "Wenigstens werden wir auf zukünftige Vorfälle vorbereitet sein. \"Vorräte\" wie diese zu bewegen ist ein riskantes Vorhaben. Man weiß nie, wer meint, seine große Klappe aufreißen zu müssen.\n\n&lt;Keyton zieht das, was man für eine Augenbraue halten könnte, hoch.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28145] = {title = "Gegenmittel für Giftblut", objective = "Füllt die Gegengiftphiole mit dem Gift von 8 Giftblutskorpidkadavern.", description = "Iset hat versucht, diesen heiligen Boden gegen die Banditen der Wüstenläufer zu verteidigen, als sie ihn geplündert haben.\n\nAnscheinend haben sie ein starkes Gift verwendet, das von Giftblutskorpiden stammt.\n\nNehmt diese Phiole und sammelt Gift aus ihren Kadavern, damit ich ein Gegenmittel herstellen kann. Ich fürchte, Iset bleibt nicht mehr viel Zeit.", progress = nil, completion = "Danke, &lt;Name&gt;. Vielleicht können wir Iset doch noch retten.", rewards = "Armschienen der dunklen PyramideGürtel von Mar'atAuf Euch wartet eine dieser Belohnungen:\n\nLeuchtendes Skorpidauge\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28146] = {title = "Delikatessen der Küste!", objective = "Füttert die hungrige Minenspinne mit 12 Murlocs vom Weststrand.", description = "Meine Spinnen sind hungrig und aufgebracht! Sie haben seit Tagen nichts zu fressen bekommen und beginnen, unsere menschlichen Gefangenen anzuknabbern. Das geht so nicht. Wir brauchen diese Menschen, damit sie in den Schlickfeldern arbeiten.\n\nIch möchte, dass Ihr eine meiner hungrigen Minenspinnen mit hinausnehmt und ihr Murlocs vom Weststrand südlich von hier zum Fraß vorwerft. Sie wird fressen, was immer Ihr tötet! Je mehr, desto besser!", progress = nil, completion = "Das sollte sie für ein paar Tage glücklich und zufrieden machen. Ihr habt da gute Arbeit gemacht, &lt;Name&gt;!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDespawn All Summons\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28147] = {title = "Lila ist Eure Farbe", objective = "Hebt 8 Zwielichtkleidungsfetzen auf.", description = "Soweit ich das sagen kann, haben sich die Stopfwampenoger direkt vor der Höhle hier noch nicht dem Schattenhammer angeschlossen. Wenn wir schlau sind, können wir die beiden Gruppierungen gegeneinander ausspielen.\n\nLasst uns mit einem kleinen Trick beginnen, den ich in Silithus gelernt habe. Zunächst müssen wir für Euch einen Satz Kultistenroben zusammenbekommen.\n\nBegebt Euch nach Süden und tötet einige Zwielichtwindwirbler im Schattenriss. Abgesehen davon, dass wir sie bei dem, was sie tun, stören, bietet sich Euch die Chance, Gewandungsfetzen zu sammeln.", progress = "Das ist gut, <Name>. Mit Helden wie Euch, die da draußen für Unruhe sorgen, werden wir den Kult von unserer Hauptinvasion ablenken.\n\nHabt Ihr eine Verkleidung?", completion = "Was habt Ihr bekommen? Ich denke, daraus können wir etwas zusammenflicken.\n\nSchließlich wollt Ihr dem Kult nicht beitreten. Wir müssen nur ein paar Oger täuschen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28148] = {title = "Die Verderbten erlegen", objective = "Sammelt 10 verderbte Pelze von Wutklauenbären oder Teufelspfotenwölfen.", description = "Die abscheuliche Verderbnis der Dämonen durchzieht den gesamten Wald. Die Erde, die Bäume, die Tiere... alle tragen die teuflische Magie in sich.\n\nWir vom Smaragdkreis haben geschworen, diesen Wald zu läutern. Das aber bedarf eines ständigen Kampfes. Vieles kann noch geheilt werden - die Bären und Wölfe jedoch, die in der Nähe umherstreifen, sind bereits zu verderbt.\n\nWir müssen ihr Leiden beenden und sicherstellen, dass Ihre Kadaver die Verderbnis nicht noch weiter verbreiten. Jagt sie und bringt mit ihre Bälge.", progress = "Ich muss die Pelze haben, um sie von der verbliebenen dämonischen Essenz zu säubern.", completion = "Ich werde dafür sorgen, dass sie schnell und sicher verbrannt werden, &lt;Name&gt;. Ich danke Euch vielmals.", rewards = "WutklauengamaschenTeufelspfotenstiefelGürtel der ZufluchtAuf Euch wartet eine dieser Belohnungen:\n\nRotfederband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28149] = {title = "Flüstern im Wind", objective = "Beschafft einen Windsprecherglücksbringer und 5 Vortexhauche.", description = "Hört Ihr das, <Klasse>? Stimmen aus der Höhle. Sie woll'n reden, aber sie ham keinen Atem.\n\nLasst uns 'ne Möglichkeit finden, zuzuhören. Die vom Schattenhammer, die reden mit dem Wind. Geht zum Schattenriss südlich von hier und holt den Windsprecherglücksbringer vom Lager. Er ist oben auf 'ner Steinsäule.\n\nWir brauchen auch Atem von Elementaren! Tötet die Sturmvortex und nehmt Euch, was Ihr braucht.", progress = "Pschscht, <Name>! Hört mal. Hört mal...", completion = "Das isses, Mann.\n\nHört Ihr sie jetzt? Die Geister, sie sprechen, aber sie sagen nix gutes.\n\nHolen wir sie ans Licht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28150] = {title = "Ein arkaner Verbündeter", objective = "Sprecht mit Arkanistin Delaris bei den Ruinen von Constellas.", description = "Der Smaragdkreis hat geschworen, die Hilfe aller anzunehmen, welche die Dämonen des Teufelswalds zu bekämpfen wünschen. Obwohl die arkanen Künste bei meinem Volk lange verpönt waren, können wir uns einen derartigen Vorteil hier nicht versagen.\n\nArkanistin Delaris, eine überlebende Magierin der Hochgeborenen, hilft uns im Kampf gegen die Jadefeuersatyrn. Folgt der Straße nach Norden und Ihr findet sie in unserem Lager, das die Ruinen von Constellas überblickt.\n\nWenn es Euer Wunsch ist, bei der Läuterung des Teufelswalds mitzuwirken, erfüllt ihre Wünsche, wie ihr meine erfüllt habt.", progress = nil, completion = "Wir haben nicht viel Zeit für Unterhaltungen, &lt;Klasse&gt;. Die Druiden kämpfen tapfer gegen die Satyrn, aber teuflische Magien versperren ihnen den Weg.\n\nZum Glück habe ich einen Plan...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28151] = {title = "Todschick", objective = "Tötet 10 Stopfwampenoger. Eure Schattenhammerverkleidung wird automatisch angelegt, wenn Ihr auf Stopfwampes Anhöhe seid.", description = "Eure Verkleidung ist fertig, <Name>. Wenn Ihr in Zukunft nach Norden zu Stopfwampes Anhöhe geht, werden Eure Schattenhammerabzeichen die Oger täuschen.\n\nDer Rest des Plans ist einfach: Ihr tötet ein paar Stopfwampenoger und sie machen den Kult dafür verantwortlich. Seid Ihr bereit, um in dem Ogercamp Verwirrung zu stiften? Das dachte ich mir.", progress = nil, completion = "Ha! Ich bin sicher, dass der Schattenhammer diese Oger zu ihren Rängen zählen wollte. Jetzt müssen sie sich wahrscheinlich gegen sie wehren.\n\nDas ist gut, &lt;Name&gt;. Mit einem gut platzierten &lt;Klasse&gt; haben wir es geschafft, die Arbeit einer kleinen Armee zu verrichten. Ich werde Kriegsfürst Krogg über Eure Arbeit hier unterrichten!", rewards = "Brustplatte des OgertötersArmschienen der trügerischen NachtKultbalgschiftungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28152] = {title = "Jaedenar wartet", objective = "Liefert die Arkanistenkräuter bei Greta Mooshuf in Wildherzens Lager ab.", description = "Die Kultisten, die Ihr als Wachen der Klaue gesehen habt, waren Mitglieder des Schattenrats - widerliche Hexenmeister, die hinter fast jedem Versuch stecken, Dämonen nach Azeroth zu holen.\n\nNördlich von hier ist Jaedenar, das seinen Namen zu Ehren von Kil'jaeden erhielt. Tief darunter erstreckt sich die Schattenfeste, ein früherer Grabhügel und die Festung des Schattenrats hier auf Azeroth.\n\nBringt diese Kräuter nach Norden zu Wildherzens Lager auf der Ostseite der Straße. Greta Mooshuf wird sie für ihren Plan brauchen, die Schattenfeste endgültig zu säubern.", progress = "Seid gegrüßt, <Klasse>. Was führt Euch her?", completion = "Ah, darauf habe ich gewartet. Mit diesen Kräutern sind die Vorbereitungen für Jaedenar beinahe abgeschlossen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28153] = {title = "Schattenlord Fel'dan", objective = "Tötet Schattenlord Fel'dan.", description = "Schattenlord Fel'dan wartet noch tiefer drinnen, <Name>.\n\nSein Zorn wird unvergleichlich sein, da Ihr seine Lieblinge getötet habt. Doch auch ohne Moora und Salia an seiner Seite ist er eine nicht zu unterschätzende Macht.\n\nHütet Euch vor seinen dunklen Kräften, er ist inzwischen beinahe mehr Dämon als Orc.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28154] = {title = "Matschkiemes Flosse oder so...", objective = "Liefert Matschkiemes Flosse bei Hauptmann Keyton am Azurschacht im Vorgebirge des Hügellands ab.", description = "Das sieht wie Matschkiemes Flosse oder so was aus. Vielleicht gibt es jemanden, den es kümmert, dass Ihr diesen Murloc im Lager am Azurschacht getötet habt. Vielleicht auch nicht, aber einen Versuch ist es wert.\n\nBringt Matschkiemes Rückenflosse oder was immer es auch sein mag zu Hauptmann Keyton am Azurschacht im südwestlichen Hügelland.", progress = "Seh' ich wie ein Murlocforscher aus?", completion = "Matschkieme sagt Ihr. Nie von ihm gehört. Was ist das hier überhaupt? Eine Art Flosse oder so was?", rewards = "Keytons SchärpeSchlapper SchulterschutzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28155] = {title = "Lord Schattenfluch", objective = "Tötet Lord Schattenfluch.", description = "Jetzt lauert nur noch eine Macht in den Tiefen der Schattenfeste: Lord Schattenfluch.\n\nDer Schattenrat hier ist ihm zu Willen und sogar Fel'dan war nur ein Werkzeug für ihn, um dieses Land für eine weitere Invasion der Brennenden Legion vorzubereiten.\n\nSeid auf der Hut, <Name>. Ein Schreckenslord ist ein furchterregender Gegner. Seid standhaft und triumphiert!", progress = nil, completion = "Wirklich unfassbar, &lt;Name&gt;. Sich einfach in die Höhle des Löwen zu begeben und jeden Feind zu töten, der sich einem in den Weg stellt... Ich bin überwältigt.\n\nDer Smaragdkreis dankt Euch für Eure Arbeit hier im Teufelswald. Was Andalar betrifft, werde ich Späher zu seiner Rettung entsenden. Wir werden ihm einen Heldenempfang bereiten.", rewards = "Geläuterter Gürtel des SchattenratsFarlus' StabIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28156] = {title = "Rettung aus den Tiefen der Mine", objective = "Bringt Kagbuhn in Sicherheit!", description = "<Ihr hört Kagbuhn durch die Spinnweben hindurch sprechen.>\n\nHEY! ÜBERALL SPINNEN! DER HAUPTMANN HAT MICH GESCHICKT, UM DIE WELT ZU RETTEN UND MENSCHEN ZU FANGEN! WAS IST DAS HIER ÜBERHAUPT FÜR EIN ORT? ES IST SO HEISS HIER! ICH...\n\n<Kagbuhn redet immer weiter über seine Lage.>\n\nVielleicht solltet Ihr ihn befreien und ihn in Sicherheit bringen. Ihr könnt ihn auch hier lassen, obwohl es Eure Schuld ist, dass er hier in der Mine feststeckt.", progress = nil, completion = "Schon mal was von \"Der Stärkste überlebt\" gehört? Was Ihr da tut, steht in Konflikt mit den Naturgesetzen, mein Lieber! Der Idiot hätte in den Minen sterben sollen. Nicht auszudenken, welchen Schaden er sich oder anderen als nächstes zufügt, jetzt, da Ihr ihn vor seinem unausweichlichen Tod bewahrt habt.\n\nUnd Ihr wisst, wessen Fehler das dann sein wird, oder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28157] = {title = "Vier Elemente des Schattens", objective = "Sammelt die vier Elemente des Schattens: Luft, Erde, Feuer, und Wasser.", description = "Der Schattenhammer hat eine Monstrosität beschworen. Sie ist eine Mischung der vier Elemente, vereint mit der Macht ihres Sonderelementes Elementium.\n\nIhr müsst sie besiegen, wenn Ihr Euer geliebtes Tausend Nadeln vor der Zerstörung retten möchtet. Zuerst werdet Ihr jedoch ein paar Gegenstände brauchen, um sein Schutzschild zerstören zu können.\n\nÖstlich von hier in der Ödnis könnt Ihr die vier Elemente des Schattenhammers finden. Bringt sie zu mir.", progress = "Habt Ihr alle Elemente, <Name>?", completion = "&lt;Magatha starrt Euch mit purer Verachtung an.&gt;\n\nIch werde sie in eine nützliche Form bringen und es für Euch einfach machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28158] = {title = "Unbändig", objective = "Löst die gebundene Wut und den gebundenen Vortex.", description = "Der Schattenhammer hat zwei sehr mächtige Elemente gebunden. Sie benutzen die gebundene Wut und den Vortex, um dem Animus unfassbare Kraft zu verleihen.\n\nWenn der Animus die Macht aufgesaugt hat, wird er explodieren. Tausend Nadeln und ein Großteil der Nachbarländer werden bei der Explosion ausradiert werden.", progress = nil, completion = "Eine einfache Aufgabe für einen einfachen Burschen wie Euch. Wir werden sehen, ob Ihr das Zeug habt, diese Aufgabe zu meistern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28159] = {title = "Der Verdammnisstein", objective = "Erhaltet den Verdammnisstein.", description = "Im Kern des Animus befindet sich ein als Verdammnisstein bekanntes Artefakt. Eine seiner Eigenschaften ist die Absorbtion großer Energien.\n\nSo werden die Kultisten versuchen, die Explosion hervorzurufen... indem sie den Stein überladen und seine Macht durch den Elementar verstärken.\n\nBringt mir den Verdammnisstein. Natürlich nur, um ihn sicher zu verwahren.", progress = "Habt Ihr den Verdammnisstein, <Name>?", completion = "Ich bin überrascht... Ihr habt überlebt.\n\nIch danke Euch, dass Ihr diese dreckige Aufgabe für mich erledigt habt, &lt;Name&gt;. Nun habe ich nicht nur die Rassel der Knochen, die Niederschrift der Geschichte und die Trommeln des Krieges, sondern auch das ultimative Artefakt: den Verdammnisstein!", rewards = "Armschienen der sicheren AufbewahrungVernichtende MaskeSchienbeinschützer der DrecksarbeitArmschienen des GimpelsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28160] = {title = "Verbreitet Kunde", objective = "Sprecht mit Fizzel Kupferbolz auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", description = "Für Eure nützlichen Dienste werde ich Euch dem Tod entgehen lassen. Belasst es dabei und verschwindet aus meiner Sicht. Berichtet Eurem Volk von allem, was geschehen ist.\n\nUnd sollte ich Euch jemals wiedersehen, <Name>, so werdet Ihr sterben.", progress = nil, completion = "Wow, die ist böse! Aber was bedeutet das für uns, &lt;Name&gt;? Wird Magatha uns zerstören? Führt sie den Schattenhammer an?\n\nEgal, was jetzt passieren wird, Ihr habt uns vor unseren Feinden gewarnt. Bitte, erlaubt mir, Euch meine Dankbarkeit zu zollen.", rewards = "Robe der Tausend NadelnGamaschen der Tausend NadelnWeste der Tausend NadelnBrustschutz der Tausend NadelnSchulterstücke der Tausend NadelnHelm der Tausend NadelnIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28161] = {title = "Verbreitet Kunde", objective = "Sprecht mit Pozzik auf Fizzels & Pozziks Turbodampfer in Tausend Nadeln.", description = "Für Eure nützlichen Dienste werde ich Euch dem Tod entgehen lassen. Belasst es dabei und verschwindet aus meiner Sicht. Berichtet Eurem Volk von allem, was geschehen ist.\n\nUnd sollte ich Euch jemals wiedersehen, <Name>, so werdet Ihr sterben.", progress = nil, completion = "Wow, die ist böse! Aber was bedeutet das für uns, &lt;Name&gt;? Wird Magatha uns zerstören? Führt sie den Schattenhammer an?\n\nEgal, was jetzt passieren wird, Ihr habt uns vor unseren Feinden gewarnt. Bitte, erlaubt mir, Euch meine Dankbarkeit zu zollen.", rewards = "Robe der Tausend NadelnGamaschen der Tausend NadelnWeste der Tausend NadelnBrustschutz der Tausend NadelnSchulterstücke der Tausend NadelnHelm der Tausend NadelnIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28162] = {title = "Sumpfköder", objective = "Ihr habt den Auftrag, auf Tol Barad 8 Krokiliskenbälge von Krokilisken von Baradin zu besorgen. Die Krokilisken findet Ihr im Sumpf, gleich westlich der Baradinfestung.", description = "An solchen Orten ist die Versorgung immer schwer, <Klasse>. Seit wir die Insel eingenommen haben, erkunden wir sie, aber es sieht nicht gut aus.\n\nZum Glück haben wir gerade erfahren, dass sich gleich westlich von unserem Basislager ein Sumpf voller Krokis befindet. Deren Bälge werden unseren Lederern gerade recht kommen. Bringt so viele her wie Ihr nur könnt.", progress = "Habt Ihr schon im Sumpf aufgeräumt?", completion = "Sieht aus, als habt Ihr die Krokibälge, die wir brauchen. Danke, &lt;Name&gt;, Euer Beitrag wird Euch nicht vergessen.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28163] = {title = "Die Überreste", objective = "Ihr habt den Befehl erhalten, 12 Infanteristen der Horde in Tol Barad zu töten. In der Erzraffinerie, der Hüterwacht und der Eisernen Garnison hier auf Tol Barad sind noch Widerständler zu finden.", description = "Wir haben hart um diese Insel gekämpft, <Volk>. Den Großteil des Hordenabschaums haben wir ausgelöscht, aber ihr übler Gestank liegt immer noch in der Luft.\n\nKundschaftet die Erzraffinerie, die Hüterwacht und die Eiserne Garnison aus. Tötet alle angehörigen der Horde, die Ihr findet.\n\nIhr kennt ja das Sprichwort: Nur ein toter Hordler ist ein guter Hordler!", progress = nil, completion = "Diese dreckigen Hordler hatten nicht die geringste Chance. Gute Arbeit, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28164] = {title = "Sucht Bruder Silberheil", objective = "Sprecht mit Bruder Silberheil in den Goblinslums von Orgrimmar.", description = "Man hat mir gerade mitgeteilt, dass Ihr in Orgrimmar gebraucht werdet, <Name>. Bruder Silberheil hat darum gebeten, dass Ihr so schnell wie möglich zur Stadt zurückkehrt. Seine Nachricht enthielt keine weiteren Informationen, aber es schien dringlich zu sein.\n\nSucht nach Bruder Silberheil in den Goblinslums von Orgrimmar.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28165] = {title = "D-Block", objective = "Ihr habt den Befehl erhalten, 10 beliebige Dämonen im D-Block nordwestlich der Baradinfestung zu töten.", description = "Habt Ihr schon einmal vom D-Block gehört, <Name>? Das ist einer der Zellenblöcke hier auf der Insel. Das Problem ist, dass er von Dämonen befallen ist. Wir hatten eigentlich vor, dort die übriggebliebenen Hordler, die wir auf der Insel gefunden haben, einzusperren, aber in seinem momentanen Zustand ist das unmöglich.\n\nIhr müsst dort hinuntergehen und diese Dämonen beseitigen. Meldet Euch wieder bei mir, wenn Ihr fertig seid.", progress = nil, completion = "Der D-Block ist sauber? Gute Arbeit, &lt;Name&gt;. Wir werden sofort eine Putzkolonne dort hinunterschicken, die dort aufräumt.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28166] = {title = "Thogs Nachtlicht", objective = "Holt das Licht der Seelen von Stopfwampes Anhöhe.", description = "Wir brauchen ein spezielles Licht, damit wir die Geister sehen können. Ein Licht, das das Innere erleuchtet. Das Licht der Seelen.\n\nSeit dem, was wir ihnen in Hyjal angetan haben, benutzt der Schattenhammer sie, um Verräter aufzuspüren. Sie haben eins den Stopfwampenogern geschenkt.\n\nAn Stopfwampes Anhöhe nördlich von hier findet Ihr den riesengroßen Haudrauf Thog. Der hat 'n Licht der Seelen. Wenigstens wird er das haben, bis Ihr es ihm abnehmt.", progress = "Das Licht der Seelen. Habt Ihr es, Mann?", completion = "Ah, das isses, Mann.\n\n&lt;Die Linse glüht hell in Buunus Händen und wirft überirdische Lichtstrahlen im schattigen Höhleneingang.&gt;\n\nJetzt sind wir soweit, die Geister aus den Schatten zu holen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28167] = {title = "Meldet Euch bei Carvo Sprengbolz", objective = "Meldet Euch bei Carvo Sprengbolz in Gnomeregan.", description = "Ich werde meine Leute darauf vorbereiten, diesen Ort zu verlassen. Wir können hier nicht mehr länger ausharren. Ich möchte, dass Ihr Euch in eine vorgeschobene Position mitten in dem großen Zimmer vor uns begebt.\n\nDort solltet Ihr Carvo Sprengbolz finden. Er wird Euch weitere Anweisungen geben. Viel Glück, <Name> und wir sehen uns an der Oberfläche wieder.", progress = nil, completion = "Hat Nevin Euch vorgeschickt? Das bedeutet, er bereitet sich darauf vor, die Mission zu beenden. Doch es müssen immer noch Überlebende gerettet werden. Wir müssen ihnen helfen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28168] = {title = "Ärger an den Schlickfeldern", objective = "Meldet Euch bei Aufseher Stillwasser an den Schlickfeldern im Vorgebirge des Hügellands.", description = "Aufseher Stillwasser drüben auf den Schlickfeldern nördlich von hier hat einen Notruf geschickt. Die Botschaft war nicht deutlich, aber ich entnehme dem Brief, dass es dort an den Schlickfeldern einen Aufstand gibt und dass die meisten Wachen getötet wurden. Der Aufseher hat ausdrücklich gesagt, dass eventuelle Möchtegern-Helden sich vom Hintereingang her nähern sollten, der sich auf der Westseite der Schlickfelder befindet.\n\nAußerdem hat er um Diskretion gebeten. Er möchte nicht, dass die Nachricht dieses kleinen *räusper* Aufstandes sich verbreitet.", progress = nil, completion = "Wer seid Ihr? Hat Sylvanas Euch geschickt? Alles ist BESTENS! Ja, vollkommen in Ordnung! Ich hab' alles unter Kontrolle!\n\nAlso, den Umständen entsprechend heißt das... Wir haben ein paar Probleme, bei denen Ihr vielleicht helfen könntet, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28169] = {title = "In den Laderaum zurückziehen!", objective = "Folgt den Helfern von S.I.C.H.E.R. zu Gaffer Spulfeder im Laderaum.", description = "Ausgezeichnete Arbeit, die anderen Überlebenden einzusammeln! Sie - und Ihr - sind der Grund, dass das S.I.C.H.E.R. Team immer wieder hier hinunter kommt. Nevin gibt keine Ruhe, bis nicht auch der letzte Überlebende gefunden und gerettet ist.\n\nIch schicke meine Leute in den Laderaum, um die Dekontamination vorzubereiten. Bitte folgt ihnen und sucht Gaffer Spulfeder bei Eurer Ankunft auf. Sie wird Euch für die Dekontamination vorbereiten und auf den Weg zur Oberfläche bringen.", progress = nil, completion = "Schön, Euch kennenzulernen, &lt;Klasse&gt;. Wir treffen nur selten Überlebende, die so stark und fähig sind wie Ihr. Ich kann Euch bei der Dekontamination helfen und dabei, hier herauszukommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28170] = {title = "Schrecken der Nacht", objective = "Sprecht mit Uchek im Rachen. Benutzt das Licht der Seelen aus dem Reich der Geister heraus, um Eure Sicherheit zu gewährleisten, wenn Ihr die drei Schreine in der Höhle besucht.", description = "Mein Freund Uchek ist schon in der Höhle. Wir haben da drin drei Schreine aufgebaut. Ihr müsst nur die bösen Geister aus ihnen vertreiben, Mann.\n\nGeht in die Höhle hier und redet mit Uchek. Er versetzt Euch in Trance und in das Reich der Geister. Seid vorsichtig! Wenn Ihr ein Geistungeheuer seht, keine Panik. Lasst das Licht der Seelen für 'nen Moment oder zwei darauf scheinen und das Licht wird sie für immer verscheuchen. Das Licht wird für Eure Sicherheit sorgen. Jetzt geht und säubert die drei Schreine.", progress = nil, completion = "Seht Ihr? Man muss keine Angst vor den Toten haben. Ihr habt das Licht in die Dunkelheit getragen, Mann, und nicht mal geblinzelt.\n\nJetzt können wir diese Höhle als Operationsbasis für das nördliche Hochland nutzen. Ihr seid doch der Beste, &lt;Name&gt;!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nJuju der GewandtheitUnheilslichtsymbolSchreinreinigender Läuterer\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28171] = {title = "... und der Himmel färbte sich rot", objective = "Schließt Euch dem Angriff gegen den schwarzen Drachenschwarm an.", description = "Da Todesschwinge anderweitig abgelenkt ist, stellt sich uns eine düstere und schwere Aufgabe, in der uns die Königin höchstpersönlich leiten wird. Der schwarze Drachenschwarm muss getilgt werden.\n\nEure Hilfe würde ich gern in Anspruch nehmen, wenn Ihr denn zur Verfügung steht. Sobald Ihr bereit seid, werde ich Euch mit der nächsten Angriffswelle losschicken.", progress = nil, completion = "Offensichtlich seid Ihr immer noch bei uns. Ich weiß das irgendwie zu schätzen.\n\nDanke.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28172] = {title = "Unschuldig", objective = "Beschafft einen befreiten roten Welpling, einen befreiten grünen Welpling, einen befreiten blauen Welpling und einen befreiten bronzefarbenen Welpling.", description = "Die Schwarzfelsorcs in der Steppe dienen einem finsteren Meister, der abartige Experimente an lebenden Wesen durchführt, um seine eigene Menagerie der Monstrositäten zu schaffen. Viele seiner Testobjekte sind so verderbt wie ihr Meister, aber ein paar davon sind vollkommen unschuldig.\n\nIn den Schlupfhügeln im Süden ketten sie Jungdrachen am Boden fest, um sie für solche Experimente vorzubereiten. Das lasse ich nicht zu. Zerbrecht ihre Fesseln und bringt die Brutlinge zu mir... in Sicherheit.", progress = "Ich hoffe, wir kommen nicht zu spät.", completion = "Ich werde mich darum kümmern, dass diese Drachen versorgt werden.", rewards = "WelpenpflegerstabJungtierbeschützerAuf Euch wartet eine dieser Belohnungen:\n\nFlammensternamulett\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28173] = {title = "Schwarz vor Augen", objective = "Benutzt die Wyrmjägerhaken, um 8 Obsidianflammenschwingen zu erreichen und tötet diese dann.", description = "Die Zwielichtdrachenjäger haben teuflische Werkzeuge angewendet, um unsere Drachen vom Himmel zu holen. Haken, die sich tief in die Schuppen bohrten und es den Anhängern des Zwielichts gestatteten, unsere Angehörigen gefahrlos zu Boden zu zerren.\n\nWir befinden uns jenseits aller Aussicht auf Frieden. Ohne Hoffnung, daß sie sich rückbesinnen werden. Die Vernichtung, der sie sich so leidenschaftlich hingeben, ist die einzige Gnade, die wir dem schwarzen Schwarm noch gewähren können.\n\nBenutzt diese Haken, um die Obsidianflammenschwingen südlich von hier zu töten. Richtig angewendet, verschaffen sie Euch in der Luft reichlich Bewegungsfreiheit", progress = nil, completion = "Ihr scheint diese verstörenden Werkzeuge mit Leichtigkeit einzusetzen.\n\nEs tröstet mich zu wissen, dass einige Werkzeuge des Bösen am Ende dazu benutzt werden können, um Leben zu retten. Alles erfüllt einen Zweck.", rewards = "WyrmjägerschiftungNachtschuppengurtDrachenschwingengamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28174] = {title = "Brennende Rache", objective = "Tötet 5 Jungdrachenbändiger des Schwarzfels und 5 Flammenschuppenbrutlinge.", description = "Die Schwarzfelsorcs geben nicht auf. Sie schwärmen über die Schlachtfelder im Osten, bereit, jeden Moment zuzuschlagen.\n\nSie haben mein Heimatland bereits einmal angegriffen. Ich bin hier um sicherzustellen, dass das nicht noch einmal geschieht.\n\nWenn Ihr auch nur im Entferntesten etwas für die Menschheit übrig habt, macht Ihr dasselbe. Also beweist Euch. Begebt Euch nach Süden zu den Schlupfhügeln und tötet ihre Jungdrachenbändiger und die ausgeschlüpften schwarzen Drachen. Beweist mir, dass Ihr für diesen Krieg bereit seid.", progress = nil, completion = "Ihr seid also dabei?\n\nGut.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28175] = {title = "Licht in der Dunkelheit", objective = "Benutzt Alexstraszas Träne in der Aushöhlung unter dem Obsidianbaum.", description = "Der große versteinerte Baum, der sich vor uns im Süden befindet, war einst ein Leuchtfeuer von großem Leben. Unser Leuchtfeuer. Wir haben diesen Wald an den schwarzen Schwarm verloren und seitdem ist er verdorben und versteinert. Es ist fast nicht rückgängig zu machen.\n\nAber noch ist nicht alle Hoffnung verloren. Ich habe ein mächtiges Werkzeug hergebracht, um den Heilungsprozess zu beginnen. Mit viel Zeit und Glück kann der Baum vielleicht noch gerettet werden - und mit ein wenig Anstrengung von Euch vielleicht.\n\nNehmt das hier, Alexstraszas Träne, und benutzt sie im hohlen Inneren des Baums.", progress = "Der schwarze Schwarm wird wahrscheinlich nie wieder rehabilitiert, aber auch nach all ihrer Zerstörung gibt es immer noch Hoffnung auf neues Leben.", completion = "Ihr habt heute etwas Wunderbares begonnen, mitten in all dem Blutvergießen.\n\nEs mag viele Jahre dauern, aber dieses Verwüstete Land wird wiederhergestellt werden. Es wird wieder wunderschön sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28176] = {title = "Folgt den Jungen heim", objective = "Benutzt die Flamme der Mutter auf Obsidianeiern, um Welpen hervorzubringen. Folgt diesen Jungen zum Hort ihrer Mutter.", description = "Im südwestlichen Teil des Obsidianwalds werdet Ihr einige Gelege schwarzer Eier finden. Viele Eier können jederzeit zum Schlüpfen gebracht werden, wenn die richtige Flamme sie ein wenig wärmt. Wenn die Welpen schlüpfen, werden sie einen Schrei ausstoßen und nach ihrer Mutter suchen.\n\nKeine Angst, wenn die Auslöschung sich auf die Welpen ausweiten sollte, werde ich Euch diese Aufgabe nicht aufzwingen. Ich möchte nur, dass Ihr sie heraus lasst und ihnen nach Hause folgt, wenn sie ihre Mutter suchen. Mit ihr müssen wir uns auseinandersetzen.", progress = "Kein schwarzer, brutfähiger Drache darf am Leben bleiben.", completion = "Lirastrasza hat mich bereits in der Annahme zum Hort vorausgeschickt, dass der Schwarzdrache, den wir suchen, vielleicht noch hier ist. Den Jungen nach zu urteilen, hat sie wohl recht gehabt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28177] = {title = "Aufstockung", objective = "Besorgt 5 rasiermesserscharfe Skorpidstachel.", description = "Wenn wir einen Krieg gegen den Schwarzfelsklan führen wollen, müssen wir vorausplanen. Mein Oberst hat bereits einen Plan geschmiedet - jetzt wird es Zeit, ihn in die Tat umzusetzen.\n\nIch brauche Skorpidstachel... die schärfsten, die Ihr finden könnt. Skorpide befinden sich überall in der Steppe, aber die meisten befinden sich in der Schlucht im Westen.\n\nZerbrecht Euch nicht den Kopf darüber, wofür sie sind. Das werdet Ihr noch früh genug herausfinden.", progress = "Schon zurück?", completion = "Man kann diese Skorpiden leicht unterschätzen. Ihr habt Glück, dass Ihr nicht an einem dieser Stachel steckt. Oder vielleicht seid Ihr einfach nur gut.\n\nIch füge sie dem Vorratslager hinzu. Wir sind noch nicht fertig, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\nScharfer Skorpidstachel"}
MultiLanguageQuestData['de'][28178] = {title = "Ein zukünftiges Projekt", objective = "Besorgt 11 Glutworgbälge.", description = "Wir werden Worgbälge brauchen und zwar viele. Es spielt keine Rolle, ob sie zerrissen, verbrannt oder blutig sind. Hauptsache es sind genügend.\n\nWahrscheinlich ist es sogar besser, wenn sie ein wenig ramponiert aussehen.\n\nWorgs findet Ihr im Westen und im Osten.", progress = "Dann schauen wir uns die Bälge mal an.", completion = "Glaubt mir, &lt;Name&gt;... Ich kann es genauso wenig wie Ihr abwarten, bis wir endlich zum Töten kommen. Aber wir müssen uns an den Plan halten. Das Jüngste Gericht kommt früh genug.\n\nIch werde diese Bälge hier aufbewahren.", rewards = "Ihr bekommt:\n\nGlutworgenauge"}
MultiLanguageQuestData['de'][28179] = {title = "Schlammschlacht", objective = "Besorgt 9 Haufen obsidiandurchsetzten Schlamm.", description = "Ich hoffe, Ihr habt keine Angst davor, Euch schmutzig zu machen. Aber wenn ich Euch so ansehe, dürfte das kein Problem sein.\n\nIm Norden am Rand der Lava findet Ihr dunkle Schlammhaufen. Den Schlamm brauche ich.\n\nAm besten stellt Ihr keine Fragen und konzentriert Eure Bemühungen darauf, Befehle zu befolgen, <Name>.", progress = "Ihr solltet Euch vor den Obsidianelementaren hüten. Sie schleichen sich gerne an.", completion = "Das ist genau das, was wir brauchen!\n\nKeine Sorge, &lt;Name&gt;... Das Orctöten wird noch früh genug kommen.", rewards = "Ihr bekommt:\n\nObsidiandurchsetzte Gugel"}
MultiLanguageQuestData['de'][28180] = {title = "Der Sand, der Apfelwein und die Kugel", objective = "Sprecht mit Gorzeeki Wildaug in der Nähe des Altars der Stürme.", description = "Oberst Trottmann wartet auf uns im Osten. Bevor wir uns auf den Weg machen, sollten wir allerdings noch etwas mehr Zeug zusammensuchen. Diesmal werdet Ihr es einem Hexenmeister mit Namen Gorzeeki Wildaug abnehmen.\n\nWahrscheinlich findet Ihr ihn im Nordwesten in der Nähe des Altars der Stürme. Sagt ihm, dass er uns helfen wird. Wir brauchen den Sand, den Apfelwein und die Kugel.\n\nEr weiß schon, was das bedeutet.", progress = nil, completion = "Bah! Wer seid Ihr?\n\nOh, also hat Keeshan Euch geschickt? Gut. Würde es Euch etwas ausmachen, wenn Ihr eine Weile hier bleibt? Nichts großes... Ihr müsst nur ein paar Hexenmeister für mich töten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28181] = {title = "Hexenmeister haben das beste Zeug", objective = "Besorgt eine Handvoll Schlummersand, einen Krug Teufelskarussellstöffsche und eine lupenreine Glaskugel.", description = "Keeshan sagte, er braucht Vorräte? Ich habe reichlich Vorräte! Das Problem ist nur, dass diese Hexenmeister mich aus meinem Zuhause geworfen haben und mich nicht wieder hineinlassen.\n\n<Gorzeeki mustert Euch.>\n\nIhr könntet vielleicht hineingelangen. Geht nach Norden und holt mir meinen Schlummersand, mein Teufelskarussellstöffsche und eine klare Glaskugel. Ich bin mir ziemlich sicher, dass es das ist, was er haben will.\n\nOh, und falls Ihr aus Versehen ein paar dieser Orcs tötet, während Ihr da oben seid, wäre ich bestimmt nicht traurig.", progress = "Mal sehen, ob Ihr alles bekommen habt.", completion = "Ich hoffe, dass ist das, wonach Keeshan gesucht hat. Im Moment kann ich jedenfalls nicht viel damit anfangen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28182] = {title = "Schattenboxen", objective = "Tötet Ner'gosh den Schatten.", description = "Ner'gosh der Schatten ist der Anführer dieser Hexenmeister, die sich nördlich von uns befinden. Er ist der Fiesling, der mich aus meinem Haus vertrieben hat, als diese Schwarzfelsorcs aufgetaucht sind. Nun, eigentlich sind sie alle Fieslinge, aber er ist der fieseste.\n\nWenn ich jemals in die Nähe des Altars zurückkehren möchte, muss Ner'gosh verschwinden.", progress = nil, completion = "So wie ich diese Orcs kenne, wird bald ein anderer seinen Platz einnehmen. Ich werde versuchen, mich zurück in den Altar zu schleichen, bevor das passiert.\n\nHabt Dank, mein Bester.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28183] = {title = "Rückkehr zu Keeshan", objective = "Bringt die Hexenmeisterausrüstung zurück zu John J. Keeshan am Flammensternposten in der Brennenden Steppe.", description = "Ich schätze, ich bin hier mit Euch fertig. Ich werde diese anderen Orcs davonscheuchen, sobald ich den Mut dazu gefunden habe.\n\nHier, vergesst Eure Vorräte nicht.", progress = "Sieht aus, als wärt Ihr mit Gorzeeki gut zurecht gekommen.", completion = "&lt;Keeshan wirft einen Blick in die Kiste.&gt;\n\nGut, gut, gut. Wir können weiter. Unser Krieg führt uns nach Osten, weg vom Schwarzfels... fürs Erste.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28184] = {title = "Meißelgriff, das Herz der Steppe", objective = "Tötet 15 beliebige Schwarzfelstruppen auf Eurem Weg nach Meißelgriff.", description = "Wir sind auf dem Weg nach Meißelgriff, das sich genau im Herzen dieser Steppe befindet. Wir treffen uns dort mit der Thoriumbruderschaft und außerdem mit Trottmann.\n\nSeid Ihr mit der Bruderschaft vertraut? Diese Dunkeleisenzwerge haben mir mehr als einmal geholfen. Wir brauchen ihre Hilfe vielleicht erneut.\n\nWir kommen auf unserem Weg dorthin durch den Schwarzzahnunterschlupf. Was haltet Ihr davon, wenn wir unterwegs ein paar Orcs töten? Ich werde in diesem Lager langsam ein wenig unruhig.", progress = nil, completion = "Ihr müsst mich entschuldigen, aber wir empfangen derzeit keine Besucher. Ich bitte Euch, Meißelgriff auf demselben Weg wieder zu verlassen, den Ihr gekommen seid.\n\nOh, Keeshan... Seid Ihr das?", rewards = "WillkommenswesteSchwarzzahnhelmEntlastete SchulterstückeErzknöchels GewehrIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28185] = {title = "Svarnos", objective = "Ihr müsst Svarnos im D-Block töten und mit seinem verfluchten Halsband zurückkehren. Svarnos hält sich im D-Block auf, direkt nordwestlich der Baradinfestung.", description = "Ihr habt bei der Eroberung der Insel ausgezeichnete Arbeit geleistet, <Klasse>. Jetzt, wo wir die Insel in Besitz genommen haben, müssen wir diese Zellenblocks für Gefangene herrichten. Der D-Block erweist sich als besonders schwer zu säubern. Unglücklicherweise wird er von zahlreichen Dämonen und Ähnlichem heimgesucht.\n\nWir konnten die Dämonen etwas dezimieren, aber ein großer Kernhund hat sich aus seiner Zelle freigekämpft und richtet dort unten Chaos und Verwüstung an. Ihr müsst ihn töten und mir sein Halsband bringen.", progress = "Ist der Kernhund tot?", completion = "Svarnos ist endlich tot? Sieht so aus, als ob wir uns zu guter Letzt an die Arbeit machen können, den Zellenblock herzurichten. Habt Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28186] = {title = "Verfluchte Fesseln", objective = "Ihr wurdet gebeten, 8 verfluchte Fesseln aus dem D-Block zu beschaffen, der direkt nordwestlich der Baradinfestung liegt.", description = "Wart Ihr schon im D-Block, <Name>? Jedes Mal wenn wir den verseuchten Zellenblock leerräumen, scheinen diese Dämonen ziemlich schnell zurückzukehren. Wir haben herausgefunden, dass sie sich mithilfe der verfluchten Fesseln regenerieren, die in dieser Gegend verstreut herumliegen. Und da kommt Ihr ins Spiel, <Name>.\n\nIhr müsst so viele dieser Fesseln wie möglich einsammeln und zu mir bringen. Wir werden sie dann unverzüglich zerstören.", progress = "Habt Ihr viele Fesseln gefunden? Den Berichten zufolge liegen sie dort überall verstreut herum.", completion = "Die Fesseln! Wir werden sofort mit der Zerstörungsprozedur dieser Fesseln beginnen, &lt;Name&gt;. Habt Dank für Eure Hilfe.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28187] = {title = "Um Haaresbreite!", objective = "Sprecht mit Kommandant Schnottz, wenn Ihr bereit seid, ihn aus dem brennenden Gebäude zu geleiten.", description = "Also gut, <Volk>! Aus Spaß ist gerade Ernst geworden!\n\nJemand glaubt wohl, dass er mich so leicht loswerden kann, wie?\n\nDas werden wir ja sehen! Nichts kann diese Arbeit aufhalten! Nichts!\n\n<Schnottz sieht auf das Feuer, das sich überall ausbreitet.>\n\nWir sollten vermutlich von hier verschwinden.\n\nBeeilung! Keine Zeit verschwenden!", progress = nil, completion = "In Zeiten wie diesen, stellt man fest, wer seine wahren Freunde sind...", rewards = nil}
MultiLanguageQuestData['de'][28188] = {title = "Gefangenenaufstand", objective = "Ihr wurdet beauftragt, 10 beliebige Gefangene im Loch zu töten, das südwestlich der Baradinfestung liegt.", description = "Die Insel gehört uns. Jetzt müssen wir unsere Anlagen hier einsatzbereit machen. Wir haben einen aufgegebenen Zellenblock südwestlich von hier gefunden und wir müssen ihn auskundschaften, <Name>.\n\nBerichten zufolge ist er voller Gefangener, die dort drinnen seit Jahren festsitzen. Tut, was immer ihr müsst, um den Ort zu säubern. Meldet Euch bei mir, wenn Ihr fertig seid.", progress = nil, completion = "Ihr habt das Gebiet gesäubert? Es sieht so aus, als ob Ihr Euch als nützlicher erweist, als wir dachten, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28189] = {title = "Das Richtige tun", objective = "\"Rettet\" 15 menschliche Keimlinge.", description = "Euch bietet sich ein entsetzlicher Anblick. Jemand hat alle Menschen bis zum Hals eingegraben, sodass sie aussehen wie eingepflanzt. Die Ghule, die anscheinend dieses Feld von menschlichen Keimlingen pflegen, springen in regelmäßigen Abständen zum nächstgelegenen Menschen und fressen seine Kopf!\n\nIhr könnt dies hier und jetzt beenden. Nehmt diese Schaufel und \"rettet\" die Menschen.\n\nTut das Richtige.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSchaufel der Gnade"}
MultiLanguageQuestData['de'][28190] = {title = "Der besudelte Schlamm", objective = "Vernichtet 8 besudelte Schlämme.", description = "Dies alles begann mit Winna Hazzard. Sie war eine Apothekerin der Verlassenen im Blutgiftposten, die Methoden erforschte, wie man den dämonischen Schlamm gegen die Allianz einsetzen könnte.\n\nWir haben sie davor gewarnt, sie würde zu weit gehen, aber sie wollte nicht hören. Und wir haben nicht schnell genug gehandelt. Jetzt sind sie und jeder andere im Blutgiftposten nichts weiter als hirnlose Schleimkreaturen...\n\nDie widerlichen Schlämme, die sie verwendet hat, streifen noch immer in der Nähe der Tümpel im Süden umher. Ich flehe Euch an, <Klasse>, zerstört sie, sodass sie nicht weiterhin so viel Böses verbreiten können.", progress = "Schon allein der Gedanke an diese ekelerregenden Kreaturen macht mich krank! Urgh...", completion = "Mein Zorn wird durch diese Neuigkeiten gemildert... Vielleicht wird es mir jetzt leichter fallen, mich zu erholen und zu genesen.\n\nUnd vielleicht wird sich mein Magen ebenfalls beruhigen. Urgh...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28191] = {title = "Ein passendes Ende", objective = "Tötet 10 Obsidianwyrmkin.", description = "Die Obsidianwyrmkin sind überall über die Landschaft südlich von uns verstreut. Sie sind nicht in der Lage, uns zurückzuschlagen, aber man kann nie wissen, welche neuen Gefahren die Schlacht mit sich bringt.\n\nIch will, dass Ihr die Wyrmkin angreift. Vernichtet sie, sodass wir damit fortfahren können, dieses Land von der verunreinigenden Anwesenheit des schwarzen Drachenschwarms zu befreien.", progress = nil, completion = "Ihr habt Euch als ein wichtiger Verbündeter erwiesen. Nach unserer ersten Begegnung hätte ich niemals damit gerechnet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28192] = {title = "Niemand kommt hier lebend heraus", objective = "Schätzt die Situation auf den Schlickfeldern ein.", description = "Dieser Hof ist abgeriegelt! Nichts und niemand kommt hier heraus! Wir analysieren noch immer die Lage und versuchen, herauszufinden, was genau geschehen ist. Aber meiner Theorie nach aßen die Arbeiter die Pilze und sind irgendwie zu abscheulichen, untoten Monstern mutiert. Ich meine, wie sonst könnte so etwas passiert sein? Dies ist nur ein Hof! Wir produzieren hier Pilze! Und Schlamm! Ja, Schlamm!\n\nSeht Euch um, <Klasse>, denn jetzt wo Ihr hier seid, könnt Ihr nicht fort, bis diese Angelegenheit geklärt ist.\n\nSeht selbst!", progress = nil, completion = "Wie Ihr sehen könnt, sie sind alle zu Monstern geworden! Die meisten meiner Wachen starben und diejenigen, die es geschafft haben, zu entfliehen, verteidigen jetzt die Barrikaden, um zu verhindern, dass diese möglicherweise gefährlichen Kreaturen herauskommen.\n\nWir brauchen Eure Hilfe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28193] = {title = "Abgeriegelt!", objective = "Kommandant Schnottz will, dass Ihr die Gäste in Schnottz' Landeplatz überwacht.", description = "Das Gebäude ist nicht von alleine explodiert!\n\nJemand hat versucht, mich abzumurksen und Ihr werdet nicht ruhen, bis ich herausgefunden habe wer!\n\nBleibt bei den Gästen. Mischt Euch unter sie, beobachtet ihr Verhalten und dann meldet Euch wieder bei mir.\n\nWenn sie irgendetwas wissen sollten, werde ich sie verhören lassen!\n\nWegtreten!", progress = nil, completion = "Sie wissen nichts, sagt Ihr?\n\nAlso gut. Die Suche geht weiter...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28194] = {title = "Die große Flucht", objective = "Der produktive Schriftsteller in Schnottz' Landeplatz will, dass Ihr 6 frische Seemannsuniformen von Seemännern von Schnottz einsammelt.", description = "Bitte, <Klasse>! Wir brauchen Eure Hilfe!\n\nWir werden gegen unseren Willen in diesem Gebäude gefangen gehalten. Und da der Kommandant so schlecht gelaunt scheint, wissen wir nicht, was er uns antun wird.\n\nWenn Ihr uns ein paar Uniformen ergattern könntet, können wir uns davon schleichen.\n\nWir hätten niemals hierher kommen sollen. Das ist mir jetzt klar.\n\nWenn Ihr uns helft, zu fliehen, werde ich die WAHRHEIT über das aufschreiben, was hier passiert ist.\n\nDie Männer auf den Schiffen tragen alle die Kleidung, die wir benötigen.", progress = "Wart Ihr in der Lage, uns ein paar Uniformen zu besorgen, <Volk>?", completion = "Die sind perfekt, &lt;Klasse&gt;.\n\nWünscht uns Glück!", rewards = "Maske des falschen GesichtsStulpen des ObeliskenSpiegelblank polierte StiefelFormeller Baton des OffiziersDer folgende Zauber wird auf euch gewirkt:\n\nThe Great Escape Initialize\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28195] = {title = "Eine Botschaft senden", objective = "Kommandant Schnottz will, dass Ihr Kapitän Margun, Kapitän Cork und Kapitän Kronkh tötet.", description = "Ich habe meine Augen und Ohren in jedem Winkel dieser Gegend, <Volk>.\n\nIch habe gehört, was unter meinen Truppen getuschelt wird. Ich war diesem erbärmlichen Verhalten gegenüber äußerst tolerant – bis jetzt!\n\nIch werde eine Botschaft an jeden in meinen Reihen senden. Zwietracht wird nicht länger geduldet! \n\nIhr sollt die Kapitäne auf den Schiffen in meiner Anlegestelle töten. Sie sind von der besonders entrüsteten Sorte.\n\nWenn das vollbracht ist, werde ich die Ohren weiter spitzen und entscheiden, was als Nächstes zu tun ist. \n\nWegtreten!", progress = nil, completion = "Sehr gut, &lt;Volk&gt;...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28196] = {title = "Kampf um das Hügelland", objective = "Bringt \"Kampf um das Hügelland\" zu Aufseher Stillwasser bei den Schlickfeldern im Vorgebirge des Hügellands.", description = "Das Tagebuch beschreibt die letzten 62 Tage aus Amtmann Horatio Weißross' Leben. Es enthält vernichtende Behauptungen gegen Aufseher Stillwasser und seine Taten auf den Schlickfeldern.\n\nIhr solltet es dem Aufseher zeigen. Er wird für das, was in diesem Tagebuch beschrieben steht, zweifellos eine Erklärung haben.", progress = "Was ist das?", completion = "&lt;Aufseher Stillwasser blättert durch das Tagebuch und liest leise.&gt;\n\nGeschwafel eines Verrückten! Er hatte offensichtlich zu viele Pilze gegessen. Es ist gut, dass Ihr mir das gebracht habt, &lt;Name&gt;. Ich werde es eigenhändig verbrennen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28197] = {title = "Diskretion ist der Schlüssel", objective = "Tötet Bürger Wilkes und Amtmann Horatio Weißross.", description = "Wir müssen alle Beweise vernichten, <Name>! Sagte ich Beweise? Ich meinte natürlich verrückte Untote! Auf jeden Fall ist Vorsicht die Mutter der Porzellankiste. Wir dürfen nicht zulassen, dass diese wilden Untoten aus den Schlickfeldern entkommen und niemand außerhalb dieser Anlage darf wissen, was hier geschehen ist!\n\nGenau südöstlich von hier liegt das, was mal der Pilzhof war. Dort findet Ihr einen wiederbelebten Feind namens Bürger Wilkes mit seinem Kollegen Amtmann Horatio Weißross. Sie haben meinen Wachen einige Probleme bereitet. Findet sie und tötet sie!", progress = nil, completion = "Gut gemacht! Wilkes wurde gehängt, nachdem wir herausgefunden haben, dass er massenhaft von diesen Pilzen und andere hochgiftige Substanzen zu sich genommen hat. Nach seinem Tod wurde er als untoter Geist wiedergeboren. Viele meiner Wachen fielen Wilkes zum Opfer, bevor er davonrannte und sich versteckte. Wir fürchten, dass so etwas noch einmal passieren könnte und verbrannten deshalb den Amtmann, bis nur noch Knochen von ihm übrig waren!\n\nWarum sie freiwillig, giftige Substanzen zu sich genommen haben? Ich habe keine Ahnung! Dies ist ein gewöhnlicher Hof, mein Herr, nichts weiter!", rewards = "Armbrust des zweifach GetötetenAmtmann Weißross' UmhangAuf Euch wartet eine dieser Belohnungen:\n\nBürger Wilkes' Ring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28198] = {title = "Das schwächste Glied", objective = "Sprecht mit Salhet am Außenposten der Legion von Ramkahen in Uldum.", description = "Man sagt, eine Kette sei immer so stark wie das schwächste Glied.\n\nIch unterschreibe diese Theorie und baue sie sogar noch weiter aus.\n\nAnstatt das schwächste Glied zu entfernen, muss man es... stärken. \n\nDie anderen Glieder werden ihre Leistungen aus Angst erhöhen, dass sie selbst das schwächste Glied werden.\n\nIm Falle meiner Armee, hat unser schwächstes Glied einen Namen. Salhet.\n\nIhr findet ihn beim Üben am Fuße dieser Stufen.\n\nFangt bei ihm mit etwas Leichtem an. Die Hyänen auf den Hügeln im Westen vielleicht.", progress = nil, completion = "Es ist eine große Ehre, Euch kennen zu lernen, &lt;Name&gt;! Ich habe viel von Euch gehört.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28199] = {title = "Für die Wissenschaft!", objective = "Beschafft 6 Fleischproben.", description = "Proben... jaaa... brauche Proben! Diese, öhm, Experimente... Ich meine, diese unglücklichen Arbeiter müssen untersucht werden.\n\nReist nach Südosten zum ersten Hof und tötet die auferstandenen Ghule. Ihr müsst aus ihren verfaulten Körpern Fleischproben entnehmen. Bringt diese zu mir!\n\n<Arnauld reibt sich die Hände und lacht wie wahnsinnig - ohne erkennbaren Grund.>\n\nMuss forschen!", progress = "Für die Wissenschaft!", completion = "Diese Proben werden uns ein besseres Verständnis dieser hirnlosen Untoten geben. Nehmt diese Münzen als Belohnung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28200] = {title = "Versorgungslücke", objective = "Sammelt 20 gehärtete Krokiliskenbälge.", description = "Ihr habt sicher bemerkt, dass wir für eine Schlacht eher leidlich gerüstet sind. \n\nDie Stämme der Tol'vir standen Jahrtausende lang vor keiner Auseinandersetzung dieses Ausmaßes.\n\nSämtliche Kampfprotokolle, welche die Titanen unseren Vorfahren einprogrammierten, sind aber noch vorhanden. Manche sind Teil unserer Instinkte, andere werden als Tradition weitergegeben.\n\nAber das alles kann eine Versorgungslücke nicht ausgleichen. Wir brauchen Waffen. Wir brauchen Rüstungen.\n\nDie besten Rüstungen sind mit dem Leder der Flusskrokilisken aus dieser Gegend gefüttert. Helft uns, ein paar zu sammeln.", progress = "Es freut mich, zu sehen, dass Ihr Euch nicht über diese Art von Aufgabe erhaben fühlt.", completion = "Gute Arbeit, &lt;Name&gt;. Ihr glaubt vielleicht nicht, dass dies sonderlich nützlich ist, aber es kann für einen unserer Soldaten durchaus den Unterschied zwischen Leben und Tod ausmachen.", rewards = "Beinplatten von HeilopolisKartuschenbeschriebene SchiftungSarkophagarmschienenMesser der giftigen AspisviperIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28201] = {title = "Pflugscharen zu Schwertern", objective = "Rekrutiert 8 Arbeiter von Ramkahen.", description = "Wir haben eine beachtliche Armee, aber ich befürchte, dass das herannahende Kräftemessen mit den Tol'vir der Neferset es erforderlich macht, alle Tol'vir von Ramkahen und Orsis in den Kampf mit einzubinden.\n\nIch will, dass Ihr an der Spitze unserer Rekrutierungsbemühungen steht.\n\nBegebt Euch über den Fluss zu den Feldern von Akhenet und rekrutiert die Arbeiter, die dort ihrem Tagewerk nachgehen.", progress = nil, completion = "Ihr seid ein geborener Anführer, &lt;Name&gt;. Es wäre gut, Euch an unserer Seite zu wissen, wenn der Krieg diese Länder erreicht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28202] = {title = "Ein perfektes Kostüm", objective = "Bringt die angemessene Menge an Gegenständen vom Schneidertisch zu Thelaron Düsternadel in Meißelgriff.", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als einen Orc verkleiden. Ihre Armee besteht hauptsächlich aus Orcs, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.", progress = nil, completion = "Das soll sie sein? Das ist Eure Verkleidung?\n\nIch habe das Gefühl, dass unsere Chancen rapide sinken. Es war schön, Euch kennengelernt zu haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28203] = {title = "Ein perfektes Kostüm", objective = "Bringt die angemessene Menge an Gegenständen vom Schneidertisch zu Thelaron Düsternadel in Meißelgriff.", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als Oger verkleiden. Die Oger der Feuermägen haben immer für die Schwarzfelsorcs gearbeitet, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.", progress = nil, completion = "Das soll sie sein? Das ist Eure Verkleidung?\n\nIch habe das Gefühl, dass unsere Chancen rapide sinken. Es war schön, Euch kennengelernt zu haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28204] = {title = "Ein perfektes Kostüm", objective = "Bringt die angemessene Menge an Gegenständen vom Schneidertisch zu Thelaron Düsternadel in Meißelgriff.", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als Goblin verkleiden. Die Schwarzfelsorcs haben schon immer goblinische Söldner angeheuert, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.", progress = nil, completion = "Das soll sie sein? Das ist Eure Verkleidung?\n\nIch habe das Gefühl, dass unsere Chancen rapide sinken. Es war schön, Euch kennengelernt zu haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28205] = {title = "Ein perfektes Kostüm", objective = "Bringt die angemessene Menge an Gegenständen vom Schneidertisch zu Thelaron Düsternadel in Meißelgriff.", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als Troll verkleiden. Die Gluthauertrolle haben stets mit den Schwarzfelsorcs zusammengearbeitet, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.", progress = nil, completion = "Das soll sie sein? Das ist Eure Verkleidung?\n\nIch habe das Gefühl, dass unsere Chancen rapide sinken. Es war schön, Euch kennengelernt zu haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28206] = {title = "Schönling auf Abwegen", objective = "Findet Johnny Imba in den Schlickfeldern im Vorgebirge des Hügellands.", description = "Es war erst gestern, dass ich ihn losschickte, um den Bauernhof östlich von hier zu untersuchen, aber es fühlt sich an wie eine Ewigkeit!\n\nWahre Perfektion. Wie seine blonden Locken sein makelloses Elfengesicht umrahmen... Und erst diese Stärke. Ich wollte ihn gar nicht gehen lassen, aber er hat darauf bestanden! Und wie könnte ich ihm einen Wunsch abschlagen, wenn er mich mit seinen strahlenden Augen ansieht...\n\nAber jetzt ist Johnny Imba nicht zurückgekehrt! Ich befürchte das Schlimmste, <Name>. Findet ihn!", progress = nil, completion = "&lt;Johnny schluchzt laut.&gt;\n\nGl... Glitzer!!! Di... Er hat sie getötet!\n\n&lt;Johnny heult weiter.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28207] = {title = "Eine schleimige Angelegenheit", objective = "Sammelt 7 smaragdgrüne Schimmerkappen.", description = "Dieser arme Tauren hier ist bei der Flucht aus dem Blutgiftposten nur knapp mit dem Leben davon gekommen! Wenn wir verhindern wollen, dass er sich, wie all die anderen, in eine Schleimkreatur verwandelt, werden wir die Infektion behandeln müssen.\n\nIn der Nähe der hellen, grünen Gewässer in dieser Gegend wachsen viele Pilze. Zum Beispiel am Teich im Osten, zwischen den Wasserfällen. Die meisten von ihnen sind zu nichts zu gebrauchen... Aber die hellgrün leuchtenden müsst Ihr für mich sammeln!\n\nAus ihnen kann ich etwas Schmackhaftes zubereiten, das dem Armen hilft. Lasst Euch nicht zu viel Zeit!", progress = "Denkt daran, die hellgrün leuchtenden Pilze!", completion = "Die meisten Leute denken, dass das grüne Leuchten auf dämonische Verderbnis hinweist... aber wenn man ein Auge für Farben und Schattierungen hat, dann kann man sehen, dass dies die Energien des Smaragdgrünen Traums sind! Diese kleinen Pilze werden nicht durch die Gewässer verdorben, sondern sie tun ihr Bestes, um sie zu läutern!\n\nJetzt pürieren wir sie und machen einen leckeren Brei für den Herrn Tauren. Wenn er die gegessen hat, wird er sich besser fühlen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28208] = {title = "Winnas Kätzchen", objective = "Beschafft Miezis Ohrmarke von Winnas Kätzchen.", description = "Herr Tauren hat mir viel darüber berichet, was am Blutgiftposten geschehen ist. Er sagte Winna Hazzard ist noch immer dort!\n\nSie ist nicht mehr zu retten, aber was von ihr übrig ist, produziert reichlich neuen Schleim. Wir müssen ihn aufhalten!\n\nGlücklicherweise habe ich einen Plan. Herr Tauren sagte, Winna hätte früher ein Kätzchen gehabt. Sie hat ihm verdorbenes Schleimwasser zu trinken gegeben. Daraufhin ist es in die Wälder gelaufen. Ich sah im Südwesten hinter dem Blutgiftturm etwas herumschleichen, aber es war größer als ein Kätzchen! Seht mal nach, ob das Miezekätzchen eine Ohrmarke trägt...", progress = "Habt Ihr das Kätzchen gefunden?", completion = "Armes kleines Miezekätzchen, leidet schon so lange dort draußen in den Wäldern! Ihr habt dem armen Ding etwas Gutes getan, &lt;Name&gt;. Und auch all den Reisenden, die es noch gefressen hätte.\n\nDiese Ohrmarke wird sich als nützlich erweisen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28209] = {title = "Freiheit für Lydon", objective = "Findet Lydons Käfigschlüssel.", description = "Das hier ist kein Hof! Stillwasser hat an den Menschen vom Hügellandhof Experimente durchgeführt. Diese Monstrositäten hier sind alles seine Schöpfungen.\n\nDas ist nicht das Schlimmste daran, <Klasse>. Diese Entartungen, die den Schlüssel zu meinen Käfig haben, sind ehemalige Verlassene. Stillwassers Experimente haben die Nebenwirkung, Verlassene in hirnlose Zombies zu verwandeln. Warum glaubt Ihr, dass er so viel Angst davor hat, dass dies hier herauskommt? Er weiß, dass so ein Verbrechen mit dem endgültigen Tod bestraft wird.\n\nHolt mich hier raus! Die infizierten Schlickwachen dort draußen haben den Schlüssel!", progress = "Findet den Schlüssel!", completion = "&lt;Lydon nimmt Euch den Schlüssel ab.&gt;\n\nIch lasse mich selbst raus, danke.\n\nIch war noch nie so wütend! Stillwasser kommt damit nicht davon. Ich werde seinen Kopf persönlich der Bansheekönigin präsentieren.\n\nWir beide arbeiten zusammen, &lt;Name&gt;.\n\nIch weiß ja nicht, was den Burschen da angeht, aber am liebsten wäre mir, wenn er zurückbleibt.", rewards = "Anormale WesteMonströser SchildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28210] = {title = "In Form bringen", objective = "Helft Salhet dabei, 8 Murrbluthyänen zu töten.", description = "Hochkommandant Kamses hat eine spezielle Aufgabe für mich?\n\nWartet... sagt es mir nicht. Es sind wieder die Hyänen, richtig?\n\nNun gut, ich werde mein Bestes geben.\n\nTrefft mich am Sonnenbehütergrat.\n\nIch werde Euch nicht enttäuschen.", progress = "Wie viele haben wir?", completion = "Nun... Das war nicht so richtig gut, oder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28211] = {title = "In Elementarflammen gehärtet", objective = "Sammelt 8 gehärtete Speere.", description = "Das Wichtigste zuerst: Wir werden Munition brauchen. Munition, die stark genug ist, die Panzerhaut eines Schwarzdrachen zu durchschlagen. \n\nWestlich von Donnermar ist eine Stadt des Wildhammerklans, die von unbändigen Feuerelementaren überrannt wurde. Jede Waffe, die in dem Großbrand zurückgelassen wurde, wird in den Elementarflammen gehärtet worden sein. Es ist jetzt härter als alles, was ich in dieser Schmiede auf die Schnelle herstellen könnte!\n\nBringt mir Speere aus der Humboldtfeuersbrunst, <Name>. Je spitzer desto besser.", progress = "Speere, ja? Meine Schnellfeuerspeerharpune wäre ohne sie nutzlos.", completion = "Seht Euch das an – AUTSCH! Spitz! Heiß!\n\nDiese Speere sollten durch den Drachenpanzer schneiden wie ein elektrischer Käsehobel durch warme Butter.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28212] = {title = "Heißes Zeug", objective = "Sammelt 5 Kügelchen glühenden Zorn.", description = "Ich habe einen Plan, wie wir das empfohlene Drehmoment für eine Speerharpune dieser Größe vervierfachen könnten, aber meinen Berechnungen zufolge würde das Abfeuern dieser Waffe das Gehäuse zerspringen lassen. Und eventuell noch den Planeten in zwei Teile spalten.\n\nIch kann ein Gehäuse zusammenschweißen, das hundertmal stärker ist, wenn ich eine zuverlässige Quelle reiner Elementarflammen für die Verhüttung hätte.\n\nUngebundene Glutbiesten wüten in der Gegend westlich von hier in der Humboldtfeuersbrunst. Wenn man sie tötet, sollten sie auf die Größe von Kügelchen glühenden Zorns schmelzen. Bringt mir ein paar!", progress = "Habt Ihr den glühenden Zorn? Nein, nein, gebt sie mir nicht in die Hand. Hier, verwendet die Zangen!", completion = "Wunderbar! Ich werde dieses Erz zu einer köstlichen Suppe verschmelzen. Eine glühende Suppe. Aus flüssigem Metall.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28213] = {title = "Giftmüllbeseitigung", objective = "Verwendet Miezis Ohrmarke, um Winna Hazzards Aufmerksamkeit zu erregen und dann vernichtet sie.", description = "Winna ist in die Quelle des Schleims am hinteren Ende des Blutgiftpostens im Westen eingeklinkt. Sie sorgt dafür, dass der Schleim weiter fließt und der Brunnen sorgt für ihren Schutz! Aber wenn Ihr ihre Aufmerksamkeit erregen könnt...\n\nNehmt die Ohrmarke und zeigt sie Winna. Wenn nur ein kleines bisschen von der alten Winna in ihr übrig ist, kommt es vielleicht zum Vorschein. Vielleicht wird ihr Bedauern für ihre arme, verlorene Miezi Oberhand gewinnen, vielleicht wird sie noch einmal Mitleid haben und sie wird vielleicht aus dem Schleim herauskommen!\n\nUnd dann könnt Ihr sie vielleicht töten und den Schleim aufhalten. Juhu!", progress = nil, completion = "Hurra! Der Wald wird jetzt sicherer sein!\n\nIhr seid $gein solcher Held;eine solche Heldin;, &lt;Name&gt;! Für alles, was Ihr für mich und Herrn Tauren und die Bäume und die Tiere und Blumen getan habt, verdient Ihr eine Belohnung!\n\nJuhu!", rewards = "Blumiger MantelBlattlieds WesteHerrn Taurens StiefelGürtel des BedauernsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28214] = {title = "Den Blutgiftposten säubern", objective = "Tötet 6 Schleimsklaven des Blutgiftpostens.", description = "Hurg...\n\nKönntet Ihr... uh... Könntet Ihr bitte... HUÄRG!\n\nEntschuldigt, mir ist ein wenig... uh, mein Magen. Wenn Ihr Euch zum Blutgiftposten im Westen begebt, könntet Ihr bitte HUURG...\n\nBe... Befreit einfach das, was von meinen Freunden übrig ist, von ihrem Elend. Und geht JETZT. In Eurem eigenen Interesse. Uuuuurg...", progress = nil, completion = "Habt Dank, &lt;Klasse&gt;. Ich fühle mich viel besser und es ist gut, dass diese Monstrositäten fort sind.\n\nIhr solltet Euch vielleicht trotzdem ein wenig von mir fernhalten. Sicherheitshalber...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28215] = {title = "Potentielle Energie", objective = "Sammelt 10 gewundene Spulen aus Elementium.", description = "Wie Ihr wisst, ist die Menge an Energie, die in einer herkömmlichen Feder gespeichert ist, gleich der Hälfte der Elastizität der Feder multipliziert mit der Weggröße im Quadrat. Es sei denn, man verwendet eine Elementiumfeder. Dann werden die Zahlen irrsinnig groß! Mathematisch gesehen grotesk! \n\nIch brauche ein paar Elementiumkreise für meine Geheimwaffe und wie es nun mal so ist: Die Schattenhammerkultisten verwenden Spulen wie diese, um die Erdelementare zu binden.\n\nFindet sie an den Obsidiansteinsklaven östlich von hier in der schrecklichen Region, die Schwarzer Riss genannt wird.", progress = "Wenn Ihr jetzt haufenweise Elementiumspulen aus Eurem Rucksack zieht, dann macht Ihr mich zu einem sehr glücklichen Gnom!", completion = "Ausgezeichnet! Diese Schätzchen werden sich mit der Kraft von tausend Sonnen entspannen!\n\nDas ist natürlich nur eine grobe Schätzung. Macht mich ja nicht für diese Zahlen verantwortlich!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28216] = {title = "Magmalord Falthazar", objective = "Sammelt den Kopf von Magmalord Falthazar.", description = "Ich habe gerade die schlimmen Nachrichten aus dem Westen gehört. Wir haben Humboldts Siedlung verloren. Sie wurde einfach von einer Feuerwand von dieser Welt getilgt!\n\nSchuld daran ist der Schattenhammer. Die Überlebenden sagen, es wäre das Werk eines gewissen Magmalord Falthazar. Er ist einer der Aszendenten. So nennen sie den höchsten Rang unter den Schattenhammerkultisten, die eins mit den Elementen werden. Er ist ein Wesen aus reinem Feuer.\n\nUnd bald wird er ein Wesen aus reinem Tod sein! Tötet Falthazar bei der Humboldtfeuersbrunst und bringt mir seinen Kopf!", progress = "All die Jahre dachte der alte Humboldt, Stopfwampes Oger auf dem Gebirgskamm wären sein größtes Problem. Doch dann kam der Schattenhammer.\n\nIn nur einem Wimpernschlag setzten sie das ganze Tal in Flammen, als wäre es eine Geburtstagstorte. Herzlos.", completion = "Jep, genau das ist er. Kaum vorzustellen, dass das hier einmal ein Mensch war.\n\nDa seht Ihr das wahre Gesicht des Schattenhammers. Was sie nicht vernichten, verderben sie.\n\nVielen Dank, &lt;Klasse&gt;.", rewards = "Beinplatten der abgekühlten MagmaFeuerfeste TreterVerderbnisresistente HandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28217] = {title = "Gesucht: Der Dämonenjäger", objective = "Tötet Feronas Sündschwelger.", description = "Seit der Jadefeuerbach von den Dämonen zurückerobert wurde hat der Smaragdkreis viele Druiden geschickt, um die langwierige Läuterung der Ruinen zu beginnen. Letzte Nacht wurden gleich mehrere von ihnen ermordet... von einem Nachtelf!\n\nZeugen berichten, dass der Täter ein Dämonenjäger war, einer von Illidans geisteskranken Schülern. So etwas sieht man nicht alle Tage. Ohne Zweifel hat die Macht ihn wahnsinnig gemacht, genau wie seinen Meister.\n\nIch bezahle gutes Geld für einen Beweis dafür, dass dieser Mörder tot ist. Man hat ihn zuletzt abseits der Straße im Norden in einem Tal unter dem Jadefeuerbach gesehen.", progress = "Haben sie jemand anderen geschickt?", completion = "Wie edel von Euch... einfach ohne zu fragen auf eine Mordmission zu gehen und meinen Kopf zu verlangen, nur weil ein anderer Euch darum bittet.\n\nZügelt Euren Zorn und hört Euch zuerst meine Geschichte an. Ihr werdet sehen, was edles Unwissen diesem Land angetan hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28218] = {title = "Ein Schicksal voll Feuer und Leid", objective = "Nehmt an Illidans Schlacht gegen Arthas teil.", description = "Meinesgleichen wurde schon immer für das gehasst, was wir tun... Verabscheute Ausgestoßenene, denen eine nicht mehr heilbare Verderbtheit vorgeworfen wurde.\n\nDoch es ist der Verdienst eines Dämonenjägers, dass diese Wälder hier nicht die größte Bastion der Brennenden Legion in Azeroth sind. Ich spreche von meinem Meister Illidan Sturmgrimm, dem \"Verräter\".\n\nSeht selbst. Seht, was hier geschehen ist, als Illidan befreit wurde und die dämonischen Mächte des Schreckenslords Tichondrius ohne Gegenwehr über diesen Wald herrschten...", progress = nil, completion = "Und so machte sich mein Meister auf, um den Schädel zu suchen... Er riskierte erneut sein Leben im Kampf gegen eine Armee von Dämonen, um den Quell der Verderbnis des Teufelswalds zu finden. Stellt Euch nur vor, er hätte es nicht getan! Stellt Euch vor, wie es hier aussehen würde, wenn der Schädel von Gul'dan sein Werk ungehindert fortgesetzt hätte...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28219] = {title = "Brummer fürs Baby", objective = "Tötet 10 Eisenholzbrummer, um den Beschützersetzling zu füttern.", description = "<Der winzige Setzling breitet seine Blätter weit aus, wie ein Jungvogel, der gefüttert werden möchte. Er spricht mit sehr leiser Stimme:>\n\nHunger... will... Käfer...\n\n<Ihr könnt aus dem Süden das Summen von Wespen hören. Ob die sind, was der Kleine fressen möchte?>", progress = nil, completion = "&lt;Der Setzling reibt sich mit einem wurzeligen Arm den Stängel, als wäre er satt. Er scheint auch ein wenig gewachsen zu sein!&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28220] = {title = "Bodensuche", objective = "Bringt den Beschützersetzling zu 7 Flecken fruchtbaren Bodens.", description = "<Der winzige Setzling tapst herum und lenkt eure Aufmerksamkeit nach Süden. Ihr könnt gerade so eine leise Stimme hören.>\n\nBoden...<Offenbar möchte er frischen Erdboden. Vielleicht solltet ihr ihn zu einem der Flecken begleiten, die am fruchtbarsten aussehen.>", progress = nil, completion = "&lt;Der Setzling kräuselt seine Wurzeln, offenbar entzückt.&gt;\n\nWachsen... groß...", rewards = "Ihr bekommt:\n\nUralte Samenhülse"}
MultiLanguageQuestData['de'][28221] = {title = "Wurzeln, wie zum Stampfen gewachsen", objective = "Tötet 10 Donnerstampfer der Eisenstämme.", description = "Es gibt hier noch so viele andere Geister, die in verrottenden Körpern gefangen sind...\n\nSeht Ihr? Die Donnerstampfer der Eisenstämme im Norden. Die sind vor Dämonenzeug ganz krank und mit Pilzschlabber bewachsen. Die armen Geister in ihnen können nicht entkommen.\n\nIhr könnt helfen! Fällt sie und die Geister können raus. Ich stecke mir die Geister ein und wir können alle Freunde sein, wenn ich groß bin. Helft Ihr ihnen? Bitte?", progress = nil, completion = "So glücklich! Könnt Ihr uns hören? Wir sind jetzt so viele Freunde.\n\nImmer größer und größer, mit Platz für alle Freunde...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28222] = {title = "Wochenend und Sonnenschein", objective = "Begleitet den Beschützersetzling zu 5 Sonnenstrahlen im Eisenwald.", description = "Wir wachsen immer großer... Zeit, dass wir strahlen! Zeit, unsere Blätter der Sonne entgegenzurecken!\n\nBringt mich zur Sonne! Die Sonne ist weit weg, aber ihre Strahlen kommen zu uns. Ihr Licht macht uns wieder groß und stark. Das Licht kommt die großen Äste hinunter zu den kleinen, wie unseren.\n\nDa drüben! Die Sonne kommt im Norden zu uns! Nehmt uns mit, nehmt uns zum Tanz!", progress = nil, completion = "So warm und frisch und voller Leben. Wir lieben die Sonne, sie macht uns stärker.\n\nBald nun, bald, ist die Zeit zum Wachsen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28223] = {title = "Der Wärter", objective = "Tötet Wärter Silva im Loch und kehrt mit seinen Schlüsseln zurück. Das Loch ist südwestlich der Baradinfestung.", description = "Wir haben es fast geschafft, die aufständischen Gefangenen im Loch zu beseitigen, doch ein Problem bleibt: Der Wärter.\n\nWärter Silva ist ihr Meister. Für ihn tun sie alles. Wenn wir ihn ausschalten, schalten wir alle aus. Tötet ihn und bringt mir seine Schlüssel. Mit den Schlüsseln können wir den Zellenblock weiter erkunden und hoffentlich auch zur Wasserversorgung der Insel vordringen.", progress = "Ist der Wärter endlich tot?", completion = "Aah, die Schlüssel des Wärters. Wieder einmal habt Ihr gute Arbeit geleistet, &lt;Name&gt;. Diese Schlüssel werden sich noch als nützlich erweisen.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28224] = {title = "Der letzte Beschützer", objective = "Besiegt den siechenden Beschützer.", description = "Ahhh... ich danke Euch, <kleiner/kleine:r> <Volk>. Ich und andere haben schon so oft versucht, in diesem Wald zu wachsen, waren jedoch nie erfolgreich.\n\nDer siechende Beschützer, der im Norden sein Unwesen treibt, ist das einzige Urtum, der es seit der Verseuchung dieses Waldes zur Reife geschafft hat, aber sein Körper ist krank und sein Geist verrückt. So wie wir die Geister der Treants gerettet haben, möchte ich auch die Geister retten, die in ihm wohnen, anstatt sie ihrem Schicksal zu überlassen.\n\nBesiegt ihn und lasst seine Geister sich mir anschließen, bevor ich Wurzeln schlage.", progress = nil, completion = "Ja... die Zeit ist gekommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28225] = {title = "Beweist Eure Loyalität", objective = "Tötet 10 Dunkeleisenzwerge in den Ruinen von Thaurissan.", description = "Ihr könnt gern für 'ne Weile hier in Meißelgriff bleiben, aber ich muss wissen, ob Ihr ein Freund seid.\n\nWir von der Thoriumbruderschaft sind nich' die einzigen Dunkeleisenzwerge hier in der Steppe. Ganz im Gegenteil. Wir sind ziemlich deutlich in der Unterzahl gegenüber den Dunkeleisenzwergen vom Schwarzfels. Unser Stützpunkt hier in Meißelgriff ist ausreichend sicher, aber sie stören uns noch immer aus den nahegelegenen Ruinen von Thaurissan im Norden.\n\nStellt Euch uns unter Beweis, <Volk>. Tötet sie für mich.", progress = nil, completion = "Na, so was sieht man doch gern! Ihr seid in Ordnung, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28226] = {title = "Verschrottete Golems", objective = "Tötet Kriegshäscher in den Ruinen von Thaurissan und sucht dann nach 3 Obsidiankolben, 3 Fluxausstoßsieben, 3 Thoriumgetriebewellen und nach einem steinernen Kraftkern unter den Kriegshäscherteilen, die zu Boden fallen.", description = "Wir halten hier Wächtergolems. Die Zwerge nördlich von hier halten auch Golems, aber ich weiß nicht genau, warum.\n\nFürs Töten in erster Linie, denke ich zumindest.\n\nWir könnten Ersatzteile für unsere Golems brauchen, und ich habe auch schon einen Plan, wie wir sie bekommen können: Tötet deren Golems und sucht nach Teilen, die auf den Boden gefallen sind. Plündert alles, was nützlich ist. Ihr werdet nicht alles tragen können, also wählt die Teile mit Bedacht.", progress = "Wir haben diese Golems selbst gebaut, wisst Ihr. Ein wenig mechanisches Handwerk, ein wenig elementares Handwerk... das Resultat ist gar nich' mal so schlecht, wenn Ihr mich fragt.", completion = "Das ist genau das, was wir brauchten. Ich lass die Jungs gleich mit der Arbeit am nächsten Schwung Golems anfangen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28227] = {title = "Golemausbildung", objective = "Helft 4 gemeißelten Golems bei ihrer Kampfausbildung.", description = "Ihr erweist Euch als ziemlich hilfreich, <Volk>. Ich hab' mir gedacht, Ihr könntet bei einer letzten Sache helfen.\n\nUnsere Wächter sind stark, aber nich' so stark, wie Ihr. Ich hab' mir gedacht, Ihr könntet, wenn Ihr nichts dagegen habt, ein paar unserer Golems bei ihrem Training helfen? Sprecht einfach einen an und kämpft ein paar mal mit ihm. Hoffentlich lernen sie was von Euren Kampfkünsten und werden besser.", progress = nil, completion = "Ihr seid ein Lebensretter, &lt;Name&gt;. Mit Golems wie diesen werden wir von den Dunkeleisenzwergen, den Schwarzfelsorcs... sogar von den Drachen nichts zu befürchten haben müssen!\n\nWenn Ihr jemals etwas von der Thoriumbruderschaft benötigen solltet, zögert nicht, uns zu fragen. Das gilt auch für Eure Freunde.", rewards = "Umhang des TutorsArmschienen der freundschaftlichen GefallenKampfausbildungswesteMeißelgriffschildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28228] = {title = "Zurück in den Wald", objective = "Bringt den erblühenden Beschützer zurück zu dem Hügel in der Mitte des Eisenwaldes.", description = "Es ist jetzt Zeit, Lebewohl zu sagen. Ihr habt mich von Setzlingswurzeln an begleitet, und so kurz die Zeit auch war, muss ich mich jetzt wieder dem Wald anschließen.\n\nBringt mich zurück auf den Hügel, auf dem Ihr mich gefunden habt. Dort werde ich meine Wurzeln schlagen und im Schatten der Urtume wachsen, die vor mir kamen.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Geschenkter ZweigAuf Euch wartet eine dieser Belohnungen:\n\nAmulett des lebenden HolzesJahresringband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28229] = {title = "Veranlagung und Umwelt", objective = "Füllt die Phiole am Mondbrunnen im Wisperwindhain und gießt sie auf dem Boden zwischen den toten Urtumbeschützern im Eisenwald aus.", description = "Die Urtumbeschützer des Eisenwalds im Norden sind schon seit Jahren tot und ihre leblosen Hüllen sind ein Mahnmal für den Schaden, der diesem Land zugefügt worden ist.\n\nVier Mal im Jahr tragen wir Wasser von diesem Mondbrunnen zu ihnen und bewässern den Boden dort - in der Hoffnung, dass daraus neues Leben entspringen wird. Wenn Ihr möchtet, könnt Ihr das Wasser selbst dorthin bringen.\n\nEs ist eine ausgezeichnete Gelegenheit, in sich zu gehen. Nehmt diese Phiole und füllt sie am Mondbrunnen, gießt sie dann auf der Spitze des kleinen Hügels zwischen den drei Urtumen aus.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nIrontree Woods Guardian Aura\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28230] = {title = "Notfallregelung", objective = "Tötet die Ray-Getz-Kalaba-Monstrosität.", description = "Bevor der Aufseher sein Fett weg kriegt, müssen wir uns um diesen Ausbruch kümmern. Wir können es nicht riskieren, diesen Erreger auf die Welt loszulassen.\n\nIm Arbeiterquartier direkt nördlich von hier treibt sich eine Monstrosität herum, die von Stillwasser aus drei Bauern zusammengeflickt wurde. Dieses Ungeheuer muss zerstört werden, wenn wir die Schlickfelder sichern wollen. Die Notfallregelungen verlangen es so.", progress = nil, completion = "Sobald wir uns um die restlichen Untoten gekümmert haben, ziehen wir Stillwasser zur Rechenschaft!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28231] = {title = "Für Glitzer", objective = "Tötet den Schmied Verringtan.", description = "Aufseher Stillwasser hat mich ins Feld geschickt, um diesen Ausbruch zu untersuchen. Als ich hier ankam, sind Glitzer und ich von dieser schwerfälligen Monstrosität namens Verringtan angegriffen worden. Ich fiel von Glitzers Rücken und rannte sofort um mein Leben. Glitzer hielt aber die Stellung und hielt das Biest auf. Leider wurde sie aber überwältigt und anschließend in den Boden gepflanzt, als wäre sie so eine Art glorreicher Sternenponysetzling.\n\nSie hat ihr Leben gegeben, um mich zu beschützen. Ich will Rache! Wenn Ihr es für nichts anderes tun wollt, dann tut es für Glitzer!", progress = nil, completion = "Sie kommt jetzt in den großen Pferdehimmel in den Sternen. Wir werden dich niemals vergessen, Glitzer. NIEMALS!", rewards = "SternenponygamaschenStarke Stiefel\"Jennys\" Handschuhe"}
MultiLanguageQuestData['de'][28232] = {title = "Essen von unten", objective = "Ihr wurdet gebeten, 12 Rationen aus dem Zellenblock aus dem Loch südwestlich der Baradinfestung zu besorgen.", description = "Uns gehen die Vorräte im Lager aus, <Name>. Wir haben vor Kurzem von einem Zellenblock südwestlich von hier gehört, in dem nach jahrelangem Betrieb noch Rationen übrig sind. Wir brauchen so viele Rationen wie ihr tragen könnt hier im Lager.\n\nOh, und noch etwas: in dem Zellenblock wimmelt es von Gefangenen, also seid vorsichtig.", progress = "Konntet Ihr die Rationen ausfindig machen? Berichten zufolge kann man sie über den ganzen Ort verteilt finden.", completion = "Die Rationen werden unseren Truppen sehr helfen, &lt;Name&gt;. Vielen Dank für Eure Hilfe.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28233] = {title = "Der verlorene Bruder", objective = "Findet Bahrum Schmiedehammer.", description = "Mein Bruder Bahrum ist verschwunden!\n\nEr war einer der ersten, die die Gegend ausgekundschaftet haben. Alle anderen sind zurückgekehrt, aber von ihm fehlt jegliche Spur. Papa meint, dass er nur irgendwo herumschlawenzelt, aber er ist mein einziger Bruder, und ich habe meiner Mutter versprochen, auf ihn aufzupassen. Könnt Ihr ihn finden?", progress = nil, completion = "He, nicht schauen! Ich hab keine Hosen an!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28234] = {title = "Meine Hosen!", objective = "Findet Bahrums Beinschützer.", description = "Warum ich in der Kornkiste stehe? Mh, um es zusammenzufassen, da waren Hornissen und Anhänger des Drachenmalklans, die zu einem recht ungünstigen Zeitpunkt aufgeschlagen sind. Ich konnte mich in Sicherheit bringen, aber meine Beinschützer haben die Bastarde an sich genommen! Meine Schwester hat sie selbst für mich angefertigt und sogar meinen Namen eingearbeitet... Ich würde sterben vor Scham, wenn sie rausfindet, dass ich sie verloren habe.\n\nBitte, findet sie für mich. Ich habe gesehen, wie der Hosendieb in die Festung dort drüben gegangen ist. Ich werde mich hier weiterhin *räusper* bedeckt halten. Und fragt einen Wildhammer nie, was er unter seinem Kilt trägt!", progress = "Habt Ihr sie gefunden? Das Korn kratzt ganz schön.", completion = "Vielen Dank! Und jetzt dreht Euch um, damit ich sie anziehen kann.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSummon Bahrum Flavor\n\nIhr bekommt:\n\nGetreidesack"}
MultiLanguageQuestData['de'][28235] = {title = "Uferbach muss sterben", objective = "Tötet Magistrat Uferbach.", description = "Magistrat Uferbach war einst der Bürgermeister dieser Gegend. Zu Lebzeiten war er ein mächtiger Gegner in der Schlacht um das Hügelland. Im Untod wird er unsere Fähigkeiten sicher auf die Probe stellen.\n\nUferbach kanalisiert mächtige arkane Magie im nordwestlichen Teil der Schlickfelder. Führt uns dorthin und gemeinsam werden wir seiner Herrschaft ein für alle Mal ein Ende bereiten.", progress = "Verschwendet nicht meine Zeit, <Name>.", completion = "Jetzt lassen wir Aufseher Stillwasser Gerechtigkeit erfahren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28237] = {title = "Eine Seuche überzieht das Land", objective = "Schlagt Aufseher Stillwasser den Kopf ab.", description = "Nun da der Ausbruch des Untodes eingedämmt wurde, ist es an der Zeit, Aufseher Stillwasser und seine Gefolgsleute zur Rechenschaft zu ziehen. Auch wenn wir eine Tragödie verhindert haben, deren Ausmaß dem der Invasion der Geißel geglichen hätte, müssen wir sicherstellen, dass so etwas nie wieder geschehen kann. Sie werden alle den wahren Tod erleiden!\n\nKommt, <Name>! Ich will Stillwassers Kopf rollen sehen.", progress = "Verschwendet nicht meine Zeit, <Name>.", completion = "Ich werde diesen Kopf persönlich der Bansheekönigin überbringen. Natürlich werde ich Eure Rolle bei alldem erwähnen, &lt;Name&gt;.\n\nWas Eure Belohnung betrifft - nehmt Euch aus Stillwassers Vorräten, was immer Ihr wollt. Ihr habt es Euch verdient.", rewards = "StillwasserdolchStillwassermantelAuf Euch wartet eine dieser Belohnungen:\n\nStillwassersignet\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28238] = {title = "Zwielichtufer", objective = "Sprecht mit Fargo Flintlocke im Hafen von Sturmwind.", description = "Die Zeit ist gekommen, <Klasse>. Nun da Sturmwind sicher ist, werden wir die Schlacht zu unseren Feinden tragen. Auf ins Hochland!\n\nDer Großteil unserer Flotte ist schon unterwegs, dank Eurer Bemühungen. Aber Fargo Flintlocke hat ein Wasserflugzeug vorbereitet, in dem Ihr die Reise doppelt so schnell hinter Euch bringen könnt.\n\nSprecht unten am Hafen mit Flintlocke, und sagt ihm, dass Ihr bereit seid, ihn ins Hochland zu begleiten. Er wird sich am Wasser befinden. Gute Reise, <Name>.", progress = nil, completion = "Ein Flug ins Hochland soll's also sein? Da hab' ich genau das Richtige!\n\nIch mach' Euch mal ein bisschen Platz in meinem Wasserflugzeug. Ich werd' wohl das Katzenfutter wieder rauswerfen müssen - Ihr wisst schon, falls wir in den Bergen abstürzen und wochenlang keine Aussicht auf Rettung haben.\n\nWenn ich's mir so überlege, nehmt das Katzenfutter doch einfach auf den Schoß, aye.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28239] = {title = "In den Schwarzzahnunterschlupf", objective = "Sprecht mit Rüstmeister Kaoshin im Schwarzzahnunterschlupf in der Brennenden Steppe.\n\nBereitgestellter Gegenstand: \n", description = "Das ist nicht unbedingt die... überzeugendste Verkleidung, die ich je gesehen habe, aber sie wird schon ausreichen. Bei verdeckten Ermittlungen geht es ja auch eigentlich fast nur um Wichtigtuerei. Verhaltet Euch einfach, als hättet Ihr alles Recht der Welt, dort zu sein und es wird schon klappen.\n\nEure Kontaktperson im Schwarzzahnunterschlupf ist ein Orc mit Namen Rüstmeister Kaoshin. Er weiß NICHT Bescheid, dass Ihr ein Spion seid, also haltet Euch bedeckt.\n\nErfüllt, worum auch immer Kaoshin Euch bittet. Oberst Trottmann wird mittels des Gnomcorders Kontakt mit Euch halten und Euch genauere Anweisungen geben.\n\nViel Glück da draußen, <Soldat/Soldatin>.", progress = nil, completion = "Wo bleibt Ihr denn, Grunzer? Ihr seid spät dran! Gebt mir auch nur einen Grund, warum ich Euch nicht auf der Stelle einen Kopf kürzer machen sollte!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28240] = {title = "Ausgebrannt", objective = "Harrison Jones möchte, dass Ihr in ein bis zwei Wochen noch einmal mit ihm sprecht.", description = "Hört her, <Name>. Ihr wisst ja, dass ich nur dafür da bin, Euch zu unterhalten und dass ich mir alle Mühe gebe, Euch angenehm beschäftigt zu halten und so weiter.\n\nAber wie es der zufall nun will sind mir völlig die Ideen ausgegangen.\n\nDas war's!\n\nNormalerweise fallen mir beim Questen mit Euch immer ein paar Dinge ein, die ich Euch als nächstes tun lassen kann, was mir wiederum Zeit verschafft, das nächste großartige Ziel auszudenken. Aber damit ist es jetzt vorbei.\n\nIch stehe mit leeren Händen da. Völlig eingebungslos. Könnte mir nicht mal etwas einfallen lassen, wenn mein Leben davon abhinge.\n\nOh, moment mal! Ich weiß, was wir machen können!\n\nSprecht noch einmal in ein bis zwei Wochen mit mir...", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][28241] = {title = "Eine Vision des Zwielichts", objective = "Findet ein Auge des Zwielichts im Schwarzen Riss.", description = "Cho'gall bleibt durch diese seltsamen magischen Kugeln über seine Diener informiert: die \"Augen des Zwielichts\".\n\nWenn Ihr eine davon beschaffen könntet, glaube ich, dass wir Cho'gall ausspionieren und sehen können, was seine Diener treiben. Besorgt mir eine!\n\nSucht im Schwarzen Riss östlich von hier, nördlich des Flusses. Findet ein Auge des Zwielichts und tut, was auch immer getan werden muss, um es zu mir zu bringen.", progress = nil, completion = "&lt;Das Auge liegt vor Euch und summt unheilvoll vor dunkler Energie.&gt;\n\n&lt;Ohne Warnung dreht sich die Kugel, als sehe sie Euch an. Ihr spürt die Anwesenheit des Bösen, als sei die Kugel lebendig.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28242] = {title = "Wir müssen alle Opfer bringen", objective = "Tötet 10 Schamanen der Schwärze.", description = "<Das Auge spricht mit Euch; seine 'Stimme' scheint aus allen Richtungen zugleich zu erschallen.>\n\nIhr wünscht einen Blick durch mich zu werfen, <Volk>? Meine Macht ist nur für einen bestimmten Preis zu haben. Diese Jünger des Zwielichts haben mich mit dem Blut der Wildhammerzwerge beehrt, aber ich verspüre immer noch Durst. Vielleicht könntet Ihr es besser machen.\n\nTötet meine alten Herren und meine Visionen gehören Euch. Ehrt mich, indem Ihr Schamanen der Schwärze tötet. Schließlich ist ein Blut so gut wie das andere.", progress = "Ich habe Euch beobachtet, <Volk>.", completion = "&lt;Das Auge glänzt dunkel und Farben huschen über seine dunkle Oberfläche.&gt;\n\nAh, die saftige Genugtuung eines erloschenen Lebens. Könnt Ihr es spüren, &lt;Klasse&gt;? Genießt Ihr es so sehr wie ich?\n\nNein, wie ich sehe, ist dem nicht so. Ihr kämpft, um das Leben Anderer zu schützen. Wie schade.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28243] = {title = "Im Auge des Betrachters", objective = "Bringt das Auge des Zwielichts zum Unterschamanen Blundy in Donnermar im Schattenhochland.", description = "Nun gut, <Volk>. Ihr habt Euch meine Dienste mit Blut erkauft. Bringt mich zum \"Unterschamanen\" von Donnermar.\n\nOh ja, ich weiß bereits, wohin Ihr mich bringen werdet. Blundys mittelmäßige, biergetränkte Fähigkeiten sind uninteressant. Ihr jedoch - Ihr fasziniert mich, <Volk>. Stellt Euch nur vor, welche Verwüstung wir in dieser erbärmlichen Welt mit meiner Sicht und Euren Fähigkeiten gemeinsam anrichten könnten...", progress = "Ihr wieder? Wat? Wat bringt'n Ihr mir da?", completion = "Ihr habt eins gefunden? Ein richtig echtes Auge des Zwielichts? Lasst mal sehen.\n\nIhr Götter. Es guckt mich an. Glotzt ja genau zurück!\n\nIch brauch 'nen Kurzen. Könnt Ihr das Ding zur Wand drehen, oder so?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28244] = {title = "Ich sehe was, was Ihr nicht seht...", objective = "Schaut in das Auge des Zwielichts für den Unterschamanen Blundy.", description = "Ich will ehrlich sein, <Name>. Das Ding macht mich nervös. Aber wo Ihr Euch so viel Mühe gemacht habt, es hierher zu bringen, denke ich mal, wir sollten auch Gebrauch davon machen.\n\nIhr zuerst.\n\nSchaut in das Auge und lasst es Euch das Innere von Cho'galls Bastion des Zwielichts zeigen. Wir finden schon noch heraus, was der dicke, zweiköpfige Schlingel im Schilde führt und benutzen das dann gegen ihn.", progress = nil, completion = "Was habt Ihr gesehen, &lt;Name&gt;? Cho'gall? Moment - er hat EUCH gesehen?\n\nOh, aye. Dieses tückische kleine Auge! Das schaut in beide Richtungen. Dieser freche Glubscher! Wo is' mein Hammer!?", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAuge der VerzweiflungDunkelaugenring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28245] = {title = "Grunzertreiberei", objective = "Poliert 7 Paar Schwarzfelsstiefel sehr gründlich.", description = "Pah! Ihr habt Glück, dass mir heute die Arbeitskräfte fehlen. Sonst hätte ich Euch für diese Woche zu <meinem Prügelknaben/meinem Prügelmädchen> gemacht.\n\nDie Stiefel der Offiziere und hochrangigen Soldaten müssen gewienert werden. Sie stehen draußen vor ihren Hütten.\n\nIch möchte mich darin spiegeln können, Grunzer! An die Arbeit!", progress = nil, completion = "Hmpf. Gute Arbeit, Grunzer.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28246] = {title = "Personaleinsparungen", objective = "Benutzt den rasiermesserscharfe Skorpidstachel, um Voodooist Timan auf der Aschensäule, Worgmeisterin Othana in den Worgzwingern und Gorlop bei den Lavateichen auszuschalten.", description = "<Rauschen> <Name>... <Name>, könnt Ihr mich hören? Hier spricht Trottmann.\n\nHört zu, wir haben gerade erst neue Informationen für Eure nächste Mission erhalten. Wir möchten, dass Ihr drei Personen unschädlich macht. Das erste Ziel ist Voodooist Timan, den Ihr oben auf der Aschensäule findet. Worgmeisterin Othana hält sich in den Worgzwingern in der Mitte des Lagers auf. Das letzte Ziel, Gorlop, befindet sich in der Nähe der Lavateiche im Süden.\n\nIhr findet die Skorpidstachel, die Ihr gesammelt habt, in Euren Habseligkeiten. Wendet die Stachel zur richtigen Zeit auf die Zielpersonen an.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28247] = {title = "Die letzte ihrer Art", objective = "Tötet Obsidia.", description = "Obsidia ist eins der letzten ausgewachsenen Drachenweibchen, die die Blutlinie des schwarzen Drachenschwarms fortsetzen könnte. Sie muss getötet werden.\n\nWenn Ihr sie erfolgreich töten könnt, solltet Ihr Lirastrasza sofort von Eurem Sieg unterrichten. Sie arbeitet schon lang auf dieses Ziel hin.\n\nDanke, dass Ihr in diesen Schlachten unsere Speerspitze wart. Ihr habt Euch als <ein mächtiger Verbündeter/eine mächtige Verbündete> herausgestellt.", progress = nil, completion = "Ihr habt Obsidia in ihrem eigenen Hort besiegt? Beeindruckend, &lt;Volk&gt;. Es tut mir leid, dass ich nicht dabeisein konnte.\n\nIhr steht zu Eurem Wort und Eure Versprechen sind nicht nur Schall und Rauch. Ich danke Euch.", rewards = "Taillenschutz der Endgültigkeit des ZwielichtsKapuze der verlorenen EinsamkeitArmschiene der letzten ErinnerungenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28248] = {title = "Gipfel des Siegers", objective = "Sprecht mit Kurdran Wildhammer am Gipfel des Siegers.", description = "Ihr habt Eure Absichten und Fähigkeiten mehr als bewiesen. Nun, da Grim Batol abgeschnitten und die Schwarzdrachen verjagt wurden, sitzen die Schattenhammerkultisten in ihrer Zitadelle in der Falle.\n\nSucht Eure Anführer auf. Sie sollten nordöstlich von hier am Gipfel des Siegers sein. Lasst sie wissen, dass zu Beginn des Angriffs auf die Schattenzitadelle die roten Drachen in den Himmeln kreisen werden. Ihr werdet nicht für all die Taten Eurer Verbündeten Buße tun können, aber in diesem einen Kampf werden wir an Eurer Seite sein.\n\nDer Schattenhammer wird fallen!", progress = nil, completion = "Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Wir sind gerade dabei, den Angriff vorzubereiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28249] = {title = "Der Schmetterschlagposten", objective = "Sprecht mit Kriegsfürstin Zaela im Schmetterschlagposten.", description = "Ihr habt Euren Willen und Eurer Können mehr als ausreichend bewiesen. Jetzt, da Grim Batol abgeschnitten ist und die schwarzen Drachen besiegt sind, sitzt der Schattenhammer in seiner Zitadelle in der Falle.\n\nGeht zu Euren Anführern. Ihr findet sie im Westen, im Schmetterschlagposten. Lasst sie wissen, dass der rote Drachenschwarm die Himmel zum Beben bringen wird, wenn der Angriff auf die Schattenzitadelle beginnt. Vielleicht könnt Ihr nicht für alle Sünden büßen, die Eure Verbündeten begangen haben, aber in dieser Schlacht werden wir Euch zur Seite stehen.\n\nDer Schattenhammer wird fallen.", progress = nil, completion = "Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Wir sind gerade dabei, den Angriff vorzubereiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28250] = {title = "Diebische Pflücker", objective = "Vermöbelt 30 Sandpygmäen mit dem Hammer der Tahretdynastie", description = "Ich habe nicht den glanzvollsten Beruf in der Welt.\n\nKriegsangelegenheiten und die tiefen Geheimnisse der Hallen von Uldum oder sonst was kümmern mich wenig.\n\nIch trage die Verantwortung über diesen Boden... und dieser Boden lässt Datteln wachsen.\n\nNun sind diese Dattelpflücker gefräßig genug geworden, sich gegenseitig auf die Schultern zu steigen und zu versuchen, meine kostbaren Früchte zu stehlen.\n\nDamit ist jetzt Schluss.\n\nNehmt diesen Hammer - er wurde von den Titanen gefertigt und trägt den Segen der Sonnenkönige und wer weiß was noch alles - und macht diese Kümmerlinge platt!", progress = nil, completion = "Ihr habt diesen diebischen Plagegeistern gezeigt, wo der Hammer hängt. Gute Arbeit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28251] = {title = "Ärger in Süderstade", objective = "Sprecht mit Serge Hinott bei den Ruinen von Süderstade im Vorgebirge des Hügellands.", description = "Ich war in Süderstade stationiert, bevor man mich gefangen genommen und eingesperrt hat. Bei den Ruinen habe ich in erster Linie Schlammproben entnommen und sichergestellt, dass die Seuche, die wir freigesetzt hatten, sicher verbreitet wird. Das wäre ohne die ständigen Angriffe der Worgen eine leichte Arbeit gewesen.\n\nIch möchte, dass Ihr Euch nach Süderstade begebt und nach meinem Lehrling Serge Hinott sucht. Ich muss wissen, ob es ihm gut geht, und er muss wissen, dass ich zurückkommen werde, wenn meine Arbeit hier beendet ist.\n\nDie Ruinen von Süderstade sind in der Nähe der Küste, südöstlich von hier.", progress = nil, completion = "Die Situation mit den Worgen hat sich nicht verbessert und Helcular macht mir echt Angst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28252] = {title = "Das Horn des Kodorufers", objective = "Benutzt das Horn der Rufer, um 7 Kriegskodos des Schwarzfels zurück zum Lager zu rufen. Bekämpft feindselige Kodos, bis sie aufgeben.", description = "Nun gut, ich habe richtige, ehrliche und sogar wichtige Arbeit für Euch! Wir müssen die Kodos rufen, die in den Gebieten südlich von hier grasen. General Thorg'izog sagt, dass wir bald ins Rotkammgebirge aufbrechen, und ich kann nicht zulassen, dass wir ohne die Kodos aufbrechen.\n\nBenutzt dieses Horn in der Nähe eines Kodos. Sobald es den Ruf hört, wird es sich auf in Richtung Lager machen.\n\nIhr müsst aber aufpassen. Manchmal sind die Kodos ein bisschen angriffslustig, und es kann sein, dass Ihr ein bisschen mit ihnen 'spielen' müsst, bevor sie auf Euch hören.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28253] = {title = "Wir behalten das Horn", objective = "Bringt das Horn der Rufer zurück zu Oberst Trottmann in Meißelgriff in der Brennenden Steppe.", description = "<Name>, Trottmann hier. Ich will, dass Ihr dieses Horn behaltet. Ich bin sicher, dass wir improvisieren können, um es in unseren Plan einzubinden.\n\nIch bin etwas besorgt über das, was Kaoshin zum Angriff auf das Rotkammgebirge gesagt hat. Wir wussten, dass ein neuer Angriff aussteht, aber wir haben uns um mehrere Tage verrechnet.\n\nKehrt mit dem Horn zu mir zurück. Wir werden hier in Meißelgriff weitersprechen. Versucht, Eure Verkleidung nicht zu verlieren. Ihr seid mit Eurer verdeckten Arbeit noch nicht fertig.", progress = "Willkommen zurück, Soldat.", completion = "Ich hatte nicht damit gerechnet, einen Gegenstand wie diesen erhalten zu können. Unsere Pläne werden dementsprechend geändert werden.", rewards = "Gamaschen der SteppenImprovisierte BrustplatteHelm der glücklichen FügungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28254] = {title = "Die Nadel im Höllhaufen", objective = "Sprecht mit Thelaron Düsternadel in Meißelgriff in der Brennenden Steppe.", description = "Ihr und ich können uns zu zweit keiner Armee stellen, <Name>. Wir werden zahlenmäßig überwältigt werden. Deswegen müssen wir uns genau an Trottmanns Plan halten.\n\nFür den nächsten Schritt laut Plan bedarf es etwas Feingefühls... und darin bin ich nicht besonders gut. Hier kommt Ihr ins Spiel.\n\nSprecht mit Thelaron Düsternadel, dem Schneider hier vor Ort. Ich habe ihm bereits die Bälge und den Schlamm gegeben, die Ihr gesammelt habt. Er muss Eure Maße nehmen.\n\nGenau, <Name>: Wir werden Euch als einen der Feinde verkleiden.", progress = nil, completion = "Ihr braucht eine Verkleidung? Nun, da seid Ihr genau am richtigen Ort, Schätzchen.\n\nLasst mich mal sehen... mm-hmm. Ich weiß genau, was wir machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28255] = {title = "Was kommt als Nächstes?", objective = "Kommandant Schnottz will doch nur umarmt werden...", description = "Wie wird das alles enden? Hmm?\n\nWerde ich mich gegen meinen dunklen Meister stellen, wer auch immer das sein mag?\n\nWerde ich zu einem einfühlsameren und teilnahmsvolleren Anführer werden?\n\nOder werde ich meine Ambitionen umsetzen, mit allen Mitteln voranstürmen und nicht ruhen, bis ganz Azeroth mir gehört?\n\nUnd was dann, hmm?\n\nVielleicht klärt sich ja alles nächste Woche...\n\n... oder vielleicht die Woche darauf...", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][28256] = {title = "Der Schädel des Gul'dan", objective = "Erlebt Illidans Kampf um den Schädel des Gul'dan.", description = "Illidan ist aufgebrochen, um den Schädel des Gul'dan zu finden. Er hat ganze Armeen von Dämonen bekämpft und sie mit einer Kraft getötet, die ihn zu einem verhassten Ausgesetzten gemacht haben.\n\nStellt Euch ihm in der Schlacht, <Name>. Werdet Zeuge vom stärksten Kämpfer gegen die Verderber Teufelwalds und erledigt ihn.", progress = nil, completion = "Nun werdet Ihr bald verstehen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28257] = {title = "Der Sturz von Tichondrius", objective = "Erlebt Illidans Kampf mit Tichondrius.", description = "Ja, Illidan hat die Macht des Schädels von Gul'dan erlangt.\n\nAber ist er damit in die Dunkelheit geflohen? Hat er sie für seinen eigenen Ruhm genutzt? Nein... seine erste Tat mit der neuerlangten Macht war es, den Schreckenslord Tichondrius anzugreifen!\n\nWerdet Zeuge seines Triumphs, <Name>. Werdet Zeuge davon, wie Illidan Teufelswald von den Dämonen befreite... und von dem Dank, den er dafür erhalten hat.", progress = nil, completion = "Habt Ihr es gesehen? Mein Meister hat das getan, was getan werden musste, um die Dämonen aus diesen Ländern zu vertreiben, und zum Dank wurde er verbannt.\n\nDie Druiden richten nun alles und klopfen sich auf die Schultern, weil sie die Überreste der Streitmächte der Legion vertrieben haben.\n\nDas ist aber nicht der Grund, warum ich sie getötet habe.", rewards = "Maske des BetrügersSündschwelgers ArmschützerSchulterstücke der undankbaren TatenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28258] = {title = "Trefft Ander Germaine", objective = "Sprecht mit Ander Germaine in der Kommandozentrale südlich von Sturmwinds Altstadt.", description = "Ander Germaine hat Euch eine Nachricht zukommen lassen. Er möchte, dass Ihr ihn in der Kommandozentrale in Sturmwinds Altstadt besucht, so schnell Ihr könnt. Es klang sehr wichtig, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28259] = {title = "Trefft Demisette Cloyce", objective = "Sprecht mit Demisette Cloyce im Keller des Gasthauses Zum Geschlachteten Lamm im Magierviertel von Sturmwind.", description = "Soeben habe ich eine Nachricht von Demisette Cloyce in Sturmwind erhalten. Sie fordert Euch auf, sie im Gasthaus Zum Geschlachteten Lamm zu treffen. Genaueres zu diesem Treffen hat sie nicht angegeben, aber ich hatte den Eindruck, dass es sich um etwas Wichtiges handelt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28260] = {title = "Trefft Wulf Hansreim", objective = "Sprecht mit Wulf Hansreim in der Kommandozentrale südlich von Sturmwinds Altstadt.", description = "Wulf Hansreim hat aus Sturmwind Kunde geschickt - er möchte Euch so bald wie möglich treffen. Ihr werdet ihn in der Kommandozentrale südlich der Altstadt von Sturmwind auffinden können.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28261] = {title = "Betrüger in unserer Mitte", objective = "Tötet 12 Jadefeuerschleicher in der Jadefeuerschlucht.", description = "Nun, da Ihr in der Unvoreingenommenheit unterrichtet wurdet, möchtet Ihr vielleicht erfahren, WARUM ich diese Druiden getötet habe.\n\nDie Antwort ist einfach: Sie sind keine Druiden.\n\nDämonen suchen die Ruinen noch immer heim und haben die Gestalt von friedlichen Hütern angenommen. Seht es Euch mit eigenen Augen an - diese Augenbinde hier ist von dem Blut eines Dämonen getränkt. Nehmt sie und geht zur Jadefeuerschlucht in den Hügeln nördlich von hier, und verbindet Euch dort die Augen damit. Sie ermöglicht es selbst dem nichtsahnendsten Narren, die wahre Natur eines Dämonen zu erkennen.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSündschwelgers Beschwörung\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28262] = {title = "Trefft Lord Tony Romano", objective = "Sprecht mit Lord Tony Romano im Hauptquartier von SI:7 südlich von Sturmwinds Altstadt.", description = "Lord Tony Romano, einer der erfahrensten Schurkenlehrer von Sturmwinds SI:7, hat verlauten lassen, dass er Euch sprechen möchte. Begebt Euch so bald wie möglich nach Sturmwind und sucht ihn im Gebäude des SI:7 südlich von Sturmwinds Altstadt auf.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28263] = {title = "Trefft Maginor Dumas", objective = "Sprecht mit Maginor Dumas im Magiersanktum im Magierviertel von Sturmwind.", description = "Soeben habe ich eine Nachricht von Maginor Dumas, dem führenden Magierlehrer in Sturmwind erhalten. Er bittet Euch, ihn im Magiersanktum in Sturmwind zu besuchen, sobald Euch die Reise möglich ist.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28264] = {title = "Navarax' Schachzug", objective = "Tötet den Dämonen, der als Erzdruide Navarax erscheint.", description = "Ich habe diesen betrügerischen Dämonen lange aufgelauert und endlich den Standort ihres Anführers ausfindig gemacht. Es handelt sich dabei um keinen geringeren als den Erzdruiden Navarax, Anführer des Smaragdkreises.\n\nDer Dämon schützt sich selbst durch Unschuldige. Wenn ich den Wisperwindhain betreten würde, um ihn zu jagen, so würden mich seine unwissenden Beschützer abhalten... aber Ihr! Ihr könnt ihn unbemerkt erwischen.\n\nBegebt Euch erneut zum Wisperwindhain. Steigt den Druidenturm hinauf - ganz oben werdet Ihr Navarax finden, in seinem Raum inmitten der Zweige.", progress = "Habt Ihr Neuigkeiten für mich?", completion = "Es fällt mir schwer, Euch das alles zu glauben, aber die Leiche des Dämons ist Beweis genug.\n\nIch werde umgehend eine Untersuchung der Druiden am Jadefeuerbach in die Wege leiten, und dafür sorgen, dass meine Vorgesetzten alle wissen, dass der Dämonenjäger wohl kein Problem damit hat, im Exil zu bleiben.", rewards = "Seluras UmhangAuf Euch wartet eine dieser Belohnungen:\n\nDämonenherzenanghängerNavarax' Signet\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28265] = {title = "General Thorg'izog", objective = "Sprecht mit General Thorg'izog.", description = "Kaoshin hat sich als hilfreicher herausgestellt, als wir vermutet hatten, aber jetzt brauchen wir ihn nicht mehr. Es ist an der Zeit, mit dem General zu sprechen. Ich glaube, Ihr seid bereit.\n\nGeneral Thorg'izog ist einer der \"großen Drei\", die die Bodentruppen in der Brennenden Steppe anführen. Er befindet sich in der Schwarzfelsfestung im Nordwesten. Zieht Eure Verkleidung an und sprecht mit ihm. Versucht, sein Vertrauen zu gewinnen. Trottmann wird sich bei Euch melden, sollte ich noch etwas von Euch brauchen.", progress = nil, completion = "Noch mehr Außenstehende? Was wollt Ihr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28266] = {title = "Magmataufe", objective = "Sprecht mit Würtl Sprillhuper und bittet ihn, Magmalord Kolob freizulassen. Besiegt danach Magmalord Kolob im Kampf.", description = "Ich muss aus dieser Situation das Beste machen. Diese Goblinsöldner haben mir diesen riesigen Feuerelementar als \"Dankeschön\" geschickt, weil ich sie angeheuert habe. Was soll ich denn hier in der Steppe mit einem Elementar anfangen? Das ist ja fast, wie Wasser zum Meer zu tragen.\n\nWenn Ihr nach Arbeit sucht, so könnt Ihr Euch nun beweisen. Sprecht mit diesem Goblin hier und fordert seinen Elementar zum Kampf heraus. Ich werde dem Sieger meinen Respekt zollen und meine Zeit geben.", progress = "Was ist los? Habt Ihr Angst?", completion = "Ich hatte fast damit gerechnet, dass Ihr als Sieger hervortreten würdet. Mir gefällt Eure Art, zweifellos.", rewards = "Umhang des MagmafürstenStillose HandschuheArmschienen des GladiatorenkampfesAuf Euch wartet eine dieser Belohnungen:\n\nThorg'izogs Band\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28267] = {title = "Erschießungskommando", objective = "Sprecht mit Kommandant Schnottz.", description = "Folgt mir nach draußen, <Volk>.\n\nIch möchte, dass Ihr etwas mit anseht.", progress = nil, completion = "Schnottz arbeitet also für Todesschwinge?\n\nDas ist weitaus beunruhigender, als Ihr Euch vorstellen könnt...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchnottz' Medaillon der BefehlsgewaltTalisman der finsteren OrderHarrisons Insigne des Flairs\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28268] = {title = "Trefft Lord Grayson Schattenbruch", objective = "Sprecht mit Lord Grayson Schattenbruch bei der Kathedrale des Lichts in Sturmwinds Kathedralenviertel.", description = "Lord Grayson Schattenbruch der Kathedrale des Lichts in Sturmwind hat Euch einen Nachricht geschickt. Er möchte, dass Ihr Euch bei ihm meldet, wenn Ihr das nächste Mal in der Stadt seid. Ihr könnt ihn im Kathedralenviertel finden.", progress = nil, completion = "Ich wünschte, Ich hätte gute Nachrichten für Euch, &lt;Name&gt;, aber leider habe ich Euch hierher gebeten, weil wir Euer Talent brauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28269] = {title = "Trefft mich in Vir'sar", objective = "Sprecht mit Harrison Jones in der Oase Vir'sar.", description = "Hört mir gut zu, <Name>.\n\nIch wusste, dass die Obelisken etwas mit der Lade der Verheißung zu tun haben, aber das ist noch nicht alles.\n\nEs scheint, dass es mit der Lade etwas sehr Wichtiges auf sich hat - etwas, das die Schöpfer die Hallen des Ursprungs nennen.\n\nNun, da wir wissen, dass dieser Schnottz und seine Truppe mit Todesschwinge im Bunde sind, ist es nur noch dringlicher, dass wir die Lade zuerst bekommen.\n\nIch werde nördlich von hier in der Oase Vir'sar auf Euch warten.\n\nBeeilt Euch! Sie haben bereits einen Vorsprung!", progress = nil, completion = "Ahh, freut mich, dass Ihr es geschafft habt.\n\nIch könnte hier etwas Hilfe gebrauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28270] = {title = "Sozius", objective = "Begleitet Harrison zur Oase Vir'sar.", description = "In Ordnung, <Name>, ich stehe kurz davor, den letzten Obelisken aktivieren zu können.\n\nMir fehlen nur noch ein paar Informationen, und mit ein bisschen Glück werden wir sie vor Ort finden können.\n\nDie Vorräte sind schon eingepackt. Sagt Bescheid, wenn Ihr bereit seid.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Kohlenspeiender ZauberstabAuf Euch wartet eine dieser Belohnungen:\n\nRing des schimmernden WassersHalsreif des SteuermannsKanonenstabilisierer\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28271] = {title = "Produktivitätseinbußen", objective = "Tötet 15 Ausgräber von Schnottz oder Aufseher von Schnottz.", description = "Also, <Name>. So viel konnte ich herausfinden.\n\nAn einem Ort namens Hallen des Ursprungs gibt es ein Gerät der Titanen. Es soll eine Art Notfallschalter sein, der alles Leben in Azeroth zurücksetzt. Wenn er aktiviert wird, wird jedes Lebewesen auf der ganzen Welt vernichtet!\n\nNatürlich ist es nur für den absoluten Notfall gedacht, aber wenn es Todesschwinge gelingt, die titanischen Wächter zu verderben, kann er den Inhalt der Lade benutzen, um das Gerät auszulösen.\n\nGeht zum Obelisken des Mondes, <Name>. Haltet sie auf!", progress = nil, completion = "Schnottz' Männern habt Ihr es gezeigt.\n\nEure Lektion werden sie so schnell sicher nicht vergessen.\n\nHoffentlich hat uns das die nötige Zeit verschafft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28272] = {title = "Fehlende Stücke", objective = "Sammelt 7 uralte Kupferschriftrollen.", description = "Mir fehlen nur noch ein paar spezielle Informationen.\n\nSobald diese Lücken geschlossen sind, werden wir bereit sein, den letzten Obelisken zu aktivieren. Dann beginnt der Wettlauf um die Lade der Verheißung gegen Schnottz und seine Handlanger.\n\nDie Narren graben diesen Ort so schnell sie können um. Sie richten mehr Schaden an, als sie finden.\n\nGeht zum Obelisken und durchsucht ihre Beute, <Name>.\n\nSchaut, ob Ihr unsere fehlenden Puzzleteile finden könnt.", progress = "Konntet Ihr etwas Interessantes finden, <Name>?", completion = "&lt;Harrison überfliegt die Rollen zügig.&gt;\n\nJa... ja... Perfekt!\n\nIch werde etwas Zeit brauchen, um sie zu entschlüsseln, aber die Informationen sind darin enthalten.\n\nGute Arbeit, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28273] = {title = "Der Freund eines Freundes", objective = "Harrison möchte, dass Ihr mit Sullah in der Oase Vir'sar sprecht.", description = "Ich muss auspacken und die Gegend ein wenig auskundschaften. In der Zwischenzeit möchte ich, dass Ihr einen alten Freund von mir trefft.\n\nSullah und ich kennen uns seit Ewigkeiten. Man kann ihm vertrauen, und das ist schon selten heutzutage.\n\nWarum geht Ihr nicht zu ihm und begrüßt ihn?", progress = nil, completion = "Willkommen, &lt;Klasse&gt;!\n\nWir beide werden uns gut verstehen! Das kann ich jetzt schon sagen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28274] = {title = "Zwei Zelte", objective = "Begleitet Sullah zu Sullahs Fahrendem Zirkus", description = "Seht Euch an! Das Abenteuer steht Euch förmlich ins Gesicht geschrieben!\n\nIhr müsst Euch aber auch ein wenig erholen. Ihr seht angespannt aus und das macht einen schnell müde.\n\nVertraut mir, mit Erholung kenne ich mich aus!\n\nA propos Erholung: Jonesy hat mir anscheinend die Zelte gebracht, um die ich ihn gebeten habe.\n\nKommt. Reitet mit mir!", progress = nil, completion = "Da wären wir, &lt;Name&gt;!\n\nGroßartige Dinge werden hier stattfinden... magische Dinge!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28275] = {title = "Bom-ben-los!", objective = "Zerstört 10 scheußliche Versorgungsboote.", description = "Wellsons Werft empfängt dauernd Vorräte von den Küstengewässern aus und das muss aufhören. Sie haben Kanonen an den Docks aufgestellt, um sich zu verteidigen, aber wenn Ihr zu ihnen durchbrechen könnt, können wir mit ihnen die Versorgungsschiffe zerstören.\n\nBegebt Euch dorthin und seht mal, was Ihr tun könnt. Erstattet mir über Eure Fortschritte Bericht.", progress = nil, completion = "Ausgezeichnete Arbeit mit den Versorgungsbooten, &lt;Name&gt;! Wir wussten, dass Ihr was taugt!", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28276] = {title = "Salhets Geheimnis", objective = "Findet Salhet am südlichen Ende des Sonnenbehütergrats in Uldum.", description = "Hört gut zu, <Name>. Bevor Ihr Euer Vertrauen in mich verliert, würde ich Euch gerne noch etwas zeigen.\n\nWie Ihr wisst, bin ich kein Kämpfer. Meine Koordination ist nicht gut.\n\nIch sehe mich eher als Taktiker an.\n\nTrefft mich am südlichen Ende des Grats und ich werde Euch zeigen, was ich meine.", progress = nil, completion = "Sind sie nicht wunderschön?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28277] = {title = "Salhet der Taktiker", objective = "Sprecht mit Salhet und tötet 30 Murrblutaasfresser", description = "Schon als ich ein Junges war, wollte ich unbedingt ein General werden.\n\nIch wollte unbedingt der Armee beitreten. Aber wie Ihr gesehen habt, ist es um meine Kampfkünste schlecht bestellt.\n\nIch wurde schon früher zum Hyänentöten geschickt. Ich wurde schon so oft hierher geschickt, dass ich mich inzwischen mit den Löwen angefreundet und sie trainiert habe, das zu machen, was ich will.\n\nSie sind meine Soldaten, folgen meinen Befehlen und töten massenweise Hyänen. Seht selbst!", progress = nil, completion = "Nicht schlecht, was? Vielleicht könnt Ihr beim Hochkommandanten ein gutes Wort für mich einlegen?\n\nVielleicht erteilt er uns Zuständigkeit über unsere eigene Einheit!", rewards = "Krone des großen GeneralsGamaschen der katzenhaften BeherrschungSalhets verzierter DolchIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28278] = {title = "Ich bin das Gesetz und dessen starker Arm", objective = "Benutzt den Disziplinarknüppel des Schwarzfels bei 20 Einheiten in den Feldern der Ehre. Wenn jemand merkt, wer Ihr seid, so erschlagt ihn, bevor er Eure Maskierung aufheben kann.", description = "Ich war auf der Suche nach <einem starken Soldaten/einer starken Soldatin> wie Euch. Ich brauche jemanden, der dafür sorgt, dass meine Truppen sich benehmen.\n\nAußerhalb der Festung bereiten sich die Orcs, Oger und Trolle auf einen Angriff auf das Rotkammgebirge vor. Meine Unteroffiziere halten sie zwar auf Trab, aber sie brauchen Hilfe.\n\nNehmt diesen Knüppel und diszipliniert ein paar meiner Soldaten.\n\nEs ist mir egal, ob sie in Reih und Glied stehen oder sich fehlverhalten - ich will nur, dass sie eine Tracht Prügel bekommen. Ich will, dass sie sich konzentrieren, auf die Schlacht vorbereitet und abgehärtet sind, und gefolgsam.\n\nGeht nun.", progress = nil, completion = "Ich habe das Gefühl, dass wir von Euch noch viel hören werden, Soldat. Ich freue mich darauf, an Eurer Seite im Rotkammgebirge zu kämpfen.\n\nWegtreten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28279] = {title = "Machtmissbrauch", objective = "Tötet 5 Feldwebel des Schwarzfels mit dem Disziplinarknüppel des Schwarzfels. Besiegt sie schnell, bevor sie Eure Maskierung aufheben können.", description = "<Name>? Trottmann hier.\n\nWie es scheint, habt Ihr Thorg'izogs Vertrauen gewonnen, denn er hat Euch für die Disziplinierung eingeteilt. Das ist ein Glück.\n\nWir müssen diese Feldwebel loswerden. Ihr findet sie außerhalb der Schwarzfelsfestung in den Feldern der Ehre auf Wölfen reitend. Benutzt den Knüppel so oft wie nötig, bis sie sterben. Ihr müsst schnell handeln, denn wenn sie merken, dass Ihr <keiner/keine> von ihnen seid, dann werden sie versuchen, Eure Maskierung aufzuheben. Seid schnell und zügellos, <Name>.\n\nTrottmann aus.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28280] = {title = "Reißt sie vom Himmel!", objective = "Benutzt den tragbaren Drachentöter, um 8 Schwarzdrachen des Drachenmals zu töten.", description = "Um Himmels Willen! Sie sind hier, <Name>. Sie sind hier!\n\nIch hatte gehofft, eine ganze Armee mit meinen tragbaren Drachenfäusten ausrüsten zu können, aber ich habe nur einen einzigen, extrem teuren und viel zu wenig getesteten Prototypen. Hier, nehmt ihn!\n\nSchießt auf die Schwarzdrachen des Drachenmals, die um Donnermar kreisen, und lasst sie vom Himmel stürzen!", progress = nil, completion = "Ihr habt es geschafft, &lt;Name&gt;! Wieder einmal hat die Genialität der Allianz den Tag gerettet.\n\nNatürlich habe ich jetzt nichts, mit dem Ihr die abgestiegenen Reiter auf dem Boden bekämpfen könntet. Aber Ihr seid ein &lt;Klasse&gt;. Improvisiert!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28281] = {title = "Letztes Gefecht in Donnermar", objective = "Tötet 8 Himmelskrallen des Drachenmalklans ohne Reittiere.", description = "Ich überlasse es Euch und Euren Freunden von der Allianz. Ihr habt es dem Drachenmalklan bisher schon gut gezeigt!\n\nViele ihrer berittenen Kämpfer sind bereits ihre Reittiere los, aber sie kommen immer noch in unsere Richtung und meine Verteidiger kommen ohne Hilfe nicht zurecht.\n\nTötet die Himmelskrallen des Drachenmalklans ohne Reittiere und Donnermar wird für immer in Eurer Schuld stehen!", progress = "Wir sollten eine Kampfpause einlegen und die Feuer löschen, oder Donnermar wird aussehen wie der Rest der Welt, die in Trümmern liegt...", completion = "Ihr müsst Euch auf dem Schlachtfeld gut zurechtfinden können, &lt;Klasse&gt;. Es scheint, als sei ein neuer Einfall geplant.\n\nWir brauchen nur noch einen entscheidenden Schlag...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28282] = {title = "Narkrall, der Drachenzähmer", objective = "Tötet Narkrall Harkenklaue. Sprecht mit Colin Donnermar, wenn Ihr bereit seid.", description = "Narkrall vom Drachenmalklan wird auch der \"Drachenzähmer\" genannt. Ich weiß nicht, wie er die Macht erlangt hat, diese Bestien zu befehligen, aber der schwarze Terror, den er reitet, ist der grausigste Drache, der in den ganzen Hochländern zu finden ist.\n\n<Name>, Narkrall ist ein Feind, der das Leben meines Vaters genommen und Donnermars Schicksal in meine Hände gelegt hat.\n\nIch kann mich ihm nicht alleine stellen, aber ich habe gesehen, zu was Ihr in der Lage seid, <Klasse>. Vielleicht können wir diesem Schrecken gemeinsam ein Ende bereiten.\n\nLasst mich wissen, wenn Ihr bereit seid, und wir werden Narkrall gemeinsam bekämpfen!", progress = nil, completion = "Wir haben es geschafft, &lt;Name&gt;! Narkrall Harkenklaue liegt tot zu meinen Füßen und Donnermar hat einen Sturm von Drachen abgewehrt!\n\nOhne die Hilfe der Allianz wäre das nicht möglich gewesen. Die Schuld, in der ich stehe werde ich wohl nie begleichen können.", rewards = "DrachenzornstreitkolbenZornbestimmter TaillenplattenschutzBiergetränkter HandschutzNarkralls GamaschenStab der DrachenbesänftigungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28283] = {title = "Was ist das für eine Rassel?", objective = "Untersucht die Rassel der Knochen in Düsterwolkengipfel in Tausend Nadeln.Habt Ihr die leuchtende Rassel gesehen, die vor Ishas Hütte auf dem Boden liegt?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Habt Ihr die leuchtende Rassel gesehen, die vor Ishas Hütte auf dem Boden liegt?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28284] = {title = "Was ist das für eine Rassel?", objective = "Untersucht die Rassel der Knochen in Düsterwolkengipfel in Tausend Nadeln.Habt Ihr die leuchtende Rassel gesehen, die vor Ishas Hütte auf dem Boden liegt?", description = "Habt Ihr die leuchtende Rassel gesehen, die vor Ishas Hütte auf dem Boden liegt?", progress = nil, completion = "Interessant...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28285] = {title = "Trefft Hohepriesterin Laurena", objective = "Sprecht mit Hohepriesterin Laurena bei der Kathedrale des Lichts im Kathedralenviertel von Sturmwind.", description = "Ich habe eine Schriftrolle aus der Kathedrale des Lichts erhalten, <Name>. Hohepriesterin Laurena schickt Kunde, dass sie Euch sprechen möchte. Ihr solltet sie so bald wie möglich treffen.", progress = nil, completion = "Das Licht hat meine Gebete erhört. Endlich seid Ihr hier.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28286] = {title = "Genug Schaden für einen Tag", objective = "Kehrt zu Oberst Trottmann in Meißelgriff zurück.", description = "Wir haben keine weitere strategische Verwendung für Thorg'izog oder die Bodentruppen des Schwarzfels. Wir müssen nun die nächste Phase des Plans einläuten.\n\nWenn Ihr bei der Festung fertig seid, kehrt zurück zu uns in Meißelgriff.", progress = nil, completion = "Alles in Ordnung?\n\nGut. Ihr habt gute Arbeit geleistet, &lt;Name&gt;. Packt Eure Sachen zusammen. Wir ziehen ab.", rewards = "Kubits DolchGürtel der VorbereitungStulpen des AbschlussesBrustplatte des mobilen BataillonsAuf Euch wartet eine dieser Belohnungen:\n\nBand der Kriegslist\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSchwarzfelsverkleidung entfernen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28287] = {title = "Trefft Scharfseherin Umbrua", objective = "Sprecht mit Scharfseherin Umbrua im Gasthaus Zum Goldenen Fass im Zwergendistrikt von Sturmwind.", description = "Eine Nachricht von Scharfseherin Umbrua hat mich soeben erreicht, <Name>. Es gibt ein wichtiges Anliegen, das sie mit Euch besprechen möchte, und sie bittet darum, dass Ihr sie im Gasthaus Zum Goldenen Fass im Zwergendistrikt in Sturmwind aufsucht, so bald Ihr könnt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28288] = {title = "Öffnet ihre Augen", objective = "Benutzt Delaris' Prisma, um 20 Jadefeuerwichtel zu erschrecken.", description = "Bevor Ihr geht...\n\nIch habe meine Zeit allein mit Impsy hier genutzt, um ein paar interessante Fakten über Wichtel herauszufinden. Er hat mir nämlich von einer Sache erzählt, die alle Wichtel am meisten fürchten. Etwas, das sie regelrecht in Angst und Schrecken versetzt.\n\nIch fand das sowohl nützlich als auch interessant, also habe ich ein paar geringere Beschwörungen durchgeführt. Dieses Prisma wird ein Bild projizieren von... nun, von dem, was Impsy beschrieben hat.\n\nIm Schattenlauergrat wimmelt es immer noch nur so von Wichteln. Warum geht Ihr nicht dorthin und schaut für mich, wie sie darauf reagieren?", progress = nil, completion = "Ich verstehe... Ihre Augen sind geöffnet.\n\n&lt;Delaris lächelt amüsiert.&gt;\n\nVielleicht behalte ich Impsy doch noch eine Weile bei mir. Er kann mir noch viel beibringen...", rewards = "GoldtopfhandschuheFröhliche SchulternAuf Euch wartet eine dieser Belohnungen:\n\nRegenbogenband\n\nIhr bekommt außerdem:\n\nRegenbogengenerator"}
MultiLanguageQuestData['de'][28289] = {title = "Mondlichtung ruft", objective = "Reist nach Mondlichtung und sprecht mit Loganaar in Nachthafen.", description = "Ich habe Nachrichten aus Mondlichtung erhalten. Unsere Brüder bitten um Eure Hilfe, <Name>. Ihr solltet Euch auf die Reise machen und Loganaar in Nachthafen aufsuchen.", progress = nil, completion = "Gut, Euch wieder zu sehen, &lt;Name&gt;. Ich wünschte, ich könnte Euch gute Nachrichten überbringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28290] = {title = "Trefft Grezz Zornfaust", objective = "Sprecht mit Grezz Zornfaust im Tal der Ehre in Orgrimmar.", description = "Grezz Zornfaust hat Euch eine wichtige Nachricht geschickt, <Name>. Er möchte, dass Ihr ihn umgehend im Tal der Ehre in Orgrimmar aufsucht. Er scheint ein wichtige Aufgabe für Euch zu haben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28291] = {title = "Zum Lager zurückkehren", objective = "Kehrt zu Hochkommandant Kamses am Außenposten der Legion von Ramkahen zurück.", description = "Was meint Ihr, <Name>? Vielleicht gibt mir der Hochkommandant ein paar Leute, die ich befehligen kann.\n\nVielleicht können wir zusammen ein Regiment aufstellen. Was meint Ihr?", progress = nil, completion = "Salhet? Ein Taktiker, sagt Ihr?\n\nHah! Na ja, wenn Ihr Euch für ihn verbürgt, können wir bestimmt etwas arrangieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28292] = {title = "Das ist keine Pyramide!", objective = "Sprecht mit Harrison Jones in Burg Sturmwind in Sturmwind.", description = "Die Pyramide bei der Terrasse des Schöpfers in Uldum ist nicht wirklich eine Pyramide im klassischen Sinne. Es ist eine große Maschine, die für unzählig viele Funktionen umprogrammiert werden kann.\n\nTodesschwinge wollte, dass der Schattenhammer sie in eine riesige Waffe umfunktioniert!\n\n<Name>, Ihr müsst das Portal benutzen, um Harrison Jones in Sturmwind diese Information zukommen zu lassen. Er wird wissen, was zu tun ist.", progress = nil, completion = "Uldum? Was ist damit?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28293] = {title = "Das ist keine Pyramide!", objective = "Sprecht mit Bellok Leuchtklinge in der Feste Grommash in Orgrimmar.", description = "Die Pyramide bei der Terrasse des Schöpfers in Uldum ist nicht wirklich eine Pyramide im klassischen Sinne. Es ist eine große Maschine, die für unzählig viele Funktionen umprogrammiert werden kann.\n\nTodesschwinge wollte, dass der Schattenhammer sie in eine riesige Waffe umfunktioniert!\n\n<Name>, Ihr müsst das Portal benutzen, um Bellok Leuchtklinge in Orgrimmar diese Information zukommen zu lassen. Er wird wissen, was zu tun ist.", progress = nil, completion = "Uldum? Was ist mit Uldum? Sprecht, schnell!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28294] = {title = "Gipfeltreffen in Kirthafen", objective = "Sprecht mit Lachlan MacGraff in Kirthafen im Schattenhochland.", description = "Dank der Abreibung, die wir dem Drachenmal verpasst haben, werden ihre Angriffe auf Donnermar wohl aufhören. Vielleicht haben die Wildhämmer einen Platz in der Allianz - Donnermar steht in jedem Fall in Eurer Schuld.\n\nUnser großer Schamane, Lachlan MacGraff, hat versucht, ein Gipfeltreffen der Anführer der überlebenden Wildhammerfamilien zu veranstalten. Es ist keine leichte Aufgabe, alle zusammenwirken zu lassen, aber ich werde es zumindest versuchen.\n\nFliegt nach Kirthafen und sprecht mit Lachlan MacGraff. Ich werde Euch dort treffen!", progress = nil, completion = "Hallo, &lt;Klasse&gt;! Keegan Feuerbart hier hat mir schon viel von Euren Heldentaten im Süden berichtet. Ich danke Euch für Eure Bemühungen, uns Wildhämmern zu helfen.\n\nWie ich sehe, ist auch Colin Donnermar eingetroffen. Unser Gipfeltreffen kann beginnen! Bitte, bleibt und seht, wie die Dinge sich entwickeln...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nColin zum Gipfel beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28295] = {title = "Die Karawane treffen", objective = "Sprecht mit Adarrah in Disteltal in Tanaris.", description = "Die Pyramide in der Terrasse des Schöpfers in Uldum kann als eine Art Superwaffe benutzt werden, die alles Leben in Azeroth auslöschen wird.\n\n<Harrison denkt einen Augenblick lang nach.>\n\nIhr müsst Eure Untersuchungen zu Ende führen. Reist ans südliche Ende Kalimdors, zur Tanariswüste. Dort findet Ihr eine Karawane, die nach Uldum aufbrechen wird.\n\nVielleicht könnt Ihr Euch anschließen.", progress = nil, completion = "Harrison schickt Euch also?\n\nNa so ein Glück!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28296] = {title = "Die Karawane treffen", objective = "Sprecht mit Adarrah in Disteltal in Tanaris.", description = "Die Pyramide in der Terrasse des Schöpfers in Uldum kann als eine Art Superwaffe benutzt werden, die alles Leben in Azeroth auslöschen wird.\n\n<Belloc denkt einen Augenblick lang nach.>\n\nIhr müsst also mit Euren Untersuchungen fortfahren. Reist nach Süden zur Tanariswüste. Dort findet Ihr eine Karawane, die nach Uldum aufbrechen wird.\n\nVielleicht könnt Ihr Euch anschließen.", progress = nil, completion = "Bellok schickt Euch also?\n\nNa so ein Glück!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28297] = {title = "Trefft Ormak Grimmschlag", objective = "Sprecht mit Ormak Grimmschlag im Tal der Ehre in Orgrimmar.", description = "Ich habe eine Schriftrolle von Ormak Grimmschlag aus Orgrimmar erhalten. Er möchte, dass Ihr Euch auf den Weg zum Tal der Ehre begebt und ihn so schnell wie möglich aufsucht. Es klang sehr dringlich, <Name>.", progress = nil, completion = "Die Horde benötigt Eure Fähigkeiten, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28298] = {title = "Trefft Gordul", objective = "Sprecht mit Gordul in der Kluft der Schatten in Orgrimmar.", description = "Gordul, der Anführer der Schurken der Zerschmetterten Hand, möchte Euch treffen. Begebt Euch so schnell wie möglich nach Orgrimmar, <Name>, und sucht ihn der Kluft der Schatten auf. Er scheint eine wichtige Aufgabe für Euch zu haben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28299] = {title = "Trefft Zevrost", objective = "Sprecht mit Zevrost in der Kluft der Schatten in Orgrimmar.", description = "Ich habe soeben eine Nachricht von Zevrost erhalten, dem mächtigsten Lehrer für Hexenmeister. Er wünscht, dass Ihr nach Orgrimmar reist und ihn in der Kluft der Schatten trefft. Es klang, als habe er eine wichtige Aufgabe für Euch.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28300] = {title = "Trefft Ureda", objective = "Sprecht mit Ureda in der Kluft der Schatten in Orgrimmar.", description = "Ich habe eine Schriftrolle aus Orgrimmar für Euch, <Name>. Sie ist von Ureda, eine der Magierlehrerinnen. Sie möchte, dass Ihr Euch in der Kluft der Schatten mit ihr trefft, wenn Ihr das nächste Mal in der Stadt seid.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28301] = {title = "Trefft Kardris Traumsucher", objective = "Sprecht mit Kardris Traumsucher im Tal der Weisheit in Orgrimmar.", description = "Ich habe eine wichtige Nachricht für Euch erhalten, <Name>. Sie ist von Kardris Traumsucher, einer Schamanenlehrerin aus Orgrimmar. Sie möchte, dass Ihr Euch so schnell wie möglich ins Tal der Weisheit in Orgrimmar begebt und dort mit ihr sprecht.", progress = nil, completion = "Wir leben in gefährlichen Zeiten, &lt;Name&gt;. Die Horde kann sich glücklich schätzen, dass eine &lt;Volk&gt; wie Ihr in ihren Reihen kämpft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28302] = {title = "Trefft Sonnenläufer Atohmo", objective = "Sprecht mit Sonnenläufer Atohmo im Tal der Weisheit in Orgrimmar.", description = "Ihr solltet so schnell wie möglich nach Orgrimmar aufbrechen, <Name>. Sonnenläufer Atohmo hat Kunde geschickt, dass er Euch in einer wichtigen Angelegenheit der Horde sprechen möchte. Sucht ihn im Tal der Weisheit auf.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28303] = {title = "Trefft Meister Pyreanor", objective = "Sprecht mit Meister Pyreanor in der Feste Grommash in Orgrimmar.", description = "Meister Pyreanor hat Euch eine wichtige Nachricht zukommen lassen, <Name>. Er bittet Euch, ihn in der Feste Grommash im Tal der Stärke aufzusuchen, wenn Ihr das nächste Mal in der Stadt seid. Es klang, als habe er eine wichtige Aufgabe für Euch.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28304] = {title = "Trefft die dunkle Klerikerin Cecille", objective = "Sprecht mit der dunklen Klerikerin Cecille in der Feste Grommash im Tal der Stärke in Orgrimmar.", description = "Die dunkle Klerikerin Cecille, eine Angehörige der Delegation der Bansheekönigin in Orgrimmar, hat darum gebeten, dass Ihr sie bei Eurem nächsten Besuch in der Stadt trefft. Sie ist in der Feste Grommash im Tal der Stärke in Orgrimmar. Es muss sich um eine wichtige Angelegenheit handeln, wenn sie direkt nach Euch schickt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28305] = {title = "Das Schicksal Blutgiftpostens", objective = "Sprecht mit Kelnir Blattlied beim Blutgiftposten.", description = "Während wir uns um Jaedenar gekümmert haben, ist eine Freundin von mir zum Blutgiftposten aufgebrochen. Wir hatten früher unregelmäßige Besuche von den Tauren von dort, aber in letzter Zeit haben wir von ihnen nichts mehr gehört.\n\nKelnir Blattlied ist noch nicht zurückgekehrt. Könntet Ihr nach Norden reisen, um nach ihr zu suchen und die Lage in Blutgiftposten erkunden?\n\nWenn Ihr Kelnir finden solltet, müsst Ihr achtsam sein... Dryaden wie sie werden von vielen anderen Völkern als seltsam empfunden.", progress = nil, completion = "Oh, hi! Hat Farlus Euch geschickt? Wie schön, dass er sich daran erinnert hat!\n\nBlutgipfelposten ist voll und ganz von diesen furchtbaren Schleimdingern überfüllt und dieser arme Tauren hier ist der Einzige, der noch übrig ist! Wir müssen ihm helfen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28306] = {title = "Wisperwindhain", objective = "Sprecht mit Hüterin Purhain in Wisperwindhain.", description = "Ihr wart hier so eine große Hilfe!\n\nIch werde hier bleiben und mich um den armen Herrn Tauren kümmen, bis er sich nicht mehr ganz so oft übergibt. Warum geht Ihr solange nicht nach Wisperwindhain? Da ist es wirklich schön, und alle Druiden sind richtig nett!\n\nBitte richtet Frau Purhain aus, dass es mir gut geht. Sie soll sich keine Sorgen machen, wenn ich mal länger weg bin. Vielleicht wird sie Euch bitten, ihr mit den Blumen zu helfen. Das macht soo viel Spaß!", progress = nil, completion = "Kelnir? Hahaha...\n\nManchmal frage ich mich, ob ihr Geschwätz der Grund für das Verschwinden der anderen Dryaden war. Aber ich bin froh, dass es ihr gut geht.\n\nWillkommen in Wisperwindhain, &lt;Klasse&gt;. Wenn Ihr Frieden im Herz habt, so kann Euch Wisperwindhain eine gute Heimat sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28307] = {title = "Trefft Tyelis", objective = "Sprecht mit Tyelis in der Feste Grommash im Tal der Stärke in Orgrimmar.", description = "Tyelis, ein Mitglied der Delegation Silbermonds in Orgrimmar, hat Euch zu einem Treffen aufgefordert, wenn Ihr das nächste Mal in der Stadt seid. Ihr könnt ihn in der Feste Grommash in Orgrimmars Tal der Stärke finden. Es muss eine wichtige Angelegenheit sein, wenn er Euch so direkt auffordert, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28308] = {title = "Trefft Seherin Liwatha", objective = "Sprecht mit Seherin Liwatha im Tal der Weisheit in Orgrimmar.Seherin Liwatha schickt ihre Grüße aus dem Tal der Weisheit in Orgrimmar, <Name>. Sie hat mich gebeten, eine Einladung für Euch auszusprechen. Sie möchte, dass Ihr sie besucht, wenn Ihr das nächste Mal in der Stadt seid. Es klang, als habe sie ein wichtiges Anliegen mit Euch zu besprechen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Seherin Liwatha schickt ihre Grüße aus dem Tal der Weisheit in Orgrimmar, <Name>. Sie hat mich gebeten, eine Einladung für Euch auszusprechen. Sie möchte, dass Ihr sie besucht, wenn Ihr das nächste Mal in der Stadt seid. Es klang, als habe sie ein wichtiges Anliegen mit Euch zu besprechen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28309] = {title = "Trefft Schattenläufer Zuru", objective = "Sprecht mit der dunklen Klerikerin Cecille in der Feste Grommash im Tal der Stärke in Orgrimmar.Schattenläufer Zuru, ein angesehener Priesterlehrer, hat um ein Treffen mit Euch in Orgrimmar gebeten. Ihr könnt ihn im Tal der Geister bei den anderen Lehrern vom Stamm der Dunkelspeere finden. Es muss sehr wichtig sein, wenn sie so direkt nach Euch schickt, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Schattenläufer Zuru, ein angesehener Priesterlehrer, hat um ein Treffen mit Euch in Orgrimmar gebeten. Ihr könnt ihn im Tal der Geister bei den anderen Lehrern vom Stamm der Dunkelspeere finden. Es muss sehr wichtig sein, wenn sie so direkt nach Euch schickt, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28310] = {title = "Morgans Wacht", objective = "Meldet Euch bei Oralius in Morgans Wacht in der Brennenden Steppe.", description = "Unsere Arbeit hier in Meißelgriff ist abgeschlossen; in erster Linie, weil Ihr uns geholfen habt. Nun werden wir uns in Richtung Osten begeben, zu Morgans Wacht.\n\nWir wurden informiert, dass Morgans Wacht leersteht, weil die meisten Einwohner zum Schwarzfels gezogen sind, um ihren Kampf gegen die Orcs des Schwarzfelsklans zu führen. Morgans Wacht sollte ein guter Operationspunkt für die letzten Phasen unseres Vorhabens sein.\n\nNatürlich wird Keeshan Euch begleiten. Und ich auch.", progress = nil, completion = "Ihr seid angekommen! Und gerade rechtzeitig zur Freundschaftszeremonie!\n\n&lt;Oralius blickt wehmütig über seine Schulter zu dem Ogerkopf und verfällt in Panik.&gt;\n\nHauptmann Winky! Wo ist Hauptmann Winky hin?\n\nOh, bitte, sagt nicht, dass er kalte Füße bekommen hat!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28311] = {title = "Geschwärzte Asche", objective = "Sammelt 9 Haufen Obsidianasche.", description = "Ihr müsst für mich noch etwas besorgen, bevor wir uns dem Rest der Schwarzfelsarmee annehmen können. Wenn wir das hier tun wollen, sollten wir es richtig tun, und das bedeutet, dass wir uns vorbereiten müssen.\n\nIch brauche Asche, <Name>. Nicht irgendwelche Asche... Asche von den großen Obsidianelementaren, die sich in den Ebenen im Nordwesten aufhalten. Das Zeug ist tiefschwarz, und genau das brauchen wir für unsere nächste Verkleidung.\n\nKeine Sorge, Ihr habt schon eine Verkleidung. Diese ist für jemanden... naja, für ETWAS... anderes.", progress = "Die Asche der Obsidianelementare ist besonders dunkel - und genau, was wir für unser Vorhaben benötigen.", completion = "Ja, die sind gut genug. Ich werde sie für Euch schön einpacken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28312] = {title = "Schlafende Dämonen des Landes", objective = "Sammelt 18 gefallene Flammkin.", description = "Die Lavaseen westlich von hier sind die Heimat der Flammkin, eine besondere Art Feuerdämonen, die die Steppe schon lange beheimaten. In der Schwarzfelsarmee sieht es so aus, als könnten wir - wenn wir vorsichtig genug sind - ein paar der Flammkin hinter die feindlichen Linien schmuggeln, um für Verwüstung zu sorgen.\n\nBringt mir die Leichen von mehreren Flammkin. Als Dämonen kann man sie leicht wiederbeleben, und dann für seine eigenen Zwecke einsetzen.", progress = "Die Flammkin sind schwach, aber sie reisen in Rudeln. Seid vorsichtig.", completion = "Für das ungeübte Auge sehen sie aus wie Wichtel.\n\nWir müssen sie nur diesem eben ungeübten Auge unterjubeln. Ich werde sie jetzt für den Einsatz vorbereiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28313] = {title = "Ein köstlicher Haufen Worg", objective = "Benutzt die Worgsäge, um aus den frisch getöteten riesigen Glutworgs 40 Worgschnitzel zu schneiden.", description = "Wir brauchen frisches Fleisch und deshalb werdet Ihr Euch auf die Worgjagd machen. Die Worgs auf dieser Seite der Steppe sollten die sein, auf die Ihr Euch bei der Jagd konzentriert.\n\n<Trottmann holt eine große Klinge hervor und händigt sie Euch aus.>\n\nMacht Jagd auf die riesigen Glutworgs. Benutzt diese Säge, um die besten Fleischstücke aus den frisch getöteten Worgs zu schneiden. Worgs sind überall in der Steppe zu finden; nordöstlich von hier ist gleich das erste Rudel.", progress = "Glück bei der Jagd gehabt?", completion = "Das Fleisch sieht gut aus... aber ich glaube, wir müssen es noch ein bisschen \"würzen\". Ich werde sicherstellen, dass sich jemand darum kümmert.\n\nVielen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28314] = {title = "Blutrunde", objective = "Tötet 25 schwarze Großdrachenbrut oder Schwarzwyrmkin.", description = "Meine Beine werden schon wieder ein wenig rastlos. Habt Ihr Lust, eine kleine Runde zu drehen, <Name>?\n\nWir werden uns auf eine Reise um den Schreckensfels begeben. Ich möchte die Schwarzfelsarmee erst ein wenig unter die Lupe nehmen, bevor wir zuschlagen. Da dachte ich mir, wir könnten auch ein paar von ihnen töten, wenn wir schon auf dem Weg sind.", progress = nil, completion = "&lt;Keeshan trieft vor Blut und Schweiß.&gt;\n\nGenau das hatte ich im Sinn!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28315] = {title = "Drachenvorhut", objective = "Tötet Minyoth, Welpenbändigerin Akumi, Terromath den Versengten und Tugnar Blutschlund.", description = "Die Schwarzfelsorcs kommen nicht allein. Die Oger der Feuermägen und Trolle der Gluthauer, die an ihrer Seite kämpfen, habt Ihr bereits gesehen. Leider haben sie aber auch die schwarzen Großdrachen auf ihrer Seite.\n\nDie Orcs und Drachen haben bereits ihre Champions zu Sammelpunkten geschickt, um Wache zu stehen. Ihr könnt sie an den Drachenschädeln auf Piken erkennen, die herumstehen. Wir beide werden diese Sammelpunkte finden und die Vorposten ausschalten, bevor die Schlacht beginnt.\n\nSeid Ihr bereit?", progress = "Kommt schon, <Name>, es sind noch ein paar von ihnen übrig. Unsere Arbeit ist noch nicht erledigt.", completion = "Ihr werdet immer besser, &lt;Name&gt;! Jetzt fallen sie, so wie wir es wollten.\n\nUnd wir werden siegen. Das Rotkammgebirge wird NIEMALS diesen Feiglingen gehören.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28316] = {title = "Ein Handel mit einem Drachen", objective = "Bringt die geretteten Welplinge zu Acride im Schlitterfels in der Brennenden Steppe.", description = "Auf unserer Reise um den Schreckensfels gibt es noch einen Zwischenstopp.\n\nErinnert Ihr Euch noch an die Brutlinge, die Ihr aus den Schlupfhügeln befreit habt? Trottmann hat sich um sie gekümmert. Jetzt werden wir sie zu jemandem bringen, der besser für sie sorgen kann als wir. Er hält sich am Schlitterfels auf, nordöstlich des Schreckensfels.\n\nSein Name ist Acride. Er ist vielleicht der Schlüssel zum Sieg in der bevorstehenden Schlacht.", progress = "Da seid Ihr ja, <Name>.", completion = "Ja, die Welplinge. Ich werde mich um sie kümmern.\n\nUnd was die Vereinbarung angeht, die ich zuvor mit Eurem Oberst Trottmann getroffen habe, sagt ihm, dass ich meinen Teil des Handels erfüllen werde. Ich werde Euch Euren Drachen für die Schlacht gegen die Orcs schicken.\n\nWir hegen zwar keine Sympathien für das Rotkammgebirge, aber wir teilen Eure Verachtung dem Schwarzfelsklan gegenüber.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28317] = {title = "Eine Lieferung für Thorg'izog", objective = "Tragt Eure Schwarzfelsverkleidung und bringt die in Karussellstöffsche marinierten Schnitzel zu General Thorg'izog im Ofen der Feuermägen in der Brennenden Steppe. Sprecht mit Oberst Trottmann, wenn Ihr eine neue Schwarzfelsverkleidung braucht.", description = "General Thorg'izog ist bei den Ogern im Ofen der Feuermägen, eine Höhle in der Westwand des Schreckensfels. Bringt diese Lieferung zu ihm und den Ogern.\n\nDarin befinden sich die Worgschnitzel, die Ihr besorgt habt. Sie wurden in dem Teufelskarussellstöffsche mariniert, das wir vom Altar der Stürme erhalten haben.\n\nIhr solltet nichts davon essen, wenn es Euch irgendwie möglich ist.\n\nBringt die Schnitzel zu General Thorg'izog. Er wird sich darum kümmern, dass seine Streitmächte Essen im Magen haben und mit ein bisschen Glück isst er auch etwas davon.", progress = "Was habt Ihr da, Soldat?", completion = "Nun seht Euch das an! Jetzt weiß ich, wer mein Lieblingssoldat ist!\n\nIch werde die Schnitzel unter den Ogern verteilen.\n\nIch werde Euch am Rotkamm wieder sehen, Soldat. Für die Ehre des Schwarzfels!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKarussellstöffsche mariniertes Fleisch beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28318] = {title = "Eine Lieferung für Neeralak", objective = "Legt Eure Schwarzfelsverkleidung an, schleicht Euch in die Schädelhöhle und überzeugt Drachenlord Neeralak, Eure Kiste voller schlafender Flammkin anzunehmen. Sprecht mit Oberst Trottmann, wenn Ihr eine neue Schwarzfelsverkleidung benötigt.", description = "Die Hexenmeister des Schwarzfelsklans üben ihre Magie oft in der Schädelhöhle östlich des Schreckensfels. Ihr Anführer Xi'lun ist gerade andernorts beschäftigt, sodass die Höhle derzeit von einem anderen der großen Drei beaufsichtigt wird: Drachenlord Neeralak. Neeralaks Fachgebiet sind Drachen, nicht die Totenbeschwörung.\n\nIch habe die Flammkin, die Ihr gefangen habt, mit dem Schlummersand bestreut. Überzeugt Neeralak davon, dass es sich dabei um Hexenmeisterwichtel handelt, nicht um Flammkin. Wenn sie aufwachen, werden sie alles andere als glücklich sein.", progress = "Was?", completion = "Was soll das sein? Aha, das sind also Wichtel?\n\nIch bin mir sicher, dass Wichtel nicht einfach so in Kisten schlafen!\n\nAber ich nehme Euch beim Wort. Ich verstehe nichts von diesem Hexenmeisterquatsch. Stellt sie in der Ecke ab.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSack voller schlafender Flammkin beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28319] = {title = "Eine Lieferung für Xi'lun", objective = "Legt Eure Schwarzfelsverkleidung an und bringt die klare Glaskugel zum obersten Hexenmeister Xi'lun auf dem Schreckensfels in der Brennenden Steppe.", description = "Man hat uns berichtet, dass der oberste Hexenmeister Xi'lun, das letzte Mitglied der großen Drei, sich in einer Höhle auf dem Gipfel des Schreckensfels aufhält und seinen großen Augenblick vorbereitet.\n\nEr erwartet eine Lieferung: eine Kugel der Herrschaft, mit der er ein mächtiges Beschwörungsritual durchführen kann. Ich möchte, dass Ihr ihm das hier gebt.\n\n<Trottmann reicht Euch eine Glaskugel.>\n\nDies ist die klare Glaskugel, die Ihr aus dem Altar der Stürme befreit habt. Sie ist machtlos. Gebt sie Xi'lun und betet, dass er den Unterschied nicht bemerkt.", progress = "Ich habe keine Zeit für Spielchen, Narr. Geht mir aus den Augen.", completion = "Pff! Ihr seid spät dran! Wisst Ihr, wie lange ich schon warte, dass Ner'gosh mir endlich diese Kugel bringt?\n\n&lt;Xi'lun schaut auf die Kugel, dann wieder zu Euch.&gt;\n\nEtwas ist merkwürdig an dieser Kugel... Sie ist zu...\n\n&lt;Xi'lun verstummt.&gt;\n\nAch, schon gut. Meine Nerven liegen wohl einfach blank. Vielen Dank für die Lieferung. Für Blut und Donner!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKlare Glaskugel beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28320] = {title = "Angriff auf den Schreckensfels", objective = "Tötet 200 Eindringlinge des Schwarzfels. Wenn Ihr Euer Fahrzeug verlieren solltet, benutzt das Horn der Rufer, um es herbeizurufen.", description = "Das ist es also, <Name>! Hier soll es geschehen. Hier fügen sich alle Teile zusammen.\n\nSchnallt Euch an und kommt mit mir. Wir werden mit Acride sprechen und den Gefallen einfordern, den er uns schuldet. Dann werden wir die Invasion im Rotkammgebirge aufhalten, bevor sie überhaupt begonnen hat.", progress = nil, completion = "Habt Ihr gesehen, wie sie gerannt sind? Sie hatten keine Ahnung, wie ihnen geschieht! Wunderbar!\n\nUnsere Aufgabe ist fast erledigt, &lt;Name&gt;. Es ist Zeit, ihnen den Todesstoß zu versetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28321] = {title = "Ruhm im Chaos", objective = "Tötet General Thorg'izog, Drachenlord Neeralak und oberster Hexenmeister Xi'lun.", description = "Ihr und Keeshan geht zurück zu diesem Berg. Drei Orcs haben den Angriff überlebt, und wir geben keine Ruhe, bis sie den Tod gefunden haben.\n\nGenau, ich spreche von den großen Drei.\n\nGeneral Thorg'izog ist in den Ofen der Feuermägen gekrochen und Drachenlord Neeralak hat sich in der Höhle auf dem Berggipfel verschanzt. Xi'lun hält sich im hinteren Teil der Schädelhöhle auf und schmiedet Pläne mit seinen Hexenmeisterfreunden.\n\nMacht Euch einen Namen, <Name>. Jagt diese Jammerlappen des Schwarzfels und zeigt ihnen die Macht des Rotkammgebirges!", progress = "Viel Glück, Soldat.", completion = "&lt;Oberst Trottmann strahlt vor Freude.&gt;\n\nWillkommen daheim, Jungs.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28322] = {title = "Kriegsbeute", objective = "Untersucht die Kiste mit übriggebliebenen Vorräten in Morgans Wacht in der Brennenden Steppe.", description = "Wir haben heute einen Riesen überwältigt, <Name>. Die Schwarzfelsorcs schwirren zwar immer noch im Berg herum, aber ich bezweifle, dass ihre Pläne sie in nächster Zeit auch nur in die Nähe des Rotkammgebirges führen. Das habt Ihr und Keeshan ihnen sicher ausgetrieben.\n\nIch muss sagen, dass wir hier in der Brennenden Steppe nicht mit Einfallsreichtum gegeizt haben. Diese Hexenmeisterausrüstung, die wir gesammelt haben, war äußerst praktisch, und auch die Obsidianasche, mit der wir unseren Drachen versteckt haben, war ein cleverer Schachzug.\n\nWir haben jedoch noch ein paar Gegenstände übrig. Bitte, sucht Euch etwas aus, bevor Ihr die Steppe wieder verlasst und weiterzieht.", progress = nil, completion = "Ihr schaut hinein und findet...", rewards = "Obsidiandurchsetztes CapeGlutworgstiefelRasiermesserscharfer SkorpidgürtelHandschutz des GolemzerschmetterersAuf Euch wartet eine dieser Belohnungen:\n\nXi'luns Signet\n\nIhr bekommt außerdem:\n\nGesprungene Kugel der Herrschaft"}
MultiLanguageQuestData['de'][28323] = {title = "Ein Treffen mit Bruder Silberheil", objective = "Sprecht mit Bruder Silberheil in den Goblinslums von Orgrimmar.Bruder Silberheil wünscht Euch zu sprechen. Wenn Ihr das nächste Mal in Orgrimmar seid, sucht ihn in den Goblinslums auf. Es klang, als hätte er etwas Wichtiges mit Euch zu bereden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Bruder Silberheil wünscht Euch zu sprechen. Wenn Ihr das nächste Mal in Orgrimmar seid, sucht ihn in den Goblinslums auf. Es klang, als hätte er etwas Wichtiges mit Euch zu bereden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28324] = {title = "Studien der Tödlichkeit", objective = "Sammelt 250 Seuchenproben.", description = "Wir haben einen ziemlich mächtigen Erregerstamm der Seuche gegen die Menschen in Süderstade eingesetzt. Und wie Ihr seht hat es wunderbar funktioniert. Das Problem beim Einsatz der Seuche ist jedoch, dass sie nachdem sie ihren Zweck erfüllt hat nicht so einfach verschwindet.\n\nIch möchte, dass Ihr diese Testausrüstung nehmt und eine Tödlichkeitsanalyse an dem Seuchenschlamm vornehmt, den wir in der Gegend ausgesetzt haben. Benutzt den Tödlichkeitsanalysator am Seuchenschlamm, der in den Schleimpfützen umherschleimt. Kehrt zu mir zurück, wenn Ihr ein paar handfeste Daten gesammelt habt.", progress = nil, completion = "Oh je. 250? Dieses Ding zeigt maximal 250 an. Ihr habt Glück, dass Ihr noch steht. Ihr solltet eigentlich schon längst zu einer Schleimpfütze zerflossen sein. Diese Nachrichten werden Sylvanas gar nicht gefallen. Vielleicht können wir innerhalb von ein paar Jahrzehnten die Tödlichkeitswerte in dieser Gegend verringern, aber dann geraten wir immer noch etwa hundert Jahre ins Hintertreffen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28325] = {title = "Denkt grün!", objective = "Sammelt 8 gebrauchte Seuchenkanister.", description = "Recycling! Das ist in letzter Zeit in aller Munde. Die Bansheekönigin hat befohlen, dass wir Ressourcen schützen müssen, wenn wir als Volk erblühen wollen. Und jeder muss schließlich seinen Teil beitragen, nicht wahr? Also werdet Ihr unseren Teil für uns erledigen.\n\nEs liegen bestimmt Tausende von Seuchenkanisterteilen in ganz Süderstade verstreut. Wir können diese Kanister gut für weitere aufregende Seuchenangriffe nutzen. Geht einfach in die Ruinen hier und nehmt alles mit, was Ihr finden könnt.", progress = "Bringt mir diese Kanister!", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Ihr seid unglaublich widerstandsfähig gegenüber dieser Seuche. Wir müssen bei Gelegenheit einmal ein paar Tests an Euch durchführen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28326] = {title = "Aufstellung der Bauern", objective = "Kehrt zu Oberst Trottmann in Morgans Wacht in der Brennenden Steppe zurück.", description = "<Name>. Ihr und Keeshan scheint Eure Aufgaben erledigt zu haben. Ich bin ebenfalls mit meiner fertig.\n\nKehrt zu Morgans Wacht zurück. Ich habe ein paar Pakete für die großen Drei vorbereitet: Thorg'izog, Neeralak und Xi'lun. General Thorg'izog habt Ihr ja schon getroffen. Jetzt habt Ihr die Gelegenheit, auch den anderen beiden zu begegnen.\n\nBevor wir sie töten meine ich natürlich.", progress = nil, completion = "Gut, Ihr seid zurück.\n\nIch hoffe, Ihr habt die Verkleidung noch. Ihr werdet Euch wieder mitten unter die Feinde begeben, &lt;Name&gt;.", rewards = "BauernarmschienenArmschienen der WachtSubversive SchritteBrustplatte des verdeckten ThoriumbrudersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28327] = {title = "Geladen und entsichert", objective = "Meldet Euch bei Oberst Trottmann in Morgans Wacht in der Brennenden Steppe.", description = "<Name>, bitte melden. Könnt Ihr mich hören?\n\nDie Schlacht beginnt gleich. Ich hoffe, Ihr habt alle Pakete ausgeliefert.\n\nIch brauche Euch hier in Morgans Wacht, SOFORT.", progress = nil, completion = "&lt;Name&gt; ist da! Wir können loslegen.\n\nDas ist der Moment, auf den wir gewartet haben, &lt;Name&gt;. Ich hoffe, Ihr seid in Bestform.", rewards = "Imitierte HexenmeisterpantoffelnHandschuhe des listigen GleitersBoshafte SchiftungArmschienen des FehlverhaltensAuf Euch wartet eine dieser Belohnungen:\n\nGlasiges Band\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSchwarzfelsverkleidung entfernen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28328] = {title = "Zwielichtränke", objective = "Benutzt die leuchtende Fackel, um 8 Abschriften des Glaubensbekenntnisses des Schattenhammers im Domizil der Schwarzfelstiefen zu zerstören.", description = "Der Einfluss des Schattenhammers reicht weit. Sie sind unablässig auf der Suche nach Verbündeten in ihrer Schlacht gegen uns und rekrutieren jetzt sogar die Dunkeleisenzwerge der Schwarzfelstiefen für ihre Sache.\n\nMoira hat die Dunkeleisenzwerge nur dürftig im Griff. Jeden Tag wenden sich mehr und mehr ihrer Leute von ihrer Herrschaft ab. Wir müssen ihre Rekrutierung sabotieren.\n\nIch möchte, dass Ihr in das Domizil der Schwarzfelstiefen geht und diese Fackel benutzt, um die Bücher zu verbrennen, die der Schattenhammer dort verteilt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKrone der Geheiligten"}
MultiLanguageQuestData['de'][28329] = {title = "Böser Schlamm! Böser Schlamm!", objective = "Tötet 5 wütende Seuchenschlamme.", description = "Dieser Seuchenschlamm scheint wirklich wütend zu sein. In seinem Ektoplasma kann man sogar ganz schwach die Konturen eines wütenden humanoiden Gesichts sehen. Hinott wäre sicher nicht allzu erfreut, wenn seine Schleimpfützen mit unkooperativem Schlamm übersät sind.\n\nTötet den wütenden Seuchenschlamm und versucht, einer ihrer Brutpfützen Herr zu werden.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Player Phase/Auras\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28330] = {title = "Dreckige Spuren", objective = "Tötet Chet den Schleimzüchter.", description = "Die Spur aus Dreck und Wut führt in die Ruinen des Rathauses. Sicherlich befindet sich eine Brutpfütze in dem Gebäude. Kämpft Euch hinein und macht kurzen Prozess mit dem wütenden Schleimzüchter, den Ihr dort findet!\n\nWenn Ihr Erfolgt habt, solltet Ihr Serge Hinott in den Ruinen von Süderstade unbedingt davon berichten.", progress = nil, completion = "Jetzt, da Chet vernichtet ist, sinken die Tödlichkeitswerte an diesem Ort vielleicht schneller. Gute Arbeit, &lt;Name&gt;!", rewards = "Hinotts ÜberrobeChets schleimige ArmschienenTödlichkeitsgamaschenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28331] = {title = "Helculars Rute gibt...", objective = "Benutzt Helculars Rute, um 8 dunkle Waldläuferinnen zu stärken.", description = "Kaum vorstellbar, dass ich, Meister der Totenbeschwörung und Schüler Kel'Thuzads selbst, nur noch eine Leiche in einem Grab sein sollte! Zum Glück fand mein geistreicher Novize Thaivand eine Gruppe von Helden, die das hier wiederbeschafft haben:\n\n<Helcular zieht seine Rute hervor.>\n\nDurch die Macht der Rute konnte ich wiedergeboren werden. Die Rute gibt und die Rute nimmt!\n\nNun benutzt sie, um unsere dunklen Waldläuferinnen zu stärken, die sich auf dem Feld nördlich von uns eine Schlacht mit den Worgen liefern. Erneuert ihre Lebenskraft mit meiner Rute.", progress = nil, completion = "Wie ich sagte, die Rute gibt unseren dunklen Waldläuferinnen und nimmt von unseren Feinden!", rewards = "Ihr bekommt:\n\nHelculars andere Rute"}
MultiLanguageQuestData['de'][28332] = {title = "Helculars Befehl", objective = "Tötet 15 Blutfangverlassenenjäger.", description = "Unsere dunklen Waldläuferinnen suchen die Felder nach Attentätern der Worgen ab. Diese Worgen wurden von ihren dunklen Meistern ausgesandt, um uns zu jagen und zu töten. Und obwohl unsere dunklen Waldläuferinnen ausgezeichnete Kämpferinnen sind, greifen die Worgen oft in Rudeln an, denen nicht einmal die stärkste Waldläuferin standhalten kann.\n\nDurchkämmt die Ruinen von Süderstade nach Blutfangverlassenenjägern. Tötet alle, die Ihr finden könnt! Für die Verlassenen und für Lordaeron!", progress = nil, completion = "Wir hätten Blutfang im Silberwald töten sollen. Es ist eine Schande, dass er noch am Leben ist. Und es ist noch eine größere Schande, dass wir bis jetzt noch keine Worgen in Untote verwandeln konnten. Es muss doch einen Weg geben...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28333] = {title = "Wie geschmiert", objective = "Benutzt Darlas Enterhaken, um Ölkannen aus dem Eisenwald zu sammeln, und benutzt sie, um 7 Eisenwaldschredder zu schmieren.", description = "Aus der Eisenwaldlichtung kommen drei Dinge: Holz, Öl und müde Arbeiter. Die ersten beiden Dinge sind der Grund für Letzteres, aber ich möchte so effizient wie möglich arbeiten.\n\nUnsere Schredder machen dreifache unbezahlte Überstunden. Im Zeitplan ist einfach kein Platz für Wartungsarbeiten.\n\nBenutzt diesen Enterhaken, um Euch ein paar der schwebenden Ölkannen aus dem Lager zu beschaffen und die Schredder zu schmieren, ja?", progress = nil, completion = "Effiziente Arbeitskraft! Wunderbar.\n\nVielleicht sollte ich später mal nach den Goblins in den Schreddern sehen.", rewards = "Überarbeitete SchulternHelm des SchredderführersEffizienzzauberkolbenÖlfilterschildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28334] = {title = "Da geht Euch ein Licht auf", objective = "Benutzt Darlas Kiste mit Megaleuchtfeuern, um 8 Nachtlaubstreuner zu enttarnen, und tötet sie.", description = "Unser Werk hier erfreute sich bisher höchster Diskretion, aber die Worgen drüben in der Nachtlaublichtung sitzen uns im Nacken. Sie haben alles in ihrer Macht Stehende versucht, um uns den Hahn abzudrehen.\n\nEinige meiner Arbeiter haben berichtet, dass sie auf der Lichtung Worgen vorbeihuschen sahen. Nehmt diese übergroßen Megaleuchtfeuer. Sie sind hell genug, um alles in ihrer Nähe sichtbar zu machen.\n\nBenutzt die Leuchtfeuer, um streunende Worgen ausfindig zu machen. Stellt sicher, dass sie diesen Ort nicht lebend verlassen!", progress = nil, completion = "Diese verfilzten Köter denken, sie könnten einfach so hier hereinmarschieren und meine exakt geplante Unternehmung zunichtemachen. Hah!\n\nIch hab Euch doch gesagt, dass Ihr nicht direkt in das Leuchtfeuer schauen sollt, oder? Ups.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28335] = {title = "Ausschalten! Ausschalten!", objective = "Schaltet die Hauptkontrollpumpe tief in der Eisenwaldhöhle aus.", description = "Das waren diese verdammten Worgen! Sie sind direkt an mir vorbei in die Höhle geschossen.\n\nBestimmt haben sie sich an der Hauptkontrollpumpe zu schaffen gemacht. Wenn das Ding zu lange eingeschaltet bleibt, wird jedes einzelne Rohr unter unseren Füßen in die Luft fliegen! Ihr findet die Lecks schon schlimm? Na dann wartet mal ab!\n\nHört zu, wenn Ihr zur Hauptkontrollpumpe ganz hinten in der Höhle gelangt, könnt Ihr sie ausschalten und uns alle retten!", progress = nil, completion = "Ihr legt den größten Hebel der Hauptkontrollpumpe um, den Ihr finden könnt, und das Klappern in den Rohrleitungen verstummt.\n\nIn dem Moment der Stille hört Ihr von draußen Flammen und eine vertraute Stimme, die aus einem blechernen, kratzenden Lautsprecher erklingt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28336] = {title = "Backpfeifen für die Pfeifen", objective = "Ohrfeigt 7 panische Arbeiter, damit sie die Ölspritzer abdichten.", description = "Ach zum... nicht schon wieder! Wenn Ihr den Stellvertreter da draußen habt schreien hören, haben wir es mit einem ausgewachsenen Ölleck zu tun! Das waren schon wieder diese verdammten Worgen!\n\nHört zu, da draußen wird das reinste Chaos herrschen. Übermüdete Goblins werden schreiend durcheinander rennen und nicht wissen, was sie tun sollen. Ihr müsst die Arbeiter wieder zur Vernunft bringen.\n\nEine kräftige, schnelle Ohrfeige mitten ins Gesicht sollte Wunder wirken. Sobald sie wieder bei Sinnen sind, werden sie an die Arbeit gehen und die Ölspritzer abdichten.", progress = nil, completion = "Es funktioniert nicht! Wir müssen die Quelle ausschalten.\n\nSprecht sofort mit dem Stellvertreter. Er wird Euch alles erklären!", rewards = "ÖlfußpantoffelnÖlschwallgamaschenBrustschutz der ArbeitskraftUmhang des SchlafentzugsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28337] = {title = "Die Eisenwaldschredder", objective = "Zerstört 9 Eisenwaldschredder.", description = "Widerlich, oder? Schaut sie Euch nur an. Erbärmliche kleine Wesen, die nicht einmal mit ihrem eigenen Körper schuften können.\n\nSie walzen mit ihren massiven Metallschreddern einfach alles platt und verwandeln den Wald in Sägemehl. Bestimmt glauben sie, dass sie in den Dingern sicher sind, so warm und geborgen.\n\nBeweist ihnen das Gegensteil. Fegt nach Norden durch das Lager und zerstört so viele Schredder, wie Ihr könnt. Sobald Ihr ein wenig Blut vergossen habt, werden wir diesen Ort ein für alle Mal auseinandernehmen.", progress = nil, completion = "Das war nur unser erster Schlag.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28338] = {title = "Totenwaldfelle des Nordens", objective = "Tötet 15 Furbolgs der Totenwaldfelle im Revier der Teufelspfoten.", description = "Direkt südwestlich von hier befindet sich ein Lager der Furbolgs der Totenwaldfelle. Das Lager ist von der Verderbnis durchzogen, und ich möchte dem ein Ende setzen, bevor es noch zu einem echten Problem wird.\n\nDie Totenwaldfelle sind böse, doch es sind die Auswirkungen der Verderbnis, die ihren Geist vernebeln. Sie sind nicht von Geburt an so feindselig und dennoch gibt es kein Heilmittel für sie. Es schmerzt mich, dass wir unsere eigenen Brüder bekämpfen müssen.\n\nBitte, <Name>. Ich verlange etwas von Euch, das getan werden muss. Erspart mir einfach die Einzelheiten. Diese schrecklichen Bilder würden mich zu sehr in Aufruhr versetzen.", progress = nil, completion = "Ich spüre, dass Ihr einen Sieg errungen habt. Sieg... Welch schalen Nachgeschmack hinterlässt dieses Wort in Anbetracht der grausamen Aufgabe, die Ihr erledigen musstet. Dennoch habt Ihr bewiesen, dass Ihr unseres Vertrauens würdig seid.\n\nEs mag vielleicht ein wenig dauern, bis die Furbolgs der Holzschlundfeste Euch mit Freundlichkeit willkommen heißen. Doch wenn Ihr Euch weiter bemüht, wird der Argwohn meiner Brüder Euch gegenüber sicher schnell dahinschmelzen. Solange Ihr uns nicht verratet oder die Waffen gegen uns erhebt, werden wir uns sicher einigen können.", rewards = "Gamaschen des UrsaHelm des PfadfindersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28339] = {title = "Das läuft weg wie Öl", objective = "Sammelt 10 Rohteerklumpen von öligem Schlick.", description = "Das letzte Mal, als wir hier so ein schlimmes Ölleck hatten, hat das Öl selbst versucht auszubüxen.\n\nIch weiß nicht, was der Grund dafür ist. Vielleicht ist es der ganze Dämonenschlamm, der hier herumschleimt. Wenn wir ein großes Leck haben, rottet sich jedenfalls das halbe Öl zusammen und versucht zu flüchten.\n\nDas ist bares Gold, was da auszubrechen versucht! Verfolgt diesen öligen Schlick und bringt mir mein wundervolles, teures Öl zurück!", progress = "Das Zeug sollte sich besser nicht mehr bewegen, wenn Ihr es hierher zurückbringt.", completion = "Welch ein Glück! Mein Öl ist in Sicherheit! Gut gemacht, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28340] = {title = "Ein Bombengeschäft", objective = "Sammelt 8 Stück Eisenwaldsprengstoff aus der Eisenwaldhöhle.", description = "Alle meine Arbeiter wurden von diesen großen Sumpfdingern aus der Höhle vertrieben! Darla hat mich hierher geschickt, um die Reste aufzusammeln, aber habt Ihr gesehen, wie es da drin ausschaut? Ich gehe da nicht rein!\n\nWir haben eine Unmenge von Sprengstoff zurückgelassen, auf den wir einfach nicht verzichten können.\n\nIch schlage Euch ein Geschäft vor: Ihr begebt Euch dort hinein und sammelt den Sprengstoff und ich bleibe hier und werde nicht von den Sumpfdingern getötet. Und wenn Ihr es auch heil hinaus schafft, dann bezahle ich Euch! Wie findet Ihr das?", progress = "Wir hatten eine Abmachung, oder? Oder?", completion = "Hui, super! Ich nehme Euch das hier ab... vorsichtig...\n\nVerratet den Arbeitern ja nicht, dass ich nicht den Mumm hatte, selbst hineinzugehen, ja? Hier ist Eure Bezahlung... und noch ein bisschen obendrauf.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28341] = {title = "Verderbnis sammeln", objective = "Sammelt 8 entropische Essenzen von entropischen Schrecken im Narbengrund.", description = "Obwohl wir Druiden die dämonischen Mächte scheuen, die dieses Land heimsuchen, müssen wir uns doch darum kümmern.\n\nDer Narbengrund im Süden ist ganz von der Verderbnis verseucht. Die Energien dort sind so chaotisch, dass sie sich als gewalttätige Wesen manifestieren, reine teuflische Magie, die nach allem Leben trachtet.\n\nIch habe diese chaotischen Wesen genau beobachtet und ihre Stärken untersucht. Ich muss sichergehen, dass sie immer noch mit der Zeit schwächer werden. Bringt mir ihre Essenzen, damit ich sicherstellen kann, dass ihre Zahl sich verringert.", progress = "Seid vorsichtig mit der Essenz. Sie ist mindestens so gefährlich wie mächtig.", completion = "Allein schon an der Größe der Essenzen kann ich erkennen, dass die teuflische Verderbnis heilt. Langsam... aber merklich.\n\nVielen Dank, &lt;Name&gt;. Ich werde sicherstellen, dass diese Exemplare ordnungsgemäß geläutert werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28342] = {title = "Fahrt zur Hölle", objective = "Sammelt 9 Einheiten Höllenbestienüberreste im Narbengrund.", description = "Die im Narbengrund lauernden Höllenbestien sind stark, aber alles andere als unbesiegbar. Wir haben in letzter Zeit ihre Zahl schon erheblich gemindert.\n\nDoch sie zu vernichten ist nur ein kleiner Schritt zur Lösung des Problems. Ich habe herausgefunden, dass die Steine, aus denen die Höllenbestien bestehen, auch nach ihrem Tod noch große Mengen teuflischer Magie enthalten.\n\nDie Überreste vernichteter Höllenbestien bedecken den Narbengrund und ihre Verderbnis sickert zurück in die Erde. Wenn Ihr sie für mich einsammeln würdet, wäre ich sehr dankbar.", progress = "Achtet darauf, auch die Überreste der von Euch besiegten Höllenbestien einzusammeln.", completion = "Schön zu sehen, dass sich jemand darum bemüht, den Wald rein zu halten. Vielen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28343] = {title = "Der Atem des Cenarius", objective = "Beschafft den Atem des Cenarius von Pyromant Weisenkorn in den Schwarzfelstiefen und benutzt das Artefakt, um 3 Elementartore zu schließen.", description = "<Name>, wir haben erfahren, dass ein verlorengegangenes cenarisches Artefakt sich in den Händen eines Zwielichtpyromanten befindet. Pyromant Weisenkorn hat das Artefakt, den Atem des Cenarius, in die Schwarzfelstiefen gebracht und nutzt dort seine Macht, um Elementartore zu erschaffen.\n\nWir müssen handeln und Weisenkorn davon abhalten, Elementare zu beschwören, mit denen er die Reihen seiner Dunkeleisenverbündeten weiter verstärken kann. Holt das Artefakt von ihm zurück und nutzt seine Macht, um die von Weisenkorn benutzten Tore wieder zu verschließen.", progress = "Wir können nicht zulassen, dass die Dunkeleisenzwerge sich mit dem Schattenhammer verbünden.", completion = "Es erfüllt mich mit Zufriedenheit, den Atem des Cenarius wieder dort zu wissen, wo er hingehört. Und ich bin mir sicher, dass der Zirkel von Euren Anstrengungen beeindruckt sein wird. Hinzu kommt, dass Ihr vermutlich sogar die Pläne des Schattenhammerkults ein wenig zurückgeworfen habt. Gute Arbeit.", rewards = "Kopfputz des tiefgrünen ZirkelsKopfputz des grünen ZirkelsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28344] = {title = "Was zum Lok'tar geht hier ab?", objective = "Sucht Orkus den Königsmörder in den Ruinen von Süderstade im Vorgebirge vom Hügelland.", description = "Kurz bevor Ihr hier ankamt traf ein Orc auf einem Frostwyrm ein und verlangte, dass ich ihm zeigen sollte \"wo die Neuen so abhängen\". Unsicher wegen seiner Ausdrucksweise sagte ich ihm, dass er seine Pflicht als Mitglied der Horde erfüllen und sich um die Worgenbedrohung in dieser Gegend kümmern solle. Er murmelte etwas davon, was zum Lok'tar eigentlich abginge und machte sich Richtung Süden zu den Docks auf.\n\nEigentlich kümmert es mich nicht besonders, wenn ein Orc plötzlich verschwindet, aber ich bin doch ziemlich neugierig, was das Abgehen und den Lok'tar betrifft. Findet es heraus.", progress = nil, completion = "*KEUCH*\n\nHILFE!\n\nICH ERTRINKE!\n\n*GURGEL*", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28345] = {title = "*Gurgel* HILFE! *GURGEL*", objective = "Rettet Orkus den Königsmörder aus dem Wasser.", description = "*GURGEL*\n\nHILFE! *KEUCH*\n\nORKUS ERTRINKT! HELFT MIR, QUESTGEBER <Name>!\n\n*BLUBB*\n\nZwerg hat Orkus ins Wasser geworfen! Darf nicht sterben!\n\n*GURGEL*\n\nDie Schande wäre zu groß.", progress = nil, completion = "&lt;Orkus' Gesicht färbt sich so rot wie seine Rüstung.&gt;\n\nIch... äh... der Mensch muss irgendeinen Beeinflussungszauber auf Orkus gesprochen haben. Orkus erklärt es Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28346] = {title = "Der Junggeselle", objective = "Besprecht mit Keegan Feuerbart die Möglichkeit einer Heirat. Ihr findet ihn in Kirthafen im Schattenhochland.", description = "Das hier muss funktionieren, <Name>. Die Antwort liegt im Blut! Familienbande haben die Wildhammerklans einander entfremdet. Ich werde die Familientreue dazu benutzen, um sie wieder zusammenzuschweißen. Es ist ein wagemutiger Versuch, aber wir werden uns als Kuppler betätigen!\n\nIch werde Colin Donnermar ausfindig machen und mit ihm sprechen. Ihr habt ein vertrauenserweckendes Wesen, daher solltet Ihr reingehen und mit Keegan Feuerbart sprechen. Er ist vernünftig genug, um den Wert einer politischen Ehe zu erkennen. Findet heraus, an wem sein Herz hängt!", progress = nil, completion = "Was? Kurdran spricht von Heirat!? Hat er etwa nicht gesehen, wie die alte Donnerfratze und ich uns gerade die Köppe eingeschlagen haben?\n\nDie einzige Donnermar, die in Frage käme, ist Fanny. Sie sieht ja schon gut aus, keine Frage. Alle Kurven am richtigen Platz, wenn Ihr wisst, was ich meine. Aber Ihr fehlt das gewisse Etwas, das ein Feuerbart in einer Frau sucht, nicht wahr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28348] = {title = "Sturmlanzentreffen", objective = "Erfahrt etwas über das Sturmlanzentreffen von Orkus.", description = "In der Hoffnung, etwas über die Truppenbewegungen der Allianz im Hügelland in Erfahrung zu bringen, habe ich den schwächlichen Nekromanten Helcular aufgesucht.\n\nHelcular hat mich mit dem Aufspüren und Töten von Worgen beauftragt. Normalerweise wäre das eine leichte Aufgabe für Orkus, doch hatte ich gerade mehrere Portionen Dirges abgefahrener Chimaerokkoteletts verschlungen. Das hatte mir ganz schöne Magenschmerzen bereitet. Damit fing der ganze Ärger an und ich endete im Wasser.\n\nHört Orkus an, <Name>.", progress = nil, completion = "Die Rache wird mein sein, doch zuerst müssen wir Kasha heilen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28349] = {title = "Megs vom Marketing", objective = "Sprecht mit Megs Schredderschreck beim HGK-Hauptquartier in Kezan.", description = "Boss, während Ihr unten in den Minen wart, hat Megs Schredderschreck aus dem Marketing nach Euch gefragt. Es ging um ein neues Gefährt für Euch.\n\nSie hält sich außerhalb des Gebäudes auf der linken Seite auf.", progress = nil, completion = "Da ist er ja! Ich glaube, das hier wird Euch gefallen!", rewards = nil}
MultiLanguageQuestData['de'][28350] = {title = "Fallenstellermeister", objective = "Sullah möchte, dass Ihr 5 Fleischfetzen von den Tieren in Uldum sammelt.", description = "Eine Sache, die Ihr vielleicht nicht wisst, <Name>...\n\nIch stamme von einer langen Reihe von Fallenstellern ab. Mein Vater hat mir beigebracht, so wie sein Vater ihm, die Kunst des Fallenstellens in einer äußerst humanen Art und Weise auszuführen.\n\nWie Euch jeder Meisterfallensteller bestätigen wird, ist die wichtigste Komponente einer effektiven Falle der Köder.\n\nFangen wir also damit an.\n\nFüllt diesen Eimer mit Fleischfetzen von beinah jedem beliebigen Tier in Uldum.", progress = "Habt Ihr genug gesammelt, um meinen Eimer zu füllen, <Name>?", completion = "Gute Arbeit, mein Junge!\n\nAuch Ihr werdet im Nu ein Meister des Fallenstellens sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28351] = {title = "Unbegrenztes Potenzial", objective = "Verwendet den verstärkten Käfig, um 5 hüpfende Pygmäen einzufangen.", description = "Einige sehen in den Sandpygmäen nicht mehr als eine Plage, Ungeziefer oder gar bösartige kleine Dämonen.\n\nIch finde, sie werden völlig missverstanden!\n\nVielleicht würden sich diese kleinen Racker mit der richtigen Pflege und Führung gar als Geschenk der Natur entpuppen.\n\nIch möchte, dass Ihr diese Käfige dazu benutzt, um einige von ihnen einzufangen, damit ich mit ihnen arbeiten kann.\n\nIhr werdet hart mit ihnen kämpfen müssen, bevor sie sich einfangen lassen. Letztlich ist es aber zu ihrem Besten.\n\nIhr werdet schon sehen!\n\nIm Süden findet Ihr Pygmäen.", progress = nil, completion = "Ganz vortrefflich!\n\nEs entwickelt sich viel besser, als ich es je zu träumen gewagt hätte!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28352] = {title = "Kamelraderie", objective = "Benutzt Sullahs Kamelzaumzeug, um 3 Kamele zu zähmen.", description = "Grüße!\n\nIhr seid in meinem bescheidenen Zelt stets willkommen.\n\nSeid Ihr auf der Suche nach Arbeit? Sullah hat genau das Richtige für Euch!\n\nEs ist immer gut, Kamele zu besitzen! Doch wenn man wie ich eine solche Attraktion wie meinen fahrenden Zirkus betreibt, sind sie ein absolutes Muss!\n\nNehmt diesen Harnisch und bändigt mit seiner Hilfe ein umherziehendes Kamel.\n\nOh, und vergesst nicht, es erst ein wenig ruhigzustellen... wenn Ihr wisst, was ich meine.\n\nDie südliche Wüste ist voll von wilden Kamelen.", progress = nil, completion = "Ihr habt es geschafft!\n\nJetzt habe ich massig Kamele. Vielleicht werden wir eines Tages mit unserer Schau auf Reisen gehen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCamel Tow Completion\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28353] = {title = "Jonesy sucht Euch", objective = "Sprecht mit Harrison Jones in der Oase Vir'sar.", description = "Hört zu, <Name>, Ihr solltet bei Gelegenheit zu Jonesy zurückkehren.\n\nWahrscheinlich ist das, worüber er mit Euch sprechen möchte, dringlicher als alles, womit ich Euch beauftragen könnte.", progress = nil, completion = "Alles klar, Junge.\n\nMeine Nachforschungen sind abgeschlossen. Wir sind fast soweit, den letzten Obelisken zu aktivieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28354] = {title = "Kasha wird wieder fliegen", objective = "Sammelt 8 Morastschnauzenkappen.", description = "Kasha wird wieder fliegen, <Name>. Sie muss, wenn wir unsere Rache einfordern wollen! Leider muss Orkus hier bei Kasha bleiben. Ihr müsst uns helfen. Ich flehe Euch an!\n\nHört mir genau zu, Questgeber. Als ich hier eintraf, flog ich einige Tage umher, um mir die Beschaffenheit der Umgebung einzuprägen. Östlich von hier liegt ein schon lange verlassener Hof, auf dem sich mittlerweile Gnolle eingenistet haben. Auf diesem Hof gedeiht eine besondere Pilzgattung, die Morastschnauze. Reist zum Bauernhof und sammelt Morastschnauzen für Kasha. Kehrt hierher zurück, wenn Eure Taschen voll sind.", progress = "Habt Ihr Morastschnauzen mitgebracht?", completion = "Diese Pilzart ist tödlich für alles Lebende, aber wirkt regenerierend auf Untote. Lasst uns herausfinden, welche Wirkung sie auf Kasha hat.", rewards = "Rote ReithandschuheMorastschnauzenschiftungBrustplatte des KönigsmördersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28355] = {title = "Schreckliche kleine Kreaturen", objective = "Tötet 10 Gnolle bei der Nethandersiedlung.", description = "Gnolle! Diese schrecklichen kleinen Kreaturen sind wie eine Plage für jedes Land. Bedenkt man, dass das Hügelland zum Gebiet der Verlassenen gehört, soll das schon einiges heißen. Tötet nahe der Nethandersiedlung so viele Gnolle, wie Ihr nur könnt. Es ist zum Wohle der Welt!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28356] = {title = "Präventivschlag", objective = "Tötet 15 beliebige Naga am Oststrand.", description = "Diese Pläne sind der Beweis, dass ein Angriff auf Süderstade kurz bevor steht. Jetzt, wo die Allianz aus der Stadt vertrieben wurde, planen die Naga des Oststrandes, sie einzunehmen.\n\nDas heißt, sofern Ihr sie nicht aufhaltet!\n\nTötet alle Naga am Oststrand und meldet Euch mit den Angriffsplänen der Säbelflossen bei Helcular an den Ruinen von Süderstade.", progress = nil, completion = "HAH! Diese Naga haben vielleicht Vorstellungen! Zu glauben, sie könnten Süderstade innerhalb der Grenzen unseres eigenen Landes so einfach erobern. Ausgemachter Unsinn ist das.\n\n&lt;Helcular lacht.&gt;\n\nIhren Angriff zu vereiteln war ausgezeichnete Arbeit. Allerdings frage ich mich, ob sie in der Seuche auch nur eine Minute überlebt hätten.", rewards = "Präventiver StabSäbelflossendolchAuf Euch wartet eine dieser Belohnungen:\n\nBand des OststrandesSäbelflossenball\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28357] = {title = "Unter den Bäumen", objective = "Tötet 8 Nachtlaubverteidiger.", description = "Diese räudigen Köter glauben doch tatsächlich, sie könnten einfach in meinem Revier herumschnüffeln! Denen werde ich es zeigen...\n\nUnd damit meinte ich natürlich, dass IHR es ihnen zeigen werdet! Ihr und diese kleine Armee axtschwingender Goblins, die ich angeheuert und zur Nachtlaublichtung geschickt habe.\n\nDort muss es mittlerweile vor Worgen nur so wimmeln. Sie sind jetzt genau dort, wo wir sie haben wollten. Macht Euch in den Südwesten auf! Trefft Euch dort mit dem Rest unserer Truppen und wirbelt etwas Fell auf.", progress = nil, completion = "Hoffen wir mal, dass wir genügend von Ihresgleichen umgelegt haben, um ihnen eine klare Botschaft zu vermitteln.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28358] = {title = "Jagd auf die Verdammten", objective = "Tötet 6 Höllenbestienwachposten.", description = "Die ersten Dämonen, die einen Fuß in diesen Wald setzten, waren Höllenbestien. Vor langer Zeit fielen diese mächtigen Wesen aus Stein und dämonischem Feuer vom Himmel herab, um dieses Land im Namen der Brennenden Legion in Besitz zu nehmen.\n\nDie rußgeschwärzten Krater des Narbengrunds südlich von hier markieren den Ort, an dem diese Höllenbestien herniedergingen. Noch heute verweilen viele von ihnen dort. Sie sind mächtige Gegner. Einen von ihnen zu töten ist gleichermaßen nobel und eine Herausforderung.\n\nIch biete allen eine Belohnung, die sich der Jagd anschließen. Kehrt anschließend hierher zurück.", progress = nil, completion = "&lt;Klasse&gt;, ich muss Euch dafür danken, dass Ihr in meinem Namen jagt.\n\nIch habe erkannt, dass ich mich zügeln muss... So sehr in der Dämonenjagd aufzugehen ist ein gefährlicher Weg.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28359] = {title = "Der Kern von Kroshius", objective = "Besorgt Kroshius' Höllenbestienkern.", description = "Der gefährlichste aller Dämonen im Narbengrund ist Kroshius. In all den Jahren haben viele ihn gejagt, doch seine vielfache Vernichtung hat ihn nur noch stärker gemacht.\n\nImmer und immer wieder suchten Hexenmeister diesen Wald auf, um Kroshius erneut zum Leben zu erwecken. Umgeben von dämonischen Flammen lauert er jetzt im Südosten all jenen auf, die versuchen, seine Macht an sich zu reißen.\n\nDieser verderbte Kreislauf darf nicht länger fortbestehen! Tötet Kroshius und bringt mir seinen Höllenbestienkern.", progress = "Der Kern darf nie wieder in den Narbengrund zurückkehren.", completion = "Dieser verderbte Brocken lockte Jahr um Jahr immer wieder Hexenmeister an. Ich werde ihn persönlich beschützen, oder wenn möglich vernichten, auf dass sich Kroshius niemals wieder erheben kann.", rewards = "SchattenfluchkapuzeWisperwindarmbänderHöllenbestienbrustplatteHexenmeisterbannschildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28360] = {title = "Der Lauf der Dinge", objective = "Tötet 8 Teufelsmoderrenner.", description = "Gerne würde ich jede Kreatur des Waldes retten, doch wie Ihr sicherlich schon bemerkt habt, ist es für einige von ihnen bereits zu spät.\n\nAls wir uns am Wisperwindhain ansiedelten, waren die Wälder südlich von hier voller wunderschöner Renner, majestätische und friedfertige Lebewesen. Die Verderbnis an diesem Ort machte sie zwar nicht aggressiv, doch sind sie mittlerweile nur noch ein Schatten ihrer selbst.\n\nSelbst wenn man sie von der Verderbnis reinigen würde, müssten sie nur Schmerz und Leid ertragen. <Klasse>, bitte helft mir, ihnen einen gnadenvollen Tod zu gewähren.", progress = nil, completion = "Vielen Dank, &lt;Name&gt;. Sie werden die Verderbnis nicht mehr weiter verbreiten und auch keine Schmerzen mehr erdulden müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28361] = {title = "Eichhörnchenpflege", objective = "Reinigt 6 besudelte Eichhörnchen.", description = "Die großen Tiere sind der Verderbnis oft schon zu lange ausgesetzt, als das man sie noch retten könnte. Aber Ihr wärt überrascht, wie widerstandsfähig die kleinen Bewohner des Waldes sind.\n\nNehmen wir zum Beispiel die Eichhörnchen. Wenn sie in verderbtem Wasser gebadet haben, können sie die Verseuchung bis weit über die Grenzen ihrer Quelle hinweg verbreiten, doch selbst fallen sie nur langsam der Verderbnis zum Opfer. Tatsächlich muss man sie nur waschen und man hat ein gereinigtes Eichhörnchen und einen wesentlich sichereren Wald!\n\nHier, nehmt diese Flasche mit Reinigungslösung. Schnappt und reinigt jedes Eichhörnchen, das Euch in den Wäldern im Süden über den Weg läuft... Sie werden es Euch danken!", progress = nil, completion = "Sind sie nicht süß?\n\nEs sind diese kleinen Erfolge, die mich zum Weitermachen motivieren. Eichhörnchen um Eichhörnchen werden wir diesen Wald retten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28362] = {title = "Dummer Drizle!", objective = "Sucht Drizle im Revier der Teufelspfoten.", description = "Dummer, dummer Drizle! Ich hatte ihm gesagt, er solle nicht gehen!\n\nDrizle wollte noch mehr Honig aus dem Revier der Teufelspfoten stehlen... Ihr wisst schon, westlich von hier. Ihr könnt es vom Felsvorsprung aus sehen...\n\nJedenfalls... Ich sagte ihm, dass es eine dumme Idee sei, doch er ist dennoch losgezogen und dann haben ihn die Totenwaldfälle gefangen genommen und... und...\n\nSchnief...\n\nIch weiß nicht, was sie mit ihm anstellen werden! Bitte sucht ihn, <Herr/Frau:r> <Volk>! Auch wenn er ein Idiot ist! Ich will nicht, dass sie Drizle fressen!", progress = nil, completion = "HILFE! Bitte helft mir!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28363] = {title = "Stich ins Hornissennest", objective = "Sprecht mit Sullah bei Sullahs Fahrendem Zirkus.", description = "Wow!\n\nMir scheint, Ihr habt ihre volle Aufmerksamkeit, <Name>. Wir werden es niemals dort hinein schaffen, solange sie derart in Alarmbereitschaft sind.\n\nEs muss doch einen Weg geben...\n\nEs ist nur noch eine Frage der Zeit, bis Schnottz' Leute den Obelisken aktivieren, und ich muss diese Schriftrollen erforschen, die Ihr gefunden habt. Ihr müsst diese Situation ohne mich lösen.\n\nSullah hat einige Verbindungen in dieser Gegend. Vielleicht weiß er einen Weg, wie wir hinein gelangen könnten.", progress = nil, completion = "Wisst Ihr, ich glaube, ich habe genau das Richtige für Euch!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28364] = {title = "Der Schlüssel des Häuptlings", objective = "Besorgt Drizles Schlüssel von Häuptling Blutmagen.", description = "Schnief... Es tut mir so leid! Ich wollte nicht, dass sie mich erwischen! Als sie mich gefangen nahmen, legten sie mir diese Kette an und ließen mich hier zurück. Ich kann mich nicht bewegen, meine Beine schlafen ein und ich habe Hunger!\n\nDer Häuptling besitzt den Schlüssel... Häuptling Blutmagen nannten die anderen ihn. Er befindet sich am nördlichen Ende des Lagers.\n\nAber beeilt Euch! Bitte! Lasst mich hier nicht zurück!", progress = "Habt Ihr den Schlüssel?", completion = "Oh danke, ich danke Euch! Ich werde hier sofort verschwinden!\n\nFalls Euch Ferli geschickt hat, sagt ihr bitte nicht, dass ich geweint habe!!", rewards = "Gamaschen der UnruhestiftungWeste des SchluchzensBlutmagens GürtelDer folgende Zauber wird auf euch gewirkt:\n\nDrizle flieht\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28365] = {title = "Drizle sicher", objective = "Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28366] = {title = "Bären entwaffnen", objective = "Sammelt 7 Waffen der Totenfelle im Revier der Teufelspfoten.", description = "Wir sollten tun, was wir können, um mein Volk vor dem Stamm der Totenwaldfelle zu beschützen, ohne gleich jeden einzelnen von ihnen zu töten. Wir haben bereits früher schon Schritte in diese Richtung unternommen. Wenn Ihr Euch also den Furbolgs der Holzschlundfeste beweisen wollt, schlage ich vor, dass Ihr dasselbe tut.\n\nHaltet nach Waffenstapeln Ausschau, die im Revier der Teufelspfoten im Südwesten gelagert werden. Nehmt so viele an Euch, wie Ihr könnt. Vielleicht können wir dem Blutvergießen ein Ende setzen, wenn wir den Stamm der Totenwaldfelle jetzt entwaffnen.", progress = "Habt Ihr die Waffen?", completion = "Ich danke Euch, &lt;Volk&gt;. Euer Handeln bringt Euch dem Ziel näher, Euch als wahrer Verbündeter der Holzschlundfeste zu beweisen.", rewards = "HolzschlundarmschienenHolzschlundgamaschenHolzschlundstiefelHolzschlundbrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28367] = {title = "Tuch der Schöpfer", objective = "Sabotiert 7 von Schnottz' Pulverfässern.", description = "Es ist schön, Freunde zu haben, <Klasse>! Auch wenn Freundlichkeit unsere einzige Belohnung ist, können wir mitunter auch greifbarere Vorteile erlangen.\n\nEin paar Freunde von mir haben kürzlich eine Lieferung von Schnottz' Plunder abgefangen und etwas gefunden, das uns gute Dienste leisten könnte.\n\nEs handelt sich dabei um Titanentechnologie, die den Träger fast unsichtbar macht. Wenn Ihr sie im feindlichen Lager benutzt, könnt Ihr vielleicht ihren Sprengstoff neu verdrahten und ihre Machenschaften hier ins Chaos stürzen.\n\nDie Wirkdauer dieser Technologie ist begrenzt, also begebt Euch nicht zu tief in Gefahr!", progress = nil, completion = "Hah!\n\nIch konnte es von hier aus hören! Wie gerne hätte ich es mit eigenen Augen gesehen!", rewards = "Wiederentdeckte DeltaläuferPulverfassarmschienenGamaschen der Vir'naalIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28368] = {title = "Flammenhölle", objective = "Tötet Grolvitar den Ewigbrennenden.", description = "Verdammich, Partner! Diese Ventile habt Ihr aber mal so richtig abgeschaltet.\n\nLeider hatten wir einen kritischen Durchbruch in unserem vermaledeiten Zentralbrennerregulator. Frau Darla hat so viele Arbeiter geschickt, wie sie entbehren kann, um ihn zu versiegeln, aber diese Flammen haben ihren ganz eigenen Kopf.\n\nUnd das mein' ich wörtlich! Die hüpfen durch die Gegend und schnappen sich jeden, der ihnen zu nahe kommt! Darla sagt, wenn Ihr aus der Höhle kommen und diesen Elementar vernichten könntet, hätte sie einen schönen Preis für Euch auf Lager!", progress = nil, completion = "Nun, mein gesamtes Vorhaben hier ist fast den Bach runter gegangen. Aber Ihr wart meine Rettung in letzter Sekunde, &lt;Name&gt;.\n\nEs hätte schlimmer sein können! Ich muss den Hut vor Euch ziehen.", rewards = "Stulpen der rohen KraftImmerbrennender UmhangAuf Euch wartet eine dieser Belohnungen:\n\nSchürfraupenband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28369] = {title = "Meine Schwester Fanny", objective = "Sprecht mit Fanny Donnermar in Donnermar im Schattenhochland.", description = "Bevor Ihr geht solltet Ihr in der Gaststätte hinter mir vorbeischauen. Meine Schwester Fanny hält sich dort auf.\n\nÜberall aus den verbrannten Wildhammersiedlungen um uns herum strömen Flüchtlinge nach Donnermar. Ich habe Fanny beauftragt, sich um sie zu kümmern. Sie ist hart im Nehmen. Aber dennoch könnte sie Eure Hilfe sicher gut brauchen.", progress = nil, completion = "Mein Bruder schickt Euch? Gut! Ich kann einen &lt;Klasse&gt; wie Euch gut brauchen. Könnt Ihr Euch im Kampf behaupten?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28370] = {title = "Irrwischentführung", objective = "Benutzt Darlas Irrwischmagnet, um 5 Nachtlaubirrwische zu sammeln.", description = "Könnt Ihr glauben, dass diese Worgen hier Irrwische haben? Die Nachtelfen haben ihnen all diesen Druidenkram beigebracht. Jetzt haben sie auch ihre eigenen kleinen Irrwische, die ihnen ihr Baumaterial bringen, ohne ihre kostbaren Bäume zu beschädigen.\n\nWenn wir auch solche Schätzchen hätten, könnten wir noch mehr Holz aus jedem Baum in unserem Lager herausholen. Kostenloses Material, kostenloser Profit! Daher habe ich an dieser Einfangvorrichtung hier gearbeitet.\n\nGeht zur Nachtlaublichtung und stehlt uns ein paar Irrwische. Zielt einfach auf sie und drückt die Taste.", progress = nil, completion = "Hübsche kleine Dinger, oder? Ich frage mich, ob wir vielleicht herausfinden könnten, wie man mehr davon macht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28372] = {title = "Zurück zum Geschäft", objective = "Fliegt zur Eisenwaldlichtung und sprecht mit Darla Schürfraupe.", description = "Dieses ganze \"Wir sind so tolle, glückliche Freunde\"-Getue ist super, oder? Alle arbeiten zusammen, um den Wald zu heilen. Aber was passiert mit dem Wald, wenn er geheilt ist? Steht er dann einfach nur so rum?\n\nWir brauchen dieses Holz. Die Horde braucht es. Ich habe Befehle, so viele treue Soldaten der Horde wie möglich zur Eisenwaldlichtung im Norden zu schicken - und ich bin mir sicher, dass Ihr besonders treu seid.\n\nIch habe Euch beim Flugmeister bereits einen kostenlosen Hippogryphenritt dorthin organisiert. Sprecht mit Darla Schürfraupe, sobald Ihr gelandet seid.", progress = nil, completion = "Fez hat Euch also geschickt, hm? Dann taugt er also doch zu etwas.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28373] = {title = "Die Holzschlundfeste", objective = "Sprecht mit Nafien bei der Holzschlundfeste im Teufelswald. Die Holzschlundfeste liegt im Osten, hinter dem Revier der Teufelspfoten.", description = "Es ist vielleicht ein Schuss ins Blaue, aber fragen kann ja nicht schaden.\n\nWährend ich mich um die Verstrahlung und diesen ganzen anderen lächerlichen Kram kümmere, der hier passiert ist, müsst Ihr für mich mit ein paar Bären sprechen. Die Furbolgs der Holzschundfeste kontrollieren die Wälder im Nordosten und mögen uns nicht besonders.\n\nIch brauche einfach jemanden, der ihnen klar macht, dass die Horde gar nicht so schlimm ist. Geht nach Nordosten zur Holzschlundfeste und fragt den Furbolg, den Ihr an ihrem Eingang finden werdet, ob wir ihnen einen Gefallen tun können. Macht aber einen großen Bogen um das Revier der Teufelspfoten!", progress = nil, completion = "Wir Furbolgs sind keine Narren, &lt;Name&gt;. Wir werden die Tore der Holzschlundfeste nicht einfach so öffnen, nur weil man uns darum bittet.\n\nJedoch sind auch wir dringend auf Hilfe angewiesen. Wenn Ihr uns helft, werdet Ihr unsere Gunst erlangen und Ihr könnt sie passieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28374] = {title = "Unkraut jäten", objective = "Reißt 7 Peitscher von Wisperwind heraus, um sie auf Verderbnis zu prüfen.", description = "An einem Ort wie diesem kann sogar etwas so Einfaches wie Blumen pflanzen und Unkraut jäten zu einer Aufgabe für echte Helden werden.\n\nDie Orchideenpeitscher, die an allen Ecken des Hains wachsen, sind ein Zeichen für seine Heilung. Jedoch sind sie nicht makellos. Einige von ihnen verfallen hin und wieder der dämonischen Verderbnis.\n\nNach meiner Erfahrung überprüft man das am besten, indem man sie ausreißt. Wenn sie normal sind, wandern sie einfach ein wenig in der Gegend herum und verwurzeln sich dann wieder. Wenn nicht, dann... Nun, macht Euch lieber auf einen Kampf gefasst.", progress = "Es wäre mir wirklich eine große Hilfe, wenn Ihr die Peitscher untersuchen würdet.", completion = "Es ist harte Arbeit, aber wenn man sie zu großen, starken Pflanzen heranwachsen sieht, haben sich alle Mühen gelohnt.\n\nNatürlich nur, wenn sie nicht voller dämonischer Dornen sind!", rewards = "Geblümte PantalonsPurhainschiftungUnkrautjäterarmschienenDornenabwehrende SchienbeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28375] = {title = "Der Weg ins Fegefeuer", objective = "Begleitet Orkus den Königsmörder auf die Fegefeuerinsel.", description = "Die Zeit der Rache ist gekommen, <Name>. Dank Euch kann Kasha wieder fliegen. Sie wird uns zur Fegefeuerinsel bringen, damit wir uns dem General der Sturmlanzenzwerge Vanndar Sturmlanze und seinem Hauptmann Balinda Steinbruch in den Weg stellen können. BEIDE werden für ihre Taten bezahlen.\n\nSeid Ihr bereit? Orkus kann das nicht alleine tun.", progress = nil, completion = "Dieser Ort ist düster... unheilsschwanger. Er stinkt nach Pisse und Fell. Hier gibt es ganz sicher Worgen und sehr wahrscheinlich auch Zwerge.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28376] = {title = "Myzerians Kopf", objective = "Bringt Myzerians Kopf zu Sullah bei Sullahs Fahrendem Zirkus.", description = "Ihr haltet jetzt den Kopf eines der berüchtigtsten schwarzen Drachen Todesschwinges in Händen.\n\nViele in Azeroth würden sicher einen hohen Preis für solch ein Artefakt bezahlen, aber etwas sagt Euch, dass er in einem Museum ausgestellt werden sollte, damit alle ihn sehen und sich erinnern können.\n\nHarrison Jones hat dafür bestimmt die richtigen Verbindungen.\n\nSullah wäre sicher mehr als bereit, ihm den Kopf zu bringen.", progress = "Ihr habt diesen Drachen erlegt?!\n\nBeeindruckend!", completion = "Eine reife Leistung, &lt;Name&gt;.\n\nIch werde ihn Harrison geben, sobald seine Expedition hier abgeschlossen ist.", rewards = "Ihr bekommt:\n\nInfernorubinHeliodorOzeansaphir"}
MultiLanguageQuestData['de'][28377] = {title = "Rettung auf Stopfwampes Anhöhe", objective = "Sucht nach Colin Donnermar auf Stopfwampes Anhöhe im Schattenhochland.", description = "Wenn man vom Teufel im blauen Kleid redet. Fanny hat sich doch tatsächlich von Ogern entführen lassen!\n\nIch glaube nicht, dass die Donnermars alleine eine Rettungsaktion auf die Beine stellen können. Ich werde meine Greifenreiter versammeln und ihnen ein wenig Unterstützung aus der Luft bieten.\n\n<Name>, ich bin sicher, dass sie jemand wie Euch dort unten gut brauchen können. Schnappt Euch Eure Ausrüstung und sucht nach Colin Donnermar im Lager von Stopfwampes Ogern. Es liegt südwestlich von hier, unterhalb der Klippen. Beeilt Euch!", progress = nil, completion = "Schön, dass Ihr erneut an meiner Seite kämpft, &lt;Name&gt;.\n\nUnd die Feuerbärte sind auch da! Sie sorgen sicher für Ablenkung, während meine Jungs und ich hier die Schwerstarbeit verrichten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28378] = {title = "Findet Fanny", objective = "Sucht und rettet Fanny Donnermar.", description = "Wir nehmen dieses Lager Stein für Stein auseinander, <Name>, aber immer noch keine Spur von Fanny. Vielleicht könnt Ihr sie finden.\n\nDie Höhle hinter mir im Nordwesten haben wir noch nicht überprüft. Schaut, ob Ihr Fanny in der Höhle finden könnt!", progress = nil, completion = "Fanny ist in Sicherheit! Feuerbart war also mit Euch da drin? Wie schön, dass er endlich seinen Beitrag leistet.\n\nWartet, warum schaut Ihr mich so an, &lt;Name&gt;? Wisst Ihr etwas, das ich nicht weiß?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28379] = {title = "Ogergekloppe", objective = "Tötet 10 von Stopfwampes Oger (entweder Stopfwampes Trommler, Stopfwampes Schleuderer oder Stopfwampes Schläger).", description = "Stopfwampes Oger! Ich würde ja sagen, sie sind dumm wie ein Sack Hämmer, aber das wäre den Hämmern gegenüber nicht gerecht.\n\nWir haben ihre Beutezüge jahrelang abgewehrt, aber wenn sie frech genug sind, einen von uns zu entführen, dann müssen wir ihnen eine Lektion erteilen.\n\nHelft uns, ein paar von Stopfwampes Ogern eine ordentliche Tracht Prügel zu verabreichen! Tötet ihre Trommler, Schleuderer oder Schläger hier draußen oder noch besser in der Höhle. Das wird ihnen eine Lehre sein!", progress = nil, completion = "Hah! Meine Männer könnten echt noch etwas lernen, wenn sie Euch bei der Arbeit zusehen. Gut gemacht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28380] = {title = "Pikwik in Gefahr", objective = "Sprecht mit Großknecht Pikwik in der Eisenwaldhöhle.", description = "Was zum Teufel ist hier los? Großknecht Pikwik hätte die Ventile schon längst abgeschaltet haben sollen.\n\nWenn das Zentralventil ausgeschaltet ist, können wir diese Lecks den ganzen Tag lang abdichten und zögern doch nur eine gewaltige Explosion heraus.\n\nHört mal, wenn Euch was an Geld liegt oder Eurem Leben oder vielleicht sogar an beiden, dann solltet Ihr lieber nach Süden in die Eisenwaldhöhle gehen und nach Großknecht Pikwik suchen.", progress = nil, completion = "Es ist eine Katastrophe! Die Pumpe ist hinüber und all meine Männer da drin sind dahin...\n\nIhr müsst mir helfen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28381] = {title = "Die Höhlenmutter", objective = "Fliegt zur Nachtlaublichtung und sprecht mit Höhlenmutter Ulrica.", description = "Nur einen Krähenflug entfernt im Norden verwüsten die Goblins den Wald. Sie roden jeden einzelnen Baum, um Kraftstoff für die Kriegsmaschinen der Horde zu gewinnen und sich selbst ein goldenen Näschen zu verdienen. Der da wickelt die Druiden hier mit seinen schmeichelnden Worten und geschickten Lügen ein, damit sie nicht hinsehen. Sie haben Angst, die angespannte Neutralität hier zu gefährden.\n\nDie Worgen der Nachtlaublichtung haben genug davon. Schließt Euch uns an! Der Hippogryphenmeister bringt Euch direkt in unser Zuhause. Höhlenmutter Ulrica heißt <jeden/jede:r> <Volk> willkommen, <der/die:r> kampfbereit ist.", progress = nil, completion = "Willkommen im Zuhause meines Rudels, &lt;Klasse&gt;. Bereitet Euch auf einen Krieg vor.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28382] = {title = "Der Feind an unseren Wurzeln", objective = "Tötet 8 Eisenwaldhacker.", description = "Die Goblins sitzen uns schon im Nacken!\n\nWir haben mit aller Kraft versucht, die Goblins aufzufordern, die Eisenwaldlichtung zu verlassen, bevor wir Gewalt anwenden. Doch sie wollten unseren Warnungen kein Gehör schenken, also haben wir zugeschlagen. Anstatt den Wald jetzt zu verschonen, geben sie lieber ihr Leben für ihre Gier.\n\nBald werden Sie das volle Ausmaß unseres Zorns kennenlernen! Die Schlacht tobt direkt hinter unserem nördlichen Tor. Schließt Euch unserem glorreichen Rudel an und tötet alle Goblins, die es wagen, uns gegenüberzutreten!", progress = nil, completion = "Möge ihr Blut unseren Baum nähren. Ihr kämpft gut, &lt;Name&gt;.", rewards = "Schiftung des RudelläufersHelm der tauben OhrenKlauenbewehrter AstBlutwasserschildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28383] = {title = "Irrwische der Wälder", objective = "Benutzt die Flinkwindgerte, um 5 Nachtlaubirrwische zu sammeln.", description = "Ich bemühe mich zusammen mit der Höhlenmutter schon seit langem, die Lehren des Cenarius und die Wege der Natur zu verbreiten. Sie hat sich mein Vertrauen verdient, und im Gegenzug durfte ich ihren Schülern die Geister des Waldes vorstellen. Die Gesellschaft der Irrwische ist eine große Ehre und ein nützlicher Segen.\n\nDoch nun ist die Goblinplage über uns hereingebrochen. Sie versuchen, die Irrwische für ihre üblen Zwecke zu stehlen. Bitte, verhindert diese Lästerung!\n\nRuft die Irrwische aus den westlichen Wäldern mit diesem gesegneten Zweig hierher und beschützt sie.", progress = nil, completion = "Vielen Dank, &lt;Name&gt;. Jetzt kann die Horde diese armen Geister nicht mehr besudeln, um sie für ihre grausamen Taten einzusetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28384] = {title = "Auf die Lichtung", objective = "Sprecht mit Alton Redding in der Nähe der Eisenwaldhöhle", description = "Die Eisenwaldlichtung muss dem Erdboden gleichgemacht werden. Wir können uns kein Mitleid leisten, wenn wir die Goblins daran hindern wollen, ihre Zerstörungswut auf den gesamten Wald auszubreiten.\n\nAlton Redding, mein vertrauenswürdigster Beschützer, hat bereits ein Großteil des Rudels hinter die feindlichen Linien geführt, um zuzuschlagen, solange sie hier abgelenkt sind. Sucht im Westen nach ihm, in der Nähe der Eisenwaldhöhle.", progress = nil, completion = "Willkommen im Rudel, &lt;Volk&gt;. Hoffentlich habt Ihr nichts dagegen, wenn es etwas unzivilisierter hergeht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28385] = {title = "Öl und Ironie", objective = "Sabotiert die Hauptkontrollpumpe in der Eisenwaldhöhle.", description = "Ich habe vor, die Gier und die Verschmutzung der Goblins gegen sie selbst einzusetzen. Ihre weitere Ausbreitung zu verhindern rechtfertigt eine weitere Ausnutzung des Landes, das sie ohnehin schon gerodet haben.\n\nTief in der Eisenwaldhöhle, direkt unter uns, verlaufen unzählige Rohre, die Öl über die gesamte Lichtung durch den Boden pumpen. Diese Rohre sind an eine Hauptkontrollpumpe tief in der Höhle angeschlossen.\n\nBetretet die Höhle und sabotiert die Pumpe. Das daraus entstehende Chaos wird uns die Gelegenheit für unseren letzten Schlag geben.", progress = nil, completion = "Ihr legt ein paar Schalter an der Pumpe um und dreht den langen Hebel ganz nach rechts. Die Wände um Euch herum erzittern und rumpeln.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28386] = {title = "Ausgeliehene Bomben", objective = "Sammelt 8 Stück Eisenwaldsprengstoff aus der Eisenwaldhöhle.", description = "Die Arbeiter in der Eisenwaldhöhle wurden bereits vertrieben. Etwas anderes hat die Höhle eingenommen.\n\nDas kommt uns gelegen. Ich habe gesehen, wie ein paar von ihnen auf der Flucht Sprengstoff fallen ließen... Sprengstoff, den wir für den nächsten Teil unseres Plans gut brauchen können.\n\nBegebt Euch in die Höhle und bergt alle zurückgelassenen Bomben, die Ihr finden könnt. Wenn Ihr damit und mit der Pumpe fertig seid, werden wir unseren letzten Angriff starten.", progress = "Hatte ich Recht? Wie viele habt Ihr gefunden?", completion = "Perfekt. Ich habe den Rest des Rudels weiteren Sprengstoff aus dem Lager sammeln lassen. Zusammen mit diesem hier haben wir genug, um die Sache ins Rollen zu bringen, sobald das Öl fließt.", rewards = "ÖlfußpantoffelnAltons GamaschenBrustplatte des ProtestsEisenwaldumhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28387] = {title = "Feuerfontäne", objective = "Benutzt den gestohlenen Eisenwaldsprengstoff, um 7 Ölgeysire auf der Eisenwaldlichtung in Brand zu setzen.", description = "Durch Eure Sabotage an der Pumpe sind die Rohre im gesamten Lager gebrochen. Die Goblins sind wegen der Geysire in Panik. Und es wird noch schlimmer!\n\nNehmt den gesammelten Sprengstoff und setzt die Geysire in Brand. Wir werden dem Lager so viel Schaden wie möglich zufügen und sie daran hindern, dieses Öl als Schreddertreibstoff zu verwenden... oder schlimmer noch, als Treibstoff für Kriegsschiffe der Horde.", progress = nil, completion = "Schaut nur, wie sie rennen... Die wenigen Überlebenden meine ich natürlich. Herrlich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28388] = {title = "Blutiger Lohn", objective = "Tötet 7 panische Arbeiter.", description = "Erbärmliche kleine Feiglinge... Schaut nur, wie sie in Panik fliehen!\n\nLasst Euch davon nicht beirren, <Name>. Sobald sie wieder bei Verstand sind, werden diese Goblins jede freie Sekunde nutzen, um diesen Wald zu Kleinholz zu verarbeiten und die Ergebnisse der Horde zur Unterstützung ihres Krieges schicken.\n\nGebt ihnen keine Gelegenheit dazu. Tötet die Arbeiter auf der Eisenwaldlichtung. Habt kein Erbarmen... Zeigt ihnen, dass ihre Gier einen hohen Preis verlangt!", progress = nil, completion = "Sie haben es verdient. Jeder einzelne. Hoffen wir nur, dass ihre Anführer den Rest dieser gierigen Plünderer woanders hin schicken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28389] = {title = "Meldet Euch bei der Höhlenmutter", objective = "Sprecht mit Höhlenmutter Ulrica auf der Nachtlaublichtung.", description = "Jetzt, da die Goblins verstreut sind und ihre Ausrüstung zerstört ist, werden sie entweder die Botschaft verstehen und abziehen oder leichte Beute sein, wenn sie bleiben. Wir haben gewonnen.\n\nIhr habt so wild gekämpft, wie jedes Mitglied dieses Rudels, <Name>. Kehrt zur Höhlenmutter zurück und berichtet ihr von unserem Erfolg. Ich halte hier weiter Wache.", progress = nil, completion = "Lasst die Goblins und die gesamte Horde wissen, dass wir nicht zulassen, dass sie Friedensangebote und Ort der Zuflucht missbrauchen... vor allem nicht in unserem neuen Zuhause.\n\nIch bin dankbar, dass mein Volk solch mutige Verbündete wie Euch gefunden hat, &lt;Name&gt;. Diese Belohnung ist ein Zeichen für das Band zu unserem Rudel. Ihr seid hier immer willkommen.", rewards = "Fäuste des RudelsUmhang der HöhlenmutterAuf Euch wartet eine dieser Belohnungen:\n\nZeichen der Bindung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28390] = {title = "Glop, Sohn des Glop", objective = "Sprecht mit Erdheilerin Norsala und tötet dann Fungumant Glop.", description = "Glop hatte einen Sohn. In seiner unermesslichen Selbstherrlichkeit nannte er ihn Glop. Und so wird die Blutlinie der Fungumanten fortgeführt.\n\nIch möchte, dass Ihr diesen neuen Fungumanten tötet. Eure Schamanenverbündete ist bereits zurückgekehrt und erwartet Euch in seiner Höhle südwestlich der Wacht Verlok.", progress = nil, completion = "Eines Tages können wir diese Steintroggs vielleicht schneller töten, als sie sich fortpflanzen, und damit die Blutlinie der Fungumanten für immer ausrotten.\n\nAlles zu seiner Zeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28391] = {title = "Die rastlose Brut", objective = "Besiegt Aeosera.", description = "Aeosera ist rastlos und stur. Sie spottet über unsere Herrschaft und muss ständig an ihre Position erinnert werden.\n\nIch habe noch immer den Schlaghammer, den Ihr für mich besorgt habt. Kehrt zum westlichen Rand des Bleichen Horts zurück und schlagt auf den Resonanzkristall.\n\nIch werde Euch dort treffen und Euch alle Hilfe zur Verfügung stellen, die ich Euch bieten kann. Verweist sie in ihre Schranken, <Klasse>.", progress = "Und so setzt sich der Kreislauf der Steindrachen fort. Wilde Geister in stoischer Gestalt.", completion = "Ihr seid ganz schön geschickt darin, den Willen des Drachen zu brechen, &lt;Volk&gt;. Ich wäre ja neidisch auf Eure Gewandtheit, wenn Eure Hülle nicht so zerbrechlich wäre.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28392] = {title = "Die Furbolgs der Holzschlundfeste", objective = "Sprecht mit Nafien am Eingang zur Holzschlundfeste.", description = "Die Furbolgs der Holzschlundfeste sind der letzte bekannte Stamm unverderbter Furbolgs. Sie drängen sich am Rand dieses Landes zusammen und verteidigen ihre Heimat in der Holzschlundfeste mit aller Macht.\n\nObwohl sie stolze Wesen sind, brauchen sie dennoch Hilfe. Falls Ihr sie unterstützen wollt, folgt der Straße von hier aus nach Norden und sucht sie am Eingang zur Holzschlundfeste auf.", progress = nil, completion = "Die Druiden der Nachtlaublichtung haben uns schon früher geholfen. Wir sind immer noch nicht an die \"freundlichen\" Worgen in diesen Wäldern gewöhnt, doch auch unser Volk kennt die Sorgen von Flüchen und Verderbnis...\n\nSorgen, bei denen Ihr uns hoffentlich helfen könnt, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28393] = {title = "Ein gefährliches Bündnis", objective = "Tötet 6 Brandwachenzerstörer und beschafft Euch die Angriffspläne des Generals von General Zornesschmied in der Westgarnison der Schwarzfelstiefen.", description = "Die letzten Berichte des SI:7 über die Machenschaften des Schattenhammers und der Dunkeleisenzwerge machen mir Sorgen, <Name>. Es gibt Beweise, dass sie im Schwarzfels einen gemeinsamen Angriff planen. Einer solchen geballten Macht zu widerstehen wird uns schwer fallen, aber wenn wir handeln, bevor sie zuschlagen können, können wir den Angriff vielleicht abwenden.\n\nIhr müsst in die Schwarzfelstiefen reisen und die Angriffspläne des Schattenhammers von General Zornesschmied in der Westgarnison beschaffen. Zögert nicht, die Elementare auszuschalten, die seine Streitmächte unterstützen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Gesichtsschutz der KroneKopfschutz der KroneIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28394] = {title = "Die Geschöpfe des Golemlords", objective = "Beschafft 5 Elementarmodule von den Golems in der Manufaktur der Schwarzfelstiefen und stehlt die Baupläne für einen Elementargolem.", description = "Die neusten Informationen des SI:7 über die Schwarzfelstiefen sind beunruhigend, <Name>. Wie es scheint arbeitet der Schattenhammer mit dem Ingenieur der Dunkeleisenzwerge Argelmach zusammen, um durch Elementare beseelte Kriegsgolems zu erschaffen. Diese Golems könnten sich als vernichtende Waffe gegen uns herausstellen.\n\nIhr müsst das verhindern, <Name>. Findet die Manufaktur in den Schwarzfelstiefen, besorgt Euch die Blaupausen, mit denen er diese Golems erschafft, und beschafft die Module, die ihnen Leben einhauchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHelm der Krone"}
MultiLanguageQuestData['de'][28395] = {title = "Federn für Nafien", objective = "Zwar habt Ihr Euch mir als würdig erwiesen, aber meine argwöhnischen Stammesbrüder werden Euch bestimmt noch nicht so ohne Weiteres akzeptieren. In dieser Hinsicht kann ich Euch weiterhin helfen.\n\nManche Furbolgs der Totenwaldfelle schmücken sich mit speziellen Federn, die als Beweis dafür herhalten könnten, dass Ihr ihre Reihen gelichtet habt. Bringt mir eine Feder von jedem Kopfschmuck, den Ihr bekommen könnt; jeweils fünf von ihnen erkauft Euch ein Stück Anerkennung bei der Holzschlundfeste.", description = nil, progress = "Zwar habt Ihr Euch mir als würdig erwiesen, aber meine argwöhnischen Stammesbrüder werden Euch bestimmt noch nicht so ohne Weiteres akzeptieren. In dieser Hinsicht kann ich Euch weiterhin helfen.\n\nManche Furbolgs der Totenwaldfelle schmücken sich mit speziellen Federn, die als Beweis dafür herhalten könnten, dass Ihr ihre Reihen gelichtet habt. Bringt mir eine Feder von jedem Kopfschmuck, den Ihr bekommen könnt; jeweils fünf von ihnen erkauft Euch ein Stück Anerkennung bei der Holzschlundfeste.", completion = "gut gemacht, &lt;Name&gt;! Ich werde mein Volk von Euren Taten in Kenntnis setzen.\n\nIhr könnt alle Federn, die Ihr findet, zu mir bringen. Ich werde sie weiterhin so lange wir nötig annehmen.", rewards = nil}
MultiLanguageQuestData['de'][28396] = {title = "Federn für Grazle", objective = "Zwar habt Ihr Euch mir als würdig erwiesen, aber meine argwöhnischen Stammesbrüder werden Euch bestimmt noch nicht so ohne Weiteres akzeptieren. In dieser Hinsicht kann ich Euch weiterhin helfen.\n\nManche Furbolgs der Totenwaldfelle schmücken sich mit speziellen Federn, die als Beweis dafür herhalten könnten, dass Ihr ihre Reihen gelichtet habt. Bringt mir eine Feder von jedem Kopfschmuck, den Ihr bekommen könnt; jeweils fünf von ihnen erkauft Euch ein Stück Anerkennung bei der Holzschlundfeste.", description = nil, progress = "Zwar habt Ihr Euch mir als würdig erwiesen, aber meine argwöhnischen Stammesbrüder werden Euch bestimmt noch nicht so ohne Weiteres akzeptieren. In dieser Hinsicht kann ich Euch weiterhin helfen.\n\nManche Furbolgs der Totenwaldfelle schmücken sich mit speziellen Federn, die als Beweis dafür herhalten könnten, dass Ihr ihre Reihen gelichtet habt. Bringt mir eine Feder von jedem Kopfschmuck, den Ihr bekommen könnt; jeweils fünf von ihnen erkauft Euch ein Stück Anerkennung bei der Holzschlundfeste.", completion = "gut gemacht, &lt;Name&gt;! Ich werde mein Volk von Euren Taten in Kenntnis setzen.\n\nIhr könnt alle Federn, die Ihr findet, zu mir bringen. Ich werde sie weiterhin so lange wir nötig annehmen.", rewards = nil}
MultiLanguageQuestData['de'][28397] = {title = "Damit rechnen sie nie", objective = "Tötet 8 Zwerge der Sturmlanzen und 8 Blutfangwachen auf der Fegefeuerinsel.", description = "Sie haben einen Fehler gemacht, als sie mich nicht getötet haben, solange sie die Gelegenheit hatten. Vielleicht dachten sie, Orkus würde ertrinken. HAH! Jetzt werden sie für ihre Nachlässigkeit bezahlen.\n\nWir beide werden diese Insel in Stücke reißen, <Name>. Damit rechnen sie nie! Sobald all ihre Soldaten tot sind, werden wir ihre Anführer stellen. Haltet nach den Angriffsplänen Ausschau. Wenn wir die Pläne in die Finger kriegen, werden wir ihrer ganzen Invasion ein Ende machen können!\n\nLos, <Name>!", progress = "Wir werden sie alle töten!", completion = "Schaut Euch nur dieses Massaker an, &lt;Name&gt;. Wir beide sind ein tolles Team!\n\nJetzt müssen wir ihre Pläne finden und ihre Anführer erledigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28398] = {title = "Der Zauberfoliant des Pyromanten", objective = "Tötet 6 Zwielichtabgesandte und besorgt Weisenkorns Zauberfoliant von Pyromant Weisenkorn am Schrein von Thaurissan in den Schwarzfelstiefen.", description = "Tief im Schwarzfels wächst die Macht der Dunkeleisenzwerge und ihrer Schattenhammerverbündeten. Pyromant Weisenkorn, ein hoch angesehener Magier, spielt bei der Anführung der Streitmächte des Schattenhammers dort eine große Rolle. Wenn wir seinen Zauberfolianten in die Finger bekommen, könnte ich mir vielleicht Gegenzauber oder andere Mittel ausdenken,mit denen wir ihre Macht einschränken können.\n\nIhr müsst in die Schwarzfelstiefen hinabsteigen, den Schrein von Thaurissan ausfindig machen und den Zauberfolianten besorgen. Zeigt Weisenkorn und seinen Zwielichtdienern keine Gnade!", progress = "Konntet Ihr den Zauberfolianten des Pyromanten besorgen?", completion = "&lt;Der Magierlehrer blätter rasch durch den Folianten.&gt;\n\nIch habe jetzt schon mindestens ein Dutzend Zauber gesehen, von deren Existenz ich bisher nichts wusste. Das hier wird mir gute Dienste leisten, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nKapuze des königlichen Zauberers"}
MultiLanguageQuestData['de'][28399] = {title = "Steine der Bindung", objective = "Besorgt 6 Steine der Elementarbindung aus den Schwarzfelstiefen. Ihr findet die Steine in der Schattenschmiede, dem Domizil, am Schrein von Thaurissan, in der Ostgarnison und in der Westgarnison.", description = "Ich weiß aus sicherer Quelle, dass der SI:7 sich Sorgen wegen einer Zusammenarbeit zwischen dem Schattenhammer und den Dunkeleisenzwerge in den Schwarzfelstiefen macht. Wir können diese Information als Anlass nutzen, um zu handeln, der Allianz unseren Wert zu beweisen und gleichzeitig etwas für uns selbst zu erreichen.\n\nDer Bericht besagt, dass die Anhänger des Schattenhammers mehrere Steine der Elementarbindung in der Schattenschmiede, dem Domizil, dem Schrein von Thaurissan, der Westgarnison und der Ostgarnison aufgestellt haben. Findet und holt Euch diese Steine!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHörner der gerechtfertigten Sünden"}
MultiLanguageQuestData['de'][28400] = {title = "Helden der Horde!", objective = "Stehlt die Schlachtpläne der Allianz und werdet Helden der Horde.", description = "Jetzt müssen wir ihre Schlachtpläne finden und ihre Anführer erledigen! Wenn wir Erfolg haben, gibt es da einen Obersten Kriegsfürsten der Orcs, der im Krieg im Silberwald gekämpft hat und nun in Tarrens Mühle stationiert ist, mitten im Herzen des Hügellands. Er wird uns beide dafür belobigen! Wir werden Helden der Horde sein, <Name>!\n\nVorwärts! Gemeinsam besiegen wir diesen Abschaum der Allianz!", progress = "<Oberster Kriegsfürst Cromush schaut finster drein.>", completion = "&lt;Oberster Kriegsfürst Cromush salutiert.&gt;\n\nEr wird als Held der Horde geehrt werden, so wie er es sich immer gewünscht hat. Was Ihr und Orkus getan habt wird Hunderte von Leben retten und sicherstellen, dass wir unsere Position im Hügelland nicht verlieren.", rewards = "Gürtel des HeldenHandschuhe des HeldenSchiftung des HeldenStiefel des HeldenDer folgende Zauber wird auf euch gewirkt:\n\nDespawn All Summons\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28401] = {title = "Sklaven des Feuerlords", objective = "Benutzt das Totem der Freiheit, um die Essenzen von 6 Brandwachen, Brandwachenzerstörern oder lodernden Brandwachen in den Schwarzfelstiefen zu befreien.", description = "In den Hallen der Schwarzfelstiefen versammeln der Schattenhammerkult und die Dunkeleisenzwerge ihre Streitkräfte. Ihre Legionen werden von Horden aus Feuerelementaren unterstützt, die der Feuerlord Ragnaros als Diener an sich gebunden hat.\n\nWenn wir die Elementare aus ihrem Bund befreien, können wir sowohl unsere Feinde schwächen als auch den Elementen Ehre erweisen. Nehmt dieses Totem und wirkt es auf die unterworfenen Brandwachen. Das wird ihre Geister befreien und ihren natürlichen Zustand wiederherstellen.", progress = nil, completion = "Ihr habt der Allianz und Eurer Berufung als &lt;Klasse&gt; einen großen Dienst erwiesen.", rewards = "Kopfbedeckung des ScharfsehersMaske des ScharfsehersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28402] = {title = "Schnottz und Wasser", objective = "Tötet 10 Elitesoldaten von Schnottz in der Kammer des Mondes.", description = "Ich bin fast fertig, <Name>.\n\nEure Rollen enthielten genügend Informationen, um ihre Verschlüsselungsmethode zu erkennen. Jetzt muss ich die Codes nur noch übersetzen.\n\nIhr müsst für mich die Kammer unter dem Obelisken des Mondes ausspähen. Wahrscheinlich halten sich dort unten ein paar von Schnottz' Truppen auf, die Eurer Explosion entkommen konnten.\n\nKümmert Euch um sie. Ich werde Euch dort treffen, wenn ich fertig bin.", progress = nil, completion = "In Ordnung, &lt;Name&gt;.\n\nIch glaube, jetzt ist alles bereit. Dann mal los!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28403] = {title = "Ungültige Daten", objective = "Begleitet Harrison Jones in der Kammer des Mondes.", description = "In dieser Kammer müsste es zwei Kommunikationsgeräte der Titanen geben.\n\nWenn meine Berechnungen korrekt sind, ist eines davon eine Todesfalle und das andere nimmt die Codes an und aktiviert den Obelisken.\n\nIch hoffe, ich habe alles richtig verstanden.\n\nGebt mir Bescheid, wenn Ihr bereit seid.", progress = nil, completion = "Gut, &lt;Name&gt;.\n\nIch glaube, ich kann das manuell erledigen, aber ich brauche dazu Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28404] = {title = "Ich mache das von Hand", objective = "Besiegt den titanischen Wächter.", description = "Ja, das kommt mir ziemlich bekannt vor.\n\nDank der Informationen, die Ihr für mich gesammelt habt, kann ich den Mechanismus bestimmt aktivieren. Ich muss mich jedoch eine Weile ganz genau konzentrieren können.\n\nSobald ich loslege wird dieses Titanenkonstrukt sicher versuchen, mich aufzuhalten.\n\nUnd genau da kommt Ihr ins Spiel.\n\nIch muss Euch sicher nicht daran erinnern, was auf dem Spiel steht. Schaltet diesen Wächter aus!", progress = nil, completion = "Das sollte genügen.\n\nBleibt zurück!", rewards = "Gürtelplatte des WächtertötersTitanische TreterStulpen von AhmtulDer folgende Zauber wird auf euch gewirkt:\n\nDo It By Hand Initialize\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28405] = {title = "Waffen der Dunkelheit", objective = "Sammelt 5 elementarerfüllte Waffen von den Zwergen der Zorneshämmer in den Schwarzfelstiefen und zerbrecht sie auf dem Schwarzen Amboss in der Schattenschmiede.", description = "In den Schwarzfelstiefen hausen schon lange unsere Feinde, aber jetzt hat der SI:7 uns informiert, dass die Dunkeleisenzwerge und der Schattenhammer verstärkt zusammenarbeiten. Mit dem Wissen des Kultes verstärken die Dunkeleisenzwerge ihre Waffen mit elementaren Kräften. Sie haben die Legion der Zorneshämmer mit diesen schrecklichen neuen Waffen ausgerüstet.\n\nIch möchte, dass Ihr in die Schwarzfelstiefen reist und den Zwergen der Zorneshämmer ihre Waffen abnehmt. Zerbrecht sie auf dem Schwarzen Amboss im Herzen der Schattenschmiede.", progress = nil, completion = "Dank Eurer Bemühungen werden diese Waffen niemals das Blut der Allianz vergießen. Ausgezeichnete Arbeit, &lt;Name&gt;.", rewards = "Helm des OrdensGesichtsschutz des OrdensKopfschutz des OrdensIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28406] = {title = "Die Armee der Dunkeleisenzwerge", objective = "Benutzt das schnell wirksame Gift, um 6 Getreiderationen in der Westgarnison oder Ostgarnison der Schwarzfelstiefen zu vergiften.", description = "So langsam werden die Dinge im Schwarzfels interessant, <Name>. Unsere Quellen berichten, dass die Dunkeleisenzwerge sich immer enger an den Schattenhammer binden und gemeinsam einen bedeutenden Angriff planen.\n\nIch habe die wichtigsten Anführer in Sturmwind über den Inhalt dieser Berichte informiert und möchte, dass Ihr uns dabei helft, dieser wachsenden Bedrohung durch die Dunkeleisenzwerge Herr zu werden.\n\nDie Rationen für die Armeen der Dunkeleisenzwerge werden größtenteils in der Ostgarnison und Westgarnison der Schwarzfelstiefen aufbewahrt. Nehmt dieses Gift und gebt es auf ihre Getreidevorräte.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSpezialgesichtsmaske von SI:7"}
MultiLanguageQuestData['de'][28407] = {title = "Die Junggesellin", objective = "Sprecht mit Fanny in Kirthafen im Schattenhochland.", description = "Feuerbart? Meine Schwester heiraten?! Ich schwöre Euch, die Welt ist verrückt geworden, <Name>!\n\nAber vielleicht hat Kurdran Recht. Eine nette, ganz normale Hochzeit würde alle auf andere Gedanken bringen... und Feuerbart ein wenig abkühlen. Es hat mir eigentlich ganz schön Spaß gemacht, hier mit ihm gegen die Oger zu kämpfen.\n\nAlso gut! Fanny hat das letzte Wort. Irgendetwas sagt mir, dass sie sich nicht gern binden lassen möchte.\n\nFliegt zurück nach Kirthafen und fragt sie, ob sie einverstanden ist. Ich werde unsere schmutzige Aufgabe mit den Ogern hier erledigen.", progress = nil, completion = "&lt;Fanny wirft verärgert die Arme in die Luft.&gt;\n\nIhr, Kurdran, Feuerbart und jetzt auch noch mein Bruder. Anscheinend ist bei allen das Hochzeitsfieber ausgebrochen!\n\nGut, dann heirate ich Keegan Feuerbart eben. Aber nur weil er stark und gutaussehend ist und einen Kiefer hat, der Steine zerbeißen kann, und einen Hintern so hart wie ein Amboss. Nicht aus politischen Gründen.\n\nAber wir werden Eure Hilfe brauchen. Wir haben eine Mordshochzeit auszurichten und nicht viel Zeit dafür.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28408] = {title = "Etwas Geballtes", objective = "Sammelt 12 makellose Eulenfedern.", description = "Traditionell tragen die Bräute der Wildhämmer weiß als Symbol ihrer Reinheit. Zusätzlich tragen sie eine Krone aus schwarzen Federn, um ihren geballten Mumm zu zeigen.\n\nAm besten zeigt man seinen Mumm mit Eulenfedern, und Fanny verdient nur das Beste. Im Hochland leben viele Waldeulen. Sie kreisen meist um die Bäume an den Klippen. Nehmt Euch ihre Federn.\n\nAm besten tötet ihr sie vorher.", progress = "Habt Ihr Fannys Federn?", completion = "Ah, Ihr arbeitet schnell. Eine geballte Ladung Federn für eine geballte Ladung Frau. Gut gemacht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28409] = {title = "Etwas Gebrautes", objective = "Sprecht mit Hammerhand auf der Straße östlich von Kirthafen und begleitet die Versorgungskarawane sicher in die Stadt.", description = "Eine Wildhammerhochzeit ohne standesgemäße Getränke wäre eine Beleidigung. Kurdran selbst hat ein paar Fässer des seltenen Donnerbräu Lagerbiers aus Hochstade angefordert, aber die Karawane konnte den Pass nicht überqueren.\n\nFolgt der Straße östlich von hier, die um die Südseite des Bergs Donnerschlag führt, und holt die Karawane ein. Sucht nach einem Kerl namens Hammerhand und helft ihm, das Gebräu über den Pass zu bringen!", progress = "Ist die Straße frei? Oder macht das Drachenmal wieder Ärger?", completion = "Ah, Russell der Barde schwärmt immer von Donnerbräu Lagerbier. Es hat sicher nicht den Kick eines guten Wildhammerbräus, aber er hört gar nicht auf von seinem \"Körper\" und den \"Geschmacksnuancen\" zu reden. Schätze, wir werden es herausfinden, was?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28410] = {title = "Etwas Gestohlenes", objective = "Sammelt einen Ballen feinen dunklen Stoffs.", description = "Für solch ein Ereignis will jeder natürlich besonders gut aussehen, aber feiner Zwirn ist im Hochland rar.\n\nSoweit ich weiß benutzen jedoch diese verdammten Goblins an der Küste feinste Seide, um die Ballons ihrer Zeppeline zu reparieren. Was für eine Verschwendung!\n\nFindet einen Zeppelin, der zwischen dem Hafen des Drachenmals und den Krazzwerken hin und her fliegt, und stibitzt ein wenig Seide aus dem Frachtraum in den unteren Decks.", progress = "Wie lief der Raubzug in den Lüften?", completion = "Oh, genau! Kilts für die Herren, Roben für die Brautjungfern.\n\nSagt den Damen bloß nicht, dass sie Kleider tragen, die für ein Luftschiff gefertigt wurden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28411] = {title = "Etwas Geschmortes", objective = "Sammelt 8 Scheiben frisches Wildbret und 5 Worgrippchen.", description = "Und schließlich brauchen wir noch ein Festmahl. Und bestimmt nicht solche modernen \"Häppchen\". Diese Menge will Fleisch und zwar viel davon.\n\nSammelt Wildbret von den Hochlandelchen und Hochlandrehen. Die Hochlandworgs sind auch ganz lecker. Bringt mir ein paar Rippchen. Wir werden Euch einen Schmaus auftischen, wie Ihr ihn in den ganzen Östlichen Königreichen noch nie gesehen habt, Freund.", progress = "Was gibt es Neues von der Nahrungsfront, <Name>?", completion = "Da schau mal einer an! Ihr biegt Euch ja richtig unter dem Gewicht des ganzen Fleischs. Dann schicke ich meine Leute lieber mal an die Töpfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28413] = {title = "Text und Musik von...", objective = "Sprecht mit Russell Brower und helft ihm, ein Lied zu schreiben.", description = "Ich habe in meinem Leben schon viele epische Melodien verfasst, <Name>, aber diese nahende Hochzeit verdient eine ganz besondere Ballade. Und das schnell!\n\nSoll ich eine Ode an die Liebe schreiben? Eine scherzhafte Melodei? Ein anzügliches Trinklied?\n\nIch könnte ein wenig Hilfe mit dem Text brauchen, wenn Ihr Lust habt, Euch als Schreiber zu versuchen.\n\nSprecht mit mir, dann schreiben wir zusammen ein Lied!", progress = "\"Text und Musik von Russell Brower, dem Barden, und <Name>, dem <Klasse>.\"\n\nKlingt fantastisch.", completion = "Ein echter Ohrwurm, so viel ist sicher.\n\nAber ist es auch ein Klassiker?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28414] = {title = "Drölfmeterschießen", objective = "Steigt in den Bilgewasserbukanier und schießt das Siegertor, indem Ihr die Fußbombe durch die beiden Schornsteine hinter dem gegnerischen Tor schießt.", description = "Jetzt liegt es an Euch, <Junge/Mädel>. Ihr habt die Dampfdruckhaie vernichtet, also müsst Ihr jetzt nur noch das Siegertor schießen.\n\n<Der Trainer beugt sich zu Euch hinüber und flüstert Euch ins Ohr.>\n\nNur unter uns... Ich finde, wir müssen jetzt aufs Ganze gehen. Ich möchte nicht, dass Ihr einfach nur ein Tor schießt... Ich möchte, dass Ihr so weit schießt, dass die Fußbombe zwischen den beiden Schornsteinen hinter dem Ziel hindurch fliegt!\n\nIch habe die Fußbombe ein wenig verändert, sodass sie die zusätzliche Leistung hat, die Ihr benötigt.\n\nUnd jetzt geht raus da und macht mich stolz!", progress = nil, completion = "Äh... Ihr habt es geschafft, Junge. Ihr habt es WIRKLICH geschafft! Wir haben das Spiel gewonnen und...\n\nHABT IHR DIESEN DRACHEN GESEHEN?!", rewards = "AthletenrobeBlutgrätschenbrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28415] = {title = "Sieben auf einen Streich", objective = "Sammelt 7 Feuerfliegen.", description = "Wir müssen handeln. Winky und Gor'tesh hatten sich gestritten, also habe ich diese Freundschaftszeremonie geplant, damit sie sich wieder versöhnen. Alles lief super, bis...\n\nNun, den Rest kennt Ihr ja.\n\nIch habe sogar Getränke besorgt!\n\nWinky liebt Flammenfliegen. Er schleicht sich fast jede Nacht davon, um sie zu jagen. Vielleicht ist er ja dorthin gegangen.\n\nIhr findet die Flammenfliegen im Westen und Norden, immer in der Nähe von Lava. Bringt mir sieben davon. Beeilt Euch!\n\nGor'tesh geht vielleicht als Nächster!", progress = "<Oralius schnappt in die Luft, hebt seine Faust und späht hoffnungsvoll zwischen seinen geschlossenen Fingern hindurch.>", completion = "Ihr werdet nie glauben, was passiert ist! Winky ist zurück! Wir haben gar keine Feuerfliegen gebraucht.\n\nBekommt ein Zwerg hier vielleicht einen Bauchkrauler zur Feier des Tages? Kommt schon! KRAULT MEIN BÄUCHLEIN!", rewards = "BauchkraulerFlammenfliegenschiftungGor'Teshs StiefelIhr bekommt:\n\nWinzige Flammenfliege"}
MultiLanguageQuestData['de'][28416] = {title = "Brennende Rache", objective = "Tötet 5 Jungdrachenbändiger des Schwarzfels und 5 Flammenschuppenbrutlinge.", description = "<Name>... seid Ihr das? Ich dachte, Ihr wärt tot, so wie der Rest!\n\nNein, Ihr wart schon immer stark. Schon damals im Rotkammgebirge.\n\nUnser Kampf ist noch nicht vorbei, <Name>. Sie haben schon einmal unsere Heimat angegriffen. Ich bin hier, um sicherzustellen, dass das nicht noch einmal passiert.\n\nWenn Ihr immer noch so kämpfen könnt wie damals, dann schließt Euch mir an. Geht zunächst nach Süden in die Schlupfhügel und tötet ihre Jungdrachenbändiger und Schwarzdrachenbrutlinge.\n\nEs wird wie in alten Zeiten sein.", progress = nil, completion = "Ich bin froh, Euch an meiner Seite zu wissen, &lt;Name&gt;. Die Kompanie Bravo wieder vereint, was?\n\nOh, habe ich erwähnt, dass Trottmann auch hier ist?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28417] = {title = "Unschuldig", objective = "Beschafft einen befreiten roten Welpling, einen befreiten grünen Welpling, einen befreiten blauen Welpling und einen befreiten bronzefarbenen Welpling.", description = "Die Schwarzfelsorcs in der Steppe dienen einem finsteren Meister, der abartige Experimente an lebenden Wesen durchführt, um seine eigene Menagerie der Monstrositäten zu schaffen. Viele seiner Testobjekte sind so verderbt wie ihr Meister, aber ein paar davon sind vollkommen unschuldig.\n\nIn den Schlupfhügeln im Süden ketten sie Jungdrachen am Boden fest, um sie für solche Experimente vorzubereiten. Das lasse ich nicht zu. Zerbrecht ihre Fesseln und bringt die Brutlinge zu mir... in Sicherheit.", progress = "Ich hoffe, wir kommen nicht zu spät.", completion = "Ich werde mich darum kümmern, dass diese Drachen versorgt werden.", rewards = "WelpenpflegerstabJungtierbeschützerAuf Euch wartet eine dieser Belohnungen:\n\nFlammensternamulett\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28418] = {title = "Brennende Rache", objective = "Tötet 5 Jungdrachenbändiger des Schwarzfels und 5 Flammenschuppenbrutlinge.", description = "Ich bin von Geburt an ein Schwarzfelsorc. Ich habe einen Großteil meiner Kindheit in diesem Berg verbracht.\n\n<Ariok zeigt auf den Schwarzfels im Norden.>\n\nAber auch wenn das gleiche Blut in unseren Adern fließt, teile ich ihre Ansichten nicht. Ich suche nach einem Verbündeten, der mir dabei hilft, ihren kommenden Angriff aufzuhalten.\n\nAlso beweist Euch. Reist nach Süden in die Schlupfhügel und tötet ihre Jungdrachenbändiger und Schwarzdrachenbrutlinge. Zeigt mir, dass Ihr für diesen Krieg bereit seid.", progress = nil, completion = "Ihr seid also dabei?\n\nGut.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28419] = {title = "Aufstockung", objective = "Besorgt 5 rasiermesserscharfe Skorpidstachel.", description = "Wenn wir einen Krieg gegen den Schwarzfelsklan führen wollen, müssen wir vorausplanen. Mein Vater hat bereits einen Plan geschmiedet - jetzt wird es Zeit, ihn in die Tat umzusetzen.\n\nIch brauche Skorpidstachel... die schärfsten, die Ihr finden könnt. Skorpide befinden sich überall in der Steppe, aber die meisten befinden sich in der Schlucht im Westen.\n\nZerbrecht Euch nicht den Kopf darüber, wofür sie sind. Das werdet Ihr noch früh genug herausfinden.", progress = "Schon zurück?", completion = "Man kann diese Skorpiden leicht unterschätzen. Ihr habt Glück, dass Ihr nicht an einem dieser Stachel steckt. Oder vielleicht seid Ihr einfach nur gut.\n\nIch füge sie dem Vorratslager hinzu. Wir sind noch nicht fertig, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\nScharfer Skorpidstachel"}
MultiLanguageQuestData['de'][28420] = {title = "Ein zukünftiges Projekt", objective = "Besorgt 11 Glutworgbälge.", description = "Laut meinem Vater brauchen wir Worgbälge, und zwar viele. Es macht nichts, wenn sie zerrissen, versengt oder blutig sind. Hauptsache es sind genügend.\n\nEigentlich wäre es sogar besser, wenn sie ein wenig ramponiert aussehen.\n\nWorgs findet Ihr im Westen und im Osten.", progress = "Dann schauen wir uns die Bälge mal an.", completion = "Glaubt mir, &lt;Name&gt;... Ich kann es genauso wenig wie Ihr abwarten, bis wir endlich zum Töten kommen. Aber wir müssen uns an den Plan halten. Das Jüngste Gericht kommt früh genug.\n\nIch werde diese Bälge hier aufbewahren.", rewards = "Ihr bekommt:\n\nGlutworgenauge"}
MultiLanguageQuestData['de'][28421] = {title = "Schlammschlacht", objective = "Besorgt 9 Haufen obsidiandurchsetzten Schlamm.", description = "Ich hoffe, Ihr habt keine Angst davor, Euch schmutzig zu machen. Aber wenn ich Euch so ansehe, dürfte das kein Problem sein.\n\nIm Norden am Rand der Lava findet Ihr dunkle Schlammhaufen. Den Schlamm brauche ich.\n\nAm besten stellt Ihr keine Fragen und konzentriert Eure Bemühungen darauf, Befehle zu befolgen, <Name>.", progress = "Ihr solltet Euch vor den Obsidianelementaren hüten. Sie schleichen sich gerne an.", completion = "Genau das brauchen wir.\n\nKeine Sorge, &lt;Name&gt;... Eure Klinge wird bald Blut zu schmecken bekommen.", rewards = "Ihr bekommt:\n\nObsidiandurchsetzte Gugel"}
MultiLanguageQuestData['de'][28422] = {title = "Der Sand, der Apfelwein und die Kugel", objective = "Sprecht mit Gorzeeki Wildaug in der Nähe des Altars der Stürme.", description = "Mein Vater wartet auf uns im Osten. Bevor wir aufbrechen müssen wir jedoch noch ein paar Vorräte sammeln. Diesmal werdet Ihr es einem Hexenmeister mit Namen Gorzeeki Wildaug abnehmen.\n\nWahrscheinlich findet Ihr ihn im Nordwesten in der Nähe des Altars der Stürme. Sagt ihm, dass er uns helfen wird. Wir brauchen den Sand, den Apfelwein und die Kugel.\n\nEr weiß schon, was das bedeutet.", progress = nil, completion = "Bah! Wer seid Ihr?\n\nOh, also hat Ariok Euch geschickt? Gut. Würde es Euch etwas ausmachen, wenn Ihr eine Weile hier bleibt? Nichts großes... Ihr müsst nur ein paar Hexenmeister für mich töten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28423] = {title = "Hexenmeister haben das beste Zeug", objective = "Besorgt eine Handvoll Schlummersand, einen Krug Teufelskarussellstöffsche und eine lupenreine Glaskugel.", description = "Ariok sagt, er braucht Vorräte? Ich habe haufenweise Vorräte! Das Problem ist nur, dass diese Hexenmeister mich aus meinem Zuhause geworfen haben und mich nicht wieder hineinlassen.\n\n<Gorzeeki mustert Euch.>\n\nIhr könntet vielleicht hineingelangen. Geht nach Norden und holt mir meinen Schlummersand, mein Teufelskarussellstöffsche und eine klare Glaskugel. Ich bin mir ziemlich sicher, dass es das ist, was er haben will.\n\nOh, und falls Ihr aus Versehen ein paar dieser Orcs tötet, während Ihr da oben seid, wäre ich bestimmt nicht traurig.", progress = "Mal sehen, ob Ihr alles bekommen habt.", completion = "Ich hoffe, dass ist das, wonach Ariok gesucht hat. Im Moment kann ich jedenfalls nicht viel damit anfangen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28424] = {title = "Schattenboxen", objective = "Tötet Ner'gosh den Schatten.", description = "Ner'gosh der Schatten ist der Anführer dieser Hexenmeister, die sich nördlich von uns befinden. Er ist der Fiesling, der mich aus meinem Haus vertrieben hat, als diese Schwarzfelsorcs aufgetaucht sind. Nun, eigentlich sind sie alle Fieslinge, aber er ist der fieseste.\n\nWenn ich jemals in die Nähe des Altars zurückkehren möchte, muss Ner'gosh verschwinden.", progress = nil, completion = "So wie ich diese Orcs kenne, wird bald ein anderer seinen Platz einnehmen. Ich werde versuchen, mich zurück in den Altar zu schleichen, bevor das passiert.\n\nHabt Dank, mein Bester.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28425] = {title = "Rückkehr zu Ariok", objective = "Bringt die Hexenmeisterausrüstung zu Ariok am Flammensternposten in der Brennenden Steppe.", description = "Ich schätze, ich bin hier mit Euch fertig. Ich werde diese anderen Orcs davonscheuchen, sobald ich den Mut dazu gefunden habe.\n\nHier, vergesst Eure Vorräte nicht.", progress = "Sieht aus, als wärt Ihr mit Gorzeeki gut zurecht gekommen.", completion = "&lt;Ariok wirft einen Blick in die Kiste.&gt;\n\nGut, gut, gut. Wir können weiter. Unser Krieg führt uns nach Osten, weg vom Schwarzfels... fürs Erste.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28426] = {title = "Meißelgriff, das Herz der Steppe", objective = "Tötet 15 beliebige Schwarzfelstruppen auf Eurem Weg nach Meißelgriff.", description = "Wir sind auf dem Weg nach Meißelgriff, das sich genau im Herzen dieser Steppe befindet. Wir treffen uns dort mit der Thoriumbruderschaft und mit meinem Vater.\n\nSeid Ihr mit der Bruderschaft vertraut? Diese Dunkeleisenzwerge haben mir mehr als einmal geholfen. Wir brauchen ihre Hilfe vielleicht erneut.\n\nWir kommen auf unserem Weg dorthin durch den Schwarzzahnunterschlupf. Was haltet Ihr davon, wenn wir unterwegs ein paar Orcs töten? Ich werde in diesem Lager langsam ein wenig unruhig.", progress = nil, completion = "Ihr müsst mich entschuldigen, aber wir empfangen derzeit keine Besucher. Ich bitte Euch, Meißelgriff auf demselben Weg wieder zu verlassen, den Ihr gekommen seid.\n\nOh, Ariok... Seid Ihr das?", rewards = "WillkommenswesteSchwarzzahnhelmEntlastete SchulterstückeErzknöchels GewehrIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28427] = {title = "Die Nadel im Höllhaufen", objective = "Sprecht mit Thelaron Düsternadel in Meißelgriff in der Brennenden Steppe.", description = "Lok'tar, <Klasse>. Mein Name ist Etrigg vom Argentumkreuzzug... ehemals Ehrenwache des Kriegshäuptlings. Und davor Schwarzfelsorc.\n\nIch nehme an, mein Sohn hat Euch in unseren Plan eingeweiht. Hat er nicht? Nun, es ist vermutlich besser so.\n\nDer nächste Teil des Plans erfordert ein wenig Feingefühl. Sprecht mit Thelaron Düsternadel, dem Schneider hier vor Ort. Ich habe ihm bereits die Bälge und den Schlamm gegeben, die Ihr gesammelt habt. Er muss Eure Maße nehmen.\n\nGenau, <Volk>: Wir werden Euch als einen der Feinde verkleiden.", progress = nil, completion = "Ihr braucht eine Verkleidung? Nun, da seid Ihr genau am richtigen Ort, Schätzchen.\n\nLasst mich mal sehen.... mm-hmm. Ich weiß genau, was wir machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28428] = {title = "Ein perfektes Kostüm", objective = "Bringt die angemessene Menge an Ausrüstung vom Tisch des Schneiders zu Thelaron Düsternadel in Meißelgriff.", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als einen Orc verkleiden. Ihre Armee besteht hauptsächlich aus Orcs, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.", progress = nil, completion = "Das soll sie sein? Das ist Eure Verkleidung? Mein Vertrauen in unsere Chancen schmilzt.\n\nAber ich habe trotzdem noch Vertrauen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28429] = {title = "Ein perfektes Kostüm", objective = "Bringt die angemessene Menge an Ausrüstung vom Tisch des Schneiders zu Thelaron Düsternadel in Meißelgriff.", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als Oger verkleiden. Die Oger der Feuermägen haben immer für die Schwarzfelsorcs gearbeitet, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28430] = {title = "Ein perfektes Kostüm", objective = "Bringt die angemessene Menge an Ausrüstung vom Tisch des Schneiders zu Thelaron Düsternadel in Meißelgriff.", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als Goblin verkleiden. Die Schwarzfelsorcs haben schon immer goblinische Söldner angeheuert, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.", progress = nil, completion = "Das soll sie sein? Das ist Eure Verkleidung? Mein Vertrauen in unsere Chancen schmilzt.\n\nAber ich habe trotzdem noch Vertrauen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28431] = {title = "Ein perfektes Kostüm", objective = "Bringt die angemessene Menge an Ausrüstung vom Tisch des Schneiders zu Thelaron Düsternadel in Meißelgriff.", description = "Eurem Gewicht, Eurer Statur und Eurer Größe nach zu urteilen, werden wir Euch als Troll verkleiden. Die Gluthauertrolle haben stets mit den Schwarzfelsorcs zusammengearbeitet, also werdet Ihr nicht weiter auffallen.\n\nSeid Ihr in der Kunst des Schneiderns bewandert? Wenn nicht, dann betrachtet dies als Eure erste Lektion. Auf meinem Arbeitstisch dort drüben liegen alle notwendigen Dinge dafür bereit.\n\nNehmt Euch, was immer Ihr für notwendig haltet und bringt es her. Thelaron wird Euch entsprechend herrichten.", progress = nil, completion = "Das soll sie sein? Das ist Eure Verkleidung? Mein Vertrauen in unsere Chancen schmilzt.\n\nAber ich habe trotzdem noch Vertrauen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28432] = {title = "In den Schwarzzahnunterschlupf", objective = "Sprecht mit Rüstmeister Kaoshin im Schwarzzahnunterschlupf in der Brennenden Steppe.\n\nBereitgestellter Gegenstand: \n", description = "Bei verdeckten Ermittlungen geht es eigentlich fast nur um Wichtigtuerei. Verhaltet Euch einfach, als hättet Ihr alles Recht der Welt, dort zu sein und es wird schon klappen.\n\nEure Kontaktperson im Schwarzzahnunterschlupf ist ein Orc namens Rüstmeister Kaoshin. Er weiß NICHT Bescheid, dass Ihr ein Spion seid, also haltet Euch bedeckt. Tut, was immer er von Euch verlangt.\n\n<Etrigg drückt Euch ein kleines, mechanisches Objekt in die Hand.>\n\nSteckt Euch dieses Gerät ins Ohr. Ich werde mit Euch in Kontakt bleiben und spezielle Anweisungen geben.\n\nViel Glück da draußen, <Soldat/Soldatin>.", progress = nil, completion = "Wo bleibt Ihr denn, Grunzer? Ihr seid spät dran! Gebt mir auch nur einen Grund, warum ich Euch nicht auf der Stelle einen Kopf kürzer machen sollte!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28433] = {title = "Grunzertreiberei", objective = "Poliert 7 Paar Schwarzfelsstiefel sehr gründlich.", description = "Pah! Ihr habt Glück, dass mir heute die Arbeitskräfte fehlen. Sonst hätte ich Euch für diese Woche zu <meinem Prügelknaben/meinem Prügelmädchen> gemacht.\n\nDie Stiefel der Offiziere und hochrangigen Soldaten müssen gewienert werden. Sie stehen draußen vor ihren Hütten.\n\nIch möchte mich darin spiegeln können, Grunzer! An die Arbeit!", progress = nil, completion = "Hmpf. Gute Arbeit, Grunzer.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28434] = {title = "Personaleinsparungen", objective = "Benutzt den rasiermesserscharfe Skorpidstachel, um Voodooist Timan auf der Aschensäule, Worgmeisterin Othana in den Worgzwingern und Gorlop bei den Lavateichen auszuschalten.", description = "<Ihr hört ein Summen in Eurem Ohr.>\n\n<Name>? Ich bin es, Etrigg.\n\nWir haben gerade die letzte Information für Eure nächste Mission erhalten. Es gibt drei Ziele, die ihr für uns aus dem Weg schaffen müsst. Das erste ist Voodooist Timan, den Ihr auf der Aschensäule findet. Worgmeisterin Othana hält sich in den mittleren Worgzwingern auf. Und Gorlop findet Ihr in der Nähe der Lavabecken im Süden.\n\nIn Eurem Gepäck werdet Ihr die Skorpidstachel finden, die Ihr gesammelt habt. Wendet die Stachel zur richtigen Zeit auf die Zielpersonen an.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28435] = {title = "Das Horn des Kodorufers", objective = "Benutzt das Horn der Rufer, um 7 Kriegskodos des Schwarzfels zurück zum Lager zu rufen. Bekämpft feindselige Kodos, bis sie aufgeben.", description = "Nun gut, ich habe richtige, ehrliche und sogar wichtige Arbeit für Euch! Wir müssen die Kodos rufen, die in den Gebieten südlich von hier grasen. General Thorg'izog sagt, dass wir bald ins Rotkammgebirge aufbrechen, und ich kann nicht zulassen, dass wir ohne die Kodos aufbrechen.\n\nBenutzt dieses Horn in der Nähe eines Kodos. Sobald es den Ruf hört, wird es sich auf in Richtung Lager machen.\n\nIhr müsst aber aufpassen. Manchmal sind die Kodos ein bisschen angriffslustig, und es kann sein, dass Ihr ein bisschen mit ihnen 'spielen' müsst, bevor sie auf Euch hören.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28436] = {title = "Wir behalten das Horn", objective = "Bringt das Horn der Rufer zurück zu Etrigg in Meißelgriff in der Brennenden Steppe.", description = "<Name>, Etrigg hier. Ich will, dass Ihr dieses Horn behaltet. Ich bin sicher, dass wir improvisieren können, um es in unseren Plan einzubinden.\n\nIch bin etwas besorgt über das, was Kaoshin zum Angriff auf das Rotkammgebirge gesagt hat. Wir wussten, dass ein neuer Angriff aussteht, aber nicht schon so bald!\n\nKehrt mit dem Horn zu mir zurück. Wir werden hier in Meißelgriff weitersprechen. Versucht, Eure Verkleidung nicht zu verlieren. Ihr seid mit Eurer verdeckten Arbeit noch nicht fertig.", progress = "Willkommen zurück, Soldat.", completion = "Ein Angriff auf das Rotkammgebirge ist zwar auch ein Angriff auf die Allianz... aber es ist auch ein Angriff auf Unschuldige.\n\nDas lasse ich nicht zu. Nicht als Kreuzfahrer. Nicht als &lt;Volk&gt;.\n\nEs ist Zeit, dem Schwarzfelsklan, meinem alten Klan, beizubringen, dass die Tage ihrer Raubzüge gezählt sind.", rewards = "Gamaschen der SteppenImprovisierte BrustplatteHelm der glücklichen FügungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28437] = {title = "General Thorg'izog", objective = "Sprecht mit General Thorg'izog.", description = "Kaoshin hat sich als hilfreicher herausgestellt, als wir vermutet hatten, aber jetzt brauchen wir ihn nicht mehr. Es ist an der Zeit, mit dem General zu sprechen. Ich glaube, Ihr seid bereit.\n\nGeneral Thorg'izog ist einer der \"großen Drei\", die die Bodentruppen in der Brennenden Steppe anführen. Er befindet sich in der Schwarzfelsfestung im Nordwesten. Zieht Eure Verkleidung an und sprecht mit ihm. Versucht, sein Vertrauen zu gewinnen. Ich werde mich bei Euch melden, sollte ich noch etwas von Euch brauchen.", progress = nil, completion = "Noch mehr Außenstehende? Was wollt Ihr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28438] = {title = "Magmataufe", objective = "Sprecht mit Würtl Sprillhuper und bittet ihn, Magmalord Kolob freizulassen. Besiegt danach Magmalord Kolob im Kampf.", description = "Ich muss aus dieser Situation das Beste machen. Diese Goblinsöldner haben mir diesen riesigen Feuerelementar als \"Dankeschön\" geschickt, weil ich sie angeheuert habe. Was soll ich denn hier in der Steppe mit einem Elementar anfangen? Das ist ja fast, wie Wasser zum Meer zu tragen.\n\nWenn Ihr nach Arbeit sucht, so könnt Ihr Euch nun beweisen. Sprecht mit diesem Goblin hier und fordert seinen Elementar zum Kampf heraus. Ich werde dem Sieger meinen Respekt zollen und meine Zeit geben.", progress = "Was ist los? Habt Ihr Angst?", completion = "Ich hatte fast damit gerechnet, dass Ihr als Sieger hervortreten würdet. Mir gefällt Eure Art, zweifellos.", rewards = "Umhang des MagmafürstenStillose HandschuheArmschienen des GladiatorenkampfesAuf Euch wartet eine dieser Belohnungen:\n\nThorg'izogs Band\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28439] = {title = "Ich bin das Gesetz und dessen starker Arm", objective = "Benutzt den Disziplinarknüppel des Schwarzfels bei 20 Einheiten in den Feldern der Ehre. Wenn jemand merkt, wer Ihr seid, so erschlagt ihn, bevor er Eure Maskierung aufheben kann.", description = "Ich war auf der Suche nach <einem starken Soldaten/einer starken Soldatin> wie Euch. Ich brauche jemanden, der dafür sorgt, dass meine Truppen sich benehmen.\n\nAußerhalb der Festung bereiten sich die Orcs, Oger und Trolle auf einen Angriff auf das Rotkammgebirge vor. Meine Unteroffiziere halten sie zwar auf Trab, aber sie brauchen Hilfe.\n\nNehmt diesen Knüppel und diszipliniert ein paar meiner Soldaten.\n\nEs ist mir egal, ob sie in Reih und Glied stehen oder sich fehlverhalten - ich will nur, dass sie eine Tracht Prügel bekommen. Ich will, dass sie sich konzentrieren, auf die Schlacht vorbereitet und abgehärtet sind, und gefolgsam.\n\nGeht nun.", progress = nil, completion = "Ich habe das Gefühl, dass wir von Euch noch viel hören werden, Soldat. Ich freue mich darauf, an Eurer Seite im Rotkammgebirge zu kämpfen.\n\nWegtreten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28440] = {title = "Machtmissbrauch", objective = "Tötet 5 Feldwebel des Schwarzfels mit dem Disziplinarknüppel des Schwarzfels. Besiegt sie schnell, bevor sie Eure Maskierung aufheben können.", description = "<Name>? Etrigg hier.\n\nWie es scheint, habt Ihr Thorg'izogs Vertrauen gewonnen, denn er hat Euch für die Disziplinierung eingeteilt. Das ist ein Glück.\n\nWir müssen diese Feldwebel loswerden. Ihr findet sie außerhalb der Schwarzfelsfestung in den Feldern der Ehre auf Wölfen reitend. Benutzt den Knüppel so oft wie nötig, bis sie sterben. Ihr müsst schnell handeln, denn wenn sie merken, dass Ihr <keiner/keine> von ihnen seid, dann werden sie versuchen, Eure Maskierung aufzuheben. Seid schnell und zügellos, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28441] = {title = "Genug Schaden für einen Tag", objective = "Kehrt zu Etrigg in Meißelgriff zurück.", description = "Wir haben keine weitere strategische Verwendung für Thorg'izog oder die Bodentruppen des Schwarzfels. Wir müssen nun die nächste Phase des Plans einläuten.\n\nWenn Ihr bei der Festung fertig seid, kehrt zurück zu mir und meinem Sohn in Meißelgriff.", progress = nil, completion = "Seid Ihr wohlauf?\n\nGut. Ihr habt dort draußen Stärke bewiesen, &lt;Name&gt;. Stärke und Weisheit.\n\nUnd nun packt Eure Sachen zusammen. Wir ziehen weiter.", rewards = "Kubits DolchGürtel der VorbereitungHandschuhe des SchwarzfelsschamanenAbgenutze Brustplatte des ArgentumkreuzfahrersAuf Euch wartet eine dieser Belohnungen:\n\nBand der Kriegslist\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSchwarzfelsverkleidung entfernen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28442] = {title = "Flammenkamm", objective = "Meldet Euch bei Kibler auf dem Flammenkamm in der Brennenden Steppe.", description = "Unsere Arbeit hier in Meißelgriff ist getan. Das verdanken wir vor allem Euch. Wir werden jetzt weiter nach Nordosten ziehen, zum Flammenkamm.\n\nDer Flammenkamm liegt in den Klippen, hinter den Ruinen von Thaurissan. Dieser Ort sollte ein geeigneter Ausgangspunkt für den letzten Teil unseres Plans sein.\n\nNatürlich reist mein Sohn Ariok mit Euch. Und ich ebenso.", progress = nil, completion = "Oh. Besucher?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28443] = {title = "Geschwärzte Asche", objective = "Sammelt 9 Haufen Obsidianasche.", description = "Ihr müsst für mich noch etwas besorgen, bevor wir uns dem Rest der Schwarzfelsarmee annehmen können. Wenn wir das hier tun wollen, sollten wir es richtig tun, und das bedeutet, dass wir uns vorbereiten müssen.\n\nIch brauche Asche, <Name>. Nicht irgendwelche Asche... Asche von den großen Obsidianelementaren, die sich in den Ebenen im Südosten aufhalten. Das Zeug ist tiefschwarz, und genau das brauchen wir für unsere nächste Verkleidung.\n\nKeine Sorge, Ihr habt schon eine Verkleidung. Diese ist für jemanden... naja, für ETWAS... anderes.", progress = "Die Asche der Obsidianelementare ist besonders dunkel - und genau, was wir für unser Vorhaben benötigen.", completion = "Ja, die sind gut genug. Ich werde sie für Euch schön einpacken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28444] = {title = "Schlafende Dämonen des Landes", objective = "Sammelt 18 gefallene Flammkin.", description = "Die Lavaseen südlich von hier sind die Heimat der Flammkin, eine besondere Art Feuerdämonen, die die Steppe schon lange beheimaten. In der Schwarzfelsarmee sieht es so aus, als könnten wir - wenn wir vorsichtig genug sind - ein paar der Flammkin hinter die feindlichen Linien schmuggeln, um für Verwüstung zu sorgen.\n\nBringt mir die Leichen von mehreren Flammkin. Als Dämonen kann man sie leicht wiederbeleben, und dann für seine eigenen Zwecke einsetzen.", progress = "Die Flammkin sind schwach, aber sie reisen in Rudeln. Seid vorsichtig.", completion = "Für das ungeübte Auge sehen sie aus wie Wichtel.\n\nWir müssen sie nur diesem eben ungeübten Auge unterjubeln. Ich werde sie jetzt für den Einsatz vorbereiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28445] = {title = "Ein köstlicher Haufen Worg", objective = "Benutzt die Worgsäge, um aus den frisch getöteten riesigen Glutworgs 40 Worgschnitzel zu schneiden.", description = "Wir brauchen frisches Fleisch und deshalb werdet Ihr Euch auf die Worgjagd machen. Die Worgs auf dieser Seite der Steppe sollten die sein, auf die Ihr Euch bei der Jagd konzentriert.\n\n<Etrigg holt eine große Klinge hervor und händigt sie Euch aus.>\n\nMacht Jagd auf die riesigen Glutworgs. Benutzt diese Säge, um die besten Fleischstücke aus den frisch getöteten Worgs zu schneiden. Worgs sind überall in der Steppe zu finden; nordöstlich von hier ist gleich das erste Rudel.", progress = "Glück bei der Jagd gehabt?", completion = "Das Fleisch sieht gut aus... aber ich glaube, wir müssen es noch ein bisschen \"würzen\". Ich werde sicherstellen, dass sich jemand darum kümmert.\n\nVielen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28446] = {title = "Blutrunde", objective = "Tötet 25 schwarze Großdrachenbrut oder Schwarzwyrmkin.", description = "Meine Beine werden schon wieder ein wenig rastlos. Habt Ihr Lust, eine kleine Runde zu drehen, <Name>?\n\nWir werden uns auf eine Reise um den Schreckensfels begeben. Ich möchte die Schwarzfelsarmee erst ein wenig unter die Lupe nehmen, bevor wir zuschlagen. Da dachte ich mir, wir könnten auch ein paar von ihnen töten, wenn wir schon auf dem Weg sind.", progress = nil, completion = "&lt;Ariok trieft vor Blut und Schweiß.&gt;\n\nGenau das hatte ich im Sinn!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28447] = {title = "Drachenvorhut", objective = "Tötet Minyoth, Welpenbändigerin Akumi, Terromath den Versengten und Tugnar Blutschlund.", description = "Die Schwarzfelsorcs kommen nicht allein. Die Oger der Feuermägen und Trolle der Gluthauer, die an ihrer Seite kämpfen, habt Ihr bereits gesehen. Leider haben sie aber auch die schwarzen Großdrachen auf ihrer Seite.\n\nDie Orcs und Drachen haben bereits ihre Champions zu Sammelpunkten geschickt, um Wache zu stehen. Ihr könnt sie an den Drachenschädeln auf Piken erkennen, die herumstehen. Wir beide werden diese Sammelpunkte finden und die Vorposten ausschalten, bevor die Schlacht beginnt.\n\nSeid Ihr bereit?", progress = nil, completion = "Ihr werdet immer besser, &lt;Name&gt;! Jetzt fallen sie, so wie wir es wollten.\n\nUnd wir werden siegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28448] = {title = "Ein Handel mit einem Drachen", objective = "Bringt die geretteten Welplinge zu Acride im Schlitterfels in der Brennenden Steppe.", description = "Auf unserer Reise um den Schreckensfels gibt es noch einen Zwischenstopp.\n\nErinnert Ihr Euch noch an die Brutlinge, die Ihr aus den Schlupfhügeln befreit habt? Ich habe mich um sie gekümmert. Jetzt werden wir sie zu jemandem bringen, der besser für sie sorgen kann als wir. Er hält sich am Schlitterfels auf, nordöstlich des Schreckensfels.\n\nSein Name ist Acride. Er ist vielleicht der Schlüssel zum Sieg in der bevorstehenden Schlacht.", progress = "Da seid Ihr ja, <Name>.", completion = "Ja, die Welplinge. Ich werde mich um sie kümmern.\n\nUnd was die Vereinbarung angeht, die ich zuvor mit Eurem Vater getroffen habe, sagt ihm, dass ich meinen Teil des Handels erfüllen werde. Ich werde Euch Euren Drachen für die Schlacht gegen die Orcs schicken.\n\nWir hegen beide einen Groll gegen den Schwarzfelsklan.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28449] = {title = "Aufstellung der Bauern", objective = "Kehrt zu Etrigg auf dem Flammenkamm in der Brennenden Steppe zurück.", description = "<Ihr hört ein Summen in Eurem Ohr.>\n\n<Name>. Ihr und Ariok scheint Eure Aufgaben erledigt zu haben. Ich bin ebenfalls mit meiner fertig.\n\nKehrt zum Flammenkamm zurück. Ich habe ein paar Pakete für die großen Drei vorbereitet: Thorg'izog, Neeralak und Xi'lun. General Thorg'izog habt Ihr ja schon getroffen. Jetzt habt Ihr die Gelegenheit, auch den anderen beiden zu begegnen.\n\nBevor Ihr sie tötet, meine ich natürlich.", progress = nil, completion = "Gut, Ihr seid zurück.\n\nIch hoffe, Ihr habt die Verkleidung noch. Ihr werdet Euch wieder mitten unter die Feinde begeben, &lt;Name&gt;.", rewards = "BauernarmschienenFlammenkammarmschienenSubversive SchritteBrustplatte des verdeckten ThoriumbrudersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28450] = {title = "Eine Lieferung für Thorg'izog", objective = "Tragt Eure Schwarzfelsverkleidung und bringt die in Karussellstöffsche marinierten Schnitzel zu General Thorg'izog im Ofen der Feuermägen in der Brennenden Steppe. Sprecht mit Etrigg, wenn Ihr eine neue Schwarzfelsverkleidung braucht.", description = "General Thorg'izog ist bei den Ogern im Ofen der Feuermägen, eine Höhle in der Westwand des Schreckensfels. Bringt diese Lieferung zu ihm und den Ogern.\n\nDarin befinden sich die Worgschnitzel, die Ihr besorgt habt. Sie wurden in dem Teufelskarussellstöffsche mariniert, das wir vom Altar der Stürme erhalten haben.\n\nIhr solltet nichts davon essen, wenn es Euch irgendwie möglich ist.\n\nBringt die Schnitzel zu General Thorg'izog. Er wird sich darum kümmern, dass seine Streitmächte Essen im Magen haben und mit ein bisschen Glück isst er auch etwas davon.", progress = "Was habt Ihr da, Soldat?", completion = "Nun seht Euch das an! Jetzt weiß ich, wer mein Lieblingssoldat ist!\n\nIch werde die Schnitzel unter den Ogern verteilen.\n\nIch werde Euch am Rotkamm wieder sehen, Soldat. Für die Ehre des Schwarzfels!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKarussellstöffsche mariniertes Fleisch beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28451] = {title = "Eine Lieferung für Neeralak", objective = "Legt Eure Schwarzfelsverkleidung an, schleicht Euch in die Schädelhöhle und überzeugt Drachenlord Neeralak, Eure Kiste voller schlafender Flammkin anzunehmen. Sprecht mit Etrigg, wenn Ihr eine neue Schwarzfelsverkleidung benötigt.", description = "Die Hexenmeister des Schwarzfelsklans üben ihre Magie oft in der Schädelhöhle östlich des Schreckensfels. Ihr Anführer Xi'lun ist gerade andernorts beschäftigt, sodass die Höhle derzeit von einem anderen der großen Drei beaufsichtigt wird: Drachenlord Neeralak. Neeralaks Fachgebiet sind Drachen, nicht die Totenbeschwörung.\n\nIch habe die Flammkin, die Ihr gefangen habt, mit dem Schlummersand bestreut. Überzeugt Neeralak davon, dass es sich dabei um Hexenmeisterwichtel handelt, nicht um Flammkin. Wenn sie aufwachen, werden sie alles andere als glücklich sein.", progress = "Was?", completion = "Was soll das sein? Aha, das sind also Wichtel?\n\nIch bin mir sicher, dass Wichtel nicht einfach so in Kisten schlafen!\n\nAber ich nehme Euch beim Wort. Ich verstehe nichts von diesem Hexenmeisterquatsch. Stellt sie in der Ecke ab.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSack voller schlafender Flammkin beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28452] = {title = "Eine Lieferung für Xi'lun", objective = "Legt Eure Schwarzfelsverkleidung an und bringt die klare Glaskugel zum obersten Hexenmeister Xi'lun auf dem Schreckensfels in der Brennenden Steppe. Sprecht mit Etrigg, wenn Ihr eine neue Schwarzfelsverkleidung benötigt.", description = "Man hat uns berichtet, dass der oberste Hexenmeister Xi'lun, das letzte Mitglied der großen Drei, sich in einer Höhle auf dem Gipfel des Schreckensfels aufhält und seinen großen Augenblick vorbereitet.\n\nEr erwartet eine Lieferung: eine Kugel der Herrschaft, mit der er ein mächtiges Beschwörungsritual durchführen kann. Ich möchte, dass Ihr ihm das hier gebt.\n\n<Etrigg reicht Euch eine Glaskugel.>\n\nDies ist die klare Glaskugel, die Ihr aus dem Altar der Stürme befreit habt. Sie ist machtlos. Gebt sie Xi'lun und betet, dass er den Unterschied nicht bemerkt.", progress = "Ich habe keine Zeit für Spielchen, Narr. Geht mir aus den Augen.", completion = "Pff! Ihr seid spät dran! Wisst Ihr, wie lange ich schon warte, dass Ner'gosh mir endlich diese Kugel bringt?\n\n&lt;Xi'lun schaut auf die Kugel, dann wieder zu Euch.&gt;\n\nEtwas ist merkwürdig an dieser Kugel... Sie ist zu...\n\n&lt;Xi'lun verstummt.&gt;\n\nAch, schon gut. Meine Nerven liegen wohl einfach blank. Vielen Dank für die Lieferung. Für Blut und Donner!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKlare Glaskugel beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28453] = {title = "Geladen und entsichert", objective = "Meldet Euch bei Etrigg auf dem Flammenkamm in der Brennenden Steppe.", description = "<Name>, bitte melden. Könnt Ihr mich hören?\n\nDie Schlacht beginnt gleich. Ich hoffe, Ihr habt alle Pakete ausgeliefert.\n\nIch brauche Euch hier auf dem Flammenkamm, SOFORT.", progress = nil, completion = "&lt;Name&gt; ist da! Wir können loslegen.\n\nDas ist der Moment, auf den wir gewartet haben, &lt;Name&gt;. Ich hoffe, Ihr seid vorbereitet.", rewards = "Imitierte HexenmeisterpantoffelnHandschuhe des listigen GleitersBoshafte SchiftungArmschienen des FehlverhaltensAuf Euch wartet eine dieser Belohnungen:\n\nGlasiges Band\n\nDer folgende Zauber wird auf euch gewirkt:\n\nSchwarzfelsverkleidung entfernen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28454] = {title = "Angriff auf den Schreckensfels", objective = "Tötet 200 Eindringlinge des Schwarzfels. Wenn Ihr Euer Fahrzeug verlieren solltet, benutzt das Horn der Rufer, um es herbeizurufen.", description = "Das ist es also, <Name>! Ein trauriger Tag... aber ein Tag, an dem die Schwarzfelsorcs eine wichtige Lektion lernen. Heute setzen wir unseren Plan in die Tat um.\n\nKommt mit mir. Wir werden mit Acride sprechen und den Gefallen einfordern, den er uns schuldet. Dann werden wir die Invasion im Rotkammgebirge aufhalten, bevor sie überhaupt begonnen hat.", progress = nil, completion = "&lt;Etrigg blickt auf die Zerstörung unter ihm hinab.&gt;\n\nUnsere Aufgabe ist fast erledigt, &lt;Name&gt;. Es ist Zeit, ihnen den Todesstoß zu versetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28455] = {title = "Ruhm im Chaos", objective = "Tötet General Thorg'izog, Drachenlord Neeralak und oberster Hexenmeister Xi'lun.", description = "Ihr und mein Sohn geht zurück zu diesem Berg. Drei Orcs haben den Angriff überlebt, und wir geben keine Ruhe, bis sie den Tod gefunden haben.\n\nGenau, ich spreche von den großen Drei.\n\nGeneral Thorg'izog ist in den Ofen der Feuermägen gekrochen und Drachenlord Neeralak hat sich in der Höhle auf dem Berggipfel verschanzt. Xi'lun hält sich im hinteren Teil der Schädelhöhle auf und schmiedet Pläne mit seinen Hexenmeisterfreunden.\n\nMacht Euch einen Namen, <Name>. Besiegt diese verderbten Schwarzfelsorcs ein für alle Mal.", progress = nil, completion = "&lt;Etrigg verneigt sich.&gt;\n\nWillkommen daheim, Jungs.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28456] = {title = "Kriegsbeute", objective = "Untersucht die Kiste mit übriggebliebenen Vorräten auf dem Flammenkamm in der Brennenden Steppe.", description = "Die Schwarzfelsorcs schwirren zwar immer noch in ihrem Turm herum, aber ich bezweifle, dass ihre Pläne sie in nächster Zeit auch nur in die Nähe der Unschuldigen im Rotkammgebirge führen. Das habt Ihr und Ariok ihnen sicher ausgetrieben.\n\nIch muss sagen, dass wir hier in der Brennenden Steppe nicht mit Einfallsreichtum gegeizt haben. Diese Hexenmeisterausrüstung, die wir gesammelt haben, war äußerst praktisch, und auch die Obsidianasche, mit der wir unseren Drachen versteckt haben, war ein cleverer Schachzug.\n\nWir haben jedoch noch ein paar Gegenstände übrig. Bitte, sucht Euch etwas aus, bevor Ihr die Steppe wieder verlasst und weiterzieht.", progress = nil, completion = "Ihr schaut hinein und findet...", rewards = "Obsidiandurchsetztes CapeGlutworgstiefelRasiermesserscharfer SkorpidgürtelHandschutz des GolemzerschmetterersAuf Euch wartet eine dieser Belohnungen:\n\nXi'luns Signet\n\nIhr bekommt außerdem:\n\nGesprungene Kugel der Herrschaft"}
MultiLanguageQuestData['de'][28457] = {title = "Ein gefährliches Bündnis", objective = "Tötet 6 Brandwachenzerstörer und beschafft Euch die Angriffspläne des Generals von General Zornesschmied in der Westgarnison der Schwarzfelstiefen.", description = "Die Zerschmetterte Hand glaubt, dass die Dunkeleisenzwerge und der Schattenhammer zusammenarbeiten. Es gibt Beweise, dass sie im Schwarzfels einen gemeinsamen Angriff planen. Wir können nicht zulassen, dass eine solche Armee aus dem Schwarzfels marschiert.\n\nIhr müsst in die Schwarzfelstiefen reisen und die Angriffspläne des Schattenhammers von General Zornesschmied in der Westgarnison beschaffen. Beseitigt die Elementare, die der Schattenhammer zur Unterstützung der Truppen bereitgestellt hat.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Gesichtsschutz der HordeKopfschutz der HordeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28458] = {title = "Der Zauberfoliant des Pyromanten", objective = "Tötet 6 Zwielichtabgesandte und besorgt Weisenkorns Zauberfoliant von Pyromant Weisenkorn am Schrein von Thaurissan in den Schwarzfelstiefen.", description = "Tief im Schwarzfels wächst die Macht der Dunkeleisenzwerge und ihrer Schattenhammerverbündeten. Pyromant Weisenkorn ist ein mächtiger und angesehener Magier in der Gesandtschaft des Schattenhammers. Wenn wir seinen Zauberfolianten in die Finger bekämen, könnte ich mir vielleicht Gegenzauber für die Flüche und Zauber des Schattenhammers ausdenken.\n\nIhr müsst in die Schwarzfelstiefen hinabsteigen, den Schrein von Thaurissan ausfindig machen und den Zauberfolianten besorgen. Zeigt Weisenkorn und seinen Zwielichtdienern keine Gnade!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKapuze des arkanen Pfades"}
MultiLanguageQuestData['de'][28459] = {title = "Steine der Bindung", objective = "Besorgt 6 Steine der Elementarbindung aus den Schwarzfelstiefen. Ihr findet die Steine in der Schattenschmiede, dem Domizil, am Schrein von Thaurissan, in der Ostgarnison und in der Westgarnison.", description = "Die Zerschmetterte Hand hat von einer verstärkten Zusammenarbeit zwischen dem Schattenhammer und den Dunkeleisenzwerge in den Schwarzfelstiefen erfahren. Wir haben die Möglichkeit, unserem Feind einen Schlag zu versetzen und unsere eigene Macht zu stärken, <Name>.\n\nDie Anhänger des Schattenhammers haben mehrere Steine der Elementarbindung in der Schattenschmiede, dem Domizil, dem Schrein von Thaurissan, der Westgarnison und der Ostgarnison aufgestellt. Findet und holt Euch diese Steine!", progress = "Konntet Ihr die Steine der Bindung finden?", completion = "Diese Steine der Bindung sind überaus mächtig. Wir haben den Feinden der Horde nicht nur einen schweren Schlag versetzt, sondern gleichzeitig eine faszinierende Quelle der Macht entdeckt.", rewards = "Ihr bekommt:\n\nHörner des linken Pfades"}
MultiLanguageQuestData['de'][28460] = {title = "Bedrohung durch die Winterfelle", objective = "Tötet 15 Furbolgs der Winterfelle in der Nähe der Frostfeuerquellen.", description = "Ich kam nach Winterquell, um die Frostfeuerquellen zu untersuchen. Mir ist aufgefallen, dass das Wasser... merkwürdige Eigenschaften zu haben scheint. Ich konnte die Quelle aber noch nicht entdecken, und um die Wahrheit zu sagen, hatte ich in letzter Zeit durch die Furbolgs der Winterfelle einige Schwierigkeiten.\n\nSie scheinen von den Quellen angezogen zu werden, genau wie ich. Mittlerweile wachen sie extrem eifersüchtig über das Wasser und lassen mich nicht einmal in die Nähe der beiden größeren Quellen, die von hier aus im Norden liegen.\n\nIch würde meine Studien aber gern fortsetzen. Könntet Ihr mir wohl helfen?", progress = nil, completion = "Ich danke Euch vielmals, &lt;Name&gt;! Jetzt kann ich mich hier wieder an die Arbeit machen.\n\nHabt Ihr im Lager der Winterfelle irgendetwas Interessantes gefunden?", rewards = "Donovas fusselige RobeSandalen der heißen QuellenSchneewehbeinwickelWinterfellgürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28461] = {title = "Die Geschöpfe des Golemlords", objective = "Beschafft 5 Elementarmodule von den Golems in der Manufaktur der Schwarzfelstiefen und stehlt die Baupläne für einen Elementargolem.", description = "Die Zerschmetterte Hand meldet beunruhigende Informationen aus den Schwarzfelstiefen. Wie es scheint arbeitet der Schattenhammer mit dem Ingenieur der Dunkeleisenzwerge Argelmach zusammen, um durch Elementare beseelte Kriegsgolems zu erschaffen. Diese Golems könnten ein großer Vorteil für unsere Feinde sein.\n\nEs ist unsere Pflicht, dies zu verhindern. Findet die Manufaktur in den Schwarzfelstiefen, besorgt Euch die Blaupausen, mit denen er diese Golems erschafft, und beschafft die Module, die ihnen Leben einhauchen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nHelm des großen Jägers"}
MultiLanguageQuestData['de'][28462] = {title = "Feuerwasser der Winterfelle", objective = "Bringt das leere Feuerwasserfläschchen zu Donova Schneeweh in Winterquell.", description = "Diese Phiole, die Ihr bei den Winterfellfurbolgs aufgehoben habt, ist leer, aber Ihr könnt im Inneren ein paar Tropfen einer merkwürdigen grünen Flüssigkeit sehen. Sie scheint fast zu glühen.\n\nIst es etwas Wichtiges?\n\nDonova Schneeweh könnte Euch wahrscheinlich mehr sagen, da sie nun schon einige Zeit bei den heißen Quellen in Winterquell lagert.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28463] = {title = "Die Armee der Dunkeleisenzwerge", objective = "Benutzt das schnell wirksame Gift, um 6 Getreiderationen in der Westgarnison oder Ostgarnison der Schwarzfelstiefen zu vergiften.", description = "Als Mitglied der Zerschmetterten Hand wisst Ihr, dass Eure Aufgabe darin besteht, die Feinde der Horde zu beobachten. Wir haben herausgefunden, dass die Dunkeleisenzwerge und ihre neuen Verbündeten vom Schattenhammer einen Angriff vorbereiten.\n\nIch entsende Euch, damit Ihr dieser Bedrohung Herr werdet, bevor die Dunkeleisenarmee ausrücken kann. Nehmt dieses Gift und gebt es auf die Rationen der Soldaten in den Schwarzfelstiefen.\n\nDie Rationen für die Armeen der Dunkeleisenzwerge werden größtenteils in der Ostgarnison und Westgarnison der Schwarzfelstiefen aufbewahrt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGesichtsmaske der Zerschmetterten Hand"}
MultiLanguageQuestData['de'][28464] = {title = "Der Verderbnis erliegen", objective = "Findet den Kessel der Winterfelle im nördlichen Lager der Winterfelle.", description = "Die Aggressivität der Winterfelle muss irgendwo ihren Ursprung haben. Ich will der Sache auf den Grund gehen, wenn ich kann!\n\nIch habe gesehen, wie die Furbolgs in den Lagern im Norden etwas in einem Kessel gebraut haben. Sie schienen den Inhalt des Kessels mit Argusaugen zu bewachen... Wenn das, was sie darin kochen, der Grund ist, muss ich es mit eigenen Augen sehen!\n\nFindet den Kessel, wenn er noch dort ist, und bringt mir, was sich darin befindet!", progress = nil, completion = "Im Kessel blubbert eine faulige, Ekel erregend riechende Substanz...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28465] = {title = "Sklaven des Feuerlords", objective = "Benutzt das Totem der Freiheit, um die Essenzen von 6 Brandwachen, Brandwachenzerstörern oder lodernden Brandwachen in den Schwarzfelstiefen zu befreien.", description = "In den Hallen der Schwarzfelstiefen versammeln der Schattenhammerkult und die Dunkeleisenzwerge ihre Streitkräfte. Ihre Legionen werden von Horden aus Feuerelementaren unterstützt, die der Feuerlord Ragnaros als Diener an sich gebunden hat.\n\nWenn wir die Elementare aus ihrem Bund befreien, können wir sowohl unsere Feinde schwächen als auch den Elementen Ehre erweisen. Nehmt dieses Totem und wirkt es auf die unterworfenen Brandwachen. Das wird ihre Geister befreien und ihren natürlichen Zustand wiederherstellen.", progress = nil, completion = "Eure Taten ehren die Ahnen und die Horde, &lt;Name&gt;.", rewards = "Kopfbedeckung des RednersMaske des RednersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28466] = {title = "Waffen der Dunkelheit", objective = "Sammelt 5 elementarerfüllte Waffen von den Zwergen der Zorneshämmer in den Schwarzfelstiefen und zerbrecht sie auf dem Schwarzen Amboss in der Schattenschmiede.", description = "In den Schwarzfelstiefen hausen schon lange unsere Feinde, aber jetzt hat die Zerschmetterte Hand uns informiert, dass die Dunkeleisenzwerge und der Schattenhammer verstärkt zusammenarbeiten. Mit dem Wissen des Kultes verstärken die Dunkeleisenzwerge ihre Waffen mit elementaren Kräften. Sie haben die Legion der Zorneshämmer mit diesen schrecklichen neuen Waffen ausgerüstet.\n\nIch möchte, dass Ihr in die Schwarzfelstiefen reist und den Zwergen der Zorneshämmer ihre Waffen abnehmt. Zerbrecht sie auf dem Schwarzen Amboss im Herzen der Schattenschmiede.", progress = nil, completion = "Ohne diese Waffen sind die Dunkeleisenzwerge der Horde niemals gewachsen. Ihr habt Euren Brüdern und Schwestern heute einen großen Dienst erwiesen, &lt;Name&gt;.", rewards = "Helm des SonnenläufersGesichtsschutz des SonnenläufersKopfschutz des SonnenläufersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28467] = {title = "Geheimnisvoller Glibber", objective = "Berichtet Donova Schneeweh von Euren Entdeckungen.", description = "Die grünliche Substanz im Kessel ist übelriechend und zähflüssig. Egal, was es ist, es sieht nicht gut aus.\n\nEs wäre das Beste, Donova von Euren Funden zu berichten und ihr eine Probe aus dem Kessel mitzubringen.", progress = "Ich hoffe, Ihr habt etwas gefunden, <Name>. Die Winterfelle werden immer aggressiver!", completion = "Das sind wirklich beunruhigende Neuigkeiten. Dieses Zeug erinnert mich mehr an den Teufelswald als an Winterquell...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28469] = {title = "Läufer der Winterfelle", objective = "Sucht den Läufer der Winterfelle und nehmt ihm die Kiste der Winterfelle ab.", description = "Sehr interessant, <Name>...\n\nWenn diese toxische Substanz mit dem Wasser aus den heißen Quellen gemischt wird, verliert sie ihre Toxizität und behält lediglich die Fähigkeit zurück, Kreaturen vorübergehend zu beeinflussen, die sie einnehmen. Darum verteidigen die Winterfelle die heißen Quellen wohl so vehement - sie brauchen sie, um ihr Feuerwasser zu läutern.\n\nWir müssen sie aufhalten... den Kontakt zwischen den Winterfellen und den Totenwaldfellen abschneiden. Eine Gruppe von Läufern ist zwischen ihrem Dorf und dem Teufelswald unterwegs. Sucht und besiegt sie und stehlt ihre Lieferung.", progress = "Wir werden sehen, was passiert, wenn die Winterfelle ihr Feuerwasser nicht bekommen!", completion = "&lt;Donova untersucht den Inhalt der Kiste.&gt;\n\nIch frage mich, ob die Einnahme dieser Substanz die Furbolgs aggressiver macht. Sie wirken irgendwie viel größer...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28470] = {title = "Oberhäuptling der Winterfelle", objective = "Tötet den Oberhäuptling der Winterfelle", description = "Die Furbolgs der Winterfelle sind normalerweise kein aggressiver Stamm und diese Änderung ihres Verhaltens führt mich zu der Annahme, dass sie Befehle ihres Häuptlings ausführen. Wir werden wohl den Schaden, der bereits angerichtet ist, nicht mehr beheben können, aber ich denke, wenn ihr Anführer erledigt ist, wird es zumindest nicht schlimmer werden.\n\nGeht erneut nach Osten, jenseits des Ortes, an dem Ihr diesen Kessel gefunden habt. Der Oberhäuptling der Winterfelle befindet sich dort, am östlichsten Ende des Holzschlundpostens.", progress = nil, completion = "Ich danke Euch vielmals, &lt;Name&gt;. Ich hoffe zu meinen Studien zurückkehren zu können, ohne Angst, dass ich in einen Hinterhalt gerate. Nehmt dies bitte als Belohnung.", rewards = "Armschienen aus FurbolgfellPrinzessin Zoes alte JagdhandschuheÜberfallarmschützerZauberstab der plötzlichen VeränderungenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28471] = {title = "Das letzte Stück", objective = "Bringt das kunstlos geschriebene Logbuch zu Donova Schneeweh in Winterquell.", description = "Das Logbuch, das Ihr bei dem Oberhäuptling gefunden habt, scheint recht ausführlich zu sein, aber nachdem Ihr einige Seiten durchgesehen habt, stellt Ihr fest, dass Ihr den Text nicht lesen könnt. Die Zeichen sind so kunstlos und schlecht geformt, dass Ihr nicht sicher seid, ob überhaupt jemand sie lesen kann.\n\nAber vielleicht kann Donova Euch sagen, was sie bedeuten...", progress = "Was habt Ihr da, <Name>?", completion = "Ich frage mich, was das alles bedeutet... Ich kann mir keinen Reim darauf machen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28472] = {title = "Worte des Oberhäuptlings", objective = "Bringt das kunstlos geschriebene Logbuch zu Kelek Himmelshüter am Kel'therilsee.", description = "Die Winterfelle sind für mich keine Bedrohung mehr, aber wenn Ihr immer noch herausfinden möchtet, was die Furbolgs dazu gebracht hat, dieses merkwürdige Feuerwasser herzustellen und zu trinken, solltet Ihr Kelek Himmelshüter aufsuchen.\n\nEr ist ein Druide, der einst geholfen hat, den Teufelswald zusammen mit dem Smaragdkreis zu reinigen. Vor einer Weile ist er hierher gekommen, um die Ruinen in der Nähe zu untersuchen.\n\nIhr findet ihn wahrscheinlich im Osten am Kel'therilsee, wo er sich in letzter Zeit meist aufhält.", progress = "Was habt Ihr da bei Euch, <Klasse>?", completion = "Ja, wenn Ihr es mich eine Weile untersuchen lasst, kann ich es für Euch vielleicht übersetzen.\n\n&lt;Kelek blättert durch die Seiten.&gt;\n\nWenn ich es ganz durchgesehen habe, werde ich Euch eine Nachricht schicken.\n\nDanke, dass Ihr dies mit mir teilt, &lt;Name&gt;. Man weiß sehr wenig über die Winterfellfurbolgs.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nStärke des OberhäuptlingsMacht des Oberhäuptlings\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28473] = {title = "Waffen der Dunkelheit", objective = "Sammelt 5 elementarerfüllte Waffen von den Zwergen der Zorneshämmer in den Schwarzfelstiefen und zerbrecht sie auf dem Schwarzen Amboss in der Schattenschmiede.", description = "In den Schwarzfelstiefen hausen schon lange unsere Feinde, aber jetzt hat die Zerschmetterte Hand uns informiert, dass die Dunkeleisenzwerge und der Schattenhammer verstärkt zusammenarbeiten. Mit dem Wissen des Kultes verstärken die Dunkeleisenzwerge ihre Waffen mit elementaren Kräften. Sie haben die Legion der Zorneshämmer mit diesen schrecklichen neuen Waffen ausgerüstet.\n\nIch möchte, dass Ihr in die Schwarzfelstiefen reist und den Zwergen der Zorneshämmer ihre Waffen abnehmt. Zerbrecht sie auf dem Schwarzen Amboss im Herzen der Schattenschmiede.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Helm des OrdensGesichtsschutz des OrdensKopfschutz des OrdensIhr bekommt:\n\nWappenrock der Blutritter"}
MultiLanguageQuestData['de'][28474] = {title = "Zwielichtränke", objective = "Benutzt die leuchtende Fackel, um 8 Abschriften des Glaubensbekenntnisses des Schattenhammers im Domizil der Schwarzfelstiefen zu zerstören.", description = "Der Einfluss des Schattenhammers in den Schwarzfelstiefen wächst. Sie haben sich mit den Dunkeleisenzwergen verbündet und wollen sie überreden, auch außerhalb des Berges zuzuschlagen.\n\nWir müssen die Instrumente des aufwieglerischen Schattenhammers vernichten. Ihr Einfluss auf die Dunkeleisenzwerge muss eingeschränkt werden.\n\nIch möchte, dass Ihr in das Domizil der Schwarzfelstiefen geht und diese Fackel benutzt, um die Bücher zu verbrennen, die der Schattenhammer dort verteilt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKrone des aufgegebenen Glaubens"}
MultiLanguageQuestData['de'][28475] = {title = "Zwielichtränke", objective = "Benutzt die leuchtende Fackel, um 8 Abschriften des Glaubensbekenntnisses des Schattenhammers im Domizil der Schwarzfelstiefen zu zerstören.", description = "In den Schwarzfelstiefen bemüht sich der Schattenhammer, die Dunkeleisenzwerge dazu zu überreden, ihre Allianz zu stärken und ihre Armeen für einen Feldzug außerhalb des Berges vorzubereiten.\n\nWir dürfen nicht zulassen, dass durch diese Manipulation eine gemeinsame Streitmacht aus Dunkeleisenzwergen und Schattenhammer entsteht! Wir müssen die Werkzeuge der Gehirnwäsche durch den Schattenhammer vernichten.\n\nIch möchte, dass Ihr in das Domizil der Schwarzfelstiefen geht und diese Fackel benutzt, um die Bücher zu verbrennen, die der Schattenhammer dort verteilt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKrone des Sonnenjägers"}
MultiLanguageQuestData['de'][28476] = {title = "Zwielichtränke", objective = "Benutzt die leuchtende Fackel, um 8 Abschriften des Glaubensbekenntnisses des Schattenhammers im Domizil der Schwarzfelstiefen zu zerstören.", description = "In den Schwarzfelstiefen bemüht sich der Schattenhammer, die Dunkeleisenzwerge dazu zu überreden, ihre Allianz zu stärken und einen Eroberungsfeldzug zu führen.\n\nWir müssen handeln, bevor die Kultisten den Blutdurst in den Dunkeleisenzwergen und ihren Anführern wecken können. Vielleicht sollten wir die Materialien zerstören, die die Kultisten an die Zwerge aushändigen.\n\nIch möchte, dass Ihr in das Domizil der Schwarzfelstiefen geht und diese Fackel benutzt, um die Bücher zu verbrennen, die der Schattenhammer dort verteilt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKrone der Erdenmutter"}
MultiLanguageQuestData['de'][28477] = {title = "Zwielichtränke", objective = "Benutzt die leuchtende Fackel, um 8 Abschriften des Glaubensbekenntnisses des Schattenhammers im Domizil der Schwarzfelstiefen zu zerstören.", description = "Unsere Feinde schmieden in den Schwarzfelstiefen Pläne gegen uns. Die Schattenhammerkultisten beten und händigen Bücher an die Zwerge aus, die ihnen sagen, dass die Zeit für einen Krieg gekommen sei. Mit den Truppen der Dunkeleisenzwerge im Rücken hätte der Schattenhammer eine fast unbesiegbare Streitmacht. Wir müssen dieser Aufwiegelei ein Ende setzen!\n\nIch möchte, dass Ihr in das Domizil der Schwarzfelstiefen geht und diese Fackel benutzt, um die Bücher des Schattenhammers zu verbrennen!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKrone des Schattenwandlers"}
MultiLanguageQuestData['de'][28478] = {title = "Zwielichtränke", objective = "Benutzt die leuchtende Fackel, um 8 Abschriften des Glaubensbekenntnisses des Schattenhammers im Domizil der Schwarzfelstiefen zu zerstören.", description = "Es war ihren Meistern nicht genug, die Welt zu zerbrechen, nein! Der Schattenhammer bemüht sich mit aller Macht, unsere Feinde gegen uns zu vereinen, vor allem in den Schwarzfelstiefen. Sie haben eine ganze Horde von Gesandten dorthin geschickt, um ihre schmutzige Propaganda für einen gemeinsamen Angriff zu verteilen.\n\nMan sagt ja immer, dass das Medium die Botschaft selbst wäre. Nun, dann ist es an der Zeit, die Botschaft zu zerstören!\n\nIch möchte, dass Ihr in das Domizil der Schwarzfelstiefen geht und diese Fackel benutzt, um die Bücher des Schattenhammers zu verbrennen!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKrone der goldenen Anbetung"}
MultiLanguageQuestData['de'][28479] = {title = "Die Ruinen von Kel'Theril", objective = "Sprecht mit dem Kaldoreigeist auf dem Kel'therilsee in Winterquell.", description = "An diesem See wurde der Kristall von Zin-Malor von den Hochgeborenen gestohlen. Der Kristall war ein mächtiges Artefakt, das arkane Magie auf wilde und nicht vorhersehbare Weise biegen konnte... doch es konnte nur von den Würdigen verwendet werden und stürzte alle anderen ins Verderben.\n\nDie Geister, die hier umherstreifen, umspannen ganze Generationen, die alle von Zin-Malor an diesen Ort gefesselt wurden. Einige sprechen und erzählen von ihrem Schicksal.\n\nFalls Ihr etwas über das Schicksal von Zin-Malor erfahren möchtet, sucht den Geist in der Mitte des Sees auf...", progress = nil, completion = "Bemitleidet mich, Fremder, und all die Hochgeborenen, denn an diesem Ort begann unsere Dummheit... Unsere Dummheit, die unsere Kinder verfluchte und die Kinder unserer Kinder bis zum heutigen Tag.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28480] = {title = "Offiziere der Dunkelheit", objective = "Tötet Skorpionfürst Namkhare und Hohepriester Sekhemet.", description = "Die Armeen von Ramkahen werden von Nefersets unsterblichen Wächtern vernichtet.\n\nDer einzige Weg, sie zu besiegen, besteht darin, den dunklen Pharao von Neferset zu töten.\n\nBevor wir jedoch zuschlagen, müssen wir erst seine Offiziere aus dem Weg räumen.\n\nBegebt Euch hinter die Kampflinien und tötet Skorpionfürst Namkhare und Hohepriester Sekhemet. Nur dann werden wir dem dunklen Pharao selbst gegenübertreten können.", progress = nil, completion = "Ihr seid ein wertvoller Verbündeter, &lt;Name&gt;. Wir sind der Vernichtung unseres Feindes einen Schritt näher gekommen.", rewards = "Armbrust mit eingesetzten SkarabäenAuf Euch wartet eine dieser Belohnungen:\n\nSiegel von Sekhemet\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28482] = {title = "Sullahs Geschenk", objective = "Sprecht mit Harrison Jones an der Pilgerklippe.", description = "Jonesy hat mir erzählt, dass Ihr beide auf den Berg dort hinauf müsst.\n\nNun, solange diese Soldaten dort überall wie Ameisen auf einer Leiche herumwuseln, wird Euch das kaum gelingen.\n\nEinige meiner Freunde konnten etwas Ausrüstung von unseren Feinden stehlen. Das sollte Eure Reise etwas erleichtern.\n\nBegebt Euch hinauf auf den Grat im Norden und Ihr werdet die Ausrüstung finden.\n\nViel Glück, Euch beiden!", progress = nil, completion = "Schön, dass Ihr es geschafft habt, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28483] = {title = "Lasst den Feind bluten", objective = "Sammelt 10 Insignien aus Neferset.", description = "Ich werde Euch nicht belügen, <Name>. Vor uns liegt eine riesige Herausforderung.\n\nWenn Ihr Euch in Neferset hinter feindliche Linien begebt, müsst Ihr mir die Insignien dieses Nefersetabschaums mitbringen.\n\nEs wäre ein Segen für unsere Armeen, wenn sie wüssten, dass Ihr dem Feind einen verheerenden Schlag versetzt habt.", progress = "Schön, Euch wiederzusehen, <Name>.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Unsere Truppen werden von Euren Taten erfahren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28484] = {title = "Eine Herzensangelegenheit", objective = "Sammelt 12 schlagende Yetiherzen.", description = "Der Magus ist schon zu lange unbeschäftigt, und unbeschäftigte Magier führen oft zu schlecht geplanten Intrigen. Dieses Mal ist es meine Aufgabe, verschiedene Tierorgane als Energiequelle für eine Art Kontrollstab zu sammeln. Ich bin viel zu zart, um auf Bestienjagd zu gehen, besonders wenn es sich dabei um Yetis handelt!\n\nWenn ich Euch eine Belohnung anbiete, würdet Ihr das dann übernehmen? Ihr müsst nur nach Westen in die Yetihöhlen gehen und Yetis töten. Reißt ihnen die noch schlagenden Herzen aus der Brust und bringt sie mir.", progress = "Bringt mir Yetiherzen, <Name>.", completion = "Ich... äh... nun... Es hat sich herausgestellt, dass er keine Herzen mehr braucht. Tut mir leid! Ich hoffe, Ihr hattet nicht allzu viele Probleme. Aber abgemacht ist abgemacht, also hier Eure Belohnung. Ihr dürft die Yetiherzen behalten. Wie ich höre haben sie ausgezeichnete Nährwerte, falls Ihr so etwas mögt.", rewards = "Bel'varils ArmbänderWeiche YetigamaschenTratscharmschienenIhr bekommt:\n\nYetischockenherzen"}
MultiLanguageQuestData['de'][28485] = {title = "Yetimus der Yetifürst", objective = "Besorgt Yetimus' verdrehtes Horn.", description = "Viele Jahre lang durften die Yetis in dieser Gegend sich selbst regieren. Unsere Selbstzufriedenheit in der Handhabung der Yetibedrohung hat jedoch zu einer Fehlentwicklung geführt. Yetimus, der Fürst aller Yetis, ist so groß und stark geworden, dass unsere Wache ihn einfach nicht mehr unter Kontrolle hat. Wenn sein Appetit ihn nach Tarrens Mühle führt, wird er uns vermutlich alle verschlingen.\n\nVersammelt eine Gruppe streitbarer Recken und beseitigt diese Bestie. Er streift im Westen durch das Land.\n\nBringt mir eines seiner Hörner und ich werde Euch fürstlich entlohnen.", progress = "Yetimus muss sterben!", completion = "Also ist es wahr! Ihr habt die Bestie getötet. Die Bewohner des Hügellands stehen in Eurer Schuld, &lt;Name&gt;. Ihr habt das Land sicherer für unsere Bürger gemacht.\n\nNehmt aus unseren Kisten, was immer Euer Herz begehrt.", rewards = "Yetimus MaximusSchild des ungezügelten AppetitsAuf Euch wartet eine dieser Belohnungen:\n\nTarrens Kugel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28486] = {title = "Salhets Schachzug", objective = "Begleitet den Waldläuferhauptmann von Ramkahen an einen höher gelegenen Ort.", description = "Neferset ist zu gut verteidigt. Der Berg daneben jedoch nicht.\n\nIch habe mit dem Waldläuferhauptmann gesprochen. Er ist bereit, den strategisch gut gelegenen Berggipfel mit einigen seiner Leute zu sichern.\n\nEs gibt jedoch einen Haken, <Name>. Er hat zwar zugestimmt, aber nur, wenn Ihr die Angriffsspitze bildet.\n\nEs muss eine kleine Gruppe sein, sonst ziehen wir zu früh die Aufmerksamkeit des Feindes auf uns, aber vertraut mir... die Waldläufer von Ramkahen sind so hart im Nehmen, wie es nur geht. Mit Euch an ihrer Seite werden wir sicher Erfolg haben.", progress = "Grüße, <Name>!", completion = "Ihr habt es geschafft, &lt;Name&gt;! Ausgezeichnet!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28487] = {title = "Humberts persönliche Probleme", objective = "Holt Humberts Schwert, Humberts Helm und Humberts Hose zurück.", description = "Also, das ist mir ein wenig peinlich. Wo soll ich nur anfangen?\n\nNun, seht Ihr, Melisara hat mich ausgeschickt, um die Yetibedrohung in den nahegelegenen Höhlen westlich von hier auszukundschaften. Es war schon spät und meine Rüstung wurde mir so schwer. Ich habe meine Sachen abgelegt und beschloss, mich ein wenig umzusehen. Ja, ich, äh, habe einen kleinen Spaziergang gemacht. Als ich jedenfalls zurückkam, waren meine Sachen gestohlen! Es waren die Yetis. Ich bin mir ganz sicher. Sie haben meine Hose, mein Schwert und meinen Helm genommen und sind in ihre Höhle geflüchtet. Bringt sie mir wieder, und ich werde Euch belohnen.", progress = "Ich bin hier fast nackt, <Name>. Helft mir, ja?", completion = "Vielen Dank, &lt;Name&gt;. Ich verspreche, dass ich diese Sachen nie wieder ablegen werde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28488] = {title = "Unter der Oberfläche", objective = "Beschafft einen riesigen Rubinkristallklumpen.", description = "In den Bruchtiefen, weit außerhalb unserer Reichweite, gibt es viele wertvolle Edelsteine, unter anderem auch riesige Rubinkristallklumpen. In ihnen steckt eine schreckliche Energie.\n\nEin solcher Klumpen wird schwer zu beschaffen sein, denn sie werden streng bewacht. Aber Ihr seid stur und tapfer. Ich glaube, Ihr könntet es schaffen.\n\nSucht in den Bruchtiefen nach Orten, an denen die Tunnel abrupt in Stein übergehen. Wenn überhaupt, werdet Ihr die Klumpen dort finden. Solltet Ihr einen entdecken, dann bringt ihn mir.", progress = "Diese Kristalle sind sehr wertvoll, vor allem für Gorsik. Sollte ich einen bekommen, werde ich große Macht über ihn gewinnen. Ich möchte, dass das geschieht.", completion = "Genau danach habe ich gesucht. Danke, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28489] = {title = "Hirschbrötchen", objective = "Besorgt 8 Stück Hirschfleisch.", description = "Schon mal ein Hirschbrötchen gegessen? Ich auch nicht. Schmeckt angeblich toll. Essen interessiert mich nicht, Geschäfte schon. Meine Gäste wollen Hirschbrötchen, also kriegen sie welche.\n\nWahrscheinlich fragt Ihr Euch: \"Was geht mich das an?\". Die Antwort, <Klasse>, lautet: Ich brauche Hirschfleisch! Ich bezahle Euch für jedes Stück Hirschfleisch, das Ihr mir von den Hügelhirschen des Hügellands bringt. Ist doch ein gutes Geschäft, oder?\n\nLegt los! Im Westen gibt es die meisten Hirsche.", progress = "Ich brauche Hirschfleisch!", completion = "Ihr schleppt ja ganz schön was mit Euch herum. Das sollte meine Gäste für eine Weile zufriedenstellen.\n\nUnd wie versprochen: Hier, Eure Bezahlung.", rewards = "Ihr bekommt:\n\nHirschbrötchenHirschbrötchenmesser"}
MultiLanguageQuestData['de'][28490] = {title = "Heldenaufruf: Dunkelküste!", objective = "Meldet Euch bei Priesterin Dentaria in Lor'danel in Dunkelküste.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Priesterin Dentaria in Lor'danel in Dunkelküste einzufinden.\n\nDie Einwohner von Lor'danel müssen sich um die kümmern, die Auberdines Zerstörung überlebt haben, und ihre Stadt vor dem Schattenhammer schützen. Dazu benötigen sie Eure Hilfe. Sprecht mit Vesprystus, dem Hippogryphenmeister in Rut'theran, außerhalb von Darnassus und erwerbt einen Flug nach Dunkelküste.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Der König hat unser Flehen erhört? Elune sei Dank! Wir können alle Hilfe gebrauchen, die man uns gewährt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28491] = {title = "Nicht Stubenfliegen, Flammenfliegen", objective = "Beschafft 7 Flammenfliegen.", description = "Die meisten Bewohner verlassen den Flammenkamm früher oder später. Die Brennende Steppe ist ihnen wohl nicht SPANNEND genug.\n\nDas sehe ich anders. Ich finde immer einen Grund hier zu bleiben. Der neueste sind die Flammenfliegen, die seit kurzem hier auftauchen.\n\nBei Tag findet man sie nahe der Lava. Nachts sind sie fast überall.\n\nWenn Ihr Lust hättet, welche zu sammeln, würde sich das für Euch lohnen.", progress = "Und?", completion = "Gute Arbeit! Neue Haustiere für Kibler!", rewards = "StreichelhandschuheFlammenfliegenschiftungLavastiefelAuf Euch wartet eine dieser Belohnungen:\n\nKiblers Apportierspielzeug\n\nIhr bekommt außerdem:\n\nWinzige Flammenfliege"}
MultiLanguageQuestData['de'][28492] = {title = "Heldenaufruf: Eschental!", objective = "Meldet Euch bei Schildwache Shyela bei Orendils Zuflucht im nordwestlichen Eschental.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Schildwache Shyela in Orendils Zuflucht im nordwestlichen Eschental einzufinden.\n\nDie Übergriffe der Horde auf Eschental müssen aufhören! Eure Hilfe wird benötigt. Schlagt die Eindringlinge zurück und heilt den heiligen Wald. Reist nach Süden durch das Zwielichttal in Dunkelküste, um zum Wald von Eschental zu gelangen.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Seid Ihr hier, um uns gegen die Streitkräfte der Horde zu unterstützen? Jede Klinge und jeder Zauber sind willkommen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28493] = {title = "Auf Befehl des Kriegshäuptlings: Eschental!", objective = "Meldet Euch bei Kadrak am Schutzwall von Mor'shan zwischen dem Nördlichen Brachland und Eschental.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Kadrak am Schutzwall von Mor'shan zwischen dem Nördlichen Brachland und Eschental zu melden. Helft, die Nachtelfen aus dem Wald zu vertreiben, damit unser Volk seine Ressourcen nutzen kann!\n\nIhr erreicht den Schutzwall von Mor'shan, indem Ihr vom Wegekreuz im Nördlichen Brachland die Goldstraße Richtung Norden nehmt.\n\nDas Schicksal ruft!", progress = nil, completion = "Ihr seid also die Verstärkung? Soll mir recht sein, solange Ihr Nachtelfen töten könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28494] = {title = "Auf Befehl des Kriegshäuptlings: Nördliches Brachland!", objective = "Meldet Euch bei Kargal Schlachtnarbe in der Fernwacht im Nördlichen Brachland.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Kargal Schlachtnarbe in der Fernwacht im Nördlichen Brachland zu melden.\n\nEure Hilfe wird bei der Verteidigung des Brachlands gegen eindringende Stacheleber und Zentauren benötigt.\n\nDie Fernwacht erreicht Ihr, indem Ihr westlich durch die Südstromaue von Durotar reist und die Brücke ins Nördliche Brachland nehmt.\n\nDas Schicksal ruft!", progress = nil, completion = "Ihr seht aus, als könntet Ihr mit einer Waffe oder einem Zauberbuch umgehen. Helft uns, die Stacheleber aus dieser Gegend zu vertreiben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28495] = {title = "Selbstverteidigung", objective = "Rettet 10 Hügelkitze.", description = "Gesegnet sei das Licht! Ich brauche Eure Hilfe!\n\nAuf meinem Weg zum Hügellandhof bemerkte ich einige niedliche Rehfamilien. Ich wollte gerade ein kleines Kitz streicheln, als eine Bergkatze hervorsprang und es tötete. Ich floh nach Tarrens Mühle und schwor mir, das Leid der Hügelkitze zu lindern. Tagelang probierte ich herum, aber jetzt habe ich eine Lösung für die Hügelkitze gefunden!\n\nNehmt meinen Zauberstab, geht zu den Feldern im Westen und gebt den kleinen Hügelkitzen Kraft. Dann werden sie in der Lage sein, sich selbst zu helfen!", progress = nil, completion = "WAS!? Sagt das nicht, &lt;Name&gt;! Das kann nicht sein! Mein... Ich... Ich würde nie...\n\nIch gebe nicht auf, &lt;Klasse&gt;. Wartet nur ab. Ich werde diese Rehkitze retten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28496] = {title = "Auf Befehl des Kriegshäuptlings: Azshara!", objective = "Meldet Euch bei Arbeitsaufseher Grabbit am Hinteren Tor von Orgrimmar in Azshara.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Ag'tor Blutfaust am Hinteren Tor von Orgrimmar in Azshara zu melden.\n\nHelft bei der Vertreibung der Allianzstreitkräfte und sichert Azshara zum Ruhm der Horde!\n\nVerlasst Orgrimmar durch das nördliche Tor, um zum Hinteren Tor von Orgrimmar in Azshara zu gelangen.\n\nDas Schicksal ruft!", progress = nil, completion = "Wir können Hilfe gut gebrauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28497] = {title = "Feuer vom Himmel", objective = "Tötet 100 Soldaten von Schnottz, während Ihr auf der konfiszierten Artillerie sitzt.", description = "Sullah meinte es ernst. Auf dem Hügel wimmelt es von Truppen!\n\nSpringt auf und markiert die Ziele für mich.\n\nJeder Schuss muss sitzen, <Name>! Der Weg nach oben muss frei sein.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;.\n\nMal sehen, ob wir es nach oben schaffen, bevor sie sich erholen.", rewards = "Kanopische BrustplattePulververbrannte SchiftungAuf Euch wartet eine dieser Belohnungen:\n\nKonfiszierte Erkennungsmarken\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28498] = {title = "Das Geheimnis von Nahom", objective = "Beschafft 8 von Atulhets Aufzeichnungsfragmenten.", description = "Es gibt eine alte Geschichte über Nahom. Darin geht es um einen mächtigen Propheten namens Atulhet, der dem Ansturm seiner Feinde standhielt, indem er die Kraft der Sonne durch diesen Tempel hier leitete.\n\nDie meisten halten diese Geschichte für eine Legende, aber eine solche Macht... könnte uns jetzt sehr von Nutzen sein.\n\nDie abscheulichen Neferset haben Atulhets Grab geplündert. Sie haben alle Artefakte der Macht an sich genommen und die Tafeln, die seine Erinnerungen verschlüsselten, zerschlagen.\n\nGeht zu den Gräbern der Wegbereiter östlich von hier und bergt alle Fragmente, die Ihr findet.", progress = "Habt Ihr sie gefunden, <Name>? Konntet Ihr sie bergen?", completion = "Hervorragend. Schauen wir mal, ob wir etwas Wichtiges finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28499] = {title = "Bestraft die Eindringlinge", objective = "Tötet 10 beliebige Eindringlinge von Neferset an den Gräbern der Wegbereiter.", description = "Wir, die Priester von Nahom, bewachen die Gräber der Wegbereiter.\n\nSeit sich die Neferset ihrem neuen Herren unterworfen haben, begehen sie große Frevel.\n\nAuf der Suche nach mächtigen Artefakten plündern sie die Gräber unserer Vorväter und zerstören dabei wertvolle Relikte.\n\nSucht die Grüfte östlich von hier auf und bestraft die Grabräuber. Sie dürfen sich ihren Brüdern nicht anschließen, wenn die Neferset Nahom angreifen.", progress = nil, completion = "Vielleicht seid Ihr wirklich so mächtig, wie ich gehört habe.\n\nEuch gebührt unser Dank.", rewards = "Zeremonienhammer von RamkahenSchulterplatten des GrabhütersGamaschen des erbarmungslosen GrabesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28500] = {title = "Die Chiffre von Keset", objective = "Beschafft die Chiffre von Keset.", description = "<Priester scharen sich um Salhet, als er die Tafeln betrachtet.>\n\nEs ist alles hier, <Name>. Atulhet baute eine mächtige Waffe in diesen Tempel ein. Ohne die korrekte Chiffre kann man sie nicht benutzen.\n\nAngeblich wurde sie auf dem Kesetpass versteckt. Hoffentlich haben die Plünderer von Neferset sie noch nicht gefunden. Räuberfürst Havat regiert dort. Er ist der skrupelloseste von allen.\n\nOhne Verstärkung könnte die Waffe jedoch unsere einzige Hoffnung bei der Verteidigung von Nahom sein.", progress = "Habt Ihr den Kodex gefunden, <Name>?", completion = "Es stimmt also? Es gibt ihn wirklich!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSonnenleuchten\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28501] = {title = "Die Verteidigung von Nahom", objective = "Sprecht mit einem Unteroffizier der Ramkahen und verteidigt Nahom bis zum Sieg.", description = "Der Feind kommt... in großer Zahl.\n\nEs wird keine weitere Verstärkung geben. Hoffentlich können wir dem Angriff der Neferset standhalten.\n\nWenn Nahom fällt, wird Ramkahen folgen.\n\nGeht nach draußen und sprecht mit einem meiner Unteroffiziere, wenn Ihr bereit seid. Ich werde Euch mit all meinen Kräften bei der Führung der Streitkräfte unterstützen.", progress = nil, completion = "Geschafft, &lt;Name&gt;! Wir haben Nahom gehalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28502] = {title = "Der Kriegsherr der Banditen", objective = "Tötet Kriegsfürst Ihsenn.", description = "Unsere Gesetze verlangen, dass die Verantwortlichen für diesen Überfall bestraft werden.\n\nDer Anführer der Banditen wird Kriegsfürst Ihsenn genannt.\n\nIhr findet ihn ganz im Westen der Wüste. Sorgt dafür, dass seine Übergriffe nicht ungestraft bleiben.", progress = "Ihr seid zurück, <Name>.", completion = "Ich danke Euch, &lt;Name&gt;. Diese Barbaren müssen für ihre Taten bestraft werden.", rewards = "QuebnetschienbeinschützerHeptukopfschutzArmschienen der BanditengeißelIhsenns Stab des TerrorsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28503] = {title = "Heldenaufruf: Tausend Nadeln!", objective = "Meldet Euch bei Caryssia Mondjäger in Neu-Thalanaar an der Grenze zwischen Feralas und Tausend Nadeln", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Caryssia Mondjäger in Neu-Thalanaar an der Grenze zwischen Feralas und Tausend Nadeln einzufinden.\n\nDie Schildwachen benötigen Eure Unterstützung gegen die plündernden Räuber der Grimmtotem, die diese Gegend terrorisieren. Neu-Thalaanar erreicht Ihr, indem Ihr ins östliche Feralas reist, nahe der Grenze von Tausend Nadeln.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Ihr seid gerade rechtzeitig eingetroffen, &lt;Klasse&gt;. Wir brauchen Eure Hilfe, um die Grimmtotem aufzuhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28504] = {title = "Auf Befehl des Kriegshäuptlings: Tausend Nadeln!", objective = "Meldet Euch bei Nyse in Morastwinkel in den südlichen Düstermarschen.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Nyse in Morastwinkel zu melden. Schließt Euch den Hordenstreitkräften im Kampf gegen die rebellischen Grimmtotem an, die das Gebiet beherrschen.\n\nNyse wird für den Transport zur Front sorgen. Sie wartet auf Euch im Gasthaus von Morastwinkel, das versteckt in den südlichen Düstermarschen liegt.\n\nDas Schicksal ruft!", progress = nil, completion = "Die Streitkräfte der Horde in Tausend Nadeln brauchen dringend Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28505] = {title = "Die Schlacht um Andorhal", objective = "Sprecht mit Guthrum Donnerfaust und besorgt Euch einen Flug nach Andorhal in den Westlichen Pestländern. Meldet Euch dann bei Thassarian in Andorhal.", description = "Ich habe Neuigkeiten, <mein Freund/meine Liebe>. Es sieht nicht gut aus.\n\nDie Stadt Andorhal steckt mitten in einem dreiseitigen Krieg zwischen den Verlassenen, der Allianz und der Geißel. König Wrynn hat den Stein ins Rollen gebracht und einen seiner Todesritter entsandt, um den Sturmangriff für seine Sache zu leiten. Dennoch bin ich sicher, dass er jede Hilfe gebrauchen kann.\n\nIch lasse Euch nicht gern gehen, aber man hat Euch speziell angefordert, <Name>. Sprecht draußen mit Guthrum Donnerfaust. Er wird Euch auf den ersten Greifen nach Andorhal setzen.", progress = nil, completion = "Das wurde auch Zeit, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28506] = {title = "Der Marsch der Sturmlanzen", objective = "Beobachtet den Marsch der Sturmlanzen.", description = "Die Pläne, die Ihr besorgt habt, erzählen eine interessante Geschichte, <Name>. Seit über einem Monat verlegen die Sturmlanzen ihre Armeen vom Alteractal in die \"vier Finger\" des Hügellands. Es ist ihnen gelungen, ohne das Wissen unserer Streitkräfte dort Anlagen zu errichten. Hätten wir diese Pläne nicht bekommen, wären sie uns in einer Woche entgegenmarschiert und hätten alles auf ihrem Weg vernichtet.\n\nDank dieser Pläne können wir den Spieß umdrehen.\n\nWir müssen Folgendes tun...", progress = nil, completion = "Wir müssen jetzt handeln. Die Sturmlanzen müssen vernichtet werden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28507] = {title = "Heldenaufruf: Tanaris!", objective = "Meldet Euch bei Kelsey Stahlblitz in Gadgetzan in Tanaris.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Kelsey Stahlblitz in Gadgetzan einzufinden.\n\nDie Allianz braucht Eure Hilfe, um Zugeständnisse des ortsansässigen Barons und Zugriff auf die wertvollen Ressourcen der Gegend zu bekommen. Nach Gadgetzan kommt Ihr, indem Ihr Euch von der Schimmernden Tiefe in Tausend Nadeln nach Süden wendet.\n\nFür den Ruhm und die Ehre der Allianz!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28508] = {title = "Die Schlacht um Andorhal", objective = "Sprecht mit Kellen Kuhn und fliegt nach Andorhal in den Westlichen Pestländern. Meldet Euch dann bei Koltira Todeweber in Andorhal.", description = "Ich habe gerade eine merkwürdige Nachricht erhalten. Wirklich merkwürdig...\n\nDie Stadt Andorhal steckt mitten in einem dreiseitigen Krieg zwischen den Verlassenen, der Allianz und der Geißel. Sylvanas hat anscheinend die Initiative ergriffen. Das Interessante daran ist, dass sie Todesritter Koltira Todesweber das Kommando übertragen hat.\n\nMan hat speziell nach Euch gefragt, <Name>. Sprecht mit Kellen Kuhn, dem Fledermausführer. Er wird Euch auf die erste Fledermaus nach Andorhal setzen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28509] = {title = "Auf Befehl des Kriegshäuptlings: Tanaris!", objective = "Meldet Euch bei Megs Schredderschreck in Gadgetzan in Tanaris.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich bei Megs Schredderschreck in Gadgetzan zu melden. Sorgt dafür, dass die Horde und das Bilgewasserkartell Tanaris besetzen, bevor die Allianz das tut!\n\nNach Gadgetzan kommt Ihr, indem Ihr Euch von Fizzels und Pozziks Turbodampfer in Tausend Nadeln nach Süden zum Strand wendet.\n\nDas Schicksal ruft!", progress = nil, completion = "Ich könnte Eure Hilfe brauchen, &lt;Klasse&gt;. Diese verdammte Gnomenfrau versucht das Dampfdruckkartell auf ihre Seite zu ziehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28510] = {title = "Auf Befehl des Kriegshäuptlings: Feralas!", objective = "Meldet Euch bei Konu Runentotem in Camp Ataya in Feralas.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Konu Runentotem in Camp Ataya in Feralas zu melden. Helft der Horde, den großen Wald gegen die Allianz und die Grimmtotem zu verteidigen.\n\nIhr erreicht Camp Ataya, indem Ihr von Desolace südlich nach Feralas reist.\n\nDas Schicksal ruft!", progress = nil, completion = "Es gibt viele Probleme in Feralas. Eure Hilfe ist mir willkommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28511] = {title = "Heldenaufruf: Feralas!", objective = "Meldet Euch bei Telaron Windsegler in Träumersruh in Feralas.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Telaron Windsegler in Träumersruh in Feralas einzufinden.\n\nDie Allianz braucht Eure Hilfe im Kampf gegen unsere Feinde, die Horde und die Grimmtotem. Ihr erreicht Träumersruh, indem Ihr von Desolace südlich nach Feralas reist.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Eure Ankunft ist ein Zeichen von Elune, &lt;Klasse&gt;. Es gibt viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28512] = {title = "Hilfe für die Thoriumbruderschaft", objective = "Sprecht mit Jack Felsbein am Thoriumvorstoß in der Sengenden Schlucht.", description = "Die Dunkeleisenzwerge sind zwar intrigant und boshaft... aber nicht alle sind unsere Feinde. Ich habe schon einige Male mit den Zwergen der Thoriumbruderschaft gesprochen und sie waren stets hilfsbereit.\n\nEin Freund von mir, Jack Felsbein, kam vor kurzem in die Stadt und fragte, ob ich ihn auf eine Art Expedition begleiten würde. Es klang wichtig.\n\nIch habe gerade zu tun, aber vielleicht möchtet Ihr ja mitgehen? Reist nach Westen, zur Straße, die in die Sengende Schlucht führt. Ihr werdet ihn kurz hinter dem Ödland finden.", progress = nil, completion = "Na, was haben wir denn hier? Wollt Ihr helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28513] = {title = "Der Stolz der Hochgeborenen", objective = "Tötet 8 gepeinigte oder leidende Hochgeborene.", description = "Vor zehntausend Jahren...\n\n... lebten die Hochgeborenen hier in großem Wohlstand. Wir blickten herab auf die gewöhnlichen Nachtelfen. Magie und Reichtum erfüllten all unsere Bedürfnisse. Wir gaben uns den Begierden und der Ablenkung hin. Und der Gier...\n\nDie Geister, die Ihr hier seht, sind erfüllt von Reue und Bedauern. Ihre Pein kettet sie hier fest. Wenn Ihr mehr von Kel'theril und Zin'malor erfahren wollt, müsst Ihr sie aus ihrer Not befreien.", progress = "Der Tod ist nicht immer eine Erleichterung.", completion = "Der Kristall von Zin-Malor wurde ohne Skrupel aus einem weit entfernten Tempel gestohlen. Mit ihm konnte man das Arkane kontrollieren. Wir fieberten danach, spielten mit ihm und als er zerbrach, kam der Fluch über uns alle. Kel'theril litt, bis die Zerschlagung den Kristall endgültig zerstörte.\n\nDer Fluch von Zin-Malor fesselt alle, die hier nach seiner Macht suchen. Ich erlag als erstes der Versuchung. Tausende Jahre später traf es unsere lang verlorenen Nachfahren...", rewards = "Dolch des LeidensAuf Euch wartet eine dieser Belohnungen:\n\nAmulett des KaldoreigeistesRing von Zin-Malor\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28514] = {title = "Mouton Flammenstern", objective = "Meldet Euch bei Mouton Flammenstern am Flammensternposten in der Brennenden Steppe.", description = "Heutzutage verlasse ich die Sengende Schlucht kaum noch. Seit Monaten möchte ich einen Freund in der Brennenden Steppe besuchen, aber ich komme einfach nicht dazu.\n\nSein Name ist Mouton Flammenstern. Er ist zwar kein Mitglied der Bruderschaft, aber ein guter Freund und sehr vertrauenswürdig.\n\nKönntet Ihr ihm meine Grüße ausrichten? Ihr müsst nach Süden gehen, durch den Fuß des Schwarzfels. Reist immer weiter gen Süden, dann findet Ihr ihn.\n\nDanke.", progress = nil, completion = "Oh, Schlickfaust schickt Euch? Hah!\n\nWisst Ihr, weshalb man ihn Schlickfaust nennt? Fragt ihn einmal danach.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28515] = {title = "Mouton Flammenstern", objective = "Meldet Euch bei Mouton Flammenstern am Flammensternposten in der Brennenden Steppe.", description = "Heutzutage verlasse ich die Sengende Schlucht kaum noch. Seit Monaten möchte ich einen Freund in der Brennenden Steppe besuchen, aber ich komme einfach nicht dazu.\n\nSein Name ist Mouton Flammenstern. Er ist zwar kein Mitglied der Bruderschaft, aber ein guter Freund und sehr vertrauenswürdig.\n\nKönntet Ihr ihm meine Grüße ausrichten? Ihr müsst nach Süden gehen, durch den Fuß des Schwarzfels. Reist immer weiter gen Süden, dann findet Ihr ihn.\n\nDanke.", progress = nil, completion = "Oh, Schlickfaust schickt Euch? Hah!\n\nWisst Ihr, weshalb man ihn Schlickfaust nennt? Fragt ihn einmal danach.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28516] = {title = "Jahrhunderte des Leids", objective = "Sprecht mit dem Geist der Kaldorei in der Mitte des Kel'therilsees.Ich habe nur wegen der Gerüchte, der Kristall von Zin-Malor könnte hier zu finden sein, zugestimmt, über eine Kooperation mit den Nachtelfen und der Allianz nachzudenken.\n\nDer Kristall ist ein mächtiges, uraltes Artefakt, dessen Zerstörung das Land verflucht und dessen Zusammenfügung kaum Linderung gebracht hat.\n\nAber ich kann mich den Geistern, die dort hausen, nicht stellen. Verhöhnt mich ruhig, wenn es sein muss, oder versucht es selbst. Vielleicht werden die gelassenen Geister in der Mitte des Sees ja zu Euch sprechen...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ich habe nur wegen der Gerüchte, der Kristall von Zin-Malor könnte hier zu finden sein, zugestimmt, über eine Kooperation mit den Nachtelfen und der Allianz nachzudenken.\n\nDer Kristall ist ein mächtiges, uraltes Artefakt, dessen Zerstörung das Land verflucht und dessen Zusammenfügung kaum Linderung gebracht hat.\n\nAber ich kann mich den Geistern, die dort hausen, nicht stellen. Verhöhnt mich ruhig, wenn es sein muss, oder versucht es selbst. Vielleicht werden die gelassenen Geister in der Mitte des Sees ja zu Euch sprechen...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28517] = {title = "Die Heulende Eiche", objective = "Sprecht mit Genn Graumähne an der Heulenden Eiche in Darnassus.", description = "So, das ist sie... unsere neue Heimat. Vielleicht werde ich mich nirgends mehr wirklich zu Hause fühlen.\n\nDoch wir müssen den Nachtelfen dankbar sein. Ihr Volk heißt nicht jeden willkommen. Dass sie uns aufgenommen haben, spricht für ihr Vertrauen und ihren Großmut.\n\nGwen und Graumähne sind an der Heulenden Eiche in der eigentlichen Stadt. Sucht sie auf. Nehmt das Portal unter dem Baum nördlich von uns und begebt Euch zur Heulenden Eiche im Nordteil der Stadt.", progress = nil, completion = "Diese Eiche entstand mit Hilfe der Druiden aus einem Samen, der aus Gilneas kam. Sie steht für alles, was wir erlitten und alles, was wir erreicht haben.\n\nMöge sie uns stets daran erinnern, dass unser Fluch auch ein Segen ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28518] = {title = "Erbe der Hochelfen", objective = "Besorgt Zin-Malors Erinnerung vom Geist des Erzmagiers Maenius.", description = "Vor Einhundert Jahren...\n\nKam ich mit einer kleinen Gruppe anderer Hochelfen aus unserem Heimatland, Quel'thalas. Wir suchten nach den uralten Rätseln Kel'therils... wir wollten wissen, warum es zerstört wurde.\n\nWir entdeckten Fragmente im Eis - Splitter eines Kristalls. Der Erzmagier, der uns begleitete, erlag schnell ihrem Einfluss. Wir waren zu dumm, um es rechtzeitig zu erkennen.\n\nSein Geist wandert südöstlich von hier zwischen denen umher, die er in den Wahnsinn trieb. Er klammert sich immer noch an die Erinnerung seines geliebten Splitters...", progress = "Maenius war ein mächtiger Magier und ehrenwerter Elf. Sein Geist hatte ein so unwürdiges Schicksal nicht verdient.", completion = "Wir waren entsetzt, bevor wir starben. Entsetzt, weil jemand aus unserem edlen und nüchternen Volk so rasch in teuflische Besessenheit verfallen war. Wir starben als naive Narren, Opfer unserer unbekümmerten Voreingenommenheit.\n\nDie Lebenden wissen, dass sich diese Ereignisse wiederholen sollten... hier und mit dem Fall von Quel'thalas im gesamten Elfenvolk.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28519] = {title = "Der Schmerz der Blutelfen", objective = "Tötet 7 elende Geister oder elende Schreckgespenster am Kel'therilsee.", description = "Vor einem Jahr...\n\n... erreichte die Legende des Kristalls von Zin-Malor Silbermond. Ich führte eine Gruppe der besten Krieger und Gelehrten in dieses Land. Wir brachten genügend Manakristalle mit, so dass niemand versucht sein würde, den Kristall zu probieren.\n\nDoch auch ohne unseren Hunger verderbte uns der Kristall. Als wir ihn in Besitz nahmen, verwandelte er alle außer mir in elende Bestien.\n\nDie elenden Geister wandern noch immer umher und suchen nach Lebenden, die sie an diesen See ketten können. Werdet Ihr sie von ihrem Leid erlösen... oder fliehen, um eines Tages auf sicherem Boden zu sterben?", progress = nil, completion = "Der lebende Weltenwanderer, der Euch hierher schickte, ertrug es nicht, unser Schicksal zu sehen. Er lief davon... eine weise Entscheidung.\n\nWenn nun wieder jemand den Kristall von Zin-Malor in Händen hält, werden alle in seiner Nähe verloren sein. Er hätte nie wieder zusammengefügt werden dürfen.", rewards = "Dolch der Elenden GespensterKlinge der elenden GeisterStreitkolben des Sin'doreigeistesIhr bekommt:\n\nKugel von Kel'theril"}
MultiLanguageQuestData['de'][28520] = {title = "Der Fall von Neferset", objective = "Tötet den dunklen Pharao Tekahn in Neferset in Uldum.", description = "Wir sind bereit zum Angriff, <Name>.\n\nWenn wir den dunklen Pharao Tekahn töten, werden die unsterblichen Kolosse fallen und unseren Armeen den Weg nach Neferset ebnen.\n\nFindet und greift ihn furchtlos an. Ich werde dafür sorgen, dass Ihr nicht allein seid, wenn die Zeit seines Untergangs gekommen ist.", progress = nil, completion = "Es ist vollbracht. Wir haben die Neferset in ihrer eigenen Stadt geschlagen.\n\nIch wünschte, nun könnte mein Volk endlich in Frieden leben, aber es wird noch mehr Blutvergießen geben.", rewards = "Stulpen der gefallenen BruderschaftWickeltuch der gefallenen StadtTuch der Zerstörung von NefersetAuf Euch wartet eine dieser Belohnungen:\n\nHalskette der toten Stadt\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28521] = {title = "Sprecht mit Salfa", objective = "Reist durch die Holzschlundfeste und verlasst sie in Winterquell. Sprecht mit Salfa, der den Eingang zur Holzschlundfeste bewacht.", description = "Nicht nur die Furbolgs der Totenwaldfelle im Süden bedrohen uns mit der Verderbnis, sondern sie lauert auch im Osten und bei den Furbolgs der Winterfelle in Winterquell. Sprecht mit Salfa am Winterquelleingang auf der anderen Seite der Feste, wenn Ihr uns weiterhin unterstützen wollt. Ihr gelangt über den linken Pfad dorthin.", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt; - Ich wache hier als Sprecher der Holzschlundfeste hier in Winterquell und als Verteidiger meines Stammes.\n\nUnsere Brüder, die Winterfelle, sind in diesem eisigen Land von der gleichen Verderbnis heimgesucht worden wie die Furbolgs von Teufelswald. &lt;Solltet Ihr den Furbolgs der Holzschlundfeste helfen wollen, würden wir dieses Angebot annehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28522] = {title = "Aktivität der Winterfelle", objective = "Beschafft 10 Geisterperlen von Furbolgs der Winterfelle.", description = "Die Furbolgs der Holzschlundfeste bleiben meist unter sich, <Name>. Wir gewähren allen, die ihre Vertrauenswürdigkeit unter Beweis gestellt haben, freies Geleit, meiden aber, wenn möglich, andere Furbolgstämme.\n\nDer Winterfellstamm zeigt uns gegenüber immer größere Feindseligkeit. Sie scheinen in Rage zu sein und ganz von ihrer Furcht und dem Hass auf alles beseelt, das sie nicht verstehen.\n\nDie Winterfelle tragen Geisterperlen bei sich, die sie offensichtlich nicht vor der Verderbnis schützen konnten. Bringt mir 10 dieser Perlen als Beweis dafür, dass Ihr ihre Reihen ausgedünnt habt.", progress = "Wir danken Euch für alles, was Ihr für die Holzschlundfeste getan habt, <Name>. Helft uns auch weiterhin, dann werdet Ihr Euch das Vertrauen und den Respekt meines Stammes verdienen.", completion = "Ich danke Euch für Eure Dienste, auch wenn sie mich traurig stimmen. Nehmt dies als Zeichen meines Danks.\n\nIch hoffe, dass Ihr uns auch weiterhin unterstützt, &lt;Name&gt;. Wir haben nur wenige Verbündete und ohne Eure Hilfe könnten wir die Gefahren, die meinem Stamm drohen, nicht bewältigen.", rewards = "Handschuhe des ErdwächtersHandschuhe des PfadfindersWeste des HöhlenbehütersUrsas UmarmungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28523] = {title = "Mehr Perlen für Salfa", objective = "Mein Vertrauen habt Ihr, <Name>, aber das meines misstrauischen Stamms müsst Ihr Euch weiterhin verdienen. Es gibt etwas, mit dem Ihr dieses Vertrauen erlangen könnt.\n\nDie Winterfelle tragen Geisterperlen, die sie vor bösen Geistern beschützen sollen. Diese Perlen sind ihrem Zweck nicht gerecht geworden, da die Winterfelle selbst nun die Verderbnis verbreiten. Bringt mir die Geisterperlen gefallener Furbolgs der Winterfelle. Jeweils fünf Perlen werden Euren Ruf bei der Holzschlundfeste verbessern.", description = nil, progress = "Mein Vertrauen habt Ihr, <Name>, aber das meines misstrauischen Stamms müsst Ihr Euch weiterhin verdienen. Es gibt etwas, mit dem Ihr dieses Vertrauen erlangen könnt.\n\nDie Winterfelle tragen Geisterperlen, die sie vor bösen Geistern beschützen sollen. Diese Perlen sind ihrem Zweck nicht gerecht geworden, da die Winterfelle selbst nun die Verderbnis verbreiten. Bringt mir die Geisterperlen gefallener Furbolgs der Winterfelle. Jeweils fünf Perlen werden Euren Ruf bei der Holzschlundfeste verbessern.", completion = "Wieder einmal beweist Ihr uns Eure Ehrenhaftigkeit! Ich werde dafür sorgen, dass Eure Taten sich bei meinem Volk herumsprechen.\n\nVergesst nicht, mir alle Winterfellperlen zu bringen, die Ihr findet. Jedes Mal, wenn Ihr mir neue Perlen bringt, werde ich mich in unserem Stamm für Euch einsetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28524] = {title = "Lieferung für Donova", objective = "Bringt Salfas Korb zu Donova Schneeweh in Winterquell.", description = "Donova Schneeweh ist eine großherzige Zwergenfrau, die häufig bei den heißen Quellen zu finden ist. Sie sagt, sie würde ihre magischen Eigenschaften untersuchen.\n\nSie ist gütig und wird gern in unserem Stamm gesehen. Als die Winterfelle feindseliger wurden, begann sie nach der Ursache ihrer Verderbnis zu forschen.\n\nIch kann meinen Posten nicht verlassen, aber ich möchte ihr einen Korb mit Erfrischungen geben. Bitte bringt ihn ihr an meiner Stelle und sagt Ihr, dass wir ihren nächsten Besuch erwarten.", progress = "Willkommen bei den heißen Quellen. Was habt Ihr denn da?", completion = "Diese Furbolgs sind wirklich nett. Sie tun mir Leid. Aus Angst vor der Welt verstecken sie sich in ihrer Feste.\n\nIch kann sie verstehen. Die Furbolgs der Winterfelle sind ebenso feindselig geworden wie die im Teufelswald. Ich möchte, dass das aufhört... nicht nur wegen meiner Recherchen, sondern auch wegen meiner Freunde in der Holzschlundfeste.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28525] = {title = "Heldenaufruf: Krater von Un'Goro!", objective = "Meldet Euch bei Williden Marschall an Marschalls Wehr im Krater von Un'Goro.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Williden Marschall an Marschalls Wehr einzufinden.\n\nIhr sollt im Namen der Allianz Marschalls Expeditionen unterstützen, die die Geheimnisse uralter Bestien, einzigartiger Flora und mächtiger Kristalle ergründen wollen. Den Krater erreicht Ihr, wenn Ihr das westliche Tanaris verlasst und der Straße bis nach Marschalls Wehr folgt.\n\nFür den Ruhm und die Ehre der Allianz!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28526] = {title = "Auf Befehl des Kriegshäuptlings: Krater von Un'Goro!", objective = "Meldet Euch bei Williden Marschall an Marschalls Wehr im Krater von Un'Goro.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Williden Marschall an Marschalls Wehr zu melden. Unterstützt Marschalls Expeditionen bei der Entdeckung der Geheimnisse des Kraters von Un'Goro. Vielleicht wird die Horde die einzigartigen Bestien und Kristalle in diesem Krater in irgendeiner Weise verwenden können.\n\nDen Krater erreicht Ihr, wenn Ihr die Straße nehmt, die aus dem westlichen Tanaris in den Krater führt und ihr bis nach Marschalls Wehr folgt.\n\nDas Schicksal ruft!", progress = nil, completion = "Willkommen, &lt;Klasse&gt;. Meine Wissenschaftler und Entdecker werden für Eure Hilfe dankbar sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28527] = {title = "Auf Befehl des Kriegshäuptlings: Silithus!", objective = "Meldet Euch bei Windruferin Prachthorn in Burg Cenarius in Silithus.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Windruferin Prachthorn in Burg Cenarius zu melden. Unterstützt unsere Verbündeten in ihrem Kampf gegen den Schattenhammer. Cho'galls Handlanger dürfen Silithus nicht beherrschen!\n\nUm nach Silithus zu gelangen, müsst Ihr der nordwestlichen Straße aus dem Krater von Un'Goro folgen.\n\nDas Schicksal ruft!", progress = nil, completion = "Willkommen in Burg Cenarius.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28528] = {title = "Heldenaufruf: Silithus!", objective = "Meldet Euch bei Windruferin Prachthorn in Burg Cenarius in Silithus.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Windruferin Prachthorn in Burg Cenarius einzufinden.\n\nUnsere Verbündeten vom Zirkel des Cenarius benötigen Eure Unterstützung im Kampf gegen den Schattenhammer. Ihr gelangt nach Silithus, indem Ihr die nordwestliche Straße aus dem Krater von Un'Goro nehmt.\n\nFür den Ruhm und die Ehre der Allianz!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28529] = {title = "Schriftstücke der Leere", objective = "Bringt die Schriften des dunklen Herolds zu Waldläuferin Glynda Nal'Shea in Lor'danel.", description = "Die Schriften sind vage und scheinen Teil eines größeren Rätsels zu sein. Ihr vermutet jedoch, dass sie einige Angaben über den zu beschreitenden Weg, ein Dämonenjäger zu werden, enthalten.\n\nDie meisten Nachtelfen lehnen die dunklen Schwüre und Rituale ab, die angehende Dämonenjäger benötigen, also würden sie diese Schriften wahrscheinlich gern geheim halten.\n\nWaldläuferin Glynda Nal'Shea wird wissen, was mit diesen Schriftrollen anzufangen ist.", progress = "Was kann ich für Euch tun, <Klasse>?", completion = "Wo habt Ihr die gefunden?! Ihr habt sie doch niemand anderem gezeigt, oder?\n\nEntschuldigt. Ihr habt mich auf dem falschen Fuß erwischt. Telarius war ein mächtiger Dämonenjäger, der vor vielen Jahren im Kampf gegen Maiev, den Aufseher, fiel. Ihr habt Glück, dass sein Geist nur noch ein Schatten seiner selbst war. Ich frage mich, wie viele den Weg zu ihm in den Ruinen gefunden haben.\n\nIch werde dafür Sorge tragen, dass diese Schriftrollen sofort zur Hohepriesterin gebracht werden. Danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28530] = {title = "Brühende Zeichen", objective = "Beschafft 7 Stücke verdächtigen grünen Schlick von brühenden Quellbrandern oder kochenden Quellgurglern.", description = "In diesem Kessel scheint sich konzentriertes Material befunden zu haben. Wenn die Winterfelle dieses Zeug in den Quellen verdünnen, würden sie mit der Zeit verseucht werden... wodurch die Lösung zunehmend an Wirksamkeit verlieren würde.\n\nAn der Quelle nordöstlich von hier wimmelt es von Elementaren. Ich dachte, das hinge mit dem Kataklysmus zusammen, doch es könnte auch eine Reaktion darauf sein.\n\nWürdet Ihr bei ihnen nach Anzeichen der Verderbnis suchen? Jagt einige Elementare und bringt mir den fremdartigen grünen Stoff, den sie hinterlassen.", progress = "Was habt Ihr gefunden?", completion = "Das ist ziemlich viel... die Winterfelle rutschen stetig weiter ab. Und nun müssen wir uns auch noch um die anderen Wildtiere sorgen, aber eines nach dem anderen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28531] = {title = "Heldenaufruf: Desolace!", objective = "Meldet Euch bei Jankie in Tethris Aran in Desolace.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Offizier Jankie auf der Straße nach Desolace in Tethris Aran einzufinden.\n\nDie mutigen Soldaten der Nijelspitze werden von Dämonen und den Armeen der Horde heimgesucht. Sie brauchen Eure Hilfe. Nehmt die Straße nach Süden, die aus dem Verbrannten Tal im Steinkrallengebirge führt, dann gelangt Ihr nach Desolace.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Ich kann Euch auf schnellstem Weg zur Nijelspitze bringen! Wir brauchen dringend Verstärkung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28532] = {title = "Auf Befehl des Kriegshäuptlings: Steinkrallengebirge!", objective = "Meldet Euch bei Blutwache Aldo Steinregen in der Silberwindzuflucht im Eschental.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Blutwache Aldo Steinregen in der Silberwindzuflucht im Eschental zu melden. Ihr müsst die Streitkräfte der Horde im Steinkrallengebirge in ihrem Kampf gegen die Eindringlinge der Allianz verstärken und unser Volk beschützen. Die Blutwache wird Euch den Weg zur Grenze des Steinkrallengebirges weisen.\n\nUm die Silberwindzuflucht zu erreichen, müsst Ihr ins Herz des Eschentals reisen und Euch unseren Streitkräften nahe des Sees anschließen.\n\nDas Schicksal ruft!", progress = nil, completion = "Lasst Ihr Euch ins Steinkrallengebirge versetzen? Gut. Wir werden Eure Fähigkeiten brauchen, um den Sieg über die Allianz davonzutragen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28533] = {title = "Die Entscheidung des hohen Rates", objective = "Sprecht mit König Phaoris in Ramkahen in Uldum.", description = "Der hohe Rat wird nun seine Entscheidung über den Krieg gegen den Stamm der Neferset fällen.", progress = nil, completion = "Nun gut, dann ist es wohl Zeit. Seht ruhig zu, wenn es Euch beliebt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSummon High Council Event Camera\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28534] = {title = "Nachkommen der Hochgeborenen", objective = "Sprecht mit dem Geist der Quel'dorei.", description = "Kurz nach meinem Tod wurde mein Volk wegen seiner Gier verbannt. Einen Kontinent entfernt wurden aus ihnen die Quel'dorei, die Hochelfen. In Quel'thalas sonnten sie sich in der Macht ihres Sonnenbrunnens und vergaßen das Verlangen und die Gier, die ihnen anhafteten.\n\nDie Hand des Schicksals führte ihre weit entfernten Nachkommen hierher und zwang sie, die Geschichte zu wiederholen. Hört ihre Geschichte, so wie ich es getan habe...", progress = nil, completion = "Wir waren stolz und edel. Unser Glaube an das Licht schützte uns und der Sonnenbrunnen gab uns alles, was wir wollten.\n\nDiese Blindheit war schuld daran, dass wir an diesem Ort unsere tragische Geschichte wiederholen mussten - und später unser gesamtes Volk.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28535] = {title = "Nachkommen der Hochelfen", objective = "Sprecht mit dem Geist der Sin'dorei.", description = "Lange nach meinem Tod beging mein Volk einen noch größeren Fehler. Die Hochelfen verließen sich auf den Sonnenbrunnen in all seiner Glorie. Wir konnten uns eine Welt ohne ihn nicht vorstellen, deshalb trafen wir nie Vorkehrungen für einen solchen Fall.\n\nAls der Sonnenbrunnen schließlich den Untoten in die Hände fiel, waren meine Nachkommen verloren und hilflos... der Weg, den sie daraufhin einschlugen, sollte sie auf ewig verändern.\n\nDie Sin'dorei, die immer noch nach Wiedergutmachung strebten, kamen ebenfalls hierher...", progress = nil, completion = "Wir waren nicht so naiv wie unsere Vorväter. Wir waren misstrauisch und listig und witterten überall Verrat.\n\nDoch unser Stolz und unsere Gier trieben uns wieder in den Untergang. Wie viele werden Kel'theril noch zum Opfer fallen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28536] = {title = "Der Fluch von Zin-Malor", objective = "Kehrt zu Kelek Himmelshüter am Kel'therilsee in Winterquell zurück.", description = "Ihr habt genug gesehen. Der Kristall von Zin-Malor bringt allen in seiner Nähe nichts als Unglück.\n\nVerlasst diesen Ort, wenn Ihr nicht wie wir werden wollt.", progress = nil, completion = "Der Schatten! Ja, ich habe ihn auch gesehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28537] = {title = "Jagd auf Schatten", objective = "Jagt und tötet den Schatten des Geistsprechers und sucht nach Hinweisen auf seinen Meister.", description = "Ihr sagt, er habe von einem Meister gesprochen? Einem, der Zin-Malor besitzt?\n\nDas sind schlimme Neuigkeiten. Ihr müsst handeln, <Klasse>! Ich sah den Schatten gen Süden fliegen. Nehmt den Pfad zu den oberen Ruinen und versucht den gefroreren Wasserfall dahinter zu besteigen!\n\nUnd seid vorsichtig... er wartet vielleicht auf Euch.", progress = "Habt Ihr den Schatten gefunden? Gab es Hinweise auf seinen Ursprung?", completion = "Lasst mal sehen... zwischen den eingravierten Beschwörungen steht kaum erkennbar der Name seines Meisters!\n\n\"Umbranse...\"", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28538] = {title = "Der Schrei der Banshee", objective = "Fasst 10 SI:7-Agenten mit Hilfe des Bansheespiegels.", description = "Ihr sollt also unser Retter sein? Nun denn, ich werde mich mit Euch verbinden. Durch diese Verbindung kann ich durch Eure Augen blicken und mit Euch dort draußen kommunizieren.\n\nLaut der Pläne, die Ihr uns gebracht habt, nehmen die Sturmlanzen die Hilfe von SI:7 bei Soferas Landspitze nördlich von hier in Anspruch. SI:7 besteht vollständig aus Menschen - Menschen, die wir zu unserem Vorteil nutzen können.\n\nNehmt meinen Spiegel und geht nach Norden. Kämpft gegen Mitglieder von SI:7, bis sie dem Tode nahe sind. Benutzt den Spiegel, wenn sie verwundet sind.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28539] = {title = "Heldenaufruf: Steinkrallengebirge!", objective = "Meldet Euch bei Jägerin Jalin an der Sternenstaubspitze im Eschental.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Jägerin Jalin an der Sternenstaubspitze im Eschental einzufinden.\n\nDie Streitkräfte der Horde versuchen, ins Steinkrallengebirge vorzudringen. Wir müssen sie aufhalten! Die Sternenstaubspitze liegt im südlichen Teils des Eschentals, nahe der Grenze zum Steinkrallengebirge.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Die Horde hat einen riesigen Pass in die Berge geschlagen. Wir können kaum Schildwachen entbehren. Wir müssen sie irgendwie aufhalten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28540] = {title = "Bärenstarke E'komagie", objective = "Beschafft Reifpelz' Herz.", description = "Mau'ari macht seit Jahren Glücksbringer aus den Geistern der Wildnis. Mau'ari PFLÜCKT das E'ko einfach aus den Tieren und macht Glücksbringer für die Kinder und die Abenteurer.\n\nIm Osten gibt es einen großen Hügel, der von Splitterzahnbären umzingelt wird. Auf dem Hügel lebt Reifpelz, der älteste Bär des Waldes.\n\nMau'ari braucht den Bär für ihre Magie. Bringt mir das große, alte Herz des Bären.", progress = "Habt Ihr den Bären erwischt? Lasst mal seh'n.", completion = "Das ist ein schönes, großes Herz! Mau'ari kann Euch zeigen, wie man das E'ko kriegt....", rewards = "Gürtel des E'kosammlersHerzgreiferSchiftung des HexendoktorsBärenjägergürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28542] = {title = "Auf Befehl des Kriegshäuptlings: Teufelswald!", objective = "Meldet Euch bei Tenell Laubschleicher im Smaragdrefugium in Teufelswald.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Tenell Laubschleicher im Smaragdrefugium in Teufelswald zu melden. Der Zirkel des Cenarius versucht, Teufelswald den Dämonen und anderen verderbten Kreaturen zu entreißen. Eure Hilfe wird benötigt! \n\nDas Smaragdrefugium liegt nördlich von Eschental. Folgt der Straße bis zum Refugium.\n\nDas Schicksal ruft!", progress = nil, completion = "Willkommen. Meine Brüder und ich widmen uns der Erlösung und Wiederbelebung dieses einst heiligen Waldes.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28543] = {title = "Heldenaufruf: Teufelswald!", objective = "Meldet Euch bei Tenell Laubschleicher im Smaragdrefugium im Teufelswald.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Tenell Laubschleicher im Smaragdrefugium einzufinden.\n\nVon Euch wird verlangt, den Teufelswald von den dämonischen Kräften zu befreien, die den Wald beherrschen. Begebt Euch in den Norden des Eschentals und folgt der Straße zum Teufelswald, bis Ihr das Smaragdrefugium erreicht.\n\nFür den Ruhm und die Ehre der Allianz!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28544] = {title = "Heldenaufruf: Winterquell!", objective = "Meldet Euch bei Donova Schneeweh an den Frostfeuerquellen in Winterquell.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Donova Schneeweh an den Frostfeuerquellen einzufinden.\n\nHelft ihr, die Bedrohung durch die Winterfelle abzuwenden. Reist aus dem nördlichen Teufelswald gen Osten und durch die Holzschlundfeste nach Winterquell.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Gut, dass Ihr hier seid. Ich habe das Geheimnis der aggressiven Winterfelle entdeckt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28545] = {title = "Auf Befehl des Kriegshäuptlings: Winterquell!", objective = "Meldet Euch bei Donova Schneeweh an den Frostfeuerquellen in Winterquell.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Donova Schneeweh an den Frostfeuerquellen zu melden. Sie hat etwas über die Furbolgs der Winterfelle herausgefunden, das uns bei der Beseitigung dieser Bedrohung helfen könnte.\n\nDie Frostfeuerquellen liegen in Winterquell. Reist aus dem nördlichen Teufelswald nach Osten und durchquert die Holzschlundfeste.\n\nDas Schicksal ruft!", progress = nil, completion = "Ich glaube zu wissen, weshalb die Furbolgs der Winterfelle so stark geworden sind, aber ich hoffe, dass Ihr meinen Entdeckungen Sinn verleihen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28548] = {title = "Auf Befehl des Kriegshäuptlings: Desolace!", objective = "Meldet Euch bei Furien in Tethris Aran in Desolace.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Furien in Tethris Aran in Desolace zu melden. Die tapferen Hordenkrieger von Desolace brauchen Eure Hilfe. Ihnen stehen die Armeen der Allianz und uralte Dämonen gegenüber.\n\nNehmt die Straße nach Süden, die aus dem Verbrannten Tal im Steinkrallengebirge führt, dann gelangt Ihr nach Tethris Aran.\n\nDas Schicksal ruft!", progress = nil, completion = "Ihr... kommt gerade noch... rechtzeitig...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28549] = {title = "Auf Befehl des Kriegshäuptlings: Südliches Brachland!", objective = "Meldet Euch bei Nura Pfadfinder auf dem Höhenpfad im Südlichen Brachland.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Nura Pfadfinder auf dem Höhenpfad im Südlichen Brachland zu melden. Die Allianz hat in letzter Zeit einige Siege im Brachland erfochten. Nun drohen sie unsere Nachschublinien abzuschneiden. Dann säßen unsere Krieger fest. Wir müssen handeln!\n\nReist aus dem Steinkrallengebirge gen Osten, dann gelangt Ihr zum Höhenpfad.\n\nDas Schicksal ruft!", progress = nil, completion = "Ihr dürftet bemerkt haben, was die Allianz dem Brachland angetan hat, &lt;Klasse&gt;. Wenn wir nicht handeln, wird es hier bald keine Horde mehr geben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28550] = {title = "Heldenaufruf: Südliches Brachland!", objective = "Meldet Euch bei Kommandant Walpole am Steinkrallenpass im nordwestlichen Teil des Südlichen Brachlands.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Kommandant Walpole am Steinkrallenpass im Südlichen Brachland einzufinden.\n\nUnsere tapferen Soldaten sind tief ins Brachland vorgestoßen, doch dafür haben sie einen hohen Preis bezahlt! Sie benötigen Eure Hilfe, um das eroberte Land zu halten. Reist im Steinkrallengebirge südöstlich durch das Hochwipfeltal, dann gelangt Ihr ins Südliche Brachland.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Tagtäglich schlagen wir uns mit schweren Gegenangriffen der Horde herum, &lt;Klasse&gt;. Eine helfende Hand können wir sehr gut gebrauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28551] = {title = "Heldenaufruf: Südliches Brachland!", objective = "Meldet Euch bei Dockmeister Lewis vor der Feste Nordwacht im Südlichen Brachland.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Dockmeister Lewis nahe der Feste Nordwacht einzufinden.\n\nUnsere tapferen Soldaten sind tief ins Brachland vorgestoßen, doch dafür haben sie einen hohen Preis bezahlt! Sie benötigen Eure Hilfe, um das eroberte Land zu halten. Zu den Docks vor der Feste Nordwacht gelangt Ihr, indem Ihr das Schiff von Beutebucht nach Ratschet nehmt und dann entlang der Küste in südliche Richtung reist.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Die Horde leistet starken Widerstand, &lt;Klasse&gt;. Jede Verstärkung ist uns willkommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28552] = {title = "Heldenaufruf: Düstermarschen!", objective = "Meldet Euch bei Calia Hastings auf der Insel Theramore in den Düstermarschen.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Calia Hastings auf der Insel Theramore einzufinden.\n\nUnterstützt Calia Hastings vom SI:7 bei der Suche nach den Gefahren, die im Inneren von Theramore und außerhalb seiner Mauern lauern. Die Insel Theramore erreicht Ihr entweder, indem Ihr in Menethil ein Schiff besteigt oder vom Südlichen Brachland durch die Marschen reist.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Desertierte Stadtwachen sorgen für Unzufriedenheit bei den Soldaten. Wir müssen dem auf den Grund gehen, bevor unsere Verteidigungsfähigkeit beeinträchtigt wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28553] = {title = "Okrilla und die Verwüsteten Lande", objective = "Meldet Euch bei Kriegsmatrone Okrilla in Feste Schreckenfels in den Verwüsteten Landen.", description = "Ich muss Euch eine letzte Nachricht überbringen, <Name>. Sie stammt aus der Feste Schreckensfels in den Verwüsteten Landen südlich von hier.\n\nKriegsmatrone Okrilla kämpft gegen die Allianzstreitkräfte von Burg Nethergarde. Sie benötigt Unterstützung, <ein beherzter/eine beherzte:c> <Klasse> wird gebraucht. Da hat man sofort an Euch gedacht.\n\nReist gen Süden in die Verwüsteten Lande, dann weiter nach Westen. Viel Glück, <Name>.", progress = nil, completion = "Nun, seht mal an... unter welchem Stein hat man Euch denn gefunden?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28554] = {title = "Auf Befehl des Kriegshäuptlings: Düstermarschen!", objective = "Meldet Euch bei Krog in Brackenwall in den Düstermarschen.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Krog in Brackenwall zu melden. In den Marschen wimmelt es von den unterschiedlichsten Feinden und die Streitkräfte der Allianz sind gefährlich stark.\n\nDie Düstermarschen erreicht Ihr, indem ihr dem Pfad im östlichen Teil des Südlichen Brachland in Richtung Brackenwall folgt.\n\nDas Schicksal ruft!", progress = nil, completion = "Wenn wir den Sumpf unter Kontrolle bringen, könnten wir die Allianz angreifen, während die meisten ihrer Truppen im Brachland beschäftigt sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28555] = {title = "Weist die Abgesandten aus", objective = nil, description = "<Not yet implemented.>Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28556] = {title = "Brecht die Hand", objective = "Platziert eine goblinische Hosentaschenbombe bei Soferas Landspitze, Corrahns Dolch, der Landzunge und Gavins Landspitze.", description = "Wenn wir die Übergriffe der Sturmlanzen beenden wollen, müssen wir ihnen die Finger brechen.\n\n<Cromush reicht Euch ein kleines Paket.>\n\nIn dem Paket befinden sich vier starke Sprengladungen der Goblins. Infiltriert die vier Finger - Soferas Landspitze, Corrahns Dolch, die Landzunge und Gavins Landspitze - und platziert in jedem eine goblinische Hosentaschenbombe.\n\nWenn Ihr das getan habt - und alles andere, um das Melisara Euch bittet - kehrt zu mir zurück.", progress = nil, completion = "Wenn Melisara mit Euch fertig ist, werden wir die Sprengladungen zünden!", rewards = "Soferas GürtelGavins SchulterstückeCorrahns UmhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28557] = {title = "Auf Befehl des Kriegshäuptlings: Uldum!", objective = "Sprecht mit Adarrah im Disteltal im westlichen Tanaris.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Adarrah im Disteltal in Tanaris zu melden.\n\nIn uralten Schriften ist zu lesen, dass in Uldum unfassbare Reichtümer und unvergleichliche Schätze liegen. Geht hin und holt sie Euch im Namen der Horde!\n\nIhr könnt Adarrahs Karawane erreichen, indem ihr in den südwestlichen Teil von Tanaris reist und dort im Disteltal nach ihr sucht.\n\nDas Schicksal ruft!", progress = nil, completion = "Ihr könntet seit Jahrtausenden einer der ersten Sterblichen sein, die Uldum betreten. Denkt nur an die Schätze, die auf uns warten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28558] = {title = "Heldenaufruf: Uldum!", objective = "Sprecht mit Adarrah im Disteltal im westlichen Tanaris.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Adarrah im Disteltal in Tanaris einzufinden.\n\nSchließt Euch denen an, die als erste das ruhmreiche Uldum betreten und seine Schätze im Namen der Allianz an sich bringen!\n\nAdarrahs Karawane erreicht Ihr, indem Ihr zu den westlichen Ausläufern Tanaris' reist.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Jenseits dieses Tals warten Wunder nur darauf entdeckt zu werden! Sie werden uns gehören!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28559] = {title = "Heldenaufruf: Blutmythosinsel!", objective = "Meldet Euch bei Vorkhan dem Elekktreiber in Kessels Wegelager auf der Blutmythosinsel.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Vorkhan dem Elekktreiber in Kessels Wegelager einzufinden.\n\nHelft den Bewohnern der Blutmythosinsel im Kampf gegen verräterische Blutelfen und gefährliche Kreaturen, die auf der Insel ihr Unwesen treiben. Kessels Wegelager liegt auf der Blutmythosinsel. Reist zur Azurmythosinsel und nehmt die Brücke nach Norden.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Wollt Ihr uns helfen? Es gibt viel zu tun...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28560] = {title = "Auf Befehl des Kriegshäuptlings: Geisterlande!", objective = "Meldet Euch bei Arkanist Vandril in Tristessa in den Geisterlanden.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Arkanist Vandril in Tristessa in den Geisterlanden zu melden.\n\nWerft die zahllosen Eindringlinge der Geißel zurück und sichert Euch die Hilfe der Verlassenen im Kampf gegen unseren gemeinsamen Feind.\n\nNehmt die Straße, die von Morgenluft nach Süden in die Geisterlande führt, um nach Tristessa zu gelangen.\n\nDas Schicksal ruft!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28561] = {title = "Nahom muss gehalten werden", objective = "Meldet Euch beim Regiment in Nahom in Uldum.", description = "Wenn wir nach Westen aufbrechen, um Neferset anzugreifen, wird der Feind unsere Schwäche im Osten ausnutzen und dort zuschlagen.\n\nNahom wird als erstes fallen und dann Ramkahen.\n\nEin kleiner Stoßtrupp ist bereits dort.\n\nDie Soldaten werden Euch alles erklären. Sorgt dafür, dass sie Nahom halten, bis ich weitere Truppen schicken kann.", progress = nil, completion = "&lt;Name&gt;! Ihr seid es! Mein Regiment wurde auf dem Weg hierher angegriffen.\n\nUnser Hauptmann wurde getötet und ich musste das Kommando übernehmen... aber jetzt seid Ihr ja da!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28562] = {title = "Heldenaufruf: Westfall!", objective = "Meldet Euch bei Leutnant Horatio Laine auf Jansens Hof in Westfall.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Leutnant Horatio Laine auf Jansens Hof einzufinden.\n\nWestfall wird von Bettlern und Vertriebenen überrannt, was zu einem massiven Anstieg der Kriminalität geführt hat. Helft bei der Wiederherstellung der öffentlichen Ordnung. Jansens Hof liegt in Westfall, westlich des Walds von Elwynn.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Mord, Grünschnabel. Genau das seht Ihr auf dem Boden vor Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28563] = {title = "Heldenaufruf: Rotkammgebirge!", objective = "Meldet Euch bei Wachhauptmann Parker an der Turmwacht im Rotkammgebirge.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Wachhauptmann Parker an der Turmwacht im Rotkammgebirge einzufinden.\n\nHauptmann Parkers Truppen werden von umherstreifenden Gnollen und Orcs angegriffen. Die Bewohner von Seenhain sind in Gefahr. Helft bei ihrem Schutz. Reist von der Grenze des Walds von Elwynn durch Drei Ecken im Rotkammgebirge bis nach Turmwacht.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Hab gehört, dass Westfall tief im Dreck steckt.\n\n&lt;Parker dreht sich noch nicht einmal zu Euch um.&gt;\n\nNa ja, wir haben hier unsere eigenen Probleme. Seht Ihr die Gnolle da draußen? Die führen doch wieder was im Schilde. Gefällt mir nicht. Gefällt mir ganz und gar nicht.", rewards = "Parkers ZollstockGürtel der unlösbaren ProblemeKlemmenstiefelUnglückselige TreterIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28564] = {title = "Heldenaufruf: Dämmerwald!", objective = "Meldet Euch bei Kommandantin Althea Schwarzhaupt in Dunkelhain im Dämmerwald.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Kommandantin Althea Schwarzhaupt in Dunkelhain einzufinden.\n\nDie Wachen der Kommandantin reichen nicht aus, um gleichzeitig gegen umherstreunende Wölfe und Banden wilder Worgen zu kämpfen. Ohne Eure Hilfe werden sie nicht mehr lange durchhalten. Wendet Euch auf der Straße an der Grenze zwischen dem Wald von Elwynn und dem Rotkammgebirge nach Süden, um nach Dunkelhain im Dämmerwald zu gelangen.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Ihr seid die Hilfe, die wir angefordert haben?\n\n&lt;Althea seufzt.&gt;\n\nDann müsst Ihr uns wohl genügen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28565] = {title = "Heldenaufruf: Sumpfland!", objective = "Meldet Euch bei Gebirgsjäger Rharen in Dun Algaz.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Gebirgsjäger Rharen in Dun Algaz einzufinden.\n\nDer Kataklysmus und seine Zerstörungen haben wilde Bestien, Orcräuber und grausame Gnolle ins Sumpfland gelockt! Reist von Loch Modan nach Norden durch die Zwergenfestung Dun Algaz, dann gelangt Ihr ins Sumpfland.\n\nFür den Ruhm und die Ehre der Allianz!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28566] = {title = "Dezimierung", objective = "Tötet Hauptmann Eisherz und 12 Soldaten der Sturmlanzen.", description = "<Melisaras Abbild erscheint vor Euch.>\n\nDas Vorauslager der Sturmlanzen befindet sich auf Corrahns Dolch, westlich von Soferas Landspitze. Dringt in das Lager ein und tötet jeden Zwerg, den Ihr seht. Sie müssen lernen, was Furcht bedeutet und es gibt keine bessere Lektion als völlige Dezimierung.\n\nKeine Überlebenden, <Name>. Auch ihr Hauptmann - insbesondere ihr Hauptmann - muss sterben.\n\nIch werde Euch kontaktieren.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28567] = {title = "Heldenaufruf: Loch Modan!", objective = "Meldet Euch bei Pilot Hammerfuß am Südtoraußenposten in Loch Modan.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Pilot Hammerfuß am Südtoraußenposten einzufinden.\n\nSeit der Zerstörung des Damms und der Rückkehr der Kobolde und Troggs, sind unsere Gebirgsjäger überfordert. Wir benötigen dringend Verstärkung! Nehmt den Südtorpass im östlichen Dun Morogh, dann gelangt Ihr zum Südtoraußenposten.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Haben unsere Anführer mein Flehen erhört? Wir verteidigen Loch Modan nur noch mit einer Handvoll Piloten und Gebirgsjägern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28568] = {title = "Auf Befehl des Kriegshäuptlings: Der Silberwald!", objective = "Meldet Euch bei Großexekutor Mortuus in der Kommandozentrale der Verlassenen im Silberwald.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Großexekutor Mortuus in der Kommandozentrale der Verlassenen im Silberwald zu melden.\n\nMehr denn je wird Eure Hilfe benötigt, um die Heimsuchung durch unsere Feinde in dieser Region zu beenden und den Hafen von Gilneas zu erobern!\n\nIhr müsst nach Süden durch Tirisfal reisen und Euch in den Silberwald begeben, um die Kommandozentrale der Verlassenen zu erreichen. Folgt der Straße im Silberwald nach Süden, bis Ihr die Kommandozentrale der Verlassenen erreicht.\n\nDas Schicksal ruft!", progress = nil, completion = "Sehr gut! Ein neuer Rekrut ist eingetroffen. Es gibt viel zu tun... in der Tat sehr viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28569] = {title = "Der Kraulsumpfexpress", objective = "Sprecht mit Sharon Bummhatse in der südöstlichen Ecke der Brennenden Steppe und erwerbt eine Fahrt im Kraulsumpfexpress zu den Sümpfen des Elends. Sprecht dann mit Handelsbaron Silberkniff in Kraulsumpf.", description = "Ich habe Gerüchte über eine Straße in die Sümpfe des Elends gehört. In diesen mysteriösen Geschichten wird von einem gewundenen Bergpfad gesprochen, der das Rotkammgebirge umgeht und Euch direkt in Kraulsumpf ausspuckt!\n\nWenn Ihr hier nichts mehr zu tun habt, müsst Ihr uns wohl verlassen. Was uns alle sehr traurig stimmen würde. Wenn Ihr geht, dann sprecht mit Sharon Bummhatse in der südöstlichen Ecke der Steppe. Sie wird für Euren Transport sorgen.\n\n<Oralius legt den Kopf schief, so als lausche er etwas.>\n\nWinky? WINKY! NEIN!", progress = nil, completion = "Zeit ist Geld, &lt;Klasse&gt;... und ich habe genug von beidem.\n\nWas kann ich für Euch tun?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28570] = {title = "Der Kraulsumpfexpress", objective = "Sprecht mit Sharon Bummhatse in der südöstlichen Ecke der Brennenden Steppe und erwerbt eine Fahrt im Kraulsumpfexpress zu den Sümpfen des Elends. Sprecht dann mit Handelsbaron Silberkniff in Kraulsumpf.", description = "Ihr seid <ein ziemlich großer/eine ziemlich große:r> <Volk>, richtig? Seht Euch an... wie erwachsen Ihr geworden seid. Dabei haben wir uns gerade erst kennengelernt!\n\nIch weiß, wie das läuft... bald wisst Ihr nicht mehr, was Ihr auf dem Flammenkamm machen sollt. Ihr versprecht zurückzukehren. Aber das macht Ihr nicht.\n\nKibler kennt das schon.\n\nWenn Ihr geht, dann sprecht mit Sharon Bummhatse in der südöstlichen Ecke der Steppe. Sie wird Euch im Express mitfahren lassen.\n\nWas? Och, das ist nur eine Rakete. Vollkommen sicher.", progress = nil, completion = "Zeit ist Geld, &lt;Klasse&gt;... und ich habe genug von beidem.\n\nWas kann ich für Euch tun?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28571] = {title = "Auf Befehl des Kriegshäuptlings: Das Vorgebirge des Hügellands!", objective = "Meldet Euch bei Hochexekutorin Darthalia am Südwachttor im Vorgebirge des Hügellands.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Hochexekutorin Darthalia am Südwachttor im Vorgebirge des Hügellands zu melden. Die Kriegsmaschine der Verlassenen marschiert unaufhaltsam weiter und sichert der Horde Lordaeron!\n\nFolgt der Straße durch den Silberwald in Richtung Süden und biegt an der Gabelung nach Osten in das Vorgebirge des Hügellands ab. Dort findet ihr die Südwacht.\n\nWeiter, <Bruder/Schwester>! Das Schicksal ruft!", progress = nil, completion = "Ich habe mich schon gefragt, wann die Verstärkung eintreffen würde. Macht Euch bereit, &lt;Name&gt;. Zeit, etwas Gerechtigkeit walten zu lassen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28572] = {title = "Auf Befehl des Kriegshäuptlings: Arathihochland!", objective = "Meldet Euch bei Dunkelläuferin Alina bei Galens Sturz im Arathihochland.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Dunkelläuferin Alina bei Galens Sturz zu melden. Die Streitkräfte der Dunklen Fürstin wollen das Herrschaftsgebiet der Horde vergrößern und die Allianz zurückschlagen. Helft ihnen dabei.\n\nDas Arathihochland liegt östlich des Vorgebirges des Hügellands. Folgt der Straße, die am Thoradinswall vorbeiführt.\n\nDas Schicksal ruft!", progress = nil, completion = "Endlich ist die Verstärkung des Kriegshäuptlings eingetroffen. Die Dunkle Fürstin hat für Euch ebenso große Pläne wie für uns.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28573] = {title = "Heldenaufruf: Arathihochland", objective = "Meldet Euch bei Hauptmann Nials in der Zuflucht im Arathihochland.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Hauptmann Nials in der Zuflucht einzufinden.\n\nDie Ehre der uralten Burg Stromgarde muss wiederhergestellt werden! Zu lange schon beschmutzen Oger und Kriminelle ihre Straßen. Verlasst das Sumpfland in Richtung Norden und benutzt den Thandolübergang, um nach Arathi zu gelangen. Folgt der Straße bis zur Zuflucht und stellt Euch dem Hauptmann vor.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Ich wünschte, Ihr wärt eine ganze Kompanie, aber es muss auch so gehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28574] = {title = "Auf Befehl des Kriegshäuptlings: Das Hinterland!", objective = "Meldet Euch beim Ältesten Stumpfhauer im Dorf der Bruchhauer im Hinterland.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend beim Ältesten Stumpfhauer im Dorf der Bruchhauer zu melden.\n\nDie Zwerge der Wildhämmer haben sich offiziell der Allianz angeschlossen. Das heißt, sie sind nun unsere Feinde. Sie müssen besiegt werden!\n\nBegebt Euch vom Gebirgspass im östlichen Vorgebirge des Hügellands ins Hinterland und begebt Euch zur östlichen Küste. Dort findet Ihr das Dorf der Bruchhauer.\n\nDas Schicksal ruft!", progress = nil, completion = "Seid Ihr gekommen, um uns gegen die Wildhämmer zu unterstützen? Der Kriegshäuptling weiß, dass das, was hier geschieht, wichtig für die Zukunft der Horde ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28575] = {title = "Auf Befehl des Kriegshäuptlings: Westliche Pestländer!", objective = "Meldet Euch bei Koltira Todesweber in Andorhal in den Westlichen Pestländern.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Koltira Todesweber in Andorhal zu melden.\n\nDie Streitkräfte der Allianz rücken auf die zerstörte Stadt Andorhal vor, um sie einzunehmen. Wir müssen ihren Angriff stoppen, bevor sie dort einen Stützpunkt errichten können.\n\nBegebt Euch hinter das Bollwerk am östlichen Rand von Tirisfal und folgt den Straßen in Richtung Südosten nach Andorhal. Schließt Euch dort unseren Streitkräften an.\n\nDas Schicksal ruft!", progress = nil, completion = "Mehr kann der Kriegshäuptling nicht entbehren? Keine Sorge, Ihr könnt Euch hier nützlich machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28576] = {title = "Heldenaufruf: Westliche Pestländer!", objective = "Meldet Euch bei Thassarian in Andorhal in den Westlichen Pestländern.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Thassarian in Andorhal einzufinden.\n\nNach unseren ersten Siegen in Andorhal holen die Verlassenen nun zum Gegenschlag aus. Eure Hilfe wird benötigt. Vertreibt die Geißel und die Horde und erobert die verlorene Stadt Andorhal zurück.\n\nIhr erreicht Andorhal, indem Ihr in Richtung Norden durch das Vorgebirge des Hügellands reist und der Straße folgt, die am Zugwindlager vorbeiführt.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Es gibt hier viel zu tun. Wir stehen zwei unbarmherzigen Feinden gegenüber, die uns gnadenlos abschlachten würden, wenn wir unsere Klingen niederlegten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28577] = {title = "Auf Befehl des Kriegshäuptlings: Östliche Pestländer!", objective = "Meldet Euch bei Fiona am Ostufer des Thondroril in den Östlichen Pestländern.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Fiona am Ostufer des Thondroril zu melden.\n\nDer Argentumkreuzzug hat seine Stellungen in den Pestländern ausgebaut. Eure Hilfe wird benötigt, um diese Siege zu sichern.\n\nÜberquert den Thondroril an der Ostgrenze der Westlichen Pestländer und sucht am anderen Ufer nach Fiona. \n\nDas Schicksal ruft!", progress = nil, completion = "Vielleicht könnt Ihr ja helfen, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28578] = {title = "Heldenaufruf: Östliche Pestländer!", objective = "Meldet Euch bei Fiona am Ostufer des Thondroril in den Östlichen Pestländern.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Fiona am Ostufer des Thondroril einzufinden.\n\nDer Argentumkreuzzug braucht Eure Hilfe, um die Östlichen Pestländer aus der Gewalt der Geißel zu befreien.\n\nUm die Östlichen Pestländer zu erreichen, müsst Ihr von den Westlichen Pestländern kommend den Thondroril überqueren. Sucht am Ostufer nach Fiona.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Vielleicht könnt Ihr ja helfen, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28579] = {title = "Heldenaufruf: Ödland!", objective = "Meldet Euch bei Gek Düsenschub an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Gek Düsenschub an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern einzufinden.\n\nDie Schäden, die Todesschwinge angerichtet hat, müssen begutachtet werden, ebenso die Aufstellung der Hordenstreitkräfte im Ödland. Dazu wird Eure Hilfe benötigt.\n\nIm Austausch für Eure Hilfe hat sich Gek bereiterklärt, Euch per Rakete ins Ödland zu bringen. Sucht nach ihm an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern..\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Ihr seid bestimmt hier, um Luntenbrand zu helfen! Ich bringe Euch sofort ins Ödland.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28580] = {title = "Auf Befehl des Kriegshäuptlings: Ödland!", objective = "Meldet Euch bei Gek Düsenschub an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Gek Düsenschub an der Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern zu melden.\n\nDie Allianz versucht verzweifelt, einen Stützpunkt im Ödland zu errichten. Eure Pflicht ist es, sie zurückzudrängen und Euch ein Bild von den Zerstörungen zu machen, die Todesschwinge angerichtet hat.\n\nGek wird Euch per Rakete ins Ödland befördern. Trefft ihn bei der Kapelle des Hoffnungsvollen Lichts.\n\nDas Schicksal ruft!", progress = nil, completion = "Natürlich kann ich Euch ins Ödland bringen, aber Ihr müsst mir versprechen, dort meinen Kameraden zu helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28581] = {title = "Auf Befehl des Kriegshäuptlings: Sengende Schlucht!", objective = "Meldet Euch bei Jack Felsbein am Thoriumvorstoß in der Sengenden Schlucht.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Jack Felsbein am Thoriumvorstoß zu melden.\n\nDie Zerschmetterte Hand meldet, dass die Dunkeleisenzwerge der Sengenden Schlucht sich auf etwas vorzubereiten scheinen. Es ist Eure Pflicht, so viel wie möglich über ihre Machenschaften herauszufinden und sie zu durchkreuzen.\n\nIhr erreicht die Sengende Schlucht, indem Ihr im Ödland der Straße nach Westen folgt.\n\nDas Schicksal ruft!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28582] = {title = "Heldenaufruf: Sengende Schlucht!", objective = "Meldet Euch bei Jack Felsbein am Thoriumvorstoß in der Sengenden Schlucht.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Jack Felsbein am Thoriumvorstoß einzufinden.\n\nSI:7 meldet, dass die Dunkeleisenzwerge der Sengenden Schlucht anscheinend einen Angriff vorbereiten. Es ist Eure Pflicht, so viel wie möglich über ihre Machenschaften herauszufinden und sie zu durchkreuzen. \n\nIhr erreicht die Sengende Schlucht, indem Ihr im Ödland der Straße nach Westen folgt.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Wir trauen den Dunkeleisenzwergen ebenfalls nicht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28583] = {title = "Krazzwerke", objective = "Bringt den Patentantrag zu Kapitän Krazz an den Krazzwerken im Schattenhochland.", description = "Das neue Schredderdesign ist der Hammer, <Name>. Der Hammer! Der nächste Schritt ist der Schutz meines gedanklichen Eigentums. Ich muss Patente ausfüllen, Marken zeichnen und Unterlassungen erklären. Oh, und Bestechung darf auch nicht fehlen!\n\nHier, bringt diesen Patentantrag zu Kapitän Krazz an den Krazzwerken. Er hat die Zerstörung seines Zeppelins überlebt und sucht wahrscheinlich nach neuen Geschäftsmodellen.\n\nDie Krazzwerke befinden sich nördlich von hier auf einem vollkommen sicheren Berggipfel. Auf geht's, <Junge/Mädchen>. Zack zack!", progress = "Euch kenne ich doch! Ihr wart bei der Hinreise mit mir auf dem Zeppelin.", completion = "Was ist das? Der \"&lt;Name&gt;-o-Matik:\" ein Schredder mit integrierter Raketenplattform?\n\nPah! Den hat Arbeitsaufseher Grabbit aus Azshara längst patentieren lassen. Das ist wertlos!\n\nWas ich wirklich brauche, ist eine Maschine, die Zwerge vom Himmel holt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28584] = {title = "Qualitätsarbeit", objective = "Versiegelt 10 defekte Ventile mit Dichtungsband.", description = "Hört mal zu, <Chef/Chefin>, wenn es diesen Vollidiot mir gegenüber nicht gäbe, wären die Krazzwerke in einem Topzustand.\n\nDummerweise - und so sehen das alle Beteiligten - hat \"Schickimicki\" Rothmann beschlossen, das Ding auf einem Berggipfel zu bauen! Wer kommt auf so eine Idee?\n\nJetzt gibt es überall Lecks, weil die Ventile defekt sind. Wärt Ihr vielleicht so nett, sie mit dem Dichtungsband zu versiegeln?", progress = nil, completion = "Na also. Wollen wir als nächstes Rothmanns Mund versiegeln?", rewards = "Handschuhe des wahnsinnigen PilotenSchutzhelm des TechnikersBrustschutz des KartografenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28586] = {title = "Poolponyrettung", objective = "Benutzt die Poolponys, um 10 Arbeiter der Krazzwerke, die ins Wasser gefallen sind, zu retten.", description = "Dieser Idiot mir gegenüber bringt noch alle um!\n\nBrett \"der Bomber\" hat die Krazzwerke am falschen Ort ausgepackt und jetzt sind sie extrem instabil. Bei den Explosionen, die durch die Instabilität entstehen, werden unsere Arbeiter von den Plattformen ins Wasser geschleudert.\n\nWärt Ihr so freundlich hinunterzufliegen und sie mit Hilfe einiger Poolponys zu retten, <Name>?", progress = nil, completion = "Danke, &lt;Name&gt;! Könnten wir doch nur die Krazzwerke stabilisieren, damit unsere Leute nicht mehr von den Plattformen geschleudert werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28587] = {title = "Die Hilfe der Frostwölfe", objective = "Sprecht mit Voggah Todesgriff im Alteracgebirge im Vorgebirge des Hügellands.", description = "Ich werde die Schlachtpläne der Sturmlanzen studieren und mich auf einen Überfall vorbereiten. Geht ins Alteractal und bittet den Frostwolfklan um Hilfe. Diesem Klan gehört sogar unser ehemaliger Kriegshäuptling Thrall an. Sie müssen uns im Kampf gegen die Zwerge der Sturmlanzen unterstützen! Gemeinsam werden wir die Eindringlinge in den Staub treten und für immer aus Lordaeron vertreiben!\n\nGeht jetzt, <Name>. Das Alteractal liegt nordöstlich von Tarrens Mühle. Findet Voggah Todesgriff und sagt ihm, dass die Horde die Hilfe der Frostwölfe benötigt!\n\nLOK'TAR!", progress = nil, completion = "Ihr kommt aus Tarrens Mühle? Ihr stinkt nach Tod...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28588] = {title = "Wildhammerplage", objective = "Tötet 10 Räuber der Wildhämmer.", description = "Während die beiden Idioten noch darüber streiten, wer hier den Bockmist gebaut hat, müssen wir uns mit einer Invasion der Krazzwerke herumschlagen!\n\nDiese nichtsnutzigen Wildhämmer sind überall. Geht los und säubert die Krazzwerke von dieser übelriechenden, biersaufenden Plage.", progress = nil, completion = "Ihr habt ein Händchen fürs Zwergentöten, soviel ist sicher, &lt;Name&gt;. Das ist gut.\n\nZwergenmassaker Teil 2, demnächst in diesem Theater.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28589] = {title = "Niet- und nagelfest", objective = "Tötet 15 Sturmkrallen der Wildhämmer.", description = "Ihr müsst etwas wegen dieser Sturmkrallen der Wildhämmer unternehmen. Sie reißen uns in Stücke!\n\nWir haben leider keine Munition mehr, deshalb müssen wir improvisieren. Wir haben die Krazzkanonen mit allem möglichen Zeug beladen: Poolponys, Kaja'Coladosen, Essensbehälter, Brennstoffzellen, Reifen... Ihr versteht, was ich meine.\n\nAlles, was nicht niet- und nagelfest ist.\n\nHabt Ihr Lust auf ein paar Zielübungen?", progress = "Was'n los? Seid Ihr erblindet? Seht Ihr nicht, dass wir immer noch fertiggemacht werden?\n\nRan an die Kanonen und pulverisiert diese Wildhämmer!", completion = "So ist's richtig! Muss ganz schön erniedrigend sein, von Müll abgeschossen zu werden.", rewards = "Werkzeugverstärkende ArmschienenNietensicherer BrustschutzArtilleriehandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28590] = {title = "Vergeltung", objective = "Sprecht mit Flick auf der Himmelsreißer, die über Hochstade kreist.", description = "Dieser Allianzabschaum wird endlich kriegen, was er verdient. Außerdem gibt es da etwas, das uns gehört. Ich habe einen Frontalangriff auf Hochstade autorisiert.\n\nGeht an Bord der Himmelsreißer und stürzt Euch in den Kampf. Flick wird Euch alles erklären, wenn Ihr dort eintrefft.", progress = nil, completion = "Gut, dass Ihr hier seid, &lt;Name&gt;. Seid Ihr bereit, ein wenig Chaos zu verbreiten?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28591] = {title = "Auf der Mauer, auf der Lauer", objective = "Vernichtet 80 Scharfschützen von Hochstade, 12 Kanoniere von Hochstade und 4 Kanonen von Hochstade mit dem Geschützturm des Himmelsreißers.", description = "Ihr seht aus, als hättet Ihr Lust auf einen Kampf. Setzt Euch in einen der Geschütztürme und macht die Verteidiger auf der Mauer fertig.\n\nUnd zwar schnell. Am besten, bevor wir als großer Feuerball enden.", progress = nil, completion = "Die modernisierte goblinische Zerstörungskraft ist erstaunlich, oder? Ich liebe diese Dinger.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28592] = {title = "Abschiedspakete", objective = "Legt Bomben auf dem Boot, am Festungseingang und in einem der nördlichen Türme.", description = "Flick verfolgt sicherlich einen größeren Plan, aber das wäre kein Angriff, wenn wir nicht wenigstens ein paar explosive Geschenke zurücklassen würden.\n\nGeht runter und bringt etwas von dem Sprengstoff auf dem Boot, am Festungseingang und in einem der nördlichen Türme an. Damit sollten sie eine Weile beschäftigt sein.\n\nWir werden uns ebenfalls zum Boden begeben. Trefft uns am östlichen Turm, wenn Ihr fertig seid.", progress = nil, completion = "Hahah! Tolle Vorstellung.\n\nDamit haben wir sie ordentlich im Hochland willkommen geheißen.", rewards = "Klettergürtel der KrazzwerkeTreter der ReparaturmannschaftHaischildbedeckungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28593] = {title = "Von größter Wichtigkeit", objective = "Beschafft das Induktionssamophlang.", description = "Mit Garroshs Zeppelin ist auch das Induktionssamophlang, das Ihr für uns in Azshara geborgen habt, abgestürzt. Die Allianz hat es irgendwo in dieser Festung versteckt. Krazz will es wiederhaben.\n\nIch tippe auf den Keller der Festung, also beginnt Eure Suche dort. Kehrt zu mir in die Nähe des Ostturms zurück, wenn Ihr es in Händen haltet.", progress = "Krazz wartet. Trödelt nicht.", completion = "Brillant! Dafür wird Krazz Euch auf Händen tragen. Freut mich für Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28594] = {title = "Nichtmehrganzsohochstade", objective = "Tötet 10 Verteidiger von Hochstade.", description = "Geht runter und scheucht dieses Allianzgesindel auf. Egal, welches. Sie sollen wie kopflose Hühner umherlaufen, damit Ihr Euch auf das echte Ziel konzentrieren könnt.\n\nIhr findet uns nahe des Ostturms, wenn Ihr fertig seid.", progress = nil, completion = "So macht man das. Kopflose Hühner... Aber eine große Klappe hatten sie schon, oder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28595] = {title = "Krazz werkelt!", objective = "Sprecht mit Molch, um zu den Krazzwerken zurückzufliegen. Gebt dort Kapitän Krazz das Induktionssamophlang.", description = "Das war's. Wir sind fertig. Lasst uns aufbrechen.\n\nMolch hat ein paar Gyrokopter an der Spitze des Turms angebunden. Geht zu ihr und fliegt kurz zurück zu den Krazzwerken. Wir räumen hier auf.", progress = "Sagt mir, dass Ihr es geschafft habt. Ihr schafft es immer. Zeigt mir meine Schönheit!", completion = "Darauf habe ich mich die ganze Zeit gefreut! Mit dieser Schönheit hebt die Flotte schon bald wieder ab.\n\nIhr wisst genau, was ich mag, &lt;Name&gt;. Und ich weiß, was Ihr mögt - nehmt das.", rewards = "HimmelsreißerkampfplatteBeinschützer des LuftangriffsKapuze des StoßtruppsoldatenAuf Euch wartet eine dieser Belohnungen:\n\nLuftangriffssignal\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28596] = {title = "Willkommen in Hochstade!", objective = "Tötet 10 Angreifer der Horde in Hochstade.", description = "Willkommen im Hochland, <Soldat/Soldatin>. Ihr kommt gerade rechtzeitig.\n\nDie Hordentruppen haben gerade mit ihrem Luftangriff begonnen. Unternehmt etwas dagegen. Werdet sie los!", progress = nil, completion = "Das sieht schon besser aus. Den Rest kehren wir von hier aus der Stadt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28597] = {title = "Kanonenfutter", objective = "Sammelt 10 Säcke mit Kanonenpulver.", description = "Har! Wir können direkt loslegen, <Name>. Hochstade hat anscheinend ein echt großes Zeppelinproblem. Das Luftschiff zerlegt die Mauern.\n\nIch habe eine Idee, die so dämlich ist, dass man sie genial nennen könnte. Ich brauche nur etwas Kanonenpulver.\n\nSammelt alles Pulver ein, das ihr in Hochstade finden könnt und trefft mich im Handelsviertel!", progress = "Ich brauche mehr Pulver! Bringt mir mehr Pulver! Mehr mehr mehr!", completion = "Jawoll, das reicht.\n\n&lt;Flintlocke stopft sich etwas von dem Pulver in den Mund.&gt;\n\nOhhh, frisch. Berauschend. Feinstes Korn aus dem Rotkammgebirge mit einem Hauch Westfallschwefel und einem milden Nachgeschmack. Hochstade kriegt nur das Beste.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28598] = {title = "Ein hohes Ziel", objective = "Wartet, bis Euch Fargo Flintlocke auf den Zeppelin gebracht hat und bringt seine Sprengladung in der unteren Kabine an.", description = "Seht mal, <Name>. Ich hab' die größte Waffe in Hochstade! Wir werden 'ne Taktik ausprobieren, die mein Papa von seinem Papa gelernt hat und der von seinem Papa, kurz bevor er in die Luft flog.\n\nSie nennt sich \"<Klasse>-Schuss.\"\n\n<Ein/Eine:c> <Klasse> muss in 'ne riesige Kanone und dann – hey, entspannt Euch. Das haut meistens hin.\n\nNehmt den Sprengstoff und wartet neben mir. Wenn das Luftschiffchen wieder vorbeikommt, schieße ich Euch aufs Deck. Bringt den Sprengstoff in seinem Rumpf an und... keine Ahnung, denkt Euch was aus.", progress = "Es gibt kein Problem, das man nicht mit einer Bombe lösen könnte.", completion = "&lt;Flintlocke wischt sich die Tränen aus den Augen.&gt;\n\nOh, &lt;Name&gt;. &lt;Name&gt;!\n\nDas ... war wunderschön.", rewards = "Ihr bekommt:\n\nFlintlockes Hackkarabiner"}
MultiLanguageQuestData['de'][28599] = {title = "Kurdran wartet", objective = "Sprecht mit Kurdran Wildhammer in der Burg Hochstade im Schattenhochland.", description = "Der Angriff hat anscheinend aufgehört, <Name>. Eigentlich schade, sonst hätten wir die <Klasse>-Rakete noch ausprobieren können.\n\nWie dem auch sei, Kurdran Wildhammer steht oben auf der Festung. Er will Euch garantiert als <Helden/Heldin> feiern. Habt Ihr auch verdient! Redet mal mit ihm!\n\nIch gehe schon mal vor und erkunde den Strand.", progress = nil, completion = "Ihr wurdet vom König persönlich geschickt? Es freut mich, dass Sturmwind sicher ist.\n\nIch hatte eigentlich weitere Truppen erwartet, aber so wie man hört, wurde die Allianzflotte auf dem Weg hierher von der Horde angegriffen. Sie haben alles gegeben, trotzdem wurde ihre Flotte zerschossen.\n\nWenn wir hier im Hochland Fortschritte machen wollen, werden wir die Hilfe von Helden wie Euch brauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28600] = {title = "Eine Frage der Loyalität", objective = "Sprecht mit Drek'Thar.", description = "Ich habe keine Entscheidungsgewalt bei solchen Angelegenheiten. Ihr müsst mit unserem Anführer Drek'Thar sprechen. Ich habe Eure Ankunft in Burg Frostwolf bereits angekündigt. Drek'Thar wird sich persönlich mit Euch treffen.", progress = nil, completion = "&lt;Oberster Kriegsfürst Cromush wird blass.&gt;\n\nSIE LASSEN UNS IM STICH? SIE LASSEN DIE HORDE IM STICH? Das kann nicht sein!\n\nIch...\n\n&lt;Cromush geht auf ein Knie.&gt;\n\nIch... ICH WERDE NICHT AUFGEBEN. Wir werden das auch ohne ihre Hilfe schaffen. Zur Hölle mit den Frostwölfen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28601] = {title = "Alter Kahn", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][28602] = {title = "Seid vorbereitet", objective = "Sammelt 6 Stücke Seil.", description = "Jeder Abenteurer, der etwas auf sich hält, weiß, dass man niemals einen Fuß in eine Höhle, ein Verlies, eine Krypta oder eine Grabstätte setzt, ohne ausreichend Seil dabeizuhaben... nicht wahr?\n\nNun, meine Seile waren in dem Wagen voller Sprengstoff, den Ihr in die Luft gejagt habt.\n\nWieso seht Ihr Euch nicht mal hier um, ob Ihr noch etwas findet.", progress = "Was macht die Suche?", completion = "Irgendwie habe ich das Gefühl, ich werde es brauchen.", rewards = "Helm der gebrochenen KnochenBeinknochenbrechende StampferSeilgreiferhandschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28603] = {title = "Infiltration", objective = "Tötet Ausbilder Rufus, Ausbildungsoffizier Magnus und Hauptmann Rattenbart.", description = "Hier ist Eure nächste Mission: Reist nach Westen zur Landzunge und infiltriert das Übungsgelände der Sturmlanzen. Dort gibt es zwar hunderte Sturmlanzen in der Ausbildung, aber eine meiner Banshees wird Euch so tarnen, dass Ihr wie einer der Menschen ausseht, die vor kurzem gefangen genommen wurden. Dann könnt Ihr Euch frei zwischen den Feinden bewegen.\n\nBetretet die Landzunge und sucht nach den Ausbildern der Sturmlanzen. Findet sie und bringt sie dazu, Euch anzugreifen! Wenn sie das tun, bringt Ihr sie um. Ohne ihre Ausbilder werden sie keine weiteren Soldaten mehr unterweisen können!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28604] = {title = "Täuschung und Betrug", objective = "Vergiftet 30 Lehrlinge der Sturmlanzen mit dem Wasserfass.", description = "Solange ich an Eurer Seite bleibe, werden die Feinde Euch für <einen/eine> der ihren halten. Eure neue Menschlichkeit sollte Euch allerdings nicht dazu verleiten, draufgängerisch zu werden. Wenn Ihr Aufmerksamkeit erregt, werden die Zwerge misstrauisch und Euch wahrscheinlich angreifen!\n\nDoch ich habe einen Plan. Nehmt dieses Fass mit vergiftetem Wasser und stillt damit den Durst von müden Lehrlingen der Sturmlanzen. Wenn sie davon trinken, werden sie todkrank und schließlich an dem Gift sterben.", progress = "Täuschung und Betrug - dies sind Eure Werkzeuge!", completion = "Sie werden nicht sofort sterben, aber sterben WERDEN sie! Wenn sie erkennen, wer für den Tod ihrer Soldaten verantwortlich ist, werdet Ihr längst weg sein - ein Phantom des Todes!", rewards = "Vergiftete ArmschienenWeste des PhantomsLiliths ZauberstabAuf Euch wartet eine dieser Belohnungen:\n\nBand des vorsätzlichen Mordes\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28605] = {title = "Beherrschung", objective = "Tötet 10 Ingenieure der Sturmlanzen.", description = "<Melisaras Gedanken mischen sich in Eure eigenen.>\n\nEure letzte Aufgabe wird ein Angriff auf die Belagerungstechniker von Gavins Landspitze, westlich der Landzunge, sein. Brecht zum letzten Finger auf und vernichtet die Zwergen- und Gnomeningenieure, die für den Bau und die Befestigung der Kriegsmaschinen der Sturmlanzen verantwortlich sind. Vergesst nicht, Cromushs letzte Hosentaschenbombe zu platzieren.", progress = nil, completion = "Die Streitkräfte der Sturmlanzen sind geschwächt. Es ist Zeit für die Sprengung!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28606] = {title = "Schlüssel für den Hot Rod", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSchlüssel für den Hot Rod"}
MultiLanguageQuestData['de'][28607] = {title = "Schlüssel für den Hot Rod", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSchlüssel für den Hot Rod"}
MultiLanguageQuestData['de'][28608] = {title = "Das Schattengrab", objective = "Holt zähe Balsamierungsflüssigkeit und Leichenflickerzwirn aus dem Schattengrab in Todesend.", description = "Es freut mich, dass Ihr wieder auf den Beinen seid, <Name>. Ihr habt Euch gut gehalten, obwohl Ihr so lange tot wart!\n\nAndere hatten weniger Glück. Würdet Ihr meine Balsamierungsflüssigkeit und etwas Faden holen, damit ich diese Leichen zusammenflicken kann? Beides werdet Ihr im Schattengrab, dem Gebäude direkt hinter mir, finden.\n\nDarnell wird Euch begleiten. Er kennt den Weg.", progress = "Ihr findet die Gegenstände im Schattengrab. Ich glaube, ich habe sie auf meinem Arbeitstisch liegen gelassen.", completion = "Genau die brauche ich. Ihr werdet für die Verlassenen von Nutzen sein, &lt;Name&gt;.\n\nMan sagt, dass Ihr in Eurem letzten Leben ein ziemlich guter &lt;Klasse&gt; wart. Vielleicht sollte ich Euch eine etwas aufregendere Aufgabe geben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28609] = {title = "Hammerschläge", objective = "Sprecht mit Deez Felsklau.", description = "Seit Wochen streiten wir drei uns darüber, wessen Waffen die besten sind.\n\nNiemand soll behaupten, dass meine Streitkolben zweitklassig wären. Kilrams Äxte und Serils Schwerter kommen niemals an die Stärke meiner Waffe heran.\n\nDer Streit geht mir auf die Nerven. Ich werde den beiden mit einer kleinen Vorführung beweisen, dass ich recht habe. Würdet Ihr bitte nach draußen gehen und Deez Felsklau sagen, dass ich den größten Felsbrocken brauche, den er auftreiben kann?", progress = nil, completion = "Lilith möchte also, dass ich einen Felsbrocken in das Observatorium bringe? Das ist mein Geschäft: kompakte Waren. Normalerweise kommen Einzelkunden nicht zu mir, aber ich werde bestimmt keine Fragen stellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28610] = {title = "Grollendes Geröll", objective = "Beschafft 6 hochwertige Geröllbrocken von Frostsplitterrumplern.", description = "Ihr könnt den Felsbrocken mit meinem patentierten Fels-in-der-Kiste hineinbringen! Normalerweise würde ich ihn Euch einfach verkaufen, aber mir sind die Materialien ausgegangen.\n\nAuf dem Gipfel südlich der Stadt sind Erdelementare aufgetaucht. Die sind eine gute Quelle für Geröll. Bringt mir genug davon, dann bezahle ich Euch für die Aufstockung meines Lagers und lege noch einen Fels-in-der-Kiste dazu. Umsonst!", progress = "Habt Ihr das Geröll?", completion = "Das sollte reichen! Hier ist Eure Bezahlung, wie versprochen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28611] = {title = "Das Ritual der Entweiher", objective = "Unterbrecht das Ritual der Neferset in der Finstergrundhöhle.", description = "Ah, ich sehe bereits klarer, <Name>.\n\nEs ist richtig, den bösartigen Neferset zu misstrauen. Ich spüre bereits, dass sie hinter den Kräften stecken, die den Fluss verderben.\n\nTaucht noch einmal hinab und findet die Finstergrundhöhle. Ihr werdet sehen, dass die Neferset dort ein dunkles Ritual der Verderbnis ausüben.\n\nHaltet sie auf, damit der Fluss wieder rein wird.", progress = "Ist es vollbracht, <Name>?", completion = "Das Wasser des Flusses ist fast wieder klar. Unsere prophetischen Visionen werden bald zurückkehren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28612] = {title = "Harrison Jones und der Tempel von Uldum", objective = "Erbeutet die Lade der Verheißung.", description = "Wir haben viel durchgemacht, aber das scheint sich jetzt endlich auszuzahlen!\n\nUns trennen nur noch wenige Schritte von der Lade... Ich habe die Chiffren studiert, um sie zu enthüllen... Schnottz hält uns für tot.\n\nIch glaube, wir kriegen das doch noch hin!", progress = nil, completion = "Aber Ihr habt Glück, denn dieser Zwerg hat noch ein oder zwei Asse im Ärmel!\n\nHeehee! ...Ihr hättet Euren Gesichtsausdruck sehen sollen!", rewards = "Begräbnisschiftung des PharaosGurt des UraltenGamaschen der VersprechenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28613] = {title = "Wir sehen uns auf der anderen Seite!", objective = "Sprecht mit Harrison Jones auf dem Aufstieg des Schöpfers in Uldum.", description = "Also gut, <Name>. Wir haben uns ein wenig Zeit verschafft, aber die dürfen wir nicht vertrödeln.\n\nFolgt mir!", progress = nil, completion = "So weit, so gut...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28614] = {title = "Bärserker", objective = "Tötet Grolnar den Berserker.", description = "Die Abwesenheit von Oberhäuptling Winterfell hat den Zorn der Winterfelle nicht gerade gemindert. In der Zwischenzeit hat ihr größter Krieger enorme Macht an sich gerissen.\n\nGrolnar der Berserker haust in der Höhle ganz oben im Lager der Winterfelle. In ihm steckt genug verderbtes Feuerwasser, um zehn normale Furbolgs zu töten.\n\nEr ist zu einer aufgeblähten, schrecklichen Bestie geworden! Unsere Krieger werden mit ihm nicht fertig... seid Ihr stark genug, um ihn zu besiegen, <Klasse>?", progress = nil, completion = "Eure Taten beweisen mir und der Holzschlundfeste wieder einmal, was für ein mächtiger Krieger Ihr seid!\n\nHoffentlich haben wir die Winterfelle damit endgültig besiegt...", rewards = "Gürtel des AufblähensBärserkerschiftungBurndls gebündelte StiefelAuf Euch wartet eine dieser Belohnungen:\n\nFeuerwasseramulett\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28615] = {title = "Erdwiderstand", objective = "Überladet 4 Erdtotems der Winterfelle mit Tanrirs überladenem Totem.", description = "Trotz ihres Wahnsinns und ihrer Verderbnis klammern sich die Winterfelle mit letzter Kraft an ihre schamanischen Kräfte. Dass sie die Macht der Elemente benutzen, um meinem Stamm und anderen Unschuldigen Schaden zuzufügen, verstört mich.\n\nWir werden ihre Totems gegen sie wenden! Nehmt mein Totem mit ins Lager der Winterfelle. Setzt seine Macht aus der Ferne bei den Totems der Winterfelle ein, dann wird der Zorn der Erde über alle kommen, die sich in der Nähe aufhalten!\n\nDass Ihr einen Sicherheitsabstand einhalten solltet, muss ich wohl nicht erwähnen!", progress = nil, completion = "Mögen die Winterfelle nie wieder die Holzschlundfeste bedrohen. Danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28616] = {title = "Sturmlanzenapokalypse", objective = "Werdet Zeuge der Sturmlanzenapokalypse.", description = "Bevor wir fortfahren, möchte ich um eine Schweigeminute für unseren gefallenen Bruder Orkus bitten, ohne den wir von den Sturmlanzen vernichtet worden wären. Das ist für Euch, Bruder!\n\n<Cromush geht auf ein Knie.>\n\nNun, <Name>, glaubt nicht, dass ich Euren Anteil an all dem vergessen hätte! Deshalb gewähre ich Euch die Ehre, die goblinischen Hosentaschenbomben zu zünden.\n\nSeid Ihr bereit? FÜR DIE HORDE!", progress = nil, completion = "Die Finger sind zerstört, die Hand ist zerschlagen. Jetzt werden sich die Sturmlanzen in ihre Höhle im Alteractal zurückziehen müssen.\n\n&lt;Cromush spuckt aus.&gt;\n\nKriegshäuptling Höllschrei wird von Eurem Mut erfahren, &lt;Name&gt;.\n\nUnd Ihr könnt sicher sein, dass wir den Verrat des Frostwolfklans ebenfalls erwähnen werden!", rewards = "Gebrochene Finger des HügellandesHosentaschenbombengürtelUmhang des VerratesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28617] = {title = "Blumenkinder", objective = "Überlebt eine riesige Zombiewelle.", description = "Ihr habt bereits gelernt, wie man die Speier verwendet, aber wusstet Ihr, dass alles schneller wächst, wenn man Sonnenblumen benutzt? Wir werden ein paar Sonnenblumen heranziehen und einige Speier pflanzen und damit Aufseher Stillwassers verrückte Monstrositäten aufhalten.\n\nLos!", progress = nil, completion = "Ich glaube, das war erst der Anfang, Kumpel! NEUE WELLE!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28618] = {title = "Felslieferung", objective = "Gebt einen Fels in einer Kiste bei Lilith der Lieblichen in der Ewigen Warte ab.", description = "Bitte sehr, wie versprochen! Ein Fels in einer Kiste.\n\nDarum hat Lilith doch gebeten, oder? Sie ist meine einzige Kundin!", progress = "Oh, Ihr schon wieder. Wo ist der Fels?", completion = "Ah, Ihr habt tatsächlich einen Fels mitgebracht! Das überrascht mich etwas.\n\nTretet zurück und werdet Zeuge allerhöchster Handwerkskunst.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28619] = {title = "Auf Befehl des Kriegshäuptlings: Arathihochland!", objective = "Meldet Euch bei Dunkelläuferin Alina bei Galens Sturz im Arathihochland.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Dunkelläuferin Alina bei Galens Sturz zu melden. Die Streitkräfte der Dunklen Fürstin wollen das Herrschaftsgebiet der Horde vergrößern und die Allianz zurückschlagen. Helft ihnen dabei.\n\nDas Arathihochland liegt östlich des Vorgebirges des Hügellands. Folgt der Straße, die am Thoradinswall vorbeiführt.\n\nDas Schicksal ruft!", progress = nil, completion = "Endlich ist die Verstärkung des Kriegshäuptlings eingetroffen. Die Dunkle Fürstin hat für Euch ebenso große Pläne wie für uns.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28620] = {title = "Ostwachtturm", objective = "Sprecht mit Nils Bierwurz am Ostwachttum im Vorgebirge des Hügellands.", description = "In unserem Außenposten im Südosten gibt es einige Probleme. Mehr weiß ich auch nicht, nur... nun, ich werde Euch einfach aus dem letzten Brief vorlesen:\n\n\"Die Orcs werden bockig. Schickt Hilfe, sonst lasse ich sie mit Schilfrohr schlagen.\"\n\nDas ist alles. Der Brief stammt von unserem Chefpsylosophen Nils Bierwurz. Und nein, ich weiß auch nicht, was das heißen soll. Würdet Ihr bitte zum Ostwachttum reisen und herausfinden, was er braucht? Ich halte diese kryptischen Briefe nicht mehr aus!\n\nWendet Euch nach Süden und folgt dann der Straße nach Osten.", progress = nil, completion = "Endlich schickt dieser Schwachkopf Hilfe! Diesen beiden Orcs ist nicht mehr zu helfen. Sie leiden unter etwas, das ich \"Durnholdesyndrom\" nenne. Sie waren so lange eingekerkert, dass sie begonnen haben, Zuneigung für ihre Wärter zu empfinden. Sie sitzen mit ihren großen Eisenkugeln auf meinem Sofa und weinen.\n\nHoffentlich werdet Ihr Euch als nützlicher erweisen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28621] = {title = "Legt das Baby in die Wiege!", objective = "Sprecht mit Harrison Jones beim Tempel von Uldum.", description = "Ach!\n\nIhr und Junior habt Euch ja schön viel Zeit gelassen, oder!?\n\n<Bier trinken/Händchen halten>, die Aussicht genießen - liege ich richtig?\n\nBrecht Euch nicht die Hand, wenn Ihr Euch auf die Schulter klopft. Die richtige Arbeit kommt erst noch!\n\nIn diesem alten Artefakt steckt mehr, als es den Anschein hat. Um seine Geheimnisse zu ergründen, müssen wir es zur Wiege der Uralten bringen!\n\nAber wie stellen wir das am besten an?\n\nVielleicht fällt Junior ja was Schlaues ein.", progress = nil, completion = "Natürlich habe ich einen Plan, wie wir die Lade transportieren.\n\nVielleicht wird dieser alte Kautz ja eines Tages lernen, mir zu vertrauen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28622] = {title = "Ein, zwei, nein, drei Signalleuchtfeuer", objective = "Benutzt die Signalleuchtfeuer beim Tempel von Uldum.", description = "Ich wollte die Lade eigentlich zur Untersuchung in mein Labor bringen, aber anscheinend hat Brann hier andere Pläne.\n\nEr meint, zu wissen, wie wir Todesschwinges Pläne hier in Uldum durchkreuzen können.\n\nMein Kumpel Jock wartet nur auf unser Signal, um mit dem Transport zu beginnen.\n\nNehmt diese Signalleuchtfeuer und stellt sie um den Tempel herum auf, damit er weiß, dass wir bereit sind.", progress = nil, completion = "Gute Arbeit, mein Freund.\n\nAnscheinend haben alle die Reise überstanden.\n\nSo langsam verstehe ich, warum Ihr Junior begleiten dürft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28623] = {title = "Auf nach Westen", objective = "Meldet Euch bei König Phaoris in den Außenbezirken von Neferset in Uldum.", description = "Unsere Arbeit hier ist getan, <Name>. Obwohl alles gegen uns sprach, konnten wir einen Vorstoß der Neferset auf Nahom verhindern.\n\nWir sollten uns den Streitkräften anschließen, die den Kampf nach Westen tragen, sonst streichen sie all den Ruhm allein ein.\n\nWahrscheinlich haben sie schon die Randgebiete von Neferset erreicht.", progress = nil, completion = "Ihr seid gerade rechtzeitig eingetroffen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28624] = {title = "Kilrams Prahlerei", objective = "Sprecht mit Deez Felsklau.", description = "Pah! Primitiv und schwerfällig, was anderes kann ich dazu nicht sagen!\n\nStärke ist nicht alles. Meine Äxte sind so stark wie Liliths Streitkolben, aber so scharf, dass ich einen Baum mit einem Schlag fällen kann!\n\nIhr habt es gehört. Ein Schlag! Ich werde es Euch vor allen hier beweisen. Geht zu Deez. Er soll einen Baum herbringen!", progress = nil, completion = "Jetzt wollen sie einen Baum? Mal sehen, was ich habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28625] = {title = "Baum fällt!", objective = "Beschafft 10 Stücke frischgeschlagenes Frostholz von Frostlaubtreants.", description = "Ich handle viel mit Brettern, aber komplette Bäume? Das wird selten verlangt. Ebenso wie Felsen.\n\nVielleicht könnt Ihr mir ja noch einen Gefallen erweisen. Westlich der Stadt gibt es einen Hain, von dem aus man den Kel'Therilsee sehen kann. Ich weiß nicht, ob es an den Geistern liegt oder an all dem magischen Elfenmüll, der überall herumliegt, aber in letzter Zeit tauchen dort Treants und Peitscher auf.\n\nSeit sie dort sind, macht es keinen Spaß mehr, Holz zu fällen, also warum fällt Ihr sie nicht stattdessen? Bringt mir das Holz der Treants.", progress = "Zeigt mir das Holz.", completion = "Das ist eine ordentliche Ladung. Vielleicht sollten wir anfangen, Treants anstatt Bäumen zu pflanzen...", rewards = "Zack-zack-StiefelSchuhe aus TreantrindeFelsspitzelhelmAuf Euch wartet eine dieser Belohnungen:\n\nFrostlaubband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28626] = {title = "Baumlieferung", objective = "Bringt den Wunderwuchs-Instantbaum zu Kilram im Gasthaus der Ewigen Warte.", description = "Bitte sehr, ein Wunderwuchs-Instantbaum, hergestellt mit 80% natürlicher Zutaten!\n\nKeine Wurzel, keine Nuss, kein Verdruss. Gebt ihn Kilram und sorgt dafür, dass er ein ordentliches Stück zurücktritt, bevor er ihn benutzt.", progress = "Zack zack!", completion = "Also gut! Bleibt zurück und seht Euch an, was eine Waffe von gehobener Qualität anrichten kann!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28627] = {title = "Serils Prahlerei", objective = "Sprecht mit Deez Felsklau.", description = "Wilde und Amateure.\n\nEs spielt keine Rolle, wie scharf oder schwer eine Waffe ist, wenn man damit nur herumfuchteln kann wie ein Oger. Ich könnte versuchen, Dinge wie Raffinesse und Geschwindigkeit, Balance und Kontrolle zu erklären... aber diese Narren werden das nur verstehen, wenn ich es ihnen zeige.\n\nSagt Deez, dass wir noch eine Lieferung von ihm benötigen. Ich brauche einen Eisblock.", progress = nil, completion = "Oh, Ihr schon wieder! Was für eine Überraschung!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28628] = {title = "Eislieferung", objective = "Bringt den Soforteisblock zu Seril Geißelbann in der Ewigen Warte.", description = "Also gut, ein 100% reiner Soforteisblock von höchster Qualität!\n\nIch habe versucht, die Kunden eine Weile lang zum Schutz zu verkaufen. Ihr wisst schon, wie dieser Trick, den Magier drauf haben? Die Sache mit dem \"Atmen\" habe ich nur nie hinbekommen.", progress = "Ah, da seid Ihr ja!", completion = "Perfekt. Jetzt werdet Ihr sehen, worauf es bei einer Waffe ankommt... Raffinesse.", rewards = "Lilith der Lieblichen kleiner HammerKilrams MörderGeißelbanns SchwertGeißelbanns SchnitzlerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28629] = {title = "Sind wir endlich da, Yeti?", objective = "Erbeutet 10 dicke Yetifelle von Eisdistelyetis.", description = "Meine Freunde haben immerzu tolle Ideen. Ich habe nie das Gefühl gehabt, mit ihnen mithalten zu können... bis heute! Gerade habe ich die Pläne für etwas Großes angefertigt! Wenn Ihr versprecht, es nicht zu erzählen, weihe ich Euch in das Geheimnis ein... \n\nIch werde einen mechanischen Yeti herstellen! Meine Freunde werden ganz bestimmt durchdrehen, wenn sie ihn sehen, aber wenn sie darüber hinweg sind, bin ich mir sicher, dass sie beeindruckt sein werden!\n\nIch brauche dickes Yetifell von Eisdistelyetis. Ihr werdet sie südöstlich von hier in den Eisdistelbergen finden.", progress = "Für den Anfang habe ich mehr als genug. Bitte bringt mir die Felle so schnell Ihr könnt!", completion = "Diese Felle sind perfekt, &lt;Name&gt;. Damit haben wir einen guten Anfang!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28630] = {title = "Echo Drei", objective = "Findet Echo Drei.", description = "Oben in den Eisdistelbergen sind zahlreiche Goblins verschwunden. Beinahe wäre mir das auch passiert!\n\nIch bin auf die Idee gekommen, einen Sensor zu installieren, der uns warnen sollte, wenn die Yetis sich der Ewigen Warte nähern. Natürlich funktioniert der auch nicht. Die Hügel sind voller Yetis, aber ich habe noch keinen Laut von ihm gehört.\n\nWürdet Ihr ihn für mich überprüfen? Vielleicht lässt er sich reparieren. Echo Drei steht südöstlich von hier, am Rand der Eisdistelberge. Fragt nicht, was aus Echo Eins und Zwei geworden ist.", progress = nil, completion = "Ein Teil der Maschine bewegt sich noch, aber als Ihr genauer hinseht, bemerkt Ihr, dass sie stark beschädigt ist. Das Metall ist verbogen und aufgerissen. Riesige Fußabdrücke sind rund herum im Schnee zu sehen.\n\nUnd es klingt, als nähere sich etwas in diesem Moment...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nYetihinterhalt\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28631] = {title = "Perfekte Hörner", objective = "Erbeutet Eisklatschers makellose Hörner.", description = "Ich kann doch keinen Yeti ohne Hörner machen!\n\nSeit einer Ewigkeit suche ich schon nach den perfekten Hörnern... aber die, die ich finde, sind nicht gut genug! Vor ein paar Tagen habe ich jedoch den größten Yeti in ganz Winterquell gesehen.\n\nIch nenne ihn Eisklatscher. Seine Hörner wären genau richtig! Er lauert ganz hinten in der Höhle auf dem östlichen Kamm der Eisdistelberge.\n\nBringt mir seine Hörner... aber vergesst nicht, Echo Drei auf dem Weg zu überprüfen!", progress = "Sind sie perfekt? Das hoffe ich!", completion = "Ich kann es gar nicht erwarten, das meinen Freunden zu zeigen! Also, wartet einen Moment, während ich die hier befestige... \n\nPerfect!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28632] = {title = "Frisch von den Hügeln", objective = "Besorgt 7 Stücke reines Gletschereis aus der Höhle in den Eisdistelbergen.", description = "Dieses Mal soll es Eis sein? Klar, was auch sonst. Ich habe gute und schlechte Nachrichten für Euch.\n\nDie guten: Es gibt reines, festes Eis in der Höhle in den Eisdistelbergen, östlich der Ewigen Warte. Die schlechten: Leider gibt es da auch jede Menge grausamer Yetis.\n\nAber wenn Ihr mit Yetis fertigwerdet, ist das ein Kinderspiel! Geht einfach zu den größeren Brocken und zerschlagt sie mit Eurer Waffe. Bringt alles hierher und überlasst mir den Rest.", progress = "Oh, Ihr seid zurück! Wie lief es mit den Yetis?", completion = "Nicht schlecht! Dann hoffen wir mal, dass sie als nächstes nicht um Lava bitten, richtig?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28633] = {title = "Die Lade der Verheißung", objective = "Gebt Brann Bronzebart den Inhalt der Lade der Verheißung.", description = "Ich bin mir nicht sicher, was uns hier erwartet, also haltet die Augen offen.\n\nDiese Codes sollten uns den wahren Zweck der Lade enthüllen und uns Werkzeuge in die Hand geben, mit denen wir die Pläne, die Todesschwinge für Uldum hat, endgültig durchkreuzen können!\n\nBleibt zurück!", progress = "Also dann.\n\nSeht Euch das an!?", completion = "Natürlich! Ich hatte geahnt, dass wir das finden würden.\n\nAllerdings überraschen mich die organischen Transformationen doch ein wenig.\n\nIn diesem alten Relikt steckt mehr, als ich zu hoffen gewagt hatte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28634] = {title = "Ausrottung", objective = "Tötet 12 tobende Eulenbestien.", description = "Eulenbestien... Seelenlose, gefiederte Monstrositäten, die den dunkelsten Tiefen des Wirbelnden Nethers entstiegen sind, um den Schwachen nachzustellen.\n\n<Nils zeigt auf die Wälder, die den Ostwachttum umgeben.>\n\nSie kreisen uns ein und sie planen einen Angriff - ich spüre es. Haltet sie auf, bevor sie eine Strategie entwickeln.\n\nGeht in den Wald und tötet jede Eulenbestie, die Ihr seht. KEINE DARF ÜBERLEBEN!", progress = nil, completion = "Das Jucken hat aufgehört - erst einmal - aber sie werden zurückkehren.\n\nOh ja, das werden sie...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28635] = {title = "Gespenstischer Hügellandhof", objective = "Sucht in Dun Garok nach Beweisen für Geister.", description = "Der Kampf um Dun Garok war der blutigste in der Geschichte der Hügellandschlachten. Die Zwerge standen vor einer zehnfachen Übermacht, kämpften aber bis zum bitteren Ende. Sie alle starben bei der Verteidigung dieses Stück Landes.\n\nNun heißt es, dass es dort spukt. Niemand traut sich heran! Dummerweise habe ich den Befehl erhalten, Dun Garok für eine Besiedlung vorzubereiten.\n\nWürdet Ihr mir den Gefallen erweisen, nach Dun Garok zu gehen und nach Beweisen für diese Geister zu suchen? Dun Garok liegt weit im Südosten.", progress = nil, completion = "Geister? Das kann man wohl sagen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28636] = {title = "Das Schweigen der Zwerge", objective = "Tötet 10 Geister von Dun Garok.", description = "Die Geister meiner Soldaten spuken in diesem Fort, <Junge/Mädchen>. Ihre Seelen sind an diesen Ort gebunden. Selbst im Tod kämpfen sie weiter für ihn. Traurig.\n\nMacht ihrem Leid ein Ende, dann könnt Ihr den Sieg Eures Volks vielleicht genießen.", progress = nil, completion = "Selbst nach dem Tod kämpfen sie noch für ihr Land - so wie die Verlassenen. Ich werde der Kommandozentrale melden, dass Dun Garok unbewohnbar ist. Sie sollen behalten, was ihnen so am Herzen liegt.", rewards = "Mantel des SpukensHerrn Hiders ArmschienenGriffe des UnnachgiebigenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28637] = {title = "Bärenhunger", objective = "Tötet 15 Splitterzahnbären.", description = "Habt Ihr jemals Bärenfleisch probieren dürfen? In Gilneas hatte ich nie Gelegenheit dazu, aber die Bären hier sind wahre Delikatessen.\n\nDas Fleisch der Splitterzahnbären, die südlich von hier umherziehen, ist durch die Kälte gut mit Fett durchsetzt. Ich habe sie schon selbst gejagt, was ein ziemlicher Jux ist, aber noch lieber esse ich sie!\n\nWarum probiert Ihr die Jagd nicht einmal aus? Konzentriert Euch auf die Splitterzahnbären mit weißem Fell. Der Hauptmann wird alle, die Ihr tötet, hierher bringen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28638] = {title = "Die Eulen sind die besten", objective = "Tötet 15 Winterquelleulen.", description = "Ich habe mein ganzes Leben lang Eulen gegessen. Eulen schmecken gut, mein Freund Jez findet das auch. Ich habe ihm als erster vorgeschlagen, Eule zu verkaufen!\n\nDer hochwohlgeborene Worgen da vorn behauptet, Bär schmecke besser, aber ignoriert ihn einfach. Jagt erst einmal selbst ein paar Eulen. Südlich von hier gibt es jede Menge. Haltet Euch erstmal an die grauen und meldet Euch bei mir mit dem kleinen Sprechgerät, das Jez Euch gegeben hat, wenn Ihr ein paar zusammen habt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28639] = {title = "Ursius", objective = "Tötet Ursius.", description = "Es heißt ja, man ist, was man isst. Ich weiß nicht, ob ich das glauben soll, aber wenn es stimmt... Also dann will ich die stärkste Kreatur essen, die ich finden kann.\n\nUrsius ist der größte Bär in ganz Winterquell. Er frisst als erster, wenn sein Rudel Splitterzähne eine Schimäre oder einen Eulenbär tötet. Ihm gehört die gemütlichste Höhle im Land der Splitterzähne. Und er hat... bemerkenswerten Einfluss auf die Weibchen der Splitterzähne.\n\nSo ein Bär gefällt mir.\n\nIch will ihn essen.\n\nSeine Höhle liegt in der Nähe der Raufer. Viel Glück!", progress = nil, completion = "Ursius schmeckt... nicht gerade köstlich. Sein Geschmack erinnert mich an eine Mischung aus Tannenzapfen und saurer Milch, nur... öliger.\n\nUnd Ihr seid sicher, dass das Ursius ist? Der große Bär? In der Höhle?\n\nDas ist furchtbar. Das Fleisch schmeckt so, als habe man es in Urin eingelegt.\n\nIch fühle mich nicht stärker.\n\nBah. Das ist wirklich übel. Wollt Ihr mal probieren?", rewards = "SplitterzahnhandschuheUrsius' KappeMit Bärenöl behandelter KettenpanzerArmschiene des beträchtlichen EinflussesMorcotts BogenIhr bekommt:\n\nUrsius' Flanke"}
MultiLanguageQuestData['de'][28640] = {title = "Frische Frostsäbler", objective = "Tötet 15 Frostsäbler oder Frostsäblerpirscherinnen.", description = "Riecht das nicht gut? Mein geräuchertes Fleisch bringt die höchsten Preise. Niemand außer mir bietet die exotischen Geschmackserlebnisse, die es hier in den Hügeln gibt. Und es ist sehr effizient. Ihr geht gegen ein kleines Entgelt auf die Jagd und meine guten Freunde bringen die Bestien hierher, wo sie gehäutet und geräuchert werden!\n\nIch beherrsche den Markt für Frostsäblerfleisch momentan. Unglaublich leckeres Zeug, aus dem man gute Würste machen kann. Zieht los und jagt die Katzen westlich von hier. Das ist ein guter Anfang!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28641] = {title = "Katzenburger", objective = "Tötet 15 Frostsäblerjägerinnen oder Rudelbehüterinnen der Frostsäbler.", description = "Also gut, <Kleiner/Kleine>, jetzt geht es weiter nach draußen!\n\nDiese Lieferung war nicht schlecht, aber weiter westlich gibt es wesentlich größere Kätzchen. Die Rudelbehüterinnen und Jägerinnen sind wesentlich muskulöser. Hamburger aus ihrem Fleisch schmecken PHANTASTISCH. Sie verkaufen sich wie verrückt!\n\nGebt mir kurz Bescheid, wenn Ihr fertig seid, dann lassen wir Euch auf den Hauptgang los.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28643] = {title = "Die Herausforderung von Durnholde: Zephyrus", objective = "Tötet Zephyrus.", description = "Burg Durnholde war stets ein Ort des Unfriedens. Jahrelang benutzten die Menschen sie als Internierungslager und Gefängnis für die Orcs. Danach wurde sie vom Syndikat übernommen. Und jetzt? Die Dunkle Fürstin hat mächtige Elementare gefangen und innerhalb ihrer Mauern ausgesetzt. Sie hat mir die Leitung der \"Herausforderung von Durnholde\" übertragen. Wer alle Elementare besiegt, erhält eine große Belohnung! Nehmt dieses Handbuch und stellt Euch Eurer ersten Herausforderung: Zephyrus!\n\nDurnholde liegt nordöstlich von uns.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28644] = {title = "Die Herausforderung von Durnholde: Teracula", objective = "Tötet Teracula.", description = "Das Handbuch benennt Teracula als Eure nächste Herausforderung. Er folgt dem Pfad vor Zephyrus' Versteck.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28645] = {title = "Die Herausforderung von Durnholde: Blutgift", objective = "Tötet Blutgift.", description = "Das Handbuch benennt Blutgift als Eure nächste Herausforderung. Dieser furchterregende Elementar hält sich auf der unteren Ebene der Burg Durnholde, nahe des westlichen Gefängnisses auf.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28646] = {title = "Die Herausforderung von Durnholde: Infernus", objective = "Tötet Infernus.", description = "Das Handbuch benennt Infernus als Eure nächste Herausforderung. Diesen Alptraum aus geschmolzener Lava und wütenden Flammen findet Ihr auf der unteren Ebene der Burg Durnholde, nahe des östlichen Gefängnisses.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28647] = {title = "Die Herausforderung von Durnholde: D-1000", objective = "Tötet den D-1000.", description = "Ein Wesen, das aus reinem Quecksilber besteht, wird in der alten Arena der Burg Durnholde gefangen gehalten. Die Verlassenen nennen es den D-1000. Tötet den D-1000 und holt Eure Belohnung ab!", progress = nil, completion = "Noch nie zuvor hat jemand die Herausforderung abgeschlossen. Ihr seid ein wirklich mächtiger &lt;Klasse&gt;, &lt;Name&gt;. Wie versprochen könnt Ihr Euch eine Belohnung aussuchen.", rewards = "Axt des Jüngsten GerichtsHammer des UnterbrechersAuf Euch wartet eine dieser Belohnungen:\n\nD-1000-Ring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28649] = {title = "Eine besondere Überraschung", objective = "Ritterkommandant Seuchenfaust bei der Kapelle der Scharlachroten Flamme hat Euch befohlen, den Gefangenen der Argentumdämmerung, Lord Harford, im nahegelegenen Gefängnis hinzurichten.", description = "Wir kamen hierher, zerlegten alles und machten uns auf den Weg zum Zellenblock. Wir haben nicht mit dem gerechnet, was wir dort fanden, <Name>. Der Kreuzzug hat ganze Arbeit geleistet. Da sitzen jede Menge Gefangene der Argentumdämmerung. Die meisten waren schon tot, als wir eintrafen, aber ein paar haben noch geatmet.\n\nIch wollte den Rest eigentlich selbst hinrichten, aber ich denke, die Ehre gebührt Euch. Vor allem den angriffslustigen Worgen, der dort sitzt, werdet Ihr bestimmt mit großer Freude hinrichten.", progress = "Wie fühlt Ihr Euch?", completion = "Das war doch gut, oder? Ihr gehört jetzt nicht mehr zu ihnen, &lt;Name&gt;. Ihr seid jetzt bei der Geißel. Ihr seid auf ewig einer von uns...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28650] = {title = "Eine besondere Überraschung", objective = "Ritterkommandant Seuchenfaust bei der Kapelle der Scharlachroten Flamme hat Euch befohlen, den Gefangenen der Argentumdämmerung, Gally Klumpfleck, im nahegelegenen Gefängnis hinzurichten.", description = "Als wir hier ankamen, haben wir alles auseinandergenommen und sind dann zum Gefängnis gezogen. Was wir dort fanden, hatten wir nicht erwartet, <Name>. Es scheint, der Kreuzzug war sehr fleißig. Das ganze Ding ist voller Gefangener der Argentumdämmerung. Die meisten waren schon tot, als wir eintrafen, doch ein paar atmeten noch.\n\nIch wollte gerade hingehen und den Rest umbringen, doch ich denke, Ihr solltet die Ehre haben. Es ist ein besonders aufmüpfiger Goblin darunter. Ich glaube, ihn zu richten wird Euch große Freude machen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28651] = {title = "Novizin Elreth", objective = "Sprecht mit Novizin Elreth in Todesend in Tirisfal.", description = "Jetzt, da die Ausbildung abgeschlossen ist, solltet Ihr mit Elreth sprechen. Sie dient Schattenpriester Sarvis. Wahrscheinlich hat sie einige Aufgaben, für die Ihr Eure neu erworbenen Fähigkeiten einsetzen könnt.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][28652] = {title = "Verwalter Caice", objective = "Sprecht mit Verwalter Caice an den Gräbern von Todesend in Tirisfal.", description = "Ich brauche Euch nicht mehr. Es gibt jedoch andere, für die Eure Hilfe wichtig ist.\n\nVerwalter Caice auf dem Stumpf hinter mir wird Euch wohl einen Auftrag geben können. Sprecht jetzt mit ihm.", progress = nil, completion = "Ja, bitte? Und Ihr seid...?", rewards = nil}
MultiLanguageQuestData['de'][28653] = {title = "Schattenpriester Sarvis", objective = "Sprecht mit Schattenpriester Sarvis in Todesend in Tirisfal.", description = "Ihr seid noch immer hier, <Name>? Ich bin ja leider nur eine Todeswache und habe kaum Aufgaben, die ich zufälligen Passanten geben kann.\n\nAm besten sprecht Ihr mit Schattenpriester Sarvis. Nachdem sie mich damals aus dem Grab geholt hatten, hat er mich wieder auf die Beine gebracht. Er tut das sicher auch für Euch.\n\nIhr findet ihn in der Kapelle, hier auf der Westseite der Stadt.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][28654] = {title = "Des Pudels Kern", objective = "Brann Bronzebart möchte, dass Ihr ihn in den Hallen des Ursprungs trefft.", description = "Ich würd' ja gern noch ein Weilchen bleiben und mit Euch in die Gegend schauen, <Bürschchen/Mädel>.\n\nAlso, ich hab' bestimmt schon die tollsten Dinger gesehn, aber so was ist mir mein Lebtag noch nicht untergekommen.\n\nLeider muss ich diese Scheiben noch gründlicher untersuchen, eh' ich mich zu den Hallen des Ursprungs aufmachen kann.\n\nIch glaub', Ihr seid schwer in Ordnung. Wollt Ihr mal sehen, wie ein richtiger Archäologe arbeitet? Dann kommt mit!", progress = nil, completion = "Höchste Zeit, dass Ihr eintrefft, Bursche.\n\nAuf geht's! An die Arbeit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28655] = {title = "Wilde Wildhammer-Hochzeit", objective = "Sagt Grundy MacGraff, dass die Hochzeitszeremonie beginnen kann. Tötet jeden Schattenhammer, der versucht, sie zu verhindern.", description = "Wir sind bereit, <Name>!\n\nIch weiß aber aus sicherer Quelle, dass der Schattenhammer versuchen wird, die Zeremonie zu vereiteln. Damit soll der Wildhammer demoralisiert und zerstört werden. Es kann gefährlich werden!\n\nDeshalb werde ich die Zeremonie selbst vollziehen und Braut und Bräutigam in nächster Nähe behalten. Klingt das gut? Bestens!\n\nDa Fannys Vater nicht mehr lebt und ihr Bruder Trauzeuge des Bräutigams ist, bittet sie darum, dass Ihr sie an den Altar geleitet. Welch eine Ehre! Gebt mir Bescheid, wenn Ihr bereit seid.", progress = nil, completion = "&lt;Name&gt;, wir haben's geschafft! Wie alle Wildhämmer zusammen gegen dieses... Ding gekämpft haben - das hat sie so richtig zusammengeschweißt. Die Familienoberhäupter sind so einig wie nie zuvor. Zum Wohl, &lt;Name&gt;, lasst uns feiern!!\n\nMit unserer Arbeit stehen wir natürlich noch ganz am Anfang. Ich lasse unsere neue Wildhammerverstärkung zum Rest der Allianz hinzustoßen und den Sturm der Bastion des Zwielichts vorbereiten.\n\nWir treffen uns bestimmt bald wieder.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28656] = {title = "Seltsame Lebenskräfte", objective = "Begebt Euch zu Schneewehs Berghütte in Winterquell und sprecht dort mit Hexendoktorin Mau'ari.", description = "Beim Tod dieser Kreatur ist ihr eine Art Energie entstiegen. Diese Energie ist auf Euch übergegangen und so fühlt Ihr Euch etwas stärker.\n\nGlaubt man den Einwohnern von Winterquell, dann ist die Hexendoktorin Mau'ari an Schneewehs Berghütte eine Expertin für die Tierwelt dieser Gegend. Vielleicht weiß sie was über die geheimnisvolle Energie.", progress = nil, completion = "Was'n das? Du riechst nach E'ko! Lass dir von Mau'ari mal was übers E'ko erzähl'n un' was es so tut.\n\nDu hast Glück, &lt;Volk&gt;. Das E'ko is' zu dir gekommen. Ein einfacher Troll wie ich muss selber E'ko such'n.\n\nDie Kreaturen von Winterquell hab'n alle E'ko. Die Furbolgs, die Schimären, die Splitterzähne... sogar die Eisdistelyetis! Wenn du so 'ne Kreatur tötest, kommt manchmal 'n bisschen E'ko 'raus. Verschiedene Kreaturen... verschiedenes E'ko.\n\nDann mal los. Such' weiter E'ko!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28657] = {title = "Ein riesiges Problem", objective = "Ihr wurdet beauftragt, Problim zu töten, einen Riesenettin, der die Wege von Tol Barad unsicher macht.", description = "Endlich haben wir diesen gottverdammten Fels eingenommen und dann treibt so ein riesiger Ettin hier sein Unwesen und schaltet unsere Wachpatrouillen aus!\n\n<Name>, trommelt ein paar Verbündete zusammen und erledigt den Ettin. Wir können nicht zulassen, dass die Bestie hier alles verwüstet.\n\nSeid auf der Hut, von der Front wird gemeldet, dass er mit einem riesigen Baum bewaffnet ist. Und er hat keine Skrupel, ihn einzusetzen.", progress = nil, completion = "Ihr habt ihn tatsächlich getötet?! Ich kann es kaum glauben!", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28658] = {title = "Sumpfköder", objective = "Ihr habt den Auftrag, auf Tol Barad 8 Krokiliskenbälge von Krokilisken von Baradin zu besorgen. Die Krokilisken findet Ihr im Sumpf, gleich westlich der Baradinfestung.", description = "An solchen Orten ist die Versorgung immer schwer, <Klasse>. Seit wir die Insel eingenommen haben, erkunden wir sie, aber es sieht nicht gut aus.\n\nZum Glück haben wir gerade erfahren, dass sich gleich westlich von unserem Basislager ein Sumpf voller Krokis befindet. Deren Bälge werden unseren Lederern gerade recht kommen. Bringt so viele her wie Ihr nur könnt.", progress = "Habt Ihr schon im Sumpf aufgeräumt?", completion = "Sieht aus, als habt Ihr die Krokibälge, die wir brauchen. Danke, &lt;Name&gt;, Euer Beitrag wird Euch nicht vergessen.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28659] = {title = "Die Überreste", objective = "Ihr habt den Auftrag, 12 Infanteristen der Allianz auf Tol Barad zu töten. In der Erzraffinerie, der Hüterwacht und der Eisernen Garnison hier auf Tol Barad sind noch Widerständler zu finden.", description = "Wir haben hart um diese Insel gekämpft, <Volk>. Den Großteil des Allianzdrecks haben wir rausgeschmissen, aber ihr übler Gestank liegt noch immer in der Luft.\n\nKundschaftet die Erzraffinerie, die Hüterwacht und die Eiserne Garnison aus. Tötet alle Angehörigen der Allianz, die Ihr findet.\n\nIhr kennt ja das Sprichwort: Nur ein toter Allianzler ist ein guter Allianzler!", progress = nil, completion = "Dieser Allianzabschaum hatte nicht die geringste Chance. Gut gemacht, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28660] = {title = "Die Tiefen säubern", objective = "Ihr habt den Auftrag, 9 Geister beliebigen Typs in den Verfluchten Tiefen gleich östlich der Baradinfestung zu töten.", description = "Wie schön, Euch zu sehen, <Name>. Jetzt, da wir Tol Barad eingenommen haben, fängt die Schlacht erst an.\n\nGleich östlich von hier haben wir einen Zellenblock entdeckt, den Ihr ausräumen müsst. Er steckt zum Bersten voll mit Geistern, die seit Ewigkeiten dort eingesperrt sind.\n\nBeseitigt so viele wie möglich und meldet Euch dann bei mir.", progress = nil, completion = "Ihr seid lebendig davongekommen? Ihr seid stärker als ich es bin, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28661] = {title = "Der gefangene Erzmagier", objective = "Ihr müsst Erzmagier Galus töten und mit seinem Stab aus den Verfluchten Tiefen östlich der Baradinfestung zurückkehren.", description = "Seit wir auf Tol Barad gelandet sind, versuchen wir, den Zellenblock in den Verfluchten Tiefen auszuräumen. Jedes Mal, wenn wir uns nähern, taucht dieser Erzmagier auf und drängt uns zurück.\n\nJetzt, da wir die Insel eingenommen haben, ist es an der Zeit, es noch einmal zu versuchen. Begebt Euch dorthin und bringt mir seinen Stab zum Beweis, dass Ihr den Auftrag erledigt habt.", progress = "Konntet Ihr den Erzmagier beseitigen?", completion = "Galus ist tot? Fantastische Arbeit, &lt;Name&gt;. Jetzt können wir die Putzkolonne dort hinunterschicken und den Zellenblock für neue Gefangene vorbereiten.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28662] = {title = "Aus der Vergangenheit lernen", objective = "Ihr habt den Auftrag, aus den Verfluchten Tiefen gleich östlich der Baradinfestung vier Verstaubte Gefängnistagebücher zu holen.", description = "Nun, da wir diese jämmerliche Insel endlich beherrschen, können wir herausfinden, was sie so zugerichtet hat. Einige unserer Kämpfer haben Tagebücher erspäht, gleich westlich von hier am Eingang zum Zellenblock der Verfluchten Tiefen.\n\nUnsere Schriftgelehrten im Basislager werden sich für diese Tagebücher ganz besonders interessieren. Ihr müsst vier davon an Euch bringen und mir so schnell wie möglich übergeben.\n\nSeid vorsichtig, <Name>. Da unten wimmelt's nur so von Untoten.", progress = "Seid Ihr im Besitz der Tagebücher? Die Meldungen besagen, dass sie in den Zellen und auch außerhalb gesichtet wurden.", completion = "Diese Tagebücher sind bestens erhalten, &lt;Name&gt;. Wir machen uns sofort daran, sie zu entziffern. Die Zeit wird zeigen, welche Geheimnisse sie bergen.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28663] = {title = "D-Block", objective = "Ihr wurdet angewiesen, 10 beliebige Dämonen im D-Block, gleich nordwestlich der Baradinfestung, zu töten.", description = "Habt Ihr schon einmal von dem D-Block gehört, <Name>? Das ist einer der Zellenblöcke hier auf der Insel. Das Problem ist, dass er von Dämonen befallen ist. Wir hatten eigentlich vor, dort die verbliebenen Mitglieder der Allianz einzusperren, die wir auf der Insel gefunden haben, aber in seinem momentanen Zustand ist das unmöglich.\n\nIhr müsst dort hinuntergehen und diese Dämonen beseitigen. Meldet Euch wieder bei mir, wenn Ihr das erledigt habt.", progress = "Sind die Dämonen schon erledigt? Wir warten auf Euch, <Name>. Lasst mich wissen, wenn Ihr fertig seid.", completion = "Ist der D-Block ausgeräumt? Gute Arbeit, &lt;Name&gt;. Wir schicken sofort einen Reinigungstrupp los.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28664] = {title = "Svarnos", objective = "Ihr müsst Svarnos im D-Block töten und sein verfluchtes Halsband herbringen. Svarnos befindet sich im D-Block, gleich nordwestlich der Baradinfestung.", description = "Ihr habt Hervorragendes für die Eroberung der Insel geleistet, <Klasse>. Jetzt, da wir die Insel eingenommen haben, müssen wir die Zellenblöcke für die Gefangenen herrichten. Der D-Block war besonders schwer zu bereinigen. Leider wimmelte er nur so von Dämonen aller Art.\n\nWir konnten einige beseitigen, doch dann brach ein großer Kernhund aus seiner Zelle aus - er verwüstet dort alles. Tötet ihn und bringt mir sein Halsband.", progress = "Ist der Kernhund tot?", completion = "Svarnos ist wirklich tot? Sieht aus, als könnten wir endlich loslegen und den Zellenblock herrichten. Danke Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28665] = {title = "Verfluchte Fesseln", objective = "Ihr erhieltet den Auftrag, 8 Verfluchte Fesseln aus dem D-Block, gleich nordwestlich der Baradinfestung, zu holen.", description = "Wart Ihr schon im D-Block, <Name>? Wenn der verseuchte Zellenblock gerade frei ist, sind die Dämonen jedes Mal ganz schnell wieder drin. Man sagte uns, sie regenerieren sich aus den im Gelände verstreuten Verfluchten Fesseln. Da ist Euer Einsatz gefragt, <Name>.\n\nIhr müsst so viele Verfluchte Fesseln wie möglich einsammeln und herbringen. Wir zerstören sie dann sofort.", progress = "Habt Ihr viele Fesseln gefunden? In den Meldungen hieß es, sie seien dort überall verstreut.", completion = "Die Fesseln! &lt;Name&gt;, wir fangen sofort damit an, diese Fesseln zu zerstören. Vielen Dank für Eure Hilfe.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28666] = {title = "Heldenaufruf: Brennende Steppe!", objective = "Meldet Euch bei John J. Keeshan am Flammensternposten in der Brennenden Steppe.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei John J. Keeshan am Flammensternposten zu melden.\n\nIhr müsst dringend helfen, der Bedrohung durch die Schwarzfelsorcs ein Ende zu bereiten!\n\nDer Weg zur Brennenden Steppe führt südlich der Sengenden Schlucht durch den Schwarzfels. Haltet Ausschau nach dem Flammensternposten auf der anderen Seite des Schwarzfels.\n\nRuhm und Ehre der Allianz!", progress = nil, completion = "Höchste Zeit, dass die Schwarzfelsorcs den ganzen Zorn der Allianz zu spüren bekommen. Jetzt werden sie für ihre Untaten büßen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28667] = {title = "Auf Befehl des Kriegshäuptlings: Brennende Steppe!", objective = "Meldet Euch bei Ariok am Flammensternposten in der Brennenden Steppe.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Ariok am Flammensternposten zu melden.\n\nUnterstützt Etriggs geehrten Sohn Ariok und haltet die blinde Aggression der Schwarzfelsorcs auf, ehe sie die Nachbarländer besetzen.\n\nDer Weg zur Brennenden Steppe führt südlich der Sengenden Schlucht durch den Schwarzfels. Der Flammensternposten ist südlich vom Schwarzfels.\n\nDas Schicksal ruft!", progress = nil, completion = "Wir müssen die Schwarzfelsorcs stoppen, bevor sie ihren Einflussbereich ausdehnen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28668] = {title = "Gefangenenaufstand", objective = "Ihr wurdet beauftragt, 10 beliebige Gefangene im Loch zu töten, das südwestlich der Baradinfestung liegt.", description = "Die Insel gehört uns. Jetzt müssen wir unsere Anlagen hier einsatzbereit machen. Wir haben einen aufgegebenen Zellenblock südwestlich von hier gefunden und wir müssen ihn auskundschaften, <Name>.\n\nBerichten zufolge ist er voller Gefangener, die dort drinnen seit Jahren festsitzen. Tut, was immer ihr müsst, um den Ort zu säubern. Meldet Euch bei mir, wenn Ihr fertig seid.", progress = nil, completion = "Ihr habt das Gebiet gesäubert? Es sieht so aus, als ob Ihr Euch als nützlicher erweist, als wir dachten, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28669] = {title = "Der Wärter", objective = "Tötet Wärter Silva im Loch und kehrt mit seinen Schlüsseln zurück. Das Loch ist südwestlich der Baradinfestung.", description = "Wir haben es fast geschafft, die aufständischen Gefangenen im Loch zu beseitigen, doch ein Problem bleibt: Der Wärter.\n\nWärter Silva ist ihr Meister. Für ihn tun sie alles. Wenn wir ihn ausschalten, schalten wir alle aus. Tötet ihn und bringt mir seine Schlüssel. Mit den Schlüsseln können wir den Zellenblock weiter erkunden und hoffentlich auch zur Wasserversorgung der Insel vordringen.", progress = "Ist der Wärter endlich tot?", completion = "Aah, die Schlüssel des Wärters. Wieder einmal habt Ihr gute Arbeit geleistet, &lt;Name&gt;. Diese Schlüssel werden sich noch als nützlich erweisen.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28670] = {title = "Essen von unten", objective = "Ihr wurdet gebeten, 12 Rationen aus dem Zellenblock aus dem Loch südwestlich der Baradinfestung zu besorgen.", description = "Uns gehen die Vorräte im Lager aus, <Name>. Wir haben vor Kurzem von einem Zellenblock südwestlich von hier gehört, in dem nach jahrelangem Betrieb noch Rationen übrig sind. Wir brauchen so viele Rationen wie ihr tragen könnt hier im Lager.\n\nOh, und noch etwas: in dem Zellenblock wimmelt es von Gefangenen, also seid vorsichtig.", progress = "Konntet Ihr die Rationen ausfindig machen? Berichten zufolge kann man sie über den ganzen Ort verteilt finden.", completion = "Die Rationen werden unseren Truppen sehr helfen, &lt;Name&gt;. Vielen Dank für Eure Hilfe.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28671] = {title = "Auf Befehl des Kriegshäuptlings: Verwüstete Lande!", objective = "Meldet Euch bei Okrilla in der Feste Schreckensfels in den Verwüsteten Landen.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Okrilla an der Feste Schreckensfels zu melden.\n\nOkrilla, Kommandantin der Hordenstreitmacht an der Feste Schreckensfels braucht Eure Hilfe bei der Sicherung des Außenpostens vor rebellischen Ogern und der Streitmacht der Allianz.\n\nZieht zur Feste Schreckensfels auf der Straße südlich der Sümpfe des Elends.\n\nDas Schicksal ruft!", progress = nil, completion = "Die Zahl unserer Feinde ist groß, &lt;Klasse&gt;. Sie alle zu überwinden erfordert Tapferkeit und Geschick.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28672] = {title = "Der Exekutor im Feld", objective = "Meldet Euch bei Exekutor Arren.", description = "Ich kann Euch die ganze Woche hier in der Stadt beschäftigen... aber Ihr scheint mir mehr der Kämpfertyp zu sein.\n\n<Elreth nimmt Euch in Augenschein und nickt.>\n\nJa, Ihr seid in Ordnung. Bitte sprecht mit Exekutor Arren. Folgt dem Pfad, der aus Todesend nach Norden herausführt. Ihr findet ihn kurz hinter den Barrikaden.", progress = nil, completion = "Was haben wir denn hier? Ein frischgebackener &lt;Klasse&gt;, der in den Kampf ziehen will, hm?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28673] = {title = "Heldenaufruf: Verwüstete Lande!", objective = "Meldet Euch bei Rüstmeister Lungertz in der Burg Nethergarde.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Rüstmeister Lungertz an der Burg Nethergarde zu melden.\n\nDie Garnison von Nethergarde benötigt dringend Eure Hilfe, um den Vormarsch der Horde in die Verwüsteten Lande zu stoppen! Zieht von den Sümpfen des Elends aus nach Süden und folgt der Straße nach Osten zur Burg Nethergarde.\n\nRuhm und Ehre der Allianz!", progress = nil, completion = "Über Jahrzehnte hat die Garnison in Nethergarde der Bedrohung durch die Horde standgehalten und auch jetzt werden wir uns nicht ergeben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28674] = {title = "Sternfall", objective = "Sprecht mit Wynd Nachtjagd in Sternfall.", description = "Ihr habt Euch hier in der Gegend ja ganz schön nützlich gemacht. Wenn Ihr noch an guten Werken oder Eurer Bezahlung interessiert seid, dann habe ich hier etwas für Euch.\n\nSternfall liegt direkt im Nordwesten der Ewigen Warte. Die Nachtelfen dort klagen über starken Insektenbefall und bitten dringend um Hilfe.\n\nEin paar Goblins von hier sind schon losgezogen, um mit dem Ausrotten zu beginnen. Aber es ist sicher noch Platz für Euch. Sprecht mit Wynd Nachtjagd, er sagt Euch alles Wichtige.", progress = nil, completion = "Willkommen in Sternfall, &lt;Klasse&gt;. In dieser Zeit der Not öffnen wir unsere Tore allen Reisenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28675] = {title = "Heldenaufruf: Sümpfe des Elends!", objective = "Meldet Euch bei Handelsbaron Silberschnapp in Kraulsumpf in den Sümpfen des Elends.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Handelsbaron Silberschnapp in Kraulsumpf zu melden.\n\nDie Kräfte der Allianz brauchen dringend die vom Baron beschaffte Munition! Tut alles Nötige, um den Baron zu überzeugen, unsere Kräfte auch weiterhin zu vernünftigen Preisen zu versorgen.\n\nUm zu den Sümpfen zu gelangen, folgt Ihr der Straße von den südöstlichen Brennenden Steppen durch das Rotkammgebirge.\n\nRuhm und Ehre der Allianz!", progress = nil, completion = "Willkommen in Kraulsumpf, &lt;Klasse&gt;. Ich bin sicher, Ihr werdet all unsere Annehmlichkeiten in vollen Zügen genießen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28676] = {title = "Kammerjäger am Werk", objective = "Sprecht mit Rinno Vorhangfeuer im Grabhügel von Ban'Thallow.", description = "Unser Grabhügel wurde praktisch über Nacht befallen. In diesen Landen unbekannte, heimtückische Kreaturen sind aus unsichtbaren Eiern geschlüpft und sind in die Tunnel ausgeschwärmt.\n\nWir sind nur Wenige. So haben wir nichts weiter tun können, als ihr Vordringen aus dem Hügel zu verhindern. Wir waren gezwungen, Goblins aus der Ewigen Warte anzuheuern. Sie behaupten, Ausrottungsexperten zu sein, doch bisher haben sie keinen Erfolg gehabt.\n\nWenn Ihr sie unterstützen wollt, dann betretet den Grabhügel westlich von dieser Hütte und sprecht mit Rinno Vorhangfeuer.", progress = nil, completion = "Sehr gut, noch jemand zum mit Anpacken!\n\nIch hoffe nur, der Elf oben hat Euch nicht zu Tode gelangweilt. Wir haben hier eine Menge Ungeziefer zu vernichten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28677] = {title = "Auf Befehl des Kriegshäuptlings: Sümpfe des Elends!", objective = "Meldet Euch bei Handelsbaron Silberschnapp in Kraulsumpf in den Sümpfen des Elends.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Handelsbaron Silberschnapp in Kraulsumpf zu melden.\n\nÜberzeugt den Handelsbaron, unsere Krieger weiterhin mit Waffen und Munition zu versorgen. Alle Mittel sind recht!\n\nZu den Sümpfen des Elends gelangt Ihr über die Straße von den südöstlichen Brennenden Steppen durch das Rotkammgebirge. Besucht den Handelsbaron in seinem Seebad. \n\nDas Schicksal ruft!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28678] = {title = "Kapitän P. Harris", objective = "Ihr habt den Auftrag, Kapitän P. Harris am Kap der Verlorenen Hoffnung zu töten. Das Kap der Verlorenen Hoffnung liegt gleich nordwestlich von hier, die Küste entlang. Haltet einfach Ausschau nach den Schiffswracks.", description = "Das Kap der Verlorenen Hoffnung steckt uns hier auf Tol Barad seit Wochen wie ein Stachel im Fleisch. Die Hälfte unserer Versorgungsschiffe endet auf den Felsen dort unten.\n\nHinzu kommt, dass es von einer Bande untoter Matrosen überrannt wurde. Wir haben versucht, sie zu dezimieren, aber sie kommen immer wieder zurück. Unsere letzte Hoffnung ist es, den Kapitän zu töten, der ihnen ihre Befehle gibt. Ihr solltet ihn auf einem Schiff nahe des Ufers finden.\n\nOh, und ich hoffe, Ihr habt keine große Angst vor Haien.", progress = "Habt Ihr den riesigen Hai da draußen gesehen? Ich würde mich ihm nicht weiter als 50 Meter nähern, wenn ich Ihr wäre.", completion = "Ihr habt es geschafft! Vielleicht schaffen es jetzt endlich ein paar Schiffe in den Hafen! Danke sehr, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28679] = {title = "Stört ihre vorletzte Ruhe", objective = "Dritter Offizier Kronkar hat Euch beauftragt, 8 schiffbrüchige Seemänner am Kap der Verlorenen Hoffnung zu töten. Das Kap liegt genau im Nordwesten von hier am Strand.", description = "Seit einiger Zeit haben wir Probleme mit den Untoten unten am Kap der Verlorenen Hoffnung. Bei jedem neuen Schiffbruch schließen sich ihnen neue Untote an.\n\nKönnt Ihr uns einen Gefallen tun und die Mannschaft dort etwas ausdünnen? Ich weiß, Ihr könnt sie nicht alle töten, aber jeder Beitrag ist für uns von Nutzen.\n\nHaltet ein Auge auf die Allianz, in letzter Zeit wird gemeldet, dass ihre Kämpfer am Strand im Hinterhalt liegen.", progress = nil, completion = "Gute Arbeit mit den Untoten da oben, &lt;Name&gt;. Wir wissen Eure Hilfe wirklich sehr zu schätzen.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28680] = {title = "Stärkung der Moral", objective = "Ihr habt den Auftrag, aus den Schiffswracks am Kap der Verlorenen Hoffnung 6 Fässer Südseerum zu beschaffen. Das Kap liegt nördlich von hier, an der Küste.", description = "Unsere Kampfmoral ist geschwächt, <Name>. Wir tun alles, um den Kampfgeist der Truppen zu stärken, doch unser wichtigstes Mittel geht zur Neige. Ich spreche vom Rum.\n\nUnsere Infanterie meldet aus dem Süden, dass die Schiffswracks am Kap der Verlorenen Hoffnung beträchtliche Mengen an Südseerum gebunkert haben. Könnt Ihr Euch dorthin begeben und dem nachgehen?\n\nBringt so viel Rum her, wie Ihr nur könnt.", progress = "Habt Ihr den Rum zurückholen können? Ich würde es ja versuchen, aber ich habe Todesangst vor dem Wasser. Ganz zu schweigen von dem verrückten Hai.", completion = "Der Rum hilft uns sehr, &lt;Name&gt;. Auch wenn's ihnen morgens nicht so gut geht, wenigstens schlafen sie glücklich ein.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28681] = {title = "Tank, der Haifisch", objective = "Ihr müsst Tank, den großen Hai, der die Gewässer des Kaps der Verlorenen Hoffnung unsicher macht, töten. Das Kap liegt nördlich von hier, an der nördlichen Küste.", description = "Ich hasse Haie. Und meine Truppen auch. Deshalb brauchen wir Euch, <Name>.\n\nIhr müsst Euch zum Kap der Verlorenen Hoffnung begeben und einen riesigen Haifisch namens Tank zur Strecke bringen. Tank ist nicht auf die leichte Schulter zu nehmen. An Eurer Stelle würde ich ein paar Freunde mitnehmen.", progress = nil, completion = "Das gibt's doch nicht - Ihr habt ihn wirklich getötet? Oh ja - und heut' Abend gibt's Haifischbraten!", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28682] = {title = "Einnahme der Festung", objective = "Eure Aufgabe lautet, Festungslord Farson in der Farsonfestung zu töten. Die Farsonfestung befindet sich auf der Nordseite der Insel.", description = "Habt Ihr die Festung im Norden der Insel gesehen, <Name>? Von dort aus koordiniert Festungslord Farson seine Kriegszüge.\n\nFarson verfügt über einen kleinen Trupp ergebener Gefolgsleute. Seit wir hier eintrafen, machen sie uns Ärger. Wir haben einen Erkundungstrupp vorausgeschickt, der uns seinen genauen Standort in der Festung gemeldet hat.\n\nKönnt Ihr ihn für uns erledigen?", progress = nil, completion = "Habt Ihr ihn umgebracht? Mehrere Wochen haben wir schon versucht, ihn zu erledigen! Wir danken Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28683] = {title = "Ausdünnen der Brut", objective = "Tötet 12 Dunkelwaldlauerer im Finsterwald. Der Finsterwald liegt direkt nördlich von hier, jenseits der Brücke auf der mittleren Insel.", description = "Seit Wochen versuchen wir schon, im Finsterwald Fuß zu fassen, aber dort wimmelt es nur so von Spinnen. Tut mir einen Gefallen und schaut, ob Ihr ihre Zahl soweit eindämmen könnt, dass wir einen Angriff starten können.\n\nDoch seid vorsichtig da draußen. Mir wurde berichtet, dass Anfang der Woche Allianzruppen dort gesichtet wurden.", progress = nil, completion = "Den Spinnen habt Ihr es gezeigt, &lt;Name&gt;. Wenn wir so weitermachen, ist der Wald im Handumdrehen unser.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28684] = {title = "Eine klebrige Angelegenheit", objective = "Sammelt 4 klebrige Seidendrüsen von Dunkelwaldbrutmutterspinnen im Finsterwald. Der Finsterwald liegt gleich westlich von hier, hinter der Brücke in der Mitte der Insel.", description = "Auf dieser Insel Vorräte zu sammeln, hat sich, gelinde gesagt, als schwierig erwiesen.\n\nGlücklicherweise haben wir ein gutes Angebot an Seide ausmachen können, im Finsterwald, direkt westlich von hier. Der Nachteil an der Sache ist, dass die Seide aus den Drüsen von Brutmutterspinnen gewonnen werden muss. Ich möchte, dass Ihr mir vier davon besorgt.\n\nDas sollte genügen, um die letzte Ladung Hemden fertigzustellen.", progress = "Habt Ihr die klebrigen Seidendrüsen?", completion = "Diese Drüsen sind perfekt. Wir danken Euch für Eure Hilfe, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28685] = {title = "Lasst keine Waffen zurück", objective = "Beschafft 12 rostige Gewehre aus der Farsonfestung auf der Nordseite der Halbinsel von Tol Barad.", description = "Auf diesem Felsen kommt man nur schwer an Kampfgerät. Jedes Mal, wenn wir die Allianz abwehren, kommt es uns vor, als kämpften wir mit Stöcken und Steinen.\n\nWir haben gehört, dass Festungslord Farson im Norden der Insel einen großen Vorrat an Gewehren hat. Könnt Ihr Euch dort hinbegeben und Euch darum kümmern?\n\nVorsicht, <Name>, um Farson zu schützen, schreckt seine Gefolgschaft vor nichts zurück.", progress = "Wie läuft's mit den Gewehren?", completion = "Vielen Dank, dass Ihr die für uns aufgetrieben habt, &lt;Name&gt;. Es ist wirklich kein Kinderspiel, eine Schlacht ohne Gewehre zu führen.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28686] = {title = "Nicht die freundlichste Stadt", objective = "Kommandant Larmash möchte, dass Ihr 14 Bewohner vom Rostberg tötet. Rostberg liegt nördlich des Baradinbasislagers auf der rechten Seite.", description = "Wart Ihr schon oben auf dem Rostberg, <Name>? Ich würde Euch raten, eine frisch geschärfte Klinge mitzunehmen, wenn Ihr dorthin wollt.\n\nDie Leute in dem Dorf sehen vielleicht anständig aus, aber dort geht etwas Seltsames vor sich. Berichten zufolge erledigen sie unsere Soldaten – einen nach dem anderen. Wir haben es langsam satt. Also müsst Ihr für mich dorthin gehen und ein wenig aufräumen.\n\nErledigt so viele Dorfbewohner wie möglich und dann meldet Euch wieder bei mir, wenn Ihr fertig seid.", progress = nil, completion = "Ich habe doch gesagt, dass das Dorf voller Verrückter ist. Ihr habt beim Aufräumen dort gute Arbeit geleistet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28687] = {title = "Lehrt einen hungrigen Mann das Fischen... oder das Stehlen", objective = "Ihr müsst 22 Rostbergseebarsche aus Rostberg stehlen. Die Fische befinden sich in einer Reihe von Ständen an den Docks an der Rückseite des Dorfes. Rostberg liegt nördlich des Basislagers auf der rechten Seite.", description = "Rostberg. Dieser Ort ist für uns ein Fluch und gleichzeitig ein Segen, <Name>. Ich habe keine Ahnung, wo die Räuber gelernt haben, so gut zu fischen, aber ich habe jetzt auch keine Zeit, mir darüber den Kopf zu zerbrechen.\n\nIhr müsst dorthin gehen und so viele ihrer Fischreserven wie nur möglich stehlen. Wir leben von Abfällen, seit wir die Insel wieder unter Kontrolle haben und dies ist für uns die beste Gelegenheit, ein paar anständige Lebensmittelvorräte in die Finger zu bekommen.\n\nNehmt Euch dort oben vor Herumschleichern in Acht. Berichten zufolge sind sie innerhalb der Dorfmauern ziemlich verbreitet.", progress = "Hattet Ihr Erfolg und habt Ihr uns ein wenig Fisch mitgebracht?", completion = "Diese Fische werden uns trefflich munden, &lt;Name&gt;. Die Truppen anständig zu verpflegen und in guter Verfassung zu erhalten hat für uns absoluten Vorrang und Ihr habt Euch sehr für uns eingesetzt.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28688] = {title = "Auf Befehl des Kriegshäuptlings: Das Nördliche Schlingendorntal!", objective = "Meldet Euch bei Kommandant Aggro'gosh im Basislager Grom'gol im Nördlichen Schlingendorntal.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Kommandant Aggro'gosh im Basislager Grom'gol zu melden. Der Kommandant benötigt Eure Hilfe dabei, die Nachschublinien offen und frei von Störungen durch Einheimische und die lästigen Allianzler zu halten.\n\nUm zu Grom'gol zu gelangen, könnt Ihr den Zeppelin an Orgrimmars östlichem Zeppelinturm oder den in der Nähe der Unterstadt nehmen.\n\nFolgt dem Ruf des Schicksals!", progress = nil, completion = "Endlich. Die Verstärkungen des Kriegshäuptlings sind eingetroffen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28689] = {title = "Die Vergessenen", objective = "Erlöst die Geister von 6 gequälten Seelen am Vergessenen Hügel. Seelen können kanalisiert werden, indem Ihr Eure Hände direkt auf ihre Grabsteine legt. Der Vergessene Hügel liegt westlich von hier jenseits der Rastlosen Front.", description = "Viele Soldaten sind schon auf dieser Insel gestorben, <Name>. Es ist nur recht und billig, dass wir ihnen unseren Respekt auf jede uns mögliche Art zollen.\n\nIhr müsst für mich zum Vergessenen Hügel reisen, der westlich von hier liegt. Dort müsst Ihr die gequälten Seelen unsere Waffenbrüder erlösen. Aber seid dort drüben wachsam. Es häufen sich Berichte von Aktivitäten der Untoten in diesem Gebiet.", progress = nil, completion = "Mögen ihre Seelen in Frieden ruhen.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28690] = {title = "Bergt die Überreste", objective = "Ihr müsst 9 verfluchte Oberschenkelknochen von den Ghulen bergen, die sich auf dem Vergessenen Hügel herumtreiben. Der Vergessenen Hügel liegt auf der Westseite der Vergessenen Insel hinter der Rastlosen Front.", description = "Der Vergessene Hügel ist von Zombies und Ghulen überrannt worden, seit dem Tag, an dem wir diese erbärmliche Insel für uns beanspruchten. Wir haben versucht, sie loszuwerden, aber es scheint, als kämen sie immer wieder.\n\nEiner unserer Leutnants hat vorgeschlagen, die Ghulknochen wegzuräumen, nachdem wir sie getötet haben, in der Hoffnung, dass sie nicht über Nacht wiederauferstehen. Glaubt Ihr, dass Ihr uns hierbei helfen könntet?", progress = "Konntet Ihr die verfluchten Oberschenkelknochen bergen? Besser Ihr als ich.", completion = "Ich hätte nicht gedacht, dass Ihr das fertig bringen würdet, &lt;Name&gt;. Ihr steckt voller Überraschungen, nicht wahr?", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28691] = {title = "Oberleutnant Connor", objective = "Findet und tötet Oberleutnant Connor auf dem Vergessenen Hügel. Ihr findet den Vergessenen Hügel auf der westlichen Seite der Insel.", description = "Als ich das erste Mal von Oberleutnant Connor hörte, war ich ein junger Rekrut im Flammenschlund. Niemand von uns hätte je gedacht, dass er mal hier auf Tol Barad enden würde. Traurigerweise wandert er noch immer über diese elenden Inseln und richtet verheerenden Schaden an der Moral unserer Truppen an.\n\nIch möchte, dass Ihr seinem Elend ein Ende macht... und damit unserem.", progress = nil, completion = "He, Ihr habt es lebendig hierher zurück geschafft! Ich kann nicht behaupten, dass Ihr der Erste wart, der dieses Unterfangen versucht hat, aber Ihr seid gewiss der Erste, der in einem Stück zurückkehrt.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28692] = {title = "Goblinischer Magnetismus", objective = "Ihr habt die Aufgabe erhalten, 7 Teile Belagerungsmaschinenschrott aufzutreiben. Verwendet den magnetisierten Schrottsammler an der Rastlosen Front, um die Schrottteile zu finden. Die Rastlose Front befindet sich im Westen hinter der zweiten Brücke.", description = "Es fällt einem schwer, auf dieser Insel brauchbare Maschinenteile zu bekommen, <Name>. Wir haben versucht, die kaputte Belagerungsmaschine hier im Lager zu reparieren, aber uns gehen immer wieder die Ersatzteile aus.\n\nUnser zweites Regiment meldet ein paar demolierte Belagerungsmaschinen auf einem ehemaligen Schlachtfeld im Westen. Vielleicht findet Ihr dort ein paar Teile?\n\nEs wird nicht leicht sein, auf diesem Schlachtfeld irgendetwas zu finden, also nehmt diesen magnetisierten Schrottsammler mit. Er wird Euch sicherlich von Nutzen sein.", progress = "Hat die Magnetapparatur tatsächlich funktioniert?", completion = "Diese Teile helfen uns wirklich weiter, &lt;Name&gt;! Wer hätte gedacht, dass man in dem ganzen alten Schrott so viel nützliches Zeug finden würde?", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28693] = {title = "Bringt es zu Ende", objective = "Tötet 5 rastlose Soldaten an der Rastlosen Front. Ihr findet die Front auf der westlichen Seite der Insel, direkt vor dem Vergessenen Hügel.", description = "Wir versuchen schon die ganze Woche, an der Front brauchbaren Schrott zu sammeln. Jedes Mal, wenn wir eine Ladung zusammengestellt haben und sie zum Lager zurückbringen wollen, werden wir von den rastlosen Soldaten aus der Umgebung angegriffen. Könntet Ihr Euch dorthin begeben und sie beseitigen?", progress = nil, completion = "Wurde auch Zeit, dass sich die Burschen jemand vorknöpft.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28694] = {title = "Achtung, Splitter", objective = "Gefreiter Sarlosk hat Euch gebeten, 15 Stück Schiffsbauholz aus Wellsons Werft zu holen. Das Holz kann von den Geistern in der Werft beschafft werden und es liegt auf dem Gelände verstreut herum. Die Werft befindet sich nordwestlich von hier an der Küste.", description = "Wart Ihr schon drüben bei Wellsons Werft, <Name>? Man sollte sich unbedingt von dort fernzuhalten. Es sei denn, man hat einen guten Grund, sich dort hineinzuwagen. Unglücklicherweise muss ich Euch genau darum bitten.\n\nSeit wir diese Insel zurückerobert haben, sind wir knapp an Vorräten. Die von Geistern heimgesuchte Werft quillt über vor Nutzholz, aber jedes Mal, wenn wir eine Eskorte dorthin schicken, um das Holz zu holen, kommt sie nicht zurück.\n\nWürdet Ihr uns helfen?", progress = "Haben die Geister Euch fortgescheucht?", completion = "Ich hätte nicht gedacht, dass Ihr das schaffen würdet, &lt;Name&gt;. Ihr steckt voller Überraschungen, nicht wahr?", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28695] = {title = "GESUCHT: Vorarbeiter Wellson", objective = "Tötet Vorarbeiter Wellson in Wellsons Werft. Die Werft befindet sich nördlich von hier an der Westküste.", description = "Vorarbeiter Wellson piesackt uns schon, seit wir hierhergekommen sind. In seiner Werft gibt es große Mengen an Vorräten, die für uns extrem nützlich wären... Wenn wir nur zu ihnen gelangen könnten.\n\nEr hat seine Schergen gut im Griff und macht es uns sehr schwer, in der Werft Fuß zu fassen. Diesmal müsst Ihr Wellson für mich endgültig erledigen. Seid vorsichtig, <Name>. Wir haben Berichte erhalten, nach denen es in dem Gebiet von dreckigen Allianzlern nur so wimmelt.", progress = nil, completion = "Hervorragende Arbeit, &lt;Name&gt;. Ich werde Euren Einsatz unverzüglich dem Oberbefehlshaber melden.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28696] = {title = "Bom-ben-los!", objective = "Zerstört 10 scheußliche Versorgungsboote.", description = "Wellsons Werft empfängt dauernd Vorräte von den Küstengewässern aus und das muss aufhören. Sie haben Kanonen an den Docks aufgestellt, um sich zu verteidigen, aber wenn Ihr zu ihnen durchbrechen könnt, können wir mit ihnen die Versorgungsschiffe zerstören.\n\nBegebt Euch dorthin und seht mal, was Ihr tun könnt. Erstattet mir über Eure Fortschritte Bericht.", progress = nil, completion = "Ausgezeichnete Arbeit mit den Versorgungsbooten, &lt;Name&gt;! Wir wussten, dass Ihr was taugt!", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28697] = {title = "Geisterjäger", objective = "Tötet 14 beliebige Geister bei Largos Warte nordöstlich des Hordelagers.", description = "Seht Ihr den Hügel mit den Türmen im Nordosten? Das ist Largos Warte und es ist nicht der schönste Ort, um daneben ein Lager zu errichten. Wir mussten uns mit Geistern und Schreckgespenstern herumschlagen, seit wir unser Basislager hier aufgeschlagen haben.\n\nKönnt Ihr Euch dorthin begeben und sie wissen lassen, dass wir nicht vorhaben, uns sobald von hier wegzubewegen? Ein paar Abschüsse in ihren Reihen sollten sie zur Räson bringen.\n\nVielen Dank für Eure Hilfe hierbei, <Name>.", progress = "Wer hat Angst vor Geistern? Ich ganz bestimmt nicht. Na gut, vielleicht im Dunklen.", completion = "Hervorragend, &lt;Name&gt;! So bald sollten wir von den Geistern nichts mehr hören.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28698] = {title = "Kanonenkugel!", objective = "Ihr müsst 4 Haufen Kanonenkugeln aus Largos Warte für den Gefreiten Sarlosk beschaffen. Ihr findet Largos Warte direkt nordöstlich des Basislagers.", description = "Largo und seine Schergen bedienen sich an unsere Vorräten, seitdem wir hier unser Basislager aufgeschlagen haben. Es ist frustrierend, um es gelinde auszudrücken.\n\nWir haben Berichte erhalten, dass er oben in seiner Warte in den Türmen mit Blick aufs Meer Kanonenkugeln hortet. Könntet Ihr Euch dort hinauf begeben und versuchen, ein paar davon für uns zu beschaffen?\n\n<Name>, vergesst nicht, dabei Ausschau nach Allianzlern zu halten.", progress = "Habt Ihr die Kanonenkugeln gefunden?", completion = "Gute Arbeit mit der Beschaffung, &lt;Name&gt;. Diese Kanonenkugeln sollten eine Weile reichen.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28699] = {title = "Heldenaufruf: Das Nördliche Schlingendorntal!", objective = "Meldet Euch bei Leutnant Doren im Rebellenlager im Nördlichen Schlingendorntal.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Leutnant Doren im Rebellenlager zu melden.\n\nAuch Jahre nach Colonel Kurzens Verrat gegen Sturmwind bleibt die Wahrheit über das, was geschehen ist, ein Rätsel. Helft den Überlebenden dabei, zu erfahren, was aus dem Colonel geworden ist. Reist vom Dämmerwald aus nach Süden und nachdem Ihr den Dschungel erreicht habt, folgt der Straße nach Westen, um zum Rebellenlager zu gelangen.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Willkommen in unserem Lager, &lt;Klasse&gt;, auch wenn wir hier nichts Besonderes für Euch haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28700] = {title = "Die Rückeroberung der Warte", objective = "Gefreiter Sarslok hat Euch beauftragt, Kommandant Largo in Largos Warte zu töten. Die Warte befindet sich direkt nordöstlich des Basislagers.", description = "Es gibt nur eine Möglichkeit, wie wir Largos Warte zurückzuerobern können.\n\nIch glaube, Ihr wisst, was Ihr tun müsst, <Name>. Largo ist in letzter Zeit ziemlich paranoid. Ihr solltet ihn also auf der Turmspitze finden, wo er nach seiner eingebildeten Flotte Ausschau hält.", progress = nil, completion = "Ha! Endlich haben wir Largo erledigt! Sehr gut, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nBelobigungsabzeichen von Tol Barad"}
MultiLanguageQuestData['de'][28701] = {title = "In Sicherheit", objective = "Beschafft 5 Relikte von Sternfall aus den Grabhügeln von Ban'Thallow.", description = "Als diese Plage ausgebrochen ist, lagen glücklicherweise keine Druiden im westlichen Grabhügel. Es ist für uns jedoch noch immer eine heilige Stätte und in ihr befinden sich heilige Relikte, die schon seit langer Zeit dort unbehelligt ruhen.\n\nObwohl ich den goblinischen Kammerjägern auf eine Art vertraue, bin ich außerdem... mit den Besonderheiten vertraut, die ihr Volk ausmachen. Bitte bergt aus dem Grabhügel so viele Relikte, wie Ihr finden könnt und bringt sie zu mir zurück, damit sie nicht beschädigt werden. Sie befinden sich in Urnen, die in kleinen Nischen im Hügel aufbewahrt werden.", progress = "Ich hoffe, sie waren unversehrt...", completion = "In Euren Augen mögen sie vielleicht nichts Besonderes sein, aber diese Relikte sind für das Volk von Sternfall von unschätzbarem Wert. Ihr seid sehr gütig, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28702] = {title = "Heldenaufruf: Das Schlingendornkap!", objective = "Meldet Euch bei Bronwyn Hackschlag an der Grabungsstätte der Forscherliga am Schlingendornkap.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Bronwyn Hackschlag an der Grabungsstätte der Forscherliga zu melden.\n\nDie Expedition der Forscherliga braucht Eure Hilfe bei der Sicherung der Grabungsstätte und der Bekämpfung der plündernden Oger. Reist vom Nördlichen Schlingendorntal Richtung Süden und folgt der Straße zur Grabungsstätte der Forscherliga.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Es ist gut, dass Ihr hier seid, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28703] = {title = "Hinab in den Hügel", objective = "Tötet 10 Krabbler der Kaltlaurer und 5 Wühler der Kaltlaurer.", description = "Ich habe noch immer keine Ahnung, wo all diese Käfer hergekommen sind. Ich vermute, dass der Kataklysmus ein paar ihrer Nester im Untergrund aufgewühlt hat, von denen wir keine Ahnung hatten, dass sie existierten.\n\nAber es nützt nichts, sich darüber den Kopf zu zerbrechen, da wir sie ohnehin töten!", progress = nil, completion = "Hey, gute Arbeit!\n\nWenn Ihr irgendwann Lust habt, wieder hierher zu kommen und noch ein paar Käfer völlig ohne weitere Belohnung zu töten, tut Euch keinen Zwang an!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28704] = {title = "Auf Befehl des Kriegshäuptlings: Das Schlingendornkap!", objective = "Meldet Euch bei Sassy Hartzang in Hartzangs Versteck am Schlingendornkap.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Sassy Hartzang in Hartzangs Versteck zu melden. Sie benötigt Eure Hilfe mit ein paar Piraten und Naga, die den Dschungel überrannt haben. \n\nReist zu Hartzangs Versteck, indem Ihr vom Nördlichen Schlingendorntal Richtung Süden reist und nach der Stadt südwestlich der Arena der Gurubashi Ausschau haltet.\n\nFolgt dem Ruf des Schicksals!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28705] = {title = "Auf Befehl des Kriegshäuptlings: Die Scherbenwelt!", objective = "Meldet Euch bei Generalleutnant Orion an den Stufen des Schicksals auf der Höllenfeuerhalbinsel.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Generalleutnant Orion an den Stufen des Schicksals zu melden.\n\nDort werden Eure Fähigkeiten benötigt, um die Anwesenheit der Brennenden Legion auf den zerschmetterten Resten der Scherbenwelt zu bekämpfen.\n\nBegebt Euch zu Orgrimmars Kluft der Schatten und verwendet das Portal in der Nähe des Magierlehrers, um in die Verwüsteten Lande zu gelangen. Dann reist durch das Dunkle Portal selbst, um die Höllenfeuerhalbinsel zu erreichen.\n\nFolgt dem Ruf des Schicksals!", progress = nil, completion = "Bereitet Euch auf den Kampf vor. Die Horde braucht Euch hier.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28706] = {title = "Räuchert sie aus", objective = "Bringt die Kiste mit Käfertodräucherapparaten zu Remma Vorhangfeuer im Grabhügel von Ban'Thallow.\n\nBereitgestellter Gegenstand: \n", description = "Meine Geschwister sind schon weiter unten im Hügel und versuchen, mit diesen Käfern fertigzuwerden, aber sie werden langsam von ihnen überwältigt. Ich sage, es wird Zeit, diese Höhle auszuräuchern.\n\nNehmt diese Räucherapparate. Aber setzt sie nicht selbst ein. Dazu muss man ein gut ausgebildeter Profi sein und das richtige Timing haben. Findet meine Geschwister und verteilt die Geräte an sie.\n\nRemma sollte sich in der Nähe des Eingangs befinden. Begebt Euch den Gang entlang und haltet Euch rechts, sobald Ihr die Rampe hinuntergeht.", progress = nil, completion = "Ihr bringt mir den Käfertod, wie? Ich schätze, dann geht es wohl nicht anders.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28707] = {title = "Räuchert sie noch mal aus", objective = "Bringt die Kiste mit Käfertodräucherapparaten zu Marcy Vorhangfeuer im Grabhügel von Ban'Thallow.", description = "Ich werde den hier jetzt vorbereiten.\n\nDer nächste ist für Marcy. Sie ist weiter unten im Hügel. Geht diesen Gang entlang und sucht nach ihr in der nächsten Hauptkammer.", progress = "Ich habe nicht damit gerechnet, hier unten einen Fremden zu treffen!", completion = "Räucherapparate? Von Rinno? Oje...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28708] = {title = "Heldenaufruf: Die Scherbenwelt!", objective = "Meldet Euch bei Kommandant Duron an den Stufen des Schicksals auf der Höllenfeuerhalbinsel.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Kommandant Duron auf der Höllenfeuerhalbinsel zu melden.\n\nDie Expeditionskräfte benötigen Eure Unterstützung bei der Bekämpfung der Dämonenarmeen der Brennenden Legion! Verwendet das Portal auf der mittleren Ebene des Turms im Magierviertel, um in die Verwüsteten Lande zu gelangen. Dann reist durch das Dunkle Portal, um die Stufen des Schicksals in der Scherbenwelt zu erreichen.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Die Expedition braucht Eure Hilfe, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28709] = {title = "Heldenaufruf: Nordend!", objective = "Meldet Euch bei Rekrutierungsoffizier Blythe in der Valianzfeste in der Boreanischen Tundra.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Rekrutierungsoffizier Blythe in der Valianzfeste in der Boreanischen Tundra zu melden.\n\nDie Expedition Valianz benötigt Eure Hilfe dabei, die Kräfte der Geißel unter Kontrolle zu halten und die zivilisierten Länder zu sichern! Begebt Euch zu den Docks von Sturmwind und nehmt das Schiff nach Norden zur Valianzfeste.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Die Expedition braucht Eure Hilfe, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28710] = {title = "Räuchert sie schon wieder aus", objective = "Bringt die Kiste mit Käfertodräucherapparaten zu Sana Vorhangfeuer im Grabhügel von Ban'Thallow.", description = "Rinno hätte uns ruhig mehr Unterstützung schicken können, als nur Euch, <Klasse>! Dieser Schmarotzer...\n\nIch werde den hier jetzt aufstellen. Begebt Euch von diesem Raum aus nach Norden durch den Gang und sucht nach Sana. Sie hat sich vermutlich in der letzten Kammer verirrt. Also seht auch in den Seitengängen nach, sobald Ihr dort eintrefft.", progress = "Was macht Ihr hier?", completion = "Rinno hat Euch geschickt? Und ihr habt... Räucherapparate dabei? Pfui!", rewards = "VorhangfeuermantelAusräucherergamaschenAuf Euch wartet eine dieser Belohnungen:\n\nPestizidring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28711] = {title = "Auf Befehl des Kriegshäuptlings: Nordend!", objective = "Meldet Euch beim Rekrutierungsoffizier des Kriegshymnenklans in der Kriegshymnenfeste in der Boreanischen Tundra.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend beim Rekrutierungsoffizier des Kriegshymnenklans in der Kriegshymnenfeste zu melden.\n\nDie Kriegshymnenoffensive benötigt Eure Hilfe dabei, die anhaltende Bedrohung durch die Untoten der Geißel zu beenden.\n\nNehmt den Zeppelin an Orgrimmars westlichem Zeppelinturm zur Kriegshymnenfeste und stellt Euch beim Rekrutierungsoffizier vor.\n\nFolgt dem Ruf des Schicksals!", progress = nil, completion = "Die Kriegshymnenoffensive könnte mehr von Eurer Sorte gebrauchen, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28712] = {title = "Auftritt der Drachenkönigin", objective = "Sprecht mit Lirastrasza im Kreis des Lebens im Schattenhochland.", description = "Hallo, <Volk>. Ich wünschte, unser Treffen würde unter erfreulicheren Umständen stattfinden. Die Welt hängt an einem seidenen Faden und alles, was die Titanen erschaffen haben, steht auf dem Spiel.\n\nEs betrübt mich zutiefst, aber mein Urteil ist unumstößlich. Todesschwinge, die entsetzliche Kreatur, die einst der Erdwächter und mein Freund war, muss vernichtet werden.\n\nIch habe eine Stätte oben im Hochland errichtet. Sie liegt westlich des Zinnoberrefugiums. Dort kann ich es zu Ende bringen. Sucht nach dem Kreis des Lebens. Darin befindet sich Lirastrasza. Sprecht mit ihr. Ich werde dort zu Euch stoßen.", progress = nil, completion = "Hallo, &lt;Volk&gt;. Ich habe gehört, dass Ihr bei unserem Vorstoß gegen Grim Batol von großer Hilfe wart. Habt Dank!\n\nAlexstrasza hat diesen Boden geheiligt, in der Hoffnung damit Todesschwinge hierher zu locken. Sie wird eine Zeremonie durchführen, um ihn hervorzulocken und ihn dann in diesem heiligen Kreis zu vernichten.\n\nHoffen wir, dass ihr Plan aufgeht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28713] = {title = "Das Gleichgewicht der Natur", objective = "Tötet 6 junge Nachtsäbler.", description = "Seid gegrüßt, <Name>. Ich bin Ilthalaine. Meine Aufgabe im Laubschattental besteht darin, junge Helden wie Euch auszubilden, <Klasse>, und sicherzustellen, dass das Naturgleichgewicht erhalten bleibt.\n\nDer Frühlingsregen war dieses Jahr besonders reichlich. Einige Geschöpfe des Dschungels haben davon profitiert und andere haben darunter gelitten. Unglücklicherweise ist die Zahl der Nachtsäbler zu groß geworden und sie werden andere Kreaturen ausrotten, wenn sie nicht selbst dezimiert werden.\n\nReist weiter, <Klasse>, und dünnt die Population der Nachtsäbler aus, damit die Harmonie der Natur erhalten bleibt.", progress = "Ihr habt noch immer zu tun, <Name>. Kehrt zu mir zurück, sobald Ihr die Population der Nachtsäbler dezimiert habt.", completion = "Ihr seid Eurer Pflicht vorbildlich nachgekommen, &lt;Name&gt;.", rewards = "Ausbildungshandschuhe zum BogenschießenStammblattarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28714] = {title = "Verderbtes Teufelsmoos", objective = "Sammelt 6 Teufelsmoose von den Grellkin im Westen von Ilthalaine.", description = "Ihr scheint zu wissen, was Ihr tut. Vielleicht kann ich Euch mit einer etwas gewichtigeren Aufgabe betrauen.\n\nWie Ihr vielleicht wisst, wurde die Verderbnis in Teldrassil angeblich ausgemerzt. Und doch geht etwas Verdorbenes um. Die Kreaturen haben sich nicht beruhigt und es plagen uns weiter alle möglichen Probleme.\n\nIhr müsst Euch um die Grellkin kümmern, die sich im Westen versammelt haben und während Ihr dort seid, möchte ich, dass Ihr sie nach Teufelsmoos absucht. Dies wird mir helfen, herauszufinden, woher diese fortgesetzte Verderbnis stammt.", progress = "Bestätigt meinen Verdacht, <Name>. Bringt mir das Teufelsmoos von den Grellkin.", completion = "Für Euren Dienst an den Geschöpfen des Laubschattentals habt Ihr Euch eine Belohnung verdient, &lt;Name&gt;.\n\nMeine Sorge habt Ihr jedoch bestätigt. Die Grells sind trotz der Segnung Teldrassils noch immer vom Teufelsmoos befleckt. Etwas Finsteres ist in dem Baum verblieben. Ich kann nur hoffen, dass der Furbolgstamm der Knarzklauen frei von Verderbnis ist, oder wir sind noch immer in großer Gefahr.\n\nIch werde mich näher damit befassen und mich mit denjenigen in Verbindung setzen, die uns helfen können. Habt Dank, &lt;Klasse&gt;.", rewards = "SchutzgamaschenStiefel des FährtenlesensRankenhandschuheIhr bekommt:\n\nHeilkraut"}
MultiLanguageQuestData['de'][28715] = {title = "Dämonische Diebe", objective = "Beschafft Melithars gestohlene Taschen in der Nähe der Grellkin im Westen.", description = "Bösartige kleine Grells! Sie haben schon wieder etwas von unseren Lebensmittelvorräten gestohlen.\n\nWenn es Euch nichts ausmacht, mir zur Hand zu gehen: Sie haben sicherlich meine gestohlenen Taschen in ihrem Lager im Westen. Ich werde Euch mit Freuden belohnen, wenn ihr sie mir zurückbringt.", progress = "Ich habe keine Vorräte für meine Kunden, bis meine gestohlenen Waren wieder bei mir sind. Wie ist es gelaufen?", completion = "Elune sei gepriesen! Und Ihr ebenfalls, &lt;Klasse&gt;.\n\nViele junge Nachtelfen benötigen diese dringend, aber es ist mir eine große Freude, Euch eine dieser Taschen als Belohnung zu überreichen. Ich bin mir sicher, sie wird Euch von Nutzen sein.\n\nIch wünsche Euch eine sichere Reise.", rewards = "Ihr bekommt:\n\nMelithars Vorratstasche"}
MultiLanguageQuestData['de'][28716] = {title = "Heldenaufruf: Das Schattenhochland!", objective = "Sprecht mit König Varian Wrynn in Burg Sturmwind in Sturmwind.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend im Thronraum von Burg Sturmwind einzufinden.\n\nKönig Wrynn benötigt einen vertrauenswürdigen und erfahrenen Helden für eine Aufgabe von höchster Wichtigkeit.\n\nBurg Sturmwind befindet sich im östlichen Teil von Sturmwind.\n\nFür den Ruhm und die Ehre der Allianz!", progress = nil, completion = "Wir sind erfreut, dass Ihr unserem Ruf gefolgt seid, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28717] = {title = "Auf Befehl des Kriegshäuptlings: Das Schattenhochland!", objective = "Meldet Euch bei Garrosh Höllschrei in der Feste Grommash in Orgrimmar.", description = "Allen tauglichen Mitgliedern der Horde wird hiermit befohlen, sich umgehend bei Garrosh Höllschrei in der Feste Grommash zu melden.\n\nDer Kriegshäuptling braucht Eure Hilfe bei der Vorbereitung eines glorreichen Angriffs auf das Schattenhochland und unsere beiden Feinde: die Allianz und den Schattenhammer.\n\nTrefft den Kriegshäuptling in der Feste Grommash, die mitten in Orgrimmars Tal der Stärke liegt.\n\nFolgt dem Ruf des Schicksals!", progress = nil, completion = "Bald wird der Angriff auf das Schattenhochland beginnen und ich will, dass Ihr daran teilnehmt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28718] = {title = "Wo es Rauch gibt, ist auch köstliches Fleisch", objective = "Findet Jez Gutmampf in Gutmampfs Räuchergrube in Winterquell.", description = "Heda, <Klasse>... Mögt Ihr Fleisch? Oder besser: mögt Ihr Geld? \n\nEiner meiner Cousins zweiten Grades verdient sich eine goldene Nase mit Tiefkühlfleisch. Er hat eine Räuchergrube oben im Norden eingerichtet und er braucht Hilfe bei der Jagd auf all die gefährlichen Bestien, die gewöhnlich so vorzüglich schmecken.\n\nFleischfresser zahlen gut. Ich bin hier zu sehr in diesem Grabhügel beschäftigt. Was habe ich mir nur dabei gedacht? Ich kann also den Tipp genauso gut an jemanden wie Euch weitergeben, <Volk>.\n\nSein Name ist Jez. Begebt Euch nach Nordosten und haltet einfach Ausschau nach dem Rauch!", progress = nil, completion = "Seht Euch um. Das ist das größte Jagdreservat in ganz Kalimdor, das in der Hand von Goblins ist! Ich habe eine Abschusslizenz und esse alle Kreaturen, die sich zwischen hier und der Ewigen Warte auf dem Schnee bewegen... Und eins kann ich Euch sagen: Sie schmecken prima!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28719] = {title = "Ein wenig gewöhnungsbedürftig", objective = "Tötet 15 Splitterzahnraufer.", description = "Viele finden das Fleisch des Splitterzahnbären etwas zu gewöhnungsbedürftig. Ich bin anderer Meinung, obwohl es mir nicht zusteht, den Geschmack von anderen zu verurteilen.\n\nDie Splitterzahnraufer jedoch – ihre braunfelligen Cousins im Süden – haben ein sehr viel zarteres Fleisch, besonders an ihren Tatzen. Ich habe gehört, dass die Schnauze ebenfalls als Delikatesse gilt.\n\nSetzt Eure Jagd fort, <Name>. Zeigt mal, ob Ihr diese Splitterzahnraufer für den ollen Francis in den Sack stecken könnt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28722] = {title = "Yetiphobie", objective = "Erschreckt Legacki mit Umis mechanischem Yeti.", description = "Es ist alles bereit, <Name>!\n\nJetzt habe ich meiner Freundin Legacki erzählt, dass ich eine Überraschung für sie habe. Und da kommt Ihr ins Spiel!\n\nIch werde Euch meinen mechanischen Yeti geben und Euch gebührt die Ehre, sie damit zu überraschen. Ihr findet sie auf der anderen Seite der Ewigen Warte in der Nähe des Gasthauses.\n\nBegebt Euch zu Ihr und schaltet den Yeti ein... Ich werde von hier aus zusehen!", progress = "Damit wird sie niemals rechnen!", completion = "Ha! Sie wird es sich zweimal überlegen, bevor sie sich wieder über meine Ideen lustig macht!\n\nHabt Dank für Eure Hilfe, &lt;Name&gt;. Ohne Euch hätte ich nie so viel Spaß gehabt!", rewards = "Schneeschuhe der Ewigen WarteHelm der YetiphobieFinger des StreichespielersAmüsante SchulterstückeUmis meisterliches SchießeisenIhr bekommt:\n\nMechanischer Yeti"}
MultiLanguageQuestData['de'][28723] = {title = "Mondpriesterin", objective = "Sprecht mit Dentaria Silbertal zwischen den beiden Teichen im Zentrum des Laubschattentals.", description = "Jetzt, wo Ihr Euch in Eurer neuen Fähigkeit geübt habt, seid Ihr vielleicht bereit uns beim Kampf gegen die Verderbnis zu helfen, die das Laubschattental heimsucht.\n\nMondpriesterin Dentaria Silbertal hat uns ihre Hilfe angeboten. Ihr solltet sie zwischen den beiden Teichen nördlich unseres Großen Baumes finden. Schlagt einen Bogen um den Baum, um zu ihr zu gelangen und helft ihr so gut Ihr könnt, <Klasse>.", progress = nil, completion = "Es ist gut, dass Ihr gekommen seid. Es scheint, Eure Ausbildung schreitet schnell voran.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28724] = {title = "Iverrons Gegengift", objective = "Sammelt 7 Mondblütenlilien.", description = "Unser Freund Iverron ist vom Gift der Waldweberspinne befallen worden. Ich kann dafür sorgen, dass sich sein Zustand nicht verschlechtert, aber ich brauche jemanden, der eine Zutat sammelt, damit ich ihm ein Gegengift mischen kann.\n\nÜberall um die Teiche herum solltet Ihr Mondblütenlilien finden. Diesen Blumen wohnt eine große Heilkraft inne. Wenn ich sie gemeinsam mit anderen Zutaten verwende, die ich bereits habe, kann ich Iverron wieder gesund machen.\n\nWürdet Ihr sie für mich sammeln? Es müsste viele in Sichtweite von hier in der Nähe des Ufers geben.", progress = "Unserem lieben Freund geht es nicht sehr gut - trotz meiner Pflege. Habt Ihr mir gebracht, was ich benötige?", completion = "Die sind perfekt. Habt Dank, &lt;Name&gt;. Besonders für Eure Schnelligkeit.", rewards = "SeggenriedkniehosenRindenpanzerwesteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28725] = {title = "Die Beschützerin des Waldlandes", objective = "Sucht nach der Dryade mit dem Namen Tarindrella in der Schattenweberhöhle am nördlichen Ende des Laubschattentals.", description = "Nun muss ich Euch um einen Gefallen bitten, der durchaus gefährlich ist. Seltsame Kunde ist mir durch das Tuscheln der Waldgeister zu Ohren gekommen. Die rätselhafte Beschützerin des Waldlandes, Tarindrella, ist ins Laubschattental zurückgekehrt.\n\nDie Anwesenheit der Dryade war das letzte Mal vor der Segnung von Teldrassil zu spüren. Irgendetwas muss im Argen liegen, wenn sie zurück in dieses Land gereist ist.\n\nSucht nach Tarindrella in der Schattenweberhöhle im Norden. Es ist gefährlich, aber wir werden dieses Gegengift sicherheitshalber bereithalten.", progress = nil, completion = "Ich sehe, Ihr habt mich gefunden, &lt;Volk&gt;. Dentaria war weise genug, Euch zu mir zu schicken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28726] = {title = "Verderbnis der Waldweber", objective = "Tötet 12 Waldweberspinnen.", description = "Ich hatte gehofft, niemals wieder wegen solch düsterer Angelegenheiten nach Teldrassil zurückzukehren. Ich hoffte, dass hier die Verderbnis inzwischen vollständig ausgerottet sei. Etwas Schändliches geht um.\n\nDiese Spinnen leiden viel stärker unter der Verderbnis als die anderen Tiere der Umgebung. Sie werden zu einer Gefahr für mein Volk und zu einer Gefahr für den Wald. Wir müssen Ihre Anzahl dezimieren, aber noch wichtiger: Wir müssen die Quelle der Verderbnis finden, die sie plagt.\n\nIch werde mit Euch kommen und Euch in dieser Sache unterstützen.", progress = "Dies ist eine abscheuliche Arbeit. Es schmerzt mich, dass wir so viel Gewalt über ein Geschöpf des Waldes bringen müssen, sei es nun verdorben oder nicht.", completion = "Die Verderbnis, unter der diese Spinnen zu leiden haben, ist nicht nur oberflächlich. Es kann weder Magie sein noch unterschwellige Böswilligkeit. Es ist in sie hineingezüchtet worden.\n\nEs ist offensichtlich, was unsere nächste Aufgabe ist.", rewards = "DistelholzdolchDistelholzstabDistelholzklingeDistelholzschlägelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28727] = {title = "Abscheuliche Berührung", objective = "Tötet Githyiss die Üble am Nordende der Schattenweberhöhle.", description = "Wenn diese Spinnen alle schon mit der Verderbnis in ihren Adern geboren wurden, dann muss ihre Brutmutter die Quelle dieses Bösen sein.\n\nBrechen wir auf in den äußersten nördlichen Winkel dieser Höhle und suchen wir Githyiss die Üble. Sie trägt die Antwort, die wir suchen, in sich.", progress = "Ich verehre diese Wälder. Ich will, dass sie vollständig von dieser Verderbnis befreit werden. Wenn ich das nächste Mal zurückkehre, will ich es froheren Herzens tun.", completion = "Githyiss und ihre Brut wurden von diesem Totem verdorben. Dies ist ein Totem der Furbolgs.\n\nDies ist tatsächlich sehr beunruhigend. Es bedeutet, dass die Knarzklauen noch immer eine Gefahr für diesen Wald darstellen. Wir haben uns zu früh zu sicher gefühlt.", rewards = "Drapierter UmhangGeschwärzter LedergürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28728] = {title = "Anzeichen der Dinge, die da kommen werden", objective = "Sprecht mit Dentaria Silbertal zwischen den beiden Teichen im nördlichen Laubschattental.", description = "Ich werde der Spur der Knarzklauen nachgehen und dieser Verderbnis bis zu ihrer Quelle folgen. Falls Ihr jemals Athridas Bärenfell in Dolanaar begegnet: Er weiß über die Probleme dieses Waldes genauestens Bescheid und er kann Euch raten, wie Ihr weiter helfen könnt. \n\nIch bin mir sicher, dass wir uns wiedersehen. Vielleicht könntet Ihr mir dabei helfen, die Quelle dieser Verderbnis zum Versiegen zu bringen, sobald wir sie ausgemacht haben. Jetzt werde ich Euch zurück zu Dentaria bringen, sodass Ihr Eure Ausbildung abschließen könnt. Habt Dank für alles, was Ihr für uns getan habt, <Name>.", progress = nil, completion = "Ihr seid zurückgekehrt! Es ist gut, dass Ihr hier seid. Es scheint, Ihr habt die Quelle der Verderbnis erfolgreich bekämpft, die große Teile des Laubschattentals bedroht hat.\n\nTeldrassil leidet noch immer und bedarf weiterhin unserer Aufmerksamkeit, aber wir können einen Augenblick dafür aufwenden, Eure Ausbildung hier im Laubschattental abzuschließen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28729] = {title = "Teldrassil: Krone von Azeroth", objective = "Füllt die Kristallphiole am Mondbrunnen im nordöstlichen Laubschattental.", description = "Als Teil des Abschlussrituals Eurer Ausbildung hier im Laubschattental werdet Ihr etwas über unsere jüngere Geschichte erfahren.\n\nDafür müsst Ihr eine Aufgabe erfüllen. Geht zum Mondbrunnen im Nordosten und füllt eine Phiole mit seinem Wasser. Während Ihr dort seid, werdet Ihr einen flüchtigen Augenblick unserer Magie zu Gesicht bekommen und etwas über unsere Vergangenheit erfahren.\n\nWenn Ihr dort fertig seid, bringt das Wasser zu mir zurück und ich werde Euch weitere Anweisungen geben.", progress = "Unsere jüngere Geschichte ist voller Zwietracht und Gewalt. Es gibt noch immer viel, womit wir uns arrangieren müssen.", completion = "Gut gemacht, &lt;Name&gt;. Ihr habt noch eine Aufgabe vor Euch, bevor Ihr vom Laubschattental zur offenen Wildnis von Teldrassil reist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28730] = {title = "Wertvolle Wasser", objective = "Bringt die gefüllte Kristallphiole zu Tenaron Sturmgewalt auf der Spitze von Aldrassil im Laubschattental.", description = "Tenaron Sturmgewalt überwacht alles, was in diesem Tal geschieht. Er hat seinen Wohnsitz auf der Spitze Aldrassils.\n\nFalls Ihr nach Süden blickt, werdet Ihr den unteren Teil der Rampe sehen, die zu ihm hinaufführt. Steigt diese Rampe hinauf und vollendet Eure Ausbildung.\n\nEs war wundervoll, Euch kennengelernt zu haben, <Name>. Ich bin sehr stolz, zu wissen, dass unter den jungen Nachtelfen auch solche sind, die so selbstlos und voller Leben sind wie Ihr. Ihr werdet große Taten für unser Volk vollbringen. Ihr werdet große Dinge in dieser Welt tun.\n\nMögen wir uns bald wiedersehen.", progress = "Die Mondbrunnen enthalten die Wasser des Brunnens der Ewigkeit, der uralten Quelle der Magie, die so viele Schrecken über unsere Welt gebracht hat.\n\nDie Druiden nutzen die Eigenschaften des Wassers, die Schildwachen verehren die Brunnen als Schreine der Elune und jetzt richten sogar die zurückgekehrten Hochgeborenen sehnsüchtige Blicke auf die Brunnen.", completion = "Ihr habt also den ersten Teil der Nachwirkungen von der Schlacht am Hyjal erfahren. Es gibt noch viel mehr für Euch zu erfahren und die Aufgabe, die Ihr hier begonnen habt, wird sich für den Rest Eurer Reise durch Teldrassil bis nach Darnassus fortsetzen.", rewards = "WaldlandtunikaWaldlandschildWaldlandrobenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28731] = {title = "Teldrassil: Gebt das Wissen weiter", objective = "Bringt das teilweise gefüllte Gefäß zu Corithras Mondzorn in Dolanaar.", description = "Es gibt noch mehr, was ich Euch über die Mondbrunnen erzählen könnte und über Teldrassil, aber ich muss Euch nun fortschicken. Corithras Mondzorn wird Euch erwarten. Ich habe die Phiole mit dem Wasser, das Ihr gebracht habt, in dieses Gefäß gefüllt.\n\nSucht nach Corithras. Ihr findet ihn am Mondbrunnen in Dolanaar. Folgt der Straße südlich von Aldrassil aus dem Laubschattental hinaus und geht weiter entlang der Pflastersteine, wenn sich die Straße nach Westen wendet.\n\nAchtet aber darauf, auf der Straße zu bleiben, <Name>. In den Wäldern lauern neuerdings gefährliche Ungeheuer.", progress = "Seid gegrüßt, <Klasse>. Welchem Anlass verdanke ich die Freude unserer Zusammenkunft?", completion = "Ah, ich verstehe. Tenaron hat Euch gesandt. Nun gut, es scheint, dass wir viel zu bereden und noch mehr zu tun haben.\n\nBevor wir uns um die zu erledigende Aufgabe kümmern, solltet Ihr die Lektion dieses Mondbrunnens erlernen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28732] = {title = "Das kann nur eins bedeuten...", objective = "Nehmt Pips Maulwurfmaschine zum Schwarzfels.", description = "Raz und ich wurden von den Wächtern des Hyjal beauftragt, das Wiederauftauchen von Ragnaros in unsere Welt zu untersuchen. Lasst mich weiterziehen und bestätigen, dass er zurück ist und dass er erzürnt ist! Wir haben außerdem Beweise, dass diese Schattenhammerkultisten Elementare von hier zu den Schwarzfelshöhlen in den Östlichen Königreich bringen.\n\nRaz und ich waren auf dem Weg dorthin, um die Sache zu untersuchen. Wir haben in der Maulwurfmaschine noch Platz für eine Person, falls Ihr interessiert seid? Trefft uns einfach draußen und unsere Reise kann beginnen.", progress = "HILFE! HILFE!", completion = "Oje, Raz wurde gefangengenommen! Sobald wir drin waren, haben uns ein dutzend Schattenhammerkultisten und ein dicker, fetter Oger angegriffen. Ich bin losgerannt, während Raz versucht hat, sie abzuwehren. Wir müssen ihn retten, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28733] = {title = "Pflanzenkunde für Anfänger", objective = "Überlebt eine riesige Zombiewelle.", description = "HILFE! HILFE! Durchgedrehte Untote greifen meinen Hof an! Dieser verrückte Aufseher drüben bei den Schlickfeldern ist vermutlich für diese Sauerei verantwortlich. Helft mir, die Zombies abzuwehren!", progress = nil, completion = "PUH! Das war knapp! Ihr seid ein echtes Naturtalent, wenn es um diese Pflanzen geht, &lt;Klasse&gt;. Wisst Ihr, ich habe die Samen hier von den Verlorenen Inseln mitgebracht. Ich bin mir sicher, sobald ich alles über sie herausgefunden habe, werde ich ein Vermögen mit dem Verkauf von tödlichen Blumen machen!\n\nWa... SEHT! ES KOMMEN NOCH MEHR!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28734] = {title = "Ein Gefallen für Melithar", objective = "Sprecht mit Melithar Hirschhaupt im Laubschattental.", description = "Ihr solltet mit Melithar sprechen. Ich glaube, er hatte bereits einige Probleme mit den Grells.\n\nIch schätze, er kann Euch Platz anbieten, an dem Ihr einiges von Eurem Hab und Gut verstauen könnt, falls Ihr ihm helft.", progress = nil, completion = "Ilthalaine hat Euch geschickt? Es war weise von ihm, das zu tun. Ich brauche in der Tat Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28735] = {title = "Zur Kammer der Einäscherung!", objective = "Tötet Rom'ogg Knochenbrecher.", description = "Es war ein Hinterhalt, <Name>! Kaum waren wir drin, griff uns ein dicker, fetter Oger namens Rom'ogg Knochenbrecher an! Raz hat mich mutig verteidigt, während ich davongerannt bin, um mich zu verstecken. Ich musste zusehen, wie sie ihn bewusstlos schlugen und ihn dann zu einem Ort brachten, den der Fette \"Kammer der Einäscherung\" nannte. Ich glaube, sie ist in der Halle auf der anderen Seite der Brücke.\n\nIch habe zu viel Angst, um auch nur einen Schritt weiter zu gehen. Nehmt meinen Allzwecktaucherhelm und sucht nach Raz. Durch den Helm kann ich mit Euch sprechen.\n\nUnd wenn Ihr diesen Oger findet, tötet ihn!", progress = nil, completion = "&lt;Finkles Helm knistert vor statischer Aufladung.&gt;\n\nRAZ! Was haben sie ihm angetan!? FOLGT IHM!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28736] = {title = "Feuer vom Himmel", objective = "Steigt in die beschlagnahmte Artillerie und verwendet sie, um 100 Infanteristen von Schnottz zu töten.", description = "Die Überreste von Schnottz' Organisation halten sich hier beharrlich auf dem Aufstieg des Schöpfers, was dieses Gebiet für jeden, der sich nähert, zur Todesfalle macht.\n\nEs gibt reichlich Munition, aber ohne einen guten Beobachter schieße ich einfach blindwütig umher.\n\nSpringt auf und geht mir zur Hand. Diesen Soldaten wird das Hören und Sehen vergehen!", progress = "Hier gibt es reichlich Ziele, <Klasse>.", completion = "Der Feind auf dem Aufstieg des Schöpfers bleibt eine Bedrohung, aber dank Eurer Hilfe haben wir ihrer Anzahl und ihrem Kampfgeist einen ernsthaften Schlag versetzt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28737] = {title = "Wo sind wir hier?", objective = "Tötet Corla, Botin des Zwielichts.", description = "<Pips Helm versetzt Euch einen leichten Stromschlag.>\n\nWas ist das für ein Ort? Es sieht aus, als würden sie dem Netherdrachen schreckliche Dinge antun. Seine Energie wird in die Frau dort geleitet! Wir müssen das Ritual aufhalten!\n\nTötet Corla, um diese Halle hinter Euch zu lassen!", progress = "<Pips Helm gibt ein statisches Knistern von sich.>", completion = "&lt;Pips Helm gibt ein statisches Knistern von sich.&gt;\n\nUns bleibt nicht viel Zeit. Sieht aus, als wäre Raz verletzt. Wenn wir ihn rechtzeitig erreichen, haben wir vielleicht sogar eine Chance, ihn in einen gewöhnlichen Orc zurückzuverwandeln!\n\n&lt;Ihr fühlt einen stechenden Schmerz im Hinterkopf und hört das Klingeln von Münzen&gt;\n\nEntschuldigt das. Ich dachte, ich würde Euch etwas Gold durchschicken... für Eure Mühen und so...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Player Phase/Auras\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28738] = {title = "Die Zwielichtschmiede", objective = "Tötet Karsh Stahlbieger.", description = "<Pips Helm summt vor Energie.>\n\nVerdammt nochmal! Raz hört einfach nicht auf! Es ist, als hätte ihn eine brennende Rachsucht gegen alles mit Zwielicht im Namen ergriffen! Sieht so aus, als müssten wir den Zwielichtrüstungsschmied Karsh Stahlbieger ausschalten, wenn wir den Raum hinter uns lassen und zu Raz aufschließen wollen.", progress = "<Pips Helm gibt ein statisches Knistern von sich.>", completion = "&lt;Pips Helm gibt ein statisches Knistern von sich.&gt;\n\nDas sollte ihrem Arsenal ein Ende bereitet haben... zumindest vorerst.\n\nRaz ist über die Rampe auf der anderen Seite der Schmiede weggerannt. LOS, LOS, LOS!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Player Phase/Auras\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28740] = {title = "Kann ich meinen Augen trauen?", objective = "Tötet Bella", description = "<Ein lautes, mädchenhaftes Kreischen entweicht Pips Helm.>\n\nDAS KANN NICHT SEIN! Ich... Ich habe fast einen ganzen Monat in einem dieser Dinger festgesteckt. Ja, buchstäblich im Magen. Ohne meinen Anzug und meinen Allzwecktaucherhelm hätte mich ein feuriger Tod ereilt! Und schaut Euch das an, es hat Nachwuchs bekommen!\n\nI... Ihr müsst dieses Ding aufhalten, <Name>! Wir dürfen nicht zulassen, dass es oder sein Nachwuchs hier lebendig hier rauskommen!", progress = "<Finkles Helm knistert vor statischer Aufladung.>", completion = "&lt;Pips Helm gibt ein statisches Knistern von sich.&gt;\n\nPuh... Eine Sache weniger, um die ich mir Sorgen machen muss, sollten wir es hier jemals rausschaffen.", rewards = "Bellissimas HalsbandBellas Bazillenübersätes DeckchenAuf Euch wartet eine dieser Belohnungen:\n\nAuto-Dekodierband\n\nDer folgende Zauber wird auf euch gewirkt:\n\nUpdate Player Phase/Auras\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28741] = {title = "Aszendentenfürst Obsidius", objective = "Tötet Aszendentenfürst Obsidius.", description = "<Pips Helm brummt.>\n\nMEINE GÜTE! Schaut Euch diesen Ort an! S... Sind das etwa Kratzspuren von Todesschwinge an der Decke?! Und was ist das für eine Kreatur da in der Mitte der Kammer?\n\nIch kann Raz nicht sehen. Kümmern wir uns um dieses Monster und finden Raz!", progress = nil, completion = "Armer Raz. Er war der beste Freund, den ein Gnom jemals hatte. Zumindest haben wir seinen Tod gerächt und diese höllischen Höhlen gesäubert!", rewards = "Raz' BrustplatteDiamantbesetzter HelmSäurezerfressene WesteDer folgende Zauber wird auf euch gewirkt:\n\nUpdate Player Phase/Auras\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28742] = {title = "Shy-Rotam", objective = "Tötet Shy-Rotam.", description = "Zeit für den großen Abschuss, Kumpel! Shy-Rotam schleicht im Norden umher - der größte Frostsäbler, den es gibt.\n\nIhr solltet Euch geehrt fühlen. Es gibt keine größere Herausforderung für einen Jäger... und wenn Ihr die Belohnung gesehen hättet, die mir von diversen Leckermäulern angeboten wurde, die ein Stück von diesem Kerl haben wollen, würden Euch die Augen ausfallen!\n\nSobald Ihr ihn erledigt habt, kommt zurück zum Lager. Ihr wollt unsere Frostsäblerpopulation schließlich nicht an einem Tag ausrotten...", progress = nil, completion = "Erstaunlich. Ihr seid einen Tick besser als die anderen! Ich bin habe ungefähr fünf verschiedene Vertragsjäger angeheuert, um diese Katze zu töten.\n\nNun, zwei von ihnen haben wir gefunden, nachdem der Hauptmann den Kadaver bekommen hatte, aber vertiefen wir das nicht weiter...", rewards = "ShybrustplatteShytuchFrostsäblerhelmBrustplatte des fünften JägersSchild des LeichenschleppersIhr bekommt:\n\nSteak von Shy-Rotam"}
MultiLanguageQuestData['de'][28743] = {title = "Heckschütze!", objective = "Schießt 15 Fliegerasse von Schnottz ab.Ist Euch nach ein wenig Jagen zumute, <Name>?\n\nSteigt ein! Ich fliege, Ihr schießt!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ist Euch nach ein wenig Jagen zumute, <Name>?\n\nSteigt ein! Ich fliege, Ihr schießt!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28744] = {title = "Ghule hassen meine Saat", objective = "Überlebt 2 riesige Zombiewellen.", description = "Ihr seid ein Fachmann in dieser Sache, <Name>! Ein regelrechter Aushilfsbotaniker! Hört, ich habe ein neues Saatgut auszutesten, das Felsnuss genannt wird. Verwendet es, um die Untoten zu blockieren. Werft es einfach auf den Boden und sie bleiben wie angewurzelt stehen. Untote sind so dämlich!\n\nVersuchen wir es!", progress = nil, completion = "Ich glaube, ich habe Stillwasser erzürnt. Jetzt fährt er die großen Geschütze auf. Keine Zeit zu verlieren, los geht's!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28745] = {title = "Schmackhafte Kreischer", objective = "Tötet 15 Winterquellkreischer.", description = "Diese kleineren Eulen sind schon sehr lecker, aber Gutmampf sagt, es gibt weiter im Süden sogar noch größere! \"Kreischer\" werden sie von den Leuten aus der Gegend genannt. Sie machen ganz schön viel Lärm, wenn man sich mit ihnen prügelt. \n\nAber er sagt, es sind die besten Eulen, die er je gekostet oder verkauft hat und ich glaube ihm. Warum scheucht Ihr nicht ein paar von ihnen für uns auf und ich streite mich hier weiter mit Francis.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28746] = {title = "Ihre Verteidigung durchbrechen", objective = "Verschafft Euch Zutritt zum Kontrollraum der Titanen.", description = "Los geht's, <Name>!\n\nDirekt hinter dieser Tür liegt der Kontrollraum.\n\nIch renne einfach hinein, deaktiviere den Neuerschaffungsmechanismus und dann gehen wir alle wieder nach Hause. So einfach ist das.\n\nIhr werdet sehen, <Bursche/Mädel>, es ist diese hohe Kunst der Vorbereitung, die den wahren Archäologen von dem durchschnittlichen Jäger eines verlorenen Schatzes unterscheidet.\n\nEs ergibt keinen Sinn, die Bestien aufzumischen, wenn man's nicht muss. Man veranstaltet nur unnötig ein großes Durcheinander...", progress = "Was gibt's, <Name>?", completion = "Nun, ich habe eine schlechte Nachricht für Euch und eine...\n\nNein, streicht das. Ich habe nur schlechte Nachrichten.", rewards = "OfflineschienbeinschützerWarenlagerstulpenStiefel des schweren WegesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28747] = {title = "Kürbisbomben", objective = "Überlebt 2 riesige Zombiewellen.", description = "Habt Ihr so was schon mal gesehen?\n\n<Brazie zieht einen Kürbis heraus.>\n\nDies sind keine gewöhnlichen Kürbisse. Seht, sobald man sie einpflanzt, warten sie bis ein Zombie auftaucht und dann, KABUMM, fliegen die Zombies in Einzelteilen durch die Luft. Los geht's!", progress = nil, completion = "H... Habt Ihr das Rumpeln gehört? Ich glaube, Stillwasser kommt! Heiliger Strohsack, passt auf!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28748] = {title = "Rasen der lebenden Toten", objective = "Besiegt Aufseher Stillwasser.", description = "ES IST STILLWASSER! ER IST FAST HIER! Wir werden alles ins Rennen werfen müssen, was wir haben, um ihn zu schlagen. Auf geht's!", progress = nil, completion = "Ich kann nicht glauben, dass wir ihn besiegt haben, &lt;Name&gt;! Das war der härteste Kampf, den wir bisher hatten, aber es gibt noch immer Hunderte von durchgeknallten Zombies, die im Hügelland ihr Unwesen treiben. Wir müssen auf der Hut bleiben.", rewards = "BotanikerkniehosenBrazies PflanzenlampeIhr bekommt:\n\nBrazies Sonnenblumensamen"}
MultiLanguageQuestData['de'][28749] = {title = "Die Schlacht um Andorhal", objective = "Sprecht mit Kriegsmagier Erallier, um nach Andorhal in den Westlichen Pestländern teleportiert zu werden. Dann meldet Euch bei Thassarian in Andorhal.", description = "Gerade ist ein Greif mit Neuigkeiten aus den Pestländern eingetroffen. Es klingt nicht gut.\n\nDie Stadt Andorhal befindet sich inmitten eines Krieges zwischen drei Fronten: die Verlassenen, die Allianz und die Geißel. König Wrynn hat eine Entscheidung getroffen und einen Todesritter geschickt, der seine Sache anführen soll, aber ich bin mir sicher, dass er jede Hilfe braucht, die er bekommen kann. \n\nDie Nachricht sagt ausdrücklich: \"<Klasse> von der Allianz für besondere Einsätze gesucht\". Wenn Ihr die Herausforderung annehmt, sprecht wieder mit mir und ich werde ein Portal beschwören.", progress = nil, completion = "Es wurde Zeit, dass Ihr kommt, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28750] = {title = "Die Schlacht um Andorhal", objective = "Sprecht mit Arkanist Arman, um nach Andorhal in den Westlichen Pestländern teleportiert zu werden. Dann meldet Euch bei Koltira Todesweber in Andorhal.", description = "Gerade ist ein Windreiter mit Neuigkeiten aus den Pestländern eingetroffen. Es klingt nicht gut.\n\nDie Stadt Andorhal ist in der Mitte eines Krieges zwischen drei Fronten: die Verlassenen, die Allianz und die Geißel. Es klingt so, als ob Sylvana eine Entscheidung getroffen hat und um es noch interessanter zu machen, hat sie dem Todesritter Koltira Todesweber das Kommando übertragen.\n\nDie Nachricht sagt ausdrücklich: \"<Klasse> von der Horde für besondere Einsätze gesucht\". Wenn Ihr die Herausforderung annehmt, sprecht wieder mit mir und ich werde ein Portal beschwören.", progress = nil, completion = "Es wurde Zeit, dass Ihr kommt, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28751] = {title = "Unkraut jäten", objective = "Überlebt 2 riesige Zombiewellen.", description = "Obwohl wir Aufseher Stillwasser geschlagen haben, streifen seine Zombies noch immer durch die Gegend. Seht dort, eine neue Welle nähert sich uns! Helft mir, sie zurückzuschlagen, Kumpel! Los geht's!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28752] = {title = "Unaufhaltsamer Ansturm", objective = nil, description = "Seht, wie lange Ihr durchhaltet! Übersteht mindestens 10 Anstürme und ich gebe Euch ein paar Münzen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28753] = {title = "Auf die harte Tour", objective = "Brann Bronzebart will, dass Ihr Isiset, Ammunae, Setesh und Rajh tötet.", description = "So ein verdammter Mist!\n\nJemand hat das gesamte System zum Absturz gebracht! Ich kann von dieser Konsole überhaupt nicht mehr auf den Hauptspeicher zugreifen.\n\nWir werden es auf die harte Tour machen müssen, <Kumpel/Mädel>. Ich hoffe, Ihr und Eure Freunde hier haben Lust auf einen Kampf.\n\nEs gibt vier Wächter auf den oberen Ebenen dieser Anlage. Ich werde nicht in der Lage sein, diese Scheiben zu verwenden, bis sie... ähm, sagen wir mal abgeschaltet sind.", progress = nil, completion = "Aaalso gut.\n\nDeponieren wir diese Scheiben und das war's dann!", rewards = "Handschuhe des SchatzjägersArmschienen des wahren ArchäologenHelm der NeuerschaffungDer folgende Zauber wird auf euch gewirkt:\n\nPing Brann\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28755] = {title = "Annalen der Silbernen Hand", objective = "Treibt einen verschollenen Band der Annalen der Silbernen Hand in Stratholme auf.", description = "Wisst Ihr, wer die Ritter der Silbernen Hand waren? Es waren die ursprünglichen Paladine des Lichts und aus ihren Reihen stammten die Ritter, die später der Argentumdämmerung oder den Scharlachroten Kreuzfahrern beitraten. Obwohl viele vom Weg abgekommen sind, besitzen sie noch immer wertvolle Relikte der Silbernen Hand.\n\nTief in Stratholme unter den wachsamen Augen von Archivar Galford haben Bände der Annalen der Silbernen Hand die Zeiten überdauert. Jeder Band, den Ihr auftreiben könnt, wäre eine passende Ergänzung für die umgewidmete Kapelle des Hoffnungsvollen Lichts.", progress = "Konntet Ihr die verschollenen Aufzeichnungen der Silbernen Hand ausfindig machen?", completion = "Dies ist tatsächlich einer der verschollenen Bände! Tyrosus wird hocherfreut sein, wenn er von Eurem Fund erfährt.", rewards = nil}
MultiLanguageQuestData['de'][28756] = {title = "Entartung des Knochens", objective = "Tötet Blutrippe im Ossuarium von Scholomance.", description = "Im Leben kämpften meine Brüder und ich gegen all die Kräfte der Geißel, aber niemand war so schändlich wie die Totenbeschwörer. Es hat ihnen nicht gereicht, unsere toten Kameraden auferstehen zu lassen und sie gegen uns kämpfen zu lassen, nein, sie erschufen perverse Golems aus Knochen mit Sicheln statt Händen.\n\nDiese Entartungen töteten viele meiner Brüder und dennoch konnten sie nicht alle vernichten. Ich bitte Euch, <Name>, die Aufgabe der Gefallenen fortzuführen. Reist in das Ossuarium von Scholomance und vernichtet die größte und gefährlichste dieser scheußlichen Kreaturen.", progress = nil, completion = "Eure Taten ehren diejenigen, die bei der Verteidigung dieses heiligen Bodens gefallen sind.", rewards = nil}
MultiLanguageQuestData['de'][28757] = {title = "Schlagt sie zurück!", objective = "Tötet 6 Kampfworgs des Schwarzfels.", description = "Ihr seid also der neue Rekrut aus Sturmwind, wie? Ich bin Marschall McBride, Kommandant dieser Garnison. Ich bin froh, Euch an Bord zu haben...\n\n<McBride sieht ein paar Zettel durch.>\n\n<Name>. Ihr seid <Name>, ja?\n\nIhr seid genau zur rechten Zeit gekommen. Die Schwarzfelsorcs haben es geschafft, sich durch einen Felsspalt in den Nordhain einzuschleichen. Meine Soldaten tun ihr Bestes, sie zurückzuschlagen, aber ich fürchte, sie werden bald übermannt werden.\n\nBegebt Euch nach Nordwesten in den Wald und tötet die angreifenden Worgs des Schwarzfels! Helft meinen Soldaten!", progress = nil, completion = "Ihr habt uns ein wenig Zeit verschafft, &lt;Name&gt;, aber wir haben jetzt ein noch größeres Problem, um das wir uns kümmern müssen.", rewards = "Ihr bekommt:\n\nGurt des Abtes von Nordhain"}
MultiLanguageQuestData['de'][28758] = {title = "Der Kampf um Leben und Tod", objective = "Steigt auf einen Zinnoberroten Vorposten. Tötet 8 Zwielichtschattendrachen.", description = "Todesschwinge und Alexstrasza haben sich in den Himmel über Grim Batol erhoben! Ihr Plan droht zu scheitern - die Königin der Drachen ist außerhalb des Kreises des Lebens, den sie zuvor eingerichtet hat. Wir werden sie mit allem unterstützen müssen, was wir haben.\n\nBeeilung! Steigt auf einen der Zinnoberroten Vorposten hinter mir.\n\nWenn wir auf irgendwelche Zwielichtdrachen treffen, die Todesschwinge helfen, werden wir sie töten müssen. Sitzt auf, schnell!", progress = nil, completion = "Dank Eures schnellen Handelns lebt die Königin der Drachen noch. Sie wird zurück zum Wyrmruhtempel gebracht, um sich zu erholen.\n\nAber die Schlacht war kein vollständiger Fehlschlag. Todesschwinge ist schwer verwundet. Ich vermute, er wird sich verstecken, um zu Kräften zu kommen. Alexstrasza hat uns Zeit verschafft, um zuzuschlagen!", rewards = "Umhang des roten SchwarmsAuf Euch wartet eine dieser Belohnungen:\n\nRoter DrachenherzringAnhänger des siegreichen Zorns\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28759] = {title = "Worgs im Schafspelz", objective = "Tötet 8 Spione des Schwarzfels.", description = "Die einfallenden Orcs sind keine Narren. Sie schätzen uns ab, stellen sicher, dass ihre Angriffe zu ihrem Vorteil sein werden.\n\nIm Wald nordwestlich sind Spione der Schwarzfelsorcs. Sie spähen uns durch Handfernrohre aus, überwachen jeden unserer Schritte - und warten. Ich will, dass Ihr sie angreift!\n\nTötet die Spione der Schwarzfelsorcs! Wir müssen ihnen zeigen, dass wir wissen, dass sie uns beobachten und dass wir vorbereitet sind!", progress = nil, completion = "Hervorragende Arbeit, &lt;Name&gt;. Es hat sich herausgestellt, dass Ihr ein echter Gewinn für die Garnison seid. Es wird Zeit für Eure Ausbildung!", rewards = "Ihr bekommt:\n\nBeine des Meisterspions"}
MultiLanguageQuestData['de'][28760] = {title = "Rache für Orsis", objective = "Tötet Asaad.", description = "Die große Stadt Orsis wurde von den Armeen der Lüfte angegriffen.\n\nWir wurden gefangen genommen. Und dabei waren wir noch diejenigen, die Glück hatten.\n\nDie meisten starben, begraben unter dem schweren Wüstensand.\n\nAl'Akirs Kalif Asaad hat den Angriff befohlen... und dafür soll er mit dem Leben bezahlen.", progress = nil, completion = "Seid gesegnet. Bitte nehmt dies als Zeichen meiner Dankbarkeit.", rewards = "Schienbeinschützer von OrsisAuf Euch wartet eine dieser Belohnungen:\n\nZeichen der DankbarkeitKalifenband\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28762] = {title = "Schlagt sie zurück!", objective = "Tötet 6 Kampfworgs des Schwarzfels.", description = "Ihr seid also der neue Rekrut aus Sturmwind, wie? Ich bin Marschall McBride, Kommandant dieser Garnison. Ich bin froh, Euch an Bord zu haben...\n\n<McBride sieht ein paar Zettel durch.>\n\n<Name>. Ihr seid <Name>, ja?\n\nIhr seid genau zur rechten Zeit gekommen. Die Schwarzfelsorcs haben es geschafft, sich durch einen Felsspalt in den Nordhain einzuschleichen. Meine Soldaten tun ihr Bestes, sie zurückzuschlagen, aber ich fürchte, sie werden bald übermannt werden.\n\nBegebt Euch nach Nordwesten in den Wald und tötet die angreifenden Worgs des Schwarzfels! Helft meinen Soldaten!", progress = nil, completion = "Ihr habt uns ein wenig Zeit verschafft, &lt;Name&gt;, aber wir haben jetzt ein noch größeres Problem, um das wir uns kümmern müssen.", rewards = "Ihr bekommt:\n\nWorgwärterhandschuhe"}
MultiLanguageQuestData['de'][28763] = {title = "Schlagt sie zurück!", objective = "Tötet 6 Kampfworgs des Schwarzfels.", description = "Ihr seid also der neue Rekrut aus Sturmwind, wie? Ich bin Marschall McBride, Kommandant dieser Garnison. Ich bin froh, Euch an Bord zu haben...\n\n<McBride sieht ein paar Zettel durch.>\n\n<Name>. Ihr seid <Name>, ja?\n\nIhr seid genau zur rechten Zeit gekommen. Die Schwarzfelsorcs haben es geschafft, sich durch einen Spalt im Felsen in den Nordhain einzuschleichen. Meine Soldaten tun ihr Bestes, sie zurückzuschlagen, aber ich fürchte, sie werden bald übermannt werden.\n\nBegebt Euch nach Nordwesten in den Wald und tötet die angreifenden Schwarzfelsworgs! Helft meinen Soldaten!", progress = "Habt Ihr die Kampfworgs des Schwarzfels zurückgeschlagen?", completion = "Ihr habt uns ein wenig Zeit verschafft, &lt;Name&gt;, aber wir haben jetzt ein noch größeres Problem, um das wir uns kümmern müssen.", rewards = "Ihr bekommt:\n\nGurt des Abtes von Nordhain"}
