MultiLanguageQuestData['de'][28767] = {title = "Schlagt sie zurück!", objective = "Tötet 6 Kampfworgs des Schwarzfels.", description = "Ihr seid also der neue Rekrut aus Sturmwind, wie? Ich bin Marschall McBride, Kommandant dieser Garnison. Ich bin froh, Euch an Bord zu haben...\n\n<McBride sieht ein paar Zettel durch.>\n\n<Name>. Ihr seid <Name>, ja?\n\nIhr seid genau zur rechten Zeit gekommen. Die Schwarzfelsorcs haben es geschafft, sich durch einen Spalt im Felsen in den Nordhain einzuschleichen. Meine Soldaten tun ihr Bestes, sie zurückzuschlagen, aber ich fürchte, sie werden bald übermannt werden.\n\nBegebt Euch nach Nordwesten in den Wald und tötet die angreifenden Schwarzfelsworgs! Helft meinen Soldaten!", progress = nil, completion = "Ihr habt uns ein wenig Zeit verschafft, &lt;Name&gt;, aber wir haben jetzt ein noch größeres Problem, um das wir uns kümmern müssen.", rewards = "Ihr bekommt:\n\nLäuferstiefel"}
MultiLanguageQuestData['de'][28768] = {title = "Winterquell!", objective = "Meldet Euch bei Donova Schneeweh an den Frostfeuerquellen in Winterquell.", description = "Die Zwergenfrau Donova Schneeweh ist mit dem Furbolgs der Holzschlundfeste befreundet.\n\nWir handeln mit Feuerwasser.\n\nSie ist bei den Frostfeuerquellen im Westen, wenn Ihr durch unsere Höhle geht.\n\nSie braucht Unterstützung beim Verprügeln der Furbolgs der Winterfelle. Vielleicht könnt Ihr ihr helfen.", progress = nil, completion = "Dem Licht sei Dank, dass Ihr hier seid. Ich habe das Geheimnis der grimmigen Furbolgs der Winterfelle aufgedeckt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28769] = {title = "Worgs im Schafspelz", objective = "Tötet 8 Spione der Schwarzfelsorcs.", description = "Die einfallenden Orcs sind keine Narren. Sie schätzen uns ab, stellen sicher, dass ihre Angriffe zu ihrem Vorteil sein werden.\n\nIm Wald nordwestlich von hier lauern Spione der Schwarzfelsorcs. Sie kundschaften uns mit ihren Handfernrohren aus, überwachen jeden unserer Schritte - und warten. Ich will, dass Ihr sie angreift!\n\nTötet die Spione der Schwarzfelsorcs! Wir müssen ihnen zeigen, dass wir sehr wohl wissen, dass sie uns beobachten und dass wir vorbereitet sind!", progress = nil, completion = "Hervorragende Arbeit, &lt;Name&gt;. Es hat sich herausgestellt, dass Ihr ein echter Gewinn für die Garnison seid. Es wird Zeit für Eure Ausbildung!", rewards = "Ihr bekommt:\n\nRobe des Abtes von Nordhain"}
