MultiLanguageQuestData['de'][28775] = {title = "Zerbrochene Schlangenfigur", objective = "Repariert die zerbrochene Figur mithilfe Eurer Fertigkeit und den richtigen Materialien.", description = "Diese zerbrochene Figur wurde von ihrem ehemaligen Besitzer fortgeworfen. Mit den richtigen Materialien und Euren Fertigkeiten in der Juwelierskunst könntet Ihr sie jedoch vollständig reparieren.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFigur - Juwelenbesetzte Schlange"}
MultiLanguageQuestData['de'][28776] = {title = "Zerbrochene Figur eines Irdenen", objective = "Repariert die zerbrochene Figur mithilfe Eurer Fertigkeit und den richtigen Materialien.", description = "Diese zerbrochene Figur wurde von ihrem ehemaligen Besitzer fortgeworfen. Mit den richtigen Materialien und Euren Fertigkeiten in der Juwelierskunst könntet Ihr sie jedoch vollständig reparieren.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFigur - Irdener Wächter"}
MultiLanguageQuestData['de'][28777] = {title = "Beschädigte Figur einer Eule", objective = "Repariert die zerbrochene Figur mithilfe Eurer Fertigkeit und den richtigen Materialien.", description = "Diese zerbrochene Figur wurde von ihrem ehemaligen Besitzer fortgeworfen. Mit den richtigen Materialien und Euren Fertigkeiten in der Juwelierskunst könntet Ihr sie jedoch vollständig reparieren.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFigur - Traumeule"}
MultiLanguageQuestData['de'][28778] = {title = "Zerbrochene Figur eines Keilers", objective = "Repariert die zerbrochene Figur mithilfe Eurer Fertigkeit und den richtigen Materialien.", description = "Diese zerbrochene Figur wurde von ihrem ehemaligen Besitzer fortgeworfen. Mit den richtigen Materialien und Euren Fertigkeiten in der Juwelierskunst könntet Ihr sie jedoch vollständig reparieren.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFigur - König der Eber"}
MultiLanguageQuestData['de'][28779] = {title = "Weit von zuhause entfernt", objective = "Beschafft das Herz von Großwesir Ertan.", description = "Ich habe das Gefühl, dass man mich hat fliehen lassen, weil ich hier ohnehin nicht fort kann.\n\nIch sitze auf diesen Plattformen fest und deshalb finden sie mich früher oder später sowieso. Es sei denn...\n\nMan sagt, das Herz eines Elementarfürsten übertrüge demjenigen, der es in Händen hält, die Eigenschaften des jeweiligen Elements. Im Falle von Luft wäre das für eine Reise hinab äußerst nützlich.\n\nBringt mir das Herz von Großwesir Ertan, sodass ich mithilfe seiner Magie sicher an der Küste von Uldum landen kann.", progress = "Ihr solltet mir besser nicht anbieten, mit Euch zu reiten... was auch immer das für ein Ding ist, auf dem Ihr hierhergeflogen seid.", completion = "Ich danke Euch, &lt;Name&gt;. Selbst nach meiner Flucht habe ich nicht ernsthaft zu hoffen gewagt, einst nach Hause zurückzukehren.", rewards = "Umhang von IteshGamaschen des VortexgipfelsAuf Euch wartet eine dieser Belohnungen:\n\nBand der Sackgasse\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28780] = {title = "Stürzt Euch in die Schlacht!", objective = "Meldet Euch bei Stellvertreter Willem hinter der Abtei von Nordhain im Wald von Elwynn.", description = "Während Ihr unterwegs wart, um zu trainieren, habe ich eine dringliche Nachricht von Stellvertreter Willem erhalten. Wie sich herausstellt, haben die Schwarzfelsorcs goblinische Auftragsmörder angeheuert. Sie haben unser Bataillon hinter der Abtei aus dem Hinterhalt angegriffen. Willem bat mich, ihm einen Helden zu schicken. Ihr müsst ihnen helfen, <Name>!\n\nFindet Stellvertreter Willem nördlich der Abtei am Kommandozelt. Geht!", progress = nil, completion = "Es stimmt, man hat uns aus dem Hinterhalt angegriffen. Ich wage es nicht, noch weitere Soldaten dort hinauszuschicken und zu riskieren, sie auch noch zu verlieren. Ich brauche einen Freiwilligen. Jemanden, der bereit ist, sein Leben zu riskieren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28781] = {title = "Gelegenheitsziele", objective = "Tötet General Husam und 2 eingeschworene Hauptmänner.", description = "Wir waren Teil einer verdeckten Operation, die Prinz Nadun von Ramkahen eingefädelt hat. Wir haben die meisten unserer Einheiten in einem Hinterhalt verloren und wir sind jetzt nicht mehr in der Lage, unsere Mission abzuschließen.\n\nFalls es für Euch eine Rolle spielt, kann ich Euch zu einer ansehnlichen Belohnung verhelfen.\n\nUns wurde aufgetragen, jedes sich bietende Ziel auszuschalten, das für die militärische Infrastruktur der Feinde von Bedeutung ist.\n\nWir haben General Husam ausfindig gemacht und zwei seiner Hauptmänner. Wenn Ihr sie für uns tötet, würdet Ihr Ramkahen einen großen Dienst erweisen.", progress = "Ist es vollbracht, <Name>?", completion = "Hervorragende Arbeit, &lt;Name&gt;. Ihr werdet Eurem Ruf gerecht.", rewards = "Geheime SchulternArmschienen der Verlorenen StadtHauptmann Hadans SchulterstückeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28782] = {title = "Ein legendärer Vogel", objective = "Tötet Höllenschuhu.", description = "Die einheimischen Legenden berichten von einer riesenhaften Eule, die über den Berggipfeln kreist wie der geflügelte Tod. Man nannte sie Todesschwinge.\n\nKurz darauf erfuhr man, dass der Name bereits vergeben war. Also entschied man sich für einen Ersatznamen, der ebenfalls Furcht und Schrecken verbreiten sollte:\n\nHöllenschuhu.\n\nHöllenschuhu ist auf dem Berggipfel südwestlich unserer Räuchergrube anzutreffen. Bringt dieses teuflische Nachttier zum Schweigen... damit wir es essen können!", progress = nil, completion = "Höllenschuhu ist besiegt und Ihr Fleisch ist tatsächlich so wohlschmeckend, wie wir es uns gedacht haben.\n\nHeute verspeisen wir eine Legende. Habt Dank, &lt;Name&gt;.", rewards = "Handschuhe des teuflischen NachtaktivenHöllenschuhumantelWeste der RäuchergrubeLegendenfresserstiefelSchuhujägergamaschenIhr bekommt:\n\nHöllenschuhubarbecue"}
MultiLanguageQuestData['de'][28783] = {title = "Die Quelle ihrer Macht", objective = "Tötet Siamat.", description = "Bevor unsere Truppe in den Hinterhalt geriet, haben wir es noch geschafft, den Gegner auszuspionieren. \n\nWir haben herausgefunden, dass Siamat, der Gesandte von Todesschwinge, den Neferset ihre neue Kraft verleiht.\n\nSie haben behauptet, er hätte ihnen wieder zu alter Größe verholfen, aber es ist noch etwas anderes geschehen. Ihre Seelen wurden verdorben.\n\nAls einer der vier Winde ist Siamat unglaublich mächtig. Aber dieser Prozess hat ihn einiges seiner Kraft gekostet.\n\nSchlagt jetzt zu, während es noch möglich ist, ihn zu vernichten und bereitet diesem Wahnsinn ein Ende.", progress = nil, completion = "Es stimmt also? Die große Seuche, die unser Volk befallen hat, hat bald ein Ende, jetzt, wo die Neferset ihre Fähigkeit verloren haben, unser Volk noch weiter zu korrumpieren.\n\nNennt Euren Preis, &lt;Klasse&gt;. Das ist das Mindeste, was wir für Euch tun können.", rewards = "Treter der NefersetFrontstiefel von RamkahenMantel des SeuchenheilersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][28784] = {title = "Stürzt Euch in die Schlacht!", objective = "Meldet Euch bei Stellvertreter Willem hinter der Abtei von Nordhain im Wald von Elwynn.", description = "Während Ihr unterwegs wart, um zu trainieren, habe ich eine dringliche Nachricht von Stellvertreter Willem erhalten. Wie sich herausstellt, haben die Schwarzfelsorcs goblinische Auftragsmörder angeheuert. Sie haben unser Bataillon hinter der Abtei aus dem Hinterhalt angegriffen. Willem bat mich, ihm einen Helden zu schicken. Ihr müsst ihnen helfen, <Name>!\n\nFindet Stellvertreter Willem nördlich der Abtei am Kommandozelt. Geht!", progress = nil, completion = "Es stimmt, man hat uns aus dem Hinterhalt angegriffen. Ich wage es nicht, noch weitere Soldaten dort hinauszuschicken und zu riskieren, sie auch noch zu verlieren. Ich brauche einen Freiwilligen. Jemanden, der bereit ist, sein Leben zu riskieren!", rewards = "Ihr bekommt:\n\n"}
