MultiLanguageQuestData['de'][28789] = {title = "Stürzt Euch in die Schlacht!", objective = "Meldet Euch bei Stellvertreter Willem hinter der Abtei von Nordhain im Wald von Elwynn.", description = "Während Ihr unterwegs wart, um zu trainieren, habe ich eine dringliche Nachricht von Stellvertreter Willem erhalten. Wie sich herausstellt, haben die Schwarzfelsorcs goblinische Auftragsmörder angeheuert. Sie haben unser Bataillon hinter der Abtei aus dem Hinterhalt angegriffen. Willem bat mich, ihm einen Helden zu schicken. Ihr müsst ihnen helfen, <Name>!\n\nFindet Stellvertreter Willem nördlich der Abtei am Kommandozelt. Geht!", progress = nil, completion = "Es stimmt, man hat uns aus dem Hinterhalt angegriffen. Ich wage es nicht, noch weitere Soldaten dort hinauszuschicken und zu riskieren, sie auch noch zu verlieren. Ich brauche einen Freiwilligen. Jemanden, der bereit ist, sein Leben zu riskieren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28790] = {title = "Eine persönliche Einladung", objective = "Scharfseher Krogar will, dass Ihr Euch mit ihm in Orgrimmar trefft.", description = "<Ein ungewohntes Gefühl steigt in Euch auf und überflutet Euren Geist mit Gedanken und Bildern.>\n\nHöret meine Worte, <Name>.\n\nEine fürchterliche Krise hält unsere Welt fest in ihrem Griff. \n\nIch rufe Euch an, uns in dieser verzweifelten Stunde Hilfe zu leisten.\n\nIch bin Krogar.\n\nSucht mich umgehend auf und Euer Schicksal wird sich enthüllen.\n\nIhr findet mich nördlich der Gasse in Orgrimmar.", progress = nil, completion = "Möge Euer Sinn für Ehre und Pflicht Azeroth gute Dienste leisten, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28791] = {title = "Sie haben Auftragsmörder losgeschickt", objective = "Tötet 8 goblinische Auftragsmörder.", description = "Habt Ihr jemals einen Goblin gesehen, <Name>? Diese jämmerlichen, kleinen, grünhäutigen Monster mögen nur zwei Dinge: Gold und sich selbst.\n\nDie Schwarzfelsorcs haben sich goblinische Auftragsmörder zu Hilfe geholt, die unsere Soldaten töten sollen. Wenn Ihr zum Feld im Norden blickt, könnt Ihr schwach ihre Umrisse erkennen, wie sie im Gras umherschleichen.\n\nIhr müsst Euch dort hinbegeben und jeden Goblin töten, den Ihr zu Gesicht bekommt. Sie müssen kapieren, dass man sich nicht mit der Allianz anlegt!", progress = nil, completion = "Ihr habt diesen Monstern eine Lektion erteilt! Sie werden es sich zweimal überlegen, bevor sie noch einen Mordauftrag der Orcs annehmen.", rewards = "Ihr bekommt:\n\nAusstattergürtel"}
MultiLanguageQuestData['de'][28792] = {title = "Sie haben Auftragsmörder losgeschickt", objective = "Tötet 8 goblinische Auftragsmörder.", description = "Habt Ihr jemals einen Goblin gesehen, <Name>? Diese jämmerlichen, kleinen, grünhäutigen Monster mögen nur zwei Dinge: Gold und sich selbst.\n\nDie Schwarzfelsorcs haben sich goblinische Auftragsmörder zu Hilfe geholt, die unsere Soldaten töten sollen. Wenn Ihr zum Feld im Norden blickt, könnt Ihr schwach ihre Umrisse erkennen, wie sie im Gras umherschleichen.\n\nIhr müsst Euch dort hinbegeben und jeden Goblin töten, den Ihr zu Gesicht bekommt. Sie müssen kapieren, dass man sich nicht mit der Allianz anlegt!", progress = nil, completion = "Ihr habt diesen Monstern eine Lektion erteilt! Sie werden es sich zweimal überlegen, bevor sie noch einen Mordauftrag der Orcs annehmen.", rewards = "Ihr bekommt:\n\nAusstatterhandschuhe"}
