MultiLanguageQuestData['de'][28797] = {title = "Sie haben Auftragsmörder losgeschickt", objective = "Tötet 8 goblinische Auftragsmörder.", description = "Habt Ihr jemals einen Goblin gesehen, <Name>? Diese jämmerlichen, kleinen, grünhäutigen Monster mögen nur zwei Dinge: Gold und sich selbst.\n\nDie Schwarzfelsorcs haben sich goblinische Auftragsmörder zu Hilfe geholt, die unsere Soldaten töten sollen. Wenn Ihr zum Feld im Norden blickt, könnt Ihr schwach ihre Umrisse erkennen, wie sie im Gras umherschleichen.\n\nIhr müsst Euch dort hinbegeben und jeden Goblin töten, den Ihr zu Gesicht bekommt. Sie müssen kapieren, dass man sich nicht mit der Allianz anlegt!", progress = nil, completion = "Ihr habt diesen Monstern eine Lektion erteilt! Sie werden es sich zweimal überlegen, bevor sie noch einen Mordauftrag der Orcs annehmen.", rewards = "Ihr bekommt:\n\nAusstatterstiefel"}
MultiLanguageQuestData['de'][28798] = {title = "Elunes Wasser", objective = "Ihr habt einen ungewöhnlichen Brunnen entdeckt. Das Wasser leuchtet wie Mondlicht und gibt weiche, summende Töne von sich. Mit einer Hochgeborenenschriftrolle und Euren eindrucksvollen, archäologischen Fähigkeiten, könntet Ihr den Zweck dieses Brunnens entschlüsseln.", description = nil, progress = "Ihr habt einen ungewöhnlichen Brunnen entdeckt. Das Wasser leuchtet wie Mondlicht und gibt weiche, summende Töne von sich. Mit einer Hochgeborenenschriftrolle und Euren eindrucksvollen, archäologischen Fähigkeiten, könntet Ihr den Zweck dieses Brunnens entschlüsseln.", completion = "Nach ein paar Augenblicken seid Ihr in der Lage, mithilfe des Schlüsselsteins das Geheimnis des Wassers zu enthüllen...", rewards = "Ihr erlernt:\n\nWasser von Elune\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28799] = {title = "Die Macht der Irdenen", objective = "Auf den ersten Blick erscheint dieser Pfeiler sehr unbedeutend, aber dank Eurer Archäologiekenntnisse wisst Ihr, dass dem nicht so ist. Wenn Ihr einen Zwergenrunenstein hättet, könnte sein Ursprung ans Licht gebracht werden.", description = nil, progress = "Auf den ersten Blick erscheint dieser Pfeiler sehr unbedeutend, aber dank Eurer Archäologiekenntnisse wisst Ihr, dass dem nicht so ist. Wenn Ihr einen Zwergenrunenstein hättet, könnte sein Ursprung ans Licht gebracht werden.", completion = "Aha! Ihr wusstet, dass Ihr diesem Grad meisterlichen Handwerks schon zuvor begegnet seid. Jetzt, mit dem letzten Teil...", rewards = "Ihr erlernt:\n\nMacht der Irdenen\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28800] = {title = "Das Flüstern des Djinns", objective = "Diese Kohlenpfanne ist offensichtlich magisch, aber sie scheint nicht empfänglich für Eure Versuche, ihre Kräfte zu entfesseln. Wenn Ihr nur einen Schlüsselstein für Tol'vir-Hieroglyphen zur Verfügung hättet, könntet Ihr damit die Steingravuren an ihrer Seite entschlüsseln.", description = nil, progress = "Diese Kohlenpfanne ist offensichtlich magisch, aber sie scheint nicht empfänglich für Eure Versuche, ihre Kräfte zu entfesseln. Wenn Ihr nur einen Schlüsselstein für Tol'vir-Hieroglyphen zur Verfügung hättet, könntet Ihr damit die Steingravuren an ihrer Seite entschlüsseln.", completion = "Es scheint, als ob in dieser speziellen Kohlenpfanne ein niederer Djinn gefangen gehalten wird. Ihn zu befreien würde sicherlich eine Belohnung mit sich bringen. Oder?", rewards = "Ihr erlernt:\n\nFlüstern des Djinns\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28801] = {title = "Hieroglyphen der Tol'vir", objective = "Dieser Grabstein markiert eine seltsame Grabstätte – vermutlich von einem der ursprünglichen Erbauer. Wenn Ihr Tol'vir Hieroglyphen zur Verfügung hättet, könnten sie Euch helfen, den Text zu verstehen. Dies könnte sich als bedeutender, archäologischer Fund erweisen!", description = nil, progress = "Dieser Grabstein markiert eine seltsame Grabstätte – vermutlich von einem der ursprünglichen Erbauer. Wenn Ihr Tol'vir Hieroglyphen zur Verfügung hättet, könnten sie Euch helfen, den Text zu verstehen. Dies könnte sich als bedeutender, archäologischer Fund erweisen!", completion = "Mithilfe des Schlüsselsteins findet Ihr heraus, dass dies das Grab eines der ursprünglichen Erbauer ist. Ihr habt wichtige Details über den Mumifizierungsprozess erfahren.", rewards = "Ihr erlernt:\n\nGeheimnisse der Tol'vir\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28802] = {title = "Die Karte der Architekten", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nKarte der Architekten\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28803] = {title = "Die Rache der Wildhämmer", objective = "Diese alten Knochen scheinen zwergisch zu sein. Eventuell stammen sie von den ursprünglichen Erbauern von Grim Batol. Möglicherweise findet Ihr beim Vergleich der Zeichen auf der steinernen Gürtelschnalle mit einem Zwergenrunenstein mehr über Euren Fund heraus.", description = nil, progress = "Diese alten Knochen scheinen zwergisch zu sein. Eventuell stammen sie von den ursprünglichen Erbauern von Grim Batol. Möglicherweise findet Ihr beim Vergleich der Zeichen auf der steinernen Gürtelschnalle mit einem Zwergenrunenstein mehr über Euren Fund heraus.", completion = "Nachdem Ihr beides sorgfältig miteinander verglichen habt, seid Ihr Euch sicher, dass dies die Überreste eines Wildhammerzwergs sind. Der Verrat, der gegen sie begangen wurde, erfüllt Euer Herz mit Wut.", rewards = "Ihr erlernt:\n\nRache der Wildhämmer\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28804] = {title = "Ausweichplan der Dunkeleisenzwerge", objective = "Dies sind definitiv Pläne irgendeiner Art, aber wofür könnt Ihr nicht sicher sagen. Sie sind mit charakteristischen Zeichen versehen, die mit denen eines Zwergenrunensteins verglichen werden können.", description = nil, progress = "Dies sind definitiv Pläne irgendeiner Art, aber wofür könnt Ihr nicht sicher sagen. Sie sind mit charakteristischen Zeichen versehen, die mit denen eines Zwergenrunensteins verglichen werden können.", completion = "Interessant! Es scheint, als hätten die Dunkeleisenzwerge eine Strategie für den Fall entwickelt, dass sie einer Invasion von Elementaren gegenüberstehen würden. Da Elementarkräfte unveränderlich sind und nicht altern, scheint es, als ob diese uralten Techniken auch noch heute anwendbar sind.", rewards = "Ihr erlernt:\n\nKatastrophenplan der Dunkeleisenzwerge\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28805] = {title = "Das Auge des Sturms", objective = "Scharfseher Krogar will, dass Ihr in die Wasser der Weitsicht schaut.", description = "Seid gegrüßt, <Name>!\n\nJa, Euer Name ist dem Irdenen Ring nicht unbekannt.\n\nDie Zahl Eurer Heldentaten und Errungenschaften ist Legion. Azeroth steht schon jetzt tief in Eurer Schuld und dennoch bedarf das Land erneut seiner Helden.\n\nIch bin nur ein Bote. Eine bekannte Präsenz wünscht mit Euch zu sprechen.\n\nSchaut in die Wasser der Weitsicht und sehet das Schicksal unserer Welt.", progress = "Ja, <Klasse>?", completion = "Jetzt, wo Ihr die Wahrheit gesehen habt, werdet Ihr Euch dazu entschließen zu dienen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28806] = {title = "Fürchtet nicht das Böse", objective = "Belebt 4 verletzte Soldaten von Sturmwind wieder.", description = "Habt Ihr Euch schon zum Heiligen Licht bekannt, <Bruder/Schwester>? Durch das Heilige Licht werden wir errettet! Das Heilige Licht versetzt mich in die Lage, diese überaus fordernden Soldaten zu heilen! Und durch das Heilige Licht werdet Ihr in der Lage sein, hinaus ins Feld nach Norden zu gehen, und unsere gefallenen Brüder zu retten!\n\nTragt dieses Gebetsbuch mit Euch ins Feld und wirkt die heilende Berührung des Lichts auf die Verwundeten.", progress = nil, completion = "Ich glaube, Ihr versteht nun, welche Macht dem Licht innewohnt. Das Licht spendet Hoffnung, Bruder, und das Licht lässt die Finsternis schwinden! GESEGNET SEI DAS LICHT!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Player Phase/Auras\n\nIhr bekommt:\n\nArmschienen der Grenzlande"}
MultiLanguageQuestData['de'][28807] = {title = "Die Meinung des Spezialisten", objective = "Bringt die verdächtigen Abzeichen zu Mathias Shaw im SI:7 Hautquartier in Sturmwind.", description = "<Anduin hält die zueinanderpassenden Abzeichen hoch.> \n\nDas Medaillon, das wir auf dem Hof gefunden haben, ist identisch mit dem in Samuelsons Aufzeichnungen! Das kann kein Zufall sein. Ich glaube, Samuelson hat etwas vor, aber wir brauchen einen schlagenden Beweis, bevor wir einen Wächter beschuldigen, der das höchste Vertrauen meines Vaters genießt.\n\nEs gibt nur eine Person, der ich zutraue, dies alles wieder einzurenken: Mathias Shaw, der Anführer von SI:7. Zeigt ihm diese Abzeichen und wir sehen, was er darüber denkt. In der Zwischenzeit werde ich mich ebenfalls zurück zur Burg Sturmwind begeben und werde dort Samuelson keine Sekunde aus den Augen lassen!", progress = "Was habt Ihr mir da mitgebracht?", completion = "Anduin stellt Nachforschungen über den Schattenhammer an? Solltet Ihr nicht dafür sorgen, dass er NICHT in Schwierigkeiten gerät?\n\nHmmm. Lasst mich diese Abzeichen sehen, die Ihr entdeckt habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28808] = {title = "Fürchtet nicht das Böse", objective = "Belebt 4 verletzte Soldaten von Sturmwind wieder.", description = "Habt Ihr Euch schon zum Heiligen Licht bekannt, <Bruder/Schwester>? Durch das Heilige Licht werden wir errettet! Das Heilige Licht versetzt mich in die Lage, diese überaus fordernden Soldaten zu heilen! Und durch das Heilige Licht werdet Ihr in der Lage sein, hinaus ins Feld nach Norden zu gehen, und unsere gefallenen Brüder zu retten!\n\nTragt dieses Gebetsbuch mit Euch ins Feld und wirkt die heilende Berührung des Lichts auf die Verwundeten.", progress = nil, completion = "Ich glaube, Ihr versteht nun, welche Macht dem Licht innewohnt. Das Licht spendet Hoffnung, Schwester, und das Licht lässt die Finsternis schwinden! GESEGNET SEI DAS LICHT!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Player Phase/Auras\n\nIhr bekommt:\n\nSchuhe des Abtes von Nordhain"}
