MultiLanguageQuestData['de'][28813] = {title = "Fürchtet nicht das Böse", objective = "Belebt 4 verletzte Soldaten von Sturmwind wieder.", description = "Habt Ihr Euch schon zum Heiligen Licht bekannt, <Bruder/Schwester>? Durch das Heilige Licht werden wir errettet! Das Heilige Licht versetzt mich in die Lage, diese überaus fordernden Soldaten zu heilen! Und durch das Heilige Licht werdet Ihr in der Lage sein, hinaus ins Feld nach Norden zu gehen, und unsere gefallenen Brüder zu retten!\n\nTragt dieses Gebetsbuch mit Euch ins Feld und wirkt die heilende Berührung des Lichts auf die Verwundeten.", progress = nil, completion = "Ich glaube, Ihr versteht nun, welche Macht dem Licht innewohnt. Das Licht spendet Hoffnung, Bruder, und das Licht lässt die Finsternis schwinden! GESEGNET SEI DAS LICHT!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Player Phase/Auras\n\nIhr bekommt:\n\nWeste des Wolfsjägers"}
MultiLanguageQuestData['de'][28814] = {title = "Eine Anführerin und ihre Anhänger", objective = "Vernichtet Hohepriesterin Azil und 101 ihrer ergebenen Anhänger.", description = "Die Dokumente beschreiben die genauen Umstände der Ankunft von Hohepriesterin Azil in den Tiefen des Steinernen Kerns.\n\nAzil wird als ein hochrangiges Mitglied des Zwielichtrates beschrieben. Darüber hinaus bereitet ihre Gefolgschaft aus über hundert ergebenen Anhängern ein schreckliches Ritual von unvorhersehbarer Finsternis vor.\n\nKlingt wie ein Ereignis, das Ihr abwenden müsst.", progress = "Ihr seid zurückgekehrt, <Name>. Welche Neuigkeiten bringt Ihr?", completion = "Eine Hohepriesterin sagt Ihr? Und ein Mitglied des Zwielichtrates?\n\nAusgezeichnete Arbeit. Ich hoffe, Ihr empfindet Eure Belohnung als angemessen.", rewards = "Schulterstücke der unheiligen RitualeBand der Einhundert und EinsAuf Euch wartet eine dieser Belohnungen:\n\nSignet der Hohepriesterin\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][28815] = {title = "Dokumente des Schattenhammers", objective = "Beschafft die Dokumente des Schattenhammers.", description = "Wir sind einem der Schattenhammeragenten bis hierher gefolgt. Er trägt den Namen Millhaus Manasturm.\n\nWir haben Grund zu der Annahme, dass er wichtige Dokumente bei sich trägt.\n\nBis zu diesem Punkt können wir gehen, ohne unsere Pflicht zu verletzen, den innersten Teil des Tempels der Erde zu verteidigen.\n\nFindet Manasturm und holt Euch die Dokumente von ihm.", progress = "Dies scheinen die richtigen Dokumente zu sein.", completion = "&lt;Ihr öffnet die Dokumente und durchsucht sie nach bedeutsamen Informationen.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28816] = {title = "In die Tiefe", objective = "Meldet Euch bei Kommandant Thorak in der Messerbucht in Durotar.", description = "Der Irdene Ring hat die wasserreichen Gefilde von Vashj'ir als Quelle zerstörerischer Energien des Feindes ausgemacht.\n\nEs ist noch immer unklar, mit welchen Gefahren wir es hier zu tun haben. Jegliche Informationen, die Ihr sammeln könnt, sind von großem Wert.\n\nDie Horde schickt in diesem Augenblick Kriegsschiffe in die Region. Um dorthin zu gelangen, sprecht mit Kommandant Thorak in der Messerbucht.\n\nMögen die Geister Euch leiten, <Name>.", progress = nil, completion = "Lok'tar, Bruder! Ihr kommt gerade zur rechten Zeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28817] = {title = "Gefahr gebannt", objective = "Meldet Euch bei Marschall McBride vor der Abtei von Nordhain im Wald von Elwynn.", description = "Ausgezeichnete Arbeit, <Name>! Sie werden uns definitiv nicht mehr in den Rücken fallen. Wir kümmern uns um die Nachzügler. Ich will, dass Ihr zurück zu Marschall McBride geht, der südlich von hier vor der Abtei von Nordhain steht. Lasst ihn wissen, dass die Situation mit den Goblins unter Kontrolle ist.\n\nLebt wohl, <Klasse>.", progress = nil, completion = "Dank Eurer Hilfe ist es uns gelungen, die nördlichen und westlichen Abschnitte von Nordhain zu sichern. Dennoch gibt es im Osten noch immer eine ziemlich große Ansammlung von Schwarzfeslorcs und sie haben damit begonnen, den Wald niederzubrennen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28818] = {title = "Gefahr gebannt", objective = "Meldet Euch bei Marschall McBride vor der Abtei von Nordhain im Wald von Elwynn.", description = "Ausgezeichnete Arbeit, <Name>! Sie werden uns definitiv nicht mehr in den Rücken fallen. Wir kümmern uns um die Nachzügler. Ich will, dass Ihr zurück zu Marschall McBride geht, der südlich von hier vor der Abtei von Nordhain steht. Lasst ihn wissen, dass die Situation mit den Goblins unter Kontrolle ist.\n\nLebt wohl, <Klasse>.", progress = nil, completion = "Dank Eurer Hilfe ist es uns gelungen, die nördlichen und westlichen Abschnitte von Nordhain zu sichern. Dennoch gibt es im Osten noch immer eine ziemlich große Ansammlung von Schwarzfeslorcs und sie haben damit begonnen, den Wald niederzubrennen!", rewards = "Ihr bekommt:\n\n"}
