MultiLanguageQuestData['de'][28909] = {title = "Sauranok wird den Weg weisen", objective = "Sprecht mit Sauranok dem Mystiker in der Feste Grommash in Orgrimmar.", description = "Wie ich sehe, habt Ihr noch nicht mit meinem Berater, Sauranok dem Mystiker, gesprochen. Seit unserer gemeinsamen Kampagne in Nordend ist er nicht von meiner Seite gewichen.\n\nUm das Schattenhochland anzugreifen, brauchen wir eine Karte des Küstenstreifens. Ich habe Sauranok die Aufgabe gebeben, diese Information bereitzustellen. Seht nach, ob er Eure Hilfe benötigt! Er steht direkt neben mir.", progress = nil, completion = "&lt;Sauranok nickt Euch zu.&gt;\n\n&lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
