MultiLanguageQuestData['de'][28934] = {title = "Die Krone zerschmettern", objective = "Tötet 5 Techniker der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich vom Grab des Khartut in Uldum zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: offenbar in Uldum, direkt östlich vom Grab des Khartut, in der Nähe des Zugangs von Tanaris. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", progress = nil, completion = "Gut gemacht! Dafür habt Ihr Euch eine kleine Belohnung verdient. Und kommt doch morgen wieder zu mir, wenn Ihr Zeit habt! Vielleicht habe ich eine Aufgabe für Euch.", rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][28935] = {title = "Die Krone zerschmettern", objective = "Tötet 5 Techniker der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich vom Grab des Khartut in Uldum zu zerstören und kehrt zu Inspektor Snap Schnappbolz in Orgrimmar zurück.", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: offenbar in Uldum, direkt östlich vom Grab des Khartut, in der Nähe des Zugangs von Tanaris. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", progress = nil, completion = "Gut gemacht! Dafür habt Ihr Euch eine kleine Belohnung verdient. Und kommt doch morgen wieder zu mir, wenn Ihr Zeit habt! Vielleicht habe ich eine Aufgabe für Euch.", rewards = "Ihr bekommt:\n\nZeichen der Liebe"}
MultiLanguageQuestData['de'][28936] = {title = "Diva-Dilemma", objective = "Tötet 6 Naga.", description = "TBD.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][28937] = {title = "Alliance Breadcrumb", objective = "Sprecht mit Lady Gurga in der Faldirbucht.Monster! Da waren Monster, sage ich!\n\nUnser Schiff ist südlich von Stromgarde vor Anker gegangen, aber die Küste wimmelt nur so vor merkwürdigen Kreaturen.\n\nIhre hässlichen Fratzen zu sehen und ihre komischen Gurgelgeräusche zu hören reicht mir. Ich habe mich aus dem Staub gemacht, bevor klar wurde, was sie im Schilde führen. Ihr geht besser meinen Schiffskameraden helfen, <Name>!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Monster! Da waren Monster, sage ich!\n\nUnser Schiff ist südlich von Stromgarde vor Anker gegangen, aber die Küste wimmelt nur so vor merkwürdigen Kreaturen.\n\nIhre hässlichen Fratzen zu sehen und ihre komischen Gurgelgeräusche zu hören reicht mir. Ich habe mich aus dem Staub gemacht, bevor klar wurde, was sie im Schilde führen. Ihr geht besser meinen Schiffskameraden helfen, <Name>!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
