MultiLanguageQuestData['de'][29015] = {title = "Des Minenarbeiters Vermögen", objective = "Erhaltet den Katzenaugensmaragd von einem der Vorarbeiter oder Vollstrecker der Venture Co.", description = "He, <Volk>, seid Ihr an Schätzen interessiert? Wusste ich es doch, dass das Eure Aufmerksamkeit gewinnen würde.\n\nHier an den Flussdocks geht das Gerücht um, dass einer der Minenarbeiter in der Felsadermine der Venture Company nordöstlich von hier einen Smaragd von der Größe Eurer Faust gefunden hat.\n\nIch kenne ein paar Käufer, die daran interessiert wären, so etwas in die Finger zu bekommen, und ich wäre bereit, halbe-halbe beim Verkauf mit Euch zu machen. Seid Ihr dabei?", progress = "Wenn wir nur wüssten, welcher der Minenarbeiter den Smaragd gefunden hat, wäre das der reinste Spaziergang...", completion = "Seht Euch nur an, wie riesig das Ding ist! Wir sind reich! Mal sehen, wenn man nach dem in Lorenhall gültigen Kurs für Edelsteine geht, sollte ich Euren Anteil berechnen können - fünfzig Prozent, selbstredend!\n\nAlso, dann sehen wir mal... Ich denke, damit sollten wir quitt sein. Es war mir ein Vergnügen, Geschäfte mit Euch zu machen, &lt;Name&gt;.", rewards = "HändlerhandschuheUnregelmäßiger GürtelMissgestaltete StiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29016] = {title = "Eimer mit Süßigkeiten", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSüßes oder Saures\n\nIhr bekommt:\n\nEine Handvoll Süßigkeiten"}
