MultiLanguageQuestData['de'][29020] = {title = "Eimer mit Süßigkeiten", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSüßes oder Saures\n\nIhr bekommt:\n\nEine Handvoll Süßigkeiten"}
MultiLanguageQuestData['de'][29021] = {title = "Samophlang", objective = "Verschafft Euch Zugang zur Steuerkonsole in der Forschungseinrichtung der Venture Company.\n\nBereitgestellter Gegenstand: \n", description = "Die Venture Company hat weit nördlich von hier, westlich des Schlickmoores, eine kleine Forschungseinrichtung errichtet. Was die Leute dort tun, weiß ich nicht genau, aber ich habe herausgefunden, dass sie dort mit etwas experimentieren, das \"Samophlang\" genannt wird.\n\nWas zum Teufel ist ein Samophlang? Naja, was immer es auch ist, ich möchte es untersuchen, also brauche ich jemanden, der eines beschafft.\n\nIch habe ein Exemplar der Bedienungsanleitung für ihr Steuersystem in die Finger bekommen; Ihr solltet also herausfinden können, wie man das Samophlang daraus entfernt.", progress = nil, completion = "Eine Vielzahl von Knöpfen, Hebeln und blinkenden Lampen sind etwas ungeordnet auf der Oberfläche der Steuerkonsole angebracht. Eine kleine Anzeige deutet darauf hin, dass die Apparatur momentan optimal funktioniert und dass die Ventile eins bis drei derzeit geöffnet sind. Rechts unten an der Seite der Steuerkonsole befindet sich ein kleines Schlüsselloch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29022] = {title = "Samophlang", objective = "Schließt das Treibstoffzufuhrventil, das Regelventil und das Hauptsteuerventil, und benutzt dann noch einmal die Steuerkonsole.", description = "Die drei Steuerventile sind momentan geöffnet. Die verschiedenen Anzeigen der Steuerkonsole führen Euch zu der Annahme, dass man sie zunächst schließen muss, bevor der Apparat ausgeschaltet werden kann.", progress = "Blinkende Lampen auf der Steuerkonsole deuten darauf hin, dass die Hauptsteuerventile noch nicht geschlossen wurden.", completion = "Die Lampen erlöschen, sobald die drei Steuerventile geschlossen werden. Grüne Lampen wechseln langsam zu gelb, und der Schalter zur Steuerung des Apparats kann jetzt betätigt werden. Da alle Ventile geschlossen sind, könnt Ihr ihn ausschalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29023] = {title = "Samophlang", objective = "Besorgt Euch bei Tüftler Kichers den Konsolenschlüssel.", description = "Da der Apparat jetzt ausgeschaltet ist, kann die Steuerkonsole geöffnet und das Samophlang entfernt werden. Alles andere sollte unangetastet bleiben und Ihr benötigt jetzt nur noch den Schlüssel, mit dem die Konsole geöffnet werden kann.", progress = "Die Lampen der Konsole leuchten schwach und sämtliche Anzeigen und Skalen stehen auf null, alles ist im Leerlauf.", completion = "Kaum wird der Schlüssel herumgedreht, öffnet sich die Steuerkonsole. Oben auf der Konsole erlischt eine rote Lampe und das Terminal führt keinen Strom mehr.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29024] = {title = "Samophlang", objective = "Bringt das Samophlang zu Stotterspritter in Düsentopfs Außenposten im Nördlichen Brachland zurück.", description = "Nach dem Öffnen der Front der Steuerkonsole zeigt sich ein dichtes Gewirr aus Kabeln, Schläuchen und anderen seltsamen, mechanischen Objekten - die meisten davon scheinen keinen praktischen Nutzen zu haben. Ihr schiebt sie beiseite und arbeitet Euch tiefer in die Konsole vor, bis Ihr schließlich das Samophlang gefunden habt. Mit einem Ruck zieht Ihr es aus der Halterung.", progress = "Ihr seid zurück, <Name>! Habt Ihr das Samophlang?", completion = "Das ist... äh... interessant... wirklich. Ein komplexes Gerät wie dieses sollte von einem Team fähiger Ingenieure in einem sterilisierten Raum analysiert werden, die in mühsamer Kleinarbeit jedes Bauteil einzeln unter kontrollierten Bedingungen nachkonstruieren.\n\nAber wer hat schon diese Zeit?\n\nSchmeißen wir das Teil einfach an und schauen mal was passiert...", rewards = "Liebevoll hergestellter GürtelStiefel des sterilisierten RaumsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29026] = {title = "Wenikee Kübelbolz", objective = "Bringt das zerbrochene und ramponierte Samophlang zu Wenikee Kübelbolz. Sprecht mit Brak, um direkt zu ihr teleportiert zu werden.", description = "Ich glaube, ich habe das Ding wirklich kaputt gemacht: sieht so aus, als hätte ich einen der tragenden Fluxoren in die Speichen des Deregulatorgetriebes gehämmert. Aber das können wir ganz einfach beheben. Ich kenne eine Expertin für 3-fach Expansionskolbenantriebe, die liebend gern ein Samophlang in die Finger bekommen würde. Bringt das zerbrochene Samophlang zu Wenikee Kübelbolz südlich des Schutzwalls von Mor'shan und sie wird es schon zusammenflicken.\n\nHe, Ihr müsst noch nicht einmal zu Fuß gehen. Das ist die perfekte Gelegenheit, meinen persönlichen Personenporter zu testen!", progress = "Ich bin gerade sehr beschäftigt, <Klasse>. Wenn Ihr also nichts für mich habt, dann solltet Ihr am besten einfach wieder gehen...", completion = "Oh, was haben wir denn hier? Ein Samophlang, sagt Ihr? Was ist ein Samophlang?\n\nAh, jetzt schaut doch nur, es bewegt sich, wenn man es anfasst. Und im Inneren ist das Geräusch eines komplizierten Getriebes. Oh Mann! Ich will das Ding unbedingt reparieren und sehen, was es tut, Ihr nicht?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29027] = {title = "Schraubnieten", objective = "Sammelt 10 Schraubnieten aus den Wergzeugkisten um den Hof der Brennenden Klinge im Südwesten.", description = "Ich möchte das Samophlang reparieren, aber dazu brauche ich ein paar Dinge. Ich habe keine 17,5er Schraubnieten mehr, und davon werde ich für meine Arbeit hier eine ganze Menge brauchen.\n\nLeider ist der nächstgelegene Ort, an dem man sie bekommen kann, der Hof der Brennenden Klinge im Südwesten. Der Ort wird schwer bewacht, seid also vorsichtig. Durchsucht die Werkzeugkisten und kehrt zu mir zurück, wenn Ihr genug Schraubnieten gesammelt habt.", progress = "Habt Ihr die Schraubnieten, <Name>? Ständig muss ich mir dieses Samophlang ansehen - ich kann es gar nicht erwarten, endlich daran herumzubasteln.", completion = "Prima, Ihr habt sie! Jetzt kann ich mich endlich an die Arbeit machen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29028] = {title = "Hinein nach Jaedenar", objective = "Macht Andalar Dämmertal in Jaedenar ausfindig.Der Schattenrat verdirbt diesen einst wunderschönen Wald von ihrer Festung Jaedenar aus, die nordwestlich von hier liegt.\n\nEiner der Unseren ist nun dort verschwunden. Wir haben einen einzelnen Späher mit Namen Andalar Dämmertal in der Hoffnung losgeschickt, dass er die Reihen des Feindes heimlich lichten kann.\n\nSeit Tagen haben wir nichts von ihm gehört und befürchten das Schlimmste. Es besteht eine kleine Chance, dass er noch am Leben ist. <Name>, bitte brecht sofort auf und macht ihn ausfindig!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Der Schattenrat verdirbt diesen einst wunderschönen Wald von ihrer Festung Jaedenar aus, die nordwestlich von hier liegt.\n\nEiner der Unseren ist nun dort verschwunden. Wir haben einen einzelnen Späher mit Namen Andalar Dämmertal in der Hoffnung losgeschickt, dass er die Reihen des Feindes heimlich lichten kann.\n\nSeit Tagen haben wir nichts von ihm gehört und befürchten das Schlimmste. Es besteht eine kleine Chance, dass er noch am Leben ist. <Name>, bitte brecht sofort auf und macht ihn ausfindig!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29029] = {title = "Sterbendes Wissen", objective = "Bringt die gefüllte Feldflasche zu Andalar Dämmertal.<Das verderbte Wasser blubbert und schäumt, als wolle es vor sich selbst entkommen.>\n\nBringt dieses Wasser zu unserem Feldspäher. Er sollte in der Lage sein, es für unseren Angriff auf die Verteidigung der Schattenfeste zu läutern!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "<Das verderbte Wasser blubbert und schäumt, als wolle es vor sich selbst entkommen.>\n\nBringt dieses Wasser zu unserem Feldspäher. Er sollte in der Lage sein, es für unseren Angriff auf die Verteidigung der Schattenfeste zu läutern!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29030] = {title = "Ehrt die Flamme", objective = "Ehrt das Freudenfeuer des Irdenen Rings auf dem Hyjal.", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, <Name>?", progress = nil, completion = "Ehrt die Flamme des Hyjal.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVerehrung der Flamme\n\nIhr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][29031] = {title = "Ehrt die Flamme", objective = "Ehrt das Freudenfeuer des Irdenen Rings in Vashj'ir.", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, <Name>?", progress = nil, completion = "Ehrt die Flamme von Vashj'ir.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVerehrung der Flamme\n\nIhr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][29032] = {title = "Solange sie noch jung sind", objective = "Sammelt 8 Frostsäblerjunge aus den Bauen rund um den Frostsäblerfelsen.", description = "Ich kann Euch beibringen, wie man einen Winterquellfrostsäbler reitet, aber das braucht Zeit und Hingabe. Damit das funktioniert, müssen sowohl Säbler als auch Reiter hervorragend ausgebildet sein und es muss zwischen ihnen tiefempfundenes Vertrauen bestehen.\n\nDie Jungtiere sind für dieses Training nur empfänglich, wenn sie in jungen Jahren mit ihrem Reiter vertraut gemacht werden. In den Bauen rund um den Frostsäblerfelsen gibt es Junge, die das richtige Alter haben, um ihre Ausbildung zu beginnen. Wenn Ihr mir helft, die vielversprechendsten dieser Jungtiere einzusammeln, gestatte ich Euch, dass Ihr Euer Training mit Eurem eigenen Jungtier aufnehmt.", progress = "Wir müssen die Säblerjungen in unsere Obhut nehmen, solang sie noch jung genug sind, uns anzunehmen. Wenn sie zu alt werden, bleiben sie ihr Leben lang wild.", completion = "Diese Jungen haben genau das richtige Alter, um ihre Ausbildung zu beginnen. Einige von ihnen haben sogar die nötigen Eigenschaften, um als Reittiere zu dienen. Wie versprochen werde ich eines dieser Jungtiere für Euch zum Abrichten aussuchen. Dieser Bursche hier scheint Euch zu mögen.\n\nIch werde die gewöhnlichen, etwas zahmeren Jungen für den Markt in Darnassus ausbilden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29034] = {title = "Wie schnell sie heranwachsen", objective = "Sammelt 20 Schnurrhaare eines Winterquelljungen, die von Eurem Winterquelljungen abgeworfen worden sind. Bringt die Schnurrhaare, 20 Runenstoff, 20 unverwüstliches Leder und 80 Gold zu Rivern Frostwind.", description = "Ich glaube, dieser kleine Bursche passt gut zu Euch.\n\nDieses Junge wird eine Menge Aufmerksamkeit brauchen, damit es groß und stark wird. Ihr solltet mindestens einmal täglich nach Eurem Jungen sehen. Die beste Methode, ein Vertrauensverhältnis mit ihm aufzubauen, besteht darin, es zu füttern und zu umsorgen.\n\nWenn Euer Junges heranwächst, wird es seine alten Schnurrhaare abwerfen und neue, seiner Größe angemessene bekommen. Bringt mir Euer Junges zusammen mit ein paar Materialien für Euren Sattel, sobald es zwanzig Schnurrhaare verloren hat.", progress = "Wie geht es Eurem jungen Säbler?", completion = "Wie es scheint, habt Ihr hervorragende Arbeit bei der Aufzucht Eures Jungen geleistet, &lt;Name&gt;. Euer Säbler ist zu einem starken, gesunden und loyalen Begleiter herangewachsen. Ihr passt gut zueinander.\n\nNehmt diese Pfeife. Euer Winterquellfrostsäbler wird Eurem Ruf folgen, wenn Ihr mit ihm reiten wollt.", rewards = "Ihr bekommt:\n\nZügel des WinterquellfrostsäblersErstes Katzenspielzeug"}
MultiLanguageQuestData['de'][29035] = {title = "Katzenhunger", objective = "Sammelt 6 Stück Splitterzahnfleisch von beliebigen Splitterzahnbären in Winterquell und verfüttert sie an Euer Winterquelljunges.", description = "Euer Winterquelljunges schaut Euch an und leckt sich die Lippen. Die kleine Katze muss Hunger haben und es ist Eure Aufgabe, geeignetes Futter für Euren Schützling zu finden.\n\nRivern Frostwind hat erwähnt, dass er immer etwas Fleisch von Splitterzahnbären vorrätig hat, mit dem er seine Frostsäblerjungen füttert. Vielleicht mag Euer Junges ja auch etwas Splitterzahnfleisch. Überall in Winterquell kann man verschiedene Arten von Splitterzahnbären finden.", progress = "Euer Winterquelljunges sieht Euch an als wolle es sagen \"Das soll alles sein?\".", completion = "Euer Winterquelljunges sieht glücklich und zufrieden aus und scheint bereit zu sein, sich für ein Schläfchen zusammenzurollen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCub's Cravings Completion\n\nIhr bekommt:\n\nSchnurrhaar eines Winterquelljungen"}
MultiLanguageQuestData['de'][29036] = {title = "Ehrt die Flamme", objective = "Ehrt das Freudenfeuer des Irdenen Rings in Tiefenheim.", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, <Name>?", progress = nil, completion = "Ehrt die Flamme von Tiefenheim.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVerehrung der Flamme\n\nIhr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][29037] = {title = "\"Leihgabe\" von den Winterfellen", objective = "Sammelt 6 Stück Räucherfleisch aus einem der beiden Lager der Winterfellfurbolgs in Winterquell und verfüttert sie an Euer Winterquelljunges.", description = "Euer Junges sieht Euch erwartungsvoll an. Was es wohl jetzt möchte?\n\nDie kleine Katze leckt sich die Lippen. Es muss wohl wieder Zeit zum Essen sein! Als <Ersatzvater/Ersatzmutter> für das Junge ist es Eure Aufgabe, für Futter zu sorgen, bis es selbst auf die Jagd gehen kann.\n\nAber was, wenn Ihr jemand anderem das Jagen überlassen würdet? Die Winterfellfurbolgs in Winterquell haben für gewöhnlich eine Menge Räucherfleisch in ihren beiden Lagern. Ein paar Stücke würde doch niemand vermissen und Euer Junges könnte etwas Neues probieren.", progress = nil, completion = "Euer Junges sieht fürs Erste zufrieden aus.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWintersaber Cub Daily Counter\n\nIhr bekommt:\n\nSchnurrhaar eines Winterquelljungen"}
MultiLanguageQuestData['de'][29038] = {title = "Jagen üben", objective = "Bringt Euer Junges fünfmal in die Nähe von schneebedeckten Bauen im nördlichen Winterquell, damit es lernt, wie man Arktishasen jagt.", description = "Euer Winterquelljunges spielt mit Euren Händen. Ohne Spielgefährten hat das Kätzchen nur selten Gelegenheit, seine Jagdfähigkeiten zu üben.\n\nVielleicht solltet Ihr Euer Junges Jagd auf die kleinen Arktishasen, die ihre Baue im nördlichen Winterquell graben, machen lassen. Bringt Euer Junges in die Nähe der Schneewehen, die die Hasenbaue bedecken, und wartet, bis das Junge seinen Instinkten folgt.", progress = nil, completion = "Euer Winterquelljunges sieht müde, zufrieden und vielleicht etwas erfahrener aus.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForce Cast Clear Aura and Growth Credit\n\nIhr bekommt:\n\nSchnurrhaar eines Winterquelljungen"}
MultiLanguageQuestData['de'][29039] = {title = "Jagen üben", objective = "Bringt Euer Junges fünfmal in die Nähe von schneebedeckten Bauen im nördlichen Winterquell, damit es lernt, wie man Arktishasen jagt.", description = "Euer Winterquelljunges spielt mit Euren Händen. Ohne Spielgefährten hat das Kätzchen nur selten Gelegenheit, seine Jagdfähigkeiten zu üben.\n\nVielleicht solltet Ihr Euer Junges Jagd auf die kleinen Arktishasen, die ihre Baue im nördlichen Winterquell graben, machen lassen. Bringt Euer Junges in die Nähe der Schneewehen, die die Hasenbaue bedecken, und wartet, bis das Junge seinen Instinkten folgt.", progress = nil, completion = "Euer Junges sieht müde, zufrieden und vielleicht etwas erfahrener aus.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nForce Cast Clear Aura and Growth Credit\n\nIhr bekommt:\n\nSchnurrhaar eines Winterquelljungen"}
MultiLanguageQuestData['de'][29040] = {title = "Kätzchens erstes Spielzeug", objective = "Erhaltet einen schweren Yetibalg und 5 Wildekinfedern. Stellt daraus ein Katzenspielzeug aus Winterquell her und benutzt es, um mit Eurem Winterquelljungen zu spielen.", description = "Das Winterquelljunge spielt mit einem kleinen Fellknäuel, das von einem großen Tier zu stammen scheint. Es sieht zwar so aus, als ob Euer Junges Spaß an dem neuen Spiel hat, Ihr fragt Euch aber, ob es an einem richtigen Katzenspielzeug nicht mehr Spaß haben würde.\n\nMit etwas Leder von einem Yetipelz und einigen Federn von den wahnsinnigen Mondkin könntet Ihr ein brauchbares Spielzeug herstellen. Ihr braucht einen Balg von den Yetis in den Eisdistelbergen südöstlich der Ewigen Warte und Federn von den Mondkin im Versteckten Hain oder dem Eulenflügeldickicht.", progress = "Das Junge schaut Euch an. Was Ihr wohl vorhabt?", completion = "Euer Winterquelljunges scheint sein neues Spielzeug zu lieben, aber ob das Spielzeug den Enthusiasmus des Kätzchens überlebt ist ungewiss.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWintersaber Cub Daily Counter\n\nIhr bekommt:\n\nSchnurrhaar eines Winterquelljungen"}
MultiLanguageQuestData['de'][29051] = {title = "Kätzchens erstes Spielzeug", objective = "Erhaltet einen schweren Yetibalg und 5 Wildekinfedern. Stellt daraus ein Katzenspielzeug aus Winterquell her und benutzt es, um mit Eurem Winterquelljungen zu spielen.", description = "Das Winterquelljunge spielt mit einem kleinen Fellknäuel, das von einem großen Tier zu stammen scheint. Es sieht zwar so aus, als ob Euer Junges Spaß an dem neuen Spiel hat, Ihr fragt Euch aber, ob es an einem richtigen Katzenspielzeug nicht mehr Spaß haben würde.\n\nMit etwas Leder von einem Yetipelz und einigen Federn von den wahnsinnigen Mondkin könntet Ihr ein brauchbares Spielzeug herstellen. Ihr braucht einen Balg von den Yetis in den Eisdistelbergen südöstlich der Ewigen Warte und Federn von den Mondkin im Versteckten Hain oder dem Eulenflügeldickicht.", progress = "Das Junge schaut Euch an. Was Ihr wohl vorhabt?", completion = "Euer Winterquelljunges scheint sein neues Spielzeug zu lieben, aber ob das Spielzeug den Enthusiasmus des Kätzchens überlebt ist ungewiss.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWintersaber Cub Daily Counter\n\nIhr bekommt:\n\nSchnurrhaar eines Winterquelljungen"}
MultiLanguageQuestData['de'][29052] = {title = "Katzenhunger", objective = "Sammelt 6 Stück Splitterzahnfleisch von beliebigen Splitterzahnbären in Winterquell und verfüttert sie an Euer Winterquelljunges.", description = "Euer Winterquelljunges schaut Euch an und leckt sich die Lippen. Die kleine Katze muss Hunger haben und es ist Eure Aufgabe, geeignetes Futter für Euren Schützling zu finden.\n\nRivern Frostwind hat erwähnt, dass er immer etwas Fleisch von Splitterzahnbären vorrätig hat, mit dem er seine Frostsäblerjungen füttert. Vielleicht mag Euer Junges ja auch etwas Splitterzahnfleisch. Überall in Winterquell kann man verschiedene Arten von Splitterzahnbären finden.", progress = "Euer Winterquelljunges sieht Euch an als wolle es sagen \"Das soll alles sein?\".", completion = "Euer Winterquelljunges sieht glücklich und zufrieden aus und scheint bereit zu sein, sich für ein Schläfchen zusammenzurollen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCub's Cravings Completion\n\nIhr bekommt:\n\nSchnurrhaar eines Winterquelljungen"}
MultiLanguageQuestData['de'][29053] = {title = "\"Leihgabe\" von den Winterfellen", objective = "Sammelt 6 Stück Räucherfleisch aus einem der beiden Lager der Winterfellfurbolgs in Winterquell und verfüttert sie an Euer Winterquelljunges.", description = "Euer Junges sieht Euch erwartungsvoll an. Was es wohl jetzt möchte?\n\nDie kleine Katze leckt sich die Lippen. Es muss wohl wieder Zeit zum Essen sein! Als <Ersatzvater/Ersatzmutter> für das Junge ist es Eure Aufgabe, für Futter zu sorgen, bis es selbst auf die Jagd gehen kann.\n\nAber was, wenn Ihr jemand anderem das Jagen überlassen würdet? Die Winterfellfurbolgs in Winterquell haben für gewöhnlich eine Menge Räucherfleisch in ihren beiden Lagern. Ein paar Stücke würde doch niemand vermissen und Euer Junges könnte etwas Neues probieren.", progress = nil, completion = "Euer Junges sieht fürs Erste zufrieden aus.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWintersaber Cub Daily Counter\n\nIhr bekommt:\n\nSchnurrhaar eines Winterquelljungen"}
MultiLanguageQuestData['de'][29054] = {title = "Stinkbomben los!", objective = "Sprecht mit Gertrude Fenlow, um Zugang zu einem Besen zu bekommen. Werft dann Stinkbomben auf Unterstadt ab.", description = "Grüße, <Klasse>! Ich hoffe, Ihr genießt die Schlotternächte. Ach, genug geplaudert... kommen wir zum Geschäftlichen. Unterstadt. Sie setzen Hexen und widerwärtige Magie ein, um Angriffe auf unsere Stadt zu führen. Manch einer mag sagen \"ignoriert doch die Kindereien der Horde\". Ich aber sage \"zeigen wir's ihnen!\"\n\nSprecht mit meiner Schwester Gertrude und sie wird Euch dabei helfen, ein paar Stinkbomben auf Unterstadt abzuwerfen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSüßes Saures"}
MultiLanguageQuestData['de'][29066] = {title = "Gute Neuigkeiten... und schlechte Neuigkeiten", objective = "Sprecht mit Matookla am Hain von Aessina auf dem Hyjal.", description = "<Schwarzhorn hat die Macht von Thol'embaars Überresten verwendet, um seine Fesseln loszuwerden. Aber immerhin scheint sich das Inferno zu legen.>\n\n<Matookla wird von dem Geschehen hier erfahren wollen. Sie wartet auf Euch am Hain von Aessina.>", progress = nil, completion = "Was? Schwarzhorn hat Euch geholfen, das Inferno zu bekämfen und ist dann verschwunden? Dieses verschlagene Wiesel!\n\nMacht Euch keine Vorwürfe, &lt;Name&gt;. Er hatte sich diesen Plan vermutlich in dem Moment ausgedacht, in dem er die Flammen den Berg hinaufsteigen sehen hat. Wir werden uns später um ihn kümmern müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29067] = {title = "Meister der Tränke", objective = "Bringt eine große Anzahl Tränke zu einem Alchemielehrer in einer beliebigen Hauptstadt.", description = "Tränke, Tränke, Tränke. Was ich Euch alles über Tränke beibringen könnte!\n\nBringt mir Proben Eurer Arbeit, damit ich weiß, dass Ihr bereit dazu seid.\n\nVergesst nicht, <Name>, dass Ihr nur EINE Spezialisierung erlernen könnt, Euch also die Elixier- und Transmutationsspezialisierung danach nicht mehr angeboten werden.", progress = "Habt Ihr die Tränke?", completion = "Hervorragend!", rewards = "Ihr erlernt:\n\nMeister der Tränke\n\nDer folgende Zauber wird auf euch gewirkt:\n\nMeister der Tränke"}
MultiLanguageQuestData['de'][29071] = {title = "Mit Eile nach Sturmwind!", objective = "Veteranen von Nordend, König Wrynn und die Allianz benötigen Eure Hilfe! Sturmwind und die Allianz werden von Todesschwinge und seinen Anhängern des Schattenhammerkults auf beispiellose Weise bedroht!\n\nIhr findet in diesem Brief einen Ruhestein, der Euch nach Sturmwind transportieren wird. Die Krone hat für Unterkunft für alle zurückkehrenden Helden im Gasthaus \"Zum Goldenen Fass\" im Zwergendistrikt gesorgt.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRuhestein des Helden"}
MultiLanguageQuestData['de'][29073] = {title = "Mit Eile nach Orgrimmar!", objective = "Veteranen von Nordend, Kriegshäuptling Garrosh befiehlt Euch umgehend nach Orgrimmar zurückzukehren! Ihr werdet die Klinge sein, die die Horde gegen Todesschwinge und seine Schattenhammergefolgsleute führen wird.\n\nBenutzt den in diesem Schreiben eingeschlossenen Ruhestein, um Euch nach Orgrimmar zu transportieren. Unsere Verbündeten erwarten Eure Rückkehr, Held.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRuhestein des Veteranen"}
MultiLanguageQuestData['de'][29074] = {title = "Eine Zeit zum Feiern", objective = "Sprecht mit Celestine Erntedank vor den Toren Sturmwinds.", description = "Frohe Grüße, <Klasse>!\n\nDie Schlotternächte sind eine Zeit des Feierns und der Besinnlichkeit, obwohl es scheint, dass viele von uns vergessen haben, warum. In der Tat sind manche Aspekte des Festes, wie der Weidenmann, über die Zeit verlorengegangen... bis jetzt, mit der Rückkehr von Gilneas in die Arme der Allianz.\n\nBegebt Euch vor die Tore Sturmwinds und sprecht mit Celestine Erntedank. Sie wird Euch mehr von der Weidenmannzeremonie erzählen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29075] = {title = "Eine Zeit des Gewinnens", objective = "Benutzt das Freudenfeuer vor dem Weidenmann.", description = "Grüße, <Klasse>. Der Weidenmann, der vor Euch steht, symbolisiert das Ich. Die Flammen, die ihn verbrennen, sind reinigendes Feuer.\n\nDie Tradition besagt, dass wir unsere Bürden ablegen und sie dem Feuer übergeben. Wir entledigen uns allem, was uns belastet und bereiten uns auf den Winter vor und erlangen Klarheit und Frieden. Nehmt doch an dieser Tradition teil, <Klasse>.\n\nNehmt einen Zweig von dem nahegelegenen Freudenfeuer und werft ihn nach dem Weidenmann.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSüßes Saures"}
MultiLanguageQuestData['de'][29076] = {title = "Kevin's Test Quest", objective = "Einfach abschließen.Ein Testquest.Der folgende Zauber wird auf euch gewirkt:\n\n", description = "Ein Testquest.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKevin's Test Script2"}
MultiLanguageQuestData['de'][29078] = {title = "Schlagt sie zurück!", objective = "Tötet 6 Kampfworgs des Schwarzfels.", description = "Noch ein Allianzrekrut, hm? Ich bin Marschall McBride, Kommandant dieser Garnison. Von Eurem Schlag sieht man hier sehr viele, <Volk>, aber wir können Eure Hilfe sicher brauchen.\n\nIhr kommt gerade rechtzeitig. Die Schwarzfelsorcs haben es geschafft, sich durch eine Lücke im Berg nach Nordhain einzuschleichen. Meine Soldaten tun ihr Bestes, sie zurückzudrängen, aber ich befürchte, wir werden bald überrant werden.\n\nGeht nach Nordwesten in den Wald und tötet die angreifenden Kampfworgs des Schwarzfels! Helft meinen Soldaten!", progress = nil, completion = "Ihr habt uns etwas Zeit verschafft, &lt;Name&gt;, aber jetzt müssen wir uns um größere Probleme Kümmern.", rewards = "Ihr bekommt:\n\nLäuferstiefel"}
MultiLanguageQuestData['de'][29079] = {title = "Worgs im Schafspelz", objective = "Tötet 8 Spione des Schwarzfels.", description = "Die einfallenden Orcs sind keine Narren. Sie schätzen uns ab, stellen sicher, dass ihre Angriffe zu ihrem Vorteil sein werden.\n\nIm Wald nordwestlich sind Spione der Schwarzfelsorcs. Sie spähen uns durch Handfernrohre aus, überwachen jeden unserer Schritte - und warten. Ich will, dass Ihr sie angreift!\n\nTötet die Spione der Schwarzfelsorcs! Wir müssen ihnen zeigen, dass wir wissen, dass sie uns beobachten und dass wir vorbereitet sind!", progress = nil, completion = "Hervorragende Arbeit, &lt;Name&gt;. Es hat sich herausgestellt, dass Ihr ein echter Gewinn für die Garnison seid.\n\nEs steht Euch frei, mit unseren Ausbildern in und um die Abtei herum zu sprechen, wenn Ihr Eure Kampfkünste schulen wollt.\n\nWenn Ihr soweit seid habe ich einen weiteren Auftrag für Euch...", rewards = "Ihr bekommt:\n\nBeine des Meisterspions"}
MultiLanguageQuestData['de'][29080] = {title = "Stürzt Euch in die Schlacht!", objective = "Meldet Euch bei Unteroffizier Willem hinter der Abtei von Nordhain im Wald von Elwynn", description = "Ich habe hier eine dringende Nachricht von Unteroffizier Willem. Wie es aussieht, haben die Schwarzfelsorcs goblinische Auftragsmörder angeheuert. Sie haben unser Bataillon hinter der Abtei überfallen. Willem bittet mich, ihm einen Helden zu schicken. Ihr müsst ihnen helfen, <Name>!\n\nIhr findet Unteroffizier Willem nördlich von der Abtei im Kommandozelt. Los!", progress = nil, completion = "Es ist wahr, wir wurden überfallen. Ich wage es nicht, noch mehr Soldaten dort hinauszuschicken und sie auch noch zu verlieren. Ich brauche einen Freiwilligen. Jemanden, der bereit ist, sein Leben aufs Spiel zu setzen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29081] = {title = "Sie haben Auftragsmörder losgeschickt", objective = "Tötet 8 goblinische Auftragsmörder.", description = "Habt Ihr jemals einen Goblin gesehen, <Name>? Diese jämmerlichen, kleinen, grünhäutigen Monster mögen nur zwei Dinge: Gold und sich selbst.\n\nDie Schwarzfelsorcs haben sich goblinische Auftragsmörder zu Hilfe geholt, die unsere Soldaten töten sollen. Wenn Ihr zum Feld im Norden blickt, könnt Ihr schwach ihre Umrisse erkennen, wie sie im Gras umherschleichen.\n\nIhr müsst Euch dort hinbegeben und jeden Goblin töten, den Ihr zu Gesicht bekommt. Sie müssen kapieren, dass man sich nicht mit der Allianz anlegt!", progress = nil, completion = "Ihr habt diesen Monstern eine Lektion erteilt! Sie werden es sich zweimal überlegen, bevor sie noch einen Mordauftrag der Orcs annehmen.", rewards = "Ihr bekommt:\n\nAusstattergürtel"}
MultiLanguageQuestData['de'][29082] = {title = "Fürchtet nicht das Böse", objective = "Belebt 4 verletzte Soldaten von Sturmwind wieder.", description = "Habt Ihr Euch schon zum Heiligen Licht bekannt, <Bruder/Schwester>? Durch das Heilige Licht werden wir errettet! Das Heilige Licht versetzt mich in die Lage, diese überaus fordernden Soldaten zu heilen! Und durch das Heilige Licht werdet Ihr in der Lage sein, hinaus ins Feld nach Norden zu gehen, und unsere gefallenen Brüder zu retten!\n\nTragt dieses Gebetsbuch mit Euch ins Feld und wirkt die heilende Berührung des Lichts auf die Verwundeten.", progress = "Rettet unsere Soldaten!", completion = "Ich glaube, Ihr versteht nun, welche Macht dem Licht innewohnt. Das Licht spendet Hoffnung, Bruder, und das Licht lässt die Finsternis schwinden! GESEGNET SEI DAS LICHT!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Player Phase/Auras\n\nIhr bekommt:\n\nArmschienen der Grenzlande"}
MultiLanguageQuestData['de'][29083] = {title = "Gefahr gebannt", objective = "Meldet Euch bei Marschall McBride vor der Abtei von Nordhain im Wald von Elwynn.", description = "Ausgezeichnete Arbeit, <Name>! Sie werden uns definitiv nicht mehr in den Rücken fallen. Wir kümmern uns um die Nachzügler. Ich will, dass Ihr zurück zu Marschall McBride geht, der südlich von hier vor der Abtei von Nordhain steht. Lasst ihn wissen, dass die Situation mit den Goblins unter Kontrolle ist.\n\nLebt wohl, <Klasse>.", progress = nil, completion = "Dank Eurer Hilfe ist es uns gelungen, die nördlichen und westlichen Abschnitte von Nordhain zu sichern. Dennoch gibt es im Osten noch immer eine ziemlich große Ansammlung von Schwarzfeslorcs und sie haben damit begonnen, den Wald niederzubrennen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29084] = {title = "Zufälliger, klassischer Dungeon 35-39 (Erster)", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRanzen voller hilfreicher Waren"}
MultiLanguageQuestData['de'][29085] = {title = "Zufälliger, klassischer Dungeon 35-39 (Nter)", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRanzen voller hilfreicher Waren"}
MultiLanguageQuestData['de'][29086] = {title = "Konkurrenz? Pah!", objective = "Erhaltet 6 von Stotterspritters Blaupausen von Zwangsarbeitern, Söldnern oder Peons der Venture Co.", description = "Ich bin nur ein kleiner Mann, der versucht, sich selbständig zu machen. Ich arbeite fleißig daran, den azerothischen Traum in die Tat umzusetzen, wisst Ihr?\n\nTja, kaum hatte ich mich hier niedergelassen, hat die Venture Co. nebenan entschieden, dass sie mich hier nicht wollen. Sie haben mich mit Drohbriefen schikaniert und dabei Wörter wie \"Unterlassungsklage\" benutzt.\n\nViel schlimmer ist, dass die Baupläne für meine neuste Maschine verschwunden sind und ich weiß genau, dass diese Langfinger sie gestohlen haben! Geht zum Schlickmoor und haut ein paar ihrer Arbeiter um. Ich bin mir sicher, dass sie meine Blaupausen haben!", progress = "Ich kann gar nicht glauben, dass sie sich auf dieses Niveau herablassen würden. Habt Ihr meine Blaupausen zurückbekommen?", completion = "Danke, dass Ihr meine Blaupausen beschafft habt. Jetzt kann meine Arbeit an der Silberblitz X-831 weitergehen.", rewards = nil}
MultiLanguageQuestData['de'][29087] = {title = "Schlickuntersuchungen", objective = "Untersucht 5 schlammige Spuren im Schlickmoor.", description = "He, <Name>, seht Ihr diese Fußabdrücke? Die sind gestern Nacht überall im Lager aufgetaucht! Es fehlt nichts, aber all unsere Habseligkeiten wurden... untersucht. Die schlammige Spur führt zurück zum Schlickmoor.\n\nDa hat jemand herumgeschnüffelt und das gefällt mir gar nicht. Könnt Ihr Euch nach Westen aufmachen und das Schlickmoor untersuchen? Seht nach, ob Ihr dort auch so eine Spur wie diese hier finden könnt!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29088] = {title = "Hyänenausrottung", objective = "Tötet 6 Fleischreißerhyänen.", description = "He, <Name>, wir haben hier ein echtes Problem. Die Hyänenpopulation westlich des Schlickmoors nimmt Überhand und die werden langsam zu einer Bedrohung.\n\nWenn ich deren Radau noch eine Nacht ertragen muss, werd' ich noch verrückt! Vernon da drüben sagt, die Hyänen könnten sogar etwas mit dem Verschwinden eines seiner Schweine zu tun haben. So etwas kommt überhaupt nicht in die Tüte.\n\nKönntet Ihr ihre Reihen etwas lichten gehen? Ihr könnt sie im Westen finden. Dort lungern sie bei helllichtem Tage herum.", progress = nil, completion = "Auf Nimmerwiedersehen! Diese dreckigen Plagegeister bedeuten mehr Ärger als einem lieb sein kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29089] = {title = "Schlickbestie!", objective = "Untersucht den Schlafplatz der Schlickbestie und tötet was auch immer zum Vorschein kommt.", description = "Was auch immer da im Schlickmoor lauert scheint nicht humanoid zu sein. Den Überresten in der Umgebung der Spuren nach zu urteilen, ist es außerdem gefährlich.\n\nIhr entschließt Euch, den Spuren zum Boden des Sees zu folgen und nach dem Ruheplatz des Wesens zu suchen.", progress = nil, completion = "Ihr habt gesehen, wie Abwasserschlamm direkt in den See gepumpt wurde? Es würde mich nicht überraschen, wenn die Schlickbestie durch die Sorglosigkeit der Venture Co. entstanden wäre.", rewards = "SchlickmoorumhangDüsentopfs WesteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29090] = {title = "Eine Brennende Bedrohung", objective = "Tötet 8 Mitglieder der Brennenden Klinge auf dem Hof im Südwesten.", description = "Wer passt auf, was hinter uns vor sich geht, während wir uns ganz dem Kataklysmus widmen? Unsere Anführer rufen gegen Todesschwinge zu den Waffen und währenddessen plant die Brennende Klinge unseren Untergang.\n\nJetzt in diesem Moment strömen neue Rekruten und Vorräte zu der Farm im Südwesten. Mir steht der Sinn nicht danach, von der Brennenden Klinge in den Rücken gestochen zu werden.\n\n<Name>, helft Ihr mir, dieses Schicksal abzuwenden? Geht und richtet unter ihnen ein Blutbad an, bevor es zu spät ist.", progress = nil, completion = "Danke, &lt;Name&gt;. Ihr habt einem alten Orc heute Nacht zu einem etwas ruhigeren Schlaf verholfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29091] = {title = "Freiheitsbewegung", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][29092] = {title = "Setzt den Urahnen in Kenntnis", objective = "Reist in eine Hauptstadt und sprecht mit dem Urahnen des Irdenen Rings.", description = "Diese Informationen müssen an den gesamten Irdenen Ring weitergeleitet werden. Ich bin mir nicht sicher, wie wir vorgehen sollten, aber der Urahn, der Euch überhaupt erst diese Aufgabe gestellt hat, weiß es vielleicht. Bitte sucht diesen Urahnen auf und findet heraus, was zu tun ist - wir müssen etwas unternehmen!", progress = nil, completion = "Das sind in der Tat schlimme Neuigkeiten. Wir müssen alles in unserer Macht Stehende tun, um diesen Krieg zu verhindern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29093] = {title = "Rund um den Schlund", objective = "Reist zur Späherkuppe in Westfall und steigt auf einen Mietchopper, um den Rasenden Schlund mit Eurem Waisenkind zu besichtigen.", description = "Einer meiner Freunde sagt, dass ein Dampfpanzermechaniker in Westfall Besucher seine Chopper fahren lässt. Mein Freund durfte sogar auf einem fahren!\n\nIch habe Leute auf Choppern am Waisenhaus vorbeifahren sehen. Die sind total laut und so ziemlich das Schnellste, das ich je gesehen habe! So einen will ich mal ausprobieren!\n\nKönnten wir zur Späherkuppe in Westfall reisen und einen dieser Chopper ausleihen? Bitte? Ich bin auch ganz artig und außerdem könnten wir dann dieses irre Riesenloch sehen, das aufgerissen wurde, als die Welt sich verändert hat!", progress = nil, completion = "Das war das Größte! Das will ich nächstes Jahr wieder machen. Wenn ich erwachsen bin, werde ich auch einen Chopper haben, aber den werde ich selbst bauen und alle meine Freunde auf eine Spritztour mitnehmen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29094] = {title = "Nach Hause katapultieren", objective = "Genießt einen Ritt auf der Silberblitz X-831.", description = "Sieht so aus, als wäre Eure Arbeit hier getan, <Klasse>. Ihr kehrt besser zum Wegekreuz zurück.\n\nIhr habt Glück, denn der Prototyp meiner Silberblitz X-831 ist fertig und sie wartet nur auf eine Probefahrt. Was haltet Ihr davon, mir einen letzten Gefallen zu tun und eine kleine Spritztour zu machen?\n\nEiner meiner Assistenten wird Euch begleiten. Euer fahrbarer Untersatz wartet auf der Plattform hinter mir auf Euch. Springt einfach drauf, wenn Ihr bereit seid.", progress = nil, completion = "Ich dachte, mit Euch wäre es aus gewesen. Schön, dass Ihr noch in einem Stück seid.", rewards = "Hosen des TestpilotenNotfallhackebeilchen"}
MultiLanguageQuestData['de'][29095] = {title = "Meldung bei Thork", objective = "Meldet Euch bei Thork am Wegekreuz im Nördlichen Brachland.", description = "Nun da die Bedrohung hier eingedämmt ist, solltet Ihr zum Wegekreuz zurückkehren. Thork möchte mit Euch sprechen.\n\nLebt wohl, Freund.", progress = nil, completion = "Hallo &lt;Name&gt;. Darsok hat mir von Euren Taten berichtet. Ihr seid der Horde wahrlich ein wertvoller &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29096] = {title = "Schließt Euch dem Konvoi von Mor'shan an", objective = "Sprecht mit Rocco Peitschenschwinger und fahrt mit dem Konvoi von Mor'shan nach Norden.", description = "Rocco Peitschenschwinger wartet auf Euch an der Straße, die nördlich aus dem Wegekreuz führt. Lasst ihn wissen, dass Ihr bereit seid, den Konvoi zu begleiten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29097] = {title = "Mor'shan Konvoirettung", objective = "TBDTBDIhr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "TBDIhr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29099] = {title = "Mor'shan Konvoilieferung", objective = "TBDTBDIhr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "TBDIhr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29100] = {title = "Bwembas Geist", objective = "Warnt die Bewohner des Schlingendorntals und findet den anderen Abgesandten der Dunkelspeere.", description = "Es sind gefährliche Zeiten für uns Dunkelspeere. Die Zandalaritrolle versammeln alle Trollklans und hab'n vor, die Länder wiederzuerobern, die sie verlor'n hab'n.\n\nWir versuch'n alle zu warnen, die wir können. Aber es könnte zu spät sein.\n\nEin weiterer Dunkelspeertroll is' ins Schlingendorntal gegang'n, um die Leute zu warnen. Aber es is' nich' sicher, allein da durchzuwandern.\n\nHilf mir, ihn zu find'n und sicherzustell'n, dass die Leute im Schlingendorntal von der Bedrohung durch die Trollstämme erfahr'n.\n\nIch werd' meinen Geist mit deinem verbind'n. Wenn du ins Schlingendorntal gelangst, werd' ich dir helf'n können.", progress = nil, completion = "Da siehst du's, &lt;Name&gt;. Sieht aus, als würd'n wir einen Angriff auf die Gurubashi in Zul'Gurub anführ'n.\n\nDies sind dunkle Zeiten für uns Dunkelspeere. Aber für die Zandalaritrolle werd'n sie noch dunkler. Sie sind zu weit gegang'n.\n\nDu bist gut zu Bwemba gewes'n, hoffentlich wirst du weiter das ganze Schlingendorntal unterstütz'n.\n\nMög'n die Geister mit dir sein, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\n4.1 - ZG Event - Cancel Bwemba Aura [DND]\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29101] = {title = "Ab ins Wasser!", objective = "Kickt 5 Abkömmlinge von Tortolla ins Wasser.", description = "Babyschildkröten sind so süß, auch wenn sie manchmal ein bisschen bissig sein können.\n\n<Mylune hält einen verbundenen Finger hoch.>\n\nAber auf ihren kurzen Beinchen sind sie so langsam, da können sie den Feuerwesen, die den Hyjal angreifen, nicht entkommen!\n\n<Mylune klatscht mit den Händen.>\n\nBITTE rettet sie, <Name>! Nehmt die klitzekleinen Schildkröten und kickt sie in das Wasser des Aschensees. Macht Euch keine Sorgen wegen des Kickens, sie haben harte Panzer.\n\nAußerdem haben sie ziemlich harte Zähne, Ihr solltet sie also nicht am Mund hochnehmen.", progress = nil, completion = "&lt;Mylunes Stimme schallt durch Euren Kopf, zusammen mit ungebetenen Bildern von verspielten Kätzchen.&gt;\n\nIhr habt die klitzekleinen Schildkröten gerettet, &lt;Name&gt;! Ich hoffe, der Tritt, den Ihr ihnen gegeben habt, war sanft, liebevoll und so fest wie möglich.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29102] = {title = "Auf nach Fort Livingston", objective = "Reist nach Fort Livingston im Nördlichen Schlingendorntal, um den Abgesandten der Dunkelspeere ausfindig zu machen.", description = "Zunächst sollt'n wir dort nachschau'n, wo sie vermutlich zuerst angreif'n werd'n. Der Ort nennt sich Fort Livingston.\n\nFort Livingston is' von Trollruinen umgeb'n... Und stellt ein einfaches Ziel dar.\n\nVielleicht find'n wir den Abgesandten dort. Hoffentlich is' es noch nich' zu spät.", progress = nil, completion = "Ein anderer Botschafter der Dunkelspeere ist hier vor einiger Zeit durchgekommen und hat uns gesagt, wir sollen auf der Hut sein.\n\nEr hat erwähnt, dass weitere Trolle auftauchen würden, aber nicht in Geistform und auch nicht, dass ein &lt;Klasse&gt; ihn begleitet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29103] = {title = "Schlangen und Gift", objective = "Tötet Dschungelschlangen und untersucht die vergifteten Abenteurer, damit Bwemba sie heilen kann.", description = "Dank der Warnung des Abgesandten konnten wir noch ein paar Abenteurer zur Verteidigung gewinnen. Aber wir haben erwartet, dass wir gegen Trolle kämpfen müssten, doch dann wurden wir von diesen Schlangen überwältigt!\n\nSie scheinen von überall her zu kommen. Wir können kaum noch durchhalten und ich fürchte, dass es nur noch schlimmer wird.\n\nHelft uns und eliminiert diese Schlangen... und vielleicht kann Eure Trollfreundin hier etwas Magie anwenden, um die Vergifteten zu heilen.", progress = nil, completion = "Danke für Eure Hilfe, &lt;Klasse&gt;. Die Schlangen sind ja überall.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRemove Mod Aura Vision - Quest Zone Specific 1\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29104] = {title = "Die Geister sind mit uns", objective = "Bereitet das Freudenfeuer in Fort Livingston für Bwembas Ritual vor.", description = "Mit den Schlangen hat was nich' gestimmt, <Name>. In ihrem Gift war eine Spur von schlechtem Mojo und das passiert nich' von Natur aus.\n\nDas Freudenfeuer in der Mitte des Lagers - dort können wir ein Ritual abhalt'n.\n\nWas auch immer diese Schlangen zum Angreif'n bringt, passt bestimmt noch gut auf sie auf.\n\nDas einzige Problem is', <Name>, dass ich nur in Geisterform hier bin. Du musst meine Hände sein. Geh zu dem Feuer und bereite es für mich vor. Dann kümmere ich mich um den Rest.", progress = nil, completion = "Venoxis... das kann nix Gutes heiß'n, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29105] = {title = "Nesingwary wird es wissen", objective = "Warnt die Jäger in Nesingwarys Expedition im Nördlichen Schlingendorntal.", description = "Großartig. Genau, was wir jetzt brauchen. Die Gurubashi sind auf dem Kriegspfad und benutzen Schlangen als erste Angriffswelle. Immerhin wissen wir Bescheid.\n\nWir können vermutlich davon ausgehen, dass die Jäger in Nesingwarys Expedition mehr darüber wissen. Und selbst, wenn nicht, wissen sie sicher eine gute Methode, wie man Schlangen loswird.\n\nMacht Euch dorthin auf den Weg und erzählt ihnen, was Ihr hier gesehen habt. Lasst sie wissen, dass die Trolle Schlangen als Waffen einsetzen.", progress = nil, completion = "Über die Schlangen wissen wir Bescheid, &lt;Name&gt;. Aber da draußen lauert noch etwas anderes... Der Dschungel ist zum Leben erwacht, &lt;Klasse&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29106] = {title = "Der größte Diamant aller Zeiten!", objective = "Bringt Euer Menschenwaisenkind in die Altstadt von Eisenschmiede unterhalb des Hohen Sitzes und besichtigt die letzte Ruhestätte von König Magni Bronzebart. Wenn Euer Waisenkind nicht bei Euch ist, wenn Ihr ankommt, solltet Ihr es herbeirufen.", description = "Ich habe gehört, dass Magni Bronzebart, der frühere König von Eisenschmiede, sich in einen riesigen Diamanten verwandelt hat! Stimmt das? Wie verwandelt man sich denn einfach so in einen Diamanten? Vielleicht muss man ja König sein, und deshalb hat es noch niemand vor ihm gemacht.\n\nGehen wir ihn besuchen? Er sollte in dem Teil von Eisenschmiede sein, der Altstadt von Eisenschmiede genannt wird, direkt unterhalb des Hohen Sitzes.", progress = nil, completion = "König Magni wollte also gar kein Diamant werden? Das ist aber traurig.\n\nHe, Schamanen arbeiten doch ständig mit Steinen und der Erde, oder? Vielleicht können sie ihm eines Tages helfen, wieder ein Zwerg zu werden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29107] = {title = "Malfurion ist zurückgekehrt!", objective = "Bringt Euer Menschenwaisenkind in den Tempel des Mondes in Darnassus, um Malfurion Sturmgrimm zu treffen. Wenn Euer Waisenkind nicht bei Euch ist, wenn Ihr ankommt, solltet Ihr es herbeirufen.", description = "Ich habe gehört, dass Malfurion Sturmgrimm aus dem Smaragdgrünen Traum zurückgekehrt ist. Ich weiß zwar nicht, wo das ist, aber es klingt ziemlich weit weg.\n\nJedenfalls soll er bei der Hohepriesterin oben im Tempel des Mondes in Darnassus sein. Meint Ihr, wir könnten ihn besuchen gehen? Er muss doch der mächtigste Druide in der Geschichte Azeroths sein!", progress = "Meint Ihr, ich könnte eines Tages auch ein Druide sein?", completion = "Das war großartig! Habt Ihr gesehen, wie Malfurion diese Flügel auf mich gewirkt hat? Die anderen Waisenkinder werden es so schade finden, dass sie diesen Ausflug verpasst haben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29108] = {title = "Mor'shan Test Quest", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][29109] = {title = "Schließt Euch dem Konvoi von Mor'shan an", objective = "Sprecht mit Rocco Peitschenschwinger und fahrt mit dem Konvoi von Mor'shan nach Norden.", description = "Die Schlacht ums Eschental tobt stetig weiter. Unsere Streitkräfte am Schutzwall von Mor'shan brauchen dringend Verstärkung und Nachschub.\n\nWir haben hier eine große Ladung Medikamente und Nahrungsmittel, die nach Norden gebracht werden soll, und <ein fähiger/eine fähige:c> <Klasse> wie Ihr ist vonnöten, <der/die:c> die Ladung bewacht.\n\nRocco Peitschenschwinger wartet auf Euch an der Straße, die nördlich aus dem Wegekreuz führt. Lasst ihn wissen, dass Ihr bereit seid, den Konvoi zu begleiten.", progress = nil, completion = "Das sind schreckliche Neuigkeiten! &lt;Name&gt;, wenigstens seid Ihr sicher angekommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29110] = {title = "Rettet den Konvoi von Mor'shan", objective = "Rettet Balgor Peitschenschwinger.", description = "Sie haben Balgor und die Konvoigüter unter unserer Nase weggeschnappt!\n\nDiese Lieferung ist für den Sieg gegen die Allianz im Eschental unabdingbar und Balgor... wenn meinem lieben kleinen Bruder auch nur ein Haar gekrümmt wird, reiße ich persönlich jedes einzelne Mitglied der Brennenden Klinge in Stücke.\n\n<Name>, Ihr müsst Balgor und die gestohlenen Güter retten. Folgt dem Pfad nördlich von uns zum Glutnebelgipfel. Lasst keinen einzigen dieser Hunde am Leben.", progress = nil, completion = "&lt;Name&gt;, Ihr eilt mir zur Rettung!", rewards = nil}
MultiLanguageQuestData['de'][29111] = {title = "Bringt den Konvoi von Mor'shan durch", objective = "Verteidigt den Konvoi von Mor'shan.", description = "Ihr habt es geschafft, den Unterschlupf der Brennenden Klinge aufzuscheuchen. Unsere Späher berichten, dass sie sich für einen Angriff sammeln.\n\nIhr müsst die Reise des Konvois abschließen, bevor sie hier ankommen. Die Vorräte sind verstaut, die Kodos sind ausgeruht und ich hoffe, Ihr habt nichts dagegen, dass ich ein paar Veränderungen an Eurem Gewehr vorgenommen habe.\n\nFalls wir auf Widerstand stoßen, solltet Ihr erst schießen und später Fragen stellen.\n\nSchnell! Da sind sie! Sprecht mit mir, wenn Ihr bereit zum Aufbruch seid.", progress = nil, completion = "An manchen Tagen machen wir Boden gut, an anderen Tagen werden wir wieder hinter unsere Mauern zurückgedrängt. Und jeden Tag begraben wir mehr von unseren Brüdern und Schwestern.\n\n&lt;Kadrak hält inne und atmet tief durch.&gt;\n\nDass Ihr uns Nachschub gebracht habt, hat nicht nur unsere Truppen gestärkt, Eure Heldentaten haben ihnen auch neuen Mut gegeben. Danke, &lt;Klasse&gt;.", rewards = "Handschuhe des wilden ReitersGamaschen des Karawanenführers von Mor'shanKadraks AxtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29112] = {title = "Dämonensaat", objective = "Bringt die Dämonensaat in Euren Besitz.", description = "Hört her, <Name>. Wir können noch nicht von hier weg. Ich habe ihre Pläne mitangehört, als sie das Ritual vorbereitet haben.\n\nSie haben vor, ein mächtiges Artefakt, das sie Dämonensaat nennen, dazu zu benutzen, einen Großangriff auf die Horde zu führen. Sie halten es dort drüben in der Höhle streng bewacht.\n\nWenn wir die Dämonensaat in unsere Hände bekommen können, sollten wir sie zu meiner Schwester Nagala bringen. Sie weiß sicher, was wir damit tun sollten.", progress = "Was habt Ihr auf der Spitze des Berges gefunden?", completion = "&lt;Name&gt;, Ihr seid zurück! Balgor hat es vor Euch vom Berg geschafft und hat bereits zwei Schüsseln Raptoreintopf gegessen. Wenn sein Appetit ein Hinweis ist, wird er sicher bald reisebereit sein.\n\nIch werde sicherstellen, dass dieses Artefakt sicher verwahrt wird. Ihr habt uns heute einen großen Dienst erwiesen.", rewards = "Ihr bekommt:\n\nOpferklinge"}
MultiLanguageQuestData['de'][29114] = {title = "Dem Spurenleser auf der Spur", objective = "Findet Grent Düsterhammer im Nördlichen Schlingendorntal.", description = "Wir schlagen hier schon seit Tagen die Schlangen zurück, <Name>. Aber Schlangen sind nichts im Vergleich zu dem, was sich da sonst noch so im Dschungel herumtreibt.\n\nWir Jäger werden zu Gejagten.\n\nEin großer Panther namens Mauti hat meine Männer einen nach dem anderen in den Busch weggezerrt.\n\nWir haben Grent Düsterhammer, einen unserer besten Jäger, auf dieses Mistviech angesetzt.\n\nDüsterhammer ist nach Osten aufgebrochen. Vielleicht könnt Ihr ihn dort finden.", progress = nil, completion = "Schhh...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29115] = {title = "Die Rache des Jägers", objective = "Gewährt Grent Düsterhammer die Genugtuung, die er sich wünscht, indem Ihr Mauti tötet.", description = "Die Bestie, die uns auf der Spur war... ich habe nach ihr gejagt.\n\nIhr Name ist Mauti. Sie ist ziemlich schlau. Doch sie hat einen großen Fehler begangen, als sie meinen Bruder getötet hat. Das wird sie teuer zu stehen kommen. Der alte Düsterhammer ist ihr auf den Fersen.\n\nIch habe sie oberhalb von Kurzens Truppenlager herumstreifen sehen. Wenn wir schnell zuschlagen, können wir ihr den Garaus machen.\n\nSeid Ihr bereit, <Name>?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29116] = {title = "Folgt dieser Katze", objective = "Findet heraus, wohin Mauti Grent Düsterhammer gebracht hat.", description = "Tja, deshalb schien Mauti wohl kleiner... Der echte Mauti hat sich mit Grent Düsterhammer davongemacht, aber da er so ein vorausschauender Jäger ist, hat er Signalfeuer abgeschossen, damit Ihr ihm auf der Spur bleiben könnt. Findet Düsterhammer, bevor es zu spät ist!", progress = nil, completion = "Da sind wir... Der Jäger, er is' in der Höhle. Die Bestie... Etwas stimmt mit ihr nicht...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRemove See Quest Invis 10\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29117] = {title = "Drachensteigen", objective = "Kauft einen Doppelpack Papierdrachen von Craggle Schlingerkreisel in Sturmwind und benutzt sie, um mit Eurem Menschenwaisenkind einen Drachen steigen zu lassen. Wenn Euer Waisenkind nicht bei Euch ist, solltet Ihr es herbeirufen.", description = "Neulich, als ein paar von uns mit der Matrone unterwegs waren, haben wir einen Gnom gesehen, der einen Wagen mit Spielzeugen geschoben hat. Er hatte Puppen, Rennwagen aus Kupfer, Lederbälle und Papierdrachen. Ich wollte schon immer einen Drachen haben und die Matrone sagt, dass ich nur all mein Geld sparen muss, dann kann ich mir einen kaufen, aber das dauert noch ewig.\n\nIch glaube, der Name des Gnoms war Craggle Schlingerkreisel oder so was. Wenn wir ihn aufspüren, könnten wir uns ein paar Drachen holen und sie steigen lassen? Ich habe ihn die Kanäle um den Handelsdistrikt herum entlanggehen sehen.", progress = nil, completion = "Danke für den Drachen, &lt;Name&gt;. Jedesmal wenn ich ihn steigen lasse, werde ich an den Tag denken, an dem Ihr ihn mir geschenkt habt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29118] = {title = "Folgt dieser Katze", objective = "Findet heraus, wohin Mauti Grent Düsterhammer gebracht hat.", description = "Der echte Mauti hat sich mit Grent Düsterhammer davongemacht, aber da er so ein vorausschauender Jäger ist, hat er Signalfeuer abgeschossen, damit Ihr ihm auf der Spur bleiben könnt. Findet Düsterhammer, bevor es zu spät ist!Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRemove See Quest Invis 10\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29119] = {title = "Lecker Eis", objective = "Kauft ein Eis im Laden Kältekegel und teilt es mit Eurem Waisenkind.", description = "Es gibt einen brandneuen Eisladen in Sturmwind und dort verkaufen sie nicht einfach nur gewöhnliches Eis. Deren Eis wird von Magiern gemacht! Glaubt Ihr, es wird verschwinden, wenn ich es nicht innerhalb von fünfzehn Minuten schaffe?\n\nIch wette, das schmeckt richtig lecker. Gehen wir kosten?\n\nIch habe einige der anderen Kinder darüber reden hören und die sagen, der Laden heißt 'Der Kältekegel' und steht drüben beim Blauen Eremiten im Magierviertel.", progress = "Eiscreme mag ich am liebsten.", completion = "Meint Ihr, die Lehrlinge stört es, all das Eis einfrieren zu müssen? Ich wünschte, wir dürften in der Schule Eis machen. Dann wäre der Unterricht viel spannender, findet Ihr nicht?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29120] = {title = "Mauti", objective = "Bringt Bwemba zu den Überresten von Mauti.", description = "Ich hab das Gefühl, dass mit dem Panther was nich' stimmt, <Name>. Fühlt sich unnatürlich an. Ich werd' ein paar Rituale über dem Leichnam abhalt'n müss'n. Töte Mauti und dann werd'n wir mal seh'n, was wir herausfinden können, <Name>.", progress = nil, completion = "Hohepriesterin Kilnara steckt hinter dieser Monstrosität. Das sieht nich' gut aus. Wir sollt'n nach dem Zwerg seh'n und dann herausfind'n, was sonst noch so los ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29121] = {title = "Die letzten Botten", objective = "Holt die Stiefel von Grent Düsterhammer.", description = "Ah... Ihr seid es, <Name>. Mauti... Er ist tot? Dann wurde mein Bruder gerächt. Ich habe nur noch eine Bitte an Euch... Dieser Schuft hier hat an meinen nackten Füßen herumgekratzt. Kein Zwerg sollte ohne Stiefel unter die Erde müssen.\n\nBitte, begrabt mich mit meinen Stiefeln.", progress = "Habt Ihr meine Stiefel? Gewährt einem Zwerg doch seinen letzten Wunsch, ja?", completion = "Da-Danke... Kumpel.\n\nPapi...?\n\n\nBist...\n\n\n\ndu das...\n\n\n\n\n...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\n4.1 - ZG Event - Nessingwary - Summon Dirt Mound\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29122] = {title = "Echos von Nemesis", objective = "Sprecht mit Tooga, um Nemesis zu beschwören und zu töten. Stellt Euch unter Toogas Panzer, um Euch vor Nemesis' 'Glühendem Zorn' zu schützen.", description = "<Mylunes Stimme singt wie eine Melodie in Eurem Kopf.>\n\nErinnert Ihr Euch an die furchtbare Feuerschildkröte, Nemesis, aus den Feuerlanden? Sie ist jetzt tot (hurra!), aber ihre Echos versuchen, zum Hyjal durchzubrechen.\n\nGeht zu den Ufern des Aschensees und sprecht mit meinem Freund Tooga. Lasst ihn wissen, wenn Ihr bereit seid, Euch einem Echo von Nemesis zu stellen und die Schildkröten werden es in diese Welt ziehen. Dann könnt Ihr es schlagen! Hart!\n\nVersteckt Euch in Toogas Panzer, wenn das Echo beginnt, auszubrechen.", progress = nil, completion = "Hurra! Da sieht man mal wieder, wenn eine Schildkröte sich was vorgenommen hat, dann...\n\n&lt;Mylune wird von einem Schmetterling abgelenkt und bringt den Gedanken niemals zu Ende.&gt;", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29123] = {title = "Sturm gegen die Flammen", objective = "Tötet 6 beliebige Eindringlinge aus den Feuerlanden am Geheilten Hyjal oder in Sethrias Nest.", description = "Von all unseren Aufgaben hier am Hyjal ist die dringendste recht einfach: diese Eindringlinge zu vernichten. Es liegt in der Natur des Feuers, dass es alles und jeden verzehrt. Wenn Ihr in Eurer Verteidigung nur einen Moment nachlasst, wird es alles im Sichtbereich zerstören.\n\nVernichtet alle feurigen Eindringlinge, die Ihr findet. Jeder bezwungene Feind erkauft dem Hyjal mehr Zeit.", progress = nil, completion = "Ihr habt Euch gut geschlagen, &lt;Name&gt;. Legt für eine Zeit eine Pause von den Flammen ein.\n\nDer Hyjal wird einen weiteren Tag erleben, und wenn dieser Tag anbricht, brauche ich Euch lebend.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29124] = {title = "Warnung an das Rebellenlager", objective = "Begebt Euch zum Rebellenlager.", description = "Dieser Tod is' nich' umsonst gewes'n, <Name>. Wir hab'n herausgefund'n, dass Kilnara auf der Jagd ist. Das sieht alles gar nich' gut aus.\n\nWir sollt'n besser das Rebellenlager im Norden auskundschaft'n. Vielleicht find'n wir meinen Kontakt dort.", progress = nil, completion = "Erst sind es Schlangen, dann sind es Panther und dann haben wir es mit Trollen zu tun.\n\nBloß gut, dass Ihr hier seid. Wir können jede Hilfe brauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29125] = {title = "Zwischen den Bäumen", objective = "Fangt drei Geister von Malorne, indem Ihr Euch in ihre Nähe bewegt.", description = "Geisterfragmente von Malorne, die uns Sterblichen wie geisterhafte, weiße Hirsche erscheinen, tollen noch immer durch diese Wälder. Auch wenn Malorne nicht mehr unter uns weilt, könnten uns diese Geister von Nutzen sein.\n\nBegebt Euch nach Osten und wandelt unter diesen Bäumen. Wenn es Euch gelingt, nah genug an eines dieser Geisterfragmente heran zu kommen, so wird es seine Macht auf Euch übertragen.\n\nOh, und nehmt diesen Stab. Ihr könntet ihn später vielleicht brauchen.", progress = nil, completion = "&lt;Direkt nachdem Ihr den letzten der Geister von Malorne berührt habt, hört Ihr Matooklas Stimme.&gt;\n\nGut gemacht. Mit den Hörnern von Malorne an unserer Seite haben wir gegen einen der mächtigsten Bewohner der Feuerlande eine Chance: Galenges.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29126] = {title = "Die Macht von Malorne", objective = "Benutzt den Stab des Wächters um Galenges zu beschwören und zu bezwingen.", description = "<Matooklas Stimme fährt fort.>\n\nDas Portal, das sich östlich von uns geöffnet hat, wird von einem mächtigen Flammenschürer namens Galenges bewacht. Wir werden alles an Hilfe brauchen, was Malorne uns geben kann, um ihn zu bezwingen.\n\nErinnert Ihr Euch an den Stab, den ich Euch gegeben habe? Platziert ihn auf dem Aschehaufen vor dem Portal. Und dann betet, dass Malorne Euch zu Hilfe kommt.", progress = nil, completion = "Galenges ist gefallen, das Unzerbrechliche wurde zerbrochen... aber noch ist unsere Arbeit nicht getan.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29127] = {title = "Sturm gegen die Flammen", objective = "Tötet 8 beliebige Eindringlinge aus den Feuerlanden am Geheilten Hyjal oder in Sethrias Nest.", description = "Von all unseren Aufgaben hier am Hyjal ist die dringendste recht einfach: diese Eindringlinge zu vernichten. Es liegt in der Natur des Feuers, dass es alles und jeden verzehrt. Wenn Ihr in Eurer Verteidigung nur einen Moment nachlasst, wird es alles im Sichtbereich zerstören.\n\nVernichtet alle feurigen Eindringlinge, die Ihr findet. Jeder bezwungene Feind erkauft dem Hyjal mehr Zeit.", progress = nil, completion = "Ihr habt Euch gut geschlagen, &lt;Name&gt;. Legt für eine Zeit eine Pause von den Flammen ein.\n\nDer Hyjal wird einen weiteren Tag erleben, und wenn dieser Tag anbricht, brauche ich Euch lebend.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29128] = {title = "Die Verteidiger des Hyjal", objective = "Tötet 6 feurige Ungetüme oder wutentbrannte Pyrolords.", description = "Wir müssen mehr Druck auf den Angriffsstützpunkt in Sethrias Nest machen. Ragnaros' Diener nutzen diesen Bereich als Ausgangspunkt, um ihre Front über die Grenzen von Hyjal hinauszudrücken. Ich übertrage Euch das Kommando über einen kleinen Trupp, um es mit ihnen aufzunehmen.\n\nIch habe einen Elitetrupp von Kämpfern ausgewählt, um Euch zu unterstützen. Reist zu Sethrias Nest. Eure Mitstreiter haben den Befehl, Euch dort bei Eurer Ankunft zu treffen. Setzt den Angriffen der Elementare ein Ende.", progress = nil, completion = "Ihr habt Euren Auftrag gut erledigt, Soldat. Obwohl unsere Mission in den Feuerlanden entscheidend ist, dürfen wir doch nicht das Wohlergehen des Hyjal vergessen.\n\nSprecht morgen erneut mit meinem Bruder und er wird einen weiteren Trupp für Euch bereit haben.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29129] = {title = "Eine legendäre Verabredung", objective = "Sprecht mit Anachronos in den Höhlen der Zeit.", description = "Es ist mir ein Vergnügen, <Klasse>.\n\n<Ziradormi lächelt.>\n\nAus mir unbekannten Gründen wünscht mein Meister eine Audienz mit Euch.\n\nIch rate Euch, diese Einladung nicht auf die leichte Schulter zu nehmen. Anachronos hat nur selten einen Grund, direkten Kontakt mit Sterblichen zu suchen. Es wäre weise, ihn sofort in den Höhlen der Zeit aufzusuchen.\n\nSprecht mit mir, wenn Ihr bereit seid, und ich werde Euch persönlich dorthin bringen.", progress = nil, completion = "Es ist keine launische Willkürlichkeit, die Euch hierhergeführt hat, Sterblicher.\n\nIhr müsst jedes letzte bisschen Mut für das aufbringen, was Ihr gleich sehen werdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29131] = {title = "Verteidigt das Rebellenlager", objective = "Helft mit, das Rebellenlager drei Minuten lang zu verteidigen.", description = "Wir sind hier in Schwierigkeiten, <Name>. Euer Trollfreund ist hier durchgekommen und hat uns gewarnt, dass es bald ernst werden würde, aber ich habe nicht mit so etwas gerechnet.\n\nWir werden unser Bestes geben, um diese Trolle fernzuhalten, aber jede Hilfe, die Ihr anbieten könnt, wäre sehr willkommen.", progress = nil, completion = "Danke, dass Ihr uns eine Verschnaufpause verschafft habt.\n\nWie ich schon sagte, war Euer Freund für kurze Zeit hier. Er hat uns gewarnt, dann ist er wieder aufgebrochen.\n\nJakob Windstill hat ihm geholfen, zu seinem nächsten Bestimmungsort zu kommen, vielleicht kann er Euch helfen.\n\nViel Glück, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29132] = {title = "Eine legendäre Verabredung", objective = "Sprecht mit Anachronos in den Höhlen der Zeit.", description = "Ich habe mir schon gedacht, dass ich Euch hier treffen würde, <Klasse>. Allerdings sind wir vom bronzenen Drachenschwarm da auch ein wenig im Vorteil, wenn es um solche Dinge geht.\n\n<Coridormi lächelt.>\n\nAus mir unbekannten Gründen wünscht mein Meister eine Audienz mit Euch.\n\nIch rate Euch, diese Einladung nicht auf die leichte Schulter zu nehmen. Anachronos hat nur selten einen Grund, direkten Kontakt mit Sterblichen zu suchen. Es wäre weise, ihn sofort in den Höhlen der Zeit aufzusuchen.\n\nSprecht mit mir, wenn Ihr bereit seid, und ich werde Euch persönlich dorthin bringen.", progress = nil, completion = "Es ist keine launische Willkürlichkeit, die Euch hierhergeführt hat, Sterblicher.\n\nIhr müsst jedes letzte bisschen Mut für das aufbringen, was Ihr gleich sehen werdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29133] = {title = "Zur Grabungsstätte", objective = "Begebt Euch zur Grabungsstätte der Forscherliga am Schlingendornkap.", description = "Der andere Abgesandte der Dunkelspeere war kurz hier. Er wollte dringend zum nächsten Ort, um die Leute dort zu warnen. Ich habe ihn auf einen Greifen zur Grabungsstätte der Forscherliga am Schlingendornkap gesetzt. Ich hoffe, er war nicht zu spät.\n\nIch gebe Euch einen meiner Greifen für einen Direktflug dorthin. Sprecht mit mir, wenn Ihr bereit seid, <Name>.", progress = nil, completion = "Das sieht nich' gut aus, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29134] = {title = "Eine Furche in der Zeit", objective = "Sprecht mit Anachronos in den Höhlen der Zeit, um <Zeuge/Zeugin> der Zukunft Azeroths zu werden.", description = "Hört gut zu, <Klasse>, denn obwohl wir erst am Anfang stehen, wird die Zeit bereits knapp und die Folgen unseres Scheiterns sind unvorstellbar.\n\nEin Ereignis in der jüngsten Vergangenheit wurde durch mächtige Magie vor mir verschleiert.\n\nSeine Auswirkungen jedoch nicht.\n\nWenn nichts unternommen wird, um den Ablauf dieser Zeitlinie zu ändern, ist das Resultat klar.\n\nHaltet an Euch, <Sterblicher/Sterbliche>, und seht die Zukunft Azeroths.", progress = "Werdet Zeuge des Untergangs unserer Welt, <Klasse>.", completion = "Jetzt, Sterblicher, kennt Ihr den Grund hinter meiner Einladung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29135] = {title = "Ein allsehendes Auge", objective = "Sammelt 25 Stück Immerglut aus den Feuerlanden sowie 3 Handvoll Sande der Zeit.", description = "Ich kann die Fragen sehen, die Eure Gedanken in Aufruhr versetzen und ich muss gestehen, dass auch ich mir nicht sicher bin... eine ungewöhnliche Situation für jemanden wie mich und eine sehr beunruhigende.\n\nWährend ich die Zeit durchforste, um Spuren dieses verhüllten Ereignisses zu finden, müsst Ihr mir bei der Erschaffung eines Auges helfen. Dadurch werdet Ihr Eure Würdigkeit beweisen und ein wesentliches Werkzeug zur Entschlüsselung dieses Rätsels beschaffen.\n\nReist in die Elementarebene des Feuers, <Klasse>, und sammelt Immerglut. Bringt mir diese sowie die Sande der Zeit und ich werde das Auge herstellen.", progress = "Nun, <Klasse>?\n\nHabt Ihr die notwendigen Materialien sammeln können?", completion = "Ihr habt Eure Sache gut gemacht.\n\nVerhaltet Euch ruhig, während ich uralte Magie wirke, um das zeitlose Auge herzustellen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nTimeless Orb Creation Effect\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29137] = {title = "Lücke in der Verteidigung", objective = "Tötet 5 Lavabohrer.", description = "Lavawürmer brechen durch den Boden hinter unseren Reihen. Sie durchbrechen unsere Formationen und erlauben es Elementaren, hindurchzuschlüpfen. Ihr werdet sie über unsere gesamte Front im Norden und auf den Aschenfeldern weiter draußen finden.\n\nTrampelt sie zurück in ihre Löcher.", progress = nil, completion = "Wir sind dankbar für Eure Unterstützung. Eure Anwesenheit auf dem Schlachtfeld gibt uns genügend Zeit, uns neu zu sammeln. Eure Mühen sind das Zünglein an der Waage.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29138] = {title = "Brandopfer", objective = "Heilt 8 verwundete Verteidiger des Hyjal.", description = "Wir haben Krieger draußen im Feld, die verwundet zu Boden gehen, und viele unserer Druiden sind zu beschäftigt mit dem Kampf, um ihnen die nötige Hilfe zukommen zu lassen. Ich möchte, dass Ihr nach Norden geht, in Richtung der Aschenfelder, und Euch zumindest so weit um ihre Wunden kümmert, dass sie sich in Sicherheit bringen können.\n\nSolltet Ihr über keine Verbände oder heilende Zauber verfügen, so nehmt diese Salbe, die ich Rayne habe herstellen lassen. Sie sollte ausreichen, damit sie wieder auf die Beine kommen.", progress = "Zu unserem Glück verwunden Ragnaros' Streitkräfte unsere Krieger sehr viel häufiger, als dass sie sie direkt töten. Ihre Angriffe brennen die Wunden, die sie zufügen, auf natürliche Art und Weise aus. Das ist sehr schmerzhaft, aber es ist besser als zu sterben.", completion = "Ich habe mehrere unserer Krieger gesehen, wie sie kurz nach Eurem Aufbruch in Sicherheit gelangt sind. Eure Anstrengungen scheinen überaus effektiv gewesen zu sein. Danke.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29139] = {title = "Aggressives Wachstum", objective = "Pflanzt 5 Stickrankensamen in den Aschehaufen in den Aschenfeldern.", description = "Unsere Krieger tun, was sie können, um diese Elementare zurückzuhalten, aber ihre Reihen sind endlos. Wir müssen etwas tun, um den Angriff zu verlangsamen.\n\nFindet passende Flecken von Erde oder Asche draußen in den Aschenfeldern im Norden von uns und pflanzt diese Samen. Aus ihnen werden tödliche Ranken erwachsen, die unsere Feinde vielleicht ein wenig verlangsamen. Das mag nicht viel sein, aber jede Kleinigkeit hilft.", progress = nil, completion = "Wir werden diese Schlacht gewinnen. Egal, was es uns abverlangt, wir werden diese Elementare nicht wieder auf den Hyjal lassen.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29140] = {title = "ns Feuer", objective = "[DEPRECATED]This is the wrong choice. Accept the quest, \"The Warden's Charge.\" Those quests are more fleshed out.", description = "[DEPRECATED]This is the wrong choice. Accept the quest, \"The Warden's Charge.\" Those quests are more fleshed out.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][29141] = {title = "Fallhöhe", objective = "Tötet 3 geschmolzene Ungetüme.", description = "Geschmolzene Ungetüme haben sich den Elementaren auf dem Schlachtfeld angeschlossen. Sie zermalmen unsere Frontlinien. Ich brauche Euch, um ihrer Wucht Einhalt zu gebieten.\n\nIhr werdet sehen, die Bestien sind zwar langsam und ungeschickt und sie lassen sich leicht ausmanövrieren, aber wenn sie Euch treffen, dann mit zerstörerischer Kraft. Bleibt in Bewegung, <Klasse>.", progress = nil, completion = "Die Elementare werden lernen, Euch zu fürchten.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29142] = {title = "Rückkehr der Verräter", objective = "Tötet 3 Druiden der Flamme.", description = "Die Druiden der Flamme greifen unsere Frontlinie an, <Name>.\n\nDiese üblen Kreaturen haben Elunes Lehren den Rücken zugewandt und verehren stattdessen den Feuerfürsten Ragnaros. Von seiner wahnsinnigen Macht verdorben, ersehnen sie nichts so sehr, wie uns in Asche zu begraben.\n\nWir müssen ihrem Angriff sofort etwas entgegensetzen!", progress = nil, completion = "Gut. Unsere Feinde wissen jetzt, dass sie unsere Stärke fürchten sollten.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29143] = {title = "Irrwische los", objective = "Führt einen Irrwisch des Hyjal zu einem der Feuerportale in den Aschenfeldern und beschützt den Irrwisch, bis er das Portal geschlossen hat. Solltet Ihr Euren Irrwisch verlieren, so solltet Ihr zu Rayne Federsang bei Malfurions Bresche zurückkehren.", description = "Die Feuerelementare ergießen sich aus den Portalen jenseits der Aschenfelder. Wir brauchen jemanden, der sie schließt und ihnen die Verstärkung abschneidet.\n\nFür das Bannen dieser Art von elementarer Magie sind unsere Irrwische perfekt geeignet. Einer von ihnen wird Euch begleiten. Führt ihn zu einem Portal und haltet ihn am Leben, bis er seine Aufgabe beendet hat.", progress = nil, completion = "Gut gemacht, &lt;Klasse&gt;. Ich werde Eure Fähigkeiten in Zukunft noch öfter einsetzen müssen.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29144] = {title = "Aufräumen in Sturmwind", objective = "Benutzt den Arkanreiniger, um die Stinkbomben rund um Sturmwind zu entfernen.", description = "Grüße, <Klasse>! Genießt Ihr die Schlotternächte? Offenbar hat sich die Horde nach unserem Stinkbombenabwurf auf Unterstadt dazu entschlossen, unsere Stadt auch zu bombardieren. Die Stinkbomben, die sie benutzen, sind stärker als die, die sie letztes Jahr verwendet haben. Die Kraft der Pinie wird nicht genug sein. Wir brauchen etwas mit mehr Wumms. Benutzt dieses arkane Reinigungsmittel, um die Stinkbomben aus der Stadt zu beseitigen.", progress = nil, completion = "Ah, viel besser, &lt;Name&gt;. Diese alten Weiber in Unterstadt haben keine Vorstellung davon, wie mächtig wir inzwischen sind. Und jetzt, nehme ich an, hättet Ihr gerne eine Belohnung.", rewards = "Ihr bekommt:\n\nSüßes Saures"}
MultiLanguageQuestData['de'][29145] = {title = "Das Öffnen der Tür", objective = "Meldet Euch bei dem Erzdruiden Hamuul Runentotem am Nordunegrat auf dem Hyjal.", description = "Ihr kommt ein wenig spät. Hamuul, Malfurion und einige unserer geschätzten Gäste sind bereits zum Invasionspunkt, oben auf der Klippe, gereist.\n\nUnser Tor zu den Feuerlanden ist noch nicht fertig, aber es wird es in Kürze sein. Je eher wir durchbrechen können, umso besser.\n\nGeht! Hamuul wird Euch schon erwarten.", progress = nil, completion = "&lt;Name&gt;. Es ist gut, Euch wiederzusehen. Unser Tor ist fast offen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29146] = {title = "Ein Ritt auf der Raketenbahn", objective = "Reist zur Südlichen Endhaltestelle der Raketenbahn in Azshara und steigt in den Windhund-Zweisitzer-Prototyp an der Spitze des Turms.", description = "Ich habe gehört, dass die neusten Mitglieder der Horde, die Goblins, eine verrückte Straße nur für Raketen in Azshara gebaut haben! Könnt Ihr Euch das vorstellen? Seit ich davon gehört habe, will ich mal dorthin. Ich habe Matrone Schlachterbe danach gefragt, und sie sagt, man nennt es die Raketenbahn!\n\nSie hat mir sogar erzählt, dass sie an einem Zweisitzer-Prototyp arbeiten. Wollen wir dort mal hinreisen und nachsehen, ob wir ihn ausprobieren können? Ich wette, die experimentelle Rakete ist in der Nähe vom Geheimlabor am südlichen Ende der Raketenbahn...", progress = "Das wird die beste Kinderwoche aller Zeiten!", completion = "Das war toll! Ich habe sogar gelernt, wie man die Rakete steuert und so! Habt Ihr gesehen, wie ich uns gerettet habe? Wenn ich groß bin, werde ich ein Raketenpilot!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29147] = {title = "Schwarmruf", objective = "Benutzt Eure Fähigkeit 'Schwarmruf' um 12 Gebirgssingvögel, 5 Waldeulen und 2 Goldschwingenfalken einzusammeln.", description = "Heute haben wir die Gelegenheit, einen weiteren Angriff gegen einen von Ragnaros' mächtigeren Dienern zu führen: Millagazor. Allerdings müssen wir uns zunächst Unterstützung besorgen.\n\n<Matookla hält eine große, seidene Feder hoch.>\n\nBenutzt dieses Artefakt, um die Macht von Aviana zu beschwören. Habt Ihr das getan, so reist gen Nordwesten und versammelt einige der ihren, indem Ihr ihnen zuruft.\n\nSobald Ihr das getan habt, werden wir gegen Millagazor ziehen können.", progress = nil, completion = "&lt;Zwischen dem Gezwitscher, Eulengeheul und hektischen Krächzen Eurer Vogelkollegen hört Ihr aus der Ferne die Stimme von Matookla zu Euch sprechen.&gt;\n\nGut gemacht, &lt;Volk&gt;. Nun da der Schwarm versammelt ist, schlagen wir zu.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29148] = {title = "Flammende Schwingen", objective = "Benutzt den Federkiel der Vogelkönigin um Millagazor zu beschwören und zu besiegen.", description = "<Matooklas Stimme schallt weiter durch Euren Kopf.>\n\nMillagazor ist eine Kreatur der Flamme, aber, auf vielerlei Art, ist er den Vögeln dieses Landes gar nicht so unähnlich. Deshalb könnte Avianas Artefakt immer noch über die Macht verfügen, ihn herbeizurufen.\n\nIhr werdet ihn beim feurigen Portal im Westen finden. Benutzt den Federkiel in der Nähe des Portaleingangs und macht Euch auf einen erbitterten Kampf gefasst.", progress = nil, completion = "Gut gemacht, Champion.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29149] = {title = "Sturm gegen die Flammen", objective = "Tötet 7 beliebige Eindringlinge aus den Feuerlanden am Geheilten Hyjal oder in Sethrias Nest.", description = "Von all unseren Aufgaben hier am Hyjal ist die dringendste recht einfach: diese Eindringlinge zu vernichten. Es liegt in der Natur des Feuers, dass es alles und jeden verzehrt. Wenn Ihr in Eurer Verteidigung nur einen Moment nachlasst, wird es alles im Sichtbereich zerstören.\n\nVernichtet alle feurigen Eindringlinge, die Ihr findet. Jeder bezwungene Feind erkauft dem Hyjal mehr Zeit.", progress = nil, completion = "Ihr habt Euch gut geschlagen, &lt;Name&gt;. Legt für eine Zeit eine Pause von den Flammen ein.\n\nDer Hyjal wird einen weiteren Tag erleben, und wenn dieser Tag anbricht, brauche ich Euch lebend.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29150] = {title = "Voodoozombies", objective = "Rettet 10 Überlebende der Grabungsstätte.", description = "Die Leute... alles Zombies, Voodoozombies! Das wird nich' schön, <Name>.\n\nDu musst die alle töt'n.\n\nAber sobald sie erledigt sind, gibt es einen Weg, wie ich sie zurückhol'n kann. Wieder in die Personen verwandeln, die sie war'n.\n\nWir müss'n schnell handeln, die Zombies schlafen nich'.", progress = nil, completion = "Wir hab'n getan, was wir konnt'n, &lt;Name&gt;. Wir können diese Zombies nich' länger bekämpf'n. Wir müss'n die Wurzel dieses Voodoos ausfindig mach'n. Und ich glaub', ich weiß, wo wir anfang'n.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29151] = {title = "Verdorbene Vorräte", objective = "Überprüft die Nahrungsvorräte bei der Grabungsstätte der Forscherliga.", description = "Einige der Überlebenden hab'n Nahrungsmittel erwähnt, <Name>. Wir sollt'n ihre Vorräte überprüf'n. Ich hab ein schlechtes Gefühl bei der Sache.", progress = nil, completion = "Zanzil... Es fängt alles an, Sinn zu ergeb'n. Wenn ich meinen Kontakt find'n kann, können wir einen Angriffsplan entwickeln.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29152] = {title = "Kontaktaufnahme", objective = "Begebt Euch nach Beutebucht und findet Bwembas Kontaktperson.", description = "Ihr seid keiner von den Zombies...\n\nEin Troll? Ich habe einen gesehen, direkt vor dem Ausbruch... Er hat uns gewarnt, gesagt, dass wir vorsichtig sein sollen... Aber es war zu spät.\n\nEuer Trollfreund ist nach Beutebucht gegangen, um sie zu warnen...", progress = nil, completion = "Ich werde Baron Revilgaz jetzt von der Zandalaribedrohung erzählen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\n4.1 - ZG Event - Booty Bay - Warning Booty Bay Quest Complete [DND]\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29153] = {title = "Die Interessen Beutebuchts", objective = "Spürt ein Artefakt auf, das die Trolle aus Zul'Gurub von Beutebucht fern halten könnte.", description = "Also, <Name>. Ihr habt uns schon gewaltig geholfen, aber das wird noch nicht reichen. Diese verrückten Trolle müssen aufgehalten oder zumindest von Beutebucht ferngehalten werden.\n\nIch werde jemanden losschicken, der das Geschehen im Auge behält, aber von Euch möchte ich, dass Ihr in Zul'Gurub eindringt und die Dinge in Bewegung setzt.\n\nIhr müsst mir zumindest etwas bringen, das diese Trolle aus Beutebucht fernhält.\n\nBringt das zustande und wir werden uns erkenntlich zeigen.", progress = "Habt Ihr etwas gefunden, <Name>?", completion = "Ihr habt sie alle getötet? Ich wünschte, das wäre genug, um mir keine Sorgen mehr zu machen. Aber diese Typen scheinen die Angewohnheit zu haben, von den Toten zurückzukehren.\n\nAh, was habt Ihr denn da?\n\nIhr meint, das könnte sie aus Beutebucht fernhalten?\n\nSo kommen wir ins Geschäft!\n\nOh, sagte ich, dass ich eine Belohnung für Euch habe? Natürlich... gebt mir nur einen Moment, um die Belohnung zu finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29154] = {title = "Die Interessen Beutebuchts", objective = "Spürt ein Artefakt auf, das die Trolle aus Zul'Gurub von Beutebucht fern halten könnte.", description = "Ich wurde von Baron Revilgaz aus Beutebucht hergeschickt, damit ich sicherstelle, dass diese Trollbedrohung aufgehalten wird. Oder dass sie zumindest vor den Toren von Beutebucht aufgehalten wird.\n\nIch will Taten und Ergebnisse sehen.\n\nIhr geht da jetzt für mich rein und veranstaltet ein Gemetzel.\n\nIhr geht da jetzt rein und sucht mir etwas, das diese Trolle aus Beutebucht fernhält.\n\nBringt das zustande und wir werden uns erkenntlich zeigen.", progress = "Habt Ihr etwas gefunden, <Name>?", completion = "Ihr habt sie alle getötet? Ich wünschte, das wäre genug, um mir keine Sorgen mehr zu machen. Aber diese Typen scheinen die Angewohnheit zu haben, von den Toten zurückzukehren.\n\nAh, was habt Ihr denn da?\n\nIhr meint, das könnte sie aus Beutebucht fernhalten?\n\nSo kommen wir ins Geschäft!\n\nOh, sagte ich, dass ich eine Belohnung für Euch habe? Natürlich... gebt mir nur einen Moment, um die Belohnung zu finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29155] = {title = "Eine glitzernde Beute", objective = "Holt Euch Eure Belohnung aus einer Kiste in der Statue auf der Janeirospitze.", description = "Es gibt etwas Plündergut innerhalb der Statue auf der Janeirospitze, gleich nordwestlich von Beutebucht im Schlingendorntal.\n\nBegebt Euch zur Statue und nehmt Euren Preis an Euch, <Klasse>.", progress = nil, completion = "Endlich Beute!", rewards = "Ihr bekommt:\n\nSchwarzes EisGoldene HalsketteStumpfe KroneEdelsteinbesetzte Armreife"}
MultiLanguageQuestData['de'][29156] = {title = "Trollinvasion", objective = "Sprecht mit Kommandant Spitz im Hafen von Sturmwind.", description = "Eine Gruppe von Trollen, die behaupten, für die Dunkelspeere zu sprechen, sind im Hafen von Sturmwind angekommen. Unsere Wachen halten sie fürs Erste zurück.\n\nDie Hafenwachen von Sturmwind suchen nach kampferprobten Abenteurern, die dabei helfen, diese Trolle zu entfernen. Meldet Euch bei Kommandant Spitz im Hafen von Sturmwind.", progress = nil, completion = "Ah gut, ein &lt;Klasse&gt;. Vielleicht habt Ihr ja mehr Erfolg mit diesen Trollen.\n\nFindet heraus, was sie wollen, und seht dann zu, dass Ihr sie loswerdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29157] = {title = "Die Zandalari-Bedrohung", objective = "Sprecht mit Bwemba in Orgrimmars Tal der Geister.", description = "Die Zandalaritrolle sind im Schlingendorntal auf dem Vormarsch!\n\nWenn Ihr den Dunkelspeeren helfen wollt, meldet Euch bei Bwemba in Orgrimmars Tal der Geister.", progress = nil, completion = "Grüße, &lt;Volk&gt;. Wir leb'n in verzweifelten Zeiten. Die Zandalaritrolle sind dabei, ihre Ländereien zurückzuerobern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29158] = {title = "Der Abgesandte der Zandalari", objective = "Trefft Euch mit Bwemba im Hafen von Sturmwind.<Klasse>! Hört meinen Ruf. Das Schlingendorntal benötigt Eure Hilfe! Kommt zu mir am Hafen.", description = "<Klasse>! Hört meinen Ruf. Das Schlingendorntal benötigt Eure Hilfe! Kommt zu mir am Hafen.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][29159] = {title = "Pyrorachnophobie", objective = "Tötet 8 Aschenweberspinner oder -krabbler.", description = "Wir haben hart darum gekämpft, diese Gegend zu sichern, aber unser Stand hier ist unsicher.\n\nUnsere Späher haben berichtet, dass es in der Gegend um uns herum vor bösartigen Feuerspinnen nur so wimmelt. Sie sind die Nachkommen der üblen Brutwitwe Beth'tilac.\n\nHelft uns, unsere Stellung zu halten, indem Ihr die Gegend von Aschenweberspinnern oder -krabblern befreit. Es wird sie wahnsinnig machen, ihre Kinder erschlagen zu sehen.", progress = nil, completion = "Wundervoll! Je mehr Spinnen wir loswerden, desto einfacher wird es sein, voranzukommen.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29160] = {title = "Ver-ei-teln", objective = "Sammelt 20 Aschenweber-Eier von den Säulen im Gelege der Witwe.", description = "Wir haben hier ein echtes Problem an den Händen. Die Spinnen in der Nähe sind nicht nur bösartig und räuberisch, es scheint von ihnen auch endlos viele zu geben.\n\nWir müssen das Wachstum ihrer Armee aufhalten. Wir müssen ihnen die Köpfe schon in den Eiern abschlagen, nicht erst auf dem Schlachtfeld.\n\nDie Eier der Aschenweberspinner liegen zwischen den Steinsäulen im Norden. Sammelt 20 Eier ein und bringt sie mir.", progress = "Es scheint, als seien die Aschenweberspinner die Wärter von Beth'tilacs Brut.", completion = "Phantastische Arbeit, &lt;Klasse&gt;. Wollen wir hoffen, dass diese kleinen Spinnenbisse nicht ansteckend sind.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29161] = {title = "Die Bären da in den Bäumen", objective = "Erklettert die Bäume im Rauschenden Hain, schnappt Euch gestrandete Hyjalbärenjunge und werft sie dann von den Baumwipfeln aus zum weichen Ziel. Das Ganze ist absolut sicher.", description = "Oh, Himbeeren! Wir hatten gerade das letzte Bärenjunge aus den Baumwipfeln gerettet, da kam das Feuer zurück und hat sie wieder verschreckt!\n\nIch weiß nicht, ob Ihr es schon wusstet, aber Babybären sind kostbar und weich.\n\nGeht zum Rauschenden Hain, weit im Nordwesten. Klettert auf die Bäume, schnappt Euch die Bärenjungen und werft sie - vorsichtig! - zu dem weichen Ziel in der Mitte des Hains.\n\n<Ohne Vorwarnung reißt Mylune Euch plötzlich an ihre Brust und beginnt zu schluchzen.>\n\nKleine B-b-b-b-Bärenbabies! Rettet sie, <Name>!", progress = nil, completion = "&lt;Mylunes Gedanken schallen durch Euren Geist, zusammen mit ungebetenen Bildern von Blumen und Eichhörnchen.&gt;\n\nOh, Ihr habt es geschafft, &lt;Name&gt;! Die Babybären sind so glücklich.\n\nSo langsam habe ich das Gefühl, dass sie absichtlich damit angefangen haben.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29162] = {title = "Segen der Natur", objective = "Benutzt den Smaragd von Aessina, um Pyrachnis zu beschwören und zu töten.", description = "<Mylunes Stimme erklingt in Eurem Kopf wie das Geräusch von zwitschernden Vögeln.>\n\nIch liebe alle Wesen des Waldes, sogar Spinnen, obwohl sie eklig sind. Aber die Spinnen aus den Feuerlanden, die sind schlimmer als bloß eklig. Die brennen und sie gehören nicht hierher.\n\nFindet das Feuerportal im westlichen Teil des Geheilten Hyjal und benutzt den Edelstein, den ich Euch zuvor gegeben habe, um es zu öffnen. Wenn eine Feuerspinne rauskommt, dann tretet auf sie drauf! Es sei denn natürlich, sie ist groß. Dann macht irgendwas, was Ihr als <Klasse> halt so macht.\n\nOh, und benutzt den Edelstein, wenn Ihr Euch durch das Spinnengift benommen fühlen solltet.", progress = nil, completion = "Oh, NEIN, Ihr seid ja über und über mit SPINNEN-BUÄRKS bedeckt!\n\n&lt;Mylune bedeckt ihre Augen, um Euch nicht anblicken zu müssen.&gt;\n\nIhr seid so tapfer, &lt;Volk&gt;. Ich hoffe, Ihr geht schon bald in die Feuerlande und tretet auf ALLE Spinnen.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29163] = {title = "Sturm gegen die Flammen", objective = "Tötet 9 beliebige Eindringlinge aus den Feuerlanden am Geheilten Hyjal oder in Sethrias Nest.", description = "Von all unseren Aufgaben hier am Hyjal ist die dringendste recht einfach: diese Eindringlinge zu vernichten. Es liegt in der Natur des Feuers, dass es alles und jeden verzehrt. Wenn Ihr in Eurer Verteidigung nur einen Moment nachlasst, wird es alles im Sichtbereich zerstören.\n\nVernichtet alle feurigen Eindringlinge, die Ihr findet. Jeder bezwungene Feind erkauft dem Hyjal mehr Zeit.", progress = nil, completion = "Ihr habt Euch gut geschlagen, &lt;Name&gt;. Legt für eine Zeit eine Pause von den Flammen ein.\n\nDer Hyjal wird einen weiteren Tag erleben, und wenn dieser Tag anbricht, brauche ich Euch lebend.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29164] = {title = "Gut heulen will geübt sein", objective = "Benutzt den Fangzahn des Wolfs über den Leichnamen von 10 Eindringlingen der Feuerlande innerhalb des Geheilten Hyjal.", description = "Dem uralten Wolf, Lo'Gosh - oder, wenn Ihr es vorzieht, Goldrinn - stehen viele Waffen zur Verfügung, doch die am meisten unterschätzte ist wohl sein Geheul. Heute werden wir diese Waffe einsetzen, um Lylagar zu beschwören und zu töten, einen der Leutnants der Flamme, der in den Feuerlanden lauert.\n\nBezwingt jedwede Kreatur des Geheilten Hyjal und benutzt dann den Fangzahn des Wolfs während Ihr über ihren Leichnamen steht. Schon bald wird Euer Geheul über ganz Kalimdor erklingen.", progress = nil, completion = "&lt;Matooklas vertraute Stimme dringt in Euer Bewusstsein.&gt;\n\nJa, Ihr seid bereit. Nun werden wir den Schlag gegen Lylagar führen.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29165] = {title = "Der Ruf des Rudels", objective = "Benutzt den Fangzahn des Wolfs, um Lylagar zu beschwören und besiegt ihn.", description = "<Matookla fährt fort:>\n\nDas östlichste Flammenportal ist das Reich von Lylagar. Stellt Euch vor das Portal und stoßt ein herausforderndes Geheul aus. Zwingt dann die Bestie dazu, sich zu ergeben.", progress = nil, completion = "Ich habe die Echos Eurer triumphierenden Schreie über die Bergfelsen hinweg gehört.\n\nIch habe auch gehört wie Lylagar eine... andere Art von Schrei von sich gegeben hat.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29166] = {title = "Nachschub für die andere Seite", objective = "Sammelt 7 Blauknollenwinden.", description = "Eine der größten Gefahren, denen sich unsere Druiden innerhalb der Feuerlande stellen müssen, ist profanes Austrocknen. Unsere Proviantmeister verbringen sehr viel Zeit damit, die Feldflaschen für die Truppen auf der anderen Seite herzurichten. Wir haben allerdings andere Methoden.\n\nIm grüneren Dickicht im Osten solltet Ihr noch immer einige Blauknollenwinden finden, die noch nicht verbrannt wurden. Diese Pflanzen haben einen enormen Wasseranteil in ihren Wurzeln - und bieten dem müden Soldaten einiges an Energie.", progress = "Dann wollen wir mal sehen... wie viele habt Ihr denn bisher sammeln können?", completion = "Ich werde diese hier sofort verpacken und verschicken lassen.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29167] = {title = "Die Bansheekönigin", objective = "Bringt Euer Waisenkind ins Königsviertel von Unterstadt und besucht Fürstin Sylvanas Windläufer. Wenn Euer Waisenkind nicht bei Euch ist, wenn Ihr ankommt, solltet Ihr es herbeirufen.", description = "Fürstin Sylvanas, die Anführerin der Verlassenen, soll eine der besten Kämpferinnen der Horde sein, vielleicht sogar so gut wie der Kriegshäuptling selbst!\n\nIch wollte sie schon immer mal treffen, <Name>. Vielleicht kann ja <ein Abenteurer/eine Abenteuerin> wie Ihr eine Audienz mit ihr bekommen! Würdet Ihr mich zum Königsviertel von Unterstadt bringen, damit ich Fürstin Sylvanas treffen kann? Das ist ganz schön weit weg und die Wachen würden mich nie allein reinlassen!", progress = nil, completion = "Sie ist genauso grimmig, wie ich sie mir vorgestellt hatte! Aber dieser Botschafter ist ganz schön wütend geworden, als ich mit Fürstin Sylvanas gesprochen habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29169] = {title = "Die Tiere im Inneren", objective = "Tötet die Blütenflügelschwarmkönigin, Tor-Tun den Schläfer sowie einen von Gahz'rankas verlorenem Nachwuchs in Zul'Gurub.", description = "<Maywiki ist unruhig.>\n\nNach dem Fall Hakkars ist die Stadt der Gurubashi immer mehr verfallen und der Dschungel hat Zul'Gurub Stück für Stück zurückerobert. In den Schlupfwinkeln der alten Stadt leben jetzt einige mächtige Tiere.\n\nWir haben gesehen, welche Mächte die Gurubashipriester befehligen - mit ihren giftigen Gebräuen bringen sie sogar die Flora gegen uns auf. Bitte Ihr Helden, beseitigt diese Tiere bevor Jin'do und seine Handlanger sie zu ihren willenlosen Dienern machen!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29170] = {title = "Wo sind wir hier?", objective = "Tötet Corla, Botin des Zwielichts.", description = "<Finkles Helm versetzt Euch einen kleinen Schlag.>\n\nWas ist das für ein Ort? Es sieht so aus, als ob sie mit diesem Nethergroßdrachen etwas Schreckliches anstellen. Die Energie wird von dem Geschöpf auf die Frau übertragen! Wir müssen dieses Ritual unterbrechen!\n\nTötet Corla, um die Halle durchqueren zu können!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29171] = {title = "Wo sind wir hier?", objective = "Tötet Corla, Botin des Zwielichts.", description = "<Finkles Helm versetzt Euch einen kleinen Schlag.>\n\nWas ist das für ein Ort? Es sieht so aus, als ob sie mit diesem Nethergroßdrachen etwas Schreckliches anstellen. Die Energie wird von dem Geschöpf auf die Frau übertragen! Wir müssen dieses Ritual unterbrechen!\n\nTötet Corla, um die Halle durchqueren zu können!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29172] = {title = "Die Tiere im Inneren", objective = "Tötet die Blütenflügelschwarmkönigin, Tor-Tun den Schläfer sowie einen von Gahz'rankas verlorenem Nachwuchs in Zul'Gurub auf heroischem Schwierigkeitsgrad.", description = "<Blutschlächterin T'ara beäugt Euch einen Moment lang.>\n\nNach dem Fall Hakkars is' die Stadt der Gurubashi immer mehr verfall'n und der Dschungel hat Zul'Gurub Stück für Stück zurückerobert. In den Schlupfwinkeln der alten Stadt leb'n jetzt einige mächtige Tiere.\n\nWir hab'n geseh'n, welche Mächte die Gurubashipriester befehlig'n - mit ihren giftigen Gebräuen bring'n sie sogar die Flora gegen uns auf. Du hältst dich für stark? Dann beseitige diese Tiere, bevor Jin'do und seine Handlanger sie zu ihren willenlosen Dienern mach'n!", progress = nil, completion = "&lt;T'aras Hauer bewegen sich ein wenig. Ist das ein Lächeln?&gt;\n\nGut gemacht.\n\nWir werd'n heute Nacht ruhig schlaf'n in dem Wissen, dass Jin'do und Zanzil diese mächtigen Tiere nich' dem Willen der Gurubashi unterwerf'n können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29173] = {title = "Sekundärziele", objective = "Tötet Kaulema den Beweger, Mor'Lek den Zerleger und Mortaxx, das Schlagen der Stunde in Zul'Gurub auf heroischem Schwierigkeitsgrad.", description = "Die Gurubashitrolle hab'n ihre mächtigsten Verbündeten zusammengeruf'n, um Zul'Gurub wiederaufzubau'n und das Schlingendorntal zurückzuerobern.\n\nDie mächtigsten unter diesen Verbündeten sind zwei monströse Trolle, Kaulema der Beweger und Mor'Lek der Zerleger, sowie ein gefährlicher Seelendieb namens Mortaxx.\n\nSie sind zwar nich' die Befehlshaber in Zul'Gurub, aber diese mächtigen Diener zu besieg'n wird dafür sorg'n, dass die Gurubashi so schnell nich' an die Macht komm'n.", progress = nil, completion = "Jin'dos Reich bricht um ihn herum in sich zusammen, wie die Ruinen dieser verlassenen Stadt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29174] = {title = "Brecht ihren Willen", objective = "Tötet Gub und den Meisterkoch der Gurubashi in Zul'Gurub.", description = "Eine Stadt wie Zul'Gurub ähnelt den mächtigen Bäumen, die Ihr hier in der Umgebung sehen könnt.\n\nDer Stamm mag dick und das Laubdach dicht und üppig sein, aber ohne Nährstoffe aus den Wurzeln muss der Baum welken und umstürzen.\n\nJin'dos Armee wird hauptsächlich durch die Handlungen von zwei niederen Gurubashitrollen versorgt. Wenn Ihr diese Wurzeln durchtrennt, wird die Stadt umso schneller fallen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29175] = {title = "Brecht ihren Willen", objective = "Tötet Gub und den Meisterkoch der Gurubashi in Zul'Gurub auf heroischem Schwierigkeitsgrad.", description = "Eine Stadt wie Zul'Gurub ähnelt den mächtigen Bäumen, die du hier in der Umgebung seh'n kannst.\n\nDer Stamm mag dick und das Laubdach dicht und üppig sein, aber ohne Nährstoffe aus den Wurzeln muss der Baum welk'n und umstürz'n.\n\nJin'dos Armee wird hauptsächlich durch die Handlungen von einer Handvoll niederer Gurubashitrolle versorgt. Wenn du diese Wurzeln durchtrennst, wird die Stadt umso schneller fall'n.", progress = nil, completion = "Das große Reich der Gurubashi fängt bereits an, zu vergeh'n.\n\nJetzt is' es nur noch eine Frage der Zeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29176] = {title = "Der gefallene Häuptling", objective = "Besucht die Teufelsfelsen mit Eurem Waisenkind, um Cairne Bluthufs Scheiterhaufen zu sehen. Wenn Euer Waisenkind nicht bei Euch ist, wenn Ihr ankommt, solltet Ihr es herbeirufen.", description = "Matrone Schlachterbe sagt, dass die Horde eine 'Stimme der Weisheit' mit Cairne Bluthufs Tod verloren hat. Ich weiß nicht, was das heißt, aber ich wollte ihn schon immer mal treffen. Einige der anderen Waisenkinder haben sogar seinen Hufabdruck.\n\nNehmt Ihr mich nach Mulgore mit? Unser Lehrer sagt, die Tauren bringen ihre Toten zu einem Ort, den sie die Teufelsfelsen nennen, und dort verehren sie sie. Lasst uns dorthin gehen und sehen, ob wir Cairne finden.", progress = "Ich möchte öfter Mulgore besuchen.", completion = "Eines Tages werde ich auch so toll kämpfen können wie Cairne oder der Kriegshäuptling. Alle werden sich an meine Taten erinnern und die Geister werden auch meine Seele in ihre Reihen aufnehmen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29177] = {title = "Geflügelte Wachsamkeit", objective = "Legt eine Zwielichtfeuerlanze an und fliegt auf Avianas Wächter. Vernichtet 10 Zwielichttjoster, indem Ihr in sie hineinfliegt. Drückt die Taste 'Flattern', damit Euer Reittier mit den Flügeln schlägt!", description = "Die Agenten des Zwielichts setzen ihren Angriff innerhalb dieses Kessels in den Feuerlanden fort. Wir dürfen nicht in unserer Offensive nachlassen! Schwingt Euch in die Lüfte und vernichtet so viele der Tjoster, wie Ihr könnt!\n\nVergesst nicht, Euch zunächst mit einer Lanze auszurüsten.", progress = "Unsere Wachsamkeit darf nicht nachlassen. Ganz besonders jetzt nicht, da sie auf die Probe gestellt wird!", completion = "Gut gemacht, &lt;Klasse&gt;. Ich hoffe, Ihr vergesst uns hier in der Brutstätte nicht.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nJoust Lance Cleanup\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29179] = {title = "Feindliche Elemente", objective = "Tötet 8 verkohlte Soldaten oder Bezwinger.", description = "Die Elementare drängen weiterhin voran und ich erwarte nicht, dass sie bald nachlassen werden.\n\nIhr werdet sie im Norden finden, wo sie sich auf die Aschenfelder ergießen. Dünnt ihre Reihen aus.", progress = "Wir können nicht zulassen, dass diese Elementare Boden gutmachen. Es ist unwahrscheinlich, dass sie in ihren Angriffen nachlassen und uns erlauben, ihn zurückzuerobern.", completion = "Wir wissen Eure fortgesetzten Anstrengungen zu schätzen, &lt;Klasse&gt;. Wir werden diesen Krieg gewinnen, solange wir Kämpfer wie Euch an unserer Seite haben.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29180] = {title = "Versprechen, Versprechen...", objective = "Sucht auf Hohepriester Nalorakks Terrasse in Zul'Aman nach Budds Karte.", description = "Meine Theorien bestätigen die Gerüchte, dass in Zul'Aman sagenhafte Schätze zu finden sind. Das bedeutet Reittiere und Anwesen für alle!\n\nNun ja, eins nach dem anderen. Ihr müsst Euch Euren Anteil natürlich verdienen...\n\nUnsere anfänglichen Bemühungen haben uns hier doch nicht so weit gebracht, wie ich es mir erhofft hatte. Tatsächlich sieht es so aus, dass meine Karte, und die Tagelöhner, denen ich sie geliehen habe, verschwunden sind. Sie sind aufgebrochen, um einen Troll namens Nalorakk zu jagen. Ich kann zwar die Gruppe ersetzen, aber ich brauche diese Karte!\n\nSolltet Ihr diese Aufgabe bewältigen, dann wird man von Euch sagen, dass Ihr derjenige wart, der Budd Winterhäldler geholfen hat, die Geheimnisse von Zul'Aman zu lüften!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29181] = {title = "Druiden der Kralle", objective = "Sammelt 150 Abzeichen des Weltenbaums.", description = "Himmelsfürst Omnuron und seine Druiden der Kralle waren eine furchterregende Streitkraft, damals in Hyjal. Ich weiß, dass sie die bekannten Himmel dieses Schlachtfelds vorziehen, aber die Zeit mag kommen, dass wir sie trotzdem hier brauchen.\n\nSolltet Ihr es schaffen, genügend Abzeichen zusammenzubekommen, so appelliert an Omnuron, dass seine Druiden an der Hauptfront sein sollten. Omnuron passt auf die seinen auf, aber er versteht auch die Wichtigkeit dieser Anstrengung.", progress = "Es ist gut, Euch wiederzusehen.", completion = "Ich verstehe. Ich kann nicht behaupten, dass ich erpicht darauf wäre, meine Leute in die Feuerlande zu schicken, aber mir war klar, dass es irgendwann notwendig werden würde.\n\nWir werden da sein, &lt;Klasse&gt;. Danke, dass Ihr die Nachricht überbracht habt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFlag Druid Tree, Stage 2 Tracking Quest\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29182] = {title = "Der Flug der Sturmkrähen", objective = "Sprecht mit Himmelsfürst Omnuron bei Malfurions Bresche.", description = "Viele der Druiden der Kralle haben sich auf Euer Geheiß zur Geschmolzenen Front begeben. Ihr solltet zu Himmelsfürst Omnuron bei Malfurions Bresche gehen und sehen, wie sich ihre Schwingen in diesen brennenden Himmeln schlagen.", progress = nil, completion = "Diese Himmel sind tatsächlich beklemmend, aber wir haben es geschafft, uns größtenteils durchzunavigieren.\n\nEs kann sein, dass wir Eure Hilfe brauchen, um zusätzliche Landeplätze hinter dem Schmelzofen zu sichern. Ich werde Euch rufen, wenn wir so weit sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29183] = {title = "Daily Tier 2 Heroic (Nth)", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][29185] = {title = "Daily Tier 2 Heroic (1st)", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][29186] = {title = "Der Fetisch des Hexlords", objective = "Erbeutet den Fetisch des Hexlords von Hexlord Malacrass in Zul'Aman.", description = "Dieser neue Kriegsherr der Amani is' ohne den Schutz eines starken Hexendoktors nichts als ein zu groß geratener Haudrauf. Leider genießt er genau diesen Schutz.\n\nMit dem neuen Kriegsherrn im Bunde steht Hexlord Malacrass, der seit Jahrzehnten gefürchtetste Hexendoktor unter den Amani. Daakara wird sein Volk nich' dazu bring'n, sich der Kontrolle der Zandalari zu unterstell'n, es sei denn, der Hexlord befiehlt es.\n\nBesieg Hexlord Malacrass, bring mir seinen Lieblingsfetisch und ich garantier' dir eine angemessene Belohnung.", progress = "Hast du Hexlord Malacrass ausgeschaltet?", completion = "Das ist also der Fetisch vom mächtigen Malacrass? Der macht sich sicher gut in meiner Sammlung, &lt;Name&gt;. Und für dich is', glaub' ich, 'ne Belohnung angebracht.", rewards = "T'wansis HandlappenFetischschienbeinschützerVoodoojagdbogenIhr bekommt:\n\nZerlumpter Beutel aus Hexerstoff"}
MultiLanguageQuestData['de'][29189] = {title = "Nervige Netze", objective = "Befreit 8 Opfer aus Aschenweberkokons.", description = "Einige unserer Späher haben sich nicht zum Dienst zurückgemeldet. Wir fürchten, dass sie den tödlichen Spinnen in der Umgebung zum Opfer gefallen sind.\n\nAllerdings sind wir noch nicht bereit, alle Hoffnung fahren zu lassen, denn die Spinnen wickeln ihre Opfer oft noch lebend ein, um sie später zu... konsumieren.\n\nGeht und sucht bei den Säulen im Norden nach eingesponnenen Opfern. Vielleicht gelingt es Euch, einige unserer Brüder zu retten.", progress = nil, completion = "Unsere verlorenen Verbündeten sind bereits zurückgekehrt. Sie sind gebeutelt, aber sie sind am Leben. Vielen Dank, dass Ihr sie gerettet habt.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29190] = {title = "Drachensteigen", objective = "Kauft einen Doppelpack Papierdrachen von Blax Flaschenzünder in Orgrimmars Gasse und benutzt sie, um mit Eurem Orcwaisenkind einen Drachen steigen zu lassen. Wenn Euer Waisenkind nicht bei Euch ist, solltet Ihr es herbeirufen.", description = "Neulich, als ein paar von uns mit der Matrone unterwegs waren, haben wir einen Goblin gesehen, der einen Wagen mit Spielzeugen geschoben hat. Er hatte Puppen, Rennwagen aus Kupfer, Lederbälle und Papierdrachen. Ich wollte schon immer einen Drachen haben und die Matrone sagt, dass ich nur all mein Geld sparen muss, dann kann ich mir einen kaufen, aber das dauert noch ewig.\n\nIch glaube, der Name des Goblins war Blax Flaschenzünder oder so was. Wenn wir ihn aufspüren, könnten wir uns ein paar Drachen holen und sie steigen lassen? Ich habe ihn und seinen Karren in der Gasse gesehen.", progress = "Ich dachte, dass ich ganz bestimmt eine Million Jahre lang sparen muss, bis ich mir einen Drachen kaufen kann!", completion = "Danke für den Drachen, &lt;Name&gt;. Jedesmal wenn ich ihn steigen lasse, werde ich an den Tag denken, an dem Ihr ihn mir geschenkt habt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29191] = {title = "Lecker Eis", objective = "Kauft ein Eis im Laden 'Kältekegel' und teilt es mit Eurem Waisenkind.", description = "Es gibt einen brandneuen Eisladen in Orgrimmar und dort verkaufen sie nicht einfach nur gewöhnliches Eis. Deren Eis wird von einem verrückten Goblinmagier gemacht! Glaubt Ihr, es verschwindet, wenn ich es nicht innerhalb von fünfzehn Minuten schaffe?\n\nIch wette, das schmeckt richtig lecker. Gehen wir kosten?\n\nIch habe einige der anderen Kinder darüber reden hören und die sagen, der Laden heißt 'Der Kältekegel' und steht im Südteil der Goblinslums.", progress = "Eiscreme mag ich am liebsten.", completion = "Ich glaube, das ist das erste Mal, dass ich einen Goblin Essen machen sehe, für das er keine große, laute Maschine benutzt, die dicken Rauch spuckt. Vielleicht würden mehr Leute ihre Gerichte mögen, wenn sie sie wie normale Leute zubereiten würden... oder wie Magier! Das Eis war so lecker!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29192] = {title = "Die Wächter sehen zu", objective = "Greift einen Druiden der Flamme an, um ihn zu schwächen und lockt ihn dann in die Falle der Schattenwächterin.", description = "Wir müssen vorsichtig vorgehen, <Klasse>. Fandrals Druiden der Flamme praktizieren ihre feurige Magie jenseits der Säulen im Norden.\n\nIch möchte, dass Ihr einen dieser Druiden lebend gefangennehmt, damit wir ihn befragen können. Wir müssen jede Gelegenheit beim Schopf ergreifen, um ihre Pläne in Erfahrung zu bringen.\n\nEine meiner Wächterinnen wird Euch begleiten. Folgt ihren Anweisungen, wenn Ihr am Leben bleiben wollt.", progress = "Die Druiden der Flamme sind fern jeder Erlösung. Jetzt werden sie für ihre Verbrechen zur Rechenschaft gezogen.", completion = "Ich bin beeindruckt, &lt;Klasse&gt;. Eure Taten werden unter den Schattenwächtern nie vergessen werden.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29193] = {title = "Auf gut Glück", objective = "Bringt das zeitlose Auge nach Kaltarra.", description = "Wir haben guten Nutzen aus unserer Zeit gezogen, <Sterblicher/Sterbliche>.\n\nWährend Ihr auf der Ebene des Feuers gekämpft habt, haben meine Wächter und ich herausgefunden, wann und vor allem wo unser Blick behindert wurde.\n\nWir haben festgestellt, dass der Schleier über den Nexus, im hohen Norden, im Reich des blauen Drachenschwarms, gelegt wurde.\n\nIch habe das zeitlose Auge darauf abgestimmt, dass es Euch zeigen wird, was uns hier bisher verhüllt bleibt.\n\nBringt es sofort nach Kaltarra und findet einen geeigneten Ort, um das Auge zu aktivieren.\n\nGeht jetzt. Wir haben keine Zeit zu verlieren...", progress = nil, completion = "Ihr seid entweder ein Narr oder ein Wahnsinniger. Doch ungeachtet dessen müsst Ihr dahin zurückkehren, wo Ihr herkommt.\n\nWärt Ihr irgendeinem anderen Mitglied meiner Brut begegnet, wäre Euer Ende bereits gekommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29194] = {title = "Wie in einem Spiegel", objective = "Blickt in das zeitlose Auge am Nethervortex im Inneren des Nexus.\n\nTrefft Tarecgosa im Nexus, wo sie Euch zum Riss eskortieren wird.", description = "<Tarecgosa hört Euch zu, während Ihr Eure Anwesenheit in Kaltarra erklärt.>\n\nEure Geschichte klingt glaubwürdig, <Klasse>. Viel hat sich seit Malygos' Tod geändert - wenig davon zum Guten.\n\nIch weiß von dem Gerät, das Ihr mit Euch führt, und ich erkenne Anachronos' Magie in seiner Erschaffung. Es gibt in ganz Kaltarra nur einen Ort, der es erlaubt, dass dieses zeitlose Auge diskret eingesetzt wird.\n\nIhr werdet meine Hilfe brauchen, falls Ihr auf Erfolg hofft. Sprecht mich im Inneren des Nexus erneut an und sie soll Euch gewährt werden.", progress = nil, completion = "Das kann nicht sein, &lt;Klasse&gt;.\n\nDas muss ein Trick sein!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29195] = {title = "Ein Ritual der Flamme", objective = "Bekämpft die Wellen der verkohlten Eindringlinge auf dem Nordunegrat bis das Portal geöffnet ist.", description = "Es scheint, als hätten wir alles unter Kontrolle. Unser Invasionsportal zu den Feuerlanden wird jeden Augenblick geöffnet werden und die Elementare haben sich bisher nicht besonders zur Wehr gesetzt.\n\nHelft unseren Druiden, indem Ihr die letzten paar Elementare erledigt. Sobald das Tor dann geöffnet ist, können wir losschlagen.", progress = "Setzt den Kampf fort, <Name>. Es sollte jetzt nur noch ein wenig dauern.", completion = "Leyara... sie ist am Leben. Ich spüre, dass Fandral die Hände mit im Spiel hat...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29196] = {title = "Zum Heiligtum!", objective = "Meldet Euch bei Matookla beim Heiligtum von Malorne auf dem Hyjal.", description = "Für den Augenblick sollten wir uns keine Sorgen um diese \"Druidin der Flamme\" machen. Wir müssen uns um die Fortführung unserer Operation kümmern.\n\nKehrt zu Matookla beim Heiligtum von Malorne zurück. Wenn Ragnaros auf unsere Ankunft vorbereitet war, dann erwarte ich, dass seine Streitkräfte schon bald einen Gegenangriff starten werden.", progress = nil, completion = "Was ist dort oben geschehen? Ich habe Feuer gesehen und... Ach, unwichtig, Ihr könnt es mir später erzählen. Wir haben andere, dringendere Dinge, um die wir uns kümmern müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29197] = {title = "Kalt erwischt", objective = "Helft Ahnenzweig, Thisalee Krähe, Tholo Weißhuf und Anren Schattensucher, den Flammen zu entkommen.", description = "Es sieht so aus, als sei unser Invasionsplan nach hinten losgegangen. Einige unserer Vögel haben sich bereits zurückgemeldet und berichten von Feuern, die in den Tälern des zentralen Hyjal ausgebrochen seien.\n\nNun sind viele von unseren Druiden im Feld gestrandet, unvorbereitet für solch einen großangelegten Angriff. Thisalee war in der Nähe des Aschensees und verschiedene andere befanden sich beim Geheilten Hyjal, im Nordosten.\n\nGeht, <Name>! Findet sie und stellt sicher, dass sie dieser Explosion nicht zum Opfer fallen!", progress = "Wir haben keine Zeit! Bewegung!", completion = "&lt;Name&gt;! Ihr seid zurück!\n\nSie haben uns zum Heiligtum zurückgedrängt. Wir sind ihnen zahlenmäßig weit unterlegen. Bei diesem Tempo haben die Wächter des Hyjal kaum eine Chance zu überleben.\n\nIch bin froh, dass Ihr hier an unserer Seite steht.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29198] = {title = "Das Heiligtum darf nicht fallen", objective = "Schützt Malfurion, während er Malorne wiederauferstehen lässt.", description = "Malfurion arbeitet an einem Wunder für uns. Er glaubt, dass er in diesen gefährlichen Zeiten Malorne wiederauferstehen lassen kann, um das Heiligtum zu beschützen. Ich habe Vertrauen in ihn.\n\nIn der Zwischenzeit müssen wir die Stellung hier halten. Haltet Euch bereit und stellt sicher, dass dem Erzdruiden kein Leid widerfährt.", progress = nil, completion = "Malornes Stärke alleine hat vielleicht gerade Kalimdor gerettet. Sich vorzustellen, dass Malorne heute zurückgekehrt ist, nach so langer Abwesenheit...\n\n&lt;Malfurion überblickt die Gegend.&gt;\n\nWir haben heftige Verluste erlitten. Obwohl die unmittelbare Bedrohung nicht länger besteht, werden unsere Streitkräfte doch Zeit brauchen, zu gesunden, und alle verbleibenden Feuer am Hyjal zu löschen.\n\nUnser Angriff auf die Feuerlande wird warten müssen.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29199] = {title = "Verstärkung rufen", objective = "Sammelt 20 Abzeichen des Weltenbaums.", description = "Durch die Gegenwehr während unseres Invasionsversuchs haben wir schwere Verluste erlitten. Unser zweiter Versuch darf einfach nicht fehlschlagen.\n\nWir brauchen Verstärkung, bevor wir uns an einer neuen Invasion versuchen können. Bitte, <Name>, arbeitet mit Matookla zusammen, um neue Quellen zu erschließen, um Verstärkung zu ermöglichen. Dann werden wir uns zum zweiten und letzten Mal daran versuchen, die Feuerlande anzugreifen.", progress = "Je eher wir einen Durchbruch durch unser Invasionsportal erzielen können, umso besser.", completion = "Ausgezeichnete Arbeit. Ich fordere sofort unsere Verstärkung an.", rewards = nil}
MultiLanguageQuestData['de'][29200] = {title = "Leyara", objective = "Findet Leyara, die Druidin der Flamme.", description = "Bevor wir aufbrechen, <Name>, gibt es noch eine weitere Sache, um die Ihr Euch kümmern solltet.\n\nEine dieser \"Druiden der Flamme\" wurde in den Ruinen im Nordwesten gesehen. Ich schätze, dass es dieselbe ist, die uns vor einigen Tagen am Portal angegriffen hat. Jetzt wäre ein idealer Zeitpunkt, um herauszufinden, was sie wirklich will... und sie, wenn nötig, zu erledigen.\n\nKümmert Euch um diese Flammendruidin, dann können wir auf dem geplanten Weg fortfahren.", progress = nil, completion = "&lt;Matookla hört aufmerksam zu, als Ihr erklärt, was geschehen ist.&gt;\n\n&lt;Sie ist sichtbar erschüttert.&gt;\n\nIhr seid von unserem Plan abgewichen, &lt;Name&gt;. Unser Angriff hätte heute stattfinden sollen! All diese Vorbereitungen... wie können wir ohne die Hilfe Hamuuls siegreich sein?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29201] = {title = "Durch die Tore der Hölle", objective = "Geht durch das Portal auf dem Nordunegrat und helft Malfurion dabei, die Stellung an der Geschmolzenen Front zu sichern.", description = "Wir werden später um Hamuul trauern. Er war das erste von vielen unvermeidlichen Opfern dieses Kriegs... Aber unser Angriff kann nicht warten und die Triebkraft, die wir über die letzten Tage aufgebaut haben, darf nicht verschwendet werden.\n\nHeute greifen wir die Feuerlande an.\n\nDas Portal auf dem Nordunegrat ist jetzt geöffnet. Unsere Verstärkungen sind vorbereitet und sie warten nur auf meinen Befehl, um durch das Portal zu gehen.\n\nWir werden uns auf der anderen Seite des Portals wiedersehen. Sobald wir einmal dort sind, werden wir sicherstellen, dass unsere Stellung gesichert ist.", progress = nil, completion = "Sehr gut gemacht, &lt;Klasse&gt;. Wir haben es geschafft, uns im Reich des Feindes eine Stellung einzurichten, ohne dass sie es bemerkt haben. In genau diesem Moment bewegen sich unsere Armeen voran und errichten eine Front.\n\nUns steht ein langer, brutaler Krieg bevor. Es ist meine Hoffnung, dass Ihr an unserer Seite sein werdet, um uns hierbei zu helfen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nStart Foothold Completion Event\n\nIhr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29202] = {title = "Das Schicksal von Runentotem", objective = "Sprecht mit Dorda'en Nachtweber beim Heiligtum von Malorne auf dem Hyjal.", description = "Ich entschuldige mich dafür, dass ich Euch gegenüber zuvor so kurzangebunden war. Der Verlust von Hamuul hat mich schockiert und es ist nicht einfach, damit umzugehen.\n\nSie haben seinen Körper hereingebracht, während Ihr weg wart. Er lebt, aber er hat - wie Ihr Euch denken könnt - sehr, sehr schwere Verbrennungen erlitten.\n\nDie Wunden sind tief. Vielleicht wird er es nicht überleben.\n\nIch habe ihm einige unserer besten Heiler zur Seite gestellt, die sich um ihn kümmern. Wenn es nicht zu viel verlangt ist, könntet Ihr vielleicht mit Dorda'en Nachtweber sprechen? Er und die anderen Pfleger könnten vielleicht Eure Hilfe brauchen.", progress = nil, completion = "Ja, Hamuul lebt. Ihr könnt ihn in dem Zelt hinter mir besuchen, aber seid bitte vorsichtig. Er ist in sehr schlechtem Zustand und wir tun alles in unserer Macht Stehende, um ihn am Leben zu halten und es ihm bequem zu machen.\n\nWer auch immer das dem Erzdruiden angetan hat, hat keinerlei Gnade gezeigt. Ich hoffe, dass Ihr Euch dafür irgendwann revanchieren könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29203] = {title = "In die Tiefen", objective = "Tötet Leyara.", description = "Leyara ist in den Feurigen Tiefen entdeckt worden. Eine Gruppe Schattenwächter hat sie umzingelt.\n\nBegebt Euch sofort dorthin. Ich werde Euch treffen, sobald ich eine notwendige Vorbereitung abgeschlossen habe.", progress = nil, completion = "Leyaras Geschichte ist tragisch. Es schmerzt mich, dass es so weit gekommen ist.\n\nHirschhaupt muss aufgehalten werden, bevor er noch weitere mit sich in den Abgrund reißt.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29204] = {title = "Der Angriff der Wächterinnen", objective = "Wenn Ihr den Wächterinnen helfen wollt, den Einsamen Turm anzugreifen, dann sprecht mit Hauptmann Saynna Sturm in den nordöstlichen Aschenfeldern.Hauptmann Saynna Sturmläufer ist im Begriff, einen Angriff gegen den Einsamen Turm zu führen. Wenn Ihr Euch nach Nordosten begebt, werdet Ihr sie unten an der Rampe finden, die zu der Anhöhe führt.\n\nIch habe ihr eine große Gruppe unserer Männer unterstellt, aber ihre Erfolgsgruppen würden enorm steigen, wenn Ihr Euch ihr anschließen würdet. Es ist Eure Entscheidung, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Hauptmann Saynna Sturmläufer ist im Begriff, einen Angriff gegen den Einsamen Turm zu führen. Wenn Ihr Euch nach Nordosten begebt, werdet Ihr sie unten an der Rampe finden, die zu der Anhöhe führt.\n\nIch habe ihr eine große Gruppe unserer Männer unterstellt, aber ihre Erfolgsgruppen würden enorm steigen, wenn Ihr Euch ihr anschließen würdet. Es ist Eure Entscheidung, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29205] = {title = "Der Einsame Turm", objective = "Beschützt einen der Druiden, die versuchen, den Einsamen Turm einzunehmen.", description = "Hauptmann Saynna Sturmläufer ist im Begriff, einen Angriff gegen den Einsamen Turm zu führen. Wenn Ihr Euch nach Nordosten begebt, werdet Ihr sie unten an der Rampe finden, die zu der Anhöhe führt.\n\nGeht dorthin und eskortiert einen ihrer Druiden zum Turm mit allen Streitkräften, die sie entbehren kann. Euch steht ein ordentlicher Kampf bevor - stellt sicher, dass der Druide bis zum Ende überlebt oder es wird ihnen nicht möglich sein, den Turm zu erobern.", progress = nil, completion = "Gut gemacht, &lt;Klasse&gt;. Das sollte ein guter Ausgangspunkt sein, um weiter in feindliches Gebiet vorzudringen.\n\nIch kann in der Nähe Druiden der Flamme spüren. Vielleicht sollten wir auch mit ihnen kurzen Prozess machen.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29206] = {title = "Ins Feuer", objective = "Eskortiert einen Windrufer durch den Schmelzofen und sichert den Eingang zum Geschmolzenen Strom.", description = "Der Himmelsfürst Omnuron und seine Druiden versuchen durch den Schmelzofen im Nordwesten durchzubrechen. Es war ihnen möglich, über die Gefahren hinwegzufliegen, aber sie benötigen wirklich jemand auf dem Boden, der ihnen hilft, das Gebiet jenseits des Feuers zu sichern... jemanden wie Euch.\n\nWenn Ihr den Druiden der Kralle helfen wollt, so wartet darauf, dass einer von Omnurons Windrufern versucht, das Feuer zu durchbrechen, bleibt in seiner Nähe und beschützt ihn vor Angreifern aus den Flammen.", progress = nil, completion = "Es ist gut zu sehen, dass der Himmelsfürst endlich jemand Fähigen ohne Flügel gefunden hat. Die Fähigkeit zu fliegen nützt uns in diesen beengten Umständen und im Anbetracht der Thermalwinde jenseits dieses Grats wenig.\n\nEs sieht so aus, als müssten wir uns auf konventionellere Taktiken verlassen. Seid Ihr dabei?", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29208] = {title = "Ein alter Freund", objective = "Zwischen all den Raptoren in Mandokirs Reich sticht ein vertrautes Gesicht heraus. Sie ist etwas größer geworden und hat ein paar mehr Narben, aber sie ist noch immer hier und wartet auf Eure Rückkehr.\n\nSie erkennt Euch wieder. Ihr Papa ist endlich da, um sie zu retten.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSchmetterschwanzjunges"}
MultiLanguageQuestData['de'][29209] = {title = "Hinein in die Feurigen Tiefen", objective = "Sprecht mit Theresa Baumrinde in den Feurigen Tiefen.Eine unserer Druidinnen ist vorangegangen in die Feurigen Tiefen, auf der Jagd nach einem Druiden der Flamme.\n\nGeht zu ihr. Helft ihr.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Eine unserer Druidinnen ist vorangegangen in die Feurigen Tiefen, auf der Jagd nach einem Druiden der Flamme.\n\nGeht zu ihr. Helft ihr.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29210] = {title = "Erdulden der Hitze", objective = "Findet den Weg in die Feurigen Tiefen und zerstört dann alle 8 der blauen Runen, die sich im Inneren befinden.", description = "Shalis ist mit einem unserer Druiden losgezogen, um einen Druiden der Flamme davon abzuhalten, in den Feurigen Tiefen unter uns ein Beschwörungsritual zu vollziehen. Ihnen ist aufgetragen worden, den Druiden zu töten, aber ich brauche Euch, um das Ritual zu stoppen.\n\nIhr werdet den Eingang zu den Feurigen Tiefen östlich der Magmaquellen finden. Sobald Ihr im Inneren seid, werdet Ihr 8 blaue Runen über die Höhle verteilt sehen. Ihr könnt diese Runen benutzen, um Euch vor den feurigen Kreaturen zu schützen, aber Ihr werdet alle von ihnen austreten müssen, um das Ritual zu beenden. Ihr werdet schnell handeln müssen.", progress = "Ihr müsst die Runen zerstören! Beeilt Euch!", completion = "Gut gemacht!\n\nSie haben versucht, Rituale wie dieses überall an der Geschmolzenen Front durchzuführen, doch bisher konnten wir dieses Vorhaben noch immer vereiteln. Hoffentlich werdet Ihr auch in Zukunft da sein, um uns dabei zu helfen, diesen Trend fortzusetzen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Zone Auras\n\nIhr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29211] = {title = "Solarkernzerstörung", objective = "Sprengt den Solarkern.", description = "Der Kampf hat uns direkt zu Fandrals Haustür gebracht. Seine Druiden kanalisieren Energien der Feuerlande in ein Behältnis, das der Solarkern genannt wird.\n\nSollte dieses Behältnis auf Azeroth explodieren, wird keinem von uns eine Heimat bleiben, in die wir zurückkehren könnten.\n\nWir müssen jetzt einen Schlag gegen den Solarkern führen, solange er noch angreifbar ist. Ihr könnt das infernalische Gerät auf der nordöstlichen Kante der Insel finden.", progress = nil, completion = "Ist er zerstört? Gut. Ich bezweifle, dass das Fandral lange aufhalten wird, aber wir müssen uns jeden Vorteil sichern, den wir bekommen können.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29213] = {title = "Wie geht's dem Jäger?", objective = "Seht nach Grent Düsterhammer.", description = "Das sah nich' gut aus. Der Panther stand unter irgendeiner Art von mächtiger Magie... Wir sollt'n besser nach dem Jäger seh'n und schau'n, wie's ihm geht.", progress = nil, completion = "Oh... Mein Kreuz. Bist du das, Bruder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29214] = {title = "Die Schattenwächterinnen", objective = "Sammelt 150 Abzeichen des Weltenbaums.", description = "Die Schattenwächterinnen sind zurück im Geheilten Hyjal. Ich weiß, dass sie den Verlust von Fandral aus ihrem Gewahrsam sehr ernst nehmen, weshalb es wenig Ansporn bedürfen wird, sie in die Feuerlande zu bringen und die Druiden der Flamme zu jagen.\n\nSobald Ihr genügend Abzeichen zusammen habt, solltet Ihr Euch bei Hauptmann Saynna Sturmläufer beim Heiligtum von Malorne melden und Euch ihre Unterstützung sichern.", progress = "Ja, <Klasse>?", completion = "Ich verstehe. Die Zeit ist also gekommen, dass wir uns der Jagd in den Feuerlanden anschließen. Meine Schwestern werden hinter Euch stehen, &lt;Klasse&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFlag Druid Tree, Stage 2 Tracking Quest\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29215] = {title = "Die Jagd beginnt", objective = "Sprecht mit Hauptmann Saynna Sturmläufer bei Malfurions Bresche.", description = "Die Schattenwächterinnen haben sich auf Eure Bitte hin dem Kampf an der Geschmolzenen Front angeschlossen. Ihr solltet Hauptmann Saynna Sturmläufer finden und dafür sorgen, dass sie einen Weg finden, ihre Fähigkeiten am besten einzusetzen.", progress = nil, completion = "Hallo &lt;Name&gt;. Es ist gut, Euch wiederzusehen.\n\nIhr hättet Euch keine Sorgen machen müssen, wir haben uns hier ganz gut eingerichtet. Ich habe mehrere meiner Wächterinnen ausgeschickt, um dabei zu helfen, die Druiden der Flamme zur Strecke zu bringen und ich habe die Angriffspläne für den Einsamen Turm angefertigt. Wenn der Zeitpunkt gekommen ist, werdet Ihr Euch uns vielleicht dort anschließen wollen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29216] = {title = "alfurion's Breach", objective = "[DEPRECATED]Secure a foothold in the Firelands.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][29217] = {title = "Die gefangenen Späher", objective = "Befreit die gefangenen Späher: Hazlek, Bakkalzu, Norkani und Kasha. Sie werden von den Hohepriestern der Amanitrolle gefangen gehalten.", description = "Nachdem wir hier angekomm'n sind, habe ich meine Späher losgeschickt, um mehr über die Anwesenheit der Zandalari hier in Zul'Aman zu erfahr'n. Viele sind mit nützlichen Informationen zurückgekehrt, aber vier werd'n noch immer vermisst. Wenn wir nich' schnell handeln, werd'n die Handlanger des neuen Kriegsherrn sie zu Ehren der Gesandten der Zandalari opfern.\n\nFinde meine Späher, <Name>, und befrei sie, bevor die Priester sie opfern!", progress = "Hast du meine Späher gefund'n?", completion = "Ich hätte nich' gedacht, die nochmal wiederzuseh'n, &lt;Name&gt;. Die Informationen, die sie gesammelt hab'n, werd'n der Schlüssel dazu sein, den Einfluss der Zandalari in Zul'Aman zu brech'n. Herzlichen Dank von mir und meinen Spähern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29218] = {title = "Abzeichen des Weltenbaums", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29219] = {title = "Bwembas Geist", objective = "Warnt die Bewohner des Schlingendorntals und findet den anderen Abgesandten der Dunkelspeere.", description = "Es sind gefährliche Zeiten für uns Dunkelspeere. Die Zandalaritrolle versammeln alle Trollklans und hab'n vor, die Länder wiederzuerobern, die sie verlor'n hab'n.\n\nWir versuch'n alle zu warnen, die wir können. Aber es könnte zu spät sein.\n\nEin weiterer Dunkelspeertroll is' ins Schlingendorntal gegang'n, um die Leute zu warnen. Aber es is' nich' sicher, allein da durchzuwandern.\n\nHilf mir, ihn zu find'n und sicherzustell'n, dass die Leute im Schlingendorntal von der Bedrohung durch die Trollstämme erfahr'n.\n\nIch werd' meinen Geist mit deinem verbind'n. Wenn du ins Schlingendorntal gelangst, werd' ich dir helf'n können.", progress = "Das wird keine einfache Aufgabe, <Name>.", completion = "Da siehst du's, &lt;Name&gt;. Sieht aus, als würd'n wir einen Angriff auf die Gurubashi in Zul'Gurub anführ'n.\n\nDies sind dunkle Zeiten für uns Dunkelspeere. Aber für die Zandalaritrolle werd'n sie noch dunkler. Sie sind zu weit gegang'n.\n\nDu bist gut zu Bwemba gewes'n, hoffentlich wirst du weiter das ganze Schlingendorntal unterstütz'n.\n\nMög'n die Geister mit dir sein, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\n4.1 - ZG Event - Cancel Bwemba Aura [DND]\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29220] = {title = "Nach Bambala", objective = "Reist nach Bambala im Nördlichen Schlingendorntal, um den Abgesandten der Dunkelspeere zu finden.", description = "Zuerst sollt'n wir dort nachsehen, wo vermutlich der erste Angriff stattfindet, also in Bambala.\n\nBambala is' gefährlich nahe an der Trollstadt Zul'Gurub dran... ein leichtes Ziel.\n\nVielleicht find'n wir den Abgesandten dort. Hoffentlich is' es noch nich' zu spät.", progress = nil, completion = "Wie's aussieht, sind die Geister mit dir, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29221] = {title = "Schlangen und Gift", objective = "Tötet Dschungelschlangen und untersucht die vergifteten Kopfjäger, damit Bwemba sie heilen kann.", description = "Die Warnung hat geholf'n, <Name>.\n\nWir hab'n mehr Kopfjäger für unsere Verteidigung versammelt. Aber Kopfjäger... na ja, die jag'n für gewöhnlich nich' die Köpfe von Schlangen. Wir werd'n also bald überwältigt sein. Diese Schlangen scheinen von überall herzukomm'n. Und wahrscheinlich wird's nur noch schlimmer.\n\nHilf uns, die Schlangen zu töt'n und lass Bwemba ihr Mojo verwend'n, damit die Vergifteten geheilt werd'n.", progress = nil, completion = "Danke für deine Hilfe, &lt;Klasse&gt;. Die Schlangen sind ja überall.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRemove Mod Aura Vision - Quest Zone Specific 1\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29222] = {title = "Die Geister sind mit uns", objective = "Bereitet das Freudenfeuer vor dem Schlangenschrein in der Nähe von Bambala für Bwembas Ritual vor.", description = "Mit den Schlangen hat was nich' gestimmt, <Name>. In ihrem Gift war eine Spur von schlechtem Mojo und das passiert nich' von Natur aus.\n\nDas Freudenfeuer in der Mitte des Lagers - dort können wir ein Ritual abhalt'n.\n\nWas auch immer diese Schlangen zum Angreif'n bringt, passt bestimmt noch gut auf sie auf.\n\nDas einzige Problem is', <Name>, dass ich nur in Geisterform hier bin. Du musst meine Hände sein. Geh zu dem Feuer und bereite es für mich vor. Dann kümmere ich mich um den Rest.", progress = nil, completion = "Venoxis... das kann nix Gutes heiß'n, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29223] = {title = "Nesingwary wird es wissen", objective = "Warnt die Jäger in Nesingwarys Expedition im Nördlichen Schlingendorntal.", description = "Die Gurubashi sind also auf dem Vormarsch und die benutz'n Schlangen als erste Angriffswelle.\n\nWeißt du, wer sich darauf versteht, die Wildtierbestände hier klein zu halt'n? Die Jäger in Nesingwarys Expedition.\n\nSpazier doch mal da 'rüber und frag sie nach einer guten Methode, wie man Schlangen loswird.\n\nWenn die's nich' wiss'n, dann solltest du sie wenigstens warn'n, dass mit diesen Schlangen was nich' stimmt.", progress = nil, completion = "Über die Schlangen wissen wir Bescheid, &lt;Name&gt;. Aber da draußen lauert noch etwas anderes... Der Dschungel ist zum Leben erwacht, &lt;Klasse&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29224] = {title = "O LONGER USED", objective = "[DEPRECATED]Gaze into the Timeless Eye.\n\nSpeak to Tarecgosa at the Rift to activate the artifact.", description = "[DEPRECATED]Here we are, mortal.\n\nThe rift emits intense energy that will shield the magic of your artifact.\n\nWhen you are ready, I will activate the Eye. Doing so will require all of my focus. You must witness the vision on your own.\n\nHurry now, <Klasse>. It is unsafe for us to tarry here.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29225] = {title = "Informationen mit Konsequenzen", objective = "Sprecht mit Kalecgos bei Nordrassil auf dem Hyjal.", description = "<Tarecgosa hört gebannt zu, während Ihr Eure Vision schildert.\n\nUnmöglich!\n\nNicht einmal Arygos würde es wagen, so weit zu gehen.\n\nIch stelle hier nicht Eure Integrität in Frage, <Klasse>, doch müsst Ihr verstehen, Euer sterblicher Geist kann leicht getäuscht werden.\n\nDoch in jedem Fall muss Kalecgos über diese Ereignisse unterrichtet werden. Ihr müsst sofort nach Nordrassil reisen und ihn aufsuchen.\n\nIch bleibe hier und beseitige die Beweise unserer Aktivitäten. Erzählt sonst niemandem davon.", progress = nil, completion = "&lt;Kalecgos hört sich Eure Erzählung der jüngsten Ereignisse an.&gt;\n\nEs war weise von Tarecgosa, Euch zu mir zu schicken, &lt;Klasse&gt;.\n\nObwohl Eure Vision im Nexus fast sicher eine ausgeklügelte Illusion war, wäre es unverantwortlich von mir, die Sache nicht zu untersuchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29226] = {title = "Dem Spurenleser auf der Spur", objective = "Findet Düsterhammer im Nördlichen Schlingendorntal.", description = "Wir schlagen hier schon seit Tagen die Schlangen zurück, <Name>. Aber Schlangen sind nichts im Vergleich zu dem, was sich da sonst noch so im Dschungel herumtreibt.\n\nWir Jäger werden zu Gejagten.\n\nEin großer Panther namens Mauti hat meine Männer einen nach dem anderen in den Busch weggezerrt.\n\nWir haben Grent Düsterhammer, einen unserer besten Jäger, auf dieses Mistviech angesetzt.\n\nDüsterhammer ist nach Osten aufgebrochen. Vielleicht könnt Ihr ihn dort finden.", progress = nil, completion = "Schhh....", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29227] = {title = "Die Rache des Jägers", objective = "Gewährt Grent Düsterhammer die Genugtuung, die er sich wünscht, indem Ihr Mauti tötet.", description = "Die Bestie, die uns auf der Spur war... ich habe nach ihr gejagt.\n\nIhr Name ist Mauti. Sie ist ziemlich schlau. Doch sie hat einen großen Fehler begangen, als sie meinen Bruder getötet hat. Das wird sie teuer zu stehen kommen. Der alte Düsterhammer ist ihr auf den Fersen.\n\nIch habe sie oberhalb von Kurzens Truppenlager herumstreifen sehen. Wenn wir schnell zuschlagen, können wir ihr den Garaus machen.\n\nSeid Ihr bereit, <Name>?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29228] = {title = "Folgt dieser Katze", objective = "Findet heraus, wohin Mauti Grent Düsterhammer gebracht hat.", description = "Tja, deshalb schien Mauti wohl kleiner... Der echte Mauti hat sich mit Grent Düsterhammer davongemacht, aber da er so ein vorausschauender Jäger ist, hat er Signalfeuer abgeschossen, damit Ihr ihm auf der Spur bleiben könnt. Findet Düsterhammer, bevor es zu spät ist!", progress = "Unterschätzt Mauti nich'. Er ist ein schlauer Panther.", completion = "Da sind wir... Der Jäger, er is' in der Höhle. Die Bestie... Etwas stimmt mit ihr nicht...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRemove See Quest Invis 10\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29229] = {title = "Folgt dieser Katze", objective = "Findet heraus, wohin Mauti Grent Düsterhammer gebracht hat.", description = "Tja, deshalb schien Mauti wohl kleiner... Der echte Mauti hat sich mit Grent Düsterhammer davongemacht, aber da er so ein vorausschauender Jäger ist, hat er Signalfeuer abgeschossen, damit Ihr ihm auf der Spur bleiben könnt. Findet Düsterhammer, bevor es zu spät ist!Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRemove See Quest Invis 10\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29230] = {title = "Mauti", objective = "Bringt Bwemba zu den Überresten von Mauti.", description = "Ich hab das Gefühl, dass mit dem Panther was nich' stimmt, <Name>. Fühlt sich unnatürlich an. Ich werd' ein paar Rituale über dem Leichnam abhalt'n müss'n. Töte Mauti und dann werd'n wir mal seh'n, was wir herausfinden können, <Name>.", progress = nil, completion = "Hohepriesterin Kilnara steckt hinter dieser Monstrosität. Das sieht nich' gut aus. Wir sollt'n nach dem Zwerg seh'n und dann herausfind'n, was sonst noch so los ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29231] = {title = "Wie geht's dem Jäger?", objective = "Seht nach Grent Düsterhammer.", description = "Das sah nich' gut aus. Der Panther stand unter irgendeiner Art von mächtiger Magie... Wir sollt'n besser nach dem Jäger seh'n und schau'n, wie's ihm geht.", progress = nil, completion = "Oh... Mein Kreuz. Bist du das, Bruder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29232] = {title = "Die letzten Botten", objective = "Holt die Stiefel von Grent Düsterhammer.", description = "Ah... Ihr seid es, <Name>. Mauti... Sie ist tot? Dann wurde mein Bruder gerächt. Ich habe nur noch eine Bitte an Euch... Dieser Schuft hier hat an meinen nackten Füßen herumgekratzt. Kein Zwerg sollte ohne Stiefel unter die Erde müssen.\n\nBitte, begrabt mich mit meinen Stiefeln.", progress = "Habt Ihr meine Stiefel? Gewährt einem Zwerg doch seinen letzten Wunsch, ja?", completion = "Da-Danke… Kumpel.\n\nPapi...?\n\n\nBist...\n\n\n\ndu das...\n\n\n\n\n...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\n4.1 - ZG Event - Nessingwary - Summon Dirt Mound\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29233] = {title = "Warnt Grom'gol", objective = "Begebt Euch zum Basislager Grom'gol.", description = "Dieser Tod war nich' vergebens, <Name>. Wir hab'n herausgefund'n, dass Kilnara auf Streifzug is'. Das sieht ziemlich düster für uns aus.\n\nWir seh'n besser nach, wie es in Grom'gol im Westen aussieht. Vielleicht find'n wir ja auch meine Kontaktperson dort.", progress = nil, completion = "Erst waren es Schlangen, dann Panther und jetzt sind es blutrünstige Trolle.\n\nBloß gut, dass Ihr hier seid, &lt;Klasse&gt;, es gibt reichlich Trolle abzuschlachten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29234] = {title = "Delegierung", objective = "Holt den Zweig von Nordrassil aus den Feuerlanden zurück.", description = "Meine Pflicht bindet mich, Euren Aussagen unverzüglich nachzugehen, <Volk>, was bedeutet, dass meine Mission hier nun in Eure Hände fällt.\n\nEin Anstieg uralter Magie, viel zu stark, um natürlichen Ursprungs zu sein, führte mich hierher. Seitdem habe ich eine zutiefst beunruhigende Entwicklung entdeckt.\n\nEin Ast wurde von Nordrassil abgebrochen und tief in die Feuerlande verschleppt. Dort droht ein mächtiges Ritual, Nordrassil zu verderben und ihn in Flammen aufzuzehren.\n\nIhr müsst einen Weg finden, das Ritual zu unterbrechen und den Zweig des Weltenbaumes zurückzuholen.", progress = "Konntet Ihr den Zweig von Nordrassil zurückholen, <Klasse>?", completion = "Der Zweig von Nordrassil…\n\nIhr habt Euch gut geschlagen, sterbliches Wesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29235] = {title = "Verteidigt Grom'gol", objective = "Helft dabei, das Basislager Grom'gol drei Minuten lang zu verteidigen.", description = "Ich hoffe, Ihr kämpft gern, <Name>. Euer Trollfreund ist hier durchgekommen und hat uns gewarnt, dass die Gurubashi auf dem Vormarsch sind. Ich hätte nie gedacht, dass die Schlacht so glorreich werden würde.\n\nKommt, werft Euch mit uns in die Schlacht und zeigt diesen Gurubashitrollen die Macht der Horde!", progress = nil, completion = "Diese Trolle strömen immer weiter auf uns ein, &lt;Name&gt;. Fantastisch!\n\nWie ich schon sagte, war der Abgesandte der Dunkelspeere für kurze Zeit hier. Er hat uns gewarnt, dann ist er wieder aufgebrochen.\n\nThysta, unsere Windreitermeisterin, hat ihm geholfen, zu seinem nächsten Bestimmungsort zu kommen, vielleicht kann sie Euch helfen.\n\nGute Jagd, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29236] = {title = "Nach Hartzangs Versteck", objective = "Begebt Euch nach Hartzangs Versteck am Schlingendornkap.", description = "Bwemba... Seid Ihr das?\n\nEuer Kontakt war hier. Er war erpicht darauf, zum nächsten Ort zu eilen und die Leute zu warnen. Ich habe ihn auf einen Flug nach Hartzangs Versteck am Schlingendornkap geschickt. Ich hoffe, er war nicht zu spät.\n\nIhr könnt einen meiner Wyvern verwenden, um zum Versteck zu gelangen.\n\nSagt Bescheid, wenn Ihr bereit seid aufzubrechen, <Name>.", progress = nil, completion = "Das sieht nich' sehr gut aus, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29237] = {title = "Voodoozombies", objective = "Rettet 10 Überlebende des Verstecks.", description = "Die Leute... alles Zombies, Voodoozombies! Das wird nich' schön, <Name>.\n\nDu musst die alle töt'n.\n\nAber sobald sie erledigt sind, gibt es einen Weg, wie ich sie zurückhol'n kann. Wieder in die Personen verwandeln, die sie war'n.\n\nWir müss'n schnell handeln, die Zombies schlafen nich'.", progress = nil, completion = "Wir hab'n getan, was wir konnt'n, &lt;Name&gt;. Wir können diese Zombies nich' länger bekämpf'n. Wir müss'n die Wurzel dieses Voodoos ausfindig mach'n. Und ich glaub', ich weiß, wo wir anfang'n.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29238] = {title = "Verdorbene Vorräte", objective = "Überprüft den Ort in Hartzangs Versteck, an dem Nahrungsmittel zubereitet werden.", description = "Einige der Überlebenden hab'n Nahrungsmittel erwähnt, <Name>. Wir sollt'n ihre Vorräte überprüf'n. Ich hab ein schlechtes Gefühl bei der Sache.", progress = nil, completion = "Zanzil... Es fängt alles an, Sinn zu ergeb'n. Wenn ich meinen Kontakt find'n kann, können wir einen Angriffsplan entwickeln.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29239] = {title = "Der Zweig von Nordrassil", objective = "Besorgt Euch den Zweig von Nordrassil beim Bernsteinflöz in der Boreanischen Tundra.", description = "Viel hat sich seit unserem letzten Gespräch ereignet.\n\nIch habe es auf mich genommen, zum Nexus zu reisen und Anachronos' Artefakt zurückzuholen, doch nicht ohne es selbst zu verwenden. Jetzt kann auch ich das bezeugen, was Ihr gesehen habt.\n\nBevor wir noch weiter darüber reden, erlaubt mir, Euch meine Dankbarkeit auszusprechen, sowohl hierfür als auch für die Feuerlande.", progress = nil, completion = "Der Zweig von Nordrassil ist jetzt mit dem zeitlosen Auge verbunden.\n\nSelbst ein kampferprobter Held wie Ihr kommt nicht umhin, bei einem solchen Geschenk Demut zu empfinden.", rewards = "Ihr bekommt:\n\nZweig von Nordrassil"}
MultiLanguageQuestData['de'][29240] = {title = "Notextrahierung", objective = "Begleitet Kalecgos nach Kaltarra.\n\nSprecht mit ihm, wenn Ihr bereit seid.", description = "Nun wieder zur anstehenden Aufgabe...\n\nIch bin mir sicher, dass die Vision im Nexus eine von Todesschwinges Illusionen ist, um unseren Schwarm in dieser schweren Zeit in Streit zu versetzen.\n\nDer Weltenbrecher würde nur noch stärker werden, wenn wir zu den Waffen greifen.\n\nDennoch, mir ist nicht ganz wohl bei der Sache, somit bin ich versucht einen Pfad der Vorsicht einzuschlagen.\n\nEs wäre weise, wenn ich mich mit Tarecgosa zurückziehen würde, bis die Zeit der Wahl gekommen ist.", progress = nil, completion = "Sie stirbt, &lt;Name&gt;.\n\nIch habe... sie enttäuscht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29241] = {title = "Brecht den Götterbrecher", objective = "Tötet Jin'do den Götterbrecher in Zul'Gurub auf heroischem Schwierigkeitsgrad.", description = "<Blutschlächterin Zala zeigt auf den entfernten Tempel.>\n\nAls Jin'do das letzte Mal ins Jenseits befördert wurde, hat er als schwacher und gebrochener Schemen in der Geisterwelt überlebt.\n\nAber Jin'do hatte ja schon immer Macht über die Geister. Einen nach dem anderen hat er sie seinem Willen unterworf'n und mit jeder verschlungenen Seele is' er seinem Ziel näher gekomm'n, einen Riss in unsere Welt zu öffnen.\n\nJetzt is' er hier...\n\nDie Geister sind mit uns. Wir müss'n Jin'do ein Ende bereit'n.", progress = nil, completion = "&lt;Blutschlächterin Zala greift sich an die Brust.&gt;\n\nEs ist also getan. Das Blut unserer Brüder zu vergieß'n is' keine schöne Aufgabe. Die Stadt der Gurubashi hat jahrelang nur Tod und Hass erlebt.\n\nVielleicht is' es an der Zeit, dass der Dschungel Zul'Gurub zurückerobert und den Gestank des Todes von diesem Ort fortwäscht.\n\nBlut und Donner, Champion! Den Siame Quashi wirst du auf ewig als \"Blutschlächter\" bekannt sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29242] = {title = "Unbezahlbar mit Rabatt", objective = "Untersucht den Hort des Wahnsinns und findet das mysteriöse Schmuckstück der Gurubashi.", description = "Hört zu, <mein Bester/meine Beste>. Ich kenne Euch nicht und Ihr kennt mich nicht, aber wo wir beide nun hier sind: Revilgaz wollte, dass ich etwas erwähne.\n\nVielleicht macht Ihr ja einen Spaziergang durch diese trollinfizierte Dschungelkalypse. Vielleicht findet Ihr ja rein zufällig das eine oder andere kostbare Trollartefakt. Vielleicht bringt Ihr es zu mir und ich lasse aus Versehen ein kleines Geschenk für Euch zurück.\n\nWenn Ihr es unbedingt wissen müsst, es ist für ein Projekt. Und nein, Ihr dürft nicht fragen, was das für ein Projekt ist.", progress = "Na, habt Ihr etwas gefunden? Mir hängen nämlich langsam die Hosen auf Halbmast von all den Schätzen, auf die ich für Euch aufpasse.", completion = "Was habt Ihr denn da?\n\nEin merkwürdiges Schlangengötzenbild? Was soll ich denn damit anfangen? Etwa jemandem damit eins auf den Deckel geben und etwas stehlen, was tatsächlich was wert ist?\n\nDas Ding ist doch Ramsch!\n\n&lt;Briney wirft das Schmuckstück ins Wasser.&gt;\n\nNa dann danke für Eure \"Hilfe\". Hier habt Ihr Eure \"Belohnung.\"\n\nTrottel.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29243] = {title = "Ein Stich ins Herz", objective = "Tötet den Leutnant der Flamme.", description = "Einer von Ragnaros' Leutnants hat sich auf Ragnaros' Ebenen gezeigt. Es ist Zeit, zuzuschlagen. Hauptmann Saynna hat darum gebeten, dass Ihr dabei seid und ihr im Kampf beisteht.\n\nDorrzweig und einige andere werden sich bereits dem Kampf angeschlossen haben, wenn Ihr eintrefft. Ihr solltet Euch besser gleich in Richtung Nordwesten aufmachen und sie finden.", progress = nil, completion = "Sehr gut gemacht, &lt;Name&gt;! Das sollte sie erheblich hemmen.\n\nWenn wir das durchhalten, sollten wir den Kampf leicht zu Ragnaros selbst tragen können.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29244] = {title = "Lieutenant of Flame", objective = "[DEPRECATED]Report to Captain Saynna Stormrunner at Ragnaros' Reach.[DEPRECATED]Captain Saynna has requested your presence at Ragnaros' Reach. A Lieutenant of Flame has shown himself and she thinks you are our greatest chance at striking against him.\n\nMake your way there as soon as you're able.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "[DEPRECATED]Captain Saynna has requested your presence at Ragnaros' Reach. A Lieutenant of Flame has shown himself and she thinks you are our greatest chance at striking against him.\n\nMake your way there as soon as you're able.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29245] = {title = "Das mysteriöse Samenkorn", objective = "Bringt die Eichel zu Avrilla in Malfurions Bresche in den Feuerlanden.\n\nBereitgestellter Gegenstand: \n", description = "Eine kleine, trockene Eichel ist aus der Robe des Flammendruiden gefallen.\n\nWarum sollte ein Druide der Flamme so etwas mit sich herumtragen?\n\nVielleicht würde jemand in Malfurions Bresche sie gerne mal sehen.", progress = nil, completion = "Faszinierend! Es scheint sich um eine Eichel zu handeln!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29246] = {title = "Lindert den Schmerz", objective = "Sammelt 4 flammenumwundene Herzen von wutentbrannten Pyrolords.", description = "Der Erzdruide kann ungeheure Schmerzen ertragen. Ich habe Opfer von Verbrennungen behandelt, die vierundzwanzig Stunden am Tag vor Schmerzen geschrien haben und ihre Verbrennungen waren nicht einmal halb so schlimm wie die, die Hamuul erlitten hat.\n\nNichtsdestotrotz kann ich sehen, dass er heute unter größeren Beschwerden leidet als normal. Bringt mir die Herzen der großen Feuerelementare im Südosten. Ich kann sie verwenden, um eine beruhigende Salbe für unseren Patienten herzustellen.", progress = "Diese Herzen werden uns genau das geben, was Hamuul benötigt, um sich zu erholen.", completion = "Ich muss mich sofort daran machen, die Salbe zuzubereiten. Diese Reagenzien verlieren jede Minute an Wirkungskraft.\n\nHabt Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29247] = {title = "Verarzten der Wunden", objective = "Besorgt 4 sulfurgetränkte Bandagen von den feurigen Ungetümen in Sethrias Nest.", description = "Wir haben hier beim Heiligtum ausreichend Vorräte an medizinischer Ausrüstung, aber wir dürfen nicht aus den Augen verlieren, dass wir uns im Krieg befinden. Hamuul ist nicht der Einzige, der Verbände benötigt.\n\nDie feurigen Ungetüme, die Sethrias Nest durchstreifen, tragen feuerresistente Bandagen, die Hamuul genauso gute Dienste leisten werden wie alle anderen Bandagen. Bringt mir diese Bandagen und ich werde sie dazu vorbereiten, sie dem Erzdruiden anzulegen.", progress = "Es gibt Leute, die sagen, dass das Sulfur in diesen Bandagen heilende Wirkung hätte. Ich persönlich bin davon nicht überzeugt, aber für den unwahrscheinlichen Fall, dass dem doch so ist, bin ich willens, den Geruch zu ertragen.", completion = "Vielen Dank, &lt;Klasse&gt;.\n\nIhr habt den Kriegsanstrengungen einen Dienst erwiesen. Opfer von Verbrennungen haben einen hohen Verbrauch an Verbänden und Hamuul ist da keine Ausnahme.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29248] = {title = "Den Druck lindern", objective = "Sammelt 100 Flammenschürerschuppen.", description = "Nachdem er so furchtbare Verbrennungen erlitten hat, leidet der Erzdruide Hamuul unter Ödemen - Schwellungen des Körpergewebes. Es kostet seine Pfleger große Mühen, die Schwellungen so weit in Schach zu halten, dass er atmen kann.\n\nNormalerweise würden wir die Schwellung behandeln, indem wir Einschnitte ins Fleisch vornehmen, aber er ist zu schwach dafür, <Name>. Ich kann ihn heute nicht heilen. Ich brauche Eure Hilfe.\n\nFlammenschürerschuppen helfen gegen die Schwellungen, aber man braucht davon eine ganze Menge.", progress = "Habt Ihr die Schuppen? Ich zögere, dem Erzdruiden weitere Schnittwunden zuzufügen, aber wir müssen irgendwie die Schwellung bekämpfen.", completion = "Ihr seid barmherzig, &lt;Volk&gt;. Mit diesen vielen Schuppen werden wir ihm zumindest für einen Tag keine weiteren Schnitte zufügen müssen. Vielleicht sogar für zwei.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29249] = {title = "Pflanzzeit", objective = "Pflanzt die Eichel in der Erde von Un'Goro bei Malfurions Bresche ein.", description = "Die Eichel scheint unversehrt zu sein.\n\n<Avrilla zuckt mit den Schultern.>\n\nLasst uns nicht um den heißen Brei reden: Pflanzen wir sie ein und sehen, was daraus wird.\n\nZum Glück für Euch haben wir etwas Resterde mitgebracht, um uns beim Aufbau unserer Basis zu helfen.\n\nIhr findet die Erde beim Friedhof, direkt im Osten.", progress = nil, completion = "Eine rote Blume erwächst aus der Erde.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29250] = {title = "Kontaktaufnahme", objective = "Begebt Euch nach Beutebucht und findet Bwembas Kontaktperson.", description = "Ihr seid keiner von den Zombies...\n\nEin Troll? Ich habe einen gesehen, direkt vor dem Ausbruch... Er hat uns gewarnt, gesagt, dass wir vorsichtig sein sollen... Aber es war zu spät.\n\nEuer Trollfreund ist nach Beutebucht gegangen, um sie zu warnen...", progress = nil, completion = "Ich werde Baron Revilgaz jetzt von der Zandalaribedrohung erzählen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\n4.1 - ZG Event - Booty Bay - Warning Booty Bay Quest Complete [DND]\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29251] = {title = "Die Interessen Beutebuchts", objective = "Spürt ein Artefakt auf, das die Trolle aus Zul'Gurub von Beutebucht fern halten könnte.", description = "Also, <Name>. Ihr habt uns schon gewaltig geholfen, aber das wird noch nicht reichen. Diese verrückten Trolle müssen aufgehalten oder zumindest von Beutebucht ferngehalten werden.\n\nIch werde jemanden losschicken, der das Geschehen im Auge behält, aber von Euch möchte ich, dass Ihr in Zul'Gurub eindringt und die Dinge in Bewegung setzt.\n\nIhr müsst mir zumindest etwas bringen, das diese Trolle aus Beutebucht fernhält.\n\nBringt das zustande und wir werden uns erkenntlich zeigen.", progress = "Habt Ihr etwas gefunden, <Name>?", completion = "Ihr habt sie alle getötet? Ich wünschte, das wäre genug, um mir keine Sorgen mehr zu machen. Aber diese Typen scheinen die Angewohnheit zu haben, von den Toten zurückzukehren.\n\nAh, was habt Ihr denn da?\n\nIhr meint, das könnte sie aus Beutebucht fernhalten?\n\nSo kommen wir ins Geschäft!\n\nOh, sagte ich, dass ich eine Belohnung für Euch habe? Natürlich.. gebt mir nur einen Moment, um die Belohnung zu finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29252] = {title = "Die Interessen Beutebuchts", objective = "Spürt ein Artefakt auf, das die Trolle aus Zul'Gurub von Beutebucht fern halten könnte.", description = "Ich wurde von Baron Revilgaz aus Beutebucht hergeschickt, damit ich sicherstelle, dass diese Trollbedrohung aufgehalten wird. Oder dass sie zumindest vor den Toren von Beutebucht aufgehalten wird.\n\nIch will Taten und Ergebnisse sehen.\n\nIhr geht da jetzt für mich rein und veranstaltet ein Gemetzel.\n\nIhr geht da jetzt rein und sucht mir etwas, das diese Trolle aus Beutebucht fernhält.\n\nBringt das zustande und wir werden uns erkenntlich zeigen.", progress = "Habt Ihr etwas gefunden, <Name>?", completion = "Ihr habt sie alle getötet? Ich wünschte, das wäre genug, um mir keine Sorgen mehr zu machen. Aber diese Typen scheinen die Angewohnheit zu haben, von den Toten zurückzukehren.\n\nAh, was habt Ihr denn da?\n\nIhr meint, das könnte sie aus Beutebucht fernhalten?\n\nSo kommen wir ins Geschäft!\n\nOh, sagte ich, dass ich eine Belohnung für Euch habe? Natürlich.. gebt mir nur einen Moment, um die Belohnung zu finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29253] = {title = "Eine glitzernde Beute", objective = "Holt Euch Eure Belohnung aus einer Kiste in der Statue auf der Janeirospitze.", description = "Es gibt etwas Plündergut innerhalb der Statue auf der Janeirospitze, gleich nordwestlich von Beutebucht im Schlingendorntal.\n\nBegebt Euch zur Statue und nehmt Euren Preis an Euch, <Klasse>.", progress = nil, completion = "Endlich Beute!", rewards = "Ihr bekommt:\n\nSchwarzes EisGoldene HalsketteStumpfe KroneEdelsteinbesetzte Armreife"}
MultiLanguageQuestData['de'][29254] = {title = "Kleiner Peitscher", objective = "Bringt Avrilla den Purpurpeitscher.", description = "Die kleine rote Blume wackelt zufrieden mit den Ranken. Sie scheint Euch zu mögen!\n\nMöglicherweise würde Avrilla gerne sehen, was aus der Eichel erwachsen ist.", progress = nil, completion = "Oh, hallo! Wer ist denn Euer kleiner Freund? Es ist Euch gefolgt, sagt Ihr?", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29255] = {title = "Glutharz", objective = "Besorgt Euch 5 Portionen Glutharz von verkohlten Soldaten und Bezwingern.", description = "Der Purpurpeitscher hat auf seinen Ranken einige aufbrechende Blasen entwickelt. Ohne Behandlung könnte dieser Zustand lebensbedrohlich werden.\n\nZum Glück produzieren die verkohlten Soldaten und Bezwinger in dieser Gegend eine wächserne Substanz mit Namen Glutharz, die die Qualen des Peitschers lindern könnte.\n\nBringt mir etwas von dieser Substanz und tötet diese garstigen Feuerelementare, während Ihr dabei seid.", progress = "Der Peitscher wächst sehr schnell.", completion = "Es riecht nicht besonders gut, aber es sollte dem Peitscher wieder auf die Beine helfen.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29257] = {title = "Magmolien, die ich stahl", objective = "Sammelt 8 Magmolien in den Magmaquellen im Norden.", description = "Wir haben eine neue Blumenart entdeckt, die in den Magmaquellen im Norden wächst. Erstaunlicherweise leben sie von reiner geschmolzener Lava!\n\nBitte geht und besorgt ein paar Exemplare dieser Pflanze für mich. Ich bin mir sicher, dass weitere Studien an diesen Pflanzen uns Aufschluss geben werden über unseren kleinen Freund hier.\n\nWo ich gerade von ihm spreche: er scheint ganz erpicht darauf zu sein, mit Euch zu gehen. Wollen wir hoffen, dass er sich benimmt.", progress = "Faszinierend! Je mehr Zeit ich in den Feuerlanden verbringe, desto mehr Hinweise erhalte ich, dass hier ein echtes Ökosystem am Werk ist.", completion = "Habt Dank, &lt;Name&gt;. Ich werde diese Proben sofort analysieren.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29258] = {title = "Meteoritenjagd", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][29261] = {title = "Zul'Aman Voodoo", objective = "Der Erschaffer dieses Voodoohaufens ist während des Vorgangs gestorben. Wenn Ihr ihn jedoch abschließen könntet, würden die Geister Euch vielleicht beschützen...", description = nil, progress = "Der Erschaffer dieses Voodoohaufens ist während des Vorgangs gestorben. Wenn Ihr ihn jedoch abschließen könntet, würden die Geister Euch vielleicht beschützen...", completion = "Die Schrifttafel enthält den letzten Zauberspruch, um die Magie des Voodoohaufens an Euch und Eure Gruppe zu binden!", rewards = "Ihr erlernt:\n\nMacht der Amani\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][29262] = {title = "Zul'Gurub Voodoo", objective = "Dieser mächtige Haufen Voodoohexenkunst verströmt starkes Mojo...", description = nil, progress = "Dieser mächtige Haufen Voodoohexenkunst verströmt starkes Mojo...", completion = "Als Ihr die Tafel in den Voodoohaufen steckt, zerreißt ein markerschütternder Schrei die Stille.", rewards = "Ihr erlernt:\n\nRuf des Raptors\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][29263] = {title = "Eine bittere Pille", objective = "Findet die Luftblasen des unterirdischen Magmawurms und besiegt ihn dann, indem Ihr ihn die bittere Pille schlucken lasst.", description = "Soweit es mich betrifft, gibt es kein Problem, das nicht mithilfe von Bomben gelöst werden kann. Und wenn eine Bombe das Problem nicht beim ersten Versuch löst... dann muss man eben eine größere Bombe nehmen.\n\nEs gibt da also diesen großen Wurm, der Leute bei der Lavapfütze im Norden frisst. Haltet Ausschau nach Luftblasen, um ihn zu finden. Greift ihn an, bis er sich bereit macht, zuzubeißen, und platziert dann die Bombe vor ihm. Und dann könnt Ihr Euch zurücklehnen und das Feuerwerk genießen.\n\nHmm... es gab noch eine andere Sache, die ich sagen wollte... Ach ja! Lasst Euch nicht fressen.", progress = nil, completion = "Ah, ich wusste, dass Rickets Bomben noch einmal nützlich sein würden. Es war nur eine Frage, ob wir etwas ausreichend Großes zum in die Luft sprengen finden würden.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29264] = {title = "Flammenschürer des Geschmolzenen Stroms", objective = "Erschlagt 8 Flammenschürer im Geschmolzenen Strom.", description = "Von allen Dienern Ragnaros' scheinen die Flammenschürer die hingebungsvollsten zu sein. Die meisten von ihnen weilen in dieser Höhle und bereiten sich auf einen weiteren Angriff vor. Wir haben hier vielleicht eine recht sichere Stellung, aber wir werden keine Überraschungsangriffe von diesem Gewürm tolerieren.\n\nNein, wir werden als erste zuschlagen.\n\nReißt sie in Stücke, <Name>.", progress = nil, completion = "Mir gefällt, wie Ihr arbeitet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29265] = {title = "Feuerblumen", objective = "Sammelt 5 Luzifarne.", description = "Meine Kollegin, Choluna, hat uns gebeten, alles, was wir an pflanzlichem Leben in den Feuerlanden finden, einzusammeln...\n\n... Ich weiß nicht, wessen Idee es war, Wissenschaftler an eine Kriegsfront zu schicken.\n\nNichtsdestotrotz, da Ihr nun schon mal in der Höhle sein werdet - und Dinge tötet - könnt Ihr auch genauso gut Ausschau nach Dingen halten, die am Boden wachsen.", progress = "Sie können überall wachsen. Haltet die Augen offen.", completion = "Diese Dinge werden nie aufhören, mich in Staunen zu versetzen. Ob sie nun wirklich Pflanzen sind oder einfach nur feingliedrige Steinformationen... der Umstand, dass sie unter solch feindlichen Bedingungen wachsen können, verblüfft mich einfach nur.\n\nIch muss sie sofort an Avrilla zur Analyse schicken.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29266] = {title = "DEPRECATED Zul'Gurub Voodoo (NYI)", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nRuf des Raptors\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][29267] = {title = "Glück im Unglück", objective = "Das Pantherkätzchen sieht Euch mit einem Ausdruck an, der sagt \"Bist du mein neuer Papa?\"", description = "So viel Gewalt, so viel Tod. Brüder sind gestorben, eine Mutter ist gestorben und nun wird ein Pantherjunges sterben, wenn sich niemand seiner annimmt.\n\nWerdet Ihr Euch für einen Moment von der Gewalt abwenden und für ein Pantherjunges sorgen?Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRemove See Quest Invis 15\n\nIhr bekommt:\n\nPantherjunges"}
MultiLanguageQuestData['de'][29268] = {title = "Glück im Unglück", objective = "Kümmert Euch um das Pantherjunge. Schließlich habt Ihr seine Mutter auf dem Gewissen.", description = "So viel Gewalt, so viel Tod. Brüder sind gestorben, eine Mutter ist gestorben und nun wird ein Pantherjunges sterben, wenn sich niemand seiner annimmt.\n\nWerdet Ihr Euch für einen Moment von der Gewalt abwenden und für ein Pantherjunges sorgen?", progress = nil, completion = "Das Pantherkätzchen sieht Euch mit einem Ausdruck an, der sagt \"Bist du mein neuer Papa?\"", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRemove See Quest Invis 15\n\nIhr bekommt:\n\nPantherjunges"}
MultiLanguageQuestData['de'][29269] = {title = "Vereint", objective = "Sprecht mit Kalecgos, um der Bitte zuzustimmen.", description = "Ich war mit ihrer Sicherheit betraut, und doch war sie es, die sich für mich opferte.\n\nIch ertrage es nicht, sie zu verlieren, <Name>. Ich muss Euch eine entscheidende Bitte stellen.\n\nNoch nie hat ein Sterblicher die Essenz eines wahren Drachen getragen, doch mit Eurer Erlaubnis würde ich eine Ausnahme machen.\n\nBitte, solange noch etwas Leben in ihr verweilt, erlaubt mir Tarecgosa an Euch zu binden.", progress = nil, completion = "Ich bin dankbar, &lt;Name&gt;.\n\nWärt Ihr nicht gewesen oder hättet Ihr abgelehnt, wäre Tarecgosa für mich für immer verloren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29270] = {title = "Die Zeit drängt", objective = "Sammelt 1000 Einheiten siedender Schlacke aus den Feuerlanden.", description = "Tarecgosa ist an Euch gebunden, <Name>, aber nur auf begrenzte Zeit. Die Macht eines Aspekts ist von Nöten, um ihre Essenz permanent zu versiegeln.\n\nMalygos' Nachfolger wird nicht vor der nächsten Mondfinsternis Azeroths bestimmt und der Bund, den Ihr mit ihr teilt wird nicht so lange überdauern.\n\nGlücklicherweise gibt es eine Möglichkeit, uns die nötige Zeit zu verschaffen. Es gibt mächtige Elemente, die die Dauer des Rituals verlängern können. Einige davon können in der Ebene des Feuers gefunden werden, mit der Ihr bereits vertraut seid.\n\nBesorgt sie, <Klasse>, und haltet Tarecgosa bis zur Mondfinsternis aufrecht.", progress = "Es tut gut, Euch wiederzusehen, <Name>.", completion = "Ich spüre, dass Tarecgosa noch immer bei Euch ist.\n\nDas habt Ihr gut gemacht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29271] = {title = "ound for Warmer Weather", objective = "[DEPRECATED]Speak to General Taldris Moonfall at Malfurion's Breach on the Molten Front.[DEPRECATED]We should be okay here for now, and they have need of you in the Firelands. You should go through the portal and help them out.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "[DEPRECATED]We should be okay here for now, and they have need of you in the Firelands. You should go through the portal and help them out.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29272] = {title = "Brauche... Wasser... Dringend...", objective = "Bringt Anren Schattensucher zum Eingang der Geschmolzenen Front.", description = "Brauche... Wasser... Dringend...", progress = nil, completion = "Ihr! Ihr seid derjenige, der Anren gerettet hat. Meinen besten Freund Anren.\n\nWir sind in dieser Höhle getrennt worden. Ich wusste nicht, wie ich ohne Anren weitermachen sollte.\n\nIhr seid ein einfallsreicher &lt;Klasse&gt;. Vielleicht werden wir Euch später noch einmal um Unterstützung bei unseren Erkundungsmissionen bitten. Mit Eurer Hilfe werden Anren und ich möglicherweise nicht länger mit dem entsetzlichen Risiko leben müssen, voneinander getrennt zu werden.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29273] = {title = "Wie heiß", objective = "Benutzt Tholos Thermometer, um die Temperatur in den drei großen Lavaseen des Schwarzrauchgipfels zu messen.", description = "Die Feuerfalken des Schwarzrauchgipfels können unglaublichen Temperaturen widerstehen. Man kann sie sowohl dabei beobachten, wie sie am Himmel ihre Kreise ziehen, als auch dabei, wie sie in flüssiger Lava schwimmen.\n\nStimmt doch, oder, Anren?\n\nWir würden gerne wissen, wie heiß diese Lava werden kann. Der Schwarzrauchgipfel verfügt über drei große Lavaseen. Benutzt dies, um in jedem von ihnen die Temperatur zu messen.", progress = nil, completion = "Diese Ergebnisse werden uns sehr dabei helfen, die Feuerfalken besser zu verstehen und - noch wichtiger - Alysrazar, ihre neue, feurige Königin.\n\nTholo und ich sind dankbar, dass Ihr uns hier ausgeholfen habt.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29274] = {title = "Die Hunde von Shannox", objective = "Sammelt 6 kleine Haufen Asche von Hundeknochen.", description = "Auf der größten Insel der Feuerlande haben unsere Truppen Probleme im Kampf gegen Shannox, den Jäger der Flammenschürer. Er verfügt nicht nur über unfehlbare Zielgenauigkeit, sondern er hält sich auch abgerichtete Hunde, die unseren Truppen Ärger ohne Ende bereiten.\n\nTholo, in seiner Weisheit, glaubt, dass es eine gute Idee wäre, die Biologie dieser Hunde zu studieren. Ich stimme natürlich mit Tholo überein.\n\nIhr werdet mehrere Hunde im Geschmolzenen Strom finden, unterhalb des Schmelzofens. Wir werden ihre Asche für unsere Studien benötigen.", progress = "Jede Information, die wir kriegen können, wird hilfreich sein, wenn wir unseren Männern helfen wollen, Shannox zu bezwingen.", completion = "Diese Asche mag genauso aussehen wie alle anderen Arten von Asche, die man auf dieser gottverlassenen Insel findet, aber vertraut mir... Ihr habt das richtige Zeug gefunden.\n\nWir werden es sofort untersuchen lassen.\n\nKehrt bald zurück. Ich verbringe zwar gerne Zeit mit Anren, aber Eure Gesellschaft ist uns auch sehr angenehm, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29275] = {title = "Fandrals Methoden", objective = "Beschafft Euch einen Flammendruidenstab, ein Flammendruidenzauberbuch, einen Flammendruidenreagenzienbeutel sowie einen Flammendruidengötzen.", description = "Die Druiden der Flamme... ein Orden von Druiden von dem Tholo und ich bis vor wenigen Wochen noch niemals gehört hatten. Und nun, unter der Führerschaft von Fandral Hirschhaupt, bedrohen sie den Erfolg unserer Mission mit ihrer Herrschaft über das Feuer.\n\nEs scheint, als würden sie einige Ausrüstungsgegenstände in den Feurigen Tiefen aufbewahren, im Nordosten. Wenn es uns gelingt, in den Besitz von einigen Teilen dieser Ausrüstung zu gelangen, haben wir vielleicht mehr Glück, wenn wir den Kampf zu Fandral tragen.", progress = "Vertraut mir - alle Informationen, die wir hier sammeln, werden uns sehr dabei helfen, zu verstehen, was die Quelle für Fandrals Macht ist.", completion = "Anren, seht was &lt;Name&gt; entdeckt hat! Das ist genau das, was wir brauchen!\n\nWir werden einige Zeit brauchen, um diese Ausrüstung anzusehen. In der Zwischenzeit ist Euch unser Dank gewiss.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29276] = {title = "Die Flammenspinnenkönigin", objective = "Sammelt 8 Proben Flammengift und 8 Proben sengende Spinnenseidenflüssigkeit.", description = "Das Gelege der Witwe, im Nordosten, ist nach Beth'tilac benannt, der riesigen Königin der Flammenspinnen. Ihre Netze und ihr Gift sind eine nagende Bedrohung unserer Hauptoffensivkraft.\n\nWir glauben, wenn wir die Flammenspinnen hier an der Geschmolzenen Front studieren, dann können wir diese Information einsetzen, um einen Erfolg gegen Beth'tilac zu erzielen. Setzt alle Euch zur Verfügung stehenden Methoden ein, um Proben ihres Gifts und ihrer Spinnenseidenflüssigkeit zu sammeln und kehrt dann zu meinem getreuen Freund Anren zurück.", progress = "Seid vorsichtig mit diesen Flüssigkeiten, <Name>. Wir wollen doch nicht, dass etwas davon verschüttet wird.", completion = "Ihr seid ein echter Gewinn für unsere Sache, &lt;Name&gt;. Tholo und ich danken Euch.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29278] = {title = "Lebendes Obsidium", objective = "Sammelt 10 Obsidiummeteoriten ein.", description = "Habt Ihr diese Feuerbälle gesehen, die vom Himmel kommen? Ich habe gesehen, wie einer von ihnen in die Felder im Norden eingeschlagen ist und das Gestein, was da gelandet ist, bestand aus purem Lebendem Obsidium!\n\nIch kann das Material benutzen, um ultra-robuste, hitzebeständige Rüstung und Waffen für unsere Truppen herzustellen. Könntet Ihr mir das Erz bringen?\n\nGeht zu den Magmaquellen und berührt einen der magnetischen Steine. Passt nur auf, wo Ihr steht, wenn der Feuerregen herunterkommt, und sammelt das Gestein ein, bevor es durch den Aufprall zerbricht.", progress = "Wie geht es voran? Habt Ihr schon Meteoriten gefunden?", completion = "Fantastisch! Dann kann ich mich ja jetzt an die Arbeit machen.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29279] = {title = "Befüllung des Mondbrunnens", objective = "Sammelt 125 Abzeichen des Weltenbaums.", description = "Wir haben diesen Mondbrunnen erschaffen, doch erfüllt er wenig Zweck, solange er noch nicht mit den Wassern des Brunnens der Ewigkeit gefüllt wurde.\n\nMit einem aktiven Mondbrunnen wäre es uns möglich, unsere Lebensmittelvorräte zu segnen, zu denen Ihr selbstverständlich Zugang bekommen würdet. Es sollte uns auch möglich sein, den Segen des Mondbrunnens zu nutzen, um Euch Schutz vor dem Feuer zu gewähren.\n\nSobald Ihr genügend Abzeichen zusammen habt, solltet Ihr mit Matookla am Heiligtum von Malorne sprechen. Sie wird in der Lage sein, für den sicheren Transport des heiligen Wassers zu sorgen.", progress = "Wie kann ich Euch helfen, <Name>?", completion = "Natürlich. Ich werde mich sofort darum kümmern, dass die heiligen Wasser durch das Portal gebracht werden.\n\nDanke, &lt;Klasse&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nTenaron Sturmgewalt beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29280] = {title = "Lebensspendende Wasser", objective = "Sprecht mit Ayla Schattensturm bei Malfurions Bresche.", description = "Ich habe die Wasser des heiligen Mondbrunnens zu Malfurions Bresche gesandt, wie Ihr es gewünscht habt. Ayla ist gut darin ausgebildet, sich um sie zu kümmern. Ihr solltet zu ihr zurückkehren und sehen, welche Segen sie für Euch dort bereithält.", progress = nil, completion = "Es wird Euch freuen, zu hören, dass die Wasser hier sicher angekommen sind. Nun da der Mondbrunnen gefüllt ist und der Schatten des Wachenden Baums über uns liegt, kann ich manchmal sogar mehrere Momente lang vergessen, dass wir in den Feuerlanden sind.\n\nIch habe den Segen des Mondbrunnens auf diese Bäume und Büsche verteilt. Nehmt die Frucht mit Euch, bevor Ihr geht. Sie ist erfrischender als Ihr Euch vorstellen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29281] = {title = "Verstärkung", objective = "Sammelt 125 Abzeichen des Weltenbaums.", description = "Diesen Druiden fehlen die Werkzeuge, um ihre Aufgaben hier vernünftig zu erledigen. Ich hab' aber 'nen Kumpel beim Schrein des alten Hirschbocks, auf der anderen Seite des Portals. Wenn wir uns wiedertreffen sollten, dann hätten wir sicher ein bisschen Spielzeug, das wir gegen Ragni und seine Kumpane einsetzen könnten.\n\nNehmt einige der Abzeichendinger und geht damit zu Matookla. Fragt sie nach Ricket. Wir brauchen sie hier, damit wir ordentlich Ärger anzetteln können.", progress = "Ja, <Name>?", completion = "Ich hatte mich schon gefragt, ob sich diese zwei nicht noch als nützlich erweisen würden. Sie schienen recht fehl am Platz zu sein, seitdem sie angekommen sind.\n\nIch habe Ricket vor ein paar Augenblicken hier in der Gegend gesehen. Ich werde sie mit Vergnügen mit Euch zusammen durch das Portal schicken. Auf der Seite wird sie auch weniger Gefahr laufen, das lokale Pflanzenleben in die Luft zu sprengen.\n\nLasst mich mal sehen... wo ist sie...?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRickets Rakete beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29282] = {title = "Gut bewaffnet", objective = "Sprecht mit Ricket bei Malfurions Bresche.", description = "Ricket sollte zusammen mit Damek bei Malfurions Bresche sein, wie von Euch erbeten. Ich bin mir allerdings nicht sicher, dass Ihr wirklich wisst, worauf Ihr Euch mit den beiden einlasst.\n\nWo wir gerade davon sprechen: Ihr solltet vermutlich mal nach ihnen sehen... um sicherzugehen, dass sie es noch nicht geschafft haben, den Wachenden Baum in die Luft zu jagen. So lange Ihr sie mit Elementaren beschäftigt haltet, sollte die Wahrscheinlichkeit von \"Unfällen\" an der Bresche dramatisch sinken.", progress = nil, completion = "Hey Ihr! Gut, Euch wiederzusehen!\n\nIch habe mich hier eigentlich schon ganz gut eingelebt! Es ist schön, mal wieder Zeit mit dem guten alten Damek zu verbringen. Ich hätte nie gedacht, dass ich mich mal so gut mit einem Zwerg verstehen würde, aber was die wichtigen Dinge angeht, da liegen er und ich auf derselben Wellenlänge.\n\nMacht Ihr mal Euer Ding und sorgt Euch nicht um uns. Wenn wir irgendwelches nettes Spielzeug für Euch haben, dann werden wir es Euch wissen lassen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29283] = {title = "Rufen der Urtume", objective = "Sammelt 125 Abzeichen des Weltenbaums.", description = "Die Urtume warten in Hyjal. Die Feuerlande werden sich als gefährlicher Ort herausstellen, wenn man ihre... Zusammensetzung bedenkt, aber ihre Stärke wird uns sehr von Nutzen sein, wenn wir uns Ragnaros' Leutnants stellen müssen.\n\nSammelt Eure Abzeichen und sprecht mit Ahnenzweig am Heiligtum von Malorne. Wenn sie an unserer Seite marschieren sollen, so wäre er derjenige, der sie durch das Portal anführen würde.", progress = "Seid gegrüßt, junges Wesen.", completion = "Ich verstehe. Wir sind bereit. Wir werden uns dem Zug anschließen und Euch auf der am weitesten entfernten Seite des Portals treffen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAhnenzweig beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29284] = {title = "Hilfe der Urtume", objective = "Sprecht mit Ahnenzweig bei Malfurions Bresche.", description = "Die Urtume haben den Wert Eurer Weisheit erkannt und sich bei Malfurions Bresche niedergelassen. Ihr solltet Ahnenzweig aufsuchen. Ich bin sicher, er würde sich freuen, von Euch zu hören.", progress = nil, completion = "Ihr habt einen weisen Zeitpunkt ausgewählt, um zu uns zu kommen, &lt;Klasse&gt;. Ich war besorgt gewesen, ob wir in diesem Reich gegen die Elemente bestehen könnten, aber der Schutz des Wachenden Baums hat sich als mehr als ausreichend erwiesen.\n\nWir werden alles tun, um Euch in Euren Bemühungen zu unterstützen. Dorrzweig hat sich mit Euren anderen Verbündeten getroffen und bespricht mit ihnen Wege, einige von Ragnaros' Leutnants in die Ecke zu treiben. Ihr solltet mit ihnen sprechen, wenn die Zeit gekommen ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29285] = {title = "Ausrichtung", objective = "Begleitet Kalecgos zum Konzil der blauen Drachen.\n\nSprecht mit Kalecgos in Kaltarra, wenn Ihr bereit seid.", description = "Die Zeit der Wahl ist gekommen, <Name>.\n\nObwohl nur Mitglieder des blauen Drachenschwarms dort erlaubt sind, macht die Bindung mit Tarecgosa Eure Anwesenheit dort erforderlich.\n\nIch muss Euch bitten, ihre Form anzunehmen und in ihrem Namen abzustimmen.\n\nTrödelt nicht, der Zeitpunkt der Mondfinsternis ist nahe...", progress = "Es ist vollbracht, <Klasse>.", completion = "Arygos' Pläne wurden durchkreuzt, und zwar größtenteils wegen Eurer Mühen, &lt;Klasse&gt;.\n\nAls meine erste Tat als Aspekt des blauen Drachenschwarms wird Euer Bund mit Tarecgosa nun ein stabiler sein.\n\nDie Macht, die diesen Bund einst getragen hat, übertrage ich nun in Euren Stab.\n\nMöge der Runenstab von Nordrassil Euch wohl dienen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAlignment Completion Aura\n\nIhr bekommt:\n\nRunenstab von Nordrassil"}
MultiLanguageQuestData['de'][29287] = {title = "Der Gipfel des Interesses", objective = "Besorgt ein Ei eines Feuerfalken von der Spitze des Schwarzrauchgipfels.", description = "Diese Feuerfalken sind Wesen aus Feuer, aber sie zeigen viel von dem Verhalten, dass wir auch bei den Vögeln in unserer Heimat beobachtet haben. Ich frage mich, was wohl ihr Ursprung sein mag.\n\nAber zurück zum Punkt - ich glaube, es könnte uns gelingen, sie abzurichten. Sie zähmen, wenn Ihr es so sagen wollt. Sie gegen unsere Feinde einsetzen.\n\nIch möchte, dass Ihr Euch eins ihrer Eier vom Schwarzrauchgipfel besorgt. Wenn Ihr es heil zu mir zurückbringt, werde ich mich um den Rest kümmern.", progress = "Ist es Euch gelungen, ein Ei zu besorgen?", completion = "Das wird perfekt funktionieren! Kommt in einem oder zwei Tagen wieder und wir werden sehen, wie sich die Dinge entwickelt haben.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFire Hawk Egg Retrieved\n\nIhr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29288] = {title = "Junges Blut", objective = "Besorgt Euch 5 Feuerfalkenjunge.", description = "Unsere Späher kommen mit Berichten von Feuerfalkenjungen überall auf dem Gipfel zurück... ihre Eier müssen also vor Kurzem ausgebrütet worden sein. Und, was noch besser ist: sie scheinen extrem gelehrig zu sein.\n\nIch weiß, es mag sich wie eine seltsame und vielleicht auch geschmacklose Bitte anhören, aber wenn es Euch gelänge, ein paar dieser Jungtiere zu mir zu bringen, dann könnte ich sie vielleicht ausbilden, um uns in unseren Kriegsanstrengungen zu helfen.\n\nSeid Ihr willens?", progress = "Ich kann mich einfach nicht entscheiden, wie ich diese Kreaturen sehen soll. Sie verhalten sich genauso wie andere Vögel, aber sie sind ganz offensichtlich an diesem feurigen Ort heimisch.\n\nIch frage mich, warum Ragnaros und seine Diener keine Versuche unternommen haben, sie gegen uns einzusetzen...", completion = "Es sieht so aus, als hätten sie Eure Handschuhe ein wenig angesengt, aber ich sehe ansonsten keine weiteren Schäden. Gut gemacht, &lt;Klasse&gt;.\n\nKommt in den nächsten paar Tagen wieder, um zu sehen, wie es mit der Ausbildung vorangeht.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFire Hawk Egg Retrieved\n\nIhr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29289] = {title = "Die Sorgen einer Mutter", objective = "Bezwingt die Feuerfalkenmatriarchin.", description = "Wenig überraschend hat die Matriarchin Anstoß daran genommen, dass wir ihre Jungen für unsere eigenen Zwecke ausgebildet haben. Verständlich... und eigentlich ein wenig tragisch. In dieser Sache sind wir die Bösen.\n\nJetzt ist aber nicht die Zeit, über solche Dinge nachzudenken. Diese Kreaturen sind Wesen aus Feuer und bei mehr als einer Gelegenheit haben sie Leben in unseren Reihen gefordert. Nun da ihre Matriarchin verärgert ist, ist die Gefahr immens gewachsen.\n\nIch brauche jemanden, der ihren Zorn besänftigt, und ich fürchte, dass Ihr dazu am fähigsten seid.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29290] = {title = "Feuer am Himmel", objective = "Benutzt den dressierten Feuerfalken, um 100 Flammenschürersalamander, 40 Aschenweberspinnen und 3 geschmolzene Lords, die in den Feuerlanden häufig anzutreffen sind, zu töten.", description = "Schaut Euch das an! Es ist unglaublich! Gerade mal vor zwei Tagen geboren und schon ausgewachsen. Traurigerweise fürchte ich, dass ihre Lebensdauer entsprechend kurz sein wird, deshalb sollten wir die Zeit ausnutzen, die wir haben.\n\nSeine Ausbildung ist erstaunlich gut verlaufen. Ich möchte, dass Ihr derjenige seid, der ihn auf die Masse an feindlichen Streitkräften loslässt, die sich in der Nähe von Ragnaros' Unterschlupf versammelt haben.\n\nZeigt keine Gnade, <Volk>.", progress = "Einige unserer fähigsten Streitkräfte sind bereit, Ragnaros selbst anzugreifen. Wenn diese Angriffe gut laufen, sind wir vielleicht in der Lage, ihnen die Gelegenheit zu geben, die sie benötigen.", completion = "Ich nehme an, Euer Angriff war erfolgreich! Großartig. Dies könnte ein Schlüsselmoment im Durchbrechen von Ragnaros' Verteidigung sein.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCancel Fire Hawk Egg Retrieved\n\nIhr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29291] = {title = "Mit Schirm, Charm und Bomben", objective = "Der folgende Zauber wird auf euch gewirkt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFire Hawk Egg Retrieved"}
MultiLanguageQuestData['de'][29292] = {title = "Falkenfeuer", objective = "Der folgende Zauber wird auf euch gewirkt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCancel Fire Hawk Egg Retrieved"}
MultiLanguageQuestData['de'][29293] = {title = "Gesengte Flügel", objective = "Rettet 5 verletzte Druiden der Kralle auf dem Schwarzrauchgipfel.", description = "Viele unserer Sturmkrähen sind vorausgeflogen, um die Spitze auszukundschaften und zu versuchen, einige der Feuerfalkeneier zu besorgen, allerdings mit wenig Erfolg, fürchte ich. Die Thermalwinde machen sicheres Fliegen fast unmöglich und die Feuerfalken sind auch nicht gerade besonders freundlich.\n\nIch möchte, dass Ihr Euch dorthin begebt und so viele Druiden rettet, wie Ihr könnt. Ich habe Schienen, Verbände, Brandsalben, Riechsalze... alles, was Ihr braucht, um ihnen wieder auf die Beine zu helfen, vorausgesetzt, sie leben noch. Bitte beeilt Euch und helft allen, die Ihr finden könnt.", progress = nil, completion = "Mehrere unserer Brüder und Schwestern sind hier vorbeigekommen, als sie in die Sicherheit des Wachenden Baums zurückkehrten. Ihr habt da draußen sehr gute Arbeit geleistet, &lt;Name&gt;. Danke.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29294] = {title = "nimate Embers", objective = "[DEPRECATED]Retrieve 6 Animate Embers.[DEPRECATED]Several of our scouts have reported seeing what seemed to be living flames skittering around the surfaces of Fireplume Peak.\n\nIf the reports are accurate, we need these for study immediately. We've yet to fully understand where all of the attacking elementals come from, and these could well lend us significant insight.Ihr bekommt:\n\n", description = "[DEPRECATED]Several of our scouts have reported seeing what seemed to be living flames skittering around the surfaces of Fireplume Peak.\n\nIf the reports are accurate, we need these for study immediately. We've yet to fully understand where all of the attacking elementals come from, and these could well lend us significant insight.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29295] = {title = "Je größer...", objective = "Sammelt 10 Stücke lebendiges Obsidium von den Obsidiumbestrafern auf dem Schwarzrauchgipfel.", description = "Ihr wollt Euch ja wohl nicht in DER Ausstattung den feurigen Ungetümen stellen, oder? Wenn Ihr nicht meine aus Obsidium hergestellten Sachen tragt, dann werdet Ihr sofort in Flammen aufgehen! Und selbst wenn Ihr sie tragt, Ihr könnt nie genug von den guten Dingen haben.\n\nSchaut, <Bruder/Schwester>, ich kann Euch die beste Rüstung herstellen, die für Gold zu haben ist, aber ich brauche zuerst reines, unverhüttetes lebendiges Obsidium.\n\nDie Obsidiumbestrafer auf dem Schwarzrauchgipfel bestehen im wahrsten Sinne des Wortes aus dem Zeug. Geht und tötet sie und sammelt ihre Überreste ein.", progress = "Habt Ihr mir die Waren mitgebracht?", completion = "Das sollte genügen. Gute Arbeit, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29296] = {title = "Territoriale Vögel", objective = "Tötet 5 Feuerfalken.", description = "Die Feuerfalken sind aufgebracht über unsere fortgesetzte Anwesenheit. Sie werden langsam extrem feindselig und nicht nur auf die übliche territoriale Art. Ich mache mir Sorgen, dass sie sich schon bald dem Angriff auf unseren Baum anschließen werden, wenn wir sie sich selbst überlassen - und ich bin mir nicht sicher, ob wir in der Lage sein werden, damit umzugehen.\n\nBegebt Euch zum Schwarzrauchgipfel und tut, was Ihr tun müsst, um sie in Schach zu halten. Im Moment ist mir unsere Sicherheit um einiges wichtiger als ihre, handelt also entschlossen.", progress = "Je eher, je besser, <Name>. Ihre Aggression könnte sie weiter von ihrem Nest führen, wenn wir sie unkontrolliert sich selbst überlassen.", completion = "Gut gemacht, &lt;Name&gt;. Es ist gut zu wissen, dass ich auf Euch zählen kann.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29297] = {title = "Wo ist das Vögelchen?", objective = "Tötet drei Druiden der Flamme, während sie in Feuerkrähengestalt unterwegs sind, mit dem Vogelpiekser.", description = "Hirschhaupts Druiden schlagen an der Wildflammenspitze im Nordosten ordentlich zu.\n\nDie Druiden fliegen in Gestalt von Feuerkrähen über uns und greifen an, wenn wir es am wenigsten erwarten. Das Schlimmste ist, dass sie genau wissen, wie sie außerhalb unserer Reichweite bleiben!\n\nWir wären vollkommen hilflos, wenn mir Damek nicht seine getreue Harpune geliehen hätte. Er sagt, dass diese Waffen gerade und zuverlässig fliegen, selbst in dieser dicken Luft.\n\nNehmt die Waffe des Zwergs und holt ein paar dieser Vögel vom Himmel!", progress = nil, completion = "Diese verdammten Vögel sind tot? Gut, dass wir die los sind!", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29298] = {title = "Verrußtes Medaillon", objective = "Bringt das verrußte Medaillon zu Rabine Saturna in Nachthafen auf der Mondlichtung.", description = "Auf der Oberseite dieses Medaillons sind einige kleine, blattförmige Schnitzereien zu sehen, aber alle anderen Details haben sich mit der Zeit abgescheuert oder sind durch Feuer verbrannt worden. Es scheint druidischer Natur zu sein.\n\nDie meisten Druiden besuchen die Mondlichtung während ihrer Ausbildung. Wenn Euch jemand dabei helfen kann, die Herkunft dieses Medaillons herauszufinden, dann ist das Rabine Saturna in Nachthafen.", progress = "Ja, junger <Volk>?", completion = "Was haben wir denn da? Eine Halskette? Nein, ein Medaillon...\n\nOh je...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29299] = {title = "Manche mögen's heiß", objective = "Beobachtet den Purpurpeitscher, wenn er von 6 Glutlachen trinkt. Glutlachen entstehen durch den Kampf gegen Glutspeiskorpione.", description = "Ich bin in meinen Studien vorangekommen, <Name>. Basierend auf den Dingen, die wir in der lokalen Flora beobachtet haben, ist es durchaus möglich, dass Euer Peitscher auch supererhitzte Flüssigkeiten als Hauptnahrungsquelle verträgt.\n\nIch hätte gerne, dass Ihr mir bei einem kleinen Experiment helft. Die Glutspeiskorpione, die in den Magmaquellen im Norden hausen, versprühen im Kampf brennende Feuerlachen.\n\nNehmt den Peitscher und beobachtet seine Reaktion auf die Glutlachen der Skorpione.", progress = nil, completion = "Hat es funktioniert? Meine Theorie war also korrekt?", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29302] = {title = "Aufdecken verborgener Geheimnisse", objective = "Beobachtet die in dem verrußten Medaillon gespeicherten Erinnerungen.", description = "Die Initialen auf dem Medaillon scheinen verblasst zu sein, aber ich kann eine Macht darin spüren, die auf nur einen möglichen Besitzer schließen lässt:\n\nLeyara, die Druidin der Flamme.\n\nTretet zurück und wir werden sehen, welche Überraschungen dieses Medaillon bereithält.", progress = nil, completion = "Wenn Leyara den Krieg der Sandstürme miterlebt hat, dann ist es wahrscheinlich, dass sie Fandral kannte - und seinen verstorbenen Sohn, Valstann - und zwar sehr viel näher, als wir jemals vermutet hätten.\n\nEs scheint, dass Eure Reise hier noch nicht endet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29303] = {title = "Tragödie und Familie", objective = "Bringt das verrußte Medaillon zu dem nachtelfischen Grab in der Nähe von Astranaar im Eschental.", description = "Es war sehr einsichtsvoll von Euch, mir dieses Medaillon zu bringen, <Name>. Ich bin einer der wenigen, die wissen, wo Valstanns Leichnam begraben ist.\n\nIhr findet seine letzte Ruhestätte auf einem kleinen Friedhof, südöstlich von Astranaar im Eschental. Bringt dieses Medaillon zu dem Ort und vielleicht eröffnet es Euch weitere Erinnerungen.\n\nLebt wohl, <Name>, und viel Glück für Eure Reise.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29304] = {title = "Die Hunde des Krieges", objective = "Tötet 5 Aschenhunde oder uralte Aschenhunde.", description = "Unsere Truppen werden von entfesselten Monstrositäten in die Knie gezwungen - Aschenhunde aus den geschmolzenen Tiefen.\n\nDiese Hunde fürchten nichts und niemanden und werden nicht innehalten, bis ihr Blutdurst befriedigt ist. Unsere Streitkräfte können sie gerade so zurückhalten.\n\nGeht und schließt Euch den Verteidigern auf den Aschenfeldern oder im Geschmolzenen Strom an. Vielleicht gelingt es Euch, ihre Anzahl ein wenig zu reduzieren.", progress = nil, completion = "Gut, &lt;Klasse&gt;. Der Feind mag hart sein, aber Ihr habt heute bewiesen, dass Ihr härter seid.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29305] = {title = "Ein Stich ins Herz", objective = "Tötet den Leutnant der Flamme.", description = "Einer von Ragnaros' Leutnants hat sich auf Ragnaros' Ebenen gezeigt, dem von Mauern umgebenen Bereich im Nordosten von uns.\n\nIch hatte gehofft, Euch direkt nach Eurer Rückkehr wieder aussenden zu können, aber ich fürchte, dass Dorrzweig und einige unserer Streitkräfte sich bereits in die Schlacht gestürzt haben. Ihr solltet Euch beeilen.\n\nEs sollte Euch möglich sein, diese Klippe direkt hier hinunterzuspringen und sie so schnell zu erreichen.", progress = nil, completion = "Sehr gut gemacht, &lt;Name&gt;! Das sollte sie erheblich hemmen.\n\nWenn wir das durchhalten, sollten wir den Kampf leicht zu Ragnaros selbst tragen können.", rewards = "Ihr bekommt:\n\nAbzeichen des Weltenbaums"}
MultiLanguageQuestData['de'][29307] = {title = "Herz der Flamme", objective = "Verstärkt den Runenstab von Nordrassil mit 250 schwelenden Essenzen und besorgt Euch das Herz der Flamme.", description = "Ihr seid <der/die> erste Sterbliche, <der/die> einem Drachenkonzil beiwohnt und gehört zu den einzigen Wesen in Azeroth, die an der Wahl eines Aspekts teilnehmen.\n\nMein Aufstieg hat mich mit unglaublicher Macht erfüllt. Ich habe mir erlaubt, Tarecgosas Band mit Euch zu stärken, obschon sie ein... permanenteres Zuhause benötigt.\n\nIch möchte, dass Ihr ein letztes Mal in die Ebene des Feuers reist und mir das Herz von Ragnaros bringt.\n\nWenn wir uns das nächste Mal begegnen, werde ich Euch angemessen für alles, was Ihr getan habt, belohnen können.", progress = "Ein feiner Tag für eine Zeremonie. Findet Ihr nicht, <Name>?", completion = "Ihr habt Großes geleistet, &lt;Name&gt;.\n\nBereitet Euch nun darauf vor, die Belohnung eines Helden zu empfangen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29308] = {title = "Herz der Flamme", objective = "Verstärkt den Runenstab von Nordrassil mit 250 Essenzen der Seelenflamme und besorgt Euch das Herz der Flamme.", description = "Ihr seid <der/die> erste Sterbliche, <der/die> einem Drachenkonzil beiwohnt und gehört zu den einzigen Wesen in Azeroth, die an der Wahl eines Aspekts teilnehmen.\n\nMein Aufstieg hat mich mit unglaublicher Macht erfüllt. Ich habe mir erlaubt, Tarecgosas Band mit Euch zu stärken, obschon sie ein... permanenteres Zuhause benötigt.\n\nIch möchte, dass Ihr ein letztes Mal in die Ebene des Feuers reist und mir das Herz von Ragnaros bringt.\n\nWenn wir uns das nächste Mal begegnen, werde ich Euch angemessen für alles, was Ihr getan habt, belohnen können.", progress = "Ein feiner Tag für eine Zeremonie. Findet Ihr nicht, <Name>?", completion = "Ihr habt Großes geleistet, &lt;Name&gt;.\n\nBereitet Euch nun darauf vor, die Belohnung eines Helden zu empfangen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29309] = {title = "Der Stoff, aus dem Legenden sind", objective = "Sprecht mit Hallegosa.", description = "Es ist eine Ehre, Euch kennen zu lernen, <Volk>.\n\nEure Taten sind bei den Kreaturen Azeroths in aller Ohren, sowohl sterblich als auch unsterblich.\n\nIch werde Kalecgos nach seiner Ankunft das Herz von Ragnaros präsentieren. Seine Macht wird dazu verwendet werden, Eure Waffe noch zu verstärken.\n\nDie Zeremonie beginnt in Kürze. Ich wurde dazu ernannt, Euch dort hinzuführen, sobald Ihr bereit seid.", progress = "Seht! Drachenzorn, Tarecgosas letzte Ruhe.", completion = "Eure Heldentaten werden nie vergessen werden, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nPlayer Trophy Initialize\n\nIhr bekommt:\n\nDrachenzorn, Tarecgosas letzte Ruhe"}
MultiLanguageQuestData['de'][29310] = {title = "Die Trendwende", objective = "Bringt das verrußte Medaillon zu dem kleinen Grabstein bei Leyaras Trauer beim Hyjal.", description = "An dem Tag, an dem Leyara Hamuul angriff, hat sie in der Nähe von einigen Ruinen am Hyjal gewartet, nordwestlich des Geheilten Hyjal. Sie hat sich zu der Zeit seltsam verhalten: gefasst, ruhig und mit Blick in die Ferne. Möglicherweise ist der Ort für sie wichtig.\n\nDas Medaillon könnte vielleicht reagieren, wenn es an diesen Ort gebracht wird.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29311] = {title = "Der Rest ist Geschichte", objective = "Bringt das verrußte Medaillon zu Malfurion an der Geschmolzenen Front.\n\nBereitgestellter Gegenstand: \n", description = "In ihren Erinnerungen hat Leyara von Malfurion gesprochen. Die Tragödien ihrer Vergangenheit sind - zumindest ihrer Meinung nach - hauptsächlich seinen Handlungen geschuldet.\n\nMalfurion muss sich an Leyara erinnern, bevor sie eine Druidin der Flamme wurde. Ihr entschließt Euch, ihm das Medaillon in die Feuerlande zu bringen. Hoffentlich kann er alle offenen Fragen beantworten.", progress = nil, completion = "Ja, ich kannte Leyara und ich war mir ihres Zorns bewusst, selbst bevor sie sich den Druiden der Flamme anschloss. Einst war sie eine vielversprechende junge Druidin. Leider sind Familienbande oft stärker als die Macht der Vernunft und letztendlich hat sie sich dafür entschieden, Fandral auf seinem verräterischen Pfad zu folgen.\n\nIhr solltet dieses Medaillon behalten, &lt;Name&gt;. Möge es Euch daran erinnern, dass jeder von uns auf seinem eigenen Pfad durchs Leben geht... und dass einige Pfade einfacher sind als andere.", rewards = "Ihr bekommt:\n\nLeyaras Medaillon"}
MultiLanguageQuestData['de'][29312] = {title = "Der Stoff, aus dem Legenden sind", objective = "Sprecht mit Hallegosa.", description = "Es ist eine Ehre, Euch kennen zu lernen, <Volk>.\n\nEure Taten sind bei den Kreaturen Azeroths in aller Ohren, sowohl sterblich als auch unsterblich.\n\nIch werde Kalecgos nach seiner Ankunft das Herz von Ragnaros präsentieren. Seine Macht wird dazu verwendet werden, Eure Waffe noch zu verstärken.\n\nDie Zeremonie beginnt in Kürze. Ich wurde dazu ernannt, Euch dort hinzuführen, sobald Ihr bereit seid.", progress = "Seht! Drachenzorn, Tarecgosas letzte Ruhe.", completion = "Eure Heldentaten werden niemals in Vergessenheit geraten, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nPlayer Trophy Initialize\n\nIhr bekommt:\n\nDrachenzorn, Tarecgosas letzte Ruhe"}
MultiLanguageQuestData['de'][29313] = {title = "Das Geheimnis des perfekten Kimchis", objective = "Findet 8 vergrabene Kimchikrüge in Darnassus.", description = "Meine Familie stellt seit Generationen das beste Kimchi in ganz Darnassus her, <Name>. Das Geheimnis ist eine ganz einfache Sache, aber sie macht den ganzen Unterschied.\n\nWir vergraben die Krüge im Boden, bis der Inhalt bereit ist, serviert zu werden, und die letzte Ladung hat gerade diesen Punkt erreicht. Ihr könnt die Krüge überall in der Stadt in Erdhügeln vergraben finden. Würdet Ihr mir helfen, sie einzusammeln, solange ihr Inhalt genau richtig ist?", progress = "Habt Ihr die Krüge gefunden?", completion = "Habt Dank, &lt;Name&gt;. Ich hätte sie nie alle rechtzeitig finden können und es wäre doch schade gewesen, so viel gutes Kimchi zu verpassen!", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29314] = {title = "Gedenkt der Vorfahren", objective = "Sammelt die gesegneten Reiskuchen aus dem Tempel des Mondes ein.", description = "Die Lebenden sind nicht die einzigen, die Nahrung brauchen. Eine meiner Pflichten besteht darin, die Reiskuchen zuzubereiten, die den Vorfahren dargebracht werden. Normalerweise hat meine oberste Schülerin die Ehre, die Kuchen zum Tempel des Mondes zu bringen, damit sie dort gesegnet werden, und sie dann den Vorfahren darzubieten. Würdet Ihr, da sie heute nicht in der Stadt ist, diese Pflicht an ihrer Stelle übernehmen?", progress = "Dies ist der Schrein, von dem der Ausbilder gesprochen hat.", completion = "&lt;Ihr plaziert die Reiskuchen um den Schrein herum, der anfängt, sanft zu leuchten. Euch überkommt ein mildes Gefühl der Dankbarkeit.&gt;", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29315] = {title = "Fungourmet", objective = "Besorgt 12 Abflusskappen. Liefert die Pilze bei Eunice Burch in Unterstadt ab.", description = "Manche Köche beschweren sich darüber, dass unsere geliebte Unterstadt nicht mit den nötigen Zutaten aufwarten kann, um wahrhaftig köstliche Speisen zuzubereiten.\n\nWas für jammernde Einfaltspinsel. Dabei gibt es hier doch solche Köstlichkeiten!\n\nSammelt einige der ranzigen, schleimigen Abflusskappen, die entlang der Nordwestkanäle der Unterstadt wachsen und bringt sie zu mir.", progress = "Habt Ihr genügend Abflusskappen finden können?", completion = "Die riechen ja einfach nur widerlich. Perfekt!", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29316] = {title = "Grundnahrungsmittel", objective = "Helft den Bewohnern der Terrasse der Handwerker und der Terrasse der Händler Reis in Mehl zu verwandeln, indem Ihr den Inhalt der Reiskörbe zermahlt.", description = "Es gibt bestimmte Dinge, die jeder braucht, vom Koch im kleinsten Haushalt bis zum obersten Küchenchef. Eines der wichtigsten Grundnahrungsmittel der Stadt ist Reismehl. Die meisten Familien haben mindestens einen Korb Reis in ihrem Haus und das gilt genauso für die Bewohner der Terrassen der Handwerker und der Händler.\n\nIch trage meinen Schülern oft auf, dabei zu helfen, Reis in Mehl zu verwandeln, da es eine gute Übung und eine Endlosaufgabe ist. Warum versucht Ihr es nicht einmal?", progress = nil, completion = "Nur durch viel Fleiß und Mühe können wir sicherstellen, dass es genügend Mehl für alle gibt. Danke für Eure Hilfe, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29317] = {title = "Fischkopp", objective = "Armand Kromwell möchte, dass Ihr für Apothekermeister Faranell einen abgetrennten Monstrositätenkopf aus den Kanälen von Unterstadt angelt.", description = "Es hat einen... Vorfall mit einer Orcwache und einer von Apothekermeister Faranells Monstrositäten gegeben.\n\nOffenbar hat der Aufseher der Kor'kron ihr kurzerhand den Kopf abgeschlagen und ihn in den Schleim getreten.\n\nFaranells Lehrlinge suchen schon seit Stunden danach, können das Ding aber einfach nicht finden. Würdet Ihr versuchen, nach ihm zu angeln? Ich bin sicher, dass der alte Knabe sehr dankbar wäre.", progress = "Ihr habt nicht rein zufällig einen abgetrennten Monstrositätenkopf gesehen, oder...?", completion = "Ah! DA ist er ja! Wie habt Ihr ihn nur gefunden?\n\nNun, ganz gleich. Meine Schüler waren nicht in der Lage, den Kopf zu finden, obwohl sie stundenlang im Schleim herumgeplantscht haben. Aber dabei haben sie IMMERHIN diesen Beutel mit Glitzerkram gefunden... vielleicht könnt Ihr ja mit dem Inhalt etwas anfangen?\n\nIch danke Euch.", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29318] = {title = "Rippchen für die Schildwachen", objective = "Benutzt die rohen Rippchen in der Nähe eines Herdes oder Lagerfeuers, um sie zu kochen und benutzt sie dann, um 5 Schildwachen von Darnassus zu verpflegen.", description = "Einer meiner Verantwortungsbereiche umfasst die Verpflegung der Schildwachen von Darnassus, wenn sie im Dienst sind. Diese Aufgabe kostet Zeit, aber es ist eine, die ich gerne erledige. Würde es Euch etwas ausmachen, mir beim heutigen Essen zu helfen? Nehmt einfach diese Rippchen, bereitet sie in einem Herd oder über einem Feuer zu und verteilt sie unter den Schildwachen in der Stadt.", progress = nil, completion = "All diese Schildwachen zu verköstigen ist mit Eurer Hilfe viel einfacher. Diesmal musste sich niemand für sein Essen anstellen.", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29319] = {title = "Kaulquappen des Todes", objective = "Armand Kromwell in Unterstadt möchte, dass Ihr ihm 8 riesige fleischfressende Kaulquappen bringt.", description = "Einige unserer Apotheker haben es sich zur Gewohnheit gemacht, ihren etwas bedenklicheren chemischen Müll in den Stillwassertümpel zu kippen und... nun, sagen wir einfach, dass niemand so genau wissen möchte, wie groß mutierte fleischfressende Kröten werden können.\n\nWärt Ihr bereit, ein paar riesige fleischfressende Kaulquappen zu fangen, bevor es soweit kommt? Fasst sie nur besser nicht mit bloßen Händen an.", progress = "Habt Ihr ein paar mutierte Kaulquappen finden können? Ihr solltet sie besser nicht mit bloßen Händen anfassen.", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Ich sorge dafür, dass sie sofort... verwahrt werden.\n\nWas könnten unsere wunderbaren Apotheker denn auch mit einer Armee monströser, giftspuckender, fleischfressender Superkröten anfangen?", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29320] = {title = "Ein toller Hecht", objective = "Grabt einen Leichenwurm im Innenhof der Ruinen von Lordaeron aus und benutzt ihn als Köder um einen leichengefütterten Hecht zu fangen. Leichengefütterte Hechte gibt es im Blendwassersee, nordöstlich von Unterstadt.", description = "Ihr habt doch schon im Blendwassersee geangelt, oder?\n\nDer größte Fang in dem See ist, einen der riesigen leichengefütterten Hechte an Land zu ziehen. Sie beißen allerdings nur bei einer ganz besonderen Ködersorte an... Leichenwürmer.\n\nSucht bei den Gräbern im Innenhof an der Oberfläche. Dort solltet Ihr welche finden können.", progress = "Schon den Hecht gefangen?", completion = "Das ist ein toller Hecht, &lt;Name&gt;. Gut gemacht.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLeichenwurmköder entfernen\n\nIhr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29321] = {title = "Muscheltaucher", objective = "Sammelt 10 Teldrassilmuscheln von den Ufern in der Nähe von Rut'theran.", description = "Es scheint, als würden alle, die ich kenne, Muscheln lieben, aber ich kann ihren Anblick nicht ertragen! Sie riechen schlecht und sind schleimig und um sie zu ernten, muss man im Matsch graben. Da würde ich einer Angel und ein bisschen Köder doch jeden Tag den Vorzug geben.\n\nTrotzdem möchte ich meinen Bruder mit einem Eimer frischer Muscheln überraschen. Euch winkt eine Belohnung, wenn Ihr Euch bereit erklärt, mir diese Muscheln zu beschaffen.\n\nGeht einfach durch das Portal nach Rut'theran und sucht in den seichten Stellen am Ufer nach Muscheln.", progress = "Habt Ihr genug Muscheln gefunden?", completion = "Igitt, die sehen so eklig aus, aber mein Bruder mag sie am liebsten. Danke, dass Ihr mir diese unangenehme Aufgabe abgenommen habt!", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29322] = {title = "Schleim-Time", objective = "Sammelt 10 zuckende Schleimschimmel. Liefert sie bei Armand Kromwell in Unterstadt ab.", description = "Es braucht schon eine ganz besondere Art von Angler, um die Schätze der blubbernden Schleimkanäle von Unterstadt wertzuschätzen. Meint Ihr, Ihr könnt ein paar der zuckenden Schleimschimmel einsammeln, die dort unten herumkriechen?\n\nIhr könnt versuchen, sie zu angeln, aber sie sind verschlagen; vielleicht wäre es einfacher, ein Schleimbad zu nehmen und sie einfach zu packen.\n\nDenkt daran, dass sie uns nur lebendig und intakt etwas nützen... Wer möchte schon gern tote Schleimschimmel essen?! Widerwärtig.", progress = "Gar nicht so einfach zu fangen, was?", completion = "Diese Schleime sehen perfekt aus. Ich schicke sie auf den Weg zu Eunice, damit sie sie zubereitet. Vielen Dank.", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29323] = {title = "Aufstockung", objective = "Fangt 5 Seefelchen, indem Ihr in Darnassus angelt.", description = "Wir haben die meisten unserer Lebensmittelvorräte benutzt, um diejenigen zu versorgen, deren Häuser und Lebensgrundlagen zerstört wurden. Wenn wir unsere Vorräte nicht wieder aufstocken, werden wir alle in Gefahr sein, wenn das nächste Mal ein schlimmer Sturm oder eine Invasion der Horde über uns hereinbricht.\n\nVielleicht seid Ihr bereit, mir dabei zu helfen, unsere Bestände an Seefelchen wieder aufzufüllen. Ihr könnt sie überall in Darnassus fangen und sobald sie getrocknet sind, halten sie sich, bis sie gebraucht werden.", progress = "Wenn all unsere Fischer mit anpacken, dann wird es nicht lange dauern, bis wir unsere Vorräte wieder aufgefüllt haben.", completion = "Die sind prächtig! Danke, &lt;Name&gt;. Ich hänge sie zum Trocknen auf.", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29324] = {title = "Der Anhänger der Schwester", objective = "Erhaltet Aquinnes Mondanhänger aus dem Magen eines riesigen Welses. Ihr solltet sie an jeder Angelstelle in Darnassus fangen können.", description = "Habt Ihr schon Schwester Aquinne kennengelernt? Sie und ich sind gemeinsam in Dolanaar aufgewachsen und sie ist vor kurzem in der Stadt angekommen, um im Tempel des Mondes ausgebildet zu werden. Wir haben eine Bootsfahrt gemacht, aber der ungeschickte Ruderer hat das Boot zum Kentern gebracht!\n\nAls wir wieder am Ufer waren, war Aquinnes Anhänger verschwunden. Die Seen von Darnassus sind voll von riesigen Welsen, die alles was glänzt verschlucken.\n\nIch habe ohne Pause nach ihnen geangelt und gehofft, dass ich einen mit ihrem Anhänger finde. Wollt Ihr mir vielleicht helfen?", progress = "Konntet Ihr Aquinnes verlorenen Anhänger finden? Ich muss schon etwa fünfzig dieser Monster gefangen haben und habe nicht die geringste Spur!", completion = "&lt;Astaia nimmt Euch den Anhänger ab.&gt;\n\nUnter all dem Schleim und Anlauf glaube ich, es wiederzuerkennen! Aquinne wird sich so freuen, es wiederzubekommen... natürlich nachdem ich es gründlich gereinigt habe. Ich kann Euch nicht genug danken, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29325] = {title = "Ein glitschiger Snack", objective = "Sammelt 6 Babyoktopusse aus dem seichten Wasser in der Nähe von Rut'theran.", description = "Habt Ihr schon einmal Oktopusfleisch gegessen? Es ist etwas gewöhnungsbedürftig, aber es ist mein Leibgericht! Ich kenne sogar Leute, die die Dinger am Stück und lebendig essen!\n\nIch habe nicht vor, das bald auszuprobieren, aber mir sind gerade die frischen Oktopusse ausgegangen. Helft Ihr mir, neue zu bekommen? Sie leben im seichten Wasser an der Küste von Rut'theran.", progress = "Es ist unmöglich, Oktopusse mit einer Rute zu fangen. Ihr müsst sie einfach packen!", completion = "Die werden köstlich sein, das weiß ich jetzt schon! Danke, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29326] = {title = "Das Nordrassilgipfeltreffen", objective = "Sprecht mit Thrall unter dem Weltenbaum am Hyjal und beobachtet die Zeremonie des Irdenen Rings.", description = "Hallo, <Klasse>! Meine Brüder und Schwestern vom Irdenen Ring haben Gutes über Eure Taten nach dem Kataklysmus zu berichten gewusst. Doch noch immer muss vieles getan werden, wenn diese zerbrochene Welt geheilt werden soll.\n\nBegleitet mich ein paar Schritte. Vorbereitungen für eine Zeremonie sind im Gange, für ein Ritual, von dem ich hoffe, dass es der Wendepunkt in unserem Kampf gegen den Schattenhammer darstellen wird.\n\nSobald alles abgeschlossen ist, werdet Ihr das Wort über unseren Triumph hier in die Welt tragen können.", progress = nil, completion = "Es kann nicht vorbei sein. Wir dürfen die Hoffnung nicht aufgeben!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29327] = {title = "Elementare Bande: Zweifel", objective = "Sprecht mit Zyklonas, um eine sichere Passage zu Thrall zu bekommen. Kämpft dann mit den Windelementaren, die ihn peinigen, bis er frei ist.", description = "Ich kenne denjenigen, nach dem Ihr sucht... aber ich weiß nicht, ob es weise von Euch ist, ihm zu folgen. Er hat sich selbst in den Zyklon gestürzt. Die Winde zehren nun an seinem Körper und seinem Geist, zweifellos lassen sie nichts zurück als Fetzen und Zweifel.\n\nHinter ihm herzujagen würde Euch nur demselben Schicksal aussetzen. Der schneidende Wind lässt nichts unberührt.\n\nIhr seid gewarnt worden. Was habt Ihr jetzt vor?", progress = "Bleibt wachsam, <Name>! Gebt Go'el nicht auf.", completion = "Was ist dieses... Wasser?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29328] = {title = "Elementare Bande: Verlangen", objective = "Vernichtet die Fluten des Verlangens und die Wirbel des Verlangens in der Nähe des Wirbelnden Abgrunds, bis Thrall aus ihren Fängen befreit ist.", description = "Noch einmal, <Klasse>, ich schaffe es nicht ohne Eure Hilfe. Ich werde versuchen, den Sturm zu besänftigen, aber Ihr werdet die instabilen Elementare zurückdrängen müssen, die darum herumwirbeln. Nur dann können wir Go'el befreien!", progress = nil, completion = "Luft, Wasser... und jetzt Erde?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29329] = {title = "Elementare Bande: Geduld", objective = "Sprecht mit Aggra, wenn Ihr bereit seid, Thrall zu helfen. Bezwingt dann die Elemente und Kernsteine der Geduld, die ihn gefangen halten.", description = "Mit dem Segen der Steinmutter kann ich uns dahin bringen, wo Go'el gefangen gehalten wird.\n\nWir müssen vorsichtig sein. Der Schattenhammer verfügt überall über Agenten. Helft mir, sie zurückzuhalten, während ich versuche, zu Go'el durchzukommen!\n\nSprecht mit mir, wenn Ihr bereit seid, und ich werde Euch zu ihm bringen.", progress = "Wir sind fast da, <Name>. Bleibt noch ein wenig länger an meiner Seite. Wir werden es schaffen, zu ihm durchzudringen.", completion = "&lt;Aggra ballt ihre Fäuste und starrt auf die Stelle, an der Thrall noch vor wenigen Augenblicken stand.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29330] = {title = "Elementare Bande: Zorn", objective = "Tötet Feuerelementare neben Aggras Lufttotem an der westlichen Kante des Plateaus, bis es aktiviert ist. Macht dann bei Aggras Wassertotem, Aggras Erdtotem und Aggras Feuertotem weiter.", description = "Die Totems, <Name>! Wir müssen sie aktivieren oder Go'el ist verloren!\n\nTötet die Elementare neben jedem meiner Totems, die an den Kanten dieses Plateaus platziert sind. Sobald alle vier Totems aktiviert sind, sollte es uns möglich sein, das letzte Stück von Go'els Seele zu befreien!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29331] = {title = "Elementare Bande: Das Gelübde", objective = "Sprecht mit Thrall bei Nordrassil auf dem Hyjal.", description = "Bevor er durch das Portal zum Hyjal trat, hat Thrall Euch gebeten, ihm zu folgen. Es gibt da etwas, von dem er möchte, dass Ihr es seht.", progress = nil, completion = "Ich danke Euch – ich lebe erneut! Und dank der gemeinsamen Anstrengungen des Zirkels des Cenarius und dem Irdenen Ring wird der Weltenbaum ebenfalls neues Leben nach Azeroth bringen.\n\nWährend wir uns weiterhin um Todesschwinge und den Rest unserer Feinde kümmern müssen, möchte ich gerne etwas mit Euch teilen.", rewards = "Mantel des VerlangensMantel des ZweifelsMantel des FurorsMantel der GeduldDer folgende Zauber wird auf euch gewirkt:\n\nElemental Bonds (Vow): Summon Controller\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29332] = {title = "Leckere Lilien", objective = "Besorgt 10 Stillwasserlilien. Liefert die Pflanzen bei Eunice Burch in Unterstadt ab.", description = "Die Lilien, die um den Stillwassertümpel herum wachsen, lassen sich zu einer köstlichen Suppe verkochen.\n\nNun ja... \"köstlich\" in dem Sinne, dass nicht sofort jedem Orc schlecht wird, der sie trinkt.\n\nWarum sammelt Ihr nicht ein paar für mich, hmmm? Gebt nur gut auf die riesigen fleischfressenden Kaulquappen Acht.", progress = "Habt Ihr genügend Stillwasserlilien finden können?", completion = "Ah, so eine üppige Ladung Lilien. Bravo! Ich koche sie sofort ein...", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29333] = {title = "Schneckt lecker!", objective = "Sammelt 8 Blendwasserschnecken. Liefert sie bei Eunice Burch in Unterstadt ab.", description = "Die Orcwachen beschweren sich ständig über fade, schimmlige Kost in Unterstadt - als ob WIR etwas dafür könnten, dass sie sich nicht von Pilzen und alten Leichen ernähren können - also finde ich, dass es an der Zeit ist, dass sie herausfinden, was für exotische Köstlichkeiten wir zubereiten können, wenn wir wollen.\n\nSammelt ein paar Süßwasserschnecken aus dem Blendwassersee und ich zeige ihnen, was eine wahre kulinarische Meisterin zaubern kann.", progress = "Schon die Süßwasserschnecken gesammelt?", completion = "Ihr müsst ein guter Schwimmer sein... Ich kann höchstens Toter-Mann spielen.\n\nWie dem auch sei, Ihr habt da ein hervorragendes Bündel Schnecken gesammelt. Danke.", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29334] = {title = "Ein wahres Schabsal", objective = "Beschafft 20 träge Kakerlaken. Liefert die Insekten bei Chefköchin Audrey in Unterstadt ab.", description = "Bei all dem Gemecker, das diese Aufseher der Kor'kron für die Verpflegung in Unterstadt übrig haben, gibt es eine Sache, die sie schaufelweise essen: der dreifach gewürzte Knuspereintopf meiner Schwester.\n\nWeil er so beliebt ist, gehen ihr ständig die Zutaten aus. Würdet Ihr ein paar zu ihr zum Wagen bringen, aus dem sie den Eintopf verkauft?\n\nÜberall in der Stadt werdet Ihr Fallen finden; bringt einfach deren Inhalt zu Audrey und sie kümmert sich um den Rest!", progress = "Ich nenne meine kleinen Fallen \"Kakerlabinen\".\n\nKakerlaken spazieren hinein, sie spazieren aber nicht wieder heraus.", completion = "Gerade noch rechtzeitig bevor meine Vorräte erschöpft waren. Danke!", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29335] = {title = "In die beißenden Winde", objective = "Sprecht mit Zyklonas auf dem Felsen des Südwinds in Uldum.", description = "<Klasse>, ich weigere mich zu glauben, dass mein Go'el für immer verloren ist. Sein Geist ist über die Elementarebene zerstreut worden. Sollte auch nur ein Teil von ihm noch existieren, dann können wir ihn finden, ich brauche allerdings Eure Hilfe.\n\nWir werden mit der Ebene der Luft beginnen.\n\nSprecht mich erneut an und wir werden gemeinsam zum Vortexgipfel reisen. Wir müssen mit einem Elementar namens Zyklonas sprechen. Ein launischer Geselle, aber im Reich der Luft sieht er alles. Wenn mein Liebster dort sein sollte, so wird Zyklonas wissen, was mit ihm geschehen ist.", progress = nil, completion = "&lt;Ihr spürt, wie der Wind über Eure Arme fegt, über Euer Gesicht, Eure Waffen und Rüstung...&gt;\n\n&lt;Zyklonas inspiziert Euch.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29336] = {title = "In die drängenden Fluten", objective = "Sprecht mit Hydrius beim Wirbelnden Abgrund in den Abyssischen Tiefen von Vashj'ir.", description = "Go'el muss sich auf der Ebene des Wassers befinden... im Meeresschlund selbst! Mich fröstelt, wenn ich mir vorstelle, was ihn dort erwartet.\n\nFindet den Elementar Hydrius, in der Nähe des Wirbelnden Abgrunds. Er weiß von Go'el und sympathisiert mit unserem Kampf gegen Ragnaros. Wenn Euch jemand dort helfen kann, dann er.\n\nIch werde Euch unter den Strömen Vashj'irs treffen, <Volk>...", progress = nil, completion = "Ich werde tun, was ich kann, um Euch zu helfen, &lt;Klasse&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nElemental Bonds (Vashj'ir): Summon Hydrius (Opening)\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29337] = {title = "In die beständige Erde", objective = "Sprecht mit Therazane bei Therazanes Thron in Tiefenheim.\n\nAggra kann Euch vom Wirbelnden Abgrund aus zu Therazanes Thron teleportieren.", description = "Die Zeit ist knapp! Mein Liebster liegt in Tiefenheim. Ich werde uns dorthin bringen, sobald Ihr bereit seid, und wir werden mit Therazane, der Steinmutter, sprechen.", progress = nil, completion = "Ich weiß bereits, wonach Ihr sucht, Fleischlinge. Und ich habe mich entschieden, Euch zu helfen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nElemental Bonds (Deepholm): Summon Therazane Controller\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29338] = {title = "In die unnachgiebige Flamme", objective = "Sprecht mit Aggra auf dem Nimbusrücken in Tiefenheim, um eine Passage in die Feuerlande zu sichern.", description = "Wir müssen nun zu den Feuerlanden reisen. In diesem Reich kann Go'els brennender Geist so fürchterlich wie Ragnaros selbst werden! Macht Euch bereit, da er allein in einer feindlichen Welt sein wird.\n\nSprecht mich an, wenn Ihr bereit seid... und mögen die Vorfahren uns beschützen!", progress = nil, completion = "Haltet Euch bereit, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29339] = {title = "Short-Supply Reward", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeutel voller exotischer Geheimnisse"}
MultiLanguageQuestData['de'][29340] = {title = "Short-Supply Reward", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][29341] = {title = "Short-Supply Reward", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][29342] = {title = "Eisangeln", objective = "Fangt 5 Seesaiblinge, indem Ihr im Helmsbettsee in Dun Morogh angelt.", description = "Die leckersten Fische leben in den kalten Gewässern Dun Moroghs, <Name>, lasst Euch da mal nichts anderes erzählen! Mein Favorit, und am beliebtesten in Eisenschmiede, ist der Seesaibling, der aus den Ländern unserer Ahnen kommt.\n\nIch möchte ihn als Eisenschmiedes Geschenk an die Welt bezeichnen!\n\nWarum versucht Ihr nicht mal selbst, ein paar davon zu fangen? Der beste Ort, um diesen Fisch zu finden, ist im Helmsbettsee, im östlichen Teil von Dun Morogh.", progress = "Habt Ihr schon versucht, diese Saiblinge zu fangen?", completion = "Sie sind wunderschön, &lt;Name&gt;! Ich glaube, Ihr habt jetzt langsam den Dreh raus.", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29343] = {title = "Für die Nachwelt", objective = "Fangt einen jungen Eisenkiefer in Eisenschmiedes Düsterem Viertel und stellt ihn in der Bibliothek neben der leeren Plakette aus.", description = "Ich bin mir sicher, dass Ihr inzwischen schon mal vom alten Eisenkiefer gehört habt, dem berühmtesten und am schwersten fassbaren Fisch in den Gewässern von Eisenschmiedes Düsterem Viertel. Nun, in seinen vielen Lebensjahren war er dafür verantwortlich, dass jede Menge Nachkommen das Licht der Welt erblickten. Lasst Euch nicht von dem Namen \"Junger Eisenkiefer\" täuschen, <Name>, diese Jungfische sind genauso clever wie ihr Vater, ihnen mangelt es nur ein wenig an Erfahrung.\n\nMit Können und Geduld wird es Euch sicher gelingen, einen zu fangen, und wenn es so weit ist, dann bringt ihn zum Museum in Eisenschmiedes Bibliothek und stellt ihn aus, damit ihn alle sehen können!", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Vielleicht wird Euer Fang ja mehr Zwerge dazu inspirieren, das Angeln anzufangen!", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29344] = {title = "Fische für Squirky", objective = "Angelt 3 blinde Elritzen aus dem Teich im Düsteren Viertel und verfüttert sie an Squirky.", description = "Hab ich Euch schon meinen Begleiter Squirky vorgestellt? Ich bringe ihm bei, wie man angelt, so richtig mit allen Schikanen! Bisher habe ich ihn mit Elritzen gefüttert, die ich aus dem Teich in diesem Viertel gefischt habe.\n\nVielleicht wollt Ihr es ja mal versuchen? Werft einfach Euren Köder in dem Teich da drüben aus und füttert Squirky mit den Elritzen, die Ihr rauszieht. Er wird Euch für immer lieben!", progress = nil, completion = "Ihr habt gute Arbeit geleistet. Squirky sieht zufrieden aus und ich hatte Zeit, ein paar neue Köder zu basteln. Danke für Eure Hilfe!", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29345] = {title = "Tümpelschrecken", objective = "Kah Nebelläufer in Donnerfels braucht 8 Azsharaschlangenköpfe aus dem Teich in Donnerfels.", description = "Ein Goblinbesucher, der es sicher nur gut meinte, hat Azsharaschlangenköpfe in unseren Gewässern ausgesetzt und die überrennen jetzt unseren Teich.\n\nIch bitte Euch, wenn Ihr ein paar von diesen gefräßigen Raubfischen fangen könnt, bevor sie alle Kleinfische und Matschschnapper in Donnerfels gefressen haben, wäre ich sehr dankbar.", progress = "Konntet Ihr schon ein paar Azsharaschlangenköpfe fangen?", completion = "Gut gemacht, &lt;Name&gt;. Alle Angler von Donnerfels müssen mit anpacken, damit sich diese boshaften Geschöpfe nicht in Mulgores Gewässern ansiedeln.", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29346] = {title = "Ein Ring sie zu knechten", objective = "Angelt einen blinden Höhlenfisch aus den Teichen der Visionen in Donnerfels. Wenn Ihr einen gefangen habt, nehmt ihn aus und seht nach, ob er den Ring verschluckt hat.", description = "Einer der Verlassenen aus den Teichen der Visionen ist an mich herangetreten und hat mir gesagt, dass sein Ring von einem blinden Höhlenfisch in den dortigen Teichen verschluckt worden ist.\n\nEs könnte auch sein Finger gewesen sein. So richtig verstanden habe ich ihn nicht; sein Kiefer hat sich nicht bewegt und sein Orcisch war nicht besser als mein eigenes.\n\nWie dem auch sei, ich dachte mir, dass wir unseren ungewöhnlichen Gästen einen Gefallen tun könnten und Höhlenfische ausnehmen könnten, bis wir den Ring - oder den Finger - gefunden haben.\n\nWürdet Ihr mir helfen?", progress = "Ihr habt nicht zufällig meinen Ring gesehen, oder? Ich glaube, einer der Höhlenfische hat ihn verschluckt...", completion = "Ihr habt also meinen Ring gefunden, wie? Ich bin Euch überaus dankbar.\n\nUm ganz ehrlich zu sein, ich habe keine Ahnung, warum ich das Ding überhaupt behalte. Ich erinnere mich noch nicht einmal, wie er in meinen Besitz gekommen ist... vermutlich bin ich einfach ein Gewohnheitstier.\n\nWie ich schon sagte, bin ich Euch sehr dankbar. Diese Dinge hier habe ich während meiner Suche nach dem Ring gefunden. Vielleicht sind sie für Euch von Nutzen?", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29347] = {title = "Lebendköder", objective = "Benutzt Grimnurs Köder an Euch selbst und springt dann in den Helmsbettsee in Dun Morogh.", description = "Wenn Ihr schon mal auf der Jagd nach Flusskrebsen wart, dann wisst Ihr, dass sie am besten auf Lebendköder reagieren. Und je mehr Köder, desto besser! Würdet Ihr gerne meinen neuen Köder ausprobieren? Schmiert Euch einfach damit ein und hüpft in den Helmsbettsee im östlichen Dun Morogh.\n\nBringt Euren Fang zu Koch Ghilm am Steinbruch Gol'Bolar westlich des Sees. Er ist ein Experte in der Zubereitung dieser zu groß geratenen Krabbeltiere!", progress = nil, completion = "Sie sind wunderschön, &lt;Name&gt;! Grimnur wird so stolz sein, wenn er davon hört!\n\nOh, er hat mir gesagt, ich soll Euch das hier geben, wenn der Plan aufgeht.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFlusskrebsfang abbrechen\n\nIhr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29348] = {title = "Neue Fische für Donnerfels", objective = "Kah Nebelläufer in Donnerfels braucht 2 scharfe Kleinfische und 2 liebestolle Matschschnapper aus dem Steinbullensee in Mulgore.", description = "Der Fischteich von Donnerfels wird von gefräßigen Azsharaschlangenköpfen heimgesucht. Es sind kaum noch Kleinfische oder Matschschnapper übrig.\n\nUnsere Angler sind schon dabei, so viele Schlangenköpfe wie möglich zu töten, aber könntet Ihr uns bei unseren Bemühungen, den Teich wieder zu bevölkern, ein wenig zur Hand gehen?\n\nWenn Ihr ein paar Fische aus dem Steinbullensee sammeln könntet und sie hierher nach Donnerfels bringt, wäre ich sehr dankbar.", progress = "Habt Ihr die Fische aus dem Steinbullensee dabei?", completion = "Wir wissen Eure Hilfe sehr zu schätzen, &lt;Name&gt;.\n\nHoffentlich helfen diese Fische dabei, unseren Fischteich wieder zu bevölkern.", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29349] = {title = "Lust auf Flusskrebs", objective = "Kah Nebelläufer in Donnerfels braucht 10 Steinbullenflusskrebse aus dem Steinbullensee in Mulgore.", description = "Eine der berühmtesten Delikatessen Mulgores sind die Flusskrebse, die in unseren Seen und Flüssen leben. Sie sind besonders beliebt bei Hochzeiten oder Geburtsfeiern.\n\nWürdet Ihr mir dabei helfen, einige dieser gerissenen Krustentiere für die Kochtöpfe von Donnerfels zu fangen?\n\nIhr könnt sie im Steinbullensee angeln, oder einfach hineinspringen und sie so fangen.", progress = "Krebse sind so schmackhaft. Habt Ihr viele gefangen?", completion = "Ah, so viele Krebse!\n\nHabt Ihr sie geangelt? Oder seid Ihr ihnen hinterhergeschwommen?\n\nIst auch egal. Ausgezeichnete Arbeit, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29350] = {title = "Der gnomische Köder-o-Matik", objective = "Benutzt die Baupläne für einen Köder-o-Matik mit 5 glänzenden Schmuckstücken, einem haarfeinen Sprengstoffauslöser und 3 Rattenfallen um einen gnomischen Köder-o-Matik herzustellen.", description = "Einer von den gnomischen Ingenieurskunstlehrern hat mir die Baupläne für einen raffinierten Köder gegeben, von dem er behauptet, dass er mir hilft, Fische schneller zu fangen und sie davon abzuhalten, abzuhauen.\n\nHier sind die Baupläne. Ihr werdet glänzende Schmuckstücke benötigen, die Ihr von meiner Assistentin im Gebäude erhalten könnt, einen haarfeinen Sprengstoffauslöser von einem Händler für Ingenieurskunstwaren in Tüftlerstadt und ein paar Rattenfallen von der Tiefenbahn.", progress = "Und, wie sieht's aus mit diesem raffinierten neuen Köder?", completion = "Ich denke, es sieht nicht nach was aus, was ein Fisch interessant finden könnte, aber man weiß ja nie. Fische sind seltsame Viecher. Danke, dass Ihr es versucht habt, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29351] = {title = "Eine Runde für die Wachen", objective = "Verteilt die Rationen aus Eisenschmiede an 6 Wachen aus Eisenschmiede.", description = "Die Wachen, die Eisenschmiede schützen, riskieren ihr Leben im Kampf gegen unsere vielen Feinde, und es ist an uns, uns um sie zu kümmern.\n\nHeute bestehen ihre Rationen aus zwei Lieblingsdingen der Zwerge: Haggis und Silberbräu aus Eisenschmiede. Wäret Ihr so gut, mir dabei zu helfen, die Rationen zu verteilen? Dadurch bekommen alle ihr Essen rechtzeitig und wir können zu der Erledigung anderer Aufgaben übergehen.", progress = nil, completion = "Eine volle Wache ist eine glückliche Wache, pflege ich immer zu sagen. Danke für Eure Hilfe, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29352] = {title = "Geflügelmangel", objective = "Fangt 6 Hühner von Dun Morogh in der Nähe des Eingangs von Eisenschmiede.", description = "Oh nein, <Name>, das wird ein Desaster, wenn wir nicht bald ein paar Hühner finden... Man kann doch eine Lauch-Hühnersuppe nicht ohne Huhn kochen! Das geht einfach nicht!\n\nEs ist immer noch Zeit genug, die Suppe und die Brühe herzustellen, wenn Ihr ein paar frische Hühner findet. Werdet Ihr mir helfen? Es laufen normalerweise immer ein paar Hühner außerhalb des Haupteingangs der Stadt herum. Wenn Ihr, sagen wir mal, sechs von ihnen erwischt, dann würdet Ihr mir den Hals retten.", progress = "Die Hühner, <Name>, habt Ihr sie oder nicht?", completion = "Ja, das ist genau das, was ich brauchte. Ihr habt meinen Dank, &lt;Name&gt;, und meine Entschuldigung, dass ich vorher so barsch war. Ich kann den Gedanken einfach nicht ertragen, dass eine Mahlzeit nicht rechtzeitig fertig wird.", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29353] = {title = "Haggis für alle!", objective = "Besorgt einen Sack voller Schafsinnereien, 5 Pakete milder Gewürze und 4 Säcke voller Hafermehl.", description = "Der Haggis muss fließen. Na gut, bildlich gesprochen. Haggis wird niemals flüssig sein! Ihr wollt gar nicht wissen, was passiert, wenn die Bevölkerung von Eisenschmiede keinen Haggis bekommt.\n\nIch arbeite gerade an der nächsten Ladung, aber mir fehlen noch ein paar Zutaten.\n\nSognar Klippenbart ist der Fleischverkäufer im Militärviertel und er kann Euch den Sack voller Schafsinnereien verkaufen, den ich brauche. Milde Gewürze bekommt Ihr von jedem Kochbedarfshändler und Säcke voller Hafermehl findet Ihr in den Gasthäusern oder den Vorratslagern der Stadt.", progress = "Habt Ihr die Zutaten?", completion = "Ihr habt sie alle? Wunderbar! Dann frisch ans Werk.", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29354] = {title = "Glänzende Schmuckstücke", objective = "Nahari Wolkenjäger in Donnerfels braucht 20 glänzende Steine vom Fuß der zentralen Anhöhe.", description = "Eines der einfachsten und nützlichsten Hilfmittel eines jeden Anglers ist das glänzende Schmuckstück. Selbst der ungeübteste Angler hat mit einem glänzenden Schmuckstück an der Sehne gute Chancen.\n\nBei all dem Fischen in letzter Zeit gehen die Vorräte von Donnerfels aber schnell zur Neige!\n\nKönnte ich Euch bitten, glänzende Steine vom Fuß der zentralen Anhöhe zu sammeln? Bringt sie zu Nahari Wolkenjäger, damit sie mit ihnen Nachschub anfertigen kann.", progress = "Habt Ihr mir vielleicht ein paar glänzende Steine mitgebracht?", completion = "Das sind aber besonders hübsche Steine! Daraus werden perfekte glänzende Schmuckstücke werden, danke sehr.\n\nHier... Kah hat mir Bescheid gesagt, dass Ihr mit den Steinen vorbeikommen würdet und hat mich gebeten, Euch dies bei Eurer Ankunft zu geben.", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29355] = {title = "Gewürzbrot en masse", objective = "Backt oder erhaltet 10 Scheiben Gewürzbrot.", description = "Es mag zwar nichts Besonderes sein, <Name>, aber Gewürzbrot ist in Eisenschmiede schon seit jeher sehr beliebt. Manchmal komme ich mit meinen Lieferungen gar nicht hinterher!\n\nMöchtet Ihr vielleicht ein paar Laibe backen, damit Ihr nicht aus der Übung kommt, und mir damit helfen, meine Kunden zu versorgen? Ihr könnt alle Zutaten, die Ihr braucht, von meinem Bruder, Emrul Riknussun, ein Stockwerk unter uns erhalten.", progress = "Wie läuft es mit dem Gewürzbrot?", completion = "Dieses Brot sieht köstlich aus. Danke, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29356] = {title = "Helft den Bierdürftigen", objective = "Holt das Fass voll Drugans EKW von der Brauerei in Kharanos ab und bringt es nach Eisenschmiede zurück.", description = "Mein Vorrat an EKW, Eisenschmieder Kristallweizen für Euch Grünschnäbel, gehen zur Neige. Zum Glück ist die Brauerei nicht weit weg und die sollten schon ein neues Fass voll Drugans EKW für uns haben. Dieser Drugan ist ein echtes Brauereigenie, sag' ich Euch.\n\nIch werde es heute nicht schaffen, selbst nach Kharanos hinunterzulaufen, aber vielleicht könnt Ihr dort hinunter flitzen, ein neues Fass abholen und es hierher bringen? Was sagt Ihr?", progress = "Und? Habt Ihr das Fass oder nicht?", completion = "Ah, gut gemacht! Ich sage Euch, dieser Drugan ist ein echtes Universalgenie - Entdecker, Historiker, Brauer - gibt es etwas, das dieser Zwerg nicht gemeistert hat?", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29357] = {title = "Jede Menge Gewürzbrot", objective = "Stellt 10 Laibe Gewürzbrot her oder besorgt sie Euch anderweitig.", description = "Ist es nicht erstaunlich, wie etwas so einfaches wie Gewürzbrot jeden Tag in Darnassus verbraucht wird? Wenn ich mich nicht um meine anderen Verantwortlichkeiten kümmere, dann backe ich gerne Gewürzbrot, um meine Fähigkeiten als Koch zu verfeinern und an meiner Technik zu arbeiten.\n\nWarum probiert Ihr es nicht mal aus? Ihr solltet die Zutaten eigentlich hier im Laden finden.\n\nEgal wie viel wir herstellen, es wird nie schlecht. Bringt mir einige Laibe, wenn Ihr fertig seid und ich werde jemanden schicken, um sie mit unseren Freunden, den Gilneern, zu teilen.", progress = "Ich liebe diesen Geruch von frisch gebackenem Brot einfach, besonders von Gewürzbrot, Ihr nicht?", completion = "Diese hier sind gut gemacht, &lt;Name&gt;. Ich hoffe, Ihr fandet es genauso entspannend wie ich.", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29358] = {title = "Wir benötigen mehr Pinienkerne", objective = "Sammelt 30 Pinienkerne, indem Ihr Kienäpfel von Mulgore in Donnerfels sammelt und sie röstet. Liefert die Kerne bei Aska Nebelläufer in Donnerfels ab.", description = "Die Shu'halo verwenden Pinienkerne in so vielen Gerichten: Wild, Fisch, Gemüse, selbst Backwaren versetzen wir mit ihnen.\n\nDie Erdenmutter hat uns damit gesegnet, dass die allerbesten Pinienkerne von den Bäumen auf diesen Anhöhen stammen.\n\nSammelt einfach Kienäpfel und röstet sie über einem Feuer, damit die Kerne herausfallen. Es sind fast nie genug für alle da...", progress = "Habt Ihr viele dieser leckeren Pinienkerne finden können?", completion = "Ihr arbeitet so schnell!\n\nIch sorge dafür, dass sie an die verschiedenen Köche und Bäcker von Donnerfels verteilt werden.\n\nHabt Dank!", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29359] = {title = "Der Klassiker", objective = "Angelt 8 Kaldoreiheringe, indem Ihr in der Nähe von Rut'theran Eure Angel auswerft.", description = "Hering ist eine der meistverlangten Fischarten in Darnassus, aber Hering ist nicht gleich Hering. Der Kaldoreihering kommt nur in den Gewässern um Teldrassil vor.\n\nIch versuche, immer ein paar vorrätig zu haben, weil dieser Fisch so vielseitig ist! Ich habe gerade erst wieder welche fertig geräuchert, deshalb muss ich meine Vorräte aufstocken. Würde es Euch etwas ausmachen, mir zu helfen? Ihr könnt Kaldoreihering fangen, wenn Ihr in der Nähe von Rut'theran angelt.", progress = "Habt Ihr die Heringe?", completion = "Danke! Ich frage mich, was ich mit denen wohl anstellen könnte...", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29360] = {title = "Und als Beilage: Fliegen", objective = "Beschafft 25 fette Fliegen von dem \"Fleisch\" in der Nähe der Fleischwagen. Kehrt anschließend zu Eunice Burch in Unterstadt zurück.", description = "Wir verpflegen hier nicht nur die Orcs, <Klasse>. Diesmal geht es darum, Nahrung für deren Ablösung zuzubereiten.\n\nWir müssen klein beginnen und Fliegen fangen. Fliegen lieben fauliges Fleisch und wir lieben fauliges Fleisch... als Belagerungsgeschosse!\n\nDurchsucht die Fleischwagen nach überschüssigen Fleischbrocken. Wo es Fleisch gibt, gibt es auch Fliegen.\n\nBringt mir 25 fette Fliegen, damit ich Phase Zwei unseres Kochplans einleiten kann.", progress = "Ich wette, ein Bisschen von dem \"Fleisch\" ist noch gut.", completion = "Ah! Perfekt! Fett, träge und bereit, gefressen zu werden! Als nächstes werden wir sie an unsere Spinnen verfüttern. Die werden gemästet und dann verfüttern wir sie an die Frösche...\n\nAch, ich plappere schon wieder. Die Details müsst Ihr gar nicht wissen. Das ist nur ein kleiner Schritt in einem großen kulinarischen Plan.", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29361] = {title = "Das Monster im Burggraben", objective = "Benutzt den Allianzlockvogelbausatz, um das Burggrabenmonster in den Ruinen von Lordaeron hervorzulocken. Verwendet dann die fetten Frösche, um das Monster zu füttern.", description = "Manchmal muss man beim Angeln seinen Fang wieder ins Wasser zurückwerfen, <Klasse>.\n\nWir haben diese Frösche nur für diesen Zweck gemästet. Sie haben fette Spinnen bekommen, die ihrerseits mit fetten Fliegen gefüttert worden sind, und jetzt füttern wir ein echtes Monster.\n\nIn den Burggräben an der Oberfläche, in den Ruinen von Lordaeron, lebt unser eigenes Burggrabenmonster.\n\nHeute ist Fütterungstag. Aber wir müssen es dabei auch abrichten. In diesem Beutel findet Ihr einen Lockvogelbausatz und ein paar fette Frösche. Stellt den Lockvogel auf und werft dem Monster die Frösche zu, sobald es auftaucht.", progress = nil, completion = "Die Toten ernähren die Fliegen. Die Fliegen ernähren die Spinnen. Die Spinnen ernähren die Frösche. Die Frösche füttern unser Burggrabenmonster... ein entzückender Lebenszyklus, bei dem so viele Leben beendet werden.", rewards = "Ihr bekommt:\n\nSack voll Glitzerkram"}
MultiLanguageQuestData['de'][29362] = {title = "\"Magische\" Pilze", objective = "Sammelt 6 \"magische\" Pilze aus den Teichen der Visionen in Donnerfels. Liefert sie bei Aska Nebelläufer in Donnerfels ab.", description = "Ihr kennt doch sicher die Teiche der Visionen, oder?\n\nDort wächst eine bestimmte Pilzart... nicht die ledrigen, wuchernden Pilze, die dort überall stehen, sondern kleinere, zerbrechlichere Schwämme, die unter ihnen wachsen.\n\nSie sind selten, sehr köstlich und verleihen Gerichten einen Geschmack, den man magisch nennen könnte.\n\n...Was denn? Ernsthaft. Sie schmecken einfach nur gut. Sonst nichts.", progress = "Konntet Ihr die Pilze finden?", completion = "Danke, &lt;Name&gt;! Ich bin sicher, dass sie ein einfach magisches Aroma in jedes Gericht zaubern.\n\nWas ist denn? Hört auf mich so anzuschauen!", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29363] = {title = "Gewürzbrot aus Mulgore", objective = "Kombiniert die Gewürze aus Mulgore mit Gewürzbrot, um 5 Laibe frisches Gewürzbrot aus Mulgore herzustellen (Ihr könnt Euer eigenes Gewürzbrot backen, oder welches aus anderen Quellen verwenden). Liefert die Brote bei Aska Nebelläufer in Donnerfels ab.", description = "Ich werde oft gefragt \"Aska, wer bäckt eigentlich all dieses Gewürzbrot aus Mulgore?!\"\n\nEine berechtigte Frage. Unser gutes und edles Brot wird an unzähligen Orten in jedem Winkel Azeroths gehandelt, selbst von unseren erbittertsten Feinden. SO LECKER IST ES!\n\nUnd die Antwort lautet...?\n\n\"IHR seid es.\" Bitte nehmt dieses Paket mit Gewürzen aus Mulgore und macht damit aus fadem, langweiligem Gewürzbrot Gewürzbrot aus MULGORE!", progress = "Habt Ihr schon das Gewürzbrot aus Mulgore gebacken?", completion = "Ooh, das Brot duftet aber köstlich. Ihr seid ja ein Meisterbäcker.\n\nWer weiß, wie weit diese exquisiten Laibe reisen werden... wie ich höre, sind sie sogar bei den Draenei auf der Azurmythosinsel beliebt.", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29364] = {title = "Maisbrei", objective = "Helft den Bewohnern von Donnerfels, Maismehl herzustellen, indem Ihr Schüsseln mit Maiskörnern mahlt.", description = "Eins der wichtigsten Grundnahrungsmittel hier in Donnerfels ist Maismehl; in fast jedem Haushalt findet man Schüsseln mit Mais.\n\nDa so viele Mühlen im Land ständig von Harpyien, Gnollen, rücksichtslosen Bergbaugesellschaften und weiß die Erdenmutter wem angegriffen werden, bitte ich oft meine Lehrlinge, beim Maismahlen mitzuhelfen.\n\nWürdet Ihr vielleicht auch mit anfassen?", progress = nil, completion = "Es steckt viel Arbeit darin, genügend Maismehl für alle zu machen. Danke für Eure Hilfe, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29365] = {title = "Perfekt ausgewählte Portionen", objective = "Besorgt vier \"perfekte Portionen\" von den Händlern in Donnerfels. Liefert die Zutaten bei Aska Nebelläufer in Donnerfels ab.", description = "Selbst Einsteigerköche wissen, dass ein großartiges Gericht mit großartigen Zutaten beginnt.\n\nIch habe bei den Händlern von Donnerfels Daueraufträge, aber ich möchte gern sehen, wie ihr Euch dabei schlagt, die allerbesten Waren auszuwählen, die sie im Angebot haben.\n\nBitte geht von Händler zu Händler und besorgt mir perfekte Portionen Fleisch, Fisch, Gemüse und Kräuter.", progress = "Habt Ihr alle nötigen Zutaten gesammelt?", completion = "&lt;Aska beäugt die Zutaten, die Ihr ausgewählt habt.&gt;\n\nMmmhmmm. Ja. Gut gemacht!\n\nIch hätte sie selbst nicht besser auswählen können.", rewards = "Ihr bekommt:\n\nFeinschmeckerpreis"}
MultiLanguageQuestData['de'][29371] = {title = "Eine Zeit des Verlierens", objective = "Benutzt das Löschmittel gegen den Weidenmann in den Ruinen von Lordaeron.", description = "Seid gegrüßt, <Klasse>. Während wir versuchen, uns an der Weidenmannzeremonie zu erfreuen, ist es nicht verwunderlich, dass die Horde versucht, unsere Feierlichkeiten zu ruinieren.\n\nDie schlauste Lösung wäre es wohl, einfach darüber zu stehen und diese Angriffe zu ignorieren.\n\nIch bewundere diejenigen, die das schaffen, doch ich kann ihnen nicht helfen. Doch denjenigen, die zurückschlagen möchten... denen kann ich helfen. Falls Ihr Interesse habt, <Klasse>, nehmt dieses Löschmittel und setzt es gegen den Weidenmann der Horde in den Ruinen von Lordaeron ein.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSüßes Saures"}
MultiLanguageQuestData['de'][29372] = {title = "Ärger in Posemuckel", objective = "Rettet den Sheriff.", description = "Gesetzlose haben den Sheriff entführt!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29373] = {title = "Ärger in Posemuckel", objective = "Rettet den Sheriff.", description = "Wir haben Sheriff Blundy niemals besonders viel Aufmerksamkeit geschenkt, wie er sich da ständig aufgeplustert hat wegen seinen \"Gesetzen\" und \"Fehl-ver-halt-en\". Aber den dreckigen alten McClintocks und ihrem Kuhtreiber von einem Vater vom Truckshawgrat hat es bis hier gestanden mit den ständigen Kerkerhaften und Verhandlungen und Sippenhaften und \"Tot oder lebendig!\"-Steckbriefen und da sind sie letzte Woche gekommen und haben das Gesetz in die eigenen Hände genommen - im wahrsten Sinne des Wortes - indem sie den guten Sheriff verschleppt haben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29374] = {title = "Stinkbomben los!", objective = "Sprecht mit Crina Fenlow und nehmt einen Besen, um damit über Sturmwind zu fliegen. Benutzt die Stinkbomben, um die Stadt und ihre Einwohner damit zu bewerfen.", description = "Die närrische Allianz hat Hexen eingestellt, um einen Angriff auf unsere Stadt durchzuführen. Na, wie meine Schwester mal gesagt hat: \"Gleiches Recht für alle!\".\n\nWir werden ihnen den Gefallen mit Freuden zurückzahlen. Sprecht mit meiner Schwester und sie wird Euch einen Ritt auf einem Besen über Sturmwind organisieren. Sobald Ihr Euch über Sturmwind befindet, solltet Ihr die Stinkbomben auf die Stadt und ihre Einwohner fallenlassen. Lasst sie leiden!\n\nWir werden diesen Hexen in Sturmwind schon zeigen, wer mächtiger ist.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSüßes Saures"}
MultiLanguageQuestData['de'][29375] = {title = "Aufräumen in Unterstadt", objective = "Benutzt den Arkanreiniger, um die Stinkbomben in Unterstadt zu entfernen.", description = "Seid gegrüßt, <Klasse>! Genießt Ihr die Schlotternächte? Es scheint, dass die Allianz als Antwort auf unseren Stinkbombenangriff auf Sturmwind auch unsere Stadt mit Stinkbomben angreift.\n\nZum Glück verfügen wir über Magien, die mit dem Gestank der Allianz fertigwerden. Benutzt diesen Arkanreiniger, um die Stinkbomben aus der Stadt zu beseitigen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSüßes Saures"}
MultiLanguageQuestData['de'][29376] = {title = "Eine Zeit des Aufbaus", objective = "Benutzt das Freudenfeuer vor dem Weidenmann, um ihn in Brand zu stecken. Benutzt die Asche auf dem Boden in der Nähe des Weidenmanns.", description = "Wir verbrennen den Weidenmann als Symbol für unseren Kampf gegen diejenigen, die sich uns in den Weg stellen. Wir tragen die Asche des verbrannten Weidenmanns als Symbol für den niemals endenden Kampf gegen diejenigen, die uns versklaven wollen.\n\nBenutzt das nahe Lagerfeuer, um den Weidenmann zu entzünden. Nehmt Euch dann die herumliegende Asche und beschmiert Euer Gesicht damit.\n\nDiese Gesten werden unsere Feinde daran erinnern, dass wir niemals innehalten werden.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSüßes Saures"}
MultiLanguageQuestData['de'][29377] = {title = "Eine Zeit des Vandalismus", objective = "Benutzt das Löschmittel gegen den Weidenmann vor Sturmwind.", description = "Seid gegrüßt, <Klasse>. Während wir versuchen, uns an der Weidenmannzeremonie zu erfreuen, ist es nicht verwunderlich, dass die Allianz versucht, unsere Feierlichkeiten zu ruinieren.\n\nWir haben die Möglichkeit, es ihnen heimzuzahlen. Falls Ihr Interesse habt, <Klasse>, nehmt dieses Löschmittel und setzt es gegen den Weidenmann der Allianz vor Sturmwind ein.\n\nLöscht ihre Flamme und erfreut Euch an ihrem Leid.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSüßes Saures"}
MultiLanguageQuestData['de'][29382] = {title = "Danke, aber nein danke", objective = "Wenn Euch Euer Geschenk wirklich nicht gefällt, dann könnt Ihr es gegen Gold eintauschen, indem Ihr mit einem Händler der Kokelwälder sprecht.\n\nDer Umtausch lässt sich nicht rückgängig machen.", description = "Ein Feiertagspulli gefällt vielleicht nicht jedem.\n\nAuf dem Beleg steht, dass Ihr ihn bei jedem Händler der Kokelwälder gegen Gold umtauschen könnt.\n\nDer Umtausch lässt sich nicht rückgängig machen.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\n[DND] Summon Gift\n\nIhr bekommt:\n\nBezahlung eines Geizhalses"}
MultiLanguageQuestData['de'][29383] = {title = "Danke, aber nein danke", objective = "Wenn Euch Euer Geschenk wirklich nicht gefällt, dann könnt Ihr es gegen Gold eintauschen, indem Ihr mit einem Händler der Kokelwälder sprecht.\n\nDer Umtausch lässt sich nicht rückgängig machen.", description = "Ein Feiertagspulli gefällt vielleicht nicht jedem.\n\nAuf dem Beleg steht, dass Ihr ihn bei jedem Händler der Kokelwälder gegen Gold umtauschen könnt.\n\nDer Umtausch lässt sich nicht rückgängig machen.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\n[DND] Summon Gift\n\nIhr bekommt:\n\nBezahlung eines Geizhalses"}
MultiLanguageQuestData['de'][29385] = {title = "Ein Winterhauchgeschenk", objective = "Auf dem Schildchen des Geschenks steht:\n\nFrohe Feiertage, <Name>!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWinterhauchgeschenk"}
MultiLanguageQuestData['de'][29386] = {title = "Heldenaufruf: Hyjal!", objective = "Sprecht mit Cenarius' Abgesandter Jademond, um auf die Mondlichtung zu reisen.", description = "Auf Anweisung seiner königlichen Hoheit König Varian Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Botschafterin Windweise in Nachthafen auf der Mondlichtung zu melden.\n\nUnsere Brüder im Zirkel des Cenarius haben uns berichtet, dass Todesschwinges Anhänger einen vernichtenden Angriff gegen den Weltenbaum gestartet haben und drohen, ihn zu verbrennen!\n\nSprecht mit Cenarius' Abgesandter Jademond in Sturmwind, um Zugang zur Mondlichtung zu erlangen.\n\nFür den Ruhm und die Ehre der Allianz! Auf in den Kampf, <Bruder/Schwester>!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29387] = {title = "Die Wächter des Hyjal: Die Invasion der Feuerlande!", objective = "Meldet Euch bei Matookla beim Heiligtum von Malorne am Hyjal.", description = "Die Wächter des Hyjal, angeführt von dem Erzdruiden Malfurion Sturmgrimm, suchen nach tapferen Helden, die bei einem großangelegten Angriff auf die Feuerlande helfen.\n\nFähige Helden der Allianz sollten sich augenblicklich beim Heiligtum von Malorne am Hyjal einfinden.", progress = nil, completion = "Danke, dass Ihr unserem Ruf gefolgt seid, &lt;Name&gt;.", rewards = nil}
MultiLanguageQuestData['de'][29388] = {title = "Die Wächter des Hyjal: Die Invasion der Feuerlande!", objective = "Meldet Euch bei Matookla beim Heiligtum von Malorne am Hyjal.", description = "Die Wächter des Hyjal, angeführt von dem Erzdruiden Malfurion Sturmgrimm, suchen nach tapferen Helden, die bei einem großangelegten Angriff auf die Feuerlande helfen.\n\nFähige Champions der Horde sollten sich augenblicklich beim Heiligtum von Malorne am Hyjal einfinden.", progress = nil, completion = "Danke, dass Ihr unserem Ruf gefolgt seid, &lt;Name&gt;.", rewards = nil}
MultiLanguageQuestData['de'][29389] = {title = "Die Wächter des Hyjal: Die Invasion der Feuerlande!", objective = "Meldet Euch bei Matookla beim Heiligtum von Malorne am Hyjal.", description = "Eure Arbeit hat uns den Vorteil verschafft, den wir brauchen, um gegen die Bewohner der Feuerlande zu mobilisieren. Genau in diesem Moment versammeln wir unsere Invasionsstreitkräfte südlich Eurer Position.\n\nWir könnten Eure Stärke ein weiteres Mal brauchen, <Volk>. Sprecht mit Matookla am Heiligtum von Malorne. Sie koordiniert die Invasionsanstrengungen.", progress = nil, completion = "Danke, dass Ihr unserem Ruf gefolgt seid, &lt;Name&gt;.", rewards = nil}
MultiLanguageQuestData['de'][29390] = {title = "Die Wächter des Hyjal: Der Ruf der Uralten", objective = "Helft Lo'Gosh, Tortolla, Aviana und Aessina beim Hyjal.", description = "Die Wächter des Hyjal, angeführt von dem Erzdruiden Malfurion Sturmgrimm, suchen nach tapferen Helden, die helfen, den Hyjal vor den Elementarangreifern zu schützen. Diese Angreifer müssen zurückgedrängt werden, bevor Streitkräfte für den direkten Angriff auf die Feuerlande mobilisiert werden können.\n\nFähige Helden sollten sich augenblicklich am Hyjal einfinden und den uralten Verteidigern zu Hilfe kommen: Lo'Gosh, Tortolla, Aviana und Aessina.\n\nReisende, die sich zum ersten Mal zum Hyjal aufmachen, können sich nach einem Befehl des Kriegshäuptlings auf einem beliebigen Aufrufbrett der Horde umsehen.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][29391] = {title = "Die Wächter des Hyjal: Der Ruf der Uralten", objective = "Helft Goldrinn, Tortolla, Aviana und Aessina beim Hyjal.", description = "Die Wächter des Hyjal, angeführt von dem Erzdruiden Malfurion Sturmgrimm, suchen nach tapferen Helden, die helfen, den Hyjal vor den Elementarangreifern zu schützen. Diese Angreifer müssen zurückgedrängt werden, bevor Streitkräfte für den direkten Angriff auf die Feuerlande mobilisiert werden können.\n\nFähige Helden sollten sich augenblicklich am Hyjal einfinden und den uralten Verteidigern zu Hilfe kommen: Goldrinn, Tortolla, Aviana und Aessina.\n\nReisende, die sich zum ersten Mal zum Hyjal aufmachen, können sich nach einem Heldenaufruf auf einem beliebigen Aufrufbrett der Allianz umsehen.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][29392] = {title = "Vermisste Erbstücke", objective = "Durchsucht die Kabine auf dem Schiff des angeheuerten Kuriers im Hafen von Sturmwind nach Hinweisen, was den Kurier aufhalten könnte.", description = "Meine letzten Besitztümer hätten eigentlich heute aus Theramore eintreffen sollen. Das Schiff ist angekommen, aber ich habe nichts von dem Kurier gehört. Die Kiste, die er transportieren sollte, enthält Gegenstände, die schon seit Generationen im Familienbesitz sind.\n\nWürdet Ihr vielleicht hinunter zum Hafen von Sturmwind gehen und nachsehen, was ihn aufhält?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29393] = {title = "Gebräu fürs Braufest", objective = "Ihr habt 4 Minuten, um den Widder zu reiten und dabei 3 verschiedene Geschwindigkeitsstufen für jeweils 8 Sekunden zu halten.", description = "Ihr wollt also die Rennwidder testen? Die Zwerge bilden sich ein, dass sie's besonders drauf hätten; aber seien wir mal ehrlich, die meiste Zeit sind sie ja sowieso betrunken, so schwer kann's also gar nicht sein!\n\nSo, bevor Ihr Euch ins Abenteuer stürzt, müsst Ihr mir zeigen, dass Ihr mit diesen feinen, auf legale Weise erworbenen Widdern umgehen könnt.\n\nJetzt zur Abmachung. Ich borge Euch Zügel und lasse Euch auf einem Widder reiten. Mal sehen, was Ihr drauf habt.\n\nLasst den Widder traben, dann leicht galoppieren und schließlich richtig galoppieren. Ihr müsst jede Geschwindigkeit 8 Sekunden lang halten.", progress = nil, completion = "Der Unfall auf dem Weg nach Messerbucht hat den Bierfluss ganz schön ins Stocken gebracht! Und es hilft natürlich überhaupt nicht, dass die Dunkeleisenzwerge gefühlt jede Stunde angreifen!\n\nWenn Ihr also helfen wollt, machen wir es so: Ich borge Euch Zügel und lasse Euch auf einem Widder reiten.\n\nJedes Mal, wenn Ihr mir einen Becher bringt, gebe ich Euch ein paar Abzeichen. Für jeden Becher, den Ihr mir bringt, werde ich Euch den Widder ein wenig länger nutzen lassen!\n\nABER: Wenn Ihr einmal damit angefangen habt, dann könnt Ihr es erst morgen erneut versuchen.\n\nSeid Ihr sicher, dass Ihr bereit seid, es zu versuchen?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBrewfest - Daily - Relay Race Accept - QUEST - DND\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29394] = {title = "Gebräu fürs Braufest", objective = "Ihr habt 4 Minuten, um den Widder zu reiten und dabei 3 verschiedene Geschwindigkeitsstufen für jeweils 8 Sekunden zu halten.", description = "Ihr wollt also die Rennwidder testen? Die Zwerge bilden sich ein, dass sie's besonders drauf hätten; aber seien wir mal ehrlich, die meiste Zeit sind sie ja sowieso betrunken, so schwer kann's also gar nicht sein!\n\nSo, bevor Ihr Euch ins Abenteuer stürzt, müsst Ihr mir zeigen, dass Ihr mit diesen feinen, auf legale Weise erworbenen Widdern umgehen könnt.\n\nJetzt zur Abmachung. Ich borge Euch Zügel und lasse Euch auf einem Widder reiten. Mal sehen, was Ihr drauf habt.\n\nLasst den Widder traben, dann leicht galoppieren und schließlich richtig galoppieren. Ihr müsst jede Geschwindigkeit 8 Sekunden lang halten.", progress = nil, completion = "Beim Braufest besteht immer Bedarf nach weiteren Bechern und Kharanos verfügt über jede Menge Becher, die sie entbehren können!\n\nIch werde Euch die Zügel zu einem meiner Privatwidder leihen.\n\nJedes Mal, wenn Ihr mir einen Becher bringt, gebe ich Euch ein paar Abzeichen. Für jeden Becher, den Ihr mir bringt, werde ich Euch den Widder ein wenig länger nutzen lassen!\n\nBeachtet aber: Wenn Ihr einmal damit angefangen habt, dann könnt Ihr es erst morgen erneut versuchen.\n\nSeid Ihr sicher, dass Ihr bereit seid, es zu versuchen?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBrewfest - Daily - Relay Race Accept - QUEST - DND\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29396] = {title = "Ein neuer Souvenirlieferant", objective = "Löst Euren Gutschein für einen Braufestkrug bei Blix Fixtand im hinteren Teil des Braufestlagers ein.", description = "<seufz>\n\nHört mir auf mit den Krügen vom letzten Jahr...\n\nIch glaube, dass diese zwielichtigen Bierkruglieferanten irgendwas mit diesem merkwürdigen Schattenhammerkult zu tun hatten, der aufgetaucht ist, bevor die Elementare eingefallen sind.\n\nUnd das ist der Grund, warum wir einen neuen Lieferanten und einen besseren Krug haben!\n\nHier habt Ihr einen Gutschein für einen Bierkrug.\n\nSprecht mit Blix in der Nähe des hinteren Endes des Braufestlagers. Er ist ziemlich seltsam, vor allem, weil er immer diese Brille aufhat. Er wird den Gutschein für Euch bearbeiten, und alle anderen Transaktionen des Braufests.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Was ist das? Ein Gutschein für einen Braufestkrug? Ihr trinkt also gerne? Großartig! Sobald Ihr den Krug habt, solltet Ihr Euch ein paar Schluck gönnen... und noch ein paar mehr... und mehr... Dann, und das ist wichtig, kommt wieder hierher zu mir.\n\nIch weiß doch, dass Ihr wieder hierherkommt. Wenn Ihr Eure Gutscheine einlösen möchtet, dann müsst Ihr hierher zu mir.\n\nNaja, hier ist der Krug. Vergesst nicht, später noch einmal mit mir zu sprechen.", rewards = "Ihr bekommt:\n\nÜberquellender violetter Braufestkrug"}
MultiLanguageQuestData['de'][29397] = {title = "Ein neuer Souvenirlieferant", objective = "Löst Euren Gutschein für einen Braufestkrug bei Belbi Blitzknips im Braufestlager ein.", description = "Je weniger Worte wir über die Krüge vom letzten Jahr verlieren, je besser, <Name>. Ich kann Euch sagen, die letzten Lieferanten, das waren zwielichtige Typen. Letztendlich hat sich herausgestellt, dass sie in irgendwelche Kultistenaktivitäten verwickelt waren...\n\nMit Leuten, die versuchen, die Welt zu zerstören, können wir nicht arbeiten!!\n\nDeshalb haben wir uns einen neuen Lieferanten und einen neuen Krug gesucht.\n\nBringt diesen Gutschein zu Belbi Blitzknips im hinteren Teil des Braufestlagers. Sie kümmert sich außerdem um alle sonstigen Braufestgeschäfte, die während der Festtage anstehen.", progress = "Was ist los, Schätzchen? Habt Ihr etwas für mich?", completion = "Ooch, es ist nur ein Gutschein für einen Braufestkrug... vielleicht gebt Ihr Euch ja auch nur so unnahbar. So, hier habt Ihr den diesjährigen Krug.\n\nIch nehme an, dass ich Euch noch öfter hier sehen werde. Denn wenn Ihr Eure Gutscheine einlösen möchtet, dann bin ich Euer Mädel hier...\n\noder vielleicht seins...\n\nooohhh... oder seins...", rewards = "Ihr bekommt:\n\nÜberquellender violetter Braufestkrug"}
MultiLanguageQuestData['de'][29398] = {title = "Hehlerware", objective = "Folgt den Spinnen zu ihrem Ziel und befragt den Mann, den Ihr dort findet.", description = "Eine schnelle Überprüfung der Kabine ergibt keine Hinweise auf die Identität des Mörders oder seine Motive. Die Kiste, wegen der Ihr gekommen seid, ist verschwunden.\n\nWährend Ihr Euch umdreht, um die Kabine zu verlassen, bemerkt Ihr, dass sich am Boden etwas Kleines bewegt. Eine Gruppe Spinnen kriecht unter dem Bett des erschlagenen Kuriers hervor. Wo könnten sie hinwollen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29399] = {title = "Preise vergleichen", objective = "Begebt Euch zum Laden \"Schattenspiele\" im Zwergendistrikt von Sturmwind und sucht nach Hinweisen auf den Besuch des Kistendiebes.", description = "Ich habe dem 'Herrn' gesagt, dass es da einen Laden im Zwergendistrikt gibt, der vielleicht besser geeignet ist für seine Bedürfnisse. Er heißt \"Schattenspiele\" und Ihr findet den Eingang in der Nähe der Kanäle auf der westlichen Seite des Distrikts.\n\nQuincy Messerschmied ist Euer Mann. Er handelt mit Waren, die ein ehrlicher Händler nicht mal mit der Kneifzange anfassen würde!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29400] = {title = "Eine Zeit zum Feiern", objective = "Sprecht mit der Ruferin der Dunkelheit Yanka in den Ruinen von Lordaeron direkt außerhalb des Eingangs zu Unterstadt.", description = "Frohe Grüße, <Klasse>.\n\nDie Schlotternächte sind eine Zeit des Feierns und der Besinnlichkeit, obwohl es scheint, dass viele von uns vergessen haben, warum. Das Verbrennen des Weidenmanns im Besonderen ist ein Rätsel für viele außerhalb der Verlassenen.\n\nBegebt Euch zu den Ruinen von Lordaeron über Unterstadt und sprecht mit der Ruferin der Dunkelheit Yanka. Sie wird Euch mehr von der Weidenmannzeremonie erzählen.", progress = nil, completion = "Die Weidenmannzeremonie ist eine ehrwürdige Tradition. Es ist schön zu sehen, dass die Horde sich uns in den Feierlichkeiten anschließt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29401] = {title = "Weggeweht", objective = "Jaga möchte, dass Ihr 5 entflohene Ballons in Orgrimmar einsammelt.", description = "Bitte, <Onkel/Tante>, Ihr müsst mir helfen!\n\nMein Papa hat mir auf dem Dunkelmond-Jahrmarkt ein paar Luftballons gekauft. Das beste Geschenk... aller... ZEITEN! Sie sind magisch, wisst Ihr, und sie verlieren nie ihre Schwebkraft!\n\nDa gibt es nur ein Problem...\n\nEin riesiger Windstoß hat sie mir direkt aus den Händen gerissen. Jetzt sind sie über ganz Orgrimmar verteilt!\n\nIch würde ja selber hinter ihnen herlaufen, aber die Stadt ist so groß, dass ich mich ganz sicher verlaufen würde.\n\nKönnt Ihr sie für mich einsammeln, bevor sie weggeweht werden?\n\nBitte?", progress = "Habt Ihr alle meine Ballons gefunden, Onkel?", completion = "Das ist so SUPER! Ihr habt es geschafft!\n\nDanke, Onkel!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBallonkind beschwören\n\nIhr bekommt:\n\nHordenballon"}
MultiLanguageQuestData['de'][29402] = {title = "Vorsichtsmaßnahmen", objective = "Besorgt Euch 2 Portionen seltsamen Staub, 5 Kristallphiolen und 5 Blutnesseln.", description = "Ich wäre vorsichtig mit allen, die sich als rechtmäßige Besitzer der Kiste und ihres Inhalts ausgeben. Hat man Euch nicht vor der Gefahr gewarnt?\n\nHier ist eine bessere Idee: Lasst uns zusammenarbeiten, um die Kiste zurückzuholen und sicherzugehen, dass ihr Inhalt niemandem schadet. Um uns selbst zu schützen werden wir ein Gebräu benötigen, das aus einigen Ingredienzien besteht, die in der Stadt zu finden sind.\n\nKauft etwas seltsamen Staub bei einem Reagenzienhändler, besorgt Euch ein paar Phiolen von einem Alchemisten und sammelt ein paar Blutnesseln in den Feldern nördlich der Stadt.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSchutztrank trinken\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29403] = {title = "Der Agent des Sammlers", objective = "Unterbrecht das Treffen zwischen Sanath Lim-yo und dem Dieb in den Katakomben unterhalb der Kathedrale des Lichts.", description = "Quincy zufolge ist der \"Sammler\", der die Kiste haben will, niemand anders als der wahnsinnige Erzmagier Xylem aus Azshara.\n\nDer treue Diener des Erzmagiers soll sich mit dem Mann, der die Kiste hat, in den Katakomben unterhalb der Kathedrale des Lichts treffen.\n\nIhr müsst Euch rechtzeitig dort einfinden, um den Austausch zu verhindern und die Kiste in Euren Besitz zu bringen, bevor sie für immer an Xylem verloren ist. Trefft mich im \"Goldenen Fass\", sobald Ihr die Kiste habt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29404] = {title = "Viel zu lernen", objective = "Sprecht mit Meister Shang Xi.Nun, da Eure Ausbildung begonnen hat, erhaltet Ihr Eure erste, recht simple Aufgabe: Sprecht mit Meister Shang Xi.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Nun, da Eure Ausbildung begonnen hat, erhaltet Ihr Eure erste, recht simple Aufgabe: Sprecht mit Meister Shang Xi.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29405] = {title = "Die Lektion des Eisenstabes", objective = "Nehmt eine Übungswaffe von einem Waffenregal und legt sie an.", description = "Für Eure Ausbildung müsst Ihr Euch zunächst einmal ausstatten. Beschafft Euch eine Waffe von einem der Waffenregale dort unten, bringt sie zu mir und zeigt mir, dass Ihr auch wisst, wie man sie richtig hält.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29406] = {title = "Die Lektion der Sandfaust", objective = "Zerstört 5 Übungsziele.", description = "Ich würde gern beobachten, wie Ihr Euer neues Werkzeug einsetzt, <mein junger Schüler/meine junge Schülerin>. Das wird mir helfen, darüber zu entscheiden, welcher Grad der Ausbildung Euren Talenten am ehesten entspricht.\n\nWir haben dort unten auf dem Ausbildungsgelände eine Menge Übungsziele. Erprobt Eure Angriffe an ihnen und kehrt zu mir zurück, sobald Ihr ein Gefühl für Eure neue Ausrüstung entwickelt habt.", progress = nil, completion = "Gar nicht schlecht, &lt;Name&gt;. Ihr scheint tatsächlich den richtigen Pfad gewählt zu haben.\n\nGut. Lasst uns fortfahren.", rewards = "InitiandengelenkwickelInitiandenarmschienenInitiandenarmschützerDer folgende Zauber wird auf euch gewirkt:\n\nSee Quest Invis 22\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29408] = {title = "Die Lektion der brennenden Schriftrolle", objective = "Entreißt Meister Shang Xi die Flamme und verbrennt dann das Edikt der Mäßigung.", description = "Jede Weisheit hat einen rechten Ort und eine rechte Zeit, aber die Zeiten ändern sich für all diejenigen, die auf Shen-zin Su leben. Für diese Lektion bitte ich Euch um zwei Dinge.\n\nZunächst halte ich eine Flamme in meiner Hand. Konzentriert Euch und versucht, sie mir zu entreißen, sobald Ihr Euch bereit fühlt.\n\nSolltet Ihr erfolgreich sein, möchte ich, dass Ihr den Tempel besteigt und das Edikt der Mäßigung verbrennt, das Ihr dort oben finden könnt.", progress = nil, completion = "Dass Ihr mir die Flamme so einfach entreißen konntet, ist keine geringe Leistung.\n\nDas Edikt der Mäßigung ist eine Schriftrolle mit Weisheiten, die über unzählige Generationen hinweg überliefert worden sind. Weisheiten aus einer friedlicheren Zeit.\n\nJede Lehre hat einen rechten Ort und eine rechte Zeit... und nun, da sich die Dunkelheit am Horizont zusammenbraut, gehört die rechte Zeit dieser Weisheiten der Vergangenheit an.\n\nDas Verbrennen der Schriftrolle stellt die Akzeptanz dieser Zeichen und gleichzeitig ein Versprechen dar, zu handeln. Eure Hand trug die Flamme und ich bin gewiss, dass sie dies auch in Zukunft tun wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29409] = {title = "Die Herausforderung des Schülers", objective = "Besiegt Jaomin Ro.", description = "Ich sehe große Stärke, gewaltigen Mut und eine unübertroffene Reinheit der Seele in Euch, <Name>.\n\nEure Ausbildung hat zwar gerade erst begonnen, aber ich denke, dass Ihr bereits für größere Aufgaben gewappnet seid.\n\nGeht die Treppen hinunter und überquert die Brücke. Dort werdet Ihr Jaomin Ro finden, einen unserer erfahrensten Schüler. Fordert ihn heraus und besiegt ihn in einem ehrenhaften Kampf - dadurch werdet Ihr den ersten Teil Eurer Ausbildung abschließen.", progress = nil, completion = "Sehr beeindruckend, &lt;Name&gt;. Es scheint, dass Ihr als &lt;Klasse&gt; tatsächlich den richtigen Pfad gewählt habt.", rewards = "InitiandenhandschuheInitiandenhandschützerInitiandenstulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29410] = {title = "Aysa, Anhängerin der Tushui", objective = "Sprecht mit Händler Lorvo bei Fus Teich.", description = "In so kurzer Zeit habt Ihr mir gezeigt, dass in Euch das Potenzial steckt, <ein wahrer Meister/eine wahre Meisterin> Eurer Klasse zu werden, <Klasse>. Das Ausbildungsgelände liegt hinter Euch, und nun müsst Ihr Euch beweisen, indem Ihr eine ungleich größere Herausforderung annehmt, die bislang noch keiner meiner Schüler bewältigt hat.\n\nBitte kehrt zu Huo zurück, dem Geist des Feuers im Tempel der Fünf Sonnenaufgänge.\n\nMeine zwei besten Schüler neben Euch werden Euch bei dieser Aufgabe unterstützen. Sucht zunächst bitte Aysa Wolkensänger auf. Ihr findet sie beim Teich im Westen.", progress = nil, completion = "Ihr sucht nach Aysa? Ihr... Ihr solltet sie besser nicht unterbrechen, bis sie mit ihren Übungen fertig ist. Sie spricht mit niemandem, bevor ihre Übung abgeschlossen ist.\n\nKönntet Ihr mir in der Zwischenzeit vielleicht behilflich sein? Ich hatte etwas Pech mit den Waldgeistern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29411] = {title = "Was jetzt?", objective = "Gebt die Kiste Anson Hastings in der \"Güldenen Rose\" in Sturmwind.\n\n-ODER-\n\nGebt die Kiste Hudson Barnes im \"Goldenen Fass\" in Sturmwind.", description = "Endlich habt Ihr die Kiste gefunden, die Anson Euch ausgeschickt hat, zurückzuholen. Es scheint allerdings, dass die Warnungen des Archäologielehrlings korrekt waren.\n\nEs besteht kein Zweifel, dass Euer Auftraggeber Euch bezüglich der Gefahren dieses Auftrags angelogen hat. Wollt Ihr ihm die Kiste wirklich übergeben oder wollt Ihr sie lieber Hudson Barnes geben, der glaubt, dass es besser wäre, den Inhalt der Kiste sicher zu verwahren?Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHeimgesuchte Box abgeben\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29412] = {title = "Weggeweht", objective = "Vin möchte, dass Ihr 5 entflohene Ballons in Sturmwind einsammelt.", description = "Bitte, <Onkel/Tante>, Ihr müsst mir helfen!\n\nMein Papa hat mir auf dem Dunkelmond-Jahrmarkt ein paar Luftballons gekauft. Das beste Geschenk... aller... ZEITEN! Sie sind magisch, wisst Ihr, und sie verlieren nie ihre Schwebkraft!\n\nDa gibt es nur ein Problem...\n\nEin riesiger Windstoß hat sie mir direkt aus den Händen gerissen. Jetzt sind sie über ganz Sturmwind verteilt!\n\nIch würde ja selber hinter ihnen herlaufen, aber die Stadt ist so groß, dass ich mich ganz sicher verlaufen würde.\n\nKönnt Ihr sie für mich einsammeln, bevor sie weggeweht werden?\n\nBitte?", progress = "Habt Ihr alle meine Ballons gefunden, Onkel?", completion = "Das ist so SUPER! Ihr habt es geschafft!\n\nDanke, Onkel!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBallonkind beschwören\n\nIhr bekommt:\n\nAllianzballon"}
MultiLanguageQuestData['de'][29413] = {title = "Die unheimliche Kiste", objective = nil, description = "Nach ihr ist gesucht worden, sie wurde gestohlen und verkauft. Jeder, der versucht hat, die in ihr enthaltene Magie anzuzapfen, musste erleben, dass sich diese Macht gegen ihn wandte.\n\nUnd doch erscheint die Kiste selbst unversehrt zu sein und erfüllt von magischer Energie. Von Zeit zu Zeit zittert und hüpft sie, als ob ihr Inhalt lebendig wäre.\n\nSie scheint an Euch gebunden zu sein und jetzt gehört sie Euch.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nUnheimliche Kiste"}
MultiLanguageQuestData['de'][29414] = {title = "Der Weg der Tushui", objective = "Beschützt Aysa, während sie meditiert.", description = "Es ist mir eine Freude, Eure Bekanntschaft zu machen, <Klasse>. Ich heiße Aysa und bin eine Anhängerin der Tushui.\n\nIch habe viel Zeit mit Nachsinnen verbracht, seit Meister Shang mir offenbart hat, dass die Suche nach Huo, dem Geist des Feuers, unsere Aufgabe sein würde. Ich weiß, wo er sich aufhält, aber nicht, wie man zu ihm gelangen könnte. Die Antworten sind allerdings zum Greifen nah.\n\nFolgt mir zur Höhle der Meditation gleich in der Nähe. Sie ist ein Ort großer Weisheit. Ich werde dort meditieren und meinen Geist öffnen - dann wird der Weg sich uns offenbaren.", progress = nil, completion = "Euer Weg ist vorgezeichnet. Ihr werdet derjenige sein, der den Geist des Feuers neu entfacht und ihn in die Sicherheit des Tempels zurückführt.\n\nDas wird nicht das letzte Mal sein, dass Ihr mit Aysa zusammenarbeitet. Sie ist stark und weise. Ihr könnt ihr vertrauen.", rewards = "InitiandenrobeInitiandenwesteInitiandenbrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29415] = {title = "Vermisste Erbstücke", objective = "Durchsucht die Kabine auf dem Schiff des angeheuerten Kuriers in den Docks östlich von Orgrimmar nach Hinweisen, was den Kurier aufhalten könnte.", description = "Ich habe dem Kurier gesagt, dass er den Zeppelin nehmen soll, aber nein, er musste ja unbedingt ein Goblinschiff nehmen! Na ja, jetzt ist er verspätet und die wertvollen Erbstücke meiner Familie sind bei ihm.\n\nWenn Ihr helfen wollt, könntet Ihr vielleicht hinunter zu den Docks östlich von Orgrimmar gehen, Euch an Bord des Goblinschiffs begeben und nachsehen, was ihn aufhält?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29416] = {title = "Hehlerware", objective = "Folgt den Spinnen zu ihrem Ziel und befragt den Mann, den Ihr dort findet.", description = "Eine schnelle Überprüfung der Kabine ergibt keine Hinweise auf die Identität des Mörders oder seine Motive. Die Kiste, wegen der Ihr gekommen seid, ist verschwunden.\n\nWährend Ihr Euch umdreht, um die Kabine zu verlassen, bemerkt Ihr, dass sich am Boden etwas Kleines bewegt. Eine Gruppe Spinnen kriecht unter dem Bett des erschlagenen Kuriers hervor. Wo könnten sie hinwollen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29417] = {title = "Der Weg der Huojin", objective = "Tötet 8 Fe-Feng-Angreifer.", description = "Wir nennen diese teuflischen Affen, die über die Siedlung herfallen, Ho-zen. Normalerweise bleiben sie unter sich, aber sie spüren, dass irgendetwas Schlimmes bevorsteht, und fangen deshalb an, sich Vorräte zusammenzustehlen.\n\nFür ein Problem wie dieses gibt es nur eine Lösung - eine drastische Lösung. Diese Affen werden verschwinden, wenn wir sie dazu zwingen! Unsere Siedlung und damit diejenigen, die wir lieben, nicht zu verteidigen, wäre das wahre Verbrechen. Das ist der Weg der Huojin.", progress = nil, completion = "Ihr habt aber Mumm in den Knochen! Ich glaube, wir werden gut miteinander auskommen.", rewards = "InitiandengamaschenInitiandenkniehoseInitiandenbeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29418] = {title = "Das Feuer entfachen", objective = "Sammelt 5 trockene Hartriegelwurzeln.", description = "Nun, da diese Angelegenheit erledigt ist, lasst uns also beginnen!\n\nHuo, der Geist des Feuers, hungert nach trockenen Hartriegelwurzelspänen. Hartriegel wächst im Wald südlich des Dorfes. Es sollte Euch ein Leichtes sein, ein paar Wurzeln zu sammeln.", progress = "Ich hoffe, dass Ihr Euch nicht zu fein seid, Euch die Hände schmutzig zu machen.", completion = "&lt;Name&gt;! Ihr seid zurück - und wie ich sehe, habt Ihr die Wurzeln mitgebracht. Ihr seid kein Kerl, der lange fackelt, was?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29419] = {title = "Der vermisste Fahrer", objective = "Rettet den Karrenfahrer.", description = "Mein Fahrer ist den Waldgeistern nachgerannt, kurz nachdem sie uns angegriffen hatten. Ich glaube nicht, dass sie ihm ernsthaft etwas zuleide tun werden, aber ich brauche ihn hier, damit er mir dabei helfen kann, dieses Durcheinander beim Karren in Ordnung zu bringen.\n\nEr hat sie in Richtung der Klippen im Norden gejagt. Wenn Ihr Euch dahin aufmacht, solltet Ihr ihn recht schnell finden können.", progress = nil, completion = "Sehr liebenswürdig, &lt;Klasse&gt;. Vielen Dank.", rewards = "Ihr bekommt:\n\nUmhang der MitfühlendenHändlerranzen"}
MultiLanguageQuestData['de'][29420] = {title = "Der Wächter des Geistes", objective = "Sprecht mit Meister Li Fei im Schrein des Inneren Lichts.", description = "Ihr habt Euch soweit gut geschlagen, <mein Schüler/meine Schülerin>. Ihr seid im Besitz der benötigten Materialien, um Huo, den Geist des Feuers, neu zu entfachen.\n\nEr erwartet Euch in der Höhle im Südwesten, aber er wird von Meister Li Fei bewacht, dem Pandarenältesten, dem Ihr in der Höhle der Meditation begegnet seid. Begebt Euch mit den Opfergaben zu ihm. Beweist Euch und findet dann Huo.", progress = nil, completion = "Im Leben geht es nicht darum, sich selbst zu finden. Es geht darum, sich selbst zu formen. Es liegt ein Weg vor Euch, aber Ihr selbst wählt die Prüfungen, denen Ihr gegenübersteht, und die Prüfungen, die Ihr bestehen werdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29421] = {title = "Nur die Würdigen dürfen passieren", objective = "Besiegt Meister Li Fei im Kampf.", description = "Es ist an der Zeit, dass Ihr mir gegenübertretet. Nun, da diese drei Feuer Euer wahres Potenzial erhellen, werden wir Gewissheit darüber erhalten, ob Eure entschlossene Seele wirklich würdig genug ist, um passieren zu dürfen.", progress = nil, completion = "Erinnert Euch stets daran, dass der überlegene Krieger durch seine Taten glänzen, aber seine Worte maßvoll wählen sollte.", rewards = "Streitkolben des MeistersDolch des MeistersStab des MeistersIhr bekommt:\n\nBrotbeutel des Meisters"}
MultiLanguageQuestData['de'][29422] = {title = "Huo, der Geist des Feuers", objective = "Entfacht Huo, den Geist des Feuers, von Neuem.", description = "Ihr habt Euch als würdig erwiesen, <Klasse>.\n\nHuo, der Geist des Feuers, ruht in der Kammer hinter uns. Lasst ihn sich an den Spänen, die Ihr gesammelt habt, nähren und benutzt den Wind, um seine Flammen anzufachen. Indem Ihr dies tut, werdet Ihr ihn Euch geneigt stimmen. Sobald er entfacht - und gewillt - ist, führt ihn zurück zum Tempel der Fünf Sonnenaufgänge, dem hoch aufragenden Gebäude im Zentrum der Insel.", progress = nil, completion = "&lt;Durch das grelle Licht hindurch sieht es fast so aus, als würde Huo lächeln. Er scheint sich für Euch zu erwärmen.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29423] = {title = "Die Passion von Shen-zin Su", objective = "Bringt den Geist des Feuers in den Tempel der Fünf Sonnenaufgänge.", description = "<Huo springt aufgeregt hin und her. Er ist offensichtlich bereit, Euch zu folgen.>\n\n<Meister Shang Xi hat Euch aufgetragen, Huo zu ihm in den Tempel der Fünf Sonnenaufgänge im Zentrum der Insel zu bringen. Ihr solltet Euch auf den Weg machen.>", progress = nil, completion = "&lt;Name&gt;, Ihr habt Euch sehr gut geschlagen. Huo, der Geist des Feuers, ist hier. Die Flammen des Tempels sind neu entfacht. Ihr habt Eure letzte Herausforderung bestanden, und ohne große Mühe, wie es scheint.\n\nEs gibt auch einen sehr guten Grund dafür, Huo in den Tempel zu bringen. Es ist an der Zeit, dass ich Euch mehr über die bevorstehenden Ereignisse erzähle.", rewards = "Schild des leuchtenden WillensFlammenherzarmbrustSchwert des brennenden GeistesDolch der stummen FlammeDer folgende Zauber wird auf euch gewirkt:\n\nSummon Fire Central Temple Turn-in Controller\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29424] = {title = "Gegenstände von äußerster Wichtigkeit", objective = "Beschafft 6 Übungsmaterialien von den Honigblattstrolchen wieder.", description = "Honigblattstrolche haben meinen Karren umzingelt und die meisten der Übungsmaterialien gestohlen, die ich gerade zum Ausbildungsgelände bringen wollte. Sie waren schon immer Unruhestifter, aber sie sind noch nie so aggressiv gewesen. Ich weiß nicht, was mit ihnen passiert ist.\n\nIch bitte Euch, helft mir, die Materialien wiederzubeschaffen!", progress = "Ihr braucht Euch keine Sorgen darüber zu machen, den Waldgeistern etwas zuleide zu tun. Im Endeffekt sind sie einfach nur sehr quirlige Pflanzen - sie werden schon wieder aufsprießen.", completion = "Vielen Dank! Ihr seid ein ehrenhafter &lt;Klasse&gt;. Eure Ausbildung trägt schon jetzt Früchte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29425] = {title = "Preise vergleichen", objective = "Begebt Euch zum Laden \"Droffers und Sohn Bergungen\" in der Gasse in Orgrimmar und sucht nach Hinweisen auf den Besuch des Kistendiebes.", description = "Passt auf, ich habe diesem zwielichtigen Kerl gesagt, dass es da einen Laden in der Gasse gibt, der seinen, ähm, Waren vielleicht offener gegenübersteht. \"Droffers und Sohn Bergungen\" ist der Name des Geschäfts.\n\nHaltet nach Dran Droffers Ausschau. Er überwacht die 'Bergung' von seltenen und wertvollen Gegenständen aus ganz Azeroth.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29426] = {title = "Vorsichtsmaßnahmen", objective = "Besorgt Euch 2 Portionen seltsamen Staub, 5 Kristallphiolen und 5 Blutnesseln.", description = "Es hat Euch also jemand anders angeheuert, um diese Kiste zu besorgen? Das hört sich für mich gar nicht gut an.\n\nDer Inhalt dieser Kiste gehört unter die Aufsicht der Archäologischen Akademie. Die in ihr enthaltenen Gegenstände sind sehr mächtig und sehr gefährlich.\n\nWir müssen zu dem Treffen gehen, dass Dran zwischen dem Dieb und dem Sammler vereinbart hat, aber zunächst müssen wir uns vor den Effekten schützen, die der Umgang mit der Kiste mit sich bringt.\n\nKauft etwas seltsamen Staub bei einem Reagenzienhändler, besorgt Euch ein paar Phiolen von einem Alchemisten und sammelt ein paar Blutnesseln im Tal der Weisheit.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSchutztrank trinken\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29427] = {title = "Der Agent des Sammlers", objective = "Unterbrecht das Treffen zwischen Sanath Lim-yo und dem Dieb in den Ruinen von Lordaeron.", description = "Dran zufolge ist der \"Sammler\", der die Kiste haben will, niemand anders als der wahnsinnige Erzmagier Xylem aus Azshara.\n\nDer treue Diener des Erzmagiers soll sich mit dem Mann, der die Kiste hat, in einer versteckten Ecke im Hof der Ruinen von Lordaeron treffen.\n\nSchnell, nehmt den Zeppelin nach Tirisfal!\n\nIhr müsst Euch rechtzeitig dort einfinden, um den Austausch zu verhindern und die Kiste in Euren Besitz zu bringen, bevor sie für immer an Xylem verloren ist. Trefft mich im \"Wyvernschweif\" im Tal der Ehre, sobald Ihr die Kiste habt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29428] = {title = "Was jetzt?", objective = "Ihr könnt die Kiste entweder Edgar Siegesfroh im \"Gebrochenen Hauer\" in Orgrimmars Tal der Stärke zurückbringen.\n\n-ODER-\n\nIhr könnt die Kiste Delian Sonnenschatten im \"Wyvernschweif\" in Orgrimmars Tal der Ehre übergeben.", description = "Endlich habt Ihr die Kiste gefunden, die Edgar Euch ausgeschickt hat, zurückzuholen. Es scheint allerdings, dass die Warnungen des Repräsentanten der Archäologischen Akademie korrekt waren.\n\nEs besteht kein Zweifel, dass Euer Auftraggeber Euch bezüglich der Gefahren dieses Auftrags angelogen hat. Wollt Ihr ihm die Kiste wirklich übergeben oder wollt Ihr sie lieber Delian Sonnenschatten geben, der glaubt, dass es besser wäre, den Inhalt der Kiste sicher zu verwahren?Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHeimgesuchte Box abgeben\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29429] = {title = "Die unheimliche Kiste", objective = nil, description = "Nach ihr ist gesucht worden, sie wurde gestohlen und verkauft. Jeder, der versucht hat, die in ihr enthaltene Magie anzuzapfen, musste erleben, dass sich diese Macht gegen ihn wandte.\n\nUnd doch erscheint die Kiste selbst unversehrt zu sein und erfüllt von magischer Energie. Von Zeit zu Zeit zittert und hüpft sie, als ob ihr Inhalt lebendig wäre.\n\nSie scheint an Euch gebunden zu sein und jetzt gehört sie Euch.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nUnheimliche Kiste"}
MultiLanguageQuestData['de'][29430] = {title = "Ein Freund in der Not", objective = "Besucht Anson Hastings in der \"Güldenen Rose\" in Sturmwinds Handelsdistrikt.", description = "Wisst Ihr, ich habe Anson noch gar nicht hier draußen gesehen.\n\nIn letzter Zeit verbringt er seine ganze Zeit damit, sich in der \"Güldenen Rose\" volllaufen zu lassen.\n\nEtwas muss ihm wirklich an die Nieren gehen! Würdet Ihr vielleicht mal nach ihm sehen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29431] = {title = "Ein Freund in der Not", objective = "Sprecht mit Edgar Siegesfroh im \"Gebrochenen Hauer\" in Orgrimmar.", description = "Mit meinem Freund Edgar ist etwas nicht in Ordnung. Normalerweise liebt er die Festivitäten rund um die Schlotternächte.\n\nEr verbringt seine ganze Zeit damit, in der Kneipe \"Zum Gebrochenen Hauer\" in Orgrimmar mit den Orcs zu trinken. Wäret Ihr so gut und würdet mal bei ihm vorbeischauen und nachsehen, ob es irgendwas gibt, womit man ihn aufmuntern könnte?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29433] = {title = "Beweist Eure Stärke", objective = "Kerri Hicks möchte, dass Ihr 250 grausige Trophäen erbeutet. Um sie zu bekommen, müsst Ihr Wesen töten, die Euch Erfahrung oder Ehre gewähren und den Abenteuerführer des Dunkelmond-Jahrmarkts bei Euch tragen.", description = "Einige Leute haben so lange Spaß, bis jemand verletzt wird. Ich nenne solche Leute Schwächlinge.\n\nWahre Stärke beweist nur der, der jemanden oder etwas verletzt. Ihr verletzt Euch selbst, weil Ihr Euren Körper an seine Grenzen führt, und Ihr verletzt die, die anderen schaden wollen.\n\nWenn Ihr der Stärkste sein wollt, müsst Ihr kämpfen. Wie wichtig ist Euch das?\n\nIch will, dass Ihr die niederstreckt, die Euch herausfordern und mir einen Beweis Eures Triumphs bringt.", progress = "Ohne Fleiß kein Preis.", completion = "Habt Ihr Euch Herausforderungen gesucht oder einfach nur Eber auf einem Feld abgeschlachtet?\n\nIch bin aus gutem Grund die Stärkste.\n\nVielleicht werde ich Euch eines Tages zeigen, wie stark ich wirklich bin, &lt;Klasse&gt;. Bis dahin müsst Ihr Euch weiter anstrengen, aber vergesst nicht, ab und zu eine Pause zu machen.\n\nSo wie jetzt zum Beispiel. Hier, genießt den Dunkelmond-Jahrmarkt.", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29434] = {title = "Panzergeneral", objective = "Zerstört mit Eurem Dunkelmond-Panzer 30 Ziele in der veranschlagten Zeit.", description = "Willkommen zu unserem bescheidenen kleinen Dampfpanzerkampf-Simulator! Für nur einen Spieljeton könnt Ihr Euer strategisches Können unter Beweis stellen. Fahrt über unseren Parcours und zerstört die Panzerziele.", progress = "Aufgetankt und einsatzbereit!", completion = "Eine beeindruckende Demonstration!\n\nHier ist Eure Belohnung.", rewards = "Ihr bekommt:\n\nDunkelmond-SpielpreisGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29436] = {title = "Die menschliche Kanonenkugel", objective = "Erreicht 5 Kanonenzielpunkte, indem Ihr in der Nähe des Kanonenziels landet.", description = "Für nur einen Spieljeton des Dunkelmond-Jahrmarkts könnt Ihr Euch aus der Blastenheimer 5000 Ultrakanone abschießen lassen. Doch damit ist der Spaß noch nicht vorbei! Wir haben ein Ziel im Meer nahe des Piers aufgebaut.\n\nWenn Ihr bei Euren Landungen fünf Punkte erzielt, könnt Ihr Gewinnlose bekommen.\n\nEin Treffer ins Schwarze bringt 5 Punkte, einer ins Ziel 3 Punkte und einer knapp neben dem Ziel 1 Punkt.\n\nViel Glück bei der Landung!", progress = "Hals und Beinbruch!", completion = "5 Punkte? Gut gemacht! Hier sind Eure Lose.\n\nViel Spaß auf dem Rest des Dunkelmond-Jahrmarkts!", rewards = "Ihr bekommt:\n\nDunkelmond-SpielpreisGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29437] = {title = "Der gefallene Wächter", objective = "Stellt und tötet Alysra bei den Ruinen von Lar'donir.", description = "Fandral Hirschhaupt ist hier auf dem Hyjal gefangen gehalten worden. Es war der grüne Drache Alysra - eine von uns! -, die damit beauftragt war, Fandral zu bewachen.\n\nWir können nur vermuten, dass es dem Schattenhammer gelungen ist, sie zu verderben. Ihr müsst sie stellen, <Name>. Vernichtet sie, wenn es sein muss - ich kann es nicht ertragen, dabei zuzusehen.\n\nZuletzt wurde sie bei den Ruinen von Lar'donir gesichtet, westlich des Weltenbaums.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29438] = {title = "Er schießt, er trifft!", objective = "Erreicht 25 Punkte in 60 Sekunden.", description = "Glaubt Ihr, dass Ihr gut schießen könnt? Habt Ihr eine ruhige Hand?\n\nWie wäre es dann mit ein paar Schüssen?\n\nEs kostet Euch nur einen Spieljeton, Eure Fähigkeiten unter Beweis zu stellen.\n\nNa, wie gut seid Ihr?", progress = "Ein stehendes Ziel zu treffen, ist nicht so einfach, wie es aussieht.", completion = "Ich wusste, dass Ihr das schafft, &lt;Klasse&gt;. Hier ist Euer Preis. Genießt den Jahrmarkt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWhack! Summon Aura\n\nIhr bekommt:\n\nDunkelmond-SpielpreisGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29439] = {title = "Der Ruf des Weltenschamanen", objective = "Sprecht mit Thrall, direkt südlich des Weltenbaums auf dem Hyjal.", description = "Der Irdene Ring bittet Euch erneut um Eure Mithilfe, <Name>.\n\nAls ein Mitglied der Allianz weiß ich, dass Ihr möglicherweise Bedenken hegt, mit dem, den Ihr Thrall nennt, dem früheren Kriegshäuptling der Horde, zusammenzuarbeiten. Aber er hat explizit darum gebeten, dass es ein Held der Allianz ist, der ihm bei seiner nächsten Unternehmung zur Seite steht, bei einem Heilungsritual, das tiefgreifende Auswirkungen auf unsere Welt haben wird.\n\nLasst Eure Zweifel beiseite, <Klasse>, und antwortet dem Ruf des Weltenschamanen.\n\nIhr werdet ihn unter den Zweigen von Nordrassil auf dem Hyjal finden, auf der südlichen Seite des Baums.", progress = nil, completion = "Es scheint, als wäre meine Nachricht in Sturmwind angekommen.\n\nIch danke Euch, &lt;Name&gt;. Dann wollen wir uns mal an die Arbeit machen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29440] = {title = "Der Ruf des Weltenschamanen", objective = "Sprecht mit Thrall, direkt südlich des Weltenbaums auf dem Hyjal.", description = "Der Irdene Ring bittet Euch erneut um Eure Mithilfe, <Name>.\n\nThrall hat sein Amt als Kriegshäuptling der Horde niedergelegt, aber für seine neue Aufgabe benötigt er die Unterstützung seines Volkes mehr als je zuvor. Er hat darum gebeten, dass einer der besten Streiter der Horde ihm bei seiner nächsten Unternehmung zur Seite steht, bei einem Heilungsritual, das tiefgreifende Auswirkungen auf unsere Welt haben wird.\n\nIhr werdet ihn unter den Zweigen von Nordrassil auf dem Hyjal finden, auf der südlichen Seite des Baums.", progress = nil, completion = "Es scheint, als wäre meine Nachricht in Orgrimmar angekommen.\n\nIch danke Euch, &lt;Name&gt;. Dann wollen wir uns mal an die Arbeit machen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29441] = {title = "Aus dem Bauch der Bestie", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][29443] = {title = "Ein merkwürdiger Kristall", objective = "Bringt den energiegetränkten Kristall zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", description = "Energie wirbelt in dem seltsamen Kristall umher. Vielleicht diente er einst als magischer Brennpunkt, als Energiequelle oder als simpler Glücksbringer. Das lässt sich nicht sicher sagen.\n\nDer Abenteuerführer des Dunkelmond-Jahrmarkts weist Euch darauf hin, dass sich Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt dafür interessieren könnte.", progress = "Was habt Ihr denn da?", completion = "Wo habt Ihr den her?\n\nSolche Kristalle sind sehr selten, viele Sammler suchen danach. Ich würde diesen gern untersuchen und auf dem Jahrmarkt ausstellen. Würdet Ihr ihn gegen eine großzügige Anzahl von Losen des Dunkelmond-Jahrmarkts eintauschen?", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29444] = {title = "Ein exotisches Ei", objective = "Bringt das monströse Ei zu Yebb Nabetand auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", description = "Ihr seid Euch nicht sicher, welches Wesen sich in diesem Ei befindet, aber das Ei stammt sicherlich nicht von einem normalen Tier.\n\nIm Abenteuerführer des Dunkelmond-Jahrmarkts heißt es, ein unerschrockener Abenteurer könne bei seinen Reisen auf eine ganze Reihe seltsamer Eier stoßen. Außerdem weist er darauf hin, dass das Kuriositätenkabinett auf dem Dunkelmond-Jahrmarkt stets am Erwerb solcher Exemplare interessiert ist.\n\nBringt das Ei zu Yebb Nabetand auf dem Dunkelmond-Jahrmarkt.", progress = "Was habt Ihr denn da?", completion = "Wo habt Ihr dieses Ei gefunden? Darin verbirgt sich sicherlich etwas Monströses und Wunderbares. Ein sehr passender Neuzugang für unseren Zoo. Würdet Ihr Euch davon für eine großzügige Anzahl Lose des Dunkelmond-Jahrmarkts trennen?", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29445] = {title = "Ein faszinierender Zauberfoliant", objective = "Bringt den geheimnisvollen Zauberfolianten zu Sayge auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", description = "Ihr findet keinen Hinweis auf den Ursprung dieses gewaltigen magischen Werkes. Seine Seiten sind voll mit Zaubern und Verzauberungen, von denen Euch nur einige wenige vertraut sind.\n\nIm Abenteuerführer des Dunkelmond-Jahrmarkts steht, der Foliant könnte für Sayge, den berühmten gnollischen Jahrmarktswahrsager auf dem Dunkelmond-Jahrmarkt, von Interesse sein.", progress = "Was habt Ihr denn da?", completion = "Ein seltsamer Zauberfoliant, wie interessant! So einen habe ich noch nie gesehen. Ich hätte ihn sehr gern für meine Sammlung. Würdet Ihr ihn gegen Lose des Dunkelmond-Jahrmarkts eintauschen?", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29446] = {title = "Eine wundersame Waffe", objective = "Bringt die verzierte Waffe zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", description = "Ihr untersucht die Waffe und seht, dass sie hervorragend verarbeitet und edel verziert ist. Einige winzige Scharten weisen darauf hin, dass sie auch im Kampf benutzt wurde.\n\nIm Abenteuerführer des Dunkelmond-Jahrmarkts sind verschiedene seltene und wertvolle Waffen aufgeführt, daher würde sich Professor Thaddeus Paleo vom Dunkelmond-Jahrmarkt bestimmt für dieses Stück interessieren.", progress = "Was habt Ihr denn da?", completion = "Wo habt Ihr eine solch wundervolle Klinge gefunden?\n\nWas für eine Verarbeitung! Das ist wahrlich eine Waffe, mit der sich jeder Held schmücken könnte. Ich würde sie sehr gern ausstellen.\n\nWürdet Ihr eine großzügige Anzahl Lose des Dunkelmond-Jahrmarkts dafür annehmen?", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29451] = {title = "Der Meisterstratege", objective = "Bringt die Abhandlung zu strategischem Vorgehen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", description = "Dieser Foliant über Strategie ist das Meisterwerk des berühmten menschlichen Generals Anduin Lothar. Darin beschreibt der Kommandant in seinen eigenen Worten die korrekte Aufstellung einer Armee und Strategien, mit denen man fast jede Schlacht gewinnen kann.\n\nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt würde sich bestimmt für ein so seltenes Buch interessieren.", progress = "Das sieht nach einem sehr seltenen Buch aus…", completion = "Ich weiß nicht, wie Ihr daran gekommen seid und ich bin klug genug, nicht zu fragen. Würdet Ihr Euch für Lose des Dunkelmond-Jahrmarkts davon trennen?", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29452] = {title = "Eure Zeit ist gekommen", objective = "Sprecht mit Ziradormi in Orgrimmar.", description = "<Ein angenehmes Bild erscheint vor Eurem inneren Auge, als eine ruhige Stimme Euren Körper erfüllt.>\n\n<Junger/Junge:c> <Klasse>, seid ganz ruhig und hört meine Worte.\n\nIch wurde gerufen, um Euch abzuholen und abzuliefern, bei jemandem, dessen Blick niemand entkommt.\n\nFindet mich in Orgrimmar, sterbliches Wesen, denn Eure Zeit ist gekommen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29453] = {title = "Eure Zeit ist gekommen", objective = "Sprecht mit Coridormi in Sturmwind.", description = "<Ein angenehmes Bild erscheint vor Eurem inneren Auge, als eine ruhige Stimme Euren Körper erfüllt.>\n\n<Junger/Junge:c> <Klasse>, seid ganz ruhig und hört meine Worte.\n\nIch wurde gerufen, um Euch abzuholen und abzuliefern, bei jemandem, dessen Blick niemand entkommt.\n\nFindet mich in Sturmwind, sterbliches Wesen, denn Eure Zeit ist gekommen.", progress = nil, completion = "Lasst uns beginnen, sterbliches Wesen.\n\nWir haben keine Zeit zu verschwenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29455] = {title = "Werft den Ring", objective = "Werft 3 Ringe auf die Dunkelmond-Schildkröte.", description = "Hey Ihr! Haltet ein!\n\nWollt Ihr allen beweisen, wie talentiert Ihr seid? Sorgt dafür, dass drei Ringe auf der Dunkelmond-Schildkröte landen, dann bekommt Ihr eine Belohnung.\n\nFür einen Spieljeton könnt Ihr einen Stapel Ringe kaufen, um der Welt zu zeigen, warum wir Euch auf dem Jahrmarkt <Name>, \"<den Adleräugigen/die Adleräugige>\" nennen.", progress = "Geht's dem Wurfarm gut?", completion = "Ich wusste, dass Ihr das könnt, &lt;Klasse&gt;. Gebt uns die restlichen Ringe, falls welche übrig sind, dann bekommt Ihr Euer Gewinnlos.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWhack! Summon Aura\n\nIhr bekommt:\n\nDunkelmond-SpielpreisGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29456] = {title = "Ein erbeutetes Banner", objective = "Bringt das Banner der Gefallenen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", description = "Auf dem zerschlissenen Banner ist ein verblasstes Gildenwappen zu sehen. Das alte Banner muss viele Schlachten mitgemacht haben.\n\nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt sammelt Banner und andere Kriegsrelikte. Vielleicht wäre er auch an diesem interessiert. Zeigt ihm das Banner, wenn Ihr den Dunkelmond-Jahrmarkt das nächste Mal besucht.", progress = "Was habt Ihr denn da?", completion = "Was für ein wundervolles Banner! Das hätte ich gerne in meiner Sammlung.\n\nWürdet Ihr es mir für einige Lose des Dunkelmond-Jahrmarkts überlassen?", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29457] = {title = "Das Insigne des Feindes", objective = "Bringt das eroberte Insigne zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", description = "Das Insigne eines gegnerischen Offiziers ist auf dem zerbeulten Abzeichen zu sehen. Für Euch ist es kaum mehr wert als das Metall, aus dem es besteht, aber für einen Sammler von Kriegsandenken wäre es von großem Interesse.\n\nDie Sammlung von Kriegsartefakten, die Professor Thaddeus Paleo vom Dunkelmond-Jahrmarkt zusammengetragen hat, ist in ganz Azeroth bekannt. Zeigt ihm das Abzeichen, wenn Ihr den Dunkelmond-Jahrmarkt das nächste Mal aufsucht.", progress = "Was habt Ihr denn da?", completion = "Das ist ein bemerkenswert gut erhaltenes Offiziersinsigne der Allianz. Viele Offiziere besuchen zwar den Jahrmarkt, aber keiner von ihnen will sich von seinen Abzeichen trennen. Würdet Ihr einige Lose des Dunkelmond-Jahrmarkts dafür annehmen?", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29458] = {title = "Das erbeutete Tagebuch", objective = "Bringt das Tagebuch eines Abenteurers zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", description = "Der Umschlag des Buches besteht aus abgewetztem, mit Blut und Schlamm besudeltem Leder. Ihr blättert die Seiten durch und erkennt, dass es sich um das Tagebuch eines Abenteurers handelt, der sehr von sich und seinen Abenteuern eingenommen ist.\n\nProfessor Thaddeus Paleo vom Dunkelmond-Jahrmarkt könnte sich dafür interessieren.", progress = "Was habt Ihr denn da?", completion = "Ein bemerkenswerter Fund!\n\n&lt;Der Professor blättert in dem Buch.&gt;\n\nEinige Seiten sind kaum noch lesbar, aber wenn auch nur ein Drittel des Inhalts der Wahrheit entspricht, handelt es sich um einen wahren Schatz. Würdet Ihr es gegen eine großzügige Anzahl Lose des Dunkelmond-Jahrmarkts eintauschen?", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29463] = {title = "Hau-den-Gnoll", objective = "Erreicht 30 Punkte beim Gnollhauen.", description = "Wollt Ihr ein paar Gnolle hauen? Dann seid Ihr am richtigen Ort.\n\nEure Aufgabe ist einfach: Erreicht 30 Punkte in einer Minute.\n\nBenutzt den Holzhammer, den ich Euch geben werde und legt los. Sprecht mich an, wenn Ihr bereit seid.", progress = "Wie habt Ihr Euch geschlagen?", completion = "Ihr habt die Gnolle also besiegt. Fühlte sich gut an, oder?\n\nHier ist Euer Preis. Genießt den Rest des Dunkelmond-Jahrmarkts!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWhack! Summon Aura\n\nIhr bekommt:\n\nDunkelmond-SpielpreisGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29464] = {title = "Werkzeuge der Weissagung", objective = "Bringt die Wahrsagerrunen zu Professor Thaddeus Paleo auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", description = "Diese Sammlung abgenutzter Runensteine wurde offensichtlich häufig benutzt. Die Steine wirken alt. Ihr könnt die Einkerbungen auf ihnen nicht zuordnen.\n\nEin Gelehrter oder Sammler könnte mehr darüber wissen. Bringt sie zu Professor Thaddeus Paleo, wenn Ihr den Dunkelmond-Jahrmarkt das nächste Mal besucht.", progress = "Was habt Ihr denn da?", completion = "Wo habt Ihr diese Runensammlung her? So eine habe ich seit Jahren nicht mehr gesehen. Es wird mir eine Freude sein, ihr Rätsel zu entschlüsseln!\n\nWürdet Ihr einige Lose des Dunkelmond-Jahrmarkts dafür annehmen?", rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29469] = {title = "Wiederbewaffnung, Wiederverwendung, Wiederverwertung", objective = "Beschafft 6 Stücke Panzerschrott vom Lagerplatz des Dunkelmond-Jahrmarkts.", description = "Die Jahrmarktsbesucher lieben unsere Dampfpanzer! Wenn der Dunkelmond-Jahrmarkt schließt, liegt all der Panzerschrott auf dem Platz herum.\n\nWäre doch schade, wenn das gute Metall einfach im Dreck verrotten würde.\n\nWäret Ihr so nett, mir einige der größeren Stücke zu bringen, damit ich die kaputten Panzerteile damit reparieren kann? Das ist weitaus billiger als jedes Mal neues Metall zu kaufen. Was meint Ihr?Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSpieljeton des Dunkelmond-JahrmarktsGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29475] = {title = "Gobliningenieurskunst", objective = "Bringt 20 große Eisenbomben, 20 Stangen robustes Dynamit und 5 explodierende Schafe zu einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt.", description = "Ein geübter Ingenieur kann sich für EINE Spezialisierung entscheiden. Ich kenne die Geheimnisse der Gobliningenieurskunst.\n\nIhr seht aus, als würdet Ihr gern Dinge in die Luft jagen, aber ich benötige Proben Eurer Arbeit. Bringt mir zwanzig große Eisenbomben, zwanzig Stangen robustes Dynamit und fünf explodierende Schafe.\n\nWenn Ihr diese Gegenstände zu einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt bringt, wird er Euch offiziell zum Gobliningenieur mit Zugang zu allen Bauplänen ernennen!", progress = "Überlasst mir Eure gefertigten Ingenieurskunstgegenstände zur Bewertung, dann werde ich Euch das Wissen vermitteln, das Ihr benötigt, um Mitglied im exklusiven Club der Gobliningenieure zu werden.", completion = "Anscheinend seid Ihr tatsächlich bereit für eine richtige Ausbildung. Hiermit ernenne ich Euch zum Gobliningenieur, &lt;Name&gt;!\n\nIhr könnt Euch die teuflischen Erfindungen aller Gobliningenieure ansehen. Genießt es und versucht, Euch nicht in die Luft zu sprengen.", rewards = "Ihr erlernt:\n\nGobliningenieur\n\nDer folgende Zauber wird auf euch gewirkt:\n\nGobliningenieurskunst"}
MultiLanguageQuestData['de'][29477] = {title = "Gnomeningenieurskunst", objective = "Bringt 6 Mithrilrohre, ein genaues Zielfernrohr und zwei hochentwickelte Zielattrappen zu einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt.", description = "Ein geübter Ingenieur kann sich für EINE Spezialisierung entscheiden. Ich kann Euch die Gnomeningenieurskunst beibringen.\n\nIhr scheint zwar zu wissen, was Ihr tut, aber ich benötige einige Proben Eurer Arbeit. Bringt mir sechs Mithrilrohre, ein genaues Zielfernrohr und zwei hochentwickelte Zielattrappen.\n\nSobald Ihr diese Gegenstände bei einem Ingenieurskunstlehrer in einer beliebigen Hauptstadt abgebt, seid Ihr offiziell ein Gnomeningenieur und erhaltet Zugriff auf alle Baupläne!", progress = "Sobald Ihr mir Eure gefertigten Ingenieurskunstgegenstände zur Bewertung unterbreitet habt, könnt Ihr ein zertifizierter Gnomeningenieur werden. Dann erhaltet Ihr uneingeschränkten Zugriff auf alle Baupläne der Gnomeningenieure.", completion = "Am heutigen Tag wird aus Euch ein echter Ingenieur, &lt;Name&gt;. Macht Euch keine Gedanken mehr über diese schmutzigen Bomben und Sprengstoffe, denn Ihr werdet bald über Euch selbst hinauswachsen.", rewards = "Ihr erlernt:\n\nGnomeningenieur\n\nDer folgende Zauber wird auf euch gewirkt:\n\nGnomeningenieurskunst"}
MultiLanguageQuestData['de'][29481] = {title = "Meister der Elixiere", objective = "Bringt eine Reihe verschiedener Fläschchen zu einem Alchemielehrer.", description = "Bei Elixieren geht es nur um Stärke! Ich kann Euch zum Meister der Elixiere ausbilden, wenn Ihr das wünscht.\n\nDas ist nichts für jeden und ich verlange einen Beweis für Eure Ernsthaftigkeit, bevor wir fortfahren können. Mit einigen Fläschchen könnt Ihr mir Eure Entschlossenheit zeigen.\n\nVergesst nicht, <Name>, dass Ihr nur EINE Spezialisierung erlernen könnt. Wenn Ihr die Elixierbeherrschung abgeschlossen habt, werden Euch Tränke und Transmutation nicht mehr angeboten.", progress = "Habt Ihr die Fläschchen?", completion = "Sehr gut!", rewards = "Ihr erlernt:\n\nMeister der Elixiere\n\nDer folgende Zauber wird auf euch gewirkt:\n\nMeister der Elixiere"}
MultiLanguageQuestData['de'][29482] = {title = "Meister der Transmutation", objective = "Bringt die verlangten Materialien zu einem Alchemielehrer in einer beliebigen Hauptstadt.", description = "Eisen zu Gold, Wasser zu Feuer... ich kann Euch helfen, wenn Ihr ein Meister der Transmutation werden wollt.\n\nDie Ausbildung ist sehr teuer, also müsst Ihr mir einige der besten transmutierten Materialien der Welt bringen.\n\nVergesst nicht, <Name>, dass Ihr nur EINE Spezialisierung erlernen könnt. Wenn Ihr die Transmutationsbeherrschung abgeschlossen habt, werden Euch Tränke und Elixiere nicht länger angeboten.", progress = "Habt Ihr die Materialien?", completion = "Sehr gut!", rewards = "Ihr erlernt:\n\nMeister der Transmutation\n\nDer folgende Zauber wird auf euch gewirkt:\n\nMeister der Transmutation"}
MultiLanguageQuestData['de'][29506] = {title = "Eine prickelnde Mischung", objective = "Mischt mit Hilfe des Cocktail-Shakers aus Mondbeerensaft und prickelndem Marktgetränk 5 Krüge Mondbeerenfizz.", description = "Als <Alchemist/Alchemistin> habt Ihr sicherlich schon zahlreiche Tränke gebraut. Würdet Ihr mir vielleicht bei etwas weniger Gehaltvollem helfen?\n\nIch wollte immer schon eine fruchtige Variante unserer beliebten Prickelgetränke kreieren. Wenn Ihr Euch daran versuchen wollt, würde ich Euch das Basisgetränk verkaufen. Anschließend mischt Ihr es mit etwas Mondbeerensaft.\n\nEin Gastwirt im Wald von Elwynn oder in Mulgore wird Euch genügend Saft für Eure Kreation verkaufen können.", progress = "Was macht der Mondbeerenfizz?", completion = "Eure Kreation sieht vielversprechend aus. Mit ein wenig Glück werden wir bald ein neues Lieblingsgetränk haben!\n\nIch danke Euch für Eure Hilfe!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\n[DNT] Quest Complete: A Fizzy Fusion TRACKER\n\nIhr bekommt:\n\nSpieljeton des Dunkelmond-JahrmarktsGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29507] = {title = "Spaß für die Kleinen", objective = "Bringt 15 mit Archäologie aufgespürte Fossilienfragmente zu Professor Thaddeus Paleo beim Dunkelmond-Jahrmarkt.", description = "Kinder fragen so oft, was ein Archäologe tut und wie Archäologie funktioniert, dass ich eine kleine Demonstration für sie vorbereitet habe.\n\nIch vergrabe Artefakte und Fossilien im Sandkasten hinter dem Zelt. Die Kinder können sie ausgraben und so ihre eigenen Entdeckungen machen, lernen, wie man Knochen zusammensetzt und herausfinden, was ihnen die Archäologie über Geschichte beibringen kann.\n\nWürdet Ihr mir einige Fossilien für mein Projekt spenden, solltet Ihr welche übrig haben?", progress = "Wie sieht es aus? Wollt Ihr ein paar Fossilienfragmente spenden?", completion = "Großartig! Die Kinder werden sich sehr freuen, wenn sie diese Teile \"entdecken\".", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\n[DNT] Quest Complete: Fun for the Little Ones TRACKER\n\nIhr bekommt:\n\nSpieljeton des Dunkelmond-JahrmarktsGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29508] = {title = "Baby braucht zwei Paar Schuhe", objective = "Stellt aus den Eisenbeständen 4 Hufeisen her und legt sie Baby auf dem Dunkelmond-Jahrmarkt an.", description = "Habt Ihr meine Stute Baby da hinten neben den Wagen gesehen? Sie zieht den Karren mit allen Tieren unseres Kuriositätenkabinetts.\n\nSie arbeitet hart und braucht mehr Hufeisen, als Ihr Euch vorstellen könnt. Es ist wieder einmal Zeit für neue. Die Rohmaterialien habe ich bereits gekauft.\n\nIhr müsst sie nur auf einem Amboss bearbeiten und Baby anlegen. Geht schnell und ist mir ein paar Lose wert, also was meint Ihr?", progress = "Wie geht's dem alten Mädchen?", completion = "Danke für Eure Hilfe, &lt;Name&gt;! Hier ist die versprochene Bezahlung.", rewards = "Ihr bekommt:\n\nSpieljeton des Dunkelmond-JahrmarktsGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29509] = {title = "Wie der Frosch knusprig wird", objective = "Bereitet 5 Knusperfrösche zu, indem Ihr Eure fetten Frösche in herkömmlichem Mehl wälzt und in dem Kessel hinter Stampf Donnerhorn bratet.", description = "Die Knusperfrösche des Dunkelmond-Jahrmarkts sind in ganz Azeroth berühmt!\n\nWir haben gerade frische Frösche bekommen. Warum helft Ihr uns nicht bei der Zubereitung und tut gleichzeitig etwas für Eure Kochkunst?\n\nDas Mehl, in dem Ihr die Frösche wälzen müsst, bekommt Ihr bei jedem Handwerkswarenhändler im Wald von Elwynn oder in Mulgore.", progress = "Rieche ich etwa frische Knusperfrösche?", completion = "Die sind auf den Punkt gebraten, &lt;Name&gt;. Sehr gute Arbeit.", rewards = "Ihr bekommt:\n\nSpieljeton des Dunkelmond-JahrmarktsGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29510] = {title = "Auch Abfall kann nützlich sein", objective = "Sammelt 6 Wahrsagerstaub, indem Ihr die abgelegten Waffen, die auf dem Platz des Dunkelmond-Jahrmarkts liegen, entzaubert.", description = "Die Leute kommen nicht nur zum Spaß auf den Jahrmarkt, <Name>. Die meisten wollen auch etwas mit nach Hause nehmen, deshalb helfe ich bei der Herstellung der magischen Schmuckstücke, die Besucher mit ihren Gewinnlosen kaufen können.\n\nDafür benötige ich ständig Wahrsagerstaub. Seht Euch auf dem Platz um, da gibt es jede Menge abgelegter Waffen. Diese Gegenstände kann jemand wie Ihr, der die Kunst des Verzauberns beherrscht, in Staub verwandeln. Würdet Ihr mir helfen?", progress = "Habt Ihr etwas Wahrsagerstaub bekommen?", completion = "Das hilft mir schon mal weiter. Wenn Ihr noch einmal helfen wollt, besucht einfach den alten Sayge, wenn der Dunkelmond-Jahrmarkt in der Stadt ist.", rewards = "Ihr bekommt:\n\nSpieljeton des Dunkelmond-JahrmarktsGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29511] = {title = "Panzerreparatur", objective = "Repariert 5 beschädigte Dampfpanzer auf dem Gelände des Dunkelmond-Jahrmarkts.", description = "Die Dunkelmonddampfpanzer gehören zu unseren beliebtesten Attraktionen. Unsere Besucher testen ihr Können stundenlang, aber bei all dem Spaß werden die Panzer stark beansprucht.\n\nIhr scheint zu wissen, wie man mit einem Schraubenschlüssel umgeht. Würdet Ihr mir bei der Reparatur der beschädigten Panzer helfen? Ich würde Euch für Euren Zeitaufwand entschädigen.", progress = nil, completion = "Sehr gute Arbeit. Die Panzer laufen wieder. Hier sind die versprochenen Lose.", rewards = "Ihr bekommt:\n\nSpieljeton des Dunkelmond-JahrmarktsGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29512] = {title = "Kratzer, Beulen, blaue Flecke", objective = "Nehmt die Bandagen des Dunkelmond-Jahrmarkts und heilt damit 4 verletzte Schausteller.", description = "Die Arbeit auf dem Dunkelmond-Jahrmarkt ist gefährlich, <Name>. Unsere Arbeiter verletzen sich oft beim Aufbau, Abbau und Transport der Attraktionen.\n\nEinige der verletzten Arbeiter findet Ihr in der Nähe der Wagen. Andere wollen sich im Heilzelt behandeln lassen. Warum nehmt Ihr nicht diese Bandagen und seht, ob Ihr den verletzten Arbeitern helfen könnt?", progress = "Habt Ihr Euch um die verletzten Arbeiter gekümmert?", completion = "Ich danke Euch für Eure Hilfe, &lt;Name&gt;. Der Jahrmarkt kann nur weiterbestehen, wenn wir alle zusammenhalten.", rewards = "Ihr bekommt:\n\nSpieljeton des Dunkelmond-JahrmarktsGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29513] = {title = "Leckerer Fisch im Schlafrock", objective = "Fangt 5 große Meeresheringe im Ozean rund um die Dunkelmond-Insel.", description = "Wir haben gerade ein neues Gericht in unsere Speisekarte aufgenommen, den Fisch im Schlafrock. Es ist so beliebt, dass wir die Nachfrage kaum erfüllen können!\n\nIhr seht aus, als wüsstet Ihr, wie man mit einer Angel umgeht, <Volk>. Würdet Ihr mir bei der Aufstockung meiner Vorräte helfen?\n\nWir wollen doch all die Jahrmarktsbesucher, die etwas Neues ausprobieren wollen, nicht enttäuschen, oder?", progress = "Habt Ihr die Fische?", completion = "Genau die richtigen! Hier sind wie versprochen Eure Lose.", rewards = "Ihr bekommt:\n\nSpieljeton des Dunkelmond-JahrmarktsGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29514] = {title = "Heilkräuter", objective = "Sammelt 6 Dunkelblüten auf dem Lagerplatz des Dunkelmond-Jahrmarkts.", description = "Die kleinen purpurnen Blumen, die überall auf dem Platz wild wachsen, sind mehr als nur hübsch.\n\nMit ihnen kann man Wunden behandeln und Essen würzen.\n\nIhr scheint ein Talent zum Kräutersammeln zu besitzen. Würdet Ihr mir dabei helfen, meinen Vorrat an Dunkelblüten aufzustocken?", progress = "Wie geht das Kräutersammeln voran?", completion = "Danke, &lt;Name&gt;. Sobald der Dunkelmond-Jahrmarkt wieder in der Stadt ist, würde ich gern noch einmal auf Eure Hilfe zurückgreifen.", rewards = "Ihr bekommt:\n\nSpieljeton des Dunkelmond-JahrmarktsGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29515] = {title = "Ein Blick in die Zukunft", objective = "Stellt aus dem Bund exotischer Kräuterprophetische Tinte her. Verbindet die Tinte mit leichtem Pergament, um Sayges Horoskope zu schreiben.", description = "Die Beliebtheit des Dunkelmond-Jahrmarkts nimmt zu. Immer mehr Leute suchen mich auf, um einen Blick in ihre Zukunft zu werfen.\n\nHäufig bitten sie um Wissen, das besser im Nebel der Zeit verborgen bleiben sollte, aber solche Ratschläge stehen mir nicht zu.\n\nMein Vorrat an geschriebenen Horoskopen neigt sich dem Ende zu und Ihr scheint eine sichere Hand zu haben. Stellt Tinte aus diesen Kräutern her und schreibt einige Horoskope für mich. Das Pergament, das Ihr dafür braucht, könnt Ihr bei jedem Handwerkswarenhändler im Wald von Elwynn oder in Mulgore erwerben.", progress = "Habt Ihr die Horoskope geschrieben?", completion = "Die sehen genau wie meine aus. Ihr habt ein gutes Gespür für Details. Ich danke Euch für Eure Hilfe, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSpieljeton des Dunkelmond-JahrmarktsGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29516] = {title = "Jahrmarkt der Eitelkeiten", objective = "Sucht nach Glasscherben auf dem Platz des Dunkelmond-Jahrmarkts und schleift daraus 5 funkelnde \"Edelsteine\".", description = "Die Künstler und Tiere des Dunkelmond-Jahrmarkts benötigen mehr Schmuck, als ich mir je hätte erträumen lassen. Zum Glück bestehen die Edelsteine nur aus geschliffenem Glas. Aber auch die muss jemand herstellen.\n\nSeid Ihr geübt in Juwelierskunst und würdet uns helfen, einige glitzernde Glasedelsteine für unsere Künstler herzustellen?\n\nManchmal kann man die erstaunlichsten Scherben auf dem Platz finden. Wenn die von jemandem mit einem Händchen für Juwelierskunst bearbeitet werden, entstehen daraus wunderschöne Edelsteine.", progress = "Ist es Euch gelungen, Ersatzedelsteine für den Schmuck unserer Künstler zu schleifen?", completion = "Sehr gute Arbeit, &lt;Name&gt;. Ihr seid wirklich talentiert.", rewards = "Ihr bekommt:\n\nSpieljeton des Dunkelmond-JahrmarktsGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29517] = {title = "Begehrte Preise", objective = "Stellt mit Hilfe des Handwerkersets des Dunkelmond-Jahrmarkts 5 Gewinne des Dunkelmond-Jahrmarkts her. Dazu benötigt Ihr groben Faden, glänzende Schmuckstücke und blauen Farbstoff.", description = "Die Spiele werden immer beliebter, was bedeutet, dass wir mehr Preise ausgeben als je zuvor.\n\nWir brauchen dringend neue Preise. Wenn Ihr geübt in der Lederverarbeitung seid, würde ich Euch gern ein Set geben. Ihr werdet einige Teile bei einem Handwerkswarenhändler im Wald von Elwynn oder in Mulgore erwerben müssen, aber sie sind nicht teuer.\n\nWollt Ihr mir helfen?", progress = "Habt Ihr die Preise hergestellt?", completion = "Sehr gute Arbeit! Die Preise sehen genauso aus wie die anderen. Ich danke Euch für Eure Hilfe.\n\nWenn Ihr noch einmal helfen wollt, dann sucht mich auf, wenn der Dunkelmond-Jahrmarkt das nächste Mal in der Stadt ist.", rewards = "Ihr bekommt:\n\nSpieljeton des Dunkelmond-JahrmarktsGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29518] = {title = "Wiederbewaffnung, Wiederverwendung, Wiederverwertung", objective = "Beschafft 6 Stücke Panzerschrott vom Lagerplatz des Dunkelmond-Jahrmarkts.", description = "Die Jahrmarktsbesucher lieben unsere Dampfpanzer! Wenn der Dunkelmond-Jahrmarkt schließt, liegt all der Panzerschrott auf dem Platz herum.\n\nWäre doch schade, wenn das gute Metall einfach im Dreck verrotten würde.\n\nWäret Ihr so nett, mir einige der größeren Stücke zu bringen, damit ich die kaputten Panzerteile damit reparieren kann? Das ist weitaus billiger als jedes Mal neues Metall zu kaufen. Was meint Ihr?", progress = "Habt Ihr Schrott gefunden? Der Platz ist voll davon.", completion = "Das ist eine Menge Schrott. Ich danke Euch für Eure Hilfe. Damit werde ich viele Panzer reparieren können.\n\nHier, nehmt dies als kleine Belohnung.", rewards = "Ihr bekommt:\n\nSpieljeton des Dunkelmond-JahrmarktsGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29519] = {title = "Gerbt meine Häute", objective = "Schabt 4 aufgespannte Häute auf dem Lagerplatz des Dunkelmond-Jahrmarkts ab.", description = "Auf dem Dunkelmond-Jahrmarkt wird ständig Leder für Zelte, Stiefel und alles, was Ihr Euch vorstellen könnt, benötigt. Ich habe einige Kreaturen gefangen und ihre Häute aufgespannt.\n\nIhr scheint Euch mit Häuten auszukennen. Ich würde Euch belohnen, wenn Ihr mir beim Abschaben der neuen Häute helfen könntet.", progress = "Die Arbeit auf dem Dunkelmond-Jahrmarkt hört nie auf.", completion = "Ich danke Euch für Eure Hilfe, &lt;Name&gt;. Ich werde Euch in guter Erinnerung behalten.\n\nUnd wenn Ihr möchtet, könnt Ihr mir gern wieder helfen, wenn der Dunkelmond-Jahrmarkt das nächste Mal in der Stadt ist.", rewards = "Ihr bekommt:\n\nSpieljeton des Dunkelmond-JahrmarktsGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29520] = {title = "Banner, überall Banner!", objective = "Stellt mit einem groben Faden sowie rotem und blauem Farbstoff zusammen mit dem Bannersets des Dunkelmond-Jahrmarkts ein Banner des Dunkelmond-Jahrmarkts her. Steckt es in einen Haufen loser Steine auf dem Lagerplatz des Jahrmarkts.", description = "Ist es nicht wundervoll, dass überall Banner des Dunkelmond-Jahrmarkts wehen? Das genieße ich am meisten beim Aufbau, aber viele sind mittlerweile alt und zerschlissen und müssten ersetzt werden.\n\nNehmt Nadel und Faden, wenn Ihr damit umgehen könnt, und stellt ein Banner aus diesem Set her. Steckt es dann in einige lose Steine auf dem Lagerplatz des Jahrmarkts.\n\nEs fehlen noch einige Teile, doch die solltet Ihr bei jedem Handwerkswarenhändler im Wald von Elwynn oder in Mulgore erwerben können.", progress = nil, completion = "Danke für Eure Hilfe. Ihr seid recht begabt mit Nadel und Faden. Wenn der Dunkelmond-Jahrmarkt das nächste Mal in der Stadt ist, könnt Ihr uns gern wieder helfen.", rewards = "Ihr bekommt:\n\nSpieljeton des Dunkelmond-JahrmarktsGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][29521] = {title = "Die Singenden Teiche", objective = "Sprecht mit Aysa Wolkensänger bei den Singenden Teichen.", description = "Es ist von höchster Wichtigkeit, dass wir die drei verbleibenden Geister ebenfalls unversehrt zurückbringen. Ich bin zu alt, um dies selbst zu bewerkstelligen, und Aysa und Ji sind trotz ihrer Stärken zu engstirnig, was ihre Ideale betrifft.\n\nIhr besitzt alle Qualitäten <eines Helden/einer Heldin> und zusätzlich eine Ausgewogenheit, über die sie nicht verfügen. Ihr seid <derjenige, der/diejenige> die; diese Aufgabe erfüllen muss.\n\nShu, der Geist des Wassers, befindet sich irgendwo in den Singenden Teichen östlich von hier. Sucht dort Aysa auf und arbeitet mit ihr zusammen, um ihn zu finden. Wir alle verlassen uns auf Euch.", progress = nil, completion = "Es ist schön, Euch wiederzusehen, &lt;Name&gt;.\n\nDas hier ist der Teich des Stinktiers, wie Ihr sicherlich bemerkt habt.\n\nSeit der Entstehung von Shen-zin Su sind über die Jahre hinweg Tiere in einigen dieser magischen Teiche verendet. Durch ihren Tod wurden die Gewässer von ihrem Geist durchdrungen und jeder, der das Wasser berührt, wird ihre Gestalt annehmen.\n\nEs gibt einige verfluchte Teiche hier, von denen manche gefährlicher sind als andere.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29522] = {title = "Ji, Anhänger der Huojin", objective = "Sprecht mit Ji Feuerpfote in Wu-Song.", description = "Ein weiterer meiner talentiertesten Schüler wartet in Wu-Song im Nordwesten auf Euch. Ihr werdet feststellen, dass er in vielerlei Hinsicht anders denkt und handelt als Aysa, aber durch ihre Unterschiede bringen sie sich gegenseitig ins Gleichgewicht.\n\nJi Feuerpfote wird Euch beim Sammeln der Opfergaben für den Geist des Feuers anleiten. Vertraut auf seine Weisheit.", progress = nil, completion = "Seid gegrüßt! Ihr seht selbstsicher und zuversichtlich aus… Das gefällt mir!\n\nIch habe einige recht beeindruckende Gerüchte über Euch gehört. Wenn Ihr nur halb so fähig seid, wie man sagt… Ich habe das Gefühl, dass wir gute Freunde sein werden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29523] = {title = "Die Flammen schüren", objective = "Beschafft eine flatternde Brise.", description = "Das Eigenartige am Wind ist, dass es durchaus schwer sein kann, ihn in die Finger zu bekommen.\n\nMeiner Meinung nach ist die beste Methode, eine Art lebendigen Wind zu finden. Wenn er mir eine verpassen kann, dann kann ich auch ihm eine verpassen und er wird mir nicht einfach davonwehen.\n\nMacht Euch auf den Weg zum Schrein der Sommerbrise und beschwört mit diesem Windstein einen solchen lebendigen Wind. Bezwingt ihn, entnehmt ihm eine flatternde Brise und kehrt zu mir zurück, damit wir entscheiden können, wie der nächste Schritt aussehen wird.", progress = "Wenn sich eine Gelegenheit ergibt, ist es unsere Pflicht, sie zu ergreifen. Eine Entscheidung im Nachhinein zu bezweifeln ist genauso viel wert, wie gleich aufzugeben.", completion = "Ihr wisst, was es heißt, eine Gelegenheit beim Schopfe zu packen. Ich denke, dass wir beide aus demselben Holz geschnitzt sind, &lt;Name&gt;.", rewards = "InitiandenpantoffelnInitiandenfußwerkInitiandenstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29524] = {title = "Die Lektion des unterdrückten Stolzes", objective = "Bezwingt 6 Huojin- oder Tushui-Schüler.", description = "Es ist etwas ganz anderes, einem lebenden Gegner anstatt dieser Übungsziele im Hof gegenüberzustehen. Lebende Gegner schlagen zurück. Eine sehr reelle Angst vor dem Versagen, und manchmal sogar dem Tod, kann Euch überkommen.\n\nIhr müsst den Mut aufbringen, diese Ängste zu überwinden.\n\nFordert die anderen Schüler innerhalb des Tempels oder auf den Stufen davor heraus und bezwingt sie.", progress = nil, completion = "Faszinierend, mein junger Schüler.\n\nDie meisten der anderen Schüler haben schon einige Zeit hier verbracht, aber Ihr seid schon jetzt in der Lage, Euch mit ihnen zu messen.\n\nDas spricht für Euch, aber es gibt noch weitere Lektionen, die ich Euch gerne lernen sehen würde.", rewards = "InitiandenschnürgürtelInitiandengürtelInitiandenwickelgurtDer folgende Zauber wird auf euch gewirkt:\n\nUpdate Zone Auras\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29527] = {title = "Krieg im Bollwerk", objective = "Tötet Wachhabenden Gargolmar, Vazruden den Herold und Vazrudens Drachen Nazan. Bringt Gargolmars Hand und Nazans Kopf zu Steingardist Stok'ton.", description = "Wachhabender Gargolmar und Vazruden der Herold haben das Kommando über die Verteidigung des Bollwerks.\n\nWenn Ihr sie ausschaltet, werden die Soldaten in Panik geraten.\n\nTötet sie und bringt mir einen Beweis für Eure Tat, damit die Invasion beginnen kann!", progress = "Diese Mission hängt von Eurem Erfolg ab, <Name>.", completion = "Ohne ihre Anführer sollten die Truppen in Panik geraten.\n\nAber es geht hier um mehr als die Beseitigung einiger Wachen, &lt;Klasse&gt;.", rewards = "Jadeschulterstücke des KriegersHandschützer der PräzisionStiefel des sicheren SchrittsMantelung der MagiemachtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29528] = {title = "Krieg im Bollwerk", objective = "Tötet Wachhabenden Gargolmar, Vazruden den Herold und Vazrudens Drachen Nazan. Bringt Gargolmars Hand und Nazans Kopf zu Vorhutsspäher Chadwick.", description = "Die Verteidigung der Höllenfeuerzitadelle hängt in erster Linie vom Bollwerk ab, das als eine Art Frühwarnsystem dient.\n\nBeseitigt Wachhabenden Gargolmar und Vazruden den Herold. Ohne sie wird die Eroberung des Bollwerks ein Kinderspiel sein.", progress = "Wart Ihr erfolgreich? Von dieser Mission hängt sehr viel ab, <Name>.", completion = "Ich wusste, dass ich auf Euch zählen kann!\n\nIhre Streitkräfte sind nun führerlos. Die Invasion kann beginnen.", rewards = "Jadeschulterstücke des KriegersHandschützer der PräzisionStiefel des sicheren SchrittsMantelung der MagiemachtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29529] = {title = "Dämonen in der Zitadelle", objective = "Tötet Omor den Narbenlosen und bringt seinen Huf zu Vorhutsspäher Chadwick.", description = "Einer unserer Späher berichtet, er habe irgendwo im Bollwerk einen Agenten der Brennenden Legion gesehen. Wenn das stimmt, laufen wir Gefahr, dass die Ehrenfeste von zwei Seiten angegriffen wird!\n\nWenn Ihr diesen Teufel findet, dann bringt ihn um.", progress = "Habt Ihr dort drinnen Dämonen entdeckt?", completion = "Dann ist es also wahr. Die Höllenorcs und die Brennende Legion arbeiten auf irgendeine Weise zusammen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29530] = {title = "Dämonen in der Zitadelle", objective = "Tötet Omor den Narbenlosen und bringt seinen Huf zu Steingardist Stok'ton.", description = "Einer unserer Späher hat unangenehme Neuigkeiten überbracht. Wir haben einen mächtigen Agenten der Brennenden Legion im Bollwerk entdeckt!\n\nBringt diesen Dämon um, bevor er seinen Vorgesetzten von unseren Plänen berichten kann.", progress = "Konntet Ihr die üble Kreatur beseitigen?", completion = "Gut gemacht. Wir brauchen die Zeit, die Ihr uns erkauft habt, um der Verbindung zwischen Höllenorcs und brennender Legion nachzugehen. Eure Taten haben vielleicht Hunderten das Leben gerettet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29531] = {title = "Kill Stuff", objective = "Kill stuff for Questvendor.", description = "I really need you to kill some stuff for me. It's pretty important.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29535] = {title = "Lasst sie bluten!", objective = "Beschafft 10 Phiolen mit Höllenorcblut und eine Teufelsinjektionsspritze für Caza'rez.", description = "Der Schöpfer erzeugt neue Höllenorcs, indem er ihnen Dämonenblut injiziert.\n\nMeine Vorgesetzten glauben, dass sich der Prozess rückgängig machen lässt, aber um das auszuprobieren, benötigen wir Proben ihres Blutes und die Injektionsspritze des Schöpfers.", progress = "Ihr seid zurück und sogar lebendig! Gut gemacht. Besser als alle anderen bis jetzt.", completion = "Diese Phiolen könnten das Ende der Höllenorcs einläuten. Ich hoffe, dass Ihr versteht, wie wichtig das für unseren Feldzug wäre.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29536] = {title = "Herz des Zorns", objective = "Untersucht den Blutkessel vollständig und meldet Euch wieder bei Caza'rez.", description = "Wir wissen, dass die Höllenorcs ihren Fokus erhöhen, indem sie Orcs Dämonenblut injizieren.\n\nBegebt Euch tief in diese unheiligen Hallen und findet heraus, was dort geschieht. Wir können es erst riskieren, eine Armee hineinzuschicken, wenn wir genau wissen, was uns erwartet.", progress = nil, completion = "&lt;Ihr erzählt Caza'rez alles, was Ihr im Blutkessel gesehen habt.&gt;\n\nWenn sie das den braunen Orcs der Mag'har antun können, dann sind auch wir in Gefahr! Wir müssen vorsichtig sein, sonst werden alle in Thrallmar zu hirnlosen Bestien.", rewards = "Perfekt ausbalanciertes CapeAuf Euch wartet eine dieser Belohnungen:\n\nPurpurroter Anhänger der KlarsichtHeiliges Band der Heilung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][29537] = {title = "Vorsicht, Lücke!", objective = "Tötet Keli'dan den Zerstörer und kehrt zu Caza'rez zurück.", description = "Im ganzen Blutkessel gibt es nur ein Gebiet, das unsere Seher trotz aller Mühen nicht erreichen können.\n\nDiese \"Lücke\", wie sie es nennen, ist recht groß. Dort wird bestimmt Magtheridon gefangen gehalten.\n\nIhr müsst die Ursache dieser Störungen finden und vernichten.", progress = nil, completion = "Die Störungen haben nachgelassen, aber wir können das Gebiet immer noch nicht sehen. Wir werden der Sache weiter nachgehen. Ich danke Euch für Eure Hilfe.", rewards = "Brustplatte der VergeltungSchuppenbeinlinge der ZerstörungMondkinkopfputzGamaschen des TodestunnlersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29538] = {title = "Lasst sie bluten!", objective = "Beschafft 10 Phiolen mit Höllenorcblut und eine Teufelsinjektionsspritze für Gunny.", description = "Mit Dämonenblut und einer speziellen Spritze verwandelt der Schöpfer braune und grüne Orcs in rote. Wir würden uns das Blut gern ansehen und damit herumspielen, bis es Orcs aller Farben in harmlose, friedliche Ochsen verwandelt.\n\nBringt mir einige Proben ihres Blutes, damit wir anfangen können. Und vergesst die Spritze nicht!", progress = "Habt Ihr das Blut, Prinzessin? Wir haben Euch bestimmt nicht darum gebeten, weil es unwichtig ist.", completion = "Verdammt beeindruckend! Damit steigt Ihr auf Platz acht meiner Lieblingspersonen in den qualmenden Ruinen dieses bemitleidenswerten Planeten auf!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29539] = {title = "Herz des Zorns", objective = "Untersucht den Blutkessel vollständig und meldet Euch wieder bei Gunny.", description = "Hat sich gezeigt, dass die Eierköpfe in der Ehrenfeste nicht viel von diesem Ort hier sehen können. Lügende, faule Magier sind das, nichts weiter.\n\nWie dem auch sei, wir wissen nicht genau, was hier vorgeht. Also werdet Ihr das herausfinden!", progress = nil, completion = "&lt;Ihr erzählt Gunny alles, was Ihr im Blutkessel gesehen habt.&gt;\n\nIhr habt doch auch Beute für den alten Gunny, oder?\n\nNein, Ihr habt natürlich recht. Ich schulde Euch eine Belohnung für Eure harte Arbeit, auch wenn Ihr ohne mich überhaupt nicht hineingegangen wäret.", rewards = "Perfekt ausbalanciertes CapeAuf Euch wartet eine dieser Belohnungen:\n\nPurpurroter Anhänger der KlarsichtHeiliges Band der Heilung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][29540] = {title = "Der Zerstörer", objective = "Tötet Keli'dan den Zerstörer und kehrt zu Gunny zurück.", description = "Die verstecken hier irgendwo so einen großen, alten Dämon, hab ich gehört. Und da gibt's auch einen Orc, der darauf achten soll, dass er bleibt, wo er hingehört.\n\nEin Orc ist ein Orc, und Orcs werden umgebracht, richtig? Ist egal, was er tut oder getan hat, einer weniger schadet nie.", progress = nil, completion = "Wirklich? Ihr wollt eine Belohnung, weil Ihr einen Orc umgebracht habt? So wie in Ruhm und Reichtum und edle Reittiere?\n\nZu meiner Zeit war es Belohnung genug, einen Orc töten zu DÜRFEN!", rewards = "Brustplatte der VergeltungSchuppenbeinlinge der ZerstörungMondkinkopfputzGamaschen des TodestunnlersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29541] = {title = "Take Care of It", objective = "Resolve the dispute any way you see fit.", description = "This looks bad... you'd better do something.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][29542] = {title = "Die Eroberung der Zitadelle", objective = "Sprecht mit Steingardist Stok'ton im Höllenfeuerbollwerk.", description = "Die Legion steht auf der einen, die Höllenorcs auf der anderen Seite. Sie werden Thrallmar überrennen, wenn wir nichts unternehmen.\n\nMacht Euch auf den Weg nach Westen zum Höllenfeuerbollwerk und sprecht mit Steingardist Stok'ton. Die Geheimmission, die er leitet, wird der Horde den Weg in die Zitadelle ebnen.", progress = nil, completion = "Schädelbrecher ist nicht gerade freundlich, aber er weiß, was er tut. Und für Euch gibt es auch genug Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29543] = {title = "Die Eroberung der Zitadelle", objective = "Sprecht mit Vorhutsspäher Chadwick im Höllenfeuerbollwerk.", description = "Die Legion steht auf der einen, die Höllenorcs auf der anderen Seite. Sie werden die Ehrenfeste in Kürze überrennen, wenn wir nichts unternehmen.\n\nMacht Euch auf nach Westen zum Höllenfeuerbollwerk und sprecht dort mit Vorhutsspäher Chadwick. Die Mission, die er leitet, wird der Allianz den Weg in die Zitadelle ebnen.", progress = nil, completion = "Altumus ist wirklich ein Juwel. Aber wir werden hier nur lebend herauskommen, wenn wir im Bollwerk siegreich sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29547] = {title = "Der Befehl des Königs", objective = "Sucht Großadmiralin Jes-Tereth im Kriegsraum von Burg Sturmwind in Sturmwind auf.", description = "Seid gegrüßt, <Klasse>.\n\nIch wurde beauftragt, eine Gruppe für eine Mission von höchster Wichtigkeit zusammenzustellen.\n\nBitte eilt sofort in die Burg Sturmwind für eine Besprechung mit König Varian Wrynn. Ich werde im Kriegsraum des Königs auf Euch warten.", progress = nil, completion = "Unsere Rolle ist äußerst wichtig. Admiral Taylor und sein Flaggschiff sind verschwunden. Was noch wichtiger ist: Der junge Prinz war bei ihm und unser primäres Ziel besteht darin, ihn sicher zurück nach Hause zu bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29548] = {title = "Die Mission", objective = "Meldet Euch bei Admiralin Rogers auf der Himmelsfeuer.", description = "Nun denn, Ihr habt den König gehört. Admiral Taylors letzte Übertragung kam von irgendwo im südlichen Meer.\n\nWir werden umgehend mit der Luftaufklärung beginnen. Der Prinz - der Weiße Bauer - ist dabei die oberste Priorität.\n\nDie Himmelsfeuer ist vollgetankt, beladen und zum Aufbruch bereit. Sie wartet mit ihrer Mannschaft am Himmel nördlich des Hafens.\n\nTrefft Eure letzten Vorbereitungen und meldet Euch dann bei Himmelsadmiralin Rogers auf dem Deck. Wir werden ohne weitere Verzögerungen aufbrechen.", progress = "Ah, ein Veteran aus den Kataklysmusfeldzügen! Sehr gut - ich kann fähige Hände hier wirklich gut gebrauchen.", completion = "Das da unten ist eine komplette Basis der Horde! Wo waren unsere Aufklärer!?\n\nNun denn, &lt;Klasse&gt;, es wird Zeit herauszufinden, wozu dieses aufgerüstete Luftschiff in der Lage ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29552] = {title = "In kritischem Zustand", objective = "Belebt 6 verwundete Piloten im Hain von Pel'zin wieder. Ihr könnt auch Heilzauber oder Bandagen verwenden, um sie wiederzubeleben.", description = "Die erste Schlacht haben wir zwar gewonnen, es gibt aber noch eine äußerst wichtige Aufgabe.\n\nIn der ersten Luftschlacht wurden Dutzende Himmelsfeuerpiloten abgeschossen.\n\nOhne medizinische Hilfe wird sich ihr Zustand im Lauf der Zeit verschlechtern, bis sie schließlich sterben. Wir sind ihre einzige Überlebenshoffnung.\n\nBegebt Euch in den Obstgarten und belebt alle Piloten wieder, die Ihr findet.\n\nWir werden niemanden zurücklassen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Dank Eurer Anstrengungen werden diese Soldaten einen Tag länger leben und kämpfen.", rewards = "PeonhackeraxtMishkas BandagenschneiderRotor eines abgestürzten RotorsGroßschwert von Kofinna KottrHimmelwächterschildIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29553] = {title = "Der vermisste Admiral", objective = "Findet Admiral Taylor.", description = "Also gut. Die Hinweise, die Ihr gefunden habt, deuten darauf hin, dass es Anduins Schiff mit Admiral Taylor als Kapitän war. \n\nUnd laut Admiral Taylors letztem Eintrag wollte er die Ho-zen abwehren und das Schiff nach dem Schiffbruch schützen.\n\nDie Einheimischen behaupten, die Ho-zen würden manchmal Gefangene nehmen, und ich habe Taylors Leichnam zwischen den Wrackteilen nicht gefunden. Taylor ist also wahrscheinlich im Lager der Ho-zen im Nordosten.\n\nBrecht auf, wir haben keine Zeit zu verlieren!", progress = nil, completion = "&lt;Ihr habt ihn gefunden, aber der Admiral ist bewusstlos. Er scheint dem Tode näher als dem Leben.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29555] = {title = "Der Weiße Bauer", objective = "Durchsucht das Wrack der Herold im Jadewald nach Hinweisen auf seine Ladung und bergt das verschlüsselte Logbuch des Kapitäns.", description = "Also, Soldat. Ich habe eine entscheidende Mission für Euch.\n\nBegebt Euch zur Küste südlich von hier - in der Bucht dort werdet Ihr das Wrack eines Schiffs der Allianz finden. Ich möchte, dass Ihr es durchsucht und herausfindet, ob Anduin Passagier darauf war.\n\nBergt dann das Logbuch des Kapitäns und sucht darin nach Hinweisen darauf, wo wir ihn finden können.\n\nDa es sich um das Logbuch eines Militärschiffes handelt, wird es in Code verfasst sein. Bringt es anschließend zu Nick Codeknack. Er bewacht das Wrack am anderen Ende der Bucht.", progress = "Nun?", completion = "Schön... zeigt her... der Code vom Zeitpunkt des Verschwindens des Schiffs...\n\n&lt;Nick rechnet offenbar in seinem Kopf.&gt;\n\nAha!", rewards = "Ihr bekommt:\n\nTeilweise aufgeweichte Seiten"}
MultiLanguageQuestData['de'][29556] = {title = "Ho-zen sind nicht Freund, sondern Feind", objective = "Tötet 14 Ho-zen am Wrack der Herold.", description = "Wir haben ein Wrack der Allianz im Süden geortet. Den Einheimischen dort zufolge wird es jedoch derzeit von einer Gruppe dieser \"Ho-zen\" genannten Geschöpfe geplündert.\n\nDass sie unsere Schiffswracks ausnehmen, beweist bereits, dass sie uns nicht freundlich gesinnt sind. Wir können nicht zulassen, dass sie in unseren Schiffen auf Beutezug gehen, unseren Nachschub stehlen und - schlimmer noch - womöglich Überlebende gefangen nehmen oder gar töten.\n\nAuf mit Euch, erledigt sie! Wenn Ihr damit fertig seid, meldet Euch bei Nick Codeknack, unserem SI:7-Agent in der Gegend.", progress = nil, completion = "Gute Arbeit. Solche Dreckskerle - uns zu treten, wenn wir am Boden liegen...\n\nDas wird sie lehren, nicht noch einmal ein Schiff der Allianz zu plündern!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29558] = {title = "Der Kriegspfad", objective = "Tötet 12 Kronenhüpfer oder Schlammseher der Schlingschwänze.", description = "Ich merke, dass Ihr Euren Freund retten wollt. Ich kann Euch helfen, wenn Ihr mir ebenfalls helft.\n\nZunächst einmal ist es wohl offensichtlich, dass eine Flucht viel leichter zu bewerkstelligen sein wird, wenn hier weniger Schlingschwänze umherstreifen.\n\nTötet die Wachen der Ho-zen um uns herum und wir sind der Freiheit schon einen Schritt näher.", progress = "Ihr kämpft gut, Fremder.", completion = "Ahahaha! Ihr seid tapfer.\n\nEine bewundernswerte Eigenschaft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29559] = {title = "Unsere Brüder befreien", objective = "Befreit 6 Jinyu- oder Allianzgefangene.", description = "Ihr mögt ein Außenstehender sein, doch wir haben in den Ho-zen einen gemeinsamen Feind.\n\nViele Mitglieder meines Stammes sind in Käfigen in der Nähe eingesperrt. Ich habe außerdem Eure... Allianzsoldaten gesehen.\n\nIch kann nicht fortgehen, ohne meine Brüder befreit zu haben - so, wie Ihr Eure Kameraden nicht zurücklassen könnt.\n\nDie Schlingschwänze sind im Besitz der Schlüssel zu diesen Käfigen. Findet die Schlüssel und befreit unsere Freunde.", progress = nil, completion = "Ihr habt meine Brüder befreit? Gut.\n\nWir stehen in Eurer Schuld.", rewards = "Ledergürtel des KäfigberstersKettenverbund des KäfigberstersSeidene Kordel des KäfigberstersSatinkordel des KäfigberstersBalggürtel des KäfigberstersRingpanzertaillenschutz des KäfigberstersBrünierter Schnallengürtel des KäfigberstersGepanzerter Gurt des KäfigberstersSchwerer Gurt des KäfigberstersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29560] = {title = "Uralte Macht", objective = "Sammelt 8 uralte Ho-zen-Schädel.", description = "Die Schädel der Ho-zen sind begehrte Objekte in meinem Dorf.\n\nWir verwenden sie, um Riten zu zelebrieren. Je älter der Schädel, desto mächtiger ist seine Magie.\n\nZu unserem Glück sind die Ho-zen nachlässig, die schmutzigen Biester. Sie lassen die Schädel ihrer Verstorbenen überall zwischen ihren Hütten und Lagerfeuern herumliegen.\n\nSammelt diese Schädel für mich und ich werde Euch fürstlich belohnen.", progress = "Diese Schädel sind für meinen Stamm sehr wertvoll. Wie viele habt Ihr eingesammelt?", completion = "Es ist gut zu sehen, dass Ihr so einfallsreich seid, &lt;Name&gt;. Diese Eigenschaft wird von meinem Volk bewundert.\n\nDiese wunderbaren Exemplare, die Ihr mir gebracht habt, werden mächtige Magie hervorbringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29562] = {title = "Ausbruch aus dem Gefängnis", objective = "Tötet 10 Entbeiner der Schlingschwänze.", description = "Ohne Heilung wird Euer Freund Taylor sterben. Mein Dorf befindet sich im Osten von hier, mitten in dem großen See.\n\nIch werde Taylor selbst dorthin tragen, doch die Kämpfe in dieser Richtung sind höchst gefährlich.\n\nIch brauche Eure Hilfe, um mir einen Weg durch die Ho-zen zu bahnen, damit ich sicher zu meinem Dorf laufen kann.\n\nSchafft Ihr das?", progress = nil, completion = "Danke, &lt;Name&gt;. Dank Euch haben wir es sicher hierher geschafft.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKarasshi den Draufgänger beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29563] = {title = "Verschollen im Kampf", objective = "Findet heraus, was Naturalist Biss und Jäter Gründaum zugestoßen ist. Kehrt dann zu Behüterin Jhang zurück.", description = "Ihr müsst mir helfen! Wir wurden ausgesandt, um die verschiedenen Bereiche des Kessels zu erkunden, aber das war vor einiger Zeit und meine Freunde sind noch nicht zurückgekehrt.\n\nBitte findet heraus, ob ihnen etwas zugestoßen ist. Naturalist Biss und Jäter Gründaum sind in diese Richtung gegangen.", progress = nil, completion = "Der Verlust des Lebens... so schmerzhaft.\n\n&lt;Behüterin Jhang seufzt.&gt;\n\nDanke, &lt;Name&gt;. Wenn wir alle wieder vereint sind, werden uns die Naga nichts anhaben können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29564] = {title = "Der betrogene Bruder", objective = "Tötet Mennu den Verräter und kehrt zu Nahuud zurück.", description = "Anfangs gelang es meinem Dorf, den Angriffen der Naga auszuweichen. Wir hätten es bis nach Nagrand geschafft, wenn mein Bruder nicht gewesen wäre. Mit unseren Seelen erkaufte er sich seine Freiheit.\n\nNun arbeitet er hier als Sklavenaufseher und peitscht seine eigenen Brüder aus, bis ihre Rücken bluten. Dafür muss Mennu bezahlen, <Volk>.", progress = nil, completion = "Mennus Tod kann die Wunden meiner Familie und Freunde nicht heilen, aber wenigstens können sie den Rest ihres Lebens in Freiheit verbringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29565] = {title = "Des Pudels Kern", objective = "Bringt die Klaue des Eindringlings und das Auge des Sklaventreibers zu Behüterin Jhang.", description = "Nahuud hat mir erklärt, zwei mächtige Wesen, Rokmar der Zerquetscher und Quagmirran, seien als erste von den Naga nach deren Ankunft versklavt worden. Sie haben bei der Unterwerfung vieler Völker in den Zangarmarschen geholfen.\n\nIch tue das sehr ungern, aber ich muss Euch bitten, sie zu töten.", progress = "Habt Ihr sie getötet?", completion = "Ich bin froh, dass ihr Geist nun frei ist. Ich wünschte, das gleiche könnte man von den anderen ihrer Art sagen.\n\nEs gibt noch viel zu tun, vor allem in den anderen Teilen des Echsenkessels.", rewards = "Dunkler Umhang der MarschenGoldrankenwickeltücherAuf Euch wartet eine dieser Belohnungen:\n\nCenarischer Ring des Zauberwirkens\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][29566] = {title = "Die verlorene Expedition", objective = "Sprecht mit Behüterin Jhang in den Sklavenunterkünften.", description = "Die Sümpfe sind wunderschön, findet Ihr nicht? Abgesehen natürlich von den Naga, die das Wasser abpumpen.\n\nIch habe eine kleine Expedition zum Echsenkessel geschickt. Sie sollte die Naga beobachten, aber bis jetzt ist niemand zurückgekehrt. Ich mache mir Sorgen um sie.\n\nWürdet Ihr Euch zu den Sklavenunterkünften unterhalb des Schlangensees begeben und nach Behüterin Jhang suchen?", progress = nil, completion = "Was macht Ihr denn hier unten? Ihr könnt doch sehen, dass es hier nicht gerade sicher ist!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29567] = {title = "Tötet die Mutter", objective = "Bringt das Gehirn der Schattenmutter zu T'shu.", description = "Die Fungusgiganten greifen zwar heutzutage mein Volk an, aber die Marschenläufer haben bereits mehr Unschuldige auf dem Gewissen als alle anderen Kreaturen, die ich kenne. Sie sind seit Urzeiten unser Feind.\n\nIhre Brutmutter, die man auch Schattenmutter nennt, lebt in den Tiefen dieses Sumpfes. Wenn es Euch gelingen sollte, sie zu vernichten und mir ihr Gehirn als Beweis zu bringen, würde ich noch meinen Enkeln von Eurer ruhmreichen Tat erzählen.", progress = "Ihr seid zurück. Heißt das die Schattenmutter ist nicht mehr?", completion = "Die Schattenmutter ist tot! Normalerweise schwelge ich ja nicht in solchen Gemetzeln, aber der Schmerz, den die große Mutter und ihre Brut über Jahrhunderte meinem Volk zugefügt haben, ist unaussprechlich.\n\nIch bin Euch auf ewig dankbar, mutiger &lt;Volk&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMit Essenz erfüllter PilzMit Macht erfüllter Pilz\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][29568] = {title = "Ein notwendiges Übel", objective = "Tötet Hungarfenn und kehrt zu Naturalist Biss zurück.", description = "Hungarfenn und Quagmirran herrschten einst gemeinsam über die Fungusgiganten. Seit Quagmirrans Tod lastet diese Verantwortung allein auf Hungarfenns Ranken.\n\nWir müssen den Riesen töten, bevor er versklavt und als Waffe gegen uns eingesetzt werden kann.", progress = nil, completion = "Ihr habt den Zangarmarschen an diesem Tag einen großen Gefallen erwiesen, &lt;Name&gt;. Die Fungusgiganten sind zwar von Natur aus angriffslustig, aber sie sind ein wichtiger Teil des Ökosystems.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29570] = {title = "Die Rettung der Expedition", objective = "Findet heraus, was mit Erdbinder Rayge und Windrufer Klaue geschehen ist. Kehrt dann zu Behüterin Jhang zurück.", description = "Die restlichen Mitglieder meiner Expedition sind irgendwo hier drinnen. Wir brauchen das Wissen, das sie erlangt haben, und die Fähigkeiten, die sie besitzen, sonst werden wir die Naga niemals schlagen.\n\nSucht nach Erdbinder Rayge und Windrufer Klaue und stellt sicher, dass es ihnen gut geht.", progress = "Konntet Ihr die beiden finden? Geht es ihnen gut?", completion = "Bald werden wir wieder vereint sein, und das habe ich Euch zu verdanken!\n\nWir werden die Naga schneller besiegen, als Ihr denkt. Sie haben keine Chance!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29571] = {title = "Verteidigung der Wildnis", objective = "Sprecht mit Behüterin Jhang im Tiefensumpf.", description = "Der Irdene Ring arbeitet oft eng mit dem Zirkel des Cenarius zusammen. So ist es auch dieses Mal.\n\nReist nach Norden zum Tiefensumpf und sprecht mit Behüterin Jhang. Sie leitet eine Expedition in den Echsenkessel, um die Naga aufzuhalten und die Zangarmarschen zu retten.", progress = nil, completion = "Der Tiefensumpf steht kurz davor, zu einem Teil des Systems zu werden, das die Naga im Echsenkessel etabliert haben. Ihr müsst uns helfen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29573] = {title = "Sicherheit geht vor", objective = "Tötet 10 astrale Grufträuber, 5 astrale Zauberer, 5 Nexuswandler und 5 astrale Zauberbinder. Kehrt danach zu Konstrukteur Morphalius zurück.", description = "Es ist hier jetzt fast so sicher, dass meine Leute kommen und sich holen können, was rechtmäßig ihnen gehört. Die einzig große, noch verbleibende Gefahr stellt Shaffars Leibgarde dar. Von der wimmelt es hier.\n\nKümmert Euch um diese Streitkräfte, während ich wieder zu Kräften komme.", progress = nil, completion = "Wunderbar! Haramad wird sich über die guten Neuigkeiten freuen! Dieser Ort wird ihm wie ein reifer Apfel in die Hand fallen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29574] = {title = "Rätselhafte Wesen", objective = "Bringt Pandemonius' Essenz und Tavaroks Herz zu Mamdy dem Ologen.", description = "Nahe des Eingangs dieser Hallen gibt es eine Kreatur, die Pandemonius genannt wird. Sie ist in der Lage, die Energien der Leere so zu verändern, dass sie sich daraus versorgen und stärken kann.\n\nWeiter hinten liegt Tavarok, ein Wesen, das die gleiche Energie in eine kristalline Struktur umwandelt, die stärker ist als alles, was ich je gesehen habe!\n\nIch brauche dringend Proben für weitere Untersuchungen.", progress = "Wenn Ihr nicht habt, wonach ich suche, verschwendet Ihr nur meine Zeit.", completion = "Diese Proben sind äußerst interessant. Sie werden mir sehr helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29575] = {title = "Die Konkurrenz untergraben", objective = "Bringt Shaffars Bandagen zu Konstrukteur Morphalius.", description = "Dank der Barriere, die Nexusprinz Shaffar errichtet und der Truppen, die er aufgestellt hat, kann er diese Gruft in aller Seelenruhe ausplündern.\n\nNexusprinz Haramad ist darüber nicht gerade begeistert. Deshalb hat er einen sehr ansehnlichen Preis auf Shaffars Kopf ausgesetzt.", progress = "Hattet Ihr Euch für den Preis auf Shaffars Kopf interessiert?", completion = "Ich hätte nicht gedacht, dass ein &lt;Volk&gt; einen Nexusprinzen besiegen kann. Ihr habt mich überrascht und Euch diese schöne Belohnung mehr als verdient.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29576] = {title = "Ein Hauch von Sorge", objective = "Sprecht mit Shao dem Widerspenstigen im Obstgarten Nektarhauch.", description = "Mein Augenlicht ist schon lange verblasst, doch wenn der Wind richtig steht, kann ich immer noch die Blüten des Obstgartens Nektarhauch riechen, als ob ich sie in meinen Händen halte.\n\nHeute ist ihr Duft allerdings mit Rauch vermengt. Wenn Ihr Euch dazu in der Lage seht, schaut doch bitte im Obstgarten nach dem Rechten. Vielleicht spielt mir meine alte Nase einfach einen Streich.\n\nIhr findet den Obstgarten im Südwesten, jenseits der Statue der Jadeschlange.", progress = nil, completion = "Wenn Ihr hergekommen seid, um Euch mit meinen Fäusten zu unterhalten, stellt Euch hinten an. Ansonsten könnte ich Eure Hilfe gebrauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29577] = {title = "Ashyos Vision", objective = "Sprecht mit Ashyo bei den Teichen der Reinheit und beobachtet sein Ritual.", description = "Seht Euch das mal an!\n\n<Ashyo zeigt zum mächtigen Wasserfall im Norden.>\n\nDas muss wohl die Wasserzufuhr für das gesamte Tal sein!\n\nDenkt mal darüber nach, <Name>: Die Pandaren pflanzen mit diesem Wasser Gemüse an, das so groß ist wie ein Haus. Wie ist das möglich? Was ist das Geheimnis?\n\nDie Alten meines Volkes kennen eine Methode, um mit dem Wasser zu sprechen und die Zukunft vorherzusagen. Vielleicht gewährt die gleiche Technik auch Einblicke in den Ursprung dieses Gewässers...\n\nEs wäre zumindest einen Versuch wert!", progress = nil, completion = "Ich kann kaum glauben, dass er das mit einem Stock sehen konnte... Vielleicht steckt doch mehr hinter den \"verrückten Jinyuritualen\" als wir dachten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29578] = {title = "Widerstand", objective = "Tötet 8 Gormaliplünderer und 8 Gormaliverbrenner im Obstgarten Nektarhauch.", description = "Die verfluchten Mogu sind wie aus dem Nichts über uns hergefallen! Wen sie nicht sofort töten, den zerren sie fort in die Wälder.\n\nDas hier ist der einzige sichere Unterschlupf, und ich kann nichts anderes tun, als die Tür zuzuhalten.\n\nWas sagt Ihr? Seid Ihr willens, für die Schwachen einzustehen und für sie zu kämpfen?", progress = nil, completion = "Gute Arbeit. Doch es gibt noch mehr zu tun, wenn wir dieses Dorf retten wollen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29579] = {title = "Versammelt die Überlebenden", objective = "Sprecht mit 5 Bauern von Nektarhauch in der Umgebung vom Obstgarten Nektarhauch und schickt sie zum sicheren Unterschlupf.", description = "Die Einwohner dieses Dorfes sind einfache Bauern - keine Kämpfer wie Ihr und ich. Dennoch verteidigen sie hartnäckig ihr Zuhause so gut sie eben können.\n\nDurchsucht das Dorf nach allen, die noch aufrecht stehen können und sagt ihnen, sie sollen sich hier bei Hanae versammeln.", progress = nil, completion = "Sie sind drinnen. Aufgewühlt, aber dank Euch lebendig.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nOrchard Survivor Turn-in\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29580] = {title = "Geräte aus dem Obstgarten", objective = "Bergt 6 Obstgartenwerkzeuge aus dem Obstgarten Nektarhauch.", description = "Sie mögen keine Waffenmeister sein, doch viele dieser Bauern können eine einfache Hacke oder einen Rechen schwingen, um ihrem Willen Ausdruck zu verleihen.\n\nDiese Meisterschaft in Verbindung mit der richtigen Motivation kann eine Armee auf die Beine stellen, die in der Lage ist, den Mogu die Stirn zu bieten.\n\nWenn Ihr einige Werkzeuge aus dem Obstgarten herholt, werde ich sie an die Kampfwilligen verteilen.", progress = "Waren noch Werkzeuge da?", completion = "Unter uns gibt es niemanden wie Euch, &lt;Klasse&gt;, doch wir werden kämpfen und die, die wir lieben, beschützen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29581] = {title = "Der goldene Traum", objective = "Bringt einen Traumlaubzweig zu Yan in Neu-Cifera.", description = "Ashyo muss das erlebt haben, was wir den goldenen Traum nennen.\n\nViele von uns, die hier arbeiten, haben ihn auch gesehen - häufig nach einem langen Arbeitstag in den Teichen. Man sagt, diese Vision - und das Hochgefühl, das sie bringt - sei eine Belohnung des Geistes für die Nutzung des Körpers.\n\nEs gibt jedoch auch eine einfachere Methode, die wir allerdings kaum noch nutzen: Man kann einen Tee aus Lotuswurzeln und Traumlaub, das in der Nähe des Schreins im oberen Bereich zu finden ist, herstellen.\n\nBringt das Traumlaub in das Dorf zu Yan - er wird Euch den Tee zubereiten.", progress = "Ja, braucht Ihr etwas?", completion = "Ah... Traumlaub! Ihr wollt also den goldenen Traum sehen, nicht wahr?\n\nWenn ich jetzt so darüber nachdenke, fällt mir auf, dass ich den Traum seit Jahren nicht mehr geträumt habe - zuletzt in meinen jungen Jahren beim stundenlangen Spielen in den Teichen. Lange bevor ich mich den kulinarischen Künsten widmete.\n\nWie es aussieht, habt Ihr genügend Traumlaub für zwei Tassen Tee mitgebracht... Hmm, warum nicht?\n\nAuf bessere Zeiten!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nThe Golden Dream: Initialize\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29582] = {title = "Greks verrückte Nacht", objective = "Sprecht mit Konstrukteur Morphalius in der Managruft in Auchindoun.", description = "Grek hatte gestern ziemlich üble Nacht.\n\nGlänzender Mumienmann kam in Greks Haus und sagte, Grek solle zu Managruft in Auchindoun gehen. Aber Grek versuchte noch Steckbrief zu lesen!\n\n<Greks Augen beginnen zu leuchten.>\n\nGrek weiß! Ihr gehen zu glänzendem Mumienmann und sagt ihm, Grek schickt Euch. Perfekter Plan!", progress = nil, completion = "Der Hohlschädel hat stattdessen Euch geschickt?\n\n&lt;Konstrukteur Morphalius mustert Euch.&gt;\n\nDann werdet Ihr wohl genügen müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29583] = {title = "Eckert der Verrückte", objective = "Sprecht mit Konstrukteur Morphalius in der Managruft in Auchindoun.", description = "Ich bin ein erfahrener Ingenieur, ein brillanter Erfinder, der Mittelpunkt jeder Party und der beste Tänzer, den es jemals in Azeroth gegeben hat.\n\nAber nennt mich jemand so? Nein.\n\nDa hat man nur eine Begegnung mit einem Astralen und auf einmal nennt einen die ganze Welt \"den Verrückten\".\n\nGenau hier habe ich gestern einen gesehen, das schwöre ich! Er sagte, ich müsste ihm nur zur Managruft in Auchindoun folgen, dann würde ich einen gewaltigen Schatz bekommen und uraltes Wissen erlangen!", progress = nil, completion = "Ich hatte wirklich gehofft, dass der Gnom, den ich aufgesucht habe, meinem Ruf folgen würde.\n\n&lt;Konstrukteur Morphalius mustert Euch.&gt;\n\nNa ja, Ihr müsst mir genügen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29585] = {title = "Feuerspeier", objective = "Nutzt den Nektarhauchmost, um 12 Feuer im Obstgarten Nektarhauch zu löschen.", description = "Wir kümmern uns seit Generationen um diese Obstgärten und stellen aus dem Nektar Most her. In all der Zeit haben wir gelernt, wie wir ein Feuer im Handumdrehen löschen können.\n\n<Hanae drückt Euch einen Krug Apfelmost in die Hand.>\n\nDer Apfelmost wird klebrig und dickflüssig, wenn man ihn mit zerstoßenem Ingwerblatt und Spucke vermischt. Damit lassen sich Feuer gut löschen.\n\nBitte, könnt Ihr versuchen, die Flammen unter Kontrolle zu bringen, wenn Ihr da draußen seid? Ich habe schon Ingwerblatt daruntergemischt, Ihr müsst nur noch hineinspucken.", progress = nil, completion = "Eben war jemand hier und sagte, dass die Flammen langsam erlöschen.\n\nWir sind Euch zu großem Dank verpflichtet. Ich kann Euch unmöglich angemessen belohnen, aber nehmt das doch bitte.", rewards = "BambusfaserhandschuheBambusblatthandschuheJadehexenhandschützerBambusstreifenhandschuheBambusstreifenhandschützerBambusplattenhandschuheFuchswäldchenhandschützerBambusblattstulpenBambusplattenstulpenDer folgende Zauber wird auf euch gewirkt:\n\nUpdate Zone Auras\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29586] = {title = "Der Gesplitterte Pfad", objective = "Folgt dem Weg der gefallenen Bäume von der Nordwestecke des Obstgartens Nektarhauch aus und findet das Lager der Moguräuber.", description = "Zuerst... vor den Kriegsschreien... hörten wir die Bäume.\n\nSie stöhnten, knarrten und stürzten schließlich zu Boden, als die Mogu sich den Weg durch den Wald bahnten. Sie machten sich den Rückweg leichter...\n\nSie zerren unsere Freunde auf diesem Weg zurück zu den Ruinen westlich des Dorfes! Diese Ruinen waren seit Jahren verlassen – unsere Kinder spielen dort.\n\nWarum sollten die Mogu jetzt dorthin zurückkehren?", progress = nil, completion = "Das sieht nicht nach einer schnellen Entführung aus. Die haben etwas Größeres im Sinn.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29587] = {title = "Ungebunden", objective = "Befreit 10 gefesselte Bauern von Nektarhauch im Lager Gormal.", description = "Könnt Ihr sie sehen, $p? Bauern aus dem Obstgarten, gefesselt und unter Beobachtung. Sie werden in Ketten davongeschleppt.\n\nDen Mogu ist Stärke wichtiger als alles andere. Jeder, den sie für arbeitsfähig befinden, wird fortgeschickt, um unter ihren grausamen Peitschen zu schuften.\n\nWas die anderen angeht, nun...\n\nWir sollten keine Zeit mehr verlieren.", progress = nil, completion = "Die Pandaren waren in alten Zeiten der Moguregentschaft unterworfen - das werden wir nie wieder zulassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29590] = {title = "Der Totenwächter", objective = "Tötet Shirrak den Totenwächter und kehrt zu dem Draeneigeist zurück.", description = "Ein schreckliches, überirdisches Wesen sucht die Welt der Geister und die der Lebenden heim. Wir nennen es Shirrak.\n\nEs kann nur in Eurem Reich verletzt werden. Bitte helft uns, diesen Alptraum zu beenden.", progress = nil, completion = "Vielleicht werden wir jetzt endlich Frieden finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29591] = {title = "Wütende Geister", objective = "Tötet 5 erboste Skelette, 5 tobende Skelette und 3 Totenbeschwörer der Auchenai. Kehrt dann zur gequälten Seelenpriesterin in der Auchenaikrypta zurück.", description = "Die Auchenai haben all unseren Werten den Rücken gekehrt. Sie erwecken die Toten und halten sie als ihre unheiligen Diener!\n\nDas muss ein Ende haben. Bringt diesen Geistern den Frieden und tötet alle, die sie zu Untoten gemacht haben.", progress = nil, completion = "Die Toten gehören ins Reich der Geister, so wie Ihr in dieses Reich gehört.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29593] = {title = "Trefft sie, wo es schmerzt", objective = "Stehlt 3 Stapel Vorräte der Höllenfeuerhalbinsel und kehrt zu Steingardist Stok'ton im Höllenfeuerbollwerk zurück.", description = "Die Höllenorcs lagern eine Menge Vorräte hier.\n\nEs würde ihren Feldzug empfindlich treffen und unserem deutlich helfen, wenn sie gestohlen würden. Traut Ihr Euch das zu, <Klasse>?", progress = "Wie viele Vorräte konntet Ihr mitnehmen?", completion = "Sehr gut! Langfristig wird dieser Angriff weit schwerwiegendere Konsequenzen haben als der Tod von ein paar Orcs.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29594] = {title = "Trefft sie, wo es schmerzt", objective = "Stehlt 3 Stapel Vorräte der Höllenfeuerhalbinsel und kehrt zu Vorhutsspäher Chadwick im Höllenfeuerbollwerk zurück.", description = "Die Höllenorcs lagern eine Menge Vorräte hier.\n\nEs würde ihren Feldzug empfindlich treffen und unserem deutlich helfen, wenn sie gestohlen würden. Traut Ihr Euch das zu, <Klasse>?", progress = "Wie viele Vorräte konntet Ihr mitnehmen?", completion = "Sehr gut! Langfristig wird dieser Angriff weit schwerwiegendere Konsequenzen haben als der Tod von ein paar Orcs.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29595] = {title = "Alles wird gut", objective = "Großvater Aldrimus außerhalb der Auchenaikrypta von Auchindoun möchte, dass Ihr in die Auchenaikrypta geht und Exarch Maladaar vernichtet.", description = "Da habt Ihr ja ein ziemliches Abenteuer hinter Euch, <Name>. Dabei habt Ihr die Auchenaikrypta noch nicht einmal betreten.\n\nIch bin einer der glücklichen Geister. Ich war nie an Levixus gebunden, noch war ich Teil von Exarch Maladaars verwerflichen Experimenten in der Nekromantie. Levixus habt Ihr bereits vernichtet, aber Maladaar quält weiter die Geister in der Krypta.\n\nIch habe eine simple Bitte an Euch. Betretet die Auchenaikrypta und sprecht mit dem Draeneigeist dort. Ihr müsst Exarch Maladaar vernichten.", progress = nil, completion = "Willkommen in der Auchenaikrypta, &lt;Name&gt;. Unsere beiden Welten treffen sich hier.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29596] = {title = "Das Ende des Exarchen", objective = "Tötet Exarch Maladaar und kehrt zu dem Draeneigeist in der Auchenaikrypta zurück.", description = "Exarch Maladaar übt sein unheiliges Werk im tiefsten Teil der Krypta aus. Er stellt eine Bedrohung für unser beider Welten dar und muss aufgehalten werden.\n\nTötet ihn zum Wohle aller, dem der Toten und dem der Lebenden.", progress = nil, completion = "Ihr habt unserem Reich einen großen Dienst erwiesen. Wir werden Euch nicht vergessen.", rewards = "Schutz des ExarchenFährtenleserhalsberge der AuchenaiMönchstunika der AuchenaiAnachoretenrobe der AuchenaiIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29598] = {title = "Tarethas Ablenkungsmanöver", objective = "Reist nach Burg Durnholde und platziert mithilfe des Bündels mit Brandbomben, das Ihr von Erozion erhalten habt, 5 Brandsätze auf den Fässern in jeder Internierungsbaracke.\n\nSprecht mit Thrall im Kellergefängnis von Burg Durnholde, wenn Ihr die Internierungsbaracken angezündet habt.", description = "Taretha war es, die ursprünglich für das Ablenkungsmanöver in Durnholde sorgte und Thrall die Flucht ermöglichte.\n\nNun haben die Ewigen Taretha gefangen genommen. Wenn wir nicht eingreifen, wird es kein Ablenkungsmanöver geben. Nehmt die Brandsätze, die ich Euch gegeben habe, und brennt die Internierungsbaracken nieder.", progress = "Wer seid Ihr?", completion = "Ihr seid mit Taretha befreundet? Das ist also ihr neuer Plan. Nun gut…", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29599] = {title = "Flucht aus Durnholde", objective = "Gebt Thrall Bescheid, wenn Ihr bereit seid. Folgt Thrall aus der Burg Durnholde und helft ihm, Taretha zu befreien und sein Schicksal zu erfüllen.\n\nSprecht mit Erozion im Alten Hügelland, wenn Ihr diese Aufgabe erfüllt habt.", description = "Ich habe große Pläne für mein Volk, <Fremder/Fremde>.\n\nEines Tages wird es seine Unterdrücker stürzen und sich erheben. Es wird die Ketten sprengen, die es halten und dies wird die Geburtsstunde der orcischen Horde sein.\n\nWir fliehen, wenn Ihr bereit seid.", progress = nil, completion = "Ihr habt eine großartige Aufgabe vollbracht, &lt;Name&gt;. Nun müssen die Erinnerungen des jungen Kriegshäuptlings an diese Ereignisse wieder so verändert werden, wie sie einst waren...", rewards = "Mantelung des KriegshäuptlingsBerührung des SturmsSüderstader SchuheVerteidigergurt von Tarrens MühleIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29600] = {title = "Schnelles Urteil", objective = "Tötet 16 Klingenrückenschnapper bei den Teichen der Reinheit.", description = "Diese Teiche sind etwas ganz Besonderes: In Pandaria gibt es sonst keinen Ort, der Leben so viel Nahrung bietet.\n\nLeider hat das auch die Aufmerksamkeit der einheimischen Fauna auf sich gezogen. Vor kurzem haben Drachenschildkröten herausgefunden, dass es auf der Ebene direkt über uns viele Teiche voller Krötenlaich gibt. Jetzt haben sie sich dort oben breitgemacht, trampeln die Lotusblüten nieder und greifen meine Arbeiter an.\n\nEinzeltiere sind nicht sonderlich gefährlich, aber in Gruppen können sie ganz schön gemein sein. Bitte, wenn Ihr ein wenig Kraft erübrigen könnt, helft uns, sie loszuwerden.", progress = nil, completion = "Ich bin Euch dankbar, &lt;Name&gt;.\n\nBitte nehmt dies als Zeichen meiner Wertschätzung.", rewards = "Satinmanschetten des SeidenmeistersSonnenbeschienene BindungenSchuppenarmbänder des HuangtzeBrünierte PaoquanarmschienenSeidene Manschetten des GoldfächersEbenenfalkenarmwickelHandgelenksschützer der Wilden EbenenSchwere DonnerfußarmplattenGepanzerte SonnensangarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29605] = {title = "Bruder gegen Bruder", objective = "Befreit Lakka aus ihrer Gefangenschaft. Kehrt zu Isfar in den Sethekkhallen zurück, wenn Ihr die Rettung abgeschlossen habt.", description = "Die Sethekk verließen Skettis, als Auchindoun explodierte.\n\nMein Bruder Syth gehörte zu ihren Anführern. Auf seinen Befehl suchten wir die Ruinen auf und stellten uns unserem Gott.\n\nNach kurzer Zeit warf mich Syth jedoch aus den Hallen, weil mir Zweifel an ihren Fähigkeiten kamen. Er erlaubte mir nicht, meine Schwester Lakka mitzunehmen. Werdet Ihr mir helfen, sie zu retten?", progress = nil, completion = "Zu wissen, dass Lakka frei ist, bedeutet, dass ich endlich all meine Bande zu den Sethekk abwerfen kann.\n\nEin Teil von mir wird mir Syths Tod niemals verzeihen, aber es musste getan werden. Ich werde die Todesriten für ihn vollziehen, wenn ich in Skettis ankomme.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nProphetenhalsring der SethekkOrakelfokus der SethekkHalsband des KlauenlordsMal des Rabenwächters\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][29606] = {title = "Terokks Erbe", objective = "Bringt Terokks Maske und Terokks Federkiel zu Isfar in den Sethekkhallen.", description = "Terokk, der Held von Arakkoa, verschwand eines Tages plötzlich und ließ nur seine Maske und seinen Speer zurück.\n\nDunkelwirker Syth hat sie immer noch in seinem Besitz und Klauenkönig Ikiss wacht über seinen Speer.\n\nEs würde meinem Volk viel bedeuten, wenn wir die Gegenstände zurückbekommen würden.", progress = "Die Relikte von Terokk sind schon viel zu lange aus Skettis fort. Konntet Ihr sie von den Sethekk zurückholen?", completion = "Vielleicht wird mir meine Rolle bei den Verbrechen der Sethekk niemals vergeben werden, aber ich möchte versuchen, meine Sünden zu büßen, indem ich die Relikte von Terokk meinem Volk zurückgebe", rewards = "Terokks FederkielTerokks MaskeAuf Euch wartet eine dieser Belohnungen:\n\nDie Sage von Terokk\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][29607] = {title = "Augen der Begierde", objective = "Händler Vijaad in den Sethekkhallen möchte, dass Ihr ihm 3 Kobaltaugen bringt.", description = "Ich habe einen Kunden, der sich für die Augen der kobaltblauen Schlangen interessiert, die sich hier angesiedelt haben.\n\nWenn Ihr mir einige dieser seltenen Edelsteine besorgen könntet, würde ich den Profit mit Euch teilen.\n\nEinverstanden?", progress = "Habt Ihr die Augen bekommen?", completion = "Wunderbare Stücke, gut gemacht!\n\nHier ist Euer Anteil, wie versprochen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29608] = {title = "Verbündete in Dalaran", objective = "Macht einen Greifenritt nach Dalaran und sprecht mit Isirami Sanftwind im Gasthaus Zum Gefeierten Helden.", description = "Willkommen in Nordend, <Name>. Man hat mich gebeten, die Reise nach Dalaran für Euch zu arrangieren, damit Ihr dort unsere Verbündeten treffen könnt.\n\nReitet auf einem Greifen nach Dalaran und sucht nach der Landung unser Gasthaus Zum Gefeierten Helden auf. Sprecht dort mit Isirami Sanftwind.\n\nSie wird Euch dabei helfen, Euren Ruhestein an die Stadt zu binden. Mit dem Portal in der Silbernen Enklave könnt Ihr dann rasch nach Sturmwind zurückreisen.", progress = nil, completion = "Willkommen in Dalaran! Dieses Gasthaus gehört zur Silbernen Enklave, dem offiziellen Hauptquartier der Allianz in dieser Stadt.\n\nVergesst nicht, Euren Ruhestein hier zu binden, damit Ihr rasch in die Stadt reisen und nebenan das Portal nach Sturmwind nutzen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29609] = {title = "Freunde in Dalaran", objective = "Lasst Euch vom Flugmeister einen Flug nach Dalaran geben und sprecht mit Uda dem Biest im Rattenloch.", description = "Willkommen in Nordend. Man hat mich gebeten, Eure Reise nach Dalaran zu arrangieren, damit Ihr unsere Freunde in der Stadt kennenlernen könnt.\n\nSprecht mit mir und nehmt einen Flug nach Dalaran an. Begebt Euch nach der Landung zum Gasthaus \"Das Rattenloch\".\n\nRedet dort mit Uda dem Biest.\n\nSie wird Euch dabei helfen, Euren Ruhestein an die Stadt zu binden. Dann könnt Ihr durch das Portal in Sonnenhäschers Zuflucht rasch nach Orgrimmar reisen.", progress = nil, completion = "Ich habe Euch erwartet. Dieses Gasthaus gehört zu Sonnenhäschers Zuflucht, der Hordenenklave von Dalaran.\n\nDenkt daran, Euren Ruhestein hier zu binden, damit Ihr rasch zur Stadt kommen und das Portal nach Orgrimmar, draußen neben dem Brunnen, benutzen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29611] = {title = "Die Kunst des Krieges", objective = "Sprecht mit General Nazgrim in der Feste Grommash.", description = "Lok'tar ogar, <Volk>. Ich bin Nazgrim.\n\nHiermit befehle ich Euch, Euch unverzüglich bei Garrosh Höllschrei in der Feste Grommash zu melden.\n\nAuf seinen Erlass hin haben alle im Dienst der Horde ihrem neuen Kriegshäuptling die Treue zu schwören.\n\nLasst ihn lieber nicht warten, <Volk>.", progress = nil, completion = "Ah, gut. Ihr seid da. Und keinen Augenblick zu früh...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29612] = {title = "Die Kunst des Krieges", objective = "Sprecht mit General Nazgrim in der Feste Grommash in Orgrimmar.", description = "Lok'tar ogar, alter Freund. Es ist schon zu lange her, seit wir miteinander gesprochen haben.\n\nEs freut mich zu sehen, dass Ihr heil aus den Tiefen von Vashj'ir hervorgekommen seid.\n\nKriegshäuptling Höllschrei hat mich hier in der Feste Grommash stationiert.\n\nAuf seinen Erlass hin haben alle im Dienst der Horde ihrem neuen Kriegshäuptling die Treue zu schwören.\n\nLasst ihn lieber nicht warten, <Name>.", progress = nil, completion = "Ah, gut. Ihr seid da. Und keinen Augenblick zu früh...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29613] = {title = "Ein gerechtes Schicksal", objective = "Tötet Kriegsherr Kalithresh und kehrt zu Behüterin Jhang in der Dampfkammer zurück.", description = "Kriegsherr Kalithresh leitet Operation Dampfkammer.\n\nEr muss sterben, <Name>. Die Naga lassen uns keine andere Wahl als Gewalt.\n\nZeigt ihm keine Gnade.", progress = nil, completion = "Ich wünschte, das wäre nicht nötig gewesen, aber die Naga haben alle Verhandlungsangebote abgelehnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29614] = {title = "Eindämmung ist der Schlüssel", objective = "Tötet 3 Sumpfoberanführer und 6 Aussätzige des Echsenkessels und erbeutet ein verstrahltes Zahnrad von Robogenieur Dampfhammer. Kehrt dann zu Naturalist Biss zurück.", description = "Die Naga haben sich mit den Lepragnomen verbündet, um eine schreckliche Krankheit in den Zangarmarschen zu verbreiten. Man begegnet ihr schon überall im Dampfkessel.\n\nVernichtet alles, das bereits befallen ist, und bringt mir das mittlere Zahnrad von Robogenieur Dampfhammer. Beeilt Euch!", progress = "Geht so sorgfältig wie möglich vor. Das Schicksal der Zangarmarschen hängt davon ab.", completion = "Ich bin froh, dass wir die Krankheit eingedämmt haben, bevor sie sich in den Zangarmarschen ausbreiten konnte. Danke.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29615] = {title = "Windrufer Klaue und die Wasserdiebin", objective = "Tötet Hydromantin Thespia und kehrt zu Windrufer Klaue in der Dampfkammer zurück.", description = "Die Naga versuchen schon seit längerem, das Wasser aus den Zangarmarschen abzupumpen. Die Dampfkammer ist der Dreh- und Angelpunkt dieser Operation. Überwacht wird sie von Hydromantin Thespia.\n\nIhr Tod würde die Naga empfindlich treffen.", progress = nil, completion = "Vielleicht können wir dem Land das verzweifelt benötigte Wasser nun zurückgeben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29616] = {title = "Sturm auf die Dampfkammer", objective = "Sprecht mit Behüterin Jhang in der Dampfkammer.", description = "Bisher ist es uns nicht gelungen, die Naga in der Dampfkammer, wo sich ihre Pumpenzentrale befindet, aufzuhalten.\n\nZum Glück versucht die Expedition, die ich ausgesandt habe, das zu ändern. Würdet Ihr Euch in die Dampfkammer begeben und Behüterin Jhang Eure Hilfe anbieten?", progress = nil, completion = "Ich danke den Sternen für Euch! Wir benötigen Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29617] = {title = "Das Tiankloster", objective = "Sprecht mit Lin Zartpfote im Tiankloster im Jadewald.", description = "Aus ganz Pandaria sind Leute angereist, um sich im Tiankloster gleich nördlich von hier ausbilden zu lassen. Wahrscheinlich, weil sie niemanden abweisen. Sie kümmern sich um Jinyu, Ho-zen... oder selbst Auswärtige wie Euch!\n\nMeine Freundin, Lin, ist gerade erst vor ein paar Wochen im Kloster aufgenommen worden. Wenn Ihr mehr über die Ausbildung bei unseren Mönchen erfahren möchtet, solltet Ihr vielleicht mit ihr sprechen!", progress = nil, completion = "Ihr seid in aufregenden Zeiten hier eingetroffen. Der Hohe Älteste Wolkensturz hat zugestimmt, eine neue Klasse Schüler im Kloster aufzunehmen. Dies könnte meine Chance sein, endlich zu lernen, wie man kämpft!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29618] = {title = "Der Hohe Älteste", objective = "Sprecht mit dem Hohen Ältesten Wolkensturz im Tiankloster im Jadewald.", description = "Wie außergewöhnlich, jemanden so fremdländisches wie Euch hier in unserem Tempel begrüßen zu dürfen, <Klasse>. Seid Ihr an einer Ausbildung interessiert?\n\nIhr... Ihr seht sehr stark aus. Es sollte Euch keine Mühe machen, im Kloster aufgenommen zu werden. Vielleicht solltet Ihr mit dem Hohen Ältesten dort oben auf dem Balkon sprechen.", progress = nil, completion = "Willkommen im Tiankloster. Ich hörte, dass die junge Lin Euch schon von unserer Rolle hier in unserem Dorf in den Bergen unterrichtet hat.\n\nWir verfügen über nicht viel Erfahrung mit Fremden. Es wäre uns eine große Ehre, wenn Ihr Euch an der Seite unseres Nachwuchses ausbilden lassen wollt. Wir können Euch aber kaum etwas anbieten, &lt;Klasse&gt;... außer vielleicht Wissen und das Verständnis dafür, was es heißt, ein Pandaren zu sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29619] = {title = "Ein höflicher Gast", objective = "Sammelt 8 reife Orangen im Orangenhain südlich des Tianklosters ein.", description = "Ich habe es schon gehört! Der Hohe Älteste möchte, dass Ihr eine Ausbildung zusammen mit uns macht!\n\nFür uns Schüler wird es ein Bankett geben... Und Ihr solltet vielleicht ein Geschenk mitbringen, als Zeichen der Höflichkeit.\n\nDie Orangen im Hain südlich des Tempels sind gerade reif und sehr süß. Bringt einige davon mit zum Bankett.", progress = "Seid Ihr bereit für das Bankett? Ich bin ja so aufgeregt.", completion = "Die sind perfekt. Was für ein tolles Geschenk, &lt;Name&gt;!\n\nOh, ich? Ich bringe natürlich Bier mit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29620] = {title = "Das große Bankett", objective = "Sprecht mit dem Hohen Ältesten Wolkensturz im Bankettareal im Tiankloster.", description = "Das Bankett sollte jetzt jeden Moment beginnen. Sucht den Hohen Ältesten auf und erweist ihm die Ehre. Ich werde direkt hinter Euch sein.", progress = "Die Ausbildung wird noch früh genug beginnen, junger <Klasse>. Aber zunächst müssen wir reden, trinken und essen.\n\nAllerdings imponiert mir Eure Disziplin.", completion = "Damit sind die Einführungen beendet. Ihr werdet jetzt bald mit Eurer Ausbildung beginnen können.\n\nAllerdings... könnt Ihr erst beginnen... NACHDEM wir noch einen Krug Bier getrunken haben. Oder vielleicht zwei, was meint Ihr, &lt;Name&gt;?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nThe Great Banquet: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29621] = {title = "UNUSED", objective = "Sprecht mit den Geistern der vier Hohen Ältesten im Tiankloster.", description = "Ich bitte Euch nur um eins und es ist nicht schwierig. Sprecht bitte mit den hohen Ältesten, die vor Wolkensturz kamen.\n\nIhre Geister haben Ihre Körper verlassen, aber sie sind noch an diesem Ort. Sprecht mit ihnen, nehmt Ihre Weisheit in Euch auf und biedert Euch ihnen an.\n\nIch erwarte Eure Rückkehr voller Spannung.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29622] = {title = "Beginn der Ausbildung", objective = "Meldet Euch bei Ausbilder Xann im Tiankloster im Jadewald.", description = "<Xiao sieht nicht von seiner Schüssel auf.>\n\nHey, <neuer Schüler/neue Schülerin>! Schön, dass Ihr das Bankett überlebt habt! Übung 1: Bestanden!\n\n<Xiao isst geräuschvoll.>\n\nIhr solltet mit Ausbilder Xann sprechen. Er erwartet Euch sicher schon zu den täglichen Übungen.\n\n<Er isst weiter. Ihr vermutet, dass er Euch nichts weiter zu sagen hat.>", progress = nil, completion = "Erst trinkt Ihr zu viel Bier und dann kommt Ihr zu spät zu den Übungen? Ihr scheint Euch ja schon an die Pandaren-Kultur gewöhnt zu haben.\n\nAlso fangen wir an.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29623] = {title = "Perfektion", objective = "Führt 12 Übungsschläge in der Ausbildungsarena des Klosters aus, indem Ihr die Beispiele nachahmt.", description = "Perfektion kann durch Wiederholung erlangt werden. Alle Schüler in der Ausbildungsarena da unten werden früher oder später die perfekten Formen finden... wenn sie nicht vorher aufgeben. Das ist eine Tatsache.\n\nIch möchte Euch empfehlen, sich ihnen anzuschließen, <Name>. Als ein Ehrengast des Klosters seid Ihr schließlich nicht angehalten, die 10.000 Wiederholungen täglich auszuführen. Folgt einfach für ein paar Minuten den Beispielen derjenigen, die es vormachen.", progress = "Auch ich habe einst in diesem Bereich meine Ausbildung gemacht. Damals war alles noch viel einfacher.", completion = "Ihr kämpft aber nicht zum ersten Mal, oder? Eure Formen sind nicht perfekt, aber durchaus geübt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMit dem Trainieren aufhören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29624] = {title = "Bitte recht aufmerksam", objective = "Zerstört 2 Sandsäcke. Folgt den Anweisungen von Ausbilder Xann, um zu entscheiden, welche Säcke angegriffen werden sollen.", description = "In Eurer nächsten Prüfung geht es um Konzentration und Aufmerksamkeit. Ich möchte, dass Ihr Eure Fähigkeiten an den Sandsäcken unten im Übungsbereich verfeinert.\n\nDie Säcke sind jeweils in Zweiergruppen aufgehängt. Wenn ich \"links\" rufe, greift Ihr den Sack auf der linken Seite an. Wenn ich \"rechts\" rufe, greift Ihr den Sack auf der rechten Seite an.\n\nWenn Ihr diesen einfachen Anweisungen nicht folgen könnt, wird die Aufgabe umso schwerer.\n\nUnd jetzt schlagt auf diese Säcke ein, bis sie platzen, <Name>.", progress = "Worauf wartet Ihr?", completion = "Ihr zählt vielleicht nicht zur regulären Schülerschaft hier, aber trotzdem könnt Ihr ja etwas lernen.\n\nIch versichere Euch, dass die Fähigkeit, schnell von einem Ziel zum anderen wechseln zu können, in zukünftigen Kämpfen von großem Wert sein kann.", rewards = "NebelbernkordelSchwarzdickichtgürtelJadehexentaillenschutzGlasseeschnallengürtelSeidenwaldkordelTiefenwaldgürtelFuchswäldchengürtelDonnerholzgurtJadetigergurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29625] = {title = "UNUSED", objective = "temp", description = "temp", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][29626] = {title = "Klosterwart Wu", objective = "Meldet Euch bei Klosterwart Wu im Tiankloster im Jadewald.", description = "Wir haben nicht viele Regeln hier, aber eine davon solltet Ihr Euch merken. Wer essen will...\n\n<Xiaos Magen knurrt vernehmlich.>\n\n...muss etwas dafür tun. Der Klosterwart Wu kann Euch Eure heutigen Arbeiten zuweisen. Er befindet sich auf dem Markt im Westen.", progress = nil, completion = "&lt;Wu spricht Euch kurz angebunden an.&gt;\n\nIhr seid &lt;Name&gt;, oder? Der Lieblingssohn des Hohen Ältesten? Ja, Ihr wart doch auch auf dem Bankett.\n\nAber ich werde Euch nicht bevorzugt behandeln, junger Herr. Ihr werdet hier genauso hart arbeiten wie alle anderen Pandaren-Schüler.\n\nVielleicht sogar noch härter.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29627] = {title = "Ein ordentliche Waffe", objective = "Besorgt 6 Rattanruten aus der Gegend um den Markt vom Tiankloster.\n\nKauft eine Phiole Schwarznussextrakt von Juni Weißblüte.\n\nKauft 3 dreifach bittere Bräue von Braumeister Lei Kanglei.", description = "Aber immer der Reihe nach.\n\nOrdentliche Schüler benötigen eine ordentliche Waffe. Und die vorbildlichen Schüler bauen sich ihre eigenen Waffen... oder sammeln zumindest die Materialien dafür selbst ein.\n\nDie in der Nähe wachsenden Ruten sollten eine gute Waffe ergeben. Und außerdem müsst Ihr noch Schwarznussextrakt kaufen, um das Holz zu behandeln. Und wo Ihr schon mal Einkaufen geht, könnt Ihr gleich etwas Bier mitnehmen, damit...\n\n<Wu hält inne.>\n\nAlso, Ihr wisst schon, was man mit Bier so macht.", progress = "<Wu schaut Euch erwartungsvoll an.>", completion = "&lt;Klosterwart Wu nimmt dankbar die Materialien entgegen.&gt;\n\nBis zum Ende Eurer Ausbildung werde ich Euch eine Waffe gefertigt haben. Und jetzt weiter mit der echten Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29628] = {title = "Ein starker Rücken", objective = "Holt einen kochenden Kessel von Mutter Wu im Wachsgehölz ab und kehrt dann zu Klosterwart Wu im Tiankloster zurück.", description = "Einige unserer Schüler haben einen... enormen Appetit. Und manchmal haben wir Schwierigkeiten, genug Nahrung für alle bereitzustellen. In diesen Fällen müssen wir um Hilfe bitten.\n\nIn einem kleinen Haus im Nordwesten lebt eine freundliche, ältere Dame, die sich bereit erklärt hat, etwas Eintopf für unsere Schüler zu kochen. Ihr müsstet nur zu ihr gehen und ihn abholen.", progress = "Sie ist wirklich eine sehr nette Frau und eine sehr gute Köchin.\n\nDie beste Köchin der Welt, würde ich sagen.", completion = "Ich werde mich darum kümmern, dass der Eintopf gerecht unter den Schülern aufgeteilt wird.\n\nNachdem ich etwas für mich abgezweigt habe, versteht sich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29629] = {title = "Eine ruhige Hand", objective = "Besorgt 80 Phiolen Rötelblattextrakt von den Rötelblattbüscheln im Wachsgehölz.", description = "Der Schwarznussextrakt, den Ihr von Juni Weißblüte gekauft habt, ist nur einer von vielen Extrakten, den wir hier für verschiedene Verwendungen bereit halten.\n\nRötelblattextrakt zum Beispiel kann man aus den Blumen in der Gegend vom Wachsgehölz im Westen gewinnen. Aus einer einzigen Blume erhält man mehrere Einheiten, aber man benötigt eine ruhige Hand, um der Blume den gesamten Extrakt zu entziehen.", progress = "Die früheren Kräutermeister sollen in der Lage gewesen sein, 20 Phiolen Extrakt aus einer einzelnen Blume zu gewinnen.", completion = "Und nicht vergessen, die Hände zu waschen. Der Rötelblattsaft geht nie wieder ab.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29630] = {title = "Und eine harte Faust", objective = "Erledigt 10 Grünholztrickster im Wachsgehölz.", description = "Die Grünwaldgeister im Wachsgehölz westlich von hier stellen zwar keine unmittelbare Gefahr für uns dar, aber ihre Anzahl hat sich in letzter Zeit alarmierend erhöht - und damit auch ihre verschlagenen Possen.\n\nEs gehört zu unserer Pflicht als Hüter des Waldes, das Gleichgewicht zu wahren. Und Eure Pflicht ist es, diese Geister wieder zurück in die Erde zu befördern.", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Die Geister werden sich in wenigen Tagen schon wieder vermehrt haben, aber zumindest im Augenblick ist das Gleichgewicht gewahrt.", rewards = "NebelbernhandschuheSchwarzdickichthandschuheJadehexenstulpenGlasseehandschuheSeidenwaldhandschützerTiefenwaldhandschuheFuchswäldchenstulpenDonnerholzstulpenJadetigerstulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29631] = {title = "Mit Feuereifer", objective = "Tötet 6 Wachsgehölztiger.", description = "Kann ich Euch um einen Gefallen bitten, <Name>?\n\nBevor ich in das Kloster kam, hatte ich keinerlei Erfahrung mit Kämpfen. Im Zuge meiner Ausbildung wurde ich zwar auch im Umgang mit Waffen geschult, aber niemals wirklich gefährlichen Situationen ausgesetzt. Aber jetzt bin ich nicht mehr in der Ausbildung, sondern ein voll bezahlter Wächter. Man erwartet von mir, dass ich das Gebiet um jeden Preis verteidige.\n\nMit den Grünwaldgeistern kann ich es aufnehmen, aber die Tiger im westlichen Wachsgehölz sind eine Nummer zu groß für mich. Könntet Ihr Euch vielleicht um sie kümmern?", progress = "Bitte sagt niemanden etwas von unserer Vereinbarung. Meine Feigheit ist mir peinlich.", completion = "Ich danke Euch, &lt;Name&gt;. Tausend Dank.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29632] = {title = "Bereit zum Kampf", objective = "Besiegt 8 Schüler von Tian in Übungskämpfen im Tiankloster.", description = "Also, jetzt wollen wir doch mal sehen, aus welchem Holz Ihr geschnitzt seid.\n\nIhr trefft überall im Kloster auf Schüler. Fordert sie zu einem Kampf heraus. Bringt sie an ihre Grenzen. Ihnen wurde schließlich das gleiche aufgetragen wie Euch.\n\nEgal, ob Sieg oder Niederlage – aus dem Kampf gehen beide Kontrahenten gestärkt hervor.", progress = "In Eurer Heimat mögt Ihr zu den Helden zählen. Hier aber müsst Ihr Euch erst noch beweisen.", completion = "&lt;Meister Steinfaust schaut Euch misstrauisch an.&gt;\n\nAlso gut, ich habe genug gesehen. Schluss mit dem Verprügeln der jungen Schüler. Wir machen mit der nächsten Ausbildungsphase weiter.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29633] = {title = "Der wehrhafte Zhi-Zhi", objective = "Besiegt Zhi-Zhi im Tiankloster.", description = "Auf den Hügeln rechts von mir findet Ihr einen Ho-zen namens Zhi-Zhi. Auch er hat genug Übungskämpfe gewonnen, um einen Rang aufzusteigen. Ich denke, er sollte eine größere Herausforderung für Euch darstellen.\n\nFordert ihn heraus und versucht, ihn zu besiegen.", progress = nil, completion = "Offensichtlich muss ich Euch schon wieder einen Rang aufsteigen lassen, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29634] = {title = "Der uralte Husshun", objective = "Fordert Husshun im Tiankloster heraus und besiegt ihn.", description = "Die Jinyu sind schon seit langer Zeit Verbündete der Pandaren und die Mitglieder ihres Volkes sind jederzeit in unserem Kloster willkommen. Husshun, einer ihrer erfahreneren Schamanen, ist einer unserer neuen Schüler.\n\nSeine Fähigkeiten als Mönch sind höchstens Mittelmaß, aber er ist dennoch ein starker Gegner. Er sollte die Herausforderung darstellen, nach der Ihr sucht.", progress = nil, completion = "Ich muss Euch warnen, &lt;Klasse&gt;:\n\nWenn Ihr weiterhin meine besten Schüler besiegt, kann ich Euch nicht weiter unterrichten. Und dann habt Ihr keinen Grund mehr, meine Gesellschaft zu genießen.\n\nDenkt daran, bevor Ihr weiter mit solcher Geschwindigkeit meine anderen Schüler ausschaltet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29635] = {title = "Der hungrige Xiao", objective = "Fordert Xiao im Tiankloster heraus und besiegt ihn.", description = "Meinen besten Schüler, Xiao, habt Ihr bereits am Tisch beim Bankett kennengelernt. Ich selbst hätte ihm schon längst seinen Abschluss gegeben, aber Ausbilder Xann besteht darauf, dass er noch mehr an seiner Disziplin arbeiten müsse.\n\nMeiner Meinung nach ist Disziplin vollkommen unwichtig, solange man alle seine Kämpfe gewinnt. Ich würde gern sehen, ob Xiao seine Siegesserie gegen Euch fortsetzen kann.", progress = "Dem jungen Xiao winkt eine große Zukunft als Kampfkünstler. Ich wünsche Euch viel Glück für Euren nächsten Kampf.", completion = "Ich kann nicht behaupten, dass ich überrascht bin, &lt;Volk&gt;. Ihr seid ein herausragender Kämpfer und ein exzellenter &lt;Klasse&gt;.", rewards = "BambusblattarmplattenBambusplattenarmplattenFuchswäldchenarmschienenBambusplattenarmwickelBambusstreifenmanschettenBambusstreifenarmschienenJadehexenarmschützerBambusblattbindungenBambusfasermanschettenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29636] = {title = "Ein langer Weg", objective = "Meldet Euch bei Ausbilderin Myang im westlichen Bereich des Tianklosters.", description = "Ich habe Euch alles gelehrt, was in meiner Macht steht, <Name>. Jetzt ist es an der Zeit, dass Ihr Euch an die Ausbilderin Myang wendet.\n\nDie Kämpfe, die sie ausrichtet, sind weniger traditionell als meine. Aber der Weg von reisenden Abenteurern wie Euch ist unvorhersehbar und eine umfangreiche Kenntnis der verschiedenen Kampfstile könnte sich als großer Vorteil erweisen.\n\nLebt wohl, <Name>, und viel Glück bei Eurer weiteren Ausbildung.", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;. Ihr habt Euch einen guten Ruf unter unseren Schülern hier erworben. Viele Eurer Übungspartner haben mir von Euch berichtet. Zumeist mit aufgeplatzten und geschwollenen Lippen.\n\nIch freue mich schon darauf, Euch zu betreuen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29637] = {title = "Massenschlägerei", objective = "Entzündet das Kloster-Feuerwerk im Ring des Inneren Fokus und überlebt die zwei Minuten dauernde Massenschlägerei.", description = "Meister Steinfaust hat Euch gelehrt, wie Ihr gegen einen einzelnen Gegner bestehen könnt. Jetzt erlernt Ihr den Kampf gegen eine Gruppe von Gegnern.\n\nZum Beispiel gegen fünfzig.\n\nBegebt Euch in den Ring des Inneren Fokus da unten und entzündet das Feuerwerk, wenn Ihr bereit seid. Meine Helfer werden gemeinsam auf Euch losstürzen.\n\nVersucht, den Ansturm zu überleben.", progress = "Viel Glück, <Name>.", completion = "Euer Kampfstil ist bemerkenswert, &lt;Name&gt;. Die anderen Schüler könnten viel von Euch lernen.", rewards = "Stab des inneren FokusInstrukteursstabOrdensstab von TianSchwert des alleinigen SiegersAxt des einsamen ChampionsJadegewehrTrophäe des letzten ÜberlebendenSteitkolben des inneren FriedensMajestätische KurzklingeSteitkolben des GleichmutsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29638] = {title = "UNUSED", objective = "Meldet Euch beim Hohen Ältesten Wolkensturz im Bankettareal im Jadewald.Eure Ausbildung ist abgeschlossen, Kind. Der Kreislauf ist geschlossen. Zum Glück endet er genau dort, wo er begonnen hat... bei einem Festmahl.\n\nWir treffen uns im Bankettareal. Ich werde wahrscheinlich auf einem Tisch tanzen.Der folgende Zauber wird auf euch gewirkt:\n\n", description = "Eure Ausbildung ist abgeschlossen, Kind. Der Kreislauf ist geschlossen. Zum Glück endet er genau dort, wo er begonnen hat... bei einem Festmahl.\n\nWir treffen uns im Bankettareal. Ich werde wahrscheinlich auf einem Tisch tanzen.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFlying Colors: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29639] = {title = "Mit Bravour bestanden", objective = "Meldet Euch beim Hohen Ältesten Wolkensturz im Tiankloster im Jadewald.", description = "Ihr habt alle Prüfungen bestanden, die wir Euch gestellt haben, <Name>. Es ist an der Zeit, dass Ihr Euch jetzt um größere und wichtigere Angelegenheiten kümmert.\n\nAber zuvor gibt es noch ein Bankett! Der Hohe Älteste erwartet Euch im Bankettareal, um die Beendigung Eurer Klosterausbildung gebührend zu feiern.", progress = nil, completion = "Ich gratuliere Euch, &lt;Name&gt;. Obwohl Ihr rein freiwillig an der Ausbildung teilgenommen habt, waren Eure Ergebnisse sehr beeindruckend. Ihr seid ein Vorbild für unsere jüngeren Schüler.\n\nDer Klosterwart Wu hat dies hier für Euch angefertigt. Ihr könnt darüber verfügen, wie es Euch beliebt.", rewards = "Großaxt der EhreSchwert des EntsetzensTianverteidigerKlinge der EhreStreitkolben des SchreckensDer folgende Zauber wird auf euch gewirkt:\n\nFlying Colors: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29640] = {title = "Findet Spion To'gun", objective = "Findet Spion To'gun im Schattenlabyrinth von Auchindoun.", description = "Der Schattenrat hat die meisten unserer Spione bereits getötet, aber To'gun, der fliehen konnte, war so dumm zurückzukehren!\n\nIhr müsst ihn finden. Er ist unvernünftig, aber wir müssen herausfinden, was er weiß.", progress = nil, completion = "Wäret Ihr so nett, mir aus dem Käfig zu helfen? Er ist ein wenig beengt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29641] = {title = "Seeleninstrumente", objective = "Stehlt 5 Seeleninstrumente und bringt sie zu Spionin Grik'tha im Schattenlabyrinth von Auchindoun.", description = "Sie haben mich gefoltert, damit ich ihnen alles verrate, was ich weiß.\n\nDie anderen haben sie an Höllenschlund verfüttert, ich hätte als Nächstes dran sein sollen. Aber ich habe ihnen nichts verraten!\n\nSie benutzen spezielle Geräte, damit ihre Beschwörungen mächtiger werden. Diese Geräte müsst Ihr stehlen!", progress = "Habt Ihr To'gun gefunden?", completion = "Dies sind also die Seeleninstrumente, mit denen der Schattenrat seine Beschwörungskraft erhöht? Interessant.", rewards = "Eiserne Armschützer der Sha'tariArmschienen der AuchenaiHandgelenksschützer der SpionagemeisterinWickeltücher von ShattrathIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29642] = {title = "Ärger in Auchindoun", objective = "Meldet Euch bei Feldkommandeur Mahfuun im Schattenlabyrinth in Auchindoun in den Wäldern von Terokkar.", description = "Meine Spione in Auchindoun haben uns erschreckende Berichte geschickt. Seit seiner Explosion vor ein paar Jahren hat dieser Ort nichts als Ärger gebracht.\n\nDort ist etwas - mal wieder - ganz schön schief gegangen, und der Schattenrat bereitet sich auf einen Krieg vor. Auch wenn die Berichte viele Details verschweigen, müssen sie sich auf einen Krieg im Inneren vorbereiten.\n\nIhr müsst Euch zum Eingang des Schattenlabyrinths begeben. Mein Feldkommandeur, Mahfuun, wird Euch genau erklären, was zu tun ist.", progress = nil, completion = "Wurde auch Zeit, dass Ihr eintrefft.\n\nMehlisah hat bereits vor Tagen angekündigt, dass sie Hilfe schicken würde. Und wir kämpfen hier noch länger!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29643] = {title = "Der Kodex des Blutes", objective = "Lest den Kodex des Blutes im Schattenlabyrinth von Auchindoun.", description = "Vor zwei Jahren beschwor der Schattenrat ein Wesen, das eine Schneise der Verwüstung in Auchindoun hinterließ.\n\nLest den Kodex des Blutes, um herauszufinden, was damals geschah. Seid jedoch vorsichtig, denn Großmeister Vorpil beschützt ihn mit seinem Leben.", progress = nil, completion = "Während Ihr den magiegeladenen Folianten öffnet, überkommt Euch ein Gefühl des Schreckens.\n\nIrgendetwas ist hier eindeutig nicht in Ordnung!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29644] = {title = "In das Herz des Labyrinths", objective = "Vernichtet Murmur und meldet Euch danach bei Feldkommandeur Mahfuun im Schattenlabyrinth von Auchindoun.", description = "Der Schattenrat hat die Kontrolle über das kosmische Wesen, das sie vor fast zwei Jahren beschworen haben, verloren!\n\nMan nennt es Murmur und es droht, den Schattenrat zu überrennen und zu entkommen!", progress = nil, completion = "Ich schüttele mich bei dem Gedanken, was hätte passieren können, wenn Murmur entkommen wäre.\n\nDanke, mutiger Held.", rewards = "Eiserne Schienbeinschützer der Sha'tariStiefel der AuchenaiStiefel der SpionagemeisterinStofftreter von ShattrathIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29645] = {title = "Botschafter Höllenschlund", objective = "Tötet 12 Ritualisten der Kabale sowie Botschafter Höllenschlund und kehrt zu Feldkommandeur Mahfuun im Schattenlabyrinth von Auchindoun zurück.", description = "Als die Kabale unsere Spione entdeckte, verfütterte sie alle an Botschafter Höllenschlund.\n\nUnsere Männer verdienen Gerechtigkeit. Tötet die Ritualisten, die Höllenschlund binden und vernichtet dann auch ihn.\n\nEr hat dieses Schicksal schon lange verdient.", progress = nil, completion = "Das bringt zwar niemanden zurück, aber wenigstens wurde der Gerechtigkeit Genüge getan.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29646] = {title = "Mit Bravour bestanden", objective = "Meldet Euch beim Hohen Ältesten Wolkensturz im Bankettareal im Jadewald.", description = "So, ich habe Euch alles beigebracht, was ich konnte. Und die anderen offensichtlich auch.\n\nDer Hohe Älteste erwartet Euch im Bankettareal, um Euren Abschied gebührend zu feiern. Nicht, dass wir Euch gerne gehen lassen... Er feiert einfach gern.", progress = nil, completion = "Ich gratuliere Euch, &lt;Name&gt;. Obwohl Ihr rein freiwillig an der Ausbildung teilgenommen habt, waren Eure Ergebnisse sehr beeindruckend. Ihr seid ein Vorbild für unsere jüngeren Schüler.\n\nDer Klosterwart Wu hat dies hier für Euch angefertigt. Ihr könnt darüber verfügen, wie es Euch beliebt.", rewards = "Großaxt der EhreSchwert des EntsetzensTianverteidigerKlinge der EhreStreitkolben des SchreckensDer folgende Zauber wird auf euch gewirkt:\n\nFlying Colors: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29647] = {title = "Mit Bravour bestanden", objective = "Meldet Euch beim Hohen Ältesten Wolkensturz im Bankettareal im Jadewald.", description = "Die Krawallgrube war Eure letzte Herausforderung. Ihr habt alle Disziplinen gemeistert, die an dieser Schule gelehrt werden.\n\nEure Ausbildung begann mit einem Bankett und so soll sie auch enden. Der Hohe Älteste erwartet Euch im Bankettareal und ich werde gleich hinter Euch sein.", progress = nil, completion = "Ich gratuliere Euch, &lt;Name&gt;. Obwohl Ihr rein freiwillig an der Ausbildung teilgenommen habt, waren Eure Ergebnisse sehr beeindruckend. Ihr seid ein Vorbild für unsere jüngeren Schüler.\n\nDer Klosterwart Wu hat dies hier für Euch angefertigt. Ihr könnt darüber verfügen, wie es Euch beliebt.", rewards = "Großaxt der EhreSchwert des EntsetzensTianverteidigerKlinge der EhreStreitkolben des SchreckensDer folgende Zauber wird auf euch gewirkt:\n\nFlying Colors: Quest Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29648] = {title = "UNUSED", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][29649] = {title = "Wie man ein Leben rettet", objective = "Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr ihm Teufelsglut bringt.", description = "Gunny stirbt an einem mächtigen Fluch, <Name>.\n\nGroßhexenmeister Nethekurse benutzt zwei mystische Kohlefeuer zur Verstärkung seiner Kräfte. Vielleicht könnten wir mit etwas Glut aus einem Kohlefeuer diese dunkle Magie rückgängig machen.", progress = "Habt Ihr die Glut dabei? Wir haben nicht viel Zeit.", completion = "Er war ein guter Soldat.", rewards = "Unerschrockene HandschützerGravierter RunengürtelSpäherschulterklappen der ExpeditionHandschuhe der BewahrungStiefel des KuratIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29650] = {title = "Teufelsglut", objective = "Steingardist Stok'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr ihm Teufelsglut bringt.", description = "Caza'rez stirbt wie ein Feigling.\n\nGroßhexenmeister Nethekurse hat ihn mit einem schrecklichen Fluch belegt. Bringt mir etwas Glut aus seinen Kohlenpfannen. Vielleicht können wir die Magie damit umkehren, bevor es zu spät ist.", progress = "Habt Ihr die Glut bekommen? Caza'rez verdient es, wie ein Krieger zu sterben.", completion = "Ich werde viele Lieder zu seinem Ruhm anstimmen.", rewards = "Unerschrockene HandschützerGravierter RunengürtelSpäherschulterklappen der ExpeditionHandschuhe der BewahrungStiefel des KuratIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29651] = {title = "Ehrt die Sterbenden", objective = "Caza'rez in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr 4 Legionäre der Zerschmetterten Hand, 2 Zenturionen der Zerschmetterten Hand und 2 Champions der Zerschmetterten Hand tötet.", description = "Ihre Elitekrieger sind gnadenlos... so... mächtig.\n\n<Caza'rez spuckt Blut.>\n\nIhr müsst sie töten... sonst werden wir Kargath nie besiegen...", progress = nil, completion = "Caza'rez ist... von uns gegangen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29652] = {title = "Ein letzter Gefallen", objective = "Gunny in den Zerschmetterten Hallen der Höllenfeuerzitadelle möchte, dass Ihr 4 Legionäre, 2 Zenturionen und 2 Champions der Zerschmetterten Hand tötet.", description = "Der alte Gunny macht's nicht mehr lange...\n\nErweist mir einen letzten Gefallen und tötet die größten, übelsten Höllenorcs, die Ihr finden könnt.\n\nIm Andenken an alte Zeiten, ja?", progress = nil, completion = "Hätten wir ihn doch retten können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29653] = {title = "Der Wille des Kriegshäuptlings", objective = "Bringt Kriegshäuptling Kargaths Faust zu Steingardist Stok'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle.", description = "Kargath war einst einer der größten Helden der Horde.\n\nDoch nun trägt er den falschen Mantel des Kriegshäuptlings. Bringt mir die nach ihm benannte Waffe, damit wir uns an seine früheren Heldentaten erinnern können und nicht an die Gräuel, die er heute anrichtet.", progress = "Habt Ihr einen Beweis für den Sieg über Kargath Messerfaust?", completion = "Wir dürfen den Orc nicht vergessen, der Kargath einst war, noch die Lektion, die uns sein Fall sein sollte.", rewards = "Rute der finsteren SchattenVikarsumhangAuf Euch wartet eine dieser Belohnungen:\n\nBand des EroberersStümmelfausts Halsreif\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][29654] = {title = "Das Schicksal wenden", objective = "Bringt Kriegshäuptling Kargaths Faust zu Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle.", description = "Es gibt nur einen Weg, um sicherzustellen, dass die Höllenorcs die Ehrenfeste und die Allianz nicht länger bedrohen.\n\nIhr Kriegshäuptling muss sterben.\n\nBringt mir die Waffe, die nach ihm benannt ist, damit wir seinen Tod niemals vergessen.", progress = "Habt Ihr einen Beweis für den Sieg über \"Kriegshäuptling\" Kargath Messerfaust mitgebracht?", completion = "Mit Eurer Hilfe haben wir dem Feind schweren Schaden zugefügt.\n\nDie Ehrenfeste war schon seit Jahren nicht mehr so sicher.", rewards = "Mantel der BelebungNethekurses Rute der QualenAuf Euch wartet eine dieser Belohnungen:\n\nNalikos RacheMedaillon des tapferen Wächters\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][29655] = {title = "Ein ganz besonderes Tuch", objective = "Tötet Kriegshetzer O'mrogg und bringt sein Kriegstuch zu Steingardist Stok'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle.", description = "Kriegshetzer O'mrogg hat mehr mutige Soldaten auf dem Gewissen als jeder andere Feind, dem ich bisher begegnet bin. Er ist skrupellos, listig und äußerst mächtig.\n\nTötet ihn und bringt mir sein Kriegstuch. Wir werden ein Banner daraus nähen, sodass der Zorn der Horde für alle sichtbar ist.", progress = "Habt Ihr das Tuch dabei?", completion = "Sehr gut. Nun werden diese blutgierigen Ungeheuer sehen, mit wem sie sich angelegt haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29656] = {title = "O'mroggs Kriegstuch", objective = "Tötet Kriegshetzer O'mrogg und bringt sein Kriegstuch zu Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle.", description = "Sturmwind möchte Beweise für unsere Kriegserfolge sehen.\n\nWir könnten ihm Leichensäcke schicken, aber ich denke, das Kriegstuch von O'mrogg, Kargaths mächtigstem Krieger würde ihn mehr beeindrucken. Traut Ihr ihn Euch zu?", progress = "Habt Ihr das Tuch dabei?", completion = "Meine Vorgesetzten werden damit sehr zufrieden sein. Danke.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29657] = {title = "Aus großer Kraft folgt große Verantwortung", objective = "A'dal bittet Euch, Mechanolord Kapazitus in der Mechanar der Festung der Stürme zu töten.", description = "<Ihr hört eine Stimme, leicht wie der Klang winziger Glocken, in Eurem Kopf.>\n\nIn der Mechanar entstehen durch die Technologie meines Volks Manazellen, Objekte, die eine gewaltige Energie in sich tragen.\n\nTötet Mechanolord Kapazitus, damit Kael'thas' Streitkräfte sich diese Macht nicht zu Nutze machen können.", progress = nil, completion = "Beeindruckend, &lt;Name&gt;. Doch es gibt noch viel zu tun.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29658] = {title = "Der Kalkulator", objective = "A'dal hat Euch gebeten, Pathaleon den Kalkulator in der Mechanar der Festung der Stürme zu töten.", description = "<Eine leichte Brise streicht über Euer Gesicht.>\n\nNur noch eines bleibt zu tun.\n\nPathaleon der Kalkulator überwacht die meisten Operationen seines Herrn. Er persönlich trägt die Verantwortung für einen Großteil des Leids, das in letzter Zeit über die Welt gekommen ist.\n\nIch möchte, dass Ihr ihn vernichtet.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29659] = {title = "Der verlorene Schatz", objective = "Beschafft für A'dal den Blendenden Zorn aus dem Behälter der Legion in der Mechanar der Festung der Stürme.", description = "Ich spüre, dass eines der Artefakte meines Volkes gestohlen wurde und im Behälter der Legion aufbewahrt wird.\n\nSie dürfen nicht entdecken, wie mächtig es ist. Würdet Ihr die Torwächter töten und es wiederbeschaffen? Ich wäre Euch sehr dankbar.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29660] = {title = "Rettung der Botanika", objective = "A'dal möchte, dass Ihr Kommandantin Sarannis, Hochbotaniker Freywinn und Dorngrin den Hüter in der Botanika der Festung der Stürme tötet.", description = "Kael'thas und seinen Streitkräften ist es nicht gelungen, die vielen Kreaturen in der Botanika niederzuwerfen. Wir müssen versuchen, ihre Fehler wiedergutzumachen.\n\nDer erste Schritt ist die Eliminierung ihrer Streitkräfte, damit sie keinen weiteren Ärger mehr verursachen können.", progress = nil, completion = "Die Kreaturen an diesem Ort hätten sie früher oder später auch ohne unser Eingreifen getötet. Wir haben zum Besten aller gehandelt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29661] = {title = "Die Lektion trockenen Fells", objective = "Findet einen Weg über die Balancierpfähle und läutet die Übungsglocke.", description = "Über die Meditation werde ich versuchen herauszufinden, wo sich Shu aufhält und wie wir dorthin gelangen können. In der Zwischenzeit könntet Ihr sicherlich von etwas Übung und Disziplin profitieren.\n\nEure erste Aufgabe wird diejenige sein, die allen Schülern, die sich in die Teiche begeben, zufällt: Findet einen Weg über die Balancierpfähle im Westen und läutet die Glocke, ohne in den Teich zu fallen.\n\nSolltet Ihr herunterfallen, wird der Fluch des Teichs es Euch erschweren, den Pfahl erneut zu erklimmen, sodass Ihr zum Ufer zurückkehren müsst, um von vorn zu beginnen.\n\nOh... und passt auf die Kraniche auf...", progress = nil, completion = "Gut. Ihr lernt schnell.", rewards = "Unbeschädigte KordelUnbeschädigter GürtelbundUnbeschädigter GürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29662] = {title = "Härter als Schilfrohre", objective = "Sammelt 8 Stücke hartes Tränenholzschilf.", description = "Besorgt mir etwas Schilfrohr von den Teichen ganz in der Nähe.\n\nFragt nicht warum. Tut es einfach, und lernt.", progress = "Euch meine Stärke zu schildern ist sinnlos. Ich muss sie Euch demonstrieren.", completion = "Gut.\n\nEs gibt kein einziges Schilfrohr, das meiner Kraft jemals widerstanden hätte.\n\nTretet zurück und lasst mich Eure Zweifel zerstreuen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nStapel Schilfrohr beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29663] = {title = "Die Lektion des balancierten Steines", objective = "Besiegt 6 Mönche der Tushui auf den Balancierpfählen.", description = "Ich benötige Ruhe, während ich meditiere. Übt Euch in Eurer Kampfkunst, während ich über Shus Aufenthaltsort nachsinne.\n\nAndere Mönche trainieren ihre Balance und Fähigkeiten im Kampf auf den Balancierpfählen in den umliegenden Teichen. Fordert sie heraus und besiegt sie.", progress = nil, completion = "Eure Fähigkeiten nehmen sichtlich zu. Euer Tritt wird sicherer. Eure Schläge sind kraftvoller.\n\nDisziplin und Übung sind die Schlüssel, um Euer Potenzial voll auszuschöpfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29664] = {title = "Die Flammen des Herausforderers", objective = "Entzündet Eure unangezündete Herausfordererfackel am Kohlenbecken der flackernden Flamme und benutzt sie dann, um die 3 Kohlenbecken in der Nähe von Meister Li Fei anzuzünden.", description = "Ihr habt einen starken Geist und einen starken Willen, aber Euch fehlen die Fähigkeiten, um mir im Kampf gegenüberzutreten. Euer Körper muss den Kampf bestehen, aber in Wahrheit ist es Euer Charakter, der geprüft werden soll.\n\nLasst uns Chancengleichheit herstellen.\n\nNehmt diese Fackel, zündet sie im Kohlenbecken neben mir an und benutzt sie, um die drei erloschenen Kohlenbecken um den Teich herum anzuzünden.", progress = nil, completion = "Diese Feuer werden Euch die Stärke verleihen, die Ihr noch nicht erlangt habt. Sie werden Euer wahres Potenzial erhellen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFackel des Herausforderers abbrechen\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29665] = {title = "Vom Regen in die Traufe", objective = "Bezwingt 8 Peiniger der Tiefenschuppen.", description = "Nachdem ihr Schiff abgestürzt war, begannen finstere Kreaturen, aus dem Meer emporzusteigen und das Wrack zu durchforsten. Bei all dem Unglück, das ihnen heute widerfahren ist, wird unsere Hilfe womöglich nur ein Tropfen auf den heißen Stein sein.\n\nDennoch - diese Leute benötigen dringend unsere Hilfe. Bezwingt ihre Peiniger!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29666] = {title = "Eine knifflige Lektion", objective = "Tötet 6 Wasserkneifer.", description = "In den Teichen lauern Gefahren. Die jüngste und wildeste davon sind die Wasserkneifer. Es ist an der Zeit, ihre Zahl auszudünnen, aber ich bin dazu nicht mehr imstande.\n\nFalls Ihr ein paar der Wasserkneifer beseitigen könntet, wäre ich Euch zu Dank verpflichtet. Passt aber auf ihre Anzahl auf - manchmal ist es besser, sie aus den Teichen herauszulocken, als geradewegs hineinzustapfen.", progress = nil, completion = "Die Wasserkneifer sind merkwürdige Kreaturen. Es scheint sie zu stillen Gewässern hinzuziehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29667] = {title = "Ausdünnung der Herde", objective = "A'dal bittet Euch, 6 mutierte Fleischpeitscher, 6 mutierte Furchtkreischer und 6 mutierte Schrecken zu töten und einen schnellentwickelnden Wedel von Laj in der Botanika der Festung der Stürme zu erbeuten.", description = "Anscheinend haben Kael'thas' Streitkräfte die Wesen der Botanika bis zur Unkenntlichkeit verändert. Ich will nicht, dass sie auf die Scherbenwelt losgelassen werden, wie so viele vor ihnen.\n\nEines dieser Wesen heißt Laj. Ihn würde ich gern untersuchen, denn er scheint irgendwie anders zu sein. Vielleicht können wir etwas von ihm lernen.", progress = "Wie ich sehe, habt Ihr den Wedel erbeutet. Sehr gut.", completion = "Ihr habt Euch tapfer geschlagen, &lt;Name&gt;. Allerdings muss ich Euch noch um die Erfüllung einer letzten Aufgabe bitten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29669] = {title = "Eine äußerst traurige Aufgabe", objective = "A'dal bittet Euch, Warpzweig in der Botanika in der Festung der Stürme zu töten.", description = "Ich muss Euch leider mit einer äußerst traurigen Aufgabe betrauen.\n\nWarpzweig war einmal der Wächter der ganzen Botanika. Doch nun ist er unrein und muss beseitigt werden.", progress = nil, completion = "Als er noch lebte, war er ein stattlicher Wächter. Wir werden ihn vermissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29670] = {title = "Tötet Gormal", objective = "Tötet Unterwerfer Gormal im Lager Gormal.", description = "Dank Euch versteckt sich eine aus Bauern bestehende Bürgerwehr in der Nähe. Hanae sagte etwas davon, ihnen \"flüssigen Mut\" zukommen zu lassen. Ich bin mir ziemlich sicher, dass sie jetzt betrunken und ZORNIG sind.\n\nDie Mogu glauben, sie könnten uns einfach überrollen - wir werden ihnen einen Kampf liefern, der ihnen die Augen öffnen wird.\n\nFolgt ihrer Spur durch die Ruinen und runter an den Strand. Findet ihren Anführer. Wenn Ihr ihn angreift, kommen wir dazu, um Euch zu helfen.", progress = nil, completion = "Das ist äußerst beunruhigend. Wenn sich die Mogu so wie hier auf dem ganzen Kontinent zusammenschließen, würde dies eine ernste Bedrohung für Pandaria darstellen.", rewards = "SeidenperlengötzeSpiegelschreiteremblemLaubtatzengötzeSprossen des LebensNebeljadegötzeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29674] = {title = "Unbändige Dunkelheit", objective = "A'dal hat Euch gebeten, Zereketh den Unabhängigen in der Arcatraz der Festung der Stürme zu töten.", description = "<Ihr hört klagendes Geläut in Eurem Kopf.>\n\nWir haben die gefährlichsten Wesen, die uns auf unseren Reisen untergekommen sind, eingesperrt.\n\nZereketh ist ein mächtiger Leerenfürst. Wenn es ihm gelingt, in den Nethersturm zu entkommen, wird er die reichlich vorhandene Leerenenergie in sich aufsaugen.", progress = nil, completion = "Die Wesen der Leere sind von Natur aus chaotisch. Als Bestandteil des Universums sind sie notwendig, doch sie müssen stets unter der Kontrolle des Lichts stehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29675] = {title = "Zorn und Verdammnis", objective = "A'dal bittet Euch, Zornseher Soccothrates und Dalliah die Verdammnisverkünderin in der Arcatraz der Festung der Stürme zu töten.", description = "Zornseher Soccothrates und Dalliah die Verdammnisverkünderin sind zwei mächtige Agenten der Brennenden Legion. Sie haben damit begonnen, Dämonen um sich zu versammeln.\n\nNoch ist die Armee klein, aber Ihr dürft nicht zulassen, dasss sie größer wird, sonst wird die Arcatraz bald zu einem weiteren Stützpunkt der Legion werden.", progress = nil, completion = "Der Legion geht es nur ums Verschlingen. Das Gleichgewicht der Kräfte interessiert sie nicht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29676] = {title = "Einen alten Freund finden", objective = "Sprecht mit dem alten Liang bei Liangs Refugium an den Singenden Teichen.", description = "Wie es scheint, hatte Shu, der Geist des Wassers, einen Spielgefährten, als er über die Jahre die Teiche besuchte. Es handelt sich um einen alten Pandaren, den wir den alten Liang nennen.\n\nLiang ist von der Hauptstadt fortgezogen und geht in den Teichen schon lange nicht mehr seinen Übungen nach. Man sagte mir, dass er in einem kleinen Haus nordöstlich von hier lebt, oben auf dem Hügel.\n\nLiang weiß vielleicht, was Shu vertrieben hat und wo wir den Geist finden könnten.\n\nGeht zu Liang und fragt nach Shu.", progress = nil, completion = "Besucher sind hier oben eine Seltenheit, aber Ihr seid willkommen. Es ist schön, Eure Bekanntschaft zu machen, junger &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29677] = {title = "Die Sonnenperle", objective = "Findet die Sonnenperle.", description = "Shu, der Geist des Wassers, ist ewig jung, genau wie alle anderen Geister Shen-zin Sus. Ich bin mein ganzes Leben lang mit Shu befreundet gewesen, aber ich bin nicht mehr in der Lage, mit ihm zu spielen. Ich bin alt und habe schlicht keine Kraft mehr.\n\nBei all seiner Vielschichtigkeit ist Shu im Grunde einfach zufriedenzustellen: Er sehnt sich nach Freundschaft. Immer wenn ich zurückgekehrt bin, um mit Shu zu spielen, habe ich ihm eine Sonnenperle als Geschenk mitgebracht. Dann haben wir miteinander gespielt. In den Teichen im Südosten könnt Ihr eine Sonnenperle finden. Wer weiß, vielleicht werdet Ihr ja <sein neuer Freund/seine neue Freundin>...", progress = "Die Entscheidung, nicht mehr zu den Teichen zurückzukehren, war eine schwere. Ich glaube, dass Shu sie nie wirklich verstanden hat. Er weiß nicht, wie es ist, alt und gebrechlich zu werden.", completion = "Shus Bedürfnisse sind den unseren nicht ganz unähnlich. Er möchte nicht allein sein - ungewollt, ungeliebt. Er sehnt sich danach, gebraucht zu werden und sein Leben mit anderen zu teilen.\n\nJetzt, wo Ihr dies wisst, sollte Euch klar sein, dass es nicht schwer sein sollte, sein Vertrauen zu gewinnen. Er sehnt sich einfach nur nach etwas Gesellschaft.", rewards = "SonnenperlenhandschuheSonnenperlenwesteSonnenperlenarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29678] = {title = "Shu, der Geist des Wassers", objective = "Überredet Shu, den Geist des Wassers, zu einem Spielchen.", description = "Shu, der Geist des Wassers, schmollt im tiefen Teich nördlich von hier vor sich hin. Überquert die Felsen und lasst dann die Sonnenperle in die Mitte des Teichs fallen. Er wird wissen, was das bedeutet.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29679] = {title = "Ein neuer Freund", objective = "Wasserwandelt in 5 von Shus Wasserfontänen.", description = "Er möchte, dass Ihr mit ihm spielt. Worauf wartet Ihr?", progress = nil, completion = "Ich muss schon zugeben, das sah von hier aus ziemlich lustig aus.\n\nUnd wie es aussieht, habt Ihr einen neuen Freund gewonnen!", rewards = "Verspielte HandgelenkbänderHandschuhe des spritzenden WassersGlänzende BrustplatteIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29680] = {title = "Unsere Lebensgrundlage", objective = "Sprecht mit Ji auf dem Dai-Lo-Bauernhof. Ein Karren wartet nahe der Straße, um Euch dorthin zu bringen.", description = "Wir haben getan, was Meister Shang von uns verlangt hat. Ich werde zum Tempel zurückkehren und ihm von unserem Fortschritt berichten. Ihr solltet Euch nach Süden begeben, um Wugou, den Geist der Erde, aufzusuchen.\n\nJi erwartet Euch am Dai-Lo-Bauernhof und wird sicherlich Eure Hilfe benötigen. Ich muss Euch warnen - Ji kann in all seiner Direktheit sehr unbedacht agieren. Erinnert Euch stets an das, was ich Euch gelehrt habe: Disziplin und Geduld.", progress = nil, completion = "&lt;Name&gt;! Ich hatte mich gefragt, wann wir uns wohl wiedersehen würden.\n\nNun, die gute Nachricht ist, dass Wugou, der Geist der Erde, ziemlich einfach zu finden war. Die schlechte ist, dass er einen wirklich tiefen Schlaf hat. Er wird wohl mit einem ziemlich steifen Nacken aufwachen nach all dem Geschiebe und Getrete, mit dem ich ihn schon zu wecken versucht habe.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nTrigger Spirit of Water at Farm\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29681] = {title = "Ausbruch aus dem Hochsicherheitstrakt", objective = "A'dal hat Euch gebeten, Herold Horizontiss in der Arcatraz der Festung der Stürme zu töten.", description = "Herold Horizontiss stellt das größte Problem in der Arcatraz dar.\n\nEr hat Aufseher Mellichar korrumpiert und dafür gesorgt, dass er zahlreiche Gefangene entlässt. Es ist nur eine Frage der Zeit, bis auch der Herold selbst freigelassen wird.\n\n<Name>, Ihr dürft einen Diener der Alten Götter nicht am Leben lassen!", progress = nil, completion = "Danke, &lt;Name&gt;. Mit Euren Taten habt Ihr zahllose Tragödien verhindert.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMächtiger Anhänger der Sha'tariA'dals Halskette der ErholungMachtvoller Halsreif von Shattrath\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][29682] = {title = "Terrasse der Magister", objective = "Hauptmann Theris Morgenheim möchte, dass Ihr Exarch Larethor in der Terrasse der Magister findet.", description = "Vor kurzem haben wir eine Expedition zur Terrasse der Magister geschickt, um die Streitkräfte der Legion aufzuhalten.\n\nAllerdings haben wir seitdem nichts mehr gehört, und ich befürchte das Schlimmste.\n\nWürdet Ihr dorthin gehen und versuchen, Exarch Larethor zu finden? Er leitet die Expedition.", progress = nil, completion = "Morgenheim hielt uns für tot? Ha!\n\nIch habe ihm keinen Bericht geschickt, weil wir noch nicht weiter als bis zu diesem Punkt gekommen sind.\n\nVielleicht können wir das ja mit Eurer Hilfe ändern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29684] = {title = "Abgerissene Kommunikation", objective = "Exarch Larethor in der Terrasse der Magister möchte, dass Ihr den Bluelfenspion Tyrith findet.", description = "Wir haben vor einiger Zeit einen Kontaktmann in der Terrasse der Magister eingeschleust, der für uns Informationen sammelt, aber der Kontakt zu ihm ist abgerissen.\n\nSein Wissen ist für unsere Mission essentiell.", progress = nil, completion = "...kommt näher, &lt;Volk&gt;... Hört mir aufmerksam zu...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29685] = {title = "Nicht totzukriegen", objective = "Kalecgos hat Euch damit beauftragt, Kael'thas in der Terrasse der Magister zu bezwingen. Ihr sollt Euch mit Kaels Kopf bei Larethor in der Terrasse der Magister melden.", description = "Wie Ihr mittlerweile wisst, arbeiten die Streitkräfte der Legion unermüdlich daran, die Kräfte des Sonnenbrunnens zu manipulieren, um so ihre eigenen unholden Machenschaften zu verwirklichen.\n\nKael'thas ist aus der Asche der Niederlage auferstanden und ist einmal mehr zu ihrem Anführer geworden. Er muss aufgehalten werden.", progress = "Nun ja, <Klasse>, ich muss gestehen, dass ich mir nicht sicher war, ob ich Euch jemals wiedersehen würde.", completion = "&lt;Larethor hört aufmerksam zu, als Ihr von Euren Heldentaten in der Terrasse der Magister berichtet.&gt;\n\nMan wird Tyrith vermissen. Er war ein guter Mann. Dank Euch war sein Tod nicht umsonst.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFeingeschliffener PurpurspinellGlänzender Purpurspinell\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][29686] = {title = "Eine radikale Idee", objective = "Exarch Larethor auf der Terrasse der Magister bittet Euch, Vexallus zu töten und seine Essenz an Euch zu bringen.", description = "Wir können es uns nicht leisten, diesen Krieg zu verlieren. Ich möchte unsere Wachen stärken, damit mutige Männer und Frauen nicht sterben müssen.\n\nDer Legion ist ein mächtiges Elementarwesen in die Klauen gefallen. Seine Essenz könnte genau das sein, was wir brauchen.", progress = "Habt Ihr seine Essenz bekommen?", completion = "Hervorragend! Ich freue mich darauf, dieses Projekt meinen Vorgesetzten zu zeigen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29687] = {title = "Dunkle Allianzen", objective = "Exarch Larethor in der Terrasse der Magister möchte, dass Ihr Selin Feuerherz und Priesterin Delrissa tötet.", description = "Die Legion arbeitet immer enger mit Kael'thas' Streitkräften zusammen. Das bereitet mir große Sorgen.\n\nSoweit wir wissen, sind vor allem Selin Feuerherz und Priesterin Delrissa mit der Vereinigung der beiden Armeen beschäftigt. Ihr müsst sie aufhalten.", progress = nil, completion = "Gut gemacht, Soldat. Ein Schritt nach dem anderen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29688] = {title = "Fortführung der Kampagne", objective = "Schattenjäger Ty'jin hat Euch gebeten, mit Steingardist Stok'ton in den Zerschmetterten Hallen der Höllenfeuerzitadelle zu sprechen.", description = "Ich höre meistens zu, <Klasse>. Ich höre zu, damit es der Kriegshäuptling nicht muss.\n\nIch habe gehört, wie es um unsere Kampagne gegen die Höllenfeuerzitadelle steht. Die Zeit zur Eroberung der Zerschmetterten Hallen, dem Machtzentrum der Höllenorcs, ist gekommen.\n\nSprecht mit Steingardist Stok'ton. Ihm unterstehen die Truppen dort.", progress = nil, completion = "Zieht den Kopf ein, sonst könnte er mit der falschen Seite eines Pfeils Bekanntschaft machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29689] = {title = "Fortführung der Kampagne", objective = "Truppenkommandant Danath Trollbann hat Euch gebeten, mit Vorhutsspäher Chadwick in den Zerschmetterten Hallen der Höllenfeuerzitadelle zu sprechen.", description = "Die Zeit ist reif für einen letzten Schlag gegen die Höllenorcs.\n\nVorhutsspäher Chadwick erwartet Euch in den Zerschmetterten Hallen der Höllenfeuerzitadelle. Beeilt Euch, ihre Streitkräfte können jeden Moment die Ehrenfeste angreifen!", progress = nil, completion = "Seid still! Wenn sie uns jetzt bemerken, werden sie uns überrennen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29690] = {title = "In den Nebel", objective = "Sprecht mit General Nazgrim auf Höllschreis Faust.", description = "<Nazgrim füllt seine Lunge mit Seeluft.>\n\nRiecht Ihr das, <Name>? Das ist der Geruch unserer Heimat; jenes Landes, für das unsere Leute geblutet und ihr Leben hingegeben haben.\n\nUnd horcht... Hört Ihr das? Das ist der Klang von Frieden und Sicherheit - von jener Zuflucht, die wir uns geschaffen haben und der sich unsere Feinde nicht zu nähern wagen.\n\nMerkt Euch diese Eindrücke, denn so bald werdet Ihr sie nicht wieder genießen. Es gilt, einen Krieg zu gewinnen.\n\nNun geht und macht Euch bereit. Wir brechen auf!", progress = nil, completion = "&lt;Name&gt;!?\n\nSie hatten mir berichtet, dass Ihr gefallen seid...\n\nEs freut mich zu sehen, dass dem nicht so war. Es gilt Allianztruppen zu töten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29691] = {title = "Bringt mir ein Gebüsch!", objective = "Sammelt 5 Bluthibisken und kehrt zu T'shu im Tiefensumpf zurück.", description = "Wir benutzen Bluthibiskus für viele Zwecke.\n\nNatürlich kommt er nur im Tiefensumpf vor und zahlreiche Bewohner haben Gefallen daran gefunden.\n\nIch wäre Euch sehr dankbar, wenn Ihr mir etwas davon bringen würdet.", progress = "Habt Ihr Hibiskus gefunden?", completion = "Sehr gut, aber wir können immer etwas davon gebrauchen. Vielleicht verschlägt es Euch ja bald noch einmal in den Tiefensumpf?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29692] = {title = "Bringt mir ein weiteres Gebüsch!", objective = "Wir könnten noch mehr Bluthibiskus gebrauchen. Ständig sind wir auf der Suche danach.\n\nBringt sie mir in Fünferbündeln, dann werde ich mich erkenntlich zeigen.", description = nil, progress = "Wir könnten noch mehr Bluthibiskus gebrauchen. Ständig sind wir auf der Suche danach.\n\nBringt sie mir in Fünferbündeln, dann werde ich mich erkenntlich zeigen.", completion = "Sehr gut, aber wir können immer etwas davon gebrauchen. Vielleicht verschlägt es Euch ja bald noch einmal in den Tiefensumpf?", rewards = nil}
MultiLanguageQuestData['de'][29693] = {title = "Die Axt des Generals", objective = "Bringt General Nazgrim seine Axt.\n\nBereitgestellter Gegenstand: \n", description = "Als Ihr langsam wieder zu Bewusstsein kommt und beginnt, Eure Umgebung wahrzunehmen, fällt Euch dieses Objekt unter den herumliegenden Wrackteilen auf.\n\nEuch dämmert, dass dies das erste Mal ist, dass Ihr Nazgrims Axt nicht in seinen Händen seht. Irgendwie macht das Eure knifflige Lage nur noch schlimmer...\n\nIhr wisst, dass der General seine Waffe wiederhaben wollen würde, sei er nun tot oder lebendig.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nNazgrim beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29694] = {title = "Neu formieren!", objective = "Rettet Schattenmeisterin Kiryn, Nieti Kuppelplopp, Shokia und Unteroffizier Gorrok aus der Honigtaulichtung.", description = "Sie haben eine Luftbasis! Diesen Allianzkapitän habe ich zum letzten Mal unterschätzt. So viele gute Krieger haben ihre Leben lassen müssen...\n\nEs muss ein paar Überlebende gegeben haben, die vor dem Absturz abspringen konnten. Wir brauchen alle fähigen Kämpfer, die wir bekommen können.\n\nFindet dort unten im Wald so viele Überlebende wie möglich, während ich das Wrack selbst durchsuche. Versammelt alle im nahegelegenen Dorf, damit wir zum Gegenschlag ausholen können.", progress = nil, completion = "Das sind alle Überlebenden, &lt;Name&gt;?\n\nSo sei es. Wir werden mit dem Blatt spielen, das das Schicksal uns zuteilt.\n\n\n\nVerdammt seien ihre Zahlen. So werden Helden gemacht.", rewards = "Schwelende KanonenbootstrebeZin'Juns ZwergentfernerGeplündertes RotorblattHo-zen-KlopferkolbenBordplanke des MarinesoldatenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29696] = {title = "Meine Sterne!", objective = "Sammelt 100 von Kiryns Wurfsternen von verschlagenen Waldgeistern.", description = "Einige von Kiryns Habseligkeiten wurden von Waldgeistern in der Gegend verteilt, aber dieser Gegenstand scheint Euch wichtig zu sein.\n\nDie Tasche hing einst an ihrer Taille und war gefüllt mit Wurfsternen. Ohne sie hat sie deutlich weniger Waffen zur Verfügung.\n\nWenn Ihr die Waffen von den Plagegeistern zurückholt, die in dieser Gegend hausen, würde Euch das sicherlich helfen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29715] = {title = "Die Hexe im Wald", objective = "Findet An Windpelz an der Straße nördlich der Hütte der Jadehexe.Oh bitte, <Volk>! Könnt Ihr mir helfen?\n\nEinige der Dorfkinder haben im Wald gespielt und sind nicht zurückgekehrt. Könntet Ihr bitte nach ihnen Ausschau halten, wenn Ihr dort hingeht?\n\nIch habe diesen Dorfrackern ausdrücklich gesagt, sie sollen die alte Witwe dort im Wald in Ruhe lassen. Ich vermute, dass sie sie wahrscheinlich belästigen. Sie glauben, dass sie eine Hexe ist.", description = "Oh bitte, <Volk>! Könnt Ihr mir helfen?\n\nEinige der Dorfkinder haben im Wald gespielt und sind nicht zurückgekehrt. Könntet Ihr bitte nach ihnen Ausschau halten, wenn Ihr dort hingeht?\n\nIch habe diesen Dorfrackern ausdrücklich gesagt, sie sollen die alte Witwe dort im Wald in Ruhe lassen. Ich vermute, dass sie sie wahrscheinlich belästigen. Sie glauben, dass sie eine Hexe ist.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][29716] = {title = "Die doppelte Ho-zen-Mutprobe", objective = "Rettet 6 verängstigte Pandarenkinder.", description = "In den Wäldern gibt es eine Hexe, aber niemand glaubt mir. Sie hat meinen Freund Shin in Jade verwandelt!\n\nWir hatten alle solche Angst und versuchten, nach Hause zu rennen, aber sie hat ihre großen Jademonster hinter uns hergeschickt. Ein paar von meinen Freunden versuchten, ihnen zu entkommen, indem sie auf Bäume kletterten.\n\nKönnt Ihr mir helfen, meine Freunde zu retten?", progress = nil, completion = "Oh, vielen Dank, dass Ihr geholfen habt, meine Freunde zu finden. Ich sehe Shin aber immer noch nicht...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29717] = {title = "Braves Kätzchen!", objective = "Vernichtet 8 Jadewächter.", description = "Ich habe versucht, einen der Jadetiger in den Wäldern zu bekämpfen, aber ich hatte zu viel Angst. Wenn sie einen anstarren, verwandelt man sich in eine Jadestatue!\n\nWirklich wahr! Ni, die Freundin von Chens Schwester, hat es von Kais Mutter erfahren.\n\nIch möchte auch so mutig sein wie Ihr. Könnt Ihr mir zeigen, wie man diese Jadetiger bekämpft?", progress = "Unglaublich! Ihr seid aber wirklich mutig!", completion = "Das war ja unglaublich! Ihr habt denen so *WUMM* eine reingehauen und die nur so *AAHHH* und schon waren die hin!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nMauzbandJadebrecherbandWindpelzbandWindpelzringAns Ring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][29722] = {title = "Eine Lektion in Sachen Mut", objective = "Besiegt 8 blättrige Trickster südlich der Hütte der Jadehexe.", description = "Könntet Ihr mir beibringen, auch so tapfer zu sein wie Ihr?\n\nAls wir der Hexe einen Streich gespielt haben, haben wir ein paar blättrige Trickster verärgert. Ich glaube, die Hexe hat irgendetwas mit ihnen angestellt.\n\nKönntet Ihr mir zeigen, wie man gegen die ankommt?", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][29723] = {title = "Die Jadehexe", objective = "Besiegt die Jadehexe.", description = "Ich glaube, die Jadehexe hält Shin immer noch gefangen.\n\nAber ich... Ich kann das nicht! Ich trau' mich nicht, zu der Hexe zu gehen. Könntet Ihr vielleicht mit ihr sprechen und nachsehen, ob sie Shin immer noch gefangen hält? Ihr seid doch schon erwachsen. Ich glaube, Euch würde sie nicht in Jade verwandeln.", progress = nil, completion = "Hurra! Ich danke Euch! Shin ist gerettet und Ihr habt die alte Hexe besiegt! Und das Beste ist, dass unsere Eltern nie erfahren werden, was wir gemacht haben. Hurra!\n\nIrgendwie scheinen alle, die zurückgekommen sind, zu versuchen, ihre ganze Jade loszuwerden. Toya hat alles gesammelt und gesagt, dass Ihr mit ihm sprechen sollt.", rewards = "Ihr bekommt:\n\nWaschbär aus Jade"}
MultiLanguageQuestData['de'][29725] = {title = "SI:7 Bericht: Feuer vom Himmel", objective = "Hört Euch Sullys Bericht an.", description = "Ja, wir haben Amber gefunden und sie ist am Leben und so. Aber das sind auch schon die einzigen guten Nachrichten.\n\nIch versuche mal, da weiterzumachen, wo der gute alte Rell aufhören musste...", progress = nil, completion = "So, jetzt wisst Ihr, was mit dem guten alten Rell passiert ist.\n\n&lt;Ihr bemerkt eine Änderung in Sullys Mimik und er wendet sich plötzlich ab. Ist es möglich, dass er... weint?&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29726] = {title = "SI:7 Bericht: Feindliche Eingeborene", objective = "Hört Euch Klein-Lus Bericht an.", description = "Ich... Ich kann Euch sagen, was als Nächstes passiert ist! Wir waren auf dem Weg nach Norden, in den Wald...", progress = nil, completion = "Glücklicherweise haben wir alle überlebt.\n\nNa ja... bis auf Söckchen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29727] = {title = "SI:7 Bericht: Keine Gefangenen", objective = "Hört Euch Amber Kearnens Bericht an.", description = "Die letzte Etappe unserer Reise brachte uns in den Westen, wo es ein großes Ho-zen-Dorf gibt. Wir hatten ein kleines Lager aufgeschlagen, außerhalb ihrer Sichtweite...", progress = nil, completion = "Und so war's. Wir konnten den Weißen Bauern nicht finden, aber wir haben Geheiminformationen erhalten, die für die Allianz vielleicht noch viel wichtiger sind.\n\nDie Horde hat sich mit den Ho-zen verbündet und stattet sie aktuell gerade mit Waffen aus. Zusammen mit ihrer Affenarmee sind sie uns gegenüber dreißigfach in der Überzahl.", rewards = "MondwasserringSchlangenwirbelbandBand des lauernden TigersRing der WiederherstellungBlühender RingIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29728] = {title = "Beweismittelvernichtung", objective = "Platziert 4 improvisierte Sprengladungen in der Nähe des Wracks der Herold. Die improvisierten Sprengladungen müssen mindestens 10 Meter voneinander entfernt liegen.", description = "Ich muss Euch um einen weiteren Einsatz bitten, <Name>.\n\nWir dürfen nicht zulassen, dass die persönlichen Dinge auf diesem Schiff in die falschen Hände fallen. Wir müssen es zerstören.\n\nAus den Überresten, die Ihr mir gebracht habt, habe ich ein paar improvisierte Sprengladungen zusammengestellt.\n\nBitte platziert diese Ladungen an einer beliebigen Stelle am Schiff. Aber achtet darauf, sie nicht zu dicht zusammenzulegen.\n\nSie sind ein wenig... öh... instabil. Im Falle einer vorzeitigen Explosion sollten sie also besser etwas verteilt sein.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29730] = {title = "Späherbericht: Feindliche Eingeborene", objective = "Hört Euch Rikos Bericht an.", description = "Ich glaub', ich kenne Eure erste Frage: \"Was zum Fiddel ist mit Unteroffizier Gorrok passiert?\" Aber keine Sorge. Der ist total am Leben. Gar nicht tot oder so.\n\n<Riko rutscht nervös hin und her.>\n\nAlso, wir GLAUBEN zumindest, dass er lebt. Aber er KÖNNTE AUCH ganz schön tot sein.\n\n<Riko schaut Euch erwartungsvoll an.>\n\nAlso gut! Ich werde Euch genau erzählen, was passiert ist.", progress = "Ich bin noch nicht fertig, verfiddelt nochmal!", completion = "So, wie Ihr also seht, trifft Riko keine Schuld.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29731] = {title = "Späherbericht: Auf der richtigen Fährte", objective = "Hört Euch Kiryns Bericht an.", description = "Das MEISTE, von dem, was Riko erzählt hat, ist wahr.\n\nWir haben uns nicht getraut, Gorrok zu verfolgen - die Horde verfügt nicht über ausreichend Truppen. Wir können auch nur eine bestimmte Anzahl Verluste kompensieren und ehrlich gesagt weiß ich nicht, wie mächtig diese Hexe ist.\n\nIch erzähle von da weiter, wo der Ho-zen aufgehört hat...", progress = nil, completion = "Und so haben wir unseren Allianzgefangenen gefunden.\n\nAber es ist noch viel mehr passiert. Noch sehr viel mehr...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29732] = {title = "Was runtergeht, muss wieder rauf!", objective = "Benutzt den Goblindrohnenspender an der Freigelegten Wurzel, um Vorräte zu bergen.\n\nHINWEIS: Für jede Benutzung ist ein Klippengleiterschwanz erforderlich.", description = "Nieti hat etwas hinterlassen, was sehr wichtig zu sein scheint. Auf dem Schaft steht \"Goblindrohnenspender\".\n\nNach einer kleinen Kalibrierung kann das Gerät Drohnen ins Basislager von Nazgrim entsenden.\n\nSo weit, so gut...\n\nEs gibt nur ein Problem: Die einzigen Vorratskisten, die einen Transport wert wären, sind nach dem Aufprall von der Klippe gefallen.\n\nAls Ihr darüber nachdenkt, seht Ihr im Augenwinkel den langen, zusammengerollten Schwanz eines vorbeifliegenden Klippengleiters...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29733] = {title = "SI:7 Bericht: Verloren im Wald", objective = "Hört Euch Rells Bericht an.", description = "<Rell hustet schwer, bevor er spricht.>\n\nIch bitte Euch, <Name>. Ihr müsst Euch anhören, was wir durchgemacht haben.\n\nDie gesamte verdammte Allianz sollte sich anhören, was wir durchgemacht haben. Es bleibt vielleicht nicht mehr viel Zeit.", progress = nil, completion = "...und so &lt;hust&gt; fanden wir...\n\n&lt;Rells Erzählung wird von einem Hustenanfall unterbrochen. Blut läuft ihm aus einem Mundwinkel.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29734] = {title = "Urahne Tiefenschmiede", objective = "Ich spüre das Feuer des Lebens in Euch, <Klasse>. Ich akzeptiere Eure Ehrerbietung! Nehmt dies als Zeichen meiner Dankbarkeit...", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der UrahnenRoter Glücksumschlag"}
MultiLanguageQuestData['de'][29735] = {title = "Urahne Steinsiegel", objective = "Ich spüre das Feuer des Lebens in Euch, <Klasse>. Ich akzeptiere Eure Ehrerbietung! Nehmt dies als Zeichen meiner Dankbarkeit...", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der UrahnenRoter Glücksumschlag"}
MultiLanguageQuestData['de'][29736] = {title = "Urahne Dunkelfeder", objective = "Euer Geist steckt voller Leben, junger <Klasse>. Ich freue mich über den Respekt, den Ihr mir zollt, und gebe Euch dies als Zeichen meiner Dankbarkeit.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der UrahnenRoter Glücksumschlag"}
MultiLanguageQuestData['de'][29737] = {title = "Urahne Feuerbart", objective = "Ich spüre das Feuer des Lebens in Euch, <Klasse>. Ich akzeptiere Eure Ehrerbietung! Nehmt dies als Zeichen meiner Dankbarkeit...", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der UrahnenRoter Glücksumschlag"}
MultiLanguageQuestData['de'][29738] = {title = "Urahne Mondlanze", objective = "Der Himmel, mit seinen unzähligen Sternen, bietet die Antworten auf alle irdenen Fragen, <Name>. Mag es sein, dass wenn der Weise und Glückliche zu ihnen aufblickt, er die tiefere Wahrheit findet?", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der UrahnenRoter Glücksumschlag"}
MultiLanguageQuestData['de'][29739] = {title = "Urahnin Windsang", objective = "Der Himmel, mit seinen unzähligen Sternen, bietet die Antworten auf alle irdenen Fragen, <Name>. Mag es sein, dass wenn der Weise und Glückliche zu ihnen aufblickt, er die tiefere Wahrheit findet?", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der UrahnenRoter Glücksumschlag"}
MultiLanguageQuestData['de'][29740] = {title = "Urahnin Immerschatten", objective = "Im endlosen Glitzern der Sterne verbergen sich die Antworten auf alle irdischen Mysterien, <Name>. Darf man dann nicht annehmen, dass der Weise und der Glückspilz beim Blick nach oben die Wahrheit entdecken könnten?", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der UrahnenRoter Glücksumschlag"}
MultiLanguageQuestData['de'][29741] = {title = "Urahne Sekhemi", objective = "Alle Tol'vir waren einst wie ich. Nun besteht mein Volk aus Fleisch und Blut und benötigt die Weisheit der Zeitalter mehr als je zuvor.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der UrahnenRoter Glücksumschlag"}
MultiLanguageQuestData['de'][29742] = {title = "Urahne Menkhaf", objective = "Alle Tol'vir waren einst wie ich. Nun ist mein Volk aus Fleisch und Blut und braucht die Weisheit der Zeitalter dringender als je zuvor.", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSelbstzwingen - Verbeugen\n\nIhr bekommt:\n\nMünze der UrahnenRoter Glücksumschlag"}
MultiLanguageQuestData['de'][29743] = {title = "Missgestalt", objective = "Erstellt Zeichnungen von jedem Einzelteil der antiken Statue.", description = "Die Statue und die sie umgebenden Ruinen sind eindeutig uralt. Dieses Land besitzt offenbar eine tiefgründige Geschichte. Das bedeutet, dass es nicht aus dem Kataklysmus entsprungen sein kann.\n\nDoch obwohl diese Gewässer nunmehr seit Ewigkeiten erforscht wurden, gibt es kein Anzeichen für etwas anderes als offene See.\n\nWenn Ihr die Einzelteile dieser zerbrochenen Statue zeichnen würdet, könntet Ihr vielleicht ein wenig Licht auf die Ursprünge dieses Kontinents werfen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29744] = {title = "Naturschutz", objective = "Untersucht die Wälder der Verlorenen, nordöstlich des Grünsteinbruchs.", description = "Waldgeister sind nicht für ihre Wanderlust bekannt, deswegen wundert es mich, dass sie sich bis zum Steinmetzviertel vorgewagt haben. Irgendetwas muss sie aus ihrem normalen Lebensraum vertreiben.\n\nDiese Geister leben eigentlich in den Wäldern der Verlorenen, gleich nördlich von hier. Ich würde ja selbst dorthin gehen, aber ich hörte, dass die Wälder verwunschen sein sollen.\n\nDas ist dann also nicht mehr drin.\n\nWir werden es wohl nie erfahren.\n\n<Weng hustet.>\n\nEs sei denn... es findet sich für diese Aufgabe <ein großer starker Abenteurer/eine große starke Abenteurerin> wie IHR! Was sagt Ihr dazu?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29745] = {title = "Die Misere der Geister", objective = "Schaltet 10 steingebundene Zerstörer in den Wäldern der Verlorenen aus und offenbart ihre Quelle.", description = "<Lebende Statuen wüten in den Wäldern.\n\nBis jetzt scheinen sie sich damit zufrieden zu geben, die Waldgeister in Stücke zu hauen, aber wenn sie so weitermachen, haben die Pandaren bald andere Sorgen als nur die verschwundene Jade.>Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29747] = {title = "Den Zyklus durchbrechen", objective = "Tötet 8 Shan'ze-Geisterbinder auf der Terrasse der Zehn Donner.", description = "<Mogubeschwörer rufen die unglückseligen Geister aus der Unterwelt herauf und sperren sie in diese Statuen ein.\n\nAnscheinend reicht es nicht aus, die Statuen zu zerstören, um diesen Kreislauf zu unterbrechen.>Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29748] = {title = "Simulakrumwerfen", objective = "Tretet 6 leere Zerstörer auf der Terrasse der Zehn Donner um.", description = "<Die geborstenen Überreste einer uralten Mogustatue. Sie sieht aus, als ob sie auch vor ihrer Zerstörung nie von Leben erfüllt war.\n\nWelche dunkle Magie die Mogu auch immer hier verwenden, sie scheint die brüchigen Statuen deutlich robuster zu machen. Wir sollten sie besser zerstören, solange sie leer sind und wir die Gelegenheit dazu haben.\n\nEin guter alter Tritt sollte dazu ausreichen.>Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29749] = {title = "Ein dringendes Anliegen", objective = "Bergt den Stab von Pei-Zhi und unterbrecht das Beschwörungsritual der Mogu im Zentrum der Terrasse der Zehn Donner.", description = "<Euer Verstand wird von einem Heulen erschüttert. Darunter vernehmt Ihr eine kaum wahrnehmbare Stimme, wie von weit her.>\n\nBitte... helft... inmitten der Ruinen... ein Ritual... beschwören...\n\n... sollte nicht hier sein...\n\nMein Stab... auf dem Altar... nehmt ihn. Bitte beeilt Euch.", progress = "Geistbindung! Wie konnte es den Mogu gestattet werden, mit solch widerwärtigen Praktiken fortzufahren?! Und jetzt steh' ich hier: Das Produkt einer halb gescheiterten Beschwörung...\n\n<Der Geist zürnt noch ein wenig vor sich hin und wendet sich dann Euch zu.>\n\nIn welchem Jahrhundert befinden wir uns?", completion = "Gestatten, Pei-Zhi, meines Zeichens Meistergeistweiser unter dem letzten Pandaren-Kaiser Shaohao.\n\nZumindest... war ich das einmal.", rewards = "Axt der OpferungGeisterquetscherBeschützer des GeisterweisenSchild des GeisterweisenGeistgebundene SichelGeistgebundene AxtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29750] = {title = "Geistergefäße", objective = "Sichert 8 Geisterflaschen von den Shan'ze-Geisterklauen auf der Terrasse der Zehn Donner.", description = "Die Geisterklauen sind eine Sekte von Moguassassinenpriestern, die zu den Hochzeiten des Mogureiches die gefürchtetste und hervorragendste Truppe des Reiches darstellten.\n\nAlle ihre Mitglieder vermochten, einen Todeshieb auszuführen, der den Geist des Feindes in eine Jadeflasche bannte, um ihn dann an einen Geisterbinder auszuliefern.\n\nWenn Ihr weiter oben in den Ruinen auf Geisterklauen stoßt, solltet Ihr Folgendes wissen: An ihren Gürteln sind die verfluchten Geistergefäße befestigt.\n\nBefreit sie von dieser Bürde und bringt die Flaschen zu mir zurück.", progress = "Dass die Mogu über all diese Jahre weiter die Geisterklauen ausgebildet haben...\n\nHabt Ihr die Flaschen?", completion = "Ich danke Euch, &lt;Klasse&gt;.\n\nIch kann bereits die Geister in diesen Flaschen spüren - ich höre ihre Schreie voller Angst, Verwirrung und... Zorn.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29751] = {title = "Ritualartefakte", objective = "Bringt Pei-Zhi eine gesprungene Ritualschale, eine geruchsintensive Ritualkerze und einen Jadecong von der Terrasse der Zehn Donner.", description = "So viele Geister werden hier in Gefangenschaft gehalten... Ich kann sie überall spüren. Selbst die Wände dienen als Käfig für die schon lange Verstorbenen.\n\n<Name>, wir können den Zauber, der über diesem Ort liegt, nicht einfach brechen. Denn dann würden zahllose gepeinigte Seelen ziellos umher irren. Sie brauchen ein Signal - etwas, das sie leitet.\n\nMit Eurer Hilfe könnte ich einen Tan-Chao erstellen: eine Brücke von dieser Welt in den Himmel. Für dieses Ritual benötige ich eine Schale, eine Kerze und einen Jadecong. Ihr solltet all diese Dinge in den Ruinen finden können.", progress = "Habt Ihr die Ritualgegenstände gefunden? Ohne sie können wir die Geister nicht zurückgeleiten.", completion = "Gut gemacht. Damit kann ich das Ritual abhalten und alle Geister hier, unter anderem mich selbst, dorthin zurückgeleiten, wo sie hingehören.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29752] = {title = "Die verirrten Seelen", objective = "Verwendet den Stab von Pei-Zhi, um 10 verirrte Urahnen auf der Terrasse der Zehn Donner einzufangen.", description = "Der Vorgang der Massenbeschwörung, wie hier von den Mogu abgehalten, hat auch unerwünschte Nebeneffekte. Einige der Geister kommen zu verstört oder unruhig hier an, um sich leiten zu lassen. Dann werden sie erst einmal isoliert, bis ihre Verzweiflung sie leichter beeinflussbar macht.\n\nIch vermute, dass die Mogu irgendwo einen solchen Isolationsbereich angelegt haben, der wahrscheinlich von Geisterklauen bewacht wird.\n\nBitte nehmt noch einmal meinen Stab und verwendet ihn, um diese verlorenen Seelen einzusammeln. Ihr müsst sie nicht bekämpfen. Zeigt ihnen einfach den Stab - damit sollten sie sich einfangen lassen.", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Ich werde sie mit mir in den Nether nehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29753] = {title = "Zurück zur Natur", objective = "Befreit 8 Tiergeister, indem Ihr die Geisterflaschen im Gezeitenblickdickicht auf den Boden werft.", description = "Ich muss Euch leider erneut um einen Gefallen bitten, <Name>.\n\nDie von Euch sichergestellten Flaschen enthalten weder die Geister von Urahnen der Mogu noch jene ihrer jüngst bezwungenen Feinde, sondern vielmehr die Seelen von Tieren. Offensichtlich haben die Geisterklauen auf Wilderei zurückgegriffen, um ihre Simulakren zu erwecken.\n\nLeider macht dies unsere Aufgabe komplizierter, da ich Tiere nicht mit durch den Tan-Chao nehmen kann.\n\nBringt diese Flaschen nach Westen in das Gezeitenblickdickicht und zerschlagt sie, damit die Tiere in die Natur zurückkehren können. Einige werden ganz sicher so zornig sein, dass Ihr sie erst beruhigen müsst.", progress = nil, completion = "Ihre Körper sind schon vor langer Zeit in ihre Heimat zurückgekehrt - jetzt können ihre Seelen ihnen folgen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29754] = {title = "Eine Verbindung zwischen Erde und Himmel", objective = "Beschützt Pei-Zhi während seines Rituals auf der Terrasse der Zehn Donner.", description = "Wir sind jetzt bereit, den Tan-Chao zu öffnen und die Seelen ihrem Frieden zuzuführen.\n\nEs wäre sehr freundlich, wenn Ihr mir noch einmal helfen könntet. Die Mogu werden sicher das Ritual bemerken und alles tun, um es aufzuhalten. Ich benötige nur ein paar Momente ungestörter Konzentration. Dann wird der Weg so weit geöffnet sein, dass er nicht mehr geschlossen werden kann.\n\nWenn Ihr mir noch einmal helfen möchtet, begleitet mich bitte zur Ritualstätte.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29755] = {title = "Ende der Pei-n", objective = "Bekämpft Shan Jitong und rettet Pei-Zhi am Sitz des Geistererweckers auf der Terrasse der Zehn Donner.", description = "<Die Geister der Urahnen strömen in den Tan-Chao, Pei-Zhis Brücke in die Freiheit.\n\nEine letzte Kammer befindet sich in den Ruinen gleich nördlich des Tan-Chao. Die Luft darüber vibriert vor schändlicher Energie. Shan Jitong hat sein Werk bereits begonnen.>", progress = nil, completion = "Dies muss ein Zeitalter großer Kämpfe sein, wenn es solche Helden wie Euch hervorbringt. Ich erwarte, dass große Abenteuer vor Euch liegen.\n\nEs war mir eine Ehre, Euch kennengelernt zu haben, &lt;Name&gt;.\n\nIch werde hier bleiben, bis die letzten Geister den Tan-Chao passiert haben und dann selbst hinübergehen.\n\nAber der Todesfluch des Geistererweckers macht mir immer noch Sorgen...\n\n\"Ihr werdet den Donner nicht besiegen können.\"\n\nWas kann er damit gemeint haben?", rewards = "NebelbernmantelungSchwarzdickichtschiftungJadehexenschiftungGlasseeschiftungSeidenwaldamiciaTiefenwaldschiftungFuchswäldchenschiftungDonnerholzschulternJadetigerschulternIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29756] = {title = "Ein bescheidenes Opferangebot", objective = "Sammelt 10 Gezeitennebelkappen im Gezeitenblickdickicht ein.", description = "Ich bin fast bereit für das Ritual - wir benötigen nur noch eine einzige Sache. Eine Opfergabe.\n\nKeine Sorge, ich meine kein Blutopfer. Nur etwas Nahrung.\n\nIm Gezeitenblickdickicht im Nordwesten wachsen ganz sicher ein paar Pilze, die sich dafür eignen. Bitte bringt mir einige davon.", progress = "Selbst Tote haben Hunger.", completion = "Ich danke Euch, &lt;Name&gt;. Diese Pilze machen als Opfergabe vielleicht nicht viel her, aber die Erinnerung an sie wird ausreichen, die Geister anzulocken.\n\nAußerdem schmecken sie gebraten ganz köstlich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29757] = {title = "Trötenkröten", objective = "Holt Kröteneier von 8 Blasen gurgelndem Froschlaich aus dem oberen Bereich der Teiche der Reinheit.", description = "Habt Ihr von den Problemen bei den Teichen gehört?\n\nDie Kröten dort vermehren sich wie verrückt! Das ist zu einem echten Problem für die Lotusbauern geworden.\n\nZufälligerweise stelle ich eine Marmelade aus gallertartigem Froschlaich her. Ich nenne sie \"Trötenkröten\" und sie kommt bei der Jugend hier sehr gut an. Ich kann die nicht lange auf Lager halten.\n\nWenn Ihr zu den Teichen unterwegs seid, könntet Ihr allen einen Gefallen tun, indem Ihr einige dieser Kröteneier, ähm... befreit.\n\nUnd in diese Flasche befördert. Für mich.\n\nHaltet einfach nach Blasen Ausschau und schöpft daraus!", progress = nil, completion = "Wenn die Kinder mich jetzt fragen: \"Habt Ihr Trötenkröten?\" - Dann kann ich mit JA antworten!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29758] = {title = "Ein schöner Rücken kann entzücken", objective = "Bringt Kroshs Rücken zu Yan in Neu-Cifera.\n\nBereitgestellter Gegenstand: \n", description = "<Der Panzer dieser Drachenschildkröte ist hart wie Stein und tief zerfurcht. Einer der Einheimischen kann damit bestimmt etwas anfangen.>", progress = nil, completion = "Jetzt schaut Euch DAS an! Was für ein wunderschöner Panzer!\n\nGut, dass Ihr ihn zu mir gebracht habt. Er ist ideal für einen fantastischen Servierteller.\n\nBitte, nehmt dies als Dank für Eure Mühen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29759] = {title = "Kung Din", objective = "Holt Euch den Schlingschwanzschlüssel, indem Ihr Kung Din tötet.", description = "Ich hoffe, Ihr seid dieser nächsten Aufgabe gewachsen, denn unsere Leben hängen davon ab.\n\nEs gibt nur einen Schlüssel, um uns von unseren Ketten zu befreien. Und leider hängt dieser Schlüssel um den Hals des Haustigers der Ho-zen, Kung Din.\n\nSie halten den Tiger in der großen Grube im Norden. Um den Schlüssel zu erhalten, muss man den Tiger allerdings töten.", progress = "Habt Ihr ihn gefunden?", completion = "Ja, mit diesem Schlüssel kann ich uns von unseren Ketten befreien.\n\nIhr habt uns von diesem widerwärtigen Ort erlöst.", rewards = "Lederstiefel der LandungKettenstiefel der LandungSeidene Treter der LandungSatintreter der LandungMokassins der LandungSabatons der LandungBrünierte Schienbeinschützer der LandungKriegsstiefel der LandungPlattenstiefel der LandungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29760] = {title = "Grubenkämpfer", objective = "Sprecht mit Korgol Schädelquetscher auf dem Dunkelmond-Jahrmarkt.\n\nBereitgestellter Gegenstand: \n", description = "Um ein meisterhafter Grubenkämpfer zu werden, muss man sicherlich noch mehr machen...\n\nVielleicht weiß Korgol Schädelquetscher, der die Todesgrube des Dunkelmond-Jahrmarkts auf dem Dunkelmond-Jahrmarkt leitet, mehr.", progress = nil, completion = "Schön, Euch zu sehen, &lt;Klasse&gt;.\n\nEin Schmuckstück reicht nicht, um ein meisterhafter Grubenkämpfer zu werden.\n\nEs ist an der Zeit, dass Ihr beweist, was in Euch steckt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29761] = {title = "Meisterhafter Grubenkämpfer", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMeisterhafter Grubenkämpfer"}
MultiLanguageQuestData['de'][29762] = {title = "Familienandenken", objective = "Sammelt 8 Perlflossenerbstücke von den toten Perlflossendorfbewohnern in der Mondwasserzuflucht ein.", description = "Wir haben vor Kurzem eine harte Schlacht gegen die Ho-zen in der Mondwasserzuflucht verloren.\n\nWir haben so viele Leute rausgeholt wie nur irgend möglich, aber dennoch haben viele von uns dort ihr Leben gelassen.\n\nWir haben keine Andenken an die Toten für unsere Gebete.\n\nWenn jemand ein paar Andenken von den Toten nehmen könnte, könnten wir sie in Frieden gehen lassen und mit dem Leben fortfahren.\n\nEs würde uns wirklich viel bedeuten, wenn Ihr das tun könntet, <Name>.", progress = "Wir trauern immer noch um unsere gefallenen Brüder.", completion = "Ich danke Euch, &lt;Name&gt;. Ihr könnt Euch gar nicht vorstellen, wie viel dies den Familien der Toten bedeutet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29763] = {title = "Raubt ihnen den Donner", objective = "Verteidiger Mordun hat Euch gebeten, ihm den Kopf von Ingvar dem Brandschatzer zu bringen.", description = "Die Vrykul kennen keine Angst. Sie scheinen sich sogar nach einem Tod in der Schlacht zu sehnen. Sie sind so zahlreich und werfen sich mit solcher Macht in den Kampf, dass wir nichts gegen sie ausrichten können.\n\nEs gibt jedoch einen, den sie verehren. Sein Name ist Ingvar. Wenn Ihr ihn töten könntet, würde das ihre Kampfeslust deutlich bremsen.", progress = "Schön zu sehen, dass es Euch gut geht, <Name>.\n\nWeitere Verluste könnten wir nicht verkraften.", completion = "Hervorragend!\n\nDas könnte der Durchbruch sein, auf den wir gehofft haben.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBand des HenkersRing der DezimierungSignet des schnellen Richturteils\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][29764] = {title = "Abrüstung", objective = "Verteidiger Mordun möchte, dass Ihr 5 Waffen der Vrykul stehlt.", description = "Ihr könnt mir glauben, <Kamerad/Fräulein>, diese Vrykulwaffen sind verdammt unangenehm! Trügerisch gut ausbalanciert, brutal scharf - absolut tödlich.\n\nKlaut mir ein paar davon, bevor sie gegen uns eingesetzt werden.", progress = "Habt Ihr ein paar Äxte der Vrykul geklaut?", completion = "&lt;Mordun pfeift.&gt;\n\nSeht Euch die nur mal an! Unglaublich.\n\nIch hatte eigentlich erwartet, dass diese Steinzeitmenschen mit Knüppeln herumfuchteln und Steine werfen.\n\nLeider nicht...", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAmulett des ruhigen GemütsRasierklingenanhängerHalskette des gestreuten LichtsGewebte Stahlhalskette\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][29765] = {title = "Ich heul' mir die Augen aus", objective = "Nehmt den Ho-zen-Wutschäumern Zin'Juns Sachen wieder ab.\n\nWenn Ihr Zin'Jun verliert, sprecht mit ihm am Aufstieg der Wirbelnden Winde.", description = "Ich hätt' die Schweine fertigmach'n können, Mann!\n\nIhnen alle eine reinschieß'n und mich dann totstell'n, wenn sie näherkomm'n! Hab'n die sonst ja auch nie kapiert.\n\nAber einer von denen hat den Trick jetzt doch kapiert... Und dann sind die alle auf mich rauf und hab'n mit meinen Augen Murmeln gespielt.\n\nHab'n meine Sachen genommen und mich hier zum Sterb'n einfach liegengelass'n, diese Wilden...\n\nDu musst mir helf'n, Mann. Lass' mich nich' so würdelos sterb'n.", progress = "Hast du meine Sachen, Mann?", completion = "&lt;Zin'Jun schluchzt... Glaubt Ihr jedenfalls.&gt;\n\nDie hab'n Schnuff umgebracht...\n\nWas hat Schnuff denen denn getan?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29766] = {title = "Ein guter Start", objective = "Tötet 4 Ho-zen-Schlickschleuderer, 4 Ho-zen-Schädelbrecher und 3 Ho-zen-Fischfänger.", description = "Unabhängig von unserer misslichen Lage sind unsere Befehle klar. Wir sind hier, um das Land zu erkunden und es für Höllschreis Flotte vorzubereiten.\n\nAber zuerst müssen wir mit diesen Wilden fertigwerden!\n\nSeht Ihr die Leichen, die ich um das Lager herum aufgestapelt habe? Ich will ganze Berge davon sehen!\n\nWir sind immer noch die Horde!\n\nDiese Maden haben noch nicht gelernt, uns zu fürchten, aber das wird sich schon bald ändern...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29767] = {title = "Fischimbiss", objective = "Nehmt den Ho-zu-Fischfängern 12 ausgewachsene Karpfen ab.", description = "Das Glück belohnt die Mutigen!\n\nEure kühl kalkulierten Angriffe haben unerwartete Wirkung gezeigt. Wenn Ihr diese Fischfänger töten könnt, nachdem sie einen guten Fang gemacht haben, könnt Ihr ihnen ihre fischige Beute abnehmen.\n\nDie Feinde ausdünnen und die Verbündeten nähren - das nenne ich Effizienz!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29768] = {title = "Der fehlende Schlägel", objective = "Beschafft den Dai-Lo-Pausenhammer bei der Brauerei Ki-Han.", description = "<Name>, ich hab's! Es ist eigentlich ganz simpel. Wir müssen einfach so viel Rabatz machen, dass er keine Chance hat, davor die Ohren zu verschließen.\n\nSieh mal einer an, dieser Gong hier steht aber genau am rechten Fleck! Wenn ich mich nicht irre, dann haben sie ihn bisher wohl auf genau diese Weise aufgeweckt. Wir brauchen nur den passenden Schlägel, damit der Gong so laut wie möglich wird.\n\nDer Dorfvorsteher hat mir erzählt, dass sich der Schlägel bei der Brauerei Ki-Han am Fluss südwestlich von hier befindet. Es ist nicht weit. Macht es Euch etwas aus, ihn für mich abzuholen, während ich hier das Dorf vorwarne?", progress = "Nun, sie sind gewarnt, dass es gewarnter nicht mehr geht. Habt Ihr den Schlägel?", completion = "Ha, &lt;Name&gt;! Das nenne ich einen Schlägel. Dann wollen wir mal auf die Pauke - oder eher den Gong - hauen!", rewards = "SeidenschuheSommerschuheTanzstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29769] = {title = "Strolche!", objective = "Tötet 10 Shed-Ling.", description = "Ich suche weiter nach Möglichkeiten, diesen hartnäckigen Tiefschläfer hier aufzuwecken, aber auf dieser Insel lauert einfach an jeder Ecke ein neues Ärgernis. Die komplette Vegetation ist mit Shed-Ling verseucht, hasenartigen Dieben und Plünderern.\n\nDiese Strolche!\n\nSie vermehren sich schneller, als wir sie töten können! Aber ich habe genau die richtige Lösung für ein Problem wie dieses: Tötet sie schneller! Jetzt, da Ihr hier seid, sollte das ja kein Problem mehr sein, oder was sagt Ihr, <Name>?", progress = nil, completion = "So wird das gemacht, &lt;Name&gt;! Ihr taucht auf und Probleme lösen sich fast wie von selbst. Das ist nur einer der vielen Gründe, warum ich Euch mag!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29770] = {title = "Noch essbar", objective = "Beschafft 3 ausgegrabene Rüben, 3 gestohlene Karotten und 3 stibitzte Kürbisse wieder.", description = "Die Shed-Ling sind mit einem Großteil der Ernte davongerannt, aber sie haben sich mehr geschnappt, als sie essen können. Sie müssen ihre Beute irgendwo lagern - zumindest den Teil davon, den sie mögen.\n\nKönntet Ihr Euch auf die Suche machen und die Feldfrüchte zurückbringen? Ich habe hier eine ganze Insel zu versorgen und jedes bisschen Gemüse hilft mir dabei.", progress = "Seit Wugou, der Geist der Erde, eingeschlafen ist, ist der Boden trockener geworden und es wird immer schwerer, neue Saat zum Sprießen zu bringen. Wir müssen so viele Lebensmittel wie möglich horten - ansonsten wird der Insel eine harte Zeit bevorstehen.", completion = "Einige hiervon sind ja angebissen! Ach, was soll's... Wir finden schon einen Verwendungszweck.\n\nVielen Dank für Eure Hilfe!", rewards = "Handgemachte GamaschenWeiche KniehosenBequeme SchienbeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29771] = {title = "Härter als Holz", objective = "Sammelt 12 weggeworfene Holzbretter.", description = "Besorgt mir ein paar Holzbretter von der Baustelle in der Nähe der Brauerei Ki-Han.\n\nIhr kennt die Größe meiner Stärke noch nicht, daher werde ich sie Euch demonstrieren.", progress = "Habt Ihr erledigt, was ich Euch aufgetragen hatte?", completion = "Gut.\n\nMein Kopf ist härter als das härteste Holz.\n\nTretet zurück und lasst mich Eure Zweifel zerstreuen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nStapel Holzbretter beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29772] = {title = "Rabatz", objective = "Schlagt den Gong.", description = "Seid Ihr bereit, <Name>? Ich glaube, dass wir uns besser etwas besorgt hätten, das wir uns in die Ohren stopfen könnten, aber dafür ist es jetzt ein bisschen zu spät. Denkt einfach immer daran, dass das fiepende Geräusch, dass Ihr für die nächsten paar Stunden hören werdet, das Fiepen des Sieges ist!\n\nDie Ehre gebührt Euch, <Name>. Schlagt den Gong, sobald Ihr bereit seid!", progress = nil, completion = "Hmm... Nun, das ist definitiv das Fiepen, dass ich befürchtet hatte, aber ich hatte mir etwas mehr Reaktion von Wugou erhofft. Dieser Kerl schläft wirklich tief, so viel ist sicher.\n\nDas ist schon in Ordnung, &lt;Name&gt;. Ich habe noch eine andere Idee, für die wir kaum etwas vorbereiten müssen. Genau, wie ich es mag.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29774] = {title = "Nicht ins Gesicht!", objective = "Erbittet Shus Hilfe, um Wugou aufzuwecken, den Geist der Erde.", description = "Nun gut, <Name> - ich hatte mir schon Gedanken darüber gemacht, was wir wohl probieren könnten, falls die Idee mit dem Gong nicht funktionieren würde, und es ist mir einfach so eingefallen! Ein Schwall kaltes Wasser ins Gesicht macht mich immer hellwach! Und bei jemandem, der so trocken und erdig ist, muss das gleich den doppelten Effekt haben!\n\nKönntet Ihr Shu, den Geist des Wassers, vielleicht darum bitten, uns auszuhelfen? Er sollte in dem Teich neben dem Wasserfall auf der anderen Seite des Baumes spielen.", progress = nil, completion = "JUHU! &lt;Name&gt;, wir sind schon ein tolles Team. Wie ich immer zu sagen pflege: Hartnäckigkeit ist besser als Planung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29775] = {title = "Körper und Geist von Shen-zin Su", objective = "Bringt Shu und Wugou, die Geister des Wassers und der Erde, zum Tempel der Fünf Sonnenaufgänge. An der Straße steht ein Wagen, der Euch dorthin bringen wird.", description = "So, damit wären wir hier fertig, oder nicht? Nun, da diese beiden hier Euch liebgewonnen haben, müssen wir sie nur noch zum Tempel der Fünf Sonnenaufgänge zurückbringen.\n\nGeht ruhig schon vor. Ich verabschiede mich hier noch und komme dann nach.", progress = nil, completion = "Ihr habt Euch sehr gut geschlagen, mein junger Schüler. Drei der vier Geister sind in den Tempel zurückgekehrt. Wir sind den Antworten, die wir suchen, ein bedeutendes Stück näher.", rewards = "Roben des WassergeistesBindungen des ErdgeistesStulpen der Erde und des WassersDer folgende Zauber wird auf euch gewirkt:\n\nSummon Earth Central Temple Turn-in Controller\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29776] = {title = "Morgenhauch", objective = "Trefft Ji Feuerpfote in Morgenhauch.", description = "Der vierte und letzte Geist ist Dafeng, der Geist des Windes. Wenn er sich gerade nicht durch die Himmel schwingt, hält er sich auf dem Grat der Lachenden Winde westlich von hier auf. Ich habe sowohl Aysa als auch Ji dorthin geschickt, um Euch bei der Suche zu helfen.\n\nWenn Ihr bereit seid, werde ich helfende Winde beschwören, die Euch zur Spitze des Tempels tragen werden. Von dort aus müsst Ihr die Brücken nach Westen überqueren, um Ji in Morgenhauch zu treffen.", progress = nil, completion = "&lt;Name&gt;, lasst Euch umarmen! Diesmal waren wir ja nicht allzu lang getrennt - gut so!\n\nIhr habt mit Aysa zusammengearbeitet, oder? Unsere verschiedenen Überzeugungen haben uns lange Zeit voneinander ferngehalten, deshalb weiß ich nur wenig über sie. Aber jetzt, da ich sie ihre Rituale durchführen sehe, muss ich zugeben, dass sie mit ihrer Anmut und Disziplin einen seltsam verlockenden Eindruck auf mich macht.\n\nAber wir sollten unsere Gedanken dringenderen Angelegenheiten zuwenden, denkt ihr nicht? &lt;Name&gt;, nehmen wir uns dieses Affenproblems an, während wir nach Dafeng suchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29777] = {title = "Die Werkzeuge des Feindes", objective = "Beschafft 8 farbgetränkte Pinsel wieder.", description = "Die Ho-zen haben unsere Pinsel gestohlen und beschmieren unsere Schriftrollen mit ihren eigenen \"Weisheiten\"... wenn man das so nennen darf. Falls Ihr hier seid, um zu helfen, dann haltet sie auf und bringt uns unsere Pinsel zurück, bevor sie noch mehr Schaden anrichten können!", progress = "Ich möchte die Ho-zen nicht für ihre Ambitionen verunglimpfen - jedes Volk muss seinen eigenen Weg gehen. Was diesen Vorfall betrifft, gefährden sie aber unser Leben und unsere Kultur. Das können wir nicht zulassen", completion = "Ich bin Euch zu Dank verpflichtet, junger &lt;Klasse&gt;. Schon bald werde ich mit der mühseligen Arbeit beginnen, unsere Weisheiten erneut niederzuschreiben, damit die Schriftrollen wieder aufgehängt werden können, um nachfolgende Generationen zu leiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29778] = {title = "Umgeschriebene Weisheiten", objective = "Verbrennt 5 verschandelte Rollen der Weisheit.", description = "<Name>, wir müssen dem Ältesten Shaopai helfen. Es gibt nur wenige, die unsere Güte mehr verdient hätten als er.\n\nAuf dem Weg hierher sind Euch bestimmt die Schriftrollen aufgefallen, die in der Grotte im Süden hängen. Die Ho-zen haben viele davon besudelt und leider kann der Schaden nicht rückgängig gemacht werden. Wir werden uns des Problems auf direkte Art annehmen - indem wir die Schriftrollen zusammen mit den Schmierereien der Ho-zen vernichten.\n\nSorgt Euch nicht um Shaopai. Die Leute werden zusammenkommen und ihm dabei helfen, die Weisheiten erneut niederzuschreiben. Dafür werde ich sorgen.", progress = nil, completion = "Ihr seid herzensgut, &lt;Name&gt;. Ihr beweist das stets aufs Neue und ich bin froh, an Eurer Seite stehen zu dürfen.", rewards = "Handschuhe der WeisheitHandschuhe der WahrheitUnlackierte UnterarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29779] = {title = "Der direkte Weg", objective = "Tötet 20 Ho-zen in Fe-Feng.", description = "Jetzt reicht's, <Name>. Das ist das zweite Mal, dass wir uns mit plündernden Ho-zen herumschlagen mussten. Es ist an der Zeit, dass wir uns um das Problem kümmern - auf die Huojin-Art. Kein Abwarten mehr. Keine Meditation. Wir werden das Übel bei der Wurzel packen.\n\nWir gehen direkt ins Ho-zen-Dorf im Norden und bestrafen diese stinkenden Unruhestifter. Ich hatte mich schon darauf gefreut, endlich wieder an Eurer Seite kämpfen zu dürfen, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29780] = {title = "Kein Unrecht tun", objective = "Tötet Ruk-Ruk, den Häuptling von Fe-Feng.", description = "<Name>, Ihr müsst verstehen, dass der Weg der Huojin keineswegs der Weg der Gewalt ist. Wenn wir kämpfen müssen, zögern wir keinen Moment, aber wenn wir nicht kämpfen müssen, werden wir auch keinen Kampf anzetteln. Allerdings ist es oft der direkteste Weg, der Schlange den Kopf abzuschlagen, wie es so schön heißt.\n\nDie Ho-zen haben einen Anführer, der all diese Angriffe auf unsere Siedlungen anzettelt. Wenn wir Ruk-Ruk aus dem Spiel nehmen, müssen wir nicht alle Ho-zen ausrotten, um die Angriffe zu stoppen.\n\nIch weiß, dass Ihr kein Anhänger der Huojin seid, <Name>, aber Ihr werdet mir sicher dabei helfen, das zu tun, was getan werden muss, oder?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Schwert der Ho-zenDolch der Ho-zenStab der Ho-zenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29781] = {title = "Für Affen unzugänglich aufbewahren", objective = "Beschafft 8 gestohlene Feuerwerksbündel wieder.", description = "Die Affen haben sich bei ihren Angriffen auf das Dorf etliches unter den Nagel gerissen. Wir sollten den Verlust einiger Proviantpakete verkraften können, aber bei dem Gedanken an Affen mit Feuerwerkskörpern wird mir ein wenig flau im Magen. Außerdem weiß man ja nie, wann wir selbst einmal ein paar Raketen benötigen, nicht wahr?\n\nHelft mir, die gestohlenen Feuerwerkskörper aus ihrem Dorf zurückzuholen, <Name>!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29782] = {title = "Härter als Knochen", objective = "Bringt die Säule des Jadetigers zu Jojo Eisenstirn in Morgenhauch.\n\nBereitgestellter Gegenstand: \n", description = "Diese große Säule des Jadetigers scheint unter all diesen Ho-zen-Gebäuden fehl am Platz zu sein.\n\nSie macht aber auch einen sehr harten Eindruck. Wirklich sehr hart.\n\nIhr wisst genau, wer sich dafür interessieren dürfte.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "JadeschildJadearmbrustSchwert mit JadegriffDolch mit JadegriffDer folgende Zauber wird auf euch gewirkt:\n\nSummon Tiger Stand\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29783] = {title = "Härter als Stein", objective = "Sammelt 12 herrenlose Steinblöcke.", description = "Sammelt ein paar Steinblöcke beim Grat der Lachenden Winde im Süden für mich.\n\nIhr konntet Euch nun schon zweimal von meiner Stärke überzeugen, doch Euer Blick verrät mir, dass Ihr immer noch zweifelt... aber nicht mehr lange.", progress = "Die Stärke des Körpers kann ohne die Stärke des Geistes nicht existieren.", completion = "Gut.\n\nMein Kopf ist härter als der härteste Stein.\n\nTretet zurück und lasst mich Eure Zweifel zerstreuen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nStapel Steinblöcke beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29784] = {title = "Im Gleichgewicht", objective = "Balanciert über die Seile und sprecht mit Aysa Wolkensänger auf dem Morgenhauchsee.", description = "Aysa hat auf dem See meditiert, seit wir hier angekommen sind. All ihre Gedanken sind auf Dafeng gerichtet. Ich weiß nicht, was sie sich dort draußen zu finden erhofft, aber sie ist kein Dummkopf und Meister Shang Xi persönlich hat sie mit dieser Aufgabe betraut.\n\nIhr werdet über die Seile, die am Ende des Docks festgemacht sind, zu ihr gelangen müssen. Das wird Eure Balance auf die Probe stellen, aber ich denke, dass Ihr der Herausforderung gewachsen seid.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29785] = {title = "Dafeng, der Geist des Windes", objective = "Sprecht mit Dafeng, dem Geist der Luft, in der Kammer des Raunens.", description = "Wenn Ihr nur lang genug zuhört, wird der Wind Euch die Antwort zutragen.\n\nDafeng, der Geist der Luft, hat den Himmel aus Furcht vor der Onyxschlange Zhao-Ren verlassen. Er versteckt sich in der Kammer des Raunens an der Südseite des Plateaus.\n\nGeht zu ihm. Ji und ich werden dort zu Euch stoßen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29786] = {title = "Schlacht um den Himmel", objective = "Besiegt die Onyxschlange Zhao-Ren mithilfe von Jis Feuerwerk.", description = "Dafeng, der Geist der Luft, hat furchtbare Angst vor der Onyxschlange Zhao-Ren, <Klasse>. Wir müssen ihm helfen, sich seiner Angst zu stellen, oder ihr an seiner statt gegenübertreten.\n\nAls ich Ji von der Schlange erzählt habe, sagte er, er habe eine Idee. Er wollte außerhalb der Kammer mit den Vorbereitungen beginnen. Ich muss zugeben, dass ich ihn trotz seiner unbesonnenen Art um seine Leidenschaft und Überzeugung beneide.\n\nLasst uns nach draußen gehen, um uns der Onyxschlange zu stellen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nUmhang der feurigen Himmel"}
MultiLanguageQuestData['de'][29787] = {title = "Beweis der Würdigkeit", objective = "Besiegt den Wächter der Ältesten.", description = "Die vier Elementargeister werden Euch dabei helfen, mit dem Land zu sprechen und herauszufinden, woran es leidet, aber vorher habe ich noch eine kleine Aufgabe für Euch.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29788] = {title = "Unschöne Natur", objective = "Tötet 8 Dornzweigstrolche.", description = "Ihr hattet es schon einmal mit Waldgeistern im Tal des Anbrechenden Morgens zu tun, aber die Waldgeister in diesem Gehölz sind von einer komplett anderen Sorte. Gemeiner und gefährlicher.\n\nFalls Ihr ein paar dieser Wichte beseitigen könntet, wären die Elementargeister Euch dankbar.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29789] = {title = "Klein, aber wichtig", objective = "Sammelt 8 Kun-Pai-Ritualtalismane.", description = "Ich bin müde, <Name>. Ich muss mich ausruhen.\n\nWir müssen ein Ritual durchführen, aber wir benötigen einige der Talismane aus diesem Gehölz. Wenn Ihr es durchsucht, solltet Ihr sie überall von den Bäumen hängen sehen.\n\nIch nehme an, dass es einem jungen Hüpfer wie Euch nichts ausmacht, wenn ich mich hier hinsetze und ein wenig ausruhe, während Ihr die Talismane sammelt?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29790] = {title = "Weisheit überliefern", objective = "Hört Meister Shang Xi zu.", description = "Ihr werdet Eure Reise schon bald ohne mich fortsetzen müssen. Bleibt ein Weilchen und lauscht den Worten eines alten Mannes. Mein Wissen soll als Fundament des Euren dienen, sodass Ihr zu einem größeren Helden werden könnt, als ich es jemals war.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Kordel der TrauerSeile der TrauerSattelgurt der TrauerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29791] = {title = "Das Leiden von Shen-zin Su", objective = "Steigt in den Heißluftballon ein und sprecht mit Shen-zin Su.", description = "Die Zeit der Trauer wird noch kommen. Aber der Ballon steht bereit und Shen-zin Su erwartet uns.\n\nWir werden die ersten Pandaren sein, die nach Hunderten von Jahren wieder mit Shen-zin Su sprechen dürfen. Es ist eine große Ehre.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29792] = {title = "Zu Großem berufen", objective = "Öffnet das Tor zum Pei-Wu-Wald.", description = "Es liegt nun an Euch allen, den Stachel aus dem Fleisch Shen-zin Sus zu entfernen. Lasst Eure Unterschiede nicht zu einem Hindernis werden. Habt Vertrauen ineinander.\n\nIm Pei-Wu-Wald lebt ein Einsiedler. Begebt Euch geradewegs zu seiner Hütte. Er weiß genau, was für dunkle Gestalten sich dieser Tage in den Bäumen verstecken.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29793] = {title = "Das Böse aus dem Meer", objective = "Tötet 8 verfinsterte Gräuel oder verfinsterte Schrecken.", description = "Ich weiß nicht genau, was dieses Böse ist, das den Wald befallen hat, <Name>, aber ich weiß genau, was man dagegen tun kann. Ich denke, Ihr wisst, was ich meine...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Robe des BeschützersStiefel des MutesBeinschützer des MutigenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29794] = {title = "Keiner wird zurückgelassen", objective = "Rettet 3 verletzte Matrosen.", description = "Eure Freundin hat keine Mühen gescheut, um meine Besatzung zu retten. Ich bin ihr zu tiefstem Dank verpflichtet.\n\nWir haben hier aber immer noch mit zu vielen Problemen gleichzeitig zu kämpfen: Die Feuer am Wrack müssen gelöscht, die Leute herausgeschafft und die Gefangenen an der Flucht gehindert werden. Wir schaffen das einfach nicht allein.\n\nDa sind immer noch Besatzungsmitglieder auf dem Schiff, die wir herausholen müssen, bevor das Wrack über ihnen zusammenbricht. Ich weiß, dass ich viel von Euch verlange, aber könntet Ihr uns helfen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "ÜberlebensgamaschenWeste des MitgefühlsStulpen der GnadeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29795] = {title = "Rohre raffen", objective = "Sammelt 10 abgebrochene Bambusrohre.", description = "Meine Männer sind unterernährt, verwundet und erschöpft, aber sie sind von der Horde. Ein jeder von ihnen wird bis zum letzten Atemzug kämpfen. Ihr seid unser neuer Verbündeter und wir werden Euch zur Seite stehen, wenn die Zeit reif ist, aber wir wären eine weitaus größere Hilfe, wenn wir bewaffnet wären.\n\nIch habe meine Männer beauftragt, Bambusrohre aus der Umgebung zusammenzusammeln, die wir zu Speeren umfunktionieren könnten. Falls es Euch nichts ausmacht, könnten wir dabei ein weiteres Paar kräftige Hände gut gebrauchen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29796] = {title = "Dringende Neuigkeiten", objective = "Sprecht mit Delora Löwenherz beim Wrack der Himmelssucher.", description = "Ich bin mir sicher, dass Aysa dieser Plan nicht gefallen wird, aber es ist der einzige Plan, den wir haben. Würde es Euch etwas ausmachen, an meiner Stelle der Überbringer schlechter Nachrichten zu sein, <Name>? Sie muss wissen, was wir vorhaben, damit sie alle in Sicherheit bringen kann.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29797] = {title = "Medizinische Versorgungsgüter", objective = "Beschafft 8 Kisten mit medizinischen Versorgungsgütern wieder.", description = "Wir brauchen Medikamente und Verbandszeug, um uns um unsere Verwundeten zu kümmern, aber ich habe keine Ahnung, was mit den Kisten, in denen all das verstaut war, beim Absturz passiert ist. Wenn Ihr einfach ein paar Kisten wiederfinden könntet, dann wäre ich Euch sehr dankbar.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29798] = {title = "Ein uraltes Übel", objective = "Bezwingt Vordraka, den Alptraum aus der Tiefe.", description = "<Name>, ich habe nach Euch gesucht!\n\nEiner der entkommenen Seeleute hat Aysa im Schiffswrack gesehen, wie sie einem gigantischen Ungeheuer gegenüberstand. Sie braucht wahrscheinlich Eure Hilfe... Eilt zu ihr, schnell!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29799] = {title = "Die Heilung von Shen-zin Su", objective = "Rettet und beschützt die Heiler, bis Shen-zin Sus Wunde geheilt ist.", description = "Das ist viel schlimmer, als ich erwartet hatte, aber wir können es schaffen. Wir müssen alle Heiler zusammentrommeln, um die Wunde zu schließen. Wir müssen Shen-zin Su retten.\n\nFindet so viele Heiler, wie Ihr nur könnt! Befreit sie, entbindet sie von anderen Aufgaben - tut, was immer Ihr tun müsst, damit sie hierherkommen und diese Wunde heilen.\n\nUnd passt auf, dass ihnen dabei nichts zustößt...Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Gelenkbänder des HeilersZeremonielle GamaschenRitualbrustplatteDer folgende Zauber wird auf euch gewirkt:\n\nBlackout into Healed Phase\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29800] = {title = "Neue Verbündete", objective = "Kehrt zum Tempel der Fünf Sonnenaufgänge zurück. Beim Wrack der Himmelssucher wartet ein Wagen auf Euch der Euch zum Tempel bringen wird.", description = "Ich habe getan, was getan werden musste, <Name>. Und es hat funktioniert. Es hätte alles viel schlimmer enden können, hätten wir nicht gehandelt. Ich wünschte nur, dass Aysa das verstehen würde.\n\nEs wird noch genug Zeit zur Besinnung geben, aber wir müssen zuerst zum Tempel der Fünf Sonnenaufgänge zurückkehren. Wir müssen sie wissen lassen, dass Shen-zin Su gerettet wurde - und wir müssen über das Schicksal dieser neuen Verbündeten entscheiden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29801] = {title = "Bewährungsprobe", objective = "Bestehlt Hagara die Sturmbinderin im Auge der Ewigkeit in der Drachenseeleninstanz und beschafft Euch so einen Entschlüsselungsring des Kryptomanten.", description = "Hallo, <Name>! Im Schwarm hat sich herumgesprochen, dass Ihr ziemlich... wie soll ich sagen... geschickte Finger habt.\n\nWir könnten jemand mit Euren Fähigkeiten für eine äußerst delikate Aufgabe gebrauchen. Bevor ich fortfahre, muss ich wissen, ob Ihr <der richtige Mann/die richtige Frau> für diese Angelegenheit seid. Wenn Euch der Krieg zum Auge der Ewigkeit führt, möchte ich, dass Ihr Hagara die Sturmbinderin bestehlt und Ihr den Entschlüsselungsring eines Kryptomanten abnehmt. Wollt Ihr Euch dieser Aufgabe stellen?", progress = "Habt Ihr unsere Aufgabe abgeschlossen? Diese Artefakte sind so konstruiert, dass sie sich auflösen, wenn ihr Träger getötet wird. Nur ein geübter Dieb kann sie beschaffen.", completion = "Ihr habt einen gefunden! Ihr seid eine Zierde für Euer Volk, &lt;Name&gt;.\n\nMit diesen Ringen kann man sogar die kompliziertesten Chiffren entschlüsseln. Leider muss der Ring dazu erst aufgeladen werden...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29802] = {title = "Eine verborgene Botschaft", objective = "Ladet Euren Entschlüsselungsring des Kryptomanten auf und entschlüsselt damit Corastraszasangesengte Geheimnachricht.", description = "Corastrasza, die sich momentan im Zinnoberrefugium im Schattenhochland aufhält, hat eine kodierte Botschaft von großer Wichtigkeit abgefangen. Sie wird Euch alles erklären, aber zuallererst brauchen wir Eure Hilfe bei der Entschlüsselung der Nachricht.\n\nBringt Euren Entschlüsselungsring zu einem astralen Thaumaturgen in Eurer Hauptstadt - er sollte wissen, wie man ihn auflädt. Lasst Euch die verschlüsselte Nachricht von Corastrasza geben und dekodiert sie mit Eurem Entschlüsselungsring. Beeilt Euch! Die Zeit läuft uns davon...", progress = "Ich hatte gehofft, dass Lord Devrestrasz einen kompetenten Helfer finden würde.\n\nWas habt Ihr für uns, <Name>? Könnt Ihr die Botschaft entschlüsseln?", completion = "Worum geht's, um das \"Rabenholdtanwesen\"? Ich dachte, da oben im Vorgebirge des Hügellandes gäbe es nur eine zusammengewürfelte Diebesbande.\n\nWas wollen die denn mit einem Drachenei? Und noch wichtiger: Wie haben sie davon erfahren?\n\nWir brauchen Antworten, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29803] = {title = "Die Ohren des Lichkönigs", objective = "Verteidiger Mordun in Burg Utgarde möchte, dass Ihr Prinz Keleseth tötet.", description = "Im Fjord dient Prinz Keleseth als Arthas' Augen und Ohren.\n\nDas gefällt mir kein bisschen!\n\nMacht Arthas hier taub und blind. Damit erweist Ihr der Welt einen Gefallen.", progress = nil, completion = "Ich wette, das hat dieses Blassgesicht gespürt!\n\nEin weiterer Schritt auf dem Weg zur Abrechnung, Arthas!", rewards = "Wickel der San'laynVendettabindungenArmschienen des RunenmagiersUnterarmschienen des VergeltungsbringersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29804] = {title = "Rache für Schnuff!", objective = "Tötet Konk.", description = "Ich wollt' eigentlich liegenbleib'n und abkratz'n, Mann.\n\nAber das geht jetzt nich'!\n\nSchnuff und ich war'n schon seit Ewigkeiten Kumpels. Was hatt'n wir für schöne Zeiten zusammen...\n\nAber ich muss erst Schnuff räch'n, Mann! Sonst kann ich ihm im Jenseits nich' unter die Augen tret'n!\n\nDer Anführer dieser Mistkerle heißt Konk. Er muss dran glaub'n - für Schnuff!", progress = nil, completion = "Zin'Jun ist gestorben?\n\nWas für ein trauriger Tag, Bruder. Dafür muss dieses Gezücht bezahlen!", rewards = "Ledertunika des bedeutenden LandgutsKettenrüstung des bedeutenden LandgutsSeidene Robe des bedeutenden LandgutsSatinrobe des bedeutenden LandgutsBalgtunika des bedeutenden LandgutsRingpanzerrüstung des bedeutenden LandgutsBrünierter Brustschutz des bedeutenden LandgutsGepanzerter Brustharnisch des bedeutenden LandgutsSchwerer Brustharnisch des bedeutenden LandgutsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29806] = {title = "Der Wanderer", objective = "Bezwingt den herumstreifenden Raufbold in einem Kampf.[ph] Findet den herumstreifenden Raufbold und fordert ihn zu einem Kampf heraus.", description = "[ph] Findet den herumstreifenden Raufbold und fordert ihn zu einem Kampf heraus.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][29807] = {title = "Tod dem Verräterkönig", objective = "Pionier A'zak in Azjol-Nerub hat Euch aufgetragen, Anub'arak zu besiegen. Kehrt danach mit Anub'araks zerbrochenem Panzer zu A'zak zurück.", description = "Anub'arak der Verräterkönig ist im einst stolzen unterirdischen Azjol-Nerub zuhause.\n\nEr hat unsere Heimat in den erbärmlichen Haufen Dreck verwandelt, den wir heute sehen. Er herrscht über eine Armee untoter Neruber, die dem Lichkönig die Treue geschworen haben.\n\nSetzt der Herrschaft des Verräterkönigs ein Ende.", progress = "Ist es getan, <Klasse>? Hat der Verräterkönig endlich sein Leben ausgehaucht?", completion = "&lt;A'zaks Augen beginnen durchdringend zu leuchten, als er den Panzer anstarrt.&gt;\n\nEs ist VOLLBRACHT!\n\n&lt;Volk&gt;! Euer Name wird in die Annalen meines Volkes aufgenommen werden.", rewards = "Kilix' SeidenslipperDon Sotos StiefelHüllenfragmentsabatonsSchienbeinschützer des VerrätersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29808] = {title = "Vergesst die Eier nicht!", objective = "Pionier A'zak in Azjol-Nerub möchte, dass Ihr 6 Eier der Geißelneruber zerstört.", description = "In ganz Azjol-Nerub liegen Eier, die von den Nerubern der Geißel gehegt und gepflegt werden. Die Jungen werden bald schlüpfen um geschlachtet und als Untote wiedererweckt zu werden.\n\nDiese Eier wurden mit fauler Magie verunreinigt. Wir müssen sie unbedingt vernichten.", progress = nil, completion = "Keine Sorge, &lt;Volk&gt;.\n\nWir haben die meisten unserer Eier gut in Azjol-Nerub versteckt. Sie haben nur ein paar gefunden.\n\nUnser mächtiges Königreich wird wieder auferstehen.", rewards = "Ausstoßende StulpenReinigende HandschützerWickeltücher des bezwungenen BannsHandschuhe der verbannten AuferlegungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29809] = {title = "Effiziente Ausgrabungen", objective = "Bringt 'Effiziente Ausgrabungen' zu Bellok Leuchtklinge in Schnottz' Landeplatz.\n\nBereitgestellter Gegenstand: \n", description = "Dieses Handbuch beschreibt absonderliche Theorien, wie man große Arbeitergruppen wirksam einteilt, wenn sie mit gewaltigen Ausgrabungsprojekten beschäftigt sind.\n\nNachdem Ihr den Inhalt überflogen habt, wird Euch klar, dass der Verfasser des Buchs die Person sein muss, die für die übermäßig aggressiven Plünderer hier verantwortlich ist.\n\nEine Karte auf der Rückseite des Umschlags zeigt, dass der Verfasser einen Bunker in der südwestlichen Region von Uldum besitzt.\n\nVielleicht wäre es angebracht, sich einmal vorzustellen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29811] = {title = "Der Talisman des Torwächters", objective = "Pionier A'zak in Azjol-Nerub möchte, dass Ihr den Talisman des Torwächters von Krik'thir dem Torwächter erbeutet.", description = "Krik'thir, Wächter der Tore von Azjol-Nerub, war kein Verräter.\n\nEr fiel im Krieg der Spinne, als er unsere Heimat gegen die Geißel verteidigte.\n\nWie es seiner Stellung gebührte, besaß er den Schlüssel zum verborgenen Reich. Ich möchte, dass Ihr ihn bergt, damit er seinem Volk überbracht werden kann.", progress = "Wurde Krik'thirs Geist vom Fluch des Untodes befreit? Was ist mit dem Talisman?", completion = "Ich hatte es geahnt.\n\nEin Großteil des Reiches ist seit Krik'thirs letztem Kampf verschlossen geblieben. Vielleicht hat mein Volk die Tiefen bereits gesichert und wartet nur auf seine Befreiung. Vielleicht sind es jedoch auch die Gesichtslosen, die hinter verschlossenen Türen lauern.\n\nWir werden es irgendwann erfahren. Zuerst muss jedoch der freigelegte obere Teil von Azjol-Nerub von Arthas' Schmutz gesäubert werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29815] = {title = "Forensische Wissenschaft", objective = "Sammelt 8 Einheiten zähflüssiges Chlorophyll.", description = "Diese Kreaturen sind überall - und aggressiv sind sie noch dazu! Wir müssen uns um sie kümmern, bevor noch mehr Allianzmitglieder hier auftauchen.\n\nDieses Exemplar hier ist ziemlich übel zugerichtet, aber ich konnte dennoch einige Erkenntnisse über seine Anatomie gewinnen.\n\nMit den richtigen Reagenzien sollte es mir gelingen, ein Gift zusammenzubrauen, das im Kampf gegen diese Spezies seine Wirkung nicht verfehlen wird. Es sollte sogar reichen, einfach das Gift, das ich bei mir trage, etwas zu modifizieren.\n\nZieht los und sucht mir in der Nähe des Wassers etwas Zähflüssiges Chlorophyll. Jedes halbintelligente Pflanzenwesen dürfte den Zweck erfüllen.", progress = "Ich hoffe, Ihr hattet Erfolg. Unser Überleben hier hängt vielleicht davon ab.", completion = "Oh, ja, &lt;Name&gt;. Damit kann ich etwas anfangen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29820] = {title = "Hinein in den Nexus", objective = "Erzmagier Berinand hat Euch gebeten, mit Kriegsmagierin Kaitlyn im Nexus zu sprechen.Ich habe Kriegsmagierin Kaitlyn in den Nexus geschickt, damit sie Malygos' chaotisches Reich untersucht, aber sie hat sich seit Tagen nicht gemeldet.\n\nKönntet Ihr dorthin gehen und sie unterstützen? Sie könnte sicherlich Hilfe gebrauchen, wenn die Drachen sie nicht schon gefressen haben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ich habe Kriegsmagierin Kaitlyn in den Nexus geschickt, damit sie Malygos' chaotisches Reich untersucht, aber sie hat sich seit Tagen nicht gemeldet.\n\nKönntet Ihr dorthin gehen und sie unterstützen? Sie könnte sicherlich Hilfe gebrauchen, wenn die Drachen sie nicht schon gefressen haben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29821] = {title = "Miese kleine Diebe", objective = "Findet die fehlende Vorratskiste bei der Kaskade der Ruhe.\n\nBereitgestellter Gegenstand: \n", description = "Hört mal, <Kumpel/Schätzchen>.\n\nIch hab ein paar Versorgungsdrohnen vom Luftschiff aus losgeschickt, aber die sind alle abgestürzt oder verloren gegangen. Na ja, fast alle.\n\nEine von ihnen ist hier durchs Lager gesurrt und dann bei den Wasserfällen abgeschmiert.\n\nWarum schaut Ihr nicht mal, ob Ihr die Inhalte dieser Kiste retten und hierherbringen könnt, hmm?\n\nWir haben zwar keine Drohnen mehr, aber meine Raketenstiefel könnten hier ganz nützlich sein. Die gehen ab wie eine... äh... Rakete!\n\nHa ha, ich lach mich schief...", progress = nil, completion = "Diese Kiste sollte voller Vorräte sein...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29822] = {title = "Eigenheiten des Landes", objective = "Besucht den Schrein der Sonne, den Schrein des Mondes und tötet Djuuk Uukem.", description = "Diese verfluchten Fellknäuel! Für jeden von ihnen, den wir töten, stehen plötzlich zwei neue da...\n\nNichts hat sich geändert, <Name>. Befehle sind Befehle, egal, wie wenige wir sind und wie schlecht unsere Chancen stehen.\n\nIch muss Pläne schmieden und Probleme lösen.\n\nZieht in das Land und lernt seine Eigenheiten kennen. Kommt erst wieder, wenn Ihr etwas Nützliches zu berichten habt.\n\nUnd wenn Ihr unterwegs seid, seht zu, dass dieser jammernde Idiot die Klappe hält! Weggetreten!", progress = nil, completion = "Willkommen, Reisender.\n\nBitte, macht es Euch bequem.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29823] = {title = "Späherbericht: Der Freund meines Feindes", objective = "Hört Euch Rikos Bericht an.", description = "Wisst Ihr, wir haben nicht nur nach der Allianz gesucht. Wir haben auch nach diesen watzrommeligen, flipmippischen Jinyu gesucht!\n\nNa ja, wir ha'm sie ja auch gefunden...", progress = nil, completion = "Ja, ich bin weggelaufen. Na und? Ohne mich wäre Kiryn jetzt tot. Oh, Moment… sie ist bereits tot… bereits...\n\nGeht weg! Riko hat Kopfschmerzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29824] = {title = "Späherbericht: Butter bei die Jinyu", objective = "Hört Euch Shokias Bericht an.", description = "Nachdem unser Anführer in Jade verwandelt wurde, unser Ho-zen-Führer verschwunden war und wir einen Kriegsgefangenen im Schlepptau hatten, blieb nur eins für Kiryn und mich zu tun:\n\nIns Feindesland einmarschieren und Rache nehmen.\n\nWollt Ihr wissen, wie das gelaufen ist?", progress = nil, completion = "Das Wichtigste, das wir lernten, war... dass die Allianz nicht nur Freundschaft mit den Jinyu geschlossen hat, sondern sie auch mit Waffen versorgt und ihnen beibringt, wie man sie benutzt.\n\nDie Allianz hat jetzt eine Armee, die uns dreißig-zu-eins zahlenmäßig überlegen ist. Und wir - die HORDE - haben Freundschaft mit Affen geschlossen.", rewards = "MondwasserringSchlangenwirbelbandBand des lauernden TigersRing der WiederherstellungBlühender RingDer folgende Zauber wird auf euch gewirkt:\n\nNazgrim beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29825] = {title = "Nicht länger ein Schüler", objective = "Seher Ixit in Ahn'kahet hat Euch gebeten, Urahne Nadox zu töten.", description = "Einst nannte ich Urahne Nadox meinen Lehrer.\n\nDas änderte sich für immer, als ich zusehen musste, wie er, ein Diener der Verdammten, meine Freunde und meine Familie umbrachte.\n\nFindet ihn in den Tiefen und sorgt dafür, dass er für seine Verbrechen bezahlt.", progress = "Ist der mächtige Nadox endlich tot?", completion = "Ich hoffe, dass ich nun an Nadox' Stelle treten und mein Volk anführen kann.\n\nDas Reich von Azjol-Nerub wird Großes vollbringen, &lt;Volk&gt;...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29826] = {title = "Die Rückeroberung von Ahn'kahet", objective = "Seher Ixit in Ahn'kahet möchte, dass Ihr 3 Augen von Taldaram, einen Knochenschinder und Prinz Taldaram tötet.", description = "Prinz Taldaram und seine Geißelarmee benutzen die gleichen Barrieren, hinter denen wir einst unser Reich verbargen, um sich vor den Einheimischen der eisigen Tiefen zu schützen.\n\nDeaktiviert die Barrieren und tötet die Geißelsoldaten, die sie bewachen. Meine Streitkräfte werden zusammen mit den Einheimischen den Rest erledigen.", progress = nil, completion = "Hervorragend.\n\n&lt;Ihr hört einige klickende Geräusche.&gt;\n\nUnd nun zu unserem anderen Feind...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29827] = {title = "Saurer Regen", objective = "Benutzt den Geborgenen Gyrokopter, um 25 Ho-zen-Magenfetzer und 25 Ho-zen-Spenkspieker zu töten.", description = "Während Ihr fort wart, haben sich immer mehr von diesen Kreaturen in der Nähe unseres Lagers versammelt. Sie scheinen eine Großoffensive vorzubereiten!\n\nWir werden drastische Mittel ergreifen müssen, wenn wir nicht sang- und klanglos untergehen wollen.\n\nHier, nehmt meine vergifteten Wurfsterne und überlegt Euch, wie Ihr ihre Reihen etwas dezimieren könnt.", progress = nil, completion = "Ausgezeichnet! Welch kreative Lösung!\n\nDas sollte sie eine Weile fernhalten.", rewards = "Lederbeinschützer des ehrenhaften KampfingenieursKettengamaschen des ehrenhaften KampfingenieursSeidene Hosen des ehrenhaften KampfingenieursSatingamaschen des ehrenhaften KampfingenieursBalgbeinschützer des ehrenhaften KampfingenieursRingpanzergamaschen des ehrenhaften KampfingenieursBrünierte Beinplatten des ehrenhaften KampfingenieursGepanzerte Beinschützer des ehrenhaften KampfingenieursSchwere Beinschützer des ehrenhaften KampfingenieursIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29828] = {title = "Der Alptraum der Geißel", objective = "Kurzel in der Feste Drak'Tharon möchte, dass Ihr König Dred tötet und ihr seinen Zahn bringt.", description = "Ein flüchtender Drakkaritroll hat mir von einem großen Raptorkönig namens Dred erzählt, der gegen die Seuche immun ist.\n\nFindet diesen König Dred und bringt mir einen seiner Zähne. Vielleicht kann ich daraus eine Waffe herstellen.", progress = "Gibt es diese gewaltige Bestie wirklich?", completion = "&lt;Kurzels Augen weiten sich.&gt;\n\nBoah! Der ist ja riesig!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29829] = {title = "Diskretion ist der Schlüssel", objective = "Rhonin möchte, dass Ihr zur Violetten Festung in Dalaran geht und mit Leutnant Sinclari sprecht.", description = "Hört mir zu, <Volk>.\n\nMir wurde soeben mitgeteilt, dass sich in der Violetten Festung ein Zwischenfall ereignet hat. Es scheint, als würde der blaue Drachenschwarm eine groß angelegte Invasion Dalarans vorbereiten!\n\nIch möchte, dass Ihr Euch umgehend zum Gefängnis begebt und mit Leutnant Sinclari sprecht. Sie wird Euch alles erklären.\n\nDoch das ist nicht alles. Ihr müsst äußerst diskret vorgehen. Wir dürfen die Bürger Dalarans nicht verunsichern, wenn es sich vermeiden lässt. Habe ich mich klar ausgedrückt?\n\nGut. Dann geht jetzt.", progress = nil, completion = "Keinen Augenblick zu früh.\n\nSeid Ihr bereit, Dalaran zu verteidigen, &lt;Klasse&gt;?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29830] = {title = "Eindämmung", objective = "Leutnant Sinclari in der Violetten Festung möchte, dass Ihr die Invasion der blauen Drachen aufhaltet. Sprecht mit ihr, wenn Cyanigosa geschlagen ist.", description = "Meine Streitkräfte liegen am Boden, aber Malygos' Angreifer stürmen immer weiter auf uns ein.\n\nIhr müsst sie aufhalten, bis ihre Anführerin Cyanigosa auftaucht. Nur ihr Tod wird die Invasion beenden und Dalaran retten.\n\nSprecht mich an, wenn Ihr bereit seid.", progress = "Ist es vorbei? Konntet Ihr dem Angriff standhalten?", completion = "Danke, mein Held!\n\nDank Eures Mutes konnte Dalaran einen weiteren Tag überstehen.", rewards = "Tätowierte WildhautgamaschenVerliehene PantalonsLabyrinthische BeinschützerBeinplatten des Wächters von DalaranIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29831] = {title = "DEPRECATED: Terror on the High Seas", objective = "Sprecht mit Großadmiralin Jes-Tereth im Thronraum der Burg Sturmwind.In Sturmwind sind Meldungen eingegangen, die von furchtbaren Verbrechen gegen zivile Schiffe der Allianz berichten. Die Horde wird angeklagt, die Schiffe aufgebracht und geentert zu haben. Zudem sollen Passagiere misshandelt und Frachtgut gestohlen worden sein.\n\nHelden der Allianz, wir zählen auf Eure Hilfe, um den Wahrheitsgehalt dieser Anklagen aufzudecken! Wendet Euch an Großadmiralin Jes-Tereth in der Burg Sturmwind, wenn Ihr diesem Aufruf folgen mögt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "In Sturmwind sind Meldungen eingegangen, die von furchtbaren Verbrechen gegen zivile Schiffe der Allianz berichten. Die Horde wird angeklagt, die Schiffe aufgebracht und geentert zu haben. Zudem sollen Passagiere misshandelt und Frachtgut gestohlen worden sein.\n\nHelden der Allianz, wir zählen auf Eure Hilfe, um den Wahrheitsgehalt dieser Anklagen aufzudecken! Wendet Euch an Großadmiralin Jes-Tereth in der Burg Sturmwind, wenn Ihr diesem Aufruf folgen mögt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29832] = {title = "DEPRECATED: Gathering Evidence", objective = "Begebt Euch zum Hafen von Sturmwind und sprecht mit Schildwache Eloria, Lumian Sternwisper, Nayeth Frostmond und Finelar Nebelgänger.", description = "Ein Schiff namens Bravado transportiert regelmäßig Passagiere und Fracht vom Hafen von Sturmwind nach Rut'theran, gleich außerhalb von Darnassus.\n\nNun, das Schiff hat dieses Mal beunruhigende Nachrichten zurückgebracht. Sowohl Passagiere als auch die Besatzung haben berichtet, dass Boote der Horde die Bravado in den Gewässern von Teldrassil aufgebracht und geentert haben sollen. Sie sollen die Leute an Bord misshandelt und einiges der Fracht gestohlen haben, bevor sie das Schiff auf Heimatkurs geschickt haben.\n\nWir müssen herausfinden, was geschehen ist, <Name>. Könntet Ihr Euch zum Hafen von Sturmwind begeben und die Passagiere befragen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29833] = {title = "Offene Rechnungen", objective = "Har'koa möchte, dass Ihr mit Tol'mar in Gundrak sprecht.", description = "Der Prophet von Akali mag diese Welt zwar nicht mehr belästigen, doch es gibt noch immer Arbeit zu tun.\n\nAkalis Blut - ein Großteil davon - hat jemand anderem Macht verliehen und es ist dieser jemand, von dem die eigentliche Gefahr ausgeht.\n\nSchnell, <Name>, macht Euch auf den Weg nach Gundrak und sprecht mit Tol'mar. Er wird Euch diesbezüglich weitere Anweisungen geben können.", progress = nil, completion = "Hör zu, Mann. Die Arbeit, die hier erledigt werden muss, is' gefährlich!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29834] = {title = "Gal'darah muss bezahlen", objective = "Tol'mar möchte, dass Ihr Slad'ran, Moorabi und Gal'darah in Gundrak tötet.", description = "War das schlimmste, was ich je gesehen hab', Mann. Der große Akali - vor meinen Augen getötet. Furchtbar...\n\nIch bin nur hier, um zu beobachten, aber so was geht nich'! Gal'darah un' seine Anhänger müssen dafür bezahlen!\n\nRäche Akalis Tod, Mann. Muss sein.", progress = "Hast du Akalis Tod gerächt, <Volk>?", completion = "Du hast es getan?! Sie sind hin?\n\nHier, Mann. Das Geschenk is' für dich, weil du den Eisigen Weiten Gerechtigkeit gebracht has'.", rewards = "Listige MojoscherpeSeltsamer VoodoogürtelWaldläufergürtel des gefallenen ImperiumsSchnalle des gefallenen HalbgottsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29835] = {title = "Gal'darah muss bezahlen", objective = "Chronistin Bah'Kini möchte, dass Ihr Slad'ran, Moorabi und Gal'darah in Gundrak tötet.", description = "Der mächtige Akali is' tot, <Volk>.\n\nMeine Rolle im Leben ist es, Dinge aufzuzeichnen, nich' zu kämpfen. Aber das geht nicht! Gal'darah und seine Anhänger müssen bezahlen!\n\nRäche Akalis Tod, Mann. Muss sein.", progress = nil, completion = "Du hast es getan?\n\nDamit hast du meine Erwartungen voll übertroffen, Mann. Das Geschenk is' für dich, weil du den Eisigen Weiten Gerechtigkeit gebracht has'.", rewards = "Listige MojoscherpeSeltsamer VoodoogürtelWaldläufergürtel des gefallenen ImperiumsSchnalle des gefallenen HalbgottsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29836] = {title = "Nur ma' nachsehen", objective = "To'kini möchte, dass Ihr mit Bah'Kini in Gundrak sprecht.", description = "Unten aus Gundrak waren fürchterliche Geräusche zu hören. In letzter Zeit sind sie lauter geworden und auch häufiger zu hören.\n\nMeine langjährige Schülerin konnte von ihrem Posten westlich von Gundrak aus die Ereignisse erfassen. Hättet Ihr vielleicht Zeit, bei Ihr nachzusehen, was los ist?", progress = nil, completion = "To'kini is' mein feiger Vater - er traut sich nicht so nahe an Gundrak heran... deshalb hat er mich geschickt!\n\nHier gibt's soviel Trollgeschichte. Wir dürf'n nich' zulassen, dass Gal'darah un' seine irren Anhänger sie auf ewig vor uns verstecken!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29837] = {title = "Heilige Schriftrolle", objective = "Bringt die unlesbare Schriftrolle zu Lehrensucher Cho.\n\nBereitgestellter Gegenstand: \n", description = "Die fremdartigen Markierungen auf diesem Pergament haben eine Eleganz an sich, zu der dieser Yoggtord und seine Bande gar nicht fähig wären.\n\nIhr vermutet, dass es wie alles andere auch, was diese Ho-zen besitzen, gestohlen ist.\n\nMöglicherweise hält sich der rechtmäßige Besitzer der Schriftrolle noch in der Nähe auf...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29838] = {title = "Einzigartig", objective = "Chronistin Bah'Kini möchte, dass Ihr ein Stück des Kolosses der Drakkari in Gundrak erbeutet.", description = "Auf'n ersten Blick denkt ma', die Geschichte kenn' ich schon: Trolle zapf'n verbotene Energien an, weil sie die Wesen vernicht'n, die sie eigentlich anbeten sollt'n.\n\nWenn's stimmt, was ich so hör', dann haben sie 'nen besonderen Golem - einen, der anders is' als alle and'ren vor ihm!\n\nBring mir'n Stück von dem Golem zum Untersuchen, Mann.", progress = "Hast du mir ein Stück dieses Golems gebracht, Mann?", completion = "Ahh, ja Mann! Das ist es, wonach ich gesucht habe.\n\nHier, bitte schön - nimm dir was Schönes für den Ärger, den du hattest.", rewards = "Pelzbesetzte MokassinsRhinozerosbalgkniestiefelSchuppenstiefel der gefallenen HoffnungTrollkickerSlipper des Mojo-DojosIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29839] = {title = "Einzigartig", objective = "Tol'mar möchte, dass Ihr ein Stück des Kolosses der Drakkari in Gundrak erbeutet.", description = "Dem ganz'n Ärger hätte man aus'm Weg gehen können, wenn die Drakkari die Götter angebetet, anstatt umgebracht hätt'n.\n\nIch hab gehört, dass sie 'nen besonderen Golem haben, einen, in dem verbotene Energien stecken.\n\nBring mir ein Stück von dem Golem, Mann, damit wir von uns'ren Brüdern und Schwestern lernen können.", progress = "Hast du den Golem gefunden, Mann? Der muss da irgendwo sein.", completion = "Unglaublich! Sowas hab' ich noch nie geseh'n.\n\nGute Arbeit, Mann.", rewards = "Pelzbesetzte MokassinsRhinozerosbalgkniestiefelSchuppenstiefel der gefallenen HoffnungTrollkickerSlipper des Mojo-DojosIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29840] = {title = "Für die Nachwelt", objective = "Chronistin Bah'Kini in Gundrak möchte, dass Ihr 6 Geschichtstafeln der Drakkari sammelt.", description = "Gundrak is' nich' mehr zu rett'n, Mann. Du weißt, dass ich Recht habe.\n\nWenn du den Mut dazu hast, such nach Geschichtstafeln, in denen steht, wieso das Reich der Drakkari gefall'n is'.\n\nVielleicht könn'n wir's eines Tages wieder aufbau'n.", progress = "Haste die Geschichtstafeln der Drakkari gefund'n, Mann?", completion = "Bin dir echt dankbar dafür, Mann.\n\nDie werd'n uns 'ne große Hilfe sein.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRing des LöwenkopfesRing des faulen MojosSolides PlatinbandVoodoosiegel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][29841] = {title = "Beschaffenheit des Landes [TEMP]", objective = "Erkundet die Gegend.Grah!!\n\nFür jeden dieser Schlammschleuderer, den wir ausschalten, springen zwei weitere aus dem Wald und nehmen seinen Platz ein. Ich möchte nicht, dass die anderen es schon erfahren, aber es ist offensichtlich, dass wir hier nicht lange durchhalten werden, <Name>.\n\nIch muss hier bleiben und unseren letzten Besitz verteidigen. Erkundet Ihr die Gegend und sucht eine Lösung für unser Primatenproblem.\n\nGeht jetzt. Unsere Hoffnungen begleiten Euch...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Grah!!\n\nFür jeden dieser Schlammschleuderer, den wir ausschalten, springen zwei weitere aus dem Wald und nehmen seinen Platz ein. Ich möchte nicht, dass die anderen es schon erfahren, aber es ist offensichtlich, dass wir hier nicht lange durchhalten werden, <Name>.\n\nIch muss hier bleiben und unseren letzten Besitz verteidigen. Erkundet Ihr die Gegend und sucht eine Lösung für unser Primatenproblem.\n\nGeht jetzt. Unsere Hoffnungen begleiten Euch...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29842] = {title = "Antworten suchen", objective = "Nutzt die Kerzen, um am Cairn des Blutes zu meditieren.", description = "<Cho hört sich zuerst Eure Fragen an, bevor er spricht.>\n\nSo viel, über das man nachdenken muss, <Reisender/Reisende>...\n\nIhr müsst zuerst lernen, wie man fragt, bevor Euer Geist die Wahrheit erkennen kann.\n\nIch habe meine Meditation für heute beendet, aber meine Kerzen bleiben am Ring des Blutes.\n\nGeht dorthin. Leert Euren Geist. Wir sprechen uns wieder, wenn Ihr bereit seid, meine Worte zu hören.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29844] = {title = "Für die Nachwelt", objective = "Tol'mar in Gundrak möchte, dass Ihr 6 Geschichtstafeln der Drakkari sammelt.", description = "Das Land der Eistrolle is' nur noch'n Schatten seiner selbst.\n\nWenn du genug Mut aufbringst, dann such doch mal nach Geschichtstafeln, Mann. Da steht drin, wieso das Reich der Drakkari untergegang'n ist.\n\nEines Tages werd'n wir das Land vielleicht an 'ne neue Generation Frosttrolle weitergeb'n können.", progress = "Haste die Geschichtstafeln der Drakkari gefund'n, Mann?", completion = "Die Reiche von uns Trollen werd'n schon länger gespalten als es die and'ren Völker gibt, Mann.\n\nWir steh'n immer wieder aus den Ruinen auf.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nRing des LöwenkopfesRing des faulen MojosSolides PlatinbandVoodoosiegel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][29847] = {title = "Auf den Spuren des Diebs", objective = "Dringt in das Rabenholdtanwesen ein und findet das verschwundene Schwarzdrachenei.", description = "Unmittelbar hinter dieser Höhle liegt das Rabenholdtanwesen. Ihr müsst dort eindringen, ohne bemerkt zu werden!\n\n<Mostrasz belegt Euch mit einer Verzauberung.>\n\nGut - nun kann ich Euch auf Eurem Weg durch das Anwesen beobachten und mit Euch kommunizieren. Schleicht Euch hinein, findet das Ei und lasst Euch nicht erwischen...", progress = nil, completion = "Werdet Ihr mit mir zusammenarbeiten?\n\nGut. Sehr gut.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29848] = {title = "Die verlorene Behüterin", objective = "Kaldir Eisenbann in den Hallen des Steins möchte, dass Ihr der Maid der Trauer Frieden schenkt und eine Kristallträne der Trauer beschafft.", description = "Ich würde mein Leben mit Freuden für die Schöpfer oder ihre Wesen hingeben.\n\nSeit Lokens Verrat scheint es mir jedoch, als habe sich ganz Ulduar gegen die Welt verschworen. Vor allem die Maid der Trauer leidet entsetzlich unter ihren neuen Befehlen.\n\nBitte schenkt ihr Frieden und bringt mir eine ihrer Tränen.", progress = "Ich wünschte, es gäbe einen anderen Weg, aber nur der Tod kann die Maid jetzt noch erlösen.", completion = "&lt;Kaldir starrt einen Moment schweigend in den Kristall.&gt;\n\nKein Wesen hat das Leid je so gespürt wie die Maid der Trauer.\n\nDaran sollten wir denken, während wir unseren Kampf gegen Loken fortsetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29850] = {title = "Korrupte Konstrukte", objective = "Kaldir Eisenbann in den Hallen des Steins möchte, dass Ihr Krystallus und 3 dunkle Runenriesen tötet.", description = "Die Eisenzwerge haben damit begonnen, gewaltige Steinkonstrukte zu erschaffen, die sie, so fürchte ich, bald als mächtige Waffen einsetzen werden.\n\nIhr müsst unbedingt ihren Aufseher Krystallus und die dunklen Runenriesen, die bereits in den Hallen aufgetaucht sind, besiegen. Beeilt Euch, bevor es zu spät ist!", progress = nil, completion = "Gut gemacht, &lt;Volk&gt;.\n\nJede Waffe, die wir Loken abnehmen können, hilft unserem eigenen Feldzug.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29851] = {title = "Champion des Turniers", objective = "Hochlord Tirion Fordring hat Euch beauftragt, die Prüfung des Champions zu vollenden.", description = "Dank dieses Turniers kommen wir unserer letzten Konfrontation mit dem Lichkönig immer näher.\n\n<Name>, kämpft tapfer und ehrenhaft. Die Kämpfer hier haben sich hier zu unser aller Wohl versammelt.\n\nGemeinsam werden wir Arthas aufhalten!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29854] = {title = "DEPRECATED: Claiming Kalimdor", objective = "Meldet Euch bei General Nazgrim in der Feste Grommash in Orgrimmar.Bald wird der Sieg unser sein! Unsere Truppen haben den Feind in ganz Kalimdor in Kämpfe verwickelt.\n\nKriegshäuptling Garrosh Höllschrei hat angeordnet, dass sich ein <Volk>, der diensttauglich ist, sich auch zur Unterstützung unserer neuesten Offensive zum Dienst melden muss.\n\nBegebt Euch zur Feste Grommash in Orgrimmar und meldet Euch bei General Nazgrim zum sofortigen Einsatz! Für die Horde!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Bald wird der Sieg unser sein! Unsere Truppen haben den Feind in ganz Kalimdor in Kämpfe verwickelt.\n\nKriegshäuptling Garrosh Höllschrei hat angeordnet, dass sich ein <Volk>, der diensttauglich ist, sich auch zur Unterstützung unserer neuesten Offensive zum Dienst melden muss.\n\nBegebt Euch zur Feste Grommash in Orgrimmar und meldet Euch bei General Nazgrim zum sofortigen Einsatz! Für die Horde!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29857] = {title = "DEPRECATED: Where Are Those Ships?", objective = "Sprecht mit Aufseher Moxx im Außenposten von Zoram'gar in Eschental und tötet 6 nachtelfische Räuber auf den Schiffen vor der Stadt.", description = "Da der Großteil unserer Flotte im Angriff gegen Theramore gebunden ist oder anderswo gegen den Feind vorgeht, brauchen wir weitere Schiffe für unsere Blockade von Kalimdor.\n\nDer Kriegshäuptling hat den Schiffsbauern im Außenposten von Zoram'gar in Eschental befohlen, Überstunden zu machen, um der Nachfrage nachzukommen, aber noch ist keines der neuen Schiffe eingetroffen.\n\nReist dorthin und befragt ihren Aufseher. Sagt ihnen, der Kriegshäuptling braucht seine Schiffe!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29860] = {title = "Gegensätze", objective = "Sturmbote Eljrrin in den Hallen der Blitze möchte, dass Ihr Volkhan besiegt.", description = "Ich werde offen mit Euch sprechen, <kleiner/kleine:r> <Volk>. Mein Volk ist nicht mehr das gleiche, seit unsere Verbindung zu Thorim abgerissen ist.\n\nVolkhan wird nicht ruhen, bis er oder wir nicht mehr existieren. Wir wollen nur Frieden, doch es scheint, als läge unsere einzige Hoffnung im Krieg.", progress = nil, completion = "Volkhan wird mein Volk nicht mehr in seinen Träumen heimsuchen.\n\nMacht weiter wie bisher, kleiner &lt;Volk&gt;. Irgendwann wird mein Volk Thorim schon vergeben.", rewards = "Blitzerfüllte MantelungVerkohlter LederschulterschutzSturmgeschmiedete SchulternSchulterstücke des erloschenen HassesMantelung von VolkhanIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29861] = {title = "Mit allen Mitteln!", objective = "Sturmbote Eljrrin in den Hallen der Blitze möchte, dass Ihr Loken besiegt. Dann sollt Ihr mit Lokens Zunge zu Sturmbote Eljrrin zurückkehren.", description = "Loken wird fallen, egal, wie.\n\nDie Ehre und der Ruhm seiner Niederlage soll Euch gebühren.\n\nKehrt zu mir mit seiner gespaltenen Zunge zurück und verdient Euch meinen ewigen Dank.", progress = "Habt Ihr Gerechtigkeit über Loken gebracht?", completion = "Dieser widerliche Wurm ist tot?\n\nIhr seid wahrhaft ein Segen für mein Volk, kleiner &lt;Volk&gt;. Bitte nehmt dieses Geschenk als Anerkennung Eurer loyalen Freundschaft.", rewards = "Robe des BlitzesGehärtete ZungentunikaHalsberge des BlitzschlägersBrustplatte des gezackten SteinsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29862] = {title = "Den Weg frei machen", objective = "Sturmbote Eljrrin in den Hallen der Blitze möchte, dass Ihr 3 sturmgeschmiedete Heiler, 3 sturmgeschmiedete Taktiker und General Bjarngrim tötet.", description = "Lokens Streitkräfte bereiten sich auf den Krieg vor. Sie rechnen allerdings nicht damit, selbst angegriffen zu werden.\n\nWir müssen rasch zuschlagen. Vernichtet General Bjarngrim und seine Armee, bevor sie alles Leben auf Azeroth gefährden!", progress = nil, completion = "Nur wenige außer uns werden je davon erfahren, aber Ihr habt an diesem Tag die Welt gerettet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29863] = {title = "Sturmbote Eljrrin", objective = "König Jokkum möchte, dass Ihr die Hallen der Blitze betretet und mit Sturmbote Eljrrin sprecht.", description = "Ich habe einen Abgesandten in die Hallen der Blitze geschickt, um Loken zu bedrängen.\n\nEr könnte zweifellos Hilfe gebrauchen, wenn man die Stärke von Lokens Armeen bedenkt. Unterstützt ihn so gut Ihr könnt, damit wir den Verräter endlich besiegen können.", progress = nil, completion = "Wir haben nicht viel Zeit. Loken bereitet sich bereits auf den Krieg vor.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29864] = {title = "Die Wurzel des Übels", objective = "Argentumbeichtpatin Blondlocke möchte, dass Ihr Svala Grabesleid tötet.", description = "Wir tun alles, um die Verluste, die uns die Kriegsmaschinerie der Geißel zufügt, zu minimieren.\n\nDie Vrykul gefährden diese Mission, indem sie sich willentlich den Truppen des Lichkönigs anschließen.\n\nBitte, <edler Held/edle Heldin>, besiegt ihre spirituelle Anführerin Svala, bevor sie ihr Volk in die ewigen Schatten führt!", progress = nil, completion = "Jeder Soldat, den wir der Geißel vorenthalten, bedeutet mehr als nur ein gerettetes Leben.\n\nDanke.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29865] = {title = "Die Seidenwaldstraße", objective = "Zerquetscht 8 Seidenholzpirscher.", description = "Westlich von hier befindet sich die Seidenwaldstraße. Es ist mittlerweile sehr gefährlich, sie zu bereisen, weil die Spinnen dort immer bösartiger, um nicht zu sagen \"gefräßiger\", geworden sind.\n\nIch würde sie ja herzlich gern selbst ausrotten, aber jemand muss ja den Nudelladen... öh... verteidigen...\n\nAlso, <junger Held/junge Heldin>, geht und zerquetscht diese Biester! Wenn Ihr Erfolg habt, werde ich Euch vielleicht mit einer meiner Heldensagen belohnen.\n\nUnd mit einer Bezahlung, versteht sich.", progress = nil, completion = "Was für ein edler Held Ihr doch seid. Ihr erinnert mich an mich selbst, als ich noch jünger und weniger gut aussehend war.", rewards = "NebelbernrobeSchwarzdickichtrobenJadehexenrüstungGlasseebrustschutzSeidenwaldrobeTiefenwaldtunikaFuchswäldchenrüstungDonnerholzbrustharnischJadetigerbrustharnischIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29866] = {title = "Seidenernte", objective = "Sammelt 7 makellose Seidenstränge.", description = "Ah, willkommen, <Reisender/Reisende>. Ich würde gern Eure Dienste in Anspruch nehmen!\n\nSyra Zapfgold ist auf der Suche nach etwas Seide. Ich selbst hasse ja Seide, weil sie sich immer in meinem Fell verfängt.\n\nAber ich möchte sie wirklich gern beeindrucken.\n\nWenn Ihr mir etwas Seide aus dem Seidenwald westlich von hier bringen könnt, werde ich Euch gerne dafür bezahlen.", progress = "Habt Ihr den Seidenwald gefunden?", completion = "Oh, vielen herzlichen Dank! Die sind perfekt!\n\nIch hoffe, Ihr habt Euch nicht so darin verfangen wie ich sonst immer.\n\nIch werde jetzt gleich zu Syra gehen und sie ihr geben!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLo Flammenbräu beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29871] = {title = "Der schlaue Ashyo", objective = "Findet den schlauen Ashyo.", description = "Ich weiß nicht, wo der schlaue Ashyo den Titel \"schlau\" herhat. Alle Jinyu sind nämlich schlau, und ich würde nicht behaupten, dass er klüger als die meisten anderen ist.\n\nEigentlich ist das Gegenteil der Fall.\n\nZumindest ist er ein fähiger Kämpfer. Im Tiankloster war er gut genug, um für unsere Trainingsmission ausgewählt zu werden.\n\nWenn Ihr ihm bei der Suche nach dem verborgenen Meister helfen wollt, findet Ihr ihn an der nördlichen Grenze des Tals.", progress = nil, completion = "Wo habe ich Euch schon einmal gesehen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29872] = {title = "Lin Zartpfote", objective = "Findet Lin Zartpfote.", description = "Lin hat mehr Talent, als sie selbst glaubt. Sie hat eine starke Faust, aber einen schwachen Geist. Mit etwas mehr Selbstvertrauen könnte sie besser sein als wir alle.\n\nVielleicht gewinnt sie bei ihrer Reise in den Westen an Selbstsicherheit. Wahrscheinlich ist sie gerade jetzt unterwegs nach Steinpflug. Haltet sie auf und redet mit ihr, wenn Ihr in jenem Teil des Tals seid.", progress = nil, completion = "Oh, Ihr seid es!\n\nNein, ich habe den verborgenen Meister noch nicht gefunden. Wahrscheinlich habe ich hier draußen nur meine Zeit vergeudet.\n\n&lt;Seufz...&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29873] = {title = "Ken-Ken", objective = "Sucht Ken-Ken.", description = "Achso... Ken-Ken. Der Ho-zen.\n\nIch selbst bin beeindruckt, dass er in seiner Ausbildung so weit gekommen ist. Er hat ein Hirn zwischen den Ohren, was mehr ist, als man über die meisten seines Volks sagen kann.\n\nEr sagte, er wollte Richtung Osten, und da wir bereits weit im Osten des Tals sind, kann ich mir nicht vorstellen, dass er allzu weit von hier entfernt sein kann. Sucht nach ihm bei Zhus Wacht in der Krasarangwildnis, den Weg runter in Richtung Süden. Seht nach, was er gefunden hat.", progress = nil, completion = "Dieser Ort... er... er so TRAURIG!\n\nKen-Ken noch nie einen so traurigen Ort gesehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29874] = {title = "Kang Dornstab", objective = "Sucht Kang Dornstab.", description = "Kangs Stolz wird regelmäßig zu Vermessenheit, was ihn oft auf gefährliche Pfade führt. Sein momentaner Pfad ist eben solch ein gefährlicher - er führt tief in die Krasarangwildnis.\n\nIch würde normalerweise <einen Fremden/eine Fremde> nicht um einen Gefallen bitten, aber... würdet Ihr Euch vergewissern, dass es ihm gut geht? Es wäre eine Erleichterung für mich, zu wissen, dass <ein mutiger/eine mutige:r> <Volk> nach ihm sieht.", progress = nil, completion = "Ich bin ziemlich sicher, dass diese Siedlung vor ein paar Wochen noch nicht hier war. Wo sind diese Leute hergekommen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29875] = {title = "Kang Dornstab", objective = "Sucht Kang Dornstab.", description = "Kangs Stolz wird regelmäßig zu Vermessenheit, was ihn oft auf gefährliche Pfade führt. Sein momentaner Pfad ist eben solch ein gefährlicher - er führt tief in die Krasarangwildnis.\n\nIch würde normalerweise <einen Fremden/eine Fremde> nicht um einen Gefallen bitten, aber... würdet Ihr Euch vergewissern, dass es ihm gut geht? Es wäre eine Erleichterung für mich, zu wissen, dass <ein mutiger/eine mutige:r> <Volk> nach ihm sieht.", progress = nil, completion = "Ich bin ziemlich sicher, dass diese Siedlung vor ein paar Wochen noch nicht hier war. Wo sind diese Leute hergekommen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29877] = {title = "Grundwissen mangelhaft", objective = "Grabt 7 Landwirtschaftswerkzeuge aus.", description = "Shed-Ling - die tun mehr, als nur unsere Nahrung fressen. Die wollen ihre eigenen Höfe gründen. Das Problem is' nur... Das sind alle verfiddelt taube Nüsse.\n\nDu glaubst Muno nicht? Gestern Nacht sind sie in unsere Werkzeugschuppen eingebrochen... ha'm das meiste rausgeklaut. Als wir aufgewacht sind, fanden wir Harken und Schubkarren im Boden.\n\nDie wollten das BEWÄSSERN. Die wollten SCHUBKARREN ANBAUEN.\n\nBitte grabe unsere Sachen aus, wenn du dort draußen bist.", progress = "Mann, diese Shed-Ling sind völlig hohl.", completion = "Danke. Vielleicht kann ein Ho-zen jetzt endlich mal seiner verfiddelten Arbeit nachgehen.", rewards = "Ihr bekommt:\n\nWassermelonenbombe"}
MultiLanguageQuestData['de'][29879] = {title = "Im Ganzen verschlungen", objective = "Befreit 5 Ho-zen aus dem Inneren vollgefressener Krokilisken und sammelt 5 Bachsaiblinge am Kittitatasee.", description = "Zurück zu Eurem Dilemma.\n\nIch glaube, Ihr könnt eurem Volk helfen, eine Beziehung zu unseren Ho-zen aufzubauen, so wie es auch unser Volk getan hat.\n\nDer Pfad hinter mir wird Euch zu einem See führen, aus dem die Ho-zen ihre Fische beziehen.\n\nJedes Jahr zu dieser Zeit gibt es in dem See furchterregende Biester, denen viele hungrige Ho-zen zum Opfer fallen.\n\nWenn Ihr einige der Opfer retten und ein paar Fische sammeln könntet, würden die Ho-zen Euch vielleicht freundlicher gesinnt sein.", progress = "Nappel hat Glitschis... für mich!?", completion = "Nappel hat Ho-zen gerettet? Und Glitschis gebracht?\n\nHmm, vielleicht Nappel doch nicht so böse.\n\nTuki Tuki hat Djuuk Uukem sowieso noch nie gemocht...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29881] = {title = "Die perfekte Farbe", objective = "Sammelt 8 frisch gefallene Blütenblätter.", description = "Wie Ihr gesehen habt, gibt es in diesem Hain wunderschöne rosafarbene Blüten. Wenn die Blütenblätter welken, wird der Ton dunkler und verblasst.\n\nWärt Ihr so freundlich, mir einige frisch abgefallene Blütenblätter zu bringen? Nur die, die gerade herabgefallen sind, haben genau die Farbe, die ich brauche.\n\nDaraus kann ich eine atemberaubende Tinte herstellen. Werdet Ihr mir helfen?", progress = "Wenn ein Blütenblatt abfällt, bleibt nur wenig Zeit, in der es für den perfekten Farbton verwendet werden kann.", completion = "Ah! Ihr habt ein gutes Auge für Farben. Daraus lässt sich ein hervorragendes Pigment herstellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29882] = {title = "Feder aus Stacheln", objective = "Sammelt 6 Wespenstachel von Obstgartenwespen.", description = "Für den perfekten Pinselstrich braucht man auch das richtige Werkzeug. Meine eigenen Pinsel lassen sich nicht mehr reparieren, die Borsten sind so unnachgiebig wie Ho-zen-Haar geworden.\n\nHabt Ihr die Wespen im Arboretum gesehen? Aus ihren Stacheln kann man Schreibfedern herstellen, die sich für jeden Schärfegrad eignen.\n\nKönntet Ihr mir bitte einige besorgen?", progress = "Habt Ihr einige Stachel gefunden? Normalerweise würde ich einen Mönch darum bitten, aber die scheinen alle beschäftigt zu sein.", completion = "Vielen Dank. Daraus lassen sich schöne Schreibfedern herstellen. Hier habt Ihr etwas für Eure Mühe.", rewards = "NebelberngamaschenSchwarzdickichtbeinschützerJadehexenbeinschützerGlasseebeinplattenSeidenwaldhosenTiefenwaldbeinschützerFuchswäldchenbeinschützerDonnerholzbeinschützerJadetigerbeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29883] = {title = "Das Perlflossenproblem", objective = "Sprecht mit dem Ältesten Lusshan, Perlenhüter Fujin, Ausbilder Scharffinne und Ot-Temmdo im Dorf der Perlflossen.", description = "Ich habe nachgedacht.\n\nWir sind hier von aller Versorgung abgeschnitten und weit weg von zu Hause.\n\nZwar scheinen uns diese Perlflossen-Jinyu zu misstrauen, aber sie wirken nicht feindselig.\n\nWenn wir sie davon überzeugen können, dass wir ihre Freunde sind, könnte sich ein Bündnis zwischen unseren Völkern als sehr wertvoll erweisen.\n\n<Name>, Ihr müsst mit den Jinyu im Dorf sprechen.\n\nÜberzeugt ihre Anführer, dass sie uns nicht fürchten müssen und dass wir nichts als Frieden wollen.", progress = nil, completion = "Anscheinend habt Ihr einen guten Eindruck gemacht.\n\nIch bin beeindruckt, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29885] = {title = "Wegzehrung", objective = "Besorgt 6 Schildkrötenflanken.", description = "Wir haben keine Zeit, um hier zu warten, bis sich der Admiral erholt hat.\n\nSully und ich werden im Norden nach Anduin suchen, aber wir benötigen Vorräte für die Reise.\n\nIm See hier wimmelt es von Tieren, die wir jagen dürfen.\n\nSammelt einige Vorräte, während Sully und ich die letzten Vorbereitungen treffen.", progress = "Die Zeit ist knapp. Mit jeder Stunde, die wir verlieren, kann der Weiße Bauer weiter weg sein.\n\nWo sind die Vorräte, um die ich gebeten habe?", completion = "Das dürfte genug sein, &lt;Name&gt;. Danke.", rewards = "Ihr bekommt:\n\nSchildkrötendörrfleisch"}
MultiLanguageQuestData['de'][29886] = {title = "Zenheilung", objective = "Sammelt 6 Zenlotus.", description = "Euer Freund Taylor ist in einem schlechten Zustand. Seine Wunden sind mit Ho-zen-Gift verunreinigt worden, das sehr schwer zu heilen ist.\n\nZum Glück hat mein Volk, das seit vielen Generationen gegen die Ho-zen kämpft, Medizin gegen solche Wunden entwickelt.\n\nDie Blumen, die auf der Oberfläche des Perlsees rings um unser Dorf wachsen, werden für das Gegenmittel benötigt.\n\n<Name>, geht schnell und bringt mir ein paar Blüten. Das Leben Eures Admirals steht auf dem Spiel.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29887] = {title = "Die Instrumente des Ältesten", objective = "Holt den Stab des Wassersprechers, die zeremoniellen Roben, die Jadekrone und die Rosenholzperlen von den Langfingern der Schlingschwänze zurück.", description = "Oje, oje... Der Älteste darf es nicht erfahren!\n\nIch muss bei der Flucht die zeremoniellen Instrumente des Ältesten vergessen haben.\n\nAber... die Mondwasserzuflucht ist jetzt voller Ho-zen!\n\nWas bin ich nur für ein Perlenhüter, dass ich sie einfach zurücklasse?\n\n<Der alte Jinyu vergräbt sein Gesicht in den Händen.>\n\nKönnt Ihr mir wohl helfen?", progress = "Der Älteste ist ein Wassersprecher. Er spricht mit dem Wasser, und es antwortet.", completion = "Ihr habt alles gefunden? Oh, den Geistern des Wassers sei Dank!\n\nIhr habt mir die Schwanzflosse gerettet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29888] = {title = "Den Lehrensucher aufsuchen", objective = "Findet Lehrensucher Cho im Pavillon des Träumers im Jadewald.", description = "Mir ist aufgefallen, dass Ihr und Eure Leute verzweifelt nach Eurem Prinzen Anduin sucht.\n\nIch kenne jemanden, der Euch vielleicht helfen kann, ein Lehrensucher der Pandaren, der dieses Land besser kennt als jeder andere. Ich weiß nicht, wie er Euch empfangen wird, aber er wird Euch mit ziemlicher Sicherheit genauso neugierig begegnen wie Ihr ihm!\n\nDer Lehrensucher lebt im Wald im Südwesten. Sagt ihm, dass Euch die Perlflossen schicken.", progress = nil, completion = "Ihr seht Euch bei dem leeren Haus um.\n\nEs scheint, als wäret Ihr am richtigen Ort, doch vom Bewohner ist nichts zu sehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29889] = {title = "Geborgtes Gebräu", objective = "Kostet das köstliche Gebräu.", description = "Der Flasche auf dem Tisch entströmt ein köstlicher Duft.\n\nEin kleiner Schluck kann doch nicht schaden, oder?", progress = nil, completion = "Ich habe gehört, dass solche wie Ihr an unsere Strände gespült worden sind, aber ich hätte nicht erwartet, dass ich einen von Euch direkt vor meiner Haustür finden würde! Was bringt Euch hierher, Fremder?\n\n&lt;Ihr erklärt dem Pandaren Eure Suche nach Prinz Anduin und beschreibt ihm den Jungen.&gt;\n\nSehr interessant! Und die Perlflossen haben Euch zu mir geschickt, was?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29890] = {title = "Die innere Mitte finden", objective = "Meditiert mit Lehrensucher Cho im Pavillon des Träumers im Jadewald.", description = "Das Traumgebräu ist vollendet! Wenn Ihr es dieses Mal trinkt, müsst Ihr die Visionen, die Ihr seht, mit einem inneren Fokus betrachten.\n\nFolgt mir zu meiner Pagode und ich werde Euch lehren, wie Ihr die innere Ruhe erreichen könnt, die uns Pandaren so wichtig ist.\n\nEuer aufgewühltes Gemüt wird Euch viele Ablenkungen präsentieren, doch vergesst nicht, Euch auf Eure innere Mitte zu konzentrieren!", progress = nil, completion = "Wie habt Ihr mich gefunden?\n\n&lt;Anduin hört zu, wie Ihr die durch das Traumgebräu hervorgerufene Vision beschreibt.&gt;\n\nDas ist ja erstaunlich! Genau das ist vor einigen Tagen passiert. Seitdem haben wir uns versteckt gehalten.", rewards = "FreundschaftsringBand der AkzeptanzBand der freundlichen GabeBand der BegabungBand der FundeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29891] = {title = "Ein starkes Gebräu", objective = "Tötet Nebelkrabbler, bis ein Nebelschrecken erscheint, und nehmt ein Nebelschreckenherz an Euch.", description = "Für die Herstellung des Traumgebräus benötigen wir mehrere Zutaten.\n\nUm die Stärke zu verbessern, brauche ich eine Zutat von einer schaurigen Kreatur, dem legendären Nebelschrecken.\n\nAngeblich erscheint diese Kreatur nur dort, wo der Nebel am dichtesten ist.\n\nIm Norden und Osten findet Ihr kleinere Nebelkrabbler in den Sümpfen. Vernichtet diese Kreaturen, bis der Nebelschrecken erscheint, und bringt mir dann sein Herz.", progress = "Die Nebel scheinen einen eigenen Willen zu besitzen, was?", completion = "Das ist ein unglaubliches Exemplar! Ich bin überrascht, dass Ihr tatsächlich erfolgreich wart.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29892] = {title = "Körper", objective = "Sammelt 5 makellose Krokiliskenaugen von Sumpfkrokilisken.", description = "Der Körper eines Gebräus ist wichtig und bleibt allzu häufig unbeachtet.\n\nUm die perfekte Konsistenz zu erhalten, benötige ich makellose Augen von Sumpfkrokilisken aus dem Osten.\n\nGebt Acht. Diese Kreaturen sind ziemlich grausam.", progress = "Passt im Sumpf gut auf Euch auf, mein neuer Freund.", completion = "Gibt es da, wo Ihr herkommt, auch Krokilisken?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29893] = {title = "Färbung", objective = "Sammelt 8 Bernfliegenflügel.", description = "Das Auffälligste am Traumgebräu ist seine leuchtende traumartige Farbe.\n\nIm Osten könnt Ihr schillernde Bernfliegen finden. Ich benötige ihre Flügel, um die letzte Leuchtfarbe des Gebräus herzustellen.\n\nNehmt dieses Messer und schneidet damit 8 Flügel ab.", progress = "Habt Ihr die Zutaten besorgt? Es ist fast an der Zeit, das Traumgebräu herzustellen.", completion = "Eine wunderschöne Farbe, seltene Transparenz, schimmernd, aber nicht funkelnd… Sie sind hervorragend.\n\nSo langsam erkenne ich ein großes Potenzial in Euch, Fremdling.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29894] = {title = "Geister des Wassers", objective = "Sprecht mit dem Ältesten Lusshan und werdet Zeuge der Wassersprechzeremonie.", description = "Unser Krieg gegen die Ho-zen scheint endlos zu sein, und die Zukunft unseres Stammes ist ungewiss.\n\nDarum hat unser Wassersprecher beschlossen, um die Weisheit des Wassers zu ersuchen.\n\nDer Älteste Lusshan wartet. Bitte bringt ihm die Instrumente, damit sie beginnen können.", progress = "<Die Augen des Ältesten verklären sich. Sein Blick wird nach innen gekehrt, in Richtung des Wissens, das er gewonnen hat.>", completion = "Ich habe die Vision gesehen, &lt;Name&gt;. Was hat sie Eurer Meinung nach zu bedeuten?\n\nEs ist offensichtlich, dass Ihr eine Rolle darin spielt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29895] = {title = "Die Spur des Weißen Bauern", objective = "Zeigt Admiral Taylor im Dorf der Perlflossen im Jadewald den Mantel.\n\nBereitgestellter Gegenstand: \n", description = "Der Mantel ist zwar zerschlissen und zerrissen, aber die feine Machart und das königliche Wappen sind unverkennbar.\n\nIhr solltet ihn Eurem Kommandanten der Allianz zeigen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29898] = {title = "Heiliges Wasser", objective = "Holt heilendes Wasser aus den vier heiligen Schalen in der Höhle der Trauer.", description = "Ich bin dankbar dafür, dass Ihr den weiten Weg gemacht habt, um mich zu retten, aber Ren ist schwer verletzt.\n\nDer alte Pandaren hatte keinen Grund, mir zu helfen, und doch hat er für mich sein Leben riskiert.\n\nVor Ausbruch des Fiebers erwähnte er, dass es in der Höhle am Fuße des Hügels heilendes Wasser gäbe.\n\nEs ist gefährlich, aber ich würde alles tun, um meinem Freund zu helfen. Werdet Ihr mir dabei helfen, das Wasser zu holen?", progress = "Vielleicht könnte ich etwas von diesem heilenden Wasser mit nach Sturmwind nehmen.", completion = "Das heilende Wasser müsste Rens Fieber kurzfristig senken, aber das ist keine dauerhafte Lösung.\n\nVielen Dank, &lt;Klasse&gt;. Wir haben ihm wenigstens etwas mehr Zeit verschafft.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLaunch A Prince's Decision\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29899] = {title = "Ruhet in Frieden", objective = "Tötet 6 gepeinigte Geister.", description = "Die Geister... die Höhlenbewohner... sie schreien vor Schmerzen... \n\nGefangen... in dieser Welt... können sich nicht... zur nächsten bewegen.\n\nIch... werde verrückt... solange ich… ihre Schreie höre... \n\nBitte… bringt sie... zum Schweigen.", progress = nil, completion = "Vielen Dank… Ich bin… froh… da ich weiß… dass die Geister… Frieden gefunden haben.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLaunch A Prince's Decision\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29900] = {title = "Eine alte Legende", objective = "Holt den Gesang des Tals aus der Höhle der Trauer.", description = "Mein Vater hat sein Leben dem Studium des Tals der Ewigen Blüten gewidmet.\n\nDas Tal ist ein mystischer Ort, vollkommen abgeschieden nach der Revolution der Pandaren vor 12.000 Jahren. Wir wissen so wenig darüber.\n\nMein Vater ist einigen Hinweisen bis zu der Höhle am Fuße des Hügels gefolgt. Darin befindet sich ein sehr altes Gedicht, das als der Gesang des Tals bekannt ist, aber er kann es nicht an sich nehmen. Es wird von einer Art Geist der Ahnen bewacht.\n\nWenn Ihr ohnehin in diese Richtung wollt, könnt Ihr es ihm dann vielleicht bringen?", progress = "Habt Ihr… die Schriftrolle gefunden?", completion = "Oh… Das ist das Gedicht! Habt Ihr… es gelesen? Wo liegt… das Tal?", rewards = "NebelbernmanschettenSchwarzdickichtbindungenJadehexenhandgelenksschützerGlasseearmschienenSeidenwaldmanschettenTiefenwaldarmwickelFuchswäldchenhandgelenksschützerDonnerholzarmplattenJadetigerarmplattenDer folgende Zauber wird auf euch gewirkt:\n\nLaunch A Prince's Decision\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29901] = {title = "Anduins Entscheidung", objective = "Sagt Anduin, dass es Zeit ist, nach Hause zurückzukehren.", description = "Ihr habt für die Freunde des Prinzen getan, was Ihr könnt.\n\nIhr habt Eure Mission erfüllt und den Weißen Bauern gefunden: Prinz Anduin. Admiral Taylor und die anderen SI:7-Agenten werden darauf brennen, den Jungen in Gewahrsam zu nehmen.\n\nEs ist Zeit, nach Hause zurückzukehren.", progress = nil, completion = "Er hat WAS gemacht?!?\n\nEr hat Glück, dass ich ihn noch nicht gefunden habe, denn sonst hätte ich ihm den Kopf abgerissen!\n\nWas denkt er sich nur... dieses Tal zu suchen... Das ist kein Verhalten, das eines Prinzen würdig ist!\n\nHätten wir nicht Dringenderes zu erledigen, würde ich unsere gesamte Flotte hinter ihm herschicken!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29903] = {title = "Passt perfekt", objective = "Sprecht mit den Aqualythen der Perlflossen und stattet sie mit der richtigen Ausrüstung aus.", description = "Der Älteste Lusshan und ich sind uns einig, dass wir zusammenarbeiten sollten.\n\nWir werden unser überlegenes militärisches Wissen und unsere Waffen mit den Perlflossen teilen.\n\nDafür haben wir einen mächtigen Verbündeten, falls wir erneut auf die Horde treffen.\n\nNehmt diese Kiste mit Ausrüstungsgegenständen und Waffen. Ihr müsst durch das Dorf gehen und die Jinyu entsprechend ihrer Fähigkeiten mit Waffen ausstatten.", progress = "Die Jinyu sind unterschiedlich begabt. Es liegt an uns, ihre Stärken herauszufinden.", completion = "Gut. Jetzt können die Bastarde von der Horde ruhig wieder auftauchen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29904] = {title = "Größere Fische", objective = "Bildet die Adepten der Perlflossen aus, indem Ihr 24 Tiere in der Bambuswildnis erlegt.", description = "Ich habe eine Gruppe aus vielversprechenden Schülern der Perlflossen zusammengestellt, die Kampferfahrung brauchen.\n\nGeht mit ihnen in den Nordosten in die Bambuswildnis und erlegt alle Tiere, auf die Ihr trefft.\n\nKommt erst zurück, wenn sie bereit für den Kampf sind.", progress = "Wie machen sich die Schüler?", completion = "Eure Schüler sind vor Kurzem zurückgekehrt. Ich konnte es kaum glauben! Das waren nicht mehr dieselben Jinyu, mit denen Ihr aufgebrochen seid.\n\nHervorragende Arbeit, &lt;Klasse&gt;. Das hätte ich nicht besser machen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29905] = {title = "Lasst sie brennen", objective = "Vernichtet 15 Flotsch-Verstärkungen oder Schlingschwanz-Rekruten.", description = "Vorhutsspäher haben gemeldet, dass sich die Ho-zen in den Schlingschwanzgruben mit Verstärkung aus den Stämmen im Norden vereinen.\n\nUnsere Truppen machen sich am Kamm im Nordwesten kampfbereit und warten nur noch auf Euch.\n\nJetzt können wir ihnen zeigen, aus welchem Holz wir geschnitzt sind, und sie endgültig vernichten.", progress = nil, completion = "Das Wasser hatte in Bezug auf Euch recht, &lt;Name&gt;. Dank Eurer Bemühungen hat dieses Dorf eine Zukunft. Wir werden nie vergessen, was Ihr uns gelehrt habt, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\nFischi"}
MultiLanguageQuestData['de'][29906] = {title = "Carpe Diem", objective = "Vernichtet Häuptling Gukgut.", description = "Auch wenn die Ho-zen unkoordiniert erscheinen, steckt eine Ordnung hinter dem Chaos. Ihr Anführer, Häuptling Gukgut, ist der gerissene Lenker ihrer Angriffe.\n\nEr organisiert sie bei der großen Grube im Ho-zen-Lager im Nordwesten.\n\nSchlagt jetzt zu und zeigt keine Gnade, <Name>, denn das würde er auch nicht tun.", progress = nil, completion = "Ohne ihren Anführer wird bei den Ho-zen erneut das Chaos ausbrechen.\n\nHeute genießen wir unseren Sieg! &lt;Name&gt;, Ihr kamt als ein Fremder zu uns, doch Ihr verlasst uns als Freund.\n\nVon jetzt an seid Ihr hier außerordentlich geschätzt - als Freund und Verteidiger des Perlflossenstammes.", rewards = "JinyumeditationsstabJinyuwünschelruteJinyukampfstabJinyugroßschwertJinyuhandaxtJinyuarmbrustJinyukampfaxtJinyuszepterJinyudolchJinyuschlachtstreitkolbenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29907] = {title = "Chen und Li Li", objective = "Folgt Chen Sturmbräu zu Pangs Hof.", description = "Meine Nichte und ich sind neu hier in Pandaria. Genau wie Ihr vermutlich. Wir kommen von der Wandernden Insel und sind nur zu Besuch hier. Eigentlich wissen wir gar nicht, wohin wir gehen wollen.\n\nAuf dem Hof dort könnten wir uns doch ausruhen und etwas trinken. Was meinst du, Li Li?\n\nMöchtet Ihr uns nicht vielleicht ein Stück des Weges begleiten, <Volk>?", progress = nil, completion = "Herzlich willkommen, liebe Besucher! Möchtet Ihr die Rüben meines Sohnes probieren? Oder vielleicht ein paar Schweine kaufen?\n\nBitte fühlt Euch ganz wie zu Hause. Ich habe hier jede Menge Platz.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29908] = {title = "Ein schier unendliches Ärgernis", objective = "Tötet 8 Raffzahn-Shed-Ling, Werkzeugdiebe oder Unruhestifter. Tötet dann 18 Raffzahnnervensägen.", description = "Ich muss mich für den Zustand hier entschuldigen. Die Shed-Ling, diese kaninchenartigen Kreaturen vom Fuße der Berge, sind immer weiter auf den Hof meiner Familie vorgedrungen und haben unsere Erntepflanzen, die übrigens normalerweise viel größer und viel leckerer sind, geschädigt.\n\nIch bin kein Soldat... Aber Ihr seht aus wie einer! Könntet Ihr nicht ein paar dieser Shed-Ling von unserem Land vertreiben?", progress = nil, completion = "&lt;Pang untersucht die nähere Umgebung seines Hofes.&gt;\n\nTja, sie sind zwar nicht ALLE weg, aber zumindest sind es jetzt weniger. Und sie halten auch ihre Ohren nicht mehr ganz so hoch.\n\nIch glaube, sie haben Angst vor Euch, &lt;Name&gt;.", rewards = "Satingamaschen des SeidenmeistersSonnenbeschienene BeinschützerSchuppengamaschen des HuangtzeBrünierte PaoquanbeinplattenSeidene Hosen des GoldfächersEbenenfalkenbeinschützerBeinschützer der Wilden EbenenSchwere DonnerfußbeinschützerGepanzerte SonnensangbeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29909] = {title = "Geringe Rübenausbeute", objective = "Findet Ang Donnerfuß.", description = "Ich weiß Eure Hilfe wirklich sehr zu schätzen, <Name>. Und ich hätte noch eine weitere Aufgabe für Euch.\n\nMein Sohn, Ang, betreibt einen kleinen Hof am Fuße dieses Hügels. Er hätte mir heute morgen ein paar Früchte und etwas Gemüse bringen sollen, aber er ist bis jetzt noch nicht aufgetaucht.\n\nWürdet Ihr vielleicht dort runtergehen und mal nachsehen, was da los ist?", progress = nil, completion = "Was? Wer seid...? Mein Vater hat Euch geschickt?\n\nPah... Er kann ja manchmal so neugierig sein. Ich habe hier alles unter Kontrolle.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29910] = {title = "Miese Murmler", objective = "Vertreibt 6 mollige Murmeltiere vom Donnerfußhof und verschließt 6 Murmeltierbaue.", description = "Ich bin heute morgen losgegangen, um meinem Vater beim Kampf gegen die Shed-Ling zuzusehen. Und als ich zurückkam, war der Hof voller Murmeltiere!\n\nIch will sie gar nicht töten, aber wir müssen sie trotzdem loswerden. Hey, ich hab' eine Idee! Wir könnten doch ihre Baue verschließen!\n\nStopft etwas Dreck in die Löcher, damit sie nicht mehr auf dem Gelände unseres Hofes rauskommen.", progress = "Die Murmeltiere werden sich nicht darüber freuen, dass Ihr ihre Baue verschließt.", completion = "Ich danke Euch, guter Mann! Jetzt kann ich mich wieder meinen Pflichten widmen.", rewards = "Ihr bekommt:\n\nPlumpes Murmeltier"}
MultiLanguageQuestData['de'][29911] = {title = "Praktisch perfekte Produkte", objective = "Bringt die Kiste mit frischem Obst und Gemüse zu Pang Donnerfuß.", description = "Bitte, <Name>. Das wird meinem Vater gefallen.\n\nDanke nochmals für Eure Hilfe mit den Shed-Ling.", progress = "Rieche ich da etwa Rüben?", completion = "Ho ho! Na, so etwas sehe ich gerne!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29912] = {title = "Fantastisches Fräulein Fanny", objective = "Bringt Angs riesige rosa Rübe, Angs Sommerwassermelone und Pangs besonders scharfen Tofu zu Fräulein Fanny, und bittet sie darum, sie zu befördern. Das Essen muss zum Gehöft Donnerfuß gebracht werden.", description = "Der Großteil dieses Gemüses wird zwar verkauft, aber etwas davon möchte ich für meine Familie behalten. Insbesondere mein Neffe Liang braucht etwas zum Füttern seiner Schweine.\n\nLeider wimmelt es auf dem Weg zu Liangs Hof nur so vor Raffzahn-Shed-Ling. Wir müssen Fräulein Fanny um Hilfe bitten.\n\nBringt etwas von dem Essen, das wir gesammelt haben, zu Fräulein Fanny, die neben meinem Haus steht. Bittet sie dann - NETT! - darum, es zu Liangs Hof zu befördern.", progress = nil, completion = "Wie ich sehe, habt Ihr das Essen vom Hof meines Onkels hierher geschickt. Vielen Dank.\n\nMeine Schweine sind wählerisch, aber diese Rüben und Melonen gehören zu ihrem Lieblingsessen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29913] = {title = "Fleisch um jeden Preis", objective = "Besorgt 4 Mushanschulterstücke und 80 Fetzen Schildkrötenfleisch.", description = "Wie ich bereits sagte, sind meine Schweine sehr wählerisch. Sie brauchen Fleisch, um stark zu werden, aber sie mögen kein Hammelfleisch und kein Yak-Fleisch - und Schweinefleisch will ich ihnen schon gar nicht vorsetzen.\n\nSie fressen allerdings Mushan-Fleisch und mögen Schildkröten. Beides findet Ihr in großer Zahl im Westen.\n\nMeine Jagdfähigkeiten sind zugegebenermaßen ziemlich dürftig. Könnt Ihr einem jungen Bauern und seinen Schweinen helfen?", progress = "Es tut mir weh, sie vor Hunger quieken zu hören.\n\nWenn man eine Zeit lang Schweinebauer ist, erkennt man den Unterschied zu normalem Quieken.", completion = "&lt;Liang sieht sich das Fleisch an.&gt;\n\nIhr seid nicht nur ein &lt;Klasse&gt;, sondern wohl auch ein Metzger, oder? Ihr habt ein Auge für hochwertige Schweinenahrung, Nachbar.", rewards = "EbenenfalkenkappeKopfschutz der Wilden EbenenSeidene Kappe des GoldfächersSatinkappe des SeidenmeistersSonnenbeschienene KappeSchuppenkopfschutz des HuangtzeBrünierte PaoquankappeGepanzerte SonnensangkappeSchwere DonnerfußkappeDer folgende Zauber wird auf euch gewirkt:\n\nFleisch werfen\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29914] = {title = "Zurück in den Stall", objective = "Sucht Jian, Ling und Stinki.", description = "Ich versuche stets, meine Tiere im Auge zu behalten, aber ab und zu büchst doch eins aus. Bei dem ganzen Chaos, das die Shed-Ling verursachen, wurde ich wohl für einen Moment etwas unachtsam und einige meiner Schweine konnten entkommen.\n\nWürdet Ihr sie für mich suchen? Ich würde als Erstes den Hügel runter Richtung Westen gehen.", progress = "Habt Ihr sie gefunden? Ich glaube, es fehlen drei.", completion = "Da sind sie ja! Los, zurück in den Schweinestall ihr drei!\n\n&lt;Liang sieht zu Euch hoch.&gt;\n\nVielen Dank, Nachbar. Ich weiß Eure Hilfe wirklich zu schätzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29915] = {title = "Nachbarschaftliche Pflichten", objective = "Bringt das entlaufene Lamm zu Francis dem Hirtenjungen.", description = "Ich bin wohl nicht der Einzige, der Probleme mit seinen Tieren hat. Eins von Francis' Schafen ist diese Woche schon zum dritten Mal zu mir auf den Hof gekommen. Vielleicht braucht er Hilfe beim Hüten seiner Herde?\n\nIhr solltet ihm einen Besuch abstatten, <Nachbar/Nachbarin>. Und nehmt bitte dieses arme Ding mit.", progress = "Oh... Ihr habt eines meiner... meiner Lämmer?", completion = "Ihr hättet das Lamm wirklich nicht zu mir zurückbringen sollen. Es... Es war im Schweinestall sicherer aufgehoben als hier.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29916] = {title = "Schneidende Krallen und geifernde Schnäbel", objective = "Tötet 5 diebische Ebenenfalken und 6 diebische Wölfe.", description = "Zuerst kamen die Falken. Ihr habt bestimmt welche am Himmel kreisen sehen.\n\nKurz darauf folgten dann die Wölfe. Ich schätze, sie haben gerochen, dass ich schwach bin.\n\nIch bin nicht im Ansatz so tapfer, wie Meister Shang es dachte. Der Meister wird sich sehr über mich ärgern, wenn ich nichts gegen diese Bedrohungen unternehme.\n\nKönnt... könnt Ihr mir vielleicht helfen, <mein Herr/meine Dame>?", progress = nil, completion = "Sie... sie haben nicht aufgehört, aber zumindest haben wir uns zur Wehr gesetzt. Stimmt's?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29917] = {title = "Lupello", objective = "Tötet Lupello.", description = "Ich habe nachgedacht... Die Wölfe hören mit ihren Angriffen vielleicht auf, wenn wir ihren Leitwolf töten.\n\nWir nennen ihn Lupello, und er streift am gegenüberliegenden Ufer entlang.\n\n<Francis' Aufmerksamkeit wird von einem weiteren Angriff in Beschlag genommen. Vielleicht solltet Ihr Euch selbst um Lupello kümmern.>", progress = nil, completion = "Ich weiß, dass eigentlich ich gegen sie kämpfen sollte. Ich scheine wohl einfach nicht zum Hüten von Schafen geboren zu sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29918] = {title = "Eine Lektion in Sachen Tapferkeit", objective = "Verwendet das Viehhüterlasso, um einen großen weißen Ebenenfalken einzufangen und zu töten.", description = "<Meister Shang spricht mit seinem Hirtenjungen.>\n\nFrancis, du musst Tapferkeit zeigen! Du hast alles, was man braucht, um ein guter Hirte zu sein - du musst dich nur deinen Ängsten stellen!\n\n<Er sieht zu Euch rüber.>\n\nHeh, Ihr! Ihr habt doch schon dem Rest meiner Familie geholfen. Francis ist wie ein zweiter Sohn für mich.\n\nZeigt meinem Schüler, was Furchtlosigkeit bedeutet. Besiegt mit diesem Seil einen der großen weißen Falken über uns.\n\n<Shang zeigt zum Himmel, blickt zu Francis und geht.>", progress = "Ihr seid furchtlos. Das kann ich in Eurem Herzen spüren.", completion = "Francis braucht länger, als ich gedacht habe, um ein guter Hirte zu werden. Wir alle durchlaufen solche Phasen... Auch mein Sohn Liang war einmal schwach. Genauso wie ich.\n\nAber er wird es lernen. Das ist der Weg der Donnerfußens.", rewards = "FalkenfederbandLassoschleifeSchleife des HirtenBand des HeldenmutsRing der TapferkeitIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29919] = {title = "Zwei Dumme, ein Getränk", objective = "Begleitet Chen Sturmbräu und Li Li zur Brauerei im Südwesten.", description = "Oh, hallo, <Name>. Das ist jetzt schon das vierte Mal, dass wir uns begegnen, oder?\n\nNun... mein Fässchen wird ziemlich schnell immer leerer. Ich habe von einer Brauerei im Südwesten gehört. Wir sind auf dem Weg dorthin. Wollt Ihr uns begleiten?", progress = nil, completion = "Wenn Ihr Bier sucht, seid Ihr hier genau richtig, Nachbar.\n\nHm, ähm... entschuldigt das Durcheinander. Hatte in den letzten Tagen ein Problem mit Shed-Ling.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29920] = {title = "Die Erlaubnis erhalten", objective = "Fordert Pandriarch Zapfgold, Pandriarch Windpelz und Pandriarch Dornstab heraus und besiegt sie.", description = "Mein Schatz Lo hat um die Erlaubnis der Pandriarchen ersucht, mich heiraten zu dürfen. Obwohl sie sich in anderen Sphären befinden, würde ihre Zustimmung uns viel bedeuten.\n\nDa sie jedoch Geister sind, konnten sie weder unsere Geschenke noch unsere Tribute beeindrucken. Um ihre Gunst zu gewinnen, verlangen sie, dass entweder Lo oder ein Champion einen der ihren im Kampf besiegt.\n\nLo ist ein guter Mann, aber kein Kämpfer.\n\nWollt Ihr unser Champion sein?", progress = "Die Pandriarchen haben sich ihren Ruf im Leben erworben und danach beibehalten. Ich weiß beim besten Willen nicht, wie Ihr sie besiegen wollt.", completion = "Sie… Sie haben zugestimmt?! Großartig! Vielen Dank! Dank ihres Segens werden wir die glücklichsten Pandaren des ganzen Landes sein!\n\nBitte nehmt das. Es sollte eigentlich ein Tribut an die Pandriarchen sein, aber sie waren nicht interessiert.", rewards = "ZenlotusanängerHalskette von MorgenblüteAnhänger des TalgesangsGrünsteinanhängerJadeaugenanhängerDer folgende Zauber wird auf euch gewirkt:\n\nLo Flammenbräu beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29922] = {title = "Auf der Suche nach Weisheit", objective = "Sprecht mit Drachenmeister Ut-Nam, um nach Morgenblüte zu gelangen.", description = "Lehrensucher Cho hat während Eurer Abwesenheit nach Euch gefragt.\n\nEr braucht dringend Eure Hilfe im Ort Morgenblüte im Norden. Den Grund dafür hat er nicht genannt.\n\nSprecht mit Drachenmeister Ut-Nam. Er wird Euch mit Freuden dorthinschicken.", progress = nil, completion = "Eure Taten haben eine längst vergessene Erinnerung an eine uralte Prophezeiung hervorgerufen. Das muss untersucht werden.\n\nFür die Untersuchung benötige ich allerdings Jade. Ich habe Toya gebeten, so viel zu sammeln, wie er kann, und sie Euch zu geben, sobald er fertig ist. Bringt sie mir und wir werden versuchen, das uralte \"Omen des Kaisers\" zu entschlüsseln.\n\nWährend er Jade sammelt, könnt Ihr Euch hier gerne umsehen. Ihr werdet sehen, die Leute in diesem Ort können jemanden wie Euch gut gebrauchen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLehrensucher Cho beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29924] = {title = "Vernichtet Kher Shan", objective = "Tötet Kher Shan im Tigergehölz.", description = "Kher Shan ist ein gemeiner Knatzel.\n\nHat alle meine Söhne abgeflotscht! Ick Ick, Nag Nag, Friss Frass, Beissi Beissi und die anderen, die mir nicht mehr einfallen.\n\nNappel will Ho-zen helfen? Abflotschen Kher Shan!\n\nDer Knatzel ist da drüben.\n\n<Nibi Nibi zeigt nach Osten.>Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29925] = {title = "Was wir entbehren können", objective = "Bringt die geplünderte Jade zu Lehrensucher Cho beim Omen des Kaisers. Bittet Toya in Morgenblüte um ein Transportmittel.", description = "Ich habe jeden nur möglichen Gefallen eingefordert. Das ist alles, was wir haben.\n\nCho muss Großes vorhaben!\n\nSagt mir Bescheid, wenn Ihr bereit seid, ihn aufzusuchen – ich habe ein Transportmittel für Euch vorbereitet.", progress = "Seid gegrüßt, <Name>! Dann habt Ihr meine Nachricht also erhalten?", completion = "Ich wusste, dass Toya das für mich erledigen würde!\n\nEr kann alles besorgen, wisst Ihr.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29926] = {title = "Unglücksjade", objective = "Erschlagt 12 Grünsteinknabberer und 6 Grünsteinverschlinger im Grünsteinbruch.", description = "Habt Ihr je eine Schieferspinne gesehen, <Klasse>? Normalerweise sind sie harmlos und fressen Steine, aber neuerdings haben sie Geschmack an Jade gefunden. Einige nennen sie schon \"Knabberer\".\n\nVor einigen Tagen sind wir auf ein großes Nest dieser Viecher gestoßen. Sie verbreiteten sich in den Tunneln und drehten durch. Sie haben alles in Sichtweite aufgefressen – auch einige unserer Leute.\n\nGeht da rein und vernichtet sie, damit uns noch Jade bleibt. Der Steinbruch liegt direkt westlich von hier.", progress = nil, completion = "Unfassbar... Ihr habt es wirklich geschafft!\n\nSeid Ihr auf der Suche nach einer Festanstellung, Bruder? Jemanden wie Euch könnte ich hier gut gebrauchen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29927] = {title = "Manns Mann", objective = "Sucht Hao Mann im Grünsteinbruch.", description = "<Auf einmal senkt die Vorarbeiterin ihre Stimme.>\n\nHört mal, das ist nicht leicht... Ich muss Euch um einen weiteren Gefallen bitten. Mein törichter Ehemann Hao ist Schichtleiter im Steinbruch. Ich habe ihm gesagt, es sei zu gefährlich und er soll nicht zurückgehen, aber er ist so dickköpfig wie ein Ho-zen und doppelt so dumm. Angeblich wird er zur \"moralischen Unterstützung\" gebraucht.\n\n<Mann schnaubt.>\n\nWas ist denn mit meiner moralischen Unterstützung? Was soll ich denn machen, wenn der Idiot stirbt?!\n\nBitte... Haltet nach ihm Ausschau, und sagt ihm, er soll nach Hause kommen.\n\n<Ihr Blick wird sanft, bevor sie sich abwendet.>", progress = nil, completion = "&lt;Hao sieht Euch an und versucht, sich aus dem Geröll zu befreien.&gt;\n\nNein, nein. Ich hab's gleich. HNNGHHH!!\n\nGut, vielleicht auch nicht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29928] = {title = "Ich hab keine Jade und muss schreien", objective = "Holt 15 Jadebrocken von den schelmischen Waldgeistern im Steinmetzviertel von Grünstein.", description = "Unsere ganze Jadeversorgungslinie ist auseinandergebrochen. Die Minen sind Todesfallen, die Moral ist auf dem Tiefpunkt, und als ob das noch nicht schlimm genug wäre, wimmelt es im Steinmetzviertel jetzt von Wassergeistern!\n\nSelbst die Pflanzen wollen mich ruinieren!\n\nWenn Ihr die Jade so dringend benötigt, dann folgt der Straße in Richtung Südwesten bis zum Steinmetzviertel und holt sie Euch selbst von diesen besseren Essstäbchen.", progress = "<Mann sieht Euch mit großen Augen und geblähten Nasenflügeln an.>", completion = "Fangen? Sie haben damit FANGEN gespielt?!\n\nIch hoffe, Ihr habt diesen herumlaufenden Zahnstochern gezeigt, was Ihr davon haltet.\n\nVielleicht seid Ihr ja doch nicht so übel. Ich brauche jemanden, der mir bei meinem Problem im Steinbruch helfen kann.\n\nUnd wenn ich mir ansehe, was die Lehrensucher hier vorhaben, denke ich, dass Ihr noch sehr viel mehr Jade brauchen werdet.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFreskoszene\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29929] = {title = "In der Falle!", objective = "Befreit 8 Grünsteinbergarbeiter im Grünsteinbruch.", description = "<Hao drückt mit aller Kraft gegen das Geröll.>\n\nHNNNGHHH!!\n\nLasst mich raten: Meine Frau schickt Euch? Man stelle sich das vor, meine zarte Schneelilie macht sich Sorgen. Ha ha! Sie ist immerzu besorgt um mich. Hört mal – HNNGHH!!! – es braucht schon mehr als einen kleinen – HNNGGHHH!! – Einsturz, um den alten Hao kleinzukriegen.\n\nAber einige meiner Leute stecken in Schwierigkeiten. Helft ihnen, wenn Ihr sie findet, ja? Ich komme schon klar.\n\nWirklich.", progress = nil, completion = "&lt;Hao lacht fröhlich.&gt;\n\nIch habe gesehen, wie sie rausgelaufen sind, als wäre der alte Kher Shan selbst hinter ihnen her.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29930] = {title = "Was mein ist, ist Euer", objective = "Steigt in den Jadewagen und fahrt mit Hao zurück zum Omen des Kaisers.", description = "So, Ihr braucht also Jade, was? Ich würde mal sagen, dass wir Euch wenigstens das schulden - wir haben genug davon im Steinbruch, und dank Eurer Hilfe sind wir bald wieder im Zeitplan.\n\nIch sollte vermutlich zu meiner Frau zurück, dann kann ich Euch und diesen Wagen voller schöner Sachen auch gleich mit zu ihr nehmen.\n\nBis jetzt ist mir noch <kein/keine:r> <Volk> untergekommen, <den/die:r> ich nicht mit meinem Wagen bugsieren konnte. Klettert hinten drauf und lasst den guten alten Hao nur machen.", progress = "Also? Wo ist Hao?\n\nSagt mir nicht, Ihr konntet ihn nicht finden...", completion = "Ihr habt es geschafft! Ihr bringt mir meinen Honigbären zurück!\n\nOh, vielen Dank, &lt;Name&gt;! Danke!", rewards = "ViridianumhangNektarhauchumhangManns UmhangCape des HonigbärenWolkensturzumhangDer folgende Zauber wird auf euch gewirkt:\n\nFreskoszene\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29931] = {title = "Das Schlangenherz", objective = "Sprecht mit Vorarbeiter Raike am Schlangenherz im Jadewald.", description = "Ihr habt hier gute Arbeit geleistet, <Kleiner/Kleine>. Dank Euch haben wir eine ganze Menge zusätzliche Jade und ich wüsste da jemanden, der sie gut gebrauchen könnte.\n\nMein Freund, Vorarbeiter Raike, leitet das große Statuenprojekt am Schlangenherz.\n\nBringt ihm eine Ladung Jade und sagt ihm, seine alte Freundin Mann lässt grüßen. Er wird eure Ankunft sehnlich erwarten.", progress = nil, completion = "Sehe ich das richtig? Eine komplette Lieferung reiner, hochwertiger Jade?\n\nSo ein Glück. Ich wusste, dass uns Vorarbeiterin Mann nicht im Stich lassen würde.\n\nOh, und Ihr natürlich auch nicht. Danke fürs Bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29932] = {title = "Der Tempel der Jadeschlange", objective = "Sprecht mit der Ältestenweisen Wind-Yi vor dem Eingang zum Tempel der Jadeschlange. Sprecht mit dem Drachenmeister Shoku für einen Ritt zum Tempel.", description = "Ihr habt uns hier einen enormen Dienst erwiesen, <Reisender/Reisende>\n\nDa wir nun genügend Jade für die Fertigstellung der Statue haben, sollten wir Yu'lon der Jadeschlange von unseren Fortschritten berichten.\n\nSprecht bei Eurer Ankunft mit der Ältestenweisen Wind-Yi am Eingang zum Tempel der Jadeschlange.\n\nWenn Ihr Eure Reise beschleunigen wollt, sprecht mit Drachenmeister Shoku. Ich bin mir sicher, dass er einen Drachen für Euch entbehren kann.", progress = nil, completion = "Ihr bringt Kunde vom Schlangenherz?\n\n&lt;Der Ältestenweise hört sich geduldig an, was in den Jademinen geschehen ist.&gt;\n\nDanke, dass Ihr den ganzen Weg hierher gekommen seid, Fremder. Doch ich kann im Moment nicht zulassen, dass Ihr mit der Jadeschlange sprecht.\n\nDie Uralte ist sehr beschäftigt und, wie Ihr sehen könnt, momentan auch nicht anwesend.", rewards = nil}
MultiLanguageQuestData['de'][29933] = {title = "Meine Beine!", objective = "Sammelt 30 Käferbeine von Tigerfliegen im Tigergehölz.", description = "Du wirklich Freund der Ho-zen, Nappel? Schauen wir doch mal...\n\nDie Ho-zen aufm Flotschhügel haben keine Köder für Glitschis mehr. Beine von Tigerfliegen am besten, die zucken schön im Wasser!\n\nBo Bo keine Lust auf Stiche. Nappel besorgt Köder und bringt aufn Hügel.", progress = "Glitschiessen!", completion = "Ha! Ha! Nappel ist der Oberknatzel!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29934] = {title = "Nach Rabenholdt", objective = "Sprecht mit Mostrasz am Zinnoberrefugium und fliegt mit ihm zum Rabenholdtanwesen.", description = "Wenn das Ei wirklich im Rabenholdtanwesen ist, dann können wir keinen Frontalangriff riskieren. Es könnte zerstört werden. Jemand muss sich hineinschleichen und die Wahrheit herausfinden.\n\nDas seid Ihr, <Name>.\n\nMostrasz wird Euch bei der Infiltrierung des Anwesens helfen. Sprecht draußen mit ihm, dann fliegt gemeinsam nach Rabenholdt. Viel Glück!", progress = nil, completion = "So weit so gut. Wollt Ihr dann ein wenig spionieren?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29935] = {title = "Befehl ist Befehl", objective = "Bringt die Allianzbefehle zu Häuptling Kah Kah auf dem Flotschhügel.\n\nBereitgestellter Gegenstand: \n", description = "Hmm, vielleicht Nappel doch nicht so böse!\n\nAndere Kahlhäute nicht nett zu Ho-zen.\n\nHo-zen haben dies von bösen Nappel gestohlen!\n\nAlle Nappelbeute geht an Kah Kah - auf Befehl des Häuptlings!\n\nHier, Nappel. Nimm es. Kah Kah will bestimmt neuen Freund der Ho-zen kennenlernen.\n\nSein Lager ist im Süden vom Flotschhügel.", progress = nil, completion = "Hmm.\n\nNette Nappel kämpfen gegen gemeine Nappel?\n\nHo-zen werden auch gegen gemeine Nappel kämpfen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29936] = {title = "Sofortmitteilung", objective = "Nutzt das Signalleuchtfeuer der Höllschreis Faust nahe Häuptling Kah Kah auf dem Flotschhügel.", description = "Willkommen, Nappel! Ich Kah Kah - Häuptling von Ho-zen aufm Flotschhügel.\n\nDjuuk Uuken wollte Häuptling sein, aber guter Nappel hat ihn gut geflotscht - großes Geschenk für Kah Kah.\n\nHo-zen hat auch Geschenk für guten Nappel. Geschenk kommt von großem Absturz. Ho-zen haben für Nappel drauf aufgepasst.", progress = nil, completion = "Beeindruckend, &lt;Name&gt;.\n\nEs wäre mir nie in den Sinn gekommen, dass wir uns irgendwie mit diesen Kreaturen anfreunden können.\n\nNun können wir uns auf wichtigere Dinge konzentrieren.", rewards = "FreundschaftsringBand der AkzeptanzBand der freundlichen GabeBand der BegabungBand der FundeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29937] = {title = "Zorniges Geflügel", objective = "Sammelt 6 Handvoll Vogeleingeweide von Blutkrallen in den Knatzelgründen.", description = "Sie mögen gern Fisch, was? Wie wäre es, wenn wir beenden, was Ihr begonnen habt, und sie dazu bringen, uns zu LIEBEN?\n\nIch habe noch immer etwas Schwarzpulver aus dem Wrack, aber ich brauche etwas um die Fische anzulocken.\n\nInnereien wären gut – das hat noch immer geklappt. Südlich der Stadt habe ich einige Vögel am Himmel gesehen.\n\nUnd? Worauf wartet Ihr noch?", progress = "Ihr habt das Zeug doch nicht mit den Händen angefasst, oder?", completion = "Ja!\n\nDas ist genau das, was ich haben wollte. Wartet es nur ab...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29938] = {title = "Freunde und Feinde", objective = "Tötet 7 Strandläufer der Jinyu am Glitschifluss.", description = "Verfiddelte Jinyu flotschen Kah Kahs Neffen!\n\nNappel hat viele Ho-zen abgemurkst. Jetzt muss Nappel viele Jinyu murksen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFischi"}
MultiLanguageQuestData['de'][29939] = {title = "Leichtes Ziel", objective = "Benutzt die Filetierbomben an der Düsterbank und sammelt 5 explodierte Glitschis.", description = "So. Ich habe die Vogeleingeweide über dem Sprengstoff platziert.\n\nIch nenne sie Filetierbomben und habe ein Patent darauf angemeldet.\n\nDa Ihr Euch mit diesen Kerlen angefreundet habt, sollte ich Euch vielleicht die Ehre überlassen?\n\nZündet einfach die Zündschnur an und lasst sie an der Düsterbank hochgehen!", progress = "Mir ist noch keine Krise untergekommen, die sich nicht mit Dynamit lösen ließ.", completion = "Wir haben gerade die Nahrungsbeschaffung dieser Kretins… äh, Ho-zen revolutioniert.\n\nSie werden nie wieder die Alten sein!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFish Event\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29940] = {title = "Geklautes Gemüse", objective = "Besorgt 5 gestohlene Rüben und 5 gestohlene Wassermelonen.", description = "Gut, ich gebe es zu. Nein, ich habe hier NICHT alles unter Kontrolle. Ich musste mich den ganzen Morgen mit Shed-Ling herumschlagen. Ich konnte sie zwar von meinem Anwesen vertreiben, aber sie haben etwas von meiner Ernte mitgenommen.\n\nSie haben die Sachen zum Fluss runter Richtung Süden gebracht. Ich habe keine Ahnung, was sie damit tun, wahrscheinlich jedoch nicht essen.\n\nWenn mein Vater jetzt seine Lieferung will, brauche ich Hilfe, um meine gestohlene Ernte zurückzuholen. Könnt Ihr mir dabei helfen?", progress = "Wenn mein Vater sein Gemüse will, brauche ich Eure Hilfe.", completion = "Perfekt.\n\n&lt;Ang sieht sich die zerschrammten Rüben und die matschigen Wassermelonen an.&gt;\n\nWas haben die denn bloß damit ANGESTELLT!?", rewards = "Satinhandschuhe des SeidenmeistersSonnenbeschienene HandschuheSchuppenstulpen des HuangtzeBrünierte PaoquanhandschuheSeidene Handschützer des GoldfächersEbenenfalkenhandschuheStulpen der Wilden EbenenSchwere DonnerfußstulpenGepanzerte SonnensangstulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29941] = {title = "Jenseits des Horizonts", objective = "Sprecht mit Shokia, Unteroffizier Gorrok, Schattenmeisterin Kiryn und Häuptling Kah Kah.", description = "Ich erkenne, was Ihr hier geleistet habt, <Klasse>. Mein Bericht an den Kriegshäuptling wird auch Eure Taten auflisten.\n\nAber wir haben keine Zeit zum Ausruhen!\n\nDieses Land muss kartografiert und auf die Besiedlung durch die Horde vorbereitet werden. Ich habe bereits eine Mannschaft dafür zusammengestellt.\n\nFindet sie, bevor sie es sich hier bequem machen. Teilt ihnen mit, was sie zu tun haben, und versucht, Eure neuen Freunde davon zu überzeugen, ihnen einen Führer an die Seite zu stellen.\n\nIhr werdet hier bei mir bleiben. Wir haben Vorbereitungen zu treffen.", progress = "Ist das Außenteam unterwegs, <Name>?", completion = "Gute Arbeit, &lt;Name&gt;.\n\nDas Außenteam, das Ihr zusammengestellt habt, ist aufgebrochen.\n\nHoffentlich war Gorrok schlau genug, das zerfetzte rote Hemd auszuziehen. Ich bewundere seinen Patriotismus, aber er hat es seit dem Verlassen von Orgrimmar getragen.\n\nWenn er es trägt, werden sie niemanden überraschen können...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29942] = {title = "Dummer Nappel, Glitschis sind für Ho-zen", objective = "Besorgt 4 Schnappersteaks an der Düsterbank.", description = "Denkst du, Ho-zen sind verrückt, Nappel? Warte, bis du Ho-zen ohne Glitschis siehst!\n\nNicht genug Glitschis für Ho-zen und Nappel.\n\nSchnapper! Ho-zen hassen verfiddelte Schnapper. Nappel können alle Schnapper essen.\n\n<Kritsche Kratsche deutet gen Süden.>", progress = "Nappel alle verfiddelte Schnapper geflotscht?", completion = "Jetzt haben alle Futter. Kritsche Kratsche besitzt viel Weisheit der Ho-zen.\n\nVielleicht Kritsche Kratsche eines Tages Häuptling sein...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Zone Auras\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29943] = {title = "Guerillas in unserer Mitte", objective = "Vernichtet 8 Allianzinfiltratoren in der Nähe des Idyllischen Aussichtspunktes.", description = "Prinz Anduin Wrynn. Der Sohn des Königs unserer Feinde! Das Glück ist der Horde erneut gewogen, <Name>.\n\nAber es gibt eine Kehrseite der Medaille: Wir waren naiv zu glauben, das Kind wäre allein.\n\nJeder Allianzabschaum in diesem Land wird jetzt verzweifelt nach diesem kostbaren Prinzen suchen.\n\nGemeinsam werden wir das Gebiet durchkämmen und seine Möchtegernretter ausschalten.", progress = nil, completion = "Ja!\n\nBei Thralls blutiger Faust, die Jagd auf die Allianz hat mir gefehlt!", rewards = "NebelbernmanschettenSchwarzdickichtbindungenJadehexenhandgelenksschützerGlasseearmschienenSeidenwaldmanschettenTiefenwaldarmwickelFuchswäldchenhandgelenksschützerDonnerholzarmplattenJadetigerarmplattenDer folgende Zauber wird auf euch gewirkt:\n\nUpdate Phase Shift (Self) and Zone Aura (Demon Creator)\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29944] = {title = "Alphatiere", objective = "Tötet Aiyu die Bratpfanne, Jinanya die Klauenklinge und Hoppelkoller.", description = "Bevor ein Fass aufgemacht wird, gibt es noch Arbeit. Diese Shed-Ling sind kein bisschen anders als die Shed-Ling auf der Wandernden Insel... Eine Plage, die sich so schnell vermehrt wie die Kaninchen, denen sie ähnelt.\n\nNatürlich könnten wir jeden einzelnen Shed-Ling töten, aber wozu unnötiges Blutvergießen? Schalten wir einfach ihre Alphatiere aus, damit sie sich nicht mehr so schnell... fortpflanzen.", progress = nil, completion = "&lt;Chen nickt.&gt;\n\nGut gemacht, &lt;Name&gt;. Ihr kämpft nicht schlecht.\n\nWas meint Ihr – schließen wir uns für das zusammen, was als Nächstes kommt?", rewards = "Ihr bekommt:\n\nRübensandsack"}
MultiLanguageQuestData['de'][29945] = {title = "Aus gelb und rot wird orange", objective = "Besorgt 10 Wiesenringelblumen und 40 mit Tierblut gefüllte Phiolen.", description = "Onkel Chen sagt, wir werden diesem Kerl mit seinem Shed-Ling-Problem helfen. Kein Problem! Ich LIEBE es, Shed-Ling zu ärgern.\n\nDas ist der Plan: Wir malen ein paar Rüben orange an, und dann lassen wir die Shed-Ling glauben, es seien Karotten.\n\nDas wird ein Riesenspaß.\n\nIch werde Rüben besorgen. Sucht Ihr in der Zwischenzeit etwas zum Herstellen von essbarer Farbe.", progress = "Habt Ihr das Zeug, um die Farbe herzustellen? Ich habe in der Zwischenzeit ein paar Rüben eingesammelt.", completion = "Hey, hey, HEY! Ihr habt BLUT mitgebracht? Ich schätze, ich hätte mich erst mal selbst umschauen sollen, bevor ich Euch gebeten habe, mir etwas Rotes zu bringen.\n\nAlso wirklich.\n\n&lt;Li Li wendet sich wieder den Zutaten zu, zerstampft die Blütenblätter und mischt dann etwas vom Blut dazu.&gt;\n\n&lt;Sie fängt an zu kichern.&gt;", rewards = "Ihr bekommt:\n\nRübenfarbsprühpistole"}
MultiLanguageQuestData['de'][29946] = {title = "Die Baumutter", objective = "Besiegt Chufa, die Zuckfußbaumutter.", description = "Wir haben uns um die Alpha-Männchen gekümmert. Jetzt geht es an das Alpha-Weibchen.\n\nShed-Ling sind nicht besonders wählerisch, wenn es um die Fortpflanzung geht, aber oft gibt es eine dominante Mutterfigur. Die ist normalerweise größer, fieser und zäher als alle anderen.\n\nWisst Ihr, ich hätte nichts dagegen, meine Fähigkeiten bei einer Baumutter auf die Probe zu stellen. Kann ich gemeinsam mit Euch kämpfen?", progress = nil, completion = "Das sollte die Shed-Ling zumindest für ein paar Wochen in Schach halten. Genug Zeit für Trübtrunk, ungestört ein paar Bierchen zu brauen.\n\nUnd gehört das etwa nicht zu den wichtigen Dingen im Leben?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29947] = {title = "Der mit der Rübe tanzt", objective = "Werft orange angemalte Rüben vor 12 Zuckfußhamsterer.", description = "Onkel Chen hat mich immer noch im Auge, das heißt, so bald komme ich nicht von hier weg. Es liegt wohl an Euch, diese Rüben - ich meine natürlich \"Karotten\" - zum Gewundenen Gewirr zu bringen und für mich abzuliefern.\n\nDas sollte nicht schwer sein. Werft einfach das Gemüse vor ein paar Shed-Ling und seht Euch ihre Reaktion an, wenn sie herausfinden, dass es sich in Wirklichkeit um eine Rübe handelt!", progress = nil, completion = "Muahahahaaaa! Ich liebe es, Shed-Ling zu ärgern.", rewards = "Ihr bekommt:\n\nOrange angemalte Rübe"}
MultiLanguageQuestData['de'][29948] = {title = "Diebisch bis ins Mark", objective = "Holt 6 gestohlene Hopfensäcke aus dem Gewundenen Gewirr zurück.", description = "Ihr und dieser Chen seid gute Leute, da Ihr mir gegen die Shed-Ling so helft. Ich bitte nicht gern um 'nen Gefallen, aber ich lehn' auch keinen ab.\n\nWenn Ihr dabei seid, diese Karnickel-Männer zu ärgern, könntet Ihr dann auch nach ein paar Hopfensäcken Ausschau halten? Bin mir ziemlich sicher, dass die letzte Nacht ein paar davon haben mitgehen lassen.\n\nBenutzen sie bestimmt als Kissen.", progress = "Ich hab' genug davon, diesen Shed-Ling zu sagen, sie sollen sich von meinem Land fernhalten.", completion = "Ahhh, danke sehr, der Herr. Ihr seid ein wahrer Kavalier.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29949] = {title = "Erbe", objective = "Trinkt gemeinsam mit Chen, Li Li und Trübtrunk.", description = "Ich würde sagen, wir haben uns unsere Belohnung verdient. Ich kann es kaum erwarten zu kosten, was Trübtrunk gebraut hat.", progress = nil, completion = "Ich weiß, dass Onkel Chen zurückkommt. Ich mache mir keine Sorgen.\n\nDas ist vielleicht sogar meine große Chance, endlich Pandaria zu erkunden! Kein fetter Onkel mehr, der mir im Nacken sitzt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29950] = {title = "Li Lis freier Tag", objective = "Nehmt Li Li mit zu den Seidenfeldern, Neu-Cifera und zur Huangtzekaskade.", description = "Onkel Chen bat mich, mich während seiner Abwesenheit in keine Kämpfe verstricken zu lassen... Das heißt aber nicht, dass ich nicht auf Erkundungstour gehen kann. Endlich eine Gelegenheit, mich in Pandaria umzusehen, ohne alle 47 Schritte eine Pause zu machen!\n\nWollt Ihr mich begleiten? Ich wette, wir können viele tolle Orte aufsuchen, die nicht allzu weit weg sind.", progress = "Seid Ihr bereit zu gehen?", completion = "Das war großartig! Wir beide sollten das unbedingt einmal wiederholen.\n\nUnd wie es scheint, sind wir noch vor Onkel Chen zurückgekehrt. Perfekt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLi Li's Day Off: Summon Chen\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29951] = {title = "Schlammiges Wasser", objective = "Füllt schlammiges Wasser in Trübtrunks Phiole.", description = "Da Ihr gerade nichts besseres zu tun habt, kann ich Euch auch genauso gut mein Bierbrauverfahren vorstellen. Ist eigentlich kein großes \"Verfahren\"... Ich vermische einfach den ganzen Kram und warte.\n\nIhr habt sicherlich schon gehört, dass ich das schlammige Wasser vom Flussufer im Süden benutze. Würdet Ihr diese Phiole mit dem Wasser füllen und zurückbringen? Ich hole in der Zwischenzeit den Hopfen und die Gerste.", progress = "Schon als ich Euch das erste Mal traf, wusste ich, Ihr seid zuverlässig.", completion = "Gut gemacht, &lt;Name&gt;. Gut gemacht.", rewards = "Satintreter des SeidenmeistersSonnenbeschienene FußschützerSchuppensabatons des HuangtzeBrünierte PaoquanschienbeinschützerSeidene Treter des GoldfächersEbenenfalkenstiefelSabatons der Wilden EbenenSchwere DonnerfußkriegsstiefelGepanzerte SonnensangkriegsstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29952] = {title = "Zerstörte Träume", objective = "Sprecht mit Chen Sturmbräu und hört Euch seine Geschichte an.", description = "Ja, ich habe die Brauerei Sturmbräu gefunden... Allerdings erhielt ich dort nicht den warmen Empfang, den ich erwartet hätte.\n\n<Chen schenkt sich ein Bier ein.>\n\nWollt Ihr die Geschichte hören?", progress = nil, completion = "Vielleicht war ich nicht dazu bestimmt, mich niederzulassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29966] = {title = "Alles niederbrennen", objective = "Nutzt Nazgrims Grog, um das Lager der Allianz am Idyllischen Aussichtspunkt zu zerstören.", description = "Seht, <Name>!\n\nDie Hunde von der Allianz haben ein Lager auf dem Kamm errichtet.\n\nHier, nehmt meinen Grog. Lasst uns ein Feuer machen, das man noch in Sturmwind sehen kann!\n\nFür die Horde!", progress = nil, completion = "Die Allianz muss aus diesem Land vertrieben werden, &lt;Name&gt;!\n\nWir müssen Nägel mit Köpfen machen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29967] = {title = "Und das Dungamit macht Bumm!", objective = "Sprecht mit Nieti Kuppelplopp östlich des Flotschhügels. Wehrt den Angriff der Jinyu mit seinen Methangranaten ab.", description = "Das ist ein Notfall!\n\nAnscheinend habt Ihr durch das Auslöschen der Fischleute in ein Wespennest gestochen.\n\nSie führen einen Gegenangriff auf den Flotschhügel durch!\n\nIch hatte gehofft, noch mehr Zeit für die Forschung und Entwicklung zu haben, aber wir müssen meine Methangranatentheorie sofort auf die Probe stellen!\n\nWir treffen uns auf der Ostseite des Hügels. Wärmt Euren Wurfarm schon mal auf!", progress = "Ich glaube, dass diese Methangranaten die Umgebung beeinflussen, wenn Ihr versteht, was ich meine...", completion = "Ich würde sagen, der Angriff ist definitiv abgewehrt!", rewards = "JinyumeditationsstabJinyuwünschelruteJinyukampfstabJinyugroßschwertJinyuhandaxtJinyuarmbrustJinyukampfaxtJinyuszepterJinyudolchJinyuschlachtstreitkolbenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29968] = {title = "Grünliche Energie", objective = "Sammelt 7 grüne Zweige in den Knatzelgründen.", description = "Ich sage nur eins: Methan!\n\nWir werden Umweltschützer. Saubere Verbrennung, gute Verfügbarkeit, ganz natürlich und hält mir die Druiden vom Leib, wenn wir wieder zurückkommen.\n\nAußerdem ist mir das Schießpulver ausgegangen...\n\nDaher brauche ich Eure Hilfe, <Name>.\n\nNein, nein, die Drecksarbeit sollt Ihr nicht verrichten, ganz besonders nicht vor den Augen des Generals. Um diese 'Vorkommen' kümmere ich mich selbst.\n\nSammelt Ihr Holz für ein kleines Gebäude, denn ich plane schon einmal für einen längeren Zeitraum!", progress = "Gebt Acht vor den feuchten… oje!", completion = "Ah, der Duft von Fortschritt und Methan.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29971] = {title = "Die Rückkehr des Spähers", objective = "Sprecht mit Shokia auf dem Flotschhügel.", description = "He, unsere Späher sind zurückgekehrt, als Ihr unterwegs wart. Und jetzt haltet Euch fest - sie haben irgendeinen Allianzbengel gefunden.\n\nIhr solltet vielleicht hingehen und sie eingehend befragen.", progress = nil, completion = "Wir haben vielleicht ein Problem.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29981] = {title = "Geflügelte Plagegeister", objective = "Tötet 14 Mantis der Ik'thik in Steinpflug.", description = "Ich bin nicht von hier. Ich bin sogar vor dem heutigen Tage NOCH NIE hier gewesen. Aber selbst ich merke, dass hier etwas nicht stimmt.\n\nDie Mauer dort ist gebaut worden, um die Mantis aus dem Land der Pandaren fern zu halten. Und jetzt schicken sie ihre geflügelten Späher rüber und es ist, als ob es die Mauer gar nicht gäbe!\n\nDiese schwächlichen Späher überleben auch nur, weil sie Bauern und keine Soldaten angreifen. Gegen jemanden wie Euch hätten sie keine Chance.", progress = nil, completion = "Lin hat Euch gebeten, uns zu helfen? Wie kommt sie darauf?\n\nAber sie hat Recht, wir sind zu wenig Leute. Wir nehmen Eure Hilfe und die des Mädchens gerne an. Ich danke Euch, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29982] = {title = "Evakuierungsbefehl", objective = "Evakuiert die Familien Schwarzgrund, Schaufelprank, Grünacker und Mergelpelz.", description = "Ein paar Bauern sind noch draußen auf den Feldern... einige davon gefährlich nahe der zerbröselnden Mauer. Ich will nicht, dass sich Bauern als Helden aufführen. Wir kümmern uns um diesen Mantis-Schwarm und dann können sie nach Hause zurückkehren.\n\nMeine Shado-Pan sind zu beschäftigt mit der Verteidigung der Stadt, um die Evakuierung zu organisieren. Möchtet Ihr Euch vielleicht nützlich machen? Dann bringt diese Bauern außer Gefahr.", progress = nil, completion = "Ein paar sture Bauern wollen mir die Arbeit zusätzlich schwer machen?\n\n&lt;Der Wachkommandant seufzt.&gt;\n\nAuch gut. Ich werde keinem Pandaren das Recht verwehren, sein Land zu verteidigen.", rewards = "Gepanzerte SonnensangschulterstückeSchwere DonnerfußschulterstückeSchulterstücke der Wilden EbenenEbenenfalkenschulterstückSeidene Schulterstücke des GoldfächersBrünierte PaoquanschulterstückeSchuppenschulterstücke des HuangtzeSonnenbeschienenes SchulterstückSatinschulterstücke des SeidenmeistersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29983] = {title = "Der verborgene Meister", objective = "Sucht Meister Schrammtatz im Tal der Vier Winde.", description = "Von jetzt an sollten wir in der Lage sein, Steinpflug zu verteidigen.\n\n<Der Kommandant zeigt zu Lin Zartpfote.>\n\nLin hier sucht jemanden, den sie der \"verborgene Meister\" nennt. Ich glaube, ich weiß, von wem sie spricht und ich habe einen Hinweis für Euch.\n\nGeht nach Norden.", progress = nil, completion = "Ihr wollt ausgebildet werden?\n\n&lt;Der Pandaren mustert Euch einige Sekunden lang, ohne etwas zu sagen.&gt;\n\nIn Ordnung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29984] = {title = "Mit eiserner Faust: Herausforderung des Bambus", objective = "Sprecht mit Meister Schrammtatz und versucht dann, den Stapel Bambusstangen dreimal zu treffen.", description = "Wir werden Euch jetzt einer Prüfung unterziehen - der Herausforderung des Bambus.\n\nEure Freundin Lin hat diese Prüfung nicht bestanden.\n\nFolgt mir und hört mir aufmerksam zu.", progress = nil, completion = "Ihr habt Talent, &lt;Name&gt;. Wir werden fortfahren.\n\nUnd jetzt ist es Zeit für die erste Einheit Eurer Ausbildung.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSummon Camera Vehicle\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29985] = {title = "Inkarnationen im Nebel", objective = "Tötet 12 Nebelinkarnationen.", description = "Der Nebel in diesem Wald und die seltsamen Kreaturen darin sind ein ständiges Ärgernis - und darum überlasse ich diese Angelegenheit gerne Schülern wie Euch. Die Kreaturen, die sich im Nebel verbergen, müssen unaufhörlich bekämpft werden.\n\nBetrachtet es als Teil Eurer Ausbildung.", progress = nil, completion = "Ihr habt meine Anweisungen genauestens befolgt, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29986] = {title = "Die Nebelwarten", objective = "Entzündet die nördliche Nebelwarte, die westliche Nebelwarte und die südliche Nebelwarte.", description = "<Schüler/Schülerin>.\n\nWir sind von einigen Warten umgeben, die in der Nähe meines Zuhauses im Wald versteckt sind. Sie können recht effizient den Nebel auflösen, müssen aber fortwährend gewartet werden.\n\nIhr findet eine im Norden, eine im Westen und eine im Süden. Findet diese Warten und entzündet sie.", progress = nil, completion = "Ihr gereicht Eurem Volk zur Ehre, &lt;Name&gt;.", rewards = "Halskette der drei SündenJhuuroons HalsbandHalskette des relativen FriedensAmulett der Singenden MarschenAmulett von OtuxianIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29987] = {title = "Mit eiserner Faust: Herausforderung des Holzes", objective = "Sprecht mit Meister Schrammtatz und versucht dann, den Stapel Holzbretter viermal zu treffen.", description = "Ihr seid gut vorangekommen mit Eurer Ausbildung. Folgt mir. Ich möchte dass Ihr Euch der Herausforderung des Holzes stellt.", progress = "Ich bin bereit, <Name>. Und Ihr?", completion = "Ihr verfügt über die Gabe der Konzentration, &lt;Name&gt;. Nicht viele meiner Schüler kommen so weit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29988] = {title = "Eine Vorliebe für Eier", objective = "Sammelt 10 Eier von Kaiserschwalben, 4 Eier von Weißkopfkranichen und 1 Ei eines Hornschnabelschreiters.", description = "Ich spüre Eure Ungeduld, aber Ihr seid noch nicht so weit. Vor der letzten Prüfung warten noch weitere Ausbildungsteile auf Euch. Und jetzt zu Eurer Aufgabe... Ich möchte, dass Ihr einige Eier für mich sammelt.\n\nJawohl, Eier. Im Marschgebiet oben auf den Bergen im Osten leben viele Vögel, die allesamt sehr friedfertig sind. Ihr solltet keine Probleme haben, mir genug Eier für einige Wochen zu bringen.", progress = "Wie läuft denn die Eierjagd?", completion = "Jetzt wisst Ihr, warum ich die Eier nicht selber sammeln mag.\n\nSollen wir mit der Ausbildung fortfahren?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSummon Camera Vehicle\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29989] = {title = "Mit eiserner Faust: Herausforderung des Steins", objective = "Sprecht mit Meister Schrammtatz und versucht dann, den Stapel Steinblöcke fünfmal zu treffen.", description = "In der kurzen Zeit Eures Aufenthaltes habt Ihr schon viel erreicht, <Name>. Normalerweise würde ich Euch nicht so früh dieser Prüfung unterziehen... Aber ich habe das Gefühl, dass Ihr dazu bereit seid.\n\nEs ist Zeit für die Herausforderung des Steins.", progress = nil, completion = "&lt;Meister Schrammtatz verbeugt sich vor Euch.&gt;\n\nIhr vermögt den Stein erbeben und unter Eurer Faust zerbrechen zu lassen. Ihr verfügt über die mentale Stärke, Berge zu versetzen.\n\nEs gibt nichts mehr, was ich Euch noch lehren könnte.", rewards = "Satinrobe des SeidenmeistersSonnenbeschienene BrustplatteSchuppenrüstung des HuangtzeBrünierter PaoquanbrustschutzSeidene Robe des GoldfächersEbenenfalkentunikaBrustschutz der Wilden EbenenSchwerer DonnerfußbrustharnischGepanzerter SonnensangbrustharnischIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][29990] = {title = "Übung und Disziplin", objective = "Meldet Euch bei Wachkommandant Lun Mai bei Steinpflug im Tal der Vier Winde.", description = "Ich habe mir gesagt, dass, falls ich es jemals hierher zum verborgenen Meister schaffen würde, ich so viel wie möglich von ihm lernen werde. Das ist meine Chance, <Name>. Die lasse ich mir nicht entgehen.\n\nAllerdings fürchte ich, dass Steinpflug uns braucht. Ich bin früh weggegangen, bevor wir die Mantis-Späher zurückdrängen konnten. Ich hätte ein besseres Gefühl, wenn Ihr Euch für mich beim Wachkommandanten melden könntet.\n\nOh, und falls Ihr auf die anderen stoßt, solltet Ihr ihnen vielleicht sagen, wo sich der verborgene Meister befindet...", progress = nil, completion = "Ich freue mich zu hören, dass es Lin gut geht.\n\nUnsere Verteidigungslinien halten fürs Erste. Die Mantis schicken weiterhin ihre Späher über die Mauer, aber viel weiter sind sie noch nicht gekommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29992] = {title = "Nomen est omen", objective = "Sammelt 18 Jademondblätter.", description = "Ich würde gerne Xiao, Kang und den anderen sagen, dass ich den verborgenen Meister gefunden habe, aber jetzt lässt er mich nicht gehen! Er sagt, ich müsse zuerst die Herausforderung des Bambus bestehen.\n\n<Lin flüstert:> Wisst Ihr, wie man das macht?\n\nWie es aussieht, sitze ich hier erst einmal fest und muss mich darin üben, gegen diesen Stein zu boxen. Meine Knöchel halten das nicht mehr lange durch.\n\nWenn Ihr mir ein paar Jademondblätter bringen könntet, könnte ich eine Salbe zubereiten, die meine Schmerzen zumindest teilweise lindert.", progress = "Au! Au! Au!", completion = "&lt;Lin macht eine kurze Pause, um die Blätter über ihre geschwollenen Knöchel zu reiben.&gt;\n\nHabt Dank! Das reicht fürs Erste - eine richtige Salbe kann ich dann später zubereiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29993] = {title = "Findet den Jungen", objective = "Sprecht mit Tintenmeister Wei.", description = "Habt Ihr meinen Sohn Lo gesehen? Eben war er noch hier und ich sagte ihm, dass wir heute aufbrechen.\n\nEr ist gewiss losgezogen, um diese junge Syra Zapfgold zu beeindrucken. Das ist auch der Grund, warum wir gehen müssen!\n\nMein Sohn wird nicht mit einer Zapfgold davonlaufen!\n\nIch werde mich hier nach ihnen umsehen.\n\nIch habe sie schon ein paar Mal dabei erwischt, wie sie sich zum Arboretum geschlichen haben. Könntet Ihr dort vielleicht nach ihnen schauen?", progress = nil, completion = "Ihr sucht zwei Liebende, die sich den Wünschen ihrer Familien nicht beugen wollen. Sie waren hier und suchten einen Weg für sich.\n\nLeider konnten sie unter unseren Bäumen und Kunstwerken keine Antwort finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29995] = {title = "Schrein der Morgensonne", objective = "Sucht am Schrein der Morgensonne nach Syra Zapfgold.", description = "Die \"Kinder\", die Ihr sucht, sind eigentlich gar keine Kinder, sondern erwachsene Pandaren, auch wenn ihre Ältesten etwas anderes behaupten. Ihre Liebe kommt der Fehde zwischen ihren Familien in die Quere.\n\nIhr könnt sowohl Syra als auch Lo am Schrein der Morgensonne antreffen, wo sie bei den einstigen Pandriarchen nach einer Lösung für ihr Dilemma suchen.", progress = nil, completion = "Oh! Bitte sagt mir, dass Ihr uns helfen könnt. Sie haben meinem Lo sehr wehgetan.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29997] = {title = "Das Dilemma des Sehers", objective = "Vernichtet Wasserteufel, um den Stab des weisen Mari zurückzubekommen.", description = "Da Ihr uns bei den Minen sehr geholfen habt, wärt Ihr vielleicht auch bereit, uns bei einem kleinen Problem am Tempel zu unterstützen?\n\nDer weise Mari beschwert sich über Störungen in seinem Tempel.\n\nDie Wassergeister sind neuerdings sehr verspielt und haben sich seinen Zeremonienstab angeeignet.\n\nIch wäre Euch sehr dankbar, wenn Ihr ihm helfen könntet. Vielleicht lege ich sogar ein Wort bei der Jadeschlange für Euch ein.\n\nFolgt einfach dem Weg gen Norden.", progress = "Die Teiche sind umwölkt. Ich brauche meinen Stab, um die Geister zu beruhigen und mit dem Wasser zu sprechen.", completion = "Ich bin nur ein alter Jinyu und kann diese lästigen Wassergeister nicht fangen. Vielen Dank, &lt;Name&gt;, dass Ihr mir meinen Stab zurückgebracht habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29998] = {title = "Das Dilemma des Bibliothekars", objective = "Sprecht mit Lehrensucher Steinschritt in der Bibliothek des Tempels.", description = "Lehrensucher Steinschritt beaufsichtigt die gesamte Bibliothek des Tempels. In letzter Zeit scheint ihn und seine Arbeit etwas zu belasten.\n\nDa noch Tausende alter Folianten transkribiert werden müssen, sollte er voll konzentriert sein.\n\nWürdet Ihr dem südlichen Pfad zur Bibliothek folgen und herausfinden, was ihn plagt?", progress = nil, completion = "Der Ältestenweise Ren-Zhu schickt Euch?\n\nNun gut. Ihr dürft mir helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][29999] = {title = "Des Reiters Bindung", objective = "Findet 4 verspielte Schlangen.", description = "Habt Ihr die jungen Schlangen auf dem Ausbildungsgelände gesehen?\n\nDie Kleinen haben oft Flausen im Kopf, und einige sind weggelaufen, um vor dem Training noch zu spielen.\n\nDie Herrin wird nicht erfreut sein, wenn sie das herausfindet.\n\nKönntet Ihr sie suchen und zu mir zurückbringen? Ich möchte nicht, dass sie Ärger bekommen.\n\nSie spielen gern im Freien, also sucht in den Höfen und bei den Pavillons nach ihnen.", progress = nil, completion = "Ihr habt sie alle gefunden und zurückgebracht!\n\nSie scheinen Euch bereits zu mögen.\n\nVielen Dank!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30000] = {title = "Die Jadeschlange", objective = "Hört der Jadeschlange zu.", description = "Ihr wollt der Jadeschlange eine Nachricht überbringen, nicht wahr?\n\n<Das kleine Mädchen sieht Euch mit schräg gelegtem Kopf fragend an.>\n\nIch schätze, es ist Zeit, dass Ihr vorgelassen werdet.", progress = nil, completion = "Habt Ihr die Botschaft überbracht?", rewards = "NebelbernkapuzeSchwarzdickichthelmJadehexenhelmGlasseekopfbedeckungSeidenwaldgugelTiefenwaldhelmFuchswäldchenhelmDonnerholzhelmJadetigerhelm"}
MultiLanguageQuestData['de'][30001] = {title = "Mottenplage", objective = "Vernichtet 8 gefleckte Motten.", description = "Motten sind in der Bibliothek eingefallen. Motten!\n\nJeder Bibliothekar, der seines Namens würdig ist, weiß, dass Motten nach den Bücherwürmern die größte Gefahr für Papier sind.\n\nWie sich herausgestellt hat, sind meine Assistenten Feiglinge, die sich vor Insekten fürchten.\n\nBitte, Ihr MÜSST mir helfen, diese Motten loszuwerden! Die Werke tausender Pandaren-Geschichtenerzähler müssen geschützt werden!", progress = nil, completion = "Ja, ja, danke! Ihr habt sie wunderbarerweise dezimiert.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30002] = {title = "Historische Seiten", objective = "Sucht in der Bibliothek nach befallenen Büchern und zerquetscht 12 Bücherwürmer.", description = "Das Allerschlimmste ist geschehen, <Volk>.\n\nWir. Haben. Bücherwürmer.\n\nDie Lage ist ernst. Alle Bücherwürmer in der Bibliothek müssen augenblicklich ausgelöscht werden, damit sie sich nicht noch weiter ausbreiten.\n\nWir müssen dieses Problem ausmerzen! Bitte untersucht die befallenen Bücher und zerquetscht jeden Bücherwurm, den Ihr findet.", progress = nil, completion = "Oh, großartig! Ich bin so erleichtert, dass wir die Katastrophe verhindern konnten.\n\nNein, nein, kommt bitte nicht näher. Ihr habt noch einige zerquetschte Überreste an den Schuhen kleben.", rewards = "NebelberntreterSchwarzdickichtfußlappenJadehexensabatonsGlasseeschienbeinschützerSeidenwaldtreterTiefenwaldstiefelFuchswäldchensabatonsDonnerholzkriegsstiefelJadetigerkriegsstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30003] = {title = "Der Schein trügt", objective = "Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30004] = {title = "Alles an Ort und Stelle", objective = "Sprecht mit dem Ältestenweisen Ren-Zhu am Tempel der Jadeschlange im Jadewald.", description = "Ihr habt uns mehr geholfen, als Ihr Euch vorstellen könnt, <Name>.\n\nIch weiß nicht, was wir getan hätten, wenn unsere kostbaren Schriftrollen verloren gewesen wären.\n\nBitte kehrt zum Ältestenweisen Ren-Zhu zurück und sagt ihm, dass in der Bibliothek alles in Ordnung ist.", progress = nil, completion = "Der Meister der Schriftrollen ist wieder bei der Arbeit?\n\nBemerkenswert. Euch ist gelungen, was vier Priester, die ich losgeschickt hatte, nicht vollbringen konnten.\n\nIch... Ich glaube, meine Kopfschmerzen klingen langsam ab.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30005] = {title = "Den Himmel erleuchten", objective = "Schießt 8 Feuerwerkskörper ab.", description = "Mögt Ihr ein schönes Feuerwerk, <mein Herr/meine Dame>?\n\nIch jedenfalls schon! Früher haben wir damit Dämonen verscheucht, aber ich mag die schönen bunten Farben einfach!\n\nIch glaube, im Tempel liegen noch immer einige Abschussgeräte herum.\n\nWürdet Ihr für mich ein großes Feuerwerk entzünden? Das würde mich so glücklich machen!", progress = nil, completion = "Hurra! Ich konnte das Feuerwerk von hier aus sehen!\n\nVielen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30006] = {title = "Die Dunkelheit um uns herum", objective = "Vernichtet 15 Sha-Eindringlinge.", description = "Trotz unserer Bemühungen haben die Sha-Wesen die Siegel rings um den Haupttempel zerbrochen.\n\nWenn wir sie dort nicht zurückhalten können, wird sich ihre Dunkelheit im restlichen Jadewald ausbreiten.\n\nWir brauchen unverzüglich Eure Hilfe. Vernichtet alle Sha-Wesen, die Ihr seht. Sie dürften nicht schwer zu finden sein.", progress = nil, completion = "Danke, &lt;Name&gt;. Jeder vernichtete Sha wendet das Blatt zu unseren Gunsten.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30011] = {title = "Eine neue Vision", objective = "Sprecht mit dem Ältestenweisen Ren-Zhu in der Nähe des Hofs des Tempels der Jadeschlange im Jadewald.", description = "Bitte sagt dem Ältestenweisen Ren-Zhu, dass ich sofort mit der Arbeit beginnen werde.", progress = nil, completion = "Großartig! Mir ist ein großer Stein vom Herzen gefallen, da ich jetzt weiß, dass der Wahrsager seine Meditationen wieder aufgenommen hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30015] = {title = "Morgenblüte", objective = "Sprecht mit Lehrensucher Cho in Morgenblüte.\n\nSprecht mit dem Flugmeister des Flotschhügels, um mitgenommen zu werden.\n\nBereitgestellter Gegenstand: \n", description = "Blut und Donner! Meine Axt kann kaum noch stillhalten!\n\nWir werden nicht nach Orgrimmar zurückkehren, bis wir die gesamte, verdammte Allianz aus diesem Land vertrieben haben.\n\nIch werde die Eingeborenen selbst ausbilden, wenn's sein muss. Egal wie - wir werden dieses Land für die Ankunft der Horde vorbereiten.\n\nIn der Zwischenzeit hat mir ihr Anführer das hier für Euch gegeben - eine Karte und eine Nachricht in so einer hochtrabenden Schrift.\n\nTut also, was Ihr tun müsst. Aber beeilt Euch.\n\nDer Krieg rückt näher...", progress = nil, completion = "Seid gegrüßt, &lt;Name&gt;!\n\nWillkommen in Morgenblüte, der Heimat meines Volkes.\n\nLeider muss ich es verlassen, denn die Arbeit eines Lehrensuchers ist niemals vollendet.\n\nFühlt Euch hier wie zu Hause. Eure Talente werden meinem Volk sicherlich von Nutzen sein.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLehrensucher Cho beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30027] = {title = "Die Lektion des Eisenasts", objective = "Nehmt Euch einen Schülerstab und legt ihn an.", description = "Zuallererst werdet Ihr Waffen benötigen, die Euren Fähigkeiten entsprechen. Beschafft Euch einen Stab von einem der Waffenregale dort unten, bringt ihn zu mir und zeigt mir, dass Ihr auch wisst, wie man ihn richtig hält.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30028] = {title = "Getreiderettung", objective = "Bringt Getreidefürst Kai 8 Säcke Getreide zurück.", description = "Da Ihr auf dem Weg in Richtung Süden seid, könntet Ihr nicht versuchen, etwas von dem Getreide wiederzubringen, das mir diese Diebe gestohlen haben?\n\nWir haben Vögel und Geister gesehen, die mit ganzen Säcken unserer besten Erzeugnisse in die Felder östlich und südlich von hier geflohen sind.", progress = "Wegen dieser Vögel und Geister werden wir es nie schaffen, die Brauerei Sturmbräu ausreichend zu beliefern.", completion = "Vielen herzlichen Dank, Fremder. Heute war kein guter Tag, aber Ihr habt ihn zumindest erträglich für uns gemacht.\n\nBitte nehmt diese Belohnung. Ihr habt sie Euch verdient.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30029] = {title = "Kleine miese Diebe", objective = "Tötet 8 gerissene Korndiebe.", description = "Wir haben eine große Menge billiges Getreide gekauft. Leider war es mit Geistern verseucht.\n\nUnd ich HASSE diese Geister mit ihren kleinen Knopfaugen und ihrem ewigen Grinsen.\n\nIch möchte, dass Ihr diese Sache erledigt, ohne Aufsehen zu erregen. Kann ich Eure Dienste in Anspruch nehmen, um diese Getreidediebe diskret auszuschalten?", progress = nil, completion = "Danke für Eure Hilfe, Fremder! Ab jetzt kommen wir hoffentlich allein klar.", rewards = "Medaillon des GetreidefürstenHalsreif des GetreidefürstenHalskette des GetreidefürstenAnhänger des GetreidefürstenAmulett des GetreidefürstenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30030] = {title = "Geistlos", objective = "Besiegt Kornan den Bierbaren.", description = "Um das gleich klarzustellen: Was geschehen ist, war ein Unfall. Ich hab' das nur für das GESCHÄFT gemacht!\n\nIch hatte ja keine Ahnung, dass eine Geisterinvasion droht oder dass einer von ihnen mein neues \"Pans Wunderwachstum\" fressen würde.\n\nUnd jetzt werden sie von einer nicht nur riesigen, sondern auch verdammt zornigen Bestie angeführt.\n\nWürdet Ihr sie erlegen, wenn ich Euch dafür bezahle?", progress = "Oje... Warum musste ich nur mit der natürlichen Ordnung der Dinge herumexperimentieren? Ich wollte doch nur, dass dieses Getreide schneller wächst und sich vermehrt.", completion = "Jetzt, wo die Sache ausgestanden ist, habe ich mir ein neues Mittel ausgedacht. Ich bin gespannt.\n\nDanke für Eure Hilfe. Hier ist Eure Belohnung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30031] = {title = "Geschmacksprobe", objective = "Kostet vom reifen Getreide, hellen Getreide, frischen Getreide und vermälzten Getreide.", description = "Wenn Ihr schon einmal hier seid, könnt Ihr mir auch gerne helfen. Da ich keinen einzigen Tropfen Bier in meinem Leben getrunken habe, fühle ich mich gänzlich ungeeignet für diese Aufgabe.\n\nIhr solltet etwas von jedem der Getreide kosten. Schauen wir einmal, ob etwas davon süß genug für Onkel Chen ist.", progress = "Nichts davon schmeckt süß genug! Woran liegt das?", completion = "Hm. Keines dieser Getreide ist das richtige. Onkel Chen ist ziemlich wählerisch.\n\nVielleicht weiß der Getreidefürst, wo ich etwas… Besonderes herbekomme.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLi Li Conversation\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30032] = {title = "Die Suche nach dem süßen Getreide", objective = "Findet die vermälzte Höhlengerste am Fuße der Windschneide.", description = "Ihr sucht nach einem süßen Getreide? Mein Vater sprach einmal von einer vermälzten Höhlengerste - die könnte es sein.\n\nWenn Ihr Euch der Gefahr stellen wollt, gibt es südlich von hier eine alte Höhle am Fuße der Windschneide.\n\nEs gibt sogar einen alten Aufzug, den mein Vater für seine Ausflüge in den Dschungel gebaut hat.\n\nIn der Höhle befindet sich ein Busch, der so alt ist wie meine Familie. Ihr könnt davon ein Getreidekorn abpflücken, das so süß schmeckt, dass es Eure Sinne berauschen wird.\n\nSeht Euch nur vor den Wächtern vor.", progress = "Dieser Dschungel hört sich gruselig an.", completion = "Na DAS riecht aber einmal richtig gut!", rewards = "Satinkordel des SeidenmeistersSonnenbeschienener GürtelSchuppentaillenschutz des HuangtzeBrünierte PaoquanschnallengürtelSeidene Kordel des GoldfächersEbenenfalkengürtelGürtel der Wilden EbenenSchwerer DonnerfußgurtGepanzerter SonnensanggurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30033] = {title = "Die Lektion des Eisenasts", objective = "Nehmt Euch eine Schülerzauberklinge und einen Schülerfächer und legt sie an.", description = "Zuallererst werdet Ihr eine Waffe benötigen, die Euren Fähigkeiten entspricht. Beschafft Euch eine Zauberklinge und einen Fächer von einem der Waffenregale dort unten, bringt sie zu mir und zeigt mir, dass Ihr auch wisst, wie man sie richtig hält.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30034] = {title = "Die Lektion des Eisenasts", objective = "Nehmt Euch eine Schülerarmbrust und legt sie an.", description = "Zuallererst werdet Ihr eine Waffe benötigen, die Euren Fähigkeiten entspricht. Beschafft Euch eine Armbrust von einem der Waffenregale dort unten, bringt sie zu mir und zeigt mir, dass Ihr auch wisst, wie man sie richtig hält.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30035] = {title = "Die Lektion des Eisenasts", objective = "Nehmt Euch einen Schülerstreitkolben und ein Schülergebetsbuch und legt sie an.", description = "Zuallererst werdet Ihr Waffen benötigen, die Euren Fähigkeiten entsprechen. Beschafft Euch einen Streitkolben und ein Gebetsbuch von einem der Waffenregale dort unten, bringt sie zu mir und zeigt mir, dass Ihr auch wisst, wie man sie richtig hält.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30036] = {title = "Die Lektion des Eisenasts", objective = "Nehmt Euch ein Paar Schülerdolche und legt sie an.", description = "Zuallererst werdet Ihr Waffen benötigen, die Euren Fähigkeiten entsprechen. Beschafft Euch ein Paar Dolche von einem der Waffenregale dort unten, bringt sie zu mir und zeigt mir, dass Ihr auch wisst, wie man sie richtig hält.", progress = nil, completion = "Eine gute Waffe. Sie sollte Euren Bedürfnissen gerecht werden.\n\nLasst uns sehen, was Ihr damit anstellen könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30037] = {title = "Die Lektion des Eisenasts", objective = "Nehmt Euch eine Schüleraxt und einen Schülerschild und legt sie an.", description = "Zuallererst werdet Ihr Waffen benötigen, die Euren Fähigkeiten entsprechen. Beschafft Euch eine Axt und einen Schild von einem der Waffenregale dort unten, bringt sie zu mir und zeigt mir, dass Ihr auch wisst, wie man sie richtig hält.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30038] = {title = "Die Lektion des Eisenasts", objective = "Nehmt Euch ein Schülerschwert und legt es an.", description = "Zuallererst werdet Ihr eine Waffe benötigen, die Euren Fähigkeiten entspricht. Beschafft Euch ein Schwert von einem der Waffenregale dort unten, bringt es zu mir und zeigt mir, dass Ihr auch wisst, wie man es richtig hält.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30039] = {title = "Viel zu lernen", objective = "Sprecht mit Meister Shang Xi.", description = "Nun, da Eure Ausbildung begonnen hat, erhaltet Ihr Eure erste, recht simple Aufgabe: Sprecht mit Meister Shang Xi.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30040] = {title = "Viel zu lernen", objective = "Sprecht mit Meister Shang Xi.Nun, da Eure Ausbildung begonnen hat, erhaltet Ihr Eure erste, recht simple Aufgabe: Sprecht mit Meister Shang Xi.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Nun, da Eure Ausbildung begonnen hat, erhaltet Ihr Eure erste, recht simple Aufgabe: Sprecht mit Meister Shang Xi.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30041] = {title = "Viel zu lernen", objective = "Sprecht mit Meister Shang Xi.", description = "Nun, da Eure Ausbildung begonnen hat, erhaltet Ihr Eure erste, recht simple Aufgabe: Sprecht mit Meister Shang Xi.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30042] = {title = "Viel zu lernen", objective = "Sprecht mit Meister Shang Xi.", description = "Nun, da Eure Ausbildung begonnen hat, erhaltet Ihr Eure erste, recht simple Aufgabe: Sprecht mit Meister Shang Xi.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30043] = {title = "Viel zu lernen", objective = "Sprecht mit Meister Shang Xi.", description = "Nun, da Eure Ausbildung begonnen hat, erhaltet Ihr Eure erste, recht simple Aufgabe: Sprecht mit Meister Shang Xi.", progress = nil, completion = "Heute ist der Tag, an dem Eure Zukunft entschieden wird. Besitzt Ihr das notwendige Geschick und die Gerissenheit, die Ihr braucht, um &lt;Klasse&gt; zu werden? Oder hält das Schicksal ein Leben als einfacher Händler für Euch bereit?\n\nEin jeder findet seinen Platz, aber ich spüre, dass Ihr nach Größerem strebt.\n\nBeginnen wir also mit der Ausbildung, mein jüngster Schüler.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30044] = {title = "Viel zu lernen", objective = "Sprecht mit Meister Shang Xi.", description = "Nun, da Eure Ausbildung begonnen hat, erhaltet Ihr Eure erste, recht simple Aufgabe: Sprecht mit Meister Shang Xi.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30045] = {title = "Viel zu lernen", objective = "Sprecht mit Meister Shang Xi.Nun, da Eure Ausbildung begonnen hat, erhaltet Ihr Eure erste, recht simple Aufgabe: Sprecht mit Meister Shang Xi.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Nun, da Eure Ausbildung begonnen hat, erhaltet Ihr Eure erste, recht simple Aufgabe: Sprecht mit Meister Shang Xi.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30046] = {title = "Chens Vorsatz", objective = "Trefft Euch mit Chen Sturmbräu bei Halbhügel.", description = "Wisst Ihr was? Ich will so nicht mehr weitermachen.\n\nIch werde diesem Onkel Gao zeigen, was ein richtiger Braumeister ist. Ich werde das beste Bier brauen, das er jemals getrunken hat, mit Zutaten, die er noch nie zuvor benutzt hat.\n\nIch bin Chen Sturmbräu, und ich bin der beste Braumeister, den es gibt.", progress = nil, completion = "Jetzt geht's ans Brauen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nChen's Resolution: Summon Li Li B\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30047] = {title = "Chens Geschmacksprobe", objective = "Kehrt zu Chen Sturmbräu zurück.", description = "Onkel Chen wird begeistert sein. Oder... er sagt uns einfach nur, dass wir etwas finden müssen, das noch süßer schmeckt. So ist er halt.\n\nBringen wir einfach dieses Getreide zu ihm nach Halbhügel.", progress = nil, completion = "Ah! Na, das ist ja mal ein wunderbar vermälztes Getreide. Ihr beide habt wirklich gute Augen und Nasen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30048] = {title = "Li Li und das Getreide", objective = "Sprecht mit Li Li bei der Kaiserlichen Kornkammer im Tal der Vier Winde.", description = "Ich werde Euch meinen Brauplan verraten, <Name>: Ich plane ein Kaiser-Starkbier herzustellen. Wenn man es richtig macht, sollte es dunkel, rauchig und mit hohem Alkoholgehalt ausgestattet sein.\n\n<Ein zweifelnder Blick schleicht sich in Chens Gesicht.>\n\nMir ist gerade etwas eingefallen... Ich habe Li Li gar nichts von meinen Plänen erzählt. Sie hat überhaupt keine Ahnung, welche Art Getreide sie mitbringen soll!\n\nKönntet Ihr mit ihr sprechen? Ich möchte, dass sie das süßeste Malzgetreide mitbringt, das sie finden kann.", progress = nil, completion = "&lt;Name&gt;? Was macht Ihr denn hier?\n\nAch so, Onkel Chen will süßes Malz? Kein Problem! Gehen wir doch einfach zur Verkostung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30049] = {title = "Wasserträger", objective = "Sprecht mit Trübtrunk am Goldfächer im Tal der Vier Winde.", description = "Könntet Ihr bitte Trübtrunk aufsuchen? Er braucht vielleicht Hilfe beim Rücktransport des Wassers.\n\nIch bin mir sicher, dass er Eure Muskelkraft gut gebrauchen kann, <Klasse>.", progress = nil, completion = "&lt;Name&gt;! Ihr wollt mir helfen?! Das ist aber wirklich nett von Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30050] = {title = "Nur die Harten kommen in'n Garten", objective = "Befolgt Gärtnerin Frans Anweisung und wässert 60 ihrer Gemüsepflanzen.\n\nPflanzen kann man auch vom Rücken eines Reittiers aus wässern.", description = "Ihr wollt, dass ich Euch den Hopfen einfach GEBE? Unglaublich! Das ist heute schon das dritte Mal, dass so <ein unverschämter/eine unverschämte:r> <Volk> wie Ihr Lebensmittel umsonst haben will!\n\nIhr braucht Lebensmittel? Dann müsst Ihr dafür arbeiten!\n\n<Sie drückt Euch eine Gießkanne in die Hand.>\n\nUnd jetzt wässert meine Pflanzen!", progress = "Wässert meine Pflanzen, Ihr fauler <Klasse>!", completion = "Hm...\n\nGute Gartenarbeit.", rewards = "Sichel der GärtnerinZauberstab der GärtnerinFrans SpeerAxt der GärtnerinFrans HandaxtFrans ArmbrustStreitkolben der GärtnerinFrans goldener StreitkolbenFrans DolchFrans BronzestreitkolbenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30051] = {title = "Die Große Wasserjagd", objective = "Begleitet Trübtrunk zu den Wirbelnden Teichen des Goldfächers und helft ihm 30 Pfoten voll Wiesenwasser einzusammeln.\n\nWenn Ihr Trübtrunk aus den Augen verliert, könnt Ihr ihn neben der riesigen Banane im Goldfächer wiederfinden.", description = "Schaut, <Name>: der Goldfächer. Ich hab' viele gute Dinge über das Wasser hier gehört. Und auch viele schlechte Dinge.\n\nIch hab' keine Ahnung, welches Wasser genau Chen braucht, also warum bringen wir ihm nicht ein paar Kostproben mit?\n\nAlso los, holen wir uns etwas Wasser.", progress = "Dieser Sturmbräu behauptet, er wär' der beste Brauer weit und breit. Kann schon sein, aber bewiesen hat er's mir noch nicht.", completion = "Schaut doch mal was für 'ne hübsche Wassersammlung wir hier haben! Mit diesem magischen Wasser kann Chen sicherlich ein großartiges Bier brauen.\n\nOder ein Gebräu, das einen für die nächsten Monate an die Kloschüssel fesselt... Aber das werden wir wohl abwarten müssen.", rewards = "Umarmung der BäumeStaubrückenumhangLohfellcapeTrübtrunks UmhangUmhang des GrasgefällesIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30052] = {title = "Unkrautvernichtung", objective = "Befreit Gai Lans Feld von 100 Exemplaren Unkraut.\n\nDas Unkraut könnt Ihr auch vom Rücken eines Reittieres aus jäten.", description = "Ihr braucht etwas Hopfen? Davon habe ich draußen im Stall noch jede Menge. Ich kann Euch gern etwas davon geben - wenn Ihr mir helft, das Unkraut auf meinem Feld zu jäten.\n\nAlso los: hopf, hopf an die Arbeit!", progress = nil, completion = "Im Jäten macht Euch niemand etwas vor.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30053] = {title = "Hopfjagd", objective = "Bittet Gärtnerin Fran, Gai Lan und Den Lehmkrall um Hopfen.", description = "Da sich Li Li um das Getreide und Trübtrunk um das Wasser kümmert, brauchen wir nur noch Hopfen und ein paar gute Holzfässer. Ich kümmere mich um die Fässer... Also müsstet Ihr etwas Hopfen besorgen.\n\nIch kenne mich mit dem Hopfen in diesem Land nicht aus, aber die Bauern in der Umgebung werden sicherlich etwas haben, was zum Brauen taugt. Versucht, so viel davon zu besorgen, wie Ihr könnt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30054] = {title = "Schluss jetzt, verfiddelt noch mal!", objective = "Sammelt 100 Zähne von Shed-Ling ein.", description = "Shed-Ling fressen zu viel.\n\nFressen Mung-Mungs Karotte. Fressen Mung-Mungs Kürbis. Mung-Mung will sie verscheuchen, aber die Knatzel beißen Mung-Mung in Schwanz und Fuß.\n\nSchluss jetzt, verfiddelt noch mal.\n\nDu kämpfst viel besser als Mung-Mung. Bring mir ihre Zähne. Dann ist Schluss mit fressen und beißen.", progress = "Du bringst mir die Zähne und Mung-Mung hat vielleicht etwas Hopfen für dich.", completion = "So viele Zähne! Vielleicht klebt Mung-Mung die zusammen und macht eine Harke daraus.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30055] = {title = "Sturmbräus Hopfnung", objective = "Kehrt zu Chen Sturmbräu in Halbhügel zurück.", description = "Alle drei Bauern haben ihren Hopfen nach Halbhügel geliefert. Vielleicht solltet Ihr Chen aufsuchen, um sicherzustellen, dass er angekommen ist.", progress = nil, completion = "Schaut Euch diese Menge Hopfen an! Und das ist sogar Qualitätsware.\n\nEs geht gut voran, &lt;Name&gt;. Schon bald haben wir alle Zutaten, um mit dem Brauen zu beginnen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30056] = {title = "Die Bauerstochter", objective = "Findet Mina Lehmkrall.", description = "<Tapferer/Tapfere:c> <Klasse>, wie gut, dass Ihr da seid! Meine Tochter ist verschwunden!\n\nUnd ich glaube, dass diese Shed-Ling sie in ihre kleine, stinkende Höhle verschleppt haben. Ich bin zu alt, um diese Shed-Ling zu bekämpfen, und mein Hofhelfer ist schon ganz erschöpft, weil er die Viecher den ganzen Morgen gejagt hat.\n\nKönntet Ihr bitte nach ihr suchen?", progress = nil, completion = "Nein... nein... zurück... Ich will nicht...\n\nAber Moment, Ihr seid ja gar keine Karotte. Und auch kein Shed-Ling. Seid Ihr etwa hier, um mich zu retten?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30057] = {title = "Die orangene Bedrohung", objective = "Bringt Mina Lehmkrall zurück zu ihrem Vater.", description = "Diese Shed-Ling... Sie haben mich gezwungen, furchtbar, furchtbar absurde Dinge zu tun, die alle mit Karotten zu tun haben. Ihr glaubt ja gar nicht, mit wie vielen sie mich überhäuft haben.\n\nAber verschwenden wir besser keine Zeit: Holt mich hier raus!", progress = nil, completion = "Was soll das mit all diesen Karotten? Ich verstehe es einfach nicht.", rewards = "Satinmantelung des SeidenmeistersSonnenbeschienene SchiftungSchuppenschiftung des HuangtzeBrünierte PaoquanschiftungSeidene Amicia des GoldfächersEbenenfalkenschiftungSchiftung der Wilden EbenenSchwere DonnerfußschulternGepanzerte SonnensangschulternIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30058] = {title = "Mottallus!", objective = "Lockt Mottallus an und besiegt sie.", description = "Der werte Geselle Chu hat offensichtlich ein Monster erschaffen - den seidigen Tod mit Flügeln.\n\nMottallus.\n\nIhre Brut habt Ihr ja schon kennengelernt. Jetzt möchten wir Euch bitten, die Kreatur selbst zu bekämpfen.\n\nBitte, <Klasse>, begebt Euch in die Grube, um den Köder auszulegen. Damit könnt Ihr die Bestie anlocken.\n\nUnsere Mottenkämpfer werden Euch bei Bedarf unterstützen. Allerdings scheint die Seide an ihnen besonders stark zu kleben. Wenn sie also in Bedrängnis geraten, könnte es sein, dass Ihr vielmehr ihnen helfen müsst.", progress = "Habt Ihr die Bestie schon vernichten können?", completion = "In allem, was wir tun, streben wir nach Perfektion. Aber auf dem Weg dorthin werden uns viele Fehler unterlaufen.\n\nIch bin mir sicher, dass schon morgen wieder ein Tag voller Fehler auf uns wartet. Aber dennoch danken wir Euch für Eure Hilfe.", rewards = "SonnensangwesteDonnerfußwesteBrustplatte der Wilden EbenenEbenenfalkenwesteBrünierte PaoquanwesteSchuppenweste des HuangtzeSonnenbeschienene WesteAuf Euch wartet eine dieser Belohnungen:\n\nGeldbeutel des Helden\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][30059] = {title = "Die Mottenrebellion", objective = "Tötet 6 mutierte Seidenspinner und 8 winzige mutierte Seidenspinner.", description = "Oh... Oh, gut, <ein/eine:c> <Klasse>! Könntet Ihr mir vielleicht helfen?\n\nIch habe im Zuge meiner Experimente zur Steigerung der Seidenproduktion eine Reihe widerlicher Monster erschaffen.\n\nAm Ende gab es sogar eine echte Mottenrebellion. Könntet Ihr vielleicht Euer Talent als <Klasse> dafür einsetzen, ein paar dieser Mutanten zu vernichten?", progress = nil, completion = "Es scheinen nicht mehr GANZ so viele verderbte Motten da draußen zu sein. Zumindest aber habt Ihr mir etwas Zeit verschafft, bevor ich wirklich großen Ärger bekomme.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30063] = {title = "Hinter den Masken", objective = "Sammelt 8 Masken des Zweifels.", description = "Das Sha mag unaufhaltsam erscheinen, aber das ist es nicht.\n\nOffenbar bezieht es seine Macht aus seinen Masken. Werden eine Sha-Kreatur und die Maske getrennt, wird die Essenz der Kreatur zurück in ihr eigenes Reich verbannt.\n\nBringt mir intakte Masken, damit ich sie genauer untersuchen kann. Aber gebt Acht, denn das Sha wird sich gewiss nicht leichtherzig davon trennen.", progress = "Bitte geht vorsichtig mit den Masken um. Wenn Ihr nicht Acht gebt, werden sie versuchen, Euch zu verschlingen.", completion = "Ich vermute, dass diese Masken dem Sha ermöglichen, eine physische Verbindung zu unserer Welt herzustellen.\n\nIch muss sie genauer untersuchen, wenn wir diese Kreaturen endgültig verbannen wollen.\n\nVielen Dank, &lt;Name&gt;. Ich weiß Eure Hilfe sehr zu schätzen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30064] = {title = "Rettung der Sutras", objective = "Sammelt 6 uralte Sutras.", description = "Meine Adepten mussten ihre Studien unterbrechen, als die Sha-Invasion begann.\n\nLeider haben sie ihre Bücher auf dem Tempelgelände liegen gelassen. Diese unschätzbaren Werke müssen gerettet werden!\n\nIhr findet die Sutras in der Nähe der Ausbildungsarena und des Adeptenrings im Nordosten.", progress = "Wie sehen die Sutras aus? Wurden sie beschädigt?", completion = "Vielen Dank! Ich bin so erleichtert, dass diese Texte in Sicherheit sind.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30065] = {title = "Pfeile des Glücks", objective = "Sammelt 8 Pfeile des Verteidigers.", description = "Unser Kriegsmaterial geht zur Neige, und wir benötigen vor allem weitere Pfeile.\n\nUnsere Schlangenreiter sind geübte Schützen, doch ohne Munition können sie nicht viel ausrichten.\n\nWir brauchen jemanden, der sich auf die Schlachtfelder wagt und unbeschädigte Pfeile sammelt, um unsere Vorräte aufzustocken.\n\nJeder Pfeil, den Ihr findet, wird von Nutzen sein.", progress = "Konntet Ihr einige Pfeile finden?", completion = "Diese Pfeile sind in einem guten Zustand. Sie werden ihren Zweck erfüllen.\n\nGut gemacht, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30066] = {title = "Verborgene Macht", objective = "Bringt alte Mantras zu 6 Wächtern oder Adepten von Yu'lon.", description = "Unsere Tempelverteidiger kämpfen seit Stunden ohne Unterlass. Sie werden gewiss langsam müde.\n\nIch werde Euch Mantras geben, die Ihr unseren Kämpfern bringen könnt.\n\nLasst Euch von den Schriftstücken nicht täuschen, diese alten Schriften enthalten Worte von unsagbarer Macht.", progress = nil, completion = "Das Sha ist Legion, und wir sind nur wenige. Aber davon lassen wir uns nicht einschüchtern.\n\nDanke für Eure Hilfe beim Schutz unserer Heimat, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30067] = {title = "Der Schatten des Zweifels", objective = "Besiegt den Schatten des Zweifels.", description = "Eine der großen Manifestationen des Sha ist im Süden erschienen.\n\nSie versucht, ein altes Relikt, die Glocke der Tausend Flüsterworte, zu zerstören.\n\nDiese Glocke ist in der Geschichte des Tempels noch nie geläutet worden, da sie ein altes Instrument der Macht sein soll.\n\nBitte besiegt diesen Dämonen auf der Stelle! Wir müssen dieses Relikt retten!", progress = "Die Glocke soll die Stimmen von eintausend gefallenen Tempelpriestern enthalten.", completion = "Ihr habt uns gerettet. Vor welchem Schicksal, das mag ich mir gar nicht ausmalen...", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30068] = {title = "Flammen der Leere", objective = "Fliegt mit Eurer Kriegsschlange zu reinem Quellwasser und löscht dann 6 Flammen der Leere mit dem Wasser aus ihrem Maul.", description = "Seht Ihr die wilden Flammen, die rings um den Tempel lodern?\n\nJe größer unsere Zweifel, desto heftiger brennen sie. Wenn wir nichts unternehmen, werden sie den ganzen Tempel verschlingen.\n\nWir haben eine letzte Hoffnung.\n\nFliegt auf einer unserer Kriegsschlangen zu den reinen Wasserquellen, und löscht das Feuer mit Wasser aus den Becken.", progress = "Dieses Feuer brennt wie nichts sonst auf dieser Welt.", completion = "Ihr habt uns beim Löschen des Feuers sehr geholfen. Danke für Eure Mühe.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30069] = {title = "Kein Plan überlebt den Feindkontakt", objective = "Tötet 6 Grunzer und 4 Kupplungsschmierer von Garrosh'ar.", description = "Schnell und ruhig, genau so geht SI:7 am liebsten vor. Zumindest war es so geplant.\n\nRell Nachtwind ist schon im Inneren von Garrosh'ar und sucht nach Hinweisen auf Anduin und Taylor, da drinnen wird es aber heiß und er braucht Unterstützung.\n\nKämpft Euch an diesen Hunden vorbei und findet Rell!", progress = "Hier wimmelt es nur so von Soldaten der Horde. Mit so vielen im Nacken kommen wir nicht zu ihrem Anführer durch.", completion = "Gute Arbeit! Falls Ihr Euer Abenteurerdasein jemals an den Nagel hängen solltet, gibt es beim SI:7 bestimmt einen Platz für Euch...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30070] = {title = "Der Fall von Ga'trul", objective = "Tötet Ga'trul.", description = "Also schön, <Kumpel/Mädel>. Wir haben dieser Hexenmeisterarmee genügend Stöße verpasst... jetzt ist es Zeit, ihr den Kopf abzuhacken.\n\nGa'trul ist dort hinten, in der großen alten Tempelruine. Verdrescht ihn ordentlich, damit die Horde ihren letzten Pfeiler hier in Pandaria verliert.", progress = nil, completion = "Sha...\n\nIn fremden Gefilden gegen die Horde zu kämpfen, ist schwierig genug.", rewards = "Lederhelm des FriedensbrechersKettenhelm des FriedensbrechersSeidene Gugel des FriedensbrechersSatinkapuze des FriedensbrechersBalghelm des FriedensbrechersRingpanzerhelm des FriedensbrechersBrünierte Kopfbedeckung des FriedensbrechersGepanzerter Helm des FriedensbrechersSchwerer Helm des FriedensbrechersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30072] = {title = "So geht Seide", objective = "Sammelt Maulbeerblätter, füttert 5 hungrige Seidenraupen und besorgt Rohseide.", description = "Hättet Ihr Lust, für einen Tag <ein Seidenmeister/eine Seidenmeisterin> zu sein?\n\nDann braucht Ihr zunächst einmal Maulbeerblätter. Die findet Ihr in unserem Maulbeerbuschgarten im Nordwesten.\n\nUnd wenn Ihr die habt, verfüttert Ihr sie an eine hungrige Seidenraupe in unserer Grube im Westen.\n\nUnd schließlich müsst Ihr noch etwas Rohseide aus unserer Fertigungshütte auf der Südseite unseres Hofes besorgen.\n\nViel Spaß!", progress = "Habt Ihr alles gefunden? Habt Ihr Euch die Fertigung genau angeschaut?", completion = "Sehr gute Proben. Ich werde dafür sorgen, dass sie in die richtigen Hände gelangen. Hier, dieser kostenlose Artikel aus unserem Sortiment ist für Euch.", rewards = "SeidenmeisterschalSeidenmeistertuchSeidenmeistercapeSeidenmeisterpelerineSeidenmeisterumhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30073] = {title = "Das kaiserliche Gebräu", objective = "Bleibt vor Ort und helft Chen Sturmbräu, sein Gebräu herzustellen.", description = "Wir haben alles, was wir brauchen. Jetzt sollten wir mit dem Brauen beginnen.\n\nPasst gut auf, <Name>... Vielleicht könnt Ihr noch etwas lernen.", progress = "Bier lässt sich nicht einfach in drei Sekunden herstellen, <Name>. Selbst wenn mein Name Chen Sturmbräu lautet.", completion = "Danke, dass Ihr so lange gewartet habt. Ihr seid ebenso geduldig wie mutig.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30074] = {title = "Klopf, klopf", objective = "Trefft Euch mit Chen Sturmbräu am Eingang der Brauerei Sturmbräu.", description = "Und jetzt auf zur Brauerei Sturmbräu! Höchste Zeit, dass ich mal wieder die anderen Sturmbräus zu sehen bekomme... Und wie kann man ein Wiedersehen besser feiern als mit ein paar Krügen Bier?\n\nIhr wisst doch, wo die Brauerei ist, oder? Folgt einfach dieser Straße nach Westen, Ihr könnt sie nicht verfehlen. Aber natürlich könnt Ihr auch mit uns kommen. Wir werden jeden Augenblick aufbrechen.", progress = nil, completion = "Die Tür ist... verbarrikadiert?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSummon Controller\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30075] = {title = "Weg frei", objective = "Tötet 10 bierbenebelte Ho-zen oder schelmische Shed-Ling.", description = "Seht Ihr das? Shed-Ling, Ho-zen und Wassergeister... die alle aus den Türen und Fenstern der Brauerei herausströmen! Was zum Teufel ist da drinnen los!?\n\nEs gibt noch einen anderen Eingang, auf der Ostseite der Brauerei. Ich werde dorthin laufen und da mal nachsehen. In der Zwischenzeit könnt Ihr vielleicht diese Kreaturen beseitigen. Es gibt wirklich nichts Schlimmeres als betrunkene Ho-zen.", progress = nil, completion = "Ich hab' genug von dieser Brauerei. Vielleicht sollten wir beide da einfach reingehen und mal so richtig aufräumen.", rewards = "SeidenbrutflügelFeder eines EbenenfalkenGlückbringende \"Hasen\"-PfoteZwingzangenpanzerLohfellgeweihstangeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30076] = {title = "Das beste Wasser", objective = "Sammelt 3 Geistwasseressenzen ein.", description = "Ich hab' viele verrückte Geschichten über diese Brauerei hier gehört und immer geglaubt, dass sie nicht wahr sind... bis ich diesen riesigen Ho-zen gesehen habe.\n\nUnd dann fragte ich mich, ob an den Geschichten vielleicht doch was dran wäre. Ich hab' zum Beispiel von Wassergeistern gehört, die frei in der Brauerei herumlaufen und Krawall veranstalten. Ihre Körper BESTEHEN AUS WASSER.\n\nMit ihrem Wasser könnte man sicher ein leckeres Bierchen brauen. Würdet Ihr mir vielleicht etwas davon mitbringen, wenn Ihr ihnen begegnet?", progress = "Das wird fantastisch. Das ist genau wie Bierbrauen - nur, dass ich statt normalem Wasser diese Wassergeistkörper verwende.", completion = "Sieht für mich wie ganz gewöhnliches Wasser aus. Kaum zu glauben, dass es der Körper einer echten, sich bewegenden Kreatur gewesen sein soll.\n\nIch kann's kaum erwarten, daraus Bier zu brauen und es zu probieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30077] = {title = "Fasswerfen", objective = "Befreit 7 abgefasste Pandaren.", description = "Dieser riesige Ho-zen ist ja wirklich unfassbar! Er wirft mit diesen Fässern einfach nur so um sich!\n\nMit Fässern!\n\nUnd er scheint so gut wie allen Pandaren, die draußen vor der Brauerei gearbeitet haben, eines übergestülpt zu haben. An Eurer Stelle würde ich denen da raushelfen. Dafür könnt Ihr endlich mal Eure ganze Muskelkraft verwenden.\n\nWir sind auf dem Weg zum Hintereingang der Brauerei, im Osten. Kommt am besten auch dahin!", progress = nil, completion = "Was genau fasziniert Affen bloß immer so an Fässern?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30078] = {title = "Hausputz", objective = "Besiegt Eddy, Jooga und den sprudelnden Bierlementar.", description = "So, <Name>, jetzt habe ich wirklich die Nase voll davon.\n\nWenn sich KEINER einen Deut um diese Brauerei schert, werden wir sie für immer verlieren. Und es steckt viel zu viel Familiengeschichte - und Bier - da drinnen, um das zu riskieren.\n\nAlso werden wir durch die Hintertür einbrechen. Ihr, Li Li, Trübtrunk und ich.\n\nDas wird eine echte Massenschlägerei geben.\n\nSagt mir bitte, wenn Ihr bereit seid.", progress = nil, completion = "Schaut Euch um, draußen ist es schon viel ruhiger. Die Brauerei brauchte nur jemanden, der mit starker Hand aufräumt.\n\nEs wird eine Weile dauern, das alles hier wieder auf Vordermann zu bringen, aber das macht mir nichts aus.\n\nImmerhin... dies ist mein Zuhause.", rewards = "Satinkapuze des SeidenmeistersSonnenbeschienener HelmSchuppenhelm des HuangtzeBrünierte PaoquankopfbedeckungSeidene Gugel des GoldfächersEbenenfalkenhelmHelm der Wilden EbenenSchwerer DonnerfußhelmGepanzerter SonnensanghelmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30079] = {title = "Was ist mit Zhus Wacht los?", objective = "Sprecht in Zhus Wacht mit Einwohnern und sucht jemanden, der sich mit Euch unterhalten möchte.", description = "Pandaren heißen Reisende immer mit offenen Armen willkommen - und mit offenen Fässern! Aber diese Stadt voller Trottel!\n\nJeder so damit beschäftigt, übellaunig zu sein, dass niemand je mit Ken-Ken spricht!\n\nKönnt Ihr in der Stadt nach einem suchen, der mit uns spricht? Vielleicht normale Pandaren sich nur in den Häusern verstecken?", progress = nil, completion = "Nur eine Pandadame, die nicht verrückt ist? Das schlimmer als Ken-Ken gedacht hat...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30080] = {title = "Suche nach Yi-Mo", objective = "Sucht nach Yi-Mo Langbraue irgendwo nordöstlich von Zhus Wacht.", description = "Mein Neffe Yi-Mo war immer schon etwas depressiv. Als die Welle der Verzweiflung über der Stadt zusammenschlug, traf es ihn härter als die meisten anderen. Tagelang saß er nur herum und wollte nichts essen. Er starrte nur in die Ferne.\n\nJetzt ist er in Richtung der Klippen nordöstlich von hier davongelaufen, dorthin, wo die Donnervögel nisten und jagen.\n\nKönnt Ihr ihn bitte suchen, <Klasse>?", progress = "<Yi-Mo stößt einen langen Seufzer aus.>", completion = "Lasst mich raten: Meine Tante hat Euch geschickt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30081] = {title = "Materia Medica", objective = "Sammelt 4 Stücke einer Honigwabe, 4 glitschige Matschflosser und 4 salzige Kerne in der Zhu-Provinz.", description = "In Ordnung, Ken-Ken ganz sicher, er weiß, was mit Pandaren nicht stimmt! Habe altes, altes Ho-zen-Heilmittel, das hilft.\n\nMuss Honig, Fischöl und Salz mischen. Ken-Ken hat eine Menge Bienenstöcke in den Bäumen rund um die Stadt gesehen, und in den ausgetrockneten Teichen müssen noch Fische liegen.\n\nDann fehlt noch Salz... Mei weiß vielleicht, wo wir etwas finden.", progress = "Kann nicht glauben, dass Ken-Ken da nicht früher dran gedacht hat. Es ist die EINE Sache, die seinen ganzen Tag ruinieren kann...", completion = "Pandaren leiden an Grusel-Knatzel!\n\nKnatzel erschrecken manchmal und wollen nicht rauskommen. Arme, flauschige Mufpansel müssen bald explodieren!\n\nDas hier wird sie rauslocken. Das macht Pandaren sicher fröhlich!\n\nWie Omma immer gesagt hat: Wer nicht GEHEN kann, kann nicht WERFEN!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMateria-Medica-Outro\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30082] = {title = "Kopf hoch, Yi-Mo", objective = "Bringt Yi-Mo Langbraue zurück nach Zhus Wacht.", description = "Seit dieser Sturm begann, bin ich einfach nur... müde.\n\nNicht körperlich... nein. Es ist, als ob meine Seele erschöpft wäre. Wertlos. Hoffnungslos. Ich denke, so fühlt man sich, wenn man von seiner Gefährtin für jemanden mit runderem Leib verlassen wird. Aber ich hatte noch nie eine Gefährtin, also woher soll ich das wissen?\n\nWie kann ich behaupten, überhaupt etwas zu wissen? Ich bin für alle wertlos, außer für diese Donnervögel. Zumindest gebe ich ein gutes Mahl für sie ab.\n\n<Yi-Mo seufzt tief und starrt weiter in den Himmel. Es sieht nicht so aus, als ob er bald irgendwo hingehen würde.>", progress = nil, completion = "Ich kann nicht glauben, dass er das wirklich vorhatte... Diese Verzweiflung ist schlimmer, als ich je gedacht hätte.\n\nIch kann Euch nicht genug danken, dass Ihr ihn zurückgebracht habt.", rewards = "NayelikapuzeTodesrachenhelmTiefwildhelmNarsongkopfbedeckungAngkhalgugelFlussklingenhelmSarjunhelmKorjanihelmHelm des DojaniIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30083] = {title = "Sicherung der Provinz", objective = "Tötet 10 Saurok oder Kräuterkundige der Wildschuppen in der Provinz Zhu.", description = "Unser Einfluss auf die Provinz wird schwächer. Jetzt haben sich schon Saurok aus der Wildnis in der Höhle gleich nördlich der Stadt eingenistet.\n\nDa die meisten unserer Jäger in Tränen liegen, spazieren die Saurok einfach hier rein, als wären sie hier zu Hause. Sie bedienen sich nach Lust und Laune!\n\nIch möchte ein klares Signal aussenden: Es ist gesünder, sich nicht mit Zhus Wacht anzulegen!\n\nWerdet Ihr <mein Bote/meine Botin> sein?", progress = nil, completion = "Danke, &lt;Name&gt;. Damit dürftet Ihr diesen Wilden ihre Grenzen aufgezeigt haben.", rewards = "Sha-besessenes SchmuckstückHalsreif der VerzweiflungWildschuppenamulettAnhänger des Roten KranichsAnhänger der vergessenen DynastieIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30084] = {title = "Grenzlande", objective = "Entzündet die Gedenkflamme von Zhu, die Gedenkflamme von Rin und die Gedenkflamme von Po entlang der südwestlichen Grenze der Zhu-Provinz.", description = "Lagerfeuer erweisen sich als überraschend effektiv dabei, Bestien zu entmutigen, die Wildnis zu verlassen. Wir verfügen über drei davon an der südwestlichen Grenze, die wir normalerweise ununterbrochen am Brennen halten.\n\nEs war aber seit Tagen niemand dort, sodass die Feuer niedergebrannt sein müssen. Es ist nur eine Frage der Zeit, bis die Wildnis zurückkommt und das Land übernimmt, das wir seit Jahrhunderten gesichert haben.\n\nEntzündet bitte die Lagerfeuer wieder. Sie sind für die Sicherheit der Provinz äußerst wichtig, zudem sind sie Denkmäler für die Begründer unserer Lebensweise.", progress = nil, completion = "Danke, &lt;Name&gt;.\n\nDie Zhu-Provinz dient als Korridor von der oberen Ebene des Tals hinunter zum Meer.\n\nDie Sicherheit der Provinz erfordert tägliche Anstrengungen bei der Erhaltung der Grenze zur wilden Krasarangwildnis.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30085] = {title = "In der Brauerei", objective = "Sprecht mit Chen Sturmbräu in der Brauerei Sturmbräu.", description = "Wir müssen herausfinden, was in dieser Brauerei vor sich geht, <Name>!\n\nWir haben uns zwar vielleicht der größeren Schädlinge entledigt, aber ich bin mir sicher, dass es da wo die herkommen noch mehr gibt. Sammelt ein paar Eurer Freunde um Euch und trefft mich im Inneren!", progress = nil, completion = "Ihr seid gekommen! Großartig!\n\nIch freue mich schon darauf, erneut an Eurer Seite zu kämpfen, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30086] = {title = "Die Suche nach dem verborgenen Meister", objective = "Hört Euch das Gespräch zwischen Xiao und seinen Freunden an.", description = "Oh, hallo. Sucht Ihr nach dem Besitzer dieser Einrichtung? Dann geht zu dem Pandaren oben an der Treppe. Ich bin bloß zu Besuch hier... genau wie Ihr.\n\nWenn Ihr mich nun entschuldigen würdet, meine Freunde und ich haben etwas zu besprechen. Wir können uns danach wieder unterhalten.", progress = nil, completion = "Habt Ihr etwa zugehört? Keine Sorge, das macht mir nichts aus. Ihr könnt Euch gern an der Suche nach dem verborgenen Meister beteiligen.\n\nAber wenn Ihr ihn finden solltet, würde ich es zu schätzen wissen, wenn Ihr wieder hierherkommt und es uns mitteilt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30088] = {title = "Warum so ernst?", objective = "Sammelt 18 riesige Pantherreißzähne und 1 Pigmentkrug aus der Provinz Zhu.", description = "Schön, funktioniert nicht. Gut... Ken-Ken freut sich! Aber Pandaren immer noch traurig...\n\nWir versuchen anderes altes Ho-zen-Heilmittel - diesmal gehen wir noch weiter zurück als Omma, viel, VIEL weiter zurück zu alten Zeiten. Ho-zen machen das manchmal immer noch... meistens auf Feiern.\n\nKen-Ken hat Holz zu bearbeiten - Bringt ihm Zähne! Nicht Eure. Große Zähne wie von Panther!\n\nOh, und etwas Farbe! Mei weiß vielleicht, wo Ihr suchen könnt.", progress = "<Ken-Ken arbeitet hart dran, etwas aus der Baumrinde zu schnitzen.>\n\nDas wird toll, Ihr werdet schon sehen.", completion = "Gerade rechtzeitig! Komplett fertig... Seht!\n\n&lt;Ken-Ken hält eine geschnitzte Holzmaske mit einem albernen Gesicht hoch.&gt;\n\nJetzt noch ein paar Feinheiten und wir haben eine garantiert funktionierende SPASSMASCHINE!", rewards = "Handlappen des DojaniKorjanihandwickelSarjunhandlappenFlussklingenhandlappenAngkhalhandschützerNarsonghandlappenTiefwildhandschützerTodesrachenhandlappenNayelihandlappenDer folgende Zauber wird auf euch gewirkt:\n\nWhy So Serious?: Outro\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30089] = {title = "Ein Brett vor dem Kopf", objective = "Setze Ken-Kens Maske ein, um 8 bedrückte Wächter von Zhu in Zhus Wacht zu heilen.", description = "Also... DAS kam unerwartet!\n\nWas ich noch sagen wollte, Ken-Ken hat sich erinnert, warum Ho-zen Maske zuerst benutzt haben...\n\nDie Legende vom Affenkönig sagt, er habe eine Maske benutzt, um den alten Pandarenkaiser Shaohao zu heilen, als er zu traurig war, um seine Leute zu führen. Dann haben sie Maske begraben - mit seiner ganzen Traurigkeit - im Boden.\n\nWir sollten die Maske bei mehr Pandaren benutzen, aber anstatt Traurigkeit im Boden zu begraben, werden wir ihr IN DEN HINTERN TRETEN.\n\nMachen wir es so, <Name>!", progress = nil, completion = "Wir retten Pandaren, aber das Land immer noch traurig... Seht, Regen hört gar nicht auf!\n\n&lt;Ken-Ken schüttelt seine kleinen Fäuste gen Himmel.&gt;\n\nIn wie viele Hintern müssen wir treten, bevor in dieser Stadt wieder alles im Lot ist?!\n\n&lt;Der Himmel verfinstert sich als Antwort darauf.&gt;", rewards = "NayeligamaschenTodesrachenbeinschützerTiefwildbeinschützerNarsongbeinplattenAngkhalhosenFlussklingenbeinschützerSarjungamaschenKorjanibeinschützerBeinschützer des DojaniDer folgende Zauber wird auf euch gewirkt:\n\nSad Panda Town Weather - Heavy\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30090] = {title = "Zhus Verzweiflung", objective = "Exorziert das Sha der Verzweiflung aus Yi-Mo Langbraue in Zhus Wacht.", description = "Hmm... Ist das da hinten der kleine Yi-Mo?\n\n<Ken-Ken blinzelt gegen den zunehmenden Regenguss.>\n\nIst er! Er ist am Brunnen und er sieht gar nicht gut aus.\n\nKen-Ken hat ein ganz schlechtes Gefühl...", progress = nil, completion = "Wir haben hier und heute gute Arbeit geleistet, &lt;Name&gt;.\n\nDas Kloster sagt uns immer, wir sollen einen Ort besser zurücklassen, als wir ihn vorfanden.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKen-Kens Maske\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][30091] = {title = "Tränen von Pandaria", objective = "Tötet 12 weinende Schrecken in der Zhu-Provinz.", description = "Dies alles hat bei unseren Teichen angefangen. Das ganze Wasser hat sich an einem einzigen Tag in die Erde zurückgezogen. Als alles Wasser aus den Teichen verschwunden war, begann es vom Himmel herabzufallen.\n\nTrotz endloser Regengüsse füllen sich die Teiche nicht. Es ist, als ob das Land selbst einen Durst hätte, der nicht gestillt werden kann.\n\nNun entspringen den Teichen schreckliche Manifestationen der Verzweiflung. Elementare aus dem Wasser des Himmels und dem Salz der Erde: die Tränen von Pandaria.", progress = nil, completion = "Danke, &lt;Klasse&gt;.\n\nEs ist Zeit, dass wir unser Land diesem Fluch entreißen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSad Panda Town Weather - Medium\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30092] = {title = "Der Spitzel von Gilneas", objective = "Macht Zazzo Glitzerfinger nahe der Ruinen von Gilneas in Gilneas ausfindig.", description = "Wenn Ihr Euch mir anschließen und die untergetauchten schwarzen Drachen abschlachten wollt, behauptet Euch und tötet Hiram Altair. Er versammelt eine Armee in Gilneas.\n\nBisher ist uns nicht geglückt, an seinen Wachen vorbeizukommen, aber wir haben einen Mann vor Ort, der ihn nicht aus den Augen lässt. Zazzo Glitzerfinger, ein handwerklich geschickter arkaner Magier, der darauf wartet, dass wir mit ihm außerhalb der Ruinen der gilnearischen Hauptstadt Kontakt aufnehmen.\n\nFindet ihn, er wird Euch den Weg weisen.", progress = nil, completion = "Rabenholdt hat Euch gesandt? Ich hoffe, dass Ihr ein besserer Attentäter seid, als die anderen.", rewards = nil}
MultiLanguageQuestData['de'][30093] = {title = "Altair assassinieren", objective = "Schleicht Euch in die Ruinen von Gilneas und tötet Hiram Altair im Militärviertel.", description = "Seit Tagen schon herrscht Chaos in der Stadt. Hiram Altair, als Gilneer verkleidet, hat die meisten dieser Hunde mit seinem eigenen drakonischen Blut infiziert. Sogar die Verlassenen tun sich schwer, ihn zu überwinden.\n\nEinzig ein sauberer Mord kann das beenden!\n\nDie Brücke hinter mir ist relativ unbewacht. Begebt Euch über den Händlerplatz Richtung Süden - dort werdet Ihr Altair mitten im Militärviertel finden.\n\nIch werde Euch im Auge behalten und eingreifen, sollten Probleme auftauchen.\n\n...Und es WIRD Probleme geben!", progress = "Hiram Altair. Unter den schwarzen Drachen ist er als \"Altaitharus\" bekannt.", completion = "Altair ist vernichtet. Die Gilneer, die ihm gefolgt sind, sind jetzt allein, vorausgesetzt, dass sie nicht an seinem verderbten Drachenblut sterben.\n\nDoch egal, was mit ihnen geschieht, sie stellen nicht länger eine Gefahr für uns dar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30094] = {title = "Die Endzeit", objective = "Sprecht mit Nozdormu in der Endzeit.", description = "Nozdormu, der bronzene Drachenaspekt, hat die Champions der Horde um Hilfe gebeten. Auch Ihr wurdet auserwählt. Mehr kann ich Euch nicht sagen.\n\nEs ist äußerst ungewöhnlich, dass mein Meister sterbliche Wesen um Hilfe bittet, aber ich vermute, dass die Zeit alles verändert... sogar den Aspekt der Zeit selbst.\n\nEr wartet auf Euch in der Endzeit, in ferner Zukunft. Ich kann Euch helfen, dorthin zu gelangen, wenn Ihr es wünscht.", progress = nil, completion = "&lt;Name&gt;, Ihr seid angekommen. Das ist gut. Ich möchte mich entschuldigen, dass ich Euch unter so verdächtigen Umständen zu diesem seltsamen Ort gebracht habe.\n\nIch habe einen guten Grund dafür.\n\nWir werden Todesschwinge töten. Und ich brauche Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30095] = {title = "Die Endzeit", objective = "Sprecht mit Nozdormu in der Endzeit.", description = "Nozdormu, der bronzene Drachenaspekt, hat die Champions der Allianz um Hilfe gebeten. Auch Ihr wurdet auserwählt. Mehr kann ich Euch nicht sagen.\n\nEs ist äußerst ungewöhnlich, dass mein Meister sterbliche Wesen um Hilfe bittet, aber ich vermute, dass die Zeit alles verändert... sogar den Aspekt der Zeit selbst.\n\nEr wartet auf Euch in der Endzeit, in ferner Zukunft. Ich kann Euch helfen, dorthin zu gelangen, wenn Ihr es wünscht.", progress = nil, completion = "&lt;Name&gt;, Ihr seid angekommen. Das ist gut. Ich möchte mich entschuldigen, dass ich Euch unter so verdächtigen Umständen zu diesem seltsamen Ort gebracht habe.\n\nIch habe einen guten Grund dafür.\n\nWir werden Todesschwinge töten. Und ich brauche Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30096] = {title = "Murozond", objective = "Tötet Murozond.", description = "Wenn wir Todesschwinge töten wollen, benötigen wir die Macht der Drachenseele. Um die Drachenseele zu erhalten, müsste ich Euch zur Zerschlagung zurückbringen, zehntausend Jahre in die Vergangenheit… aber dieser Zeitpfad ist mir versperrt.\n\nDas Monster, das uns den Weg zu diesem Zeitpfad blockiert, heißt Murozond. Er muss hier und jetzt, in dieser verqueren Zukunft, getötet werden, damit wir unsere Mission fortsetzen und Todesschwinge aufhalten können.\n\nDeshalb seid Ihr hier, <Name>.", progress = nil, completion = "Murozond ist tot. Die Pfade der Zeit stehen mir wieder offen.", rewards = "BronzeblasterStiefel des verzweigten WegesStulpen des ZeitverzerrersGugel des SchicksalsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30097] = {title = "Hilfsarchivar", objective = "Tötet zwei der Echos in der Endzeit und gebt Alurmis Behältnis die Gelegenheit, ihre Informationen zu archivieren.", description = "So wie ich das sehe, möchtet Ihr diese Zukunft also abwenden. Nun, wenn dem wirklich so ist, müssen wir Daten aus dem Zeitstrang archivieren, bevor sie verloren sind.\n\nWir denken, dass die interessantesten und wertvollsten aller Elemente dieser Zukunft die mächtigen \"Echos\" sind, die im Bronzedrachenschrein widerhallen.\n\nNehmt dieses Gefäß an Euch, um die Echos verstummen zu lassen. Ein Teil ihrer Energie wird vom Bronzenen Drachenschwarm eingelagert.", progress = "Nozdormu handelt in Eile, was er gewöhnlicherweise nicht tut.\n\nAn normalen Tagen würde ich die Archivierung gründlicher durchführen, doch aufgrund dieser Umstände können wir nur einen Teil unserer Funde ins Archiv aufnehmen... und wir müssen Söldner wie Euch anheuern.", completion = "&lt;Alurmi nimmt Euch das Behältnis ab.&gt;\n\nVon hier an werde ich mich darum kümmern. Sie müssen sorgfältig benannt, dokumentiert und eingelagert werden.", rewards = "Handschuhe des ArchivarsHalbmondzauberstabZeitstrangstulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30098] = {title = "Der Brunnen der Ewigkeit", objective = "Sprecht mit Nozdormu am Brunnen der Ewigkeit.", description = "Wir müssen uns beeilen, bevor die übriggebliebenen ewigen Agenten einschreiten. Zeit ist kostbar.\n\nIch werde Euch jetzt aus Eurer fernen Zukunft weit zurück in die Vergangenheit bringen... zum Krieg der Ahnen. Unser Ziel ist die Drachenseele, ein Artefakt mit immenser Macht... genug, um Todesschwinge zu besiegen und seine Herrschaft über die Gegenwart zu beenden.", progress = nil, completion = "Lasst uns fortfahren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30099] = {title = "In Scharen", objective = "Deaktiviert die drei Dämonenportale und erschlagt dann Peroth'arn.", description = "Zwischen uns und der Drachenseele liegt eine Dämonenlegion. Bevor wir weiterziehen, müssen wir sie erledigen.\n\nWenn meine Zeiteinschätzung stimmt - wie normalerweise - sollte in Bälde ein Nachtelf mit Namen Illidan Sturmgrimm unseren Weg kreuzen. Er wird uns zweifelsohne von großem Nutzen sein bei der Dämonenjagd.\n\nHelft Illidan dabei, die Dämonenportale zu deaktivieren, tötet dann Peroth'arn, den Dämonenanführer.", progress = "Ihr solltet für den Moment jegliche Vorurteile gegenüber Illidan ablegen. Vergesst nicht, Ihr befindet Euch zehntausend Jahre in der Vergangenheit und er darf nicht für zukünftige Verbrechen bestraft werden.", completion = "Gut. Wir marschieren weiter.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30100] = {title = "Die Selbstherrlichen", objective = "Beseitigt Königin Azshara.", description = "Königin Azshara und ihre königliche Wache befinden sich vor uns. Wir können es uns nicht erlauben, dass irgendetwas unserem Plan in die Quere kommt. Also werden wir sie angreifen, bevor sie die Gelegenheit hat, sich einzumischen.\n\nEs ist eher unwahrscheinlich, dass Ihr Königin Azshara heute tötet; es existieren nur wenige verständliche Zeitstränge entlang dieses Pfades. Betrachtet es als einen Sieg, wenn Ihr es schafft, kurzzeitig ihre Aufmerksamkeit zu erringen.", progress = "Azshara und ihre Schmeichler haben sich lange auf diesen Tag vorbereitet. Sie wird über unsere Einmischung nicht erfreut sein.", completion = "Wir sind nur Momente von der Drachenseele entfernt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30101] = {title = "Der Weg zur Drachenseele", objective = "Tötet Mannoroth.", description = "Ich kann nicht einfach hochfliegen und die Drachenseele schnappen. Die Alten Götter beschützen sie.\n\nSchlimmer noch, der Schild der Götter ist von den wirbelnden arkanen Energien des Brunnens der Ewigkeit gestärkt und diese Energien werden von dem mächtigen Dämon Mannoroth fokussiert.\n\nLenkt Mannoroth ab und die Verbindung zwischen der Drachenseele und dem Brunnen wird unterbrochen. Ohne die Kraft des Brunnens ist der Schutz der alten Götter geschwächt und die Drachenseele ungeschützt.\n\nUnd dann werde ich sie an mich nehmen.", progress = "Was?", completion = "Danke für Eure Hilfe.\n\nIhr kämpft gut. Ich hoffe, in der Zukunft noch einmal an Eurer Seite zu kämpfen.", rewards = "EisenfederlangbogenKette des DämonenjägersStiefel des tückischen PfadsAuf Euch wartet eine dieser Belohnungen:\n\nDämonischer Schädel\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][30102] = {title = "Die Stunde des Zwielichts", objective = "Sprecht mit Thrall in der Stunde des Zwielichts.", description = "Es ist nicht nötig, hier so lange herumzustehen. Habt Ihr vergessen? Wir KONTROLLIEREN DIE ZEIT. Erst recht, seitdem Ihr diesen Murozond in der Zukunft beseitigt habt.\n\nDie Drachenseele, die Ihr gerade befreit habt? Thrall hat sie schon, in Eurer Gegenwart. Und er wird Eure Hilfe benötigen.\n\nSeid Ihr bereit?", progress = nil, completion = "Ihr seid eingetroffen.\n\nGut, lasst uns anfangen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30103] = {title = "Auf zum Wyrmruhtempel!", objective = "Eskortiert Thrall sicher zum Wyrmruhtempel.", description = "Die Drachenseele... eine Waffe mit genug Macht, Todesschwinge zu besiegen. Dank Euch ist sie jetzt sicher in unserer Hand.\n\nKommt! Die Aspekte erwarten uns. Wir müssen die Drachenseele zum Wyrmruhtempel im Zentrum der Drachenöde bringen.", progress = "Kommt, <Name>. Es ist nicht mehr weit.", completion = "Ich verdanke Euch mein Leben, Helden.\n\nJetzt, da sich die Drachenseele sicher in Wyrmruh befindet, verdanken vielleicht alle Bewohner Azeroths Euch ihr Leben.", rewards = "SicherheitshandschuheSattelgurt des WeltenschamanenAuf Euch wartet eine dieser Belohnungen:\n\nRing des treuen Gefährten\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][30104] = {title = "Dokumentation der Zeitwege", objective = "Tötet einen Dämon der brennenden Legion, eine königliche Hofdame und Hauptmann Varo'then und gebt Alurmis Behältnis die Gelegenheit, ihre Informationen zu archivieren.", description = "Ihr… <Name>, richtig? Ihr habt uns bereits in der Vergangenheit mit unserer Archivierung geholfen. Nun ja, genau genommen war es in der Zukunft, aber ich glaube, Ihr wisst, was ich meine. Zeit ist höchstgradig relativ.\n\nIch benötige mehr Informationen für unser Archiv. Da Ihr und Nozdormu nicht vorhabt, diesen Zeitstrang zu überschreiben, wie in der Endzeit, können wir noch mehr Informationen gewinnen.\n\nIch benötige Informationen über Hauptmann Varo'then, einen von Azsharas hübschen Handlangern und... hmm... oh, wie sieht es mit der Teufelswache unterhalb der Treppe aus?", progress = nil, completion = "Nur selten haben wir die Gelegenheit, jemand so Mutiges wie Euch zu beschäftigen, &lt;Klasse&gt;. Dank Eurer Bemühungen konnte unser Archiv weiter vervollständigt werden.", rewards = "Treter der VergangenheitBrustschutz des ChronistenSchärpe des HistorikersAuf Euch wartet eine dieser Belohnungen:\n\nAlurmis Ring\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][30105] = {title = "Der Zwielichtprophet", objective = "Findet und enttarnt den Zwielichtpropheten.", description = "In dem Schreiben steht Folgendes:\n\n\"Die Stunde des Zwielichts ist gekommen. Der Weltenschamane Thrall nähert sich mit der Drachenseele Wyrmruh und droht noch ein letztes klägliches Mal, unseren glorreichen Meister zu vernichten.\"\n\n\"Haltet Thrall auf und wir werden unseren Krieg gewinnen. Ich werde Euch aus der Nähe beobachten.\"\n\n ~Der Zwielichtprophet", progress = nil, completion = "Es ist genauso, wie wir es vorhergesehen haben: Benedictus war der Zwielichtprophet. Und jetzt weilt er nicht mehr unter uns.\n\nWir haben dem Schattenhammer heute einen mächtigen Schlag verpasst. Lasst uns hoffen, dass es sein Ende bedeutet.", rewards = "Zuckender ZauberstabAuf Euch wartet eine dieser Belohnungen:\n\nThralls DankbarkeitSignet des Zwielichtpropheten\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][30106] = {title = "Es ist vollbracht", objective = "Meldet Prinz Furorion im Rabenholdtanwesen im Vorgebirge des Hügellands Euren Erfolg.", description = "Prinz Furorion wird erfreut sein, von Eurem Erfolg zu erfahren. Begebt Euch zum Rabenholdtanwesen und erstattet ihm Bericht.\n\nDer Prinz ist bekannt dafür, seine Helfer äußerst großzügig zu entlohnen.", progress = nil, completion = "Das sind wunderbare Neuigkeiten, &lt;Name&gt;. Altair war nicht der mächtigste der verbleibenden schwarzen Drachen, doch wie er die Gilneer manipuliert hat, war wahrlich bösartig.\n\nIch habe eine Belohnung für Euch vorbereitet. Diese Klingen mögen im Moment vielleicht nicht nach viel aussehen, doch in den richtigen Händen könnten sie zum Leben erwachen.\n\nVielleicht ja in EUREN Händen...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSummon Completion Event Bunny\n\nIhr bekommt:\n\nFurchtRache"}
MultiLanguageQuestData['de'][30107] = {title = "Gelege im Gehege", objective = "Sammelt 333 schattenhafte Edelsteine durch das Plündern von Elementiumedelsteinformationen von den Kreaturen in der Drachenseeleninstanz.", description = "Die Dolche, die ich Euch gegeben habe, sind leblose Hüllen. Doch sie vermögen Großes zu vollbringen, wenn sie erst einmal in der Lage sind, die Art Macht zu speichern, an die ich denke.\n\nIhr müsst für mich Schattenedelsteine finden. Die Oberfläche dieser außergewöhnlichen Steine ist wie ein Fenster in die Unendlichkeit. Oftmals werden sie von Dienern des Schattenhammers benutzt, um die mächtigsten aller Elementare zu kontrollieren.\n\nAm Wyrmruhtempel tobt eine erbitterte Schlacht. Sammelt Elementiumedelsteine von Todesschwinges Dienern und bringt sie mir.", progress = "Wie viele Edelsteine habt Ihr gesammelt?\n\nSind die Diener meines Vaters genauso verderbt wie er?", completion = "Ah, seht Ihr, wie sie schimmern? Viele hochwertige Edelsteine glänzen im Licht, doch nur diese hier scheinen dunkel zu funkeln.\n\nIch werde sie verzaubern, während Ihr auf Eurer nächsten Mission seid.\n\nSeid Ihr bereit?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSummon Completion Event Bunny\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30108] = {title = "Der Spitzel von Karazhan", objective = "Meldet Euch bei Zazzo Glitzerfinger in den Ruinen südöstlich von Karazhan.", description = "Euer nächstes Ziel ist der schwarze Drache Yntrige, der unter den Ruinen des Turms von Karazhan in eine Art arkane Entartung verwickelt ist.\n\nEure Hauptaufgabe ist es, Yntrige zu töten, aber wenn es Euch gelingt, mir eine Phiole ihres Blutes zu bringen, kann ich es nutzen, um die Dolche, die ich Euch gab, zu verstärken.\n\nZazzo, Euer Komplize, ist bereits auf dem Weg und wird Euch vor Ort erwarten. Er hat weitere Details für Euch.", progress = nil, completion = "Wahnsinn. Das ist verrückt!\n\nIch weiß nicht, was Yntrige dort unten vorhat, aber das gesamte Untergeschoss strahlt nur so vor boshafter arkaner Energie. Ein ganzer Kult verehrt sie als seine Göttin.\n\nWenn wir sie töten wollen, müssen wir das bald tun. Ich hoffe, Ihr seid hierfür bereit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30109] = {title = "Blut des Verräters", objective = "Schleicht Euch in den Keller des Meisters in den Ruinen um Karazhan, besiegt Yntrige und beschafft Euch eine Phiole mit schwarzem Drachenblut.", description = "Ich habe Yntrige im Keller des Meisters aufgespürt, ein weitläufiges Gemäuer, das sich in den Ruinen da vorn befindet.\n\nEs wimmelt von Drachenkultisten und Yntrige hat im gesamten Gebiet sonderbare Geräte zum Sammeln arkaner Energie aufgestellt. Vielleicht wisst Ihr sie zu Eurem Vorteil zu nutzen?\n\nGelangt unbemerkt an den Kultisten vorbei, tötet Yntrige und nehmt eine Phiole mit ihrem Blut für Furorion an Euch.\n\nIch behalte Euch im Auge und hol Euch da raus, wenn es Probleme gibt. Aber ich begleite Euch NICHT mit rein!", progress = "Yntrige. Tot?", completion = "Ihr wart erfolgreich? Sie ist tot? Unglaublich! Ihr habt ein Wunder vollbracht!\n\nZeigt mir das Blut. Ich kann seine Energien in einer arkanen Matrix für Euren Heimweg aufbewahren...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30110] = {title = "Raid Finder (1st)", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][30111] = {title = "Raid Finder (Nth)", objective = "Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30112] = {title = "Eine Rechnung begleichen", objective = "Dunkelläuferin Marrah möchte, dass Ihr Prinz Keleseth in Burg Utgarde tötet.", description = "Utgardes Horden organisieren sich mit Hilfe der Ratschläge von Keleseth, dem San'layn-Botschafter der Geißel.\n\nWir können es nicht länger zulassen, dass die Vrykul von diesem Rat profitieren. Bringt ihn zum Schweigen.", progress = nil, completion = "Rache ist süß. Und dies ist nur ein Vorgeschmack dessen, was Arthas noch bevorsteht.\n\nEr wird früh genug das bekommen, was er verdient hat.", rewards = "Wickel der San'laynVendettabindungenArmschienen des RunenmagiersUnterarmschienen des VergeltungsbringersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30113] = {title = "Sieg in den Tiefen", objective = "Bringt die Phiole mit konserviertem Drachenblut und Eure Dolche Furcht und Rache zu Furorion im Rabenholdtanwesen im Vorgebirge des Hügellands.", description = "<Zazzo verzaubert die Phiole voll Blut und gibt sie Euch dann so schnell zurück, als ob sie giftig wäre.>\n\nFertig! Die Phiole und Eure zwei Dolche sollten so schnell wie möglich zurück zu Furorion.\n\nIch weiß nicht, was er mit diesem Krams vorhat. So ganz unter uns, manchmal macht mir das kleine Drachenbalg Angst. Viel Glück!", progress = "Ah, Ihr seid zurückgekehrt! Ich kann Yntriges Gegenwart nicht mehr spüren. Ist sie tot? Oder ist sie irgendwie uns beiden entkommen?", completion = "Ihr seid wahrlich ein Meister Eures Faches. Yntrige ist tot und es ist Zeit, dass Ihr für Eure Bemühungen belohnt werdet.\n\n&lt;Furorion nimmt die Phiole von Euch entgegen, sein Gesicht zeigt sowohl Verehrung als auch Verachtung. Er lässt die von Euch gesammelten Edelsteine einzeln in das Blut fallen und murmelt einen Zauberspruch.&gt;\n\n&lt;Ohne Vorwarnung gießt er das Blut über die Klingen der Dolche, deren Stahl sich wie lebendig zu winden und zu drehen scheint. Als sich der Rauch lichtet, haben die Dolche ihre Form verändert.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSummon Completion Event Bunny\n\nIhr bekommt:\n\nDer SchläferDer Träumer"}
MultiLanguageQuestData['de'][30116] = {title = "Wetzt Eure Klauen", objective = "Sammelt 60 Elementiumedelsteinformationen von den Kreaturen in der Drachenseeleninstanz.", description = "Wisst Ihr, warum ich Euch auftrage, die Drachen zu töten und das Leben der Sterblichen zu verschonen? Sie trifft keine Schuld. Sie müssen ihren eigenen Weg finden, ohne dass sich mein Volk einmischt.\n\nWir nähern uns dem Ende unserer Mission und es ist nun für Euch an der Zeit, Euren eigenen Weg zu wählen. Ich werde auch weiterhin Eure Waffen aufwerten, doch einzelne Schattenedelsteine werden dafür nicht mehr ausreichen. Ich benötige Elementiumedelsteinformationen. Ihr findet sie bei den Dienern meines Vaters...", progress = "Wie viele Formationen habt Ihr erhalten?\n\nDie Zähigkeit Eures Volkes ist mir weiterhin eine Inspiration!", completion = "Ihr habt es geschafft! Ich bin mir sicher, dass Ihr Euch und Eure Verbündeten in große Gefahr gebracht habt, um diese Edelsteine zu erhalten. Die von Euch erbrachten Opfer sollen belohnt werden. Ich werde die Edelsteine als Basis für eine mächtige Verzauberung benutzen.\n\nAber wir brauchen noch eine weitere Zutat. Seid Ihr bereit für Eure letzte und gefährlichste Mission, &lt;Klasse&gt;?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSummon Completion Event Bunny\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30117] = {title = "Steinpflug ist durstig", objective = "Liefert ein Fässchen Kaiserbier an Lun Mai in Steinpflug im Tal der Vier Winde.", description = "Entschuldigung... <Name>? Habe ich Euren Namen richtig verstanden?\n\nIch komme aus Steinpflug im Westen. Man hat mich geschickt, um Notvorräte an Bier zu besorgen, aber die Brauerei Sturmbräu ist mit Brettern zugenagelt!\n\nEuer ansehnlicher Freund da - nein, nicht Trübtrunk, der andere - scheint ein paar Fässer zu haben. Könntet Ihr vielleicht ein Fässchen für eine Stadt in Not erübrigen?", progress = "Grüße, <Klasse>.", completion = "Endlich! Emmi ist zurück.\n\nIch hoffe, in der Brauerei Sturmbräu ist alles in Ordnung. Meine Männer machen ohne Bier nämlich nicht sonderlich viel her.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30118] = {title = "Vatermord", objective = "Vernichtet Todesschwinge und bergt ein Fragment von seinem Kiefer.", description = "Euer nächstes Ziel hat das Leben all meiner bisherigen Auftragsmörder gefordert. Ihr müsst meinen eigenen Vater für mich töten.\n\nIhr müsst Todesschwinge vernichten.\n\nDie Zeit wird knapp, denn sein Wahn hat bereits alle meiner Art verderbt und wenn er nicht aufgehalten wird, wird seine Dunkelheit die gesamte Welt verschlingen.\n\nWenn Ihr, auf wundersame Weise, erfolgreich seid und mir etwas von ihm bringt - einen Teil seiner Rüstung mit der er seine wahre chaosbringende Natur verhüllt hat - werde ich Euch eine Belohnung geben, die ihresgleichen sucht.", progress = "Was ist mit meinem Vater?", completion = "Ich kann es spüren, es ist wie ein dunkler Schatten, der sich vom Land hebt. Mein Vater ist tot!\n\n&lt;Furorion nimmt das Kieferfragment entgegen. Seine Hände und sein Gesicht verschwimmen, während er eine dunkle Verzauberung murmelt und die Edelsteinformationen, die Ihr zuvor gesammelt habt, um seinen Kopf schwirren. Plötzlich zerbricht das Fragment des Kiefers, und mit einem furchtbaren Zischen erwachen Eure Zwillingsdolche.&gt;\n\nEure Belohnung ist fertig. Schnell, nehmt sie. Ihr werdet sie gleich brauchen...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSummon Cutscene Vehicle\n\nIhr bekommt:\n\nGolad, Zwielicht der AspekteTiriosh, Alptraum der Zeitalter"}
MultiLanguageQuestData['de'][30120] = {title = "Die Reinigung Drak'Tharons", objective = "Drakuru möchte, dass Ihr Drakurus Elixier an seinem Kohlenbecken innerhalb Drak'Tharons benutzt. Um das Elixier dort benutzen zu können, benötigt Ihr 5 Ausdauermojos.\n\nBereitgestellter Gegenstand: \n", description = "Bald wird Drak'Tharon von den verdorb'nen Untoten gereinigt und wieder ihrer ursprünglichen noblen Aufgabe unterstellt werd'n. Als Belohnung für deine Hilfe werd'n dir die wertvollsten Schätze der Feste zur Verfügung steh'n, Mann!\n\nSobald du ihre Spitze erreicht hast, musst du mich beschwör'n, und ich führ' das Ritual durch.\n\nAber mich zu ruf'n, Mann, wird einiges kost'n. Du musst das Mojo von den Überlebenden sammeln.", progress = nil, completion = "Wir ham' großes geleistet, Mann! Un' das is' nur der Anfang…\n\nSuch mich in Zul'Drak auf, wenn die Zeit reif is'.\n\nEs gibt 'nen Krieg zu gewinnen, Mann!", rewards = "Verführerische SabatonsSchultern des VerführersFesseln des dunklen GeflüstersSchleier der VerführungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30121] = {title = "Suchtrupp", objective = "Sucht in den Krasariruinen nach Chezin Morgenjäger.", description = "Ich habe einen Diplomaten entsandt, um in den Ruinen östlich von hier nach Verbündeten zu suchen.\n\nMein Diplomat ist noch nicht zurückgekehrt, und nun erzählt Kang mir auch noch, dass in diesem Dschungel ein übles Volk namens Mogu sein Unwesen treibt.\n\nChezin ist mein Freund und Lezas Bruder. Der Verlust eines Bruders würde sie zur Verzweiflung treiben. Sie macht sich wegen ihres Fiebers schon genug Sorgen.\n\nKönntet Ihr in den Ruinen östlich von hier Nachforschungen anstellen und in Erfahrung bringen, was geschehen ist?", progress = nil, completion = "G... Gift. Muss... Dezco... warnen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30122] = {title = "Filigranes Silberfläschchen", objective = "Füllt die Phiole mit einer mächtigen alchemistischen Mixtur.", description = "Ihr habt eine wunderschöne silberne Flasche mit filigraner Verzierung gefunden. Mit den richtigen Materialien und Euren Fähigkeiten in der Alchemie könntet Ihr etwas wirklich Magisches daraus machen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFläschchen des Alchemisten"}
MultiLanguageQuestData['de'][30123] = {title = "Huschereintopf", objective = "Sammelt 5 unversehrte Huscherdrüsen.", description = "Leza hat Fieber. Keine Mutter, die in Wehen liegt, sollte Fieber haben.\n\nMama Dornstab hat mir einst erzählt, dass Huschereintopf nahezu jede Krankheit heilen könne. Unterziehen wir dieses Wissen einer Prüfung.\n\nBesorgt mir ein paar unversehrte Huscherdrüsen, während ich die benötigten Kräuter sammle, dann werde ich einen Eintopf zubereiten.", progress = "Sogar in der Luft des Dschungels wimmelt es vor Gefahren.", completion = "Ausgezeichnet! Für Kranke gibt es nichts Besseres als einen Huschereintopf.\n\nHier, nehmt das. Es ist ein kleines Erinnerungsstück von Mama Dornstab.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30124] = {title = "Blendet sie!", objective = "Tötet die Vorreiterin von Darnassus.", description = "Diese Sonnenläufer sind ein lästiger Haufen. Ich brauche Soldaten, in denen Hordenblut fließt und ein Kriegerherz schlägt... keinen pazifistischen Sonnenabschaum.\n\nDie Allianz ist hier, $p. Sie müssen uns gefolgt sein oder irgendwie dieselbe Vision gesehen haben, mit der Leza uns hierher geführt hat. Es spielt keine Rolle. Sie dürfen nicht wissen, wie uneins wir momentan sind. Eliminiert ihren Späher südlich von hier, bevor er Bericht erstatten kann.\n\nMöge Höllschrei über Euch wachen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Ihr habt Euch vortrefflich geschlagen und uns etwas Zeit verschafft, unsere Verteidigung zu verstärken. Jetzt muss ich nur noch Dezco dazu bringen, in die Offensive zu gehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSummon Thunder Cleft Conversation Bunny 1\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30127] = {title = "Bedrohung aus Dojan", objective = "Tötet 6 Dojanieroberer, 8 Dojanispäher und 4 Dojanivollstrecker.", description = "Mogu? Sie scheinen den Elfen zu ähneln - ein uraltes Volk mit einem überzogenen Anspruchsdenken. Alle in Azeroth müssen früher oder später lernen, dass die Horde diese Welt nicht \"besucht\". Wir sind hier, und wir bleiben hier.\n\nLehrt sie diese Lektion. Dünnt ihre Reihen in den Ruinen südlich und westlich von hier aus. Zerschmettert ihre wachsenden Streitkräfte, bevor sie sich für einen Angriff entscheiden.\n\nBringt in Erfahrung, wie diese Kreaturen kämpfen und wie sie sterben.", progress = nil, completion = "Das hier ist mehr als nur eine Bedrohung durch Banditen. Es handelt sich bei ihnen um ein altes Volk, das sich unter einem einzigen Banner sammelt. Lasst Euch das gesagt sein, diese Lande werden bald den Krieg kennenlernen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30128] = {title = "Die Teiche der Jugend", objective = "Besorgt Wasser aus den Teichen der Jugend.", description = "Die Mogu haben die Teiche der Jugend gefunden!\n\nMama Dornstab hat mir alte Geschichten über sie erzählt. Zur Zeit des Mogukaiserreichs wurde das Wasser benutzt, um die Lebensdauer zu verlängern.\n\nAber aus irgendeinem Grund ging keine dieser Geschichten gut aus. Es scheint fast, als wäre das Wasser verflucht.\n\nWir sollten dieser Sache jedenfalls nachgehen. Es ist schließlich möglich, dass das Wasser Leza helfen könnte.\n\nAllem Anschein nach liegen die Teiche der Jugend an der Nordwestseite der Ruinen.", progress = "Leza hat sehr große Schmerzen. Nur Mächte, die meine eigenen übersteigen, können sie und das Kind jetzt noch retten.", completion = "Ich bin soweit, dass ich alles versuchen würde. Dieses Land droht mir meine Frau und mein ungeborenes Kind wegzunehmen. Ich brauche alle Hilfe, die ich kriegen kann.", rewards = "Tuch der LaguneWasserfalltuchBaldachintuchGrünrückencapeBalsamtuchIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30129] = {title = "Die Moguagenda", objective = "Bergt die Dojani-Befehle.", description = "Mogu versammeln sich nicht oft in so großer Zahl. Wir sollten in Erfahrung bringen, was sie planen.\n\nIch meine, gehört zu haben, wie jemand in der Nähe des Zentrums der Ruinen Befehle brüllt.\n\nWir sollten nachsehen, ob dieser Jemand nützliche Informationen hat.", progress = "Die Mogu haben einst als Kaiser geherrscht und alle Völker unterworfen, denen sie begegneten.\n\nEs scheint so, als versuchten diese Mogu, die Vergangenheit wieder aufleben zu lassen.", completion = "Wartet. In diesem Dokument ist von den Teichen der Jugend die Rede!\n\nGibt es sie wirklich?!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30130] = {title = "Heilkräuter", objective = "Sucht 20 Kaiserliche Lotusblätter.", description = "Kangs Arznei funktioniert nicht.\n\nHier ist etwas anderes am Werk. Eine Macht, die tief unter der Erde wohnt. Sie beraubt uns unserer Hoffnung, macht uns depressiv und verzweifelt.\n\nKang sagte, in diesem Land gebe es Lotuspflanzen. Vielleicht kann ich damit einen Tee kochen, der Leza hoffentlich etwas Kraft gibt.\n\nBitte, $p, sucht in den Ruinen südlich und westlich von hier nach Lotusblüten. Ich werde Euch für Eure Mühen entlohnen.", progress = "Ich wurde geschlagen, niedergestochen, von einer Klippe geworfen, von meinem eigenen Stab im Gesicht getroffen, von Stäben anderer im Gesicht getroffen... und ich bin mehr als einmal vom Aufzug in Donnerfels gefallen.\n\nKeiner dieser Schmerzen klingt auch nur halb so schlimm, wie das, was Leza durchmacht. Ich hoffe, dass dieser Tee hilft...", completion = "Ich danke Euch. Kor ist ein tapferer Krieger, doch manchmal fehlt es ihm an Mitgefühl. Das Leben sollte vor dem Tod stehen, sonst wird niemand von uns mehr da sein, wenn die Kämpfe vorüber sind.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nLotuswasser\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][30131] = {title = "Leben", objective = "Sprecht mit Sonnenläufer Dezco und wartet auf die Geburt.", description = "Mein Kind kommt. Ich muss helfen, wie ich kann.\n\nBleibt in der Nähe, $GHeld:Heldin;. Wenn meine Frau und mein Kind überleben, möchte ich, dass sie das Gesicht <desjenigen erblicken, der/derjenigen erblicken> die; sie gerettet hat.", progress = nil, completion = "Sie... sie ist gestorben. Trotz all der Macht, die mir das Licht gegeben hat, konnte ich sie nicht retten.\n\nAber dank Eurer Hilfe... haben wir meine Söhne gerettet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30132] = {title = "Auf in den Westen", objective = "Sucht die Späherin der Sonnenläufer in der Nähe des Kranichtempels.", description = "Leza wandelt nun mit den Vorfahren dieses seltsamen Landes. Ich muss mich jetzt um die Lebenden kümmern.\n\nKor hat eine Gruppe unserer Späher nach Westen tiefer in den Dschungel geführt.\n\nIch selbst habe eine Späherin zur Erkundung des Kranichtempels ausgesandt. Bitte, $p, sucht meine Späherin, holt Euch ihren Bericht und trefft Euch dann mit Kor. Gebt ihm an Hilfe, was Ihr könnt.\n\nWir werden so schnell wir können zu Euch stoßen.", progress = "Krieg. Es endet immer alles im Krieg.", completion = "&lt;Name&gt;! Gerade rechtzeitig!\n\nWir haben in den Ruinen westlich von hier einen Hinterhalt für die Allianz gelegt, als wir selbst in einen Hinterhalt der Mogu gerieten. Sie verwenden Magierportale, um Verstärkung herbeizuschaffen.", rewards = "DornbuschmedaillonDornbuschhalsreifDornbuschhalsketteDornbuschanhängerDornbuschamulettIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30133] = {title = "In die Wildnis", objective = "Findet den vermissten Kurier aus Zhus Wacht am nördlichen Flusslauf des Dojani, begebt Euch dann zum Tempel des Roten Kranichs und sprecht mit Koro Nebelgänger.", description = "Tief in der Wildnis am Südufer der Mündung des Krasarangs liegt der Tempel des Roten Kranichs, die Heimat des großen Chi-Ji und seiner gläubigsten Anhänger.\n\nSie sollten erfahren, was sich hier zugetragen hat.\n\nWenn Ihr in diese Richtung unterwegs seid, erweist mir bitte einen Gefallen: Wir schicken oft Vorräte zum Tempel, unser letzter Kurier ist jedoch nicht zurückgekehrt. Haltet bitte auf Eurem Weg nach Zeichen von ihm Ausschau. Er müsste bei der Weggabelung am Dojani nach Norden abgebogen sein. Sucht Koro Nebelgänger auf, wenn Ihr den Tempel erreicht.", progress = nil, completion = "Verstehe... Und das Sha hat bereits die gesamte Provinz durchtränkt, oder?\n\nNun, es tut mir leid, aber ich muss Euch sagen, dass auch der Tempel vom Sha überschwemmt ist. Diejenigen unter uns, die nicht getötet oder... besessen wurden, oder was auch immer, rennen um ihr Leben.\n\nWenn Ihr das Sha bei Zhus Wacht besiegt habt, muss ich Euch inständig anflehen, uns zu helfen, hier mit dem Sha fertigzuwerden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30134] = {title = "Wildes in der Wildnis", objective = "Findet Ausbilder Tong auf der Windwärtsinsel im Jadewald.", description = "Willkommen beim Orden der Wolkenschlange, <Volk>. Ich kann an dem Funkeln in Euren Augen erkennen, dass Ihr dem Orden beitreten möchtet.\n\nLasst mich Euch ansehen.\n\n<Die Älteste Anli hält sanft Euren Kopf und blickt Euch tief in die Augen.>\n\nHmm. Ich erkenne Ehrlichkeit und Aufrichtigkeit in Eurem Herzen. Ihr habt eine lange Reise hinter Euch, aber leider seid Ihr noch nicht am Ziel angekommen.\n\nEuer Weg in den Orden beginnt hier und jetzt.\n\nSprecht mit Ausbilder Tong auf der Windwärtsinsel im Nordosten, um den ersten Schritt zu tun.", progress = nil, completion = "Gott seid Dank haben sie endlich jemanden geschickt!\n\nHier sind die Dinge außer Kontrolle geraten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30135] = {title = "Entgegen aller Wahrscheinlichkeit", objective = "Tötet 8 Reißer der Schlängelschuppen oder Eitrinker der Schlängelschuppen.", description = "Zunächst hatten die Schlängelschuppen zu viel Angst, sich den wilden Schlangen zu nähern.\n\nDann habe ich sie dabei erwischt, wie sie im Schutz der Nacht Eier gestohlen haben.\n\nJetzt töten sie sowohl ausgewachsene als auch frisch geschlüpfte Schlangen!\n\nWenn wir nichts unternehmen, werden diese sanften Kreaturen vollkommen ausgerottet werden. Dann gäbe es überhaupt keinen Orden der Wolkenschlange mehr, dem Ihr beitreten könntet!\n\nTötet diese gemeinen Schlängelschuppen, dann sehen wir weiter.", progress = "Der Orden mischt sich nur selten in das natürliche Gleichgewicht hier auf der Insel ein, aber wir müssen die Schlangen retten. Sie sind zu wichtig.", completion = "Ich danke Euch, &lt;Volk&gt;.\n\nIch habe versucht, die Schlängelschuppen so weit wie möglich zurückzudrängen, aber sie waren mir zahlenmäßig überlegen.\n\nEure Arbeit heute wird helfen, eine gesamte Generation von Wolkenschlangen zu retten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30136] = {title = "Leere Nester", objective = "Fangt 6 Windwärtsjungtiere mit dem Seil ein und bringt sie zurück in ihre Nester.", description = "Als die Angriffe begannen, sind die Jungtiere in Panik geflohen.\n\nSie irren überall allein und verängstigt auf der Insel umher.\n\nWenn Ihr helfen möchtet, dann nehmt dieses Seil und fangt damit die Jungtiere ein. Bringt sie zurück in ihre Nester. Bringt sie zurück nach Hause.", progress = nil, completion = "Keine Sorge, in ihren Nestern sind die Jungtiere sicher.\n\nIch kann Euch gar nicht genug dafür danken, dass Ihr gerade rechtzeitig gekommen seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30137] = {title = "Eier sammeln", objective = "Sammelt 6 Schlangeneier ein.", description = "Ahh, ich hätte es wissen sollen! Ihr seht aus wie <ein ehrgeiziger Initiand/eine ehrgeizige Initiandin>.\n\nIch würde Euch von Herzen gern bei der Wahl eines Schlangeneis unterstützen, aber die Schlängelschuppen haben sämtliche Wolkenschlangennester geplündert.\n\nEs tut mir furchtbar leid. Ich weiß nicht, was ich sagen soll.\n\nWenn Ihr nicht verrückt genug seid, Euch in ein Sauroklager im Osten zu schleichen und einige der gestohlenen Wolkenschlangeneier zurückzuholen, dann kann ich Euch leider nicht helfen.", progress = "Die Saurok lagern die gestohlenen Eier in ihrem Lager.", completion = "Oh, wundervoll!\n\nDiese Eier sehen... also... etwas zu klein aus. Konntet Ihr denn keine besseren finden?\n\nAber was soll's... so, wie die Dinge stehen, können wir nicht wählerisch sein.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nPing Roanlark\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30138] = {title = "Das Auserwählte", objective = "Sprecht mit Ausbilder Tong auf der Windwärtsinsel im Jadewald.", description = "Ich habe alle Eier untersucht, <Name>. Und von denen, die Ihr mir gebracht habt, habe ich die drei vielversprechendsten ausgesucht.\n\nIhr müsst Euch aber für ein Ei entscheiden, das Ihr mitnehmen wollt. Seid Ihr bereit, Eure endgültige Entscheidung zu treffen?", progress = nil, completion = "Ihr müsst Euch aber für ein Ei entscheiden, das Ihr mitnehmen wollt.\n\nTrefft Eure Wahl mit Umsicht, denn Ihr könnt sie nicht rückgängig machen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBlaues SchlangeneiGrünes SchlangeneiGelbes Schlangenei\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][30139] = {title = "Des Reiters Reise", objective = "Kehrt zu Ausbilder Himmelsdorn im Arboretum im Jadewald zurück.", description = "Ausgezeichnet, einfach ausgezeichnet! Ich werde die anderen Eier unbehelligt zu ihren Nestern zurückbringen.\n\nIn der Zwischenzeit könnt Ihr Euer Ei bei Ausbilder Himmelsdorn im Arboretum abliefern.", progress = "Die wilden Wolkenschlangen leben in einem anfälligen Gleichgewicht mit der Natur. Ihre seltenen Eier sind Feinden fast schutzlos ausgeliefert.", completion = "Ah, ja - die Älteste Anli hat erwähnt, dass ein neuer Schüler seinen Weg zu uns gefunden hat. Und wie ich sehe, habt Ihr bereits ein Wolkenschlangenei gewählt.\n\nIch werde Euch in seiner Pflege unterweisen. Lasst es mich für einen Moment ansehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30140] = {title = "Des Reiters Reise", objective = "Kehrt zu Ausbilder Himmelsdorn im Arboretum im Jadewald zurück.", description = "Ausgezeichnet, einfach ausgezeichnet! Ich werde die anderen Eier unbehelligt zu ihren Nestern zurückbringen.\n\nIn der Zwischenzeit könnt Ihr Euer Ei bei Ausbilder Himmelsdorn im Arboretum abliefern.", progress = "Die wilden Wolkenschlangen leben in einem anfälligen Gleichgewicht mit der Natur. Ihre seltenen Eier sind Feinden fast schutzlos ausgeliefert.", completion = "Ah, ja - die Älteste Anli hat erwähnt, dass ein neuer Schüler seinen Weg zu uns gefunden hat. Und wie ich sehe, habt Ihr bereits ein Wolkenschlangenei gewählt.\n\nIch werde Euch in seiner Pflege unterweisen. Lasst es mich für einen Moment ansehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30141] = {title = "Des Reiters Reise", objective = "Kehrt zu Ausbilder Himmelsdorn im Arboretum im Jadewald zurück.", description = "Ausgezeichnet, einfach ausgezeichnet! Ich werde die anderen Eier unbehelligt zu ihren Nestern zurückbringen.\n\nIn der Zwischenzeit könnt Ihr Euer Ei bei Ausbilder Himmelsdorn im Arboretum abliefern.", progress = "Die wilden Wolkenschlangen leben in einem anfälligen Gleichgewicht mit der Natur. Ihre seltenen Eier sind Feinden fast schutzlos ausgeliefert.", completion = "Ah, ja - die Älteste Anli hat erwähnt, dass ein neuer Schüler seinen Weg zu uns gefunden hat. Und wie ich sehe, habt Ihr bereits ein Wolkenschlangenei gewählt.\n\nIch werde Euch in seiner Pflege unterweisen. Lasst es mich für einen Moment ansehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30142] = {title = "Es ist ein...", objective = "Beobachtet das Ausschlüpfen Eures Eis.", description = "Oh! Jeden Moment kann ein Junges aus diesem Ei schlüpfen!\n\nDer kleine Kerl scheint Euch möglichst schnell kennenlernen zu wollen.\n\nAlso, seid Ihr bereit?", progress = nil, completion = "Glückwunsch! Hier ist Euer ganz eigenes, wunderschönes Jungtier.\n\nBitte kümmert Euch gut darum, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30143] = {title = "Sie vermehren sich wie Unkraut", objective = "Sprecht mit Ausbilderin Windklinge im Arboretum.", description = "Ah, Ihr seid es wieder, <Name>.\n\nAusbilderin Windklinge sucht schon nach Euch. Ihr findet sie auf dem Hügelkamm im Osten.\n\nSie hat ein paar Neuigkeiten über Eure Wolkenschlange für Euch.", progress = "Ihr macht Euch wirklich gut.", completion = "Glückwunsch, &lt;Name&gt;.\n\nDie Früchte der eigenen Arbeit zu ernten, ist eine Genugtuung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30144] = {title = "Flugausbildung: Ringelreihen", objective = "Reitet Eure Wolkenschlange durch 6 Wolkenringe.", description = "Jetzt, da Eure Schlange ausgewachsen ist, seid Ihr bereit, mit der Flugausbildung zu beginnen.\n\nWie alle Neulinge müsst Ihr ganz von vorn beginnen.\n\nEure erste Aufgabe ist sehr einfach. Fliegt durch 6 der Wolkenringe zwischen den Spitzen im Osten.", progress = "Wie war Euer erster Flug?", completion = "Was habt Ihr in dieser Lektion gelernt?\n\nGeschwindigkeit. Es hängt alles von Geschwindigkeit ab.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30145] = {title = "Flugausbildung: Volle Kraft voraus", objective = "Folgt Ausbilderin Windklinge.", description = "Die nächste Aufgabe wird etwas schwerer.\n\nSeid Ihr bereit?", progress = "Ich hoffe nicht, dass ich Euer Engagement in Frage stellen muss.", completion = "Ihr habt Euch besser geschlagen als erwartet. Nicht schlecht für einen neuen Schüler.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30146] = {title = "Lieblingsgericht", objective = "Angelt 10 Zuckerelritzen aus Süß- oder Salzwassergewässern in Pandaria.", description = "Wolkenschlangen lieben es zu essen und eines ihrer Lieblingsgerichte ist Zuckerelritze.\n\nDiese Fische kann man überall in Pandaria sowohl in Süß- als auch in Salzwassergewässern finden. Ich gehe davon aus, dass Ihr kein unbegabter Angler seid und Eure eigene Angelrute habt, um sie zu fangen?\n\nBringt mir ein paar dieser Fische und ich bin sicher, dass diese hungrigen Biester hier Euch sehr dankbar sein werden.", progress = "Habt Ihr einen guten Ort zum Fischen gefunden?", completion = "Das ist ja wundervoll! Diese Fische werden auf jeden Fall ausreichen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30147] = {title = "Fragmente der Vergangenheit", objective = "Sucht archäologische Grabungsorte in ganz Pandaria auf und nutzt Eure Archäologenfertigkeiten, um 6 Schlangenreiterrelikte zu finden.", description = "Das Erbe des Ordens der Wolkenschlange reicht Jahrtausende zurück. Und obwohl wir versucht haben, diese uralte Kultur zu bewahren, sind einige alte Techniken im Laufe der Zeit verloren gegangen.\n\nIhr könntet uns helfen, einen Teil dieses Wissen zurückzuerlangen, indem Ihr in Pandarias Grabungsstätten nach Hinweisen auf unsere Vergangenheit sucht.\n\nNutzt Eure Archäologiefertigkeiten, während Ihr Pandaria durchsucht, und bringt mir zurück, was immer Ihr finden könnt.", progress = "Wie liefen denn die Ausgrabungen?", completion = "Das ist wirklich erstaunlich, &lt;Name&gt;. Diese Relikte sind für unsere Studien von unermesslichem Wert. Von diesen Fragmenten werden wir viel lernen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30148] = {title = "Nur eine Fleischwunde", objective = "Verwendet Windwollverbände oder schwere Windwollverbände, um 8 verletzte Junge auf der Windwärtsinsel zu versorgen.", description = "Viele der Jungtiere auf der Windwärtsinsel sind im Zuge der Kämpfe verletzt worden.\n\nIch habe gehört, dass Ihr über gute Erste-Hilfe-Fertigkeiten verfügt.\n\nBitte begebt Euch in den Nordosten und verwendet einige Eurer besten Verbände, um die verletzten Jungen zu retten.", progress = nil, completion = "Wundervoll! Nur gut, dass Ihr in der Kunst der Ersten Hilfe geschult wurdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30149] = {title = "Ein Fest für die Sinne", objective = "Sammelt 5 Fischküchlein.", description = "Ich habe gehört, dass Ihr etwas vom Kochen versteht.\n\nDas trifft sich gut, denn die Schlangen lieben Fischküchlein.\n\nWenn Ihr Eure Kochfertigkeiten einsetzt und mir 5 dieser Gerichte bringen könnt, würdet Ihr die Wolkenschlangen hier sehr glücklich machen.", progress = "Konntet Ihr die benötigten Zutaten finden?", completion = "Oh, die sehen ja wirklich sehr lecker aus. Ihr versteht wirklich etwas vom Kochen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30150] = {title = "Süß wie Honig", objective = "Sammelt 30 Honigwaben von wütenden Honigbewahrern im Arboretum ein.", description = "<Das Jungtier huscht hin und her, bevor es zu winseln und wimmern beginnt.>\n\nDas Verhalten der Wolkenschlange lässt Euch erahnen, dass es allerhöchste Zeit für ein süßes Leckerli ist.\n\nDie wohlriechenden Bäume des Arboretums beherbergen viele Bienenstöcke.\n\nEs sollte relativ einfach sein, ein paar Waben von den Honigbewahrern in der Nähe zu sammeln.", progress = "<Das Jungtier überschlägt sich vor Freude über Eure Rückkehr.>", completion = "Das Jungtier springt auf Eure Hand. Es wickelt seinen langen, gewundenen Schwanz um Euch und beginnt, den Honig von Euren Fingern zu lecken.\n\nDas kitzelt!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30151] = {title = "Fang!", objective = "Benutzt den Flummi. Dann fangt ihn und werft ihn achtmal zu Eurem Jungtier zurück.", description = "<Das Jungtier blickt Euch lustlos und gelangweilt an.>\n\nIhr bekommt das Gefühl, dass die Schlange genug davon hat, den ganzen Tag lang eingesperrt zu sein.\n\nKann man Wolkenschlangen eigentlich auch Stöckchen holen lassen?", progress = nil, completion = "Sieh einer an - Ihr und Eure Schlange scheint ja richtig Spaß zu haben! Gut gemacht, &lt;Name&gt;. Indem Ihr mit ihr spielt, stärkt Ihr sowohl ihre geistigen als auch ihre körperlichen Fähigkeiten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nTeich der Harmonie\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30152] = {title = "Das Himmelsrennen", objective = "Beendet das Himmelsrennen, indem Ihr durch 10 Kontrollpunkte hindurchfliegt und dann die Ziellinie am Arboretum unterquert.", description = "Die Zeit des großen Rennens ist gekommen!\n\nFolgt dem Kurs entlang der Spitzen und sammelt 10 Flaggen von den Ballon-Kontrollpunkten ein.\n\nUnd wenn Ihr damit fertig seid, müsst Ihr das Rennen unterhalb der Ziellinie beenden.\n\nDas wird ein hartes Rennen und ich wünsche Euch Glück. Sprecht mich einfach an, wenn Ihr bereit seid.", progress = nil, completion = "Hervorragend! Wie fühlt es sich an, das Himmelsrennen beendet zu haben?\n\nIhr müsst ganz erpicht darauf sein, Euren Preis zu erhalten!", rewards = "Ihr bekommt:\n\nSiegerbelohnungTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30154] = {title = "Der schnellste Weg zum Herzen einer Schlange", objective = "Sammelt 5 Tigerflanken.", description = "<Das Jungtier blickt Euch mürrisch an.>\n\nOh oh... Sieht aus, als wenn jemand heute schlecht drauf ist!\n\nZum Glück wisst Ihr genau, was den kleinen Racker wieder aufmuntern wird.\n\nWolkenschlangen lieben den Geschmack von Tigerfleisch, aber die Beschaffung ihrer zarten Flanken kann sich mitunter... schwierig... gestalten.\n\nZum Glück wisst Ihr auch, dass sich auf der Windwärtsinsel im Nordwesten ein paar dicke, saftige Tiger finden lassen.\n\nSicher, Ihr könntet Euch ein paar Kratzer (oder Schlimmeres) einfangen, aber für den kleinen Rabauken macht man es doch gerne... oder?!", progress = "Sieht aus, als wäre die Aufgabe erledigt.", completion = "Wie ich sehe, habt Ihr hart gearbeitet und Futter für Eure hungrige kleine Schlange beschafft. Gut gemacht. Es scheint im Moment noch nicht sonderlich lohnenswert zu sein, doch Eure Schlange wird Eure Anstrengungen nicht vergessen und Euch dafür in ihr Herz schließen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30155] = {title = "Das Gleichgewicht wiederherstellen", objective = "Tötet 8 Reißer der Schlängelschuppen oder Eitrinker der Schlängelschuppen.", description = "Die Lage auf den Inseln ist immer noch düster, <Name>.\n\nDie Schlängelschuppen haben nicht auf unsere Friedensgesuche reagiert, also bleibt uns nur noch eine Möglichkeit.\n\nUm die wilden Wolkenschlangen zu schützen, müssen wir die Insel von ihnen befreien. Nur dann können die Wolkenschlangen wieder in Frieden leben.", progress = nil, completion = "Wenn die Wilderer der Diplomatie keine Beachtung schenken, müssen sie eben unsere Klingen zu spüren bekommen. Ich danke Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30156] = {title = "Fütterungszeit", objective = "Sammelt 3 Stücke Salzrückenfleisch und verfüttert sie an Euer Jungtier.", description = "<Die Schlange schnellt vorwärts und beißt Euch in den Finger.>\n\nAutsch! Wie es aussieht, ist das kleine Biest zweifelsohne sehr hungrig. Ihr erinnert Euch an ein paar fleischig aussehende Schildkröten, die sich auf der Insel im Nordosten finden lassen, wo die wilden Wolkenschlangen leben.\n\nVielleicht kann ja ein bisschen Schildkrötenfleisch den Heißhunger Eures Jungtiers stillen.", progress = nil, completion = "Ihr lernt schnell, junger Trainer. Salzrückenfleisch ist zäh, aber reich an Nährstoffen, die ein Jungtier zum Wachsen benötigt.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30157] = {title = "Noch leerere Nester", objective = "Fangt 6 Windwärtsjungtiere mit dem Seil ein und bringt sie zurück in ihre Nester.", description = "Dem Himmel sei Dank, noch ein Wolkenschlangentrainer!\n\nIch habe gerade erfahren, dass die wild lebenden Jungtiere der Windwärtsinsel im Nordosten in schlimme Schwierigkeiten geraten sind!\n\nWer kümmert sich denn um die süßen kleinen Babys, während die ausgewachsenen Schlangen die schrecklichen Saurok bekämpfen? Niemand!\n\nWIR MÜSSEN SIE RETTEN!\n\nIch schicke jeden Trainer, den ich finden kann, dorthin, um zu helfen. Wenn Ihr nicht zu beschäftigt seid, könnt Ihr dann bitte auch dafür sorgen, dass alle Jungtiere wieder sicher in den Nestern ihrer Mütter landen?", progress = nil, completion = "Wie ich sehe, habt Ihr Euch dort draußen sehr gut um die Jungtiere gekümmert. Gut gemacht.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30158] = {title = "Entwaffnung des Feindes", objective = "Sammelt 5 Harpunen der Schlängelschuppen ein.", description = "Wenn wir die Wilderer aufhalten wollen, müssen wir entschlossener vorgehen.\n\nWenn wir den Feinden die Hauptwaffen für das Töten und Fangen von Schlangen abnehmen können, bereiten wir vielleicht ihrem ganzen Vorhaben ein Ende.\n\nIch möchte, dass Ihr in ihr Gebiet im Osten der Windwärtsinsel eindringt und ihnen die Waffen stehlt.\n\nEine Katze ohne Krallen kann niemanden kratzen.", progress = "Habt Ihr die Sache erledigt?", completion = "Wir haben sie geschwächt, aber wir dürfen uns nicht zu früh freuen. Auch ein zahnloser Tiger ist noch gefährlich.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30159] = {title = "Artenschutz", objective = "Sammelt 8 gestohlene Eier.", description = "Oh nein! Wir müssen sie aufhalten! Ihr seid <Name>, oder? Der Orden benötigt Eure Hilfe!\n\nWisst Ihr, was diese fürchterlichen Saurok der Schlängelschuppen tun?\n\nSie sind dreist genug, Wolkenschlangeneier direkt aus den Nestern der Matriarchinnen zu stehlen!\n\nWährend die Wolkenschlangen immer seltener werden, nehmen diese Bestien die Eier und... und...\n\n<Suchi atmet tief durch.>\n\n... und verspeisen sie als ihr Abendessen! Es ist schrecklich!\n\nMacht Euch auf zur Windwärtsinsel im Nordosten und bringt alle unbeschädigten Eier, die ihr finden könnt, in Sicherheit. Als Schüler des Ordens ist es unsere Pflicht!", progress = "Werden diese gemeinen Schlängelschuppensaurok denn niemals aufgeben?", completion = "Gut gemacht, &lt;Name&gt;. Als Suchi mir erzählte, dass sie Euch nach den gestohlenen Eiern ausgeschickt hatte, wusste ich, dass Ihr die Aufgabe erledigen würdet.\n\nUnsere Ausbilder werden sicherstellen, dass diese Eier an einen sicheren Ort zurückgebracht werden.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30160] = {title = "Ein Rubinsplitter für Ella", objective = "Hallo <Name>, schön, Euch wiederzusehen.", description = nil, progress = "Hallo <Name>, schön, Euch wiederzusehen.", completion = "Oh, ist der für mich? Ich, ich weiß gar nicht, was ich sagen soll.\n\nDer ist wunderschön, vielen Dank!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30163] = {title = "Für den Stamm", objective = "Rettet 8 Gefangene der Morgenjäger.", description = "Wir haben uns in die Zuflucht zurückgezogen, als die Mogu angriffen, haben aber unterwegs eine Menge Leute verloren.\n\nReist von hier aus nach Westen und Norden und sucht nach Gefangenen. Befreit so viele wie möglich, damit sie uns im Kampf verstärken.\n\nSolltet Ihr welche von der Allianz treffen, so überlasst sie ihrem Schicksal.", progress = nil, completion = "Wir haben bereits so viele verloren. Ich weigere mich, noch mehr zu verlieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30164] = {title = "Der Steinpflug-Konvoi", objective = "Wendet den kaiserlichen Lotusumschlag bei 7 Gesandten von Steinpflug an.", description = "Ich habe versucht, so viele der Steinpfluggesandten wie nur irgend möglich zu retten, aber diese \"Mantis\" haben viele von ihnen in den Dschungel gezerrt.\n\nDiese Zivilisten brauchen unsere Hilfe.\n\nBitte nehmt die Kräuter, die Ihr vorher gesammelt habt. Ich habe sie mit den letzten Gaben des Lichts erfüllt, die mir noch zur Verfügung stehen. Behandelt so viele Steinpfluggesandte damit, wie Ihr könnt.", progress = "Die erste Pflicht eines Sonnenläufers besteht darin, Leben zu bewahren und zu schützen.", completion = "Dank Euch trudeln die Zivilisten wieder hier ein. Diese \"Mantis\"-Kreaturen stellen eine ernste Bedrohung dar. Wir werden bald unsere Streitkräfte sammeln müssen, um die Lage zu entschärfen.\n\nEiner der Gesandten bat mich, Euch das hier als Zeichen seines Dankes zu geben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30168] = {title = "Diebische Räuber", objective = "Beschafft 5 Teile der geplünderten Jinyubeute wieder.", description = "Saurok!\n\nDiese bösartigen Kreaturen sind vom Töten und Stehlen besessen. Sie haben unsere Siedlung ohne Vorwarnung und völlig unprovoziert angegriffen.\n\nBitte, <Klasse>, könnt Ihr uns helfen?\n\nHelft uns, unsere letzten Besitztümer vor diesen Flussklingenräubern zu retten, die sich entlang des Flusses aufhalten, und wir werden Euch gerne belohnen.", progress = "Ich glaube, sie haben sogar meinen heiligen Spucknapf gestohlen.", completion = "Nicht viele würden anhalten, um einem Dorf in Not zu helfen... besonders so tief in der Wildnis.\n\nIhr seid wahrlich ein Champion, &lt;Name&gt;.", rewards = "SeidenbrutschnitzereiFeder des KarpfenjägersFeder des LichtungszwickersIdol der DschungeljägerinIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30169] = {title = "Räuberanführer Slovan", objective = "Tötet Slovan.", description = "Die Räuber werden von einem besonders gewalttätigen Saurok namens Slovan angeführt. Der Kranichtempel kommt uns normalerweise zu Hilfe, wenn Slovan angreift, aber mittlerweile sind wir unterlegen und werden ausmanövriert.\n\nBitte, <Klasse>, helft uns, indem Ihr diesen Räuberanführer ausschaltet.\n\nIhr findet ihn in seinem Versteck hinter den Krasarifällen.", progress = nil, completion = "Ihr habt uns heute einen großen Dienst erwiesen. Ich danke Euch im Namen meiner Leute.\n\nBitte nehmt dies als Zeichen unserer Dankbarkeit.", rewards = "Ihr bekommt:\n\nShushens Spucknapf"}
MultiLanguageQuestData['de'][30172] = {title = "Fassgeleit", objective = "Führt Trübtrunk zurück nach Halbhügel.\n\nWenn Ihr Trübtrunk verliert, könnt Ihr ihn neben der riesigen Banane am Goldfächer wiederfinden.", description = "Nö, nö, zerbrecht Euch mal nicht den Kopf, ich kann die Fässer schon selbst schleppen.\n\nIch bin vielleicht nicht der schönste oder klügste oder unterhaltsamste Pandaren, aber dafür stärker als ein Mushan.\n\nAber den Weg könnt Ihr mir gern zeigen.", progress = "Wo ist Trübtrunk?", completion = "Sehr gut! Das Wasser ist da!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30173] = {title = "Frontschweine", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30174] = {title = "Für die Familie", objective = "Sucht Kor Bluthauer.", description = "Kor sollte uns mittlerweile eingeholt haben. Er meinte, er würde aufbrechen, um die Ruinen von Korja östlich von hier zu sichern. Er wollte sich mit uns treffen, um uns bei der Bedrohung durch die Mantis zu helfen.\n\nVielleicht braucht er Hilfe gegen Bodenbrecher Brojai. Könntet Ihr ihn unterstützen? Kang und ich werden Euch in Kürze folgen.", progress = "Dieses Land fordert so viel.", completion = "Danke, dass Ihr meinen Freund gerächt habt, &lt;Name&gt;.\n\nIch weiß, er hätte gewollt, dass Ihr einen seiner Gegenstände als Andenken und als Zeichen seiner Dankbarkeit bei Euch tragt.", rewards = "NayelimantelungTodesrachenschiftungTiefwildschulterstückeNarsongschiftungAngkhalamiciaFlussklingenschiftungSarjunschiftungKorjanischulternSchultern des DojaniIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30175] = {title = "Die Mantis", objective = "Tötet 10 Vorläufer der Ik'thik.", description = "Die Mantis! Sie kamen aus dem Nichts, schlugen unseren Konvoi in Trümmer und versprengten unsere Leute in alle Richtungen.\n\nJetzt bereiten sie einen Angriff auf Steinpflug vor.\n\nBitte, <Klasse>, vernichtet ein paar dieser Bestien, bevor sie zahlreich genug sind, um uns zu umzingeln.\n\nWenn mein Cousin, Botschafter Len, immer noch am Leben ist und sich in unserem Konvoi befindet, sollte er Euch für Eure Hilfe belohnen können.", progress = nil, completion = "Danke für Eure Hilfe, &lt;Klasse&gt;! Ich habe noch nie gesehen, wie sich jemand so den Mantis entgegengeworfen hat.\n\nNun, außer den Shado-Pan natürlich...", rewards = "NayelirobeTodesrachenrobeTiefwildrüstungNarsongbrustschutzAngkhalrobeFlussklingentunikaSarjunbrustschutzKorjanibrustharnischBrustharnisch des DojaniIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30177] = {title = "Täglicher zufälliger, heroischer Dungeon (Erster) (Cataclysm)", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][30178] = {title = "In die Wildnis", objective = "Findet den vermissten Kurier aus Zhus Wacht am südlichen Flusslauf des Dojani, begebt Euch dann zum Tempel des Roten Kranichs und sprecht mit Koro Nebelgänger.", description = "Tief in der Wildnis am Südufer der Mündung des Krasarangs liegt der Tempel des Roten Kranichs, die Heimat des großen Chi-Ji und seiner gläubigsten Anhänger\n\nSie sollten erfahren, was sich hier zugetragen hat.\n\nWenn Ihr in diese Richtung unterwegs seid, erweist mir bitte einen Gefallen: Wir schicken oft Vorräte zum Tempel, unser letzter Kurier ist jedoch nicht zurückgekehrt. Haltet bitte auf Eurem Weg nach Zeichen von ihm Ausschau. Er müsste bei der Weggabelung am Dojani nach Süden abgebogen sein. Sucht Koro Nebelgänger auf, wenn Ihr den Tempel erreicht.", progress = nil, completion = "Verstehe... Und das Sha hat bereits die gesamte Provinz durchtränkt, oder?\n\nNun, es tut mir leid, aber ich muss Euch sagen, dass auch der Tempel vom Sha überschwemmt ist. Diejenigen unter uns, die nicht getötet oder... besessen wurden, oder was auch immer, rennen um ihr Leben.\n\nWenn Ihr das Sha bei Zhus Wacht besiegt habt, muss ich Euch inständig anflehen, uns zu helfen, hier mit dem Sha fertigzuwerden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30179] = {title = "Vergiftet!", objective = "Sammelt 5 vergiftete Klingen der Mogu.", description = "Die... Mogu. Traut ihnen nicht. Gift. Holt Proben... Holt Klingen. Bringt sie zu Dezco... in Donnerkluft, westlich von hier.", progress = "Habt Ihr Neuigkeiten von Chezin?", completion = "Chezin ist tot? Das sind wirklich sehr schlechte Neuigkeiten. Kor, Chezin und ich haben an fast jeder Küste, die einen Namen trägt, gegen Drachen, Untote und die Allianz gekämpft.\n\nIhn auf diese Weise zu verlieren...\n\nDanke, dass Ihr diese Waffen beschafft habt. Durch sie sollten wir viel über unseren neuen Feind erfahren können.", rewards = "Ring der Teiche der JugendRing der TränenZahnreihenbandSiegel der verlorenen JahrhunderteSiegel des verbotenen DschungelsDer folgende Zauber wird auf euch gewirkt:\n\nSummon Thunder Cleft Conversation Bunny 2\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30181] = {title = "Mushanjagd", objective = "Tötet 15 Staubrückenmushan.", description = "Mushan! Schaut Euch mal an, wie groß die sind. Und wahrscheinlich so alt wie der Staub, auf dem sie umhertrotten. Eine schöne Trophäe.\n\nWenn Ihr Euch also als <Großwildjäger/Großwildjägerin> beweisen wollt, solltet Ihr mit ihnen anfangen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;.\n\nMein Vater reist über das Meer zu einem neuen Kontinent, nur um öde Wölfe zu jagen.\n\nIch jage ja lieber Kreaturen mit ordentlich Fleisch auf den Knochen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30182] = {title = "Fuchsjagd", objective = "Tötet 15 Schlaufüchse.", description = "Auf meiner Pirsch östlich von hier habe ich ein paar Füchse gesehen. Damals auf der Wandernden Insel waren dies die ersten Tiere, die ich zu jagen gelernt habe.\n\nWenn Ihr dieselbe Herausforderung wie ich als junger Pandarenjäger erleben möchtet, dann begebt Euch Richtung Osten und legt Euch mit einer Meute Füchse an. Sie sind recht schlau und gerissen, also passt auf Euch auf.", progress = nil, completion = "Gut gemacht. Ihr habt den Füchsen keine Chance gelassen. Ich werde mit Mr. Pleeb sprechen. Vielleicht kann er Euch noch eine Trophäe anfertigen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30183] = {title = "Beherrschen der Pirscherjagd", objective = "Tötet 15 Schluchtpirscher.", description = "Tiger! Egal, welches Land ich bereise, diese Bestien mit Fangzähnen sind immer ein Thema. Und trotzdem hatte ich noch keine Gelegenheit, Jagd auf sie zu machen.\n\nLasst uns ein paar Tiger jagen. Ich gehe nach Osten und Ihr nach Westen. Ich glaube, ich habe einige in der Nähe der Staubrückenklamm gesehen. Ich wette, in der Nähe dieser Mushan halten sich jede Menge von ihnen auf.", progress = "Wie steht's mit Eurer Ausbeute?", completion = "Wahnsinn! Das nenne ich mal eine gute Ausbeute. Ich werde mit Mr. Pleeb sprechen. Vielleicht kann er aus dem besten Exemplar eine Trophäe für Euch anfertigen.", rewards = "Hemets SatingamschenHemets BalgbeinschützerHemets RingpanzergamaschenHemets brünierte BeinplattenHemets seidene BeinkleiderHemets LederbeinschützerGamaschen der Wilden EbenenHemets schwere BeinschützerHemets gepanzerte BeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30184] = {title = "Mushanjagd: Rußhaut", objective = "Holt Euch Rußhauts Kopf.", description = "Mein Junge hier ist ein begabter Jäger... in Ausbildung. Jetzt soll er mal sehen, wie ein richtiger Nesingwary das macht!\n\nÖstlich von hier habe ich einen riesigen Mushan mit einer Haut so dunkel wie die Nacht selbst gesehen. Ich wette, die Bestie hat schon einige Jäger auf dem Gewissen.\n\nWenn Ihr also an der Großwildjagd interessiert seid, dann habt Ihr jetzt ein schönes Ziel.", progress = "Größer kann die Großwildjagd nun wirklich nicht werden.", completion = "Das nenne ich doch mal eine echte Jagdtrophäe.", rewards = "MushanhackerRußhautklingeSafariverteidigerRußhautbarriereMushanpiekserNessys ScherentrophäeSafaritagebuchSafarilaterneAuf Euch wartet eine dieser Belohnungen:\n\nGeldbeutel des Helden\n\nDer folgende Zauber wird auf euch gewirkt:\n\nUpdate Phase Shift (Player)\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][30185] = {title = "Schildkrötenjagd", objective = "Besorgt 5 intakte Schildkrötenpanzer.", description = "Zugegeben, Schildkröten sind nicht gerade Großwild, aber sie können ganz schön gemein sein. Sie sind außerdem die perfekten Köder für die Großwildjagd!\n\nHabdich hat ein paar Aufzeichnungen gefunden, in denen steht, dass die Torjarigrube früher eine Opferstelle war. Das alte Reich hat da irgendetwas Komisches mit dem Wasser angestellt.\n\nWürde mich mal interessieren, was da so im Wasser schwimmt. Bringt mir ein paar frische Schildkrötenpanzer und trefft mich dann in der Grube.\n\nMal sehen, ob die alten Geschichten wahr sind.", progress = "Ich habe immer im Schatten meines großen Vaters gelebt. Aber von heute an werden sich die Leute auch an den Namen von Nesingwary Jr. erinnern!", completion = "Ich danke Euch. Das sollte mir einen Vorsprung vor meinem alten Herrn einbringen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Phase Shift (Player)\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30186] = {title = "Elterliche Fürsorge", objective = "Besiegt Torjars Fluch.", description = "Wenn diese Aufzeichnungen stimmen, muss ich nur einen kleinen Tanz aufführen, um das große Ding aus der Tiefe heraufzubeschwören.\n\nUnd wenn es auftaucht, schnappen wir uns die Bestie und beweisen meinem Vater, dass wir echte Großwildjäger sind.", progress = nil, completion = "Ihr habt meinen Sohn gerettet! Ich bin Euch unendlich dankbar. Bitte nehmt dies hier für Eure Heldentat.", rewards = "Band des großen Dings aus der TiefeBand des rituellen TanzesNesingwarys SiegelBand der elterlichen FürsorgeRing von Torjars FluchDer folgende Zauber wird auf euch gewirkt:\n\nUpdate Phase Shift (Player)\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30187] = {title = "Flugausbildung: Der richtige Kurs", objective = "Fliegt durch 10 Rennflaggen bei den Kontrollpunkten über der Nebelschleiersee", description = "Nun da Ihr die Grundlagen des Rennens erlernt habt, solltet Ihr Euch die Strecke ansehen.\n\nErkundet die Spitzen und sammelt von jedem der Kontrollpunkte eine Rennflagge ein.\n\nFliegt durch jede karierte Flagge hindurch, um sie einzusammeln.", progress = "Habt Ihr das Zeug dazu, teilzunehmen... und zu gewinnen?", completion = "Gut gemacht. Falls Ihr die Kontrollpunkte nicht gefunden hättet, wärt Ihr im Himmelsrennen wohl kaum erfolgreich gewesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30188] = {title = "Am Himmel reiten", objective = "Tretet dem Orden der Wolkenschlange bei.", description = "Ich kann Euch nichts mehr beibringen, <Name>.\n\nIhr habt Euch Eurer Schlange als würdig erwiesen.\n\nHeute werdet Ihr in unseren Orden aufgenommen. Seid Ihr bereit?", progress = nil, completion = "Heute verbrüdern wir uns.\n\nHerzlichen Glückwunsch zur Aufnahme in den Orden der Wolkenschlange. Reiten wir zusammen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZügel der Jadewolkenschlange\n\nIhr erlernt außerdem:\n\nWolkenschlangenreiten\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWolkenschlangenreiten\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][30189] = {title = "Ein hübscher Apfel für Ella", objective = "Wie geht's Euch denn so, <Name>?", description = nil, progress = "Wie geht's Euch denn so, <Name>?", completion = "Was? Für mich?\n\nSo einen hübschen Apfel sollte man nicht alleine essen.\n\nHier, bitte nehmt eine Hälfte.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In\n\nIhr bekommt:\n\nHalbierter hübscher Apfel"}
MultiLanguageQuestData['de'][30190] = {title = "Dreiste Geister", objective = "Löscht 8 Schieferhautunruhestifter aus.", description = "Diese Geister schon wieder! Ich hasse sie! Wir müssen sie aufhalten, bevor jemand zu Schaden kommt oder sie das halbe Dorf niederbrennen!\n\nWenn Ihr einen von diesen Plagegeistern seht, dann löscht ihn aus!", progress = nil, completion = "Wir müssen herausfinden, wo diese Geister herkommen. Wir plagen uns fast täglich mit diesem Problem herum und langsam nimmt es überhand.\n\nDanke für Eure Hilfe.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30191] = {title = "Weg von unserem Bier", objective = "Bergt 10 gestohlene Fässer von Nebelhauch.", description = "Jemand hat oben am südlichen Hang etwas Bier draußen rumstehen lassen. Und jetzt haben die Geister unser Bräu zu schätzen gelernt. Sie treiben sich schon den ganzen Morgen im Ort herum und stehlen alle Fässer, die sie kriegen können.\n\nBringt alles zurück, was Ihr finden könnt. Ein Pandarenarbeiter ohne Bier ist... nicht sehr produktiv. Wir müssen die Männer bei Laune halten.", progress = "Habt Ihr irgendwelche gestohlenen Fässer gefunden?", completion = "Dafür werden die Arbeiter Euch feiern!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Zone Auras\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30192] = {title = "Es brennt!", objective = "Tretet 30 Kohlengrillfeuer aus.", description = "Ich weiß ja nicht, ob Ihr es bemerkt habt, aber mein Dorf brennt...\n\nDie Geister haben begonnen, die Kohlengrills umzuwerfen! Sie werden noch das ganze Dorf in Brand setzen!\n\nBitte helft uns! Tretet alle Feuer aus, die Ihr seht!", progress = nil, completion = "Was für eine Erleichterung, dass Ihr hier seid, um zu helfen. Ich danke Euch.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Zone Auras\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30193] = {title = "Lecker Gazelle", objective = "Besorgt 10 Stücke Schönlandgazellenfleisch.", description = "Wer hart arbeitet, verdient eine herzhafte Mahlzeit. Aber ich habe kein gutes Fleisch mehr!\n\nKönntet Ihr in den Wald ziehen und mir etwas frisches Gazellenfleisch besorgen?", progress = "Hier hat auf jeden Fall immer jemand Hunger!", completion = "Das ist ja wunderbar frisch! Ich danke Euch vielmals, &lt;Klasse&gt;!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30194] = {title = "Stürmische Ausbreitung", objective = "Tötet 8 Donnermaulwölfe.", description = "Die Dorfbewohner haben heute morgen schon wieder ein Yak an einen dieser Donnermaulwölfe von der anderen Flussseite verloren. Diese Wölfe werden immer dreister.\n\nDas ist ein sicheres Zeichen dafür, dass ihre Population zu groß für dieses Tal wird. Wir müssen wieder einmal ihre Anzahl dezimieren.\n\nWenn Ihr diesen Auftrag annehmen möchtet, könnt Ihr Euch meiner Dankbarkeit gewiss sein.", progress = nil, completion = "Ihr wisst die Verantwortung für solche Jagdaufgaben zu schultern. Dafür gebührt Euch mein Respekt.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30195] = {title = "Ewige Blüten", objective = "Sammelt 10 Ewige Blüten.", description = "Würdet Ihr einem bescheidenen Händler einen Gefallen erweisen? Ich muss meinen Bestand an Ewigen Blüten auffrischen. Sie wachsen in den nahe gelegenen Wäldern.\n\nWäret Ihr vielleicht so freundlich, mir zu helfen?", progress = "Habt Ihr erfolgreich Blumen gesammelt?", completion = "Aha! Ihr seid wirklich sehr fürsorglich.\n\nIch danke Euch vielmals...", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30196] = {title = "Mjampignons!", objective = "Sammelt 12 Mjampignons zusammen.", description = "Der Aufbau eines neuen Dorfes scheint den Arbeitern mächtig Appetit zu machen!\n\nIch habe einen herzhaften Eintopf vorbereitet, aber dazu brauche ich noch ein paar Mjampignons von der Tu-Shen-Begräbnisstätte im Osten. Leider treiben dort ein paar aufgebrachte Geister ihr Unwesen und ich bin nicht gerade eine Kämpfernatur.\n\nKönntet Ihr mir ein paar Mjampignons mitnehmen, wenn Ihr heute die Begräbnisstätte aufsuchen solltet?", progress = "Die hungrigen Mägen der Arbeiter dröhnen durch das ganze Dorf!", completion = "Gerade rechtzeitig! Der Eintopf ist fast fertig.\n\nIch danke Euch.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30197] = {title = "Wagenfahrt", objective = "Fahrt mit dem Wagen nach XXX.Im Tal ist es heute Morgen ruhig gewesen. Ich schicke Rook mit einem Wagen voller Waren nach XXX. Ihr solltet ihn begleiten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Im Tal ist es heute Morgen ruhig gewesen. Ich schicke Rook mit einem Wagen voller Waren nach XXX. Ihr solltet ihn begleiten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30198] = {title = "NOT USED", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30199] = {title = "NOT USED", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30200] = {title = "Im Netz der Glut", objective = "Tötet 8 Glutnetzspinnen.", description = "Als Teil ihrer Ausbildung mussten die Schüler die Spinnen in den Ruinen erledigen, aber jetzt haben wir sie direkt zur Mogufront entsandt. Und seitdem sind die Spinnen außer Kontrolle.\n\nKönntet Ihr Euch um sie kümmern?", progress = nil, completion = "Ihr seid schneller als die Schüler. Aber alles andere hätte mich auch enttäuscht. Ich danke Euch.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30201] = {title = "NOT USED", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30202] = {title = "NOT USED", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30203] = {title = "NOT USED", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30204] = {title = "Nicht drauftreten!", objective = "Tötet 50 Glutnetzspinnlinge. Verwendet Kuns Fackel, um sie noch in den Brutsäcken zu verbrennen.", description = "Ich gebe es zu: Diese Spinnen ekeln mich an. Insbesondere ihre Eiersäcke, die sie überall liegen lassen. Immer wenn ich ungewollt auf diese Dinger drauftrete, kriechen da diese Spinnlinge raus. Wenn ich nur daran denke, bekomme ich eine Gänsehaut.\n\nIch möchte, dass Ihr sie verbrennt. Und zwar restlos alle!", progress = nil, completion = "Ich danke Euch. Ich werde mir wohl noch eine Woche Anjis Spott für mein Geheul anhören müssen, aber dann sollte die Sache vergessen sein.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30205] = {title = "Runensperre", objective = "Bergt das uralte Moguartefakt.", description = "Hallo, <mein Freund/meine Liebe>.\n\nEiner von Levens Leuten hat mir von einem Moguartefakt in den östlichen Ruinen erzählt. Aber er wusste nicht, wie man an dieses Artefakt herankommt. Ich vermute ja, dass es durch eine Runensperre gesichert ist.\n\nWenn Ihr Euch dem Artefakt nähert, solltet Ihr vier Runen in der Nähe finden, die die Sperre nach ihrer Aktivierung aufheben. Ich wäre Euch wirklich sehr verbunden, wenn Ihr mir dieses Artefakt bringen könntet.", progress = "Habt Ihr die Runen gefunden, von denen ich Euch erzählt habe?", completion = "Das ist ja fantastisch... sehr gut erhalten. Danke, mein Freund. Dafür schulde ich Euch etwas.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30206] = {title = "Runen in den Ruinen", objective = "Sammelt 12 Guo-Lai-Runensteine zusammen.", description = "In den Ruinenwänden selbst befinden sich wertvolle Runensteine, für die wir im östlichen Tal gute Verwendung hätten.\n\nWäret Ihr so freundlich, mir ein paar davon mitzubringen, wenn Ihr Euch in den Ruinen aufhaltet?", progress = "Diese Runensteine dienten einst als Energiequelle, als die Mogu noch über das Tal herrschten.", completion = "Das ist ja wundervoll! Ich danke Euch herzlich.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30225] = {title = "Tod der Glutnetzmatriarchin", objective = "Tötet Blutspitz, die Glutnetzmatriarchin.", description = "Mein lieber Kun hat heute morgen noch mehr Spinnen aus den Guo-Lai-Hallen kommen sehen. Und als er sich das näher anschauen wollte, ist er da drinnen auf eine weitere Spinnenmatriarchin gestoßen.\n\nIch möchte, dass Ihr sie umbringt.", progress = nil, completion = "Vor Eurer konsequenten Haltung habe ich wirklich Respekt, &lt;Klasse&gt;. Danke.", rewards = "Ihr bekommt:\n\nSchätze des TalsTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30226] = {title = "Das Blut erhebt sich", objective = "Tötet 8 Shao-Tien-Mogu auf der Ruinenerhebung.", description = "Eine kleine Gruppe Mogu wurde auf der Ruinenerhebung im Norden gesichtet.\n\nVernichtet sie.", progress = nil, completion = "Wie es sein sollte. Danke.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30227] = {title = "Wulon der Granitwächter", objective = "Tötet Wulon den Granitwächter.", description = "Eine der Qilenstatuen in den Guo-Lai-Hallen ist zum Leben erwacht und hätte fast meinen lieben Kun getötet. So etwas ertrage ich einfach nicht! Niemand darf meinem Kun etwas antun.\n\nIch möchte, dass Ihr dort hineinstürmt und das Ding in Tausend Stücke schlagt. Ich würde es ja selbst tun, aber ich muss mich um die Wunden meines Liebsten kümmern.", progress = nil, completion = "Danke. Ich bin Euch etwas schuldig, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\nSchätze des TalsTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30228] = {title = "Unruhe unter den Unruhestiftern stiften", objective = "Tötet 8 Steinborkentrickster.", description = "Die Waldgeister sind zurück. Ich möchte, dass Ihr sie tötet, bevor sie noch mehr Ärger machen.", progress = nil, completion = "Endlich Ruhe und Frieden. Ich danke Euch.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30229] = {title = "Die große Gefahr", objective = "Tötet 8 Korjanieroberer.", description = "Ich muss mich für meine strengen Worte von vorhin entschuldigen. Es war möglicherweise richtig von Dezco, abzuwarten, um mit vereinten Kräften weiter nach Westen zu ziehen.\n\nDie Mogu haben uns bei der Erkundung der Ruinen westlich von hier einen schweren Schlag versetzt. Sie haben uns mithilfe von Beschwörungsportalen und dunkler Magie in einen Hinterhalt gelockt. Ich habe seit der Scherbenwelt solch niederträchtige Zauberei nicht mehr gesehen.\n\nWir müssen unsere Kräfte sammeln. Geht nach Westen, tötet ihre Beschwörer und durchtrennt ihre Versorgungslinien.", progress = nil, completion = "Nun da ihre Nachschublinien unterbrochen sind, können wir anfangen, eine Offensive gegen ihren Obersten Eroberer auf die Beine zu stellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30230] = {title = "Erneute Zurückeroberung", objective = "Beschafft 10 Moguartefakte.", description = "Mogu sind Schläger. Sie waren immer schon Schläger.\n\nNur in den alten Geschichten über die von ihnen beherrschten Reiche haben sie sich einer Form der Magie bedient.\n\nAber diese Mogu verwenden arkane Portale und Zauber. Wir müssen sie aufhalten!\n\n$p, sucht nach Artefakten, die die Mogu benutzen, um ihre Magie damit zu wirken. Ich habe ein paar ihrer Sammler und Eroberer nördlich und westlich von hier gesehen, die nach solchen Gegenständen gesucht haben.", progress = "Jedes Artefakt in unserem Besitz ist eine Waffe weniger in den Händen der Mogu.", completion = "Gut gemacht, &lt;Name&gt;. Ihr habt dem Kind das Schwert aus der Hand genommen.", rewards = "NayelimanschettenTodesrachenbindungenTiefwildarmschützerNarsongarmschienenAngkhalmanschettenFlussklingenarmwickelSarjunhandgelenksschützerKorjaniarmplattenArmschienen des DojaniIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30231] = {title = "Pomfruchtlieferung", objective = "Erntet 12 Pomfrüchte.", description = "Ich brauche mehr Pomfrucht! Könntet Ihr mir bitte einige von den Bäumen schütteln?\n\nHier, nehmt das. Das benutze ich immer zum Ernten. Es beschleunigt die Angelegenheit, wenn die Früchte Euch entgegenkommen!", progress = "Es erstaunt mich immer wieder, wie viel Saft man aus diesen Dingern pressen kann.", completion = "Lecker! Ich stehe in Eurer Schuld, mein Freund.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30232] = {title = "Spitze Federn", objective = "Sammelt 80 seidige Federn.", description = "Die Falkenpopulation im Tal hat stark zugenommen. Dies ist eine gute Gelegenheit für unsere Pfeilmacher, denn wir brauchen jede Menge Federn, um die Bogenschützen auf der Mauer weiter mit Pfeilen auszustatten.\n\nKönntet Ihr vielleicht unseren Leuten beim Sammeln dieser Federn helfen?", progress = "Ich bedauere es ja fast, jemanden mit Talenten wie Euch um solch niedere Gefallen zu bitten, aber dies sind wirklich schwierige Zeiten.", completion = "Ich danke Euch wirklich von ganzem Herzen, junger Mann.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30233] = {title = "Knackzahn", objective = "Tötet Knackzahn.", description = "Hallo! Also, ich stecke sozusagen in der Klemme ... Mir fällt nur EIN guter Name für einen Wolf ein... Na, gespannt? Genau: Knackzahn! Ganz schön gewitzt, nicht wahr? Aber jetzt treiben sich gleich ZWEI große, böse Wölfe in den Wäldern herum. Und das bringt mich ganz durcheinander.\n\nIch möchte, dass Ihr einen von ihnen tötet, damit ich den Namen neu vergeben kann. Ist doch ganz einfach, oder? Besonders für jemanden mit so unglaublichen Fähigkeiten wie Euch.\n\nAlso, nehmt Ihr an? Ich hoffe doch sehr!", progress = "Knackzahn. Knackzahn. Jedes Mal, wenn ich den Namen sage, erschaudere ich vor Wonne. Ich bin wirklich unschlagbar darin, Namen zu vergeben.", completion = "Ja! Jetzt ist nur noch ein Knackzahn übrig, der die Ziegen und Yaks im Tal der Ewigen Blüten in Angst und Schrecken versetzt. Und so sollte es auch sein! Ich danke Euch!\n\nIch hoffe nur, dass nicht noch mehr große, böse Wölfe auftauchen. Ich glaube nämlich nicht, dass mir noch einmal ein so grandioser Name einfällt.", rewards = "Ihr bekommt:\n\nSchätze des TalsTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30234] = {title = "Zangenkiefer", objective = "Tötet Zangenkiefer und bringt Rens Langstab zurück.", description = "Zangenkiefer! Das klingt doch nach purer, roher Gewalt, nicht wahr? Den Namen habe ich selbst ersonnen. Und ich finde ihn sehr passend. Ich habe nämlich stundenlang versucht, ihm meinen Stab abzunehmen, aber er wollte einfach nicht loslassen!\n\nAlso gut, vielleicht waren es auch nur einige Sekunden. Ich erzähle Freunden lieber die Wahrheit. Auch wenn das meine Geschichten weniger aufregend klingen lässt.\n\nAber wäret Ihr vielleicht so freundlich, Eure nahezu allmächtigen Kräfte zu entfesseln, um diesem Krokilisken den Stab zu entreißen und ihn mir wiederzubringen? Und zwar am besten in einem Stück!", progress = nil, completion = "Mein Stab! Mein wundervoller Stab! Nie wieder werden wir uns trennen. Ich werde mich auf dich lehnen und du wirst immer bei mir sein. Und ich verspreche dir, dass ich nie wieder auf Krokilisken mit dir einprügele.\n\nIch danke Euch. Eure Stabwiederbeschaffungsfertigkeiten waren heute von unschätzbarem Wert!", rewards = "Ihr bekommt:\n\nSchätze des TalsTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30235] = {title = "Krakwall", objective = "Besiegt Kwall, den Geist der Nebelfälle.", description = "Kwall ist ein sehr mächtiger und sehr alter Wassergeist, auch wenn seine kindische Art nicht darauf schließen lässt.\n\nHeute morgen hätte Kwall fast sieben Leute in der Schenke getötet, als er nur aus Spaß ein paar Wasserfässer explodieren ließ.\n\nSo lange irgendwo Wasser fließt, ist Kwall zugegen. Man kann ihn nie endgültig ausschalten. Aber wir können ihm zeigen, dass wir seine gefährlichen Scherze nicht gutheißen.\n\nKönntet Ihr ihm diese Botschaft im Namen des Dorfes überbringen?", progress = nil, completion = "Um der Sicherheit der Dorfbewohner willen hoffe ich, dass er jetzt eine Zeit lang Ruhe gibt.\n\nIch danke Euch, mein großzügiger Freund.", rewards = "Ihr bekommt:\n\nSchätze des TalsTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30236] = {title = "Aetha", objective = "Besiegt Aetha, den Geist der Goldenen Winde.", description = "Anscheinend hat Aetha wieder einmal das Vieh freigelassen und es in den Fluss getrieben. Der Bürgermeister hat uns aufgetragen, ihr deutlich zu machen, dass solcherlei Schabernack gänzlich unerwünscht ist.\n\nWäret Ihr vielleicht so freundlich, Euch zum Hügelkamm oberhalb des Dorfes zu begeben und ihr eine Lektion zu erteilen? Ihr könnt sie nicht unwiederbringlich töten, aber zumindest könnt Ihr sie für eine Weile vertreiben. Das sollte ihr eine deutliche Warnung sein.", progress = nil, completion = "Diese Geister haben das Aussehen von Kindern, aber sie verfügen für ihre Größe über erstaunliche Kräfte. Euer Sieg über sie ist alles andere als selbstverständlich. Wir wissen das zu schätzen.", rewards = "Ihr bekommt:\n\nSchätze des TalsTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30237] = {title = "Der ewige Aufstand der Pandaren", objective = "Tötet 8 uralte Mogugeister.", description = "An der Tu-Shen-Begräbnisstätte im Osten tragen die Geister der uralten Mogu und die Geister unserer Pandarenvorfahren einen ewigen Kampf aus der Zeit des Pandarenaufstands aus. Seit die Mogu in das Tal zurückgekehrt sind, scheinen die Geister keine Ruhe zu finden.\n\nWenn Ihr uns helfen wollt, dann begebt Euch bitte zum Friedhof und besiegt die uralten Mogugeister noch einmal. Vielleicht finden dann unsere Vorfahren endlich Frieden.", progress = nil, completion = "Der Sieg über ihre Moguunterdrücker scheint die Geister der Pandarenmönche zufrieden gestellt zu haben. Es ist nur ein kleiner Sieg, aber eine Geste der Ehre für die großen Helden der Vergangenheit.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30238] = {title = "Ehre, wem Ehre gebührt", objective = "Erweist 6 Pandarengrabsteinen die Ehre.", description = "Die Geister unserer Vorfahren tragen erneut eine ihrer früheren Schlachten an der Tu-Shen-Begräbnisstätte im Osten aus.\n\n<Volk>, ich möchte Euch um einen Gefallen bitten: Erweist bitte ihren Grabsteine die Ehre. Erinnert sie daran, dass sie auch nach all diesen Jahren noch Respekt erfahren und sie es verdient haben, in Frieden zu ruhen.", progress = nil, completion = "Ich danke Euch, mein Freund. Euer Respekt gegenüber unseren Vorfahren bedeutet uns sehr viel.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30239] = {title = "Lao-Fe der Sklavenbinder", objective = "Tötet den Geist von Lao-Fe dem Sklavenbinder.", description = "Aus der oberen Höhle der Tu-Shen-Begräbnisstätte hört man das Geschrei von Lao-Fe dem Sklavenbinder.\n\nDurch seine Vernichtung sollte der Sieg der Geister der Pandarenmönche gewährleistet sein.", progress = "Lao-Fe der Sklavenbinder war selbst für einen Mogu äußerst heimtückisch. Er war einer der ersten, der während des Aufstands der Tu-Shen-Mönche überwältigt werden konnte. Dieser Sieg diente den Mönchen während des gesamten Aufstands als Ansporn.", completion = "Lao-Fe der Sklavenbinder war einer der widerwärtigsten und heimtückischsten Mogu seiner Zeit. Möge seine Vernichtung die Mogu im Tal daran an das Schicksal gemahnen, das ihnen droht, wenn sie noch einmal die heiligen Teiche beschmutzen.\n\nEure Stärke ist wahrlich beeindruckend, &lt;Klasse&gt;. Ich zolle Euch Respekt.", rewards = "Ihr bekommt:\n\nSchätze des TalsTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30240] = {title = "Überlebensring: Feuer", objective = "Betretet den Überlebensring und überlebt 60 Sekunden lang, ohne hinausgestoßen zu werden.", description = "Dies ist eine der Herausforderungen, die ich meinen Kriegern stelle, damit sie stark und flink auf den Beinen bleiben. Mal sehen, wie Ihr Euch haltet.\n\nÜberlebt 60 Sekunden im Ring, ohne hinausgestoßen zu werden. Macht Euch auf alles gefasst!", progress = nil, completion = "Nicht schlecht. Überhaupt nicht schlecht.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30241] = {title = "Warnung an Steinpflug", objective = "Reist nach Steinpflug im Tal der Vier Winde.", description = "So viel Tod. Und wenn man Botschafter Hans Geschichten von den Mantis Glauben schenken kann, ist es noch längst nicht zu Ende.\n\nWir müssen helfen. Wir müssen unseren Teil zur Rettung von Leben beitragen.\n\nReist nach Steinpflug. Warnt sie vor dem bevorstehenden Angriff der Mantis.\n\nIch werde mit den Kräften, die ich noch aufbringen kann, zu Euch stoßen, nachdem ich Kors Leichnam zur letzten Ruhe gebettet habe.", progress = nil, completion = "Mantis aus dem Süden? Das ist kein guter Tag.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30242] = {title = "Überlebensring: Klingen", objective = "Betretet den Überlebensring und überlebt 60 Sekunden lang, ohne hinausgestoßen zu werden.", description = "Dies ist eine der Herausforderungen, die ich meinen Kriegern stelle, damit sie stark und flink auf den Beinen bleiben. Mal sehen, wie Ihr Euch haltet.\n\nÜberlebt 60 Sekunden im Ring, ohne hinausgestoßen zu werden. Bleibt auf den Beinen.", progress = nil, completion = "Nicht schlecht. Überhaupt nicht schlecht.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30243] = {title = "Frittierte Mantis", objective = "Verwendet einen Kessel mit heißem Öl, um 80 Mantis am Tor der Untergehenden Sonne zu töten.", description = "Die Mantis greifen schon wieder an und wir sind auf der Mauer etwas unterbesetzt. In der Hoffnung auf Eure Hilfsbereitschaft habe ich schon einmal einen der spaßigeren Posten für Euch reserviert: das heiße Öl!\n\nDas ist etwas brutaler und etwas weniger skandalös, als es klingt.\n\nEigentlich ist es ganz einfach: Geht rauf auf die Mauer, findet eine der Stationen mit heißem Öl und kippt es auf alle Mantis, die gegen die Mauer anstürmen. Eine wirklich sehr effektive Methode.", progress = "Das Saubermachen ist viel härtere Arbeit. Aber glücklicherweise habt Ihr damit nichts zu tun.", completion = "Ihr habt den Mantis-Truppen verheerenden Schaden zugefügt. Die Mauerverteidiger sollten die Lage jetzt unter Kontrolle bringen können.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30244] = {title = "Schlangenbändigung", objective = "Tötet 10 Krik'thik-Mantis am Tor der Untergehenden Sonne.", description = "Es sind Mantis auf die Mauer gelangt. Die Verteidiger auf der Brustwehr haben nach Hilfe gerufen.", progress = nil, completion = "Die Mantis-Truppen auf der Mauer wurden ausgedünnt.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30245] = {title = "Verlorene Späher", objective = "Sichert die Berichte von 3 Shado-Pan-Spähern.", description = "Wir haben einige Späher in Richtung der Fünf Schwestern im Norden entsandt, damit sie herausfinden, was für ein Moguanführer aufgetaucht ist, um die feindlichen Truppen durch das Tal zu führen. Es sind nur wenige Späher zurückgekehrt.\n\nIch würde gern hoffen, dass sie einfach zu viel Bier getrunken oder zu viel Spaß mit einigen Pandarenmädchen haben. Aber sie könnten auch in großen Schwierigkeiten stecken.\n\nKönntet Ihr Ausschau nach den Spähern halten? Und fragt sie auch gleich nach Informationen über diesen Anführer, bitte.", progress = "Geht. Verschollene Späher. Böser Moguanführer. Erinnert Ihr Euch?", completion = "Die Späher haben den Standort des Moguanführers ausfindig gemacht.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30246] = {title = "Mantis auf der Brustwehr", objective = "Tötet 10 Krik'thik-Mantis auf der obersten Ebene des Tors der Untergehenden Sonne.", description = "Einige der Mantis haben es bis auf die oberste Ebene der Mauer geschafft. Wenn es zu viele von ihnen werden, drohen unsere Soldaten dort überrannt zu werden.\n\nIch möchte, dass Ihr Euch nach dort oben begebt und alle Feinde erledigt, die durchgebrochen sind.", progress = nil, completion = "Die Mantistruppen auf der Mauer wurden zurückgedrängt.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30247] = {title = "Rollclub: Tal der Ewigen Blüten", objective = "Schließt den Rollkurs des Tals der Ewigen Blüten ab.", description = "Folgt den Flaggen. Erreicht die Kontrollpunkte. Umrundet den Bogen. Kehrt zu mir zurück, bevor die Zeit abgelaufen ist.\n\nGebt mir Bescheid, wenn Ihr bereit seid.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][30248] = {title = "Schlachtzeit", objective = "Tötet Bai-Jin den Schlächter.", description = "Einige Späher haben den auf sich allein gestellten Shao-Tien-Imperion am Nordende der Mauer ausfindig gemacht.\n\nAnji Herbstlicht hat Euren Auftrag ganz klar definiert: Findet den Anführer und tötet ihn.", progress = "Ich hörte, dass Ihr Informationen über den Aufenthaltsort des neuen Moguanführers erhalten habt. Habt Ihr ihm schon in Anjis Auftrag eine Abreibung verpasst?", completion = "Ich bin beeindruckt! Was für eine vorausschauende und engagierte Person Ihr doch seid. Steht Euch gut.", rewards = "Ihr bekommt:\n\nSchätze des TalsTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30249] = {title = "Unter der Untergehenden Sonne", objective = "Tötet Kri'chon den Leichenhäscher.", description = "Eine riesige Bestie hat sich unter das Tor durch gegraben und ist im Hof aufgetaucht. Die Verteidiger brauchen Eure Hilfe!", progress = nil, completion = "Ich habe von Euren Heldentaten im Hof gehört! Euer Name wird an der Mauer für einige Zeit in aller Munde sein. Gut gemacht, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nSchätze des TalsTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30251] = {title = "Vyraxxis, der Schwarmfürst der Krik'thik", objective = "Tötet Vyraxxis, den Schwarm-Herrscher der Krik'thik.", description = "Ein riesiger Mantis ist in den inneren Bereich der Mauer eingedrungen. Ohne Eure Hilfe werden die Verteidiger kaum mit ihm fertig.", progress = nil, completion = "Euer Einsatz gefällt mir. Gute Arbeit.", rewards = "Ihr bekommt:\n\nSchätze des TalsTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30252] = {title = "Eine helfende Hand", objective = "Zerstört 8 unnachgiebige Felsen.", description = "Ich drücke und schiebe schon den ganzen Morgen an ihnen herum und hämmere auf sie ein, aber es ist hoffnungslos.\n\nDiese Felsbrocken bewegen sich nicht vom Fleck!\n\n\"Das ist doch ein Klacks\", hat Großvater gesagt. \"Landwirtschaft ist so einfach wie atmen!\", sagte er. Für ihn mag das so sein, aber nicht für mich!\n\nWie soll ich bei dieser LANDWIRTSCHAFT Erfolg haben, wenn ich mein Land noch nicht mal zur Bestellung freiräumen kann?\n\nHe, Moment mal. Ihr seht aus, als hättet Ihr ordentlich Muckis.\n\nWürdet Ihr mir helfen? Nur bis ich wieder zu Atem komme.", progress = nil, completion = "Was? Ihr habt die Steine beiseitegeschafft? Das ist ja wunderbar!\n\nVielleicht kann ich jetzt ja endlich etwas auf diesem Acker anbauen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nYoon beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30254] = {title = "Agrikultur II: Pflügen und Pflanzen", objective = "Pflügt 2 Flächen ungepflügtes Erdreich um, damit daraus gepflügtes Erdreich wird. Pflanzt dann auf 2 Flächen die Simp-L-WAX-Grünkohlsamen ein.", description = "So, jetzt ist es an der Zeit, die Samen einzupflanzen.\n\nAls erstes müssen wir dazu den Boden vorbereiten! Ihr müsst ihn pflügen, damit die Samen auskeimen können.\n\nPflügt die zwei Ackerflächen da drüben und pflanzt dann die Samen ein.", progress = "Also los! Wühlt den Boden um und pflanzt die Samen ein!\n\nIhr wollt doch wohl nicht aufgeben? Ich brauche Eure Hilfe!", completion = "Gut gemacht.\n\nHabt Ihr gesehen, wie sich sofort Wurzeln gebildet haben? Das ist einer der Gründe, warum dieses Tal ideal für die Landwirtschaft geschaffen ist. Irgendetwas in diesem Boden hier lässt die Pflanzen wachsen wie verrückt!\n\nAber die Arbeit ist damit noch nicht erledigt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30255] = {title = "Agrikultur III: Hegen und Pflegen", objective = "Verwendet die rostige Gießkanne, um 2 ausgetrocknete Simp-L-WAX-Grünkohlköpfe auf dem Gehöft Sonnensang zu wässern.", description = "Mein Großvater hat immer gesagt: \"Yoonie, Kohlköpfe sind wie Frauen: Wenn man sie ignoriert, verwelken sie. Aber wenn man sie hegt und pflegt, werden sie rund und proper und man kann ihnen eine Schleife umbinden und sie mit auf den Markt nehmen und stolz den Leuten zur Schau stellen und...\" Hey, schaut mich nicht so an! Das waren halt andere Zeiten damals!\n\nDer Punkt ist: Jetzt, wo unsere Kohlköpfe Wurzeln geschlagen haben, benötigen sie Pflege! Sie sehen heute etwas trocken aus, also müsst Ihr sie wässern.\n\nHier ist die alte Gießkanne meines Großvaters. Sie ist immer in der Nähe des Feldes, wenn Ihr sie braucht.", progress = nil, completion = "Sehr gut! Die Kohlköpfe sehen gesund und gepflegt aus!\n\nHeute waren sie nur durstig, aber man weiß nie, was sie als Nächstes benötigen. Behaltet die Pflanzen immer im Auge und kümmert Euch gut um sie.\n\nMein Großvater hat mir jede Menge Ratschläge mitgegeben. Wenn Ihr Euch also mal bezüglich der Pflege unsicher seid, könnt Ihr mich immer fragen!\n\nAber bitte nur Fragen zur Landwirtschaft...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30256] = {title = "Agrikultur IV: Ernten", objective = "Erntet 2 Simp-L-WAX-Grünkohlköpfe von Eurem Feld und bringt sie zu Bauer Yoon auf dem Gehöft Sonnensang.", description = "Jetzt ist es an der Zeit, dass wir die Früchte unserer harten Arbeit ernten! Normalerweise müssten wir ja einen Tag warten bis zur Ernte dieser Pflanzen.\n\nAber glücklicherweise lassen diese Samen, die wir von Grünfeld bekommen haben, die Pflanzen EXTRA SCHNELL wachsen. Der Ertrag wird nicht allzu hoch sein, aber trotzdem können Nachwuchsbauern so den ganzen Prozess kennenlernen.\n\nUnsere Kohlköpfe müssten jetzt erntereif sein. Und ich überlasse natürlich Euch diese Ehre!", progress = "Jetzt sieh sich doch einer mal diese... äh... Dinger an. Wie nennt man so was noch mal? Ach ja: Prachtexemplare!\n\nWas für Prachtexemplare!\n\nSo langsam klappt es ja mit der Landwirtschaft.", completion = "So, das waren die Grundlagen!\n\nBoden pflügen, Samen pflanzen, die Schösslinge hegen und auf das Ergebnis warten!\n\nHeute war es einfach, aber lasst Euch nicht blenden: Mein Großvater hat mir alle möglichen verrückten Dinge über das Gehöft Sonnensang erzählt.\n\nDie Landwirtschaft besteht nicht nur aus Riesenrüben und Rosen, wisst Ihr?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDisable Gift Dailies\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30257] = {title = "Lernen und Wachsen V: Halbhügelmarkt", objective = "Untersucht die dunkle Erde unter dem Haus des Bauern Yoon und bringt dann ein Geschenk zu Gina Lehmkrall auf dem Halbhügelmarkt.", description = "Na schön. Der ganze Anbau war nur zum Üben!\n\nSeid Ihr bereit, Euch an der echten Sache zu versuchen?\n\nEs gibt da eine Dame namens Gina Lehmkrall, die den Halbhügelmarkt auf der anderen Straßenseite im Süden leitet.\n\nIch höre, sie will Gemüse kaufen. Bei Eurer ersten Begegnung solltet Ihr nicht mit leeren Händen auftauchen.\n\nWarum seht Ihr Euch nicht auf dem Gehöft um, ob sich irgendwelche Gegenstände dort verbergen?\n\nVielleicht finden wir ja ein schönes Geschenk für unsere neue Nachbarin!", progress = "Hey, habe ich Euer Gesicht hier nicht schon mal gesehen? Wie heißt Ihr?", completion = "Meine Güte, eine Sumpflilie!\n\nWoher wusstet Ihr, dass das meine Lieblingsblume ist? Ihr seid ganz nach meinem Geschmack, Fremder.\n\nDanke!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30258] = {title = "Mung-Mungs Stimme I: Das Problem eines Ho-zen", objective = "Sprecht mit Mung-Mung bei Haohan Lehmkralls Haus im Tal der Vier Winde.", description = "Ich habe darüber nachgedacht, wie ich bei den Ackerbauern einen guten Eindruck machen kann, <Name>.\n\nDer Bund der Ackerbauern nimmt ja jedes Jahr neue Mitglieder auf, und der Wahlrat besteht aus fünf Leuten.\n\nGinas Stimme haben wir schon, vor den anderen vier Mitgliedern des Rats müssen wir uns aber noch bewähren.\n\nWarum geht Ihr nicht rüber und begrüßt Mung-Mung? Er arbeitet auf Herrn Lehmkralls Bauernhof im Nordwesten.", progress = nil, completion = "Ja?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30259] = {title = "Mung-Mungs Stimme II: Bis ins Mark verdorben", objective = "Sammelt 10 angenagte Karotten auf.", description = "Die Shed-Ling sind wieder da!\n\nHaben Herrn Lehmkralls Karotten angeknabbert. Ruinieren seine Ernte. Und wer muss es ausbaden? Mung-Mung, genau!\n\nSammel schnell die angenagten Karotten auf, bevor Herr Lehmkrall sie sieht. Sie sind über die Felder im Südwesten verstreut und unterirdisch, in den Tunneln der Shed-Ling.\n\nSonst bekommt Mung-Mung großen Ärger.\n\nTust du das für mich?", progress = "Ich hab' hier keine angenagten Karotten gesehen und du auch nich'. Herr Lehmkrall wird nie was davon mitkriegen, ja?", completion = "Was soll das heißen, kein Shed-Ling hat sie angefressen? Zu kleine Bissspuren? WAS? Wer sonst macht denn so was?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30260] = {title = "Den Hof pflegen I: Das Unkraut", objective = "Redet mit Gai Lan im Kernland im Tal der Vier Winde.", description = "Hey <Name>, ich habe in letzter Zeit darüber nachgedacht, meinen Hof zu erweitern.\n\nSeht Ihr diese Fläche dort, die mit Unkraut überwuchert ist? Wenn wir das beseitigen, könnten wir dieses Land für den Anbau verwenden.\n\nIch habe gehört, es gibt einen Bauer namens Gai Lan, der etwas von Unkrautvernichtung versteht.\n\nSein Hof ist im Westen. Redet mit ihm - vielleicht hilft er uns.", progress = nil, completion = "Oh ja, Bauer Yoon. Ich habe ihn in der Stadt gesehen.\n\nScheint ein anständiger Bursche zu sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30261] = {title = "Rollclub: Schlangenrücken", objective = "Schließt die Rollstrecke des Schlangenrückens ab.", description = "Erreicht so schnell wie irgend möglich den Fuß der Mauer.\n\nSprecht mich an, wenn Ihr bereit seid, loszurollen.", progress = nil, completion = "Ich glaube nicht, dass sie das beim Bau der Mauer als Nutzungsmöglichkeit in Erwägung gezogen haben...", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30262] = {title = "NOT USED", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30263] = {title = "Den Wald säubern", objective = "Tötet 6 Mogu der Shao-Tien in der Winterastlichtung.", description = "Die Shao-Tien sind in Bewegung. Die meisten haben sich nach ihrer letzten Niederlage in die Winterastlichtung zurückgezogen. Wir sollten den Vorteil nutzen.\n\nTragt den Kampf zu diesen Mogu in der Lichtung im Nordwesten. Wir sollten ihnen keine Minute der Ruhe gönnen, solange sie sich hier im Tal befinden.", progress = nil, completion = "Wir müssen unseren Vorteil nutzen, wenn sich eine Gelegenheit ergibt. Wir müssen die Shao-Tien für jeden Moment, den sie im Tal verbleiben, zahlen lassen.\n\nIhr habt heute gute Arbeit geleistet, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30264] = {title = "Der Feind vor den Toren", objective = "Vernichtet mithilfe einer Shado-Pan-Himmelsschlange 60 Angreifer der Krik'thik, 3 Kriegswagen der Krik'thik und 3 Katapulte der Krik'thik.", description = "Die Mantistruppen bestürmen die Mauer. Ich habe ein paar Himmelsschlangen angefordert, um sie aus der Luft anzugreifen.\n\nWäret Ihr bereit, eine von ihnen zu lenken?", progress = nil, completion = "Kun hat mir von Euren Großtaten da draußen erzählt. Ihr habt nicht nur ihn, sondern auch mich beeindruckt.\n\nGute Arbeit.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30265] = {title = "Das Funkeln im Auge", objective = "Bergt 8 Glitzerrubine.", description = "Ich habe lange in das Wasser geblickt und über das Leben, die Liebe und all die schönen Dinge sinniert, als ich plötzlich ein Glitzern im Wasser bemerkte. Und das waren nicht etwa die Reflexionen meiner strahlenden Persönlichkeit, sondern tatsächlich ein paar glitzernde Objekte da unten! Sicher etwas Wertvolles.\n\nWürdet Ihr vielleicht in die Tiefen hinabtauchen, um den See seiner glitzernden Geheimnisse zu berauben? Oh, bitte!", progress = "Und? Was war dieses mysteriöse Glitzern? Ich sterbe vor Neugierde. Münzen? Pokale? Ein Dutzend entsorgter Hochzeitsringe?", completion = "Rubine! Und zwar sehr wertvolle! Und vielleicht steckt dahinter eine interessante Geschichte mit einem Dutzend Bräuten mit gebrochenen Herzen? Wahrscheinlich nicht. Aber trotzdem ein aufregender Fund!\n\nIch danke Euch von ganzem Herzen, mein großzügiger Freund! Mit Euren aquatischen Fähigkeiten habt Ihr meine Garderobe davor bewahrt, ganz fürchterlich nass zu werden.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30266] = {title = "Himmel voller Blut", objective = "Tötet 30 Drohnen der Krik'thik mit einer Kanone am Tor der Untergehenden Sonne.", description = "Wir haben im oberen Bereich der Türme an den Flanken des Haupttors Kanonen platziert. Sie sind unsere beste Waffe, um die fliegenden Mantis daran zu hindern, die Mauer zu überfliegen. Und genau das versuchen sie gerade wieder.\n\nIch glaube, Ihr seid nun an der Reihe, <Name>.", progress = nil, completion = "Eure Schützentalente sind beachtlich, &lt;Klasse&gt;. Daran werde ich mich erinnern, wenn sich wieder einmal Feinde aus der Luft nähern.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30267] = {title = "Anglerträume", objective = "Besorgt 18 Lichtungsglühwürmer und 5 spindeldürre Blutfedern.", description = "Ich liebe es zu angeln. Der Spaß wäre jedoch wesentlich größer, wenn ich meine Köder hätte. Die hat aber meine Frau Rin wegen eines... eines Missverständnisses weggeworfen.\n\n<Lichtungswirker Lang seufzt.>\n\nSoll etwa ein ganzer Angeltag wegen einer winzigen ehelichen Meinungsverschiedenheit verdorben sein? Nein! Alles, was ich brauche, sind ein paar Insekten und Federn - und diese Lichtung ist voll von beidem.\n\nWürdet Ihr einem Angler vielleicht helfen?", progress = "Ich sehe es nicht ein, auf das Angeln zu verzichten. Das ist mein Leben!", completion = "Endlich jemand, der mich versteht. Angeln ist doch das Einzige, was zählt, oder?\n\nVielleicht sollte ich Neu-Cifera verlassen... Einfach meinen Kram packen und mich den Anglern unten im Süden anschließen. Natürlich könnte ich meine Familie nicht zurücklassen...\n\nAber trotzdem... Ein Pandaren kann doch auch mal träumen, stimmt's?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30268] = {title = "Das Düsterfieber", objective = "Sammelt 6 Düsterschuppenköpfe von Angreifern der Düsterschuppen im Krasarang.", description = "Seht genau hin. Der Fluss in der Nähe wimmelt von diesen Schlangen. Ihr Gift führt zu einem Zustand, den die Einheimischen \"das Düsterfieber\" nennen.\n\nEin paar Flüchtlinge wurden gebissen, als sie aus dem Tempel flohen, und zeigen bereits erste Symptome: Übelkeit, Erbrechen und Schweißausbrüche. Der Körper scheidet jegliche Flüssigkeit aus, was zu Dehydrierung und möglicherweise zum Tod führt.\n\nWir verabreichen so schnell wie möglich Gegengift, aber wir brauchen noch mehr Giftdrüsen. Haltet Euch nicht damit auf, die Drüsen selbst zu entfernen - bringt einfach den ganzen Kopf mit.", progress = "<Anduin konzentriert sich aufmerksam auf seine Hände und schneidet schnell die Giftdrüsen aus den Schlangen.>\n\nIm Rachen... fünf Zentimeter hinter der zweiten Reihe Fangzähne...", completion = "Danke, &lt;Klasse&gt;. Ich wusste, dass Ihr zäh genug seid, um damit fertigzuwerden.\n\nWenn ich mir so die Geräusche anhöre, die diese Flüchtlinge von sich geben, würde ich das Düsterfieber nicht meinem ärgsten Feind wünschen.", rewards = "DüsterfieberschutzLorifederbandSchlangenkieferbandSchlangenschwarmringSchlickschuppenbandDer folgende Zauber wird auf euch gewirkt:\n\nRefugee Camp Act II: Ping to Begin\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30269] = {title = "Unsichere Passage", objective = "Helft Koro Nebelgänger, eine Gruppe Flüchtlinge vom Tempel des Roten Kranichs zum Refugium der Kranichschwingen zu eskortieren. Sprecht vor Beginn zuerst mit Koro.", description = "Wie wir im Tempel immer sagen: \"Kämpft nie gegen einen Tiger, wenn Ihr einen Ho-zen im Nacken habt.\"\n\nWir werden uns um das Sha kümmern, aber zunächst muss unsere Aufmerksamkeit der unmittelbaren... Plage gelten.\n\n<Koro schleudert den sich krümmenden Saurok HART gegen den Felsen.>\n\nFlüchtlingsgruppen aus dem Tempel sind auf dem Weg zu einem Lager im Norden, doch sie werden von Saurok angegriffen. Helft mir, die nächste Gruppe zum Lager zu bringen, dann entscheiden wir über unser weiteres Vorgehen.", progress = nil, completion = "Danke, &lt;Name&gt;. Ohne Eure Hilfe hätten wir es nicht geschafft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30270] = {title = "Blenden der Flussklingen", objective = "Tötet 8 Wegelagerer der Flussklingen in der Umgebung des Refugiums der Kranichschwingen.", description = "\"Ein Falke mit Kappe fängt keine Beute.\"\n\nDas ist eines der ersten Mantras, die wir jungen Mönchen im Tempel beibringen. Es bedeutet, dass sogar ein Gegner, der so schnell und tödlich wie ein Falke ist, neutralisiert werden kann, indem man ihn seiner Sinne beraubt.\n\nDie Saurok verfügen in der ganzen Region über Späher, die ihren Raubzügen als Augen dienen.\n\nEs wird Zeit, dass wir ihnen die Augen ausstechen, meint Ihr nicht auch?\"", progress = nil, completion = "Gut gemacht. Ich wünschte nur, ich hätte Euch begleiten können...\n\nDas Blut auf diesen Handlappen ist nicht mein eigenes, wisst Ihr?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRefugee Camp Act II: Ping to Begin\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30271] = {title = "Shapokalypse", objective = "Tötet Sha in der Nähe von 10 hoffnungslosen Mönchen oder Akolythen, um sie zu inspirieren.", description = "Das Sha hat die mysteriöse Fähigkeit, mächtige, oft überwältigende Gefühle in seinen Opfern zu wecken.\n\nAls wir aus dem Tempel geflohen sind, blieben höherrangige Mitglieder des Ordens der Kranichschwingen zurück, um unsere Flucht zu decken. Sie wurden zweifellos einem starken emotionalen Trauma ausgesetzt, und ich befürchte, dass nicht alle stark genug sind, dem Drang zu widerstehen, der Verzweiflung zu verfallen.\n\n$p, wir müssen ihnen zeigen, dass es immer noch Hoffnung gibt! Zeigt ihnen, dass Verzweiflung besiegt werden KANN!", progress = "Haltet nach Kranichschwingen-Pandaren Ausschau, die der Verzweiflung anheimfallen, und erschlagt Sha in ihrer Nähe, während ich Euch unterstütze!", completion = "Ehrlich gesagt bin ich ein wenig überrascht, dass das funktioniert hat.\n\nPandaria erweist sich als Land, in dem die Grenze zwischen Metapher und Realität verschwommen ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30272] = {title = "Regen schlagen", objective = "Tötet 18 Spuke der Verzweiflung beim Tempel des Roten Kranichs.", description = "Was den Teil \"auf den Regen einschlagen\" angeht... Nun, manchmal muss man es einfach tun.\n\n\"Hoffnung ist die Sonne jenseits eines stürmischen Himmels - stets im Herzen, aber dem Auge verborgen.\"\n\nDas aus dem Tempel strömende Sha scheint kein Ende zu nehmen. Aber um hinter den Schleier der Verzweiflung zu sehen, müsst Ihr ihn zerschneiden.\n\nMit ein wenig Glück findet Ihr hinter den Wolken den Sonnenschein...", progress = nil, completion = "Wisst Ihr was, &lt;Name&gt;? Wir geben ein ziemlich gutes Team ab!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30273] = {title = "Im Haus des Roten Kranichs", objective = "Begebt Euch in den Keller des Tempels des Roten Kranichs und besiegt das Sha der Verzweiflung.", description = "\"Gebrochen sind die Körper, denen ein hoffnungsloses Herz innewohnt - die Seuche der Verzweiflung schlägt von innen heraus zu.\"\n\nDies war das letzte Stück Weisheit, das der Rote Kranich mir nur Stunden vor dem Ausbruch des Sha übermittelt hat. Jetzt ergibt es einen Sinn...\n\n$p, als das Sha angegriffen hat, brach es aus dem Kellergewölbe des Tempels hervor...\n\nAll die Lehren - der Weg des Kranichs selbst... Alles war eine Vorbereitung auf den Kampf gegen das Sha der Verzweiflung.\n\nDer Rote Kranich hat diesen Konflikt schon seit Jahrhunderten erwartet!", progress = nil, completion = "Ihr habt das Sha der Verzweiflung bezwungen. Mein Orden wird sich darum kümmern, hier aufzuräumen.\n\nWie es scheint, ist die Zeit gekommen, sich den Konsequenzen von Shaohaos Entscheidungen zu stellen.\n\nDieser Konflikt hat sich über Jahrtausende hinweg angebahnt - die Ankunft Eures Volkes war lediglich der Stein, der die Lawine ins Rollen gebracht hat. Wie dem auch sei, Eure Hilfe wird nötig sein, wenn Pandaria überleben soll.", rewards = "NayelikordelTodesrachengürtelTiefwildtaillenschutzNarsongschnallengürtelAngkhalkordelFlussklingengürtelSarjuntaillenschutzKorjanigurtGurt des DojaniIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30274] = {title = "Die arkane Oubliette", objective = "Sucht und deaktiviert 3 Fesseln der Oubliette.", description = "Ein Mitglied der Allianz? Hier? Elune sei gepriesen.\n\nMein Trupp ist auf ein Hindernis gestoßen. Wir haben mit ein paar alten Texten, die wir auf die Zeit vor Azsharas Herrschaft datiert haben, ein Portal zu diesem Land geöffnet.\n\nUnglücklicherweise waren die Koordinaten auf den Tafeln geschützt, und so lieferte uns das Portal, das uns zu unserem Ziel bringen sollte, in dieser Oubliette ab.\n\nWir sind hier schon seit Tagen gefangen, und das Portal zehrt langsam an unserer Energie, um sich selbst zu versorgen.\n\nKönnt Ihr die Fesseln in der Nähe suchen, die die Oubliette binden, und sie deaktivieren?", progress = nil, completion = "Fabelhaft! Euer Zeitgefühl war einwandfrei. Noch ein Tag da drin und wir hätten uns wahrscheinlich in Nichts aufgelöst.\n\nJetzt können wir unsere Suche nach den Teichen der Jugend fortsetzen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30275] = {title = "Gigantismus", objective = "Bringt den riesigen Krokiliskenschwanz zu Yan in Neu-Cifera im Tal der Vier Winde.", description = "Wie konnte dieser Krokilisk so groß werden?\n\nKlar, es gibt Gerüchte von sehr alten Krokilisken, die zu einer enormen Größe wachsen... aber dieses Weibchen ist höchstens 12 Jahre alt.\n\nVielleicht kann jemand in Neu-Cifera mehr über die Sache herausfinden.", progress = "Was habt Ihr denn da?", completion = "Dieser Schwanz stammt von einem Krokilisken? Seltsam, soweit flussaufwärts gibt es nicht besonders viele Krokis.\n\nIst Euch das gigantische Obst und Gemüse aufgefallen, das unsere Bauern anpflanzen? Dieser Krokilisk ist aus dem gleichen Grund so groß geworden - es ist irgendetwas im Wasser.\n\nWas das ist, wissen wir nicht... aber wir sehen es als ein großes Glück an. Riesiges Gemüse ist eine tolle Sache. Ein riesiger Krokilisk dann und wann ist bloß eine Nebenerscheinung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30277] = {title = "Die bröckelnde Halle", objective = "Bergt das uralte Guo-Lai-Artefakt.", description = "In den Guo-Lai-Hallen wurde jenseits der Statuenhalle ein uraltes Moguartefakt entdeckt. Wir haben schon mehrfach versucht, das Artefakt zu bergen, hatten aber bisher keinen Erfolg.\n\nDieses Artefakt darf auf keinen Fall in die Hände der Shao-Tien fallen. Jemand muss dieses Artefakt bergen - und zwar schnell.\n\nKann ich auf Euch zählen?", progress = "Habt Ihr das Artefakt schon bergen können?", completion = "Wenn alle anderen scheitern, seid Ihr zur Stelle. Das gefällt mir so an Euch.\n\nIch danke Euch, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30278] = {title = "REUSE FOR PROGRESSION", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30279] = {title = "REUSE FOR PROGRESSION", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30280] = {title = "Ein Röhren aus der Tiefe", objective = "Tötet Milau.", description = "Aus den Guo-Lai-Hallen dringt ein mächtiges Röhren. Die Mogu haben dort irgendeine uralte Bestie zum Leben erweckt. Und sie werden sie wohl schon bald auf meine Männer loslassen.\n\nIch möchte, dass Ihr in die Halle der Schlange eindringt und diese Bestie unschädlich macht, bevor die Mogu sie gegen uns einsetzen. Mit einer solch gefährlichen und bedeutenden Aufgabe kann ich niemanden außer Euch beauftragen.", progress = nil, completion = "Euch ist gelungen, was selbst mir kaum möglich gewesen wäre. Demütig zolle ich Eurer Stärke Respekt.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30281] = {title = "Leises Anschleichen", objective = "Tötet 6 Shao-Tien-Mogu am Weißblütensee.", description = "<Er lehnt sich vor und zeichnet etwas, was nur einen Mogu darstellen kann, zeigt in Richtung des Sees im Westen, zieht die stumpfe Seite seines Dolches über seine Kehle und schaut Euch erwartungsvoll an. Es scheint, als wolle er, dass Ihr die Mogu am Weißblütensee tötet.>", progress = nil, completion = "Die Anzahl der Mogu scheint ausreichend reduziert zu sein.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30282] = {title = "Den Dreck wegbrennen", objective = "Verbrennt 10 Shao-Tien-Banner.", description = "Die Mogu haben ihre dreckigen Banner rund um den See im Westen gehisst, um dieses Gebiet als ihr Territorium zu markieren. Nehmt diese Fackel und zeigt ihnen, was wir von ihren Bannern halten.", progress = nil, completion = "Ich gehe davon aus, dass der Rauch am Horizont bedeutet, dass die Mogu die Botschaft erhalten haben. Sehr gut.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30283] = {title = "Zerschlagende Argumente", objective = "Zerstört die Shao-Tien-Ritualstatuen.", description = "Manchmal tun mir diese Mogu nachgerade leid... Vielleicht reißen sie anderen Völkern nur deshalb die Seelen heraus, weil sie selbst Probleme mit ihren Familien zu Hause haben? Vielleicht sollten wir mehr Verständnis für den Ursprung ihrer Gewaltbereitschaft aufbringen?\n\nOder wir zerschlagen einfach ihre seelenraubenden Ritualobjekte da unten am See. Das würde mir persönlich ja viel mehr Spaß bringen.", progress = nil, completion = "Wenn mich irgendjemand fragt, welcher Unhold denn ihre kleinen Statuetten kaputt gemacht hat, werde ich auf Euch verweisen.\n\nAber ich weiß Eure Hilfe natürlich trotzdem zu schätzen. Wirklich sehr liebenswert.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30284] = {title = "Tausend spitze Zähnchen", objective = "Tötet 9 Messerzahnschwärmer.", description = "Das Wasser hat heute vor Gefahren nur so gebrodelt! Eine Art schwärmende, fleischfressende Fischpest hat sich in unserem See breitgemacht! Ein abscheulicher Anblick. Und das, wo ich gerade dabei war, mich vollständig zu entkleiden, um mich meinen täglichen Wasserübungen hinzugeben!\n\nIhr seid doch geübt darin, alle möglichen Kreaturen zu entsorgen, nicht wahr? Würdet Ihr also vielleicht so freundlich sein, Eure Fertigkeiten zu nutzen, um allen schwimmbegeisterten Pandaren einen Gefallen zu tun?\n\nDas wäre eine wirklich noble Tat für die Allgemeinheit - und insbesondere für mich.", progress = nil, completion = "Ihr seid aber auch wirklich zu freundlich! Ich habe tatsächlich Gefallen an Euch gefunden.\n\nUnd jetzt werde ich mich wieder dem Wassertreten widmen. Ich werde mich beherrschen und meine Garderobe erst ablegen, wenn Ihr Euch entfernt habt. Sozusagen als Entgegenkommen für Eure Freundlichkeit.\n\nAuch wenn Euch dadurch ein famoser Anblick entgeht...", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30285] = {title = "Späherberichte der Wukao", objective = "Holt 3 Wukaospäherberichte.", description = "Nach dem Angriff sind einige Späherberichte da draußen geblieben, die wir noch nicht eingesehen haben. Mit etwas Glück befinden sie sich noch im Dorf, aber vielleicht sind sie auch schon den Mogu in die Hände gefallen.\n\nWenn Ihr mir alle Späherberichte zurückbringt, die Ihr finden könnt, würdet Ihr mir einen großen Gefallen tun. Die Mogu dürfen nichts über unsere Stellungen oder unsere gefundenen Artefakte erfahren. Dann wären nämlich die Männer in einer noch viel größeren Gefahr.", progress = "Habt Ihr die Berichte finden können? Ich mache mir Sorgen um die Sicherheit meiner Männer im Feld, wenn sie in die Hände der Mogu fallen.", completion = "Ihr seid sehr freundlich, &lt;Name&gt;. Ich bin jetzt wirklich sehr, sehr erleichtert.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30286] = {title = "In die Enge getrieben", objective = "Rettet 6 in die Enge getriebene Dorfbewohner von Nebelhauch.", description = "Viele Dorfbewohner sind verängstigt und in die Enge getrieben. Ihr müsst ihnen zu Hilfe eilen und sie beschützen.\n\nBitte beeilt Euch und rettet so viele von ihnen wie möglich!", progress = nil, completion = "Wir haben alle, die wir gefunden haben, in der Schenke versammelt. Ab jetzt sollten wir sie selbst beschützen können.\n\nDanke wieder einmal für Eure Hilfe, &lt;Name&gt;. Ihr scheint immer zur Stelle zu sein, wenn wir Eure Hilfe benötigen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30287] = {title = "Mogu keine guten Gäste", objective = "Tötet 6 Shao-Tien-Angreifer in Nebelhauch.", description = "Leven hat Rook hierher geschickt, um Mogu aufzuhalten. Sind aber mehr Mogu als Rook töten kann.\n\nHelft Ihr? Rook erzählt Leven auch von Eurer Hilfe. Versprochen.", progress = "Immer noch viele Mogu. Bitte helft Rook.", completion = "Rook kommt jetzt mit restlichen Mogu klar. Danke für Hilfe, guter Mann.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30288] = {title = "Es brennt... schon wieder!", objective = "Nutzt die Wassereimer in Nebelhauch, um 60 Feuer zu löschen.", description = "Ich weiß nicht, ob Ihr es bemerkt habt, aber meine Stadt brennt... schon wieder.\n\nWir haben überall Wassereimer im Ort, aber niemanden, der die Feuer löschen kann. Bitte helft uns!", progress = "Wir haben schon unser Zuhause am Kun-Lai verloren! Dieses hier dürfen wir nicht auch noch verlieren!", completion = "Ich wünschte, Ihr würdet damit aufhören, auch die Eimer ins Feuer zu schmeißen... das Wasser an sich würde schon ausreichen.\n\nAber ganz im Ernst, was für eine Erleichterung, dass Ihr hier seid, um zu helfen. Ich danke Euch.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30289] = {title = "Befreiung der gestohlenen Seelen", objective = "Befreit 6 besessene Wachen, indem Ihr die Mogu tötet, die deren Gedanken steuern.", description = "Mogu stehlen Seelen von Leuten! Lassen sie böse Dinge tun.\n\nAber nicht die Leute töten, sondern die Mogu. Dann vergessen die Leute die Verstandklauerei der Mogu und machen keine bösen Dinge mehr. Ihr solltet den Leuten helfen. So wie Rook.", progress = nil, completion = "Viele Dorfbewohner jetzt drinnen und in Sicherheit. Ihr habt gute Arbeit gemacht.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30290] = {title = "Steingebundene Mörder", objective = "Tötet 8 steingebundene Qilen.", description = "Mogusteinhundkreaturen jagen Dorfbewohner und tun ihnen weh. Rook wollte sie zerschmettern. Aber sie sind zu schnell.\n\nKönnt Ihr helfen und auch welche zerschmettern?", progress = nil, completion = "Ja! Ihr seid schneller als Rook. Gute Arbeit gemacht!\n\nDanke, guter Freund.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30291] = {title = "Betäubende Effizienz", objective = "Sammelt 12 betäubte Weißblütenkarpfen ein.", description = "Ich habe mit dem guten Tantan hier gesprochen... Wieder und wieder... Und er besteht darauf, dass das Angeln eine erhebende Freizeitgestaltung darstelle. Und trotz meiner gebotenen Skepsis habe ich es noch einmal versucht. Aber da ich kein Freund davon bin, einen Stock in das Wasser zu halten und eine Ewigkeit zu warten, habe ich mich an einer etwas direkteren Methode versucht.\n\nWürdet Ihr vielleicht so liebenswürdig sein und alle Fische einsammeln, die zwar mit dem Bauch nach oben im Wasser treiben, aber gleichwohl vollkommen intakt sind?", progress = "Ein weiterer Vorteil meiner Methode ist der Umstand, dass sie schon gekocht sind! Das nenne ich Effizienz in Reinkultur!", completion = "Wundervoll! Eure Einsammelfähigkeiten sind wirklich beachtlich.\n\nUnd ich bin auch dankbar dafür, dass Ihr Euch nicht zu schade wart, Euch Eure schicke Rüstung nass zu machen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30292] = {title = "Böses Erwachen", objective = "Tötet 8 besessene Fleischfresser der Bleichklingen.", description = "Die Mogu haben die Kontrolle über die Seelen der Saurok am See im Westen übernommen und hetzen sie gegen uns auf! Allerdings waren die Saurok schon vorher unsere Feinde. Ich weiß also nicht, ob sie das Ganze so besonders gut durchdacht haben...\n\nAuf jeden Fall ist ja Anji mehr die Kämpferin von uns beiden - und ich mehr der Liebhaber. Ich suche also jemanden, der die Waffen schwingt, Zaubersprüche loslässt und Kriegsgeheul ausstößt und so. Mit anderen Worten: Könntet Ihr ein paar Saurok für mich töten?", progress = nil, completion = "Ihr riecht nach Saurok und Mogu. Keine allzu schöne Kombination, mein Bester. Aber es lässt darauf schließen, dass Ihr die Aufgabe erledigt habt. Vielen Dank also.\n\nVielleicht treffen wir uns ja bald mal wieder - unter geruchlich besseren Bedingungen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30293] = {title = "In der Hand des Feindes", objective = "Setzt 8 besessenen Weißblütenverteidigern zu, bis sie von der Gedankenkontrolle der Mogu befreit sind.", description = "Die Geistbeuger der Shao-Tien haben die Kontrolle über den Verstand unserer Verteidiger am Weißblütensee im Westen übernommen. Ich möchte, dass Ihr Euch dorthin begebt und die Mogu tötet, die unsere Verteidiger kontrollieren. Aber unsere Leute dürfen nicht zu Schaden kommen! Wenn die Feinde getötet werden, werden auch die Geister der Verteidiger wieder befreit.\n\nIhr solltet Euch beeilen, denn Anji könnte auf die Idee kommen, sich auch dort einzufinden und zu helfen. Aber ihre Fähigkeit, sich in der Hitze des Kampfs zurückzuhalten, gehört nicht zu den Qualitäten, aufgrund derer ich sie geheiratet habe.", progress = nil, completion = "Heute wird Euch ganz sicher mehr als nur ein Pandaren für Eure Hilfe dankbar sein.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30294] = {title = "Kleiner Trost", objective = "Lest den Ritus der Befreiung 6 gefallenen Verteidigern des Goldenen Lotus vor.Die Geistbeuger am Weißblütensee berauben die Toten ihrer Seelen, um sie irgendwelchen fürchterlichen Qualen zu unterziehen.\n\nIch habe auf dieser Schriftrolle einen Ritus niedergeschrieben, der die Seelen von den Körpern befreit und sie auf den richtigen Weg geleitet. Wohin dann ihre Reise führt und was mit ihnen dann geschieht, weiß ich nicht, aber wenigstens sind sie so in Sicherheit vor den grausamen Mogu.\n\nLest diesen Ritus bei jedem Gefallenen, den Ihr findet. Wir werden ihre Leichen dann später bergen.Ihr bekommt:\n\n", description = "Die Geistbeuger am Weißblütensee berauben die Toten ihrer Seelen, um sie irgendwelchen fürchterlichen Qualen zu unterziehen.\n\nIch habe auf dieser Schriftrolle einen Ritus niedergeschrieben, der die Seelen von den Körpern befreit und sie auf den richtigen Weg geleitet. Wohin dann ihre Reise führt und was mit ihnen dann geschieht, weiß ich nicht, aber wenigstens sind sie so in Sicherheit vor den grausamen Mogu.\n\nLest diesen Ritus bei jedem Gefallenen, den Ihr findet. Wir werden ihre Leichen dann später bergen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][30295] = {title = "Turn-in Quest Test Case", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30296] = {title = "Gaohun der Seelenschnitter", objective = "Tötet Gaohun den Seelenschnitter.", description = "Großer Moguanführer ist da! Gleich hinter dem Dorf. Wenn wir großen Moguanführer töten können, Leven wird stolz auf uns sein!\n\nIhr habt Rook schon gut geholfen. Vielleicht Ihr helft mir noch mal? Bitte?", progress = nil, completion = "Anführer weg. Leute sicher. Rook hat Dorf gerettet. Guter Freund hat auch Dorf gerettet. Rook sagt danke!", rewards = "Ihr bekommt:\n\nSchätze des TalsTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30297] = {title = "Baolai der Verbrenner", objective = "Tötet Baolai den Verbrenner.", description = "Großer Moguanführer ist da! Gleich hinter dem Dorf. Wenn wir großen Moguanführer töten können, Leven wird stolz auf uns sein!\n\nIhr habt Rook schon gut geholfen. Vielleicht Ihr helft mir noch mal? Bitte?", progress = nil, completion = "Anführer weg. Leute sicher. Rook hat Dorf gerettet. Guter Freund hat auch Dorf gerettet. Rook sagt danke!", rewards = "Ihr bekommt:\n\nSchätze des TalsTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30298] = {title = "Die Ruinen in Blut tränken", objective = "Tötet 8 Mogu in den Guo-Lai-Ruinen.", description = "Die Mogu denken, sie können diese Ruinen ungeschoren übernehmen. Wir wollen ihnen zeigen, dass sie sich irren.", progress = nil, completion = "Ihre Stellung in diesen Ruinen wird keinen Bestand haben.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30299] = {title = "Kein Stein auf dem anderen lassen", objective = "Zerstört 6 Mogustatuen.", description = "Die Mogu haben Seelen mit Gewalt in alte Statuen verpflanzt, um sie zum Leben zu erwecken, zu kontrollieren und sie gegen uns einzusetzen.\n\nDiese gebundenen Geister können nur befreit werden, indem man ihre Behältnisse zerstört.", progress = nil, completion = "Nur dank Eurer Mühen können wir der Situation hier standhalten. Ich danke Euch vielmals für Eure Hilfe, mein Freund.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30300] = {title = "Schlüssel zum Erfolg", objective = "Findet den Shao-Tien-Käfigschlüssel und befreit 6 Gefangene des Goldenen Lotus.", description = "Die Mogu haben Gefangene genommen. Sie werden sie foltern oder ihnen noch schlimmeres Leid zufügen.\n\nBitte tut alles dafür, sie aus ihren Käfigen zu befreien.", progress = "Ich wäre lieber tot als ein Gefangener der Mogu zu sein. Sie sind äußerst grausam zu ihren Gefangenen.", completion = "Viele der von Euch befreiten Gefangenen sind jetzt hier im Lager, um sich zu erholen. Ihre - und meine - Dankbarkeit ist Euch gewiss.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30301] = {title = "Ein warmer Willkommensgruß", objective = "Verbrennt 6 Moguzelte in den Guo-Lai-Ruinen.", description = "Die Zelte niederzubrennen, in denen sie schlafen, sollte ihnen eine deutliche Botschaft sein.\n\nDurchkämmt die Ruinen und zerstört jedes einzelne ihrer Zelte.", progress = nil, completion = "Der Rauch in der Ferne zeugt von Eurem Erfolg. Gute Arbeit.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30302] = {title = "Die Imperion-Bedrohung", objective = "Tötet den Shao-Tien-Imperion.", description = "Die Späher haben gesehen, dass ein Shao-Tien-Imperion die Guo-Lai-Hallen betreten hat. Ich brauche jemanden, bei dem ich mich darauf verlassen kann, dass dieser Anführer die Hallen nicht wieder lebend verlässt.\n\nUnd ich denke, Ihr habt genau die richtigen Qualitäten für diese Aufgabe, <Klasse>.", progress = "Die Mogu haben wiederholt Gruppen ihrer stärkeren Krieger in diese Kammern geschickt. Da drinnen ist definitiv etwas, das sie haben wollen.", completion = "Ihr habt mich nicht hängen lassen. Ich werde das nicht vergessen.", rewards = "Ihr bekommt:\n\nSchätze des TalsTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30303] = {title = "NOT USED", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30304] = {title = "Hart wie ein Stein", objective = "Zerstört 10 Mogustatuen.", description = "Hey! Wisst Ihr, was das Beste war, das mir heute Morgen passiert ist?\n\nIch bin mit Anji in den Ruinen spazieren gegangen und hatte meinen Blick auf den Boden gerichtet, um nicht über einen dieser ekligen Spinnensäcke zu stolpern. Und dann ist auf einmal eine der Statuen zu Leben erwacht und hat versucht, mich in Grund und Boden zu stampfen!\n\nAnji hat sie dann aber selbst in Grund und Boden gestampft. Aber das langt mir noch nicht. Ich glaube, Ihr solltet da raus gehen und alle Statuen zerschmettern - ganz gleich ob sie am Leben sind oder nicht. Das ist die einzige Möglichkeit, für absolute Sicherheit zu sorgen.", progress = nil, completion = "Ich bin Euch für Eure Ruinenzerstörungsaktion aufrichtig dankbar, mein Bester.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30305] = {title = "Er weiß, was er tut", objective = "Lockt 8 Feinde in Hees Giftfallen.", description = "Ihr kennt Hee Samtfuß? Komischer Kerl, redet nicht viel. Stellt überall in den Ruinen Fallen auf für die Mogu. Sagte, dass Rook die Mogu nur in die Fallen locken muss. Aber weiß nicht wie.\n\nVielleicht könnt Ihr das machen? Fallen finden und die bösen Jungs reinlocken? Aber bitte Hee nichts davon erzählen, ja?", progress = "Ihr macht doch diese Fallensache für Rook, ja? Bitte?", completion = "Ihr seid wirklich guter Freund. Rook mag Euch. Danke, guter Freund!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30306] = {title = "Der Kampfring", objective = "Besiegt 20 Shado-Pan-Auszubildende im Kampfring.", description = "Wir haben ein paar neue Auszubildende, die Euch zwar nicht einzeln, aber vielleicht als Gruppe gefährlich werden könnten. Und wenn nicht, erfahren sie eben eine Lektion in Demut.\n\nSteigt in den Ring, wenn Ihr bereit seid. Und macht es ihnen nicht zu leicht.", progress = "Steigt in den Ring. Zeigt ihnen, wie ein echter <Klasse> kämpft.", completion = "Sehr beeindruckend. Die anderen scheinen noch viel lernen zu müssen. Aber dafür werde ich schon sorgen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30307] = {title = "Die Ewige Wacht", objective = "Tötet 8 Mogu der Shao-Tien auf der Goldenen Terrasse.", description = "Gut, Euch an unserer Seite zu wissen, <Klasse>. Wenn Ihr in den Kampf eintreten wollt, könnte ich mehr Kämpfer oben bei der goldenen Treppe gebrauchen, um die Mogu auszuschalten, die dort eine Basis errichten wollen.\n\nKann ich auf Euch zählen?", progress = nil, completion = "Wir werden diese Linie halten. Egal, wie lange ihr Ansturm dauert - wir werden die Linie halten.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30308] = {title = "Steinharte Qilen", objective = "Tötet 6 Granitqilen.", description = "Leven sagt immer, dass nur tote Qilen gute Qilen seien. Und ich würde ihm zustimmen. Seid Ihr hier, um uns zu helfen?", progress = nil, completion = "Weniger von diesen Bestien auf dem Schlachtfeld versüßen mir immer ein bisschen den Tag. Ich danke Euch.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30309] = {title = "In Stein gemeißelt", objective = "Zerstört 6 Mogueffigien.", description = "Die Mogu haben heute ihre eitlen Steineffigien auf das Schlachtfeld geschickt. Sie erwecken sie oben auf der Goldenen Treppe zum Leben.\n\nJe größer sie sind, desto härter müssen wir sie treffen. Seid Ihr dabei?", progress = nil, completion = "Auf dem Schlachtfeld ist heute eine zufriedenstellende Menge Geröll zu sehen. Ein Zeichen Eurer guten Arbeit.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30310] = {title = "Giganten der Lüfte", objective = "Tötet 3 bezwungene Schlangen.", description = "Die Mogu haben den Willen der Himmelsschlangen gebrochen und sie gegen uns eingesetzt.\n\nDie Verteidiger haben ihnen nicht viel entgegenzusetzen, aber Ihr vielleicht schon. Begebt Euch in Richtung Nordwesten, zur Goldenen Treppe, und wischt sie vom Himmel.", progress = nil, completion = "Was für ein Kampf! Ich glaube, Eure Vorstellung hat sogar die Moral der Truppe etwas gehoben.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30311] = {title = "Gehobene Standarte", objective = "Richtet 6 Standarten des Goldenen Lotus wieder auf.", description = "Meiner Meinung nach ist die vornehmste Qualität einer Kampfstandarte ihre Eigenschaft, aufgerichtet zu stehen... und nicht zu brennen. Und genau aus diesem Grund bereitet mir unsere Standartensituation gerade Verdruss.\n\nWenn sich also <ein unbekannter/eine unbekannte:c> <Klasse> finden lassen könnte, die Standarten auf dem Schlachtfeld im Nordwesten wieder aufzurichten, wären ich und meine ungemein attraktive - wenngleich auch etwas herrische - Frau äußerst dankbar.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][30312] = {title = "Eine zweite Chance", objective = "Heilt 6 verwundete Verteidiger.", description = "Ein törichtes Kontingent hat versucht, durch den östlichen Pass eine Offensive auf die Goldene Treppe einzuleiten, doch sie wurden bombardiert. Die, die es zurückgeschafft haben, befinden sich in einem schlechten Zustand, und noch immer gibt es Verletzte draußen auf dem Feld.\n\nHier sind ein paar Verbände. Bringt die verwundeten Verteidiger mit ihrer Hilfe oder sonstigen Heilungsfähigkeiten, über die Ihr verfügen mögt, wieder auf die Beine.\n\nBitte beeilt Euch, denn es bleibt nicht viel Zeit.", progress = "Es gibt noch mehr Verwundete, um die sich jemand kümmern muss. Bitte helft ihnen, wenn Ihr könnt.", completion = "Die, die Ihr geheilt habt, sind sicher zurückgekehrt. Ich danke Euch, werter Freund. Von ganzem Herzen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30313] = {title = "Die Wandernden Nebel", objective = "Tötet 8 Nebelgänger.", description = "<Er schaut auf die tote Nebelkreatur zu seinen Füßen, dann zu Euch auf und zeigt dann in Richtung des Nebels, der den See umgibt. Offensichtlich möchte er, dass Ihr noch mehr dieser Nebelkreaturen ausfindig macht und tötet.>", progress = nil, completion = "&lt;Er klopft Euch anerkennend auf die Schulter und nickt dankbar.&gt;", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30314] = {title = "Die isolierte Bleichklinge", objective = "Tötet 8 Bleichklingen-Saurok.", description = "<Er schaut auf den toten Saurok zu seinen Füßen, dann zu Euch auf und zeigt dann in Richtung des Seeufers. Offensichtlich möchte er, dass Ihr noch mehr dieser Saurok ausfindig macht und tötet.>", progress = nil, completion = "&lt;Er lächelt Euch an und nickt dankbar.&gt;", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30315] = {title = "Normal Quest Test Case", objective = "Give me stuff.", description = "Yes?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30316] = {title = "Fernschuss", objective = "Bergt 12 verschossene Shado-Pan-Pfeile.", description = "Eine solch grausame Aufgabe würde ich jemanden mit Euren Fähigkeiten normalerweise nicht zumuten, <Klasse>. Aber da Ihr ohnehin auf dem Schlachtfeld bei der Goldenen Treppe sein werdet, könntet Ihr ein paar abgeschossene Pfeile für unsere Bogenschützen einsammeln?Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][30317] = {title = "Wasser, Wasser überall", objective = "Sprecht mit Wing Nga, um Euch einen Drachen zu leihen, und werft Wasser auf 35 staubige Stellen im Kernland ab.", description = "Wie würdet Ihr Euch gern nützlich machen?\n\nEs ist ganz schön trocken gewesen in der letzten Zeit. Ich brauche jemanden, der die Felder im Kernland wässert. Aber hört gut zu: Ihr müsst ALLE Felder wässern.\n\nDie Flugmeisterin Wing Nga dort auf der anderen Seite des Weges bewahrt einige Drachen für mich auf. Schnappt Euch einen davon und werft dann Wasser überall dort ab, wo es trocken und staubig aussieht.", progress = nil, completion = "Hmpf! Ich habe schon auf den ersten Blick erkannt, dass Ihr ein guter Wässerer seid. Ihr habt gute Arme zum Wässern.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30318] = {title = "Hühnerjagd", objective = "Sammelt Hügelprankes Hühner ein, bis Ihr seine Zuchthenne findet.", description = "Hallo Ihr da! <Name>, stimmt's? Ich habe ein Problem, bei dem mir jemand helfen sollte, dessen Beine besser sind als die meinen.\n\nMein preisgekröntes Huhn ist abgehauen! Jetzt ist es draußen und treibt sich mit anderen Hennen, Wildvögeln und... <schluck> Hähnen mit schlimmen Absichten herum.\n\nMein Hof befindet sich westlich von hier, südlich der Himmelsweite. Könntet Ihr es für mich aufspüren und zurückbringen?", progress = "Ich schwöre, das hat sie zum ersten Mal gemacht.", completion = "Ihr habt sie gefunden! Ihr habt ein Auge für Federvieh.\n\nIch werde sie fürs Erste festhalten. Keine Sorge, später erhält sie dann ihre Strafe.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30319] = {title = "Probleme mit Schädlingen", objective = "Redet mit Wika-Wika, und stampft dann auf 25 Schwarznasenmurmeltiere.", description = "Einer meiner Landarbeiter, Wika-Wika, bewirtschaftet meinen Acker ganz im Westen. Ich weiß, dass er Probleme mit Schädlingen hat.\n\nEr hat zwar viel Schädlingsbekämpfungsmittel, das er auf die Insekten sprühen kann, aber ich fürchte, dass er mit den Murmeltieren nicht zurechtkommt.\n\nKönnt Ihr ihm vielleicht helfen? Bei den ganzen wilden Ho-zen und den Angriffen durch Shed-Ling kann ich es mir nicht erlauben, auch noch wegen herkömmlichen einfachen Schädlingen Ernte zu verlieren.", progress = nil, completion = "Sehr schön. Die Sache wäre erledigt. Gut gemacht, &lt;Volk&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nPest Problems: Training Complete\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30320] = {title = "Seelenbefreiung", objective = "Dringt in die Geistervortexe ein und befreit 15 Pandarenseelen.", description = "Mir ist einer der Dolche der Geistfetzer der Shao-Tien in die Hände gefallen. Er strahlt eine mächtige Magie aus. Man hat mir gesagt, dass man damit in ihre Geistervortexe eindringen könne.\n\nDie Mogu verwenden sie, um damit Seelen zu besiegen und ihren Willen zu binden. Aber ich hoffe, dass Ihr damit die Seelen auch befreien könnt.\n\nDringt in alle Geistervortexe ein, die Ihr auf der Goldenen Treppe finden könnt, und befreit alle gefangenen Seelen, denen Ihr begegnet.", progress = "Die Mogu sind in der Lage, Pandarenseelen in tote Objekte zu verpflanzen und sie ihrem Willen zu unterwerfen. Aber die Seelen sehnen sich nach Freiheit. Vielleicht ist dies das Werkzeug, das wir benötigen, um ihnen die Freiheit zu schenken.", completion = "Sehr gut! Ich werde diesen Dolch gut verwahren. Vielleicht erhalten wir wieder einmal die Möglichkeit, ihn zu verwenden.\n\nIch danke Euch vielmals. Ihr seid mit einem gütigen Herzen gesegnet.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30321] = {title = "Der zweite Unkrautkrieg", objective = "Sprecht mit Gai Lan und vernichtet dann 100 Exemplare Unkraut auf seinem Hof. Das Unkraut könnt Ihr auch vom Rücken eines Reittieres aus jäten.", description = "Haaaallöchen... Kennt Ihr den Kerl drüb'n auf'm Hof, der... der *hicks*... das Unkrautproblem hat? Gai Lan heißter, glaub' ich. Ich mag den Kerl, echt.\n\nEgaaaal, er meinte, dass wenn ich *hicks* 'nen Abenteurer zum Herausreiß'n von Unkraut schicken könnt', dass er mir Bier schicken würde.\n\nIst wahrscheinlich nich' viel, nur 'n bisschen Unkraut halt.\n\n*hicks*", progress = nil, completion = "Danke, Heeerr *hicks* &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWeed War II: Training Complete\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30322] = {title = "Geld regiert die Welt", objective = "Besorgt Gewürzmeister Jin Jaos Bezahlung, Händler Jambeezis Bezahlung, Gastwirtin Lei Lans Bezahlung und Lolo Lios Bezahlung.", description = "Ich arbeite gerne auf dem Markt, aber etwas daran gefällt mir nicht: das Eintreiben von Schulden.\n\nDie meisten Schulden von Pandaren sind zwar auf Faulheit zurückzuführen, aber es gibt auch ein paar Leute in der Stadt, die einfach nicht zahlen wollen oder zu arm sind.\n\nEinige hier in der Stadt schulden mir Geld. Könntet Ihr mit ihnen reden und sie daran erinnern, was sie mir schulden?", progress = "Wisst Ihr, es ist schön, einen Schläg… ähm, ich meine natürlich Helfer... wie Euch zu haben, <Klasse>.", completion = "Ich bin froh, dass diese unangenehme Sache erledigt ist. Es hat Euch doch niemand Ärger bereitet, oder?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30323] = {title = "Die tragen das noch nicht einmal", objective = "Besorgt einen gestohlenen Reif, einen geplünderten Ring und ein stibitztes Armband.", description = "Vor ein paar Wochen hat eine Gruppe dieser wilden Sprungschweif-Shed-Ling meine Schließkassette aufgebrochen und Schmuck entwendet. Seitdem habe ich zwar ein paar Stücke wieder gefunden, sie haben aber immer noch einen Großteil meiner Kollektion.\n\nWenn Ihr zu den Sprungschweifhöhlen geht, bei den Klippen im Norden, solltet Ihr die Augen nach ihnen offen halten. Ich hätte gerne meinen Schmuck zurück.", progress = "Ist es denn zu glauben, wie verantwortungslos und unreif diese Shed-Ling sind? Wissen die nicht, wie viel dieser Schmuck KOSTET?", completion = "Oh, &lt;Name&gt;! Ich würde Euch hier auf der Stelle küssen, wärt Ihr nicht... nun, mit Shed-Ling-Staub bedeckt.\n\nIch danke Euch!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30324] = {title = "Nicht vor Chi-Chis Haustür", objective = "Tötet 8 Mitglieder des Kunzen-Stammes in Kunzen.", description = "Nicht alle Ho-zen sind gleich. Chi-Chi gehörte zu Wald-Ho-zen... kamen aus Jadewald. Sehr umgänglich.\n\nDie Kunzen-Eindringlinge... sie kommen aus Bergen weit im Norden. Bei Weitem nicht so nett wie Chi-Chi.\n\nSie kommen in unser grünes Land, stehlen alles, lassen großes Durcheinander zurück.\n\nChi-Chi will sie abmurksen. Hilfste mir?", progress = nil, completion = "Toll! Chi-Chi wusste, dass du das schafft!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30325] = {title = "Worauf es ankommt", objective = "Werft 8 Kunzen-Ritualkerzen, tretet viermal auf brennende Glut und tötet 1 Kunzen-Ritualist.", description = "Ich habe diese Kunzen-Ho-zen beobachtet, und mir ist dabei ein Muster aufgefallen. Immer kurz vor einem Angriff führen sie seltsame, barbarische Rituale um ihr Totem herum durch.\n\nWenn wir dieses Ritual stören, halten wir nicht nur künftige Angriffe auf, sondern können ihrer Moral einen Schlag versetzen! Geht also rein, mischt sie ordentlich auf, und sorgt für so viel Chaos wie möglich!", progress = nil, completion = "Hah! Das aufzuräumen wird sie mehrere Tage beschäftigen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30326] = {title = "Der Legenden-Häuptling der Kunzen", objective = "Besorgt ein Legendenbuch der Kunzen von einem Kunzen-Legendenhäuptling.", description = "Ich habe Leute über die Ho-zen reden gehört, als wären sie einfach nur ein Haufen tumber Idioten... Aber das stimmt nicht! Sie haben auch ein Gehirn - allerdings nutzen sie es nicht so oft.\n\nIch habe erfahren, dass der Kunzen-Stamm zwei Häuptlinge hat - einer ist für Kämpfe zuständig, der andere für Geschichten, Sagen und Erzählungen.\n\nMich würden ihre Geschichten ja wirklich interessieren...", progress = "Ich wette, die Ho-zen-Legenden unterscheiden sich kaum von unseren.", completion = "Oh! Seht Euch das an! Das ist...\n\n&lt;Fischi blättert durch die Seiten und ihr Gesicht verzieht sich.&gt;\n\nÄhm, ich glaube, das ist ein schmutziges Bild. Aber der Rest ist sehr interessant! Ich liebe es, die Denkweise anderer Kreaturen kennen zu lernen. Danke, &lt;Name&gt;!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30327] = {title = "Seil in Flammen", objective = "Verbrennt 6 Kunzen-Seile.", description = "Ich, ähm... nun...\n\nAch, nicht so wichtig. Das war eine dumme Idee.\n\nIch dachte mir nur, dass es ja vielleicht möglich wäre, die Kunzen von einem Angriff abzuhalten, ohne jemanden, nun ja... TÖTEN zu müssen. Mir sind ein paar Seile an der Bergseite aufgefallen. Ich glaube, sie klettern daran zu unseren Höfen hinab und...\n\nNein, vergesst es. Das war ein blöder Gedanke.", progress = nil, completion = "&lt;Ellas Gesicht erhellt sich.&gt;\n\nIhr habt es getan? Für mich? Oh, habt vielen Dank - danke, danke, danke!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30328] = {title = "Das tausend Jahre alte Klößchen", objective = "Besorgt 7 Gefäße konserviertes Gemüse.", description = "Eines meiner beliebtesten Rezepte ist das tausend Jahre alte Klößchen, das mit konserviertem Gemüse gefüllt ist.\n\nIch lasse normalerweise das Gemüse in einem Loch unter meinem Haus gären, aber als ich diesen Morgen danach sehen wollte, war es weg!\n\nDas waren bestimmt diese diebischen Shed-Ling.\n\nBringt mir das Gemüse zurück, und Ihr dürft mir beim Kochen helfen!", progress = "Versucht nicht, eines der Gefäße zu öffnen. Falls Ihr es doch macht, solltet Ihr nicht allzu dicht mit der Nase rangehen.", completion = "Nun, mein Schüler, passt gut auf. Ich zeige Euch jetzt das Geheimnis des tausend Jahre alten Klößchens...", rewards = "Ihr bekommt:\n\nEisentatzmarkeTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30329] = {title = "Glühmagenpfefferschoten", objective = "Besorgt 4 Glühmagenpfefferschoten.", description = "Einige Pandaren hier mögen unglaublich scharf gewürzte Gerichte. Leider sind meine Möglichkeiten, solche Gewürze zu besorgen, begrenzt.\n\nDie Kunzen-Ho-zen in den Bergen im Westen haben oft Glühmagenpfefferschoten dabei. Ein paar davon würden ein paar Tage reichen.\n\nWürdet Ihr vielleicht einige für mich besorgen? Ihr solltet vielleicht Handschuhe tragen, wenn Ihr sie anfasst.", progress = "Legt die Schoten einfach nur auf das Schneidebrett hier. Ich will sie lieber nicht selbst anfassen.", completion = "Ich kann nicht verstehen, wie die Ho-zen diese Dinger bei sich tragen können... geschweige denn essen.", rewards = "Ihr bekommt:\n\nEisentatzmarkeTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30330] = {title = "Trüffelei", objective = "Besorgt 8 Dimmlichttrüffeln und pflanzt 8 Dimmlichttrüffelsporen.", description = "Ich mag es, mit Trüffeln zu backen... wenn ich welche finde. Sie wachsen nur oben auf der Himmelsweite, und das in ganz, ganz geringen Mengen.\n\nSie sind eine fantastische Zutat, aber wir dürfen nicht zu viel von ihnen ernten. Aus diesem Grund müssen wir das ersetzen, was wir genommen haben. Holt mir eine Handvoll ausgewachsener Trüffeln und pflanzt dafür einige dieser Sporen.", progress = "Wir brauchen nicht viele Trüffeln. Die sind nur für den Geschmack.", completion = "Die werden reichen.\n\nUnd nun, &lt;Name&gt;... kommt näher. Ich werde Euch etwas über die Backkunst lehren...", rewards = "Ihr bekommt:\n\nEisentatzmarkeTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30331] = {title = "Spitzenküche", objective = "Bereitet 20 Schüsseln Mushanschwanzeintopf über dem Lagerfeuer in Kunzen zu.", description = "Habt Ihr jemals Mushanschwanzeintopf probiert? Wenn ja, dann war er höchstwahrscheinlich zäh und geschmacklos. Ihr müsst wissen, dass es einen Trick gibt, um den perfekten Mushanschwanzeintopf zuzubereiten: Man muss ihn auf großer Höhe kochen.\n\nIch habe bereits die Zutaten gesammelt. Nehmt diesen Topf mit nach Kunzen oben in den Bergen im Westen und bereitet den Eintopf über ihrem Lagerfeuer zu.", progress = "Früher ging ich jeden Tag in die Berge, nur um diesen Eintopf zu kochen.\n\nDamals war ich noch jünger.", completion = "Das ist fantastisch! Vom Kochen versteht Ihr wirklich etwas, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\nEisentatzmarkeTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30332] = {title = "Fettiges Ziegensteak", objective = "Besorgt 4 fettige Ziegensteaks.", description = "Wisst Ihr was? Ich glaube, ich werde heute ein Ziegensteak grillen.\n\nNein, nicht von den mickrigen Zottelhörnern aus dieser Gegend. Die haben bei weitem nicht genug Fett auf den Rippen.\n\n<Der Koch tätschelt seinen riesigen Bauch.>\n\nGlaubt Ihr, ich wäre mit mageren Zieglein so stattlich geworden?\n\nNun, die Zottelhörner oben auf der Himmelsweite im Westen... die sind genau richtig.", progress = "<Der Koch bereitet konzentriert Gewürze und Soßen für die Steaks vor, die er erwartet.>", completion = "Eine gute Auswahl an Steaks, &lt;Name&gt;. Ihr hättet eine Zukunft als Metzger. Wahrscheinlich seid Ihr als &lt;Klasse&gt; jedoch besser.", rewards = "Ihr bekommt:\n\nEisentatzmarkeTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30333] = {title = "Das geringere Übel", objective = "Tötet die Baumutter der Sprungschweife.", description = "Wie jede von der Landwirtschaft lebende Gemeinde haben auch wir ab und zu Ärger mit den Shed-Ling.\n\nDie stärksten Sprungschweif-Shed-Ling leben oben in den Klippen im Norden. Sie kommen nur herunter, wenn ihnen das Gemüse ausgeht.\n\nIch hatte, ehrlich gesagt, schon einmal mit Shed-Ling zu tun. Die sind nichts weiter als eine Plage, die unter Kontrolle gehalten werden muss. Und hierfür gibt es nichts effektiveres, als ihre Baumutter zu töten. So einfach ist das.", progress = nil, completion = "So, das wäre erledigt. Und jetzt konzentrieren wir uns zur Abwechslung mal wieder auf die Landwirtschaft.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30334] = {title = "Stehlen ist böse… Zurückstehlen ist in Ordnung", objective = "Stehlt 16 Exemplare gestohlenes Gemüse zurück.", description = "Die Ho-zen aus den Bergen im Westen stehlen immer noch Gemüse von den anderen Bauern. Da ich so nahe bei Halbhügel lebe, bleibe ich von Angriffen der Ho-zen meistens verschont, aber meine Freunde haben nicht so viel Glück.\n\nMeiner Meinung nach stehlen die viel mehr, als sie überhaupt essen können. Wenn Ihr unversehrtes Gemüse in diesen Bergen findet... stehlt es zurück!", progress = "Habt Ihr es?", completion = "Danke! Ich werde dafür sorgen, dass es an die anderen Bauern verteilt wird.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30335] = {title = "Der Plünderung Einhalt gebieten", objective = "Tötet 12 Kunzen-Ho-zen.", description = "Die Kunzen-Ho-zen oben in den Bergen im Westen spielen verrückt, zünden ihre Feuer an und singen lautstark. Meinen Erfahrungen nach bedeutet das, dass eine Plünderungsaktion bevorsteht.\n\nWir können zwar nicht viel tun, um sie aufzuhalten, aber wir können zumindest einige von ihnen dezimieren, bevor sie angreifen.", progress = "Der Angriff kann jeden Moment beginnen. Wir müssen vorbereitet sein.", completion = "Sie werden zwar angreifen, aber mein Hof - und die Höfe meiner Freunde - sollten nicht gefährdet sein.\n\nJedenfalls nicht, wenn wir es verhindern können. Stimmt's, &lt;Name&gt;?", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30336] = {title = "Der Kunzen-Jägerhäuptling", objective = "Tötet den Kunzen-Jägerhäuptling.", description = "Soviel ich weiß, haben die Kunzen-Ho-zen zwei Häuptlinge. Einer ist harmlos - er kümmert sich um Tränke, Medizin und Sagen. Der andere ist für die Kunzen-Jäger zuständig - und das Einzige, was die in letzter Zeit gejagt haben, ist unsere Ernte.\n\nDer Jägerhäuptling ist ein Problem, das wir angehen müssen. Die Bauern hier wären Euch dankbar, wenn Ihr Euch um ihn \"kümmern\" könntet.", progress = nil, completion = "Die Ho-zen werden heute Nacht bestimmt ein großes Ritual abhalten, um einen neuen Jägerhäuptling zu küren.\n\nIch bin einfach nur froh, dass wir Bauern uns in der Zwischenzeit erholen können.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30337] = {title = "Affenartige Sabotage", objective = "Verwendet das Fass mit Feuerwerkskörpern neben dem Stapel gestohlener Waffen, dem Stapel gestohlener Werkzeuge, dem Vorrat gestohlenen Biers und dem Haufen gestohlenen Getreides.", description = "Die Ho-zen bestehlen uns, und wir stehlen unsere Sachen wieder zurück. Das muss irgendwann einmal aufhören.\n\n<Bauer Yoon gibt Euch ein Fass mit Feuerwerkskörpern.>\n\nFindet einen Teil unserer gestohlenen Vorräte in ihrem Berglager im Westen, und legt diese Feuerwerkkörper daneben. Wenn die Explosionen losgehen, denken sie hoffentlich, dass unsere Vorräte gefährlich sind, und hören mit dem Stehlen ganz auf.\n\nEinen Versuch ist es doch wert, oder?", progress = nil, completion = "Hoffentlich hören sie jetzt mit dem Stehlen unserer Vorräte auf. Ich jedenfalls würde kein explosives Bier trinken wollen - oder mit einer Harke arbeiten, die gleich in die Luft fliegt.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30338] = {title = "Eine schwer wiegende Aufgabe", objective = "Bergt 8 Moguartefakte.", description = "Mir will beim besten Willen nicht einfallen, warum nur die Mogu all ihre Statuen und ihren anderen Tand da unten im See platziert haben sollten. Ich wette dort unten war nicht immer Wasser, aber im Falle von Regen scheint es mir dennoch ein äußerst unkomfortabler Ort zu sein.\n\nAber wer versteht schon die absonderlichen Absichten der Mogu...?\n\nWürde es Euch etwas ausmachen, dort runter zu tauchen und alles hochzuholen, was auch nur annähernd tragbar ist? Ich wäre Euch wirklich sehr dankbar dafür.", progress = "Habt Ihr ein oder zwei hübsche Artefakte für mich gefunden? Wenn es Euch gelingt, werde ich mich bei Euch mit einer fulminanten Umarmung bedanken!", completion = "Ihr erstaunt mich immer wieder! Ihr könnt nicht nur in dieser hübschen und wohl recht schweren Rüstung schwimmen, sondern auch noch ein halbes Dutzend güldener Waffen mit Euch herumschleppen! Von all Euren Fähigkeiten ist dies doch wohl die erstaunlichste, nicht wahr?\n\nIch danke Euch, Beherrscher der Binnengewässer.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30339] = {title = "Sich die Hände schmutzig machen", objective = "Sammelt 12 frische Weißblütenwürmer.", description = "Dieser See hier zählt zu den besten Fischgewässern in ganz Pandaria. Ich habe mir genug Bräu für den ganzen Tag mitgenommen, aber leider vergessen, Köder einzupacken.\n\nWer kann auch schon an alles denken?\n\nWenn Ihr mir ein paar Köder entlang der Küstenlinie einsammelt, werde ich an Euch denken, wenn ich meine Beute verkaufe. Oh, und das Bezahlen werde ich natürlich nicht vergessen. \n\nAlso, habt Ihr Interesse?", progress = "Einen ganzen Tag nur angeln! Und dazwischen einfach nichts tun!", completion = "Ihr macht Eurem Volk Ehre, indem Ihr mir einfachem Händler helft. Ich danke Euch.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30340] = {title = "Zwischen Tür und Angel", objective = "Sammelt 12 Weißblütenschilf.", description = "Ich wollte hier einen wundervollen Angeltag verbringen, aber ich habe meine Angelrute vergessen. Beim Angeln muss man ja an so vieles denken... Das kann sich ja niemand merken.\n\nDiese Schilfhalme am Ufer würden gute Angelruten abgeben. Wenn Ihr mir ein paar davon einsammelt, werde ich an Euch denken, wenn ich meine Beute verkaufe. Oh, und bezahlen werde ich Euch natürlich auch. \n\nAlso, habt Ihr Interesse?", progress = "Einen ganzen Tag nur angeln! Und dazwischen einfach nichts tun!", completion = "Ihr macht Eurem Volk Ehre, indem Ihr mir einfachem Händler helft. Ich danke Euch.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30341] = {title = "Unter Beobachtung", objective = "Tötet 8 Shao-Tien-Vermesser.", description = "<Er schaut auf den toten Mogu zu seinen Füßen, dann zu Euch auf und zeigt dann in Richtung des Seeufers. Offensichtlich möchte er, dass Ihr noch mehr dieser Moguspäher ausfindig macht und tötet.>", progress = "<Er starrt Euch ausdruckslos an.>", completion = "&lt;Er verbeugt sich dankbar vor Euch.&gt;", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30342] = {title = "Gierige Zähne, zarte Füßchen", objective = "Tötet 6 Stillwasserkrokilisken.", description = "Als ich mich wieder einmal meinem vergnüglichen Wassertreten gewidmet habe, ist einer dieser widerwärtigen Krokilisken aus dem Wasser aufgetaucht und hat versucht, mir in den Fuß zu beißen! Unverschämtheit! Ich habe mich entschieden, meine müden Füße fürs Erste vom Wasser fernzuhalten. Aber ich vermisse meine Leibesübungen im Wasser jetzt schon.\n\nWäret Ihr vielleicht so freundlich, einen oder sechs Krokilisken für mich zu töten? Und gewährt ihnen keine Gnade. Wer mich so fürchterlich erschrickt, verdient sie nämlich nicht.", progress = nil, completion = "Habt ihr gehört, meine lieben und wunderschönen Füße? Die Zeit des Leidens ist vorbei! Ich kann Euch wieder in das herrliche Nass eintauchen!\n\nOh, Ihr seid aber auch zu liebenswürdig! Vielleicht wollt Ihr mir ja eines Tages beim Wassertreten Gesellschaft leisten. Wir könnten dann über die alten Zeiten plaudern, als Ihr großzügigerweise diese Krokodile abgeschlachtet habt, um meine verängstigten und unschuldigen Füße zu schützen. Was war das doch nur für ein großartiger Tag...", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30343] = {title = "Abfackeln!", objective = "Platziert Pulverfässer in den Frachträumen aller sechs Schiffe.", description = "Ich bin Himmelshäscher Sturmgeheul, Kapitän des Luftschiffes Garroshs Faust und Kommandant dieser Operation.\n\nEure erste Aufgabe besteht darin, die 7. Flotte abzufackeln, während sie noch vor Anker liegt.\n\nKapitän Droks Marinesoldaten halten während der Operation Eures Teams die Stellung am Hafeneingang.\n\nPlatziert Pulverfässer in den Frachträumen aller Schiffe und formiert Euch dann am Hafeneingang neu, um Sprengmeister Zündlunte Bescheid zu geben. Er wird den Sprengstoff zünden und dem Luftschiff das Signal für den Weiterflug geben.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30344] = {title = "Die verlorene Dynastie", objective = "Besorgt 6 dynastische Tafeln.", description = "Ich frage mich, ob ich Euch mit noch einer Aufgabe belästigen könnte. Meine Tochter, die gute Kommandantin der Schildwachen Lyalia hier, verbietet mir, ins Feld zu ziehen.\n\nJeden Tag, den ich in dieser Oubliette gefangen war, war ich gezwungen, auf die Ruinen im Norden zu starren. Es reizt mich, sie zu erkunden.\n\nWenn wir dort sind, wo ich vermute, dass wir sind, könnten diese Ruinen der Schlüssel sein, den wir benötigen, um die sagenhaften Teiche der Jugend zu finden!\n\nBitte, <Klasse>! Geht zu diesen Ruinen und bergt alle Tafeln, die noch Schrift aufweisen.", progress = "Es ist eine Sache, die Verlorenen Dynastien zu erforschen. Es ist zweifellos etwas anderes, deren alte Ruinen zu besuchen.\n\nMir wird dabei schwindelig wie seit Jahrhunderten nicht mehr!", completion = "Oh! Fabelhaft! Fabelhaft!\n\nDer eine Ausflug von Euch hat meine Forschung weiter vorangebracht als zehn Jahre des Lesens in staubigen Folianten und zerfallenden Schriftrollen...\n\nUnd diese \"Mogu\", die Ihr gesehen habt. Ich habe auch in dieser Richtung geforscht und mit Kang darüber geredet.\n\nIch vermute jetzt, dass es sich bei ihnen um das Volk der Verlorenen Dynastien handelt, die mein Forschungsgebiet sind.\n\nNatürlich bedeutet das gleichzeitig, dass sie diejenigen sind, die einst die Teiche der Jugend kontrolliert haben.", rewards = "Ring der Teiche der JugendRing der TränenZahnreihenbandSiegel der verlorenen JahrhunderteSiegel des verbotenen DschungelsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30346] = {title = "Wo sind die Teiche?", objective = "Besorgt die Dojani-Befehle.", description = "Vielleicht wissen diese Mogu, wo die Teiche sich befinden.\n\nUnsere Späher haben berichtet, einen Kommandanten an der Südseite der Ruinen von Dojan gesichtet zu haben.\n\nTötet ihn und bringt jegliche Information mit, die er bei sich trägt. Sie sollten Euch zum Teich führen.", progress = "<Ihr spürt die Anwesenheit von Wissenshüter Vaeldrin, dann hört Ihr seine Stimme in Eurem Verstand.>\n\nHmm. Ich bin immer noch nicht sicher, was die Verweise auf \"Tortur\" in Bezug auf die Teiche der Jugend bedeuten sollen.", completion = "Gut gemacht, &lt;Name&gt;. Hmm, es sieht so aus, als ob die Mogu hier wären, um alte Relikte und Waffen aus ihrer vergessenen Dynastie zu sammeln. Das ist allerdings ein Problem, dessen wir uns später annehmen können.\n\nAh! Hier ist ein Verweis auf die Teiche der Jugend.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30347] = {title = "Die Teiche der Jugend", objective = "Besorgt ein wenig des Wassers der Jugend.", description = "Norden! Geht nach Norden zu den Teichen der Jugend. Holt etwas von dem Wasser, aber seid wachsam.\n\nDie Mogu betrachten sie als \"hochrangiges\" Ziel. Kang Dornstab wird sich dort mit Euch treffen, falls er Euch nicht schon erreicht hat.", progress = "Nichts gibt einem mehr Sinn für Dringlichkeit, als sterblich zu sein.", completion = "Ihr... Ihr habt die Teiche gefunden! Die Wasser existieren!\n\nAber etwas ist nicht richtig. Ich fühle gleiche Anteile Schatten und Licht in dieser Phiole wirbeln.", rewards = "Tuch der LaguneWasserfalltuchBaldachintuchGrünrückencapeBalsamtuchDer folgende Zauber wird auf euch gewirkt:\n\nKang Dornstab freigeben\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30348] = {title = "Unsterblichkeit?", objective = "Beobachtet Vaeldrin, während er das Wasser der Jugend probiert.", description = "Etwas ist... nicht richtig. Das Wasser fühlt sich seltsam an.\n\nAls wir hier angekommen sind, habe ich die Präsenz des Lichts gefühlt, stark und pulsierend, weit im Norden.\n\nAber dieses... dieses Wasser ist irgendwie mit einem Makel behaftet. Befleckt durch Mogumagie.\n\nIch glaube, es ist am besten, wenn ich nur einen Schluck probiere, dann sehen wir, was passiert.", progress = nil, completion = "Wa... was ist passiert? Das Wasser... es... es überträgt Leben nur. Es schafft kein neues Leben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30349] = {title = "Bedrohung aus Dojan", objective = "Tötet 6 Dojanieroberer, 8 Dojanispäher und 4 Dojanivollstrecker.", description = "Während Ihr bei den Ruinen wart und für meinen Vater Tafeln abgestaubt habt, habe ich fünf Späher an umherziehende Mogupatrouillen verloren.\n\nDiese Kreaturen haben offensichtlich nur geringes Interesse an Frieden und sind ungefähr ebenso vertrauenswürdig wie die Horde.\n\nSie sind jedoch zu zahlreich und wir zu schwach.\n\nGeht zu den Ruinen westlich von hier und dünnt die Reihen der Mogu aus. Jemanden wie Euch werden sie nicht erwarten, <Klasse>.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Noch ein paar solcher Missionen und wir müssen Euch vielleicht zu einer Ehrenschildwache machen.", rewards = "DornbuschmedaillonDornbuschhalsreifDornbuschhalsketteDornbuschanhängerDornbuschamulettDer folgende Zauber wird auf euch gewirkt:\n\nKang Dornstab freigeben\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30350] = {title = "Ekliger Gaumenschmaus", objective = "Sammelt 5 unversehrte Huscherdrüsen.", description = "Der verborgene Meister muss vielleicht warten. Seht Euch diese Leute an, $p.\n\nSie sind so DÜNN! Sie müssen ja am Verhungern sein.\n\nWisst Ihr, was wir brauchen? Eine große dampfende Schüssel Ekliger Gaumenschmaus.\n\nWenn Ihr zufällig in der Nähe eines Flusses seid, besorgt ein paar intakte Huscherdrüsen und ich werde eine Portion davon kochen.", progress = "Mama Dornstab hat immer gesagt, Ekliger Gaumenschmaus heilt jeden Hunger, auf die eine oder andere Weise.", completion = "Ha! Damit kann ich Eintopf machen, der so stark ist, dass er diese spindeldürren Elfen ruck, zuck auf die Beine bringt.", rewards = "Ihr bekommt:\n\nEkliger Gaumenschmaus"}
MultiLanguageQuestData['de'][30351] = {title = "Lotustee", objective = "Sammelt 20 Kaiserliche Lotusblätter.", description = "Die Mogu lieben ihre Gifte und Flüche. Mama Dornstab hat immer gesagt, dass Lotustee sämtliche Moguflüche heilen würde.\n\nIch habe ein paar kaiserliche Lotuspflanzen in der Nähe der Ruinen von Dojan gesehen. Wir sollten hingehen und ein paar der Blätter pflücken und griffbereit halten, für den Fall, dass die Mogu unruhig werden.\n\nIch bekomme dann zudem die Chance, meine Fäuste ein paar Mogufratzen vorzustellen.", progress = "Ich habe noch nie so viele Mogu gesehen. Sie waren immer schon ein Ärgernis, aber noch nie so schlimm.", completion = "So geht das! Ihr pflückt, ich prügle!", rewards = "Ihr bekommt:\n\nLotuswasser"}
MultiLanguageQuestData['de'][30352] = {title = "Kranich-Meisterschaft", objective = "Tötet 12 Karpfenjäger.", description = "Die Sache bei der Jagd auf Vögel ist die, dass man Munition braucht - und ich habe keine. Die Sache bei der Jagd mit Nesingwary ist, dass man beweisen muss, dass man in Abschüssen und Prahlerei nicht nachlässt.\n\nKeine Jagd, keine Prahlerei. Und ich mag Prahlerei, also ist dies eine schlechte Situation.\n\nKann ich Euch anheuern, ein paar Karpfenjäger für mich zu töten? Ihr findet sie rauf und runter am Fluss westlich von hier. Es sind ziemlich viele, also jagt nebenher ruhig ein wenig.", progress = nil, completion = "Fantastisch. Das Einzige, was diesen Jagdausflug noch unterhaltsamer machen würde, wäre ein Stuhl. Hier ist die Belohnung, die ich Euch versprochen habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30353] = {title = "Meisterlicher Profit", objective = "Besorgt 12 mit Tigerblut gefüllte Phiolen.", description = "Ein Wort: Tigerblut!\n\nDas wird sich besser verkaufen als damals Saronit auf dem Schwarzmarkt. Besonders, nachdem ich ein Gerücht über die tolle stärkende Wirkung und so verbreitet habe.\n\nUnd im Dschungel wimmelt es nur so von Tigern. Könnt Ihr ein paar mit Tigerblut gefüllte Phiolen für mich auftreiben? Ich werde Euch auch an der Gaunerei beteiligen.", progress = "Ich mag es, mit Nesingwary zu jagen und so, aber ihm geht es dabei ums Jagen. Mir geht es um den Profit, und er bezahlt uns nicht.", completion = "Großartig! Dieses Zeug wird mir drüben in Kalimdor eine Menge Geld verschaffen. Hier ist Euer Anteil.", rewards = "NayelihandschuheTodesrachenhandschuheTiefwildstulpenNarsonghandschuheAngkhalhandschützerFlussklingenhandschuheSarjunstulpenKorjanistulpenStulpen des DojaniIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30354] = {title = "Keine Schwester bleibt zurück", objective = "Rettet 8 Gefangene der Mogu.", description = "Wir haben die Ruinen südlich von hier durchsucht, als die Mogu aus dem Nichts über uns hergefallen sind.\n\nEin paar von uns konnten sich in dieses Lager zurückziehen, aber viele wurden gefangen genommen. Die Mogu haben auch einige der Horde aufgegriffen, die zufällig in der Gegend waren.\n\nBitte, $p, rettet so viele Schildwachen und Zivilisten der Pandaren, wie Ihr könnt.\n\nÜberlasst die Morgenjäger ihrem Schicksal.", progress = nil, completion = "Es gibt nur wenige von uns, und es ist eine große Erleichterung, solche Hilfe zu erfahren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30355] = {title = "Erneute Zurückeroberung", objective = "Beschafft 10 Moguartefakte.", description = "Mogu setzen KEINE arkane Magie ein.\n\nSie sind Schläger. Sie waren immer schon Schläger. Nur in den alten Geschichten über die von ihnen beherrschten Imperien haben sie sich einer Form der Magie bedient.\n\nAber diese Mogu verwenden arkane Portale und Zauber. Wir müssen sie aufhalten!\n\n$p, sucht nach Artefakten, die die Mogu benutzen, um ihre Magie damit zu wirken. Ich habe gesehen, wie sie diese Dinge stapelweise in der Nähe der Ruinen von Korja südlich von hier gesammelt haben.", progress = "Jedes Artefakt in unserem Besitz ist eine Waffe weniger in den Händen der Mogu.", completion = "Gut gemacht, &lt;Name&gt;. Ihr habt dem Kind das Schwert aus der Hand genommen.", rewards = "NayelimanschettenTodesrachenbindungenTiefwildarmschützerNarsongarmschienenAngkhalmanschettenFlussklingenarmwickelSarjunhandgelenksschützerKorjaniarmplattenArmschienen des DojaniIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30356] = {title = "Unterbrechung ihrer Nachschublinie", objective = "Tötet 8 Korjanieroberer.", description = "Die Mogueroberer verwenden Portale als Verbindung zum Kun-Lai-Gipfel. Sie schaffen Verstärkung und Vorräte dorthin.\n\nDarüber hinaus schicken sie ihre Gefangenen durch diese Portale.\n\nGeht zu den Ruinen von Korja und vernichtet so viele dieser Korjanieroberer, wie Ihr finden könnt.", progress = nil, completion = "Ihr habt uns wertvollen Raum zum Atmen verschafft, sodass wir unsere Wunden lecken und einen Gegenangriff vorbereiten können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30357] = {title = "Der Steinpflug-Konvoi", objective = "Setzt kaiserliche Lotusumschläge bei 7 Gesandten von Steinpflug ein.", description = "Helft mir, $p. Diese armen Pandaren bedürfen der Heilung und meine Kräfte sind geschwächt.\n\nIch habe allerdings einen alten Folianten in meiner Sammlung gefunden, mit dem ich die Kräuter, die Ihr zuvor gesammelt hattet, zu Heilumschlägen verarbeiten konnte.\n\nVersorgt damit die verwundeten Pandaren, dann sollten sie bald wieder auf die Beine kommen.", progress = nil, completion = "Es ist lange her, seit ich meine Ärmel hochgekrempelt und den Bedürftigen geholfen habe. In meiner Begierde nach Unsterblichkeit hatte ich vergessen, warum ich Priester geworden bin.\n\nDanke, dass Ihr mich daran erinnert habt, dass es Gutes in dieser Welt gibt, für das es sich zu kämpfen lohnt, &lt;Name&gt;.", rewards = "Kaiserlicher LotusschalKaiserliches LotustuchKaiserliches LotuscapeKaiserliche LotusmantelungKaiserlicher LotusumhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30359] = {title = "Der Oberste Eroberer", objective = "Sucht Lyalia und tötet Bodenbrecher Brojai.", description = "Sie haben meine Tochter! Brojai... dieser Oberste Eroberer! Ich kann ihn ganz klar durch Lyalias Augen erkennen.\n\nDieses närrische Mädchen muss versucht haben, ihm Auge in Auge gegenüberzutreten.\n\nBitte, $p! Geht zu den Ruinen von Korja und versucht, sie zu befreien.\n\nIch werde mir Kang holen und versuchen, Brojai mit einer Ablenkung von den Ruinen wegzulocken.", progress = nil, completion = "Danke, dass Ihr meine Tochter gerächt habt. Ich bin allerdings nicht bereit, ihren Tod hinzunehmen.\n\nIch habe immer noch die Wasser der Jugend.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30360] = {title = "Warnung an Steinpflug", objective = "Reist nach Steinpflug im Tal der Vier Winde.", description = "Mein Vater gab sein Leben für mich. Tyrande gab mir ihr Vertrauen. Meine Schildwachen gaben mir ihre Treue.\n\nEs ist Zeit, dass ich es ihnen vergelte.\n\nWo Brojai nun tot ist, können wir die restlichen Mogu erledigen. Die nächste Bedrohung sind die Mantis.\n\nGeht nach Norden nach Steinpflug und unterstützt sie dort. Sagt ihnen, ich komme mit so vielen Schildwachen, wie ich ausheben kann, und helfe ihnen bei der Verteidigung ihrer Stadt gegen die Mantis.", progress = nil, completion = "Mantis aus dem Süden? Das ist kein guter Tag.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30361] = {title = "Die Mantis", objective = "Tötet 10 Mantis der Ik'thik.", description = "Die Mantis! Sie kamen aus dem Nichts, schlugen unseren Konvoi in Trümmer und versprengten unsere Leute in alle Richtungen.\n\nJetzt bereiten sie einen Angriff auf Steinpflug vor.\n\nBitte, <Klasse>, vernichtet ein paar dieser Bestien, bevor sie zahlreich genug sind, um uns zu umzingeln.\n\nWenn mein Cousin, Botschafter Len, immer noch am Leben ist und sich in unserem Konvoi befindet, sollte er Euch für Eure Hilfe belohnen können.", progress = nil, completion = "Danke für Eure Hilfe, &lt;Klasse&gt;! Ich habe noch nie gesehen, wie sich jemand so den Mantis entgegengeworfen hat.\n\nNun, außer den Shado-Pan natürlich...", rewards = "NayelirobeTodesrachenrobeTiefwildrüstungNarsongbrustschutzAngkhalrobeFlussklingentunikaSarjunbrustschutzKorjanibrustharnischBrustharnisch des DojaniIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30363] = {title = "In die Offensive gehen", objective = "Besorgt den Bericht der Schildwache des Übergriffs.", description = "Ha! Also hat mein Vater zwanzig Jahre unserer Leben einer vergeblichen Mühe wegen verschwendet!\n\nIch übernehme das Kommando.\n\nAls Tyrande uns hierhergeschickt hat, machte sie sehr deutlich, dass wir nicht zurückkommen sollen, bis wir das Licht gefunden haben, das sie in ihren Visionen gesehen hatte. Es ist jetzt offensichtlich, dass es sich dabei nicht um die Teiche der Jugend gehandelt hat.\n\nIch möchte Euch bitten, nach meinem Späher zu suchen. Ich habe sie ausgesandt, den Kranichtempel zu erkunden, aber sie ist nicht zurückgekehrt.\n\nBesorgt ihren Bericht und trefft Euch mit uns beim Lager der Schildwachen weiter im Westen.", progress = "Habt Ihr den Späher gefunden?", completion = "&lt;Name&gt;, wie immer zur rechten Zeit. Es hat sich herausgestellt, dass auch die Mogu wissen, wie man Portale verwendet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30376] = {title = "Die Hoffnung stirbt zuletzt", objective = "Sprecht mit Lun Mai in Steinpflug.", description = "Die Shado-Pan sind sicherlich mit ähnlichen Ausbrüchen anderswo in Pandaria beschäftigt.\n\nSucht Lun Mai auf, den Wachkommandanten der Shado-Pan in Steinpflug am westlichen Ende des Tals der Vier Winde. Lasst ihn wissen, dass wir die Situation hier unter Kontrolle haben - die Shado-Pan brauchen keine Hilfe zu entsenden.\n\nGanz im Gegenteil: Ich werde einige meiner Gefolgsleute auf eine Pilgerreise schicken, damit sie den Bedürftigen eine Nachricht der Hoffnung überbringen können.\n\nNochmals vielen Dank, $p. Lebt wohl.", progress = nil, completion = "Endlich ein paar gute Nachrichten. Ich werde sofort einen Falken nach Winterblüte ausschicken und sie wissen lassen, dass der Tempel des Roten Kranichs sicher ist.\n\nMit dem Ausbruch des Sha und der zunehmenden Aggression der Mantis steht es um unsere Truppenstärke momentan nicht zum Besten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30379] = {title = "Ein Rubinsplitter für Gina", objective = "Jetzt steht doch nicht einfach so rum und haltet Maulaffen feil. Was gibt es denn?!", description = nil, progress = "Jetzt steht doch nicht einfach so rum und haltet Maulaffen feil. Was gibt es denn?!", completion = "Oh, was für ein makelloser Edelstein!\n\nWenn Ihr mir weiterhin solche Geschenke macht, kann ich mich vielleicht bald zur Ruhe setzen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30380] = {title = "Ein hübscher Apfel für Gina", objective = "Heute ist viel los auf dem Markt. Was kann ich für Euch tun?", description = nil, progress = "Heute ist viel los auf dem Markt. Was kann ich für Euch tun?", completion = "Oh, was für ein hübscher Apfel! Diese süßen Früchte mag hier wirklich jeder.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30381] = {title = "Eine Jadekatze für Ella", objective = "Habt Ihr selbst Haustiere? Ich mag Katzen, aber Hunde habe ich auch gern.", description = nil, progress = "Habt Ihr selbst Haustiere? Ich mag Katzen, aber Hunde habe ich auch gern.", completion = "Oh, eine Jadekatze!\n\nMein Vater und ich haben immer in den Feldern nach ihnen gesucht. Er hat gesagt, sie würden Glück bringen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLiebstes Geschenk geben"}
MultiLanguageQuestData['de'][30382] = {title = "Eine blaue Feder für Ella", objective = "Heute ist ein wirklich schöner Tag, findet Ihr nicht?", description = nil, progress = "Heute ist ein wirklich schöner Tag, findet Ihr nicht?", completion = "Oh, ich danke Euch. Diese Feder ist ja wirklich wunderschön.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30383] = {title = "Eine Sumpflilie für Ella", objective = "Was? Oh, hallo. Wie geht es Euch denn?", description = nil, progress = "Was? Oh, hallo. Wie geht es Euch denn?", completion = "Oh, die sind wirklich selten. Ich danke Euch vielmals dafür.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30384] = {title = "Blendet sie!", objective = "Tötet den Späher der Sonnenläufer.", description = "Sonnenläufer der Horde! Kurz bevor Ihr angekommen seid, haben wir einen ihrer Späher bei der Oubliette patrouillieren sehen.\n\nIch weiß nicht, wie er dorthin gekommen ist, aber ich kann Euch versichern, dass er garantiert nicht alleine ist. Das sind sie nie.\n\nTötet den Späher der Sonnenläufer, bevor er über unsere Position Bericht erstatten kann.", progress = nil, completion = "Sonnenläufern kann man nicht trauen. Es handelt sich bei ihnen um den kriegerischsten Zweig der taurischen Armeen der Horde.\n\nDanke für Eure Hilfe, &lt;Name&gt;. Bitte nehmt dies als Belohnung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30385] = {title = "Die Garnison der Untergehenden Sonne", objective = "Sprecht mit Anji Herbstlicht in der Garnison der Untergehenden Sonne.", description = "Für Eure Hilfe danke ich Euch von ganzem Herzen. Anji wartet in der Garnison der Untergehenden Sonne im Westen auf Euch.\n\nMöge Euch ein guter Tag beschieden sein.", progress = nil, completion = "Willkommen. Hat Chen Euch geschickt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30386] = {title = "Ein Gericht für Ella", objective = "Seid gegrüßt an diesem schönen Tag.", description = nil, progress = "Seid gegrüßt an diesem schönen Tag.", completion = "Oh, Garnelenklößchen? Mein Lieblingsessen!\n\nDankeschön.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEssen geben\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30387] = {title = "Eine Jadekatze für Gina", objective = "Besser viele Kunden als gar keinen. Und wie kann ich Euch helfen?", description = nil, progress = "Besser viele Kunden als gar keinen. Und wie kann ich Euch helfen?", completion = "Was für eine interessante kleine Figur. Wirklich hübsch. Ich danke Euch vielmals.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30388] = {title = "Eine blaue Feder für Gina", objective = "Was habt Ihr denn da Schönes?", description = nil, progress = "Was habt Ihr denn da Schönes?", completion = "So eine hübsche Feder würde einen guten Preis erzielen. Aber die verkaufe ich nicht. Danke für das schöne Geschenk.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30389] = {title = "Eine Sumpflilie für Gina", objective = "Hallo, <Name>. Lernt Ihr so langsam die Leute in der Stadt kennen?", description = nil, progress = "Hallo, <Name>. Lernt Ihr so langsam die Leute in der Stadt kennen?", completion = "Oh, wie schön! Ihr habt mir eine Sumpflilie gebracht.\n\nWoher wusstet Ihr, dass es meine Lieblingsblumen sind?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLiebstes Geschenk geben"}
MultiLanguageQuestData['de'][30390] = {title = "Ein Gericht für Gina", objective = "Ich bin schon den ganzen Tag schwer beschäftigt. Hier ist manchmal ziemlich viel los.", description = nil, progress = "Ich bin schon den ganzen Tag schwer beschäftigt. Hier ist manchmal ziemlich viel los.", completion = "Ihr bringt mir an diesem turbulenten Markttag etwas zu essen? Das ist aber lieb von Euch!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEssen geben\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30391] = {title = "Ein Rubinsplitter für den alten Hügelpranke", objective = "Ich hab' schon genug Probleme mit meinem Hof. Eure kann ich nicht auch noch gebrauchen.", description = nil, progress = "Ich hab' schon genug Probleme mit meinem Hof. Eure kann ich nicht auch noch gebrauchen.", completion = "Oh, für mich? Das ist aber wirklich nett von Euch.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30392] = {title = "Ein hübscher Apfel für den alten Hügelpranke", objective = "Die verfluchten Affen waren wieder auf meinem Hof. So was kann einem wirklich die Laune verhageln.", description = nil, progress = "Die verfluchten Affen waren wieder auf meinem Hof. So was kann einem wirklich die Laune verhageln.", completion = "Na, das is' ja echt nett. Hmpf.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30393] = {title = "Eine Jadekatze für den alten Hügelpranke", objective = "Was darf's heute sein, <Volk>?", description = nil, progress = "Was darf's heute sein, <Volk>?", completion = "Hmpf, das is' aber 'n feiner Zug von Euch, dass Ihr so an mich denkt.\n\nDanke.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30394] = {title = "Eine blaue Feder für den alten Hügelpranke", objective = "Kann ein alter Mann denn hier keine Ruhe finden?", description = nil, progress = "Kann ein alter Mann denn hier keine Ruhe finden?", completion = "...\n\nMein Sohn, Tai… als kleiner Junge hat er die gesammelt.\n\nAls seine Mutter starb, sagte ich ihm, sie seien Nachrichten von ihr, die vom Himmel fallen.\n\n&lt;Der alte Hügelpranke verfällt in düsteres Schweigen.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLiebstes Geschenk geben"}
MultiLanguageQuestData['de'][30395] = {title = "Eine Sumpflilie für den alten Hügelpranke", objective = "Es steht 'ne Ernte bevor, und mein Rücken macht mir wieder Ärger. Was soll's, wir alle müssen hier irgendwie zurechtkommen.", description = nil, progress = "Es steht 'ne Ernte bevor, und mein Rücken macht mir wieder Ärger. Was soll's, wir alle müssen hier irgendwie zurechtkommen.", completion = "Oh, diese Blumen sind ziemlich selten.\n\nWusstet Ihr, dass die Glück bringen sollen? Vielleicht fällt meine Ernte ja doch noch gut aus. Danke.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30396] = {title = "Ein Gericht für den alten Hügelpranke", objective = "Meine Frau machte früher die leckerste geschmorte Schildkröte überhaupt! Wie ich sie vermisse.", description = nil, progress = "Meine Frau machte früher die leckerste geschmorte Schildkröte überhaupt! Wie ich sie vermisse.", completion = "Dieses Gericht habe ich seit dem Tod meiner Frau nicht mehr gegessen. Auf irgendeine Weise scheint sie Euch zu mir geschickt zu haben.\n\nDanke, &lt;Volk&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEssen geben\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30397] = {title = "Ein Rubinsplitter für Chi-Chi", objective = "Was gibt's?", description = nil, progress = "Was gibt's?", completion = "Schöner Stein! Ihr dumm, wenn Ihr den hergebt. Egal, jetzt gehört er mir!\n\nDanke, &lt;Volk&gt;!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30398] = {title = "Ein hübscher Apfel für Chi-Chi", objective = "Ich bin kein Bergaffe - glaubt das ja nicht.", description = nil, progress = "Ich bin kein Bergaffe - glaubt das ja nicht.", completion = "Für mich? Roter Apfel? So glänzend! So saftig! Danke!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30399] = {title = "Eine Jadekatze für Chi-Chi", objective = "Chi-Chi war erster Ho-zen-Bauer. Wenn ich das geschafft hab', dann Ihr auch.", description = nil, progress = "Chi-Chi war erster Ho-zen-Bauer. Wenn ich das geschafft hab', dann Ihr auch.", completion = "Ooh, sehr alt, sehr wertvoll. Ich mag Kätzchen. Habe eins von Mädchen Ella.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30400] = {title = "Eine blaue Feder für Chi-Chi", objective = "Verfiddelte Berg-Ho-zen! Wissen nicht, wie hart der kleine Chi-Chi arbeitet. Böse Affen!", description = nil, progress = "Verfiddelte Berg-Ho-zen! Wissen nicht, wie hart der kleine Chi-Chi arbeitet. Böse Affen!", completion = "Du meine Güte. Wisst Ihr, was das ist? Eine Frikfrak! Nur etwas für Anführer!\n\nDas heißt also… Ihr glaubt, ich bin Anführer? Jetzt sind wir Anführerfreunde, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLiebstes Geschenk geben"}
MultiLanguageQuestData['de'][30401] = {title = "Eine Sumpflilie für Chi-Chi", objective = "Kleiner Chi-Chi hat sein ganzes Leben hier verbracht. Das ist mein Zuhause.", description = nil, progress = "Kleiner Chi-Chi hat sein ganzes Leben hier verbracht. Das ist mein Zuhause.", completion = "Oh! Schönes Blümchen! Darf ich behalten, ja? Danke! Wiedersehen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30402] = {title = "Ein Gericht für Chi-Chi", objective = "Chi-Chi arbeitet den ganzen Tag auf dem Feld. So müde!", description = nil, progress = "Chi-Chi arbeitet den ganzen Tag auf dem Feld. So müde!", completion = "Oh, ein Pfannengericht nach Vier-Winde-Art. Danke!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEssen geben\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30403] = {title = "Ein Rubinsplitter für Sho", objective = "Ja, <Klasse>. Was kann ich für Euch tun?", description = nil, progress = "Ja, <Klasse>. Was kann ich für Euch tun?", completion = "Für mich? Oh, danke sehr!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30404] = {title = "Ein hübscher Apfel für Sho", objective = "Pssst! Hört. Man muss stets wachsam sein.", description = nil, progress = "Pssst! Hört. Man muss stets wachsam sein.", completion = "Danke.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLiebstes Geschenk geben"}
MultiLanguageQuestData['de'][30405] = {title = "Eine Jadekatze für Sho", objective = "Der erste Schritte zur Disziplinierung Eures Geistes ist die Disziplinierung Eures Körpers.", description = nil, progress = "Der erste Schritte zur Disziplinierung Eures Geistes ist die Disziplinierung Eures Körpers.", completion = "Ich weiß die Geste zu schätzen, &lt;Volk&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30406] = {title = "Eine blaue Feder für Sho", objective = "Die Wache endet nie.", description = nil, progress = "Die Wache endet nie.", completion = "Ich weiß die Geste zu schätzen, &lt;Volk&gt;. Danke, dass Ihr an mich gedacht habt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30407] = {title = "Eine Sumpflilie für Sho", objective = "Ich habe hart daran gearbeit, die Ho-zen oben auf dem Berg auszurotten.", description = nil, progress = "Ich habe hart daran gearbeit, die Ho-zen oben auf dem Berg auszurotten.", completion = "Ich war nie jemand, der sich mit hübschem, nutzlosem Tand umgibt, aber ich weiß, dass Ihr mir das als Zeichen der Freundschaft schenkt. Dafür danke ich Euch. Wenn ich diese Blume ansehe, werde ich an Euch denken.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30408] = {title = "Ein Gericht für Sho", objective = "Schwankt nie in Eurer Stärke.", description = nil, progress = "Schwankt nie in Eurer Stärke.", completion = "Ah, das ist das beste Geschenk, dass mir geben konntet! Ein Krieger braucht Stärke!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEssen geben\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30409] = {title = "Ein Rubinsplitter für Haohan", objective = "Wart Ihr schon beim Haus des Bundes der Ackerbauern in Halbhügel?", description = nil, progress = "Wart Ihr schon beim Haus des Bundes der Ackerbauern in Halbhügel?", completion = "Oh ja, dieser Rubin wird sich sehr gut mit dem Rest meiner Sammlung machen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLiebstes Geschenk geben"}
MultiLanguageQuestData['de'][30410] = {title = "Ein hübscher Apfel für Haohan", objective = "Wie geht's voran auf dem Hof?", description = nil, progress = "Wie geht's voran auf dem Hof?", completion = "Hmm, ich mag einen hübschen Apfel wirklich.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30411] = {title = "Eine Jadekatze für Haohan", objective = "Was gibt's? Ich bin ein vielbeschäftigter Mann.", description = nil, progress = "Was gibt's? Ich bin ein vielbeschäftigter Mann.", completion = "Oh, das ist wirklich exquisite Handarbeit. Wo habt Ihr das bloß her?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30412] = {title = "Eine blaue Feder für Haohan", objective = "Hallo <Volk>.", description = nil, progress = "Hallo <Volk>.", completion = "Hmm, das ist eine wirklich schön glänzende Feder. Ich werde sie zu meiner Sammlung seltener Gegenstände legen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30413] = {title = "Eine Sumpflilie für Haohan", objective = "Ein guter Bauer hält seine Erde gepflügt, damit sie bepflanzt werden kann. Ungepflügter Boden nützt niemandem was, stimmt's, <Name>?", description = nil, progress = "Ein guter Bauer hält seine Erde gepflügt, damit sie bepflanzt werden kann. Ungepflügter Boden nützt niemandem was, stimmt's, <Name>?", completion = "Hmm, ich schätze, diese Blumen sollen Glück bringen. Ich fühle mich geehrt, dass Ihr sie mir gebt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30414] = {title = "Ein Gericht für Haohan", objective = "Ein guter Bauer weiß, wann es Zeit ist zu arbeiten und wann es Zeit ist, zu essen! Man muss sich auch an den Früchten seiner Arbeit erfreuen können, stimmt's?", description = nil, progress = "Ein guter Bauer weiß, wann es Zeit ist zu arbeiten und wann es Zeit ist, zu essen! Man muss sich auch an den Früchten seiner Arbeit erfreuen können, stimmt's?", completion = "Gegrilltes Tigersteak! Für mich? Woher wusstet Ihr, dass das mein Leibgericht ist?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEssen geben\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30416] = {title = "Ein Rubinsplitter für Bauer Fung", objective = "Hey, es ist die Stadtpfote!", description = nil, progress = "Hey, es ist die Stadtpfote!", completion = "Oh, das ist ein sehr schöner Stein.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30417] = {title = "Ein hübscher Apfel für Bauer Fung", objective = "Wie geht es Euch, <Volk>?", description = nil, progress = "Wie geht es Euch, <Volk>?", completion = "So ein schöner Apfel für mich?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30418] = {title = "Eine Jadekatze für Bauer Fung", objective = "Was kann ich für Euch tun?", description = nil, progress = "Was kann ich für Euch tun?", completion = "Hmmm, eine interessante kleine Statue.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30419] = {title = "Eine blaue Feder für Bauer Fung", objective = "Hallo <Volk>!", description = nil, progress = "Hallo <Volk>!", completion = "Das ist eine sehr seltene blaue Feder. Danke.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30420] = {title = "Eine Sumpflilie für Bauer Fung", objective = "Nichts fühlt sich besser an als das Gefühl, wenn die Aussaat erledigt ist.", description = nil, progress = "Nichts fühlt sich besser an als das Gefühl, wenn die Aussaat erledigt ist.", completion = "Oh, eine wirklich seltene Blume.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLiebstes Geschenk geben"}
MultiLanguageQuestData['de'][30421] = {title = "Ein Gericht für Bauer Fung", objective = "Ich glaube, mein Magen knurrt.", description = nil, progress = "Ich glaube, mein Magen knurrt.", completion = "Woher wusstet Ihr, dass das mein Leibgericht ist? Danke.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEssen geben\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30422] = {title = "Ein Rubinsplitter für Fischi", objective = "Ich habe den ganzen Tag Yaks zusammengetrieben.", description = nil, progress = "Ich habe den ganzen Tag Yaks zusammengetrieben.", completion = "Ooh, ich habe noch nie einen solch hübschen roten Stein gesehen. Danke, &lt;Name&gt;!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30423] = {title = "Ein hübscher Apfel für Fischi", objective = "Ich habe den ganzen Tag Shed-Ling gejagt.", description = nil, progress = "Ich habe den ganzen Tag Shed-Ling gejagt.", completion = "Mein Magen knurrt schon den ganzen Morgen! Das ist das perfekte Geschenk.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30424] = {title = "Eine Jadekatze für Fischi", objective = "Ich habe den ganzen Vormittag mit Schweinen gerungen.", description = nil, progress = "Ich habe den ganzen Vormittag mit Schweinen gerungen.", completion = "Oh, eine hübsche Jadekatze! Das macht mich wirklich glücklich, &lt;Name&gt;!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLiebstes Geschenk geben"}
MultiLanguageQuestData['de'][30425] = {title = "Eine blaue Feder für Fischi", objective = "Ich habe den ganzen Tag Würmer ausgegraben.", description = nil, progress = "Ich habe den ganzen Tag Würmer ausgegraben.", completion = "Whoa, so eine hübsche Farbe habe ich ja noch nie gesehen. Danke, &lt;Name&gt;!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30426] = {title = "Eine Sumpflilie für Fischi", objective = "Ich bin den ganzen Tag mit den Fischen geschwommen.", description = nil, progress = "Ich bin den ganzen Tag mit den Fischen geschwommen.", completion = "Mein Opa hat immer gesagt, dass diese Blummen viel Glück bringen. Danke, &lt;Name&gt;!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30427] = {title = "Ein Gericht für Fischi", objective = "Ich bin den ganzen Tag auf Bäume geklettert.", description = nil, progress = "Ich bin den ganzen Tag auf Bäume geklettert.", completion = "Junge, Junge, das mag ich am liebsten! Danke, &lt;Name&gt;!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEssen geben\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30428] = {title = "Ein Rubinsplitter für Tina", objective = "Wie geht es Euch heute, <Volk>?", description = nil, progress = "Wie geht es Euch heute, <Volk>?", completion = "Ohhh, ein glitzernder, glänzender Edelstein! Ich liebe ihn!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLiebstes Geschenk geben"}
MultiLanguageQuestData['de'][30429] = {title = "Ein hübscher Apfel für Tina", objective = "Wie sehe ich heute aus, <Name>?", description = nil, progress = "Wie sehe ich heute aus, <Name>?", completion = "Oh, meine Güte, danke, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30430] = {title = "Eine Jadekatze für Tina", objective = "Wisst Ihr, es ist schwer, immer so gut auszusehen.", description = nil, progress = "Wisst Ihr, es ist schwer, immer so gut auszusehen.", completion = "Meine Güte, das ist wunderschön! Vielen Dank, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30431] = {title = "Eine blaue Feder für Tina", objective = "Möchtet Ihr Euch vielleicht ein wenig zu mir setzen, <Volk>?", description = nil, progress = "Möchtet Ihr Euch vielleicht ein wenig zu mir setzen, <Volk>?", completion = "Oh, diese blaue Feder wird meine blauen Augen zum Strahlen bringen. Danke, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30432] = {title = "Eine Sumpflilie für Tina", objective = "Wie geht es auf dem Hof voran?", description = nil, progress = "Wie geht es auf dem Hof voran?", completion = "Oh, das wird mir viel Glück bringen! Danke, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30433] = {title = "Ein Gericht für Tina", objective = "Bitte grüßt Bauer Yoon von mir.", description = nil, progress = "Bitte grüßt Bauer Yoon von mir.", completion = "Oh, meine Leibgericht! Lecker!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEssen geben\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30434] = {title = "Ein Rubinsplitter für Jogu", objective = "Habt Ihr vielleicht ein Kupferstückchen für ein kleines Getränk?", description = nil, progress = "Habt Ihr vielleicht ein Kupferstückchen für ein kleines Getränk?", completion = "Oh, ein hübscher Stein! Ich werde ihn ansehen, während ich einen Schluck trinke.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30435] = {title = "Ein hübscher Apfel für Jogu", objective = "Kauft Ihr einem Jinyu was zu trinken?", description = nil, progress = "Kauft Ihr einem Jinyu was zu trinken?", completion = "Hey, das ist mein Lieblingsessen! Danke, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLiebstes Geschenk geben"}
MultiLanguageQuestData['de'][30436] = {title = "Eine Jadekatze für Jogu", objective = "Es ist harte Arbeit, wisst Ihr, all diese Visionen zu deuten.", description = nil, progress = "Es ist harte Arbeit, wisst Ihr, all diese Visionen zu deuten.", completion = "Danke-", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30437] = {title = "Eine blaue Feder für Jogu", objective = "Die Ernte von morgen wird… oh, ich kann es noch nicht sehen. Erst muss ich etwas trinken.", description = nil, progress = "Die Ernte von morgen wird… oh, ich kann es noch nicht sehen. Erst muss ich etwas trinken.", completion = "Eine schöne blaue Feder für mich? Danke, &lt;Volk&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30438] = {title = "Eine Sumpflilie für Jogu", objective = "Die Wascher schagen, dasch Euch heute das Glück hold schein wird.", description = nil, progress = "Die Wascher schagen, dasch Euch heute das Glück hold schein wird.", completion = "Die Wascher hatten recht! Diesche Blume wird mir Glück bringen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGift Turn-In"}
MultiLanguageQuestData['de'][30439] = {title = "Ein Gericht für Jogu", objective = "Wisst Ihr, was gut zu einem guten Schluck passt? Ein gutes Essen.", description = nil, progress = "Wisst Ihr, was gut zu einem guten Schluck passt? Ein gutes Essen.", completion = "Nichts kommt an ein köstliches kaltes Getränk und ein paar gebratene Karotten heran.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEssen geben\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30442] = {title = "Blanches Hammerbräu", objective = "Helft das Hammerbräu zu brauen. Sollten die Bierfässer in Brand geraten, bringt das wieder in Ordnung!", description = "Helft beim Brauen von Blanches Hammerbräu, indem Ihr auf die Bierfässer aufpasst.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30444] = {title = "Keine Atempause", objective = "Tötet 8 Shao-Tien-Mogu nahe den Fünf Schwestern.", description = "Wir genießen gerade eine kurze Atempause von den Moguangriffe auf die Fünf Schwestern im Norden. Ich würde Euch gerne entsenden, um sicherzustellen, dass wir ihnen keine solche Ruhepause gewähren.\n\nZeigt keine Gnade.", progress = nil, completion = "Das sollte sie für eine Weile aus dem Konzept gebracht haben. Ich danke Euch.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30445] = {title = "Die Wasser der Jugend", objective = "Überbringt Lyalia Vaeldrins Botschaft.", description = "Sie ist eigensinnig, meine kleine Lyalia. Ich hätte wissen müssen, dass sie versuchen würde, den Obersten Eroberer herauszufordern.\n\nSeit ihre Mutter gestorben ist, habe ich viel Zeit auf die Suche nach Unsterblichkeit verschwendet, die ich mit ihr hätte verbringen sollen. Ich beharrte einfach darauf, dass wir ewig leben könnten... zusammen.\n\nUnd jetzt hat meine Besessenheit meine kleine Lyalia das Leben gekostet.\n\nBitte, $p, wenn sie aufwacht, sagt ihr, dass ich sie liebe.", progress = nil, completion = "Er... er hätte das nicht machen sollen! Er hätte nicht für meinen Fehler bezahlen sollen!", rewards = "NayelimantelungTodesrachenschiftungTiefwildschulterstückeNarsongschiftungAngkhalamiciaFlussklingenschiftungSarjunschiftungKorjanischulternSchultern des DojaniIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30449] = {title = "Kranichkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Kranichkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Kranichkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Kranichkartenset zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Kranichkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", rewards = "Ihr bekommt:\n\nRelikt von Chi-Ji"}
MultiLanguageQuestData['de'][30450] = {title = "Ochsenkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Ochsenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Ochsenkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Ochsenkartenset zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Ochsenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", rewards = "Ihr bekommt:\n\nRelikt von Niuzao"}
MultiLanguageQuestData['de'][30451] = {title = "Schlangenkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Schlangenkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Schlangenkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Schlangenkartenset zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Schlangenkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", rewards = "Ihr bekommt:\n\nReliquie von Yu'lon"}
MultiLanguageQuestData['de'][30452] = {title = "Tigerkartenset des Dunkelmond-Jahrmarkts", objective = "Gebt das Tigerkartenset auf dem Dunkelmond-Jahrmarkt ab, sobald dieser wieder in der Stadt ist.", description = "Jetzt, da Ihr alle Karten des Tigerkartensets in einem Set gesammelt habt, erscheint auf geheimnisvolle Weise eine neunte Karte, die dieselbe Rückseite hat, wie die ersten acht. Auf dieser Karte steht: \"Bringt diese Karten zum Dunkelmond-Jahrmarkt und Ihr werdet belohnt werden.\" Ihr habt gehört, dass der Zugang zu diesem Jahrmarkt jeden Monat in der Nähe von Mulgore oder Goldhain erscheint.", progress = "Wie ich sehe, habt Ihr es geschafft, ein Tigerkartenset zusammen zu bekommen! Glückwunsch!", completion = "Ihr habt es also geschafft, ein Tigerkartenset zu komplettieren. Dass Ihr uns die Karten zurückgebt, wird ein Band zwischen uns schaffen, das wir so schnell nicht vergessen werden. Erlaubt mir, Euch eine der mächtigen Dunkelmond-Karten zu schenken. Nehmt sie als ein kleines Zeichen unserer Dankbarkeit entgegen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nReliquie von XuenReliquie von Xuen"}
MultiLanguageQuestData['de'][30457] = {title = "Raus mit dem Anführer", objective = "Tötet 10 Angehörige des Bataaristamms am Kun-Lai-Pass, bis der Feuerkrieger der Bataari auftaucht. Und dann tötet auch ihn.", description = "Eure Hilfe für uns ist wirklich heldenhaft.\n\nBitte tötet den Bataari-Stamm am Kun-Lai-Pass im Nordwesten, bis der Feuerkrieger der Bataari wütend genug ist, um aufzutauchen. Und dann erledigt auch ihn.", progress = nil, completion = "Wir sind gerettet! Ich hatte immer Vertrauen in Euch und Eure Fähigkeiten als &lt;Klasse&gt;.", rewards = "Großschwert von BinanKlinge von BinanKampfschild der BataariSchild des FlammenrufersDornbuschklingeKriegsbeil der BataariBürokratenhandbuchFächer des BürgermeistersAuf Euch wartet eine dieser Belohnungen:\n\nGeldbeutel des Helden\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][30458] = {title = "Rückkehr der Späher", objective = "Sprecht mit Rell Nachtwind im Perlflossendorf im Jadewald.<Name>, Eure Freunde sind von ihrer Spähermission zurückgekehrt. Ihr solltet sie sofort aufsuchen.\n\nIch bin besorgt...\n\nAber ich sage lieber nichts mehr. Seht es Euch selbst an.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "<Name>, Eure Freunde sind von ihrer Spähermission zurückgekehrt. Ihr solltet sie sofort aufsuchen.\n\nIch bin besorgt...\n\nAber ich sage lieber nichts mehr. Seht es Euch selbst an.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30459] = {title = "Pfeile sammeln gehen", objective = "Sammelt 12 Pfeile für Kommandantin Hsieh.", description = "Sobald ihre Verstärkungen eintreffen, werden die Yaungol unsere Positionen hier überrennen. Und wenn sie das tun, ist unser Dorf verloren.\n\nKönntet Ihr vielleicht so viele Pfeile wie möglich vom Schlachtfeld bergen? Ich habe einen Plan, der uns mit Eurer Hilfe vielleicht retten könnte.", progress = "Wie viele Pfeile habt Ihr?", completion = "Ich danke Euch, &lt;Name&gt;. Ihr habt unsere Verteidigungslinie hier gerettet.\n\nDieser nächste Angriff wäre ohne Eure Hilfe nicht möglich gewesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30460] = {title = "Gute Medizin", objective = "Benutzt die Dit Da Jow oder Eure eigenen Heilkräfte, um 8 verletzten Kriegern aus Binan zu helfen.", description = "Unsere Krieger kämpfen, um die Yaungol im Kun-Lai-Pass im Nordwesten im Zaum zu halten.\n\nNehmt dieses Einreibemittel. Es ist eine starke Medizin, deren Rezept in meiner Familie von einer Generation zur nächsten weitergegeben wurde.\n\nBenutzt die Dit Da Jow zur Heilung von verwundeten Kriegern, wenn Ihr keine eigenen Heilkräfte habt, die Ihr bei ihnen einsetzen könnt.", progress = nil, completion = "Habt meinen Dank, &lt;Name&gt;. Ihr habt durch Eure Taten große Ehrbarkeit gezeigt.\n\nIch hoffe, die Dit Da Jow meiner Familie hat Euch etwas geholfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30461] = {title = "In die Wildnis", objective = "Findet Koro Nebelgänger in der Nähe des Tempels des Roten Kranichs an der südlichen Mündung des Krasarang.", description = "Tief in der Wildnis liegt der Tempel des Roten Kranichs, die Heimat des großen Chi-Ji und seiner gläubigsten Anhänger. Ich vermute, sie wissen etwas darüber, was hier passiert ist.\n\nDer Tempel befindet sich an der südlichen Küste der Wildnis, wo der Krasarang ins Meer mündet.", progress = nil, completion = "Verstehe... Und das Sha hat bereits die gesamte Provinz durchtränkt, oder?\n\nNun, es tut mir leid, aber ich muss Euch sagen, dass auch der Tempel vom Sha überschwemmt ist. Diejenigen unter uns, die nicht getötet oder... besessen wurden, oder was auch immer, rennen um ihr Leben.\n\nWenn Ihr das Sha bei Zhus Bastion besiegt habt, muss ich Euch inständig anflehen, uns zu helfen, hier mit dem Sha fertigzuwerden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30462] = {title = "In die Wildnis", objective = "Findet Koro Nebelgänger in der Nähe des Tempels des Roten Kranichs an der südlichen Mündung des Krasarang.", description = "Tief in der Wildnis liegt der Tempel des Roten Kranichs, die Heimat des großen Chi-Ji und seiner gläubigsten Anhänger\n\nIch vermute, sie wissen etwas darüber, was hier passiert ist.\n\nDer Tempel befindet sich an der südlichen Küste der Wildnis, wo der Krasarang ins Meer mündet.", progress = nil, completion = "Verstehe... Und das Sha hat bereits die gesamte Provinz durchtränkt, oder?\n\nNun, es tut mir leid, aber ich muss Euch sagen, dass auch der Tempel vom Sha überschwemmt ist. Diejenigen unter uns, die nicht getötet oder... besessen wurden, oder was auch immer, rennen um ihr Leben.\n\nWenn Ihr das Sha bei Zhus Bastion besiegt habt, muss ich Euch inständig anflehen, uns zu helfen, hier mit dem Sha fertigzuwerden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30464] = {title = "Auf in den Westen", objective = "Reist zur Morgenjägerzuflucht.", description = "Leza wandelt nun mit den Vorfahren dieses seltsamen Landes. Ich muss mich jetzt um die Lebenden kümmern.\n\nKor hat eine Gruppe unserer Späher nach Westen tiefer in den Dschungel geführt.\n\nSpürt ihn auf und gebt ihm an Hilfe, was Ihr könnt. Wir werden so schnell wir können zu Euch stoßen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "DornbuschmedaillonDornbuschhalsreifDornbuschhalsketteDornbuschanhängerDornbuschamulettIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30465] = {title = "In die Offensive gehen", objective = "Sprecht mit Lyalia beim Lager der Schildwachen in der Krasarangwildnis.", description = "Ha! Also hat mein Vater zwanzig Jahre unserer Leben einer vergeblichen Mühe wegen verschwendet!\n\nIch übernehme das Kommando.\n\nAls Tyrande uns hierhergeschickt hat, machte sie sehr deutlich, dass wir nicht zurückkommen sollen, bis wir das Licht gefunden haben, das sie in ihren Visionen gesehen hatte. Es ist jetzt offensichtlich, dass es sich dabei nicht um die Teiche der Jugend gehandelt hat.\n\nWir rücken westwärts vor und könnten Eure Hilfe brauchen.\n\nTrefft Euch mit uns beim Lager der Schildwachen weiter im Westen, wenn Ihr bereit seid.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30466] = {title = "Genügend Motivation", objective = "Motiviert 10 Faule Ho-zen.", description = "Die Ausbildung dieser Wilden war eine Herausforderung, <Name>.\n\nSie zu motivieren war einfach, schwerer ist es jedoch, sie bei der Stange zu halten... sowie konzentriert... und wach.\n\nDa Ihr zurück seid, könnt Ihr mir helfen, die undisziplinierteren Ho-zen anzutreiben, wenn Ihr versteht, was ich meine. Ich überlasse Euch die Wahl der Methode.", progress = "Sind die Ho-zen einsatzbereit?", completion = "Hrmm, ich wäre überrascht, wenn wir es schaffen würden, dass diese Kreaturen sich lange genug konzentrieren, um überhaupt eine Taktik anzuwenden, &lt;Name&gt;.\n\nSie sollten besser nicht im Weg rumstehen, wenn die Klingen fliegen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30467] = {title = "Mein Sohn...", objective = "Findet Wu-Peng am Tintenkiemenweiher.", description = "Mein Sohn - könnt Ihr meinen Sohn suchen?\n\nAls die Jinyu angegriffen haben, rannte er verwirrt weg. Ich weiß nicht, ob sie ihm etwas angetan haben, geschweige denn, ob er überhaupt noch lebt.\n\nWenn ich ihn nicht finden kann, ist alles egal. \n\nIch würde Mei fragen... aber mit ihr stimmt etwas nicht. Seit dem Angriff scheint sie so... impulsiv zu sein. Ich kann einfach nicht darauf vertrauen, dass sie ihn sicher zurückbringt.", progress = nil, completion = "So schrecklich... Als ich das Morden sah, bin ich einfach nur gerannt. Mein Vater, Mei... sind sie am Leben?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30468] = {title = "Wütende Vergeltung", objective = "Tötet 15 wütende Jinyu.", description = "<Mit der Schwertmeisterin stimmt etwas nicht. Ihr Blick ist von einer Düsternis erfüllt, die für Pandaren ganz untypisch ist.>\n\nIch glaube nicht, dass ich jemals so... so wütend war. Oh dieser Verrat!\n\nIch schlug sie zurück, als sie angriffen, und konnte sogar ein paar von ihnen erledigen. Aber Händler Shi ist ein solcher Feigling, dass er mir nicht erlaubt, sie zu verfolgen und meine Arbeit zu Ende zu bringen!\n\nIhr! Ihr werdet es für mich tun. Ihr werdet sie alle ausschalten!", progress = nil, completion = "Es ist befriedigend zu hören, dass unsere Feinde tot sind. Vielleicht könnt Ihr eine der Waffen meines Leibwächters brauchen.", rewards = "TintenkiemenklingeLeibwächterhellebardeGroßschwert der SchwertmeisterinKlinge der SchwertmeisterinLeibwächtergewehrMeis KlingeVerzierter StreitkolbenLeibwächterdolchWiderhaken der Verstecken PassageIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30469] = {title = "Wiederinbesitznahme", objective = "Sammelt 8 gestohlene Versorgungsgüter.", description = "Natürlich liegt die oberste Priorität darauf, meinen Sohn zu finden. Wenn wir uns selbst aber nur retten, um zu verhungern, was haben wir dann am Ende erreicht?\n\nBitte, ich brauche Euch, um einige der Vorräte wiederzubeschaffen, die die Jinyu unserer Karawane geraubt haben.", progress = "Habt Ihr die Vorräte gefunden?", completion = "Danke... jetzt endlich können wir etwas essen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30470] = {title = "Ein Geschenk für Tina", objective = "Findet einen rohen Chrysoberyll.", description = "Tina Lehmkrall ist heute auf dem Halbhügelmarkt und besucht ihre Schwester. Ihre Familie hat mir wirklich sehr geholfen und ich möchte mich dafür revanchieren.\n\nIn den Klippen im Norden kann man einen kleinen Edelstein finden. Wir nennen ihn Chrysoberyll und er ändert seine Farbe, wenn man ihn in der Hand hält. SO EINEN hat sie bestimmt noch nicht!\n\nSucht in den Shed-Ling-Höhlen danach. Ich bin sicher, Ihr findet schnell einen.", progress = "Hallo, <Name>! Schön, Euch mal wieder zu sehen.", completion = "&lt;Tina hält den Stein in der Hand und beobachtet, wie seine Farbe von fahlem Blau zu leuchtendem Rot wechselt.&gt;\n\nEin Chrysoberyll? Das ist ja reizend! Und das war Andis Idee?\n\nNatürlich habe ich schon einige davon... Aber der hier ist auch wunderschön. Der wird sich gut in meiner Sammlung machen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30471] = {title = "Ein Geschenk für Chi-Chi", objective = "Besorgt ein authentisches Pfannengericht nach Vier-Winde-Art.", description = "Dieser verrückte Chi-Chi ist eigentlich gar nicht so übel. Mah sagte immer, die Ho-zen machen nichts als Ärger, aber... vielleicht ist er auch nur ein anständigerer Ho-zen als die anderen.\n\nWir sollten ihm einen Gefallen tun. Die Ho-zen in den Bergen im Westen bereiten ein aufwendiges Pfannengericht zu und bewahren oft Schüsseln davon in ihren Ho-zen-Hütten auf.\n\nIch wette, dass Chi-Chi liebend gerne etwas davon hätte!", progress = "Mmm?", completion = "Für mich? Extra für Chi-Chi?\n\nDas ist wie früher, als Chi-Chi noch ein mubbeliges Baby war. Chi-Chis Mama hat das genauso gekocht.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30472] = {title = "Ein Geschenk für Sho", objective = "Besorgt eine Schüssel Yu-Ping-Suppe.", description = "Sho, dieses Mädchen, das oben in den Bergen lebt, ist heute in der Stadt. Ich habe gesehen, dass sie in Richtung Halbhügelmarkt ging.\n\nSo ein langer Weg... Sie muss hungrig sein. Und ich glaube, ich weiß genau, was ihr gefallen würde.\n\nDie Ho-zen oben auf der Himmelsweite kochen eine Suppe aus Fischen und Äpfeln. Ich weiß, das klingt nach einem seltsamen Gericht, aber es ist wirklich köstlich. Ihr könnt es in der Nähe ihres großen, furchteinflößenden Totems finden.", progress = "Oh! Hallo, <Name>.", completion = "Ich war so hungrig! Wie konntet Ihr das wissen? Wer hat es Euch verraten?\n\nAndi? Hm, der Junge wird noch mal ein richtiger Herzensbrecher...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30473] = {title = "Ein Geschenk für Fischi", objective = "Besorgt eine Yakstatuette aus einer Hütte der Kunzen-Ho-zen.", description = "Diese Fischi Rohrroder ist schon irgendwie seltsam. Schon allein ihr Name - Fischi. Das sollte mir zu denken geben.\n\nAber wenn man erst mal mit ihr spricht, merkt man, dass sie wirklich nett ist. Wusstet Ihr zum Beispiel, dass sie Tiere über alles liebt?\n\nDas bringt mich auf eine Idee. Die Kunzen-Ho-zen in den Bergen im Westen schnitzen Tierstatuen und platzieren sie in ihren Hütten, um Feinde abzuwehren. Ich wette, Fischi würde so was einfach LIEBEN!", progress = "Hey, <Name>! Wie geht's denn?", completion = "Oh, wie schön! Wie WUNDERSCHÖN! Mit dem kleinen pelzigen Schwanz und...\n\n&lt;Sie wird wieder ernst.&gt;\n\nIch meine, ähem... danke, mein Lieber. Ist wirklich ganz reizend.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30474] = {title = "Ein Geschenk für Ella", objective = "Besorgt pikante Garnelenklößchen.", description = "Arme Ella. Sie ist so schüchtern. Ich habe gesehen, wie sie auf dem Halbhügelmarkt stand und enorm hungrig aussah. Aber sie hat sich nicht getraut, einen der Köche anzusprechen.\n\nWir sollten ihr etwas zu essen bringen. Aber nicht irgendetwas, sondern etwas Besonderes.\n\nDie Kunzen-Ho-zen machen aus den Waren, die sie uns Bauern klauen, pikante Garnelenklößchen. Die würden Ella ganz sicher gefallen.", progress = "Oh, also ... hallo.", completion = "Das wäre doch nicht nötig gewesen! Ich wollte doch gar nicht, ich brauch doch gar nicht...\n\n&lt;Ella sieht die Klöße und das Wasser läuft ihr im Mund zusammen.&gt;\n\nAlso, ja, vielleicht war ich etwas hungrig. Danke, &lt;Name&gt;. Und richtet bitte auch Andi meinen Dank aus.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30475] = {title = "Ein Geschenk für Fung", objective = "Beschafft ein blutiges Ebenenfalkenbein von einem monströsen Ebenenfalken und bringt es dann zu Kol Eisentatz auf dem Halbhügelmarkt.", description = "Bauer Fung kann ganz schön ungehobelt sein. Er jagt mir wirklich Angst ein. Aber Mah sagte immer, dass er einer der besten Landwirte im Tal sei.\n\nIch glaube, ich kenne das perfekte Geschenk für so einen gemeinen, Furcht einflößenden Kerl wie ihn.\n\nÜber den Hügeln westlich von hier kreisen ein paar kapitale Ebenenfalken. Ihr solltet einen davon erlegen, ein gutes Stück Fleisch rausschneiden und Kol Eisentatz bitten, es zu grillen!", progress = "Mmh-mmh…", completion = "Hey! Wo habt Ihr das denn her? Das könnte ja von einem Ebenenfalken sein!\n\nAndi hat Euch damit zu mir geschickt? Ha, vielleicht habe ich den Jungen doch unterschätzt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30476] = {title = "Ein Geschenk für den alten Hügelpranke", objective = "Findet eine blaue Süßwasserperle.", description = "Der alte Hügelpranke hat Millionen von Hühnern auf seinem Hof. Aber die sind ihm gar nicht SO wichtig.\n\nIch weiß nämlich, dass er am liebsten blaue Federn sammelt.\n\nIch habe keine Ahnung, wo man hier in der Gegend blaue Federn findet, aber ich weiß, wo es blaue Perlen gibt!\n\nSucht in den Austern des Rohrkolbensees im Nordwesten. Ich wette, er würde eine blaue Perle als Ergänzung zu seiner Sammlung sehr zu schätzen wissen.", progress = "<Name>! Ihr habt mich erschreckt.", completion = "Jetzt sieh sich die mal einer an! Die muss ich irgendwo aufbewahren, wo die Hühner nicht rankommen.\n\nUnd Andi hat Euch aufgetragen, die für mich zu besorgen? Netter Junge.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30477] = {title = "Ein Geschenk für Haohan", objective = "Besorgt den Zahn eines gewaltigen Rohrkolbenbarschs.", description = "Haohan Lehmkrall ist der Vorsitzende des Bundes der Ackerbauern und der reichste Landbesitzer des Tals. Es war sehr nett von ihm, mich hier willkommen zu heißen, und ich möchte ihm im Gegenzug auch einen Gefallen erweisen.\n\nEr hat einen sehr exklusiven Geschmack - er sammelt Rubinsplitter und solche Sachen. Aber ich habe nicht besonders viel Geld, also muss es etwas anderes sein...\n\nIch weiß! Ich habe einen gewaltigen Fisch im Rohrkolbensee entdeckt! Wir sollten ihm einen Zahn von diesem Fisch als Geschenk besorgen!", progress = "Kann ich etwas für Euch tun, <Klasse>?", completion = "Was haben wir denn da?! SO einen Zahn sieht man auch nicht alle Tage.\n\nHabt Ihr etwa Haie gejagt, &lt;Klasse&gt;?\n\nIch danke Euch, &lt;Name&gt;. Und richtet bitte auch Andi meinen Dank aus.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30478] = {title = "Ein Geschenk für Jogu", objective = "Bringt 8 von Yoons Äpfeln und 50 seiner Kranichbeeren zu Bobo Eisentatz, um daraus Apfelbeerenfusel brennen zu lassen.", description = "Manchmal tut mir Jogu richtig leid. Er ist der einzige Jinyu hier und er hat offensichtlich nicht viele Freunde. Von seiner stinkigen Flasche mal abgesehen, versteht sich.\n\nWisst Ihr was? Ich habe da eine Idee. Bauer Yoon hat noch einen Korb Kranichbeeren im Haus und auch noch ein paar Äpfel. Die könntet Ihr doch zum Destilliermeister auf dem Halbhügelmarkt bringen und daraus ein leckeres Tröpfchen für Jogu brennen lassen.", progress = "Hmm?", completion = "&lt;Jogu nimmt einen großen Schluck von dem Fusel.&gt;\n\nDasch isch fantaschtisch! Mein neuer Lieblingschfuschel. Der hier und schonscht keiner!\n\nWischt Ihr wasch, &lt;Name&gt;? Ihr scheid schwer in Ordnung! Wirklisch wahr!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30479] = {title = "Ein Geschenk für Gina", objective = "Findet eine Goldfeuerorchidee.", description = "Habt Ihr schon Gina Lehmkrall, das Mädchen auf dem Markt, gesehen? Sie ist perfekt: gut aussehend, intelligent und mit einem süßen, dicken Bauch ausgestattet. Würdet Ihr ihr ein Geschenk von mir bringen?\n\nIch wollte ihr gern ein paar Orchideen pflücken, die auf den höchsten Hügeln im Westen wachsen, aber so hoch komme ich einfach nicht. Könntet Ihr vielleicht eine davon pflücken und sie Gina bringen?\n\nOh, und wenn Ihr sie seht, dann grüßt sie bitte von mir.", progress = "Hallo!", completion = "Die ist ja herrlich! Ist die etwa für mich?\n\nAhh... von Andi ist sie also, ja? Ich glaube, ich kenne da jemanden, der heute Nachmittag einen dicken Kuss auf die Stirn bekommt...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30480] = {title = "Das Ritual", objective = "Sprecht mit Wassersprecher Gorai und beendet dann das Ritual.", description = "Schon als ich zum ersten Mal aus dem Fluss stieg, wusste ich, dass es mir beschieden war, Wassersprecher zu werden.\n\nIch wurde viele Rituale gelehrt, und alle von ihnen habe ich schon durchgeführt, außer einem.\n\nEs gab da ein sehr altes Ritual, das für eine Zeit gedacht war, wenn sich unser Volk je gegen uns wenden sollte.\n\nSo etwas muss sich in der fernen Vergangenheit unseres Volkes ereignet haben, denn solange die Erinnerung unseres Dorfes zurückreicht, ist das niemals nötig gewesen.\n\nJetzt ist wohl die Zeit dafür gekommen.", progress = nil, completion = "Jetzt verstehe ich, dass dieses Ritual fortreißt, was auch immer die Geister dieser Kreaturen kontrolliert. Jetzt weiß ich, was wir tun müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30481] = {title = "In Stein gemeißelt", objective = "Sammelt 12 Guo-Lai-Runensteine zusammen.", description = "Ihr seht Glitzersteine in Mauern? Rook will welche. Die Mogu haben sie auch gesammelt. Vielleicht haben die auch ein paar.\n\nWenn Ihr Steine findet, bringt Ihr sie Rook? Rook wird Euer Freund sein.", progress = "Ihr habt Steine für Rook? Bitte?", completion = "So viele! Und so glitzerig! Sehr gut!\n\nIch danke Euch, kleiner Freund. Rook mag Euch sehr.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30482] = {title = "Der Seelensammler", objective = "Tötet Schattenmeister Sydow und sichert Euch seine Seelenperlen.", description = "Während Ihr noch dabei wart, den einen Mogu zu töten, bemerktet Ihr einen anderen großen Mogu, der ein Ritual ausführte. Er wäre vielleicht nicht so klug, ihn sein Ritual beenden zu lassen.", progress = "<Er schaut Euch erwartungsvoll an.>", completion = "&lt;Als Ihr Hee die Perlen gebt, lässt sein Lächeln darauf schließen, dass er genau weiß, was sie symbolisieren. Er nickt anerkennend.&gt;", rewards = "Ihr bekommt:\n\nSchätze des TalsTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30483] = {title = "NOT USED", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30484] = {title = "Messung unseres Fortschritts", objective = "Besucht Schattenmeisterin Kiryn, Nieti Kuppelplopp, Shokia und Riko.", description = "Der Krieg steht kurz bevor, <Name>!\n\nWir haben die Einheimischen ohne Unterbrechung ausgebildet, seit Ihr aufgebrochen seid, und ich denke, dass sie nun so gut sind, wie sie es jemals sein können.\n\nAber seht selbst. Besucht die anderen und kehrt mit Euren Ergebnissen zurück.\n\nWir müssen uns darauf verlassen, dass der Feind... noch weniger vorbereitet ist.", progress = "Wie läuft es mit unserer Kampfausbildung?", completion = "Wenigstens sind sie zuversichtlich.\n\nDas ist doch die Hauptsache.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30485] = {title = "Das letzte Puzzleteil", objective = "Benutzt Chos Erbstück bei Chos Familienschrein beim Schlangenblick.\n\nUm dorthin zu kommen, sprecht mit Mishi.", description = "Diese Ho-zen verhalten sich höchst unnatürlich, <Name>. Marschieren in Formation? Und in Rüstung?\n\nDas beunruhigt mich. Allerdings müssen wir das zu einem anderen Zeitpunkt besprechen. Ich bin hier, um Euch um Eure Unterstützung zu bitten.\n\nDas uralte Fresko, dort, wo wir uns zuletzt unterhielten, ist fast enthüllt. Ich bin mir sicher, dass es uralte Weisheit enthält - Weisheit, von der der Kaiser wollte, dass wir sie nicht vergessen.\n\nDurch Meditation allein kann ich ihre Bedeutung vielleicht nicht rechtzeitig enthüllen. Bitte, bringt dieses Erbstück zum Schrein meiner Ahnen. Mit ihrer Hilfe werden wir dieses Rätsel lösen können.", progress = nil, completion = "&lt;Lehrensucher Cho schüttelt sich unwillkürlich.&gt;\n\nDie Legenden… sie sind wahr!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30487] = {title = "Über den Bergpass", objective = "Bringt den Wagen und die Wagenführer sicher durch das Nimmerlaya-Gebirge.", description = "Der Bergpass ist sehr gefährlich. Ihr braucht viel Glück, um zu überleben. Neffe Krummnagel zeigt Euch den Weg.\n\nAber vielleicht ist heute ein Glückstag für Reisen. Wind kommt aus Osten; ist gutes Zeichen. Grummel reisen am besten bei Ostwind.\n\nKlettert in den Wagen, wenn Ihr zum Aufbruch bereit seid.", progress = nil, completion = "Ihr seid gerade rechtzeitig eingetroffen, &lt;Klasse&gt;! Ich dachte schon, ich würde hier oben sterben.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDespawn All Summons LAB [INTERNAL]\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30488] = {title = "Der verschwundene Moschuspranken-Spross", objective = "Findet Moschuspranke Jr. im Witzboldwinkel.", description = "Was zur Hölle seid Ihr denn? <Ein/Eine:c> <Klasse>? Nie gehört. Seid Ihr hier, um zu helfen oder um mir meine Yaks zu stehlen?\n\nHört mal, wenn Ihr mir schon unbedingt helfen wollt, dann seht zu, ob Ihr nicht meinen Jungen findet. Er wurde von 'ner Horde Geister geschnappt und weiß wahrscheinlich nicht mal, dass wir den Hof verloren haben.\n\nSie haben ihn zum Witzboldwinkel im Südosten geschleppt. Rettet ihn, und ich werd' sehen, ob ich 'ne Belohnung für Euch auftreiben kann.", progress = nil, completion = "Danke für die Rettung, Fremder!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30489] = {title = "Frischer Nadelduft", objective = "Sammelt 100 geruchsintensive Waldgeisternadeln ein.", description = "Wenn Ihr mir wirklich helfen möchtet, könntet Ihr mir einige Nadeln von den Waldgeistern im Witzboldwinkel besorgen.\n\nDie Grummel glauben nur an Glück, das sie auch riechen können. Sie zahlen besser für Yaks mit einem frischen Nadelgeruch.", progress = "Ah! Geht doch nichts über den frischen Geruch von Nadeln.", completion = "Ihr habt mir zu einem schönen Bonus verholfen. Diese Nadeln zu besorgen ist harte Arbeit, aber eine gute Investition, bevor wir die Yaks zum Markt bringen. Bitte nehmt dies hier für Eure Mühen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30490] = {title = "Hände weg von meinen Yaks!", objective = "Tötet 9 Räuber der Burilgi auf dem Gehöft Moschuspranke.", description = "Yaungol! Die kommen an, nehmen sich, was sie wollen, und machen den Rest kaputt.\n\nIch kann nicht zulassen, dass diese Rohlinge den letzten Rest der Yaksalberei hier zerstören. Das ist alles, was meinem Jungen und mir geblieben ist.\n\nGeht rüber zu unserem alten Hof und gebt den Yaungol ordentlich was auf die Futterluke. Ich wette, wenn Ihr genug von denen erledigt, überlegen sie es sich zweimal, bevor sie hier nochmal angreifen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30491] = {title = "In der Yaksalberei", objective = "Bringt 6 entlaufene Yaks zum Eingang der Yaksalberei Lao & Sohn.", description = "Mein Vater ist einfach verrückt. Ich liebe ihn, aber er ist nun mal verrückt.\n\nDiese Yaungol haben unseren Hof vollständig auseinander genommen und unsere Yaks in alle Windrichtungen vertrieben.\n\nAber wie ich meinen Vater kenne, wird er sich in den Kampf gegen die Yaungol stürzen, um die Yaks zurückzubekommen.\n\nKönntet Ihr uns helfen und einige der Yaks zusammentreiben, damit mein Vater keine Dummheiten anstellt?\n\nTreibt sie einfach rüber zur Yaksalberei, damit wir sie sauber machen und an die Grummel verkaufen können.", progress = nil, completion = "Gut gemacht, Fremder! Hoffentlich bekommen wir gutes Geld für sie, damit wir einige der Schäden kompensieren können, die die Yaungol angerichtet haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30492] = {title = "Sauberes Yak, gutes Yak", objective = "Bringt die gewaschenen Yaks zu Achtgroschen dem Glückspilz auf dem Grummelbasar am Kun-Lai-Gipfel. Kehrt zu Moschuspranke Jr. zurück, solltet Ihr die Yaks verlieren.", description = "Ich habe nicht gelogen, als ich über Eure Belohnung sprach. Hier, bitte führt diese Yaks zum Karawanenführer Achtgroschen.\n\nIhr findet ihn auf dem Grummelbasar westlich von hier. Er wird für sie bezahlen und Euch auch einen kleinen Lohn für die Lieferung geben.\n\nEr ist von kleiner Statur, aber unser größter Kunde.\n\nKehrt zu mir zurück, wenn Ihr die Yaks verlieren solltet. Meistens laufen sie dann sowieso wieder direkt hierher zurück. Aber natürlich erst, wenn sie gewaschen sind.", progress = nil, completion = "Ah! Ich kann das Glück von hier aus riechen. Die Moschuspranken haben immer gute Yaks zum Verkauf.", rewards = "Münze der SegnungMünze der glücklichen FügungMünze des GlücksfallsMünze des GlücksGlückbringende MünzeDer folgende Zauber wird auf euch gewirkt:\n\nDespawn Anointed Yak Herd\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30495] = {title = "Liebesdienst", objective = "Bringt die Jade zu Historiker Dinh, Feldmesser Sawa, Drachenmeister Shoku und Bauleiterin Emi.", description = "Kann ich Euch um einen weiteren Gefallen bitten?\n\nWir liegen im Zeitplan zurück, und diese Jadelieferung ist die letzte, die zur Vollendung der großen Statue fehlt.\n\nIch habe alle Hände voll zu tun, könntet Ihr das Erz vielleicht zu den anderen Vorarbeitern bringen?\n\nIhr findet Historiker Dinh, Feldmesser Sawa und Drachenmeister Shoku am Fuße der Statue. Bauleiterin Emi leitet die Produktion an der Spitze der Statue.\n\nWir haben nicht mehr viel Zeit, also beeilt Euch! Die Zeit ist knapp!", progress = nil, completion = "Was, schon erledigt? Ihr seid wirklich schnell, &lt;Klasse&gt;. Habt Ihr je überlegt, damit Euren Lebensunterhalt zu verdienen?", rewards = "Medaillon der zirpenden GrilleHainvipernmedaillonKorallnattermedaillonFlammenbräumedaillonBernfliegengötzeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30496] = {title = "Der Stab des Wassersprechers", objective = "Holt Wassersprecher Gorais gestohlenen Ritualstab der Tintenkiemen von Orachi am Tintenkiemenweiher zurück.", description = "Es herrscht große Uneinigkeit am Tintenkiemenweiher, <Volk>. Der Älteste Shai Hu hat vom Sha-verderbten Wasser des Weihers getrunken und die anderen gezwungen, es ihm gleichzutun. Als ich protestierte, hat Orachi von der Stadtwache meinen Ritualstab konfisziert und mich verbannt.\n\nNun bin ich nicht nur im Exil, sondern kann überdies auch nicht mehr mit den Wassern reden, die mir einst Rat spendeten!\n\nIch bin kein Kämpfer, aber Ihr... vielleicht könnt Ihr ja Orachi meinen Stab entreißen? Ihr findet ihn in der Stadt nördlich von hier.", progress = "Habt Ihr den Stab gefunden?", completion = "Gut. Dann können wir dieses Problem vielleicht doch noch lösen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30498] = {title = "Kommt zurück!", objective = "Meldet Euch bei Admiral Taylor im Dorf der Perlflossen.\n\nBereitgestellter Gegenstand: \n", description = "Oh, bevor ich es vergesse, ich habe hier etwas, das ich Euch übergeben soll. Ein Brief von einem Eurer Kameraden, nehme ich an.\n\nMan hat mir zu verstehen gegeben, dass Eure Anwesenheit dringendst erforderlich ist, deshalb habe ich mir die Freiheit genommen, Eure Reise vorzubereiten.\n\nSprecht mit Ginsa Pfeilauge, direkt südlich von hier, wenn Ihr bereit seid. Sie hat einen Drachen für Euch.", progress = nil, completion = "Willkommen zurück, &lt;Name&gt;. Ich gehe davon aus, dass Ihr bei Eurer Reise neue Eindrücke gewinnen konntet, insbesondere hinsichtlich der Beschaffenheit des Landes. Es gibt noch viel zu tun, bevor wir in die Schlacht ziehen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30499] = {title = "Kommt zurück!", objective = "Kehrt zu General Nazgrim auf dem Flotschhügel zurück.\n\nBereitgestellter Gegenstand: \n", description = "Oh, bevor ich es vergesse, ich habe hier etwas, das ich Euch übergeben soll. Ein Brief von einem Eurer Kameraden, nehme ich an.\n\nMan hat mir zu verstehen gegeben, dass Eure Anwesenheit dringendst erforderlich ist, deshalb habe ich mir die Freiheit genommen, Eure Reise vorzubereiten.\n\nSprecht mit Ginsa Pfeilauge, direkt südlich von hier, wenn Ihr bereit seid. Sie hat einen Drachen für Euch.", progress = nil, completion = "Throm-Ka, &lt;Name&gt;! Ich hoffe, Ihr konntet bei Eurer Reise durch den Wald nützliche Informationen sammeln.\n\nUnsere Vorbereitungen sind fast abgeschlossen, aber wir benötigen noch Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30500] = {title = "Negative Konsequenzen", objective = "Vernichtet 10 Sha-Echos.", description = "Pandaria ist ein mystisches Land, <Reisender/Reisende>.\n\nEs kann nicht oft genug wiederholt werden, dass einige seiner Geheimnisse selbst Lehrensuchern verborgen sind.\n\nDas Schließen dieser Risse hat nicht geheilt, was zerbrochen war.\n\nSollten die Sagen wahr sein, so bedarf es sehr viel mehr, um dieses Land dem Griff des Sha zu entreißen.\n\nDie aggressiven Emotionen aus dem Kampf haben einen Schwarm von lebenden negativen Gefühlen geweckt. Was Ihr hier seht, sind vermutlich die ersten von vielen dieser Manifestationen.\n\nFür den Moment können wir nichts anderes tun, als zu versuchen, ihre Präsenz zu verringern.", progress = nil, completion = "Das ist schrecklich…\n\nWir müssen einen Weg finden, um das, was hier geschehen ist, wieder rückgängig zu machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30501] = {title = "Gossip Accept Quest Test Case", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30502] = {title = "Mitten ins Herz", objective = "Benutzt Brocken himmlischer Jade, um 6 Sha-Rückstände zu vernichten.", description = "Die mächtigeren Rückstände der schrecklichen Manifestation sind vielleicht zu stark, als dass Ihr Euch alleine darum kümmern könntet, <Name>.\n\nIch fürchte, ich kann Euch nur wenig im echten Kampf unterstützen, aber ich kann Euch eine Lösung vorschlagen.\n\nDie große Jadestatue sollte schon bald eine lebendige Schlange werden - eine unserer verehrten Himmlischen. Ihre Erschaffung hat sie mit besonderen Kräften erfüllt, die diese Gegner ausreichend schwächen könnten.", progress = nil, completion = "&lt;Cho blickt Euch niedergeschlagen an.&gt;\n\nDiese Jade war für… so viel mehr gedacht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30504] = {title = "Notfallplan", objective = "Benutzt Chos Feuerwerk in der Nähe von General Nazgrim, Schattenmeisterin Kiryn, Shokia und Nieti Kuppelplopp.", description = "Eure Kameraden haben sich in unseren Landen eine neue Heimat errichtet und einen gefährlichen Zwist mit sich gebracht.\n\nDas volle Ausmaß der Vernichtung können wir hier noch nicht abschätzen, doch bereits jetzt ist es… unaussprechlich.\n\nUnd doch, Eure Freunde aus Rachegefühlen sich selbst zu überlassen, würde unserer Art zu leben widersprechen. Jeder, der jetzt noch am Leben ist, ist zweifelslos verwundet und bedarf dringend Hilfe.\n\nDieses Feuerwerk war eigentlich dazu gedacht, die Fertigstellung der Statue zu feiern. Benutzt es in der Nähe Eurer Kameraden, um Mishi ein Zeichen zu geben, und sie wird sie in Sicherheit bringen.", progress = nil, completion = "Mit meinen Gedanken bin ich bei Euren gefallenen Begleitern, Reisender.\n\nMögen ihre Wunden gut heilen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMomo Appears Cloud\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30506] = {title = "Admiral Taylor ist erwacht", objective = "Sprecht mit Admiral Taylor in Binan am Kun-Lai-Gipfel.", description = "Anscheinend ist Euer Admiral Taylor von seinen Verletzungen erwacht. Er und seine Leute befinden sich oben im Haus des Apothekers in Binan.\n\nEr hat nach Eurer Anwesenheit verlangt.", progress = nil, completion = "&lt;Name&gt;, seid Ihr das? Ich kann gar nicht glauben, dass wir die Vernichtung der Jadeschlange überlebt haben.\n\nZumindest einige von uns.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30507] = {title = "Admiral Taylor ist erwacht", objective = "Sprecht mit Admiral Taylor in Binan am Kun-Lai-Gipfel.", description = "Anscheinend ist Euer Admiral Taylor von seinen Verletzungen erwacht. Er und seine Leute befinden sich oben im Haus des Apothekers auf der anderen Straßenseite.\n\nEr hat nach Eurer Anwesenheit verlangt.", progress = nil, completion = "&lt;Name&gt;, seid Ihr das? Ich kann gar nicht glauben, dass wir die Vernichtung der Jadeschlange überlebt haben.\n\nZumindest einige von uns.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30508] = {title = "Admiral Taylor ist erwacht", objective = "Sprecht mit Admiral Taylor in Binan am Kun-Lai-Gipfel.", description = "Anscheinend ist Euer Admiral Taylor von seinen Verletzungen erwacht. Er und seine Leute befinden sich oben.\n\nEr hat nach Eurer Anwesenheit verlangt.", progress = nil, completion = "&lt;Name&gt;, seid Ihr das? Ich kann gar nicht glauben, dass wir die Vernichtung der Jadeschlange überlebt haben.\n\nZumindest einige von uns.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30509] = {title = "General Nazgrim ist erwacht", objective = "Sprecht mit General Nazgrim in Binan am Kun-Lai-Gipfel.", description = "Anscheinend ist Euer General Nazgrim von seinen Verletzungen erwacht. Er und seine Leute befinden sich oben im Haus der Apothekerin in Binan.\n\nEr hat nach Eurer Anwesenheit verlangt.", progress = nil, completion = "Wo seid Ihr gewesen, &lt;Name&gt;? Schon gut. Wie Ihr sehen könnt, haben wir den Kampf bei der Jadeschlange überlebt.\n\nUnglücklicherweise... sie auch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30510] = {title = "General Nazgrim ist erwacht", objective = "Sprecht mit General Nazgrim in Binan am Kun-Lai-Gipfel.", description = "Anscheinend ist Euer General Nazgrim von seinen Verletzungen erwacht. Er und seine Leute befinden sich oben im Haus der Apothekerin auf der anderen Straßenseite.\n\nEr hat nach Eurer Anwesenheit verlangt.", progress = nil, completion = "Wo seid Ihr gewesen, &lt;Name&gt;? Schon gut. Wie Ihr sehen könnt, haben wir den Kampf bei der Jadeschlange überlebt.\n\nUnglücklicherweise... sie auch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30511] = {title = "General Nazgrim ist erwacht", objective = "Sprecht mit General Nazgrim in Binan am Kun-Lai-Gipfel.", description = "Anscheinend ist Euer General Nazgrim von seinen Verletzungen erwacht. Er und seine Leute befinden sich oben.\n\nEr hat nach Eurer Anwesenheit verlangt.", progress = nil, completion = "Wo seid Ihr gewesen, &lt;Name&gt;? Schon gut. Wie Ihr sehen könnt, haben wir den Kampf bei der Jadeschlange überlebt.\n\nUnglücklicherweise... sie auch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30512] = {title = "Westwindruhestätte", objective = "Sprecht mit Landarbeiter Bo und dem Ältesten Tsulan beim Yaungolvorstoß.", description = "<Admiral Taylor zuckt schmerzerfüllt zusammen.>\n\nDer Jadewald war eine Katastrophe. Anduin ist weg und wir haben gute Leute verloren. Wir haben nicht verhindert, dass die Horde weiter in den Kontinent vorrückt.\n\nAber ich glaube, ich habe eine Methode gefunden, um die Bevölkerung hier auf unsere Seite zu bringen. Ihr habt ihnen ja bereits geholfen, diese \"Yaungol\" abzuwehren, nicht wahr?\n\nIch habe gehört, dass die Yaungol die Westwindruhestätte, ein nahes Dorf, überfallen haben. Man sagt, dass zwei Gruppen von Überlebenden bei der Straße lagern, die nach Westen aus dem Ort führt.\n\nWenn wir ihnen helfen, ziehen sie es vielleicht in Betracht, sich der Allianz anzuschließen.", progress = "Ich werde erst ruhen, wenn mein Volk zurückgekehrt und dieses Dorf wiederaufgebaut ist.", completion = "Nun... wir leben und es geht uns besser als es ohne Eure Hilfe möglich gewesen wäre.\n\nAber wenn Ihr hier eine Operationsbasis errichten wollt und wir der Allianz beitreten sollen, dann müsst Ihr unsere Sicherheit gewährleisten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30513] = {title = "Die Ostwindruhestätte", objective = "Sprecht mit Landarbeiter Ko und dem Ältesten Shiao am Kun-Lai-Gipfel", description = "Ich bin zwar verwundet, aber wir können nicht einfach aufhören.\n\nDie Ho-zen haben sich als... unzuverlässig herausgestellt. Die Pandaren wären viel bessere Verbündete.\n\nIch bin mir sicher, dass Ihr die Flüchtlinge in diesem Dorf gesehen und von der Yaungolinvasion gehört habt.\n\nNun, wir haben von den Einheimischen gehört, dass die Ostwindruhestätte, ein Dorf in der Nähe, von den Yaungol zerstört worden ist.\n\nAnscheinend haben einige Überlebende sich an der Straße, die aus dem Ort führt, versammelt.\n\nGeht. Nehmt die Straße nach Westen. Versammelt die Überlebenden.\n\nWir werden sie beim Wiederaufbau unterstützten. Dann werden sie erkennen, welche Vorteile es hat, sich der Horde anzuschließen!", progress = nil, completion = "Nun... wir sind am Leben und das ist mehr, als wir ohne Eure Hilfe erhoffen durften.\n\nDoch bevor hier eine Operationsbasis für Euch entstehen kann und wir uns Eurer Horde anschließen, müsst Ihr noch eines tun, um unsere Sicherheit zu garantieren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30514] = {title = "Gipfelherausforderung", objective = "Setzt das Yaungolbanner in Flammen, um Ul-Bataar herbeizulocken, und besiegt ihn anschließend im Kampf.", description = "Die Yaungol waren zwar schon immer ein schwieriges, stolzes Volk, aber nie dermaßen gewalttätig oder aggressiv. \n\nIch weiß nicht, was diese Verhaltensänderung veranlasst hat, aber momentan haben wir keine Zeit, um den Grund dafür herauszufinden. Wir fürchten um unser Leben und unser Auskommen, solange Ul-Bataar, der Anführer der Bataariyaungol, am Leben ist.\n\nLos, setzt das Banner in seinem Lager in Brand, um ihn herauszufordern, und besiegt ihn dann im Kampf. Erst dann werden wir sicher sein.", progress = "Solange Ul-Bataar am Leben ist, wird es keinen Frieden geben.", completion = "Ihr habt es geschafft! Wenigstens hat die Gerechtigkeit gesiegt und wir sind nun sicher, aber auf dem Weg dorthin haben wir viel verloren.\n\nWie dem auch sei, es ist entschieden. Wir werden der Allianz beitreten und mit Eurer Hilfe dieses Dorf wieder aufbauen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAlliance Hub Swap Scene\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30515] = {title = "Gipfelherausforderung", objective = "Setzt das Yaungolbanner im Streitlager Bataar in Flammen, um Ul-Bataar herbeizulocken, und besiegt ihn anschließend im Kampf.", description = "Die Yaungol waren zwar schon immer ein schwieriges, stolzes Volk, aber nie dermaßen gewalttätig oder aggressiv. \n\nIch weiß nicht, was diese Verhaltensänderung veranlasst hat, aber momentan haben wir keine Zeit, um den Grund dafür herauszufinden. Wir fürchten um unser Leben und unser Auskommen, solange Ul-Bataar, der Anführer der Bataariyaungol am Leben ist.\n\nLos, setzt das Banner in seinem Lager in Brand, um ihn herauszufordern, und besiegt ihn dann im Kampf. Erst dann werden wir sicher sein.", progress = "Solange Ul-Bataar am Leben ist, wird es keinen Frieden geben.", completion = "Ihr habt es geschafft! Wenigstens hat die Gerechtigkeit gesiegt und wir sind nun sicher, aber auf dem Weg dorthin haben wir viel verloren.\n\nWie dem auch sei, es ist entschieden. Wir werden der Horde beitreten und mit Eurer Hilfe dieses Dorf wieder aufbauen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHorde Hub Swap Scene\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30516] = {title = "Den Hof pflegen I: Ein kleines Problem", objective = "Sammelt 6 Spinnenwurz für Gai Lan.", description = "Ihr müsst garstiges Unkraut beseitigen?\n\nKein Problem! Allerdings habe ich kaum noch Unkrautvernichter.\n\nIch habe da ein Eigengebräu - äußerst effektiv, komplett biologisch, gut für den Boden, die Pflanzen lieben es... nun... natürlich nicht dieses miese Unkraut! Das hat keine Chance!\n\nWenn Ihr mir etwas Spinnenwurz von den Terrassen westlich von uns bringen könnt, kann ich einen frischen Vorrat herstellen und persönlich Yoons Hof aufsuchen.\n\nIch würde es ja gerne selbst holen, aber... nun... ich hasse Spinnen. Ihr werdet verstehen, was ich meine.", progress = "Wie ist es mit dem Wurzelsammeln gelaufen?", completion = "Na, was haben wir denn da? Das wird eine Weile reichen.\n\nVielen Dank!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30517] = {title = "Bauer Fungs Stimme I: Yakangriff", objective = "Sprecht mit Bauer Fung im Kernland oder auf dem Halbhügelmarkt im Tal der Vier Winde.", description = "Das nächste stimmberechtigte Mitglied des Bundes der Ackerbauern ist Bauer Fung, was nicht verwunderlich ist.\n\nSein Gemüse ist nämlich das größte im ganzen Tal! Ich hoffe, dass ich eines Tages so große Kürbisse züchten kann wie er.\n\nWenn wir den Ackerbauern beitreten wollen, ist er der Nächste, den wir überzeugen müssen.", progress = nil, completion = "Oh? Ihr seid doch bei diesem neuen Bauern in der Stadt, oder?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30518] = {title = "Bauer Fungs Stimme II: In freier Wildbahn", objective = "Bringt 5 entlaufene Wollyaks zu Bauer Fungs Yakpferch am nördlichsten Ende des Grünen Gürtels zurück.", description = "Ihr wollt meine Stimme für Bauer Yoon? Hah! Das soll wohl ein Witz sein, oder?\n\nPasst auf, ich werde einer Stadtpfote, die überhaupt keine Ahnung von Landwirtschaft hat, bestimmt keine Stimme geben.\n\nEs wäre eine Schande, neben Euch oder diesem Trottel Yoon Dinge anzubauen.\n\nUnd jetzt erlaubt mir, mich um meine eigenen Probleme zu kümmern. Jemand Bösartiges hat meine Preisyaks aus ihrem Pferch herausgelassen und jetzt laufen sie nordwestlich von Halbhügel frei herum.\n\nWenn ich doch nur meine Yaks zurückbekäme, könnte ich nachts wieder schlafen.", progress = nil, completion = "&lt;Bauer Fung starrt Euch mit heruntergeklappter Kinnlade an.&gt;\n\nIch... Ich kann nicht fassen... dass IHR all meine erstklassigen Wollyaks wieder einfangen konntet!\n\nWisst Ihr... wisst Ihr überhaupt, wie viel mir das bedeutet?\n\nMeine Familie kennt sich nur mit zwei Dingen aus: dem Anbau gigantischen Gemüses und der Yakzucht.\n\nDie Wollyaks, die Ihr da seht, sind das Ergebnis der Arbeit von Generationen.\n\nIhr habt das Erbe meiner Familie gerettet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30519] = {title = "Nanas Stimme I: Nanas Geheimrezept", objective = "Sprecht mit Nana Lehmkrall in Halbhügel im Tal der Vier Winde.", description = "Die nächste Stimme, die wir brauchen, ist die von Nana Lehmkrall. Sie ist Haohans Großmutter und war schon Ackerbäuerin, bevor Ihr und ich auf die Welt kamen!\n\nSie arbeitet noch immer im Haus der Ackerbauern in Halbhügel. Warum besucht Ihr sie nicht?", progress = nil, completion = "Ja, Nana Lehmkrall... das bin ich. Ich bin zwar alt, aber mit meinem Gedächtnis ist noch alles in Ordnung. Bei dem alten Herrn Weißbart ist das allerdings eine ganz andere Sache.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30521] = {title = "Haohans Stimme I: Einbruch in der Hütte", objective = "Sprecht mit Haohan Lehmkrall im Kernland oder auf dem Halbhügelmarkt im Tal der Vier Winde.", description = "Das wird nicht einfach, <Name>.\n\nDie letzte Stimme, die wir brauchen, ist die von Haohan Lehmkrall, dem Vorsitzenden des Bundes der Ackerbauern.\n\nIch weiß, dass er uns zu Beginn nicht wohlgesinnt war. Aber wir haben schon so viel über die Landwirtschaft gelernt, dass er sich sicher umstimmen lassen wird!\n\nBitte sprecht mit ihm. Ihr könnt doch überzeugend auftreten, oder?", progress = nil, completion = "Was wünscht Ihr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30522] = {title = "Haohans Stimme II: Die wahren Schuldigen", objective = "Untersucht 8 verdächtige Fußspuren.", description = "Was macht IHR denn hier, Stadtpfote?\n\nAlso, ich habe schon alle Hände voll zu tun mit dem Einbruch in die Hütte im Westen. Einige Mistkerle sind dort mitten in der Nacht eingebrochen und haben sie geplündert.\n\nIch muss mich um verschwundene Samen, zerbrochene Werkzeuge und angebissenes Zubehör kümmern.\n\nIch werde es auf die Liste mit meinen anderen Sorgen setzen: ein gestohlener voll mit Melonen beladener Wagen; eine defekte Wasserpumpe; Ungeziefer, das mir die Ernte ruiniert...\n\nWenn ich all dem nur auf den Grund gehen könnte!", progress = nil, completion = "Hmmm, tut mir leid, hören zu müssen, dass Haohan bis zum Hals in der Klemme steckt. Danke, dass Ihr mir Bescheid sagt. Vielleicht können wir ihm helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30523] = {title = "Den Hof pflegen II: Der zerbrochene Wagen", objective = "Sprecht mit Fischi Rohrroder am Rohrkolbensee oder auf dem Halbhügelmarkt im Tal der Vier Winde.", description = "Hey <Name>. Seit meinem ersten Tag hier habe ich mir immer diesen Wagen angeschaut. Der ist ganz schön ramponiert, findet Ihr nicht?\n\nIch hab' in der Stadt gehört, dass Fischi Rohrroder gut mit Werkzeugen umgehen kann. Vielleicht kann sie ihn ja reparieren. Dann könnten wir dieses Stück Land in Ackerland verwandeln.\n\nWollt Ihr nicht mal mit ihr sprechen und sie fragen, ob sie diese Arbeit erledigen will?", progress = nil, completion = "Braucht Ihr bei irgendwas Hilfe? Da seid Ihr bei mir an der richtigen Adresse!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30524] = {title = "Den Hof pflegen II: Klopf auf Holz", objective = "Sammelt 100 gewachste Bretter zusammen.", description = "Klar! Ich kenne den Wagen, von dem Ihr erzählt habt!\n\nDen kann ich sofort reparieren, aber dafür brauche ich Holz.\n\nUnten auf dem Seegrund gibt es jede Menge davon. Wenn Ihr es denn gleich rausfischen könntet? Ha ha, fischen für Fischi - verstanden? Oh, manchmal könnt ich mich über mich selbst totlachen.\n\nAber bringt mir einfach etwas von dem Holz. Dann kann ich gleich anfangen!", progress = "Dieser See ist wirklich voller Schätze. Man muss nur wissen, wonach man suchen soll.", completion = "Ja! Das ist genau das richtige Holz. Gut gemacht, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30525] = {title = "Haohans Stimme III: Pures Gift", objective = "Sammelt 1 Blutblüte, 1 Höhlenlilie, 1 Geisterkappe und 1 Veilchenflechte ein.", description = "So, <Name>. Das ist die Gelegenheit für uns!\n\nLehmkralls Hof steckt in großen Schwierigkeiten. Diese Ho-zen aus den Bergen kommen des Nachts ins Tal, verwüsten seine Pflanzen und tun sich an seiner schwer verdienten Ernte gütlich.\n\nWir müssen sie ein für alle Mal loswerden, und ich weiß auch schon wie.\n\nMein Großvater hat mir seinerzeit gezeigt, wie man ein Verwundungsgift für das Ungeziefer auf der Farm mischt.\n\nDie Hauptzutaten dafür sind in den Höhlen der Shed-Ling im Norden zu finden.\n\nSchaut nicht so besorgt drein, <Name>! Ich bin ziemlich sicher, dass es funktionieren wird.", progress = "Auf die Ho-zen wartet eine große Überraschung!", completion = "Ihr habt die Zutaten? Gute Arbeit!\n\nUnd jetzt muss ich dieses Mittel herstellen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30526] = {title = "Einsam und allein", objective = "Besorgt 20 köstliche T-Bone-Steaks von den Himmelsweitenmushan auf der Himmelsweite im Tal der Vier Winde.", description = "Der hungrige und ausgemergelte Hund jault herzzerreißend und versucht kurz, mit dem Schwanz zu wedeln.\n\nEr sieht aus, als könne er eine gute Mahlzeit vertragen.", progress = "Die Augen des Hundes leuchten auf. Er scheint Euch wiederzuerkennen.", completion = "Beim Anblick der saftigen Steaks stellen sich die Ohren des Hundes steil nach oben.\n\nSobald Ihr sie hingeworfen habt, fängt der Hund gierig zu fressen an.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEntlaufenen Hund beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30527] = {title = "Haohans Stimme IV: Melonenmanie", objective = "Pflanzt und erntet 4 Streifenmelonen und bringt dann 20 Streifenmelonen zu Bauer Yoon.\n\nIhr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben. Nach dem Beackern und Pflegen Eurer Pflanze müsst Ihr bis zum nächsten Tag warten, um reife Streifenmelonen zu ernten.", description = "Nun, zufällig weiß ich, dass diese Ho-zen aus den Bergen süße Melonen lieben.\n\nHaohans letzte Melonenernte wurde gestohlen, also werden wir unsere eigenen züchten müssen.\n\nSobald wir sie ernten können, werden wir den Anführer dieser verdammten Ho-zen damit aus seiner Höhle locken!", progress = "Wir sehen lieber zu, dass wir ein paar anständige Melonen züchten, <Name>. Diese hinterhältigen Ho-zen mögen nur die süßesten Melonen.", completion = "Wow, &lt;Name&gt;! Wenn das keine dicken Melonen sind. Solche anzubauen ist kein Kinderspiel - ich sollte es wissen, denn ich habe es versucht! \n\nIch weiß nicht, wie ich diesen Betrieb ohne Euch schmeißen sollte, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30528] = {title = "Haohans Stimme V: Häuptling Yip-Yip", objective = "Tötet Häuptling Yip-Yip bei der Kunzen-Höhle im Nordwesten.", description = "Seid Ihr bereit für den letzten Teil des Plans?\n\nDie Ho-zen oben in Kunzen werden von einem grimmigen Häuptling namens Yip-Yip angeführt. Man sagt, dass er fast vollkommen unempfindlich gegen Schmerzen sei.\n\nIch habe die Melonen mit einem Gift injiziert, also versucht nicht, sie anzuknabbern!\n\nWenn Ihr seine Aufmerksamkeit erregt habt, werft die Melonen. Yip-Yip wird einer so süßen Streifenmelone nicht widerstehen können.\n\nWenn er hineinbeißt, wird er vorübergehend geschwächt sein, sodass Ihr Gelegenheit zum Angriff habt.", progress = nil, completion = "Der Ho-zen-Häuptling ist tot? Unser Plan hat funktioniert, &lt;Name&gt;!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nYoon beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30529] = {title = "Den Hof pflegen III: Der bemooste Felsbrocken", objective = "Sprecht mit Haohan Lehmkrall im Kernland oder auf dem Halbhügelmarkt im Tal der Vier Winde.", description = "Nachdem wir nun offiziell Mitglieder des Bundes der Ackerbauern sind, hat uns Herr Lehmkrall angeboten, uns beim Wegräumen dieses großen alten Felsens mitten in unserem Feld zu helfen.\n\nWenn dieser Stein dann weg ist, habe ich etwas Besonderes vor.\n\nLauft schnell runter und lasst ihn wissen, dass wir bereit sind.", progress = nil, completion = "Yoon braucht nachbarschaftliche Hilfe, wie? Dem kommen wir gerne nach.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30534] = {title = "Hofhelfer gesucht", objective = "Sprecht Euren besten Freund oder Eure beste Freundin an, ob er oder sie Lust hat, auf dem Gehöft Sonnensang zu arbeiten.", description = "Trotz all Eurer Bemühungen türmt sich die Arbeit auf dem Hof immer höher.\n\nVielleicht könnt Ihr ja Eure Freunde fragen, ob jemand von ihnen Lust hat, auf dem Gehöft Sonnensang zu arbeiten.", progress = nil, completion = "Die Talismane am Schrein klimpern leise im Wind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30535] = {title = "Agrikultur I: Samen", objective = "Sprecht mit Händler Grünfeld auf dem Halbhügelmarkt und erwerbt ein Päckchen mit Grünkohlsamen.", description = "Das Wichtigste zuerst! Ich werde hier eine Menge Hilfe benötigen.\n\nWenn wir Partner sein wollen, müsst Ihr lernen, wie man Pflanzen erntet. Und wenn man Pflanzen ernten will, muss man erst einmal Saat ausbringen!\n\nAlso, da gibt es einen Händler namens... Glühfell? Nein, der heißt... Fellgrün? Nein, auch nicht richtig...\n\nGrünfeld! Das war der Name! Bei ihm kann man Saatgut erwerben.\n\nGrünfeld hat einen Stand drüben auf dem Halbhügelmarkt, gleich südöstlich von hier. Geht zu ihm, um ein paar Gemüsesamen zu holen.", progress = "Alles klar, Partner? Habt Ihr die Samen von Grönkelt bekommen?\n\nÄhh ... Ich meine: Grünfeld.", completion = "Er hat mir zugewinkt! Und er hat Euch sogar die erste Packung Samen umsonst gegeben?\n\nWas für ein netter Kerl!\n\nIhr leistet wirklich gute Arbeit bis jetzt. Hier, für Euch... etwas Kohle für Kohlsamen. Hah!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30538] = {title = "Spaß für die Kleinen", objective = "Bringt 15 mit Archäologie aufgespürte Fossilienfragmente zu Professor Thaddeus Paleo beim Dunkelmond-Jahrmarkt.Kinder fragen so oft, was ein Archäologe tut und wie Archäologie funktioniert, dass ich eine kleine Demonstration für sie vorbereitet habe.\n\nIch vergrabe Artefakte und Fossilien im Sandkasten hinter dem Zelt. Die Kinder können sie ausgraben und so ihre eigenen Entdeckungen machen, lernen, wie man Knochen zusammensetzt und herausfinden, was ihnen die Archäologie über Geschichte beibringen kann.\n\nWürdet Ihr mir einige Fossilien für mein Projekt spenden, solltet Ihr welche übrig haben?", description = "Kinder fragen so oft, was ein Archäologe tut und wie Archäologie funktioniert, dass ich eine kleine Demonstration für sie vorbereitet habe.\n\nIch vergrabe Artefakte und Fossilien im Sandkasten hinter dem Zelt. Die Kinder können sie ausgraben und so ihre eigenen Entdeckungen machen, lernen, wie man Knochen zusammensetzt und herausfinden, was ihnen die Archäologie über Geschichte beibringen kann.\n\nWürdet Ihr mir einige Fossilien für mein Projekt spenden, solltet Ihr welche übrig haben?", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30565] = {title = "Ein unerwarteter Vorteil", objective = "Nehmt den Ho-zen-Wegelagerern im Osten die verschwundenen Getriebeteile mit Wasserschaden und rostigen Klemmbolzen wieder ab.", description = "In letzter Zeit scheint vermehrt alles zu unseren Gunsten zu laufen, <Name>. Auf einer Erkundungstour bin ich auf dieses Schätzchen gestoßen.\n\n<Sully deutet auf die Balliste zu seiner Rechten.>\n\nDas Problem ist, dass es eigentlich zwei sind, die andere aber in ihre Einzelteile zerlegt ist. Ich hätte sie inzwischen längst zusammengesetzt, wenn mir diese lästigen Grimmblicke nicht einige Getriebeteile und Bolzen abgenommen hätten.\n\nHey, Ihr scheint gut mit den Einheimischen umgehen zu können. Würdet Ihr dem alten Sully vielleicht ein wenig zur Hand gehen?", progress = "Habt Ihr die verschwundenen Getriebeteile und Bolzen gefunden?", completion = "Sie sind zwar nicht im besten Zustand, müssen aber reichen.\n\n&lt;Sully tätschelt die zerlegte Balliste.&gt;\n\nIch bringe sie in null Komma nichts auf Vordermann, Ihr werdet schon sehen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30567] = {title = "Blanches Hammerbräu", objective = "Schließt das Szenario Ein Sturm braut sich zusammen ab.", description = "Riecht Ihr es in der Luft? Ein Sturm braut sich zusammen. Da braue ich doch gleich mit!\n\nKommt hoch auf den Hügel, wenn der Sturm da ist, dann brauen wir gemeinsam ein Fässchen meines berühmtesten Gebräus. Kann ich auf Eure Hilfe zählen?", progress = nil, completion = "Gar nicht mal so schlecht, &lt;Klasse&gt;! Wir haben das Kloster gerettet und es ist immer noch ein halbes Fass übrig.\n\nDanke für Eure Hilfe!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30568] = {title = "Dem Ziel entgegen", objective = "Sprecht mit Karasshi dem Draufgänger, Amber Kearnen und Mishka.", description = "Willkommen zurück, <Name>! Anscheinend haben die Jinyu unsere Ausbildung besser umgesetzt als gedacht. Unsere Vorbereitungen sind fast abgeschlossen.\n\nIch brauche jemanden, der nach Amber, Karasshi dem Draufgäger und Mishka sieht. Fragt sie, ob sie Hilfe bei der Ausbildung brauchen.\n\nKarasshi und Mishka befinden sich hier, im Dorf der Perflossen. Amber bildet Rekruten in den Schlingschwanzgruben im Nordwesten aus.", progress = nil, completion = "Sehr beeindruckend, &lt;Name&gt;. Wir können bald aufbrechen. Mit unseren Verbündeten an unserer Seite wird uns niemand besiegen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30569] = {title = "Ärger auf dem Bauernhof", objective = "Sprecht mit dem Bauern Chow auf dem Bauernhof der Chows am Kun-Lai-Gipfel.", description = "Ich... Ich bin von Bauer Chows Hof südöstlich von hier entkommen. Er wurde von Yaungol eingenommen, aber der alte Mann und seine Frau wollen einfach nicht aufgeben!\n\nBitte, geht dorthin und unterstützt sie. Wenn Ihr das tut, wird er vielleicht ein paar Leute hierher schicken, die dabei helfen, Nahrung für die neue Stadt anzubauen.", progress = nil, completion = "Was für ein willkommener Anblick Ihr seid, &lt;Klasse&gt;.\n\nUnd ich will der Allianz wirklich gerne helfen. Aber zuerst müsst Ihr dafür sorgen, dass ich meinen Hof zurückbekomme.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30570] = {title = "Ärger auf dem Bauernhof", objective = "Sprecht mit dem Bauern Chow auf dem Bauernhof der Chows am Kun-Lai-Gipfel.", description = "Ich... Ich bin von Bauer Chows Hof südöstlich von hier entkommen. Er wurde von Yaungol eingenommen, aber der alte Mann und seine Frau wollen einfach nicht aufgeben!\n\nBitte, geht dorthin und unterstützt sie. Wenn Ihr das tut, wird er vielleicht ein paar Leute hierher schicken, die dabei helfen, Nahrung für die neue Stadt anzubauen.", progress = nil, completion = "Was für ein willkommener Anblick Ihr seid, &lt;Klasse&gt;.\n\nUnd ich will der Horde wirklich gerne helfen. Aber zuerst müsst Ihr dafür sorgen, dass ich meinen Hof zurückbekomme.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30571] = {title = "Rettet die Hofhelfer", objective = "Befreit 12 Bauernhofsklaven, indem Ihr die Aufseher von Ordo tötet.", description = "Diese Ordo-Yaungol lassen meine Hofhelfer sich zu Tode schuften! Das darf nicht geschehen.\n\nIch bitte Euch, <Klasse>: Rettet sie, bevor es zu spät ist.", progress = nil, completion = "Ihr seid ja wirklich zu etwas zu gebrauchen!\n\nObwohl... Ich glaube, es ist nicht fair, diese Arbeiter dazu zu zwingen, bei uns zu bleiben. Wir haben ja nicht mehr so viel Arbeit für sie...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30575] = {title = "Treibt sie zusammen", objective = "Treibt 3 Yaks der Wilden Ebenen zusammen und bringt sie zur Westwindruhestätte.", description = "Beweglichkeit wird von größter Bedeutung sein, wenn wir uns in diesem neuen Land behaupten wollen. Das Problem ist nur, dass man ohne Reittiere nicht besonders beweglich ist, und... nun, wir haben nicht viele von denen hier, nicht wahr?\n\nDie hiesigen Yaks scheinen gute Reittiere abzugeben. Zumindest sagen das die hiesigen Pandaren. Warum besorgt Ihr nicht ein paar für uns?", progress = nil, completion = "Diese Yaks sollten ausreichen. Gut gemacht, &lt;Name&gt;. Diese Situation gefällt mir schon viel besser.", rewards = "KafasatinmantelungKafabalgschiftungSchulterschutz des träumenden GeistesBrünierte KafaschiftungSeidene KafaamiciaKafalederschiftungSchulterschutz des YakhirtenSchwere KafaschulternGepanzerte KafaschulternIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30581] = {title = "Eintopf braucht Topf!", objective = "Besorgt 12-mal Wurzelgemüse und 1 gusseisernen Topf.", description = "Na klar, ich helfe Euch gerne. Aber auch wir müssen etwas essen! Ich habe noch nicht einmal einen Kochtopf! Ganz zu schweigen von Zutaten, die ich hinein tun könnte!\n\nHier ist eine Liste der Dinge, die ich brauche. Und jetzt macht Euch auf!", progress = "Habt Ihr alle Sachen von der Liste?", completion = "Na, da haben wir es doch. Das sollte wirklich mehr als ausreichend sein.", rewards = "Ihr bekommt:\n\nWurzelgemüseeintopf"}
MultiLanguageQuestData['de'][30582] = {title = "Die verschiedene Frau Moschuspranke", objective = "Bringt Lao MoschusprankeMoschusprankes Andenken zurück.", description = "Auf diesem schon reichlich abgenutzten Schmuckstück befinden sich zahlreiche Liebesbekundungen der verstorbenen Frau Moschuspranke.\n\nVielleicht hätte Lao das Schmuckstück seiner Frau gerne zurück.", progress = "Oh, was habt Ihr denn da?!", completion = "Einen wahren Wert erkennt man erst durch einen Verlust. Ich habe meine Frau schon vor ein paar Jahreszeiten verloren, aber heute ist der Tag, an dem mich ihr Lächeln am meisten trösten würde.\n\nZumindest muss sie nicht sehen, was diese Yaungol auf ihrem geliebten Hof angerichtet haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30583] = {title = "Blauer Zwerg braucht dringend Nahrung", objective = "Besorgt 160 Kun-Lai-Fleischbrocken.", description = "He da!\n\nWir brauchen dringend was zu essen, wenn wir hier für längere Zeit überleben wollen!\n\nIhr wisst es vielleicht nicht, aber ich bin selbst so etwas wie ein Koch. Warum geht Ihr nicht los und holt uns ein paar fleischige Brocken? Dann koche ich daraus etwas, und wir haben wochenlang zu essen! Oder wenigstens tagelang.", progress = "Nun... habt Ihr mein Fleisch?", completion = "Gute Arbeit! Ich sag' Euch, diese Kun-Lai-Fleischbrocken sind 1a Qualität!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30584] = {title = "Schockierend!", objective = "Angelt 7 Dojaniaale aus dem Dojani in der Krasarangwildnis.", description = "Habt Ihr schon einmal frischen Dojaniaal probiert, <Name>? Nein?\n\nNun, dann entgeht Euch aber einiges! Macht Euch zum Dojani im Norden auf und angelt uns ein paar von ihnen. Seid vorsichtig - diese Aale verpassen Euch einen Stromschlag, wenn Ihr nicht aufpasst!", progress = "Habt Ihr es geschafft, diese Aale zu fangen?", completion = "Das sieht nach ein paar schmackhaften Aalen aus, &lt;Name&gt;! Ich bin sicher, Ihr werdet sie lieben!", rewards = "Ihr bekommt:\n\nKnuspriger DojaniaalTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30585] = {title = "Was in der Tiefe lauert", objective = "Sucht einen uralten Angelteich bei den Krasarifällen im Nordwesten und fischt dort, um die Bestie aus ihrem Versteck zu locken.", description = "Den Legenden zufolge gibt es eine riesige Kreatur im Wald im Norden. Mein Sohn wird vermisst, und ich fürchte, er ist zu nah an ihren Unterschlupf geraten...\n\nGeht Richtung Nordwesten zu den Krasarifällen und haltet nach einem geheimnisvollen Strudel Ausschau - er ist der Schlüssel zu dem, was sich dort verbirgt. Tötet dieses üble Monster und sucht nach Hinweisen auf den Verbleib meines Sohns.", progress = "Gibt es Neuigkeiten über meinen Sohn?", completion = "Der Ring meines Sohns? Was bedeutet das?\n\n&lt;Rassan scheint nachdenklich zu sein.&gt;\n\nDie Situation ist hart, aber nicht hoffnungslos. Mein Sohn geht achtlos mit seinen Habseligkeiten um, also hat er den Ring vielleicht einfach in den Teich geworfen? Danke für Eure Hilfe, &lt;Name&gt;, ich werde nicht vergessen, was für einen großen Gefallen Ihr mir erwiesen habt.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30586] = {title = "Gezacktes Seeohr", objective = "Sammelt 9 Stück Seeohrenfleisch von gezackten Seeohren im Narsonggraben im Nordwesten.", description = "Die Pandaren haben über Generationen hinweg in dieser Gegend gezackte Seeohren geerntet. Jetzt ist es an der Zeit, dass Ihr das Ritual erlernt.\n\nSeeohren können gleich nordöstlich von hier im Narsonggraben gefunden werden. Aber seid vorsichtig - in der Nähe sind seit Kurzem vermehrt Haie gesichtet worden.", progress = "Habt Ihr da unten Haie gesehen?", completion = "Oh! Anscheinend habt Ihr eine Menge Seeohren dort draußen gefunden. Großartige Arbeit, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30587] = {title = "Hände weg von meinen Yaks!", objective = "Tötet 9 Räuber der Burilgi auf dem Gehöft Moschuspranke.", description = "Im Moment scheinen die Eindringlinge der Yaungol noch damit zufrieden zu sein, Yaks zu stehlen. Wenn Ihr das Gebiet näher untersucht, werdet Ihr jedoch feststellen, dass sie leicht jederzeit zur Yaksalberei weitergehen könnten.\n\nDas Ausdünnen ihrer Reihen würde den Yaungol vielleicht zeigen, dass dieses Gebiet gesichert ist.", progress = nil, completion = "Ich bin Euch wirklich sehr dankbar, dass Ihr ein paar dieser Yaungol für uns erledigt habt.\n\nIch hoffe, dass diese kleine Demonstration Eurer Stärke reichen wird, um sie davon abzuhalten, zu uns zu kommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30588] = {title = "Fischen mit blauem Auge", objective = "Tötet 8 Strandräuber der Flussklingen bei der Anglerexpedition westlich von der Anlegestelle der Angler.", description = "Der Klan der Flussklingen-Saurok greift eine unserer hiesigen Angelexpeditionen an! Sie brauchen sofort Hilfe!\n\nRäumt bei diesen Saurok auf und helft dieser Expedition, sicher zurückzukehren!", progress = nil, completion = "Die Expedition ist in Sicherheit. Vielen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30589] = {title = "Das Wrack abwracken", objective = "Sprecht mit Makael Bay im Pei-Wu-Wald.", description = "Um das Allianzschiff loszubekommen, müssen wir zuerst unseren Ingenieur finden. Unsere Wege haben sich getrennt, als wir aus dem Wrack geflohen sind.\n\nIhr solltet ihn irgendwo im Wald westlich von hier finden können. Sagt ihm, dass Korga Euch geschickt hat, und er wird seinen Posten wieder antreten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30590] = {title = "Vorsicht! Explosiv!", objective = "Bergt 6 Sprengsätze.", description = "Wir können Euch dabei helfen, das Schiff freizubekommen, aber um das zu bewerkstelligen, brauchen wir mehr von dem Sprengstoff, den wir uns von der Allianz zurückholen wollten.\n\nIch habe die Besatzung angewiesen, sich so viel Sprengstoff wie möglich zu schnappen, bevor wir uns zurückgezogen haben. Wenn Ihr die Trümmerteile und Leichname südlich von hier durchsucht, solltet Ihr einige Sprengstoffpakete finden können - zumindest die, die noch nicht in die Luft gegangen sind.\n\nBringt mir genug davon und ich werde Euch etwas Schönes zusammenbasteln...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30591] = {title = "Vom Jäger zum Gejagten", objective = "Tötet 9 Pei-Wu-Tiger.", description = "Der Wald ist deutlich gefährlicher geworden, seit Shen-zin Su begonnen hat zu beben. Die Tiger sind unruhig und haben begonnen, die Flüchtlinge anzugreifen - auch auf mich haben sie es nun abgesehen.\n\nFalls diese verletzten und geschwächten Überlebenden es bis hierher zur Hütte schaffen sollen, dann müssen wir ihnen den Weg freimachen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30592] = {title = "Der Jutepfad: Zum Basislager am Kota", objective = "Beschützt eine Gruppe Grummel auf dem Weg zur Zwischenstation des Jutepfads. Mindestens ein Grummel muss überleben.\n\nWenn Ihr die Grummel verliert, könnt Ihr den Jutepfad absuchen oder nach Einfass zurückkehren und warten, bis die nächste Gruppe aufbricht.", description = "Heute ist kein guter Tag für Grummel. Die Ho-zen haben angefangen zu plündern! Greifen unsere Versorgungslinie zum Schlangenrücken an.\n\nKönnt Ihr helfen? Wir sind keine Kämpfer. Wir sind Grummel. Das Glück lacht denen, die Grummeln helfen.\n\nGeht mit einer Gruppe Grummel zur Zwischenstation des Jutepfads. Beschützt sie. Sorgt dafür, dass wenigstens ein Grummel überlebt.\n\nGrummel geben Belohnung. Grummel geben immer Belohnung.", progress = "Viel Glück für Freunde der Grummel.", completion = "Habt Dank. Ich wünsche Euch Glück, Freund der Grummel. Aber der Weg zum Schlangenrücken ist noch nicht sicher.", rewards = "Ihr bekommt:\n\nRitualjutetasche"}
MultiLanguageQuestData['de'][30593] = {title = "Asche zu Leben zu Asche", objective = "Zerstört 14 Terrakottakrieger oder Terrakottawächter.", description = "Der Admiral erwartet, dass ich mich um ein großes Problem kümmere, aber meine Spezialität ist das Heilen und nicht das Kämpfen!\n\nDie Pandaren im Lager haben berichtet, dass im Nordosten, in Mogujia, irgendetwas die Statuen zu Leben erwachen lässt.\n\nKönntet Ihr mir in dieser Angelegenheit aushelfen, <Name>? Im Augenblick können wir uns einen Kampf mit dieser Armee Statuen einfach nicht leisten.", progress = nil, completion = "Na also! Sieht so aus, als ob wir uns nicht länger den Kopf über einen Haufen Statuen zerbrechen müssen. Gute Arbeit, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30594] = {title = "Asche zu Leben zu Asche", objective = "Zerstört 14 Terrakottakrieger oder Terrakottawächter.", description = "Ich habe hier so viel zu tun, <Name>. Ich könnte Eure Hilfe gebrauchen.\n\nIm Nordwesten gibt es einen Ort, den die Pandaren Mogujia nennen. Und durch irgendetwas dort werden die Statuen zum Leben erweckt. Unsere Pandarenfreunde hier sind deswegen wirklich beunruhigt.\n\nWenn sich nicht bald jemand darum kümmert, bekommen wir ein echtes Problem. Wir sind gerade erst angekommen. Wir können es uns gerade nicht erlauben, einen Krieg gegen eine Armee von Statuen zu führen.", progress = nil, completion = "Oh, Ihr habt Euch der Statuen angenommen? Gute Arbeit. Hier ist etwas für Eure Mühen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30595] = {title = "Historische Geschäfte", objective = "Sammelt 12 Relikte der Mogu.", description = "Lasst mich raten: Ihr seid hier, um Euch um die Mogustatuen zu kümmern, die zu Leben erwacht sind. Was für ein Zufall, denn ich bin hierher gekommen, um... öh... die Mogu zu erforschen.\n\nIch mache Euch einen Vorschlag: Wenn Ihr mir so viele Relikte der Mogu von da drinnen bringt, wie Ihr tragen könnt, bekommt Ihr einen Anteil. Von den... Forschungsgeldern.", progress = "Wo soll ich nur all diese Relikte unterbringen?", completion = "Du meine Güte! Also wirklich! Ich danke Euch, &lt;Name&gt;!\n\n\n\nJetzt wo Ihr den Weg geebnet habt, ziehe ich vielleicht selbst los. Nur noch ein paar Relikte aus den Außenbereichen. Nichts Gefährliches.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30596] = {title = "Ein Zandalari-Troll?", objective = "Tötet den Seelenerwecker der Zandalari.", description = "Während Ihr die erweckten Mogustatuen zerstört habt, hat Euch ein Troll mit dem unverwechselbaren Akzent der Zandalari verspottet.\n\nMit anderen Worten: Die Gefahr für die Westwindruhestätte ist nicht vorüber, bis er erledigt ist.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "WasserfallkapuzeMushanlederhelmHelm des träumenden GeistesKopfbedeckung des GleichmutsGugel des GeistbeugersHelm der lautlosen BlätterHelm des YakhirtenHelm des GipfelwächtersHelm der MauerwacheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30597] = {title = "Seltsamer runder Stein", objective = "Durchtränkt den Stein mit mehreren Goldlotus.", description = "Dieser wunderschöne Stein verfügt eindeutig über magisches Potenzial... zumindest für jemanden, der Erfahrung in Alchemie hat. Ihr seid Euch sicher, dass dieser Stein mit den richtigen, in Pandaria heimischen Kräutern äußerst nützlich werden könnte.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nMeditativer Alchemistenstein"}
MultiLanguageQuestData['de'][30598] = {title = "Wer hätte gedacht, dass Fische Eier mögen?", objective = "Besorgt ein makelloses Kranichei von den Narsongtürmen und fangt damit eine Silbergrundel.", description = "Große Kraniche haben über Generationen hinweg in dieser Gegend genistet. Die Narsongtürme bieten eine geschützte Umgebung, in der sie ihre Jungen großziehen können.\n\nIhre makellosen Eier sind bekannt dafür, einen exzellenten Köder für Silbergrundeln abzugeben. Beschafft ein Kranichei und findet heraus, ob auch Ihr eine Grundel fangen könnt!", progress = "Habt Ihr eine Silbergrundel gefangen?", completion = "Unglaublich, eine Silbergrundel! Ihr werdet wahrlich ein Angler, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30599] = {title = "Ein Affengötze", objective = "Werft die Leichname von Tak Tak, Dak Dak und Ko Ko auf ihren jeweiligen Altar.", description = "Früher hielten die Grummel die Ho-zen davon ab, alles zu verwüsten. Sie bestachen sie einfach mit Essen.\n\nAber jetzt haben die Bruchzahn-Ho-zen südlich von hier große, magische Götzenbilder. Der Uuk von Knatz hat ihnen beigebracht, wie sie durch Opfergaben Macht aus diesen Götzen ziehen.\n\nSie nutzen diese Magie, um Grummel zu töten!\n\nIhr müsst diese Götzen zerstören!\n\nZu jedem Götzen gehört ein Häuptling. Tötet den Häuptling und werft seinen Leichnam auf ihren Altar.", progress = "Ist Unglück, auf eigenem Altar geopfert zu werden.", completion = "Ein selbstbewusster Ho-zen ist ein gefährlicher Ho-zen.\n\nDanke für Eure Hilfe, Freund der Grummel.", rewards = "Ihr bekommt:\n\nHo-zen-Götze"}
MultiLanguageQuestData['de'][30600] = {title = "Es bleibt kein Paket zurück", objective = "Bergt 8 Grummelranzen aus dem Bruchzahnlager oder Der Tieferen.", description = "Die Ho-zen der Bruchzahn südlich von hier haben alle meine Grummel getötet. Was noch schlimmer ist, ihre Pakete wurden nicht abgeliefert.\n\nDem Glück missfällt ein Grummelpaket, das nicht ausgeliefert wird.\n\nBitte, gebt meinen Grummel Frieden auf dem langen Weg ins Jenseits und bringt mir ihre Grummelpakete.\n\nIch werde dafür sorgen, dass sie ausgeliefert werden.", progress = "Grummel sind einfach Leute. Wir geschaffen für erkunden und tragen.", completion = "Ihr bringt Grummel Glück.\n\nWenn wir wieder im Hauptlager sind, muss ich Euch das geruchsintensivste, glückbringendste Räucherstäbchen kaufen, das ich finden kann.", rewards = "Ihr bekommt:\n\nGrummelbündel"}
MultiLanguageQuestData['de'][30601] = {title = "Mut auf Bestellung", objective = "Veranlasst 3 versteckte Bergführer in der Höhle der heulenden Winde Euch zu helfen.", description = "Es ist größtes Unglück, Bergpfade ohne guten Führer zu passieren. Wir Grummel haben die besten Führer, aber viele weggerannt. Sie fürchten sich jetzt vor dem Bergpass. Viele gute Grummel dort oben verschwunden.\n\nGrummel gut bei vielen Dingen, aber nicht sehr tapfer. Vielleicht Ihr könnt sie mit Feuerlotusräucherwerk tapfer machen. Dann führen sie Euch.", progress = nil, completion = "Räucherkrams wirkt wie Zauber! Aber Wirkung ist nicht lang. Ihr müsst Euch beeilen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30602] = {title = "Die Hasenpfote", objective = "Rettet Bruder Hasenpfote aus dem Bruchzahnaußenposten.", description = "Die Bruchzahn-Ho-zen haben unseren Hasenpfote gestohlen! Er war der Grummel mit dem größten Glücksbringer.\n\nDas ist großes Pech. Bitte, <Volk>, bringt uns Hasenpfote zurück. Wir brauchen sein Glück.\n\nWürdet Ihr im Bruchzahnaußenposten nach ihm suchen?", progress = nil, completion = "Seht nur, was Bruchzahns und Faustkloppers mit Grummel-Wegstation gemacht haben. Kaum noch Glücksbringer zu finden.\n\nGrummel hatten Vereinbarung mit Ho-zen. Wir geben Nahrung, sie nicht plündern. Immer wenn sie plündern wollen, erinnern Shado-Pan sie, nicht zu plündern.\n\nAber jetzt alle Shado-Pan weg, die Mauer verteidigen. Und Ho-zen wollen mehr Nahrung, als Grummel haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30603] = {title = "Der Bruchzahn-Plot", objective = "Nehmt Mo Mo Hasenpfotes Glücksbringer wieder ab.", description = "Sie stehlen meinen Glücksbringer! Ihr Ho-zen-Anführer hier, Mo Mo, stiehlt meine Hasenpfote.\n\nDas ist großes Unglück für Grummel. Meine Hasenpfote ist großes Glücksbringer für Grummel überall. Wenn die Ho-zen lernen, wie Hasenpfote Glück bringt, ist alles verloren.\n\nBitte, könnt Ihr sie zurückholen?", progress = "Grummel erhalten Namen von Glücksbringer, das diese Grummel am meisten Glück bringt. Ho-zen dürfen niemals stehlen Glück.", completion = "Mein Glücksbringer! O, dies ist ein Glückstag! Vielen Dank!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30604] = {title = "Bruchzähne brechen", objective = "Tötet 8 Bruchzahnstürmer und 6 Bruchzahnwerfer.", description = "Ho-zen plündern nur, wenn sie denken, Essen ist wenig für ihre Münder.\n\nAber bei den Ho-zen sind immer mehr Münder als Essen.\n\nJetzt gibt es nur noch sehr wenige Grummel.\n\nEs ist viel verlangt, aber könnt ihr <ein Freund/eine Freundin> der Grummel sein und einige der Bruchzahn-Ho-zen südlich von hier beseitigen? Nur so können wir sie abhalten, die Landschaft zu zerstören.", progress = nil, completion = "Danke, &lt;Name&gt;! Hoffentlich jetzt weniger Bruchzahn-Plündereien.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30605] = {title = "Glückbringendes Yakhufeisen", objective = "Rettet Bruder Yakschuh.", description = "Als Ihr fort wart, kam eine Gruppe Grummel den Jutepfad herunter. Ihr Anführer war mein Bruder Yakschuh.\n\nAber dann greifen Faustklopper an. Bringen meinen Bruder und seine Grummel nach Norden.\n\nBitte, $p! Rettet meinen Bruder. Er hatte immer Unglück, nie Glück, aber er ist mein Bruder. Sucht ihn am Altar vor Fort Silberrücken.", progress = nil, completion = "Glück, dass ein Glücksbringer wie Ihr mich rettet.\n\nUnd Bruder Hasenpfote sagt immer, ich hab' kein Glück. Pah!", rewards = "Ihr bekommt:\n\nGrummelkuchen"}
MultiLanguageQuestData['de'][30606] = {title = "Faustklopper kloppen", objective = "Tötet 8 Faustkloppzerkracher oder Faustkloppaufspieker im Faustklopploch.", description = "Die Faustklopp-Ho-zen haben neuen Häuptling, den Uuk von Knatz.\n\nEr sieht Angst im Westen, Zorn im Süden, Hass im Norden und Yaungol im Osten.\n\nAlso sorgt er dafür, dass seine Ho-zen plündern, um Nahrung und Vorräte für die kommende Dürre zu sammeln.\n\nEs sind viele Faustklopper und sie sind gefährlich.\n\nBitte, Glücksbringer, könnt Ihr ihre Kämpfer besiegen?", progress = nil, completion = "Ihr seid wahrer Glücksbringer.", rewards = "Weste der MauerwacheWeste des GipfelwächtersWeste des YakhirtenWeste der lautlosen BlätterWeste des GleichmutsWeste des träumenden GeistesMushanlederwesteAuf Euch wartet eine dieser Belohnungen:\n\nGeldbeutel des Helden\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][30607] = {title = "Entfesselte Kräfte", objective = "Holt den Schlüssel für Yetifesseln von Cho Cho dem Verruchten und lasst den Alten Müffel frei.", description = "Die Ho-zen haben einen Yeti! Sie nennen ihn Alter Müffel und halten ihn tief in ihrer Höhle.\n\nEigentlich haben die Ho-zen Angst vor Yetis, aber jetzt füttern sie ihn mit Grummeln.\n\nSie haben einen Jagdhäuptling, Cho Cho der Verruchte. Könnt Ihr nachsehen, ob er einen Schlüssel für die Fesseln des Yetis bei sich hat?\n\nPech für die Ho-zen, wenn ein Yeti frei in ihrer Festung herumläuft.", progress = "Glücksbringer sollte nicht auf dreckige Yak zu Yeti reiten.", completion = "Oh! War wilde Ritt, nicht wahr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30608] = {title = "Yetisnacks", objective = "Rettet 5 eingesperrte Grummel, indem Ihr sie losschneidet oder aus den Käfigen befreit.", description = "Sie haben meine Grummel mitgenommen! Ho-zen essen keine Grummel... Aber Yetis. Und Faustklopper haben Yeti.\n\nBitte rettet meine Grummel. Schneidet sie los. Oder befreit sie aus Käfig. Rettet so viele wie möglich.\n\nWenn gelingen, warten Glück und Belohnung auf Euch.", progress = nil, completion = "Heute ist ein Tag von gutem Glück und nicht so gutem Glück. Nicht so gutes Glück, dass Ho-zen meine Grummel geklaut haben. Gutes Glück, dass &lt;Volk&gt; meine Grummel gerettet hat. Nicht so gutes Glück, dass so viele Ho-zen sterben mussten, um Lektion zu lernen. Gutes Glück, dass &lt;Volk&gt; Glücksbringer ist und weiß, wie man kämpft.\n\nGrummel sind keine Kämpfer. Wir tragen, wir erkunden, wir sind zufrieden.", rewards = "WasserfallkordelMushanledergürtelTaillenschutz des träumenden GeistesSchnallengürtel des GleichmutsKordel des GeistbeugersGürtel der lautlosen BlätterGürtel des YakhirtenGurt des GipfelwächtersGurt der MauerwacheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30610] = {title = "Grummel! Grummel! Grummel!", objective = "Führt 5 unbeladene Grummel zu den Vorratskisten bei der Knatzelkuppe.", description = "Jetzt, wo Grummel gerettet sind, müssen wir unsere Vorräte retten.\n\nDer Uuk von Knatz ist nur Häuptling, weil er Vorräte hat.\n\nGeht zur Knatzelkuppel im Nordwesten. Nehmt ein paar Grummel mit. Beschützt sie und bringt sie in die Nähe der Vorratskisten.\n\nAb da wissen Grummel, was zu tun ist.\n\nHasenpfote und ich treffen Euch dort.", progress = "Grummel können gut Sachen tragen.", completion = "Jetzt wird dieser König der Ho-zen herausfinden, warum es Pech bringt, Grummel zu betrügen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30611] = {title = "Freiheit für den Yeti!", objective = "Tötet 4 Käfigmeister.", description = "Euer Yeti-Ritt bringt mich auf eine Idee. Der Uuk von Knatz hat einen Yeti als Haustier, heißt Mampf Mampf.\n\nMit Yeti schüchtert er andere Ho-zen ein, damit sie ihn zum Anführer von Ho-zen machen. Wir müssen Yeti loswerden.\n\nGeht zum Uuk von Knatz und besiegt ein paar Käfigmeister, damit Mampf Mampf nicht so fest angebunden ist.\n\nHufeisen und ich treffen Euch dort mit viel Räucherwerk und schmutzigem Yak.", progress = "Wir haben Yak gefunden. Habt Ihr Ho-zen ausgeschaltet?", completion = "Bereit für Yeti?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30612] = {title = "Der Anführer der Ho-zen", objective = "Provoziert Mampf Mampf und besiegt dann den Uuk von Knatz.", description = "Die Zeit ist gekommen, uns Uuk von Knatz zu stellen. Wir schlagen ihn, und die Ho-zen haben keinen mehr, der ihnen sagt, sie sollen plündern.\n\nDas ist der Plan: Hufeisen führt Quastel in die Arena und macht Mampf Mampf Angst, bis er fortläuft.\n\nDann schleicht Ihr hinein und kämpft gegen den Uuk von Knatz, während seine Ho-zen vom Yeti abgelenkt sind, der in ihrem Zuhause wütet.\n\nWir treffen Euch im Basislager am Kota mit einer großen Belohnung. Viel Glück für Euch, <Freund/Freundin> der Grummel.", progress = nil, completion = "Der Uuk von Knatz ist tot! Hurra!", rewards = "WasserfallhandschuheMushanlederhandschuheStulpen des träumenden GeistesHandschuhe des GleichmutsHandschützer des GeistbeugersHandschuhe der lautlosen BlätterStulpen des YakhirtenStulpen des GipfelwächtersStulpen der MauerwacheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30613] = {title = "Gepanzerter Karpfen", objective = "Benutzt den Fischspeer, um 5 gepanzerte Karpfen in den Gewässern südlich der Anlegestelle der Angler zu fangen.", description = "Gepanzerte Karpfen gelten in dieser Gegend als eine Delikatesse.\n\nLeider können wir sie nicht angeln, da ihre gewaltigen Kiefer kurzen Prozess mit unseren Haken machen. Nehmt diesen Fischspeer und versucht, einige für uns zu fangen.", progress = "Hattet Ihr Glück mit diesem Fischspeer?", completion = "Passt mit diesen Karpfen auf, &lt;Name&gt;. Die haben schon Leuten Finger abgebissen!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30614] = {title = "Ölprobe", objective = "Füllt die leere Ölphiole an einem Yaungolbohrturm.", description = "Als die Yaungol herkamen, begannen sie, nach Öl zu graben. Ich frage mich, was dieses \"Öl\" ist? Vielleicht ist es ein Ding von viel unentdecktem Glück. Das muss ich wissen.\n\nHier, nehmt diese Phiole und füllt sie mit Yaungolöl von einer der Windmühlen. Ich werde Euch Reichtümer geben, wenn Ihr mir etwas davon bringt.", progress = "Yaungol sind ganz gruselig. Yaungol mit einem Glücksbringer wie diesem \"Öl\" sind nur noch mehr ganz gruselig.", completion = "Glückstag! Eure Belohnung. Mögen Euch diese Münzen viel Glück bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30615] = {title = "Ein Zandalari-Troll?", objective = "Tötet den Seelenerwecker der Zandalari.", description = "Während Ihr die erweckten Mogustatuen zerstört habt, hat Euch ein Troll mit dem unverwechselbaren Akzent der Zandalari verspottet.\n\nMit anderen Worten: Die Gefahr für die Westwindruhestätte ist nicht vorüber, bis er erledigt ist.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "WasserfallkapuzeMushanlederhelmHelm des träumenden GeistesKopfbedeckung des GleichmutsGugel des GeistbeugersHelm der lautlosen BlätterHelm des YakhirtenHelm des GipfelwächtersHelm der MauerwacheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30616] = {title = "Verkehrsprobleme", objective = "Besiegt 8 Yaungol des Streitlagers Ruqin.", description = "Yaungol greifen unseren Jutepfad an. Das ist großes Unglück für Grummel.\n\nWir nutzen diesen Pfad, um Vorräte zum Schlangenrücken zu bringen. Ohne Vorräte sind die Verteidiger der Mauer in Gefahr.\n\nGrummel sind Träger und Forscher, nicht Kämpfer. Könnt Ihr unser Glücksbringer sein und die Yaungolblockade beenden?", progress = nil, completion = "Großes Glück, dass &lt;Volk&gt; Grummel hilft. Auch großes Glück für Freund der Grummel.", rewards = "GlücksbringerringAndenken vom GrummelbasarJuteschleifeStreitlagerringRußquastenbandIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30617] = {title = "Unterstützung am Straßenrand", objective = "Entzündet acht Mal glückbringendes Juteräucherwerk entlang der Straße nach Einfass.", description = "Ein Glückspilz denkt daran, Räucherwerk auf einer Reise durch die Berge mitzunehmen. Je stärker der Glücksgeruch, desto besser.\n\nKönnt Ihr der Straße hinaus nach Einfass folgen und das Räucherwerk, das Ihr entlang des Wegs findet, entzünden?\n\nDas wird den Grummel, die die Straße entlangreisen, viel Glück bringen.\n\nBruder Flusenbeutel kann Euch viele Belohnungen geben. Sprecht mit ihm, wenn Ihr ankommt.", progress = nil, completion = "Willkommen in Einfass! Zugang zum Jutepfad und zum Nimmerlaya.", rewards = "Ihr bekommt:\n\nSilbersalbeiräucherwerk"}
MultiLanguageQuestData['de'][30618] = {title = "Neue Ware für Einfass", objective = "Bergt 8 gestohlene Vorräte aus der Heulwindhöhle.", description = "Wenn Ihr nach den besten Vorräten am Kun-Lai sucht, seid Ihr hier genau richtig! Oh sicher, es sieht etwas leer aus. Doch lasst Euch nicht von Äußerlichkeiten täuschen...\n\nAch, wem will ich denn etwas vormachen?! Die Angriffe der Ho-zen sowie die Tatsache, dass die wenigen Vorräte, die wir bekommen, von den Geistern gestohlen werden, haben meinen Bestand besorgniserregend verringert.\n\nWenn Ihr mir helfen könntet, einige meiner Vorräte zurückzubekommen, dann habe ich wahrscheinlich genug, um etwas zu Eurer Reise beizusteuern.", progress = "Habt Ihr einige meiner Waren wiedergefunden?", completion = "Oh, ich danke Euch, &lt;Name&gt;! Wenn ich jetzt die angenagten Stücke abschneide und die kleinen Schäden beseitige, kann ich die vielleicht noch verkaufen.\n\nWenn Euer Wagen bereit zur Abreise ist, werde ich die versprochenen Vorräte aufladen lassen.", rewards = "Handgelenkwickel der MauerwacheHandgelenkwickel des GipfelwächtersHandgelenksschützer des YakhirtenHandgelenkwickel der lautlosen BlätterHandgelenkwickel des GeistbeugersHandgelenkwickel des GleichmutsHandgelenkwickel des träumenden GeistesMushanlederhandgelenkwickelWasserfallhandgelenkwickelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30619] = {title = "Mogulasch", objective = "Tötet den Seelenerwecker der Mogujia.", description = "Ich weiß, Eure Freunde machen sich Sorgen um die belebten Statuen drüben in Mogujia, aber ich sage Euch, um was Ihr Euch wirklich Sorgen machen solltet.\n\nWo es belebte Statuen gibt, gibt es auch Mogu. Ich weiß zwar nicht, ob Ihr schon einmal einen gesehen habt, aber falls nicht...\n\nNun, es reicht zu sagen, dass Mogu üble, üble Nachrichten bedeuten.\n\nWenn man sich um ein Problem kümmert, muss man den Mogu finden, der dahinter steckt!", progress = nil, completion = "Das sind gute Nachrichten! Ihr habt unser aller Leben gerettet.\n\nIhr könnt Euch gar nicht vorstellen, wie viel Ärger die verursachen können.\n\nOder, na ja, jetzt könnt Ihr es Euch vielleicht doch vorstellen. So ungefähr. Fast.\n\nStellt Euch genau das vor, was Ihr Euch vorstellen würdet, und dann wäre es noch viel schlimmer und würde tausende Jahre lang andauern.", rewards = "WasserfallkapuzeMushanlederhelmHelm des träumenden GeistesKopfbedeckung des GleichmutsGugel des GeistbeugersHelm der lautlosen BlätterHelm des YakhirtenHelm des GipfelwächtersHelm der MauerwacheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30620] = {title = "Mogulasch", objective = "Tötet den Seelenerwecker der Mogujia.", description = "Ich weiß, Eure Freunde machen sich Sorgen um die belebten Statuen drüben in Mogujia, aber ich sage Euch, um was Ihr Euch wirklich Sorgen machen solltet.\n\nWo es belebte Statuen gibt, gibt es auch Mogu. Ich weiß zwar nicht, ob Ihr schon einmal einen gesehen habt, aber falls nicht...\n\nNun, es reicht zu sagen, dass Mogu üble, üble Nachrichten bedeuten.\n\nWenn man sich um ein Problem kümmert, muss man den Mogu finden, der dahinter steckt!", progress = "Habt Ihr ihn gefunden? Ist er tot? Nein? Oh oh. Macht mir doch keine Angst!", completion = "Das sind gute Nachrichten! Ihr habt unser aller Leben gerettet.\n\nIhr könnt Euch gar nicht vorstellen, wie viel Ärger die verursachen können.\n\nOder, na ja, jetzt könnt Ihr es Euch vielleicht doch vorstellen. So ungefähr. Fast.\n\nStellt Euch genau das vor, was Ihr Euch vorstellen würdet, und dann wäre es noch viel schlimmer und würde tausende Jahre lang andauern.", rewards = "WasserfallkapuzeMushanlederhelmHelm des träumenden GeistesKopfbedeckung des GleichmutsGugel des GeistbeugersHelm der lautlosen BlätterHelm des YakhirtenHelm des GipfelwächtersHelm der MauerwacheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30621] = {title = "Glücksbringer vermisst", objective = "Bringt Ji-Lu seinen Shed-Ling-Glücksfuß, sein Yakhufeisen, das vierblättrige Glückskleeblatt und die Goldmünze.", description = "Meine Reisen durch Kun-Lai haben mich zwei Dinge gelehrt: Erstens, sich niemals an einen schlafenden Yak heranzuschleichen, und zweitens, das Glück auf seiner Seite zu haben ist ein Muss, aber gar nicht so einfach.\n\nDie Grummel tragen stets einen Glücksbringer bei sich. Tja, und wenn ein einzelner Glücksbringer einem manchmal Glück bringt, dann müssen viele Glücksbringer das Glück doch garantieren!\n\nNach meiner Ankunft in Einfass sind mir meine Glücksbringer von diesen lästigen kleinen Geistern gestohlen worden. Ich wäre wirklich dankbar, wenn Ihr sie mir zurückholen würdet.", progress = "Habt Ihr meine Glücksbringer finden können? Glück kann man nämlich nie genug haben.", completion = "Danke! Anscheinend haben meine Glücksbringer Euch auch geholfen, &lt;Klasse&gt;. Während Ihr unterwegs wart, habe ich nicht gespielt und auch nicht meinen Karren verloren.\n\nIch würde ihn Euch gern für Eure Reise leihen. Außerdem muss ich einiges von diesem zwielichtigen Grummel zurückgewinnen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30622] = {title = "Es wird ausgeschwärmt", objective = "Tötet 15 Krieger der Ik'thik oder Verseucher der Ik'thik.", description = "Ohne die Mauer als Schutz haben wir keine Chance. Hättet Ihr nicht so viele Leute zusammenbekommen, stünde es schlecht um uns.\n\nMeldet Euch bei Wachkapitän Eichenschild - er sollte sich in der Nähe des Mauerdurchbruchs befinden. Tötet unterwegs so viele Mantis, wie Ihr könnt.\n\nWenn wir gewinnen, gewinnen wir. Falls wir verlieren, tun wir das nicht kampflos. Für Pandaria!", progress = nil, completion = "Meine Mauer... Ich habe mein ganzes Leben darauf verbracht...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30623] = {title = "Das Sha-mützel", objective = "Setzt Ken-Kens Maske 5 Schwadronskommandanten der Ik'thik auf und besiegt dann die Manifestationen der Angst, die herauskommen.", description = "<Mei zeigt zum Schlachtfeld.>\n\nSeht Ihr diese riesigen Mantiskommandanten dort draußen auf den Feldern? Sie haben eine seltsame Aura, die mich an die Traurigkeit erinnert, die wir in Zhus Wacht gesehen haben.\n\nVielleicht... stehen auch sie unter dem Einfluss des Sha?\n\nIch habe Ken-Kens Maske behalten - mit der hat er Yi-Mo das Sha ausgetrieben. Ich glaube, wenn wir sie den Mantis aufsetzen, können wir sie davon überzeugen, umzukehren.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30624] = {title = "Ein Bierchen in Ehren", objective = "Bringt etwas Bier zu den Wächtern von Zhu, den Priestern der Kranichschwingen, den Shado-Pan und den Nachtelfensiedlern.", description = "Ich hab' nachgedacht.\n\nWir haben ja das ganze Bier, das Chen gebraut hat, und die vielen Leute, die Ihr zusammengetrommelt habt. Wir sollten die beiden zusammenbringen.\n\nDa sind Leute auf den Feldern, die ihr Leben für Pandaria riskieren. Wir beide sollten denen zumindest ein, zwei Fässchen vorbeibringen.\n\nDann können sie mit ihren Krügen auf den Sieg anstoßen. Oder sie haben sich ein letztes Bierchen hinter die Binde gekippt, bevor sie von einem Mantis niedergemetzelt werden. Wie auch immer - ich will nicht, dass sie ohne ein gutes Bierchen im Bauch in den Kampf ziehen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30625] = {title = "Keine Schüler mehr", objective = "Findet die Kampfkunstschüler und helft ihnen dann, einen Blutwüter, eine Eier-Matrone, einen Sehnenreißer und einen Furchtschürer der Ik'thik zu erledigen.", description = "Diese fünf Schüler - diejenigen, die den verborgenen Meister gesucht haben - sind ganz alleine an die Front gegangen. Ich würde ihnen ja Shado-Pan als Unterstützung schicken, wenn ich noch welche erübrigen könnte.\n\nDa sind gefährliche Wesen in der Nähe der Mauer. Wenn Ihr diese Schüler findet, sorgt dafür, dass sie ihnen nicht zum Opfer fallen.", progress = nil, completion = "Die können so nicht mehr ewig weiterkämpfen. Sie sind zweifelsohne heldenhaft, aber ich will nicht, dass sie als Helden ihr Leben lassen müssen.\n\nEs ist an der Zeit, das Handtuch zu werfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30626] = {title = "Rückzug!", objective = "Meldet Euch bei Lun Mai in Steinpflug im Tal der Vier Winde.", description = "Ich ziehe die wenigen Truppen, die ich noch habe, zurück. Wir müssen uns bis zur Brauerei Sturmbräu oder sogar bis nach Halbhügel zurückziehen. Diese Entscheidung überlasse ich Wachkommandant Lun Mai.\n\nGeht Ihr voraus. Informiert den Kommandanten. Meine Shado-Pan werden kurz darauf folgen.", progress = nil, completion = "Ich verstehe.\n\nNun, wir haben alles gegeben. Es ist Zeit für eine Evakuierung, Leben zu retten und unsere Strategie zu überdenken, bevor diese Mantis das komplette Tal übernehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30627] = {title = "Retter von Steinpflug", objective = "Redet mit Fräulein Fanny in Steinpflug. Tötet dann mit ihrer Hilfe den Mantis-Koloss.", description = "Dieser Kommandant spricht hastig. Er hat die Waffe, die er braucht, um diese Schlacht zu gewinnen. Er hat EUCH.\n\n\"Aber das ist unmöglich\", sagt Ihr vielleicht.\n\nDas stimmt aber nicht. Es ist nicht unmöglich. NICHTS IST UNMÖGLICH.\n\nGeht jetzt, <Name>. Geht und rettet Steinpflug!", progress = "Es ist alles verloren, <Name>. Packt Eure Sachen. Wir machen uns auf nach Halbhügel.", completion = "Ich kann es nicht glauben! Ihr - ein fremder &lt;Volk&gt; - habt das geschafft, an dem die Shado-Pan bisher gescheitert waren. Ihr hattet Erfolg, als die MAUER versagte.\n\nVielleicht können wir dieses Dorf ja doch noch halten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30628] = {title = "Steinpflugs Dankbarkeit", objective = "Sucht die Truhe des Kommandanten und holt Euch Eure Belohnung.", description = "Noch eine letzte Sache, <Name>. Keine Sorge, es handelt sich nicht um einen weiteren Gefallen. Ihr habt heute schon genug Mantis getötet.\n\nWir haben kürzlich eine Lieferung hochqualitativer Rüstung vom Kun-Lai-Gipfel erhalten. Ich wollte das eigentlich für meine Leute aufheben... aber ich denke, niemand hat das mehr verdient als Ihr. Geht einfach in den zweiten Stock des Gasthauses hier in der Stadt.", progress = nil, completion = "Ihr seht hinein und findet dort...", rewards = "NayelitreterTodesrachenfußschützerTiefwildsabatonsNarsongschienbeinschützerAngkhaltreterFlussklingenstiefelSarjunsabatonsKorjanikriegsstiefelKriegsstiefel des DojaniIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30630] = {title = "In das Tal", objective = "Sprecht mit Matrone Vi Vinh im Schrein der Sieben Sterne im Tal der Ewigen Blüten.Ah, ich habe auf Eure Ankunft gewartet, <Reisender/Reisende>.\n\nIch wünschte, wir könnten uns unter besseren Umständen treffen, aber leider ist die derzeitige Situation im Tal alles andere als erfreulich.\n\nAber lasst uns im Moment nicht darüber sprechen. Besucht Matrone Vi Vinh im Schrein der Sieben Sterne.\n\nSie wird Euch dabei helfen, Euch einzuleben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ah, ich habe auf Eure Ankunft gewartet, <Reisender/Reisende>.\n\nIch wünschte, wir könnten uns unter besseren Umständen treffen, aber leider ist die derzeitige Situation im Tal alles andere als erfreulich.\n\nAber lasst uns im Moment nicht darüber sprechen. Besucht Matrone Vi Vinh im Schrein der Sieben Sterne.\n\nSie wird Euch dabei helfen, Euch einzuleben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30631] = {title = "Der Schrein der Sieben Sterne", objective = "Sprecht mit Jaluu dem Spendablen, Kuru dem Gutgelaunten, der Ältesten Lin und Matrone Vi Vinh im Tal der Ewigen Blüten.", description = "Schaut Euch diese Kreatur an. Direkt als wir ankamen, hat uns der Moguattentäter ohne jede Vorwarnung angegriffen.\n\nSein Klingenstreich galt dem Anführer des Goldenen Lotus. Es war ein sehr glücklicher Umstand, dass wir hier waren und den Angriff vereiteln konnten.\n\nNach diesem Angriff auf Zhi fürchte ich auch um die Leben derer, die das Tal bereits betreten haben.\n\nDie Verwalter bringen Eure Leute in der Stadt im Südosten unter. Geht und sprecht mit den Anführern. Sorgt für ihre Sicherheit.", progress = "Die Städte erwachen zu neuem Leben.", completion = "Gute Arbeit, &lt;Name&gt;. Willkommen in der Stadt.\n\nDennoch müssen wir wachsamer sein als zuvor, wenn wir für jedermanns Sicherheit sorgen wollen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30632] = {title = "Die Guo-Lai-Ruinen", objective = "Sprecht mit Anji Herbstlicht bei den Guo-Lai-Ruinen im Tal der Ewigen Blüten.", description = "Laut Zhi dem Harmonischen bewegen sich die Mogu aus Richtung der Guo-Lai-Ruinen im Westen in das Tal.\n\nIch habe Anji und Kun zum Erkunden der Situation ausgesandt, aber bis jetzt sind sie noch nicht zurückgekehrt.\n\nIch brauche jemanden, der so tapfer ist wie Ihr, <Klasse>, um nach ihnen zu suchen.", progress = nil, completion = "Leven schickt Euch? Ich hoffe, Ihr seid bereit für einen Kampf.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30633] = {title = "Nieder mit den Spähern", objective = "Tötet 8 Vorläufer der Shao-Tien.", description = "Uns wurde von Mogusichtungen im Tal berichtet, aber die Situation ist viel schlimmer als wir angenommen hatten.\n\nDie Ruinen im Nordwesten wimmeln von Spähern. Sie sammeln Informationen und stehlen Schätze.\n\nEuer Auftrag ist eindeutig: Erledigt alle Späher, denen Ihr begegnet. Ohne ihre Augen lässt sich eine Armee nicht bewegen.", progress = nil, completion = "Gut gemacht, &lt;Volk&gt;. Das sollte den Mogu verdeutlicht haben, dass mit uns nicht zu spaßen ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30634] = {title = "Donnernder Empfang", objective = "Sprecht mit Lao Samtfuß am Fuß des Ruinenberges und folgt ihm dann den Pfad hinauf. Deponiert dann das explosive Fässchen am Höhleneingang des Ruinenberges.", description = "Lao Samtfuß und ich haben die Ruinen im Norden ausgekundschaftet.\n\nOffensichtlich dringen die Mogu durch eine Höhle gleich da oben in den Bergen in das Tal ein. Und sie schicken auch bereits Verstärkungen auf diesem Wege durch.\n\nEs sind zu viele, um sie frontal zu bekämpfen, deshalb müsst Ihr Euch mit Lao Samtfuß am Eingang der Ruinen treffen.\n\nEr wird Euch helfen, dort unbemerkt hinein zu gelangen. Dann könnt Ihr dieses Sprengstofffass am Eingang der Höhle deponieren.\n\nDer Rest sollte sich dann von selbst erledigen.", progress = "Ist die Höhle etwa geschlossen?", completion = "Wunderbar, &lt;Name&gt;!\n\nIhr und Lao habt ganz allein den Moguvorstoß zunichtegemacht.\n\nSo geht man klug vor und macht sich die Arbeit leichter.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30635] = {title = "Tod den Qilen", objective = "Tötet 9 Steinwächter.", description = "Wir haben das Problem mit den Spähern vorerst gelöst, aber unten am Fuße der Berge, in den Guo-Lai-Hallen, treiben sich immer noch Vorstoßtruppen der Mogu herum.\n\nUnd leider werden ihre Operationen tiefer in den Ruinen von wilden und bösartigen Hunden bewacht.\n\nIch möchte, dass Ihr diese Bestien erledigt. Aber seid auf der Hut: Sie verstehen es, sich gut ihrer Umgebung anzupassen und sich zu verstecken.", progress = nil, completion = "Sehr gut. Diese Hunde kennen keine Gnade. Umso besser also, dass Ihr ihnen auch keine gewährt habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30636] = {title = "Steine der Macht", objective = "Sammelt 7 Jubelitkristalle ein.", description = "Vor vielen Tausend Jahren haben die Herrscher des Tals einen Kristall namens Jubelit als Energiequelle genutzt.\n\nMit seiner Hilfe konnten sie ganze Städte, Fabriken und ihre Kriegsmaschinerie mit Energie versorgen.\n\nZhi der Harmonische hat uns gebeten, einige Kristalle zu sammeln und in die Stadt zurück zu bringen.\n\nHaltet Ausschau nach ihnen, während Ihr in den Ruinen unterwegs seid.", progress = "Habt Ihr die Kristalle gefunden?", completion = "Ja, damit lässt sich etwas anfangen.\n\nIch werde sie sofort in das Lager bringen lassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30637] = {title = "Die Guo-Lai-Hallen", objective = "Untersucht die Anwesenheit der Mogu in den Guo-Lai-Hallen.", description = "Als Ihr die große Tür durchquert, vernehmt Ihr Geräusche aus dem Inneren.\n\nAnji hatte erwähnt, dass in dieser Gegend Späher der Mogu gesichtet wurden. Vielleicht sind sie bis in die Tiefen vor Euch eingedrungen.\n\nIhr seid alarmiert und entscheidet, die Sache näher zu untersuchen.", progress = "Was habt Ihr in den Hallen entdeckt?", completion = "Eure Instinkte haben Euch nicht getäuscht, &lt;Name&gt;.\n\nIn längst vergangenen Zeiten befanden sich mächtige Schätze in den Guo-Lai-Hallen.\n\nWir müssen den Mogukriegsfürsten um jeden Preis davon abhalten, in die versiegelten Gruften einzudringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30638] = {title = "Eine Passage schaffen", objective = "Sprecht mit Leven Morgenklinge an der Goldenen Pagode im Tal der Ewigen Blüten.", description = "Die Lage ist ernst.\n\nKun und ich werden die Situation hier im Auge behalten, aber Ihr solltet Euch zur Goldenen Pagode begeben.\n\nAlso los, beeilt Euch!", progress = nil, completion = "Greift Eure Waffen, &lt;Name&gt;! Ich dachte, wir würden mehr Zeit für die Vorbereitung der Verteidigung haben, aber die Mogu erweisen sich als ebenso tödliche wie intelligente Feinde.\n\nWir haben die Flüchtlinge und die Vorräte in die Stadt hinter uns geschafft.\n\nJetzt ist es unsere Pflicht, die Front zu verteidigen. Wir dürfen nicht zulassen, dass die Mogu auch nur einen einzigen Brückenkopf hier im Tal erobern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30639] = {title = "Die Geheimnisse von Guo-Lai", objective = "Trefft Hee Samtfuß in den Guo-Lai-Hallen und offenbart das Vorhaben der Mogu in der westlichen Kammer.", description = "Ich habe gerade Informationen von einer Wache erhalten, die bei den Guo-Lai-Ruinen stationiert ist, dass der Anführer der Shao-Tien in die Hallen eingedrungen ist und dabei zwei meiner Leute getötet hat. Sie haben etwas im Inneren vor und wir müssen sie aufhalten.\n\nHee Samtfuß ist ihnen bereits hinein gefolgt. Er sollte Euch am Eingang der westlichen Gemächer erwarten.\n\nSchnell, <Name>. Mir gefällt der Gedanke nicht, dass die Mogu uns einen Schritt voraus sein könnten.", progress = "Worauf wartet Ihr noch? Findet Hee. Haltet die Shao-Tien auf!", completion = "Die Shao-Tien sind dabei beobachtet worden, wie sie mit hundert Jadestatuen die Hallen verlassen haben. Die Mogu verfügen nun über eine gewaltige Jadearmee, die sie gegen uns einsetzen können, und wir müssen noch immer herausfinden, was sie im Tal vorhaben. Wir sind alle in Gefahr.\n\nIch hatte Euch und Hee für tot gehalten. Gut, dass ich zumindest hier falsch lag. Ruht Euch aus, erholt Euch. Vor uns liegen noch viele Kämpfe.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nFeines Zeichen des Goldenen LotusBrennendes Zeichen des Goldenen LotusHeilendes Zeichen des Goldenen LotusWildes Zeichen des Goldenen LotusRobustes Zeichen des Goldenen Lotus\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][30640] = {title = "Der Kriegsspeer des Donnerkönigs", objective = "Sichert den Kriegsspeer des Donnerkönigs.", description = "Ich habe beunruhigende Nachrichten erhalten, <Name>.\n\nDie Mogu planen, drei mächtige Artefakte aus dem Tal zu stehlen.\n\nWir müssen diese Artefakte sofort bergen und sicher vor ihnen verwahren.\n\nDas erste Artefakt ist der Kriegsspeer des Donnerkönigs.\n\nSeit dem Tod von Kaiser Lei Shen wird der Speer in einem uralten Schrein im Nordwesten verwahrt.\n\nBringt mir diesen Speer zurück.", progress = "Man sagt, dass die mächtigsten der uralten Mogu in der Lage waren, die Kräfte der Elemente zu beschwören.\n\nDer Donnerkönig selbst konnte die Kräfte des Blitzes auf seinen Speer übertragen.", completion = "Gut gemacht, &lt;Name&gt; - auch wenn es mich fast körperlich schmerzt, diesen verfluchten Speer anschauen zu müssen.\n\nDiese grauenvolle Waffe hat Tausenden Unschuldigen das Leben genommen.\n\nSo lange ich lebe, werden die Mogu nie wieder in seinen Besitz kommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30641] = {title = "Der Kriegshelm des Donnerkönigs", objective = "Sichert den Kriegshelm des Donnerkönigs.", description = "Das zweite Artefakt ist der Kriegshelm des Donnerkönigs.\n\nDer Kaiser Lei Shen hat diesen Helm in jeder Schlacht getragen. Der Helm wurde so berühmt, dass die Feinde schon allein bei seinem Anblick geflohen sind.\n\nAls der Kaiser starb, wurde der Helm in die unterste Ebene der Guo-Lai-Hallen im Westen gebracht - bewacht von Tausenden Terrakotta-Soldaten.\n\nAuf diese Weise konnten sie zu ihrem Anführer aufschauen und ihm in den Tod folgen.", progress = "Die Legende besagt, dass Lei Shen nur einen einzigen Feind fürchtete. Und schließlich war es der Tod, der ihn besiegte.", completion = "Ich danke Euch, &lt;Name&gt;.\n\nWährend unsere Soldaten die Mogu auf dem Schlachtfeld bekämpfen, arbeite ich daran, ihnen den Glanz ihrer Legenden zu nehmen.\n\nSchon bald wird Lei Shen nicht mehr als ein Schatten im Lauf der Geschichte sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30642] = {title = "Die Kriegsaxt des Donnerkönigs", objective = "Sichert die Kriegsaxt des Donnerkönigs.", description = "Das letzte Artefakt ist die Kriegsaxt des Donnerkönigs.\n\nLei Shen hat sich mit dem Speer in der einen und seiner Axt in der anderen Hand in die Schlachten gestürzt.\n\nMan sagt, dass er die Axt mit brutaler Genauigkeit werfen konnte und sie beim Aufprall auf das Ziel ein Geräusch wie einen Donnerschlag auslöste.\n\nNach seinem Tod wurde die Axt in einer Zeremonienkammer im Südwesten verwahrt.\n\nEs dürfte klar sein, dass sie nicht in die Hände der Mogu fallen darf.", progress = "Habt Ihr die Axt gefunden?", completion = "Eure Bescheidenheit ehrt Euch, &lt;Name&gt;. Ich habe bereits gesehen, dass Ihr die Axt sichern konntet. Gut gemacht.", rewards = "Feiner Brustschutz des Goldenen LotusKnisternde Kette des Goldenen LotusWärmender Brustschutz des Goldenen LotusWilde Platte des Goldenen LotusVerbundene Platte des Goldenen LotusZielwasserkette des Goldenen LotusRobuste Platte des Goldenen LotusBrennende Roben des Goldenen LotusHeilende Roben des Goldenen LotusIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30643] = {title = "Die bittere Botschaft der Mogu", objective = "Sprecht mit Zhi dem Harmonischen im Stillen Sanktum im Tal der Ewigen Blüten.", description = "Der brutale Kampf gegen die Mogu dauert nun schon eine ganze Weile. Und keine Seite weicht zurück.\n\nWir werden unsere Position nicht ewig halten können. Wir müssen den Mogu einen entscheidenden Schlag versetzen, von dem sie sich nicht wieder erholen.\n\nGeht und sprecht mit Zhi dem Harmonischen im Stillen Sanktum. Ich möchte seine Meinung in dieser Angelegenheit erfahren.", progress = nil, completion = "Zhi der Harmonische und die anderen Verteidiger wurden gnadenlos abgeschlachtet.\n\nIhr verspürt ohnmächtige Fassungslosigkeit, als Ihr realisiert, dass die Schätze des Donnerkönigs verloren sind!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMoguscharfrichter beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30644] = {title = "Tragische Entwicklungen", objective = "Sprecht mit Sun Zartherz an der Goldenen Pagode im Tal der Ewigen Blüten.", description = "Ihr solltet Euch besser umgehend bei der Goldenen Pagode melden.", progress = nil, completion = "Was?! Zhi der Harmonische... ist tot? Oh...\n\nIhr habt Euch angesichts der Umstände gut geschlagen. Ich bin mir sicher, dass ein weniger fähiger &lt;Klasse&gt; diesen Mördern unterlegen gewesen wäre.\n\nDie Dinge geschehen... so schnell. Wir alle müssen auf der Hut bleiben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30645] = {title = "Die Macht der Drei", objective = "Tötet 100 Mogueindringlinge auf den Sommerfeldern im Tal der Ewigen Blüten.", description = "Das war's, <Name>. Das ist das Ende.\n\nWenn wir die Mogu nicht aus dem Tal drängen können, werden sie die Artefakte ihrer uralten Macht erobern und mit ihrer Hilfe ganz Pandaria unterwerfen.\n\nAber unsere Streitmacht ist klein und die Kämpfer sind müde. Wir bluten, aber ihre Krieger sind aus Stein.\n\n<Name>, unsere Siegchancen sind äußerst gering, aber dennoch möchte ich Euch bitten, unseren Kämpfern zu helfen, die Mogu zurückzuschlagen.\n\nIch habe bereits zu den Himmlischen gebetet und um Hilfe gefleht. Ich hoffe nur, dass sie es auch vernommen haben.", progress = "Ich kann von hier aus nicht viel von der Schlacht sehen. Wie läuft der Kampf?", completion = "Was? Wie viele Mogu habt Ihr getötet?\n\nDas ist wirklich bemerkenswert! Wenn wir das überleben sollten, müsst Ihr mir alles erzählen, was geschehen ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30646] = {title = "Das letzte Gefecht", objective = "Tötet den Kriegsfürsten Zhao-Jin den Blutvergießer.", description = "Ich hätte nie gedacht, dass es so weit kommen würde!\n\nLeven hat sich dem Kriegsfürsten Zhao-Jin, dem Blutvergießer, auf dem oberen Abschnitt der Palasttreppe zum Kampf gestellt, aber unsere Verstärkungen kommen nicht durch!\n\nWir sind die einzigen, die zwischen ihm und den größten... und tödlichsten... Mächten des Tales stehen.\n\nBitte, <Name>, Ihr müsst einen Weg finden, ihn aufzuhalten!", progress = nil, completion = "Was Ihr heute erreicht habt, wird noch lange Zeit in den Geschichten fortleben.\n\nDank Eurer Hilfe konnten wir das Tal vor einem schrecklichen Feind beschützen.\n\nHeute haben wir den Mogu einen schmerzhaften Schlag verpasst. Ihre Versuche, das Tal zu erobern, werden nie aufhören. Aber es wird lange dauern, bis sie wieder einen groß angelegten Angriff starten können.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nBrennende Halskette des Goldenen LotusHeilende Halskette des Goldenen LotusRobuste Halskette des Goldenen LotusFeine Halskette des Goldenen LotusWilde Halskette des Goldenen Lotus\n\nDer folgende Zauber wird auf euch gewirkt:\n\nLeven Morgenklinge beschwören\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][30648] = {title = "Es geht voran", objective = "Sprecht mit Fei und reist ins Tal der Vier Winde.", description = "Eure Reise in dieses Land hat sich bereits als sehr ereignisreich erwiesen, <Reisender/Reisende>. Und die meine, so scheint es, ist bestimmt, noch ein wenig weiterzugehen.\n\nEine Kette von Ereignissen wurde in Gang gesetzt, als die Euren hier ankamen und auch wenn einige von ihnen traumatisch wirken, so fühle ich doch, dass es einen größeren Sinn hinter Eurer Anwesenheit geben muss.\n\nFür den Moment ist es am weisesten, wenn Ihr diesen Ort verlasst und Pandaria weiter erforscht.\n\nSprecht mich an, wenn Ihr bereit seid, weiterzuziehen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30649] = {title = "Der Schrein der Zwei Monde", objective = "Sprecht mit Jaluu dem Spendablen, Mokimo dem Starken, dem Ältesten Liao und Madame Vee Luo im Tal der Ewigen Blüten.", description = "Schaut Euch diese Kreatur an. Direkt als wir ankamen, hat uns der Moguattentäter ohne jede Vorwarnung angegriffen.\n\nSein Klingenstreich galt dem Anführer des Goldenen Lotus. Es war ein sehr glücklicher Umstand, dass wir hier waren und den Angriff vereiteln konnten.\n\nNach diesem Angriff auf Zhi fürchte ich auch um die Leben derer, die das Tal bereits betreten haben.\n\nDie Verwalter bringen Eure Leute in der Stadt im Südosten unter. Geht und sprecht mit den Anführern. Sorgt für ihre Sicherheit.", progress = "Die Städte erwachen zu neuem Leben.", completion = "Gute Arbeit, &lt;Name&gt;. Die Stadt sollte jetzt sicher sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30650] = {title = "Gefangene Pandaren", objective = "Befreit 8 Pandarengefangene.", description = "Seht, ich weiß ja, dass die Allianz Rekruten braucht und momentan nicht genug von uns in dieser Stadt sind, um sie kampfbereit zu machen.\n\nIch weiß aber, dass die Yaungol drüben im Streitlager Ordo im Nordwesten viele meiner Leute gefangen halten. Und ich weiß auch, dass sie höchstwahrscheinlich dazu bereit wären, sich der Allianz anzuschließen, wenn Ihr sie befreien könntet.\n\nWas meint Ihr, <Name>?", progress = nil, completion = "Das war wirklich heldenhaft, &lt;Name&gt;.\n\nIch war mir wirklich nicht sicher, ob wir bei einem Kampf hier draußen eine Chance gehabt hätten, wisst Ihr?\n\nDiese Leute mögen vielleicht noch etwas ungehobelt sein, aber wir werden sie schon in Form bringen. Und wenn wir damit fertig sind, haben wir eine echte Chance, wenn es darum geht, uns hier am Kun-Lai zu behaupten.\n\nGute Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30651] = {title = "Fässerweise Spaß", objective = "Verwendet die Sprengstofffässer im Streitlager Ordo, um die westlichen, südlichen und östlichen Bohrtürme zu zerstören.", description = "Ach, jetzt wollen wir erst einmal etwas Spaß haben, <mein Junge/Mädchen>!\n\nDiese Ordo-Yaungol im Nordwesten haben uns die Arbeit abgenommen, Bomben zu bauen. Sie haben sie nämlich schon dort.\n\nAlso, nehmen wir doch die Einladung an und zerstören ihre Ölförderpumpen mit ihren eigenen Sprengstofffässern. Was meint Ihr?", progress = nil, completion = "Ah, was für ein schöner Anblick das war. Ich hätte doch besser mit Euch dort hochgehen sollen, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nExplosives Fass"}
MultiLanguageQuestData['de'][30652] = {title = "Meditationen im Zelt", objective = "Tötet den Glutrufer, den Pyromanten, den Feuersprecher und den Flammenwirker von Ordo.", description = "Die Yaungol des Streitlagers Ordo sind eine echte Bedrohung. Ich möchte, dass Ihr Euch nach Nordwesten begebt und ihren Anführer ausschaltet.\n\nLeider halten uns seine vier Untergebenen mit einer Feuerbarriere davon ab, ihn in der angrenzenden Höhle zu stellen.\n\nErledigt sie, um diesen Schutzschild auszuschalten. Ihr findet sie in den Zelten mit ihren Ritualen beschäftigt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30653] = {title = "Ein Bierchen in Ehren", objective = "Bringt etwas Bier zu den Wächtern von Zhu, den Priestern der Kranichschwingen, den Shado-Pan und den Taurensiedlern.", description = "Ich hab' nachgedacht.\n\nWir haben ja das ganze Bier, das Chen gebraut hat, und die vielen Leute, die Ihr zusammengetrommelt habt. Wir sollten die beiden zusammenbringen.\n\nDa sind Leute auf den Feldern, die ihr Leben für Pandaria riskieren. Wir beide sollten denen zumindest ein, zwei Fässchen vorbeibringen.\n\nDann können sie mit ihren Krügen auf den Sieg anstoßen. Oder sie haben sich ein letztes Bierchen hinter die Binde gekippt, bevor sie von einem Mantis niedergemetzelt werden. Wie auch immer - ich will nicht, dass sie ohne ein gutes Bierchen im Bauch in den Kampf ziehen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30654] = {title = "Die Guo-Lai-Hallen", objective = "Untersucht die Anwesenheit der Mogu in den Guo-Lai-Hallen.", description = "Die Mogu haben irgendetwas vor. Das spüre ich.\n\nSie haben Späher in die Guo-Lai-Hallen entsandt.\n\nDie Verwalter haben gesagt, dass in den Tiefen uralte Schätze der alten Kaiser lagern. Es sind nicht nur sehr wertvolle, sondern auch sehr mächtige Artefakte.\n\nWir müssen die Mogu davon abhalten, sich diese Schätze anzueignen! Geht über die Rampe im Nordwesten herunter und haltet sie auf!", progress = nil, completion = "Ihr habt offensichtlich eine große Katastrophe verhindert, &lt;Name&gt;.\n\nWenn dieser Mogukriegsfürst auf die Schätze in den Guo-Lai-Hallen aus ist, müssen wir ihn um jeden Preis aufhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30655] = {title = "Pandarengefangene", objective = "Befreit 8 Pandarengefangene.", description = "Seht, ich weiß ja, dass die Horde Rekruten braucht und momentan nicht genug von uns in dieser Stadt sind, um sie kampfbereit zu machen.\n\nIch weiß aber, dass die Yaungol drüben im Streitlager Ordo im Westen viele meiner Leute gefangen halten. Und ich weiß auch, dass sie höchstwahrscheinlich dazu bereit wären, sich der Horde anzuschließen, wenn Ihr sie befreien könntet.\n\nWas meint Ihr, <Name>?", progress = nil, completion = "Nun, wie es aussieht, haben wir eine kleine Armee beisammen - dank Euch.\n\nSie mögen zwar noch nicht besonders beeindruckend aussehen, aber mit ein wenig Hordendisziplin bekommen wir sie im Handumdrehen in Kampfform.\n\nÜbrigens, &lt;Name&gt;... gute Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30656] = {title = "Fässerweise Spaß", objective = "Verwendet die Sprengstofffässer im Streitlager Ordo, um die östlichen, südlichen und westlichen Bohrtürme zu zerstören.", description = "Ich liebe es, Sachen in die Luft zu jagen! Das liegt mir im Blut!\n\nBei den Yaungol im Streitlager Ordo im Westen liegen tonnenweise Sprengstofffässer herum.\n\nIch schlage vor, dass wir sie dazu verwenden, ihre Ölförderpumpen hochzujagen und gleichzeitig jede Menge Spaß zu haben!", progress = nil, completion = "Das war doch ein Riesenspaß, oder, &lt;Name&gt;? Ich hätte mit Euch zusammen da rüber gehen sollen!", rewards = "Ihr bekommt:\n\nExplosives Fass"}
MultiLanguageQuestData['de'][30657] = {title = "Konzeltration!", objective = "Tötet den Glutrufer, den Pyromanten, den Feuersprecher und den Flammenwirker von Ordo.", description = "Die Yaungol des Streitlagers Ordo sind momentan unsere größte Bedrohung. Ich möchte, dass Ihr Euch nach Westen begebt und ihren Anführer ausschaltet.\n\nDer Feigling versteckt sich in einer Höhle, die von seinen vier Untergebenen mit einer Feuerbarriere beschützt wird.\n\nErledigt sie, um diesen Schutzschild auszuschalten. Ihr findet sie in den Zelten, wo sie mit ihren Ritualen beschäftigt sind.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30658] = {title = "Eine ruhige Kugel schieben", objective = "Benutzt den Fischspeer, um 5 stachelige Kugelfische in den Sarjuntiefen zu töten, und kehrt mit ihren Stacheln zurück.", description = "Habt Ihr schon vom stacheligen Kugelfisch gehört, <Name>? Natürlich habt Ihr das nicht, Ihr seid ja neu hier!\n\nSie können in den Sarjuntiefen westlich von hier gefunden werden. Nehmt diesen Fischspeer und versucht, mir ein paar ihrer giftgetränkten Stacheln zu besorgen.", progress = "Passt mit dem Speer auf, <Name>.", completion = "Ahh, wie ich sehe, habt Ihr ein paar Stacheln dabei, &lt;Name&gt;. Die machen sich sicher gut auf meinen Speerspitzen!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30660] = {title = "Der Kriegshetzer von Ordo", objective = "Tötet den Kriegshetzer von Ordo.", description = "<Der Schutzschild ist ausgeschaltet. Zeit, in die Höhle einzudringen und den Kriegshetzer der Yaungol von Ordo zu erledigen!>", progress = nil, completion = "Ihr habt es geschafft, &lt;Name&gt;! Ich stehe in Eurer Schuld!\n\nWieder einmal!", rewards = "Streitkolben von OrdoZauberstab des FlammenwirkersSpeer der WindstilleKriegshetzeraxtWindklingeFeuerflammengewehrWindschneideHandaxt von OrdoKriegshetzerdolchFeuerflammenklopperIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30661] = {title = "Der Kriegshetzer von Ordo", objective = "Tötet den Kriegshetzer von Ordo.", description = "<Der Schutzschild ist ausgeschaltet. Zeit, in die Höhle einzudringen und den Kriegshetzer von Ordo zu erledigen!>", progress = nil, completion = "Wieder einmal habt Ihr geschafft, was sonst niemand vermocht hätte.\n\nAber wer hätte daran zweifeln wollen?", rewards = "Streitkolben von OrdoZauberstab des FlammenwirkersSpeer der WindstilleKriegshetzeraxtWindklingeFeuerflammengewehrWindschneideHandaxt von OrdoKriegshetzerdolchFeuerflammenklopperIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30662] = {title = "Der Kriegshetzer von Ordo", objective = "Tötet den Kriegshetzer von Ordo.", description = "Ihr habt den Schutzschild im Streitlager Ordo ausgeschaltet. Begebt Euch erneut dorthin, bevor er wieder aktiv ist.\n\nZeit, in die Höhle einzudringen und den Häuptling zu erledigen!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Streitkolben von OrdoZauberstab des FlammenwirkersSpeer der WindstilleKriegshetzeraxtWindklingeFeuerflammengewehrWindschneideHandaxt von OrdoKriegshetzerdolchFeuerflammenklopperIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30663] = {title = "Der Kriegshetzer von Ordo", objective = "Tötet den Kriegshetzer von Ordo.", description = "Ihr habt den Schutzschild in Streitlager Ordo ausgeschaltet. Begebt Euch erneut dorthin, bevor er wieder aktiv ist.\n\nZeit, in die Höhle einzudringen und den Kriegshetzer von Ordo zu erledigen!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Streitkolben von OrdoZauberstab des FlammenwirkersSpeer der WindstilleKriegshetzeraxtWindklingeFeuerflammengewehrWindschneideHandaxt von OrdoKriegshetzerdolchFeuerflammenklopperIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30665] = {title = "Die Verteidigung des Shado-Pan-Refugiums", objective = "Tötet 15 Sha-verseuchte Yaungol.", description = "Ich habe Verstärkung aus dem Shado-Pan-Kloster angefordert, aber noch nichts von ihnen gehört. Wir haben die Stadt bereits verloren.\n\nEin paar Dorfbewohner sind vielleicht noch da, aber wir sind hier festgenagelt.\n\nUns bleibt keine Zeit für Unterhaltung. Wenn Ihr kämpfen könnt, helft meinen Männern, diesen Turm zu verteidigen. Wenn nicht, geht, denn Ihr werdet hier nicht lange überleben.", progress = nil, completion = "Ihr habt uns etwas Zeit zum Atmen verschafft. Wir dürfen nicht verzweifeln - stattdessen müssen wir handeln.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30666] = {title = "Plötzliche, unerwartete Krokiliskenaggressivität", objective = "Erschlagt 8 Todesrachenkrokilisken bei Kea-Krak.", description = "Normalerweise besteht mein Tag aus dem Fangen von Fischen, dann dem Essen von Fischen, gefolgt von einem Schläfchen. Beachtet, dass ich \"Kämpfen mit einem Krokilisken\" in der Liste der Aktivitäten nicht aufgeführt habe.\n\nIhr seht wie <ein geschickter/eine geschickte:c> <Klasse> aus. Könnt Ihr ein paar dieser Krokilisken beseitigen, damit ich meine normale Routine wieder aufnehmen kann? Die Krokilisken bleiben normalerweise für sich allein, oben bei Kea-Krak, im Nordwesten.", progress = "Was bringt die Kroks dazu, so anzugreifen?", completion = "Gestern haben wir noch fröhlich gefischt. Heute haben die Kroks einfach angefangen... zu versuchen, uns zu fressen.\n\nSeltsam.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30667] = {title = "Besonderes Gefieder", objective = "Besorgt 6 smaragdfarbene Schwanzfedern, 6 purpurrote Schwanzfedern und 6 dunkle Schwanzfedern.", description = "Als die Kroks angefangen haben, anzugreifen, haben sie ein paar der Loris auf der Insel im Nordwesten aus den Nestern aufgescheucht.\n\nIch kann diese Lorifedern gebrauchen, um ein paar besondere Köder zu fertigen, die mir gelegen kommen, falls und wenn ich aufhören kann, meine Brüder gegen diese Reptilien zu verteidigen.\n\nHabt Ihr Lust auf eine kleine Federnjagd?", progress = "<Ein Schweißtropfen glitzert im Fell über Tonys Braue.>", completion = "Danke, &lt;Name&gt;. Ihr habt meinen Tag gerettet. Ich hasse es immer, wenn eine solch vorzügliche Gelegenheit zum Federnsammeln ungenutzt verstreicht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30668] = {title = "Ein eigenes Floß", objective = "Besorgt 4 Holzbretter und etwas zähen Seetang.", description = "<Jay späht in Richtung Kea-Krak.>\n\nHmm. Sie scheinen sich nicht zu... beruhigen. Wir werden etwas anderes probieren müssen.\n\nIhr werdet ein Floß brauchen. Besorgt Euch ein paar Holzbretter und etwas Seetang und bringt alles zu mir rüber. Ich werde etwas für Euch zusammenschustern.", progress = "Ihr habt alles? Ich werde Euch Euer Floß bauen, aber ich brauche die Materialien.", completion = "&lt;Geschickt knüpft Jay die Bretter zu einem überraschend seetauglich aussehenden Gefährt zusammen und lässt dies dann ins Wasser.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFloß stoßen\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30669] = {title = "Die Lehrensucherin auf dem See", objective = "Steigt auf Euer Floß und schildert der weisen Ana Wu in der Mitte der Nayelilagune das Problem.", description = "Euer Floß ist unten im Wasser. Fahrt damit in die Mitte des Sees. Dort solltet Ihr eine Frau namens Ana Wu vorfinden.\n\nWenn ich eine Frage habe, die ich selbst nicht beantworten kann, frage ich immer sie. Sie sollte uns sagen können, warum diese Krokilisken nicht aufhören, anzugreifen.", progress = nil, completion = "Ihr wirkt beunruhigt, mein Kind.\n\nWie kann ich Euch als Lehrensucherin dienen? Was sucht Ihr zu erfahren?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30670] = {title = "Mehr Disziplin!", objective = "Sammelt 5 Essenzen der blinden Wut von Exemplaren blinder Wut im Feuerzweigwinkel ein.", description = "Unsere wahren Feinde sind nicht die Yaungol, sondern das Sha.\n\nEs ist die reine Manifestation von Emotionen. Und sehr zerstörerisch. Aber auch sehr undiszipliniert. Und undisziplinierte Macht muss scheitern. Wenn eine Flut geteilt wird, verliert sie ihre Macht. Und Buschbrände verbrennen ihren eigenen Treibstoff.\n\nUnd mit Disziplin und Weisheit lassen sich seine zerstörerischen Energien gegen es selbst wenden.\n\nBringt mir die Essenzen des Sha im Dorf - dann werde ich Euch mehr erklären.", progress = "Habt Ihr die Essenzen sammeln können?", completion = "Sehr gut. Und jetzt werdet Ihr sehen, wie sich ungezügelter Zorn besiegen lässt.\n\nMithilfe dieser Essenzen werde ich Kobai, dem Anführer der Yaungol, eine Falle stellen. Aber auch wenn er dabei gefangen wird, ist er nicht unser Hauptziel...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30671] = {title = "Weisheit hat ihren Preis", objective = "Besorgt 5 Haifilets.", description = "<Ana hört sich Eure Geschichte an und nickt.>\n\nKrokilisken greifen an? Ich kenne eine Geschichte darüber. Und ich werde sie mit Euch teilen, aber zuvor... Ich werde hungrig.\n\nHaifleisch sollte dagegen helfen. Ihr solltet genügend Haie im Wasser unter uns finden.", progress = "Ich habe großen Hunger, <Volk>. Ich befinde mich nun mehrere Tage in dieser Lagune - ohne Nahrung.", completion = "Ihr habt mir mehr Fleisch gebracht, als ich jemals essen könnte!\n\nIch denke, ich schulde Euch jetzt eine Geschichte...", rewards = "Schuhe des DojaniKorjanischuheSarjunstiefelFlussklingenschuheAngkhalschuheNarsongschuheTiefwildschienbeinschützerTodesrachenschuheNayelischuheDer folgende Zauber wird auf euch gewirkt:\n\nCroc Tale: Summon Controller\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30672] = {title = "Gleichgewicht", objective = "Erschlagt 10 Ungafischholer.", description = "Die Geschichte nahm kein gutes Ende. Es gibt keine Narsong-Krokilisken mehr.\n\nDiesmal habt Ihr jedoch vielleicht eine Chance, das Ende zu beeinflussen.\n\nDie Ho-zen im Süden überfischen diese Gewässer. Ohne Fisch hungern die Krokilisken und sind daher verzweifelt - und greifen Marista an.\n\nGeht jetzt, <Volk>! Haltet die Ho-zen davon ab, so rücksichtslos zu fischen!", progress = nil, completion = "&lt;Jay hört sich Euren Bericht über die Geschehnisse des Tages an.&gt;\n\nVerstehe. Wir werden die Unga von hier aus im Auge behalten. Und wir werden unser Bestes geben, damit auch wir diese Gewässer nicht überfischen. Zweifellos sind auch wir ein Teil des Problems.\n\nBis zum nächsten Mal, &lt;Name&gt;.", rewards = "FischhändlerklingeZauberstab des WasserbewahrersHellebarde von MaristaKlinge von MaristaWolkensturzschwertBogen von MaristaStreitkolben von MaristaAxt von MaristaWolkensturzklingeWolkensturzstreitkolbenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30673] = {title = "Im Versteck", objective = "Rettet Jin Warmfass, Ya Feuerzweig, die alte Dame Fung und Sya Zhong.", description = "Den Geistern des Himmels sei Dank, dass Ihr da seid, <Klasse>! Ich weiß nicht, ob ich noch viel länger durchgehalten hätte.\n\nAber es gibt ganz sicher noch andere Überlebende in Feuerzweigwinkel. Würdet Ihr uns helfen, sie zu retten und sie in die Sicherheit des Shado-Pan-Refugiums zu führen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30674] = {title = "Gewaltloses Gleichgewicht", objective = "Werft 6 Zappelnde Karpfen in die Nayelilagune.", description = "Einige der Fische, die die Unga-Ho-zen gesammelt haben, scheinen noch nicht tot zu sein. Es ist vielleicht noch Zeit, sie zurück ins Wasser zu werfen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30675] = {title = "Vergrabener Schatz der Ho-zen", objective = "Sucht den vergrabenen Schatz der Ho-zen.", description = "Die Karte in Euren Händen ist zerknittert, schmutzig und schlecht gezeichnet, aber Ihr könnt ein großes X am Strand sehen.\n\nGibt es irgendwo auf dieser Insel einen vergrabenen Schatz?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30677] = {title = "Taxi", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30678] = {title = "Eine Bombenidee", objective = "Setzt die Goblinangelbomben ein, um 3 Rochen zu töten und bringt ihre Stacheln zu Fiznix. Ihr findet die Rochen an der seichten Stelle westlich von der Anlegestelle der Angler.", description = "Diese Rochen sind wohl doch nicht so leicht zu fangen, wie ich dachte! Ihr scheint ja ziemlich schlau zu sein. Vielleicht könnt Ihr mir helfen?\n\nIch habe zwar Bomben gebaut, habe jedoch Schwierigkeiten mit dem Floß wegen meines verletzten Beins. Die Rochen findet man häufig in den seichten Gewässern westlich von hier. Nehmt diese Bomben und mein Floß und beschafft mir ihre Stacheln!\n\nAch ja, passt auf die Hammerhaie auf!", progress = "Habt Ihr Rochen an der seichten Stelle gefunden?", completion = "Offensichtlich seid Ihr sehr geschickt mit diesen Bomben!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30680] = {title = "Im Versteck", objective = "Rettet Jin Warmfass, Ya Feuerzweig, die alte Dame Fung und Sya Zhong.", description = "Oh, danke. Ich danke Euch vielmals. Wenn Ihr nicht gekommen wäret, dann...\n\nAber Moment! Im Winkel muss es noch mehr Überlebende wie mich geben!\n\nIch bitte Euch, <Klasse>: Rettet auch die anderen und bringt uns in Sicherheit im Shado-Pan-Refugium.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30681] = {title = "Im Versteck", objective = "Rettet Jin Warmfass, Ya Feuerzweig, die alte Dame Fung und Sya Zhong.", description = "Oh, ich danke Euch! Ich hätte es niemals ganz allein zurück geschafft.\n\nAber ich glaube, es müsste noch andere Überlebende in Feuerzweigwinkel geben, die gerettet werden müssen. Sollen wir sie gemeinsam suchen und in die Sicherheit des Shado-Pan-Refugiums bringen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30682] = {title = "Im Versteck", objective = "Rettet Jin Warmfass, Ya Feuerzweig, die alte Dame Fung und Sya Zhong.", description = "Was für ein Glück, dass Ihr bis hierhin durchdringen konntet!\n\nIch weiß nicht, wie lange ich mich hier noch hätte verstecken können.\n\nAber ich bin mir sicher, dass es noch andere Überlebende gibt. <Klasse>, wir müssen sie retten! Und dann können wir sie ins Shado-Pan-Refugium bringen. Die Meister dort werden wissen, was zu tun ist!", progress = "Da draußen gibt es Überlebende? Dann gibt es sicher noch mehr, oder, <Name>?", completion = "Wir wussten nicht, dass es da draußen Überlebende gab.\n\nDanke, dass Ihr sie in Sicherheit gebracht habt, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nJin Warmfass' Bier"}
MultiLanguageQuestData['de'][30683] = {title = "Des einen Reisenden Pech...", objective = "Durchsucht das verlassene Wrack nach Vorräten.", description = "Musstet Ihr ihnen unserer Vorräte an den Kopf werfen?! Warum nicht Eure Waffe? Vielleicht ein paar raffinierte Zauber oder Tritte? Warum die Vorräte?!\n\nJetzt haben wir nicht mehr genug, um über die Runden zu kommen, zumal Neffe Krummnagel hier ist. Sein Appetit kommt dem eines Yetis gleich!\n\nIhr habt sie geworfen, Ihr holt uns mehr. Den Weg hinunter befindet sich ein Wrack. Vielleicht findet Ihr dort Vorräte.", progress = "Neffe Krummnagel hat sich bereits die Nahrung für zwei Tage einverleibt. Ich hoffe, Ihr habt mehr gefunden!", completion = "Die Mogu haben Euch angegriffen? Das klingt furchtbar!\n\nIch frage ja nicht gern, aber habt Ihr Vorräte für uns gefunden, als Ihr um Euer Leben gekämpft habt?\n\nNein?! Das ist sehr großes Pech.", rewards = "WasserfallrobeMushanledertunikaRüstung des träumenden GeistesBrustschutz des GleichmutsRobe des GeistbeugersTunika der lautlosen BlätterRüstung des YakhirtenBrustharnisch des GipfelwächtersBrustharnisch der MauerwacheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30684] = {title = "Pfad des Unwissenden", objective = "Bewältigt den Pfad des Unwissenden, um Euch mit dem Lehrensucher Cho zu treffen. Macht an allen Schreinen entlang des Weges Halt, um Euch dort auf Eure Gedanken zu konzentrieren.", description = "Ich bin mir ziemlich sicher, dass Euer Pandaren-Freund eine Ahnung hat, wonach die Mogu eigentlich suchen.\n\nEr hat sich vor ein paar Tagen ohne Bergführer ins Gebirge aufgemacht und gesagt, dass nur Ihr ihm folgen sollt. Er hatte sich sehr klar ausgedrückt:\n\n\"<Der/Die:c> <Klasse> muss diesen Pfad allein beschreiten, vollkommen konzentriert auf <seine/ihre> eigenen Gedanken. <Er/Sie> soll jedem Schrein die Ehre erweisen, bevor wir uns am Gipfel wiedersehen.\"\n\nDer Pfad beginnt gleich nordwestlich des Lagers und ist durch Flaggen gekennzeichnet. Aber passt gut auf Euch auf! Der Pfad des Unwissenden ist selbst an den harmlosesten Tagen noch gefährlich.", progress = "Es gibt zwei Schreine auf dem Pfad unter uns und noch einen gleich hinter uns.", completion = "Ah, Ihr habt es geschafft und den Schreinen Ehre erwiesen.\n\nIch wusste, dass Ihr dazu fähig sein würdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30690] = {title = "Demaskierung der Yaungol", objective = "Lockt Kobai in die Falle der blendenden Wut, stehlt ihm die Maske der bösartigen Wut und besiegt dann die bösartige Wut.", description = "Kobai Khan einfach zu töten, wird zu nichts führen, da er von besonders mächtigem und zerstörerischem Sha besessen ist - der bösartigen Wut.\n\nIhr werdet die Falle verwenden, die ich aus den Essenzen der blendenden Wut hergestellt habe, die Ihr gebracht habt. Lockt ihn in die Falle und stehlt dann seine Maske. Sobald Ihr sie aufgesetzt habt, erscheint Euch die bösartige Wut und versucht, Kontrolle über Euch zu erlangen.\n\nBesiegt sie und wir werden diese tragische Situation in einen Sieg verwandelt haben. Ihr findet sie nördlich des Refugiums, wo sie uns mit wahnsinnigem Zorn foltert.", progress = "Ist die bösartige Wut verschwunden?", completion = "Ich sollte über den Verlust des Dorfs Scham empfinden. Ich sollte angesichts Eures Erfolgs großen Stolz empfinden.\n\nIch sollte viele Dinge empfinden, aber ich darf es mir nicht erlauben. Wir müssen die vollständige Kontrolle über unsere Emotionen behalten, bis unser Ringen mit dem Sha beendet ist.", rewards = "Kappe der MauerwacheKappe des GipfelwächtersKappe des YakhirtenKappe der lautlosen BlätterKappe des GeistbeugersKappe des GleichmutsKappe des träumenden GeistesMushanlederkappeWasserfallkappeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30691] = {title = "Elend", objective = "Erlöst Nahassa von seinem Elend.", description = "Wenn Ihr schon unten im Wasser seid, solltet Ihr Nahassa, den Patriarchen der Todesrachen, erschlagen. Er leidet. Ich kann seine Todesschreie bis an die Oberfläche der Lagune fühlen.\n\nSucht seine Höhle und erlöst ihn von seinem Elend. Das hat nichts mit Maristas Krokiliskenproblem zu tun. Macht es einfach aus Gnade.", progress = nil, completion = "Nahassas fiebriges Leiden hat ein Ende gefunden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30692] = {title = "Der Jutepfad: Zum Basislager am Kota", objective = "Beschützt eine Gruppe Grummel auf dem Weg von der Zwischenstation des Jutepfads zum Basislager am Kota. Mindestens ein Grummel muss überleben.\n\nWenn Ihr die Grummel verliert, könnt Ihr den Jutepfad absuchen oder zur Zwischenstation des Jutepfads zurückkehren und warten, bis die nächste Gruppe aufbricht.", description = "Wir sind im Land der Ho-zen. Sehr gefährlich. Aber Grummel müssen hier durch. Schlangenrücken muss versorgt werden.\n\nGeht und beschützt die nächste Gruppe Grummel auf ihrer Reise zum Basislager am Kota.\n\nWenn auch nur einer überlebt, wird das Glück Euch bald finden.", progress = "Willkommen in der Zwischenstation des Jutepfads, Freund der Grummel.", completion = "Ha ha! Held der Grummel. Willkommen im Basislager am Kota. Genießt Euer Glück für gute Ablieferung von Grummel.", rewards = "Schal des fallenden SchneesTuch der SchneewehenCape der SchneeblindheitSchneebrockenpelerineSchneemaskenumhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30694] = {title = "Mit leichtem Schritt", objective = "Lasst \"Obacht\" walten, um 10 Stachelfallen der Flussklingen aus sicherer Entfernung auszulösen.", description = "Meine Schüler haben mir erzählt, dass die Umgebung mit tödlichen Fallen verseucht ist, die zweifellos von den Saurok aufgestellt wurden. Stolpert man in eine dieser Fallen, hat man das Gesicht voller Stacheln.\n\nWie das Sprichwort sagt: \"Ist der Weg voller Gefahren - geht mit leichtem Schritt und lasst Obacht walten.\"\n\n<Koro gibt Euch einen langen Ast.>\n\nHier, das ist Obacht.\n\nSie sollte lang genug sein, um die Fallen aus sicherer Entfernung auslösen zu können.", progress = nil, completion = "Jede Falle, die Ihr ausgelöst habt, steht für ein gerettetes Leben, ob von Pandaren, Bestien oder anderen. Niemand verdient einen ehrlosen Tod wie diesen.", rewards = "Satingamaschen des NebelgängersBalgbeinschützer des NebelgängersTiefwildbeinrüstungBrünierte Beinplatten des NebelgängersSeidene Beinkleider des NebelgängersLederbeinschützer des NebelgängersSarjunbeinschützerSchwere Beinschützer des NebelgängersGepanzerte Beinschützer des NebelgängersDer folgende Zauber wird auf euch gewirkt:\n\nRefugee Camp Act II: Ping to Begin\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30695] = {title = "Auf dem Weg", objective = "Tötet die Schlunde der Verzweiflung in der östlichen und auch der westlichen Pagode des Tempels des Roten Kranichs.", description = "Riesige Schlunde der Verzweiflung speien Sha aus den Pagoden zu beiden Seiten des Tempels aus. In der Zwischenzeit geht Eure improvisierte Ausbildung im Weg des Kranichs weiter.\n\n\"Diejenigen, die zerrissene Regenschirme reparieren, bleiben trockener als diejenigen, die auf Regen einschlagen.\"\n\nObwohl ich Einwände gegen diese spezielle Lektion erhebe - manchmal können Schläge gegen den Regen recht effektiv sein - bleibt die Bedeutung in diesem Fall wahr.\n\nSchaltet diese Schlunde der Verzweiflung aus und verschafft meinem Orden eine Chance, das Tempelgelände zurückzuerobern.", progress = "Koro berichtete über eine Pagode auf jeder Seite des Tempels. Suchen wir sie und löschen wir die Sha-Präsenz in beiden aus.", completion = "Koros Metaphern können ein wenig ermüdend werden, aber es ist fürwahr stets Weisheit in ihnen verborgen.", rewards = "Schwert des Roten KranichsKranichtempelklingeBarriere der VerzweiflungSchild der HoffnungSha-verzerrte KlingeSchlund der VerzweiflungSzepter des Roten KranichsLaterne der HoffnungAuf Euch wartet eine dieser Belohnungen:\n\nGeldbeutel des Helden\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][30698] = {title = "Wiederverwertung", objective = "Nehmt das goblinische Angelfloß und fischt 15 verrostete Schiffswrackteile aus den treibenden Trümmern in der Nähe der Wracks.", description = "IHR DA! Nach jemandem wie Euch habe ich gesucht!\n\nIch brauche weitere Teile für meine Goblinangelbomben, aber ich habe mir das Bein verletzt und kann sie nicht selbst besorgen.\n\nSeht Ihr diese Schiffswracks in der Nähe? Ich wette, dort gibt es genau das, was ich brauche, wenn Ihr nur dorthin kommen und es rausfischen könnt. Nehmt mein Angelfloß und schaut, was Ihr finden könnt! Mein Kumpel hat auch versucht, mir zu helfen, es kann also sein, dass Ihr weitere Flöße in der Nähe des Wracks findet - die könnt Ihr auch gerne benutzen.", progress = "Habt Ihr die Schiffswracks gefunden?", completion = "Da habt Ihr wohl eine Menge Teile gefunden. Eine neue Ladung Angelbomben kommt sofort! Danke, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30699] = {title = "Nach Winterblüte", objective = "Sprecht mit Lin Stillstoß in Winterblüte am Kun-Lai-Gipfel.", description = "Der Kampf gegen das Sha hört niemals auf – wir können diesen Ort nicht verlassen.\n\nAber ich mache mir Sorgen über das Ausbleiben von Verstärkung aus dem Kloster, nachdem wir doch schon vor Tagen darum gebeten haben.\n\nIhr habt Bewundernswertes geleistet, vielleicht könntet Ihr nach Winterblüte reisen. So heißt unser Basislager auf dem Weg zum Shado-Pan-Kloster. Sprecht dort mit Lin Stillstoß – er wird wissen, was vor sich geht. Um dorthin zu gelangen, müsst Ihr vom Dorf aus nach Norden reisen und der Straße durch das Shado-Li-Becken nach Winterblüte folgen.", progress = nil, completion = "Shado-Meister Chong hat Euch also geschickt?\n\nJa, wir haben seine Bitte um Verstärkung erhalten.\n\nWir können aber keine schicken. Wir haben selbst gerade erst einen Kampf überstanden, und das Kloster ist vollkommen abgeriegelt.\n\nNicht einmal wir können Verstärkung bekommen, dabei liegen wir direkt unten am Hügel!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30700] = {title = "Schnappklaue", objective = "Tötet Schnappklaue in einer Höhle am Grund des Narsonggrabens und kehrt mit seiner Klaue als Beweis zurück.", description = "Eine gigantische, giftige Krabbe macht sich über die hiesigen Seeohrbestände her. Ihr müsst Euch für mich in den Narsonggraben begeben und sie ausschalten!", progress = "Habt Ihr diesen lästigen Krabbler ausgeschaltet?", completion = "Das ist ja mal eine Klaue. Schnappklaue muss größer gewesen sein, als ich gedacht habe! Aber egal, Ihr habt Eure Aufgabe gut gemacht, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30701] = {title = "Zwingzangensuppe", objective = "Tötet Zwingzangenfischer am Strand und kehrt mit 16 Augen für eine leckere Suppe zurück.", description = "Nichts schmeckt so gut wie Zwingzangensuppe. Das ist eine Krasarangspezialität!\n\nIch wollte mir gerade eine machen, als ich bemerkte, dass eine Hauptzutat fehlt: die Augen!\n\nIhr müsst die Zwingzangenfischer am Strand für mich töten und mir ihre Augen für die Suppe bringen!", progress = "Wie viele ihrer wachsamen, kleinen Augen habt Ihr bekommen?", completion = "Danke, &lt;Klasse&gt;, das könnte meine bisher beste Suppe werden!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30704] = {title = "Ho-zen im Nebel", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30705] = {title = "Logbuch des Kapitäns", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30706] = {title = "Verärgerte Kritzeleien", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30710] = {title = "Trolle provozieren", objective = "Tötet 10 Pirscher der Zandalari und 5 Hexer der Zandalari.Wir haben sie erst einmal zurückschlagen können, aber ich bezweifle, dass wir auf Sicherheit hoffen dürfen, solange wir sie nicht vernichtend geschlagen haben.\n\nMein Mann, man mag ihn einen Feigling oder Narren nennen, möchte sie angeblich nicht provozieren. Ich aber lasse mich nicht einschüchtern.\n\nUnd darum werden wir sie erst recht provozieren, indem wir ihre Späher töten. Vielleicht können wir so ihren Anführer herauslocken und sogar vernichten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Wir haben sie erst einmal zurückschlagen können, aber ich bezweifle, dass wir auf Sicherheit hoffen dürfen, solange wir sie nicht vernichtend geschlagen haben.\n\nMein Mann, man mag ihn einen Feigling oder Narren nennen, möchte sie angeblich nicht provozieren. Ich aber lasse mich nicht einschüchtern.\n\nUnd darum werden wir sie erst recht provozieren, indem wir ihre Späher töten. Vielleicht können wir so ihren Anführer herauslocken und sogar vernichten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30714] = {title = "Die Anführer vernichten", objective = "Tötet den Klingenmeister der Zandalari und den Magier der Zandalari.Und jetzt fürchten sie Euch.\n\nIhre Anführer, ein Klingenmeister und ein Magier, befinden sich tiefer in den Ruinen. Tötet sie.\nFügt ihnen Schmerzen zu. Tut es für uns.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Und jetzt fürchten sie Euch.\n\nIhre Anführer, ein Klingenmeister und ein Magier, befinden sich tiefer in den Ruinen. Tötet sie.\nFügt ihnen Schmerzen zu. Tut es für uns.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30715] = {title = "Eine ungebrochene Linie", objective = "Bettet Shado-Meister Zhiyao, Liu Tausendschlag und Shiya Scharfklinge zur letzten Ruhe.", description = "Als wir uns nach ihrem ersten Angriff neu formiert hatten, fehlten uns drei Mann. Ihr könnt kämpfen, und wir müssen unsere Verteidigung für den Fall planen, dass diese verfluchten Yaungol wieder angreifen.\n\nWenn Ihr uns helfen wollt, gewährt unseren gefallenen Kameraden ihre letzten Riten und bergt ihre Rüstungen. Ihr werdet ihre Körper im Westen finden, in der Nähe des Tors.\n\nUnd versucht, diese Aasfresser von ihnen fernzuhalten.", progress = "Unsere Kameraden... ruhen sie in Frieden?", completion = "Gut. Ich werde dafür sorgen, dass die Rüstungen ihren Schülern zukommen werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30716] = {title = "Der Hoffnung hinterher", objective = "Berührt 3 Geister des Kranichs.", description = "Chi-Ji ist immer bei uns. Auch wenn er nicht hier in der Wiege ist, rennen Teile seines Geistes durch die Wälder und über die Strände der Insel, beobachten und prüfen uns.\n\nBeweist Eure Gewandtheit in den Augen von Chi-Ji, <Name>. Sucht und fangt die Geister des Kranichs.", progress = nil, completion = "Chi-Ji lächelt auf Euch herab.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30717] = {title = "Gaben des Großen Kranichs", objective = "Besorgt 10 Gaben des Großen Kranichs.", description = "Die Kraniche von Krasarang sind eine Gabe von Chi-Ji. Sogar die Federn, die sie zurücklassen, sind eine Gabe an uns, an der wir uns erfreuen.\n\nWir verwenden diese Federn, um unsere Kleidung zu schmücken und Pfeile zu befiedern. Aber zuerst... müssen sie eingesammelt werden.", progress = "Auch die kleinste, schwächste Feder ist Beweis genug dafür, dass Chi-Ji uns liebt.", completion = "Danke, &lt;Name&gt;.\n\nKommt bald wieder.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30718] = {title = "Schüler von Chi-Ji", objective = "Duelliert Euch mit 10 Schülern von Chi-Ji.", description = "Unser Orden ist stolz auf seine Vortrefflichkeit im Kampf. Wir verbessern diese Kampffertigkeiten, indem wir uns hier in Chi-Jis Wiege duellieren.\n\nBeweist Euch in den Augen des Roten Kranichs. Begebt Euch nach Süden ins Zentrum der Insel und duelliert Euch mit Euren Mitschülern.", progress = nil, completion = "Mit jedem Kampf - Sieg oder Niederlage - verbessert Ihr Euch. Ihr werdet schneller, kühner, schlauer... besser.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30723] = {title = "Ehre, auch im Tod", objective = "Tötet 12 Kun-Lai-Leichenhacker.", description = "Hmm... Wenn Shado-Meister Chong Euch vertraut hat, könnt Ihr uns vielleicht auch helfen.\n\nDie Yaungol sind unsere Feinde.\n\nDennoch müssen wir unter Beweis stellen, dass wir besser sind als sie. Wir werden ihnen im Tode noch Ehre erweisen.\n\nWie nach den meisten Schlachten versammeln sich die Aasfresser. Verringert ihre Anzahl, damit die Leichen unserer Feinde nicht entweiht werden. Sie befinden sich auf dem Schlachtfeld im Westen.", progress = nil, completion = "Gut. Nach dem, was sie getan haben, würde ich lebenden Yaungol keine Freundlichkeit entgegenbringen. Allerdings werde ich aber auch nicht dulden, dass ihre Leichname von Vögeln gefressen werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30724] = {title = "Auf die Mauer!", objective = "Sprecht mit Drachenmeister Len in Winterblüte am Kun-Lai-Gipfel, um einen Drachen hoch zum Ochsentor zu nehmen. Sprecht mit Suna Stillstoß, wenn Ihr dort angekommen seid.", description = "Sie greifen schon wieder an!\n\n<Lin blickt in Richtung des Ochsentors>\n\nBogenschützen... Auf die Mauer!\n\nIhr müsst Euch dort hoch begeben. Meine Frau Suna ist gerade mit diesem törichten Lao-Chen dorthin aufgebrochen, um die Lage auszukundschaften. Vielleicht hätte er mehr Zeit mit der Vorbereitung der Verteidigungen als dem Bau dieses idiotischen Bieraufzugs verbringen sollen...\n\nAber das ist jetzt auch egal. Besorgt Euch westlich von hier einen Drachen von Len, dann begebt Euch dort hoch und findet meine Frau. Sie wird wissen, was zu tun ist.", progress = nil, completion = "Nicht schlecht... Ihr seid ein ziemlich talentierter Drachenflieger! Gut, dass Ihr es hier hoch geschafft habt, ohne zu sterben.\n\nIhr werdet hier auch dringend benötigt. Lao-Chen hat einen Plan, an dem er gerade arbeitet, aber mit diesen Yaungol werden wir wohl kaum allein fertig.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30725] = {title = "Ellia Rabenmähne", objective = "Besiegt Ellia Rabenmähne beim Angkhalpavillon.", description = "Wir organisieren regelmäßig Duelle, einer gegen einen, mit Schülern, die unserer Meinung nach gut zusammenpassen. Wir haben eine solche Schülerin für Euch gefunden, <Name>.\n\nIhr Name ist Ellia Rabenmähne. Das wird auch ihr erstes Duell sein. Sie erwartet Euch am Pavillon etwas südlich von hier.", progress = nil, completion = "Sehr gut!\n\nDas nächste Mal, wenn Ihr zurückkehrt, werdet Ihr einem neuen Herausforderer gegenüberstehen. Gewinnt weiterhin, und Eure Gunst in den Augen von Chi-Ji wird steigen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30726] = {title = "Minh Do-Tan", objective = "Besiegt Minh Do-Tan.", description = "Euer nächster Herausforderer ist ein weiterer, relativ neuer Schüler. Er heißt Minh Do-Tan und hat seine letzten beiden Kämpfe gewonnen.\n\nEr erwartet Euch in der Nähe der Kranichstatue im Süden.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Ihr fangt an, Euch einen Namen zu machen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30727] = {title = "Und schon wieder Ellia Rabenmähne", objective = "Besiegt Ellia Rabenmähne in der Nähe des Podests der Hoffnung.", description = "Ellia Rabenmähne hat einen erneuten Kampf verlangt. Sie scheint Euch für ihren \"Rivalen\" zu halten.\n\nWir versuchen hier in Chi-Jis Wiege, Rivalitäten zu vermeiden, aber selten lehnen wir eine Forderung nach einem weiteren Kampf ab. Ihr findet Ellia in der Nähe des Podests der Hoffnung auf der Ostseite der Insel.", progress = nil, completion = "Zwei Kämpfe, zwei Niederlagen. Verständlicherweise wird Ellia in der nächsten Zeit wohl keine weiteren Wiederholungskämpfe fordern.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30728] = {title = "Fat Long-Fat", objective = "Besiegt Fat Long-Fat oben auf dem Angkhalpavillon.", description = "Du wurdest einem... besonderen Schüler zugeteilt. Sein Name ist Fat Long-Fat.\n\n<Thelonius wählt seine Worte sorgfältig.>\n\nFat Long-Fat... operiert außerhalb der normalen Kampfregeln. Er kämpft nicht jeden Tag, und wenn er es tut, wählt er seinen Konkurrenten. Heute hat er aus irgendeinem Grund... Euch ausgewählt.\n\nIhr findet ihn auf dem Angkhalpavillon.", progress = nil, completion = "Natürlich habt Ihr gewonnen. Fat Long-Fat kämpft nicht, um zu gewinnen. Er kämpft... aus anderen Gründen.\n\nIch befürchte, ich habe schon zu viel zu diesem Thema gesagt. Von jetzt an... keine weiteren Fragen zu Fat Long-Fat.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30729] = {title = "Julia Bates", objective = "Besiegt Julia Bates.", description = "Wir heißen jeden in der Wiege willkommen, solange er die Ideologie des Roten Kranichs anerkennt und sich ihr verpflichtet. Eine unserer neuen, exotischeren Schülerinnen stammt aus den Menschenkönigreichen im Nordosten. Sie hört auf den ziemlich fremd klingenden Namen Julia Bates.\n\nSie ist Eure nächste Herausforderin. Ihr findet sie an der Westküste der Insel.", progress = nil, completion = "Noch einen Kampf gewandt gewonnen. Ich erwarte unruhig Euren nächsten Kampf, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30730] = {title = "Der geschickte Izissha", objective = "Besiegt den geschickten Izissha.", description = "Jinyu meiden normalerweise unseren Orden, aber alle paar Jahre finden wir einen, der sich dem Weg des Kranichs verschreibt. Ein solcher Jinyu ist der geschickte Izissha.\n\nIzissha ist Euer nächster Herausforderer. Er erwartet Euch an der Südwestküste der Insel.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;! Ihr gewinnt weiter an Gunst in den Augen von Chi-Ji.\n\nAn Euren nächsten Kampf werdet Ihr Euch sicher lange erinnern. Ihr kämpft nicht gegen einen Schüler. Stattdessen werdet Ihr einem Eurer Lehrer gegenüberstehen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30731] = {title = "Kuo-Na Stachelpfote", objective = "Besiegt Kuo-Na Stachelpfote.", description = "Die meisten Duelle in der Wiege finden zwischen zwei Schülern statt. Zeigt ein Schüler äußerst große Fertigkeit, erhält er eine Gelegenheit, sich mit einem Lehrer zu duellieren, was aber nur selten vorkommt.\n\nHeute kämpft Ihr in einem Duell gegen Kuo-Na. Sie erwartet Euch am Podest der Hoffnung.", progress = nil, completion = "Ihr seid weiterhin beeindruckend, &lt;Name&gt;.\n\nKommt bald wieder. Eure Ausbildung ist noch nicht beendet.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30732] = {title = "Die Rache der Ellia Rabenmähne", objective = "Besiegt Ellia Rabenmähne bei der Balrissakuppel.", description = "Eure \"Rivalin\" ist wieder aufgetaucht. Ellia Rabenmähne hat ihre Pflichten auf der Insel vernachlässigt und sich stattdessen auf persönliches Training konzentriert. Sie hat vor, Euch im Kampf zu schlagen.\n\n\"Ich werde <Name> vernichten\", hat sie gesagt.\n\nIch habe ihrer Forderung nach einem Wiederholungskampf nachgegeben, aber ich werde sie gut im Auge behalten. Ihre Motive könnten sich in eine gefährliche Richtung verschieben.", progress = nil, completion = "Ich werde Chi-Ji sofort um Rat zu Ellias Verhalten bitten. Sie bewegt sich auf dünnem Eis.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30733] = {title = "Tukka-Tuk", objective = "Besiegt Tukka-Tuk.", description = "Ihr macht Euch einen Namen, <Name>. Ich habe eine Herausforderung von einem unserer geschickteren Wettbewerber erhalten. Er meint, Ihr seid nicht so stark, wie Ihr scheint.\n\nEr heißt Tukka-Tuk, ein Ho-zen. Wenn Ihr irgendwann schon einmal gegen Ho-zen gekämpft habt, dann wisst Ihr, dass ihr Kampfgeist ihre offensichtliche Unreife Lügen straft. Viel Glück.", progress = nil, completion = "Gut gemacht, wie üblich.\n\nIch bin sicher, ich werde Euch bald wiedersehen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30734] = {title = "Kurt Karette", objective = "Besiegt Kurt Karette.", description = "Normalerweise handelt es sich bei unseren Schülern um Abenteurer wie Euch oder um Mönche aus dem Tiankloster oder gelegentlich um Shado-Pan im Ruhestand. Sehr selten jedoch begrüßen wir Schüler, die noch überhaupt keine Kampferfahrung haben.\n\nKurt Karette ist solch ein Schüler. Er hat ein Duell mit Euch gefordert. Sucht ihn an der Westküste der Insel.", progress = nil, completion = "Es bleibt nur noch ein Schüler, der im Rang über Euch steht.\n\nIch habe so ein Gefühl, dass Ihr ihm gegenüberstehen werdet, wenn Ihr zurückkehrt.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30735] = {title = "Mindel Sonnensang", objective = "Besiegt Mindel Sonnensang.", description = "Unser höchstrangiger Schüler ist ein Außenseiter wie Ihr. Es ist sowohl seltsam als auch aufregend, in einer Zeit zu leben, in der so viele Fremde sich entschließen, dem Weg des Kranichs zu folgen.\n\nEuer Herausforderer heißt Mindel Sonnensang und er erwartet Euch im Angkhalpavillon.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30736] = {title = "Yan Stachelpfote", objective = "Besiegt Yan Stachelpfote am Podest der Hoffnung.", description = "Ihr habt Kuo-Na Stachelpfote bereits besiegt. Aber Ihr seid noch nicht gegen ihren Bruder Yan angetreten.\n\nEr trifft sich mit Euch am Podest der Hoffnung, und er wird sich nicht zurückhalten. Sein Ruf als Lehrer steht auf dem Spiel.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30737] = {title = "Und schon wieder Fat Long-Fat", objective = "Besiegt Fat Long-Fat oben auf der Balrissakuppel.", description = "Fat Long-Fat hat einen weiteren Kampf mit Euch gefordert. Mir kommt das seltsam vor. Und besorgniserregend.\n\nEr erwartet Euch oben auf der Balrissakuppel.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30738] = {title = "Thelonius", objective = "Besiegt Thelonius.", description = "Als wir uns das letzte Mal unterhalten haben, habe ich Euch versprochen, Euch das Geheimnis von Fat Long-Fat zu verraten. Ich habe immer noch vor, Euch dieses Geheimnis zu verraten... nachdem ich Euren Wert festgestellt habe.\n\nTrefft Euch mit mir an der Westküste, dann werden wir uns duellieren.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30739] = {title = "Ellia Rabenmähne: Erlösung", objective = "Besiegt Ellia Rabenmähne oben auf dem Podest der Hoffnung.", description = "Ellia Rabenmähne, Eure Rivalin, ist zurückgekehrt. Sie verlangt, dass Ihr Euch mit ihr oben auf dem Podest der Hoffnung trefft.\n\nIhr müsst verstehen, <Name>... Ihr ist etwas Schreckliches zugestoßen. Sie hat sich verändert. Ihr werdet es selbst sehen, wenn Ihr am Podest ankommt.\n\nViel Glück, <Name>.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30740] = {title = "Champion von Chi-Ji", objective = "Besiegt einen Champion von Chi-Ji.", description = "Euch wird immer ein Ehrenplatz in unserem Orden gebühren, trotzdem seid Ihr immer noch willkommen, an unseren Duellen teilzunehmen.\n\nEiner unserer aktuellen Champions erwartet Euch in der Balrissakuppel. Ich weiß, dass sie sich geehrt fühlen würden, wenn Ihr mit ihnen duellieren würdet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30742] = {title = "Im Rausch der Zägen", objective = "Besiegt 12 Kafa-berauschte Bergziegen auf der Kotaspitze.", description = "Hab's vermusselt.\n\nSamen aus Kafa-Beeren zu schneiden, ist harte Arbeit! Hab' aber gesehen, wie Zägen die Beeren essen und die Samen sauber wieder zurückgeben. Nach einem Tag oder so.\n\nHab' alles den Zägen auf der Kotaspitze gegeben. Jetzt sind Zägen verrückt! Greifen alles an, was sich bewegt.\n\nKota war sicheres Gebiet für Grummel zum Kafa-Sammeln. Nicht mehr. Nicht mit den Zägen. Werdet Ihr helfen?", progress = nil, completion = "Danke Euch. Lasst Euch dies eine Lehre sein: Füttert nie die Zägen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30743] = {title = "Gourmet-Kafa", objective = "Markiert 10 Kafa'zäge-\"Vorkommen\" auf der Kotaspitze.", description = "War gute Idee. Kafa-Beeren in Zäge rein, kommen sauber wieder aus.\n\nKafa'kota ist schon selten und Vermögen wert, aber Erfindung von mir - Kafa'zäge - ist GOURMET.\n\nAber das jetzt vorbei. Onkel Kühnbohn ist aufgeregt und Gipfel ist nicht sicher. Jetzt nur noch eins zu tun: Den Rest von Kafa'zäge sammeln und es nie wieder machen.\n\nIch bitte Euch nicht, es einzusammeln - keine schöne Aufgabe, nichts für Helden - markiert es einfach, damit wir es leichter finden, wenn der Berg wieder sicher ist.", progress = nil, completion = "Gut. Ich gehe rauf und ernte. Bald.\n\n&lt;Cousin Zägenfell fängt an, sich lange Leinenstreifen um die Hände zu wickeln.&gt;\n\nKann nicht glauben, dass ich dachte, es wäre eine gute Idee.", rewards = "Ihr bekommt:\n\nKühnbohn Kafa"}
MultiLanguageQuestData['de'][30744] = {title = "Edle Kota-Mischung", objective = "Sammelt 100 Kafa'kota-Beeren auf der Kotaspitze. Ihr findet sie in den Büschen in den Bergen oder in den Yeti-Höhlen aufgehäuft.", description = "Kotaspitze ist berühmt für Kafa-Büsche. So weit oben kann nichts anderes wachsen.\n\nGrummel verdienen gutes Geld mit edle Kafa'kota-Mischung. Aber jetzt ist gefährlich. Schuld hat mein Vetter. Hat die Tiere da oben mit Kafa gefüttert und verrückt gemacht.\n\nKafa'kota seltener als je zuvor: Zägen fressen Kafa'kota auf. Yetis bringen Kafa'kota in ihre Höhlen.\n\nBringt mir Beeren runter. Ich zahle gut.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30745] = {title = "Ärger braut sich zusammen", objective = "Tötet 5 Kafa-berauschte Yetis in den Höhlen der Kotaspitze.", description = "Eine Menge Yetis in Kota, jepp. Normalerweise nicht gefährlich. Normalerweise essen nur Zägen.\n\nDann gegessen Zägen gefüllt mit Kafa...\n\n<Kühnbohn schaut Zägenfell bedrohlich an.>\n\nJetzt sind launisch, stinkig, schlafen viel, aber sind nie ausgeruht. Typische Kafasüchtige.\n\nKommen bald aus den Höhlen, ich bin sicher. Kommen und suchen nach mehr Kafa.\n\nDann wir alle haben Ärger.", progress = nil, completion = "Geschafft!\n\nYetis sind schon alleine hart - kann mir nicht vorstellen, wie ein stinkiger Kafa-süchtiger Yeti sein muss. Ihr seid mutig. Oder habt Glück. Oder seid dumm.\n\nVielleicht alles drei.", rewards = "Ihr bekommt:\n\nTasse Kafa"}
MultiLanguageQuestData['de'][30746] = {title = "Ein gerechter Handel", objective = "Bringt das Bündel Kafa'kota-Beeren zum Versteck von Kota Kon in der Nähe des Gipfels der Kotaspitze.", description = "<Das Gebrüll ertönt wieder, lauter und wilder, als alles, was Ihr bisher von Yetis gehört habt. Und wieder antwortet eine Grummelstimme...>\n\nIeep! Bitte, großer Kota Kon, vergebt Grummel. Lasst mich gehen, ich werde sofort eine Menge Kafa holen! Versprochen!\n\n<Die Bestie namens Kota Kon antwortet mit einem weiteren gehaltvollen Brüllen.>", progress = "Kota Kon will mehr Kafa, aber ich habe sie schon mit allem gefüttert, was ich habe! Dann habe ich es mit einer netten Verneigung probiert, aber sie ist nicht zufrieden!\n\n<Der erschreckte Grummel schluckt und lehnt sich für ein Flüstern zu Euch.>\n\nIch glaube, sie kann den Kafa riechen, den ich zum Frühstück getrunken habe...", completion = "Ihr habt Kafa mitgebracht?\n\nIhr...\n\nGroßartig...\n\nGlücksbringer...\n\nSchnell, geben wir ihn ihr! Vielleicht wird sie uns nicht als Imbiss fressen...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nA Fair Trade: Completion Event\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30747] = {title = "Der Juteschleifer", objective = "Gebt Kota Kon beim Basislager am Kota das Fläschchen Kafa, dann tötet 100 Ho-zen entlang des Jutepfads.", description = "Na guuut... in Ordnung, sie hat niemanden gefressen. Das ist ein guter Anfang.\n\nSie will sicher mehr Kafa, aber wir müssen ihr bei der ganzen zusätzlichen Energie etwas zu tun geben...\n\nIch hab's! Der Jutepfad! Sie kann den ganzen Tag dort Ho-zen vermöbeln!\n\n<Buchsbaum wendet sich der gewaltigen Bestie zu.>\n\nWas meinst du, hübsches Mädchen? Willst du Ho-zen vermöbeln?!\n\nIch glaube schon. Hier, gebt ihr meine Notfallflasche Kafa. Sie mag Euch.", progress = "Lasst uns unser Glück nicht herausfordern... Wir haben ihr Ho-zen-Stampfi-Stampfi versprochen!", completion = "Puh! Das war GEWALT.\n\nIch bin nicht sicher, was ich erwartet habe...\n\nIch glaube, wir haben dank Euch gerade eine Beziehung mit dem Schrecken der Kotaspitze geknüpft, die beiden nutzt.", rewards = "WasserfalltreterMushanlederfußschützerSabatons des träumenden GeistesSchienbeinschützer des GleichmutsTreter des GeistbeugersStiefel der lautlosen BlätterSabatons des YakhirtenKriegsstiefel des GipfelwächtersKriegsstiefel der MauerwacheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30750] = {title = "Mauerfall", objective = "Tötet 12 Bogenschützenveteranen oder Feuerkrieger von Osul.", description = "Die Yaungol hier auf der Mauer geben den anderen unten Feuerschutz. Ich weiß nicht, was Lao-Chen vorhat, aber ich will, dass Ihr diese Bogenschützen ausschaltet.\n\nEs gibt auch etwas Gutes zu berichten: Der Geist des Ochsen ist hier, um uns zu helfen. Wenn die Yaungol geschwächt sind, wird der Geist sie betäuben - Ihr könnt diesen Moment nutzen, um sie von der Mauer zu stoßen.\n\nDie Bogenschützen haben gleich hinter dieser Tür Position bezogen.", progress = nil, completion = "Ha! Und da fliegen sie. Gute Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30751] = {title = "Ein schreckliches Opfer", objective = "Sammelt 6 Fässer mit Feueröl der Yaungol.", description = "Ich habe eine Idee und... ich bin bereit, ein schreckliches Opfer zu bringen.\n\nSoweit ich das abschätzen kann, wird mein Gebräu für die Stärkung der Verteidiger und damit für die langfristige Sicherheit des Ochsentors benötigt...\n\nDie Sache ist zu schmerzhaft, um jetzt darüber zu sprechen. Aber ich bitte Euch, ein paar ihrer Ölfässer, mit denen sie ihre Pfeile entzünden, einzusammeln, während Ihr die Mauer verteidigt. Wir werden sie später brauchen.", progress = "Habt Ihr das Öl?", completion = "Also gut. Ich werde jetzt unsere nächsten Schritte vorbereiten. Viel Glück, mein Freund.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest - Kun-Lai Summit - Summon Lao-Chen for Transition off Wall\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30752] = {title = "Unglaublich!", objective = "Sprecht mit dem Wächter des Shado-Pan-Klosters, um Zugang zum Shado-Pan-Kloster zu erlangen.", description = "Ich kann nicht glauben, dass die Wachen uns am Betreten des Klosters hindern werden, wenn sie den Ernst unserer Lage erst einmal verstehen.\n\nGeht zur Wache vor dem Kloster im Osten und verlangt Einlass. Ich werde Euch begleiten.", progress = "Unglaublich!", completion = "Nein... es ist viel schlimmer, als ich dachte. Das Kloster selbst ist befallen!", rewards = "Schmuckstück der GartenhütersAmulett des BräutrinkersBärenherzhalsketteAnhänger des BiertrinkersBärenherzamulettIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30753] = {title = "Der Ritt auf dem Hai", objective = "Tötet einen rasenden Riffhai mit bloßen Händen.", description = "Dort, wo ich herkomme, besteht der einzige Weg, einen Hai zu töten, darin, ihn mit bloßen Händen zu erlegen!\n\nIch habe in der Nähe des Docks hier eine Menge Futter ins Wasser geworfen. Bald sollte es hier von Haien nur so wimmeln. Hüpft auf den ersten, den Ihr seht, und erledigt ihn!", progress = "Habt Ihr dem Hai gezeigt, wer der Boss ist?", completion = "Was für ein riesiger Hai, den Ihr da besiegt habt, &lt;Name&gt;! Ich bin beeindruckt!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30754] = {title = "Heller Köder", objective = "Sammelt 7 Sonnenkriecher im Wald nördlich des Außenpostens der Angler.", description = "Bestimmte Fische werden nur von hellen Lichtern angezogen. Der Wald im Norden von hier beheimatet die hiesige Art Pandaren-Glühwürmchen, die Sonnenkriecher genannt wird.\n\nIhr solltet sie unten an Baumstümpfen finden können. Bringt eine Handvoll von ihnen her, damit ich sie als Köder verwenden kann!", progress = "Hattet Ihr Glück mit den Sonnenkriechern?", completion = "Die sollten wirklich reichen, &lt;Name&gt;. Danke für die Hilfe!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30757] = {title = "Der Herr der Shado-Pan", objective = "Befreit Taran Zhu vom Sha des Hasses.", description = "Ein Sha des reinen Hasses hat unseren Herrscher, Taran Zhu, in Besitz genommen. Das ganze Kloster ist verloren!\n\nIch bitte Euch: Ihr müsst einen Weg finden, ihn zu befreien. Zuletzt sah ich ihn, wie er im Hain der Fallenden Blüten meditierte.", progress = nil, completion = "Ich danke Euch, &lt;Klasse&gt;. Jetzt bin ich wieder frei von all dem Hass.\n\nVon nun an werdet Ihr für immer zu den Helden der Shado-Pan zählen.", rewards = "Gugel der verärgerten GedankenKopfbedeckung der gestörten RuheNervende HelmkappeKapuze der endlosen UnruheKopflappen des AntagonistenKopfbedeckung des UngeduldigenGugel des ewigen StrebensHelm der FeindseligkeitHelm des instabilen TemperamentsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30763] = {title = "Piranha!", objective = "Fischt 5 Wolfspiranhas aus dem Krasarang in der Krasarangwildnis.", description = "Einige Fische sind sehr schwierig zu fangen. Der Wolfspiranha fällt auf jeden Fall in diese Kategorie.\n\nEin Glück für mich, dass Ihr aufgetaucht seid! Prüft Eure Fähigkeiten im Fischen und bringt mir ein paar von denen vom Krasarang ein Stück nordwestlich von hier.", progress = "Schon Glück gehabt?", completion = "Wie ich sehe, habt Ihr noch alle Eure Finger. Gute Arbeit.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30765] = {title = "Ehre zurückgewinnen", objective = "Beschafft Zhens Banner.", description = "<Name>, der Kriegshäuptling der Yaungol, Attilaqa der Hüne, hat Shado-Meister Zhen getötet. Er hat sein Banner.\n\nIhr müsst Attilaqa den Hünen töten und Zhens Ehre zurückgewinnen! Wenn Ihr es nicht macht, werde ich es tun.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30766] = {title = "Historische Geschäfte", objective = "Sammelt 11 weitere Relikte der Mogu ein.<Ein Relikt löst sich von der Statue. Hm, dies könnte für die richtige Person von echtem Wert sein.>\n\n<Im Außenbereich der Ruinen hält sich ein Sammler auf. Vielleicht hat er ja Interesse, Euch solche Dinge abzukaufen?>Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "<Ein Relikt löst sich von der Statue. Hm, dies könnte für die richtige Person von echtem Wert sein.>\n\n<Im Außenbereich der Ruinen hält sich ein Sammler auf. Vielleicht hat er ja Interesse, Euch solche Dinge abzukaufen?>Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30767] = {title = "Alles riskieren", objective = "Entfernt den Stachel aus dem Fleisch Shen-zin Sus.", description = "Moment - was?! Wie kann er bloß so rücksichtslos sein? Das Schiff freisprengen zu wollen ist Wahnsinn! Es könnte das Ende von Shen-zin Su bedeuten... und damit unser aller Ende.\n\nIch weiß, dass wir nicht viel Zeit haben, aber wir müssen einen anderen Weg finden...Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30768] = {title = "Mein Gatte...", objective = "Trefft Euch mit Suna Stillstoß am Außenposten Longying in der Tonlongsteppe.", description = "Lin...\n\nWas Ban, Lao-Chen oder selbst Taran Zhu sagen, ist mir egal. Ich gehe weiter nach Tonlong. Vielleicht kann ich Lin nicht selbst retten, aber ich werde nicht einfach herumsitzen und warten, bis alle anderen nachkommen.\n\nSobald Taran Zhu die Tore zu seinem kostbaren Kloster öffnet, werden wir Lin retten. In der Zwischenzeit werde ich den Weg voraus erkunden und dafür sorgen, dass es ihm gut geht.", progress = nil, completion = "Gut. Sieht so aus, als hätten die restlichen Shado-Pan beschlossen, dass die Zeit zum Aufholen gekommen ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30769] = {title = "Erster Angriff", objective = "Tötet 6 Scharfhörner von Osul.", description = "Jetzt, da wir etwas Zeit hatten, die Schwächen unserer Gegner auszuloten, wird es Zeit für uns, den Yaungol einen direkten Schlag zu versetzen.\n\nGeht und fordert die Scharfhörner von Osul auf der Mesa im Westen heraus.\n\nLasst sie wissen, dass wir hier sind und keine Angst vor ihren Drohungen haben.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Ich hoffe, Ihr habt diesen Kretins keine Gnade gezeigt.", rewards = "BleichwindschulterstückSchulterstück des TempelwächtersSchulterstück des OsulgipfelsSchulterstücke des SteppenwildsSchulterstücke des SumpfläufersSchulterstück der GoldklaueSchulterstück des ErdbewegersSchulterstücke des NebellauerersSchulterstücke des NebelquellsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30770] = {title = "Wilde Flucht", objective = "Erschreckt 8 Langhaaryaks oder Steppenmushan.", description = "Jede Armee braucht eine Nachschublinie.\n\nIm feindlichen Lager im Westen gibt es eine große Tierherde, die der Yaungol-Armee als Hauptnahrungsquelle dient.\n\nZu unserem Glück sind die Yaks und Mushan hier in der Gegend ziemlich schreckhaft.\n\nSchleicht Euch an sie heran, versetzt den Tieren einen ordentlichen Klaps und wartet ab, was passiert.", progress = nil, completion = "Ohohoho! Ich konnte die Staubwolke, die die Biester hinterlassen haben, von hier oben sehen.\n\nDie Yaungol fragen sich vermutlich noch immer, was passiert ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30771] = {title = "Pech gehabt", objective = "Sammelt 8 Einheiten Schwarzpech.", description = "Wenn der Osulstamm in den Krieg zieht, imprägnieren sie ihre Speere und Pfeile mit einem leicht entzündlichen, lang brennenden Pech.\n\nMit diesen schrecklichen Waffen vergießen sie nicht nur Blut, sondern zerstören auch die Häuser ihrer Feinde.\n\nIch möchte, dass Ihr etwas von diesem Pech sammelt, während Ihr Euch in ihrem Lager aufhaltet.\n\nDamit werden wir den Yaungol zeigen, wie leicht man sich verbrennen kann, wenn man mit dem Feuer spielt.", progress = "Den Yaungol reicht es nicht, ihre Feinde einfach zu besiegen. Nein, sie wollen sie vollständig vernichten.", completion = "Es riecht noch ganz frisch.\n\nGute Arbeit, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30772] = {title = "Rot sehen", objective = "Tötet 8 Marodeure oder Feuerspucker von Osul.", description = "Vor uns befindet sich der Hauptstoß der Yaungol-Armee.\n\nDort bereitet sich ihre gewaltige Armee darauf vor, die Dörfer des Kun-Lai anzugreifen.\n\nWenn wir jetzt gegen die Yaungol von Osul vorstoßen, treffen wir sie direkt in ihrem Kern.\n\nDenkt daran: Mit jedem von ihnen, den wir niederstrecken, retten wir einen von uns zu Hause.", progress = nil, completion = "Das sollte ihre Reihen ernsthaft ausdünnen.\n\nIch bezweifle, dass sie sich von diesen Verlusten erholen werden.", rewards = "Gamaschen des NebelquellsBeinschützer des NebellauerersGamaschen des ErdbewegersBeinplatten der GoldklaueHosen des SumpfläufersBeinschützer des SteppenwildsKilt des OsulgipfelsBeinschützer des TempelwächtersBleichwindbeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30773] = {title = "Brandstiftung", objective = "Benutzt Bans Sprengstoff, um 6 Ballisten von Osul zu zerstören.", description = "Die Belagerungswaffen der Yaungol - diese Speerwerfer-Ballisten dort unten - reißen unsere Verteidigung im Außenposten Longying und am Kun-Lai-Gipfel in Stücke.\n\nDiese entsetzlichen Waffen müssen zerstört werden.\n\nNehmt diesen Sprengstoff. Ich habe ihn in das Pech getaucht, das Ihr gesammelt habt.\n\nWerft ihn auf die Ballisten, dann zahlen wir es den Yaungol mit gleicher Münze heim.", progress = "Feuer ist eine grausame Waffe. Zum Glück zerstören wir nur Kriegsgerät damit.", completion = "Sehr gut, &lt;Klasse&gt;.\n\nJetzt können sie sich nicht mehr hinter ihren Belagerungswaffen verstecken und haben keine andere Wahl, als sich uns zu stellen.", rewards = "Ihr bekommt:\n\nBans Bombenbündel"}
MultiLanguageQuestData['de'][30774] = {title = "Die Rettung der Waldläufer", objective = "Schließt Trockenholzkäfige auf, um 4 Longying-Waldläufer und Lin Stillstoß zu retten.", description = "Ich habe eine sehr wichtige Aufgabe für Euch, <Name>.\n\nIrgendwo in den Käfigen im Lager Osul sitzt mein Mann Lin. Er ist der Mittelpunkt meiner Welt.\n\nBitte findet ihn und bringt ihn mir zurück und rettet dabei so viele von unseren Shado-Pan-Genossen, wie Ihr könnt.\n\nDie Schlüssel zu den Käfigen solltet Ihr bei den Marodeuren von Osul finden.", progress = nil, completion = "Es tut mir aufrichtig leid, dass Lin es nicht geschafft hat.\n\nSuna nimmt die Neuigkeiten recht schwer. Sie wird mir schon noch verzeihen.\n\nWas die restlichen Shado-Pan angeht, die Ihr gerettet habt, so bin ich sehr dankbar, dass sie heil und unversehrt zurück sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30775] = {title = "Die Verbannung", objective = "Tötet Urang, Ku-Tong und Battat.", description = "Was gibt es da noch zu sagen, <Fremder/Fremde>?\n\nIch bin gegen Jung Duk angetreten und habe verloren. Ich war so dumm und habe geglaubt, er würde fair kämpfen.\n\nJetzt haben sich meine eigenen Brüder gegen mich gewendet, und ich bin hier und spreche mit unseren Feinden.\n\nIch weiß, dass Ihr hier seid, um Osul-Blut zu sehen.\n\nIch habe nur eine Bitte: Findet die drei, die mich verraten haben.\n\nUrang, der mir das Gift zu trinken gegeben hat. Ku-Tong, der meinen Speer verbogen hat. Und Battat, dessen Dolch in meiner Seite landete, als mir der Sieg gewiss war.\n\nGewährt mir meine Bitte, damit ich in Frieden sterben kann.", progress = "Wie konnten sie mich bloß verraten? Sie waren doch einst meine Brüder!\n\nWarum haben sie sich gegen mich gewendet? WARUM?\n\nIch hasse sie! Ich werde sie alle umbringen!", completion = "Zu wissen, dass diese Feiglinge durch Eure Hand den Tod erlitten haben, freut mich.\n\nVielleicht wird die brennende Flut in meinem Herzen jetzt verebben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30776] = {title = "Jung Duk", objective = "Stellt das Shado-Pan-Banner auf dem zeremoniellen Haufen auf und tötet dann Jung Duk.", description = "DAS. BEDEUTET. KRIEG.\n\nIch will die Köpfe aller, die mir Lin genommen haben. ALLER!\n\nAls Erstes knöpfen wir uns den Osul-Anführer Jung Duk vor.\n\nNehmt dieses Banner der Shado-Pan und hisst sie inmitten ihres Lagers.\n\nJung Duk wird keine andere Wahl haben, als sich Euch zu stellen.\n\nZeigt ihm keine Gnade, <Name>.", progress = "Jung Duks Vermächtnis ist im Blut der Unschuldigen geschrieben.", completion = "Jung Duk ist endlich tot.\n\nHunderte, vielleicht sogar Tausende, haben wegen seines gewalttätigen Wütens ihr Leben lassen müssen.\n\nAuch, wenn sie seinen Untergang nicht miterleben durften, sind sie Euch ob Euren Mutes zu Dank verpflichtet.", rewards = "Kordel des NebelquellsGürtel des NebellauerersTaillenschutz des ErdbewegersSchnallengürtel der GoldklaueKordel des SumpfläufersGürtel des SteppenwildsGürtel des OsulgipfelsGurt des TempelwächtersBleichwindgurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30777] = {title = "Auf der Suche nach Suna", objective = "Sprecht mit Ban Bärenherz, wenn Ihr in Haderzwinge angekommen seid.", description = "Ich bringe schlechte Nachrichten. Als ich zurückkam, war Suna bereits weg.\n\nDie anderen sagten, dass sie mit Sack und Pack die Straße gen Osten heruntergezogen ist und gemurmelt hat, sie werde Jagd auf den Quell der Yaungolaggression machen.\n\nIch kann nicht zulassen, dass sie sich allein in ein gefährliches Gebiet aufmacht.\n\nIch habe bereits einen Trupp Soldaten aufgestellt, um weiter nach Osten vorzustoßen.\n\nWir brechen bald auf. Schließt Euch der Karawane an, wenn Ihr mit den Shado-Pan reisen wollt. Ihr könnt uns auch dort treffen, wenn Ihr möchtet.", progress = nil, completion = "Nun, wir haben es geschafft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30778] = {title = "Staub zu Staub", objective = "Benutzt die Fackel der Shado-Pan bei 20 Bewohnern von Bleichwind.", description = "Wenn wir hier unser Lager aufschlagen wollen, können wir diese Yaungolleichen hier nicht einfach so verwesen lassen.\n\nNehmt diese Fackel und steckt die Leichen der Dorfbewohner in Brand.\n\nDas Räucherwerk der Fackel sollte auch die Erde und Luft um sie herum reinigen.\n\nSelbst unsere Feinde verdienen es, würdig bestattet zu werden.", progress = "Der Gestank des Todes ist überwältigend.", completion = "Gute Arbeit, &lt;Name&gt;.\n\nHoffentlich sind ihre Geister jetzt an einem besseren Ort.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30779] = {title = "Jagd auf Aasfresser", objective = "Tötet 8 Aschezahnhyänen.", description = "Die verwesenden Leichen locken aasfressende Hyänen an.\n\nDiese wilden Kreaturen werden nach dem Fressen der Toten nicht nur Krankheiten verbreiten, sondern uns auch angreifen, sobald sie uns sehen.\n\nZieht los und rottet die Bestien aus. Das ist zwar bedauernswert, letztendlich aber am besten.", progress = nil, completion = "Ich danke Euch, &lt;Name&gt;. Das war eine unschöne Aufgabe, doch sie musste erledigt werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30780] = {title = "Totemische Forschung", objective = "Sammelt 9 Bleichwindtotems.", description = "Als wir das Dorf betraten, fielen mir sofort die im Lager herumliegenden Yaungoltotems auf.\n\nIch vermute, dass hier finstere Mächte am Werk sind und dass die Totems der Schlüssel sind, um sie hervorzulocken.\n\nKönntet Ihr mir ein paar dieser Totems bringen? Ich würde sie gern genauer untersuchen.", progress = "Ich glaube, die Totems könnten uns nützlich sein.", completion = "Ich hatte recht! Diese Totems wurden einst zum Speichern und Leiten gewaltiger magischer Energien benutzt.\n\nIch glaube, ich kann sie wieder genau dafür verwenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30781] = {title = "Erfüllt das Soll an Yaungol", objective = "Bringt Xiao Tu zu den Rauchzeichen in der Nähe von Haderzwinge.", description = "Ban hat mich gebeten, Untersuchungen im Dorf anzustellen, um zu ergründen, was hier vorgefallen ist.\n\nIch habe Rauch im Osten, im Westen, im Nordwesten und im Süden aufsteigen sehen.\n\nIch brauche jemanden, dem ich vertraue, um mir Rückendeckung zu geben.\n\nWas sagt Ihr? Wollt Ihr mich auf meiner ersten Spähmission unterstützen?", progress = "Etwas Furchtbares muss hier passiert sein.", completion = "Danke für Eure Hilfe, &lt;Name&gt;.\n\nWir wissen zwar nicht genau, was dort passiert ist, aber offensichtlich hat irgendetwas die Yaungol gegeneinander aufgehetzt.\n\nDoch was hätte solche Macht?", rewards = "Fackel der MittagsstundeFackel der MorgenröteFackel der AbendröteZwinge des HassesSha-verseuchte KlingeBogen des Shado-Pan-WaldläufersBiss des HassesTrennende SchneideKlinge des Shado-Pan-WaldläufersBärenherz' KeuleIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30782] = {title = "Boshafte Geister", objective = "Tötet 10 boshafte Geister.", description = "Die Geister der gefallenen Dorfbewohner haben sich erhoben! Ich spüre den Hass, der von diesen Geistern ausströmt.\n\n<Name>, wenn wir hier überleben wollen, müssen wir uns verteidigen. Nur so können wir zur Ruhe betten.", progress = nil, completion = "Gut gemacht. Wir können ihnen keine Vergeltung bringen, doch zumindest können wir ihrem Zorn ein Ende bereiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30783] = {title = "Der Hass steht uns gut", objective = "Benutzt das Totem der Harmonie, um 8 wahnsinnigen Shado-Pan-Waldläufern die Sha-Geister auszutreiben. Besiegt Manifestationen Sengenden Hasses, um Eure Verbündeten zu läutern.", description = "Ich hätte schon vorher die Präsenz eines Sha vermuten sollen!\n\nWir sind in Sicherheit, solange wir uns innerhalb des Zauberschutzes des Totems der Harmonie befinden, aber viele von uns hatten es nicht so gut.\n\nSie saßen außerhalb des Lagers fest, als sich die Kräfte des Sha manifestierten und jetzt gehen sie aufeinander los!\n\nNehmt eins meiner Totems mit. Platziert das Totem in der Nähe von verrückt gewordenen Verbündeten, um sie zu läutern, aber seid vorsichtig.\n\nIhr könntet es mit jener Dunkelheit zu tun bekommen, die von ihnen Besitz ergriffen hat.", progress = nil, completion = "Danke.\n\nDas Sha sucht sich die Schwachen und Verwundbaren als Opfer.\n\nWenn wir nicht achtgeben, werden selbst die Stärksten unter uns dem finsteren Einfluss des Sha anheimfallen.", rewards = "Ihr bekommt:\n\nTotem der Harmonie"}
MultiLanguageQuestData['de'][30784] = {title = "Punkt ohne Wiederkehr", objective = "Sucht Suna Stillstoß.", description = "Einer von unseren Waldläufern meldet, Suna auf dem Hügel im Nordwesten gesehen zu haben.\n\nIch hatte die schlimmsten Befürchtungen, was sie in ihrem Kummer machen würde, und bin erleichtert, dass sie unversehrt ist.\n\nWürdet Ihr zu ihr gehen und mit ihr sprechen?\n\nNehmt dieses Totem mit. Es könnte Euch nützlich sein, wenn Ihr unterwegs in Gefahr geratet.", progress = "Wenn ich die Vergangenheit ändern könnte, dann würde ich das machen. Wenn ich Lins Platz einnehmen könnte, dann würde ich das machen.\n\nSelbst in tausend Leben kann ich Sunas Verlust nicht wiedergutmachen oder ihr auch nur einen Bruchteil ihrer Trauer abnehmen.", completion = "Was? Sie war von dem Sha des Hasses besessen?\n\nNein. OH NEIN!\n\nWir hatten unsere Differenzen, doch sie war eine von uns. Heute haben die Shado-Pan eine geschätzte Schwester verloren.\n\nIhr Tod soll nicht umsonst gewesen sein. Ich werde erst ruhen, wenn ich das Sha des Hasses bezwungen habe!\n\nDas verspreche ich Euch, Suna!", rewards = "Robe des NebelquellsNebellauerertunikaRüstung des ErdbewegersBrustschutz der GoldklaueRobe des SumpfläufersTunika des SteppenwildsRüstung des OsulgipfelsBrustharnisch des TempelwächtersBleichwindbrustschutzIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30785] = {title = "Gao-Ran-Front", objective = "Sprecht mit Meister Taran Zhu an der Gao-Ran-Front in der Tonlongsteppe.", description = "Mit Eurer Hilfe haben wir die Geister dieses Orts bezwingen können.\n\nEndlich können sie in Frieden ruhen.\n\nUnsere Reise in dieses verfluchte Land hat jedoch gerade erst begonnen.\n\nIch habe noch einige wichtige Dinge hier zu regeln, doch bald werden wir ausschwärmen.\n\nIch brauche jemanden, der vorausgeht und Meister Taran Zhu ausrichtet, dass wir zu ihm stoßen werden.\n\nIhr findet ihn an der Gao-Ran-Front. Sagt ihm, was hier zutage getreten ist.", progress = nil, completion = "Dann ist die Nordexpedition gut gelaufen? Was gibt es Neues zu berichten?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30786] = {title = "Ein Speer in meiner Seite; die Seele in Ketten", objective = "Tötet Dmong Naruuk, den Schamanen, der Orbiss als Geisel festhält.", description = "Mein Schicksal ist besiegelt. Die Yaungol haben mir diesen Speer in die Seite getrieben. Die Wunde wird mein Tod sein.\n\nDie Yaungol haben mich mit ihrer verqueren, verdorbenen Magie auf der Stelle festgesetzt. Diese Schmach schmerzt mir mehr als die Speerwunde.\n\nMeinem Tod kann ich nicht entrinnen. Doch mein Gefängnis... aus dem könnt Ihr mich womöglich befreien.", progress = "Ich werde nicht sterben, bevor ich Rache geübt habe.", completion = "Ich bin frei.\n\nDie Yaungol müssen aufgehalten werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30787] = {title = "Die Fackeln", objective = "Besorgt 6 Nebelschamanenfackeln.", description = "Bis vor Kurzem kamen die Schamanen der Yaungol hierher, um gemeinsam mit uns zu arbeiten. Jetzt unterjochen sie mein Volk.\n\nWenn wir uns weigern, töten sie uns. Und wenn wir gehorchen... töten sie uns ebenfalls.\n\nDie Magie eines Nebelschamanen der Yaungol fließt durch seine Fackel. Nehmt ihm seine Fackel und ihm bleibt nichts mehr.", progress = "Mit diesen Fackeln kann ich Rache üben.\n\nIch bin dieser Wunde noch nicht erlegen. Ich kann mich immer noch rächen, ehe ich sterbe.\n\nMir bleibt noch Zeit.", completion = "Diese Fackel... früher haben die Yaungol sie benutzt, um mit mir, mit meinem Volk zu kommunizieren.\n\nJetzt machen sie uns mit ihnen zunichte.", rewards = "NebelschamanenhalsketteAnhänger von OrbissMedaillon der SumpfbinsenAnhänger der RacheAmulett der SehnsuchtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30788] = {title = "Golgoss", objective = "Beschwört Golgoss, indem Ihr die Nebelschamanenfackeln im Torfklumpen auf der Sumpfbinsenhöhe platziert.", description = "Der Anführer der Yaungol-Nebelschamanen heißt Jahesh. Er ist für seine Stärke bekannt.\n\nEs gibt einen unter den Meinen, der ebenfalls für seine Stärke bekannt ist. Sein Name ist Golgoss.\n\nGolgoss schlummert in den Nebeln der Sumpfbinsenhöhe. Helft mir, ihn zu beschwören, und er wird an meiner Seite unser Volk rächen.", progress = nil, completion = "Golgoss spricht Eure Sprache kaum - höchstens ein paar Worte. Ich glaube, dass ich in dieser Hinsicht ziemlich einzigartig bin.\n\nEr dankt Euch für Eure Unterstützung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30789] = {title = "Arconiss", objective = "Beschwört Arconiss, indem Ihr die Fackeln des Nebelschamanen im Torfhügel auf der Sumpfbinsenhöhe aufstellt.", description = "Wenn ich Jahesh, den Anführer der Nebelschamanen der Yaungol bekämpfen soll, brauche ich Arconiss an meiner Seite, denn seiner Grausamkeit kann keiner das Wasser reichen.\n\nEr ruht unter den Nebeln der Sumpfbinsenhöhe. Sucht seine Ruhestätte und benutzt dann diese Fackeln, um ihn aufzuwecken.", progress = nil, completion = "Mit Arconiss an meiner Seite werde ich kaum verlieren können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30790] = {title = "Golgoss' Hunger", objective = "Sammelt 10 Knotranken.", description = "Golgoss' Stärke ist groß, doch bevor er sich ihrer bedienen kann, braucht er Nahrung.\n\nDie Knotdornbüsche in der Sumpfbinsenhöhe haben dicke, faserige Äste. Die sollten seinen Hunger stillen.", progress = "Golgoss' Hunger ist groß.", completion = "Damit sind wir meinem Ziel einen Schritt näher.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30791] = {title = "Arconiss' Durst", objective = "Sammelt 4 Einheiten geronnenes Nagetierblut.", description = "Arconiss kämpft mit einer Raserei, die ihresgleichen sucht, doch er hat so lange unter den Nebeln geruht, dass er geschwächt ist.\n\nIm Sumpf wimmelt es vor Nagetieren, deren Körper prall mit nahrhaftem Blut gefüllt sind. Kehrt mit genug Blut zurück, um Arconiss' Kampfgeist zu wecken.", progress = "Unsere Vorbereitungen werden nicht mehr lange dauern.", completion = "Damit bin ich dem Erfolg meiner Mission einen Schritt näher.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30792] = {title = "Orbiss verblasst", objective = "Sammelt 8 Sprudelnebel, indem Ihr durch die Nebelgeysire auf der Sumpfbinsenhöhe lauft.", description = "Ich wusste, dass der Tod kommen würde. Allerdings war mir nicht klar, dass es so schnell geschehen würde.\n\nIch muss Zeit gewinnen. Der Nebel der Sumpfbinsenhöhe ist warm und wohlriechend. Diese Art Nebel ist für mein Volk nahrhaft.\n\nSammelt den Nebel auf jede nur erdenkliche Art... in Gläsern, Phiolen, in Euren Taschen. Bringt ihn zu mir, damit ich mich etwas länger körperlich manifestieren kann.", progress = "Ich brauche mehr Nebel. Ich verblasse...", completion = "Ich habe Euch doch gesagt, diese Wunde wird mein Tod sein. Ihr habt mir zwar etwas mehr Zeit verschafft, doch geht es bald mit mir zu Ende.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30793] = {title = "Gelegenheiten im Nebel", objective = "Erschlagt Jahesh von Osul.", description = "Die Zeit ist reif für einen Angriff.\n\nGolgoss, Arconiss und ich werden nach Osten, zu Jaheshs Domäne, aufbrechen. Stoßt dort zu uns und bereitet Euch auf den Kampf vor.\n\nHeute stellen wir den Stolz unseres Volkes wieder her.", progress = nil, completion = "Mein Name wird in Vergessenheit geraten, nicht jedoch meine Taten.\n\nUnd Eure auch nicht, &lt;Name&gt;.", rewards = "Mantelung des NebelquellsSchiftung des NebellauerersSchiftung des ErdbewegersSchiftung der GoldklaueAmicia des SumpfläufersSchiftung des SteppenwildsSchiftung des OsulgipfelsSchultern des TempelwächtersBleichwindschulternDer folgende Zauber wird auf euch gewirkt:\n\nMists' Opportunity: Complete\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30794] = {title = "Notfallversorgung", objective = "Heilt den Weisen Liao, damit er wieder auf die Beine kommt.", description = "Ich... bin am Leben... aber nur gerade so. Sie haben den Rest getötet. Meine Freunde... meine Familie...\n\nIch muss zum Dorf zurück... Aber ich habe nicht mehr lange, und ich kann mich nicht bewegen... Seid Ihr <ein Heiler/eine Heilerin>? Ich... habe einen Heiltrank in meiner Hütte... oder setzt Magie ein, wenn Ihr könnt.", progress = nil, completion = "Vielen Dank... Ich schätze... ich werde Euch um noch etwas bitten müssen, bevor ich ins Dorf zurückkehren kann. Ich kann die Leichen meiner Freunde und meiner Familie nicht hier zurücklassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30795] = {title = "In Verbindung bleiben", objective = "Benutzt die Zunge von Ba-Shon im Tal der Kaiser.", description = "Die Zunge von Ba-Shon sollte es uns ermöglichen, über große Entfernungen zu kommunizieren, <Name>.\n\nWenn das Relikt so funktioniert, wie ich glaube, sollte ich in der Lage sein, hier zu bleiben und mit meinen Meditationen fortzufahren, während Ihr das Tal der Kaiser etwas ausspäht.\n\nMishi wird Euch bis an den Rand des Tals bringen, damit wir meine Theorie testen können. Mir wäre nicht wohl dabei, wenn Ihr in den Gräbern wärt und keine Möglichkeit hättet, mich zu kontaktieren. Das wäre schrecklich!", progress = nil, completion = "Sehr gut! Das Relikt funktioniert!\n\nEs scheint mehr im Tal der Kaiser vor sich zu gehen, als ich erwartet habe. Es ist wichtig, dass wir herausfinden, warum die Mogu die Gräber öffnen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30796] = {title = "Alles hat ein Ende", objective = "Vernichtet 5 gequälte Geister.", description = "Diese Geister müssen freigelassen worden sein, als die Grabmale geöffnet wurden...\n\nDer Tod war nicht das Ende für die Mogu. Stattdessen war der Tod nur ein kurzer Halt auf dem Weg zu einem neuen Körper. Geisterbinder haben üble Magie eingesetzt, um Geister von einer Hülle zur nächsten zu übertragen.\n\nDie Jahre, die sie in den Grabmalen eingeschlossen waren, haben sie verwirrt. Sie müssen vernichtet werden, bevor sich ihre Verwirrung in Zorn verwandelt oder, was noch schlimmer ist, sie eine neue Hülle finden.", progress = nil, completion = "Ihr habt ihnen einen großen Dienst erwiesen, &lt;Name&gt;.\n\nZwischen der Welt der Lebenden und dem Jenseits festzustecken, ist ein grausames Schicksal.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30797] = {title = "Es hat fast gelebt", objective = "Reißt eine Seite aus dem offenen Buch, um sie Lehrensucher Cho zu bringen.", description = "Hier hat ein Ritual stattgefunden, und wie es scheint, war es nicht von Erfolg gekrönt.\n\nUnter den zurückgelassenen Gegenständen befindet sich ein offenes Buch. Die Sprache des Texts auf der Seite ist Euch fremd.\n\nEs könnte schwierig werden, das ganze Buch zu tragen, aber vielleicht reicht eine Seite. Wenn Ihr die Seite zu Lehrensucher Cho schaffen könnt, ist er vielleicht in der Lage, Euch zu sagen, was dort steht.", progress = "Was habt Ihr gefunden, <Name>?", completion = "Der Text ist in der Tat seltsam, &lt;Name&gt;...\n\nEr scheint in der Mengdynastie geschrieben worden zu sein, aber einige der Symbole sind falsch. Ich glaube nicht, dass die Mogu dies verfasst haben, obwohl es dem seltsam nahe kommt.\n\nIch werde einige Zeit brauchen, um es zu übersetzen. Bleibt in Bewegung und seht zu, ob Ihr noch etwas anderes finden könnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30798] = {title = "Zertrümmerung des Schilds des Kaisers", objective = "Stoppt das geistbindende Ritual im Grab der Geheimnisse.", description = "Die Mogu wurden zerstreut und waren jahrelang nur wenige. Ihr Vorhaben im Tal ergibt nun einen Sinn.\n\nBei diesen vielen rastlosen Geistern können sie mit den in den Gräbern liegenden Wächtern eine Armee aufbauen. Zusammen mit den Streitkräften der Zandalari wäre das verheerend!\n\nDas Grab der Geheimnisse beherbergt Elitekämpfer, die man den Schild des Kaisers nannte. Sie dürfen nicht wiedererweckt werden! Ihr findet das Grab auf der höchsten Erhebung im Südwesten.", progress = "Wart Ihr schon beim Grab der Geheimnisse?", completion = "Die Mogu und die Zandalari haben vor, den Donnerkönig wiederzubeleben?!\n\nDas dürfen wir nicht zulassen, &lt;Name&gt;! Der Donnerkönig wird mit seiner Rückkehr Zerstörung über dieses Land bringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30799] = {title = "Das Grab der Schatten", objective = "Sammelt ein Abpausbild der Tafel aus der Shendynastie, der Tafel der Waidynastie und der Tafel der Qiangdynastie im Grab der Schatten.", description = "Die Artefakte, die Ihr auf dem Altar gefunden habt, bringen mich zu der Annahme, dass sie versucht haben, ein Geistbindungsritual durchzuführen.\n\nDie meisten Texte über Geistbindung waren im Grab der Schatten weggesperrt. Vielleicht finden wir dort die Antworten, die wir suchen.\n\nHaltet nach allem Ausschau, das uns helfen könnte. Ihr findet das Grab auf der ersten Erhebung vom Ritualaltar aus gesehen.", progress = "Habt Ihr im Grab der Schatten etwas gefunden?", completion = "Diese Tafeln erzählen die Geschichte des Bündnisses zwischen den Mogu und den Zandalari aus der Zeit des ersten Mogukaisers.\n\nWie es aussieht, haben sie ihr Bündnis wiederbelebt. Aber warum jetzt?", rewards = "Band des GeisterbindersRing des FlammenwütersJadegeschmückter SiegelringSiegelring des blauen BergesBand der unversiegelten GruftIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30800] = {title = "Ihren Donnerkönig stehlen", objective = "Findet das unterste Fragment von Lei Shens Tafel und stellt die Tafel des Donners wieder her.", description = "Unsere einzige Hoffnung besteht darin, die Überreste des Donnerkönigs vor ihnen zu finden. Er muss im Grab der Eroberer begraben sein.\n\nAn seine Überreste zu kommen wird nicht einfach sein, <Name>. Das Grab wird zweifellos von Wächtern und anderen unangenehmen Überraschungen verteidigt werden, die Diebe fernhalten sollen.\n\nWenn Ihr erst einmal drin seid, müsst Ihr herausfinden, wo man seine Überreste nun wirklich abgelegt hat.", progress = "Habt Ihr herausgefunden, wo die Überreste des Donnerkönigs versteckt liegen?", completion = "Wir haben Glück, dass sie Lei Shens Überreste nicht gefunden haben...noch nicht.\n\nDie Zandalari werden nicht aufgeben, bis sie haben, was sie wollen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30801] = {title = "Geschichtsstunde", objective = "Lest die Schrifttafel des Donners im Grab der Eroberer.", description = "Der Donnerkönig war ein grausamer Herrscher und mit den Zandalari an seiner Seite war er nicht aufzuhalten. Seine Rückkehr würde dieses Land mit Sicherheit in Aufruhr und Elend stürzen.\n\nIhr müsst seine Überreste aufspüren und sie in Sicherheit bringen. Die Schrifttafel des Donners sollte Euch Aufschluss darüber geben, wie man in sein Grabmal hineingelangt.", progress = nil, completion = "Sie werden die Überreste an einen sicheren Ort schaffen müssen. Wir müssen sie verfolgen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30802] = {title = "Sturmjäger", objective = "Findet die durch Blut enthüllte Karte bei einem Krieger der Zandalari.", description = "Wir müssen herausfinden, wohin sie die Überreste des Donnerkönigs bringen würden. Es wird ihnen nicht möglich sein, ihn im Tal der Kaiser wiederzuerwecken. Sie müssen weiter entfernt und in Sicherheit sein.\n\nEs scheint, als ob es zudem eine weitere Herausforderung wäre, hier herauszukommen...\n\nKämpft Euch nach draußen durch und sucht nach Informationen darüber, wo sich die Überreste befinden.", progress = "Konntet Ihr Informationen zu ihrem Aufenthaltsort finden?", completion = "Das ist dunkle Blutmagie der Zandalari. Wenn wir mit der Karte fertig sind, sollten wir sie verbrennen.\n\nLaut Karte sind sie an die Küste etwas außerhalb eines kleinen Fischerdorfs namens Zouchin gezogen. Die Dorfbewohner dort können uns vielleicht helfen, die Zandalari aufzuspüren.", rewards = "Mal des LehrensuchersEmblem des LehrensuchersSiegel des LehrensuchersMedaillon des LehrensuchersInsigne des LehrensuchersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30804] = {title = "Der Angstmeister", objective = "Tötet den Angstmeister.", description = "Ich halte das nicht mehr aus. Meine Frau, gesegnet sei sie, steckte ihr Herz und ihre Seele in diese Ranch und machte sie zu dem, was sie heute ist.\n\nDiese Yaungol haben da einen Führer, der unglaublich arrogant und was noch alles ist. Ich werde Euch großzügig belohnen, wenn Ihr ihm dieses arrogante Grinsen aus seinem dreckigen, stinkenden, nichtsnutzigen Gesicht prügelt.", progress = nil, completion = "Jahuu! Ich wusste, ein &lt;Volk&gt; wie Ihr ist zu etwas zu gebrauchen. Es muss einen befriedigenden \"Bums\" gegeben haben, als er auf dem Boden aufgeschlagen ist.", rewards = "KafasatintreterKafabalgfußschützerStiefel des träumenden GeistesBrünierte KafaschienbeinschützerSeidene KafatreterKafalederstiefelStiefel des YakhirtenSchwere KafakriegsstiefelGepanzerte KafakriegsstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30805] = {title = "Gerechtigkeit", objective = "Tötet Hauptmann Fleischreißer und 6 Schwarzmähnenbriganten.", description = "Nachdem die Söldner uns ausgeraubt hatten, sind die meisten von ihnen verschwunden.\n\nAber einer von ihnen... nachdem die anderen uns alles genommen hatten... Er nahm sich den Rest von uns vor. Als Sport!\n\nLasst Gerechtigkeit für die Gefallenen walten. Vielleicht hebt die Nachricht von ihrem Tod meinen Geist genug, damit ich weitermachen kann.\n\nIhr findet sie westlich von hier.", progress = nil, completion = "Ahh... sie sind tot. Ich spüre schon, wie mein Geist belebt wird. Bald werde ich stark genug sein, um zum Dorf zurückzukehren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30806] = {title = "Der Duft des Lebens", objective = "Sammelt einen schimmernden blauen Krabbenpanzer und 8 gestohlene Pandarengewürze.", description = "Viele sind hier gestorben. Wir müssen sie auf passende Weise ehren, was bedeutet, die Zutaten für das Räucherwerk des Lebens zu sammeln.\n\nEs riecht nicht nur gut - es hat auch stärkende Eigenschaften und begünstigt sogar das Wachstum von Pflanzen. Vielleicht hilft ein Hauch der Zutaten auch mir wieder auf die Beine.\n\nIhr findet das Material bei den Kreaturen hier - nur nicht die Gewürze, die von den Söldnern gestohlen wurden, die das Dorf geplündert haben.", progress = "Rieche ich da die Zutaten für das Räucherwerk des Lebens an Euch? Oder... habt Ihr vielleicht länger nicht mehr gebadet?", completion = "Wunderbar, wunderbar. Es wäre besser, wir müssten unsere Freunde nicht begraben, aber wenn wir es schon tun müssen, dann ist es gut, dass sie eine passende Zeremonie bekommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30807] = {title = "Bei den Fällen, für die Gefallenen", objective = "Sammelt 3 vom Wasserfall geglättete Steine.", description = "Ich möchte meine Freunde nicht in namenlosen Gräbern zurücklassen und sie damit entehren.\n\nDoch haben wir noch nie so viele auf einmal begraben müssen, und ich bin nicht in der Verfassung, das Material zu sammeln.\n\nGeht bitte zu den Seen, die den Bergausläufer an der Straße nach Süden umfassen. Unter den Wasserfällen dort werdet Ihr Steine finden, die durch das fallende Wasser glänzend poliert worden sind. Sie werden geeignete Grabsteine abgeben.", progress = "Die Steine - habt Ihr sie dabei?", completion = "Gut. Danke schön. Nach all dem kann ich mir nicht vorstellen, meine Kameraden mit weniger als einem ordentlichen Begräbnis zurückzulassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30808] = {title = "Das Glück eines Grummel", objective = "Findet 8 gestohlene Glücksbringer.", description = "Die Yaungol haben unsere Glücksbringer gestohlen! Gemeine Reiter mit Speeren haben sie einer Karawane von Brüdern auf dem Jutepfad weggenommen.\n\nDas ist ein sehr großes Unglück. Wenn die Yaungol die Geheimnisse von den Glücksbringern entdecken, sind alle Grummel in großen Schwierigkeiten.\n\nHolt unsere Glücksbringer aus dem Streitlager Ruqin nördlich von hier zurück, dann zahlen wir Euch großen Reichtum.", progress = "Ein Glücksbringer bringt viel, viel Glück. Yaungol wissen nicht, wie sie Glücksbringer anwenden müssen... noch nicht.", completion = "Hurra! Unsere Glücksbringer. Vielen Dank und Glück an Freund von Grummel!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30814] = {title = "Ein Fuß in der Tür", objective = "Tötet 8 Stürmer von Osul.", description = "<Lord Taran fängt Euch in seinem stählernen Blick.>\n\n<Klasse>, Ihr tragt das Mal so manch einer geschlagenen Schlacht.\n\nGut! Wir können mehr kampferprobte Leute wie Euch gebrauchen, um die Front zurückzuschlagen.\n\nWir konnten hier zwar Fuß fassen, doch die Yaungol sind darauf erpicht, uns zu vertreiben.\n\nWenn Ihr Euch beweisen wollt, geht den Hügel hinunter und zeigt diesen Yaungol, dass wir nicht klein beigeben werden.", progress = "Wir gewinnen langsam an Boden.", completion = "Gut. Ich sehe schon, Ihr seid fähig.\n\nIch hoffe, ich kann mich für das, was kommen mag, auf Eure Talente berufen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30815] = {title = "Mein Tod", objective = "Zieht den Speer aus Orbiss.", description = "Ich habe beschlossen, diesen Speer aus meiner Flanke zu entfernen.\n\nDabei brauche ich Eure Hilfe. Eure zupackenden Hände sind stärker als meine.", progress = nil, completion = "Mit der Entfernung dieses Speers habe ich meinen eigenen Tod wahrhaftig garantiert.\n\nDas macht mir keine Angst.\n\nLieber sterbe ich, als die Waffe meines Feindes mit mir zu führen.", rewards = "SchluckspechtstreitkolbenHalcyontodSchild des OrbissGekrümmte KlingeWiderhaken des NebelschamanenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30816] = {title = "Nachsehen", objective = "Seht nach dem Weisen Liao auf dem Zaochin-Strand am Kun-Lai-Gipfel.", description = "Als die Trolle kamen, brachten sie ihre... Söldnerfreunde mit. Ich sah sie an uns vorbeiziehen, zum Anglerlager im Nordwesten. Mein Cousin, ein Heiler, lebt dort - könnt Ihr nach ihm sehen und Euch vergewissern, dass es ihm und seinem Dorf gut geht?", progress = nil, completion = "Ah... Mein Cousin macht sich aus gutem Grund Sorgen... Es geht mir nicht gut...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30817] = {title = "Die Heilung von Shen-zin Su", objective = "Rettet und beschützt die Heiler, bis Shen-zin Sus Wunde geheilt ist.", description = "Das kommt von solcher Rücksichtslosigkeit. Wie konnte er nur annehmen, dass dieser Plan aufgehen würde?\n\nWie auch immer, wir haben jetzt keine Zeit für Schuldzuweisungen. Wir müssen handeln, um Shen-zin Su zu retten.\n\nFindet so viele Heiler, wie Ihr nur könnt! Befreit sie, entbindet sie von anderen Aufgaben - tut, was auch immer Ihr tun müsst, damit sie hierherkommen und diese Wunde heilen können.\n\nBeschützt sie um jeden Preis!Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Gelenkbänder des HeilersZeremonielle GamaschenRitualbrustplatteDer folgende Zauber wird auf euch gewirkt:\n\nBlackout into Healed Phase\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30818] = {title = "Ein neues Schicksal", objective = "Kehrt zum Tempel der Fünf Sonnenaufgänge zurück. Ein Karren wartet in der Nähe der Absturzstelle der Himmelsfeuer, um Euch dorthin zu bringen.Ich bin froh und dankbar, dass der Plan aufgegangen ist, <Name> - auch wenn es knapper kaum hätte werden können. Wenn Ihr nicht gewesen wärt, würden wir alle zusammen mit ganz Shen-zin Su zum Meeresgrund sinken. Ich glaube nicht, dass ich Ji diese Rücksichtslosigkeit jemals verzeihen können werde.\n\nEs wird noch genug Zeit zur Besinnung geben, aber wir müssen zuerst zum Tempel der Fünf Sonnenaufgänge zurückkehren. Wir müssen sie wissen lassen, dass Shen-zin Su gerettet wurde - und wir müssen über das Schicksal dieser neuen Verbündeten entscheiden.Der folgende Zauber wird auf euch gewirkt:\n\n", description = "Ich bin froh und dankbar, dass der Plan aufgegangen ist, <Name> - auch wenn es knapper kaum hätte werden können. Wenn Ihr nicht gewesen wärt, würden wir alle zusammen mit ganz Shen-zin Su zum Meeresgrund sinken. Ich glaube nicht, dass ich Ji diese Rücksichtslosigkeit jemals verzeihen können werde.\n\nEs wird noch genug Zeit zur Besinnung geben, aber wir müssen zuerst zum Tempel der Fünf Sonnenaufgänge zurückkehren. Wir müssen sie wissen lassen, dass Shen-zin Su gerettet wurde - und wir müssen über das Schicksal dieser neuen Verbündeten entscheiden.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nPandaren Faction Choice\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30819] = {title = "Vorbereitung der Überreste", objective = "Kehrt zu Li Hai zurück und erzählt ihm vom Begräbnis.", description = "Vielen Dank, <mein Freund/meine Freundin>. Nach dieser Tragödie ist es gut, dass das Glück uns hold war und Euch geschickt hat.\n\nIhr habt Gerechtigkeit für meine gefallenen Freunde walten lassen und die Materialien gesammelt, die für ihre Ehrung nötig waren. Ich werde ihre Leichname bergen, die Materialien für ihre Begräbnisse vorbereiten und Euch dann am Friedhof treffen.\n\nKehrt bitte in der Zwischenzeit zu meinem Cousin zurück und bittet ihn, die Dorfbewohner für das Begräbnis zu versammeln.", progress = nil, completion = "Ich verstehe... es ist tragisch, was hier passiert ist. Wir werden zum Friedhof kommen, um sie zu ehren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30820] = {title = "Ein Begräbnis", objective = "Wohnt dem Begräbnis bei und entzündet das Räucherwerk des Lebens.", description = "Wie gesagt, ich werde die Stadt versammeln - wir werden zum Begräbnis erscheinen.\n\nWir sind der Meinung, dass es nur recht ist, das Ihr als <derjenige, der/diejenige> die; so viel getan hat, um unsere Freunde zu ehren, das Räucherwerk des Lebens anzünden und ihre Geister in das Leben danach geleiten solltet.", progress = "Ihr müsst das Räucherwerk entzünden, um die Toten zu ehren.", completion = "Gut. Lasst uns mit dem Begräbnis beginnen.", rewards = "WasserfallmantelungMushanlederschiftungSchiftung des träumenden GeistesSchiftung des GleichmutsAmicia des GeistbeugersSchiftung der lautlosen BlätterSchiftung des YakhirtenSchultern des GipfelwächtersSchultern der MauerwacheDer folgende Zauber wird auf euch gewirkt:\n\nQuest - Start Funeral Event\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30821] = {title = "Das Jutepfadmassaker", objective = "Sprecht mit Kota Kon im Basislager am Kota, um sie reiten zu dürfen und 100 Ho-zen entlang des Jutepfades zu töten.", description = "So, jetzt ist es Zeit für Kota Kons \"Ausflug\".\n\nWir haben extra für sie zwei Kannen Kafa gekocht - jetzt ist sie startbereit!", progress = "Kota Kon wartet auf Euch! Sie lässt sich nur von Euch reiten.", completion = "Ha, ha! Wir haben diese Affen selbst von hier noch schreien hören!\n\n&lt;Buchsbaum wendet sich Kota Kon zu.&gt;\n\nWas bist du nur für ein hübsches und braves Mädchen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30823] = {title = "Im Rausch der Zägen", objective = "Besiegt 12 Kafa-berauschte Bergziegen auf der Kotaspitze.", description = "Mein Vetter drüben beim Basislager am Kota hat es vermusselt. Er hat es schlimm vermusselt.\n\nEr war zu faul, um Samen von Hand aus Kafa-Beeren herauszuschneiden. Er hat festgestellt, dass Zägen die Beeren essen und die Samen zurückgeben... nach einem Tag oder so.\n\nEr hat alles, was er hatte, an die Zägen auf der Kotaspitze verfüttert, und jetzt sind sie verrückt! Sie greifen alles an, was sich bewegt.\n\nKota war sicheres Gebiet für Grummel zum Kafa-Sammeln. Nicht mehr. Nicht mit den Zägen. Werdet Ihr helfen?", progress = nil, completion = "Danke für Eure Hilfe. Danke, dass Ihr meinen Fehler behoben habt, mein Freund. Lasst Euch dies eine Lehre sein: Füttert nie die Zägen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30824] = {title = "Gourmet-Kafa", objective = "Markiert 10 Kafa'zäge-\"Vorkommen\"\" auf der Kotaspitze.", description = "Das war eine verrückte Idee: Kafa-Beeren in Zäge, Samen kommen raus.\n\nKafa'kota ist schon selten und Vermögen wert, aber Erfindung von meinem Vetter - Kafa'zäge - ist GOURMET.\n\nAber das jetzt vorbei. Onkel Kühnbohn ist aufgeregt und Gipfel ist nicht sicher. Jetzt nur noch eins zu tun: Den Rest von Kafa'zäge sammeln und es nie wieder machen.\n\nIch bitte Euch nicht, es einzusammeln - keine schöne Aufgabe, nichts für Helden - markiert es einfach, damit wir es leichter finden, wenn der Berg wieder sicher ist.", progress = nil, completion = "Ich habe gehört, dass ein Abenteurer dort oben war und die Vorkommen markiert hat. Keine schöne Aufgabe für jemand mit Euren Fähigkeiten, aber ich weiß es zu schätzen.\n\nIch werde dort hoch gehen und... sie bald einsammeln.\n\n&lt;Cousin Zägenfell fängt an, sich lange Leinenstreifen um die Hände zu wickeln.&gt;\n\nKann nicht glauben, dass ich dachte, es wäre eine gute Idee.", rewards = "Ihr bekommt:\n\nKühnbohn Kafa"}
MultiLanguageQuestData['de'][30825] = {title = "Edle Kota-Mischung", objective = "Sammelt 100 Kafa'kota-Beeren auf der Kotaspitze. Ihr findet sie in den Büschen in den Bergen oder in den Yeti-Höhlen aufgehäuft.", description = "Kotaspitze ist berühmt für Kafa-Büsche. So weit oben kann nichts anderes wachsen.\n\nGrummel verdienen gutes Geld mit edle Kafa'kota-Mischung. Aber jetzt ist gefährlich. Schuld hat mein Vetter. Hat die Tiere da oben mit Kafa gefüttert und verrückt gemacht.\n\nKafa'kota seltener als je zuvor: Zägen fressen Kafa'kota auf. Yetis bringen Kafa'kota in ihre Höhlen.\n\nOnkel Kühnbohn bezahlt Euch gut für alle Beeren, die Ihr vom Kota holt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30826] = {title = "Ärger braut sich zusammen", objective = "Tötet 5 Kafa-berauschte Yetis in den Höhlen der Kotaspitze.", description = "Eine Menge Yetis in Kota, jepp. Normalerweise nicht gefährlich. Normalerweise essen nur Zägen.\n\nDann dummer Cousin Zägenfell drüben beim Basislager am Kota füttert Kafa an die Zägen und dann die Yeti fressen die Zägen.\n\nJetzt sind launisch, stinkig, schlafen viel, aber sind nie ausgeruht. Typische Kafasüchtige.\n\nKommen bald aus den Höhlen, ich bin sicher. Kommen und suchen nach mehr Kafa.\n\nDann wir alle haben Ärger.", progress = nil, completion = "Ach, hallo! Humpen hat einen Yakboten geschickt, um uns zu sagen, dass Ihr uns bei unserem Yetiproblem helft.\n\nUnd Ihr seid nicht in kleine Stücke zerrissen! Yetis sind schon alleine hart - kann mir nicht vorstellen, wie ein stinkiger Kafa-süchtiger Yeti sein muss. Ihr seid mutig. Oder habt Glück. Oder seid dumm.\n\nVielleicht alles drei.", rewards = "Ihr bekommt:\n\nTasse Kafa"}
MultiLanguageQuestData['de'][30827] = {title = "Schatten der Wahrheit", objective = "Sprecht mit Yalia Weisenwisper, um die Zeremonie zu beginnen.\n\nAktiviert dann das Totem der Güte, das Totem der Gelassenheit und das Totem der Ruhe.", description = "Wenn ich mich nicht irre, hängt über diesem Ort eine anhaltende Finsternis.\n\nWas auch immer hier vorgefallen ist... es war jedenfalls kein natürliches Ereignis.\n\nNicht einmal die Yaungol sind brutal genug, um ihre eigenen Artgenossen auf diese Weise... abzuschlachten.\n\nIch werde mit den Totems, die Ihr mir gebracht habt, ein Läuterungsritual durchführen.\n\nIch brauche jemanden, der mir bei der Zeremonie hilft. Sagt Bescheid, wenn Ihr soweit seid.", progress = nil, completion = "Wir blicken in das wahre Antlitz des Hasses!\n\nJetzt ergibt alles Sinn. Das ist das Werk des Sha.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30828] = {title = "Reinigung des Weihers", objective = "Sucht Euch Lachen der Verderbnis am Tintenkiemenweiher und zeigt sie Wassersprecher Gorai, um ihn wissen zu lassen, dass Ihr bereit seid, ihn zu verteidigen, während er das Reinigungsritual vollzieht.", description = "Es haben sich vor Kurzem im See Bereiche mit der trüben Substanz gebildet, die auch aus Mei herausgekommen ist.\n\nIch werde mit Euch dorthin reisen. Weist mir dann die Bereiche der Verderbnis, die ich reinigen soll.\n\nIhr müsst Euch um alles kümmern, was auch immer herauskommt, und mich schützen, solange ich das Ritual vollziehe.", progress = "Ist der See gereinigt?", completion = "Der Weiher... Ich kann fühlen, wie die Verderbnis schwindet. Zumindest diese Verderbnis wird sich jetzt nicht mehr verbreiten.\n\nAber es gibt noch etwas, das wir tun müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30829] = {title = "Die Zunge von Ba-Shon", objective = "Unterstützt Lehrensucher Cho bei der Durchführung der Bindung von Ba-Shon.", description = "Danke, dass Ihr gekommen seid, $p. Es tut mir leid, dass ich so geheimnisvoll sein musste, aber ich konnte nicht riskieren, dass die Mogu auf meine Arbeit hier aufmerksam werden.\n\nSie suchen etwas im Tal. Sie plündern Relikte der Macht aus den Grabmalen ihrer alten Könige.\n\nIch konnte sie nicht lange beobachten, bevor ich fliehen musste, aber ich habe es noch geschafft, selbst ein Relikt zu bergen.\n\nMit der Zunge von Ba-Shon können wir sicher über große Entfernungen kommunizieren, aber erst, nachdem ich sie an mich gebunden habe.\n\nIch glaube, ich bin bereit, wenn Ihr es seid.", progress = "Ich werde meine Essenz an die Zunge binden müssen, dann könnt Ihr sie verwenden könnt, um von überall aus mit mir zu sprechen.", completion = "Das muss ein sehr mächtiges Relikt sein, wenn Zuan es unbedingt zurückhaben will.\n\nIch schaudere bei dem Gedanken daran, was sie in den Gräbern noch finden könnten...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30834] = {title = "Zusammenführung von Vater und Kind", objective = "Kehrt zu Händler Shi und Wu-Peng an die südöstliche Küste von Tintenkiemenweiher am Kun-Lai-Gipfel zurück.", description = "Sie haben überlebt? Mein Vater ist am Leben!\n\nIch dachte, wir würden alle hier in diesem schrecklichen Weiher durch die Hände dieser wahnsinnigen Jinyu sterben.\n\nIch werde selbst zurückfinden - trefft Euch mit mir beim Lager.", progress = "Mein Junge! Er ist am Leben!", completion = "Ihr habt ihn gefunden! Das ist alles, was ich Euch geben kann, aber indem Ihr meinen Sohn gefunden habt, habt Ihr es Euch mehr als verdient.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30855] = {title = "Der Fall von Shai Hu", objective = "Besiegt Shai Hu. Ihr findet ihn im Heiligtum des Wassersprechers, der Insel in der Mitte des Tintenkiemenweihers auf dem Kun-Lai-Gipfel.", description = "Ich kann die Stimme des Weihers hören – er wurde gereinigt.\n\nAber dieses Kapitel in der Geschichte meines Volkes wird nie abgeschlossen sein – nicht, bis wir Shai Hu besiegt haben.\n\nEr hat sich auf die Insel in der Mitte des Weihers zurückgezogen und verderbt unsere heiligste aller Stätten.\n\nVorsicht – er ist stark. Aber nach allem, was wir getan haben, vertraue ich darauf, dass wir stärker sind.", progress = nil, completion = "Danke, &lt;Name&gt;. Ihr habt sichergestellt, dass seine Verderbnis sich nicht weiter verbreitet und dass meine Leute - diejenigen, die nicht verdorben worden sind - weiterleben und ein neues Dorf gründen können. \n\nUnsere Geschichte wird weiterleben. Ihr habt mehr für uns getan, als wir uns je erhoffen hätten können.\n\nVielen Dank, mein Freund.", rewards = "WasserfallmanschettenMushanlederbindungenArmbänder des träumenden GeistesArmschienen des GleichmutsManschetten des GeistbeugersArmwickel der lautlosen BlätterHandgelenksschützer des YakhirtenArmplatten des GipfelwächtersArmschienen der MauerwacheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30879] = {title = "Runde 1: Braumeisterin Chani", objective = "Besiegt Braumeisterin Chani.", description = "Willkommen zu meinem Turnier der Champions, <Herausforderer/Herausforderin>! Heute stellen wir die Stärke der wagemutigsten Helden Pandarias auf die Probe.\n\nEure erste Gegnerin wartet beim östlichen Pavillon. Wenn Ihr sie besiegt, dürft Ihr mit der nächsten Runde fortfahren.\n\nKämpft im Namen der Stärke und Ehre.", progress = "Ohne Widerstände gibt es keine Entwicklung.\n\nDie Notwendigkeit, sich zu verändern, beharrlich zu sein und zu improvisieren - das sind die Gründe, warum die Champions mich aufsuchen.", completion = "Gut gemacht, Herausforderer.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30880] = {title = "Runde 1: Die Straßenkämpferin", objective = "Besiegt die Straßenkämpferin.", description = "Willkommen zu meinem Turnier der Champions, <Herausforderer/Herausforderin>! Heute stellen wir die Stärke der wagemutigsten Helden Pandarias auf die Probe.\n\nEure erste Gegnerin wartet beim östlichen Pavillon. Wenn Ihr sie besiegt, dürft Ihr mit der nächsten Runde fortfahren.\n\nKämpft im Namen der Stärke und Ehre.", progress = "Ohne Widerstände gibt es keine Entwicklung.\n\nDie Notwendigkeit, sich zu verändern, beharrlich zu sein und zu improvisieren - das sind die Gründe, warum die Champions mich aufsuchen.", completion = "Gut gemacht, Herausforderer.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30881] = {title = "Runde 2: Der schlaue Ashyo & Ken-Ken", objective = "Besiegt den schlauen Ashyo und Ken-Ken.", description = "Vielleicht kennt Ihr Eure nächsten Herausforderer schon. Als sie hier ankamen, haben sie sich fürchterlich gestritten. Also habe ich sie dazu verdonnert, Seite an Seite zu kämpfen.\n\nDas wird sie etwas über den Wert der Freundschaft lehren - und mich vielleicht ganz gut amüsieren.\n\nBegebt Euch in die nordöstliche Arena und stellt Euch dem Jinyu und dem Ho-zen.\n\nUnd zeigt keine Gnade. Die beiden sollen lernen, zusammen zu arbeiten.", progress = "Stärke findet man in einem Verbündeten oder sich selbst.", completion = "Zu schade, dass die beiden ihre Lektion noch nicht gelernt haben. Aber egal. Eines Tages werden auch sie Weisheit erfahren.\n\nAber jetzt möchte ich Euch zunächst einmal zu Eurem Sieg gratulieren.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30882] = {title = "Runde 2: Kang Dornstab", objective = "Besiegt Kang Dornstab.", description = "Euer nächster Herausforderer ist ein Dornstab. Die Stärke liegt ihnen im Blut. Ich erinnere mich an ein Jahrhundert, in dem es ausschließlich Dornstab-Champions gab.\n\nAber nur keine Sorge, <kleiner/kleine:r> <Volk>.\n\nBegebt Euch einfach in die östliche Arena nördlich von hier und stellt Euch dem Herausforderer. Wir werden ja sehen, ob die Stärke angeboren ist oder erworben werden muss.", progress = "Ich wurde ein Mal im Kampf von einem Dornstab besiegt. Aber zu meiner Verteidigung muss ich sagen, dass er mich mit einem Wollknäuel ablenkte.", completion = "Ah. Die Dornstab-Familie hält den Championtitel schon seit Generationen in ihrem Besitz. Und ich bin mir sicher, dass auch dieser Kandidat sich früher oder später den Titel sichern wird.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30883] = {title = "Runde 3: Der Ringer", objective = "Besiegt den Ringer.", description = "Euer nächster Herausforderer ist einer meiner Lieblingskämpfer. Er bezieht seine Stärke aus purer Gewalt und wilder Entschlossenheit.\n\nUnd er trägt eine Maske.\n\nWenn Ihr bereit seid, wartet er in der Westlichen Arena auf Euch. Viel Glück.", progress = "Manchmal verleihen auch äußere Dinge Stärke.", completion = "Gut gekämpft, Herausforderer. Das war wirklich ein harter Gegner.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30884] = {title = "Hinter der Schlachtenfront", objective = "Sucht Taoshi bei der Feuchterdengrube auf.", description = "Diese Schlachtenfront war schon während meiner Abwesenheit am Kun-Lai viel zu lange unterbesetzt und unzureichend versorgt. Wir müssen die Dinge hier ins Lot bringen, bevor wir die Spur des Sha des Hasses verfolgen können.\n\nTaoshi ist meine beste Kämpferin. Ich habe sie in den Norden entsandt, um Gerüchten auf den Grund zu gehen, denen zufolge es einige Mantis geschafft haben, die Schlachtenfront zu durchbrechen. Jemand muss ihr da draußen helfen, etwaige Löcher in unserer Verteidigung zu stopfen.\n\nWenn an den Berichten über Euch etwas dran ist, kann ich Euch die Sache wohl anvertrauen, was, <Klasse>?", progress = nil, completion = "Ihr seht fähig aus. Taran weiß, dass er mir nur die Besten schicken soll. Das gefällt mir.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30885] = {title = "Runde 3: Meister Don-Don", objective = "Besiegt Meister Don-Don.", description = "Euer nächster Herausforderer hat seine Stärke am Strand gefunden. Genauer gesagt in einer Kiste mit der Aufschrift \"Dynamit\".\n\nDamit beweist er, dass gefundene Stärke genauso tödlich sein kann wie persönliche Stärke.\n\nWenn Ihr bereit seid, wartet Meister Don-Don in der Westlichen Arena auf Euch.", progress = "Manchmal verleihen auch äußere Dinge Stärke.", completion = "Gut gekämpft, Herausforderer. Das war wirklich ein harter Gegner.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30886] = {title = "Example Pandaren Race Quest", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30887] = {title = "Unwillkommene Eindringlinge", objective = "Tötet 12 Tiefenspäher der Krik'thik mit Taoshis Hilfe.", description = "Das dort unten sind Späher der Mantis. Die Gao-Ran-Front soll sie von der östlichen Tonlongsteppe fernhalten. Wenn wir sie in den Norden der Barrikade durchlassen, müssen wir womöglich unsere Präsenz hier aufgeben.\n\nBeseitigen wir sie. Ich komme mit Euch.", progress = nil, completion = "Hier kommen sie durch, am östlichen Pass.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30888] = {title = "Durchbruch der Verteidigung", objective = "Setzt das Leuchtfeuer der Shado-Pan als Hilfsmittel beim Töten von 10 Fährtenlegern der Krik'thik.", description = "Normalerweise reicht es, wenn ein paar Späher diesen Pass im Auge behalten. Der Großteil dieses Gebiets ist in Sichtweite des Walls; Bogenschützen würden also sämtliche Mantistruppen vernichten, die hier den Durchbruch wagen würden. Nur haben die meisten Bogenschützen bereits alle Hände voll mit den Angreifern am Tor zu tun.\n\nNehmt dieses Leuchtfeuer - damit werdet Ihr die Mantis, die sich am östlichen Pass an unseren unterbesetzten Wachposten vorbeischleichen, leichter aufspüren. Tötet alle, die Ihr findet. Wir können nicht zulassen, dass sie eine Fährte legen, die die Mantisschwärme weiter in die Steppen lotst.", progress = nil, completion = "Es kommen mehr durch, als ich dachte. Es kann sein, dass ich noch eine Weile hierbleiben muss, um aufzuräumen.\n\nDoch Ihr habt mehr als Euren Teil beigetragen, &lt;Klasse&gt;. Danke.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30889] = {title = "Fallen stellen", objective = "Ladet 8 Shado-Pan-Stachelfallen neu.", description = "Freut mich, Euch zu sehen, <Klasse>. Wir haben überall entlang des Passes Fallen aufgestellt, um Mantis zu fangen, die durchzuschlüpfen versuchen. Es sind aber so viele, dass die meisten Fallen bereits ausgelöst wurden.\n\nTaoshi meinte, Ihr könntet vielleicht einige davon neu stellen, während Ihr dort draußen seid. Könnt Ihr helfen?", progress = nil, completion = "Wir könnten im Lager gut noch ein paar fähige Männer wie Euch brauchen. Vielen Dank für Eure Hilfe, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30890] = {title = "Die ruhelose Wache", objective = "Überbringt Späher Wei-Chin, Späherin Long, Späherin Ying und Späher Jai-gan den Rückkehrbefehl.", description = "Ich habe gehört, dass unsere Späher am Flachsteigpass seit mehr als 2 Tagen durchgehend im Einsatz sind. Kein Wunder, dass Mantis durchschlüpfen können. Selbst den engagiertesten Spähern unterlaufen bei solchen Schichten Fehler.\n\nIch will, dass Ihr Euch da hinausbegebt und den Spähern den Befehl überbringt, unverzüglich zur Schlachtenfront zurückzukehren, um sich auszuruhen und Verpflegung zu fassen. Ich werde eine neue Schicht einsetzen lassen.", progress = "Die gesamte Schlachtenfront ist völlig überarbeitet. Wir brauchen hier draußen mehr Männer.", completion = "Vielen Dank. Die neuen Späher werden in Kürze ihre Posten einnehmen.", rewards = "Ring des SchleichsteigsRing des wachsamen AugesBand des getreuen SpähersTaoshis SiegelringSiegel der ruhelosen WachtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30891] = {title = "Heilung für die Truppen", objective = "Sammelt 10 Zitronenveilchen.", description = "Ein neues Gesicht! Freut mich, Euch kennenzulernen. Ich heiße Septi. Ich sorge dafür, dass die Shado-Pan weiterkämpfen können.\n\nDie Mantis verfügen über ein Gift, das sich durch die Haut frisst und das Blut infiziert. Unbehandelt führt das zu einem langsamen, qualvollen Tod.\n\nIch brauche Pollen von Zitronenveilchen. Der nächste Ort, an dem Ihr welche findet, ist in der Umgebung der Feuchterdengrube im Norden der Schlachtenfront. Falls Ihr sowieso in diese Richtung unterwegs sein solltet, könntet Ihr mir welche mitbringen?", progress = "Wenn man sie richtig zusammenmischt, tragen die Pollen dieser Blumen das Gift ab, ohne dem Körper andere bleibende Schäden zuzufügen.", completion = "Fabelhaft. Und in gutem Zustand!\n\nDanke für Eure Güte, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30892] = {title = "Wieder auf den Beinen", objective = "Heilt 8 verletzte Gao-Ran-Schwarzwachen.", description = "<Name>, ich könnte Eure Hilfe gebrauchen. Wegen ihrer langen Schichten kämpfen unsere Krieger unten an der Südfront der Schlachtenfront bis zur Erschöpfung, und viele von ihnen haben das Gift der Mantis zu spüren bekommen.\n\nWir brauchen mehr Leute, die sich um die Verwundeten kümmern. Ich habe mit den Kräutern, die Ihr mir gebracht habt, ein paar Verbände vorbereitet, wenn Ihr aber Heilfertigkeiten besitzt, könnten sich diese als noch wirksamer erweisen.\n\nBitte <Name>, geht und sorgt dafür, dass unsere Männer wieder auf die Beine kommen, damit sie hierher in Sicherheit zurückkehren können.", progress = nil, completion = "So manch ein Krieger verdankt Euch sein Leben. Seid Euch meiner tiefsten Anerkennung gewiss, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30893] = {title = "Der unendliche Schwarm", objective = "Tötet 12 angreifende Krik'thik an der Gao-Ran-Front.", description = "Die Männer von Gao-Ran unten an der südlichen Front brauchen Hilfe. Wenn Ihr den Shado-Pan zur Seite stehen wollt, dann solltet Ihr ihnen helfen.", progress = nil, completion = "Die Männer der Schlachtenfront fangen an, Euch zu respektieren. Ihr wisst offenbar, wie man kämpft.", rewards = "Handschuhe des NebelquellsHandschuhe des NebellauerersStulpen des ErdbewegersHandschuhe der GoldklaueHandschützer des SumpfläufersHandschuhe des SteppenwildsStulpen des OsulgipfelsStulpen des TempelwächtersBleichwindstulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30894] = {title = "Stöbern in Überresten", objective = "Besorgt 20 Krik'thik-Beine.", description = "Ich habe eine weitere Aufgabe für Euch, <Name>, allerdings eine trostlose. Ich muss diesem Mantisgift auf den Grund gehen, dafür brauche ich aber Informationen direkt von der Quelle.\n\nKönntet Ihr mir ein paar Mantisbeine vom südlichen Schlachtfeld zurückbringen, damit ich ihre intakten Giftdrüsen genauer untersuchen kann?", progress = "Ich hoffe, ein anhaltendes Gegenmittel für das Mantisgift zu finden, damit die Männer nicht mehr davon vergiftet werden. Die Herstellung könnte etwas dauern.", completion = "Die sind sehr gut erhalten! Danke, &lt;Name&gt;!\n\nEs ist mir gelungen, etwas von ihrem Gift in eine Form zu destillieren, die wir leicht verabreichen können. Ich habe sogar Methoden entwickelt, wie man es in das Wirken von Zaubern einweben kann. Möchtet Ihr es gern ausprobieren?", rewards = "Ihr bekommt:\n\nHerausgerissener Stachel"}
MultiLanguageQuestData['de'][30895] = {title = "Provisorische Munition", objective = "Sammelt 16 explosive Schreckenskugeln in den Bernmarschen.", description = "Ich habe noch einen Auftrag für Euch.\n\nDen Drachenkanonen, auf die wir angewiesen sind, um die dichteren Schwärme der Mantis abzuwehren, geht die Munition aus. Die Kanoniere des Lagers haben einen provisorischen Sprengstoff entwickelt, der aus den Globussamen auf der westlichen Seite des Kamms hergestellt wird.\n\nSie haben vor einigen Stunden ein paar Initianden ausgesandt, um welche holen zu gehen, aber haben seitdem nichts mehr von ihnen gehört. Jetzt hätte ich gerne, dass jemand Fähigeres dafür sorgt, dass die Sache erledigt wird.\n\nSeid Ihr <der Mann/die Frau> dafür?", progress = "Schneller als ich erwartet hätte. Bringt Ihr die Samen?", completion = "Gut, ein &lt;Klasse&gt;, auf den man sich verlassen kann!", rewards = "BleichwindpantalonsPantalons des TempelwächtersBeinschützer des OsulgipfelsPantalons des SteppenwildsPantalons des SumpfläufersPantalons der GoldklaueKilt des ErdbewegersPantalons des NebellauerersPantalons des NebelquellsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30896] = {title = "Diebe und Unruhestifter", objective = "Tötet 10 aufgeregte Nesselhäute.", description = "Ich kann die kleinen Biester beim besten Willen nicht erwischen.\n\nTötet alle, die Ihr in die Hände bekommt. Und passt auf Eure Wertgegenstände auf, sie klauen nämlich alles, was nicht niet- und nagelfest ist.", progress = "Ich habe Pflanzen seit meinem Auftrag in Halbhügel nicht mehr so sehr gehasst.", completion = "Ihr seid wohl etwas schneller als ich. Danke jedenfalls.\n\nIch werde ein paar Kugeln zu sammeln versuchen und sie ins Lager zurückbringen, solange ich noch die Chance habe, mein Gesicht zu wahren.", rewards = "Ihr bekommt:\n\nFlüchtige Kugel"}
MultiLanguageQuestData['de'][30897] = {title = "In falschen Händen", objective = "Bergt Initiand Xaos Schwert.", description = "Hört zu... ähm... es ist mir wirklich peinlich. Aber ich habe mein Schwert für gerade mal EINE SEKUNDE abgesetzt, um ein paar Kugeln zu sammeln, und schon tauchte so ein fetter Waldgeist aus dem Nichts auf und schnappte es sich, um damit in der Schlucht im Westen zu verschwinden.\n\nOhne kann ich nicht zurück zum Lager. Seine Waffe zu verlieren ist Garantie dafür, von den Shado-Pan hinausgeworfen zu werden. Sie ist ihnen heilig.\n\nBitte, könnt Ihr diesen dicken Waldgeist aufspüren und mein Schwert zurückholen? Es würde mir so viel bedeuten.", progress = "Meine Mama hat mich schon davor gewarnt...", completion = "Ihr... Ihr seid die Rettung! Im Ernst.\n\nVielen, vielen Dank!", rewards = "Ihr bekommt:\n\nXaos Kekse"}
MultiLanguageQuestData['de'][30898] = {title = "Ausdünnen des Schwarms", objective = "Benutzt eine Drachenschleuder, um 50 schwärmende Mantis zu töten.", description = "Die Mantis haben zugenommen, als Ihr zur Kluft aufgebrochen seid. Setzen wir also diese Kugeln, die Ihr gesammelt habt, zu unserem Vorteil ein.\n\nGeht runter zur Schlachtenfront und bemannt eine der Kanonen. Lasst niemanden durch.", progress = "Ich kann mich nicht erinnern, schon einmal so dichte Schwärme gesehen zu haben. Zu meinen Lebzeiten scheint es das nicht gegeben zu haben.", completion = "Wir sind noch nicht fertig...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30899] = {title = "In besten Händen", objective = "Bringt das Armbrustbolzenbündel der Shado-Pan zu Falkenmeister Nurong.", description = "<Name>, nehmt diese Armbrustbolzen und bringt sie zu Falkenmeister Nurong an der Weitblickwarte im Südwesten.\n\nNurong wird unter den Wukao als unfehlbarer Schütze gefeiert. Seinen Bemühungen soll es zu verdanken sein, dass die Linien hier all die Monate standgehalten haben. Ich hoffe, dass Ihr mit ihm zusammenarbeiten könnt, um das selbst zu beurteilen. Vielleicht ist er der erste Shado-Pan, den wir für die Jagd gebrauchen können.", progress = "Eine weitere Welle fliegender Angreifer bricht herein. Macht Euch bereit.", completion = "Auf der anderen Seite der Schlucht scheint sich einiges zu tun... Da braut sich etwas ganz Großes zusammen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30900] = {title = "Geißel der Schreckensöde", objective = "Bezwingt Norvakess, die Geißel der Schreckensöde.", description = "Das Ding ist ja riesig!\n\nFür so etwas sind die Shado-Pan, die die Schlachtenfront halten, nicht ausgebildet... Gehen wir hinunter und setzen es selbst außer Gefecht.", progress = nil, completion = "Ihr da. Ihr kommt mit mir.\n\nIch habe noch nie jemanden getroffen, der sich auf dem Schlachtfeld so wie Ihr verhalten hat. Ich brauche jemand Starkes wie Euch an meiner Seite, &lt;Klasse&gt;, wenn wir uns dem Sha des Hasses entgegenstellen.", rewards = "Gao-Ran-RingBand des SchreckensSiegel von Taran ZhuRing von NorvakessBand der SchlachtenfrontIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30901] = {title = "Entlang der Südfront", objective = "Reitet mit Taran Zhu und Taoshi zum Dämmerlichtstumpf.", description = "Ich werde mit Taoshi gen Westen ziehen, um die Stärksten, die ich finden kann, um mich zu scharen und den Kampf zum Sha des Hasses zu tragen.\n\nIch möchte, dass Ihr mich begleitet.", progress = nil, completion = "Sehen wir zu, dass die Sache geregelt wird, damit wir zur Brücke hinunterkommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30902] = {title = "Runde 4: Meister Windpelz", objective = "Besiegt Meister Windpelz.", description = "Gut gemacht, <Herausforderer/Herausforderin>. Ihr habt die letzte Runde erreicht.\n\nEuer letzter Gegner ist ein mächtiger Herrscher über die Winde. Er hat sein Volk über viele Jahre beschützt und sich mehr als ein Mal als wahrer Champion bewiesen.\n\nWenn Ihr bereit seid, wartet Meister Windpelz in der Hauptarena auf Euch.\n\nIch wünsche Euch viel Glück, <Herausforderer/Herausforderin>...", progress = "Die Stärke von Meister Windpelz liegt in der Luft und den Winden, die ihn umwehen. Er herrscht über die mächtigen Kräfte der Elemente.", completion = "Ich gratuliere Euch, Champion! Heute ist Euer Ehrentag.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30907] = {title = "Runde 4: Drei gegen einen", objective = "Besiegt Hackiss, Heiliss und Tankiss.", description = "Und jetzt zur letzten Runde. Ich habe dazu gleich drei Herausforderer für Euch ausgewählt. Das könnte unfair erscheinen... aber nur für einen Schwächling. Und Ihr seid doch kein Schwächling, oder?\n\nBegebt Euch in die große Arena im Haupttempel und stellt Euch diesen drei Herausforderern. Zeigt, dass Ihr über mehr Kraft verfügt als die drei zusammen!\n\nViel Glück, <Herausforderer/Herausforderin>!", progress = "Einige beziehen Stärke aus der Anzahl. Bei richtiger Anwendung kann ich dies respektieren.", completion = "Fabelhaft! Was für eine Schlacht!\n\nIhr habt Euch als Turnier-Champion des heutigen Tages erwiesen. Gut gemacht!\n\nBitte kommt auch in Zukunft wieder, um Eure außergewöhnliche Stärke zu demonstrieren.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30910] = {title = "Grünstein", objective = "Rettet alle Dorfbewohner.", description = "Bitte helft uns!\n\nWir haben einige Abenteurer bezahlt, um die ganzen Elementargeister zu verjagen, und nun sind sie wieder da und wollen sich rächen!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30918] = {title = "Huis Rache", objective = "Besiegt den Rachsüchtigen Hui.", description = "Es ist mir etwas peinlich, aber um Grünsteins willen... dürften wir Euch wohl bitten, Euch in unserem Namen jetzt dem Rachsüchtigen Hui entgegenzustellen...?", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30921] = {title = "Die Motive der Mantis", objective = "Erschlagt Mantis in Kri'vess, damit Tai Ho ihre Leichname auf Hinweise untersuchen kann.", description = "<Klasse>. Ihr könntet uns nützlich sein.\n\nDie Shado-Pan möchten wissen, weshalb die Mantis so ungestüm angreifen. Wir haben unsere Vermutungen, sind uns allerdings nicht sicher. Außerdem sollen die Mantis nicht herausfinden, dass sie von uns untersucht werden.\n\nUnd hier kommt Ihr ins Spiel.\n\nIch möchte, dass Ihr die Mantis von Kri'vess im Norden tötet. Ich werde mich hinter Euch im Schatten versteckt halten und ihre Leichname auf Hinweise untersuchen.", progress = nil, completion = "Die vielen Yakhaare am Körper dieses Mantis deuten auf eins hin... er ist vom Niuzaotempel gekommen. Wir setzen unsere Reise Richtung Westen fort, &lt;Klasse&gt;.", rewards = "Manschetten des NebelquellsBindungen des NebellauerersBand des ErdbewegersArmschienen der GoldklaueManschetten des SumpfläufersArmwickel des SteppenwildsGelenkbänder des OsulgipfelsArmplatten des TempelwächtersBleichwindarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30922] = {title = "Natürliches Antiseptikum", objective = "Sammelt 5 volle Mushanblasen.", description = "Die Shado-Pan sind selten, elitär und ziemlich teuer in der Ausbildung und daher nur schwer zu ersetzen. Wir können uns nicht leisten, dass auch nur einer von ihnen einer vergifteten Waffe oder einem infizierten Schnitt zum Opfer fällt. Deshalb möchte ich, dass Ihr mir... etwas besorgt.\n\nLasst es mich klar und deutlich aussprechen. Der Urin der Mushan ist ein großartiges, natürliches Antiseptikum. Zum Glück erzeugen sie eine Menge davon... wir brauchen nämlich in der Regel viel.", progress = "Stimmt schon, das ist eine schmutzige Arbeit.\n\nAber bei Weitem nicht so schmutzig wie Gräber ausheben.", completion = "Eure schmutzige Arbeit hat heute möglicherweise das eine oder andere Leben gerettet, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30923] = {title = "Ein Rückschlag für die Mantis", objective = "Benutzt Schwarzpulverfässer, um die Krik'thik-Waffen und -Vorräte in Kri'vess in die Luft zu sprengen.", description = "Mit jedem Tag vergrößern die Mantis die Munitionsvorräte, die sie gegen ihre Feinde einsetzen wollen, weiter. Wir können sie nicht aufhalten, Ihr und ich... aber einen Rückschlag können wir ihnen doch verpassen.\n\n<Tai Ho gibt Euch etwas Sprengstoff.>\n\nIch muss mich bedeckt halten. Wärt Ihr so gut?", progress = nil, completion = "Wir stehen in Eurer Schuld, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30924] = {title = "Niuzaos Weisheit", objective = "Sprecht mit Ogo dem Jüngeren am Niuzaotempel in der Tonlongsteppe.", description = "Niuzao der Schwarze Ochse ruht sich im Tempel im Westen aus. Er weiß vielleicht, warum die Mantis angreifen.\n\nEr weiß vielleicht sogar viel mehr als das.\n\nIch werde am Niuzaotempel zu Euch stoßen, <Klasse>.", progress = nil, completion = "Euer Shado-Pan-Genosse hat sich mit mir unterhalten. Ja, Niuzao weiß, weshalb die Mantis angreifen. Er ist aber nicht bereit, es Euch zu erzählen.\n\nNoch nicht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30925] = {title = "Niuzaos Preis", objective = "Tötet die Mantis des Übergriffs der Sra'thik, damit Tai Ho ihre Leichen nach Teilen von Niuzaos Statuette durchsuchen kann.", description = "Niuzao ist der Besitzer einer Statuette, die er über alles schätzt: eine kleine Ikone nach seinem Ebenbild, gemeißelt von einem seiner vor langer Zeit gefallenen Wächter. Diese Statuette wurde vor Kurzem von den Sra'thik-Mantis gestohlen und in ihr Lager nördlich von hier gebracht.\n\nBringt die Statuette zurück. Dann geben wir Euch - und Eurem Shado-Pan-Genossen - die Antworten, die Ihr begehrt.", progress = nil, completion = "Niuzao wird sich freuen.\n\nTrotz seiner Körpergröße ist unser Schutzpatron ein anmutiges und mitfühlendes Geschöpf. Diese Figur war ihm viel wert... so, wie ihm jeder einzelne seiner Anhänger viel wert ist.", rewards = "Siegel des MitgefühlsSiegel der TreueSiegel der AnmutSiegel der GeduldSiegel der HingabeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30926] = {title = "Die schreckliche Wahrheit", objective = "Untersucht die Niuzaokatakomben und erlegt den Schreckensschatten, der in ihrem Inneren haust.", description = "Schweren Herzens bestätige ich Eure Vermutungen. Die Mantis stehen tatsächlich unter der Herrschaft des Sha der Angst.\n\nEs war UNSERE Pflicht, diese Kreatur unter unserem Tempel festzuhalten. Unglücklicherweise ließ unsere Wachsamkeit nach, unsere Verteidigung brach zusammen und das Sha konnte entkommen. Es ist jetzt bei den Mantis.\n\nÜberzeugt Euch selbst. Die Mantis haben sich zur westlichen Seite unserer Insel durchgewühlt.", progress = nil, completion = "Lasst mich eins klarstellen: Diese Kreatur war nicht das Sha der Angst, sondern nichts weiter als ein Schatten... ein Bruchteil der wahren Macht des Sha.\n\nNein, das Sha der Angst ist jetzt bei den Mantis. Die Ältesten meines Ordens müssen unverzüglich davon in Kenntnis gesetzt werden.\n\nDen Rest werde ich übernehmen. Vielen Dank für Eure Hilfe, &lt;Volk&gt;. Einmal mehr erweist sich Euresgleichen als Gewinn für Pandaria.", rewards = "Mal der KatakombenSiegel der KatakombenEmblem der KatakombenMedaillon der KatakombenSymbol der KatakombenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30927] = {title = "Auf dass sie in Frieden ruhen mögen", objective = "Gewährt 10 Angsterfüllten Schildwachen Frieden, indem Ihr ihre Augen schließt und sie auf den Bauch dreht.", description = "Ich habe es schon gehört. Unser Geheimnis ist also gelüftet.\n\nAls ich erfuhr, dass die Mantis sich unter unserem Tempel vergraben hatten, reagierte ich vorschnell. Ich entsandte Dutzende von Wächtern, damit sie verteidigen, was sie können, aber sie waren unvorbereitet. Sie wurden von Angst übermannt und kehrten nie wieder.\n\nEin Pandaren verdient es, die Erde umarmend zu sterben, so wie er es im Schlaf tut... nicht auf dem Rücken, den Blick starr vor Angst. Bitte, <Name>. Gewährt ihnen den Frieden, den sie verdienen.", progress = nil, completion = "Danke, &lt;Klasse&gt;.\n\n\n\nWäre ich nur dabei gewesen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30928] = {title = "Spur der Angst", objective = "Tötet 12 Schrecklinge in den Niuzaokatakomben.", description = "Jetzt kennt Ihr das Geheimnis von Niuzao. Wir sind nicht nur die Wächter dieses Tempels... wir waren die Wächter des Sha der Angst, das darunter begraben lag.\n\nDas Sha selbst mag entkommen sein... doch es hat Spuren hinterlassen. Wenn Ihr Euch wirklich in die Katakomben hinunterwagen wollt, solltet Ihr diese Spuren beseitigen, bevor auch sie entkommen und noch größere Probleme verursachen, als wir sie ohnehin schon haben.", progress = nil, completion = "Wir haben schon die Mantis, die Mogu und die Yaungol, die uns das Leben schwer machen. Dieses Problem mit dem Sha muss im Keim erstickt werden, bevor wir überrumpelt werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30929] = {title = "Unbrauchbares Yak", objective = "Helft Blausattel, Ersatz für sein unbrauchbares Yak zu bekommen.", description = "Kann man hier unbrauchbare Yaks eintauschen?\n\nKann mir hier wohl jemand weiterhelfen?", progress = "Dieses Yak ist kein gutes Yak. Ganz und gar nicht", completion = "Ich glaube, unsere Argumente sind überzeugend genug. Jetzt MÜSSEN sie mein Yak ersetzen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nRuthers beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30930] = {title = "Die Qual der Yakwahl", objective = "Fangt mit dem Yaklasso wilde Tonlongyaks ein und kämpft dann gegen sie, um herauszufinden, ob sie für Blausattel geeignet sind.", description = "Ich finde einfach kein einziges gutes Yak hier. ALLE Yaks sind unbrauchbar!\n\nDie einen stinken zu sehr, andere sind zu kampflustig oder einfach zu verängstigt.\n\nIhr seht mir wie ein Glückspilz aus, <Volk>. Hier, nehmt ein Lasso. Seht zu, ob Ihr ein gutes Yak für mich finden könnt.", progress = "Na, seht Ihr? Habe ich es nicht gesagt? Keine brauchbaren Yaks.", completion = "Nun sieh mal einer an! Ein gutes Yak!\n\nIch sag Euch was, &lt;Name&gt;. Ich nehme dieses GUTE Yak und Ihr macht mit dem völlig unbrauchbaren hier, was Ihr wollt.", rewards = "Ihr bekommt:\n\nRuthers' Geschirr"}
MultiLanguageQuestData['de'][30931] = {title = "Die Armbrust meines Vaters", objective = "Besorgt Ku-Yaos Armbrust.", description = "Ich kam hierher, um meinen Vater im Tempel zu besuchen. Gleich nach meiner Ankunft erblickte ich das grässlichste Wesen, das ich je zu Gesicht bekommen habe.\n\nEs war ein Mantis, der mit der Armbrust meines Vaters direkt an mir vorbeilief.\n\nMeinem Vater ist etwas zugestoßen! Wir müssen herausfinden, was... doch vorher brauchen wir seine Armbrust. Ich habe gesehen, wie er nach Westen gegangen ist, hinter den Tempel.", progress = "Habt... Ihr sie gefunden?", completion = "Ja, das ist Vaters Armbrust.\n\nGehen wir zum Tempel hinüber. Dort werden sie wissen, was...\n\n&lt;Ku-Mos Stimme versagt.&gt;\n\n...was ihm zugestoßen ist.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKu-Mo beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30932] = {title = "In den Fußstapfen des Vaters", objective = "Findet das Futon des Vaters, den Schild des Vaters, Ha-Cha und Späher Yalo.", description = "Ja, der Vater des Jungen - Späher Ku-Yao - ist verschwunden. Er könnte an vielen verschiedenen Orten sein... Dieser Tage mangelt es uns nicht an Feinden.\n\nEs steht Euch frei, Euch nach Belieben umzusehen. Ihr könntet damit beginnen, nach seinem Yak zu suchen oder indem Ihr Späher Yalo fragt, was er weiß.", progress = nil, completion = "Kein Schild, keine Armbrust, kein Yak… Vater ist etwas Schlimmes zugestoßen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKu-Mo beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30933] = {title = "Auf der Suche nach meinem Vater", objective = "Sucht nach Späher Ku-Yao.", description = "Ich habe überall gesucht... aber ich kann meinen Vater nicht finden. Ich WEISS, dass er noch am Leben ist. Er braucht bloß seine Armbrust... dann ist alles in Ordnung.\n\nIch habe gehört, dass Ihr von den Shado-Pan manchmal auf Sra'vess gegen die Mantis kämpft. Ich habe keine Möglichkeit, da hinzukommen. Wenn Ihr da hingeht, könntet Ihr nach meinem Vater sehen?", progress = nil, completion = "&lt;Ku-Mo scheint Euch nicht wahrzunehmen.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKu-Yau beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30935] = {title = "Die Geschichte des Fischers", objective = "Sprecht mit Mishi, um zum Pfad der Eroberer zu reisen. Von dort aus sucht Shin Flüsterwolke bei der Flüsterwolkenhöhe auf.", description = "Die Dorfbewohner von Zouchin kennen die Küste besser als sonst jemand am Kun-Lai-Gipfel. Wenn sich die Zandalari auf einer der Inseln verstecken, werden sie es wissen.\n\nMishi bringt Euch bis zum Pfad der Eroberer. Ich gehe voraus, um mit den Dorfältesten zu sprechen.\n\nFolgt dem Pfad bis zur Flüsterwolkenhöhe. Shin Flüsterwolke wird Euch helfen, das Dorf zu erreichen.", progress = nil, completion = "Wir müssen herausfinden, wo die Zandalari die Überreste des Donnerkönigs versteckt haben. Die Ältesten haben beschlossen, uns dabei zu helfen.\n\nSie stellen allerdings einige Bedingungen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30942] = {title = "Ich will kämpfen!", objective = "Tötet 4 Scharmützler der Amani, 4 Verhexer der Gurubashi und 3 Frostweber der Drakkari in der Provinz Zouchin.", description = "Pscht! Sprecht nicht so laut! Mein Vater könnte Euch hören.\n\n<Shomi zeigt auf Stahlbieger Doshu.>\n\nMein Vater ist nicht bei Trost! Er ist der Meinung, ich solle üben, wie man Tee ausschenkt, dabei wird unser Dorf angegriffen. Es ist lächerlich! Ich habe ebenso viel Mut wie jeder Mann. Ich weiß nur nicht, wie man kämpft...noch nicht.\n\nDa kommt Ihr ins Spiel. Lasst mich mit Euch ziehen! Ich lerne schnell und werde nicht im Weg sein, versprochen!\n\nBitteeeee!\n\nWenn wir getrennt werden, treffe ich Euch im Dorf wieder.", progress = "Ich werde meinem Vater beweisen, dass er mich unterschätzt hat!", completion = "Ich sagte Euch ja, dass ich schnell lerne! Ich werde zurück in mein Dorf eilen und andere ausbilden. Danke, &lt;Name&gt;.", rewards = "Shomis GroßschwertShomis KolbenShomis SchildShomis SchutzShomis DolchShomis AxtShomis KranichShomis FächerAuf Euch wartet eine dieser Belohnungen:\n\nGeldbeutel des Helden\n\nDer folgende Zauber wird auf euch gewirkt:\n\nComplete \"Make A Fighter Out of Me\" Clean Up\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][30943] = {title = "Ganz. Vorsichtig.", objective = "Bringt dem Ältesten Shu 50 Zunderblüten.", description = "Ich habe die Zahlen dieser Eindringlinge gesehen. Das wird kein einfacher Sieg. Eine Sache fällt mir jedoch ein, mit der wir uns einen Vorteil verschaffen können.\n\nUm das Dorf herum wächst eine Pflanze, mit der man eine ziemlich explosive Flüssigkeit herstellen kann. Wenn Ihr genügend sammeln könnt, kann ich damit beginnen, die Mixtur herzustellen.\n\nDie Pflanze, nach der Ihr sucht, heißt passenderweise Zunderblüte. Geht vorsichtig damit um.", progress = "Habt Ihr eine angemessene Anzahl Zunderblüten gefunden?", completion = "Die sind perfekt! Jetzt würde ich mir an Eurer Stelle ein paar Mal die Hände waschen, &lt;Klasse&gt;.\n\nIch würde auch offene Flammen für einige Tage meiden...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHelping Shu Quest Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30944] = {title = "Man braucht ein Dorf", objective = "Löst die erschöpften Verteidiger von ihren Wachtposten ab.", description = "Unsere Dorfbewohner bewachen Zouchin seit dem ersten Angriff. Sie sind erschöpft und viele von ihnen sind verletzt.\n\nWenn die Zandalari erneut angreifen, können wir es uns nicht erlauben, dass unsere Verteidiger während ihrer Wache einschlafen. Löst sie ab, sodass sie sich erholen und ihre Familien sehen können.\n\nSie sind rund ums Dorf stationiert.", progress = nil, completion = "Sehr gut, &lt;Klasse&gt;! Jetzt, da die Dorfbewohner erholt sind, haben wir vielleicht eine Chance gegen die Zandalari.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30945] = {title = "Was Euer ist, ist mein", objective = "Holt 6 gestohlene Waffen von den Eindringlingen der Zandalari zurück.", description = "Die Ältesten möchten also, dass wir die Verteidigung übernehmen? Wir sind keine Mönche, <Klasse>; wir brauchen Waffen, damit wir im Kampf eine Chance haben!\n\nErbeutet für mich ein paar der Waffen dieser Barbaren. Ich sollte sie einschmelzen und zu etwas Passenderem für unsere Dorfbewohner verarbeiten können.\n\nBringt mir so viele Ihr tragen könnt und ich kümmere mich um den Rest.", progress = "Wir brauchen mehr als nur Glück, um das zu überstehen. Ich hoffe, dass Ihr etwas Brauchbares gefunden habt.", completion = "Die sind ja besser als erhofft! Ich kann für jede ihrer Klingen vier Speere herstellen.\n\nMacht Euch keine Sorgen. Die Dorfbewohner werden bewaffnet sein, wenn es soweit ist.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHelping Doshu Quest Credit\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30946] = {title = "Enthüllungen", objective = "Sprecht mit dem zandalarischen Gefangenen.", description = "Der Gefangene befindet sich im oberen Stockwerk, <Name>. Es wird nicht einfach sein, Informationen aus ihm herauszubekommen, aber selbst das kleinste Detail über ihren Aufenthaltsort ist hilfreich.\n\nDie Ältesten haben bereits begonnen, ihn zu befragen. Mit ihrer Hilfe sollten wir unseren nächsten Schritt planen können.\n\nSprecht mit dem Gefangenen und findet heraus, ob er nützliche Informationen für uns hat.", progress = "Was hatte der Gefangene zu sagen?", completion = "Wir dürfen das nicht als Niederlage betrachten, &lt;Name&gt;, der Prophet Khar'zul muss ausgeschaltet werden.\n\nJeder Unterstützer des Donnerkönigs, den wir aus dem Weg räumen, bringt uns dem Sieg einen Schritt näher.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30952] = {title = "Die endlose Belagerung", objective = "Besiegt 12 Angreifer der Sra'thik im Niuzaotempel.", description = "Die Mantis setzen ihre Angriffe auf uns fort. Mal sind es mehr, mal weniger, doch sie hören nie auf.\n\nDas tut nichts zur Sache. Das Yak ist der Inbegriff der Ausdauer. Wir werden uns ihnen nicht beugen. Wir werden seine Heimat auf ewig verteidigen.\n\nWerdet Ihr uns helfen?", progress = nil, completion = "Ihr kämpft, als wärt Ihr einer von uns.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30953] = {title = "Gefallene Bewacher", objective = "Heilt 8 verwundete Niuzaobewacher, bis jeder mindestens 50% Gesundheit erreicht hat. Ihr könnt dabei die Yakmilchflaschen oder Eure eigenen Heilfähigkeiten einsetzen.", description = "Unsere Bewacher können tagelang ohne Unterbrechung kämpfen, doch auch ihre Belastbarkeit hat Grenzen. Seit der Mantisschwarm aufgetaucht ist, haben sich schon zu viele von ihnen übernommen.\n\nBitte helft ihnen, so gut Ihr könnt. Wenn Ihr sie nicht selbst heilen könnt, verabreicht ihnen etwas hiervon. Ein Schluck nahrhafte Yakmilch wird ihnen die Kraft geben, die sie brauchen.", progress = nil, completion = "In Zeiten wie diesen müssen wir in die Macht und den Schutz Niuzaos vertrauen. Wenn sich die Lage verschlimmert, wird er uns beschützen.\n\nDas tut er immer.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30954] = {title = "Eine Klinge ist eine Klinge", objective = "Nehmt 10 Sra'thik-Waffen an Euch.", description = "Dies ist nicht der Zeitpunkt, um an Traditionen festzuhalten. Die schwieligen Hände unserer Steinmetze bluten und zittern. Unsere Schmiede können Waffen nicht so schnell herstellen, wie unsere Schildwachen sie verschleißen.\n\nJetzt gilt es, mit Bedacht zu kämpfen.\n\nViele der Mantis tragen Waffen, die bei ihrem Tod einfach auf dem Schlachtfeld liegen bleiben. Es wäre doch eine Schande, das nicht auszunutzen.", progress = "Unsere Männer sind es gewohnt, mit Kolben und Keulen zu kämpfen. Leider haben wir nicht die Zeit, alte Bräuche zu pflegen.", completion = "Ich werde dafür sorgen, dass sie ordnungsgemäß verteilt werden und außerdem sicherstellen, dass unsere Schmiede sich etwas erholen können. Niuzao weiß, sie verdienen es.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30955] = {title = "Tribut zollen", objective = "Besorgt 6 Lebensmittelvorräte von Niuzao. Euer Niuzaokraftprotz wird die Lebensmittel für Euch tragen.", description = "Unser Schutzpatron Niuzao ist ein Berg auf Rädern... ungemein schwer zu bewegen und noch schwerer aufzuhalten. Was ich damit sagen will: Wenn wir ihn erst in Bewegung bringen, werden die Mantis alle Mühe haben, ihn wieder zu stoppen.\n\nAm einfachsten bringt man ihn dazu, sich zu bewegen, indem man ihm Essen vorsetzt. Zum Glück haben wir massenhaft Essen in unserem Tempel... selbst zu Kriegszeiten.\n\nIch werde Euch einen von meinen Kraftprotzen mitgeben, um die Last zu tragen.", progress = "Bitte, Niuzao... es ist Zeit zum Kämpfen...", completion = "Er wird aufstehen. Bald. Vielleicht nicht mehr heute, aber bald.\n\nUnd dann...\n\n&lt;Auf Paoshas Gesicht macht sich ein Lächeln breit.&gt;", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30956] = {title = "Die Belagerung wird stärker", objective = "Bezwingt 25 Angreifer der Sra'thik im Niuzaotempel.", description = "Der Mantisschwarm von heute gehört zu den schlimmsten Dingen, die ich je gesehen habe. Ein Glück, dass wir Niuzao für die Schlacht haben.\n\nHelft ihm, <Klasse>. Kehrt in den Hof zurück und helft bei der Verteidigung unseres Tempels.", progress = nil, completion = "Seht ihn Euch an, &lt;Klasse&gt;.\n\nNiuzao ist unaufhaltbar. Nur Niuzao kann Niuzao stoppen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30957] = {title = "Der überwältigende Schwarm", objective = "Bezwingt 4 Kunchong der Sra'thik.", description = "Ich kommandiere die Schildwachen von Niuzao. Jeder Verteidiger dort draußen kann es selbst mit dem Mantisschwarm aufnehmen.\n\nMit den Kunchong ist das allerdings eine andere Sache.\n\nSie sind riesig, brutal und zweifelsfrei die größte Bedrohung für das Leben meiner Schildwachen. Niuzao selbst ist der Einzige, der eine Chance gegen sie hat. Niuzao... und Ihr vielleicht.", progress = "Seid standhaft, <Volk>. Die Kunchong würden sich gegen Euch durchsetzen.", completion = "Wenn Ihr unsere Rüstung anlegt, kann man Euch von den anderen Schildwachen dort draußen nicht mehr unterscheiden.\n\nViel Glück im Kampf, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30958] = {title = "Im Schatten der Schlacht", objective = "Werft 10 Lose Steine zu den Niuzaosteinmetzen hinauf.", description = "Niuzaos Erscheinen auf dem Schlachtfeld ist ein wahrer Segen... und nicht nur in einer Hinsicht.\n\nWegen der Ablenkung, die er geschaffen hat, konnten unsere Steinmetze sich an den Wiederaufbau unserer verfallenden Wälle machen. Sie könnten Eure Hilfe gebrauchen.\n\nWerft ihnen die lose herumliegenden Steine zu, die Ihr findet. Und beeilt Euch! Niuzao wird nicht ewig wüten.", progress = "Ich lege Euch ans Herz, Euch zu sputen. Niuzaos Ablenkungsmanöver wird nicht ewig andauern.", completion = "Diese Wälle scheinen langsam wieder Formen anzunehmen. Schon bald wird der Tempel wieder errichtet sein.", rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][30959] = {title = "Schwere Geschütze", objective = "Zerstört 3 Kriegswagen der Sra'thik.", description = "Die Mantis haben den Tempel jetzt mit ihren teuflischen Kriegswagen umringt. Je schneller wir diese Dinger loswerden, umso besser. Ihr könntet sie mit Euren eigenen Waffen und Zaubern zerstören, das hier wird aber schneller gehen.\n\n<Ogo überreicht Euch ein paar kleine Fässer mit schnell zusammengepacktem Sprengstoff.>\n\nNehmt Euch vor Gegenschlägen von Mantis in Acht, die sich bei der Explosion noch in ihren Kriegswagen aufhalten. Ich würde mich so weit wie möglich von diesen Dingern fernhalten.", progress = nil, completion = "Schön, Ihr seid heil wieder zurück.\n\nHoffentlich bekommen wir in Zukunft mehr von Euch zu sehen, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][30960] = {title = "Die Rückkehr vom Pass", objective = "Meldet Euch bei Taran Zhu bei der Gao-Ran-Blockade.", description = "Ich muss hier am Pass noch etwas aufräumen - es kommen noch immer Mantis durch. Euch zur Verfügung zu haben, ist praktisch, und ich weiß, dass es Taran nicht gefallen würde, wenn ich Euch noch länger mit solch einfacher Arbeit betraue.\n\nTaran ist vermutlich noch mit Gao-Ran im Hauptlager. Meldet Euch dort. Ich komme etwas später nach.", progress = nil, completion = "Willkommen zurück. Ich habe von den Durchbrüchen am Pass im Osten gehört. Klingt, als hätte ich die richtigen Leute beauftragt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30961] = {title = "Retter der Tintenkiemen", objective = "Sprecht mit Wassersprecher Gorai an der Südwestecke des Jinyuweihers.Ich werde nun gehen und zu meinen Angehörigen zurückkehren. Besucht uns bitte an der Südwestecke des Weihers, damit wir Euch danken können.", description = "Ich werde nun gehen und zu meinen Angehörigen zurückkehren. Besucht uns bitte an der Südwestecke des Weihers, damit wir Euch danken können.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30963] = {title = "Der Feldrüstungsschmied", objective = "Sammelt 120 Fragmente eines Rankbisspanzers.", description = "Die Shado-Pan kämpfen. Deshalb werden ihre Rüstungen oft zerschnitten, zerkratzt, zerrissen und verbrannt. Meine Aufgabe ist es, sie zu reparieren.\n\nIch bin kein Rüstungsschmied, aber solange das Loch nicht zu groß ist, kann ich ein kaputtes Kettenrüstungsstück reparieren.\n\nAm liebsten verwende ich Panzerfragmente von Schildkröten, die in den Feldern im Nordosten leben. Besorgt mir welche, damit ich mehr Shado-Pan gerüstet und am Leben erhalten kann.", progress = "Ich weigere mich, auch nur einen von uns wegen einer kaputten Rüstung fallen zu sehen.", completion = "Ausgezeichnet. Ich werde die Rüstung heute Abend reparieren, wenn die meisten zurück sind.", rewards = "Treter des NebelquellsFußschützer des NebellauerersSabatons des ErdbewegersSchienbeinschützer der GoldklaueTreter des SumpfläufersStiefel des SteppenwildsSabatons des OsulgipfelsKriegsstiefel des TempelwächtersBleichwindkriegsstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30964] = {title = "Ein verbesserter Verband", objective = "Sammelt 11 Mao-Weiden.", description = "Ein trockener Verband hat wenig Nutzen, außer dass er die Wunde frei von Ungeziefer hält. In einigen Lagern ist dies das Beste, worauf man hoffen kann.\n\nAber nicht in meinem.\n\nIch ziehe es vor, eine Paste aus all den lindernden Kräutern zu mischen, derer ich habhaft werden kann, um diese zwischen den Verbänden aufzutragen. Die wirksamsten Kräuter, die ich finden konnte, sind die Mao-Weiden auf den Feldern im Nordosten. Wenn Ihr welche antrefft, bringt sie doch her.", progress = "Alles gut gelaufen da draußen, <Name>?", completion = "Das sollte reichen.\n\nDie Shado-Pan sind dankbar für Euren Beitrag, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30967] = {title = "Befreit die Dissidenten", objective = "Rettet 6 Dissidenten der Tintenkiemen am Tintenkiemenweiher.", description = "Nicht alle meiner Mitbürger vom Tintenkiemenweiher sind verderbt. Viele von ihnen haben auf meine Warnungen gehört und nicht von dem Sha-verderbten Wasser getrunken.\n\nJedoch leben sie nun in Furcht und müssen sich verstecken, da sie von den Wachen eingeschüchtert werden.\n\nBitte, sagt ihnen, dass es noch Hoffnung gibt! Reist in das Dorf im Norden. Sprecht mit ihnen, und schickt sie zu mir.", progress = nil, completion = "Obwohl wir nicht viel herzumachen scheinen, weiß ich aus den glücklosen Anfängen, dass wir es schaffen werden. Danke, mein Freund.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30968] = {title = "Das Sha des Hasses", objective = "Besiegt das Sha des Hasses.", description = "Das Ende unserer Jagd steht unmittelbar bevor. Wir haben die stärksten Shado-Pan versammelt und mit Eurer Stärke als Unterstützung werden wir das Sha des Hasses bezwingen und seinen Einfluss auf die Welt ersticken.\n\nWenn wir in den Tunnel eindringen, bleibt in der Nähe und haltet den Hass von Eurem Herzen fern. Der bevorstehende Kampf stellt für alle von uns eine Prüfung dar.\n\nWas auch immer passieren wird: es ist mir eine Ehre, mit Euch gereist zu sein, <Name>.", progress = nil, completion = "Ein Sha zu besiegen... ist nicht einfach. Es ist ein Wunder, dass wir es ohne größere Verletzungen überstanden haben.\n\nTaran gibt sich noch immer die Schuld daran, dass sein Hass die Oberhand gewonnen hat und er diese Bestie auf das Land losgelassen hat. Es mag einige Zeit dauern, bis er sich mit dieser Tatsache anfreunden wird, aber es ist wichtig, dass es irgendwann geschieht. Sonst wird er vielleicht erneut anfällig sein.\n\nHeute haben wir viel erreicht und es wird sobald nicht vergessen werden.\n\nUnd auch Ihr sollt für Euren Beitrag nicht vergessen werden. Vielen Dank.", rewards = "Kapuze des NebelquellsHelm des NebellauerersHelm des ErdbewegersKopfbedeckung der GoldklaueGugel des SumpfläufersHelm des SteppenwildsHelm des OsulgipfelsHelm des TempelwächtersBleichwindhelmIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30969] = {title = "Ein neuer Feind", objective = "Sammelt 5 verderbte Insignien von Kultisten im Flammenschlund.", description = "Die Macht dieser Dunkelschamanen hat viele Verbündete angelockt, <Name>. Ehemalige Mitglieder der Horde, die jetzt auf einen finsteren Zweck hinarbeiten.\n\nWir müssen an ihnen ein Exempel statuieren, bevor wir es mit einem weiteren Schattenhammer zu tun bekommen.\n\nTötet alle Kultisten, die Euch über den Weg laufen, und bringt mir ihre Insignien.", progress = "Habt Ihr die Insignien gesammelt?", completion = "Gut gemacht, &lt;Name&gt;. Damit dürfte allen klar sein, wie Garrosh mit Versagern vorzugehen gedenkt...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30970] = {title = "Vom Hass erzürnt", objective = "Tötet 9 sengende Fleischreißer.", description = "Diese Skorpione sind mit Sha infiziert. Es scheint sie aus ihrer Höhle und in unser Lager getrieben zu haben, wo sie die Eindringlinge in ihr Revier ihren sengenden Hass spüren lassen.\n\nWir müssen die Skorpione vernichten und das Lager absichern. Tötet alle, die Ihr findet.", progress = nil, completion = "Gut. Zumindest das, was noch vom Lager übrig ist, ist jetzt sicherer.", rewards = "Umhang der KuhleUmhang des sengenden HassesSkorpiontuchFleischreißercapeTuch des AbendlichtsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30971] = {title = "Bestandsaufnahme", objective = "Sammelt 120 Feuerpfeile der Shado-Pan.", description = "Ich wurde ins Lager zurückgeschickt, um in Pech getauchte Pfeile für unsere Bogenschützen auf der Brücke zu holen und wurde von dem hier empfangen. Mit den meisten von diesen Pandaren habe ich trainiert... Darauf war ich nicht vorbereitet.\n\nDie Bogenschützen auf der Brücke brauchen trotzdem unsere Hilfe. Wenn Ihr beim Einsammeln von Pfeilen in den Trümmern helft, können wir vielleicht etwas aus diesem Horror herausholen.", progress = "Die Pandaren auf der Brücke verlassen sich auf uns...", completion = "Ich... Ihr... ähm, danke. Ihr musstet nicht helfen und habt es trotzdem getan. Danke.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30972] = {title = "Auf in den Kampf", objective = "Bringt den Köcher voll Feuerpfeile der Shado-Pan zu Lao-Chen dem eisernen Bauch an der Dämmerlichtbrücke.", description = "Lao-Chens Bogenschützen unten bei der Brücke werden diese Pfeile brauchen. Könnt Ihr sie ihnen bringen?", progress = "Willkommen im Chaos.", completion = "Taran Zhu hat mir berichtet, was aus meinem Lager geworden ist. Ich hätte es aufgehalten, wenn ich gekonnt hätte, aber die Angriffe von der Brücke wollten nicht aufhören.\n\nDanke, dass Ihr diese Pfeile bringt - meine Bogenschützen werden sie gut einzusetzen wissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30973] = {title = "In Flammen aufgehen", objective = "Tötet 10 Holzpanzer der Kor'thik mithilfe von Lao-Chens Fässern.", description = "Die Mantis, die über die Brücke kommen, haben dicke Panzer, denen die meisten unserer Angriffe nichts anhaben können. Sie haben jedoch eine Schwachstelle: Feuer.\n\nDeshalb haben Lao-Chens Männer Fässer auf das Schlachtfeld gebracht. Werft die Fässer in eine Mantisgruppe, damit Lao-Chens Bogenschützen sie in Brand setzen können.\n\nDanach sollten die Mantis leicht zu erledigen sein.", progress = "Kreative Lösung. Lao-Chen beeindruckt.", completion = "Ein weiterer Vorteil besteht darin, dass die Moral der Mantis darunter leiden wird, wenn sie mit ansehen müssen, wie ihre Brüder verbrennen. Makaber, doch wenn ihr Druck auf unsere Truppen nachlässt, wird das viele Leben retten.", rewards = "BleichwindgürtelbundGürtelbund des TempelwächtersTaillenschutz des OsulgipfelsGürtelbund des SteppenwildsGürtelbund des SumpfläufersGürtelbund der GoldklaueGürtel des ErdbewegersGürtelbund des NebellauerersGürtelbund des NebelquellsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30974] = {title = "Heben der Stimmung", objective = "Verteilt 8 von Eisenbauchs Spirituosen an Dämmerlichtscharmützler und Dämmerlichtwaldläufer in der Nähe.", description = "Die Fässer sind mit dem Schlimmsten aus meinem Lager gefüllt. Gut zum Feuer machen, schlecht zum Trinken.\n\nIch habe aber ein paar Krüge meiner besten Spirituosen herausgeholt und sie mit den Fässern raustragen lassen - sie sind für meine Männer, die sie sie sich wirklich verdient haben! Spirituosen heben nach unendlich langen, zermürbenden Kämpfen die Stimmung.\n\nWärt Ihr wohl so gut und würdet die gute Laune verteilen?Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEisenbauchs Spirituosen"}
MultiLanguageQuestData['de'][30975] = {title = "Die Eroberung der Dämmerlichtbrücke", objective = "Helft Lao-Chen dem eisernen Bauch, die entgegengesetzte Seite der Dämmerlichtbrücke zu halten.", description = "Drängen wir diese Insekten zurück über die Brücke und brechen ihren Kampfgeist!\n\nFolgt mir.", progress = nil, completion = "Nach dieser Abreibung werden die Mantis vermutlich nicht so schnell zurückkommen... und Lao-Chen kann sich uns jetzt bei der Jagd anschließen.", rewards = "AderlassbandBand des AbendlichtsLao-Chens RingSiegel der Kor'thikFleischfetzerringDer folgende Zauber wird auf euch gewirkt:\n\nTrigger Lao-Chen Holdout Turn-in Despawn\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30976] = {title = "Auf zur Jagd", objective = "Reitet mit Taran Zhu, Taoshi und Lao-Chen zu Rensais Wachposten.", description = "Damit sind wir um einen Kämpfer stärker. Eure Hilfe ist von unschätzbarem Wert.\n\nLos, brechen wir nach Westen zu Rensais Wachposten auf, um das letzte Mitglied unserer Gruppe zu finden.", progress = nil, completion = "Wir sind ganz nah dran. Ich spüre schon die Wallungen dieses widernatürlichen Hasses.\n\nEs ist nur der Ausbildung der Shado-Pan zu verdanken, dass sie noch nicht von seinem Einfluss überwältigt wurden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30977] = {title = "Bodenständige Begrüßung", objective = "Tötet 12 abgestürzte Flinkflügel der Kor'thik.", description = "Alle meiner Männer sind unten im Südwesten bei der Weitblickwarte, um die Mantis abzuwehren, die im Flug die Schlucht zu überqueren suchen. Solange meine Schützen Pfeile haben, bringen sie alle Mantis, die es hinüberschaffen, zum Absturz.\n\nWenn Ihr helfen wollt, könnt Ihr Euch beim Räumen der Mantis nützlich machen, sobald diese am Boden sind. Wärt Ihr dazu bereit, <Klasse>?", progress = nil, completion = "Ich bin Euch dankbar für Eure Mühen, &lt;Klasse&gt;. Auch die kleinste Verschnaufpause zwischen diesen Angriffen ist heutzutage eine Erleichterung.", rewards = "Satinrobe von WeitblickBalgrobe von WeitblickBrustplatte des ErdbewegersBrünierter Brustschutz von WeitblickSeidene Robe von WeitblickLedertunika von WeitblickBrustschutz des OsulgipfelsSchwerer Brustharnisch von WeitblickGepanzerter Brustharnisch von WeitblickIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30978] = {title = "Feindliche Lüfte", objective = "Schießt 50 Schwärmer der Kor'thik und Voress'thalik ab.", description = "Gleich geht's ans Eingemachte... \n\nNehmt diese Kanone da und helft, wenn Ihr könnt. An Zielen wird es keinen Mangel geben.", progress = "Ich könnte Euch wirklich an der Kanone gebrauchen...", completion = "Hervorragend geschossen!\n\nIch bin allerdings ziemlich sicher, dass dieser dicke Käfer den Fall überlebt hat...", rewards = "Ihr bekommt:\n\nNurongs Waffe"}
MultiLanguageQuestData['de'][30979] = {title = "Verheerender Schlag", objective = "Besiegt Voress'thalik mithilfe des Falkenmeisters Nurong.", description = "Brechen wir auf, um diesem Riesenkäfer den Garaus zu machen - Ihr und ich.", progress = nil, completion = "Wo habt Ihr mein ganzes Leben lang gesteckt?! Das war unglaublich!\n\nIch würde jederzeit mit Stolz an Eurer Seite kämpfen.", rewards = "Satinkapuze von WeitblickBalghelm von WeitblickKappe des ErdbewegersBrünierte Kopfbedeckung von WeitblickSeidene Gugel von WeitblickLederhelm von WeitblickKappe des OsulgipfelsSchwerer Helm von WeitblickGepanzerter Helm von WeitblickIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30980] = {title = "Helden der Shado-Pan", objective = "Kehrt mit Falkenmeister Nurong zu Taran Zhu an Rensais Wachposten zurück.", description = "Ihr sagt, Taran Zhu ist in Tonlong und fragt nach mir? Es muss wohl wichtig sein...", progress = nil, completion = "Mir gefällt, dass ich mich immer auf Euch verlassen kann. Ihr habt die Einstellung eines echten Shado-Pan.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30981] = {title = "Taoshi und Korvexxis", objective = "Tötet Korvexxis mit Taoshis Hilfe.", description = "Taoshi bereitet einen Überfall auf einen der Mantis-Anführer auf der Südseite von Sik'vess vor. Sie hat den Auftrag, seinen Kristall zu bergen, damit wir mit ihm das Tor öffnen können.\n\nZwei sind stärker als einer. Ich will Euch auch dort haben, damit alles reibungslos über die Bühne geht.", progress = nil, completion = "Der erste Kristall gehört uns...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30982] = {title = "Ungezieferbekämpfung", objective = "Tötet Adarogg und Nagma.", description = "Der Schlund wird von Flammenhunden und Lavawürmern überrannt, und bei solchen Mengen an Troggfleisch als Nahrung können sie sich ewig dort verschanzen.\n\nWir müssen uns sofort um diese Plage kümmern, bevor die Stadt in Gefahr gerät. Ihr seht aus, als könntet Ihr auf Euch aufpassen, <Name>.\n\nIch will, dass Ihr Euch einen Weg durch die Bestien bahnt und die größten Bedrohungen ausschaltet: Adarogg und Nagma.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Wer weiß, was die Biester sonst angerichtet hätten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30983] = {title = "Die Dunkelschamanen", objective = "Besiegt Dunkelschamane Koranthal und Lavawache Gordoth.", description = "Diese Dunkelschamanen sind schon seit Monaten hier, züchten Bestien und führen dunkle Rituale aus.\n\nIch weiß nicht, was sie mit all dem bezwecken, aber Freunde der Horde sind sie jedenfalls nicht. Und da kommt Ihr ins Spiel, <Name>.\n\nKämpft Euch durch den Schlund und tötet Dunkelschamane Koranthal und Lavawache Gordoth.", progress = nil, completion = "Es sieht aus, als hätten die Dunkelschamanenexperimente Gordoth in den Wahnsinn getrieben.\n\nHoffentlich ist der Spuk jetzt zu Ende, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30984] = {title = "Kein Orc bleibt zurück", objective = "Rettet 5 Späher der Kor'kron im Flammenschlund.", description = "Es hätte eine Routineaktion sein sollen, <Name>. Ein paar Troggs aus dem Weg räumen, sicherstellen, dass keine Gefahr für die Stadt besteht, und mittags nach getaner Arbeit ab in die Taverne.\n\nStattdessen wird eine Gruppe Späher vermisst, Flammenhunde dringen in Massen aus dem Schlund hervor und Xorenth faselt etwas vom \"nächsten Schattenhammer\".\n\n<Kommandant Bagran spuckt aus.>\n\nGeht dort hinein und holt mir meine Späher zurück, damit wir feststellen können, was da unten los ist.", progress = nil, completion = "Mehr haben nicht überlebt?\n\nIch weiß nicht, für wen diese Dunkelschamanen arbeiten, aber dafür werden sie bezahlen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30986] = {title = "Die uralte Mogukrypta", objective = "Tötet den besessenen Shado-Pan-Anführer und läutert den Teich des Lebens.", description = "Unser Spähtrupp wurde VERNICHTET. Hilfe!", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][30987] = {title = "Beitritt zur Allianz", objective = "Sprecht mit König Varian Wrynn in der Burg Sturmwind.", description = "Wir haben eine Pflicht, der wir nachkommen müssen, <Name>.\n\nEs liegt in unserer Verantwortung, die Tushui-Philosophie über die Grenzen der Wandernden Insel hinaus zu verbreiten... Und es gibt keinen geeigneteren Ort, damit anzufangen, als hier: Sturmwind, das Herz der Allianz.\n\nLasst uns herausfinden, wer hier der Anführer ist. Wir brauchen Verbündete.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30988] = {title = "Der Weg der Allianz", objective = "Begleitet König Varian Wrynn.", description = "Ich habe erst vor Kurzem erfahren, dass sich einige Eurer Leute hier einfinden würden. Ich würde Euch gern zu unseren Verbündeten zählen und hoffe, dass Ihr Euch uns anschließt.\n\nBegleitet mich ein Stück, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30989] = {title = "Ein alter Grubenkämpfer", objective = "Tragt einen Übungskampf gegen König Varian Wrynn aus.", description = "Ich muss herausfinden, ob Ihr auch wirklich kämpfen könnt. Möglicherweise werden wir beizeiten Eure militärische Hilfe benötigen. Und dann muss ich sicher sein, dass Ihr mein Königreich beschützen könnt.\n\nIch habe viele Geschichten über die Kampftechniken der Pandaren gehört, aber sie noch nie persönlich beobachten dürfen.\n\nAlso? Bereit für einen Kampf?Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nStormwind Pandaren Intro: Despawn Summons/Refresh Phase\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30991] = {title = "Ein Fassrolle machen!", objective = "Nehmt eines der Fässer in der Nähe von Lao-Chen, rollt es den Hügel hinab auf die Yaungol zu und entzündet es in ihrer Nähe, um 4 Baumschleuderer von Osul und 50 Eindringlinge von Osul zu vernichten.", description = "Bei meiner Ausbildung zum Braumeister hätte ich nicht gedacht, dass ich mein Fachwissen einmal auf diese Art einsetzen würde...\n\nHabt Ihr gewusst, dass Bier brennt, wenn man es anzündet? Ja, und wenn man Yaungolöl dazumischt, ist es sogar richtig explosiv.\n\nIch habe das Öl in diese Fässer gemischt. Rollt sie zu den Yaungol drüben am Tor und zündet sie an, wenn Ihr nah dran seid. \n\nEs wird ein paar Sekunden dauern, bis das Fass hochgeht, aber dann...\n\nNa, sagen wir einfach, ich wäre dann nicht gern dabei.\n\nUnd darum werde ich hier bleiben... und den Verlust dieses Bräus betrauern.", progress = "Hmm? Ich dachte nur gerade an mein armes, armes Bier...", completion = "Jippee, das war vielleicht 'ne Explosion! Und nicht nur eine.\n\nSchade, dass mein Bier dran glauben musste, doch wenigstens sind wir jetzt sicher.", rewards = "Ihr bekommt:\n\nLao-Chens letzter Humpen"}
MultiLanguageQuestData['de'][30992] = {title = "Bringt es zuende!", objective = "Beendet die Schlacht um das Ochsentor.", description = "Wir haben Nachricht von Suna vom Wall erhalten. Irgendetwas geht da vor...\n\nEs sieht so aus, als ob sie sich auf ihren letzten Ansturm vorbereiten. Es wird Zeit, dem eine Ende zu setzen, <mein Freund/meine Liebe>.", progress = "Lin wurde gefangen genommen... Wir müssen Taran Zhu aus seiner Selbstgefälligkeit reißen!", completion = "Nun, ihr Hauptmann ist tot. Ich glaube, wir haben sie endlich aus Kun-Lai vertrieben.\n\nAber um welchen Preis? So viele Tote, Lin gefangen... Ich werde nicht zulassen, dass Taran Zhu sich weiterhin seiner Verantwortung entzieht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30993] = {title = "Wo ist meine Verstärkung?", objective = "Sprecht mit Ban Bärenherz außerhalb des Shado-Pan-Klosters am Kun-Lai-Gipfel.", description = "Das geht jetzt zu weit. Ich kann nicht länger ignorieren, dass wir hier einfach im Stich gelassen werden.\n\nNach allem, was hier geschehen ist und was Ihr in Feuerzweig durchgemacht habt, müssen wir zum Kloster reisen.\n\nEgal, was sie dort beschäftigt hält – es kann warten! Wir können in meinem Ballon den Berg hoch zum Kloster fahren. Er ist beim Lager im Nordosten festgemacht.", progress = nil, completion = "Da sind wir, und jetzt wisst Ihr, warum wir nicht erlauben können, dass unsere Brüder tatenlos zusehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30994] = {title = "Lao-Chens Schachzug", objective = "Sprecht mit Lao-Chen dem eisernen Bauch in Winterblüte am Kun-Lai-Gipfel.", description = "In Ordnung. Dank Euch ist die Mauer unter unserer Kontrolle. Gute Arbeit.\n\nIch werde noch etwas hier oben bleiben und sicherstellen, dass es keine weiteren Yaungol auf die Mauer schaffen.\n\nIhr solltet jedoch wieder hinuntersteigen und nachsehen, was sich Lao-Chen ausgedacht hat. Ich gebe es nicht gerne zu, aber vielleicht hat er doch endlich eine gute Idee gehabt...", progress = nil, completion = "Schön zu sehen, dass Ihr es in einem Stück zurückgeschafft habt. Dank Eurer Hilfe mit den Fässern habe ich es geschafft, eine hübsche Überraschung für unsere Yaungol-Freunde an der Front vorzubereiten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30995] = {title = "Niemand bleibt zurück", objective = "Rettet 5 Waldläufer des SI:7 im Flammenschlund.", description = "Ich habe vor über einer Stunde einen Aufklärungstrupp ausgesandt, und bislang hat sich noch keiner davon zurückgemeldet. Und jetzt kommen diese verdammten Hunde in Massen aus dem Schlund hervor.\n\nIch weiß nicht, was dort unten vor sich geht, aber ich gehe nirgendwohin, bis ich meine Männer wiederhabe.\n\nIch will, dass Ihr dort hineingeht und sie findet, <Name>, vorzugsweise solange sie noch am Leben sind.", progress = nil, completion = "Mehr haben nicht überlebt?\n\nDas wird die Horde in Blut bezahlen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30996] = {title = "Die Dunkelschamanen", objective = "Besiegt Dunkelschamane Koranthal und Lavawache Gordoth.", description = "Diese Dunkelschamanen sind schon seit Monaten hier unten, züchten Bestien und führen dunkle Rituale aus.\n\nIch weiß nicht, was sie mit all dem bezwecken, aber Freunde der Allianz sind sie jedenfalls nicht. Und ich brauche Eure Hilfe, um sie aufzuhalten, <Name>. \n\nKämpft Euch durch den Schlund und tötet Dunkelschamane Koranthal und Lavawache Gordoth.", progress = nil, completion = "Es sieht aus, als hätten die Dunkelschamanenexperimente Gordoth in den Wahnsinn getrieben.\n\nHoffentlich ist der Spuk jetzt zu Ende, &lt;Name&gt;.", rewards = "Roben des gescheiterten RitualsFlammenschlundgamaschenBalgweste des SchamanenSteingardistenschienbeinschützerSengender GürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][30997] = {title = "Ungezieferbekämpfung", objective = "Tötet Adarogg und Nagma.", description = "Ich bin froh, dass Ihr hier seid, <Name>. Die Horde zieht eine Armee zusammen, und ich werde nicht warten, bis ich den Grund dafür weiß.\n\nWir müssen schnell zuschlagen und ein paar der größeren Bestien erledigen, die sie hier unten haben.\n\nIch will, dass Ihr dort hineingeht und Euch um Adarogg und Nagma kümmert, bevor die Horde sie als Waffen gegen uns einsetzen kann.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Wer weiß, was die Biester sonst angerichtet hätten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30998] = {title = "Ein neuer Feind", objective = "Sammelt 5 verderbte Insignien von den Dunkelschamanenkultisten.", description = "Die Horde nutzt dunkle Magie, um Bestien zu kontrollieren und ihre Brüder hier unten zu verderben, <Name>.\n\nDem beabsichtige ich einen Riegel vorzuschieben, aber zunächst muss ich wissen, womit wir es hier überhaupt zu tun haben. Und da kommt Ihr ins Spiel.\n\nKämpft Euch durch die Höhlen und sammelt die Insignien, die die Kultisten bei sich tragen. Damit kann ich feststellen, mit welcher Art von Magie wir es hier zu tun haben.", progress = "Habt Ihr die Insignien gesammelt?", completion = "Gut gemacht, &lt;Name&gt;. Jetzt können wir herausfinden, was sie hier unten wollten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][30999] = {title = "Gefährliche Reise", objective = "Sprecht mit Onkel Kleeblatt in Einfass.", description = "Die schwierigsten Wege lehren uns oft das meiste, <Klasse>. Ich werde zweifellos sehr viel davon lernen, dem Pfad Shaohaos zu folgen.\n\nVor vielen Jahren bestieg Shaohao den höchsten Gipfel des Kun-Lai-Gebirges, um Rat bei der Jadeschlange einzuholen. Auch ich werde auf der Suche nach Weisheit zum Grat des Unwissenden reisen.\n\nVielleicht seid Ihr ja auch an einer solchen Reise interessiert? Falls dem so ist, sprecht mit Onkel Kleeblatt. Er wird Euch bei Euren Vorbereitungen helfen.", progress = nil, completion = "Die Reise zum Grat des Unwissenden birgt viele Gefahren, &lt;Klasse&gt;. Hoffentlich habt Ihr genug Glücksbringer dabei!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31000] = {title = "Schreckensort", objective = "Sprecht mit Bogenmeisterin Li auf dem Schlangenrücken.", description = "Shado-Pan-Bogenschützen halten kontinuierlich Wache über die Schreckensöde, von der Spitze des Schlangenrückens aus. Sie würden die Hilfe von jemand so Fähigem wie Euch, <Klasse>, sicher willkommen heißen.\n\nNehmt einen Drachen und meldet Euch bei Bogenmeisterin Li.", progress = nil, completion = "Ein Freiwilliger für den Dienst in der Schreckensöde? Da dürftet Ihr der erste sein.\n\nFreut mich, Euch kennenzulernen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31001] = {title = "Absturz", objective = "Seilt Euch mit dem Shado-Pan-Seil zur Terrasse von Gurthan ab und sucht nach dem gestürzten Shado-Pan-Bogenschützen.", description = "Die Mantis abzuwehren ist schlimm genug, doch jetzt haben wir auch noch Spinnen, die von den Ruinen dort unten ausschwärmen.\n\nEiner meiner besten Bogenschützen wurde von einem ihrer Netze erfasst und direkt nach unten gezogen!\n\nWir glauben, dass er noch lebt, ich habe jedoch nicht genug Leute, um jemanden zu seiner Rettung loszuschicken. Hier oben sind unsere Ressourcen ausgereizt, <Klasse>.\n\nWenn Ihr helfen wollt, benutzt das Seil hinter mir, um Euch in die Ruinen abzuseilen. Ihr leidet doch nicht etwa unter Höhenangst?\n\nUnd wie steht es mit Spinnen?", progress = nil, completion = "Der Sturz war gar nicht so schlimm. Ich hatte schon immer ein Talent für weiche Landungen.\n\nDass ich auf einem Haufen Spinnenkadaver gelandet bin, hat vermutlich dabei geholfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31002] = {title = "Pfui Spinne", objective = "Tötet 6 Schreckensspinnerhüter und benutzt das Drachengewehr der Shado-Pan, um 20 Schreckensspinnereier auf der Terrasse von Gurthan zu zerstören.", description = "Wir halten uns, aber nur mit Müh und Not. Was auch immer Ihr anstellt, um den Ansturm der Schreckensspinner zu hemmen, die über die Mauer kommen, wäre eine große Hilfe.\n\nIst Euch danach zumute, Spinneneier einzeln mit der Hand zu öffnen?\n\nHab ich mir auch nicht gedacht. Nehmt eines unserer Drachengewehre und entzündet es dort unten. Ich will die Kleinen knallen hören.", progress = "Hey, helft mir hier raus!", completion = "Gute Arbeit habt Ihr mit dem Drachengewehr geleistet. Ich habe dort unten mein Bestes gegeben, Pfeile richten gegen diese Dinger allerdings nur begrenzt Schaden an.", rewards = "MuttersaathandschuheSaftfliegenhandschuheVerdorrte HolzstulpenKlarheitshandschuheSchreckensspinnerhandschützerGeisterfuchshandschuheWindschnitterstulpenStulpen des KlingenverschriebenenKältebissstulpenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31003] = {title = "Verrückte Mantis", objective = "Untersucht die internen Kämpfe der Mantis auf der Terrasse von Gurthan.", description = "Ihr werdet nicht glauben, was ich gesehen habe! Zwei Mantis, die miteinander gekämpft und Magie hin- und hergeschleudert haben.\n\nEiner von ihnen sah anders aus als alle Mantis, die ich je gesehen habe. Völlig andere Farben und Kleidung, wie eine Art... Orakel oder so. Der andere war total verrückt und hat mit Sha-Energie um sich geschmissen, als ob sie ein Krug Sturmbräuspezialmischung wär.\n\nIch muss jetzt zurück zu meinem Posten, aber die zwei kämpfen immer noch in der Höhle hinter mir und ich hab so ein Gefühl, dass es ziemlich wichtig ist. Wollt Ihr Euch das nicht mal anschauen?", progress = "Die Kaiserin... ist... irregeleitet.", completion = "&lt;Dieser Mantis ist schwer verletzt. Er ringt keuchend nach Atem und kann kaum sprechen.&gt;\n\nHalt, &lt;Volk&gt;...\n\nWir sind... nicht Euer Feind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31004] = {title = "Von Bern umhüllt", objective = "Benutzt die Stimmgabel der Klaxxi am uralten Bernbrocken auf der Terrasse von Gurthan.", description = "Nehmt... das...\n\n<Der sterbende Mantis streckt seinen Arm aus. In seinem geschundenen Greifer ruht eine Metallgabel mit zwei langen, dünnen Zinken und einem mit Edelsteinen besetzten Griff.>\n\nErweckt... den Windschnitter...\n\nNur so... kann dem Schwarm ein Ende bereitet werden.", progress = nil, completion = "Die Klaxxi... rufen mich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31005] = {title = "Erweckungskrankheit", objective = "Bringt 100 Saftfliegenteile zu Kil'ruk dem Windschnitter auf der Terrasse von Gurthan.", description = "Verzeiht meinen derzeitigen... Zustand. Ich habe viele Jahre lang geschlafen.\n\nEin Klaxxi'va mit Kyparisaft hätte meiner Erweckung beiwohnen sollen... aber nun müsst Ihr genügen.\n\nIm Süden spüre ich das Summen von Saftfliegen. Bringt sie zu mir.", progress = "Ohne Nahrung werde ich schon sehr bald sterben.", completion = "Das wird ausreichen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Phase Shift (Player)\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31006] = {title = "Der Rat der Klaxxi", objective = "Reist nach Klaxxi'vess inmitten der Schreckensöde. Ihr könnt Kil'ruk den Windschnitter auf der Terrasse von Gurthan bitten, Euch hinzubringen, oder auf eigene Faust reisen.", description = "Es ist Zeit, dass ich den Klaxxi Bericht erstatte. Sie hätten mich nicht erweckt, wenn es die Situation nicht verlangen würde.\n\nUnd Ihr habt Euch als nicht vollkommen nutzlos erwiesen. Deshalb werde ich Euch Euer Leben lassen.\n\nDer Rat wird vielleicht sogar noch Verwendung für Euch haben.", progress = nil, completion = "Dies ist ein heiliger Treffpunkt für die Klaxxi.\n\nIhr wärt gut beraten, mir das Reden zu überlassen.", rewards = "GurthanimedaillonRatshalsreifSchwarmgeborenenhalsketteKil'ruks AnhängerGeweihtes SteinamulettDer folgende Zauber wird auf euch gewirkt:\n\nThe Klaxxi Council: Completion Event\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31007] = {title = "Die Schreckensgelege", objective = "Tötet 6 Gelegehüter der Shek'zeer in den Gelegen von Shek'zeer.", description = "Die kaiserlichen Gelege sind zu einer Abscheulichkeit verkommen! Gelegehüter treiben die Entwicklung neuer Schwarmgeborener voran, indem sie sie in dieser bösartigen \"Sha\"-Energie tränken, bevor sie sie zur Mauer schicken.\n\nDie Klaxxi wollen dieser massiven Produktion an Schwarmgeborenen in den Schreckensgelegen Einhalt gebieten. Vernichtet die Gelegehüter!", progress = nil, completion = "Ein paar Verräter weniger, die wir an die Kunchong verfüttern, wenn sich der Aufruhr gelegt hat.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCancel Aura: Angel of Death Preview\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31008] = {title = "Bernwaffen", objective = "Sammelt 6 Bernklingen von Klingenverschriebenen der Shek'zeer beim Herzen der Angst und in den Gelegen von Shek'zeer.\n\nSprecht mit Kil'ruk dem Windschnitter in Klaxxi'vess für einen Ritt zum Herzen der Angst.", description = "Ihr da! Abschaum!\n\nIhr arbeitet jetzt für mich!\n\nDie Waffen der Klingenverschriebenen der Shek'zeer gehören zu den besten im ganzen Reich. Wenn Ihr nicht direkt von ihnen aufgespießt werdet, sobald Ihr diesen Ort verlasst, bringt mir so viele von ihnen, wie Ihr nur könnt! Ich will sicherstellen, dass wir genügend Waffen in Reserve haben, sollten wir sie brauchen.", progress = "Die Klingenverschriebenen führen ihre Schwerter mit Stolz. Ich will diese Schwerter in meinen Waffenständern haben.", completion = "Wenn alles nach Plan verläuft, werden die Klaxxi die Kaiserin ohne unsere Hilfe aufhalten. Dennoch ist es meine Rolle, mich bereitzuhalten.", rewards = "KältebissschuheSchuhe des KlingenverschriebenenWindschnitterschuheGeisterfuchsschuheSchreckensspinnerschuheKlarheitsschuheVerdorrte HolzschuheSaftfliegenschuheMuttersaatschuheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31009] = {title = "Toter Winkel", objective = "Sockelt den Resonanzkristall der Klaxxi in das inaktive Schallrelais beim Herzen der Angst.\n\nSprecht mit Kil'ruk dem Windschnitter in Klaxxi'vess für einen Ritt zum Herzen der Angst.", description = "Ein Klaxxi'va flüstert dem Turm zu. Dieser verbreitet die Nachricht zu anderen Türmen, zu Mantis, zu Getreuen. Das Geflüster wird zurückgeworfen und die Klaxxi hören es.\n\nSo wissen sie alles.\n\nEin Turm neben dem Palast ist still. Das darf nicht sein. Er muss für die Klaxxi singen.\n\nEs ist meine Aufgabe, den Turm zu reparieren, aber wenn Ihr den Klaxxi dient, solltet Ihr auch mir dienen. Ihr repariert den Turm und ich werde hier warten!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31010] = {title = "In ihren Fängen", objective = "Findet und erweckt den Mantisgetreuen in den Gelegen von Shek'zeer.", description = "Der Kristall singt zu den Klaxxi. Sie spüren einen Getreuen in den Gelegen direkt östlich vom Turm.\n\nGelegehüter versuchen, ihn zu verseuchen. Die Klaxxi werden das nicht zulassen.\n\nGeht und findet den Getreuen. Legt Eure Hände auf seine Kammer, und die Klaxxi werden ihr Flüstern durch Euch kanalisieren, um ihn zu befreien. Schützt ihn, wenn Ihr könnt.", progress = nil, completion = "Mein Schlaf wurde von plötzlichen Träumen unterbrochen. Unaussprechliche Alpträume.\n\nDann wachte ich auf.\n\nDie Klaxxi haben zu mir gesprochen. Ich habe meine Befehle. Es gibt viel zu tun.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nIn Her Clutch: Completion Event\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31011] = {title = "Feinde vor den Toren", objective = "Besiegt 10 Berserker der Amani, 5 Ungetüme der Amani und 3 Blutreiter der Gurubashi.", description = "Die Zandalari greifen an! Ihr müsst bei der Verteidigung des Dorfs helfen!\n\nWenn wir sie nicht zurückschlagen können, werden wir niemals die Überreste des Donnerkönigs finden!", progress = "Das Dorf muss gerettet werden!", completion = "Die Zandalari haben ihren Rückzug begonnen, &lt;Name&gt;. Dieser Sieg wird den Dorfbewohnern viel bedeuten.\n\nIn dem Durcheinander ist es mir gelungen, einen der Kämpfer gefangenzunehmen. Vielleicht gibt er ein paar Informationen preis..", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31012] = {title = "Beitritt zur Horde", objective = "Sprecht mit Garrosh Höllschrei in Orgrimmar.", description = "Da sind wir, <Name>... Orgrimmar, das Herz der Horde.\n\nAuch jenseits der Grenzen der Wandernden Insel können wir helfen. Es gibt dort draußen zahllose Probleme, die nur darauf warten, dass wir sie lösen. Meister Shang Xi hätte es so gewollt.\n\nEs gibt keinen besseren Ort, um damit anzufangen, als hier, mit der Hilfe der Horde. Finden wir heraus, wer ihr Anführer ist. Wir brauchen Verbündete.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31013] = {title = "Der Weg der Horde", objective = "Geht mit Garrosh Höllschrei.", description = "Mir wurde kürzlich zugetragen, dass Eure Art hierher kommen könnte.\n\nIch versuche seit Kurzem, die Stärke der Horde zu erhöhen. Einige Pandaren können uns da guttun.\n\nBegleitet mich ein Stück, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31014] = {title = "Höllschreis Geschenk", objective = "Beendet Garroshs Prüfung, indem Ihr Oggax, Gadoon und Eisblut besiegt.", description = "Ich muss wissen, ob Ihr kämpfen könnt... dass Ihr töten könnt und auch überleben. Am Ende wird jeder von Euch zum Krieg gerufen werden, und ich muss wissen, dass ich auf Euch zählen kann.\n\nIch habe vorhin von einem Geschenk gesprochen. Es ist hier, im Ring der Ehre. Tretet in die Arena, direkt durch diese Tür hinter mir. Ich werde Euer Können prüfen.", progress = nil, completion = "Ihr habt Euren Wert im Kampf und im Herzen mehr als bewiesen. Nur wenige wären bereit, ihre Heimat zu verlassen, um sich der Horde anzuschließen. Noch weniger wären bereit, sich im Kampf einem angreifenden Magnataur zu stellen.\n\nIhr und die anderen aus Eurem Volk sind bei uns willkommen. Willkommen in der Horde, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31015] = {title = "Eure Privatsammlung", objective = "Füllt das leere und verstaubte Buchregal auf.", description = "Pandaria ist ein Land, das reich an Geschichte, Legenden und Wissensschätzen aller Art ist. Ich möchte Euch bitten, auf Eurer Reise durch die Welt nach Artefakten und Informationen, die unserer Arbeit hier dienlich sein könnten, Ausschau zu halten.\n\nWenn Ihr genug Wissen zusammengesammelt habt, werden wir es hier in einem Buch für Eure persönliche Sammlung zusammenfassen.\n\nIhr könnt selbstverständlich gern jederzeit wiederkommen, um die Bücher einzusehen, die wir für Euch zusammenstellen.", progress = "So viel zu lernen.", completion = "Ah! Nun da das erledigt ist, können wir anfangen, Eure gesammelten Forschungsergebnisse zusammenzustellen. Ich freue mich schon darauf, zu sehen, was Ihr gefunden habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31016] = {title = "Die Lehrensucher", objective = "Sprecht mit Lehrensucher Cho im Heim des Wissens im Tal der Ewigen Blüten.\n\nBereitgestellter Gegenstand: \n", description = "$p,\n\nwir haben etwas Unglaubliches im Tal der Ewigen Blüten entdeckt. Ein großes Archiv voller Bücher, Schriftrollen und Wissensschätze, das seit den Tagen des Mogureiches unberührt scheint.\n\nBitte kommt zu uns, sobald Ihr es einrichten könnt. Ihr findet das Heim des Wissens, indem Ihr erst zum berühmten Mogu'shangewölbe reist und dann die Landestelle gleich über den Eingang anfliegt.\n\nIch freue mich schon auf Euch!\n\nHerzliche Grüße,\n\nLehrensucher ChoIhr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31018] = {title = "Unter dem Herzen der Angst", objective = "Tötet Gehilfe Ek'vem, Gehilfe Ikkess, Gehilfe Suruz und Gehilfe Tsikzi und befreit anschließend Xaril den vergifteten Geist.", description = "Die Klaxxi haben einen weiteren Getreuen entdeckt, <Erwecker/Erweckerin>.\n\nDer hier wurde gut vor uns versteckt, und zwar aus gutem Grund.\n\nDie Kaiserin hat ihn bereits in Besitz genommen, und ihre Gehilfen versuchen ihn gerade zu vernichten.\n\nSie wirken ihre Zauber in einer Kammer tief unter dem Palast und müssen aufgehalten werden.\n\nWir halten Klaxxi'vess. Ihr müsst an unserer Statt gehen. Findet den Eingang zu ihrer Kammer beim Sims im Westen.", progress = nil, completion = "Ihr habt Eure Pflicht gut erfüllt, Erwecker.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31019] = {title = "Bern ist Leben", objective = "Tötet 7 Reißer der Nebelklingen und den Schuppenlord der Nebelklingen.", description = "Damit unsere Anstrengungen gegen das Mantisreich fortgesetzt werden können, benötigen wir mehr Bern.\n\nUnterhalb des Sees im Süden gibt es einen großen Vorrat Bern, allerdings wird diese Region von einem wilden Saurokstamm bewohnt.\n\nIch kann sonst niemanden entbehren. Ihr müsst zu dem See gehen und die Stärke des Stammes einer Probe unterziehen. Dünnt ihre Reihen aus und vernichtet ihren Anführer.\n\nDas ist doch sicher keine große Aufgabe für Euch, oder?", progress = "Der Bern kommt mir irgendwie bekannt vor…", completion = "Das Flüstern scheint diesem Bern zu entströmen.\n\nKann es sein, dass ein weiterer Getreuer darin schläft?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31020] = {title = "Die Bestie füttern", objective = "Tötet 8 Kaltbisskrokilisken.", description = "Ich muss sofort zum Rat der Klaxxi und den anderen Getreuen, aber ich kann kaum stehen.\n\nIch muss essen, <Erwecker/Erweckerin>.\n\nIch spüre die schlagenden Herzen von Kreaturen am nördlichen Ufer des Sees.\n\nTötet sie für mich und ich erledige den Rest.", progress = "Ich habe viele tausende Jahre lang geschlafen. Bevor ich dem Rat erneut beitrete, muss ich an Stärke gewinnen.", completion = "Ich spüre, wie die Kraft in meinen Körper zurückkehrt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31021] = {title = "Lebendiger Bern", objective = "Sammelt 8 Einheiten lebendigen Berns und gebt sie Korven dem Ersten zu essen.", description = "Flüssiger Bern ist höchst effizient, um einen neu erweckten Getreuen zu stärken, und wird normalerweise bei der Erweckungszeremonie bereitgestellt.\n\nLeider scheint es, als ob Ihr diese Anweisungen nicht erhalten habt. Wir müssen also improvisieren.\n\nIch spüre, dass es in dem See unter uns eine große Menge fossilisierten Berns gibt. Es würde mir helfen, aber ich bin zu schwach, es selbst hervorzuholen.\n\nWenn Ihr es für mich tut, sollt Ihr belohnt werden.", progress = "Versteht Ihr das, Erwecker? Der Bern ist ein Lebensspender.", completion = "Vielen Dank, Erwecker. Das reicht fürs Erste.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31022] = {title = "Kypari Zar", objective = "Aktiviert den Sonarturm und verteidigt anschließend Korven den Ersten, während er den Baum untersucht.", description = "Was ist das für ein Baum auf dem Hügel im Westen? Ist es vielleicht... Kypari Zar?\n\n<Korven der Erste verfällt in Schweigen.>\n\nAls ich von meinem letzten Zerstörungszug wiederkam, noch bevor ich zu einem Getreuen erhoben wurde, wurde mir die Ehre zuteil, genau diesen Baum zu pflanzen.\n\nWie ich sehe, ist er zu einem großen Kypari geworden, aber... irgendetwas stimmt nicht.\n\nEs gibt einen alten Sonarturm am Fuß des Baums. Bringt mich dorthin, <Erwecker/Erweckerin>. Ich kann den Turm nutzen, um mir die Sache genauer anzusehen.", progress = "Was ist mit unserem Zuhause passiert? Es fühlt sich nicht richtig an.", completion = "Einst wurden die Adern dieses Baums von gewaltigen Bernflüssen durchströmt. Jetzt ist er nicht weiter als eine vertrocknete Hülle.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31023] = {title = "Schwarmrelikte", objective = "Sammelt 8 Mantisrelikte.", description = "Diese merkwürdige Schnitzerei ist mit komplizierten Schriftzeichen bedeckt, die aus der Sprache der Mantis stammen könnten.\n\nEuch fallen weitere Relikte auf, die achtlos über das Lager und im See verstreut liegen.\n\nVielleicht hätten die Klaxxi Interesse daran, diese Artefakte zu untersuchen.\n\nWer weiß? Vielleicht verdient Ihr Euch dadurch einen Gefallen.", progress = "Was habt Ihr denn da?", completion = "Diese Relikte beschreiben die Geschichte von Kypari Vos und den Bernbäumen in der Nähe.\n\nIch würde sie gern untersuchen.\n\nVielen Dank, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31024] = {title = "Kunchong-Leckereien", objective = "Sammelt 4 fleischige Schildkrötenlenden.", description = "Kovok wird größer und muss zu gleichen Teilen diszipliniert und belohnt werden.\n\nAn Disziplin mangelt es mir nicht, doch unsere Fleischvorräte gehen zur Neige.\n\nWeiter im Süden werdet Ihr nördlich des Sternensees und Kypari Zars Schildkröten finden.\n\nMacht Jagd auf sie. Ihr Fleisch schmeckt Kovok.", progress = "Was habt Ihr Kovok mitgebracht?", completion = "Ja, ein angemessenes Mahl.\n\nGut gemacht.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31026] = {title = "Die Wurzel des Problems", objective = "Tötet die Kaltbissmatriarchin.", description = "Kypari Zar stirbt.\n\nVon tief unter seinen Wurzeln wird er von einer schrecklich Dunkelheit verderbt.\n\nDer Baum kann nicht gerettet werden, aber wir können zumindest seine Schmerzen lindern.\n\nSchaut. Diese bösartige Kreatur hat einen Pfad zu seinem Versteck geschaffen. Wir müssen ihm nur den Hügel hier hinter dem Turm hinunter folgen.", progress = "Der Schwarm weiß nichts von ihrer schrecklichen Torheit! Diese kostbaren Bäume müssen um jeden Preis geschützt werden!", completion = "Danke, Erwecker. Jetzt kann Kypari Zar in Frieden träumen.\n\nDie Bestie war allerdings nur ein Gefäß für die Verderbnis.\n\nNein... die wahre Verderbnis liegt viel tiefer.", rewards = "Relikt von Kypari ZarSiegel von Kypari ZarEmblem von Kypari ZarInsigne von Kypari ZarAbzeichen von Kypari ZarIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31030] = {title = "Ins Kloster", objective = "Trefft Ban Bärenherz im Shado-Pan-Kloster.", description = "Das ist ... unfassbar. Wenn das Kloster wirklich vom Sha übernommen wurde, wird es uns viel abverlangen, die Mönche darin von dem verderblichen Einfluss zu reinigen.\n\nRuft eine Gruppe Eurer Verbündeten zusammen und trefft mich im Kloster.", progress = nil, completion = "Ihr seid gekommen. Gut. Wir befinden uns in einer prekären Situation.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31031] = {title = "Ins Kloster", objective = "Trefft Ban Bärenherz im Shado-Pan-Kloster.", description = "Das ist ... unfassbar. Wenn das Kloster wirklich vom Sha übernommen wurde, wird es uns viel abverlangen, die Mönche darin von dem verderblichen Einfluss zu reinigen.\n\nRuft eine Gruppe Eurer Verbündeten zusammen und trefft mich im Kloster.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31032] = {title = "Ersticken der Himmel", objective = "Verbrennt 10 Leichen der Flinkflügel der Kor'thik.", description = "Nurong möchte, dass ich Fackeln zum Verbrennen der Leichen verteile.\n\nDie fliegenden Mantis sind zerbrechlich und werden dem heißen Rauch nicht lange standhalten.", progress = "Wenn es auch einige von ihnen durch den Rauch schaffen, sind es nur so wenige, dass wir sie leicht abschießen können.", completion = "Seid bedankt für Eure Hilfe, Fremder.", rewards = "Ihr bekommt:\n\nEinäschernde Fackel"}
MultiLanguageQuestData['de'][31034] = {title = "Feinde im Untergrund", objective = "Sprecht mit Kommandant Bagran.", description = "Direkt unter dieser Stadt befinden sich Feinde der Horde, <Klasse>.\n\nDie Dunkelschamanen erheben Anspruch auf Orgrimmar und haben bereits den Flammenschlund eingenommen! Wir müssen ihren Truppen entgegenstürmen und uns das zurückholen, was uns gehört!\n\nGeht und sprecht mit Kommandant Bagran direkt hinter dem Eingang zum Flammenschlund. Er wird weitere Befehle für Euch haben.", progress = nil, completion = "Ich habe Euch bereits erwartet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31036] = {title = "Feinde im Untergrund", objective = "Sprecht mit Kommandant Bagran.", description = "Der Flammenschlund von Orgrimmar ist an die Dunkelschamanen gefallen! <Name>, das dürfen wir nicht einfach hinnehmen, sonst gehen sie als Nächstes auf Donnerfels los.\n\nGeht und sprecht mit Kommandant Bagran direkt hinter dem Eingang zum Schlund. Helft ihm, so gut Ihr könnt, denn unsere Schicksale sind miteinander verwoben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31037] = {title = "Feinde im Untergrund", objective = "Sprecht mit Kommandant Bagran.", description = "Mit all seinem üblichen Charme erbittet Kriegshäuptling Garrosh höflichst um Eure Anwesenheit im Flammenschlund, um bei dessen Rückeroberung von den Dunkelschamanen zu helfen. Seine befestigte Stadt ist offenbar nicht ganz so uneinnehmbar, wie er dachte.\n\nGeht und sprecht mit Kommandant Bagran direkt hinter dem Eingang zum Flammenschlund. Er wird sicher froh sein, kompetente Hilfe zu bekommen.", progress = nil, completion = "Ich habe Euch bereits erwartet, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31038] = {title = "Der Ring des Herausforderers: Schneeblüte", objective = "Fordert Schneeblüte heraus und besiegt sie im Ring des Herausforderers.", description = "Die Nachrichten von Euren Heldentaten verbreiten sich im Lager, <Name>.\n\nSchneeblüte würde Eure Fertigkeit im Kampf gern testen.\n\nBereitet Euch lieber vor, <Klasse>. Sie ist nicht einfach zu besiegen.\n\nWenn Ihr Euer Potenzial unter Beweis stellen könnt, werdet Ihr eine wertvolle Freundin gewinnen.", progress = "Wie ist es gelaufen?", completion = "Ach ja, Ihr habt Schneeblüte also tatsächlich im Kampf besiegt?\n\nIch wette, die Niederlage wird ihr eine Weile lang schwer zu schaffen machen.\n\nIhr habt sie aber auf Eure Seite gebracht - gut gemacht.\n\nSie freundet sich mit Fremden nicht schnell an, wird sich aber mit der Zeit als loyale und zuverlässige Gefährtin erweisen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31039] = {title = "Die Mogubedrohung", objective = "Tötet 12 Schlangenbinder oder Bestienmeister der Shan'ze.", description = "Unsere Späher haben Truppen der Mogu auf Shan'ze Dao im Nordwesten entdeckt.\n\nDie Insel ist angeblich unbewohnt, deshalb ist ihre Anwesenheit dort beunruhigend.\n\nNoch beunruhigender ist die Tatsache, dass sie unheimliche Experimente auf der Insel durchführen.\n\nIch brauche jemand Tüchtiges wie Euch, <Klasse>, um die Lage zu prüfen.\n\nDie Shan'ze werden Euch vermutlich Probleme bereiten. Wenn dieser Fall eintritt, tötet sie.", progress = nil, completion = "Die Shan'ze führen etwas im Schilde. Gut gemacht, &lt;Name&gt;, wir müssen aber weiter im Auge behalten, was sie machen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUnterwegs mit den Shado-Pan\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31040] = {title = "Boshafte Waldgeister", objective = "Tötet 30 Dunkelholzpixies oder Dunkelholzirrlichter.", description = "Die Finsterwaldgeister von Shan'ze Dao werden jetzt von den Mogu beherrscht.\n\nDiese einst gerissenen Schwindler dienen mittlerweile zur Gänze den Shan'ze. Sie werden von Tag zu Tag unverschämter, rauben und töten, um ihre Meister zufriedenzustellen.\n\nSie müssen eliminiert werden, seid aber vorsichtig. Sie mögen vielleicht harmlos aussehen, sind jedoch ziemlich brutal.", progress = "Die Waldgeister müssen die Befehle ihrer Herren ausführen.", completion = "Gute Arbeit, &lt;Klasse&gt;. Wenn wir nicht eingegriffen hätten, würden die Waldgeister unserer gesamten Armee bald zahlenmäßig überlegen sein.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUnterwegs mit den Shado-Pan\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31041] = {title = "Eiersuche!", objective = "Sammelt 8 Eier eines Wolkenreiters.", description = "Eier. Ja, Ihr habt mich richtig verstanden. Ich habe Eier gesagt, doch zum Essen sind sie nicht.\n\nHabt Ihr schon einmal ein Wolkenschlangenei gesehen?\n\nDiese seltenen Eier sehen wie Edelsteine aus und waren einst ihr Gewicht in Gold wert.\n\nAuf Shan'ze Dao im Norden wimmelt es für gewöhnlich nur so vor Wolkenschlangen, aber die Mogu und Geister haben es auf ihre Eier abgesehen.\n\nWir müssen so viele dieser kostbaren Eier retten wie möglich.\n\nIch zähle auf EUCH, <Name>.", progress = "Konntet Ihr ein paar Eier finden? Die Schlangen legen ihre Eier in Nestern am Strand, aber die Waldgeister sind dafür berüchtigt, dass sie sie bei jeder Gelegenheit stehlen.", completion = "Sachte, sachte!\n\nDanke, dass Ihr diese Eier sicher geborgen habt, &lt;Name&gt;.\n\nIch kenne da ein paar Schlangenreiter im Jadewald, die sich bestens um sie kümmern werden.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUnterwegs mit den Shado-Pan\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31042] = {title = "Herzen aus Onyx", objective = "Sammelt 4 Herzen aus Onyx.", description = "Die Schlangenbinder der Shan'ze beherrschen die Gedanken der wilden Wolkenschlangen, sie erschaffen aber auch ihre eigenen finsteren Kreaturen aus Stein, Metall, Blut und uralten Zaubern.\n\nIhre Schöpfungen, die Onyxsturmklauen, bewachen die Insel im Nordwesten.\n\nIch möchte die Magie untersuchen, die diese Kreaturen bindet. Bringt mir ihre Herzen, damit ich besser verstehen kann, mit welcher Form der Zauberei wir es zu tun haben.", progress = "Die Onyxsturmklauen würden die Befehle ihrer Meister niemals missachten.", completion = "Die sind genau richtig, &lt;Name&gt;. Vielen Dank.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUnterwegs mit den Shado-Pan\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31043] = {title = "Dunkle Künste", objective = "Sammelt 8 Tafeln der Shan'ze.", description = "Es heißt, das Shan'ze Dao einst Standort eines großen Mogutempels war.\n\nDort studierten und praktizierten die Shan'ze die Kunst, sich die Toten oder leblose Objekte untertan zu machen.\n\nEin Großteil ihres Wissens liegt noch immer unter den Ruinen der Insel im Nordwesten verschüttet.\n\nWir müssen uns ihres Wissens bemächtigen - zum einen, damit sie es nicht in die Finger bekommen, aber auch, damit wir die Natur ihrer Experimente besser verstehen.", progress = "Wissen ist Macht. Und genau das macht die Mogu so gefährlich.", completion = "Gut gemacht, &lt;Name&gt;.\n\nWir werden uns umgehend daran machen, die Schrift dieser Tafeln zu dechiffrieren.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUnterwegs mit den Shado-Pan\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31044] = {title = "Bronzeklauen", objective = "Sammelt 20 Bronzeklauen.", description = "Unter den wildesten und getreuesten der Schöpfungen der Shan'ze sind ihre Qilen.\n\nDiese Monster jagen ihre Beute, bis sie erlegt ist oder sie selbst dabei sterben.\n\nIch möchte, dass Ihr ihre Reihen ausdünnt und außerdem ihre Bronzeklauen an Euch nehmt.\n\nIhre Klauen sind stark und rasiermesserscharf - ideal, um daraus Waffen und Haken für unsere Zwecke zu schaffen.", progress = "Die Qilen sind wild, doch auch in Euren Augen erkenne ich das Wilde.", completion = "Diese Klauen werden sich als nützlich erweisen.\n\nGute Arbeit, &lt;Klasse&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUnterwegs mit den Shado-Pan\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31045] = {title = "Illusionen der Vergangenheit", objective = "Tötet 3 Illusionisten der Shan'ze.", description = "<Klasse>, ich bin auf Eure Stärke angewiesen, um die Illusionisten der Shan'ze auf Shan'ze Dao im Nordwesten zu eliminieren.\n\nIch bedaure, Euch mit dieser schwierigen Aufgabe betrauen zu müssen.\n\nDie Illusionisten zählen zu den Stärksten unter den Elitezauberern der Shan'ze.\n\nSie werden nicht leicht zu besiegen sein, aber ich kenne niemanden, <der/die> besser für diese Aufgabe geeignet ist als Ihr, <Klasse>.", progress = nil, completion = "Ich wusste, Ihr würdet es schaffen, &lt;Name&gt;!\n\nJetzt, wo wir es nicht mehr mit so vielen Illusionisten der Shan'ze zu tun haben, wird unsere Aufgabe hier um Einiges leichter sein.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUnterwegs mit den Shado-Pan\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31046] = {title = "Kleine Jungtiere", objective = "Befreit 20 Wolkenreiterjungtiere.", description = "Ich habe die grausamen Experimente gesehen, die die Shan'ze auf ihrer Insel im Nordwesten durchführen.\n\nDie Shan'ze brüten Schlangenjunge aus ihren Eiern aus und halten sie in winzigen, total verdreckten Käfigen.\n\nDie grausamsten Wärter hungern sie aus und quälen sie.\n\nWir müssen möglichst viele Jungtiere retten. Ich erteile Euch freie Hand, jeden Mogu, der sich Euch in den Weg stellt, zu bestrafen!", progress = nil, completion = "Diese Kreaturen werden sich an Euch als ihren Retter erinnern.\n\nDas habt Ihr gut gemacht, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUnterwegs mit den Shado-Pan\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31047] = {title = "In Freiheit geboren", objective = "Befreit 6 wilde Wolkenreiter von ihren Ketten.", description = "Kennt Ihr die Geschichte der großen Wolkenschlangen von Pandaria, <Name>?\n\nEines Tages müsst Ihr sie Euch anhören. Doch jetzt ist keine Zeit, sie zu erzählen.\n\nIhr müsst wissen, die wilden Wolkenreiterschlangen von Tonlong stecken in der Klemme.\n\nDie Mogu fangen wilde Schlangen und verderben ihre Gedanken, um sie ihrem finsteren Willen zu beugen.\n\nGeht nach Shan'ze Dao im Nordwesten. Befreit die ausgewachsenen Schlangen aus ihren Ketten. Rettet sie!", progress = nil, completion = "Gute Arbeit, &lt;Volk&gt;. Es freut mich zu sehen, dass die wilden Schlangen wieder frei sind.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUnterwegs mit den Shado-Pan\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31048] = {title = "Geistreiche Urnen", objective = "Tötet 24 Ahnen der Shan'ze. Ahnen der Shan'ze sind in den Begräbnisurnen der Mogu zu finden.", description = "Wir haben antike Begräbnisurnen der Mogu in den Ruinen auf Shan'ze Dao gefunden.\n\nDas mag sonst kein Problem sein, aber diese Urnen beherbergen zornige Mogugeister.\n\nSie stellen nicht nur eine Gefahr für jene Unglückseligen dar, die auf sie stoßen; in den falschen Händen könnten sie sogar zum Werkzeug der Zerstörung werden.\n\nWir müssen Shan'ze Dao von ihnen befreien.", progress = "Haben die Geister Euch Ärger gemacht?", completion = "Gut, dass wir sie los sind! Diese Mogugeister waren längst fällig.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUnterwegs mit den Shado-Pan\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31049] = {title = "Sie gehen uns auf den Geist", objective = "Tötet die Dunkelholzfee.", description = "Die Geister von Shan'ze Dao sind von jeher launenhafte Trickster gewesen, doch jetzt sind sie unter den Einfluss der Mogu geraten.\n\nBereits jetzt organisieren sie sich unter einem neuen Anführer.\n\nDas dürfen wir nicht zulassen.\n\nIhre frechen Streiche waren eine Sache, aber wenn sie sich zusammenzuschließen, droht ihre dunkle Magie potenter und gefährlicher zu werden, als wir uns vorzustellen vermögen.\n\nSchaltet ihren Anführer aus, bevor es zu spät ist.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;.\n\nDie Waldgeister mögen harmlos aussehen, aber genau das macht sie so gefährlich.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31055] = {title = "Der Biss in den Saurokapfel", objective = "Bringt \"Der Biss in den Saurokapfel\" zu Lehrensucher Cho.\n\nBereitgestellter Gegenstand: \n", description = "$p,\n\nwir haben uns mit Eurer Saurokforschung beschäftigt und jetzt einige Dinge über ihre Vergangenheit herausgefunden.\n\nWenn Ihr uns im Heim des Wissens im Tal der Ewigen Blüten besuchen kommt, können wir diese Informationen Eurer Sammlung hinzufügen.\n\nVielen Dank für Eure Mühen!\n\nHerzliche Grüße,\n\nLehrensucher Cho", progress = nil, completion = "Ich glaube nicht, dass vor Eurer Forschung die Pandaren wussten, warum eigentlich die Saurok so feindselig sind. Wir werden dieses Wissen Eurer Sammlung hinzufügen. Wenn ich etwas darüber sagen soll, dann zeigt einfach auf das entsprechende Buch in Eurer Privatsammlung.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDer Biss in den Saurokapfel\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31058] = {title = "Affenbande", objective = "Bezwingt Kapitän Uuk.", description = "Piraten! Unsere Küsten sind von den unausgeglichensten, ungehobelsten, ungepflegtesten und ungutsten... ähm, schlechtesten Ho-zen überfallen worden, die Pandaria jemals erlebt hat. Und, um das Ganze noch schlimmer zu machen, dienen sie auch noch dem legendären Kapitän Uuk!\n\nWir sehen sie jede Nacht, wie sie auf ihrer Insel Unga Ingu feiern und Punsch brauen.\n\nWie wäre es denn, wenn wir zur Abwechslung mal ihre Getränke klauen! Ich glaube, ich kann ihre Mixtur sogar noch verbessern.\n\nSammelt ein paar Freunde und trefft mich im Süden von Unga Ingu. Es ist Zeit für einen Brausturm!", progress = "Diese Ho-zen haben ein paar gemeine Spielsachen dabei und manche ihrer Gebräue sind noch gemeiner.", completion = "Ein guter Schlag! Wahrhaftig ein guter Schlag! Das ist die Sorte Schlag, die zurückschlägt. Gut gemacht, &lt;Klasse&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31060] = {title = "Dawson test POI", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][31061] = {title = "Sturmritt", objective = "Benutzt die Bronzeklauen, um 8 Wolkenreiter der Shan'ze zu besteigen. Greift sie an, um sie von ihrer Verderbnis zu befreien.", description = "Shan'Bu, der Anführer der Shan'ze, hält auf dem höchsten Punkt der Insel im Nordwesten ein finsteres Ritual ab.\n\nWir glauben, dass die unterworfenen Wolkenreiter der Shan'ze den Zauber mit Energie versorgen. Wie, ist uns noch nicht bekannt.\n\nWir glauben, dass die Wolkenreiter der Shan'ze noch vor der Verderbnis, die sie verpestet, gerettet werden können.\n\nNehmt diese Bronzeklauen und benutzt sie, um auf den Rücken eines Wolkenreiters der Shan'ze zu steigen.\n\nGreift sie an. Prügelt etwas Vernunft in ihre Köpfe!", progress = nil, completion = "Wir begreifen weder völlig, was die Shan'ze machen, noch wie sie die wilden Schlangen beherrschen.\n\nBan hat die Theorie, dass nichts außer körperlichen Schmerzen die Gedankenkontrolle durchbrechen kann.\n\nWenn die Schmerzen der Wolkenreiter der Shan'ze groß genug sind, lockert sich der Griff der Verderbnis und sie erinnern sich endlich daran, wer sie sind.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31062] = {title = "Wenn die Toten sprechen", objective = "Tötet den Todessprecher der Shan'ze.", description = "Die Experimente der Shan'ze werden von einem mächtigen Totenbeschwörer geleitet, dem Todessprecher der Shan'ze.\n\nWenn wir ihren Unternehmungen ein Ende setzen wollen, müssen wir ihren Anführer ausschalten.", progress = "Wovon sind die Mogu besessen, solche abscheulichen Experimente durchzuführen?", completion = "Ausgezeichnete Arbeit, &lt;Name&gt;.\n\nEtwas anderes hätte ich auch nicht erwartet.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31063] = {title = "Lao-Chen und Serevex", objective = "Tötet Serevex mit der Hilfe von Lao-Chen dem eisernen Bauch.", description = "Direkt über dem Eingang im Baum im Norden von Sik'vess kämpft Lao-Chen gegen den Anführer. Er soll den zweiten Kristall zurückbringen, den wir brauchen, um uns Zutritt zum Tunnel der Mantis zu verschaffen.\n\nBrecht zu ihm auf und gewährt ihm Eure Hilfe.", progress = nil, completion = "Wir haben also den zweiten Kristall. Gut.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31064] = {title = "Nurong und Rothek", objective = "Tötet Rothek mit Hilfe von Falkenmeister Nurong.", description = "Falkenmeister Nurong ist nach Sik'vess im Nordwesten vorausgegangen, um dafür zu sorgen, dass der letzte Anführer der Mantis nicht entkommt.\n\nStoßt zu ihm und helft ihm, den Mantis-Anführer zu töten. Wenn Ihr ihm dabei helft, wird Nurong den letzten Kristall zurückbringen.", progress = nil, completion = "Der letzte Kristall gehört uns. Unsere letzte Auseinandersetzung steht unmittelbar bevor.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31065] = {title = "Verschüttet", objective = "Schaut durch das Handfernrohr an Rensais Wachposten.", description = "Taoshi hat ein Handfernrohr am Rand des Passes aufgestellt, um mir das Ergebnis ihrer Aufklärungsmission zu zeigen.\n\nGeht hin und schaut es Euch an.", progress = "Geht und schaut.", completion = "Unsere Aufgabe liegt klar vor uns.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31066] = {title = "Ein Ruf aus der Finsternis", objective = "Tötet den verderbten Getreuen in Kypari Vor.", description = "Die kaiserlichen Gelege habt Ihr also überlebt. Ihr seid... widerstandsfähig.\n\nDie Klaxxi hören einen weiteren Getreuen, im Norden, inmitten der Sha-verbrannten Wurzeln von Kypari Vor.\n\nEr schreit vor Schrecken und Schmerzen. Er kann nicht gerettet werden.\n\nDie Klaxxi wollen, dass er erlöst wird. Besiegt ihn. Solltet Ihr versagen, kehrt nicht hierher zurück.", progress = "Der Befehl steht. Tötet den gefallenen Getreuen.", completion = "Was?! Wie habt Ihr...\n\nDer Todesrufer war ein gewaltiger Held. Er war wohl noch nicht vollständig erwacht.\n\nIhr habt Glück gehabt.", rewards = "Band des kanalisierten FlüsternsRing der unaussprechlichen AlpträumeBand der plötzlichen TräumeSiegel des erweckten GetreuenGelegehütersiegelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31067] = {title = "Wenn Krieg den Himmel ganz erfüllt", objective = "Tötet Azzix K'tai.", description = "Die Mantis machen mir die Arbeit nie einfach, doch diesmal sind sie zu weit gegangen.\n\nDie gelegentlichen Angriffe aus Kor'vess können wir abwehren, doch jetzt... jetzt beginnen sie, uns einzukesseln.\n\nUnd was noch schlimmer ist: Sie saugen den Bern aus unserem Baum.\n\nDas werden wir nicht zulassen! Wir brauchen den Bern! Zum Bierbrauen!\n\nSie haben einen Bau in die Südseite des Baums gegraben. Könntet Ihr Euch für mich um sie kümmern?", progress = nil, completion = "Wir sind nicht hier, um jemanden zu verletzen. Wir wollen nur etwas Bier mit diesem Baumsaft brauen. Ist das zu viel verlangt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31068] = {title = "Heiliges Rezept", objective = "Bringt die Rolle der Vorzeichen zu Lya von den Zehn Gesängen im Abendlichtbraugarten.", description = "\"Wir müssen, wenn der Schrecken naht\nUnd Krieg den Himmel ganz erfüllt\nBefreien das Gefäß des Heils\nDas schläft, in seinen Kern gehüllt.\"\n\nDie Schriftrolle enthält noch weitere Strophen. Vielleicht kann jemand im Abendlichtbraugarten diese kryptische Botschaft entziffern.", progress = "Ist das eine Art Schriftrolle?\n\nDürfte ich sie mir wohl anschauen?", completion = "&lt;Lya liest die komplette Mitteilung.&gt;\n\nDiese Schriftrolle, diese... diese Prophezeiung...\n\nSie ist entsetzlich!", rewards = "Glücksbringer von den Zehn GesängenFlechtband von den Zehn GesängenKnoten von den Zehn GesängenDer folgende Zauber wird auf euch gewirkt:\n\nLya beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31069] = {title = "Mit Schatten gebunden", objective = "Erntet 100 Schattentropfen, indem Ihr Sha und wilde Tiere in der Nähe des Abendlichtbraugartens tötet.", description = "Diese Schriftrolle, die Ihr gefunden habt...\n\nIch sehe mir immer wieder die Zeile in der zweiten Strophe an - \"durch Holz und Schatten gebunden\". Vor allem der \"Schatten\" fasziniert mich.\n\nIch muss zugeben, dass ich schon oft darüber nachgedacht habe, etwas von der verbliebenen Sha-Essenz hier in der Gegend zu nehmen und sie in ein Gebräu einzuarbeiten. Ich vermute, das ist genau der Schatten aus unserem Rezept.\n\nSüdöstlich von unserem Baum werdet Ihr hohe Sha-Konzentrationen finden... möglicherweise könnt Ihr aber auch welches von der hiesigen Tierwelt ernten.", progress = nil, completion = "Wunderbar. Das wird einen exquisiten Zusatz zu unserem Bier abgeben.\n\nDie gefährlichsten Zutaten sind ziemlich oft auch die aromatischsten.", rewards = "SchattenbundcapeVus TuchUmhang des SaftmeistersBiergartencapeUmhang des SonnenuntergangsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31070] = {title = "Dolche der Großen", objective = "Besorgt 3 große Mushanzähne.", description = "In diesem Rezept steht: \"scharfe Dolche der großen Wesen\"...\n\n<Olon denkt über die Zeile nach.>\n\nMushan! Das ist es!\n\nDort draußen streifen viele Mushan umher, die große, lange Zähne haben... so lang wie Dolche. Das muss die Zutat für das Rezept sein.", progress = "Ich frage mich, wie wir diese Reißzähne in das Bier mischen? Ich kann sie nicht zerstoßen - das wäre zu grob.\n\nVielleicht sollte ich sie einfach kurz einweichen.", completion = "Mit Mushanzähnen zu brauen ist mir noch nie vorher eingefallen.\n\nDiese Schriftrolle enthält ein paar abgefahrene Ideen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31071] = {title = "Schande über mich", objective = "Findet das verlorene Fässchen, die verlorenen Krüge und die verlorenen Picknickutensilien.", description = "Ich habe meine Brauerfreunde im Stich gelassen.\n\nIch habe ein paar Vorräte zu der Lichtung östlich von unserem Baum gebracht... und sie dort gelassen. Mit dem Sha, das das Land verderbt, und den herumstreifenden Mantis ist es zu gefährlich, sie zurückzuholen.\n\nWenn Ihr mir bei der Suche danach helfen könntet, würde das vielleicht etwas von meiner verlorenen Ehre wiederherstellen.", progress = "Habt Ihr sie gefunden? Ist es möglich?", completion = "Ihr habt mir Freude bereitet, Reisender.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31072] = {title = "Scharfe Dolche", objective = "Besorgt Kz'Kziks und Ilikkax' Klingen.", description = "Vergesst sie und vergesst ihr GEBRÄU. Wir haben richtige Arbeit zu erledigen.\n\nDie Schriftolle erwähnt \"scharfe Dolche der großen Wesen\". Ich glaube, ich weiß, wo die zu finden sind.\n\nZwei Mantisleutnants patrouillieren die Mark des Schreckens im Süden. Beide tragen zeremonielle Dolche bei sich.\n\nBringt diese Dolche hierher, <Name>. Wir stehen vielleicht knapp vor einer großen Sache.", progress = "Ich glaube, langsam fange ich an, die nächsten paar Zeilen dieser Prophezeiung zu verstehen, <Name>.\n\nHabt Ihr die Dolche schon?", completion = "Seht Euch diese Dolche an!\n\n&lt;Lya hält die Klingen Heft an Heft.&gt;\n\nSie wurden als Paar gefertigt! Aber wie fügt man sie zusammen...?", rewards = "KältebisshandlappenHandlappen des KlingenverschriebenenWindschnitterhandlappenGeisterfuchshandlappenSchreckensspinnerhandlappenKlarheitshandlappenVerdorrte HolzhandschützerSaftfliegenhandlappenMuttersaathandlappenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31073] = {title = "Durch Holz gebunden", objective = "Besorgt 8 Stücke duftendes Kernholz.", description = "<Vu sieht sich das Rezept an.>\n\nHmm... \"durch Holz gebunden\". Normalerweise brauen wir nicht mit Holz. Saft, ja... aber kein Holz.\n\nIn Ausnahmefällen fügen wir unserem Bier Kernholz von den Treants westlich von hier hinzu. Die meisten von ihnen sind den Mantis zum Opfer gefallen... doch ihre Überreste sollten für unser Rezept ausreichen.", progress = "Wir brauen hier nicht mit Holz. Das verleiht dem Bier einen herben, schalen Geschmack, so ähnlich wie Wein.\n\n<Vu spuckt aus.>", completion = "Ich werde diese Teile vorbereiten.\n\nWir haben bereits etliche dieser Zutaten gesammelt! Bald muss ich einen Topf aufsetzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31074] = {title = "Holz und Schatten", objective = "Findet das Mal der Kaiserin und die Herzwurzel von Kypari Kor.", description = "\"Scharfe Dolche der großen Wesen\" werden \"durch HOLZ und SCHATTEN gebunden\". Hmm.\n\nWährend meiner Zeit hier habe ich eine Menge über die Kor'thik-Mantis gelernt. Ich weiß, dass sie in ihrer Siedlung Kor'vess Schreine unterhalten.\n\nEiner von ihnen ist die Herzwurzel des Baums, in dem sie hausen. Beim anderen handelt es sich um eine dunkle Säule, die sie mit ihrer Königin verbindet.\n\nDie beiden Schreine sind das Holz und der Schatten. Wenn ich mit meiner Prophezeiung recht habe... sollten die Dolche in ihrer Gegenwart reagieren.", progress = nil, completion = "&lt;Name&gt;, seht her! Die Dolche - sie sind aneinander gebunden, zu einer gegabelten Klinge.\n\nWir sind auf der richtigen Fährte. Ich wusste doch, dass das kein Bierrezept war.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31075] = {title = "Könige des Sonnenuntergangs", objective = "Trefft Euch mit Saftmeister Vu in Rikkitun.", description = "Olon hatte eine gute Idee. Er glaubt, wir sollten den Waldgeistern im Westen einen Besuch abstatten und sie fragen, ob sie welche von diesen Zutaten haben. Einige Elemente in diesem Rezept erscheinen... merkwürdig.\n\nDie Rikkitun-Waldgeister haben ein Dorf westlich von Kor'vess. Hoffentlich sehen wir uns dort, <Name>.", progress = nil, completion = "Ist schon länger her, seit ich unterwegs gebraut habe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31076] = {title = "Das Schicksal der Sturmbräus", objective = "Fragt die Bewohner des Abendlichtbraugartens, ob sie Sturmbräus gesehen haben.", description = "Seid gegrüßt, <Volk>. Ich heiße Chen Sturmbräu.\n\nIch suche nach meiner Familie. Man hat mir gesagt, dass mehrere Sturmbräus die Mauer überquert haben, um bei der Bekämpfung der Mantis zu helfen. Ich will sie finden und mich ihnen anschließen.\n\nIst Euch jemand mit dem Namen Sturmbräu begegnet, der hier durchgekommen ist? Würde es Euch etwas ausmachen, mir beim Herumfragen zu helfen?", progress = nil, completion = "&lt;Chen hört aufmerksam zu.&gt;\n\nDer Dicke Dan, Han, Evie und Mama. Ich verstehe.\n\nSieht so aus, als wäre Dan hier in Sicherheit. Ich werde mich auf die Suche nach Evie, Han und Mama Sturmbräu machen.\n\nGute Reise, &lt;Name&gt;, und folgt dem Weg des Wanderers.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nChen Sturmbräu beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31077] = {title = "Evie Sturmbräu", objective = "Hört Euch Chens Trauerrede im Abendlichtbraugarten an.", description = "Es war zu spät. Sie war so klein... und ich kam zu spät.\n\nSie sollte richtig bestattet werden. Eine kleine Kriegerin wie sie hat etwas Besseres verdient.", progress = "<Chen trauert.>", completion = "&lt;Chen ist einen Augenblick lang ruhig.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31078] = {title = "Han Sturmbräu", objective = "Findet Han Sturmbräu in der Morgenkammer unter Kor'vess.", description = "Später ist auch noch Zeit zum Trauern. Doch vorher gibt es noch mehr Sturmbräus, die gefunden werden müssen.\n\nSie sagen, Han Sturmbräu wurde zuletzt bei der Erforschung von Kor'vess gesehen. Ich vermute, dass er in den Mantisbau auf der anderen Seite unterwegs war.\n\nTrefft mich dort, <Name>. Ich zweifle nicht daran, dass ich mit ein paar Mantis im Alleingang fertigwerde... mit Euch an meiner Seite würde ich mich allerdings besser fühlen.", progress = "Ich glaube, ich sehe dort drüben jemanden, aber ich schaffe es nicht durch diese Bernstrahlen.", completion = "Zuerst Evie und jetzt Han.\n\nIch bin schon wieder zu spät gekommen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nChen Sturmbräu beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31079] = {title = "Der Schrecken nimmt zu", objective = "Tötet 7 schlurfende Nebellauerer und 2 Kypariten.", description = "Wir sind vor den Mantis geschützt. So lautete das Abkommen, das vor vielen Jahrtausenden geschlossen wurde.\n\nEs gibt jedoch Mächte, vor denen wir nicht sicher sind. Die Kypariten im Untergrund im Westen suchen uns heim, verfolgen uns... fressen uns sogar auf. Ebenso laben sich die Nebellauerer an uns.\n\nHelft unserem Volk, <Außenseiter/Außenseiterin>. Bezwingt die Kypariten.", progress = "Wir hassen es, aufgefressen zu werden.", completion = "Es ist gut, jemanden von Eurer enormen Größe in unserem Dorf zu haben.\n\nIhr seid vielseitig verwendbar.", rewards = "Kyparitischer StabKyparitischer KlauenkolbenAxt von RikkitunBogen von RikkitunObelisk von RikkitunBoggeos RitualaxtGezackte Klinge von RikkitunDornen von RikkitunBoggeos DornenKlinge des OrakelsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31080] = {title = "Feurige Flügel", objective = "Stupst Rikkileaflatterlinge und fangt dann 88 Sprenkel Flatterlingsstaub.", description = "Ich glaube, das alte Stück Papier erwähnt irgendwas über \"feurige Flügel\". Die kleinen Drachen hier in der Gegend haben Flügel. Und die sind irgendwie feurig.\n\nIhr seid schneller als ich. Versucht doch, ein paar von den Drachen zu fangen... oder zumindest ihr Pulver abzuschütteln.\n\nEs lohnt sich nicht, einen harmlosen kleinen Drachen zu töten, wenn man nichts weiter von ihm will als den Glitzerstaub von seinen Flügeln.", progress = "Ich konnte keines von diesen Dingern fangen!", completion = "JAWOHL!!! FLATTERLINGSSTAUB!!!\n\n&lt;Olon wirft das Pulver in einen Topf.&gt;\n\nDieses Gebräu sieht... merkwürdig aus und stinkt ziemlich. Langsam fange ich an zu glauben, dass Lya vielleicht recht hatte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31081] = {title = "Urzeitliche Geisterzauber", objective = "Tötet Ahgunoss und Mygoness.", description = "Ich vermute, wir werden die Hilfe dieser Waldgeister benötigen.\n\nWir haben zwei verzauberte Dolche, die mit Holz und Schatten aneinander gebunden sind. Jetzt brauchen wir jemanden, der unser Artefakt mit alten \"Geisterzaubern\" belegt.\n\nZeigen wir den Waldgeistern doch, dass wir es gut meinen, bevor wir sie um einen Gefallen bitten. Ich habe gehört, wie ihr Anführer Nebellauerer erwähnt hat, die mehrere Dorfbewohner entführt haben. Wenn wir diese Nebelviecher töten... bekommen wir im Gegenzug vielleicht die \"Geisterzauber\".", progress = nil, completion = "Gute Arbeit. Ich habe gehört, wie sich die Waldgeister über uns unterhalten.\n\nWir haben ihre Aufmerksamkeit erregt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31082] = {title = "Das Gefäß des Heils", objective = "Bringt mit der Hilfe der Rikkitunsänger 3 Muttersaatexemplare zur Sammelgrube in Rikkitun.\n\nWenn Ihr von Euren Sängern getrennt werdet, könnt Ihr sie mit der Glocke von Rikkitun erneut herbeirufen.", description = "Ich weiß, wonach Ihr und das Pandamädchen sucht. Wir können den Ritus für Euch abhalten... später.\n\nVorher benötige ich aber Hilfe. Die Saat fällt von unserem großen Mutterbaum. Sie einzusammeln ist unsere Aufgabe, selbst in gefährlichen Zeiten wie diesen.\n\nBegleitet meine Sänger zur Muttersaat, damit sie sie zur Sammelgrube zurückbringen können.", progress = nil, completion = "Ja, gut. Die Sache mit der Muttersaat hat sich erledigt.\n\nJetzt können wir uns über Eure Verzauberung unterhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31083] = {title = "Goldversprechen", objective = "Sprecht mit Häuptling Rikkitun in Rikkitun in der Schreckensöde.", description = "Sobald die Kreatur gestorben war, erschien eine seltsame Gruppe von Waldgeistern und nahm die Perle weg.\n\n Die Waldgeister leben in der Nähe, in einem Dorf namens Rikkitun. Vielleicht solltet Ihr das untersuchen.", progress = nil, completion = "Diese Glanzsaat... das war Eure Tat? Ich hatte bereits eine... aber zwei sind besser.\n\nWir brauchen nur die Samen, nicht die Hüllen. Wenn Ihr wollt, könnt Ihr sie behalten.", rewards = "Ihr bekommt:\n\nGokk'loks Muschel"}
MultiLanguageQuestData['de'][31084] = {title = "Die Bindung des Glanzes", objective = "Erlaubt, dass Häuptling Rikkitun die Gegabelte Klinge verzaubert.", description = "Es ist schon sehr, sehr lange her, seit unser Stamm gebeten wurde, dieses Ritual abzuhalten. Ich werde mein Bestes geben.", progress = nil, completion = "Die Klinge ist bereit.\n\nBleibt nur noch eine Aufgabe: Ihr müsst sie benutzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31085] = {title = "Feuer und Ängste", objective = "Benutzt die Gabel des Ruins bei Iyyokuk dem Wachen und beschützt ihn dann, bis er entkommen kann.", description = "Wir haben die Klingen gefunden, mit Holz und Schatten gebunden und mit einem alten Geisterzauber gesegnet. Wenn ich mich nicht irre, ist es jetzt Zeit, dieses Ding zu benutzen.\n\nDie Waldgeister haben ein altes Saftstück in der Bernüberwinterung erwähnt, einer Höhle der Mantis nicht weit vom Palast ihrer Kaiserin. Das muss das \"uralte Blut\" aus der Prophezeiung sein.\n\nWas auch immer in diesem Saft enthalten ist, es muss wichtig sein. Viel Glück, <Name>.", progress = nil, completion = "Im Inneren dieses Berns war ein... ein Mantis? Auf die Idee, dass die Lösung für unseren Krieg mit den Mantis... ein anderer Mantis sein könnte, wäre ich nie gekommen.\n\nEs gibt noch viel für mich zu lernen, eins weiß ich aber ganz genau: Das war BESTIMMT kein Bierrezept.", rewards = "MuttersaattreterSaftfliegenfußschützerVerdorrte HolzsabatonsKlarheitsschienbeinschützerSchreckensspinnertreterGeisterfuchsstiefelWindschnittersabatonsKriegsstiefel des KlingenverschriebenenKältebisskriegsstiefelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31086] = {title = "Uraltes Blut", objective = "Besorgt einen Brocken erstarrten Berns.", description = "In einer Angelegenheit sind Lya und ich uns einig: Das \"uralte Blut\" ist so gut wie sicher der Saft der großen Bäume in der Gegend. Ich sollte das wissen, schließlich braue ich ständig damit.\n\nDer älteste dieser Bäume dient der Großkaiserin Shek'zeer als Zuhause - er ist unter dem Namen \"Das Herz der Angst\" bekannt. Findet mir etwas Bern von diesem Baum, dann sollte unser Gebräu komplett sein.", progress = "Und? Glück gehabt?", completion = "Das sollte reichen! Rezept... vollständig.\n\nUnd jetzt wollen wir mal sehen, wie dieses Gebräu schmeckt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSummon Controller\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31087] = {title = "Unsere Reichweite ausbauen", objective = "Aktiviert das resonierende Signal in der Bernscheinkuhle.", description = "Die Klaxxi'va hören noch einen Getreuen. Seine Schreie sind schwach und verlieren sich in der Dunkelheit.\n\nDas Signal muss verstärkt werden.\n\nEs gibt einen Turm in der Bernscheinkuhle, der schon seit vielen Jahren verstummt ist. Er muss singen, die Klaxxi verlangen es!\n\nDieses Mal begleite ich Euch. Ihr werdet mir helfen, ihn zu reparieren.\n\nNehmt den Resonanzkristall und trefft mich in der Kuhle.", progress = nil, completion = "Es ist gut, dass Ihr gekommen seid.\n\nVielleicht seid Ihr ja doch nicht so nutzlos, wie ich gedacht habe...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31088] = {title = "Schuld und Sühne", objective = "Tötet 8 Bernernter der Ik'thik auf dem Stechenden Pfad.", description = "Am Stechenden Pfad finden sich junge Kyparibäume. Die Kaiserin entzieht den Schösslingen viel zu früh ihre Energie, Fremdling. Sie müssen erst wachsen, bevor der Bern entnommen werden kann.\n\nDie Klaxxi'va verlangen, dass dieses Verbrechen bestraft wird! Es wird ihnen gefallen, wenn Ihr den Tod auf die Bernernter der Ik'thik niederregnen lasst.", progress = nil, completion = "Die Klaxxi sind zufrieden mit unserer Arbeit, Fremdling. Ihr habt Euch als nützlicher herausgestellt, als wir angenommen hatten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31089] = {title = "Niemals wieder am Meer", objective = "Benutzt die Stimmgabel der Klaxxi bei den meergepeitschten Felsen, um den Getreuen zu erwecken.", description = "Die Klaxxi'va haben zu mir gesprochen, Fremdling. Der Getreue war im Salzigen Schlick verborgen, doch inzwischen hat die Tarnung versagt.\n\nDie Echsenmänner haben ihn umstellt. Er darf ihnen nicht in ihre schuppigen Hände fallen.\n\nIhr werdet ihn finden; Ihr werdet ihn erwecken. Kehrt nicht ohne ihn zurück!\n\nFür diese Tat werden uns die Klaxxi dankbar sein.", progress = nil, completion = "Was... was für eine Kreatur seid Ihr?\n\nWie habt Ihr mich aufgeweckt?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDespawn All Summons LAB [INTERNAL]\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31090] = {title = "Je älter, desto besser", objective = "Sammelt 7 mit Bern gefüllte Gläser von den Bernsammlern auf dem Stechenden Pfad.", description = "Es ist ein Verbrechen, die jungen Bäume abzuernten, doch den Bern zu verschwenden ist eine noch viel größere Schandtat.\n\nFrischer Bern ist nicht so wirkungsvoll, doch die Klaxxi brauchen ihn, um den Kampf fortführen zu können. Wir werden ihnen mehr davon bringen und sie werden mich mit Dank überhäufen!\n\nSammelt den frischen Bern. Wir lagern ihn ein, bis er lange genug gereift ist, um verzehrt zu werden.", progress = "Ich würde ja mit Euch gehen, um Bern zu sammeln, aber meine Talente finden hier besseren Einsatz.", completion = "Selbst roher Bern wird uns nützlich sein. In Zeiten wie diesen können wir es uns nicht leisten, wählerisch zu sein.\n\nDie Klaxxi'va werden sich freuen, dass ich daran gedacht habe. Ich werde ihnen sagen, dass Ihr mir geholfen habt!", rewards = "BernscheinmedaillonBernscheinhalsreifBernscheinhalsketteBernscheinanhängerBernscheinamulettIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31091] = {title = "Wiedervereinigt!", objective = "Helft Kaz'tik dem Manipulator, seine größte Waffe zutage zu fördern.", description = "Ihr seht mich an und stellt fest, dass ich kein großer Krieger bin. Warum wurde ich als Getreuer auserkoren? Nicht alle Waffen kann man sehen, <Erwecker/Erweckerin>. Man sollte nicht nach dem Aussehen allein urteilen.\n\nEhe ich Euch mehr erzähle, muss ich wissen, dass ich Euch vertrauen kann.\n\nZur Zeit meiner Bewahrung wurde etwas, das mir wichtig war, versteckt. Ohne es bin ich nichts.\n\nVerteidigt mich, während ich meine größte Waffe zutage fördere, und Ihr habt mein Vertrauen.", progress = nil, completion = "Kovok ist so imposant wie bei unserer letzten Begegnung. Er wird den Klaxxi große Siege bescheren.", rewards = "MuttersaatkapuzeSaftfliegenhelmVerdorrter HolzhelmKlarheitskopfbedeckungSchreckensspinnergugelGeisterfuchshelmWindschnitterhelmHelm des KlingenverschriebenenKältebisshelmDer folgende Zauber wird auf euch gewirkt:\n\nDespawn Kaz'tik Summon 2\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31092] = {title = "Füttern oder gefressen werden", objective = "Beginnt mit Kovoks Erziehung, indem Ihr ihn mit 6 saftigen Schildkrötenfilets von Salzpanzerschnappern aus dem Salzigen Schlick füttert.", description = "Nach vielen Jahren der Arbeit mit den Kunchong habe ich eine Theorie entwickelt: Einen von klein auf großzuziehen stärkt die Bindung und damit auch die akustische Verbindung.\n\nIch hatte gerade mit Kovoks Erziehung begonnen, als ich für die Umhüllung auserkoren wurde. Er ist noch jung und muss sorgfältig ausgebildet werden, um sein vollständiges Potenzial zu erlangen.\n\nIch vertraue Euch Kovok an, aber seid gewarnt: Sollte ihm irgendetwas zustoßen, büßt Ihr mir dafür mit dem Leben.\n\nAls Erstes müsst Ihr ihn füttern, um sein Vertrauen zu gewinnen. Die Schildkröten hier in der Gegend sollten sich dafür gut eignen.", progress = nil, completion = "Sehr gut! Ich hatte so halb befürchtet, dass Kovok einfach Euch fressen würde. Was für eine schöne Überraschung Euch beide heil und im Ganzen zu sehen.\n\nVielleicht liegt es Euch im Blut, Kunchong aufzuziehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31093] = {title = "Ho-zen im Nebel", objective = "Bringt \"Ho-zen im Nebel\" zu Lehrensucher Cho im Heim des Wissens.\n\nBereitgestellter Gegenstand: \n", description = "$p,\n\nEure Forschungen über die Ho-zen waren wirklich sehr erhellend.\n\nWenn Ihr uns im Heim des Wissens im Tal der Ewigen Blüten besuchen kommt, können wir diese Informationen Eurer Sammlung hinzufügen.\n\nVielen Dank für Eure Mühen!\n\nHerzliche Grüße,\n\nLehrensucher Cho", progress = nil, completion = "Die Ho-zen sind von Natur aus sehr ungestüm.\n\nWir werden dieses Wissen Eurer Sammlung hinzufügen. Wenn Ihr wollt, dass ich es Euch schildere, müsst Ihr einfach auf den korrekten Band in Eurer Sammlung zeigen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nHo-zen im Nebel\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31094] = {title = "Fischschwänke", objective = "Bringt \"Fischschwänke\" zu Lehrensucher Cho im Heim des Wissens.\n\nBereitgestellter Gegenstand: \n", description = "$p,\n\nich habe mit Freuden Eure Forschungsarbeit über die Jinyu gelesen. Ein wahrlich faszinierendes Volk - und so intelligent!\n\nWenn Ihr uns im Heim des Wissens im Tal der Ewigen Blüten besuchen kommt, können wir diese Informationen Eurer Sammlung hinzufügen.\n\nVielen Dank für Eure Mühen!\n\nHerzliche Grüße,\n\nLehrensucher Cho", progress = nil, completion = "Was für eine Freude. Die Jinyu haben mich immer schon fasziniert. So ein friedfertiges Volk, gesegnet mit so viel Weisheit.\n\nWir werden dieses Wissen Eurer Sammlung hinzufügen. Wenn ich etwas darüber sagen soll, dann zeigt einfach auf das entsprechende Buch in Eurer Privatsammlung.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFischschwänke\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31095] = {title = "Das dunkle Herz der Mogu", objective = "Bringt \"Das dunkle Herz der Mogu\" zu Lehrensucher Cho im Heim des Wissens.\n\nBereitgestellter Gegenstand: \n", description = "$p,\n\nwir alle haben immer gewusst, dass die Mogu finster und heimtückisch sind. Eure Forschungen deuten allerdings darauf hin, dass es alles noch viel schlimmer ist.\n\nWenn Ihr uns im Heim des Wissens im Tal der Ewigen Blüten besuchen kommt, können wir diese Informationen Eurer Sammlung hinzufügen.\n\nVielen Dank für Eure Mühen!\n\nHerzliche Grüße,\n\nLehrensucher Cho", progress = nil, completion = "Mogu. Schon bei ihrem Namen steht mir der Pelz zu Berge. Wir werden dieses Wissen Eurer Sammlung hinzufügen. Wenn ich etwas darüber sagen soll, dann zeigt einfach auf das entsprechende Buch in Eurer Privatsammlung.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDunkles Herz der Mogu\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31096] = {title = "Wofür es sich zu kämpfen lohnt", objective = "Bringt \"Wofür es sich zu kämpfen lohnt\" zu Lehrensucher Cho im Heim des Wissens.\n\nBereitgestellter Gegenstand: \n", description = "$p, Ihr habt die Geschichte des Befreiungskampfes unseres Volkes gegen die Moguunterdrücker aufgedeckt.\n\nWenn Ihr uns im Heim des Wissens im Tal der Ewigen Blüten besuchen kommt, können wir diese Informationen Eurer Sammlung hinzufügen.\n\nVielen Dank für Eure Mühen!\n\nHerzliche Grüße,\n\nLehrensucher Cho", progress = nil, completion = "Wer hätte gedacht, dass die Befreiung der Pandaren mit einem einzigen Schlag begann?\n\nWundervoll. Wir werden dieses Wissen Eurer Sammlung hinzufügen. Wenn ich etwas darüber sagen soll, dann zeigt einfach auf das entsprechende Buch in Eurer Privatsammlung.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWofür es sich zu kämpfen lohnt\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31097] = {title = "Das Herz des Mantisschwarms", objective = "Bringt \"Das Herz des Mantisschwarms\" zu Lehrensucher Cho im Heim des Wissens.\n\nBereitgestellter Gegenstand: \n", description = "$p,\n\nwir wissen Eure Bemühungen um den Wissensschatz über Pandaria sehr zu schätzen. Aber leider rauben mir diese erschreckenden Dokumente, die Ihr uns geschickt habt, Nacht für Nacht den Schlaf.\n\nWenn Ihr uns im Heim des Wissens im Tal der Ewigen Blüten besuchen kommt, können wir diese Informationen Eurer Sammlung hinzufügen.\n\nVielen Dank für Eure Mühen!\n\nHerzliche Grüße,\n\nLehrensucher Cho", progress = nil, completion = "Als wir unser Forschungsprojekt begannen, hätte ich nie gedacht, einmal so viel über dieses schreckliche Volk zu erfahren.\n\nWir werden dieses Wissen Eurer Sammlung hinzufügen. Wenn ich etwas darüber sagen soll, dann zeigt einfach auf das entsprechende Buch in Eurer Privatsammlung.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDas Herz des Mantisschwarms\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31100] = {title = "Das Lied der Yaungol", objective = "Bringt das \"Lied der Yaungol\" zu Lehrensucher Cho im Heim des Wissens.\n\nBereitgestellter Gegenstand: \n", description = "$p,\n\nEure Forschungen über die Yaungol waren wahrhaft erhellend.\n\nWenn Ihr uns im Heim des Wissens im Tal der Ewigen Blüten besuchen kommt, können wir diese Informationen Eurer Sammlung hinzufügen.\n\nVielen Dank für Eure Mühen!\n\nHerzliche Grüße,\n\nLehrensucher Cho", progress = nil, completion = "Die Yaungol sind ein sehr widerstandsfähiges Volk, gestärkt durch ihr Exil in den Gebieten jenseits der Mauer. Wir werden dieses Wissen Eurer Sammlung hinzufügen. Wenn ich etwas darüber sagen soll, dann zeigt einfach auf das entsprechende Buch in Eurer Privatsammlung.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGesang der Yaungol\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31102] = {title = "Die sieben Bürden des Shaohao", objective = "Bringt \"Die sieben Bürden des Shaohao\" zu Lehrensucher Cho im Heim des Wissens.\n\nBereitgestellter Gegenstand: \n", description = "$p,\n\nIhr scheint die Geschichte von Shaohao, des letzten Kaisers von Pandaria, vollständig aufgeklärt zu haben.\n\nWenn Ihr uns im Heim des Wissens im Tal der Ewigen Blüten besuchen kommt, können wir diese Informationen Eurer Sammlung hinzufügen.\n\nVielen Dank für Eure Mühen!\n\nHerzliche Grüße,\n\nLehrensucher Cho", progress = nil, completion = "Diese Geschichte habe ich schon lange versucht aufzuklären. Seit das Sha freigelassen wurde, hatte ich das Gefühl, dass diese Geschichte die Grundlage für alles ist.\n\nWir werden dieses Wissen Eurer Sammlung hinzufügen. Wenn ich etwas darüber sagen soll, dann zeigt einfach auf das entsprechende Buch in Eurer Privatsammlung.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDie sieben Bürden von Shaohao\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31103] = {title = "Die Ballade von Liu Lang", objective = "Bringt die \"Ballade von Liu Lang\" zu Lehrensucher Cho im Heim des Wissens.\n\nBereitgestellter Gegenstand: \n", description = "$p,\n\nendlich und dank Euer Hilfe haben wir die \"Ballade von Liu Lang\" aufarbeiten können.\n\nWenn Ihr uns im Heim des Wissens im Tal der Ewigen Blüten besuchen kommt, können wir diese Informationen Eurer Sammlung hinzufügen.\n\nVielen Dank für Eure Mühen!\n\nHerzliche Grüße,\n\nLehrensucher Cho", progress = nil, completion = "Die lange verloren geglaubte Geschichte von Lou Lang und seiner Wandernden Insel. Eine hervorragender Neuzugang für Eure Sammlung. Wenn ich etwas darüber sagen soll, dann zeigt einfach auf das entsprechende Buch in Eurer Privatsammlung.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDie Ballade von Liu Lang\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31104] = {title = "Der Ring des Herausforderers: Yalia Weisenwisper", objective = "Fordert Yalia Weisenwisper heraus und bezwingt sie im Ring des Herausforderers.", description = "Die Brüder und Schwestern bei den Shado-Pan flüstern noch immer hinter vorgehaltener Hand über Eure Heldentaten, <Name>.\n\nYalia hat sogar selbst Interesse an Euren Studien bekundet.\n\nSie wünscht, Euch im Ausbildungsring herauszufordern.\n\nIhr solltet sie nach Möglichkeit beeindrucken. Wenn Euch das gelingt, kann es durchaus sein, dass sie Euch in Zukunft helfen wird.", progress = nil, completion = "Ihr habt es geschafft! Ihr habt Yalia geschlagen!\n\nIhr habt ganz eindeutig ihre Gunst gewonnen, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31105] = {title = "Die Mogubedrohung", objective = "Tötet 12 Schlangenbinder oder Bestienmeister der Shan'ze.", description = "Unsere Späher haben Truppen der Mogu auf Shan'ze Dao im Nordwesten entdeckt.\n\nDie Insel ist angeblich unbewohnt, deshalb ist ihre Anwesenheit dort beunruhigend.\n\nNoch beunruhigender ist die Tatsache, dass sie unheimliche Experimente auf der Insel durchführen.\n\nIch brauche jemand Tüchtiges wie Euch, <Klasse>, um die Lage zu prüfen.\n\nDie Shan'ze werden Euch vermutlich Probleme bereiten. Wenn dieser Fall eintritt, tötet sie.", progress = nil, completion = "Die Shan'ze führen etwas im Schilde. Gut gemacht, &lt;Name&gt;, wir müssen aber weiter im Auge behalten, was sie machen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUnterwegs mit den Shado-Pan\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31106] = {title = "Die Mogubedrohung", objective = "Tötet 12 Schlangenbinder oder Bestienmeister der Shan'ze.", description = "Unsere Späher haben Truppen der Mogu auf Shan'ze Dao im Nordwesten entdeckt.\n\nDie Insel ist angeblich unbewohnt, deshalb ist ihre Anwesenheit dort beunruhigend.\n\nNoch beunruhigender ist die Tatsache, dass sie unheimliche Experimente auf der Insel durchführen.\n\nIch brauche jemand Tüchtiges wie Euch, <Klasse>, um die Lage zu prüfen.\n\nDie Shan'ze werden Euch vermutlich Probleme bereiten. Wenn dieser Fall eintritt, tötet sie.", progress = "Wie viele waren es?", completion = "Die Shan'ze führen etwas im Schilde. Gut gemacht, &lt;Name&gt;, wir müssen aber weiter im Auge behalten, was sie machen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUnterwegs mit den Shado-Pan\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31107] = {title = "Bürger eines neuen Reichs", objective = "Sammelt 10 Eier der Vor'thik in Kypari Vor.", description = "Auf Shek'zeers Befehl wurde der große Kyparibaum von Kypari Vor zu einem Totem des Schreckens verzerrt.\n\nGenau wie die vor dem Palast, wird auch das Gelege in der Nähe jetzt dazu verwendet, unsere Schwarmgeborenen zu verderben.\n\nBergt die Eier der Vor'thik, bevor sie verderbt werden. Wir werden sie hier ausbrüten. Sie werden die Bewohner eines neuen Reiches sein, frei vom Sha.", progress = "Kypari Vor war früher einmal schön. Reich an Bern und umgeben von erstklassigen Jagdrevieren.", completion = "Sie sind so groß. Sie werden bald ausschlüpfen.\n\nGut. Wir werden sie vielleicht brauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31108] = {title = "Konzentrierte Furcht", objective = "Sammelt 4 Schreckensbernfokusse von den Angstformern der Vor'thik in Kypari Vor.", description = "Bern ist Macht. Er bringt Leben.\n\nDieser... Schreckensbern, den Ihr mir gebracht habt, ist verderbt. Er ist konzentrierte Angst.\n\nDie Vor'thik wissen das sehr wohl. Ihr Kypari wurde vollständig vom Sha umhüllt und sie benutzen den Schreckensbern, um ihre eigenen Schwarmgeborenen zu beleben.\n\nBringt mir die Kristalle, die von den Angstformern der Vor'thik in ihren Ritualen verwendet werden. Die Klaxxi werden sie untersuchen und über die Art ihrer Entsorgung entscheiden.", progress = "Habt Ihr die Kristalle?", completion = "Ich frage mich, was wohl passieren würde, wenn Ihr einen davon essen würdet? Was würde er mit Eurem weichen, rosaroten Inneren anstellen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31109] = {title = "Die Vernichtung des Schwarms", objective = "Tötet 40 Mantis der Shek'zeer in den Gelegen von Shek'zeer. Bittet Kil'ruk den Windschnitter, Euch dort abzusetzen.", description = "Die Kaiserin sammelt weiter ihre Truppen. Wenn wir nicht eingreifen, werden sie die Mauer stürmen - selbst, wenn das bedeutet, sie unter den Leichen einer Million Schwarmgeborener zu begraben.\n\nLasst uns einen besseren Ort für diese Leichen finden.\n\nSagt Bescheid, wenn Ihr Euch zu den Gelegen aufmachen wollt - gerne werde ich Euch dort absetzen.", progress = nil, completion = "Das sollte vorläufig genügen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31110] = {title = "Durch das Portal", objective = "Sammelt 1000 Einheiten uraltes arkanes Pulver.", description = "Ach, genau <der/die:c> <Klasse>, <den/die:c> ich sehen wollte!\n\nEndlich haben wir herausgefunden, warum das Portal nicht funktioniert. Wir brauchen mehr arkanes Pulver!\n\nEine Lieferung hierher zu senden, würde Monate dauern, doch zum Glück tragen die Mogu auf dieser Insel jede Menge für ihre eigenen Zauber bei sich.\n\nSie verwenden normalerweise etwas älteres Material, also werden wir viel davon brauchen.", progress = "Habt Ihr das Pulver gefunden?", completion = "Ausgezeichnet! Hervorragend!\n\nDas ist genau das richtige Zeug, &lt;Name&gt;.\n\nWir machen uns gleich an die Arbeit. Ich habe keinerlei Zweifel daran, dass wir bald soweit sein werden.", rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31111] = {title = "Die Zan'thik auslöschen", objective = "Tötet 6 Pfähler der Zan'thik und 6 Manipulatoren der Zan'thik in Zan'vess.", description = "Die Krieger von Zan'vess gehören zu den am meisten gefürchteten und respektierten im ganzen Reich und das aus gutem Grund.\n\nPfähler sind unübertroffen in ihrer Meisterschaft des Speeres - zweifellos hat Malik zu seiner Zeit mit den Zan'thik trainiert. Ihre Manipulatoren befehlen über schreckliche Schallkräfte mit der Leichtigkeit und der Zartheit eines Atemzugs.\n\nSie beide müssen erledigt werden.", progress = nil, completion = "Ich gebe zu, Erwecker, ich bin beeindruckt.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31112] = {title = "Sie sind so dornig!", objective = "Sammelt 5 Notvorräte von den Wassergeistern.", description = "Einst war diese Kiste voller Vorräte, doch sie wurde vollständig geplündert.\n\nEine kurze Überprüfung des Gebiets offenbart Spuren der Diebe. Eisige Dornen, genau wie die der Wassergeister an der Küste im Osten.\n\nFür Eure Gruppe Überlebender ist dies eine Situation auf Leben und Tod. Die Vorräte müssen von den diebischen Plagen geborgen und zurück ins Lager gebracht werden.", progress = "Habt Ihr die Vorräte zurückerlangen können, Kumpel?", completion = "Sieh mal einer an!\n\nDiese Vorräte sollten unser Überleben für ein paar Tage mehr sichern.\n\nIhr habt's geschafft, sie nicht in die Luft zu jagen. Sehr gut, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31113] = {title = "Streitlager Gai-Cho angreifen", objective = "Tötet 16 Yaungol, Erdsprecher oder Pechschleuderer von Gai-Cho.", description = "Die Yaungol sind immer ein Ärgernis, aber die Gruppe aus dem Streitlager Gai-Cho im Nordosten hat sich unlängst für einen Übergriff auf den Kun-Lai mit den Yaungol von Osul verschworen.\n\nEin solcher Übergriff darf nicht ungestraft bleiben.\n\nGeht hin und greift das Streitlager Gai-Cho an. Wir müssen sicherstellen, dass sie beschäftig sind, damit sie sich nicht neu formieren können, um das Ochsentor noch einmal anzugreifen.", progress = nil, completion = "Nun - das sollte sie eine Zeit lang vor weiteren Angriffen abschrecken. Gute Arbeit, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLaunch Capper Quest\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31114] = {title = "Angriff auf das Plateau des Totensprechers", objective = "Tötet 8 Leichenschänder des Totensprechers und 1 Zermalmer des Totensprechers.", description = "Wir haben die Totensprecher immer in Ruhe gelassen. So lange waren sie lediglich dafür verantwortlich, die geheiligten Grabstätten der Yaungolstämme zu pflegen.\n\nJetzt jedoch haben sie sich der dunklen Magie verschrieben und schänden die Gebeine ihrer einstigen Klanbrüder... \n\nIch weiß weder, wo sie diese dunkle Magie erlernt haben noch warum sie ihren Toten auf einmal den Respekt verweigern – und es fehlt uns die Zeit, es herauszufinden. \n\nWir müssen sie aufhalten.", progress = "Habt Ihr die Totensprecher besiegt?", completion = "Weil sich die Totensprecher in der Verwendung dieser dunklen Magie verschworen haben, haben sie ihr Recht auf Protektion verwirkt. Ich hoffe, dass Eure Taten sie von ihrem eingeschlagenen Pfad abbringen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLaunch Capper Quest\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31116] = {title = "Geisterstaub", objective = "Bringt 8 Geister zur ihren sterblichen Überresten auf dem Plateau des Totensprechers zurück.", description = "Die Geister, die die Yaungol von den sterblichen Überresten ihrer Vorfahren einfangen, enthalten immer noch etwas von ihrer Lebensessenz.\n\nWenn Ihr die Geister im Kampf besiegt, könnt Ihr diese Essenz in Form von Staub einsammeln und dann zu ihren Leichen zurückbringen, was sie endlich ins nächste Leben entsenden wird.\n\nNur so können die Taten der Totensprecher wiedergutgemacht werden. Außerdem ist es gut für unsere Sicherheit.", progress = "Wurden die Geister zur letzten Ruhe gebettet?", completion = "Sehr gut, Ihr habt bei der Wiedergutmachung dieses schrecklichen Fehlers geholfen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLaunch Capper Quest\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31117] = {title = "Uruk!", objective = "Tötet Uruk auf dem Plateau des Totensprechers in der Tonlongsteppe.", description = "Uruk ist der Totensprecher der Yaungol von Tonlong. Eure Mission ist erst dann komplett abgeschlossen, wenn Ihr ihn besiegt habt. Legt los!", progress = nil, completion = "Uruk ist tot! Diese Bedrohung sind wir los, zumindest für heute. Vielen Dank, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31118] = {title = "Die Schrift der Totensprecher", objective = "Nehmt den Yaungol auf dem Plateau des Totensprechers eine Schriftrolle der Blutbindungsriten ab.", description = "Wir müssen herausfinden, was mit den Totensprechern passiert ist.\n\nSchon seit so vielen Jahren bestand ihre Aufgabe lediglich darin, die Grabstätten zu pflegen und für die Begräbnisse der gefallenen Soldaten zu sorgen.\n\nDoch bei einem kürzlich stattgefundenen Schlachtzug haben wir eine Schrifttafel entdeckt, die in einer Art und Weise verschlüsselt ist, wie wir es noch nie zuvor gesehen haben. Wenn Ihr eine verschlüsselte Schriftrolle von einem der Totensprecher besorgt, können wir beginnen, den Schlüssel zusammenzusetzen und nachzuvollziehen, was geschehen ist.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLaunch Capper Quest\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31119] = {title = "Der Feind meines Feindes... ist immer noch mein Feind!", objective = "Benutzt hochexplosive Fässer voll Yaungolöl, um damit 100 Mantis oder Yaungol auf dem Schlachtfeld von Gai-Cho zu töten.", description = "Die Mantis sind unsere Feinde. Genau wie die Yaungol von Gai-Cho.\n\nEin Glück, dass die beiden auch miteinander verfeindet sind. Mantis aus Kri'vess greifen ständig Gai-Cho-Yaungol an, die diese wiederum an ihren Vordertoren aufhalten.\n\nIch möchte, dass Ihr Chaos stiftet. \"Borgt\" Euch in Gai-Cho ein paar hochexplosive Ölfässer und werft sie aus der Luft auf das Schlachtfeld.\n\nMir ist egal, wen Ihr umbringt, solange Ihr dafür sorgt, dass es viele sind.", progress = nil, completion = "Ha! Gute Arbeit. Das wird beide lehren, sich mit den Shado-Pan anzulegen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLaunch Capper Quest\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31120] = {title = "Cheng Bo!", objective = "Tötet Cheng Bo im Streitlager Gai-Cho in der Tonlongsteppe.", description = "Cheng Bo ist der Kriegshetzer des Streitlagers Gai-Cho. Einen Dämpfer habt Ihr ihrem Betrieb bereits verpasst - jetzt habt Ihr Gelegenheit, ihnen einen wirklich heftigen Schlag zu versetzen. \n\nTötet den Kriegshetzer!", progress = "Wie läuft der Angriff?", completion = "Jetzt, da Cheng Bo überwältigt ist, können wir unsere Anstrengungen wieder voll auf unsere anderen Feinde konzentrieren. Eure Leistungen verdienen Respekt, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31121] = {title = "Bleibt ein Weilchen und hört zu", objective = "Trinkt aus Chos Teekanne.", description = "Schnell, schnell, schnell - ist Euer Volk immer so in Eile?\n\nSetzt Euch und trinkt einen Tee mit mir, dann können wir Euer Problem besprechen.\n\n<Lehrensucher Chos Lippen verziehen sich zu einem geduldigen Lächeln.>", progress = "Ich hoffe, ich habe Euch nicht gelangweilt, Reisender.", completion = "Ich werde Euch helfen, Reisender, aber zunächst erzählt mir etwas über diese Horde...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31127] = {title = "Der Ring des Herausforderers: Chao die Stimme", objective = "Fordert Chao die Stimme heraus und besiegt sie anschließend im Kampf in der Shado-Pan-Garnison in der Tonlongsteppe.", description = "Ihr scheint mir ja <ein echter Kämpfer/eine echte Kämpferin> zu sein, $p.\n\nChao hat schon davon gehört und redet davon, wie sie Euch den Hin...\n\nSagen wir einfach, ich glaube, Ihr solltet sie herausfordern und ihren Respekt erlangen.", progress = nil, completion = "Ich bin mir sicher, dass sie Euch das nicht übel nimmt. Sie hat einfach eine Schwäche für gute Kämpfe.\n\nIhr solltet Euch mit Ihr unterhalten, wenn ich das nächste Mal ein paar Missionen für Euch habe. Wie Ihr bestimmt erkannt habt, ist sie ist eine ziemlich fähige Kämpferin.", rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31128] = {title = "Der Ring des Herausforderers: Lao-Chen der eiserne Bauch", objective = "Fordert Lao-Chen den eisernen Bauch heraus und besiegt ihn anschließend im Kampf in der Shado-Pan-Garnison in der Tonlongsteppe.", description = "Lao-Chen scheint völlig abgehoben zu sein... oder vielmehr in seinem Bier versunken.\n\nSeit seinen letzten Kämpfen scheint er völlig davon besessen zu sein, das perfekte Gebräu für den Kampf zu entwickeln.\n\nDas ist ja alles gut und schön, wir brauchen ihn aber als Kämpfer!\n\nIhr solltet ihn zum Kampf herausfordern, vielleicht könnt Ihr ihn damit aufrütteln. \n\nWenn Ihr ihn besiegt, will er vermutlich losziehen und sich am Kampf beteiligen, nur um Euch zu übertreffen!", progress = nil, completion = "Wow, Ihr müsst Lao-Chen beeindruckt haben. Er redet von nichts anderem als davon, wie er sich darauf freut, aufzubrechen und mit Euch zu kämpfen. Gute Arbeit.", rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31129] = {title = "Das Schicksal der Sturmbräus", objective = "Fragt die Bewohner des Abendlichtbraugartens, ob sie Sturmbräus gesehen haben.", description = "$p! Schön, Euch wohlbehalten und so weitgereist zu sehen. Wie es scheint, sind unsere Wege ziemlich eng miteinander verflochten.\n\nIch bin hier, um nach meiner Familie zu suchen. Man hat mir gesagt, dass mehrere Sturmbräus die Mauer überquert haben, um bei der Bekämpfung der Mantis zu helfen. Ich will sie finden und mich ihnen anschließen.\n\nIst Euch jemand mit dem Namen Sturmbräu begegnet, der hier durchgekommen ist? Würde es Euch etwas ausmachen, mir beim Herumfragen zu helfen?", progress = nil, completion = "&lt;Chen hört aufmerksam zu.&gt;\n\nDer Dicke Dan, Han, Evie und Mama. Ich verstehe.\n\nSieht so aus, als wäre Dan hier in Sicherheit. Ich werde mich auf die Suche nach Evie, Han und Mama Sturmbräu machen.\n\nMacht's gut, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nChen Sturmbräu beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31130] = {title = "Ein Besuch bei Lehrensucher Cho", objective = "Freundet Euch mit Lehrensucher Cho an, indem Ihr ihm Aufgaben abnehmt: Stutzt seinen Baum, streicht seine Mauer und füttert seine Vögel.", description = "<Fremder/Fremde>, ich kann Euch vielleicht helfen, Euren Prinz zu finden. Aber erst wüsste ich gern noch ein wenig mehr über Euch und Euer Volk.\n\nHelft mir mit meinen Aufgaben und wir können ein wenig reden.\n\nIhr seht vielleicht aus wie <ein Kriegsveteran/eine Kriegsveteranin>, aber Ihr habt doch bestimmt ein paar Minuten übrig, um einem Bücherwurm wie mir bei der Hausarbeit zu helfen, oder?", progress = "Es geht doch nichts über ein wenig Handarbeit, um aus Fremden Freunde zu machen, denkt Ihr nicht auch?", completion = "Trotz all Eurer Jahre des Kampfes habt Ihr noch immer ein Auge fürs Schöne, &lt;Name&gt;. Das gefällt mir!\n\nJetzt lasst uns Euren verschwundenen Prinzen finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31131] = {title = "Weißblütensee", objective = "Sprecht mit Hee Samtfuß am Weißblütensee.", description = "Laut der Berichte ist heute alles ruhig am Weißblütensee. Aber ich habe trotzdem Ren Feuerzunge und Hee Samtfuß dorthin geschickt, damit es so bleibt.\n\nWenn Ihr weiter helfen möchtet, dann begebt Euch auf die Westseite des Sees und trefft Euch mit Hee. Helft ihm dabei, die Gegend zu sichern und vor allen Bedrohungen zu schützen.", progress = nil, completion = "&lt;Hee Samtfuß lächelt, als Ihr Euch ihm nähert.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31132] = {title = "In meine Situation versetzen", objective = "Sprecht mit Lehrensucher Cho am Ring der Knochen.", description = "Oh, was ist nur mit meinen Manieren? Ich bin ja hier der Gastgeber.\n\nErlaubt mir, Euch ein wenig über mich selbst und mein Volk zu berichten, bevor ich Euch Fragen stelle.", progress = nil, completion = "Die beste Art, Euch zu erklären, was es mit einem Lehrensucher auf sich hat, ist wahrscheinlich, es Euch zu zeigen...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31133] = {title = "Aggressive Kor'thik", objective = "Tötet 17 Kor'thik-Mantis in Kor'vess.", description = "Ich bin kein Brauer - der schiere Anblick dieser Zutatenberge macht mich schwindelig. Stellt das Bier einfach vor mich hin, wenn es fertig ist.\n\nNein, ich bin hier, um dafür zu sorgen, dass die Brauer nicht in Stücke geschnitten werden, während sie versuchen, das perfekte Bier zu brauen. Das ist keine einfache Aufgabe.\n\nDie Kor'thik-Mantis auf der anderen Seite dieses Beckens greifen uns Nacht für Nacht an. Falls Ihr ohnehin in diese Richtung geht, warum revanchiert Ihr Euch nicht und attackiert ein paar von ihnen?", progress = nil, completion = "Ihr würdet eine gute Biergartenwache abgeben, &lt;Volk&gt;. Meldet Euch bei mir, falls Euch diese ganze \"&lt;Klasse&gt;\"-Geschichte jemals zum Hals raushängen sollte.", rewards = "Satinkapuze des SonnenuntergangsBalghelm des SonnenuntergangsVerdorrte HolzkappeBrünierte Kopfbedeckung des SonnenuntergangsSeidene Gugel des SonnenuntergangsLederhelm des SonnenuntergangsWindschnitterkopfschutzSchwerer Helm des SonnenuntergangsGepanzerter Helm des SonnenuntergangsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31134] = {title = "Wenn diese Steine sprechen könnten", objective = "Nutzt die Steinmonolithen am Ring der Knochen.", description = "Dies ist ein sehr, sehr alter Ort, <Reisender/Reisende>.\n\nErst vor kurzem habe ich eine Methode entwickeln können, mit der die vergessene Sprache, die in diese Steine gemeißelt wurde, übersetzt werden kann.\n\nOh, Entdeckungen sind immer so aufregend! Glaubt mir, ich kriege nie genug davon.\n\nIhr seid der Gast, bitte, erweist mir die Ehre und tretet vor. Ich bestehe darauf.\n\nNutzt diesen Schlüssel, um den Steinen ihre Geheimnisse zu entlocken.", progress = "Eure Hilfe ist mir sehr willkommen, Reisender.", completion = "Ich glaube, wir haben für einen Tag genug übersetzt.\n\nDie Erfahrung war hoffentlich aufschlussreich für Euch.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31135] = {title = "Die Zukunft von Gnomeregan", objective = "Trefft Euch mit Xi, Freundin der Winzlinge, in Neu-Tüftlerstadt.", description = "Jeder Überlebende, den wir aus den vergifteten Hallen von Gnomeregan befreien können, ist wie ein Sieg für uns. Kämpfer wie Ihr werden eine wichtige Rolle bei der Zukunft von Gnomeregan spielen, <Klasse>. Aus diesem Grund hat unser Herrscher, Hochtüftler Mekkadrill, ein Team von Lehrern zusammengestellt, die Euch helfen werden, Eure Künste zu erlernen.\n\nXi, Freundin der Winzlinge, kommt aus einem weit entfernten Land zu uns und Euch ausbilden und Euch helfen, Euch an ein Leben an der Oberfläche zu gewöhnen. Sie erwartet Euch auf dem kleinen Übungsfeld auf der anderen Straßenseite.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31136] = {title = "Hinter den eigenen Linien", objective = "Tötet General Temuja.", description = "Die Späher berichten, dass ein Imperion unsere Linien im Süden durchbrochen haben soll und sich jetzt auf der Straße im östlichen Tal befindet.\n\nIch brauche jemanden, der ihn umgehend aufhalten kann. Bitte findet und tötet ihn so schnell wie möglich, <Name>.", progress = nil, completion = "Gute Arbeit. Ich hoffe, dass wir uns wieder einmal auf Euch verlassen können.", rewards = "Ihr bekommt:\n\nSchätze des TalsTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31137] = {title = "Der Hochtüftler", objective = "Stellt Euch bei Hochtüftler Mekkadrill in Neu-Tüftlerstadt vor.", description = "Ich weiß nicht, ob Ihr Euch an Mekkadrill erinnert. Nevin und die anderen Gnome haben mir gesagt, dass Gedächtnisverluste bei den Überlebenden von Gnomeregan sehr häufig vorkommen.\n\nHochtüftler Mekkadrill ist der Anführer aller Gnome. Er hat es sich zur Gewohnheit gemacht, jeden geretteten Überlebenden persönlich kennenzulernen. Ihr solltet Euch ihm vorstellen. Er befindet sich bei seinem Kriegsrat in dem Zelt mitten in der Stadt.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][31138] = {title = "Die Künste eines Mönchs", objective = "Ihr müsst Stufe 3 erreichen, um Tigerklaue zu erlernen. Wenn Ihr sie gelernt habt, wendet sie zweimal auf eine Trainingsattrappe in Neu-Tüftlerstadt an.", description = "Wenn Ihr kämpft, werdet Ihr bessere Fähigkeiten erhalten. Mit wachsenden Fähigkeiten werdet Ihr neue Techniken erlernen. Zieht los, seht Euch um, lernt und zeigt mir, was Ihr herausgefunden habt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nElektrostab"}
MultiLanguageQuestData['de'][31139] = {title = "Schlagt sie zurück!", objective = "Tötet 6 Kampfworgs des Schwarzfels.", description = "Ihr seid also der neue Rekrut aus Sturmwind, wie? Ich bin Marschall McBride, Kommandant dieser Garnison. Ich bin froh, Euch an Bord zu haben...\n\n<McBride sieht ein paar Zettel durch.>\n\n<Name>. Ihr seid <Name>, ja?\n\nIhr seid genau zur rechten Zeit gekommen. Die Schwarzfelsorcs haben es geschafft, sich durch einen Spalt im Felsen in den Nordhain einzuschleichen. Meine Soldaten tun ihr Bestes, sie zurückzuschlagen, aber ich fürchte, sie werden bald übermannt werden.\n\nBegebt Euch nach Nordwesten in den Wald und tötet die angreifenden Schwarzfelsworgs! Helft meinen Soldaten!", progress = "Habt Ihr die Kampfworgs des Schwarzfels zurückgeschlagen?", completion = "Ihr habt uns ein wenig Zeit verschafft, &lt;Name&gt;, aber wir haben jetzt ein noch größeres Problem, um das wir uns kümmern müssen.", rewards = "Ihr bekommt:\n\nLäuferstiefel"}
MultiLanguageQuestData['de'][31140] = {title = "Worgs im Schafspelz", objective = "Tötet 8 Spione der Schwarzfelsorcs.", description = "Die einfallenden Orcs sind keine Narren. Sie schätzen uns ab, stellen sicher, dass ihre Angriffe zu ihrem Vorteil sein werden.\n\nIm Wald nordwestlich von hier lauern Spione der Schwarzfelsorcs. Sie kundschaften uns mit ihren Handfernrohren aus, überwachen jeden unserer Schritte - und warten. Ich will, dass Ihr sie angreift!\n\nTötet die Spione der Schwarzfelsorcs! Wir müssen ihnen zeigen, dass wir sehr wohl wissen, dass sie uns beobachten und dass wir vorbereitet sind!", progress = nil, completion = "Hervorragende Arbeit, &lt;Name&gt;. Es hat sich herausgestellt, dass Ihr ein echter Gewinn für die Garnison seid. Es wird Zeit für Eure Ausbildung!", rewards = "Ihr bekommt:\n\nBeine des Meisterspions"}
MultiLanguageQuestData['de'][31141] = {title = "Kalligrafiebrief", objective = "Lest den Kalligrafiebrief und sprecht mit Bao in der Abtei von Nordhain.", description = "Ich wurde darum gebeten, Euch hierauf aufmerksam zu machen, sobald Ihr mit den Schwarzfelsspionen fertiggeworden seid, <Name>. Es scheint sich um einen versiegelten Brief mit den Insignien von Bao zu handeln, einem Pandaren, der aus einem weitentfernten Land zu uns gekommen ist. Ich würde nicht zögern, ihn zu lesen, bevor Ihr irgendwelchen anderen Geschäften hier in der Abtei nachgeht.", progress = "Ah, Ihr habt meinen Brief erhalten, <Name>... gut.\n\nIch bin von weit her gekommen, um Eurem Volk in den Lehren der Mönche zu unterrichten.", completion = "Ich bin von weit her gekommen, um die Gebräuche Eures Volkes zu erlernen. Zögert nicht, zu mir zu kommen, damit ich unterweisen kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31142] = {title = "Tigerklaue", objective = "Erreicht Stufe 3, um 'Tigerklaue' zu erlernen. Dann übt die Anwendung von 'Tigerklaue' an einer Trainingsattrappe südlich des Eingangs zur Abtei von Nordhain.", description = "Jetzt, da Ihr Gelegenheit hattet, Eure Fähigkeiten im Kampf zu erproben, wird es Zeit, Euch noch einen Grund vorzustellen, warum das Üben so wichtig ist.\n\nWenn Ihr nämlich mehr Erfahrung sammelt, könnt Ihr bald Techniken beherrschen, die Ihr Euch jetzt nicht zutrauen würdet.\n\nAlso macht Euch auf und sammelt noch etwas mehr Erfahrung. Erlernt eine neue Fähigkeit und zeigt sie mir an einer der Trainingsattrappen.", progress = nil, completion = "Ihr lernt schnell, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31143] = {title = "Stürzt Euch in die Schlacht!", objective = "Meldet Euch bei Stellvertreter Willem hinter der Abtei von Nordhain im Wald von Elwynn.", description = "Während Ihr unterwegs wart, um zu trainieren, habe ich eine dringliche Nachricht von Stellvertreter Willem erhalten. Wie sich herausstellt, haben die Schwarzfelsorcs goblinische Auftragsmörder angeheuert. Sie haben unser Bataillon hinter der Abtei aus dem Hinterhalt angegriffen. Willem bat mich, ihm einen Helden zu schicken. Ihr müsst ihnen helfen, <Name>!\n\nFindet Stellvertreter Willem nördlich der Abtei am Kommandozelt. Geht!", progress = nil, completion = "Es stimmt, man hat uns aus dem Hinterhalt angegriffen. Ich wage es nicht, noch weitere Soldaten dort hinauszuschicken und zu riskieren, sie auch noch zu verlieren. Ich brauche einen Freiwilligen. Jemanden, der bereit ist, sein Leben zu riskieren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31144] = {title = "Sie haben Auftragsmörder losgeschickt", objective = "Tötet 8 goblinische Auftragsmörder.", description = "Habt Ihr jemals einen Goblin gesehen, <Name>? Diese jämmerlichen, kleinen, grünhäutigen Monster mögen nur zwei Dinge: Gold und sich selbst.\n\nDie Schwarzfelsorcs haben sich goblinische Auftragsmörder zu Hilfe geholt, die unsere Soldaten töten sollen. Wenn Ihr zum Feld im Norden blickt, könnt Ihr schwach ihre Umrisse erkennen, wie sie im Gras umherschleichen.\n\nIhr müsst Euch dort hinbegeben und jeden Goblin töten, den Ihr zu Gesicht bekommt. Sie müssen kapieren, dass man sich nicht mit der Allianz anlegt!", progress = nil, completion = "Ihr habt diesen Monstern eine Lektion erteilt! Sie werden es sich zweimal überlegen, bevor sie noch einen Mordauftrag der Orcs annehmen.", rewards = "Ihr bekommt:\n\nAusstattergürtel"}
MultiLanguageQuestData['de'][31145] = {title = "Gefahr gebannt", objective = "Meldet Euch bei Marschall McBride vor der Abtei von Nordhain im Wald von Elwynn.", description = "Ausgezeichnete Arbeit, <Name>! Sie werden uns definitiv nicht mehr in den Rücken fallen. Wir kümmern uns um die Nachzügler. Ich will, dass Ihr zurück zu Marschall McBride geht, der südlich von hier vor der Abtei von Nordhain steht. Lasst ihn wissen, dass die Situation mit den Goblins unter Kontrolle ist.\n\nLebt wohl, <Klasse>.", progress = nil, completion = "Dank Eurer Hilfe ist es uns gelungen, die nördlichen und westlichen Abschnitte von Nordhain zu sichern. Dennoch gibt es im Osten noch immer eine ziemlich große Ansammlung von Schwarzfeslorcs und sie haben damit begonnen, den Wald niederzubrennen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31146] = {title = "Bekritzelte Schriftrolle", objective = "Lest die elegante Schriftrolle und sprecht mit Ting der Bauchstarken in Todesend.", description = "Ach ja, während Ihr unterwegs wart, um Euch um die hirnlose Geißel zu kümmern, kam diese Schriftrolle für Euch an. Der Pandarenbesucher, Ting, hat sie geschickt. Vielleicht können Mönche solchen Müll entziffern, ich kann das nicht. Ihr solltet mit ihr sprechen. Sie ist im Gasthaus, auf der anderen Seite der Straße.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31147] = {title = "Tigerklaue", objective = "Erreicht Stufe 3, um 'Tigerklaue' zu erlernen und übt die Fähigkeit an einer Trainingsattrappe.", description = "Wenn Ihr auf Eurem Weg, der inneren und äußeren Anforderungen Herr zu werden, große Herausforderungen meistert, werdet Ihr neue, tief in Euch verborgene Fähigkeiten entdecken. Geht jetzt und macht Euch selbst zum Meister. Entdeckt die Technik der Tigerklaue. Geht dann und übt sie an einer Trainingsattrappe.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31148] = {title = "Novizin Elreth", objective = "Sprecht mit Novizin Elreth in Todesend in Tirisfal.Ach, bevor ich gehe - Ihr solltet mit Novizin Elreth sprechen. Sie hat Arbeit für Euch, und es wäre gut für Euch, wenn Ihr anderen helft und Eure Fähigkeiten verbessert.\n\nWenn Ihr mich das nächste Mal sucht, findet Ihr mich in Unterstadt.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ach, bevor ich gehe - Ihr solltet mit Novizin Elreth sprechen. Sie hat Arbeit für Euch, und es wäre gut für Euch, wenn Ihr anderen helft und Eure Fähigkeiten verbessert.\n\nWenn Ihr mich das nächste Mal sucht, findet Ihr mich in Unterstadt.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][31150] = {title = "Elegante Rune", objective = "Lest die elegante Rune und sprecht mit Lo im Eisklammtal.", description = "<Name>, diese Rune wurde mir gegeben, damit ich sie an Euch weiterreiche. Nehmt Euch einen Moment Zeit, sie bei Gelegenheit zu lesen. Ich denke mal, sie kommt von unserem weit gereisten Besucher Lo. Werft doch am besten einen Blick darauf und sucht ihn in Ambossar auf.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31151] = {title = "Treten & Schlagen - nur eine Frage der Konzentration", objective = "Erreicht Stufe 3, um die Technik Tigerklaue zu erlernen und übt dann diese Fähigkeit an einer der Trainingsattrappen vor dem Eingang nach Ambossar.", description = "Die Wahrheit ist, dass Ihr bereits über das Talent und die Fähigkeiten verfügt, um alle notwendigen Dinge zu erlernen. Ich kann Euch nur den Weg zu diesem Wissen weisen.\n\nZunächst einmal müsst Ihr üben, bis Ihr eine neue Technik zu verstehen beginnt. Die erste Technik, die Ihr lernen werdet, ist die Tigerklaue. Also zieht los, lernt weiter, bis Ihr Euer ganzes Potenzial entdeckt habt und dann übt Eure neue Technik!\n\nUnd denkt daran: Es ist alles nur eine Frage der Konzentration!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31152] = {title = "Ein Blick in die Vergangenheit", objective = "Sprecht mit Lehrensucher Cho am Ring der Steine.", description = "Gleich, gleich. Lasst mich meine Sachen zusammensammeln.\n\nWollen doch nicht, dass ich jetzt meine Aufzeichnungen verliere, oder? Ganz besonders nicht, nachdem Ihr für sie Euer Leben riskiert habt!\n\nGut, fertig. Lasst uns aufbrechen.\n\nIch muss schon sagen, dass es sich viel sicherer anfühlt, gemeinsam mit Euch zu reisen, so, wie Ihr mit diesem Saurok umgegangen seid!", progress = nil, completion = "Ich bin meinen Vorfahren für das Wissen, das sie an mich weitergegeben haben, sehr dankbar.\n\nIch stehe auf ihren Schultern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31156] = {title = "Kalligrafiepergament", objective = "Lest das Kalligrafiepergament und sprecht mit Gato im Tal der Prüfungen.", description = "Ah, während Ihr weg wart, ist ein Pergament für Euch gekommen, <Name>.\n\nLest es, wenn Ihr die Zeit habt. Wenn ich mich nicht irre, kommt es von unserem Pandarenfreund, Gato. Er ist von weit entfernt zu uns gekommen und gewährt uns die Ehre seiner Weisheit und die Ausbildung als Mönch. Macht Eurem Volk keine Schande, indem Ihr bei seinen Lektionen versagt!", progress = "Ahh, Ihr seid gekommen.", completion = "Wir werden unseren jeweiligen Völkern Ehre erweisen, indem wir voneinander lernen. Ihr werdet ein großer &lt;Klasse&gt; werden, wenn ich irgendetwas zu sagen habe. Und ich werde die Gepflogenheiten Eures Volkes kennenlernen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31157] = {title = "Tigerklaue", objective = "Erreicht Stufe 3, um 'Tigerklaue' zu erlernen. Findet eine Trainingsattrappe und übt daran 2-mal die Anwendung von 'Tigerklaue'.", description = "Während Ihr den Weg Eurer Ausbildung beschreitet, werdet Ihr feststellen, dass Ihr in Euch die Macht tragt, neue Techniken zu erlernen. Ihr müsst sie noch nicht einmal von mir oder einem erfahreneren Mönch - Ihr werdet sehen, dass Ihr sie ganz alleine in Euch findet.\n\nGeht und übt Euch in den Grundlagen. Sammelt mehr Erfahrung und entwickelt eine neue Technik - sobald es soweit ist, könnt Ihr sie an einer Trainingsattrappe üben.", progress = nil, completion = "Gut, gut, Eure erste Herausforderung habt Ihr gemeistert. Wir werden viel voneinander lernen, das sehe ich.", rewards = "Ihr bekommt:\n\nTigerhandwickel"}
MultiLanguageQuestData['de'][31158] = {title = "Die Grundlagen: Dinge schlagen", objective = "Zerstört 6 Tikiziele.", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr auch versteht, wie Ihr die Waffe zu schwingen habt, mit der Ihr da rumfuchtelt.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", progress = nil, completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Schwüngen... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31159] = {title = "Aufstieg der Dunkelspeere", objective = "Trefft Zabrax auf dem Ausbildungsgelände der Dunkelspeere.", description = "Die Trolle des Dunkelspeerstamms war'n lange Zeit Opfer. Ausgestoßene. Immer wieder musst'n wir flieh'n und unser Zuhause verlass'n. Aber diesmal hat uns nich' die Flucht hierher getrieb'n.\n\nVol'jin hat uns Führung durch Weisheit angeboten und das hat uns bisher am Leben erhalt'n. Nun bietet uns diese Weisheit Vorzeich'n einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal flieh'n wir nicht. Diesmal kämpf'n wir für ein Zuhause, das besteh'n bleibt.\n\nEs ist Zeit, mit der Ausbildung zu beginnen, <Name>. Sprecht mit Zabrax im Osten.", progress = nil, completion = "Noch so ein Jungblut, wie?\n\nObwohl, Ihr seht aus, als wärt Ihr gut in Form. Ruhige Hände. Scharfe Augen. Vielleicht wird aus Euch noch ein echter &lt;Klasse&gt;.\n\nLasst uns keine Zeit mehr verschwenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31160] = {title = "Aller Anfang ist schwer", objective = "Sammelt 6 Felle einer Wildmähnenkatze.", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Mädel. Die geben sicher 'n paar mächtige Mäntel ab.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31161] = {title = "Grube der Bewährung", objective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", description = "Ihr habt Euch ganz schön gemausert, <Klasse>. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", progress = "Jeder Troll muss sich beweisen, bevor er das Trainingsgelände verlassen darf.", completion = "Ihr seid sehr gut in Form. Eines Tages werdet Ihr sehr mächtig sein.", rewards = "Ihr bekommt:\n\nMönchsstab der Dunkelspeere"}
MultiLanguageQuestData['de'][31162] = {title = "Die Künste eines Mönchs", objective = "Ihr müsst Stufe 3 erreichen, um Tigerklaue zu erlernen. Übt, indem Ihr die Tigerklaue gegen ein Tikiziel einsetzt.", description = "Wenn Ihr besser kämpfen lernt, findet Ihr Sachen heraus, an die Ihr vorher nie gedacht hättet.\n\nWollt Ihr es sehen? Los, trainiert fleißig und lernt etwas Neues.\n\nKommt dann wieder und zeigt es mir.", progress = nil, completion = "Gute Arbeit, Mann! Das schien Euch ja wirklich leicht zu fallen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31163] = {title = "Mehr als erwartet", objective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", progress = nil, completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31165] = {title = "Kalligrafienotiz", objective = "Lest die Kalligrafienotiz und sprecht mit Shoyu im Camp Narache.", description = "Gerade eben fragte eine Botin nach Euch, <Name>. Ich glaube, sie wurde von unserem Pandarengast, Shoyu, geschickt. Wenn dem so ist, würde ich sie schnellstens lesen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31166] = {title = "Tigerklaue", objective = "Ihr müsst Stufe 3 erreichen, um Tigerklaue zu erlernen. Sucht eine Trainingsattrappe in Camp Narache und übt daran.", description = "Bis jetzt habt Ihr Euch wacker geschlagen. Je weiter Euer Weg Euch führt, desto stärker werdet Ihr. Ihr erlernt dann Techniken, von denen Ihr zuvor nicht einmal zu träumen gewagt habt.\n\nEure erste Lektion wird die Macht der Erfahrung sein. Geht, erlernt eine neue Fähigkeit und führt sie mir dann vor.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31167] = {title = "Stammbaum", objective = "Zündet das Räucherwerk am Ring der Steine an.", description = "Nun wisst Ihr also Bescheid, <Reisender/Reisende>, oder zumindest wisst Ihr so viel, wie für eine vernünftige Vorstellung notwendig ist.\n\nUnd wie steht es um Euch? Unterscheidet sich Euer Volk tatsächlich so sehr von dem meinen?\n\nEs muss doch ganz bestimmt Dinge geben, die uns gemein sind. Schauen wir doch mal...", progress = "Ein wunderschöner Tag, findet Ihr nicht?", completion = "Doch nicht so unterschiedlich, Ihr und ich.\n\nIch glaube, dass wir gute Freunde werden können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31168] = {title = "Kalligrafiesiegel", objective = "Sprecht mit Laoxi in Aldrassil im Laubschattental.", description = "Dieses Siegelzeichen wurde mir durch einen Boten von unserem Pandarengast, Laoxi, überreicht. Es sieht so aus, als wollte er ein paar Worte mit Euch wechseln, wenn Ihr Zeit habt. Lest es und bringt es dann zu ihr.", progress = "Ah, Ihr seid gekommen. Gut.\n\nIch lerne so viel - Euer Volk verfügt über einen Schatz an Wissen, der mit nichts vergleichbar ist, was ich bisher gesehen habe. So klein ich mich im Angesicht dieses Umstands auch fühle, so sehr hoffe ich doch, dass auch ich Euch etwas lehren kann.", completion = "Man hat mich gewarnt, dass nicht alle Eures Volkes Fremde willkommen heißen würden, doch habe ich festgestellt, dass das Gegenteil wahr ist - man hat mich nicht nur aufgenommen, ich durfte auch so viel von Euch lernen.\n\nIhr macht einen vielversprechenden Eindruck als junger &lt;Klasse&gt; und ich hoffe, dass ich Euch viel von unseren Gebräuchen beibringen kann, so wie Euer Volk mich so viel über ihre gelehrt hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31169] = {title = "Die Kunst der Mönche", objective = "Ihr müsst Stufe 3 erreichen, um Tigerklaue zu erlernen. Sucht nach einer Trainingsattrappe und übt daran die Anwendung von Tigerklaue.", description = "Das wahre Geheimnis des Mönchs besteht darin, das Wissen und die Macht freizusetzen, die in einem selbst schlummern.\n\nGeht los, sammelt weitere Erfahrungen, und erlernt eine neue Fähigkeit. Demonstriert sie dann an einer der Trainingsattrappen.", progress = nil, completion = "Ihr habt Euch als fähig erwiesen. Wenn es an der Zeit ist, Eure Ausbildung fortzusetzen, kehrt zu mir zurück und ich werde Euch neue Techniken lehren.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFlag Night Elf Class Skill Tracker Quest\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31170] = {title = "Ausbildung zum Mönch", objective = "Sprecht mit Pao - dem Mönchlehrer - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer.", description = "Während Ihr in Eurer Klasse weiter aufsteigt, werdet Ihr sicher die Ausbildung, die Euch der Lehrer Eurer Klasse anbietet, nutzen wollen. Für junge Mönche ist hier auf der Insel der Sonnenwanderer Pao zuständig, unser Pandarengast. Sprecht mit ihr und seht, was sie Euch an Ausbildung anbieten kann.\n\nPao - wie alle anderen Lehrer auf der Insel der Sonnenwanderer auch - ist innerhalb des Sonnenturms auf der unteren Ebene anzutreffen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31171] = {title = "Tigerklaue", objective = "Erreicht Stufe 3 und erlernt Tigerklaue. Findet eine Trainingsattrappe außerhalb des Sonnenturms und übt diese Fähigkeit.", description = "Gut. Das war ein vielversprechender Anfang. Vor Euch liegt noch ein langer Weg. Aber je weiter ihr voranschreitet, desto mehr Dinge lernt Ihr, von denen Ihr zuvor nicht einmal zu träumen gewagt hättet.\n\nSammelt noch etwas mehr Erfahrung und erlernt eine neue Technik. Sucht Euch dann eine Trainingsattrappe und demonstriert Eure neue Fähigkeit.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31172] = {title = "Ausbildung zum Mönch", objective = "Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31173] = {title = "Die Tigerklaue", objective = "Erreicht Stufe 3, um die Technik Tigerklaue zu erlernen. Sucht eine Trainingsattrappe an der nordwestlichen Seite der Absturzstelle und übt diese Fähigkeit.", description = "Ich hoffe, Euren Leuten geht es gut... Dieser Absturz war ja unglaublich laut. Was für ein Chaos!\n\n<Mojo betrachtet Euch, um Euer Potenzial einzuschätzen.>\n\nJa, mit Euch kann man etwas anfangen. Sie sagen mir, dass sie mehr Kämpfer brauchen, aber sie wollen auch nicht, dass ich zu Schaden komme. Ich habe zwar keine Angst, aber ich will mich auch nicht einmischen. Also werde ich Euch unterweisen.\n\nWie Ihr wohl schon festgestellt habt, steigen Eure Fähigkeiten mit zunehmender Erfahrung. Also zieht los und versucht, eine neue Fähigkeit zu meistern. Los, zeigt's mir. Ihr bekommt das schon hin.", progress = nil, completion = "Ihr solltet diese Technik immer anwendungsbereit halten, &lt;Name&gt;. Damit könnt Ihr stärkere Gegner außer Gefecht setzen oder Euch einfach nur großartig fühlen - wie ein Tiger eben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31175] = {title = "Skeer der Blutsucher", objective = "Erweckt Skeer den Blutsucher in der Unterwasserhöhle.", description = "Unsere Anstrengungen, die Untiefen vor den Zan'vess zu erobern, haben sich gelohnt.\n\nWir haben noch einen in Bern begrabenen Getreuen entdeckt, versteckt in den Wassern im Südwesten.\n\nUnsere Reihen mit einem weiteren Getreuen zu verstärken ist überlebenswichtig. Mit noch einem Held aus vergangenen Zeiten könnte sich das Blatt zu unseren Gunsten wenden.\n\nIch würde ja sofort gehen, doch leider werde ich hier gebraucht.\n\nDa Ihr bereits <ein Erwecker/eine Erweckerin> seid, könnt Ihr diese Aufgabe für mich übernehmen.", progress = nil, completion = "Der Hunger... man hat mir gesagt, dass er heftig sein würde, so habe ich ihn mir aber nicht vorgestellt.\n\nEs ist merkwürdig, sich so... schwach zu fühlen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31176] = {title = "Merkwürdige Gelüste", objective = "Sammelt 12 Portionen Seesternfleisch.", description = "Essen. Ich muss essen.\n\nZu meiner Zeit wurde man von Seesternfleisch nicht nur stark, sondern bekam auch einen klaren Kopf. Also muss ich genau das essen.\n\nBringt mir welches aus den Untiefen in der Nähe.\n\nWenn Ihr noch länger wartet, werde ich stattdessen Euch verschlingen.", progress = "Die Säfte des Seesterns werden mir Klarheit verschaffen.", completion = "Ja, gebt es her! Gut gemacht, Erwecker.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31177] = {title = "Schick essen", objective = "Sammelt 8 Klackerschwänze.", description = "Zu Lebzeiten war ich der beste Krieger des Schwarms.\n\nHelft mir wieder zu Kräften zu kommen, und ich werde es Euch beweisen.\n\nIch kann Meeressalz in der Nähe riechen, und wo das Meer ist, da gibt es auch Salzklacker.\n\nBringt mir ihre Schwänze. Ich muss mich an ihrem Fleisch gütlich tun.", progress = "Ich habe viel zu tun. Je eher ich kämpfen kann, desto eher kann ich zum Rat zurückkehren.", completion = "Ausgezeichnet. Das wird mir die Kraft geben, meine Gegner zu bezwingen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31178] = {title = "Ein blutiges Vergnügen", objective = "Sammelt 100 Einheiten flüchtiges Blut von Schreckensschiffshaltern.", description = "Ein Krieger ist erst dann zum Kampf bereit, wenn er das Blut seiner Feinde schmeckt.\n\nIch bin immer noch zu schwach für die Jagd, also müsst Ihr meinen Platz einnehmen.\n\nEs muss das Blut von Raubtieren und Wilden sein. Ich kann sie im Wasser vor dieser Höhle draußen riechen!\n\nBringt es mir und Ihr werdet vielleicht die Macht des Blutsuchers zu sehen bekommen.", progress = "Durch das Trinken des Blutes Eurer Gegner erlangt Ihr ihre Stärke.", completion = "Ja, dieses Blut wird seinen Zweck erfüllen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31179] = {title = "Der Geruch des Blutes", objective = "Tötet 12 Fleischfresser der Schlickschuppen und den Serpentus der Schlickschuppen.", description = "Ich fürchte, ich habe mir die Hände mit Saurokblut schmutzig gemacht, während Ihr fort wart.\n\nTut mir leid, aber ich konnte einfach nicht anders.Und jetzt seht zu, wie sie mich angreifen.\n\nLächerlich!\n\nWollen sie sich damit für ihre Gefallenen rächen? Kommen sie, um MICH herauszufordern?\n\nMich, der ich hundert Kriege gewonnen habe? Mich, der ich mich im Alleingang Tausenden entgegengestellt und trotzdem meinen Feinden zugerufen habe, näherzukommen?\n\nNein, diese... Saurok... werden vor mir in sich zusammenfallen wie Papier vor einer Flamme!\n\nIch werde Euch meine Macht demonstrieren, <Erwecker/Erweckerin>. Kämpft an meiner Seite und seht zu.\n\nDa kommen sie!", progress = nil, completion = "Euch war einmal mehr Erfolg beschieden. Gut gemacht, Erwecker.", rewards = "Axt des BlutsuchersStreitkolben des BlutsuchersSchild des ErweckersAuge des ErweckersSalzschuppendolchKiefer des ErweckersLicht des ErweckersChronik der hundert KriegeAuf Euch wartet eine dieser Belohnungen:\n\nGeldbeutel des Helden\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][31181] = {title = "Frische Körbe", objective = "Bestückt 10 leere Krabbentöpfe in der Einsamen Bucht mit Ködern. Jeder Topf erfordert 2 Seemonarchenteile.", description = "Wir haben eine Menge leere Krabbenkörbe da draußen, die neue Köder brauchen.\n\nAlso, wir KÖNNTEN einen nach dem anderen einholen und sie ganz gemütlich hier oben mit Ködern bestücken. Auf einem bequemen Stuhl sitzen und vielleicht zum Warmhalten eine schöne heiße Tasse Tee trinken. Klingt doch schön, findet Ihr nicht?\n\nDaraus wird nichts.\n\nMacht Euch zur Einsamen Bucht, direkt im Südwesten, auf und füllt die Körbe mit zwei Teilen frischen Seemonarchen als Köder. Mit \"frisch\" meine ich solche, die direkt dort im Wasser getötet wurden.\n\nAch ja, und mit \"Körben\" meine ich Fallen. Wenn Ihr zur Besatzung gehören wollt, lernt Ihr lieber den Jargon.", progress = nil, completion = "Nicht übel, Grünschnabel, gar nicht übel.", rewards = "MuttersaatrobeSaftfliegentunikaVerdorrte HolzrüstungKlarheitsbrustschützerSchreckensspinnerrobeGeisterfuchstunikaWindschnitterrüstungBrustharnisch des KlingenverschriebenenKältebissbrustharnischIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31182] = {title = "Ihr wisst doch, Otter?", objective = "Benutzt den Beutel mit Muscheln, um 8 Kaltbartotter in der Einsamen Bucht zu füttern.", description = "Wisst Ihr, was den Ködern in diesen Körben zugestoßen ist?\n\nOtter. Otter sind ihnen zugestoßen.\n\nSie fressen zwar lieber frische Muscheln, wenn sie aber hungrig genug sind, räumen sie auch unsere Krabbenfallen aus.\n\nDie Otter in der Einsamen Bucht sind gesetzlich geschützt und wir sind hier ein rechtmäßiges Unternehmen. So gern ich die kleinen Ratten ein für alle Mal loswerden möchte - sorgen wir einfach dafür, dass sie keinen Hunger mehr haben und die Krabbenkörbe in Ruhe lassen.\n\nVerfüttert ein paar Muscheln an sie, damit sie beschäftigt sind, während Ihr dort draußen seid.", progress = nil, completion = "Das sollte ihre kleinen Schnurrhaare eine Weile von unseren Fallen fernhalten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31183] = {title = "Den Käpt'n treffen", objective = "Sprecht mit \"Tropf\" Su-Dao in Tropfs Wagnis.", description = "Also gut, $p, ich habe einen weiteren Auftrag für Euch.\n\nSeht Ihr die Löwenrobbe in dem Verschlag dort drüben? Sie heißt Hund und ist schon seit Jahren Tropfs Haustier.\n\nIn letzter Zeit spielt Hund verrückt - ich glaube, er wird unruhig in seinem Verschlag. Warum redet Ihr nicht mit Tropf darüber?\n\nIch finde sowieso, dass es Zeit ist, den Käpt'n kennenzulernen.", progress = nil, completion = "Neue Deckhilfe, hm? Das werden wir noch sehen.\n\nIch halte das Ruder fest in der Hand - selbst wenn es auf dem Meeresgrund sitzt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31184] = {title = "Alter und Verrat", objective = "Bergt die Charta vom Wrack der Nebelhüpfer.", description = "Also, ich hab keinen Grund, Euch zu trauen, es gibt da aber eine Aufgabe, die ich meiner Besatzung nicht geben kann.\n\nDurchsucht das Wrack unseres alten Schiffs, der Nebelhüpfer, und bringt mir ihre Charta. Sie ist in einem silbernen Rohr in einer Truhe versiegelt.\n\nSie ist etwas, äh... verfänglich. Ich kann nicht riskieren, dass jemand von der Besatzung beschließt, das alte Mädchen aufzusuchen, und sie findet. Sie ruht auf dem Riff von Mazu, westlich von hier.\n\nWenn Ihr genug Mumm habt, schlage ich vor, dass Ihr Euch von einer Rippströmung hinbringen lasst. Die findet Ihr nämlich überall auf dem Riff.", progress = "Ehrlich gesagt hoffe ich, dass die alte Charta von einem Barsch aufgefressen wurde.\n\nAndererseits könnte er dann trotzdem wieder hier landen. Verflixt!", completion = "Ja, das ist das Rohr mit der Charta. Ihr würdet wohl gern wissen, was es mit dem ganzen Getue auf sich hat, stimmt's?\n\n&lt;Tropf seufzt tief und öffnet das Rohr.&gt;\n\nBringen wir es hinter uns.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nOld Age And Treachery: Completion Event\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31185] = {title = "Gassi mit Hund", objective = "Nehmt Hund und stattet mit ihm den heißen Geysiren, dem toten Wal und dem Wrack der Nebelhüpfer auf dem Riff von Mazu einen Besuch ab.", description = "Hund ist nicht mein \"Haustier\". Er ist ein Mitglied dieser Besatzung und mein bester Freund. Hat mir mehr als einmal das Leben gerettet.\n\nIch werde aber zu alt, um ihn auszuführen, und er braucht Bewegung. Würdet Ihr eine Runde über das Riff mit Hund für mich drehen?\n\nEr schwimmt gern durch die heißen Geysire südöstlich der Untiefen.\n\nEr muss auf jeden Fall den toten Wal am westlichen Rand des Riffs... äh... \"markieren\".\n\nAch ja, und er will bestimmt auch unser altes Schiffswrack besuchen. Er schwelgt gern in Erinnerungen.", progress = nil, completion = "Wie ist es gelaufen? Ich hoffe, er hat Euch keine große Mühe bereitet!", rewards = "MuttersaatgamaschenSaftfliegenbeinschützerVerdorrter HolzkiltKlarheitsbeinplattenSchreckensspinnerbeinkleiderGeisterfuchsbeinschützerWindschnittergamaschenBeinschützer des KlingenverschriebenenKältebissbeinschützerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31186] = {title = "Hundefutter", objective = "Helft Hund, die Reste von 10 Felsschalenschnappklauen zu essen.", description = "<Hund bellt in bester Löwenrobbenmanier und deutet kraftlos mit einer Flosse auf sein enormes Maul.\n\nEr hat Hunger.\n\nDas Riff von Mazu ist mit Felsschalenschnappklauen bedeckt, die eine leckere Mahlzeit für ihn abgeben dürften.>", progress = "<Das ist mit Sicherheit die erbärmlichste Löwenrobbe, die Ihr je gesehen habt.>", completion = "&lt;Hund leckt sich zufrieden die Lefzen und sieht glücklich aus.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31187] = {title = "Krabbenfülle", objective = "Hängt eine Nebelhüpferboje an 8 volle Krabbenkörbe auf dem Riff von Mazu.", description = "Ich habe gerade gehört, dass ein paar von den Körben, die wir heute Morgen ausgeworfen haben, einen Volltreffer gelandet haben. Massenweise Krabben!\n\nDummerweise ist die Rippströmung stärker geworden und wir haben die Spur von einigen Körben verloren. Und die sitzen jetzt da draußen, gefüllt mit stacheligem blauem GOLD!\n\nIch will Euch da draußen sehen. Hängt an jede volle Falle, die Ihr findet, eine von diesen Bojen und schickt sie für uns an die Oberfläche.", progress = nil, completion = "Gute Arbeit dort draußen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31188] = {title = "Haiwoche", objective = "Sammelt 200 Drescherzähne, indem Ihr sie den Langflossendreschern auf dem Riff von Mazu zieht.", description = "Der Krabbenfang ist unsere größte Einkommensquelle, wir schicken aber alle möglichen Güter hinter die Mauer zurück. Öl, Pflanzen, sogar seltene Mineralien - hier draußen ist das Meer freigiebig!\n\nMomentan sind Drescherzähne der letzte Schrei auf den Märkten zu Hause. Angeblich eignen sie sich hervorragend für Halsketten.\n\nDas Riff von Mazu im Westen wimmelt nur so von Dreschern. Bringt mir massenweise Zähne!", progress = "Ich habe selbst gesehen, wie jemand von einem Drescher aufgefressen wurde; deshalb verstehe ich nicht ganz, warum man aus freien Stücken ihre Zähne um den Hals tragen sollte, aber egal.", completion = "Die hier sind perfekt. Legt sie einfach dort drüben hin. Ich würde sie lieber nicht selbst anfassen. Davon kriege ich eine Gänsehaut.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31189] = {title = "Einholstrategie", objective = "Helft Meisterangler Ju Lien in Tropfs Wagnis.", description = "Ich hätte nie gedacht, dass ich den Tag erleben würde, doch zum ersten Mal seit... na, zum ersten Mal ÜBERHAUPT hat mich Meisterangler Ju Lien um Hilfe mit seinen Angelleinen gebeten.\n\nAnscheinend spielt die See heute verrückt und er kann nicht Schritt halten. Seht nach, ob Ihr ihm helfen könnt. Er fischt nicht weit südlich von hier.", progress = "Geht und helft Ju Lien aus, ja?", completion = "Was ist da draußen passiert? Ich habe einen Schrei gehört, und ehe ich mich versah, kamen diese grässlichen Dinger mit der nächsten Welle an!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31190] = {title = "Die Rache des Seemanns", objective = "Lasst die Nebelhüpfer Jr. am Dock in Tropfs Wagnis zu Wasser und benutzt sie, um Jiao zu erledigen.", description = "Ich sitz doch in keinem verfluchten Schaukelstuhl, während meine Besatzung von einem Leviathan verschlungen wird!\n\nLos, wir gehen zum Dock und lassen eine Jolle zu Wasser. Ich habe eine spezielle, genau für diese Art von Situation. Meine eigene kleine Nebelhüpfer Jr.\n\nWir werden diesem Ding einen Fall von Harpunenfieber verpassen.", progress = nil, completion = "Gut geschossen dort draußen!\n\nIch wusste, dass wir es schaffen würden. Mir ist noch nie etwas begegnet, das man nicht mit genügend Harpunen hätte töten können.", rewards = "MuttersaatmantelungSaftfliegenschiftungVerdorrte HolzschiftungKlarheitsschiftungSchreckensspinneramiciaGeisterfuchsschiftungWindschnitterschiftungSchultern des KlingenverschriebenenKältebissschulternIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31194] = {title = "Schlängelschuppen unterdrücken", objective = "Tötet den Echsenlord der Schlängelschuppen.", description = "Die Schlängelschuppen gehorchen ihrem Anführer, dem Echsenlord der Schlängelschuppen. Ihr könnt ihn ganz im Südwesten der Windwärtsinsel dabei finden, wie er seine Siege feiert.\n\nWenn wir diesen Anführer ausschalten können, treffen wir ihren Stamm empfindlich.\n\nOhne ihn werden es sich die Schlängelschuppen zweimal überlegen, ob sie die friedlichen Wolkenschlangen im Osten weiterhin angreifen.", progress = nil, completion = "Wunderbar! Ich wusste, dass Ihr den Lord der Schlängelschuppen besiegen könntet.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31196] = {title = "Sra'vess-Drecksarbeit", objective = "Tötet 15 der nicht zur Elite zählenden Mantis bei Sra'vess.", description = "Die Mantis sind deutlich in der Überzahl - Hunderte von ihnen gegen einen von uns.\n\nUnd sie bedrohen uns von zwei Seiten. Bei Gao-Ran im Süden können wir sie aufhalten, aber im Westen, auf der Insel, die sie Sra'vess nennen, sammeln sie sich weiterhin ungehindert.\n\nDa wir nicht blöd sind, werden wir keinen frontalen Großangriff auf sie starten. Wir können nicht an mehreren Fronten mit voller Kraft kämpfen.\n\nStattdessen werden wir Euch und einen unserer Wukao entsenden, um ein wenig Drecksarbeit zu erledigen. Klingt doch spaßig, oder?", progress = nil, completion = "Gute Arbeit. Ich halte es immer für das Beste, dann zuzuschlagen, wenn sie nicht vorbereitet sind.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLaunch Capper Quest\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31197] = {title = "Immer auf die Großen", objective = "Tötet 4 Elitemantis auf Sra'vess.", description = "Die kleineren Mantis zu töten dient mehr der Ablenkung. Dadurch müssen sie erst wieder ihre Reihen füllen, bevor sie eine größere Offensive wagen können.\n\nWenn es uns allerdings gelingt, einige ihrer größeren Exemplare zu töten, würden wir ihre Operationen auf der Insel empfindlich stören und uns wertvolle Zeit verschaffen. Bei den Mantis steht ihre Größe in direktem Zusammenhang mit ihrer Bedeutung für das Reich.\n\nAlso tötet da draußen ein paar von den größeren Mantis für mich.", progress = nil, completion = "Sehr, sehr gute Arbeit. Das sollte uns zumindest für ein paar Tage etwas Luft verschaffen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLaunch Capper Quest\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31198] = {title = "Ein Schlag für ihre Moral", objective = "Zerstört den südlichen, mittleren, östlichen und westlichen Götzen auf Sra'vess.", description = "Die Mantis haben Statuen auf Sra'vess errichtet. Wir wissen allerdings nicht, welchem Zweck sie dienen. Vielleicht sind sie von religiöser Bedeutung oder sie nutzen sie für ihre Schallwellenkommunikation.\n\nIm Kampf gegen den Feind ist es wichtig, ihm nicht nur körperlichen, sondern auch mentalen Schaden zuzufügen. Was immer diese Statuen darstellen, sie scheinen den Mantis wichtig zu sein.\n\nUnd darum will ich, dass Ihr sie in die Luft jagt. So etwas Wichtiges zu verlieren, sollte ihrer Moral einen herben Schlag versetzen.", progress = "Die Statuen?", completion = "Ich wette, der Verlust der Statuen hat ihnen nicht gefallen, oder?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLaunch Capper Quest\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31199] = {title = "Zerstörung der Belagerungsgeschütze", objective = "Zerstört die vier Mantis-Belagerungswaffen auf Sra'vess in der Tonlongsteppe.", description = "Die Mantis greifen nicht nur in Schwärmen an. \n\nSie sind intelligent. Sie nutzen Alchemie, Bomben... und sogar Belagerungsgeschütze mit verheerender Angriffskraft.\n\nWir haben Berichte erhalten, dass sie auf Sra'vess im Westen eine Streitmacht mit Belagerungstruppen zusammenziehen. Also zieht los und zerstört diese Dinger.", progress = nil, completion = "Diese Belagerungsgeschütze stellen erst einmal kein Problem mehr dar. Vielleicht bauen sie neue, aber vorerst haben wir uns etwas Zeit verschafft.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLaunch Capper Quest\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31200] = {title = "Ausräucherung", objective = "Platziert die Shado-Pan-Gasbomben an den 5 Zielgebäuden auf Sra'vess.", description = "Unsere Alchemisten haben ein paar Gasbomben gebastelt, die dafür sorgen werden, dass die Mantis die Orte meiden, an denen wir sie hochgehen lassen. \n\nWenn wir sie an strategisch wichtigen Punkten auf Sra'vess platzieren, zwingen wir sie zur Evakuierung. Dadurch sorgen wir für tagelanges Chaos in den Reihen der Mantis.\n\nAlso macht Euch auf, <Name>.", progress = nil, completion = "Sehr schön! Ich kann den Rauch ja sogar von hier sehen. Das sollte ein hübsches Chaos verursachen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLaunch Capper Quest\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31201] = {title = "Freunde sind kein Fressen!", objective = "Rettet jeweils einen Shado-Pan-Auszubildenden in der nördlichen, mittleren und südlichen Kunchongfütterungsgrube.", description = "Unsere Späher haben uns einen sehr alarmierenden Bericht zukommen lassen. \n\nSie haben drei unserer verschollenen Auszubildenden gefunden... \n\nSie wurden von den Mantis gefangen genommen und in ihre Kunchonggruben geworfen. \n\n...in ihre KunchongFÜTTERUNGSgruben. Glücklicherweise pflegen die Kunchong nicht so häufig zu fressen.\n\nIch möchte, dass Ihr dort eindringt und die Gefangenen mithilfe dieser Rettungsdrachen dort rausholt!", progress = nil, completion = "Das sind gute Nachrichten! Ich hatte mir große Sorgen um sie gemacht.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLaunch Capper Quest\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31203] = {title = "Günstige Gelegenheit: Schwarmfürst der Sra'thik", objective = "Tötet den Schwarmfürsten der Sra'thik auf Sra'vess in der Tonlongsteppe.", description = "Wenn wir schon mal hier sind, können wir noch eine weitere Sache erledigen.\n\nDer Schwarmfürst der Sra'thik ist verantwortlich für die Koordination der Mantistruppen aus der Luft. Wenn wir ihn am Leben lassen, wird die Garnison Schwierigkeiten bekommen.\n\nAlso werden wir ihn nicht am Leben lassen. Schalten wir ihn aus, $p.", progress = "Wir müssen den Schwarmfürsten ausschalten!", completion = "Ich hörte, Ihr habt Euch ein wenig... zusätzlichen Ruhm da draußen verdient. Gute Arbeit.\n\nKommt gerne an einem anderen Tag wieder vorbei. Ich bin sicher, wir werden dann wieder etwas für Euch zu tun haben.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31204] = {title = "Günstige Gelegenheit: Brutfürst der Sra'thik", objective = "Tötet den Brutfürsten der Sra'thik.", description = "In der Nähe des Ozeans, im Osten von Sra'vess, befindet sich ein Gewölbe, das in ein ganzes Labyrinth von Höhlen führt.\n\nVon dort aus kontrolliert der Brutfürst der Sra'thik Sra'vess und schmiedet seine Pläne gegen uns. Wenn es uns gelingt, ihn auszuschalten, können wir ihre Bemühungen um Tage zurückwerfen.\n\nAlso an die Arbeit.", progress = "Wir müssen den Brutfürsten ausschalten!", completion = "Gut gemacht, &lt;Name&gt;! Dank Eures zusätzlichen Einsatzes haben wir jetzt etwas Ruhe vor den Mantis.\n\nAber wir werden ganz sicher auch in Zukunft Aufträge für Euch bereithalten. Kommt also gerne später wieder.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31206] = {title = "Der Schmelztiegel des Gemetzels: Haudrauf der Blutaugen!", objective = "Betretet die Arena im Schmelztiegel des Gemetzels und besiegt Strunz'blunz!", description = "Eins sag ich Euch, man kann hier natürlich nicht mit den Wogenden Ebenen von Nagrand oder der Arena in Zul'Drak vergleichen, aber hey, ich bin da, wo das Gold ist! Willkommen im Schattenhochland!\n\nIhr seid neu hier, also lasst mich Euch ein paar Sachen erklären. Ich bin der Kampfveranstalter und der angriffslustige Troll hier ist Wodin, mein Leibwächter. Ihr seid meine Unterhaltung. Wenn Ihr kämpfen wollt, sagt Bescheid, und ich finde den passenden Gegner für Euch.\n\nWenn Ihr mit Freunden hier seid, können wir auch gleich anfangen! Was meint Ihr?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31207] = {title = "Die Arena der Auslöschung", objective = "Betretet und beendet das Szenario der Arena der Auslöschung. Holt Euch anschließend Eure Belohnung von Wodin, dem Trolldiener.", description = "Ah, ich erinnere mich noch gut daran, damals in Nagrand aus einem Matschloch heraus Kämpfe angeführt zu haben. Wir haben schon viel mitgemacht, was, Wodin?\n\nIch sage Euch, diese Tigermönche lieben nichts mehr als eine anständige Rauferei. Sogar so sehr, dass sie mich gut bezahlt haben, um mich hier niederzulassen und die besten Kämpfer weit und breit heranzuziehen.\n\nWie wär's? Ihr und ein paar Freunde machen ein paar Runden in der Arena der Auslöschung...? Großes Geld, große Preise!", progress = "Worauf wartet Ihr? Die Mönche brennen auf eine gute Show.", completion = "Gurgthock sagte, es würde sich für Euch lohnen. Sucht Euch etwas aus!", rewards = "Liuyangs leicht beleuchteter LanghakenWolkenformer Kobos gekühlte ArmbrustJol'Grums gefrorener StreikolbenLiuyangs lieblicher LangstabChagans herrliches HackebeilSatays stechendes SchwertNarbenpanzers schimmernder StabMakis zermatschender StreitkolbenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31208] = {title = "Giftige Absichten", objective = "Sammelt 8 giftige Stacheln.", description = "Wenn wir vorhaben, die Kaiserin anzugreifen, sollten wir uns bewaffnen. Ich wähle dafür eine Waffe, die von besonders giftiger Natur ist.\n\nDie Skorpione auf der Giftigen Klippe produzieren ein tödliches Gift, das sie in ihren Schwänzen aufbewahren.\n\nBringt mir ihre Stacheln und ich werde Euch zeigen, dass ich den Titel eines Getreuen zu Recht trage.", progress = "Habt Ihr den Stich des Giftschwanzes gespürt? Welch wundervoller Schmerz.", completion = "Gut gemacht, Erwecker. Ich hoffe, Ihr seid vorsichtig mit den Stacheln umgegangen.\n\nDas natürliche Gift dieser Skorpione ist tödlich, doch es wirkt langsam.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31209] = {title = "Finstere Schwinge, finstere Dinge", objective = "Sammelt 150 Skarabäenflügel.", description = "Zur Erstellung meines ersten Giftes brauche ich eine weitere Zutat, <Erwecker/Erweckerin>.\n\nIhr findet sie ganz einfach bei den Skarabäen hier in der Nähe.\n\nTötet sie und bringt mir ihre Flügel.", progress = "Skarabäenflügel können zerstoßen werden, um ein sehr feines und tödliches weißes Pulver herzustellen.", completion = "Ja, ausgezeichnet, Erwecker! Die hier sind perfekt.\n\nHabt Ihr Euch schon einmal überlegt, die Giftkunst zu erlernen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31210] = {title = "Ein Schatten des Schreckens", objective = "Sammelt 8 Angstschatten.", description = "Die letzte Zutat ist vielleicht die tödlichste.\n\nDie Angstschattenblume wächst überall hier auf diesen Hügeln.\n\nIhr Verzehr ist dafür verantwortlich, dass die hiesigen Tiere so giftig sind.\n\nEin einziger Tropfen Angstschattennektar reicht, um das Herz eines Kunchong zum Stillstand zu bringen.\n\nZieht los und bringt mir ein paar von diesen Blumen. Lasst Euch nicht dazu verlocken, sie zu kosten.", progress = "Manchmal sind die schönsten Dinge auch die gefährlichsten.", completion = "Nicht viele würden den Wert dessen erkennen, was Ihr habt.\n\nGut gemacht, Erwecker.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31211] = {title = "Der vergiftete Geist", objective = "Sprecht mit Xaril dem vergifteten Geist. Tötet 200 Mantis und 3 Kunchong, während Ihr mit ihm fliegt.", description = "Bevor wir nach Klaxxi'vess zurückkehren, möchte ich einen Blick auf das Reich werfen. Der Rat der Klaxxi hat mir berichtet, dass der Feind sich vor dem Palast der Kaiserin sammelt.\n\nMeine Gifte sind bereit, denn wie könnte ich meine Rückkehr besser verkünden als mit Tod und Zerstörung?\n\nPasst nur auf, dass Ihr die beiden Seren nicht vermischt... zumindest nicht, solange Ihr die Gefäße noch in der Hand haltet.\n\nSprecht mit mir, wenn Ihr zum Abflug bereit seid.", progress = nil, completion = "Danke, dass Ihr mich nach Hause zurückgebracht habt, Erwecker, ich fürchte allerdings, dass der Krieg gerade erst beginnt.", rewards = "Band der Krik'thikSchleife des vergifteten GeistesXarils RingSiegel des SchlachtpanzersFlügelwächterschleifeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31216] = {title = "Der Himmel verfinstert sich", objective = "Tötet 200 Mantis und 3 Kunchong oder grauenhafte Ungetüme, während Ihr mit Xaril dem vergifteten Geist fliegt.", description = "Der Schwarm fängt an, <Erwecker/Erweckerin>! Die Mantis sammeln sich im Herzen der Angst.\n\nSie füllen den Himmel bereits mit ihren Flügeln und zerfetzen die Erde mit ihren Klauen. Sie werden ihren finsteren Marsch erst unterbrechen, wenn ihre Körper offen und blutend auf dem Boden liegen.\n\nUnd das werden wir mit Freuden tun. Wir werden von oben angreifen. Nutzt meine Gifte, um ihre Vorhut zu vernichten, während ich fliege.\n\nAber vermischt die Seren nicht, bis Ihr bereit seid, anzugreifen. Die Reaktion kann recht... heftig sein.\n\nSprecht mit mir, wenn Ihr soweit seid.", progress = "Diese wunderbare Zerstörung!", completion = "Gut gemacht, Erwecker. Ihr habt die Zielgenauigkeit eines Zerstörers.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31220] = {title = "Der Ring des Herausforderers: Falkenmeister Nurong", objective = "Fordert Falkenmeister Nurong heraus und besiegt ihn im Kampf in der Shado-Pan-Garnison in der Tonlongsteppe.", description = "Ihr verdient Euch immer mehr Respekt bei den Shado-Pan, <Name>.\n\nNurong möchte seine Fähigkeiten gegen Euch auf die Probe stellen.\n\nDas Gute daran: Wenn Ihr gewinnt, werde ich ihm erlauben, sich Euch auf Euren Missionen anzuschließen.\n\nDer Haken daran: Ich glaube eigentlich nicht, dass Ihr gegen ihn gewinnen könnt.", progress = "Keine Lust auf diese Herausforderung? Kann ich verstehen.", completion = "Tja... Offenbar habe ich mich getäuscht.\n\nGute Arbeit. Nurong wird Euch fortan gerne auf Euren Missionen begleiten.", rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31221] = {title = "Der Ring des Herausforderers: Tenwu der Rote Rauch", objective = "Fordert Tenwu den Roten Rauch heraus und besiegt ihn im Kampf in der Shado-Pan-Garnison in der Tonlongsteppe.", description = "So... Der berüchtigte Tenwu der Rote Rauch hat Euch also herausgefordert.\n\nDiesen Namen hat er sich übrigens selbst gegeben. Er ist ein guter Kämpfer und Schurke. Allerdings muss man sich wundern, wie er sich so gut an seine Gegner anschleichen kann, wo er doch immerzu lautstark prahlt.\n\nAuf jeden Fall solltet Ihr die Herausforderung annehmen. Vielleicht könnt Ihr ihn etwas Demut lehren. Vielleicht auch nicht. Wenn Ihr aber gewinnen könnt, wird er Euch wohl auf Euren Missionen begleiten wollen. \n\nUnd ich darf mich auf gute Unterhaltung freuen.", progress = "Und? Wie ist es gelaufen?", completion = "Respekt! Gut gemacht. Eure Kampffähigkeiten sind beachtlich.\n\nVielleicht wird er sich ja in Zukunft darauf konzentrieren, mit Euch mitzuhalten, und endlich seine große Klappe halten.", rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31228] = {title = "Prophet Khar'zul", objective = "Besiegt Prophet Khar'zul.", description = "Prophet Khar'zul ist ein mächtiger Zauberer, aber er unterschätzt auch Eure Fähigkeiten.\n\nKhar'zul und seine Streitkräfte müssen vernichtet werden, um dieses Dorf zu beschützen. Sein Tod wird dem Donnerkönig ein deutliches Zeichen setzen, dass wir uns nicht so einfach besiegen lassen!\n\nIhr findet ihn auf der Insel der Abrechnung.", progress = nil, completion = "Aus diesen Ereignissen sollte man lernen, &lt;Name&gt;.\n\nEs ist wichtig, dass wir aus unserer Geschichte Lehren ziehen. Wenn wir der Geschichte Aufmerksamkeit gewidmet hätten, wäre es uns vielleicht möglich gewesen, das hier früher abzuwenden.\n\nAlles Geschehene war bereits vorhergesagt, wir wussten es nur nicht zu deuten.", rewards = "WasserfallgamaschenMushanlederbeinschützerKilt des träumenden GeistesBeinplatten des GleichmutsHosen des GeistbeugersBeinschützer der lautlosen BlätterGamaschen des YakhirtenBeinschützer des GipfelwächtersBeinschützer der MauerwacheIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31230] = {title = "Willkommen in Morgenblüte", objective = "Sprecht mit Kai Wanderbräu, Meister Windpelz und Peiji Zapfgold in Morgenblüte.", description = "Cho ist unterwegs auf einem seiner Abenteuer und dieses Mal wird ein großer Batzen Jade benötigt. Ich werde wohl ein paar ausstehende Gefallen einlösen.\n\nWie wäre es, wenn Ihr Euch in der Zwischenzeit einigen der Einheimischen vorstellt?\n\nEs wäre gut, Kai Wanderbräu und Meister Windpelz kennenzulernen. Oh, und grüßt Peiji Zapfgold drüben beim Gasthaus von mir.\n\nMit den dreien solltet Ihr schon mal einen guten Eindruck vom Leben in Morgenblüte erhalten.", progress = "Glück gehabt?", completion = "Gut, gut, gut. Ihr werdet hier richtig gut reinpassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31231] = {title = "Die Auslöschung der Schreckensspinner", objective = "Tötet 8 Schreckensspinnerhüter auf der Terrasse von Gurthan. Bittet Kil'ruk den Windschnitter, Euch dort abzusetzen.", description = "Auf der Terrasse von Gurthan, wo Ihr mich gefunden habt, ziehen Schreckensspinner weiterhin die Aufmerksamkeit der Shado-Pan-Bogenschützen auf sich, die sich sonst darum kümmern könnten, diesen elenden Schwarm zu lichten.\n\nMerzt die Spinnen aus und entlastet die Bogenschützen auf der Mauer.", progress = nil, completion = "Ich konnte Spinnen noch nie leiden. Widerliche, stumpfsinnige Insekten.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31232] = {title = "Ein uraltes Reich", objective = "Sammelt 8 Gurthanitafeln.", description = "Meine Brüder reden von einem uralten Mogureich, das einst in den Ruinen im Osten existierte.\n\nDieser Stamm kannte einst unbeschreibliche Geheimnisse über die Zauberei und Unterwerfung.\n\nIch bin sehr wissbegierig, <Erwecker/Erweckerin>, und möchte mehr über die Reiche herausfinden, die nach meiner Zeit existierten.\n\nDas Wissen über die Vergangenheit bestimmt unsere Zukunft.\n\nSucht in den Ruinen nach ihren alten Tafeln. Ich werde ihre Geheimnisse studieren und sie mir zu eigen machen.", progress = "Welches Wissen bringt Ihr?", completion = "Sehr gut, Erwecker. Diese Tafeln zu entziffern wird Zeit in Anspruch nehmen, doch alles Wissen ist es wert.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31233] = {title = "Saft anzapfen", objective = "Sammelt 6 Portionen Bernsaft.", description = "Östlich von hier steht ein Wäldchen mit jungen Bernbäumen, <Erwecker/Erweckerin>.\n\nIch habe Zapfvorrichtungen an den Bäumen angebracht, hatte aber zu viel zu tun, um den Saft einzusammeln.\n\nIch brauche jemanden, der die Entsafter findet. Aktiviert sie und bringt mir dann Proben von dem Bern.", progress = "Diese Bäume sind noch jung. Sie sind noch keine Kypari.\n\nIhr Saft ist wie Wasser, während der Saft eines echten Kyparibaums Wein ähnelt.\n\nSie müssen weiterwachsen.", completion = "Oh ja, genau das habe ich gebraucht.\n\nIch werde diese Proben untersuchen. Wir müssen die Gesundheit dieser jungen Kypari weiter überwachen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31234] = {title = "Ein Auge ausstechen", objective = "Sammelt 1 makelloses Morastbestienauge.", description = "Ah! <Erwecker/Erweckerin>! Ihr müsst mir helfen! (Helft mir, sonst verhelfe ich mir zu Euch!)\n\nIch brauche mehr Material für meine Experimente, oh ja! (Blut und Eingeweide, Herzen und Hirne, Zungen und Augen, Augen, Augen!)\n\nWestlich von hier habe ich Kreaturen aus Nebel und Dunst gesehen. Sie besitzen solch große, runde, wunderbare Kugeln! Groß, um zu sehen, rund und unverwandt!\n\nGeht schon, <kleiner Erwecker/kleine Erweckerin>. Geht und bringt mir ein makelloses Auge!", progress = "Ooooh, welche großartigen, leckeren Teile habt Ihr mir denn gebracht?", completion = "Ja, ja! Wunderbar! Ach, wie köstlich!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31235] = {title = "Pfui, noch mehr Spinnen", objective = "Benutzt das Drachengewehr der Shado-Pan, um 20 Schreckensspinnereier auf der Terrasse von Gurthan zu zerstören.", description = "Diese Waffe habe ich vor Kurzem bei einem Spähgang in der Nähe der Mauer gefunden. Sie sieht genau richtig aus, um Euren Shado-Pan mit ihrer Plage auf der Terrasse von Gurthan zu helfen.\n\nJe mehr sie sich darauf konzentrieren, die Spinnen von der Mauer fernzuhalten, umso weniger Zeit bleibt ihnen zum Töten verängstigter Schwarmgeborener.", progress = nil, completion = "Eine primitive Waffe, doch sie hat ihre Berechtigung.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31237] = {title = "Die Terrasse von Insekten befreien", objective = "Zerstampft 6 Augen der Kaiserin auf der Terrasse von Gurthan. Wenn Ihr etwas tötet, wird Euch die Pheromonfährtensuche bei der Aufstöberung helfen.", description = "Wenn diese Kaiserin tatsächlich von Furcht und Verfolgungswahn befallen ist, hat sie sicherlich Kundschafter in alle Winkel des Landes entsandt, um ihre Kontrolle zu festigen.\n\nDiese Kundschafterlarven sind vermutlich überall, doch schwierig mit bloßem Auge zu entdecken. Über die Pheromonspur, die sie hinterlassen, kann man sie leichter aufspüren.\n\nIch habe Euch bereits ein reaktives Toxin... geschenkt, das Euch vorübergehend, nachdem Ihr den Siegestaumel durchlebt habt, diese Spuren erkennen lässt.\n\nBrecht jetzt zur Terrasse von Gurthan auf und findet diese Spione.", progress = nil, completion = "Information ist Macht, &lt;Name&gt;. Wir dürfen nicht zulassen, dass die Kaiserin unsere Bewegungen überwacht.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Zone Auras\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31238] = {title = "Nahrung fürs Hirn", objective = "Bringt 4 Mushanzungen zu Kaz'tik dem Manipulator in Klaxxi'vess.", description = "Kovoks Wachstum ist beschleunigt, möglicherweise kann jedoch sein Gehirn nicht Schritt halten. Er braucht eine spezielle Ernährung, damit er nicht die Kontrolle über seinen eigenen Körper verliert.\n\nMushanzungen sind reich an Nährstoffen, die das Wachsturm von Kunchonggehirnen fördern, doch normalerweise fressen sie die Tiere ganz und werden schnell satt. Wenn wir Kovok etwa alle paar Tage nur mit Mushanzungen füttern, sollte das sein Wachstum ausgleichen.\n\nIn den Hügeln östlich von hier, nicht weit von der Terrasse von Gurthan, grasen Großrückenmushan.", progress = "Habt Ihr eine passende Mahlzeit für Kovok gefunden?", completion = "Während Ihr fort wart, hat Kovok die ganze Zeit gewinselt. Es war so richtig herzergreifend.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31239] = {title = "Name ist gut, Name Name ist besser!", objective = "Tötet 7 Strandläufer der Jinyu", description = "Du willst also ein Ho-zen sein, hä, Nappel?\n\nHo-zen verteidigen ihr Land vor Feinden, wie Jinyu.\n\nKah Kah hat viele Kämpfe mit Jinyu geschlagen und alle gewonnen.\n\nHo-zen geben nur guten Flotschern zwei Namen. Geh und flotsch Jinyu und vielleicht nennen wir dich <Name> <Name>.\n\nJinyu kriechen am Fluss rum. Flotsch sie bis es dommelt!", progress = nil, completion = "Ha ha! Nappel hat verfiddelte Jinyu geflotscht!", rewards = "Ihr bekommt:\n\nFischi"}
MultiLanguageQuestData['de'][31240] = {title = "Guo-Lai-Befall", objective = "Sprecht mit Anji Herbstlicht in den Guo-Lai-Ruinen.", description = "Anji war hier und hat nach Euch gefragt. Sagte, sie war auf dem Weg nach Nordosten, in die Ruinen.\n\nOh, Anji ist wirklich ein zorniger Charakter! Ist auf lange Sicht vielleicht besser für Eure Gesundheit, wenn Ihr sie nicht warten lasst.", progress = nil, completion = "Gut, dass Ihr da seid.\n\nIch hatte schon daran gezweifelt, dass Ren Euch die Nachricht gegeben hat.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31241] = {title = "Fiese Nappels", objective = "Sammelt 6 Dienstmedaillons der Allianz von kampferprobten Fallschirmjägern.", description = "<Name> <guter/gute> Nappel, heißt es…\n\n<Name> helfen Ho-zen, heißt es…\n\nnicht mehr <Name> flotschen, heißt es.\n\nDas in Ordnung. Da drüben gucken. Fiese Nappels fallen runter wie Regen, die kann man flotschen!\n\nGeh und hab Spaß. Aber nicht vergessen, Häuptling Kah Kah kriegt die Schimmerlinge! Das ist Regel von Ho-zen Nummer zwei.\n\n<Jik Jik kratzt sich am Kopf.>\n\nHmm, alle Regeln von Ho-zen sind Nummer zwei...", progress = "Haste was, Nappel?", completion = "Nappelgeflotsche machen Ho-zen reich mit Schimmerlingen!\n\n&lt;Name&gt; macht guten zweiten Eindruck. Und für Ho-zen, Nummer Zwei ist am wichtigsten!", rewards = "NappelübermantelNappeltuchNappelcapeNappelumhangNappelwickeltuchIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31242] = {title = "Nebelhauch", objective = "Sprecht mit Che Wildmarsch in Nebelhauch.", description = "Meine Späher haben zwar heute nichts über Mogu in der Nähe des Dorfes berichtet, dafür aber von Problemen mit den Tieren in der Gegend und Geistern am Friedhof. Ich habe Che entsandt, um die Situation zu evaluieren, aber er wird sicher Eure Hilfe brauchen.\n\nBitte begebt Euch nach Südwesten in das Dorf und trefft dort Che. Bietet ihm jede erdenkliche Hilfe an.", progress = nil, completion = "Da hat Leven mir eine echte Hilfe geschickt. Dafür werde ich mich später bei ihm bedanken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31243] = {title = "Angriff auf Nebelhauch", objective = "Sprecht mit Sun Zartherz in Nebelhauch.", description = "In Nebelhauch, im Südwesten, sind Mogu gesichtet worden. Ich habe schon Rook und Sun entsandt, aber ich brauche dort noch jemanden mit Fähigkeiten wie Euren.\n\nBitte macht Euch sofort auf den Weg. Die Dorfbewohner brauchen Eure Hilfe.", progress = nil, completion = "Den Himmlischen sei Dank, dass Ihr das seid! Es ist alles noch viel schlimmer als angenommen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31244] = {title = "Guo-Lai-Lager", objective = "Sprecht mit Leven Morgenklinge in den Guo-Lai-Ruinen.Leven war ganz schön sauer und sagte etwas über Mogu in den Ruinen.\n\nIhr solltet ihn am besten suchen. Leven ist nicht witzig, wenn er sauer ist.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Leven war ganz schön sauer und sagte etwas über Mogu in den Ruinen.\n\nIhr solltet ihn am besten suchen. Leven ist nicht witzig, wenn er sauer ist.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31245] = {title = "Nebelhauch", objective = "Sprecht mit Che Wildmarsch in Nebelhauch.", description = "Che hat auf seinem Weg ins Dorf nach Euch gefragt, aber ich sagte ihm, ich hätte Euch nicht gesehen.\n\nWenn Ihr also wollt, könnt Ihr ihn jetzt aufsuchen. Aber auf diese Weise müsst Ihr Euch nicht verpflichtet fühlen! Das war doch klug bedacht von mir, nicht wahr?", progress = nil, completion = "Ren hat Euch Bescheid gesagt? Er scheint immer so unbekümmert, aber er macht das Richtige, wenn es darauf ankommt. Da kann man ihm keinen Vorwurf machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31246] = {title = "Angriff auf Nebelhauch", objective = "Sprecht mit Rook Steinzeh in Nebelhauch.", description = "Ich sehe Rauch aus dem Dorf aufsteigen. Und dieses Mal ist es nicht meine Schuld!\n\nIhr solltet Euch dorthin aufmachen und Eure Hilfe anbieten.", progress = nil, completion = "Ihr seid hier und wollt Rook helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31247] = {title = "Die Garnison der Untergehenden Sonne", objective = "Sprecht mit Anji Herbstlicht in der Garnison der Untergehenden Sonne.", description = "Anji und Kun haben hier auf dem Weg zur Garnison Rast gemacht. Ein hübsches Paar, findet Ihr nicht? So verschieden und doch so innig miteinander... Ah, wenn ich nur daran denke, geht mir das Herz auf.\n\nSie haben übrigens nach Euch gefragt. Vielleicht wollen sie ja, dass Ihr an ein paar Ausbildungseinheiten teilnehmt? Jedenfalls hoffe ich, dass sie nichts Unanständiges mit Euch vorhaben...", progress = nil, completion = "Ihr kommt gerade rechtzeitig. Ich wollte soeben mit ein paar Rekruten ein paar Ausbildungseinheiten durchgehen. Aber eigentlich interessiert es mich viel mehr, was Ihr zu bieten habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31248] = {title = "Die Guo-Lai-Ruinen", objective = "Sprecht mit Anji Herbstlicht bei den Guo-Lai-Ruinen.", description = "Ich habe Anji und Kun aufgetragen, die Erkundung der Guo-Lai-Ruinen fortzusetzen. Wir haben zwar heute keine Meldungen über die Anwesenheit von Mogu dort erhalten. Aber dennoch scheinen die Ruinen zu den Orten hier im Tal zu zählen, denen ihr größtes Interesse gilt. Vor dem Hintergrund des Angriffs auf das Gebiet am See habe ich die beiden dort auf Patrouille geschickt.\n\nUnd ich möchte, dass Ihr Euch ebenfalls dort einfindet.\n\nBegebt Euch in Richtung Westen am See vorbei bis zu den Ruinen. Anji wird Euch dort weitere Anweisungen geben können.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31249] = {title = "Nebelhauch", objective = "Sprecht mit Che Wildmarsch in Nebelhauch.", description = "Nach allem, was ich gehört habe, ist das Dorf nicht von der Shao-Tien-Offensive betroffen, aber ich möchte kein Risiko eingehen.\n\nIch werde Euch und Che Wildmarsch aussenden, um im Dorf nach dem Rechten zu schauen und den Dorfbewohnern Hilfe anzubieten.", progress = nil, completion = "Ein seltsames Gefühl, vom Kampf abgezogen zu werden. Aber Leven hat recht: Die Dorfbewohner brauchen unseren Schutz. Wir dürfen keine Risiken eingehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31251] = {title = "Besser essen geht nicht!", objective = "Besorgt 160 Kun-Lai-Fleischbrocken.", description = "Ja, ja.\n\nJeder weiß, dass wir Goblins herumbasteln. Und Sprengstoff machen. Und... Nun, Ihr wisst ja bestimmt auch von den unrühmlichen Sachen.\n\nWas aber niemand weiß, ist, dass ich hervorragend kochen kann! Das ist ein Hobby von mir.\n\nBesorgt uns ein paar leckere Stücke Fleisch von den Tieren aus dieser Gegend, und ich werde uns die besten Mahlzeiten zubereiten, die es ÜBERHAUPT gibt!\n\nUnd ich verspreche auch, nur drei oder vier Prozent Raketentreibstoff zu verwenden.", progress = "Die Fleischbrocken, <Name>? Wir brauchen sie!", completion = "Ihr wisst, was man über's Kochen sagt - LFG. Lecker, frisch... und... Geschirr?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31252] = {title = "Zurück zur Westwindruhestätte", objective = "Kehrt zu Landarbeiter Bo in der Westwindruhestätte am Kun-Lai-Gipfel zurück.", description = "Nun, so wie ich die Sache sehe, haben wir viel wiederaufzubauen.\n\nIch bin niemand, der sich einer großen Sache anschließt, aber meine Landarbeiter werden hier nicht viel zu tun haben, um ehrlich zu sein. Und da Ihr ihnen geholfen habt, wollen sie sich Eurer \"Allianz\" anschließen. Warum sollte ich sie also aufhalten?\n\nNehmt sie mit zu Landarbeiter Bo. Sie werden mir zwar fehlen, aber bei Euch sind sie besser aufgehoben.", progress = nil, completion = "Es war das Richtige, diese Jungs mitzubringen. Wir lassen sie für Euch in null Komma nichts etwas zu essen anpflanzen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest - Kun-Lai Summit - Despawn Farmhands\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31253] = {title = "Zurück zur Ostwindruhestätte", objective = "Kehrt zu Landarbeiter Ko in der Ostwindruhestätte am Kun-Lai-Gipfel zurück.", description = "Nun, so wie ich die Sache sehe, haben wir viel wiederaufzubauen.\n\nIch bin niemand, der sich einer großen Sache anschließt, aber meine Landarbeiter werden hier nicht viel zu tun haben, um ehrlich zu sein. Und da Ihr ihnen geholfen habt, wollen sie sich Eurer \"Horde\" anschließen. Warum sollte ich sie also aufhalten?\n\nNehmt sie mit zu Landarbeiter Ko. Sie werden mir zwar fehlen, aber bei Euch sind sie besser aufgehoben.", progress = nil, completion = "Es war das Richtige, diese Jungs mitzubringen. Wir lassen sie für Euch in null Komma nichts etwas zu essen anpflanzen!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest - Kun-Lai Summit - Despawn Farmhands\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31254] = {title = "Die Straße nach Kun-Lai", objective = "Reist über die Verhüllte Treppe nach Binan.", description = "Ah! Seid gegrüßt, Freund von Lehrensucher Cho. Ich habe eine Nachricht für Euch.\n\n<Die merkwürdige kleine Kreatur reicht Euch einen ramponierten Schriftrollenbehälter.>\n\nDer Lehrensucher erwartet Euch in Kun-Lai. Die Reise dorthin ist äußerst gefährlich, oh ja, äußerst gefährlich.\n\nLasst Euch von den Ortskundigen helfen, denen Ihr auf Eurem Weg begegnet.", progress = "Noch mehr Fremde? Dieser Tag bringt mich an meine Grenzen.", completion = "Oh, Ihr seid ein Freund von Cho? Willkommen! Willkommen!\n\nIch würde Euch ein Bankett auftischen, aber wie Ihr sehen könnt, stecken wir momentan in großen Schwierigkeiten.\n\nWürdet Ihr uns vielleicht helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31255] = {title = "Die Straße nach Kun-Lai", objective = "Reist über die Verhüllte Treppe nach Binan.", description = "Ah! Seid gegrüßt, <Freund/Freundin> von Lehrensucher Cho. Ich habe eine Nachricht für Euch.\n\n<Die merkwürdige kleine Kreatur reicht Euch einen ramponierten Schriftrollenbehälter.>\n\nDer Lehrensucher erwartet Euch in Kun-Lai. Die Reise dorthin ist äußerst gefährlich, oh ja, äußerst gefährlich.\n\nLasst Euch von den Ortskundigen helfen, denen Ihr auf Eurem Weg begegnet.", progress = "Noch mehr Fremde? Dieser Tag bringt mich an meine Grenzen.", completion = "Oh, Ihr seid ein Freund von Cho? Willkommen! Willkommen!\n\nIch würde Euch ein Bankett auftischen, aber wie Ihr sehen könnt, stecken wir momentan in großen Schwierigkeiten.\n\nWürdet Ihr uns vielleicht helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31256] = {title = "Treibt sie zusammen", objective = "Treibt 3 Yaks der Wilden Ebenen zusammen und bringt sie zur Ostwindruhestätte.", description = "Lok'tar, <Klasse>.\n\nWir haben Fortschritte gemacht, aber wir müssen beweglich sein, wenn wir uns hier am Kun-Lai behaupten wollen.\n\nIch sehe nicht viele Worgs, Kodos oder dergleichen in dieser Gegend. Was ich aber sehe, sind Yaks. Unsere Pandarenverbündete haben gesagt, dass sie gute Reittiere abgeben, also nehmen wir halt die.\n\nZieht los, treibt ein paar zusammen und bringt sie hierher, damit unsere Leute auf ihnen reiten können!", progress = nil, completion = "Gut gemacht! Nun, ich muss schon sagen, sie sind ziemlich störrisch. Aber sie sollten ausreichen.", rewards = "KafasatinmantelungKafabalgschiftungSchulterschutz des träumenden GeistesBrünierte KafaschiftungSeidene KafaamiciaKafalederschiftungSchulterschutz des YakhirtenSchwere KafaschulternGepanzerte KafaschulternIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31260] = {title = "Meisterprofiteur: Casheen", objective = "Sammelt das Blut der alten Tigerin.", description = "Ich hab' da eine geniale Idee für eine neue Gaunerei!\n\nBei meinem letzten Flug sah ich eine unglaublich alte Tigerin umherstreifen.\n\nWisst Ihr, was für einen Preis ihr Blut auf dem Schwarzmarkt erzielen würde? Und wenn ich dann noch ein paar Hexenmeistern erzähle, dass das Blut ihren Beschwörungszaubern zusätzliche Kraft verleiht...\n\nAlso wenn Ihr mir etwas von ihrem Blut bringt, beteilige ich Euch an der Gaunerei. Zuletzt habe ich die Tigerin auf der anderen Seite des Dojani gesehen.", progress = "Ich hatte mir ja schon überlegt, es selbst mit dieser Tigerin aufzunehmen, aber ich hänge zu sehr an meinem Leben, um ehrlich zu sein...", completion = "Beeindruckend! Riecht Ihr schon das Geld? Hier ist Euer Anteil.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDaggle Sprengschreiter beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31261] = {title = "Kapitän Jack ist tot", objective = "Bringt Kapitän Jacks Kopf zu Häuptling Kah Kah in Flotschhügel.\n\nBereitgestellter Gegenstand: \n", description = "Halb geronnenes Blut tropft aus Kapitän Jacks Kopf auf den Boden und versiegt dort, als Ihr Eure hart erkämpfte Trophäe begutachtet.\n\nSeltsam, aber Ihr habt jetzt keine Zeit, das zu untersuchen. Zu viel Arbeit muss erledigt werden.\n\nDer Häuptling Eurer neuen Freunde wird sicherlich beeindruckt sein von diesem Beweis Eurer Flotschfähigkeiten.", progress = nil, completion = "Verfiddelter Flotsch, Nappel!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31262] = {title = "Kranichbeherrschung: Dolchschnabel", objective = "Holt Euch den Dolchschnabel.", description = "Nun, da Ihr ein Gespür für den Kampfstil des Kranichs entwickelt habt, werdet Ihr es mit einem echten Prachtexemplar zu tun bekommen.\n\nDolchschnabel!\n\nZumindest nenne ich den Burschen so. Ist der größte Kranich, den ich je gesehen habe. Und sein Schnabel ist messerscharf.\n\nNordwestlich von hier befindet sich ein großer Wasserfall, aus dem der Dojani entspringt. Dolchschnabel hält sich meistens in der Nähe dieses Wasserfalls auf.\n\nWenn Ihr mir seinen Schnabel als Trophäe bringt, lege ich bei Nesingwary ein gutes Wort für Euch ein.", progress = "Ich habe gesehen, wie dieser Vogel einem Tiger das Gesicht durchbohrt hat. Wo bitteschön sind wir hier, wenn Tiger zur Beute von Vögeln werden?", completion = "Na DAS nenne ich mal eine Trophäe. Sieht ziemlich einschüchternd aus. Moment... klebt da etwa Euer Blut dran?", rewards = "Gürtelbund des DojaniKorjanigürtelbundSarjungürtelFlussklingengürtelbundAngkhalgürtelbundNarsonggürtelbundTiefwildgürtelTodesrachengürtelbundNayeligürtelbundDer folgende Zauber wird auf euch gewirkt:\n\nDaggle Sprengschreiter beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31265] = {title = "Mazus Atem", objective = "Trinkt den Trank aus Mazus Atem.", description = "Ihr seid also hier, um zu helfen, ja? Na, eins nach dem anderen.\n\n<Arie durchwühlt kurz ihre Taschen und bringt eine kleine Phiole mit einer leuchtenden blauen Flüssigkeit zum Vorschein.>\n\nHier ist es! \"Mazus Atem\". Nach einer Rezeptur des Käpt'n.\n\nWas? Ihr dachtet, ich würde Euch ohne Atemhilfe auf See schicken? Ich brauche Deckhelfer, keine Leichen!\n\nRunter damit, Grünschnabel. Damit habt Ihr dort draußen auf dem Riff eine reelle Chance.", progress = "Nein, ich habe nichts zum Runterspülen. Trinkt einfach aus!", completion = "Ihr werdet mir noch danken.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31266] = {title = "Einfall der Mogu", objective = "Findet und tötet den Spionagemeister der Shan'ze.", description = "Wir haben Berichte über mehrere Mogugruppen erhalten, die hier in Tonlong an der Küste eingefallen sind. Ich habe keine Ahnung, was sie hier tun, und ganz ehrlich: Es ist mir auch egal.\n\nIhr habt Euch bewiesen, daher wollen wir Euch diese Mission anvertrauen.\n\nFolgendes wird passieren: Ihr zieht los, findet sie und tötet sie alle.\n\nUnsere Späher haben gemeldet, dass die erste Gruppe Richtung Norden gelandet ist, zwischen hier und dem Plateau des Totensprechers. Geht dorthin und schaltet sie aus.", progress = "Warum sind sie noch nicht tot?", completion = "Es war nur eine Ablenkung! Sie machen sich bereit, den Niuzaotempel anzugreifen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31267] = {title = "Die Vernichtung der Nebelklingen", objective = "Tötet 6 Reißer der Nebelklingen.", description = "Korven hat mir erzählt, was er herausgefunden hat. Auf dem Grund des Sternensees gibt es eine gewaltige Bernablagerung.\n\nLeider lebt am Ufer des Sees ein feindseliger Saurokstamm, der den Bern als sein Eigentum betrachtet.\n\nSeine Angehörigen werden uns nicht einfach so in ihr Gebiet vordringen lassen.\n\nBegebt Euch nach Süden zum See. Tötet die Nebelklingensaurok, damit wir den Bern in der Nähe leichter abtragen können.", progress = nil, completion = "Gut gemacht. Mit diesem Bern können wir Waffen für unsere Sache fertigen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31268] = {title = "Kleine, graue Zellen", objective = "Sammelt 3 bernverkrustete Gehirne von Bernstechern der Ik'thik.", description = "Tief im Süden brütet der Schwarm Vernichtungswaffen aus - riesige Bernskorpione, die so gut wie unzerstörbar sind.\n\nWie alle anderen Kreaturen sind auch sie manipulierbar, im Gegensatz zu anderen Kreaturen haben sie sich aber noch nicht meiner Gedankenkontrolle unterworfen.\n\nWie es scheint, muss ich weitere Forschungen betreiben, ehe es mir gelingt, sie für unsere Zwecke zu beherrschen.\n\nIch muss ihre Gehirne untersuchen, und Eure Aufgabe ist es, mir ein paar Exemplare zu besorgen.\n\nNehmt diesen Schallemitter. Er hat sich als ziemlich wirksam gegen die Biester erwiesen.", progress = "Sie widersetzen sich weiterhin meiner Schallmanipulation. Ich muss herausfinden, weshalb.", completion = "Sieh mal einer an, wie interessant. Sie sind anders als alle anderen Gehirne, die ich gesehen habe.\n\nIch werde sie genau untersuchen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31269] = {title = "Der Schuppenlord", objective = "Tötet den Schuppenlord der Nebelklingen.", description = "Die Saurok am Sternensee empfangen ihre Befehle von ihrem Schuppenlord, einem grausamen, gnadenlosen Anführer, der sein Revier erbittert bewacht.\n\nWenn es uns gelingt, diesen Anführer auszuschalten, erhalten wir Zugriff auf die gewaltige Bernader unter dem See.\n\nGeht. Ihr Anführer erteilt seine Befehle von seinem unterirdischen Sitz am südlichen Seeufer aus.", progress = "Ist es vollbracht?", completion = "Gut. Freut mich zu hören, dass er tot ist.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31270] = {title = "Der Kampf gegen die Angst", objective = "Tötet 15 Schreckensschuppenskorpide.", description = "Als wir den Einfluss des Sha bei Kypari Zar bemerkten, hatte ich gehofft, die Verderbnis könnte noch geläutert werden.\n\nLeider hat der Rat der Klaxxi bestätigt, dass die Verderbnis des Sha der Angst tief verwurzelt ist und sich weiter ausbreitet.\n\nIm Süden habe ich beobachtet, wie ein Teil der heimischen Tier-und Pflanzenwelt von einem namenlosen Schrecken ergriffen wurde.\n\nDas Sha kann seine Opfer zu furchtbar abscheulichen Kreaturen verzerren.\n\nWir müssen der Verderbnis Einhalt gebieten, bevor sie noch schlimmer wird. Sucht die Sha-verseuchten Schreckensschuppenskorpide. Vernichtet sie.", progress = nil, completion = "Ihr habt die Hügel von den verseuchten Kreaturen befreit? Gut.\n\nDas Sha ist ein gnadenloser Gegner. Also dürfen auch wir ihm keine Gnade zeigen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31271] = {title = "Schlechte Gene", objective = "Tötet 3 Genomanten der Ik'thik und 6 Eierdrohnen der Ik'thik.", description = "Tief im Süden, <Erwecker/Erweckerin>, führen die Genomanten der Kaiserin ihre finsteren Experimente durch. (Finster, mag schon sein, aber nicht so finster wie meine!)\n\nSie sezieren und verändern die wilden Tiere der Umgebung und erzeugen Kreaturen nach eigenem Gutdünken. (Ihre Entwürfe werden bald meine Entwürfe sein!)\n\nDas dürfen wir nicht zulassen! (Nein, nein! Solche Macht steht nur mir zu!)\n\nIhre Mutationen werden bereits im Krieg eingesetzt. Geht los! Zerstört sie um jeden Preis!", progress = nil, completion = "Ja, ja! Sie sind tot!\n\nDanke, Erwecker. Das habt Ihr gut gemacht.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31272] = {title = "Ansteckung", objective = "Tötet 6 infizierte Wildtiere. Infizierte Wildtiere sind Knochenstaubmotten, Blauhautmushan und mutierende Skorpide.", description = "Die Genomanten der Kaiserin spielen mit gefährlichen Spielzeugen.\n\nWeiter im Süden injizieren sie den hiesigen Tieren pheromonhaltige Parasiten, um monströse Mutationen für den Krieg zu erschaffen.\n\nSie waren so nachlässig, dass ihre parasitären Würmer in das örtliche Ökosystem entkommen konnten.\n\nWenn nichts dagegen unternommen wird, breitet sich die Infektion so lange von Tier zu Tier aus, bis wir es mit einer Seuche zu tun haben.\n\nIch werde Euch ein schwaches Toxin injizieren, mit dem Ihr in der Lage sein werdet, angesteckte Kreaturen zu identifizieren.\n\nTötet die Träger auf der Stelle.", progress = nil, completion = "Die Infektion hatte sich also schon ausgebreitet. Wie es scheint, konntet Ihr die Verbreitung gerade noch stoppen.\n\nIch glaube nicht, dass die Genomanten ihre haarsträubenden Experimente einstellen werden, wir müssen ihre Anstrengungen jedoch weiter vereiteln.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nPheromonfährtensuche abbrechen\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31274] = {title = "Raid Finder (1st)", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31275] = {title = "Raid Finder (Nth)", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31277] = {title = "Überraschungsangriff!", objective = "Trefft Euch mit Ban Bärenherz am Niuzaotempel in der Tonlongsteppe und setzt der dortigen Moguinvasion ein Ende.", description = "Diese abscheulichen Mogu...\n\nDie Späher waren nur ein Ablenkungsmanöver! Während wir ihre Spione jagten, griff ihre Hauptstreitmacht den Niuzaotempel an. Verderbte Schlangen, überall Mogu... das ist eine Katastrophe!\n\nGlücklicherweise konnte Ban ihre Linien mit den Elitemitgliedern unseres Ordens durchdringen. Wenn dieses Kunststück auch Euch gelingt, stoßt zu ihm. Wir müssen dem ein Ende setzen!", progress = nil, completion = "Niuzao ist gerettet. Die Mogu wurden zurückgeschlagen. Und Ihr, mein Freund, Ihr habt Euch einer großen Ehre als würdig erwiesen. \nWir werden Euch in die Reihen der Shado-Pan aufnehmen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest - Shado-Pan Finale - Summon Induction Scene Bunny\n\nIhr bekommt:\n\nZügel der Onyxwolkenschlange"}
MultiLanguageQuestData['de'][31278] = {title = "Anleitung zur Questerstellung", objective = "Erstellt eine Schnitzeljagdquest.Juchu! Ihr dürft eine Schnitzeljagdquest erstellen! Findet heraus, was als Nächstes zu tun ist.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Juchu! Ihr dürft eine Schnitzeljagdquest erstellen! Findet heraus, was als Nächstes zu tun ist.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "GlasseekopfbedeckungBeinplatten der absoluten KlarheitIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31279] = {title = "Alles, was ich übers Kochen weiß", objective = "Überbringt Sungshin Eisentatz den Brief. Sie unterrichtet auf dem Halbhügelmarkt.", description = "Ich bin so froh, dass Euch mein Essen schmeckt. Wärt Ihr vielleicht an den Rezepten interessiert? Falls ja, solltet Ihr sie aus erster Hand von meinen Lehrern vom Halbhügelmarkt lernen. Alles, was ich über die Küche weiß, habe ich bei ihnen gelernt.\n\nUnd wenn Ihr sowieso in diese Gegend kommt, könntet Ihr dann vielleicht Sungshin Eisentatz diese Nachricht überbringen? Sie war meine Lieblingslehrerin. Ich vermisse sie, und ich möchte, dass sie das auch weiß.", progress = "Ihr habt einen Brief für mich?", completion = "Oh, wie aufmerksam. Ich höre immer sehr gerne von meinen ehemaligen Schülern.", rewards = "Ihr bekommt:\n\nEisentatzmarke"}
MultiLanguageQuestData['de'][31280] = {title = "Wie man kocht", objective = "Erlernt die Rezepte für gegrilltes Tigersteak, gebratenen Reis nach Jadewaldart, verwirbelte Nebelsuppe, Garnelenklößchen, Wildgeflügelbraten und Ginsengtee von den Meistern auf dem Halbhügelmarkt.", description = "Es gibt viele Arten, zu kochen, und jede Methode erschafft einzigartige Gerichte. Die pandarischen Wege des Kochens sind der Weg des Grills, des Woks, des Topfes, des Dampfgarers, des Ofens und des Brauens. Es scheint, als ob Ihr durch Eure Erfahrungen in fernen Ländern bereits die Grundlagen eines jeden Weges beherrscht. Falls Ihr wünscht, noch weiter ausgebildet zu werden, sprecht mit meinen Geschwistern und erlernt das erste fortgeschrittene Rezept, dass jeder von ihnen lehrt. Findet heraus, welcher Weg am besten zu Euch passt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEisentatzmarke"}
MultiLanguageQuestData['de'][31281] = {title = "Ihr wollt also Koch werden…", objective = "Erlernt das Rezept für einen Pfirsich in Scheiben von der Weiserin der Wege und bereitet ihr 5 von ihnen zu.", description = "Ihr wollt <Koch/Köchin> werden? Wenn Ihr wirklich Eure volle Hingabe beweist, kann ich Euer verborgenes Potenzial verwirklichen, egal, wie unerfahren Ihr seid.\n\nWenn Ihr etwas von mir lernen wollt, dann zeigt mir, dass Ihr zumindest einfachen Anweisungen folgen könnt. Lernt, wie man einen Pfirsich in Scheiben schneidet und zeigt mir dann, was Ihr gelernt habt. Ich kann Euch frische pandarische Pfirsiche zu einem guten Preis verkaufen.", progress = "Beweist mir, dass Ihr Anweisungen folgen könnt.", completion = "Nun gut. Ihr seid in der Lage, etwas zu lernen. Ich kann Euch viel beibringen, und ich habe die meisten Zutaten, die Ihr braucht, um etwas zu lernen. Ihr könnt Euch von mir unterrichten lassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31285] = {title = "Die Frühlingsbummler", objective = "Überlebt eine Fahrt mit der Frühlingsbummler.", description = "Wer auf eine Begegnung mit ein paar Saurok verzichten möchte, sollte die Uralte Passage nicht zu Fuß bereisen.\n\nIch mache Euch ein Angebot: Eierschale und ich wollten gerade flussaufwärts nach Binan aufbrechen. Sollen wir Euch mitnehmen?", progress = nil, completion = "Puh... Das wäre geschafft. Willkommen in Binan.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31286] = {title = "Beraubung der Räuber", objective = "Holt 7 Schwarzmarktwaren zurück.", description = "Ah, <Klasse>. Ich hätte da gerade Verwendung für Eure Fähigkeiten.\n\nOben an der Straße wurde ein Konvoi von einer Bande marodierender Saurok angegriffen. Die Räuber haben ein paar... Waren... entwendet, die Madame Goya veräußern wollte.\n\nEs gleicht einem Sakrileg, Madame Goya zu bestehlen.\n\nWenn es Euch gelingen sollte, diese Waren zurückzuholen, werde ich Euch gerne einen Finderlohn zahlen.", progress = "Die Saurok sind normalerweise nicht so dreist.", completion = "Ah, unsere Waren. Madame Goya wird sehr zufrieden sein. Ihr könnt Euch ihrer Dankbarkeit gewiss sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31287] = {title = "Erziehungsprogramm für die Saurok", objective = "Liquidiert Saugfinger.", description = "Die Lenzstraße untersteht dem Schutz unserer verehrten Madame Goya.\n\nUnd um diese Tatsache zu verdeutlichen, scheinen die Saurok im Hassschuppenbau nordöstlich von hier ein \"Erziehungsprogramm\" zu benötigen. Wir haben sie bereits in der Vergangenheit gewarnt, aber offensichtlich haben sie leider ein kurzes Gedächtnis.\n\nBegebt Euch zu ihrem Bau im Nordosten und findet ihren Schamanenanführer. Wenn es Euch gelingt, ihn zu liquidieren, ist Euch der Dank unserer verehrten Dame gewiss - neben einem angemessenen Kopfgeld, versteht sich.", progress = nil, completion = "Die Aufgabe wurde erfüllt und Schuld muss bezahlt werden. Hier ist Eure Belohnung. Seid Euch unseres Dankes gewiss.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31288] = {title = "Forschungsprojekt: Die Mogudynastien", objective = "Bergt 20 archäologische Fragmente der Mogu.", description = "Ah, <ein Entdecker/eine Entdeckerin> - Ihr kommt gerade recht. Ich stehe nämlich kurz davor, einige der dunklen Geheimnisse der Mogu aufzudecken.\n\nAllerdings nicht alle. Sie haben nämlich viele dunkle Geheimnisse. Aber zumindest bin ich ganz kurz davor, zumindest eines der vielen dunklen Geheimnisse aufzudecken.\n\nWenn Ihr also auf Euren Reisen über Mogufragmente stolpert, dann bringt sie mir. Ich werde mich dafür auch erkenntlich zeigen.", progress = "Es ist gefährlich, die Vergangenheit zu ignorieren.", completion = "Ah! Das sind ein paar sehr schöne Stücke. Wirklich sehr schön. Ich danke Euch, Abenteurer.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31289] = {title = "Forschungsprojekt: Das Pandaren-Reich", objective = "Bergt 20 archäologische Fragmente der Pandaren.", description = "Ah, gut, dass Ihr gerade da seid, <Abenteurer/Abenteurerin>. Meine Tochter und ich erforschen nämlich gerade die Historie unseres Volkes und kommen an einer Stelle nicht so recht weiter.\n\nSolltet Ihr auf antiquarische Pandarenobjekte stoßen, dann bringt sie uns bitte. Wir würden einen großen Vorteil aus solchen zusätzlichen Informationen ziehen können.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31291] = {title = "Die Geheimnisse der Vergangenheit", objective = "Setzt 1 Artefakt aus Pandaria wieder zusammen.", description = "Seid Ihr daran interessiert, auch <ein Lehrensucher/eine Lehrensucherin> zu werden? Dann stellt Euch auf viel Graben und viel Lesen und noch mehr Graben und noch mehr Lesen ein.\n\nIch verbringe ganze Tage damit, auf zerbrochene Vasen zu starren und zu überlegen, wie man sie wieder zusammensetzen kann.\n\nAber probiert es ruhig aus. Wenn Ihr eines der Artefakte aus Pandaria vollständig zusammensetzen könnt, wären wir Euch verbunden, wenn Ihr dieses Wissen mit uns teilen könntet.", progress = "Ich frage mich, ob ich wirklich genug Talent dafür habe.", completion = "Großartig! Ihr habt die Teile fast nahtlos zusammenfügen können. Die Qualität dieser Restaurierung ist ja überragend.\n\nWie habt Ihr das hinbekommen?", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31293] = {title = "Mogu keine guten Gäste", objective = "Tötet 8 Shao-Tien-Angreifer in Nebelhauch.", description = "Leven hat Rook hierher geschickt, um Mogu aufzuhalten. Sind aber mehr Mogu als Rook töten kann.\n\nHelft Ihr? Rook erzählt Leven auch von Eurer Hilfe. Versprochen.", progress = nil, completion = "Rook kommt jetzt mit restlichen Mogu klar. Danke für Hilfe, guter Mann.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31294] = {title = "Die Guo-Lai-Ruinen", objective = "Sprecht mit Anji Herbstlicht bei den Guo-Lai-Ruinen.", description = "Ich danke Euch von ganzem Herzen für Eure Hilfe. Anji wartet in den Guo-Lai-Ruinen im Nordwesten auf Euch.\n\nBitte begebt Euch dorthin. Und möge Euch Euer Mut niemals verlassen, <junger/junge:c> <Klasse>.", progress = nil, completion = "Che hat Euch geschickt? Gut, dass Ihr da seid.\n\nIn den Ruinen wimmelt es nur so von Dingen, die zertreten werden wollen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31295] = {title = "Mogu in den Guo-Lai-Ruinen", objective = "Sprecht mit Leven Morgenklinge in den Guo-Lai-Ruinen.", description = "Danke für Eure Hilfe.\n\nIch würde Euch gern weiterhin Gesellschaft leisten, aber Leven führt einen Angriff gegen die Mogu in den Guo-Lai-Ruinen nordwestlich von hier. Und er kann jeden fähigen Kämpfer gebrauchen.\n\nMögen die Himmlischen Euch beschützen, <junger Mann/junge Dame>.", progress = nil, completion = "Gut, dass Ihr da seid.\n\nIch weiß nicht, wie die Mogu so viele Truppen versammeln konnten, aber wir müssen sie angreifen, bevor sie ihren Vorstoß wagen können.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31296] = {title = "Die Guo-Lai-Ruinen", objective = "Sprecht mit Anji Herbstlicht bei den Guo-Lai-Ruinen.", description = "Die Dorfbewohner scheinen in Sicherheit zu sein und die Mogu werden langsam zurückgedrängt. Den Rest sollten wir selbst erledigen können. Danke für Eure freundliche Hilfe, <Name>.\n\nAnji hat heute morgen eine Gruppe zur Erkundung und Befreiung der Guo-Lai-Ruinen in den Nordwesten geführt. Sicherlich könnte sie dort jemanden mit Euren Talenten gebrauchen. Ihr solltet sie aufsuchen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31297] = {title = "Die Garnison der Untergehenden Sonne", objective = "Sprecht mit Anji Herbstlicht im Ausbildungslager der Untergehenden Sonne.", description = "Die Mogu werden diesen Angriff nicht lange aufrechterhalten können. Von jetzt an sollten wir die Situation in den Griff bekommen. Danke für Eure freundliche Hilfe.\n\nAber vielleicht könnt Ihr ja Anji im Ausbildungslager der Untergehenden Sonne aufsuchen? Sie ist damit beauftragt, die Pandarenrekruten auszubilden. Und Ihr könntet ihnen wohl auch noch ein oder zwei Dinge beibringen.", progress = nil, completion = "Mit Euch kann man arbeiten. Dann zeigen wir diesen Auszubildenden mal, wie ein echter &lt;Klasse&gt; kämpft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31302] = {title = "Bereit für Großes", objective = "Bereitet 5 Schüsseln Milchreis zu und gebt sie der Gewährerin der Einblicke.", description = "Ihr scheint Euch in der Küche ziemlich gut auszukennen. Zeigt mir, was Ihr könnt, indem Ihr 5 Schüsseln Milchreis zubereitet.", progress = "Ich glaube, Ihr habt das Zeug zu einem großen Koch, doch erst der Milchreis wird meine Einschätzung bestätigen.", completion = "Ihr seid bereit. Ihr seid nun ein Zen-Meisterkoch.", rewards = "Ihr erlernt:\n\nZenmeister der Kochkunst\n\nDer folgende Zauber wird auf euch gewirkt:\n\nZenmeister der Kochkunst\n\nIhr bekommt außerdem:\n\nEisentatzmarke"}
MultiLanguageQuestData['de'][31303] = {title = "Das Siegel ist zerbrochen", objective = "Versiegelt 12 Risse des Sha und verbannt das Sha des Zweifels.", description = "<Cho sieht Euch ungläubig an.>\n\nIch... Ich glaubte, Sha von dieser Größe seien ein Mythos - wir alle glaubten das. Wir hielten sie für ein Ammenmärchen, um den Kindern das Kämpfen auszutreiben.\n\nAber für Geplauder bleibt jetzt keine Zeit. Diese Risse, sie nähren es... und machen es jeden Augenblick stärker!\n\nIch muss diese Schriftrollen aus meinen Familienarchiven untersuchen. Ihr, nehmt diese Kanone und reitet Mishi.\n\nIhr müsst einen Weg finden, diesem Schrecken zu begegnen, der auf uns losgelassen wurde!", progress = nil, completion = "Ich muss viele Nachforschungen in nur wenig Zeit erledigen.\n\nDie Nachricht des Kaisers warnte nur vor einer einzigartigen Gefahr, die diesem Land Krieg bringen würde - dieses… Sha.\n\nLeider ist die Zeit, seinen Rat zu beherzigen, bereits vorüber. Wie wir nun dieser Krise ein Ende bereiten können, darüber schweigt das Omen des Kaisers.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31305] = {title = "Der Weg des Grills", objective = "Bereitet ein Hühnchenspieß mit Erdnusssoße zu und gebt es dem Meister des Grills.", description = "Wenn Ihr Essen kocht wollt, dass Euch stärker macht, sucht den Meister des Grills auf. Bereitet für ihn ein Hühnchenspieß mit Erdnusssoße zu, um ihm zu zeigen, dass Ihr die Grundlagen beherrscht.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31306] = {title = "Pfad des Unwissenden", objective = "Bewältigt den Pfad des Unwissenden, um Euch mit dem Lehrensucher Cho zu treffen. Macht an allen Schreinen entlang des Weges Halt, um Euch dort auf Eure Gedanken zu konzentrieren.", description = "Ich bin mir ziemlich sicher, dass Euer Pandaren-Freund eine Ahnung hat, wonach die Mogu eigentlich suchen.\n\nEr hat sich vor ein paar Tagen ohne Bergführer ins Gebirge aufgemacht und gesagt, dass nur Ihr ihm folgen sollt. Er hatte sich sehr klar ausgedrückt:\n\n\"<Der/Die:c> <Klasse> muss diesen Pfad allein beschreiten, vollkommen konzentriert auf <seine/ihre> eigenen Gedanken. <Er/Sie> soll jedem Schrein die Ehre erweisen, bevor wir uns am Gipfel wiedersehen.\"\n\nDer Pfad beginnt gleich nordwestlich des Lagers und ist durch Flaggen gekennzeichnet. Aber passt gut auf Euch auf! Der Pfad des Unwissenden ist selbst an den harmlosesten Tagen noch gefährlich.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31308] = {title = "Erste Erfahrungen", objective = "Gewinnt einen Haustierkampf.", description = "Da Ihr nun <Tierausbilder/Tierausbilderin> seid, ist es an der Zeit, Euer Können auf die Probe zu stellen!\n\nGeht hinaus in den Wald und beginnt einen Kampf mit einem Kampfhaustier. Vergesst nicht, Eure Fertigkeit 'Haustiere aufspüren' einzusetzen, damit Ihr kampfbereite Haustiere auf der Minikarte sehen könnt. Kommt wieder zu mir, nachdem Ihr gewonnen habt, dann setzen wir Eure Ausbildung fort. Viel Glück!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31309] = {title = "Auf dem Wege der Besserung", objective = "Stattet Erma der Stallmeisterin einen Besuch ab und heilt Eure Tiere vollständig.", description = "Nachdem Ihr nun einen Kampf gewonnen habt, müssen wir Eure Haustiere heilen, damit sie wieder einsatzbereit sind! Sucht unsere Stallmeisterin Erma auf, um Eure Haustiere zu heilen und wiederzubeleben.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31311] = {title = "Weg des Grills", objective = "Bringt 5 rohe Tigersteaks zum Meister des Grills.", description = "Der Weg des Grills der Pandaren bringt Gerichte hervor, die Eure körperliche Stärke erhöhen. Bringt einige rohe Tigersteaks zum Meister des Grills und er wird Euch beibringen, was Ihr mit ihnen anstellen könnt. Es gibt viele Tiger im Jadewald und der Krasarangwildnis, aber Ihr könnt sie auch anderswo finden.", progress = "Wenn Ihr den Weg des Grills lernen wollt, bringt mir zunächst ein paar rohe Tigersteaks.", completion = "Exzellente Stücke.", rewards = "Ihr erlernt:\n\nWeg des Grills\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWeg des Grills\n\nIhr bekommt außerdem:\n\nRohes TigersteakEisentatzmarke"}
MultiLanguageQuestData['de'][31312] = {title = "Die alte Karte", objective = "Zeigt Fischi Rohrroder am Rohrkolbensee oder auf dem Halbhügelmarkt im Tal der Vier Winde die Karte.\n\nBereitgestellter Gegenstand: \n", description = "Das alte, verblichene Leder fällt fast auseinander, ist aber immer noch lesbar.\n\nJemand scheint eine Art Karte darauf gezeichnet zu haben... und die folgenden Worte:\n\n\nTief in dem Tal, wo die Vier Winde wehen,\nlacht die Jungfer hinter ihrem güldenen Fächer.\nZu Füßen der Treppe ihrer Ahnen,\nflüstert sie ihr Geheimnis in die hallende Nacht.", progress = nil, completion = "Boah! Ich glaube, Ihr habt sie gefunden, &lt;Name&gt;! Ihr habt die Karte zum Schatz des alten Distel gefunden!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31313] = {title = "Nur eine Volkserzählung", objective = "Sprecht mit Korntrenner Pei, Steinmeißler Mac, Mama Min und dem alten Herrn Weißbart.", description = "Was!?! Das ergibt doch überhaupt keinen Sinn! <Fischi macht einen enttäuschten Eindruck.>\n\nWas soll dieses ganze Kauderwelsch von einer Jungfer, einem Ahnen und irgendeiner Treppe?\n\nIch werde daraus einfach nicht schlau... Ihr vielleicht?\n\nNun, es gibt hier eine Menge Leute, die sehr viel älter als Ihr und ich sind, <Name>.\n\nKönnt Ihr vielleicht mit den Bewohnern von Halbhügel sprechen? Ich könnte wetten, dass sie etwas wissen!", progress = nil, completion = "Natürlich! Das ergibt absolut Sinn. Der Schatz muss also an der Stelle liegen, wo der See an die Berge angrenzt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31314] = {title = "Der Schatz des alten Distel", objective = "Findet den Höhleneingang und holt Euch den Schatz des alten Distel.", description = "Na Donnerwetter! Das entwickelt sich ja zu einer waschechten Schatzsuche!\n\nEs muss im Norden eine Art Eingang oder Öffnung geben... an der Stelle, wo die Berge und der Rohrkolbensee zusammentreffen.\n\nWir treffen uns beim Eingang! Dieser Schatz gehört uns!", progress = "Wenn ich's nicht mit eigenen Augen sehen würde, wär' es kaum zu glauben!", completion = "Der Deckel der Kiste lässt sich durch einen leichten Schubser herunterschieben. Ihr blickt in die Kiste...", rewards = "Ihr bekommt:\n\nSchatz des alten Distel"}
MultiLanguageQuestData['de'][31315] = {title = "Das Kernlanderbe", objective = "Bringt den Almanach des alten Distel zu Saatwärterin Shing Sing in Halbhügel im Tal der Vier Winde.", description = "Ganz unten in der Schatzkiste findet Ihr einige Schriftrollen und einen weichen Lederbeutel mit Samen.\n\nWenn Ihr die Schriftrollen ausbreitet, seht Ihr darauf detaillierte Notizen zum Landbau, Zeichnungen von Pflanzen, Zahlen und Berechnungen, Positionen nahe gelegener Wasserquellen und einige andere Informationen.\n\nVielleicht interessiert sich ja jemand bei dem Bund der Ackerbauern dafür.", progress = "Was habt Ihr da?", completion = "Ach ja, ich kenne die Geschichte des alten Distel ziemlich gut, &lt;Volk&gt;.\n\nÜber seine Schatzsuche gibt es jede Menge verrückte Erzählungen.\n\nTatsächlich war er aber so etwas wie ein Einsiedler... exzentrisch und dabei auch ein hervorragender Bauer.\n\nAn seinem Lebensabend zog er sich in die Berge zurück und ward nie wieder gesehen.\n\nEr war trotz allem einfach nur ein Mann, der sein Leben lebte, und wie es scheint, habt Ihr sein Vermächtnis gefunden.\n\nErzählt Fischi nicht die Wahrheit. Manche der besten Geschichten sind größer als das Leben, von dem sie erzählen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31316] = {title = "Julia, die Tierzähmerin", objective = "Besiegt Julia Stevens in einem Haustierkampf.", description = "Wie ich sehe, habt Ihr Eure Fertigkeiten im Haustierkampf verbessert, <Name>. Ich glaube, Ihr seid reif für eine echte Herausforderung.\n\nIhr findet Julia Stevens in den Weinbergen der Maclures, südlich von Sturmwind. Sie ist eine aufstrebende Wildtierzähmerin und ich finde, Ihr solltet Euch mit ihr im Kampf messen!", progress = "Wie sieht es mit Eurer Mannschaft aus? Ich habe schon zwei Schlangen!", completion = "Ihr könnt besser mit diesen Tierchen umgehen, als ich dachte!", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31319] = {title = "Notfallplan", objective = "Benutzt Chos Feuerwerk in der Nähe von Admiral Taylor, Mishka und Sully.", description = "Eure Kameraden haben sich in unseren Landen eine neue Heimat errichtet und einen gefährlichen Zwist mit sich gebracht.\n\nDas volle Ausmaß der Vernichtung können wir hier noch nicht abschätzen, doch bereits jetzt ist es… unaussprechlich.\n\nUnd doch, Eure Freunde aus Rachegefühlen sich selbst zu überlassen, würde unserer Art zu leben widersprechen. Jeder, der jetzt noch am Leben ist, ist zweifelslos verwundet und bedarf dringend Hilfe.\n\nDieses Feuerwerk war eigentlich dazu gedacht, die Fertigstellung der Statue zu feiern. Benutzt es in der Nähe Eurer Kameraden, um Mishi ein Zeichen zu geben, und sie wird sie in Sicherheit bringen.", progress = nil, completion = "Mit meinen Gedanken bin ich bei Euren gefallenen Begleitern, Reisender.\n\nMögen ihre Wunden gut heilen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMomo Appears Cloud\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31320] = {title = "Einen Drink für einen Fisch?", objective = "Bringt Jogu dem Betrunkenen 1 Vier-Winde-Soju. Vier-Winde-Soju kann von den meisten Schankkellnern in Pandaria erworben werden.", description = "Heeee, Ko...Kollege... Wie läuft's denn so? Wo...wollt Ihr 'nem Ji...inyu nich' was zu trink'n ka...kauf'n?", progress = "Durstig...", completion = "Da...anke, K...Kumpel.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31321] = {title = "Eine Runde für einen Fisch?", objective = "Bringt Jogu dem Betrunkenen 5 Flaschen Pandarenpflaumenwein. Pandarenpflaumenwein kann von den meisten Schankkellnern in Pandaria erworben werden.", description = "Heyyy, das is' doch mei... <mein Freund/meine Freundin>!\n\nIhr ha...abt mich wohl hier ru...umhäng'n seh'n. Ihr mü...müsst a...aber wiss'n, dass ich nich' be...betrunk'n bin.\n\nIch mein'... se...seht mich doch mal an! Nü...nüchtern wie ein Sü...Süßwasserfisch!\n\nKlar, ich ertränk' meine So...org'n hier u...und da mal in 'nem gu...ut'n Gebräu, a...aber 'nen Jinyu kri...iegt Ihr nich' besoff'n! Kö...Könntet gena...ausogut versuch'n, 'n Fi...isch zu ertränk'n!\n\nNö, vo...von dem Gebr...äu werd' ich immer nur schl...schläfrig. Un' da...ann hab' ich Visio'n von der Zu...ukunft.\n\n\n\nJe stä...ärker das Gebräu, desto stä...ärker meine Träu...Träume! Bringt m...mir was zu schluck'n, un' i...ich schuld' Euch w...was.", progress = "Was meint Ihr mit \"Ihr lallt wie ein Betrunkener\"? S...So sprech' ich i...immer!", completion = "Oooh, da...das is' gutes Zeug...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31322] = {title = "Ein Fässchen für einen Fisch?", objective = "Bringt Jogu dem Betrunkenen 10 Flaschen Jadehexenbräu. Jadehexenbräu kann durch Kochkunst hergestellt werden.", description = "Meine Träu... meine Träume si...ind in letzter Zeit so... fa...arblos, <Volk>.\n\nIch bra...auch' was Kräftiges, damit ich wieder... a...auf die B...Beine komm'!\n\nIch hab' gehört, e...es gibt da so 'nen le...leckeren Trunk, den die Leu...Leute heutzutage zusamm'nbrau'n.\n\nEs heißt Ja...Jadehex'nbräu.\n\nWürd' ich ge...ern mal... probier'n.", progress = "Glück gehabt?", completion = "Oooh, da...das haut ja zi...iemlich rein! Ich we...werd' schon ganz schl...schläfrig...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31323] = {title = "Eine Brauerei für einen Fisch?", objective = "Bringt Jogu dem Betrunkenen 20 wahnsinnige Brauerfrühstücke. Wahnsinnige Brauerfrühstücke können durch Kochkunst hergestellt werden.", description = "Allso, <Name>, damit ich auch in Zu...ukunkft noch Visionen ha...ab'n kann, brauch' ich... meine eig'ne Bra...auerei.\n\n...\n\nIch m...mach doch nur Spaß! Hättet ma...al Euren Gesi... Gesichtsausdruck seh'n soll'n! Einfach he...errlich... hicks!\n\nJed'nfalls hab' ich von n...nem Gebräu gehört, da...as anders sein soll als alle and'ren. Das... wü...ürd' ich gern mal... probier'n.\n\nHabt Ihr schon vom... Wa...ahnsinnig'n Brauerfrühstück gehört? Wenn... Wenn Ihr mir von de...em Zeug was bringt, sind wir Fr...Freunde fürs Leb'n.", progress = "Habt Ihr es versucht?", completion = "Danke, &lt;Name&gt;! Die we...erd' ich mir fü...ür 'n schlecht'n Ta...ag... zur Seite leg'n... hicks!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31324] = {title = "Familiengeheimnisse", objective = "Sammelt 5 Geheimnisse der Sturmbräus.", description = "Unsere geheimen Rezepte! Ich habe sie gerade zusammengetragen, doch dann... Ho-zen?\n\n<Tantchen sieht sehr verwirrt aus.>\n\nWie soll Gao so denn etwas zusammenbrauen? Er braucht diese Rezepte, sonst gibt es noch eine Katastrophe!", progress = "Oh, hallo!", completion = "Ho ho, was ist denn das?\n\n&lt;Onkel Gaos fetter Bräubauch schwabbelt beim Anblick der Familienrezepte freudig auf und ab.&gt;\n\nAch, ich wusste doch, dass ich zu viel Mais benutze!", rewards = "SturmbräuserviertuchBenutztes SpültuchTantchens KochschürzeTischtuch des BierproberaumsRußschwarzer KettenumhangIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31325] = {title = "Eine sehr schöne Halskette", objective = "Bringt die Halskette zu Tina Lehmkrall in Haohans Haus oder zum Halbhügelmarkt im Tal der Vier Winde.\n\nBereitgestellter Gegenstand: \n", description = "Diese wunderschöne Halskette wurde teilweise von den schmutzigen Händen eines Ho-zen verschmiert.\n\nEs gibt im Tal nur eine Person, die ein so schönes Schmuckstück besitzen könnte.", progress = nil, completion = "Oh, das ist ja meine Lieblingshalskette! Mir war gar nicht bewusst, dass ich sie verloren hatte! Danke, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31326] = {title = "Tinas elegante Tiara", objective = "Bringt die elegante Tiara zu Tina Lehmkrall in Haohans Haus oder zum Halbhügelmarkt im Tal der Vier Winde.\n\nBereitgestellter Gegenstand: \n", description = "Es ist eine blendende Diamantentiara. Wer im Tal könnte wohl reich genug sein, um ein solches Schmuckstück zu besitzen?\n\nWer auch immer es ist, er oder sie dürfte eine nette Belohnung herausspringen lassen.", progress = nil, completion = "Oh, meine Tiara! Ich hatte sie verloren, aber wo um alles in der Welt habt Ihr sie nur gefunden?", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31327] = {title = "Ärger aus dem Fass", objective = "Tötet Yan-Zhu den Dekantierten.", description = "In der Brauerei treiben Ho-zen ihr Unwesen und... wer weiß was noch. Ich bin sicher, dass die Brauer in Schwierigkeiten stecken.\n\nWärt Ihr vielleicht so nett, herauszufinden, was da vor sich geht, <mein Freund/meine Liebe>?", progress = nil, completion = "Eine riesige, aus Gebräu entstandene Kreatur?! Wer hätte je gedacht, dass es so etwas geben kann?\n\nDanke, dass Ihr Gao vor seinen eigenen fehlgeleiteten Brauereiexperimenten gerettet habt.", rewards = "Handschuhe des MeisterbrauersArbeitshandschuhe des FässerstaplersWeinprobehandschuheKorkenziehende HandschuheIm Fass gealterte HandschuheShed-Lings-BekämpfungshandschuheGemüsehackende HandschützerStulpen des ungebetenen GastsHandschützer des strammen ZustandsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31328] = {title = "Ein exquisiter Ohrring", objective = "Bringt den exquisiten Ohrring zu Tina Lehmkrall in Haohans Haus oder zum Halbhügelmarkt im Tal der Vier Winde.\n\nBereitgestellter Gegenstand: \n", description = "Ihr nehmt den Ohrring aus dem pelzigen Ohr der Kreatur. Wie es scheint, hatte der Bursche beim Tragen dieses baumelnden Rings eine Menge Spaß. ZU VIEL Spaß.\n\nVielleicht hätte die Besitzerin dieses anmutigen Schmuckstücks es gern zurück. Ihr müsst ihr ja nicht sagen, wo Ihr es gefunden habt... oder wer es getragen hat.", progress = nil, completion = "Oh, mein Ohrring! Aber, er passt ja genau zu dem, den ich heute trage!\n\n&lt;Tina steckt sich den Ohrring ins Ohr.&gt;\n\nIch danke Euch, &lt;Name&gt;!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31329] = {title = "Eine wunderschöne Brosche", objective = "Bringt die wunderschöne Brosche zu Tina Lehmkrall in Haohans Haus oder zum Halbhügelmarkt im Tal der Vier Winde.\n\nBereitgestellter Gegenstand: \n", description = "Diese sehr alte antike Brosche wurde mit viel Liebe zum Detail gefertigt und in einen filigranen Rahmen eingefasst. Sie sieht sehr wertvoll aus.\n\nEs gibt nur eine Person, die immer wieder Schmuckstücke an pelzige Straßendiebe verliert, und sie würde dieses Erbstück vermutlich sehr gerne zurückhaben.", progress = nil, completion = "Die Brosche meiner Großmutter! Oh, was für ein Glück, dass Ihr sie gefunden habt! Es ist ein wertvolles Familienstück.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31331] = {title = "Anleitung zur Questerstellung", objective = "Erstellt eine Schnitzeljagdquest.Juchu! Ihr dürft eine Schnitzeljagdquest erstellen! Findet heraus, was als Nächstes zu tun ist.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Juchu! Ihr dürft eine Schnitzeljagdquest erstellen! Findet heraus, was als Nächstes zu tun ist.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31332] = {title = "Lektion 1: Pfirsich in Scheiben", objective = "Besorgt Euch 5 Pandarenpfirsiche für Nomis Kochstunde.", description = "Ich brenne schon richtig auf den Beginn meiner Ausbildung. Wir fangen mit einem Pfirsich in Scheiben an, richtig?", progress = "Ich will so gern Koch werden, die anderen Kinder haben aber schon vor zwei Monaten angefangen. Ohne Eure Hilfe hole ich sie niemals ein.", completion = "Hier, fertig! Und, wie habe ich mich geschlagen?", rewards = "Ihr bekommt:\n\nPfirsich in Scheiben"}
MultiLanguageQuestData['de'][31333] = {title = "Lektion 2: Fertignudeln", objective = "Besorgt 5 Portionen Fertignudeln für Nomis Kochlektion.", description = "Fertignudeln sind ja nicht so schwer zu kochen, oder?", progress = "Es ist so leicht, die Nudeln zu verkochen!", completion = "Hier, fertig! Und, wie habe ich mich geschlagen?", rewards = "Ihr bekommt:\n\nPerfekt gekochte Fertignudeln"}
MultiLanguageQuestData['de'][31334] = {title = "Lektion 3: Gerösteter Trockenfisch", objective = "Besorgt 5 Goldkarpfen für Nomis Kochlektion.", description = "Das Kochen ist schwieriger, als ich dachte. Es ist so schnell etwas verbrannt.", progress = "Hoffentlich verbrenne ich mich nicht. IIH!", completion = "Hier, fertig! Und, wie habe ich mich geschlagen?", rewards = "Ihr bekommt:\n\nGerösteter Trockenfisch"}
MultiLanguageQuestData['de'][31335] = {title = "Lektion 4: Getrocknete Nadelpilze", objective = "Besorgt 5 Nadelpilze für Nomis Kochlektion.", description = "Mit Pilzen hab' ich's nicht so besonders... aber ich werde mein Bestes tun, mehr über sie zu lernen.", progress = "Igitt.", completion = "Hier, fertig! Und, wie habe ich mich geschlagen?", rewards = "Ihr bekommt:\n\nGetrocknete Nadelpilze"}
MultiLanguageQuestData['de'][31336] = {title = "Lektion 5: Stampfreiskuchen", objective = "Besorgt Euch 5 Portionen Reis für Nomis Kochlektion.", description = "Ich liebe Reiskuchen. Ich werde mein Bestes tun, ganz besonders gute zu backen!", progress = "Ich bin schon ganz gespannt, ob sie was werden!", completion = "Hier, fertig! Und, wie habe ich mich geschlagen?", rewards = "Ihr bekommt:\n\nStampfreiskuchen"}
MultiLanguageQuestData['de'][31337] = {title = "Ein Zeichen der Anerkennung", objective = "Nehmt Nomis Geschenk an.Danke, dass Ihr Euch vergewissert habt, dass bei mir alles zum Besten steht! Ich konnte heute der Familie Eisentatz helfen, und man gestattete mir, Euch dies zu überbringen.Ihr bekommt:\n\n", description = "Danke, dass Ihr Euch vergewissert habt, dass bei mir alles zum Besten steht! Ich konnte heute der Familie Eisentatz helfen, und man gestattete mir, Euch dies zu überbringen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nLeckeres von NomiEisentatzmarke"}
MultiLanguageQuestData['de'][31338] = {title = "Ein verlorenes Schäfchen", objective = "Findet Schäfchen und bringt es zu Chi-Chi zurück.", description = "Schäfchen, Chi-Chis wertvollstes Schaf, ist verschwunden!\n\nDas dumme Ding ist immer wieder vom Hof weggelaufen.\n\nDummes Schaf! Ich hab' überall gesucht, konnte es aber nicht finden.\n\nKönnt Ihr mir helfen, <Volk>?", progress = "Habt Ihr mein Schäfchen gefunden? Ach, und ich hab' mir solche Sorgen gemacht.", completion = "Oh, Ihr habt ihn gefunden! Danke!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31339] = {title = "Schäfchen ist schon wieder weg", objective = "Findet Schäfchen und bringt ihn zu Chi-Chi zurück.", description = "Dieses dumme Schaf ist schon wieder abgehauen!\n\nKönnt Ihr es noch mal für mich suchen?", progress = "Ach, armes Schäfchen. Ist sicher ganz verängstigt und furchtbar allein...", completion = "Schäfchen, ich hab' mir ja solche Sorgen gemacht! Böses Schaf! Chi-Chi war ja so beunruhigt!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31340] = {title = "Ach, Schäfchen...", objective = "Findet Schäfchen.", description = "Seufz... Ihr habt es sicher erraten... Schäfchen ist fort... SCHON WIEDER.\n\nDummes Schaf! Macht mir immer so viel Ärger!\n\nIch muss Euch noch einmal um einen Gefallen bitten, aber ist garantiert das letzte Mal, versprochen.\n\nKönnt Ihr für mich nach Schäfchen suchen?", progress = nil, completion = "Was? Schäfchen ist... fort?\n\n&lt;Chi-Chis Lippen beginnen zu beben.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31341] = {title = "Ein Wolf im Schafspelz", objective = "Benutzt den alten Schafspelz irgendwo auf der Himmelsweite oder in Kunzen und tötet dann Krungko.", description = "AAAARRRRRGGGHHHHH!!!! Dieser letzte Tropfen hat das Fass zum Überlaufen gebracht!\n\nDiese dummen Ho-zen auf dem Berg haben mein SCHÄFCHEN umgebracht!\n\nIch weiß genau, wer es war, und diesmal werde ich mich RÄCHEN.\n\nWenn Ihr mir helfen wollt, legt diesen alten Schafspelz an.\n\nVerkleidet Euch damit und wartet irgendwo auf dem Berg im Norden auf diesen kleinen Knatzel Krungko. Wenn er aus seinem Versteck kommt, brecht ihm die Knochen!", progress = nil, completion = "Danke, &lt;Name&gt;. Das bringt mein Schäfchen zwar nicht zurück, aber wenigstens werde ich nun keine weiteren Schafe verlieren.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31342] = {title = "Der Weg zum Respekt liegt in der Gewalt", objective = "Tötet das Sha der Gewalt.", description = "Ihr habt Euch im Kampf bewiesen.\n\nWenn Ihr uns auch weiterhin unterstützen wollt, hätte ich noch eine Bitte an Euch.\n\nDas Sha der Gewalt erwartet Euch in den versiegelten Kammern. Vernichtet es, wenn Ihr Euch meinen Respekt verdienen wollt.", progress = nil, completion = "Ihr habt das Sha der Gewalt besiegt und das Kloster gerettet - damit habt Ihr Euch meinen Respekt verdient.\n\nVielleicht haben wir Eure Art falsch eingeschätzt, &lt;Name&gt;.", rewards = "Kordel des wilden ShaKun-Lai-BergsteigergürtelTaillenschutz des ShafängersWolkenschlägerkordelShado-Pan-InitiandengürtelVerbund des ElementarbogenschützenTaillenschutz des KlosterwächtersGurt des gebrochenen SiegelsKordel der gestörten TräumeIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31354] = {title = "Mazus Freigiebigkeit", objective = "Sprecht mit Meisterangler Ju Lien in Tropfs Wagnis.", description = "Das war ziemlich erstaunliche Arbeit, die Ihr mit dem Kapitän dort draußen geleistet habt, $p! Es ist eine Ehre, Euch in der Besatzung zu haben.\n\nOh! Und Ju Lien lebt noch! Nachdem Ihr die Harpunen fliegen lassen habt, ist er ans Ufer geschwommen. Er hat vor sich hingefaselt, etwas von einem riesigen Ei oder so, das mit Jiao angespült wurde.\n\nWürdet Ihr nachsehen gehen? Mittlerweile hat er es vermutlich aus dem Wasser gezerrt.", progress = nil, completion = "Hallo!\n\nAch, mir geht es gut. Ich habe nach einem Besuch im \"Abfalleimer\" Nächte erlebt, die schlimmer waren.\n\nJetzt seht Euch doch einmal dieses Ding an. Ich sah es aus dem Meeresboden ragen, als ich dort unten war - Jiao hat es wohl freigesetzt, als er um sich geschlagen hat.\n\nIch bin mir nicht ganz sicher, was ich damit anstellen soll, es sieht aber wertvoll aus. Ihr habt uns mehr oder weniger gerettet, deshalb glaube ich, dass wir Euch diesen Fang schulden.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMazu's Bounty: Completion\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31355] = {title = "Wiederherstellung der Reinheit", objective = "Helft dem weisen Mari, Liu Flammenherz und Lehrensucher Steinschritt mit ihren Sha-Problemen.", description = "<Klasse>, werdet Ihr uns helfen?\n\nDie Reinheit des Tempels ist in Gefahr. Just in diesem Moment kämpfen die drei Meister gegen ihre Zweifel an.\n\nBitte, ich flehe Euch an... helft dem weisen Mari, Liu Flammenherz und Lehrensucher Steinschritt in ihrem Kampf gegen das Sha.", progress = nil, completion = "Das Schicksal von Priesterin Flammenherz und dem weisen Mari stimmen mich zwar traurig, dennoch habt Ihr meinen aufrichtigen Dank.", rewards = "FlammenherzhandgelenksschützerArmschienen des trotzigen BogenschützenManschetten des SchriftführersSommerblattmanschettenRingelschlangenarmbandArmschienen des weisen MariArmschienen der Geschichten aus grauer VorzeitImmersichtarmschienenArmplatten des JadegötzenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31356] = {title = "Tiefe Zweifel, tiefe Weisheit", objective = "Tötet das Sha des Zweifels.", description = "Ein altes Sprichwort der Pandaren sagt: \"Aus großen Zweifeln folgt große Weisheit.\"\n\nDas Sha des Zweifels hat sich im Tempel im Jadeherz eingenistet. Es muss vernichtet werden.\n\nIch möchte behaupten, dass Ihr bald sehr viel weiser sein werdet, <Klasse>.", progress = "Das Sha des Zweifels muss vernichtet werden, <Name>, oder wir sind alle verloren.", completion = "Ich habe nie an Euch gezweifelt. Komischerweise wirkt Ihr kein bisschen weiser.\n\n&lt;Der Meister zwinkert mit dem Auge.&gt;", rewards = "Windstarke GamaschenGamaschen der fünften SonneBeinschützer der GezeitenBeinplatten der absoluten KlarheitGamaschen des inneren FriedensLuis GamaschenGleichgewichtsbeinwickelBeinschützer des gewappneten SelbstvertrauensBeinplatten des reinen ZielsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31357] = {title = "Relikte der Vier Könige", objective = "Beschafft die Laterne des Zaubererkönigs, die Waage von König Meng dem Irren, Qiangs \"Die Wissenschaft des Krieges\" und den Bogen von Subetai dem Schnellen.", description = "Die Mogu sind von Neuem erwacht und stellen eine Bedrohung für ganz Pandaria dar. Und sie stehen kurz davor, noch gefährlicher zu werden.\n\nEs gibt vier legendäre Großkönige der Mogu: Zian des endlosen Schattens, Meng der Irre, Qiang der Gnadenlose und Subetai der Schnelle. Vier Artefakte dieser Könige werden unter uns im Gewölbe der Vergangenen Könige unter Verschluss gehalten.\n\nIhr müsst diese Relikte beschaffen, bevor die Mogu sie entdecken und unaufhaltsam werden.", progress = "Wir müssen die Laterne, die Waage, die Schriftrolle und den Bogen sicherstellen, bevor Xin und seine Klans sie entdecken.", completion = "Ich werde ein besseres Versteck für die vier Relikte finden.\n\nPandaria steht in Eurer Schuld, &lt;Name&gt;.", rewards = "UnterwerfungsarmschienenArmschienen der schnellen RacheManschetten der endlosen SchattenBindungen der einwandfreien StrategieArmbänder des WiedererwecktenArmschienen des verlorenen ErbesArmschienen des inneren WissensArmplatten der KampfkunstUnterarmschienen des DichterkönigsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31359] = {title = "Der Kunchong-Flüsterer", objective = "Tötet das Orakel Zisch'et und 10 Angehörige des Stammes der Schlickschuppen.", description = "Um eine richtige Verbindung mit Kovok einzugehen, müsst Ihr ihn geistig und körperlich fordern. Respektiert seine Stärke und Intelligenz; nur dann wird er zulassen, dass Ihr ihn ernsthaft ausbildet.\n\nDie Schlickschuppen dienen möglicherweise als angemessene Prüfung seiner Fähigkeiten, und wenn Ihr dabei seid, ist er nicht in Gefahr.\n\nAußerdem können wir damit ihre Reihen im Salzigen Schlick lichten.", progress = nil, completion = "Euer Fortschritt ist höchst beeindruckend, Erwecker. Kovoks Training schreitet gut voran und er scheint Euch zu mögen.\n\nIhr seid zweifelsfrei die beste Wahl, um mir bei seiner Erziehung zu helfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31360] = {title = "Eine neue Lektion für den Meister", objective = "Tötet Xin den Waffenmeister.", description = "Ein neuer König der Mogu ist an der Macht: Xin der Waffenmeister.\n\nHat die Klans der Mogu eigenhändig unterworfen... Deren neue Anführer buhlen nun um seine Gunst.\n\nIch weiß von niemandem, der ihm im Kampf das Wasser reichen könnte. Unterschätzt Xin nicht, <Name>.\n\nUnser Schicksal liegt in Euren Händen.", progress = nil, completion = "Eine wahrlich legendäre Schlacht.\n\nIch bin froh, dass Ihr auf unserer Seite seid, &lt;Name&gt;.", rewards = "Beinkleider des wachsamen TräumersWachgamaschen des TräumersGamaschen der durchdachten FalleBeinplatten der versprengten StämmeGamaschen des EntthronersGamaschen des leeren ThronsGamaschen der gewaltsamen AusbildungBeinschützer des MogukriegsfürstenBeinplatten des WaffenmeistersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31362] = {title = "Das letzte Puzzleteil", objective = "Benutzt Chos Erbstück bei Chos Familienschrein beim Schlangenblick.\n\nUm dorthin zu kommen, sprecht mit Mishi.", description = "Ich muss sagen, <Name>, trotz der Scharmützel mit den Ho-zen habe ich die Jinyu noch nie so militant erlebt.\n\nDas beunruhigt mich. Allerdings müssen wir das zu einem anderen Zeitpunkt besprechen. Ich bin hier, um Euch um Eure Unterstützung zu bitten.\n\nDas uralte Fresko, dort, wo wir uns zuletzt unterhielten, ist fast enthüllt. Ich bin mir sicher, dass es uralte Weisheit enthält - Weisheit, von der der Kaiser wollte, dass wir sie nicht vergessen.\n\nDurch Meditation allein kann ich ihre Bedeutung vielleicht nicht rechtzeitig enthüllen. Bitte, bringt dieses Erbstück zum Schrein meiner Ahnen. Mit ihrer Hilfe werden wir dieses Rätsel lösen können.", progress = nil, completion = "&lt;Lehrensucher Cho schüttelt sich unwillkürlich.&gt;\n\nDie Legenden… sie sind wahr!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31363] = {title = "Gebt das Signal", objective = "Entfacht die Signalflamme.", description = "Wir brauchen Verstärkung! Jemand muss sich durchkämpfen und die Signalflamme entfachen.\n\nEs hängt alles von Euch ab, <Klasse>. Fühlt Euch jetzt bloß nicht unter Druck gesetzt oder so.", progress = nil, completion = "Hervorragend, &lt;Name&gt;. Ihr hättet es von der Zeit her nicht besser machen können!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31364] = {title = "Was für ein Brocken!", objective = "Tötet Raigonn.", description = "Die Mantis verfügen über etwas, das sie Raigonn nennen. Es ist ein riesiges Insekt, mit dem sie die Tore der Mauer einstoßen!\n\nLasst uns sicherstellen, dass dieses Ding nicht ins Tal gelangt!", progress = nil, completion = "Hätte ich es nicht mit eigenen Augen gesehen, ich hätte es wohl nicht geglaubt.\n\nGut gemacht, &lt;Name&gt;!", rewards = "Tuch mit aufgenähten InsektenpanzernUmhang des unendlichen SchwarmsUmhang der kollektiven GedankenTuch des brennenden SignalsUmhang des MantiskammerjägersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31365] = {title = "Irgendwo da drinnen", objective = "Rettet 12 gefangene Shado-Pan.", description = "Ich habe ein Dutzend meiner besten Männer vorausgeschickt, um die Mantisbelagerung zu infiltrieren.\n\nKeiner von ihnen ist bisher zurückgekehrt.\n\nDa Ihr die Mantis direkt angreifen werdet, bietet sich Euch die Chance, alle zu befreien, die das Pech hatten, in Gefangenschaft zu geraten.\n\nWerdet Ihr das für uns tun?", progress = "Meine Männer werden irgendwo im Bereich der Mantisbelagerung festgehalten.", completion = "Ich sage dreizehnmal danke - zwölfmal für jene, die Ihr gerettet habt, und einmal für mich selbst.\n\nUnd hier ist noch etwas, das ich Euch als Zeichen der Dankbarkeit überreichen möchte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31366] = {title = "Schaltet den Schwadronsführer aus", objective = "Tötet Schwadronsführer Ner'onok.", description = "Die Mantis belagern den Niuzaotempel.\n\nSchwadronsführer Ner'onok und seine Einheit arbeiten in diesem Augenblick daran, die letzte Kluft zu überbrücken.\n\nIhr müsst ihn und seine Leute aufhalten, bevor sie die Brücke wieder aufbauen.", progress = nil, completion = "Der Schwadronsführer ist tot, die Belagerung zerschlagen.\n\nIhr habt den Tempel gerettet, &lt;Name&gt;.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nAbzeichen der BernbelagerungBrückenbrechermedaillonAnhänger aus gehärtetem HarzMantisaugenamulettMedaillon des Saboteurs\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][31367] = {title = "Die Lehrensucher", objective = "Sprecht mit Lehrensucher Cho im Heim des Wissens im Tal der Ewigen Blüten.", description = "Ihr wollt also mehr über dieses Land erfahren?\n\nSehr gut! Dann solltet Ihr mit Lehrensucher Cho im Heim des Wissens sprechen.\n\nIhr findet ihn in dem Raum oberhalb des Eingangs zum Mogu'shanpalast. Sprecht mit Mishi, um dorthin zu gelangen.", progress = nil, completion = "Ja, ich kann Euch am Gesicht ansehen, dass Ihr ein Interesse an der Geschichte habt. Dann seid Ihr hier am richtigen Ort.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31368] = {title = "Die Lehrensucher", objective = "Sprecht mit Lehrensucher Cho im Heim des Wissens im Tal der Ewigen Blüten.", description = "Ihr wollt also mehr über dieses Land erfahren?\n\nSehr gut! Dann solltet Ihr mit Lehrensucher Cho im Heim des Wissens sprechen.\n\nIhr findet ihn in dem Raum oberhalb des Eingangs zum Mogu'shanpalast. Sprecht mit Mishi, um dorthin zu gelangen.", progress = nil, completion = "Ja, ich kann Euch am Gesicht ansehen, dass Ihr ein Interesse an der Geschichte habt. Dann seid Ihr hier am richtigen Ort.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31369] = {title = "Die Angler", objective = "Sprecht mit dem Angler Haito an der Anlegestelle der Angler in der Krasarangwildnis.", description = "Wenn Ihr all die Geheimnisse des tiefen Ozeans erkunden und ein paar richtig große Fische fangen wollt, solltet Ihr mit Haito an der Anlegestelle der Angler in der Krasarangwildnis sprechen.\n\nEr wird Euch sicher gern ein oder zwei Dinge über die Angelei erzählen!", progress = nil, completion = "Seid Ihr bereit für GROSSE Fische?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31370] = {title = "Die Angler", objective = "Sprecht mit dem Angler Haito an der Anlegestelle der Angler in der Krasarangwildnis.", description = "Wenn Ihr all die Geheimnisse des tiefen Ozeans erkunden und ein paar richtig große Fische fangen wollt, solltet Ihr mit Haito an der Anlegestelle der Angler in der Krasarangwildnis sprechen.\n\nEr wird Euch sicher gern ein oder zwei Dinge über die Angelei erzählen!", progress = nil, completion = "Seid Ihr bereit für GROSSE Fische?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31372] = {title = "Die Ackerbauern", objective = "Sprecht mit Bauer Yoon auf dem Gehöft Sonnensang im Tal der Vier Winde.", description = "Die Ackerbauern gehen ihrem Beruf in Halbhügel im Tal der Vier Winde nach.\n\nWenn Ihr Interesse an ihrer Arbeit habt, solltet Ihr vielleicht mit Bauer Yoon sprechen. Er ist noch neu im Ort.\n\nIch wette, er kann etwas Hilfe gebrauchen.", progress = nil, completion = "Ihr kommt genau zur rechten Zeit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31373] = {title = "Der Orden der Wolkenschlange", objective = "Sprecht mit Ausbilder Himmelsdorn im Arboretum im Jadewald.", description = "Der Orden der Wolkenschlange ist immer auf der Suche nach Reittalenten.\n\nWenn Ihr Euch uns anschließen wollt, solltet Ihr mit Ausbilder Himmelsdorn im Arboretum im Jadewald sprechen.\n\nIch wünsche Euch viel Glück, <Volk>.", progress = nil, completion = "Ah, Ihr möchtet Euch unserem Orden anschließen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31374] = {title = "Die Ackerbauern", objective = "Sprecht mit Bauer Yoon auf dem Gehöft Sonnensang im Tal der Vier Winde.", description = "Die Ackerbauern gehen ihrem Beruf in Halbhügel im Tal der Vier Winde nach.\n\nWenn Ihr Interesse an ihrer Arbeit habt, solltet Ihr vielleicht mit Bauer Yoon sprechen. Er ist noch neu im Ort.\n\nIch wette, er kann etwas Hilfe gebrauchen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31375] = {title = "Der Orden der Wolkenschlange", objective = "Sprecht mit Ausbilder Himmelsdorn im Arboretum im Jadewald.", description = "Der Orden der Wolkenschlange ist immer auf der Suche nach Reittalenten.\n\nWenn Ihr Euch uns anschließen wollt, solltet Ihr mit Ausbilder Himmelsdorn im Arboretum im Jadewald sprechen.\n\nIch wünsche Euch viel Glück, <Volk>.", progress = nil, completion = "Ah, Ihr möchtet Euch unserem Orden anschließen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31376] = {title = "Angriff auf den Tempel der Jadeschlange", objective = "Sprecht mit dem Ältestenweisen Tai-Feng auf dem Tempelgelände der Jadeschlange im Jadewald.", description = "Der Tempel der Jadeschlange wird in Dunkelheit gehüllt und Yu'lons Priester haben uns um Hilfe gebeten.\n\nNoch können sie das Sha in Schach halten, aber nicht mehr lange.\n\nVielleicht gelingt es Euch ja, den Feind zu überwinden, <Klasse>.", progress = nil, completion = "Ihr kommt gerade rechtzeitig.", rewards = nil}
MultiLanguageQuestData['de'][31377] = {title = "Angriff auf den Tempel der Jadeschlange", objective = "Sprecht mit dem Ältestenweisen Tai-Feng auf dem Tempelgelände der Jadeschlange im Jadewald.", description = "Der Tempel der Jadeschlange wird in Dunkelheit gehüllt und Yu'lons Priester haben uns um Hilfe gebeten.\n\nNoch können sie das Sha in Schach halten, aber nicht mehr lange.\n\nVielleicht gelingt es Euch ja, den Feind zu überwinden, <Klasse>.", progress = nil, completion = "Ihr kommt gerade rechtzeitig.", rewards = nil}
MultiLanguageQuestData['de'][31378] = {title = "Herausforderung am Tempel des Roten Kranichs", objective = "Sprecht mit Thelonius an Chi-Jis Wiege in der Krasarangwildnis.", description = "Der Tempel des Roten Kranichs ist nach dem Auftauchen des Sha immer noch in Aufruhr. Erst vor Kurzem konnten sie beginnen, die Truppen zu sammeln und die Übungen für die Krieger wieder aufzunehmen.\n\nWenn Ihr dem Tempel helfen möchtet, dann sprecht mit Thelonius an Chi-Jis Wiege.", progress = nil, completion = "Ich heiße Euch willkommen.", rewards = nil}
MultiLanguageQuestData['de'][31379] = {title = "Herausforderung am Tempel des Roten Kranichs", objective = "Sprecht mit Thelonius an Chi-Jis Wiege in der Krasarangwildnis.", description = "Der Tempel des Roten Kranichs ist nach dem Auftauchen des Sha immer noch in Aufruhr. Erst vor Kurzem konnten sie beginnen, die Truppen zu sammeln und die Übungen für die Krieger wieder aufzunehmen.\n\nWenn Ihr dem Tempel helfen möchtet, dann sprecht mit Thelonius an Chi-Jis Wiege.", progress = nil, completion = "Ich heiße Euch willkommen.", rewards = nil}
MultiLanguageQuestData['de'][31380] = {title = "Herausforderung am Tempel des Weißen Tigers", objective = "Sprecht mit Xuen am Tempel des Weißen Tigers am Kun-Lai-Gipfel.", description = "Xuen, der große Himmlische des Nordes, ist auf der Suche nach den größten Kämpfern des Landes.\n\nHeute wird er seine Herausforderungen am Kun-Lai-Gipfel abhalten.\n\nWenn Ihr Euch mit den stärksten Kämpfern aus ganz Pandaria messen wollt, dann sucht ihn auf und betretet den Ring der Herausforderer!", progress = nil, completion = "Ihr möchtet also Eure Fähigkeiten auf die Probe stellen? Sehr gut, &lt;Volk&gt;.", rewards = nil}
MultiLanguageQuestData['de'][31381] = {title = "Herausforderung am Tempel des Weißen Tigers", objective = "Sprecht mit Xuen am Tempel des Weißen Tigers am Kun-Lai-Gipfel.", description = "Xuen, der große Himmlische des Nordes, ist auf der Suche nach den größten Kämpfern des Landes.\n\nHeute wird er seine Herausforderungen am Kun-Lai-Gipfel abhalten.\n\nWenn Ihr Euch mit den stärksten Kämpfern aus ganz Pandaria messen wollt, dann sucht ihn auf und betretet den Ring der Herausforderer!", progress = nil, completion = "Ihr möchtet also Eure Fähigkeiten auf die Probe stellen? Sehr gut, &lt;Volk&gt;.", rewards = nil}
MultiLanguageQuestData['de'][31382] = {title = "Die Verteidigung des Niuzaotempels", objective = "Sprecht mit Ogo dem Ältesten im Niuzaotempel in der Tonlongsteppe.", description = "Der Niuzaotempel im äußersten Westen, wird von den Mantis angegriffen.\n\nBis jetzt konnte der Große Himmlische sie aufhalten, aber auf sich allein gestellt kann selbst er nicht ewig durchhalten.\n\nIhr müsst den Verteidigern helfen, <Klasse>. Der Tempel darf nicht fallen!", progress = nil, completion = "Ich grüße Euch. Wir können Eure Hilfe wirklich gebrauchen.", rewards = nil}
MultiLanguageQuestData['de'][31383] = {title = "Die Verteidigung des Niuzaotempels", objective = "Sprecht mit Ogo dem Ältesten im Niuzaotempel in der Tonlongsteppe.", description = "Der Niuzaotempel im äußersten Westen, wird von den Mantis angegriffen.\n\nBis jetzt konnte der Große Himmlische sie aufhalten, aber auf sich allein gestellt kann selbst er nicht ewig durchhalten.\n\nIhr müsst den Verteidigern helfen, <Klasse>. Der Tempel darf nicht fallen!", progress = nil, completion = "Ich grüße Euch. Wir können Eure Hilfe wirklich gebrauchen.", rewards = nil}
MultiLanguageQuestData['de'][31384] = {title = "Der Goldene Lotus", objective = "Sprecht mit Anji Herbstlicht in der Garnison der Untergehenden Sonne im Tal der Ewigen Blüten.", description = "Der Goldene Lotus bewacht das Tal seit Jahrhunderten. Er hat für seine Sicherheit gesorgt und es vor Schaden bewahrt.\n\nDie jüngsten Ereignisse haben fürchterliche Schrecken über unser Tal gebracht, aber die Verbündeten des Goldenen Lotus halten immer noch gegen sie aus und versuchen, den Frieden wiederherzustellen.\n\nWenn Ihr helfen möchtet, stoßt Ihr am besten bei der Garnison der Untergehenden Sonne zu ihnen.", progress = nil, completion = "Seid gegrüßt, &lt;Volk&gt;. Ihr scheint dem Aussehen nach über einige Fähigkeiten zu verfügen. Gut jemand so fähiges wie Euch, &lt;Klasse&gt;, auf unserer Seite zu wissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31385] = {title = "Der Goldene Lotus", objective = "Sprecht mit Anji Herbstlicht in der Garnison der Untergehenden Sonne im Tal der Ewigen Blüten.", description = "Der Goldene Lotus bewacht das Tal seit Jahrhunderten. Er hat für seine Sicherheit gesorgt und es vor Schaden bewahrt.\n\nDie jüngsten Ereignisse haben fürchterliche Schrecken über unser Tal gebracht, aber die Verbündeten des Goldenen Lotus halten immer noch gegen sie aus und versuchen, den Frieden wiederherzustellen.\n\nWenn Ihr helfen möchtet, stoßt Ihr am besten bei der Garnison der Untergehenden Sonne zu ihnen.", progress = nil, completion = "Seid gegrüßt, &lt;Volk&gt;. Ihr scheint dem Aussehen nach über einige Fähigkeiten zu verfügen. Gut jemand so fähiges wie Euch, &lt;Klasse&gt;, auf unserer Seite zu wissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31386] = {title = "Die Shado-Pan-Offensive", objective = "Sprecht mit Taran Zhu am Außenposten Longying in der Tonlongsteppe.", description = "Wir Shado-Pan haben unsere Truppen zum ersten Mal seit vielen, vielen Jahren wieder zusammengezogen.\n\nDas Sha des Hasses ist aus seinem Gefängnis jenseits des Schlangenrückens entkommen und es ist unsere heilige Pflicht, es wieder gefangen zu nehmen.\n\nUnsere Krieger sind zwar sehr fähig, aber leider viel zu wenige. Eure Hilfe werden wir also nicht ablehnen, <Klasse>.\n\nWenn Ihr Euch der Offensive anschließen wollt, sprecht mit Taran Zhu in der Tonlongsteppe.", progress = nil, completion = "Ich grüße Euch, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31387] = {title = "Die Shado-Pan verstehen", objective = "Erlangt beim Goldenen Lotus einen respektvollen Ruf.", description = "Die Shado-Pan gehören zu den ältesten Beschützern Pandarias.\n\nÜber viele Jahre hinweg werden wir in unserem schneebedeckten Kloster hoch auf dem Kun-Lai-Gipfel ausgebildet. Dabei perfektionieren wir die Geheimnisse der Kampfkunst, die uns von unseren Ahnen weitergereicht wurden.\n\nWir mögen nur Wenige sein, doch ein einzelner Shado-Pan kann tödlicher sein als hundert gut ausgebildete Soldaten.\n\nSich dem Orden der Shado-Pan anzuschließen ist ein langwieriges und mühsames Unterfangen voller Entbehrungen. Solltet Ihr diesen Pfad beschreiten wollen, müsst Ihr Euch erst als würdig erweisen.\n\nEs gibt hier dringende Aufgaben zu erledigen. Helft dem Goldenen Lotus bei der Verteidigung des Tals.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31388] = {title = "Die Shado-Pan-Offensive", objective = "Sprecht mit Taran Zhu am Außenposten Longying in der Tonlongsteppe.", description = "Wir Shado-Pan haben unsere Truppen zum ersten Mal seit vielen, vielen Jahren wieder zusammengezogen.\n\nDas Sha des Hasses ist aus seinem Gefängnis jenseits des Schlangenrückens entkommen und es ist unsere heilige Pflicht, es wieder gefangen zu nehmen.\n\nUnsere Krieger sind zwar sehr fähig, aber leider viel zu wenige. Eure Hilfe werden wir also nicht ablehnen, <Klasse>.\n\nWenn Ihr Euch der Offensive anschließen wollt, sprecht mit Taran Zhu in der Tonlongsteppe.", progress = nil, completion = "Ich grüße Euch, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31389] = {title = "Die Shado-Pan verstehen", objective = "Erlangt beim Goldenen Lotus einen respektvollen Ruf.", description = "Die Shado-Pan gehören zu den ältesten Beschützern Pandarias.\n\nÜber viele Jahre hinweg werden wir in unserem schneebedeckten Kloster hoch auf dem Kun-Lai-Gipfel ausgebildet. Dabei perfektionieren wir die Geheimnisse der Kampfkunst, die uns von unseren Ahnen weitergereicht wurden.\n\nWir mögen nur Wenige sein, doch ein einzelner Shado-Pan kann tödlicher sein als hundert gut ausgebildete Soldaten.\n\nSich dem Orden der Shado-Pan anzuschließen ist ein langwieriges und mühsames Unterfangen voller Entbehrungen. Solltet Ihr diesen Pfad beschreiten wollen, müsst Ihr Euch erst als würdig erweisen.\n\nEs gibt hier dringende Aufgaben zu erledigen. Helft dem Goldenen Lotus bei der Verteidigung des Tals.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31390] = {title = "Die Klaxxi", objective = "Sprecht mit Bogenmeisterin Li am Tor der Untergehenden Sonne zwischen dem Tal der Ewigen Blüten und der Schreckensöde.", description = "Die Existenz der Klaxxi ist nur eine unbestätigte Legende. Sie sollen weit jenseits der Mauer in der Schreckensöde leben.\n\nDieses Gebiet haben nur wenige betreten. Und noch weniger sind je wieder von dort zurückgekehrt, um ihre Eindrücke zu schildern.\n\nWenn Ihr also unbedingt diese... Klaxxi... finden wollt, es gibt da eine kleine Gruppe Shado-Pan, die die Mauer im Südwesten beschützt. Sie können Euch vielleicht mehr erzählen.", progress = nil, completion = "Die Schreckensöde ist ein gefährlicher Ort.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31391] = {title = "Die Klaxxi", objective = "Sprecht mit Bogenmeisterin Li am Tor der Untergehenden Sonne zwischen dem Tal der Ewigen Blüten und der Schreckensöde.", description = "Die Existenz der Klaxxi ist nur eine unbestätigte Legende. Sie sollen weit jenseits der Mauer in der Schreckensöde leben.\n\nDieses Gebiet haben nur wenige betreten. Und noch weniger sind je wieder von dort zurückgekehrt, um ihre Eindrücke zu schildern.\n\nWenn Ihr also unbedingt diese... Klaxxi... finden wollt, es gibt da eine kleine Gruppe Shado-Pan, die die Mauer im Südwesten beschützt. Sie können Euch vielleicht mehr erzählen.", progress = nil, completion = "Die Schreckensöde ist ein gefährlicher Ort.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31392] = {title = "Tempel des Weißen Tigers", objective = "Sprecht mit Anduin Wrynn im Tempel des Weißen Tigers am Kun-Lai-Gipfel.", description = "Habt Ihr die Neuigkeiten vernommen, <Reisender/Reisende>? Einer unserer heiligsten Orte wurde angegriffen, das Tal der Ewigen Blüten!\n\nIn diesem Augenblick ist ein menschlicher Prinz im Tempel des Weißen Tigers, der dafür plädiert, dass Euch und den anderen Völkern von jenseits der Nebel Einlass gewährt wird.\n\nDer Tempel befindet sich im Nordosten des Kun-Lai. Vielleicht könnt Ihr den Weißen Tiger überzeugen, Euch hineinzulassen?\n\nIch kann nur hoffen, dass das Tal nicht vollständig zerstört wurde...", progress = nil, completion = "&lt;Klasse&gt;, ich bin froh, dass Ihr hier seid! In den Überlieferungen der Pandaren gibt es einen legendären Ort, das Tal der Ewigen Blüten. Wenn man den Geschichten der Einheimischen Glauben schenken kann, handelt es sich um einen Ort mit großen heilerischen Kräften.\n\nAber der Kriegshäuptling der Horde hat dem Tal Unsagbares angetan.\n\nWir müssen dort einfach hinein!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31393] = {title = "Tempel des Weißen Tigers", objective = "Sprecht mit Dezco im Tempel des Weißen Tigers am Kun-Lai-Gipfel.", description = "Habt ihr die Neuigkeiten vernommen, <Reisender/Reisende>? Einer unserer heiligsten Orte wurde angegriffen, das Tal der Ewigen Blüten!\n\nIn diesem Augenblick ist ein menschlicher Prinz im Tempel des Weißen Tigers, der dafür plädiert, dass Euch und den anderen Völkern von jenseits der Nebel Einlass gewährt wird.\n\nDer Tempel befindet sich im Nordosten des Kun-Lai. Vielleicht könnt Ihr den Weißen Tiger überzeugen, Euch hineinzulassen?\n\nIch kann nur hoffen, dass das Tal nicht vollständig zerstört wurde...", progress = nil, completion = "Hallo, &lt;Klasse&gt;! Uns wurde eine Audienz beim Weißen Tiger gewährt. Das Tal der Ewigen Blüten wurde unlängst von unserem Kriegshäuptling verheert. Unser Anliegen ist es, dass Horde und Allianz zugleich der Zugang zum Tal gewährt wird, damit die Schäden repariert werden können.\n\nDas Tal ist ein heiliger Ort. Ich glaube, meine Frau Leza sah es in einer Vision – darum ist mein Volk nach Pandaria gekommen. Wir müssen es retten!\n\nMeint Ihr, man wird uns Zugang gewähren?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31394] = {title = "Eine himmlische Erfahrung", objective = "Sprecht mit Xuen und schließt seine Prüfungen ab.", description = "Niemand darf das Tal ohne die Erlaubnis der Himmlischen Erhabenen betreten. Xuen der Weiße Tiger scheint mir Gehör schenken zu wollen.\n\nNach allem, was sich zugetragen hat, sträubt sich Taran Zhu von den Shado-Pan aber dagegen, die Allianz oder die Horde auch nur in die NÄHE des Tals zu lassen.\n\n<Anduin schüttelt den Kopf.>\n\nVielleicht könnt Ihr mir ja helfen, mein Anliegen vorzutragen. Sprecht in unserem Namen mit dem Weißen Tiger. Doch seid vorsichtig! Er könnte Euch eine Reihe von Prüfungen auferlegen...", progress = "Seid Ihr mit den Aufgaben des Weißen Tigers fertig?", completion = "Ihr habt es geschafft, &lt;Name&gt;!\n\nDer Weiße Tiger hat uns erlaubt, die Pandaren in das Tal der Ewigen Blüten zu begleiten. Wir können dort einen Außenposten der Allianz errichten, der als unsere Botschaft bei den Pandaren fungieren kann.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31395] = {title = "Eine himmlische Erfahrung", objective = "Sprecht mit Xuen und besteht seine Prüfungen.", description = "Das menschliche Kalb tritt für uns ein. Er ist sehr wortgewandt. Ich kann sehen, warum Baine Bluthuf den Prinzen so sehr schätzt.\n\nDennoch kann ich dieses Argument nicht gelten lassen. Ich bin nicht von Bedeutung, Ihr hingegen seid <ein Held/eine Heldin> der Horde. Vielleicht könntet Ihr ja zu unseren Gunsten vermitteln?\n\nSprecht mit dem Weißen Tiger und tretet für unsere Sache ein, <Volk>.\n\nSeid vorsichtig! Er könnte Euch eine Reihe von Prüfungen auferlegen...", progress = nil, completion = "Ihr habt es geschafft, &lt;Name&gt;!\n\nDer Weiße Tiger hat uns erlaubt, die Pandaren in das Tal der Ewigen Blüten zu begleiten.\n\nEin Held der Horde hat geschafft, woran der Prinz der Allianz gescheitert ist.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31398] = {title = "Auseinanderfallen", objective = "Bringt Kaz'tik dem Manipulator den leuchtenden Bern zurück.", description = "Warum haben die Saurok Bern? Und noch viel wichtiger: Warum bewacht das Orakel Zish'et ihn so eifersüchtig?\n\nDass er aus dem schwer bewachten Zan'vess stammt, ist unwahrscheinlich - woher kommt er also?\n\nVielleicht wissen die Klaxxi, was wir davon halten sollen.", progress = "Wo habt Ihr das gefunden?", completion = "Es war klug von Euch, uns das zu bringen. Das ist ein Stück Bern, das einen anderen Getreuen umhüllt hat.\n\nDer Schaden deutet darauf hin, dass der Getreue in Schwierigkeiten stecken könnte.\n\nIch werde mit dem Rat sprechen, um eine Entscheidung zu treffen, was als Nächstes geschehen soll.", rewards = "Satinrobe des SonnenuntergangsBalgrobe des SonnenuntergangsVerdorrte HolzbrustplatteBrünierter Brustschutz des SonnenuntergangsSeidene Robe des SonnenuntergangsLedertunika des SonnenuntergangsWindschnitterbrustplatteSchwerer Brustharnisch des SonnenuntergangsGepanzerter Brustharnisch des SonnenuntergangsIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31439] = {title = "Verlorenes Signal", objective = "Erweckt den Getreuen im Dämmerwurzmoor.", description = "Jemand scheint sich am Signalfeuer in der Bernscheinkuhle zu schaffen gemacht zu haben. Kurz bevor es ausfiel, empfingen die Klaxxi'va ein Signal von einem anderen Getreuen in der Nähe.\n\nSie glauben, er versteckt sich in diesem elenden kleinen Sumpf, dem Dämmerwurzmoor.\n\nIch werde Euch im Moor treffen, um ein Behelfssignal aufzustellen, bis ich die Bernscheinkuhle wieder zum Laufen bringe.\n\nIhr werdet den Getreuen erwecken und dann werdet Ihr mir helfen.", progress = nil, completion = "Wie es scheint, fängt meine Arbeit gleich an. Ihr seid an einen gefährlichen Ort gekommen, Erwecker.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31440] = {title = "Die vier Folianten", objective = "Vernichtet die vier Folianten: \"Im Schatten des Lichts\", \"Kel'Thuzads tiefgründiges Wissen\", \"Verbotene Riten und andere nekromantische Rituale\" und \"Der dunkle Zauberfoliant\".", description = "In Scholomance gibt es vier große Folianten mit mächtigem nekromantischem Wissen: \"Im Schatten des Lichts\", \"Kel'Thuzads tiefgründiges Wissen\", \"Verbotene Riten und andere nekromantische Rituale\" und \"Der dunkle Zauberfoliant\".\n\nWährend wir uns unseren Weg durch diesen verfluchten Ort bahnen, müsst Ihr jedes dieser Bücher finden und vernichten. Wir müssen verhindern, dass sich auch nur ein weiterer Dummkopf ihre teuflischen Geheimnisse zu eigen macht.", progress = "Die Geheimnisse der vier Folianten haben diesen Ort und alle, die mit ihm in Verbindung stehen, zu ewigem Leiden verdammt.\n\nSie müssen zerstört werden!", completion = "Danke, &lt;Name&gt;.\n\nDa die Folianten nun zerstört sind, kann ich meine ewige Ruhe in dem Wissen antreten, dass diese Bücher niemals wieder einer lebenden Seele schaden werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31441] = {title = "Korruption auf allen Ebenen", objective = "Bezwingt den Verräter im Dämmerwurzmoor.", description = "Heute lernt Ihr, dass man zu Kriegszeiten niemandem vertrauen kann, <Erwecker/Erweckerin>. Selbst diejenigen, die den Klaxxi am nächsten stehen, sind anfällig für Korruption.\n\nWer weiß, seit wann dieser Verräter schon verdorben ist. Er muss vernichtet werden!\n\nIhr seht verwirrt aus. Seht Ihr den Verräter in unseren Reihen denn nicht? Erlaubt mir, Euren Blick zu korrigieren.", progress = nil, completion = "Davon werdet Ihr mehr zu sehen bekommen. Der Krieg ist niemals ein hübscher Anblick.\n\nDie Verderbtheit der Kaiserin reicht weit und ist nur schwer zu entdecken.\n\nEs gibt viel zu tun. Wir müssen anfangen, den Schaden, den Kor'ik angerichtet hat, wiedergutzumachen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31442] = {title = "Die vier Folianten", objective = "Vernichtet die vier Folianten: \"Im Schatten des Lichts\", \"Kel'Thuzads tiefgründiges Wissen\", \"Verbotene Riten und andere nekromantische Rituale\" und \"Der dunkle Zauberfoliant\".", description = "In Scholomance gibt es vier große Folianten mit mächtigem nekromantischem Wissen: \"Im Schatten des Lichts\", \"Kel'Thuzads tiefgründiges Wissen\", \"Verbotene Riten und andere nekromantische Rituale\" und \"Der dunkle Zauberfoliant\".\n\nWährend wir uns unseren Weg durch diesen verfluchten Ort bahnen, müsst Ihr jedes dieser Bücher finden und vernichten. Wir müssen verhindern, dass sich auch nur ein weiterer Dummkopf ihre teuflischen Geheimnisse zu eigen macht.", progress = "Die Geheimnisse der vier Folianten haben diesen Ort und alle, die mit ihm in Verbindung stehen, zu ewigem Leiden verdammt.\n\nSie müssen zerstört werden!", completion = "Danke, &lt;Name&gt;.\n\nDa die Folianten nun zerstört sind, kann ich meine ewige Ruhe in dem Wissen antreten, dass diese Bücher niemals wieder einer lebenden Seele schaden werden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31443] = {title = "Fliegender Tigergurami", objective = "Bringt den fliegenden Tigergurami zu Nat Pagle an der Anlegestelle der Angler.", description = "Ihr habt einen einzigartigen Fisch gefangen... mit Flügeln. Vielleicht solltet Ihr Nat Pagle bei der Anlegestelle der Angler nach seiner Expertenmeinung fragen.", progress = "Fliegende Fische?", completion = "Ist das ein fliegender Tigergurami?\n\nBei diesem kleinen Fisch handelt es sich um eine seltene Mutation von Tigergurami, die des Fliegens mächtig sind und daher im Süßwasser von Pandaria gefangen werden können.\n\nDen hiesigen Legenden zufolge soll der Person, die diesen Fisch verzehrt, das Glück hold sein. Und die örtliche Tradition gebietet, dass nur der Adel ihn verzehren darf. Wer diese \"Tradition\" verletzt, unterschreibt damit sein eigenes Todesurteil.\n\nIch werde folglich dafür sorgen, dass der Fisch den richtigen Abnehmer findet.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31444] = {title = "Stachelfischalpha", objective = "Bringt den Stachelfischalpha zu Nat Pagle an der Anlegestelle der Angler.", description = "Ihr habt etwas ganz Besonderes gefangen... und es sieht ziemlich aggressiv aus.\n\nVielleicht weiß Nat Pagle an der Anlegestelle der Angler mehr darüber?", progress = "Merkwürdige Fische?", completion = "Das ist doch nicht etwa das, wofür ich es halte, oder? Oh Mann, ein Stachelfischalpha, eines der tödlichsten Raubtiere Pandarias.\n\nStachelfische sind verformte Monstrositäten, die durch die Gegenwart eines Sha entstanden. Die größten Exemplare sind einfach furchterregend. Die Alphatiere verschlingen oft die anderen Stachelfische, obwohl an ihnen absolut nichts Essbares ist.\n\nZu unser beider Glück sind sie für Alchemisten hochinteressant.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31445] = {title = "zzOld", objective = "Sprecht mit Angler Haito an der Anlegestelle der Angler in der Krasarangwildnis.Wenn Ihr all die Geheimnisse der Tiefsee erforschen und einige große Fische fangen wollt, sprecht mit meinem Bruder Haito an der Anglegestelle der Angler in der Krasarangwildnis.\n\nIch bin mir sicher, dass er Euch gern die eine oder andere Sache über die Angelkunst beibringt.", description = "Wenn Ihr all die Geheimnisse der Tiefsee erforschen und einige große Fische fangen wollt, sprecht mit meinem Bruder Haito an der Anglegestelle der Angler in der Krasarangwildnis.\n\nIch bin mir sicher, dass er Euch gern die eine oder andere Sache über die Angelkunst beibringt.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][31446] = {title = "Fintenfisch", objective = "Bringt den Fintenfisch zu Nat Pagle an der Anlegestelle der Angler.", description = "Ihr wisst nicht genau wie, aber Ihr habt einen außergewöhnlichen Kopffüßler gefangen. Nat Pagle an der Anlegestelle der Angler dürfte sich sehr dafür interessieren.", progress = "Sich tarnende Tintenfische?", completion = "Ist das ein Fintenfisch? Einer meiner Kumpels hat vor einigen Jahren mal einen vor der Küste von Zandalar gefangen. Hätte es fast nicht lebend zurück geschafft. Lästige Trolle dort, aber schöne Gegend zum Angeln!\n\nJedenfalls sind die Tierchen nicht so selten, wie Ihr vielleicht meint. Sie tarnen sich, um sich unter Steinen und Pflanzen zu verstecken. Nur die besten Angler können sich Chancen ausrechnen, diesen scheuen, aber unglaublich gut schmeckenden Leckerbissen zu fangen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31447] = {title = "Dem Leiden ein Ende", objective = "Tötet Dunkelmeister Gandling.", description = "Der Schlüssel zum Aufheben des Fluchs, der auf diesem Ort lastet, ist der endgültige Tod von Dunkelmeister Gandling.\n\nAlso los, $p... und lasst ihn dabei leiden!", progress = nil, completion = "Erblickt meine wahre Gestalt.\n\nIch stehe tief in Eurer Schuld, werde sie aber niemals begleichen können. Doch ich danke Euch, dass Ihr meine Familie von diesem Fluch befreit habt.\n\nKel'Thuzad, der Lichkönig, und nun auch Dunkelmeister Gandling - sie alle sind tot.\n\nVielleicht finde ja nun auch ich eine Art von Frieden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31448] = {title = "Dem Leiden ein Ende", objective = "Tötet Dunkelmeister Gandling.", description = "Der Schlüssel zum Aufheben des Fluchs, der auf diesem Ort lastet, ist der endgültige Tod von Dunkelmeister Gandling.\n\nAlso los, $p... und lasst ihn dabei leiden!", progress = nil, completion = "Erblickt meine wahre Gestalt.\n\nIch stehe tief in Eurer Schuld, werde sie aber niemals begleichen können. Doch ich danke Euch, dass Ihr meine Familie von diesem Fluch befreit habt.\n\nKel'Thuzad, der Lichkönig, und nun auch Dunkelmeister Gandling - sie alle sind tot.\n\nVielleicht finde ja nun auch ich eine Art von Frieden.", rewards = "Runenverzierte TodesknochenbrustplatteBlutbespritzter Brustharnisch des SchnitzersKaltschmiedepanzerFlickwerkfleischrüstungGhulhautgewänderErsatzrobe des DunkelmeistersMachterfüllte Robe des TotenbeschwörersBeschriftete BlutkettenhalsbergeEkelhafte KadaverrüstungIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31450] = {title = "Ein neues Schicksal", objective = "Sprecht mit dem Geist von Meister Shang Xi und entscheidet Euch dann, ob Ihr mit der Allianz oder der Horde losziehen wollt.", description = "Diese neuen Verbündeten haben uns Aufschluss über eine große und wichtige Wahrheit gegeben: Nicht nur Shen-zin Su geht es schlecht, sondern dem ganzen Land jenseits der Wolken. Die Welt muss geheilt werden, und ich glaube, dass Ihr ihre Heiler sein solltet.\n\nIch möchte, dass Ihr, Ji und Aysa aufbrecht, um Eure Stärke und Weisheit in die Welt zu tragen. Die Allianz und die Horde mögen verschiedene Ideale haben, doch tief in ihrem Inneren verfolgen sie beide edle Absichten.\n\nIhr sollt selbst entscheiden, wer Euch begleiten wird.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31451] = {title = "Der vermisste Händler", objective = "Sprecht mit Händler Shi am Tintenkiemenweiher am Kun-Lai-Gipfel.", description = "Normalerweise kommt Händler Shi zum Kun-Lai-Gipfel, um mit den Jinyu und Grummel Geschäfte zu machen. Wir haben gehört, dass er nicht in Binan gewesen sein soll, und wir haben ihn auch hier nicht gesehen...\n\nIch mache mir Sorgen... vielleicht ist ihm ja etwas zugestoßen. Könntet Ihr am Tintenkiemenweiher nachsehen? Möglicherweise ist er ja dort.", progress = nil, completion = "Mein Sohn! Sie haben mir meinen Sohn genommen... Könnt Ihr mir helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31452] = {title = "Der vermisste Händler", objective = "Sprecht mit Händler Shi am Tintenkiemenweiher am Kun-Lai-Gipfel.", description = "Normalerweise kommt Händler Shi zum Kun-Lai-Gipfel, um mit den Jinyu und Grummel Geschäfte zu machen. Wir haben gehört, dass er nicht in Binan gewesen sein soll, und wir haben ihn auch hier nicht gesehen...\n\nIch mache mir Sorgen... vielleicht ist ihm ja etwas zugestoßen. Könntet Ihr am Tintenkiemenweiher nachsehen? Möglicherweise ist er ja dort.", progress = nil, completion = "Mein Sohn! Sie haben mir meinen Sohn genommen... Könnt Ihr mir helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31453] = {title = "Die Shado-Pan", objective = "Sprecht mit Shado-Meister Chong am Shado-Pan-Rückzug in Feuerzweigwinkel.", description = "Unsere neuen Rekruten haben im Stillen über eine Gruppe Pandaren gesprochen, die sie als \"Shado-Pan\" bezeichnen. Allem Anschein nach sind sie sehr stark und geheimnisvoll.\n\nWas auch immer hier am Kun-Lai geschieht, eines steht fest: Um unsere Stellung in Pandaria zu festigen, sind wir auf ein Bündnis mit diesen Shado-Pan angewiesen.\n\nUnd genau da kommt Ihr ins Spiel. Gerüchten zufolge haben sie im Südosten eine Basis... in der Nähe von Feuerzweigwinkel.\n\nBegebt Euch dorthin und schmiert ihnen ordentlich Honig um den Bart. Für die Horde!", progress = nil, completion = "Wer seid Ihr? Könnt Ihr kämpfen? Sollte dem so sein, könnten wir Eure Hilfe gebrauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31454] = {title = "Eine Legende im Werden", objective = "Lasst Euch von Furorion einen ausgeben und trinkt mit ihm.", description = "Unsere Welt steht am Scheideweg. Die nächsten paar Monate werden die Weichen für die Zukunft stellen - sollte es für uns überhaupt noch eine Zukunft geben.\n\nAch, ich greife schon wieder zu weit vor. Ich sollte wohl einen Gang zurückschalten. Kommt, trinkt mit mir. Lasst uns über die Zukunft von Azeroth sprechen.", progress = "Ist alles klar?", completion = "Natürlich muss ich in dieser Angelegenheit um Eure Diskretion bitten.\n\nSchließlich wollen wir ja keine - wie soll ich sagen - weniger fähigen Leute auf den Plan rufen, als Ihr es seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31455] = {title = "Die Shado-Pan", objective = "Sprecht mit Shado-Meister Chong am Shado-Pan-Rückzug in Feuerzweigwinkel.", description = "Unsere neuen Rekruten haben im Stillen über eine Gruppe Pandaren gesprochen, die sie als \"Shado-Pan\" bezeichnen. Allem Anschein nach sind sie sehr stark und geheimnisvoll.\n\nUnd genau da kommt Ihr ins Spiel. Gerüchten zufolge haben sie im Südosten eine Basis... in der Nähe von Feuerzweigwinkel. Reist als <Gesandter/Gesandte> der Allianz dorthin und bietet ihnen alle nur erdenkliche Unterstützung an.", progress = nil, completion = "Wer seid Ihr? Könnt Ihr kämpfen? Sollte dem so sein, könnten wir Eure Hilfe gebrauchen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31456] = {title = "Gehöft Moschuspranke", objective = "Reist zum Gehöft Moschuspranke am Kun-Lai-Gipfel und sprecht dort mit Lao Moschuspranke.", description = "Es gibt hier draußen noch eine weitere Siedlung der Pandaren, das Gehöft Moschuspranke. Leider weiß ich nicht, ob es ihnen gut geht - die Yaungolinvasion hat uns alle ziemlich auf Trab gehalten.\n\nIhr wart uns schon eine so große Hilfe... vielleicht könntet Ihr ja nach ihnen sehen, <mein Freund/meine Liebe>?", progress = nil, completion = "Was? Wer zum Henker seid Ihr? Was wollt Ihr hier?\n\nAch, Ihr wollt helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31457] = {title = "Gehöft Moschuspranke", objective = "Reist zum Gehöft Moschuspranke am Kun-Lai-Gipfel und sprecht dort mit Lao Moschuspranke.", description = "Es gibt hier draußen noch eine weitere Siedlung der Pandaren, das Gehöft Moschuspranke. Leider weiß ich nicht, ob es ihnen gut geht - die Yaungolinvasion hat uns alle ziemlich auf Trab gehalten.\n\nIhr wart uns schon eine so große Hilfe... vielleicht könntet Ihr ja nach ihnen sehen, <mein Freund/meine Liebe>?", progress = nil, completion = "Was? Wer zum Henker seid Ihr? Was wollt Ihr hier?\n\nAch, Ihr wollt helfen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31458] = {title = "Schadenskontrolle", objective = "Vernichtet 5 Flüsterer der Ik'thik und deaktiviert das Signalfeuer von Kypari Ik.", description = "Kor'ik sendet seit Wochen Signale an die Kaiserin. Sie weiß über sämtliche Bewegungen der Klaxxi Bescheid.\n\nDas muss jetzt aufhören!\n\nKypari Ik wird als Erstes von Kor'iks Ableben erfahren. Es wäre von Vorteil für uns, wenn wir dafür sorgen könnten, dass diese Nachricht die Kaiserin nicht erreicht.\n\nDie Zerstörung der Flüsterer und des Signals dort wird uns genügend Zeit verschaffen, um einen Plan zu schmieden, ehe die Kaiserin reagieren kann.", progress = "Informationen bergen Macht, Erwecker. Wer über die meisten Informationen verfügt, hat auch die meiste Macht.", completion = "Ausgezeichnete Arbeit, Erwecker! Das sollte uns die Zeit verschaffen, um den von Kor'ik angerichteten Schaden zu reparieren.\n\nDamit habt Ihr vielleicht das Blatt zu unserem Vorteil gewendet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31459] = {title = "Chos Schreiben", objective = "Sprecht mit Lehrensucher Cho in Einfass am Kun-Lai-Gipfel.", description = "Einer der Grummel kam vorbei und sagte, Lehrensucher Cho habe nach Euch geschickt. Ihr solltet Euch mit ihm treffen, vielleicht hat er Euch ja etwas Wichtiges zu sagen.\n\nDer Grummel sagte, er sei in Einfass, Richtung Norden.", progress = nil, completion = "Oh, hallo. Schön, Euch wiederzusehen.", rewards = nil}
MultiLanguageQuestData['de'][31460] = {title = "Chos Schreiben", objective = "Sprecht mit Lehrensucher Cho in Einfass am Kun-Lai-Gipfel.", description = "Einer dieser putzigen kleinen Grummel kam vorbei und sagte, Lehrensucher Cho habe nach Euch geschickt. Ihr solltet Euch mit ihm treffen!\n\nDer Grummel sagte, er sei in Einfass, Richtung Norden.", progress = nil, completion = "Oh, hallo. Schön, Euch wiederzusehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31464] = {title = "Gegnerischer Fraktionsanführer besiegt", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][31465] = {title = "Antworten entlocken", objective = "Sammelt 6 mit Gift überzogene Mandibeln von Schwarmlingen der Ik'thik in Kypari Ik.", description = "Kypari Ik ist einer von vielen Orten, an denen der Nachwuchs von Kaiserin Shek'zeer untergebracht ist. Die Jungen sind von Geburt an waghalsig und schwer zu kontrollieren. Außerdem sind sie tödlich.\n\nSchwarmlinge kommen mit einem hochtoxischen Gift zur Welt, dessen Stärke sich mit zunehmendem Alter verringert. Das Gift setzt selbst den stärksten und fähigsten Kämpfer außer Gefecht, wenn es mit seinem Fleisch in Berührung gerät.\n\nIch möchte, dass Ihr mir etwas von diesem Gift bringt.", progress = "Schwarmlinggift verschafft uns nicht nur eine zusätzliche Waffe, sondern wird uns auch helfen, herauszufinden, in welcher Phase sich der Schwarm befindet.", completion = "Dieses Gift befindet sich in einer fortgeschrittenen Phase, jedoch scheint es seine Wirkung nicht zu verlieren...\n\nSehr merkwürdig. Die Klaxxi wollen das bestimmt sofort erfahren. Danke, Erwecker.", rewards = "KältebisshandgelenkwickelHandgelenkwickel des KlingenverschriebenenWindschnitterhandgelenksschutzGeisterfuchshandgelenkwickelSchreckensspinnerhandgelenkwickelKlarheitshandgelenkwickelVerdorrte HolzhandgelenkwickelSaftfliegenhandgelenkwickelMuttersaathandgelenkwickelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31467] = {title = "Stark wie ein Tiger", objective = "Erlernt das Rezept für gegrillte Tigersteaks vom Meister des Grills und bereitet dann 5 gegrillte Tigersteaks für ihn zu.", description = "Mit dem Grill könnt Ihr diese rohen Tigersteaks zu Nahrung verarbeiten, die Euch stärker macht. Lasst Euch von mir das Rezept für gegrillte Tigersteaks beibringen. Zeigt mir, was Ihr draufhabt.", progress = "Erlernt das Rezept von mir und zeigt mir dann, was Ihr gelernt habt.", completion = "Stärke und Gesundheit! Sie verkörpern die Wege des Grills.", rewards = "Ihr bekommt:\n\nEisentatzmarke"}
MultiLanguageQuestData['de'][31468] = {title = "Prüfung des Schwarzen Prinzen", objective = "Verdient Euch beim Schwarzen Prinzen einen wohlwollenden Ruf. Mogu und Mantis der Stufe 90 im Tal der Ewigen Blüten, der Tonlongsteppe und der Schreckensöde erhöhen Euren Ruf.", description = "Ich weiß aus verlässlicher Quelle, dass Ihr ein Champion unter den Champions seid, doch würde ich mich gerne selbst von Eurem Können überzeugen - wenn Ihr es gestattet.\n\nDie Mogu, die das Tal der Ewigen Blüten angegriffen haben, die Mogudiener, die in Shan'ze Dao leben, und die vom Sha verderbten Mantis, die die Schreckensöde durchstreifen... sie alle sollten eine angemessene Herausforderung für jemanden Eures Kalibers darstellen.\n\nUnd nun beweist es mir. Aber keine Eile - diese Aufgabe sollte einige Zeit in Anspruch nehmen.", progress = nil, completion = "Wunderbar. Das ging ja richtig flott.\n\nDie Kunde von Euren vielen Leistungen ist im Tal in aller Munde!\n\nNun denn, ich werde Euch unter meine Fittiche nehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31469] = {title = "UNUSED", objective = "Bereitet dem Meister des Grills ein gegrilltes Tigersteak zu. Dafür müsst Ihr zunächst den Weg des Grills sowie das Rezept von ihm erlernen.", description = "Der Weg des Grills der Pandaren bringt Gerichte hervor, die Eure körperliche Stärke erhöhen. Lernt das Rezept für gegrillte Tigersteaks vom Meister des Grills und demonstriert ihm, was Ihr gelernt habt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEisentatzmarke"}
MultiLanguageQuestData['de'][31470] = {title = "Weg des Woks", objective = "Bringt 5 saftigleckere Karotten zur Meisterin des Woks.", description = "Wenn Ihr Gerichte zubereiten wollt, die Eure Beweglichkeit steigern, solltet Ihr der Meisterin des Woks einige Karotten und Reis bringen. Die Shed-Ling in der Gegend tragen normalerweise viele Karotten mit sich. Wenn Ihr einen Hof habt, könnt Ihr sie auch selbst anbauen.", progress = "Hallo, junger Koch. Ihr wollt den Weg des Woks lernen?", completion = "Gut gemacht.", rewards = "Ihr erlernt:\n\nWeg des Woks\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWeg des Woks\n\nIhr bekommt außerdem:\n\nSaftigleckere KarotteEisentatzmarke"}
MultiLanguageQuestData['de'][31471] = {title = "Flink wie ein Tiger", objective = "Erlernt das Rezept für gebratene Karotten von der Meisterin des Woks und bereitet dann 5 Portionen für sie zu.", description = "Mit dem Wok zu kochen erfordert einiges Geschick. In Eurer ersten Lektion geht es um gebratene Karotten.", progress = "Lasst mich Euch beibringen, wie man gebratene Karotten zubereitet.", completion = "Gute Arbeit.", rewards = "Ihr bekommt:\n\nEisentatzmarke"}
MultiLanguageQuestData['de'][31472] = {title = "Weg des Topfes", objective = "Bringt 5 Jadelungenfische zur Meisterin des Topfes.", description = "Die Küche des Wegs des Topfes hilft Euch, Euren Verstand zu schärfen und somit Eure Intelligenz zu erhöhen. Bringt der Meisterin des Topfes einige Jadelungenfische und sie wird Euch unterweisen. Jadelungenfische könnt Ihr im Jadewald angeln.", progress = "Ihr wollt das Rezept für verwirbelte Nebelsuppe lernen? Dann bringt mir einige Jadelungenfische.", completion = "Sehr gut. Jetzt lasst uns mit Eurer Lektion beginnen.", rewards = "Ihr erlernt:\n\nWeg des Topfes\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWeg des Topfes\n\nIhr bekommt außerdem:\n\nJadelungenfischEisentatzmarke"}
MultiLanguageQuestData['de'][31473] = {title = "Die Stärke Eures Gegners", objective = "Sammelt 10 Siegel der Macht und 10 Siegel der Weisheit von Endbossen in himmlischen Dungeons oder von Schlachtzugsbossen im Mogu'shangewölbe, im Herzen der Angst oder auf der Terrasse des Endlosen Frühlings.", description = "Große Anführer haben die Macht, das Schicksal ihres Volkes zu lenken, und die Weisheit, die richtigen Entscheidungen zu treffen. Pandaria verfügt über große Macht und uralte Weisheit, doch leider findet man beide nur selten am selben Ort.\n\nWollen wir mal sehen, ob Ihr und ich daran etwas ändern können!\n\nSammelt Siegel der Macht und der Weisheit von den gefallenen Helden in himmlischen Dungeons, im Mogu'shangewölbe, im Herzen der Angst oder der Terrasse des Endlosen Frühlings. Wir werden sie sinnvoller einsetzen können als ihre gegenwärtigen Besitzer.", progress = "Siegel der Weisheit sind häufig bei jenen zu finden, die die arkanen Künste praktiziert haben, während Siegel der Macht üblicherweise bei jenen gefunden werden, die rohe Stärke bevorzugen.\n\nDas ist nicht immer der Fall, aber vielleicht hilft es Euch, das zu finden, was Ihr braucht.", completion = "Mein Freund - Ihr haltet, was Ihr versprecht!\n\nWir werden Eure \"Fundstücke\" gut nutzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31474] = {title = "Die Suppe des Nachsinnens", objective = "Erlernt das Rezept für verwirbelte Nebelsuppe vom Meister des Topfes und bereitet dann 5 Portionen Nebelsuppe für ihn zu.", description = "Während man auf den Kochtopf aufpasst, hat man sehr viel Zeit zum Nachdenken. Lasst mich Euch zeigen, wie man verwirbelte Nebelsuppe zubereitet, und Ihr werdet verstehen, was ich meine.", progress = "Um den Weg des Topfes zu erlernen, müsst Ihr mit verwirbelter Nebelsuppe beginnen.", completion = "Die Intelligenz ist eine Gabe, die Ihr ein Leben lang verfeinern müsst.", rewards = "Ihr bekommt:\n\nEisentatzmarke"}
MultiLanguageQuestData['de'][31475] = {title = "Weg des Dämpfens", objective = "Bringt 5 riesige Mantisgarnelen zum Meister des Dämpfens.", description = "Eine feine Mahlzeit kann Eure Moral heben und Eure Willenskraft stärken, und das gilt ganz besonders für Gerichte, die nach dem Weg des Dämpfens zubereitet wurden. Bringt dem Meister des Dämpfens einige riesige Mantisgarnelen und er wird Euch unterweisen. Riesige Mantisgarnelen könnt Ihr im Meer angeln.", progress = "Wenn Ihr den Weg des Dämpfens lernen wollt, braucht Ihr ein paar Shrimps.", completion = "Ausgezeichnete Zutaten.", rewards = "Ihr erlernt:\n\nWeg des Dämpfens\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWeg des Dämpfens\n\nIhr bekommt außerdem:\n\nRiesige MantisgarneleEisentatzmarke"}
MultiLanguageQuestData['de'][31476] = {title = "Kochen mit Liebe", objective = "Erlernt das Rezept für Garnelenklößchen vom Meister des Dämpfens und bereitet dann 5 Garnelenklößchen für ihn zu.", description = "Wenn ich mit Dampf koche, geht meine ganze kulinarische Liebe in mein Essen über. Lasst mich Euch beibringen, wie man Garnelenklößchen zubereitet.", progress = "Lasst mich Euch beibringen, wie man Garnelenklößchen zubereitet.", completion = "Gutes Essen bessert die Laune.", rewards = "Ihr bekommt:\n\nEisentatzmarke"}
MultiLanguageQuestData['de'][31477] = {title = "Durchhaltevermögen", objective = "Erlernt das Rezept für Wildgeflügelbraten von der Meisterin des Ofens und bereitet dann 5 Wildgeflügelbraten für sie zu.", description = "Es heißt, der vom Kranich ernannte Späher stünde bei seinem Schwarm mit einem Stein im Schnabel Wache. Sollte der Späher einschlafen, fällt der Stein herunter, und er wacht wieder auf. Der kunstvolle Umgang mit dem Ofen erfordert Durchhaltevermögen und Geduld. Lernt das Rezept für Wildgeflügelbraten und zeigt mir, dass Ihr das versteht.", progress = "Lasst Euch von mir das Rezept für Wildgeflügelbraten beibringen und dann sehen wir mal, was Ihr so draufhabt.", completion = "Ausdauer und Durchhaltevermögen sind die Voraussetzung, um alles Mögliche zu meistern. Sich an einem heißen Ofen abzurackern erfordert Geduld, die Ergebnisse sind die Mühen aber mehr als wert.", rewards = "Ihr bekommt:\n\nEisentatzmarke"}
MultiLanguageQuestData['de'][31478] = {title = "Weg des Ofens", objective = "Bringt 5 Stück Wildgeflügelbrust zur Meisterin des Ofens.", description = "Wenn Ihr auf der Suche nach einer herzhaften Mahlzeit seid, die Euch lange sättigt und Eure Ausdauer erhöht, solltet Ihr Euch in den Weg des Ofens einweisen lassen. Bringt der Meisterin des Ofens einige Stücke Wildgeflügelbrust und sie wird Euch unterweisen. Im Tal der Vier Winde und im Jadewald leben viele Kraniche, doch auch von anderen Vögeln könnt Ihr Wildgeflügelbrust erjagen.", progress = "Wenn Ihr Wildgeflügelbraten zubereiten wollt, benötigt Ihr einige Stücke Wildgeflügelbrust.", completion = "Hiermit können wir etwas anfangen.", rewards = "Ihr erlernt:\n\nWeg des Ofens\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWeg des Ofens\n\nIhr bekommt außerdem:\n\nWildgeflügelbrustEisentatzmarke"}
MultiLanguageQuestData['de'][31479] = {title = "Weg des Gebräus", objective = "Bringt 1 Ginseng zum Meister des Gebräus. Ginseng kann von Sunghshin Eisentatz erworben werden.", description = "Der pandarische Weg des Gebräus produziert... nun, das lasse ich wohl am besten den Meister des Gebräus erklären. Bringt ihm ein wenig Ginseng und er wird Euch den Weg zeigen.", progress = "Ihr wollt den Weg des Gebräus erlernen?", completion = "Das ist ein sehr schöner Ginseng. Wollt Ihr lernen, wie man daraus Tee kocht?", rewards = "Ihr erlernt:\n\nWeg des Gebräus\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWeg des Gebräus\n\nIhr bekommt außerdem:\n\nGinsengEisentatzmarke"}
MultiLanguageQuestData['de'][31480] = {title = "Tut Euch was Gutes", objective = "Erlernt das Rezept für Ginsengtee vom Meister des Gebräus und bereitet dann 1 Tee für ihn zu.", description = "Meine Geschwister sind immer so ernst. Ich finde, das Leben ist viel zu kurz, um die ganze Zeit ernst zu sein. Trinkt doch einen Schluck Ginsengtee mit mir. Ich werde Euch zeigen, wie man ihn zubereitet.", progress = "Lasst mich Euch beibringen, wie man Ginsengtee zubereitet.", completion = "Sehr gut. Der Tee ist köstlich.", rewards = "Ihr bekommt:\n\nEisentatzmarke"}
MultiLanguageQuestData['de'][31481] = {title = "Die Furcht selbst", objective = "Besiegt das Sha der Angst auf der Terrasse des Endlosen Frühlings und holt Euch die Schimäre der Angst.", description = "Während meiner Zeit hier habe ich die eine oder andere Pandarenweisheit aufgeschnappt. Ganz besonders gefällt mir diese hier:\n\n\"Die Furchtsamen bekommen Angst, bevor es Probleme gibt, die Feiglinge verspüren sie, wenn es Probleme gibt. Die Tapfersten unter uns spüren die Angst erst, nachdem die Probleme beseitigt wurden.\"\n\nIst das wirklich so? Wir werden es bald erfahren.\n\nDas Sha der Angst ist zur Terrasse des Endlosen Frühlings geflohen. Verfolgt es, besiegt es, und reißt ihm den Geist aus, sofern es einen hat.\n\nEuer Mut soll stattlich belohnt werden.", progress = "Noch eine Pandarenweisheit: \"Die Angst ist kein Verbrecher, der eingesperrt werden muss, sondern ein Lehrmeister, den wir verstehen müssen.\" Nur wenn wir uns unseren Ängsten stellen, werden wir auch stärker.\n\nHabt Ihr Euch schon den Euren gestellt, <Name>?", completion = "Ihr habt es geschafft!\n\nManche mögen ja auf Magie oder Stahl vertrauen, doch nach meiner Erfahrung ist die Angst die mächtigste Waffe, die man führen kann. Setzt sie gekonnt ein, und Eure Gegner werden gar nicht erst gegen Euch kämpfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31482] = {title = "Atem des Schwarzen Prinzen", objective = "Geht bis ans obere Ende der Steintreppe bei des Steinmetz' Torheit und holt Euch bei Furorion Eure Belohnung ab.", description = "<Furorions durchdringende rote Augen haben Euch fest im Blick.>\n\nSolche wie Euch findet man nur selten, <Name>.\n\nIhr seid genau, wonach ich suchte: Eine Person mit dem Potenzial, Ereignisse auf weltweiter Ebene zu beeinflussen.\n\nKommt nun, ich versprach Euch eine Belohnung, und die sollt Ihr auch haben! Östlich von dieser Höhle liegt eine Reihe steinerner Treppen, die zu einem Aussichtspunkt führen, den die Einheimischen \"Des Steinmetz' Torheit\" getauft haben. Trefft Euch dort mit mir.", progress = "Wir treffen uns vor der Taverne bei des Steinmetz' Torheit.", completion = "Ihr habt Euch das verdient, &lt;Name&gt;! Nutzt es mit Bedacht.\n\nBitte versteht, dass ich die Schulden meines Vaters zu begleichen beabsichtige. Ich werde ALLES daran setzen, diese Welt zu verteidigen. Wenn Ihr in Zukunft jemals Zweifel haben solltet, dürft Ihr jederzeit meine Mittel in Frage stellen, niemals aber meine Absichten. Die Sicherheit dieser Welt hat für mich oberste Priorität.\n\nNun denn, lasst uns über die aktuellen Geschehnisse sprechen.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nKristallisierter SchreckenKristallisierter TerrorKristallisierter Horror\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][31483] = {title = "Unheil im Verzug", objective = "Setzt Euch mit Furorion in Verbindung, wenn Eure Kriegsflotte die Südküste von Pandaria erreicht hat.", description = "Der Feldzug der Pandaren hat gerade erst begonnen! Wir wenden unsere Aufmerksamkeit nun dem fortwährenden Konflikt zwischen der Allianz und der Horde zu.\n\nMeine Kontaktpersonen in Rabenholdt berichten mir, dass die 7. Legion der Allianz und eine beachtliche Invasionsstreitmacht der Horde sich der Südküste Pandarias nähern. Ob es uns nun gefällt oder nicht: Pandaria könnte schon bald zu einem Schlachtfeld werden.\n\nFürs Erste sind wir hier fertig, aber ich möchte, dass Ihr Euch bei mir meldet, wenn die Flotte eintrifft. Dann... werden wir gemeinsam in Aktion treten!", progress = nil, completion = "Sie sind da!\n\n&lt;Furorion klatscht in die Hände und reibt sie aufgeregt zusammen.&gt;\n\nAch, &lt;Name&gt;. Jetzt wird es spannend.", rewards = nil}
MultiLanguageQuestData['de'][31485] = {title = "UNUSED", objective = "Erlernt das Rezept für weichgekochte Eier von der Weiserin der Wege und bereitet ihr 5 von ihnen zu.", description = "Ich bin kein Meisterkoch wie meine Geschwister, doch bin ich ein erstklassiger Lehrer. Wenn Ihr engagiert seid, kann ich Euer verstecktes Potential zum Vorschein bringen, ganz egal, wie wenig Erfahrung Ihr habt.\n\nWenn Ihr lernen wollt, so zeigt mir, dass Ihr zumindest grundlegenden Anweisungen folgen könnt. Erlernt das Rezept für weichgekochte Eier, stellt fünft davon her und bringt sie zu mir. Ich habe frische Eier, die ich Euch zu einem geringen Preis anbieten kann.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31486] = {title = "Alles, was ich übers Kochen weiß", objective = "Überbringt Sungshin Eisentatz den Brief. Sie unterrichtet auf dem Halbhügelmarkt.", description = "Ich bin so froh, dass Euch mein Essen schmeckt. Wärt Ihr vielleicht an den Rezepten interessiert? Falls ja, solltet Ihr sie aus erster Hand von meinen Lehrern vom Halbhügelmarkt lernen. Alles, was ich über die Küche weiß, habe ich bei ihnen gelernt.\n\nUnd wenn Ihr sowieso in diese Gegend kommt, könntet Ihr dann vielleicht Sungshin Eisentatz diese Nachricht überbringen? Sie war meine Lieblingslehrerin. Ich vermisse sie, und ich möchte, dass sie das auch weiß.", progress = "Ihr habt einen Brief für mich?", completion = "Oh, wie aufmerksam. Ich höre immer sehr gerne von meinen ehemaligen Schülern.", rewards = "Ihr bekommt:\n\nEisentatzmarke"}
MultiLanguageQuestData['de'][31487] = {title = "Misstöne", objective = "Tötet 4 Schreckenskunchong und 6 Shek'zeer Manipulatoren in den Gelegen von Shek'zeer. Die Stimmgabel der Verwirrung wird die Kunchong verwirren und schwächen.", description = "Mit Schallgeflüster die Kunchong zu manipulieren war nur die allererste Phase meiner Forschungen und doch scheint es, als ob das Reich diese Technik vollständig übernommen hat. Die Manipulatoren der Shek'zeer sind zu ungeduldig, eine gebührliche Verbindung mit ihren Kunchong einzugehen.\n\nIhre Faulheit wird sie teuer zu stehen kommen.\n\nSchlagt die Stimmgabel nahe der Schreckenskunchong in den Gelegen an und seht, wie sie vor Verwirrung taumeln und ihre Herren angreifen werden. Nutzt diesen Vorteil aus und macht ihnen den Garaus.", progress = nil, completion = "Möge Euch dies eine Mahnung sein. Die Kunchong sollte man sowohl fürchten als auch respektieren.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31488] = {title = "Fremd in einem fremden Land", objective = "Sucht den \"Schwarzen Prinzen\" in der Taverne im Nebel an der Verhüllten Treppe auf.", description = "Verzeihung, <Klasse>. Heißt Ihr <Name>?\n\nEine Gestalt in einem dunklen Umhang hat mich gebeten, Euch das hier zu geben. Es war eine Reisende von hinter den Nebeln so wie Ihr, aber - nun, ich habe ihr nicht getraut.\n\nDie Nachricht kommt von einer Taverne an der Verhüllten Treppe. Ich gebe Euch die Nachricht, aber... Ihr solltet auf Euch achtgeben, wenn Ihr Euch dort hinaufwagt!", progress = "Dann hat meine Nachricht also ihren Weg zu Euch gefunden!", completion = "Meine Leute haben ihren Auftrag erfüllt und Euch zu mir gebracht. Wunderbar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31489] = {title = "Fremd in einem fremden Land", objective = "Sucht Furorion in der Taverne im Nebel an der Verhüllten Treppe auf.", description = "Verzeihung, <Klasse>. Heißt Ihr <Name>?\n\nEine Gestalt in einem dunklen Umhang hat mich gebeten, Euch das hier zu geben. Es war eine Reisende von hinter den Nebeln so wie Ihr, aber - nun, ich habe ihr nicht getraut.\n\nSie erwähnte den Namen \"Furorion\". Könnt Ihr damit etwas anfangen?\n\nIch gebe Euch die Nachricht, aber... Ihr solltet auf Euch achtgeben, wenn Ihr mit diesen Leuten zu tun habt.", progress = "So sieht man sich wieder!", completion = "Meine Leute haben ihren Auftrag erfüllt und Euch zu mir gebracht. Wunderbar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31490] = {title = "Gegen das Fußvolk", objective = "Tötet 50 Mitglieder des Scharlachroten Kreuzzugs in den Scharlachroten Hallen.", description = "Das Wichtigste zuerst: Wir müssen dringend einige Kreuzfahrer loswerden.\n\nUnd wenn ich davon spreche, den Scharlachroten Kreuzzug loszuwerden, meine ich, ihn auszulöschen: ALLE Kreuzfahrer bis hinunter in die untersten Dienstränge!", progress = nil, completion = "Ein guter Anfang, &lt;Name&gt;!\n\nJetzt dauert es nicht mehr lange, bis der Scharlachrote Kreuzzug nur noch eine hässliche Fußnote der Geschichte sein wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31492] = {title = "Die Fackel der Stärke", objective = "Tragt die Fackel der Stärke zu den Toren des Tempels des Weißen Tigers, ohne dass sie erlischt.", description = "Xuen hat sich eine Aufgabe ausgedacht, die dazu dienen soll, die \"Stärke zu verfeinern\". Ich glaube allmählich, dass der Begriff \"Stärke\" für ihn eine andere Bedeutung hat als für den Rest von uns.\n\nHier, bringt diese Fackel auf die Tore des Tempels. Wenn Ihr das schafft, ohne dass die Fackel erlischt, habt Ihr die Aufgabe bestanden.\n\nSetzt Euch aber auf keinen Fall mit der Fackel auf ein Reittier. Dann geht sie aus. Das könnt Ihr mir ruhig glauben.", progress = nil, completion = "Alle Achtung! Ihr habt's geschafft! Ich scheitere meist an einer dieser Windböen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31493] = {title = "Im Namen von Sicherheit und Ordnung", objective = "Holt Euch den Kodex des Kreuzzugs.", description = "Hier in den Hallen gibt es ein Buch, das großen Wert für mich hat.\n\nAber leider befindet es sich im Besitz von Flammenwirker Koegler. Ich habe schon mehrmals versucht, in seine Nähe zu kommen, aber es hat nie funktioniert.\n\nVielleicht habt Ihr ja mehr Glück. Aber passt auf Euch auf: Ich habe gehört, dass er komplett wahnsinnig geworden sein soll. Der Flammenwirker plant, alle Bücher der Bibliothek zu verbrennen.\n\nWahrscheinlich wird er dabei gleich die Scharlachroten Hallen selbst niederbrennen.", progress = "Ich muss unbedingt diesen Kodex in meinen Besitz bringen.", completion = "Ah, da ist er ja!\n\n&lt;Die vermummte Kreuzfahrerin reibt sich beim Anblick des Kodex voller Vorfreude die Hände.&gt;\n\nUnd jetzt habe ich eine Namensliste aller Mitglieder des Scharlachroten Kreuzzugs!\n\nNur für den Fall, dass jemand nicht ordnungsgemäß gelistet ist. Ich halte in solchen Dingen gerne Ordnung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31494] = {title = "Ihren Fängen entronnen", objective = "Brecht Kunchongkäfige auf, um 8 Kunchongjungtiere in den Gelegen von Shek'zeer freizulassen.", description = "Die Manipulatoren der Shek'zeer sperren junge Kunchong in das Gelege und setzen sie reinen Furchtenergien aus, die sie korrumpieren und ihr Wachstum beschleunigen.\n\nAbscheulich! Das lasse ich nicht zu!\n\nBrecht die Käfige auf und entlasst die Jungtiere in die Freiheit.", progress = nil, completion = "Ja, ich konnte sehen, wie sie sich erhoben. Ein wunderschöner Anblick!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31495] = {title = "Gegen das Fußvolk", objective = "Tötet 50 Mitglieder des Scharlachroten Kreuzzugs in den Scharlachroten Hallen.", description = "Das Wichtigste zuerst: Wir müssen dringend einige Kreuzfahrer loswerden.\n\nUnd wenn ich davon spreche, den Scharlachroten Kreuzzug loszuwerden, meine ich, ihn auszulöschen: ALLE Kreuzfahrer bis hinunter in die untersten Dienstränge!", progress = nil, completion = "Ein guter Anfang, &lt;Name&gt;!\n\nJetzt dauert es nicht mehr lange, bis der Scharlachrote Kreuzzug nur noch eine hässliche Fußnote der Geschichte sein wird.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31496] = {title = "Eine Kostprobe vom Feinsten", objective = "Benutzt das Harzgefäß an den kaiserlichen Zapfstellen vor dem Herzen der Angst viermal, um es zu füllen.", description = "Die Wunder des Kyparisaftes versetzen mich immer wieder in Erstaunen. Neben seinen zahlreichen Eigenschaften und Anwendungen lässt sich der Saft zu einem nahrhaften und äußerst aromatischen Elixier verfeinern.\n\nIhr werdet nirgendwo im Reich eine exquisitere Zubereitung dieses Gebräus finden als im Palast selbst. Gewiss finden sich doch in den Heimen der Getreuen Zapfstellen, die bis zum Rand mit diesem süßen Nektar gefüllt sind.\n\nFüllt mir diesen Krug an den Zapfstellen und bringt ihn mir. Ich sehne mich danach, das kaiserliche Ambrosia noch einmal zu schmecken.", progress = nil, completion = "Ah, ja, gebt her! Schnell! Meine Vorderbeine zittern vor Erwartung.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31497] = {title = "Im Namen von Sicherheit und Ordnung", objective = "Holt Euch den Kodex des Kreuzzugs.", description = "Hier in den Hallen gibt es ein Buch, das großen Wert für mich hat.\n\nAber leider befindet es sich im Besitz von Flammenwirker Koegler. Ich habe schon mehrmals versucht, in seine Nähe zu kommen, aber es hat nie funktioniert.\n\nVielleicht habt Ihr ja mehr Glück. Aber passt auf Euch auf: Ich habe gehört, dass er komplett wahnsinnig geworden sein soll. Der Flammenwirker plant, alle Bücher der Bibliothek zu verbrennen.\n\nWahrscheinlich wird er dabei gleich die Scharlachroten Hallen selbst niederbrennen.", progress = "Ich muss unbedingt diesen Kodex in meinen Besitz bringen.", completion = "Ah, da ist er ja!\n\n&lt;Die vermummte Kreuzfahrerin reibt sich beim Anblick des Kodex voller Vorfreude die Hände.&gt;\n\nUnd jetzt habe ich eine Namensliste aller Mitglieder des Scharlachroten Kreuzzugs!\n\nNur für den Fall, dass jemand nicht ordnungsgemäß gelistet ist. Ich halte in solchen Dingen gerne Ordnung.", rewards = "Taillenschutz der KampflinieGürtel des Scharlachroten ChampionsVerdones angekauter TaillenplattenschutzGürtel der angesengten HoffnungGurt des EimerausschüttersKordel der blutigen BekehrungSchulmeisterkordelBindungen des Scharlachroten BogenschützenLokseys verschollener GürtelIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31498] = {title = "Herausforderungsmodus der Jadeschlange - Trostpreis (Nter)", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31499] = {title = "Herausforderungsmodus der Jadeschlange - Bronze (Nter)", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31500] = {title = "Herausforderungsmodus der Jadeschlange - Silber (Nter)", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31501] = {title = "Herausforderungsmodus der Jadeschlange - Gold (Nter)", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31502] = {title = "Gestutzte Flügel", objective = "Sammelt 24 Nadlerflügel von Nadlern der Shek'zeer in den Gelegen von Shek'zeer.", description = "Die jungen Flieger dieser Ära sind faszinierend. Über ihre außergewöhnliche Wendigkeit und Ausdauer verfügten zu meiner Zeit nur unglaublich geschickte oder erfahrene Flieger.\n\nDas würde auf eine Art der Evolution in der Flügelstruktur hindeuten... Oder vielleicht eine Weiterentwicklung in der Ausbildung? Herbeigeführte genetische Mutation? Selektive Züchtung?\n\nAch! Ohne Gewebeproben lässt sich das unmöglich mit Gewissheit sagen.\n\nBringt mir ihre Flügel! Und versucht sie dabei nicht zu ruinieren, ja? Ich brauche sie intakt!", progress = "Habt Ihr die Proben?", completion = "Hervorragend, sie sind in erstklassigem Zustand.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31503] = {title = "Abkürzung zum Ruin", objective = "Tötet Vesswache Na'kal vor dem Herzen der Angst.", description = "Unter den Getreuen gibt es einen Champion, Vesswache Na'kal, dessen Stärke nicht aus seiner Erfahrung oder Entwicklung herrührt, sondern aus genetischer Modifikation. Er sollte als Musterbeispiel für die Zukunft der Mantis dienen - für die kranke Vorstellung, dass wir stark geboren werden könnten, ohne selbst etwas dazu zu tun.\n\nEr ist eine Pervertierung meiner Arbeit! Die Genverbesserung war AUSSCHLIESSLICH für reife Veteranen gedacht, die den Schwarm bereits hinter sich gelassen haben!\n\nVernichtet ihn. Vielleicht lernt Großkaiserin Shek'zeer daraus, dass Abkürzungen zum Ruin führen.", progress = nil, completion = "Meine Verbesserungen sind Werkzeuge für erfahrene Krieger und keine Spielzeuge für diese törichten Kinder!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31504] = {title = "Abrüstung", objective = "Schaltet 8 Pheromonminen rund um die Gelege von Shek'zeer und das Herz der Angst aus.", description = "Wenn die Agenten der Großkaiserin noch nach den Sicherheitsstandards meiner Zeit arbeiten, werden sie überall in den Gelegen gewaltige Pheromonminen versteckt haben.\n\nDiese könnte sie durch ein bloßes Flüstern alle gleichzeitig hochgehen lassen, um den Palast einzuhüllen und ganzen Belagerungsarmeen die Kräfte zu rauben.\n\nWenn wir bei einer größeren Konfrontation auf Erfolg hoffen wollen, müssen wir die Minen entschärfen. Mein... \"Geschenk\" an Euch, als wir uns begegneten, wird Euch in die Lage versetzen, die Minen zu sehen. Löst sie aus und begebt Euch in eine sichere Entfernung.", progress = nil, completion = "Ihr wart den Pheromonen doch nicht ausgesetzt? Das könnte nämlich zu... ach, was soll ich Euch mit Details beunruhigen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31505] = {title = "Vesswachenpflichten", objective = "Tötet Vesswache Vik'az in Zan'vess.", description = "Vesswache Vik'az koordiniert die Verteidigungstruppen in Zan'vess. Er ist im Kampf so viel wert wie zehn Mantis, und seine Gegenwart inspiriert die Zan'thik, die an seiner Seite kämpfen.\n\nIch brauche wohl kaum zu erwähnen, dass wir ihn tot sehen wollen.\n\nEr patrouilliert in dem Siedlungsbereich im Zentrum der Insel.", progress = nil, completion = "Ihre Champions fallen einer nach dem anderen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31506] = {title = "Fesseln der Manipulation", objective = "Sammelt 6 Fesseln der Zan'thik von gedankengefesselten Minenarbeitern und gedankengefesselten Schlägern in Zan'vess.", description = "Die Zan'thik verfügen über eine ganze Armee von... Arbeitsverpflichteten.\n\nYaungol tragen spezielle Fesseln, die die Auswirkungen von Schallmanipulationen verstärken und verlängern. Nur dank dieser Technik können die Manipulatoren der Zan'thik solch eine große Zahl an Knechten kontrollieren, die unaufhörlich in den Steinbrüchen für sie schuften müssen.\n\nDiese Fesseln würde ich gern untersuchen.", progress = "Das werdet Ihr doch schaffen, nicht wahr?", completion = "Wirklich ausgeklügelte Vorrichtungen. Ich habe das Gefühl, die werden sich noch als nützlich erweisen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31507] = {title = "Kernschmelze", objective = "Tötet 6 Giftstecher der Zan'thik in Zan'vess. Setzt Korvens experimentelle Granate ein, um ihren Panzer zu durchdringen.", description = "Die Giftstecherskorpione auf Zan'vess werden schon von klein auf mit Saft ernährt, der eine faszinierende Mutation bewirkt, bei der ihr natürlicher Panzer von Bern durchdrungen wird. Das ist nichts anderes als organisches Kyparit - die gleiche Substanz, die zum Schmieden der meisten Waffen und Rüstungen des Reiches verwendet wird.\n\nIch glaube, ich habe eine Methode gefunden, Kyparit chemisch aufzuschließen, aber sie muss noch getestet werden. Setzt diese Granaten gegen die Giftstecher der Zan'thik ein und beobachtet die Ergebnisse.", progress = nil, completion = "Das Kyparit hat sich also entzündet? Faszinierend!\n\nNicht ganz das, worauf ich gehofft hatte, aber immerhin.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31508] = {title = "Probenanforderung", objective = "Sammelt 6 Kyparitsplitter von Kyparitkriechern im Salzigen Schlick.", description = "Kyparitwürmer können sich extrem gut anpassen, um ihre Umwelt zu imitieren. Sie können außerdem auf eine gewaltige Größe anwachsen, und das in einem Tempo, das für die meisten Kreaturen unerhört ist.\n\nIhre Physiologie könnte wertvolle Einblicke in weitere Mutationen bieten.\n\nBringt mir Splitterproben von Kyparitkriechern in den Untiefen bei Zan'vess.", progress = "Habt Ihr die Proben?", completion = "Na seht an, Ihr habt es tatsächlich geschafft. Ich war schon fast darauf gefasst, Eure Reste mit einem Krug aus dem Schlamm schöpfen zu müssen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31509] = {title = "Verwurzelte Furcht", objective = "Vernichtet 15 Furchtsporenknollen in Zan'vess und im Salzigen Schlick.", description = "Die Folgen von Shek'zeers Wahnsinn werden noch lange nach dem Ende ihrer Herrschaft zu spüren sein. Wir werden noch viele Jahre damit zu kämpfen haben, unser Land zu heilen, und am Ende werden sich unsere Bemühungen womöglich doch als nutzlos erweisen.\n\nEine neue Spezies von Sha-verderbter Flora hat begonnen, in der Nähe von Zan'vess Wurzeln zu schlagen. Vernichtet alle Pflanzen, die Ihr findet, aber nehmt Euch in Acht – man kann nie wissen, welch unheilvolle Verteidigungsmechanismen sie haben mögen.", progress = nil, completion = "Eine interessante Spezies, aber die Risiken, sie zu Studienzwecken zu behalten, sind zu groß.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31510] = {title = "Jetzt ist Ruhe", objective = "Macht Euch an dem Resonanzkristall der Zan'thik bei den Flüsternden Steinen in Zan'vess zu schaffen, um den Gehilfen Sek'ot zu reizen, und tötet ihn.", description = "In der südwestlichen Ecke von Zan'vess liegen die Flüsternden Steine. Ähnlich wie die Türme hier sind sie für die Übertragung von Schallsignalen über weite Entfernungen sehr wichtig.\n\nEin Gehilfe der Kaiserin bedient die Steine und sorgt so für eine Verbindung zwischen ihr und den Truppen der Zan'thik. Unterbrecht das Signal und bringt ihn dann zum Schweigen.", progress = nil, completion = "Den Kontakt zu Zan'vess zu verlieren, muss sie weiter in den Verfolgungswahn und Wahnsinn treiben.\n\nGut. Soll sie leiden.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31511] = {title = "Ein historischer Moment", objective = "Sprecht mit Sonnenläufer Dezco am Tor der Himmlischen Erhabenen.", description = "Ich trommle die anderen Taurenpilger zusammen und wir reisen gemeinsam ins Tal.\n\nTrefft mich am Tor der Himmlischen Erhabenen im Süden des Kun-Lai-Gipfels und sprecht dort mit mir.", progress = nil, completion = "Danke, dass Ihr so schnell zur Stelle seid.\n\nJahrtausende lang hat der Goldene Lotus das Tal vor den Zugriffen jener, die vom Hunger nach seiner Macht getrieben wurden, bewahrt.\n\nLeider sind diese Zeiten vorbei, und wir brauchen Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31512] = {title = "Ein historischer Moment", objective = "Sprecht mit Anduin Wrynn am Tor der Himmlischen Erhabenen.", description = "Die Himmlischen Erhabenen gewähren uns erneut Zugang zum Tal! Das wird ein unvergesslicher Anblick sein.\n\nWir sollten keine Zeit verlieren. Geht zum Tor der Himmlischen Erhabenen im Süden des Kun-Lai-Gipfels und sprecht dort mit mir.", progress = nil, completion = "Danke, dass Ihr so schnell zur Stelle seid.\n\nJahrtausende lang hat der Goldene Lotus das Tal vor den Zugriffen jener, die vom Hunger nach seiner Macht getrieben wurden, bewahrt.\n\nLeider sind diese Zeiten vorbei, und wir brauchen Eure Hilfe.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31513] = {title = "Die Klingen des Gesalbten", objective = "Findet die zwei Klingen des Gesalbten.", description = "Das Problem mit dem Scharlachroten Kreuzzug ist, dass seine Kreuzfahrer selbst nach dem Tod immer wiederkehren.\n\nHinter diesen Wiederbelebungen steckt die Hochinquisitorin Weißsträhne. Ihr Tod wäre das Ende des Kreuzzuges.\n\nUm sie endgültig ins Jenseits zu schicken, benötigen wir zwei legendäre Schwerter, jedes von ihnen mit einer lange verschollenen Geschichte.\n\nZum Glück für mich... äh, ich meine uns... befinden sich diese Klingen des Gesalbten hier irgendwo im Kloster.\n\nFindet sie und stoßt sie in Weißsträhnes Leichnam, nachdem Ihr sie getötet habt. Dadurch ist ihr Tod endgültig.", progress = "<Nachdem Ihr das eine Schwert eingesammelt habt, wendet Ihr Euch der Suche nach dem zweiten zu.>\n\n<Auf der Statue hinter dem Schwert befindet sich eine Inschrift: \"Die Hand der Vorsehung\".>", completion = "&lt;Die zweite gesalbte Klinge schwebt vor der nassen Statue. Dampf steigt vom Schwert auf.&gt;\n\n&lt;Ihr habt das ungute Gefühl, dass die Hand der Vorsehung auf Euch gewartet hat.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31514] = {title = "Und zum Staub werdet Ihr zurückkehren", objective = "Durchbohrt mit den Klingen des Gesalbten den Leichnam der Hochinquisitorin Weißsträhne, um sie endgültig zu töten.", description = "<Ihr nehmt die zweite Klinge des Gesalbten in die Hand und fühlt, wie Euch die Kraft der beiden Schwerter durchströmt.>\n\n<Aber es bleibt noch eins zu tun: Wie Euch die mysteriöse Frau mit der Kapuze erklärte, müssen beide Schwerter in den Leichnam der Hochinquisitorin Weißsträhne gestoßen werden, um den Scharlachroten Kreuzzug ein für alle Mal zu besiegen.>", progress = nil, completion = "Jetzt wo Weißsträhne endgültig tot ist, ist auch der Kreuzzug am Ende. Es ist nur noch eine Frage der Zeit, bis wir seinen Widerstand gebrochen haben werden.\n\nIch danke Euch, &lt;Name&gt;. Nicht nur um meiner selbst willen, sondern auch im Namen aller, die diesem fanatischen Hass ausgesetzt waren.\n\nUnd danke auch für die beiden Schwerter. Durch ihr Blut aufs Neue gesalbt, werden sie mir im Kampf gegen Dunkelmeister Gandling in Scholomance gute Dienste leisten.\n\nUnd jetzt möchte ich mich von Euch verabschieden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31515] = {title = "Die Klingen des Gesalbten", objective = "Findet die zwei Klingen des Gesalbten.", description = "Das Problem mit dem Scharlachroten Kreuzzug ist, dass seine Kreuzfahrer selbst nach dem Tod immer wiederkehren.\n\nHinter diesen Wiederbelebungen steckt die Hochinquisitorin Weißsträhne. Ihr Tod wäre das Ende des Kreuzzuges.\n\nUm sie endgültig ins Jenseits zu schicken, benötigen wir zwei legendäre Schwerter, jedes von ihnen mit einer lange verschollenen Geschichte.\n\nZum Glück für mich... äh, ich meine uns... befinden sich diese Klingen des Gesalbten hier irgendwo im Kloster.\n\nFindet sie und stoßt sie in Weißsträhnes Leichnam, nachdem Ihr sie getötet habt. Dadurch ist ihr Tod endgültig.", progress = "<Nachdem Ihr das eine Schwert eingesammelt habt, wendet Ihr Euch der Suche nach dem zweiten zu.>\n\n<Auf der Statue hinter dem Schwert befindet sich eine Inschrift: \"Die Hand der Vorsehung\".>", completion = "&lt;Die zweite gesalbte Klinge schwebt vor der nassen Statue. Dampf steigt vom Schwert auf.&gt;\n\n&lt;Ihr habt das ungute Gefühl, dass die Hand der Vorsehung auf Euch gewartet hat.&gt;", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31516] = {title = "Und zum Staub werdet Ihr zurückkehren", objective = "Durchbohrt mit den Klingen des Gesalbten den Leichnam der Hochinquisitorin Weißsträhne, um sie endgültig zu töten.", description = "<Ihr nehmt die zweite Klinge des Gesalbten in die Hand und fühlt, wie Euch die Kraft der beiden Schwerter durchströmt.>\n\n<Aber es bleibt noch eins zu tun: Wie Euch die mysteriöse Frau mit der Kapuze erklärte, müssen beide Schwerter in den Leichnam der Hochinquisitorin Weißsträhne gestoßen werden, um den Scharlachroten Kreuzzug ein für alle Mal zu besiegen.>", progress = nil, completion = "Jetzt wo Weißsträhne endgültig tot ist, ist auch der Kreuzzug am Ende. Es ist nur noch eine Frage der Zeit, bis wir seinen Widerstand gebrochen haben werden.\n\nIch danke Euch, &lt;Name&gt;. Nicht nur um meiner selbst willen, sondern auch im Namen aller, die diesem fanatischen Hass ausgesetzt waren.\n\nUnd danke auch für die beiden Schwerter. Durch ihr Blut aufs Neue gesalbt, werden sie mir im Kampf gegen Dunkelmeister Gandling in Scholomance gute Dienste leisten.\n\nUnd jetzt möchte ich mich von Euch verabschieden.", rewards = "Stulpen der kriegerischen LäuterungStulpen der rechtschaffenen VerurteilungHandschützer der fanatischen InbrunstHandschuhe der HeiligkeitVorteilhafte HandschuheHandschuhe des Scharlachroten VisionärsHandschuhe der feurigen LäuterungStulpen des blutigen GerichtsPurpurrote MönchshandlappenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31517] = {title = "Rabaukenkampf", objective = "Besiegt Shonuf.", description = "Hier achten wir Stärke, nicht Brutalität. Es ist bedauerlich, dass sich so mancher auf meiner Türschwelle einfindet, dem diese Unterscheidung unklar ist.\n\nIch habe einen solchen Herausforderer abgewiesen. Aus Rache ist er über das Dorf Yinying hergefallen.\n\nGeht nach Yinying, südlich des Tempels, und stellt Euch diesem \"Shonuf\".", progress = nil, completion = "Ich preise Euren Sieg und danke Euch, dass Ihr mir diesen Grobian vom Hals geräumt habt.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31518] = {title = "Das Tal der Ewigen Blüten", objective = "Sprecht mit Anduin am Tor der Himmlischen Erhabenen.", description = "Es sind viele Lebensalter vergangen, seit die Tore zum Tal offen standen, <Name>.\n\nDas würde ich um alles in der Welt nicht verpassen wollen, und Ihr solltet das auch nicht!\n\nTrefft mich am Südrand des Kun-Lai-Gipfels. Ich werde dort auf Euch warten.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][31519] = {title = "Eine würdige Herausforderung: Yan-Zhu der Dekantierte", objective = "Schließt die Brauerei Sturmbräu im Herausforderungsmodus ab.", description = "<Name>, Ihr müsst eine beherzte Gruppe zusammenstellen und sie in die Brauerei Sturmbräu führen. Aktiviert die Kugel des Herausforderers und helft Yan-Zhu dem Dekantierten, sich zu verdünnisieren.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31520] = {title = "Eine würdige Herausforderung: Sha des Zweifels", objective = "Schließt den Tempel der Jadeschlange im Herausforderungsmodus ab.", description = "<Name>, Ihr müsst eine beherzte Gruppe zusammenstellen und sie in den Tempel der Jadeschlange führen. Aktiviert die Kugel des Herausforderers und vernichtet das Sha des Zweifels.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", progress = nil, completion = "Mein Dank ist Euch gewiss, &lt;Name&gt;. Ihr habt heute großen Mut an den Tag gelegt und die Herausforderung in Windeseile bewältigt. Eure Freunde werden beeindruckt und Eure Gegner verängstigt sein.", rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31521] = {title = "Pflichten eines Meisters", objective = "Bereitet Rippchen mit schwarzem Pfeffer und Garnelen, Küstennebelreisnudeln, Fischeintopf nach Moguart, Gedämpfte Krabbe, Chun-Tian-Frühlingsrollen und ein wahnsinniges Brauerfrühstück zu und kehrt dann zur Weiserin der Wege zurück.", description = "Es wird der Tag kommen, an dem Ihr alles gemeistert haben werdet, was wir Euch beizubringen haben. An jenem Tag ist es Zeit für Euch, andere etwas zu lehren. Wenn Ihr unter Beweis gestellt habt, dass Ihr alle Wege gemeistert habt, kommt zurück und redet mit mir.", progress = nil, completion = "Ihr wart ein sehr guter Schüler. Nun solltet Ihr Euer Wissen an andere weitergeben. Ich hoffe, Ihr redet mit dem Vorratsmeister und nehmt so früh wie möglich einen Lehrling an.", rewards = "Ihr bekommt:\n\nEisentatzmarke"}
MultiLanguageQuestData['de'][31522] = {title = "Eine würdige Herausforderung: Sha des Hasses", objective = "Schließt das Shado-Pan-Kloster im Herausforderungsmodus ab.", description = "<Name>, Ihr müsst eine abgeklärte Gruppe zusammenstellen und sie ins Shado-Pan-Kloster führen. Aktiviert die Kugel des Herausforderers und rettet Taran Zhu vor dem Sha des Hasses.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31523] = {title = "Eine würdige Herausforderung: Xin der Waffenmeister", objective = "Schließt den Mogu'shanpalast im Herausforderungsmodus ab.", description = "<Name>, Ihr müsst eine geschickte Gruppe zusammenstellen und sie in den Mogu'shanpalast führen. Aktiviert die Kugel des Herausforderers und bereitet Xin dem Waffenmeister ein Ende.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", progress = nil, completion = "Vielen Dank, &lt;Name&gt;. Eure Kampfkunst sucht ihresgleichen, und Eure Eilfertigkeit wird die Herzen Eurer Widersacher mit Furcht erfüllen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31524] = {title = "Eine würdige Herausforderung: Raigonn", objective = "Schließt das Tor der Untergehenden Sonne im Herausforderungsmodus ab.", description = "<Name>, Ihr müsst eine entschlossene Gruppe zusammenstellen und sie zum Tor der Untergehenden Sonne führen. Aktiviert die Kugel des Herausforderers und vernichtet Raigonn.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31525] = {title = "Eine würdige Herausforderung: Schwadronsführer Ner'onok", objective = "Schließt den Niuzaotempel im Herausforderungsmodus ab.", description = "<Name>, Ihr müsst eine scharfsichtige Gruppe zusammenstellen und sie zur Belagerung des Niuzaotempels führen. Aktiviert die Kugel des Herausforderers und bringt Schwadronsführer Ner'onok zu Boden.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31526] = {title = "Eine würdige Herausforderung: Durand", objective = "Schließt das Scharlachrote Kloster im Herausforderungsmodus ab.", description = "<Name>, Ihr müsst eine tapfere Gruppe zusammenstellen und sie in das Scharlachrote Kloster führen. Aktiviert die Kugel des Herausforderers und zerschmettert Durand mit gerechtem Zorn.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31527] = {title = "Eine würdige Herausforderung: Flammenwirker Koegler", objective = "Schließt die Scharlachroten Hallen im Herausforderungsmodus ab.", description = "<Name>, Ihr müsst eine gewitzte Gruppe zusammenstellen und sie in die Tiefen der Scharlachroten Hallen führen. Aktiviert die Kugel des Herausforderers und setzt dem bücherverbrennenden Treiben von Flammenwirker Koegler ein Ende.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31528] = {title = "Eine würdige Herausforderung: Dunkelmeister Gandling", objective = "Schließt Scholomance im Herausforderungsmodus ab.", description = "<Name>, Ihr müsst eine furchtlose Gruppe zusammenstellen und sie in die Tiefen von Scholomance führen. Aktiviert die Kugel des Herausforderers und reinigt Scholomance von der finsteren Präsenz von Dunkelmeister Gandling.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31529] = {title = "Mission: Eindämmung der Shed-Ling", objective = "Tötet 12 Shed-Ling der Sprungschweife.", description = "Ich wurde in dieses Tal entsandt, um das Kernland vor allen möglichen Bedrohungen zu verteidigen.\n\nUnd ich habe ein vordringliches Ziel ausgemacht. Die Shed-Ling der Sprungschweife haben sich in die Bergklippen hoch über dem Ackerland eingegraben.\n\nWenn sich niemand um sie kümmert, werden sie sich rasend schnell vermehren und schon bald auf den Feldern unten auftauchen.\n\nSie müssen ausgelöscht werden.", progress = nil, completion = "Die Ziele sind ausgelöscht? Gut gemacht, &lt;Klasse&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31530] = {title = "Mission: Ho-zen-Eindämmung", objective = "Tötet 12 Ho-zen von Kunzen.", description = "Seit meiner Ankunft hier habe ich die Ho-zen beobachtet. Und das Muster ihrer Aktivitäten im Lager gefällt mir ganz und gar nicht.\n\nIm Schutze der Nacht steigen mehrere Ho-zen vom Berg hinunter in das Ackerland im Tal, um Vorräte zu rauben.\n\nWir müssen diese Diebeszüge aufhalten. Ich habe bei jeder sich mir bietenden Gelegenheit einige von ihnen ausgeschaltet, aber ein Soldat allein ist nicht genug.\n\nIch benötige Eure Hilfe. Tötet ganz einfach so viele Ho-zen wie möglich.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31531] = {title = "Mission: Bedrohung aus der Luft", objective = "Tötet 12 Klippensegler.", description = "Ich habe ein weiteres, möglicherweise gefährliches Ziel ausgemacht, das wohl den meisten anderen Personen entgangen wäre.\n\nDie Klippensegler über den Hügeln im Osten stellen eine ernsthafte Gefahr dar.\n\nIch konnte beobachten, wie sie sich auf die Felder der Bauern stürzen und Getreide und Samen schnappen, wenn niemand hinschaut.\n\nUm die Höfe zu beschützen, müssen wir einige von ihnen ausschalten.", progress = nil, completion = "Ich wusste, dass Ihr diesen Auftrag problemlos erfüllen würdet. Gut gemacht, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31532] = {title = "Mission: König der Raubvögel", objective = "Tötet den großen Klippenfalken.", description = "Auf meiner täglichen Routinepatrouille durch die Berge habe ich heute Morgen einen riesigen, weißen Vogel entdeckt, der auf die Felder niederstieß.\n\nEr hat sich ein voll ausgewachsenes Yak gekrallt und ist damit in den Klippen verschwunden.\n\nHeute war es ein Yak, aber morgen könnte es einen Landarbeiter treffen!\n\nWir müssen diesen Vogel ausschalten, bevor er sich ein neues Opfer suchen kann.", progress = nil, completion = "Ihr habt es tatsächlich geschafft, &lt;Name&gt;?! Ich bin sehr erleichtert, dass das Tal dank Eures Einsatzes wieder etwas sicherer ist.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31534] = {title = "Das erste Bräu", objective = "Besorgt 1 süße Teichmelone von Haohan Lehmkrall, 1 flaumigen Pfirsich von Gina Lehmkrall, 1 Portion schwarze Kirschen von Fischi Rohrroder und 1 roten Rettich von Bauer Fung.", description = "Könnt Ihr ein Geheimnis bewahren, <Name>?\n\nIch habe mich mit dem Brauen beschäftigt. Ich habe zwar nur diese alte, handgefertigte Brauanlage, aber sie funktioniert noch ganz ordentlich.\n\nUnd ich habe eine Idee für ein neues Braurezept. Allerdings fehlen mir dazu ein paar Zutaten.\n\nIch selbst bin ja leider furchtbar schüchtern, aber ich habe gesehen, wie viele Freunde Ihr schon unter den Leuten hier gefunden habt.\n\nKönntet Ihr nicht vielleicht einige Zutaten von den Bauern für mich besorgen?", progress = "Ich weiß nicht, wie ich auf die Idee gekommen bin... Vielleicht ist es, weil ich die ganze Zeit auf diese Brauerei starre... Aber ich will das beste Bier des ganzen Tales, nein, von Pandaria brauen!\n\nOh, was für ein naiver Traum, oder?", completion = "Ihr habt sie! Das ist ja wundervoll, &lt;Name&gt;!\n\nIch werde so schnell wie möglich mit dem Brauen anfangen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31535] = {title = "Auffüllen der Speisekammer", objective = "Bringt Nam Eisentatz ein Bündel mit Zutaten. Bündel mit Zutaten werden mithilfe von Behältern hergestellt, die von Händler Cheng verkauft werden.", description = "Aus ganz Pandaria kommen die Leute, um von der Familie Eisentatz kochen zu lernen. Wir sind sehr stolz darauf, die besten Köche zu stellen, und auch darauf, unser Wissen weitergeben zu können. Aus diesem Grund verlangen wir nur sehr wenig für unseren Kochunterricht.\n\nDas bedeutet jedoch auch, dass wir oft einen Mangel an Zutaten für die Unterrichtsstunden haben. Wärt Ihr bereit, etwas der Schule zu spenden, um den Schülern zu helfen, die nicht genug Geld haben?", progress = "Es ist schwierig, kochen zu lernen, wenn man keine Zutaten hat.", completion = "Wir wissen Eure Hilfe sehr zu schätzen. Dies ist für einige unserer Schüler eine große Hilfe.", rewards = "Ihr bekommt:\n\nEisentatzmarke"}
MultiLanguageQuestData['de'][31536] = {title = "Konservierung der Frische", objective = "Bringt Nam Eisentatz einen leeren Tigerfleischkorb.", description = "Damit Kochzutaten so frisch wie möglich bleiben, müssen sie stets richtig gelagert werden. Zum Glück verkauft Händler Cheng dort drüben gute Behälter. Ich will Euch ja nur ungern eine so anspruchslose Aufgabe auftragen, aber könntet Ihr vielleicht einen leeren Tigerfleischkorb für mich kaufen?", progress = "Zutaten verderben, wenn sie nicht korrekt gelagert werden.", completion = "Ah, das ist gut. Jetzt werden diese Zutaten frisch bleiben, bis wir bereit sind zu kochen.", rewards = "Ihr bekommt:\n\nEisentatzmarke"}
MultiLanguageQuestData['de'][31537] = {title = "Ellas Kostprobe", objective = "Fragt Jogu den Betrunkenen, Bobo Eisentatz, Bauer Yoon und Nana Lehmkrall, was sie von Ellas Bräu halten.", description = "So, jetzt ist mein Bräu endlich fertig. Aber um zu wissen, ob es auch etwas taugt, muss jemand es kosten.\n\nWürdet Ihr vielleicht mein Bräu nehmen und herausfinden, was die Leute in Halbhügel dazu sagen?\n\nIch... Ich selbst traue mich nicht.", progress = "Ich finde, mein Bräu schmeckt ziemlich wild. Aber das ist meine persönliche Meinung. Ich brauche noch ein paar andere Urteile darüber.", completion = "Wirklich? Das haben sie wirklich gesagt? Unglaublich!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31538] = {title = "Ein guter Tropfen", objective = "Bittet Chen Sturmbräu, Ellas Bräu zu kosten.", description = "Jetzt fehlt nur noch eine Person, die mein Bräu kosten muss.\n\nUnd diese Person soll weit gereist und Getränke in der ganzen Welt verkostet haben.\n\nEr ist gerade vor Ort und ich würde gern wissen, was er von meinen Fähigkeiten hält.", progress = nil, completion = "Ihr wollt mich doch nicht etwa auf den Arm nehmen, oder, &lt;Name&gt;? Wenn er das wirklich gesagt hat, heißt das... dass ich etwas vom Brauen verstehe!\n\nIch danke Euch, &lt;Name&gt;. Ihr habt mir wirklich geholfen, zu etwas Selbstvertrauen zu finden.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nQuest Turn-In\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31539] = {title = "Eine Frage der Schönheit", objective = "Fertigt ein Auftragsgemälde an und bringt es zu Tintenmeister Wei im Arboretum im Jadewald. Das Rezept findet Ihr in Eurem Inschriftenkundemenü unter \"Quests\".", description = "Wir leben in einer Welt der Magie. Die Wenigen unter uns, die über eine große Begabung verfügen, können die Dinge, die wir fertigen, mit dieser Magie versehen und ihnen Kräfte verleihen. Solche Dinge werden hoch geschätzt.\n\nDoch die noch größere Ausnahme sind die Personen, die Dinge schaffen, die über mehrere Zeitalter hinweg geschätzt werden - nicht weil sie über Kräfte verfügen, sondern wegen ihrer herausragenden Schönheit.\n\nDer Tempel der Jadeschlange hat uns mit solch einem Werk beauftragt, und ich glaube, Ihr seid einer der Würdigsten unter uns. Nehmt Ihr den Auftrag an?Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRolle der Weisheit"}
MultiLanguageQuestData['de'][31540] = {title = "Stäbe für das Tiankloster", objective = "Fertigt 3 Geistereisenstäbe und 2 Regenmohnstäbe. Bringt sie zu Tintenmeister Wei im Arboretum im Jadewald.", description = "Wie es scheint, werden im Tiankloster dieses Jahr viele Mönche ausgebildet. Wir haben einen riesigen Auftrag für Stäbe erhalten. Und mit riesig meine ich wirklich RIESIG.\n\nKönntet Ihr einen Teil des Auftrags übernehmen? Das würde ich sehr zu schätzen wissen. Ihr werdet natürlich die Belohnungen für Euren Anteil erhalten.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRolle der Weisheit"}
MultiLanguageQuestData['de'][31541] = {title = "In Jade gemeißelt", objective = "Fertigt eine gravierte Jadescheibe und bringt sie zu Tintenmeister Jo Po im Arboretum im Jadewald. Das Rezept findet Ihr in Eurem Inschriftenmenü unter \"Quests\".", description = "Meister Kwang ist einer der größten Dichter unserer Zeit. Er hat ein wunderschönes Gedicht geschrieben, und eine Händlerin in Halbhügel hätte gerne diese Worte in Stein gemeißelt, um sie stolz in ihrem Zuhause ausstellen zu können. Sie will, dass jemand mit den besten Fähigkeiten damit beauftragt wird. Würdet Ihr diesen Auftrag annehmen?", progress = "Wie läuft es?", completion = "Wunderschön. Das wird mit Sicherheit Gefallen finden.", rewards = "Ihr bekommt:\n\nRolle der Weisheit"}
MultiLanguageQuestData['de'][31542] = {title = "Fleischfarbene Tinte", objective = "Um die von Tintenmeister Glenzu gewünschte Farbe zu erhalten, sind Pigmente aus einer ungewöhnlichen Quelle erforderlich. Seine Beschreibung lässt vor Eurem geistigen Auge die Farbe des Blutes erscheinen -der von Tigerblut, um genau zu sein...\n\n Stellt 5 Einheiten Fleischfarbene Tinte her. Das Rezept findet Ihr in Eurem Inschriftenkundemenü unter \"Quests\".", description = "Die Kalligrafie ist ein uralter Brauch in Pandaria. Ich arbeite an einem Werk über einen uralten Krieg, und ich suche nach einer Tinte, die für das Thema geeignet ist.\n\nIch habe wirklich fast überall nach dem richtigen Farbton gesucht, aber ich kann ihn einfach nirgends finden. Fällt Euch vielleicht eine Möglichkeit ein, an die Farbe zu kommen, die ich benötige?", progress = "Ich kann einfach nicht die richtige Farbe finden!", completion = "Wo habt Ihr... Wie habt Ihr... Das ist ja perfekt!", rewards = "Ihr bekommt:\n\nRolle der Weisheit"}
MultiLanguageQuestData['de'][31543] = {title = "Porträt einer Dame", objective = "Malt ein Porträt von Madame Goya und bringt es zu Tintenmeister Glenzu im Arboretum im Jadewald. Das Rezept findet Ihr in Eurem Inschriftenmenü unter \"Quests\".", description = "Viele große Kunstwerke sind das Ergebnis einer großen Liebe. Ein Händler in Halbhügel würde gerne ein Porträt als Geburtstagsgeschenk für seine geliebte Frau anfertigen lassen. Wollt Ihr diesen Auftrag annehmen?Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRolle der Weisheit"}
MultiLanguageQuestData['de'][31544] = {title = "Ein Tribut den Toten", objective = "Fertigt einen Beschriebenen Monumentstein an und bringt ihn zu Tintenmeister Jo Po im Arboretum im Jadewald. Das Rezept findet Ihr in Eurem Inschriftenkundemenü unter \"Quests\".", description = "Alles hat einmal ein Ende. Sogar das Leben eines guten Mannes. Eine Familie am Kun-Lai hat ein Monument für ihren geliebten Patriarchen, der vor Kurzem aus dem Leben geschieden ist, in Auftrag gegeben. Nehmt Ihr den Auftrag an?", progress = "Die Toten zu respektieren, ist Teil unserer Traditionen.", completion = "Ein großartiges Werk zu Ehren eines großartigen Mannes.", rewards = "Ihr bekommt:\n\nRolle der Weisheit"}
MultiLanguageQuestData['de'][31545] = {title = "Die schönen Dinge im Leben", objective = "Bringt die angeforderten Waren zu einem Mitglied der Pandarianischen Schatzsuchervereinigung im Tal der Ewigen Blüten.", description = "Die Pandarianische Schatzsuchervereinigung ist daran interessiert, fachmännisch gefertigte Ware von fähigen Juwelenschleifern, wie Ihr es seid, zu kaufen. Die Artikel werden katalogisiert, und die außergewöhnlichsten Schliffe werden in einer geheimen Schatzkammer aufbewahrt, während der Rest verkauft wird, um unsere Kasse aufzufüllen.\n\nUnser Ziel ist es, schließlich eine einzigartige Kollektion für ein besonderes Ereignis zu kreieren.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZenmarke des Juwelenschleifers"}
MultiLanguageQuestData['de'][31548] = {title = "Erste Erfahrungen", objective = "Gewinnt einen Kampf mit einem Haustier.", description = "Nachdem Ihr jetzt zum Ausbilden von Tieren qualifiziert seid, ist es Zeit, Eure Fähigkeiten unter Beweis zu stellen!\n\nZieht ins Tal und stellt Euch einem Kampfhaustier. Wenn Ihr gewonnen habt, kommt wieder zu mir, dann setze ich Eure Ausbildung fort. Viel Glück!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31549] = {title = "Auf dem Wege der Besserung", objective = "Heilt Eure Haustiere vollständig, indem Ihr Shelby Steinsplint die Stallmeisterin aufsucht.", description = "Nachdem Ihr nun einen Kampf gewonnen habt, müssen wir Eure Haustiere heilen, damit sie wieder einsatzbereit sind! Sucht unsere Stallmeisterin Shelby Steinsplint auf, um Eure Haustiere zu heilen und wiederzubeleben.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31550] = {title = "Hab' eins!", objective = "Fangt ein Kampfhaustier.", description = "So weit, so gut, <Name>! Wenn Ihr so weitermacht, macht Euch bei dem ganzen Haustierkram bald keiner mehr was vor. Jetzt solltet Ihr auch mal ein eigenes Haustier fangen!\n\nZieht wieder los, sucht Euch ein Kampfhaustier, gegen das Ihr kämpfen könnt, greift es an und werft Eure Falle, sobald seine Gesundheit niedrig genug ist. Dann bringt mir Euren Fang zur Begutachtung.\n\nUnd immer dran denken: Ihr braucht mindestens ein Haustier der Stufe 3, um Eure Falle verwenden zu können!", progress = nil, completion = "Aha... eine hervorragende Wahl. Ihr seid auf dem besten Weg, Euch ein tolles Team aufzubauen!\n\nDenkt daran: Ihr habt die Möglichkeit, jedes Haustier zu fangen, gegen das Ihr kämpfen könnt, also holt Euch im Laufe Eurer Abenteuer so viele wie möglich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31551] = {title = "Hab' eins!", objective = "Fangt ein Kampfhaustier.", description = "So weit, so gut, <Name>! Wenn Ihr so weitermacht, macht Euch bei dem ganzen Haustierkram bald keiner mehr was vor. Jetzt solltet Ihr auch mal ein eigenes Haustier fangen!\n\nZieht wieder los, sucht Euch ein Kampfhaustier, gegen das Ihr kämpfen könnt, greift es an und werft Eure Falle, sobald seine Gesundheit niedrig genug ist. Dann bringt mir Euren Fang zur Begutachtung.\n\nUnd immer dran denken: Ihr braucht mindestens ein Haustier der Stufe 3, um Eure Falle verwenden zu können!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31552] = {title = "Erste Erfahrungen", objective = "Gewinnt einen Kampf mit einem Haustier.", description = "Nachdem Ihr jetzt zum Ausbilden von Tieren qualifiziert seid, ist es Zeit, Eure Fähigkeiten unter Beweis zu stellen!\n\nZieht in den Wald und stellt Euch einem Kampfhaustier. Wenn Ihr gewonnen habt, kommt wieder zu mir, dann setze ich Eure Ausbildung fort. Viel Glück!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31553] = {title = "Auf dem Wege der Besserung", objective = "Heilt Eure Haustiere vollständig, indem Ihr Seriadne die Stallmeisterin aufsucht.", description = "Nachdem Ihr nun einen Kampf gewonnen habt, müssen wir Eure Haustiere heilen, damit sie wieder einsatzbereit sind! Sucht unsere Stallmeisterin Seriadne auf, um Eure Haustiere zu heilen und wiederzubeleben.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31555] = {title = "Hab' eins!", objective = "Fangt ein Kampfhaustier.", description = "So weit, so gut, <Name>! Wenn Ihr so weitermacht, macht Euch bei dem ganzen Haustierkram bald keiner mehr was vor. Jetzt solltet Ihr auch mal ein eigenes Haustier fangen!\n\nZieht wieder los, sucht Euch ein Kampfhaustier, gegen das Ihr kämpfen könnt, greift es an und werft Eure Falle, sobald seine Gesundheit niedrig genug ist. Dann bringt mir Euren Fang zur Begutachtung.\n\nUnd immer dran denken: Ihr braucht mindestens ein Haustier der Stufe 3, um Eure Falle verwenden zu können!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31556] = {title = "Erste Erfahrungen", objective = "Gewinnt einen Kampf mit einem Haustier.", description = "Nachdem Ihr jetzt zum Ausbilden von Tieren qualifiziert seid, ist es Zeit, Eure Fähigkeiten unter Beweis zu stellen!\n\nZieht in die Wildnis und stellt Euch einem Kampfhaustier. Wenn Ihr gewonnen habt, kommt wieder zu mir, dann setze ich Eure Ausbildung fort. Viel Glück!", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Ihr könnt mit diesen Haustieren besser umgehen, als ich dachte!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31557] = {title = "Die schönen Dinge im Leben", objective = "Bringt die angeforderten Waren zu einem Mitglied der Pandarianischen Schatzsuchervereinigung im Tal der Ewigen Blüten.", description = "Die Pandarianische Schatzsuchervereinigung ist daran interessiert, fachmännisch gefertigte Ware von fähigen Juwelenschleifern, wie Ihr es seid, zu kaufen. Die Artikel werden katalogisiert, und die außergewöhnlichsten Schliffe werden in einer geheimen Schatzkammer aufbewahrt, während der Rest verkauft wird, um unsere Kasse aufzufüllen.\n\nUnser Ziel ist es, schließlich eine einzigartige Kollektion für ein besonderes Ereignis zu kreieren.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nZenmarke des Juwelenschleifers"}
