MultiLanguageQuestData['de'][31568] = {title = "Auf dem Wege der Besserung", objective = "Heilt Eure Haustiere vollständig, indem Ihr Esbina die Stallmeisterin aufsucht.", description = "Nachdem Ihr nun einen Kampf gewonnen habt, müssen wir Eure Haustiere heilen, damit sie wieder einsatzbereit sind! Sucht unsere Stallmeisterin Esbina auf, um Eure Haustiere zu heilen und wiederzubeleben.", progress = nil, completion = "Jetzt strotzen Eure Haustiere ja nur so vor Gesundheit, &lt;Name&gt;. Denkt daran, Ihr könnt all Eure Haustiere jederzeit heilen und wiederbeleben lassen, indem Ihr einen Stallmeister aufsucht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31569] = {title = "Hab' eins!", objective = "Fangt ein Kampfhaustier.", description = "So weit, so gut, <Name>! Wenn Ihr so weitermacht, macht Euch bei dem ganzen Haustierkram bald keiner mehr was vor. Jetzt solltet Ihr auch mal ein eigenes Haustier fangen!\n\nZieht wieder los, sucht Euch ein Kampfhaustier, gegen das Ihr kämpfen könnt, greift es an und werft Eure Falle, sobald seine Gesundheit niedrig genug ist. Dann bringt mir Euren Fang zur Begutachtung.\n\nUnd immer dran denken: Ihr braucht mindestens ein Haustier der Stufe 3, um Eure Falle verwenden zu können!", progress = nil, completion = "Aha... eine hervorragende Wahl. Ihr seid auf dem besten Weg, Euch ein tolles Team aufzubauen!\n\nDenkt daran: Ihr könnt jedes Haustier fangen, gegen das Ihr kämpfen könnt, also holt Euch im Laufe Eurer Abenteuer so viele wie möglich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31570] = {title = "Hab' eins!", objective = "Fangt ein Kampfhaustier.", description = "So weit, so gut, <Name>! Wenn Ihr so weitermacht, macht Euch bei dem ganzen Haustierkram bald keiner mehr was vor. Jetzt solltet Ihr auch mal ein eigenes Haustier fangen!\n\nZieht wieder los, sucht Euch ein Kampfhaustier, gegen das Ihr kämpfen könnt, greift es an und werft Eure Falle, sobald seine Gesundheit niedrig genug ist. Dann bringt mir Euren Fang zur Begutachtung.\n\nUnd immer dran denken: Ihr braucht mindestens ein Haustier der Stufe 3, um Eure Falle verwenden zu können!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31571] = {title = "Erste Erfahrungen", objective = "Gewinnt einen Kampf mit einem Haustier.", description = "Nachdem Ihr jetzt zum Ausbilden von Tieren qualifiziert seid, ist es Zeit, Eure Fähigkeiten unter Beweis zu stellen!\n\nZieht in den Wald und stellt Euch einem Kampfhaustier. Wenn Ihr gewonnen habt, kommt wieder zu mir, dann setze ich Eure Ausbildung fort. Viel Glück!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31572] = {title = "Auf dem Wege der Besserung", objective = "Heilt Eure Haustiere vollständig, indem Ihr Shoja'my die Stallmeisterin aufsucht.", description = "Nachdem Ihr nun einen Kampf gewonnen habt, müssen wir Eure Haustiere heilen, damit sie wieder einsatzbereit sind! Sucht unsere Stallmeisterin Shoja'my auf, um Eure Haustiere zu heilen und wiederzubeleben.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31573] = {title = "Erste Erfahrungen", objective = "Gewinnt einen Kampf mit einem Haustier.", description = "Nachdem Ihr jetzt zum Ausbilden von Tieren qualifiziert seid, ist es Zeit, Eure Fähigkeiten unter Beweis zu stellen!\n\nZieht in den Wald und stellt Euch einem Kampfhaustier. Wenn Ihr gewonnen habt, kommt wieder zu mir, dann setze ich Eure Ausbildung fort. Viel Glück!", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Ihr könnt mit diesen Haustieren besser umgehen, als ich dachte!", rewards = "Ihr bekommt:\n\n"}
