MultiLanguageQuestData['de'][31589] = {title = "Auf dem Wege der Besserung", objective = "Heilt Eure Haustiere vollständig, indem Ihr Murog den Stallmeister aufsucht.", description = "Nachdem Ihr nun einen Kampf gewonnen habt, müssen wir Eure Haustiere heilen, damit sie wieder einsatzbereit sind! Sucht unseren Stallmeister Murog auf, um Eure Haustiere zu heilen und wiederzubeleben.", progress = "Geht es Euren Haustieren besser?", completion = "Jetzt strotzen Eure Haustiere ja nur so vor Gesundheit, &lt;Name&gt;. Denkt daran, Ihr könnt all Eure Haustiere jederzeit heilen und wiederbeleben lassen, indem Ihr einen Stallmeister aufsucht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31590] = {title = "Hab' eins!", objective = "Fangt ein Kampfhaustier.", description = "So weit, so gut, <Name>! Wenn Ihr so weitermacht, macht Euch bei dem ganzen Haustierkram bald keiner mehr was vor. Jetzt solltet Ihr auch mal ein eigenes Haustier fangen!\n\nZieht wieder los, sucht Euch ein Kampfhaustier, gegen das Ihr kämpfen könnt, greift es an und werft Eure Falle, sobald seine Gesundheit niedrig genug ist. Dann bringt mir Euren Fang zur Begutachtung.\n\nUnd immer dran denken: Ihr braucht mindestens ein Haustier der Stufe 3, um Eure Falle verwenden zu können!", progress = "Habt Ihr eins erwischt?", completion = "Aha... eine hervorragende Wahl. Ihr seid auf dem besten Weg, Euch ein tolles Team aufzubauen!\n\nDenkt daran: Ihr könnt jedes Haustier fangen, gegen das Ihr kämpfen könnt, also holt Euch im Laufe Eurer Abenteuer so viele wie möglich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31591] = {title = "Erste Erfahrungen", objective = "Gewinnt einen Kampf mit einem Haustier.", description = "Nachdem Ihr jetzt zum Ausbilden von Tieren qualifiziert seid, ist es Zeit, Eure Fähigkeiten unter Beweis zu stellen!\n\nZieht in die Wildnis und stellt Euch einem Kampfhaustier. Wenn Ihr gewonnen habt, kommt wieder zu mir, dann setze ich Eure Ausbildung fort. Viel Glück!", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Ihr könnt mit diesen Haustieren besser umgehen, als ich dachte!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31592] = {title = "Auf dem Wege der Besserung", objective = "Heilt Eure Haustiere vollständig, indem Ihr Jenova Steinschild die Stallmeisterin aufsucht.", description = "Nachdem Ihr nun einen Kampf gewonnen habt, müssen wir Eure Haustiere heilen, damit sie wieder einsatzbereit sind! Sucht unsere Stallmeisterin Jenova Steinschild auf, um Eure Haustiere zu heilen und wiederzubeleben.", progress = nil, completion = "Jetzt strotzen Eure Haustiere ja nur so vor Gesundheit, &lt;Name&gt;. Denkt daran, Ihr könnt all Eure Haustiere jederzeit heilen und wiederbeleben lassen, indem Ihr einen Stallmeister aufsucht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31593] = {title = "Hab' eins!", objective = "Fangt ein Kampfhaustier.", description = "So weit, so gut, <Name>! Wenn Ihr so weitermacht, macht Euch bei dem ganzen Haustierkram bald keiner mehr was vor. Jetzt solltet Ihr auch mal ein eigenes Haustier fangen!\n\nZieht wieder los, sucht Euch ein Kampfhaustier, gegen das Ihr kämpfen könnt, greift es an und werft Eure Falle, sobald seine Gesundheit niedrig genug ist. Dann bringt mir Euren Fang zur Begutachtung.\n\nUnd immer dran denken: Ihr braucht mindestens ein Haustier der Stufe 3, um Eure Falle verwenden zu können!", progress = nil, completion = "Aha... eine hervorragende Wahl. Ihr seid auf dem besten Weg, Euch ein tolles Team aufzubauen!\n\nDenkt daran: Ihr könnt jedes Haustier fangen, gegen das Ihr kämpfen könnt, also holt Euch im Laufe Eurer Abenteuer so viele wie möglich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31598] = {title = "Kypa'raks Kern", objective = "Bringt den massiven Kyparitkern zu Bernschmied Zikk in Klaxxi'vess.\n\nBereitgestellter Gegenstand: \n", description = "<Als der Ringwurm auseinanderbricht, fällt aus seinem Innersten ein gewaltiger Klumpen organischen Kyparits heraus. Das wird jemand in Klaxxi'vess sehen wollen.>", progress = nil, completion = "Interessant. Es war klug von Euch, die Bedeutung dieser Angelegenheit zu erkennen, Erwecker. Organisches Kyparit ist sehr wertvoll für uns.\n\nHier, eine Belohnung. Ein fairer Tausch.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31599] = {title = "Der Schlund der Matriarchin", objective = "Bringt die enormen Kunchongmandibeln zu Bernschmied Zikk in Klaxxi'vess.\n\nBereitgestellter Gegenstand: \n", description = "<Die gewaltigen Mandibeln der Kunchongmatriarchin Karanosh dürften irgendwem in Klaxxi'vess etwas wert sein.>", progress = nil, completion = "Ich erkenne diese Mandibeln. Karanosh hat nämlich meinen Bruder gefressen.\n\nAber schließlich habe ich Millionen von Brüdern.\n\n&lt;Zikk lacht gackernd.&gt;", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31600] = {title = "Szenarien ermöglichen", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][31603] = {title = "Saat der Angst", objective = "Einige der verderbten Kypari wurden während des schrecklichen Marsches des Schwarms verstreut. Dabei verteilten sie Splitter des Sha-infizierten Berns übers Land.\n\nBringt mir alles, was Ihr davon auf Euren Reisen finden könnt, damit es entsorgt werden kann.", description = nil, progress = "Einige der verderbten Kypari wurden während des schrecklichen Marsches des Schwarms verstreut. Dabei verteilten sie Splitter des Sha-infizierten Berns übers Land.\n\nBringt mir alles, was Ihr davon auf Euren Reisen finden könnt, damit es entsorgt werden kann.", completion = "So lange wie diese Splitter das Land bedecken wird unsere Heimat ein Ort der Angst und des Todes sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31605] = {title = "Die Zan'thikausgrabung", objective = "Sucht den ausgegrabenen Getreuen im Berntagebau auf Zan'vess.", description = "Wir haben auf Zan'vess soeben eine Nachricht von einem Gehilfen abgefangen. Dort haben Yaungolarbeiter im Berntagebau auf der Rückseite der Insel einen Getreuen ausgegraben.\n\nBegebt Euch sofort dorthin und befreit ihn, bevor ihn die Zan'thik vernichten!", progress = nil, completion = "&lt;Diese Mantis scheint erst kürzlich aus ihrer Kammer gebrochen worden zu sein. Sie hustet trocken.&gt;\n\n... Se... zier...er... ist... zurück...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31606] = {title = "Der Sezierer erwacht", objective = "Wehrt die Zan'thik ab, während Rik'kal erwacht.", description = "Ihr seid... nicht wie die anderen...\n\nIch kann den Ruf der Klaxxi hören... <hust>\n\nIch brauche nur einen Augenblick.", progress = "<Hust, Hust>\n\nMein Kopf...", completion = "Seht Euch nur an! So viele verschiedene Teile, ja... und alle so gut im Töten. Faszinierend.\n\nIch muss unbedingt mal Euer Gehirn anzapfen... Muhahaha.", rewards = "MuttersaatmanschettenSaftfliegenbindungenVerdorrte HolzarmbänderKlarheitsarmschienenSchreckensspinnermanschettenGeisterfuchsarmwickelWindschnitterhandgelenksschutzArmplatten des KlingenverschriebenenKältebissarmschienenIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31609] = {title = "Der Zorn von Shek'zeer", objective = "Fügt dem Mantisschwarm eine vernichtende Niederlage zu, indem Ihr Akkolon, Shox'tik, die Manifestation des Terrors und 25 unterworfene Mantis tötet.", description = "Die anderen befreiten Getreuen sind über das Herz der Angst verstreut und wehren den Mantisschwarm ab. Sie brauchen möglicherweise Eure Hilfe!", progress = nil, completion = "Die Belagerung ist gebrochen, zumindest für jetzt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31611] = {title = "Der Kun-Lai-Hammer", objective = "Beschützt das Braumondfest.", description = "Habt Ihr schon mal das Braumondfest erlebt?\n\nDie freundlichen Leute von Binan veranstalten da ein ordentliches Fest. Und die Festivitäten des heutigen Abends werden in Sachen Getränke von niemand anderem beliefert als von mir hier höchstpersönlich.\n\nIch braue meinen berühmten Kun-Lai-Hammer!\n\nWollt Ihr vielleicht vorbeikommen und ein wenig mitfeiern? Das sollte ein vollkommen entspannendes Ereignis werden, ohne irgendeine Form von Gefahr.", progress = nil, completion = "Ich scheine die Gefahren des Brauens dieser Tage unterschätzt zu haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31612] = {title = "Schatten des Kaiserreichs", objective = "Begleitet Kil'ruk den Windschnitter in die Kammer unterhalb von Klaxxi'vess.", description = "Ihr versteht unseren Orden nur teilweise. Als <Außenstehender/Außenstehende> seid Ihr entsprechend behandelt worden.\n\nEs ist nicht mehr länger angemessen, dass wir unsere Geheimnisse vor Euch verbergen. Es gibt da etwas, das Ihr sehen solltet.", progress = "Es gibt da etwas, das Ihr sehen solltet.", completion = "&lt;Kil'ruk sieht Euch merkwürdig an.&gt;\n\nDie Klaxxi'va werden Euch vielleicht nie ganz akzeptieren. Ihre fremdenfeindliche Einstellung schließt die Möglichkeit aus, dass ein &lt;Volk&gt; nützlich sein könnte.\n\nIch jedenfalls bin stolz, an Eurer Seite gekämpft haben zu dürfen, &lt;Klasse&gt;. Eure Anwesenheit und Eure Hilfe sind uns eine große Ehre.", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSiegel des ErstenSiegel des WachenSiegel des UnversehrtenSiegel des WindhäschersSiegel des Blutsuchers\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][31613] = {title = "Brisantes Grünsteinbräu", objective = "Helft bei der Verteidigung von Grünstein.", description = "Ich arbeite an einer Ladung meines berühmten brisanten Grünsteinbräus.\n\nSollte sich hervorragend dafür eignen, mit den Strolchen und den schelmischen Elementaren aufzuräumen, die wir in letzter Zeit in der Nähe der Minen gesehen haben.\n\nIch sag Euch was, wie wär's, wenn Ihr ein paar Eurer Freunde zusammentrommelt und sie herbringt, um etwas davon auszuprobieren?\n\nDie erste Runde geht aufs Haus!", progress = "Geister, Jadezerstörer, Steine, die sprechen. Diese Welt wird langsam ein beunruhigender Ort.\n\nAber... das ist nichts, was nicht mit einem starken Gebräu und einem einnehmenden Lächeln gelöst werden kann.\n\nUnd natürlich einem ordentlichen rechten Haken, oder auch zweien.", completion = "Ich sehe, Ihr habt mein brisantes Grünsteinbräu bereits sinnvoll angewendet. Gut gemacht, &lt;Klasse&gt;!", rewards = "Ihr bekommt:\n\n"}
