MultiLanguageQuestData['de'][31656] = {title = "Die Bedrohung im Süden", objective = "Sprecht mit Bogenmeisterin Li auf dem Schlangenrücken.", description = "Nun, da das Sha des Hasses tot ist, ist die größte Bedrohung dieses Landes gebannt. Unsere Reisen entlang der südlichen Grenzen haben jedoch deutlich gemacht, dass die Mantisstreitkräfte in der Schreckensöde in Bewegung sind und wahrscheinlich nicht mehr lange zurückgehalten werden können.\n\nFalls Ihr den Shado-Pan weiterhin helfen wollt, würde ich empfehlen, Euch bei Bogenmeisterin Li auf dem Schlangenrücken vorzustellen. Sie bewacht die große Mauer, die das Grauen der Schreckensöde von unseren üppigen Ländern im Osten trennt.", progress = nil, completion = "Ein Freiwilliger für den Dienst in der Schreckensöde? Ich glaube, da seid Ihr der Erste.\n\nFreut mich, Euch kennenzulernen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31660] = {title = "Dem Schwarm nicht angemessen", objective = "Tötet 30 Schwarmgeborene der Shek'zeer in den Gelegen von Shek'zeer.", description = "Frisch geschlüpfte Mantis werden nur von zwei Instinkten getrieben: Töten und fressen. Sie gehen aufeinander los und verschlingen die Schwachen. Nur die Stärksten wachsen heran.\n\nDie, die während eines Schwarms schlüpfen - die Schwarmgeborenen - werden stattdessen auf unsere Feinde losgelassen.\n\nDie Schwarmgeborenen in den Gelegen von Shek'zeer wurden verderbt. Sie werden in Schatten und Alpträume hineingeboren. Getrieben vom Schrecken, nicht vom Hunger.\n\nSie sind dem Schwarm nicht angemessen. Sie müssen geläutert werden.", progress = nil, completion = "Ihre Eier hätten noch zehn weitere Jahre in der Wärme der Sonne schwelgen und der Melodie von einer Million Flügeln lauschen sollen.\n\nDie Kaiserin wird für Ihre Verbrechen bezahlen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nCancel Aura: Angel of Death Preview\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31661] = {title = "Eine Quelle furchtbarer Macht", objective = "Bringt den Sha-besessenen Kristall zu Bernschmied Zikk in Klaxxi'vess.\n\nBereitgestellter Gegenstand: \n", description = "<Die Gelegehüter der Shek'zeer scheinen diese blendenden weißen Kristalle als magische Fokusse zu verwenden. Ihr blickt hinein und seht, wie sich dicke Schwaden schwarzen Rauchs in seiner Mitte drehen. Einer der Arbeiter in Klaxxi'vess weiß vielleicht mehr über dieses Material und warum es so viel davon in der Öde gibt.>", progress = nil, completion = "Habt Ihr irgendeine Ahnung, was das ist? Es ist Bern!\n\nAber er ist mit Angst verseucht.\n\nVon einem Außenseiter wie Euch erwarte ich allerdings nicht, dass er die daraus erwachsenden Folgen versteht.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31664] = {title = "Die Quest eines Anglers", objective = "Lest Nats Angeltagebuch.", description = "Dieses Tagebuch steckt voller verschwommener Erinnerungen an Nat Pagles große Abenteuer. Es zu lesen wird ohne Zweifel einen wertvollen Einblick in die Angelkunst bieten.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31669] = {title = "Die Kohlprüfung", objective = "Pflanzt einen Grünkohl auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", description = "Großvater hat immer gesagt, dass ein wahrer Bauer an der Qualität seines Kohls gemessen werden kann. Jedes Mal, wenn ein neuer Bauer in die Stadt kam, kaufte er ein paar Kohlköpfe, um herauszufinden, was sie darüber wussten.\n\nJetzt bin ich der neue Bauer und dies ist meine große Chance, mich unter Beweis zu stellen. Könntet Ihr bitte ein wenig Kohl für mich anpflanzen?", progress = "Gute Bauern ernten guten Kohl. Schlechte Farmer schlechten Kohl. So einfach ist das.", completion = "Wartet nur, bis sie diesen Kohl probieren. Dann werden sie erkennen, dass ich ein wahrer Bauer bin.", rewards = "Ihr bekommt:\n\nGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31670] = {title = "Verlockende Karotten", objective = "Pflanzt eine saftigleckere Karotte auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", description = "Großvater hat immer gesagt: \"Karotten sind nichts als ein Willkommensgeschenk für Shed-Ling\". Ich glaube nicht, dass er je auch nur eine einzige Karotte angepflanzt hat.\n\nAusnahmsweise stimme ich einmal nicht mit Großvater überein. Ich gehe gerne Risiken ein. Außerdem esse ich auch gerne Karotten.\n\nIch gehe gern Risiken ein, wenn ich Karotten esse.\n\nKönntet Ihr ein paar Samen besorgen und eine Karotte für mich anbauen?", progress = nil, completion = "Ich kann es kaum abwarten, bis die Karotten reif sind. Vielen Dank, &lt;Name&gt;. Bis morgen!", rewards = "Ihr bekommt:\n\nGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31671] = {title = "Frühlingszwiebeln? Warum nicht?", objective = "Pflanzt eine Frühlingszwiebel auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", description = "Ich habe Haohan sagen hören, dass er heute Frühlingszwiebeln anbauen will. Ich bin mir zwar nicht sicher, ob heute der beste Tag dafür ist, aber ich gehe davon aus, dass er schon weiß, was er tut. Schließlich ist er der Vorsitzende des Bundes der Ackerbauern.\n\nKönntet Ihr eine Frühlingszwiebel für mich pflanzen?", progress = nil, completion = "Ich kann die Frühlingszwiebeln bereits von hier riechen und freue mich schon, sie morgen zu ernten und zu verkaufen. Danke!", rewards = "Ihr bekommt:\n\nGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31672] = {title = "Der Duft des Kürbisses", objective = "Pflanzt einen Mogukürbis auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", description = "Auf dem Markt habe ich das Gerücht gehört, dass Gina Lehmkrall den Duft von Kürbisblüten liebt. Vielleicht würde sie mich ja ein wenig häufiger besuchen kommen, wenn ich auf meinem Hof ein paar Kürbisse anbaue.\n\nKönntet Ihr bitte einen Kürbis für mich pflanzen?", progress = "Habt Ihr denn schon den Kürbis angepflanzt?", completion = "Und jetzt werden wir darauf lauern, dass er reif wird...\n\nOh, entschuldigt, das hat sich vielleicht ein wenig gruselig angehört. Vergesst, dass ich das gesagt habe.", rewards = "Ihr bekommt:\n\nGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31673] = {title = "Ja, ja, so rot - rot - rot blüht der Blütenlauch...", objective = "Pflanzt eine Stange Rotblütenlauch auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", description = "Großvater hat mir mal erzählt, dass der Geruch von Lauch Krokilisken vom Grundstück fernhält. Da muss was Wahres dran gewesen sein, denn auf seinen Feldern wuchs immer Lauch und ich habe in der Umgebung seines Hofes nie auch nur einen einzigen Krokilisken gesehen.\n\nWir sind hier ziemlich weit vom Wasser entfernt... aber ich denke, man kann nie sicher genug sein.", progress = nil, completion = "Ich möchte mal einen Krokilisken sehen, der es jetzt noch wagt, meinen Hof anzugreifen!\n\nHa HA!", rewards = "Ihr bekommt:\n\nGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31674] = {title = "Wer hat die schönsten rosa Rüben im ganzen Land?", objective = "Pflanzt eine rosa Rübe auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", description = "Der alte Hügelpranke hat mit mir gewettet, dass auf meinem Land keine rosa Rüben wachsen werden.\n\nAber ich werd's ihm zeigen. Auf meinem Land werden die größten, rosansten Rüben wachsen, die der alte Kauz je gesehen hat.", progress = nil, completion = "Hah! Der alte Hügelpranke wird Augen machen.", rewards = "Ihr bekommt:\n\nGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31675] = {title = "Die Heilkraft weißer Rüben", objective = "Pflanzt eine weiße Rübe auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", description = "Großvater hat oft gesagt: \"Man soll sein Haus sauber halten, aber sein Feld noch viel sauberer\". Das hört sich vielleicht nach einem Witz an, aber er hatte schon recht.\n\nWenn man Gemüse erntet, bleiben oft noch Wurzelteile zurück, die die Erde vergiften... doch eine schöne, große, weiße Rübe ist das perfekte Gegenmittel dafür. Könntet Ihr vielleicht eine für mich anpflanzen?", progress = "Das Haus sauberzuhalten ist eher eine persönliche Sache, auch damit hatte Großvater Recht.", completion = "Schaut Euch nur diese Erde an. Sie glänzt ja beinahe.\n\nGroßvater wäre so stolz.", rewards = "Ihr bekommt:\n\nGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31676] = {title = "Uralte Rache", objective = "Tötet 6 rachsüchtige Gurthanigeister auf der Terrasse von Gurthan.", description = "Ich kann hören, wie sie vor Wut aufschreien... die Geister der Gurthanimogu, die ich vor so langer Zeit tötete. Auf der Suche nach Rache irren sie auf dieser zerstörten Terrasse umher.\n\nWenn sie mich in meinem jetzigen Zustand vorfinden, werde ich nicht stark genug sein, sie abzuwehren. Erregt ihre Aufmerksamkeit und beseitigt sie.\n\nBringt zu Ende, was ich begonnen habe, und ich werde Euch sagen, wer ich bin.", progress = nil, completion = "Die Mogu sind ein gemeinsamer Feind von uns. Und vielleicht gibt es noch andere.\n\nWir werden sehen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUpdate Phase Shift (Player)\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31677] = {title = "Die Asche des Kriegsmeisters", objective = "Bringt die Asche von Kriegsherr Gurthan zu Kil'ruk dem Windschnitter in Klaxxi'vess.\n\nBereitgestellter Gegenstand: \n", description = "<Kil'ruk der Windschnitter besiegte Kriegsherr Gurthan bereits vor Jahrhunderten, doch der Geist des Mogubestienmeisters sucht noch immer die Ruinen seiner alten Festung heim.\n\nWenn Ihr den Klaxxi beweisen könnt, dass Ihr diesen Geist bezwungen habt, könntet Ihr in ihrer Gunst steigen.>", progress = nil, completion = "Gurthan war ein Feigling, der Bestien ausgebildet hat, um für ihn zu kämpfen, und als sein Tod nahte, entschied er sich dazu, seinen Willen in einer Urne aufzubewahren.\n\nJetzt haben wir das Vergnügen, ihn so oft töten zu können, wie wir wollen.\n\nGut gemacht.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31679] = {title = "Unsere Reichweite ausbauen", objective = "Aktiviert das resonierende Signal in der Bernscheinkuhle.", description = "Die Klaxxi'va hören noch einen Getreuen. Seine Schreie sind schwach und verlieren sich in der Dunkelheit.\n\nDas Signal muss verstärkt werden.\n\nEs gibt einen Turm in der Bernscheinkuhle, der schon seit vielen Jahren verstummt ist. Er muss singen, die Klaxxi verlangen es!\n\nDieses Mal begleite ich Euch. Ihr werdet mir helfen, ihn zu reparieren.\n\nNehmt den Resonanzkristall und trefft mich in der Kuhle.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31680] = {title = "Schuld und Sühne", objective = "Tötet 8 Bernernter der Ik'thik auf dem Stechenden Pfad.", description = "Am Stechenden Pfad befinden sich junge Kyparibäume. Die Kaiserin entzieht den Schösslingen viel zu früh ihre Energie, Fremdling. Sie müssen erst wachsen, bevor der Bern entnommen werden kann.\n\nDie Klaxxi'va verlangen, dass dieses Verbrechen bestraft wird! Es wird ihnen gefallen, wenn Ihr den Tod auf die Bernernter der Ik'thik niederregnen lasst.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31681] = {title = "Je älter, desto besser", objective = "Sammelt 7 mit Bern gefüllte Gläser von den Bernsammlern auf dem Stechenden Pfad.", description = "Es ist ein Verbrechen, die jungen Bäume abzuernten, doch den Bern zu verschwenden ist eine noch viel größere Schandtat.\n\nFrischer Bern ist nicht so wirkungsvoll, doch die Klaxxi brauchen ihn, um den Kampf fortführen zu können. Wir werden ihnen mehr davon bringen und sie werden mich mit Dank überhäufen!\n\nSammelt den frischen Bern. Wir lagern ihn ein, bis er lange genug gereift ist, um verzehrt zu werden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "BernscheinmedaillonBernscheinhalsreifBernscheinhalsketteBernscheinanhängerBernscheinamulettIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31682] = {title = "Niemals wieder am Meer", objective = "Benutzt die Stimmgabel der Klaxxi bei den meergepeitschten Felsen, um den Getreuen zu erwecken.", description = "Die Klaxxi'va haben zu mir gesprochen, Fremdling. Der Getreue war im Salzigen Schlick verborgen, doch inzwischen hat die Tarnung versagt.\n\nDie Echsenmänner haben ihn umstellt. Er darf ihnen nicht in ihre schuppigen Hände fallen.\n\nIhr werdet ihn finden; Ihr werdet ihn erwecken. Kehrt nicht ohne ihn zurück!\n\nFür diese Tat werden uns die Klaxxi dankbar sein.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDespawn All Summons LAB [INTERNAL]\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31685] = {title = "Das Tal der Vier Winde", objective = "Teleportiert Euch ins Tal der Vier Winde und sprecht mit dem Gefreiten Tim P. Orär.", description = "Yarr, der Jadewald wird gerade mit Hochdruck umgebaut, aber das Tal der Vier Winde ist reif zum Entdecken. Sprecht mit mir, wenn Ihr gehen wollt, und ich kann Euch dahin bringen wohin Ihr wollt. Sprecht mit meinem Kumpel auf der anderen Seite, um was zu bekommen, das Euch auf der Reise hilft.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAuf Stufe 86 aufsteigen"}
MultiLanguageQuestData['de'][31687] = {title = "Die Sik'thik ausdünnen", objective = "Tötet 12 Mantis der Sik'thik.", description = "Trotz all unserer Bemühungen, die Mantis in der Schreckensöde zu halten, haben einige unsere Verteidigung durchbrochen. Anscheinend wollen sie zum Niuzaotempel. Meine Männer haben versucht, ihre Präsenz im Westen, bei Sik'vess, auszulöschen. Ohne Erfolg. Wenn Ihr auch nur halb so <ein/eine:c> <Klasse> seid, wie Taran behauptet, habt Ihr vielleicht mehr Erfolg.\n\nGeht nach Westen und tötet alle Mantis der Sik'thik, die Ihr finden könnt. Und denkt daran: Dies ist nicht der richtige Zeitpunkt, Gnade walten zu lassen. Im Tempel sind Leben, die ganz von uns abhängen.", progress = nil, completion = "Die Mantis sind unerbittlich. Zu unserem Glück übersteigt Eure Verbissenheit selbst die ihre.\n\nEs ist gut, dass Ihr diese Wege beschreitet, &lt;Klasse&gt;.", rewards = "Schmuckstück der Sik'thikEichenbalghalsreifRensais HalsketteAnhänger des WegekreuzesAmulett des WachpostensIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31688] = {title = "Die Suche nach dem Rastlosen Leng", objective = "Durchsucht die Käfige der Sik'thik nach dem rastlosen Leng.", description = "Einer meiner besten Späher, der rastlose Leng, ist während einer Mission auf der anderen Seite von Sik'vess verschollen. Ich hoffe, dass man ihn gefangen genommen und nicht getötet hat, aber da die Mantis so schwer Sha-verseucht sind, ist das nicht sehr wahrscheinlich.\n\nKönntet Ihr trotzdem die Käfige bei Sik'vess durchsuchen? Ich schulde ihm eine gründlichere Suchaktion als diese, aber ich kann keine Männer entbehren, ohne dass unsere südlichen Verteidigungslinien versagen.\n\nBitte, <Klasse>, selbst wenn er sein Leben ausgehaucht hat, findet ihn, damit ich sein Schicksal in Erfahrung bringen kann.", progress = nil, completion = "Leng hat mir von Euren Heldentaten berichtet. Er steht in Eurer Schuld, genauso wie ich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31689] = {title = "Die Furchtverschworenen", objective = "Tötet 6 Furchtverschworene der Vor'thik bei Kypari Vor.", description = "Die Klaxxi sehen weit und hören viel. Sie haben ihre Einsichten mit mir geteilt.\n\nDie Vor'thik heißen das Sha willkommen und benutzen seine Macht, um ihren Vormarsch in diesem falschen Schwarm zu stützen. Ihre Krieger nehmen verderbten Bern zu sich und nennen sich Furchtverschworene.\n\nSie haben keine Zukunft. Sie sind Unrat, der entfernt werden muss.\n\nUnd IHR werdet diesen Vorgang für uns in Gang setzen, wenn Ihr Kypari Vor erreicht.", progress = nil, completion = "In disziplinierten Händen ist der Speer die perfekte Waffe. Nur ein Schwächling würde ihn mit Magie belegen.\n\nUnd wir haben keinen Bedarf an Schwächlingen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31690] = {title = "Beschrifteter Tigerstab", objective = "Bringt Euren beschrifteten Tigerstab zu Tintenmeister Glenzu im Arboretum.", description = "So mächtig er auch ist, wisst Ihr doch, dass Ihr diesem Stab eines Tages entwachsen werdet. Wenn diese Zeit gekommen ist, hätte einer der Tintenmeister im Arboretum sicherlich Interesse daran, ihn Euch abzunehmen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRolle der Weisheit"}
MultiLanguageQuestData['de'][31691] = {title = "Beschrifteter Kranichstab", objective = "Bringt Euren beschrifteten Kranichstab zu Tintenmeister Jo Po im Arboretum.", description = "So mächtig er auch ist, wisst Ihr doch, dass Ihr diesem Stab eines Tages entwachsen werdet. Wenn diese Zeit gekommen ist, hätte einer der Tintenmeister im Arboretum sicherlich Interesse daran, ihn Euch abzunehmen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRolle der Weisheit"}
MultiLanguageQuestData['de'][31692] = {title = "Beschrifteter Schlangenstab", objective = "Bringt Euren beschrifteten Schlangenstab zu Tintenmeister Wei im Arboretum.", description = "So mächtig er auch ist, wisst Ihr doch, dass Ihr diesem Stab eines Tages entwachsen werdet. Wenn diese Zeit gekommen ist, hätte einer der Tintenmeister im Arboretum sicherlich Interesse daran, ihn Euch abzunehmen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRolle der Weisheit"}
MultiLanguageQuestData['de'][31693] = {title = "Julia Stevens", objective = "Besiegt Julia Stevens in einem Haustierkampf.", description = "Ihr wollt es also noch mal mit mir aufnehmen?", progress = nil, completion = "Autsch, Ihr seid wirklich ein guter Haustiertrainer! Ich schätze, damit bildet Ihr die Ausnahme.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31694] = {title = "Hisingen Blues", objective = "test log desc ! 1 Julia StevensJulia Stevens 1 test cona Julia Stevens fodasse $o1x caracois $o1 crl\n\n*DO NOT LOCALIZE*", description = "test desc! $1oa $1oo $1oo $1oa test cona $oo fodasse $oa caracois $1ox $9o crl\n\n*DO NOT LOCALIZE*", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][31695] = {title = "Hinter der Mauer", objective = "Sprecht mit Taran Zhu am Außenposten Longying in der Tonlongsteppe.", description = "Wir haben Nachricht davon erhalten, dass die Shado-Pan mit einem Gegenangriff auf die Tonlongsteppe begonnen haben. Es hört sich an, als wollten sie dem Ursprung der Yaungolinvasion auf den Grund gehen.\n\nDie Pandaren haben seit Tausenden von Jahren keine Streitkräfte in die Tonlongsteppe geführt. Die Shado-Pan sind stark und mutig, aber sie sind auch stolz und nur wenige. Sie werden die Hilfe von Helden wie Euch benötigen. Könnt Ihr durch das Tor von Winterblüte im Nordwesten reisen, um die Anführer der Shado-Pan zu finden und ihnen Eure Hilfe und Erfahrung anzubieten?", progress = nil, completion = "Willkommen in der Tonlongsteppe. Wenn Ihr schon darauf besteht, Euch in die dunkelsten Winkel Pandarias zu wagen, dann könnt Ihr Euch dabei auch wenigstens nützlich machen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31697] = {title = "ACCIDENTAL COPY [reuse if you like]", objective = "Benutzt eine Drachenschleuder, um 50 schwärmende Mantis zu töten.", description = "Die Mantis haben zugenommen, als Ihr zur Kluft aufgebrochen seid. Setzen wir also diese Kugeln, die Ihr gesammelt habt, zu unserem Vorteil ein.\n\nGeht runter zur Schlachtenfront und bemannt eine der Kanonen. Lasst niemanden durch.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31698] = {title = "Den Bestand ausdünnen", objective = "Tötet 8 Windwärtstiger oder Windwärtsalphatiere.", description = "Die letzten Winter waren sehr mild und das Ergebnis dieses Umstands ist, dass die Population wilder Tiger auf der Windwärtsinsel praktisch explodiert ist.\n\nDiese unzähmbaren Kreaturen haben fast alles Wild in der Gegend ausgerottet und jüngst damit begonnen, die Wolkenschlangennester zu überfallen.\n\nDadurch gedeihen die Tiger wie nie zuvor, während die Wolkenschlangen dahinschwinden.\n\nFalls wir nicht vorsichtig sind, könnten die Raubkatzen sie komplett ausrotten.\n\nWir müssen die Tigerpopulation ausdünnen, <Volk>.", progress = nil, completion = "Ihr habt getan, wie Euch aufgetragen wurde, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31699] = {title = "Waldgeistphobie", objective = "Tötet 7 Schattenfeetrickster.", description = "Ach, du meine Güte... Wie soll ich denn jetzt alle meine Aufgaben erledigen?\n\nAusbilder Himmelsdorn hat mir aufgetragen, ein paar Tiger auf der Windwärtsinsel zu jagen, aber ich habe gehört, dass die ganze Gegend vor Waldgeistern nur so wimmelt!\n\nIgitt! Ich hasse Waldgeister! Da läuft es mir eiskalt den Rücken hinunter!\n\nSie sind so klein und... und... sie springen einen an und... und... sie haben so kleine, kalte, tote Stockhändchen!\n\nIgittigitt! Ihr müsst mir helfen, <Name>. Macht sie weg! Bitte!", progress = nil, completion = "Ihr habt die Waldgeister zurechtgewiesen, &lt;Name&gt;. Sie sollten für eine Weile keinen Ärger mehr bereiten.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31700] = {title = "So wird ein Schuh draus...", objective = "Stehlt 14 gestohlene Stiefel zurück.", description = "Ich verabscheue Waldgeister! Einmal ist mir einer von diesen garstigen Mistkerlen den ganzen Tag lang gefolgt, hat mir Dreck in meinen Tee gestreut und Käfer ins Haar gesetzt.\n\nGanz ehrlich, wer macht sowas!?\n\nNun, ich denke, dass es Zeit für eine kleine Revanche ist. Wisst Ihr, was die Waldgeister auf der Windwärtsinsel mehr mögen als alles andere auf der Welt?\n\nGenau, Schuhe!\n\nUnd wir werden sie ihnen stehlen. Das wird sie ganz verrückt machen! Ha!\n\nAber leider fürchte ich mich vor Waldgeistern, also werdet Ihr das erledigen müssen, <Name>.", progress = "Und? Wie hat ihnen das geschmeckt? Sind sie ausgeflippt?", completion = "Wie ich sehe, habt Ihr und Ningna Euch einen kleinen Scherz erlaubt. Leider kann der Orden ein solches Verhalten nicht gutheiß... \n\nMoment, wo habt Ihr diese Schuhe gefunden? Ich habe schon seit Ewigkeiten nach diesem Paar Reitstiefel aus Maulwurfsfell gesucht!\n\nNun gut... Dieses eine Mal werde ich ein Auge zudrücken. Hmpf.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31701] = {title = "Dunkle Jägerin", objective = "Tötet die Windwärtsjägerin.", description = "Ich habe erfahren, dass eine bösartige Bestie, eine Windwärtsjägerin, den Wald im Nordwesten der Insel terrorisiert.\n\nSie hat bereits mehrere Schlangen getötet und nicht wenige Schlangenreiter verletzt, die ihrem Treiben Einhalt gebieten sollten.\n\nSie muss aus dem Weg geräumt werden, bevor sie noch größeren Schaden anrichten kann. Könntet Ihr diese Aufgabe übernehmen?", progress = nil, completion = "Vielen Dank, &lt;Name&gt;. Ihr erweist Euch als äußerst verlässlicher Schüler.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31702] = {title = "Jagdbefehl", objective = "Tötet den Windwärtssäbler.", description = "Ich habe von einer großen weißen Bestie erfahren, die sich in dem Wald im Nordwesten der Insel, auf der die wilden Schlangen leben, herumtreibt.\n\nDiese wilde Kreatur ist der Gefährte der Windwärtsjägerin und hat bereits mehrere der ausgewachsenen Wolkenschlangenmatriarchinnen zu Fall gebracht.\n\nWir können nicht zulassen, dass solch ein gefährliches Raubtier die Insel unsicher machen darf.\n\nNehmt Euch dieser Kreatur an. Wir werden sehen, ob sich Eure Ausbildung ausgezahlt hat.", progress = nil, completion = "Wie ich sehe, habt Ihr die Bestie bezwungen. Ihr seid wirklich ein vielversprechender Schüler.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31703] = {title = "Ab mit dem Tollkopf", objective = "Tötet den Schattenfeetollkopf.", description = "Es gibt eine weitere Aufgabe, mit der ich Euch beauftragen muss.\n\nDer Anführer der Waldgeister ist der Schattenfeetollkopf.\n\nWenn es irgendwo Ärger gibt, ist er meist derjenige, der im Hintergrund die Fäden zieht.\n\nWir haben keine Zeit, um uns mit den ermüdenden Possen und Frechheiten der Waldgeister herumzuschlagen. Nehmt den Schattenfeetollkopf aus dem Spiel... und tut es schnell.", progress = nil, completion = "Den wären wir los! Bei all den Problemen, mit denen wir uns momentan herumschlagen müssen, ist es gut zu wissen, dass sich zumindest eines davon gerade gelöst hat.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31704] = {title = "Ein Häufchen gemacht", objective = "Sammelt 5 kleine Beutel mit Häufchen.", description = "<Als Ihr Eure Schlange anblickt, senkt sie verschämt den Kopf.>\n\nEuch wird klar, dass jemand aus seinem Pferch ausgebüxt ist und einen kleinen \"Unfall\" gehabt hat.\n\nNun ja, bei solch einem Hunger war abzusehen, dass es irgendwann am anderen Ende wieder herauskommen musste.\n\nIhr solltet lieber die Häufchen Eurer Schlange finden und aufsammeln, bevor die Schlangenmeister davon erfahren.", progress = "<Das Jungtier blickt Euch unschuldig an.>", completion = "Das Jungtier spielt zufrieden vor sich hin und ist sich Eurer Anstrengungen gar nicht bewusst. Manchmal ist das Leben eines Schlangenausbilders wirklich undankbar.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nReset Faction Change\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31705] = {title = "Angst vor der Nadel", objective = "Benutzt den Honig auf der nördlichen Lichtung im Arboretum und tötet dann den Obstgartennadler.", description = "Das Arboretum ist unser Zuhause, ein sicherer Hafen, in dem wir unsere Jungtiere aufziehen und unsere Schüler ausbilden.\n\nLeider gibt es aber auch andere, gefährlichere Kreaturen, die es ebenfalls gern ihr Zuhause nennen würden.\n\nHinter dem Fluss im Norden haben wir eine gewaltige Wespe entdeckt, die sich von den dortigen Nektarblüten ernährt.\n\nDiese Kreatur hat bereits mehrere unserer Schüler gestochen.\n\nBenutzt den Honig hier, um die Wespe aus ihrem Versteck zu locken. Dann beseitigt sie, bevor sie noch jemandem Leid zufügen kann.", progress = nil, completion = "Die Giftwespe ist tot? Gut. Wo andere Schüler versagt haben, habt Ihr obsiegt, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31706] = {title = "Weinende Witwen", objective = "Tötet 7 weinende Witwen.", description = "Die Spinnen in der Umgebung von Sri-La sind in jüngster Zeit sehr aggressiv geworden. Sie stellen ein signifikantes Problem für die Angler dar, die entlang der Küste fischen.\n\nUm ihre Sicherheit zu gewährleisten, müsst Ihr Euch in das Klagen der Witwe begeben und dort die weinenden Witwen eliminieren.\n\nIhr könnt die Höhle an der Küste im Norden finden.", progress = nil, completion = "Ausbilder Himmelsdorn hat mich über die Situation am Klagen der Witwe auf dem Laufenden gehalten. Ihr habt das gut gemacht.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31707] = {title = "Verheddert", objective = "Zerstört die Witwennetze, um 5 Dorfbewohner von Sri-La zu befreien.", description = "Wir haben einen beunruhigenden Bericht von den Anglern in Sri-La erhalten, <Name>.\n\nViele ihrer Dorfbewohner werden vermisst - wahrscheinlich wurden sie von den Spinnen entführt, die in der als Klagen der Witwe bekannten Höhle an der Nordküste leben.\n\nDie Opfer werden in die dunklen Tiefen verschleppt, eingesponnen und so als nächste Mahlzeit aufbewahrt.\n\nWir glauben, dass einige von ihnen noch am Leben sein könnten. Es bleibt immer noch Zeit, sie zu retten! Geht und rettet so viele Dorfbewohner, wie ihr könnt.", progress = nil, completion = "Ihr habt heute Großes geleistet, &lt;Name&gt;. Das ist es, was den Orden der Wolkenschlange ausmacht - die Bewohner des Jadewalds zu beschützen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31708] = {title = "Schlangenschuppe", objective = "Sammelt 25 Schlangenschuppen.", description = "Wie ich sehe, habt ihr nun ein eigenes Jungtier, <Volk>.\n\nHabt ihr es auch gut gefüttert, für seine Sauberkeit gesorgt und mit ihm gespielt? Nur dadurch wird es stark und gesund werden.\n\nLasst mich Euch ein kleines Trainergeheimnis verraten. Im Klagen der Witwe im Norden lässt sich ein Pilz namens Schlangenschuppe finden.\n\nEr ist relativ schwer zu beschaffen, aber dieser Pilz verfügt über mächtige Eigenschaften und wichtige Nährstoffe. Eure Schlange wird ihn nicht gerade mögen, aber wer isst schon gern sein Gemüse auf?", progress = "<Eure Schlange begrüßt Euch freudig.>", completion = "&lt;Eure Schlange schnuppert an den Pilzen und verzieht das Gesicht. Sie versucht zu entkommen, aber ihr haltet sie sanft fest und bringt sie dazu, die schwammigen Happen zu fressen.&gt;", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31709] = {title = "Nagender Zweifel", objective = "Benutzt das Sha-Abstimmungsgerät an Orten mit Sha-Befall im Klagen der Witwe. Der Eingang zum Klagen der Witwe kann an der Küste im Norden gefunden werden, südlich von Sri-La.", description = "Mir ist zu Ohren gekommen, dass es einige merkwürdige Vorkommnisse am Klagen der Witwe im Norden gab.\n\nHyazinthe und ich haben uns aufgemacht, um die Sache zu untersuchen, und ich bin mir sicher, dass irgendeine Manifestation des Sha seinen Weg in die Höhle gefunden hat.\n\nIch habe dieses Gerät konstruiert, um Sha-Energie zu messen.\n\nFalls Ihr dorthin unterwegs seid, könntet ihr dann Messungen an allen Orten mit Sha-Befall vornehmen?\n\nDer Befall stellt sich meist als schwarz-weißer Strom aus Sha-Energie dar, der aus dem Boden hervorbricht.", progress = nil, completion = "Vielen Dank, dass Ihr mir diesen Bericht gebracht habt, &lt;Name&gt;. Bao der Große ist zu Recht beunruhigt.\n\nDas Sha ist ein perfider und tödlicher Gegner. Wir müssen es uns zum Ziel setzen, seine dunkle Energie von diesem Land zu tilgen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31710] = {title = "Leckerlis", objective = "Sammelt 100 winzige Spinnenaugen.", description = "Als Ihr Euch nähert, öffnet Eure Schlange ihr Maul und fängt an zu sabbern. Sieht aus, als hätte sie ganz schönen Hunger bekommen, seit Ihr sie das letzte Mal gesehen habt.\n\nDer Art und Weise nach, wie sie wimmert und mit dem Schwanz um sich schlägt, sieht es so aus, als würde irgendein beliebiges Leckerli wohl nicht mehr ausreichen - ein ganz besonders spezieller Leckerbissen muss her.\n\nEure Schlange liebt es, auf winzigen Spinnenaugen herumzukauen, aber diese Spezialität findet man nur bei den Witwenbrutspinnen in der Höhle an der Nordküste.\n\nTja, was soll ein Reiter machen? Eure Schlange wartet.", progress = "Eure Schlange richtet sich auf, als Ihr zurückkehrt.", completion = "Eure Schlange gibt Euch einen liebevollen Stups, bevor sie die Leckerlis verschlingt.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31711] = {title = "Die Saat des Zweifels", objective = "Tötet die Saat des Zweifels.", description = "Das Problem mit dem Sha des Zweifels ist seine tiefdringende Hinterlist, <Volk>.\n\nSobald die Saat des Zweifels gesät ist, wächst sie wie ein lästiges Unkraut.\n\nEine solche Saat wurde im Klagen der Witwe nördlich von hier gesät und genau wie ein Unkraut müssen wir sie so schnell wie möglich beseitigen.\n\nIhr müsst das nagende Fragment des Zweifels zerstören, bevor es weitere Opfer befallen kann.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Name&gt;. Ich \"bezweifle\" allerdings, dass dieser Feind für immer besiegt ist. Wir müssen wachsam bleiben, bis wir uns dessen sicher sein können.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31712] = {title = "Affenärger", objective = "Tötet 13 Uuna-Ho-zen.", description = "Uns wurden merkwürdige Nachrichten aus Sri-La zugetragen.\n\nAnscheinend hat es sich ein Ho-zen-Stamm in Uuna Kagu gemütlich gemacht, einer Höhle an der Küste südlich des Fischerdorfs.\n\nEin bisschen zu gemütlich, wenn Ihr mich fragt. Ihre Stammesangehörigen stehlen und plündern die Rohstoffe entlang der gesamten Küste.\n\nWir müssen ihnen eine Lektion erteilen... eine Lektion, die nur mit Härte erreicht werden kann. Sie sind schon zu lang kein gern gesehener Gast mehr.", progress = nil, completion = "Die Anwesenheit der Ho-zen ist beunruhigend. Ihr habt gut daran getan, die Anweisungen von Ausbilder Himmelsdorn zu befolgen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31713] = {title = "Uuna-hört", objective = "Sammelt 100 Sri-La-Starkbier.", description = "Das ist eine Katastrophe, <Name>!\n\nAls ich gestern die Gaststätte \"Die Tanzende Schlange\" besucht habe, war ihnen das Bräu ausgegangen. Sie haben gesagt, jemand hätte die Lieferung aus Sri-La gestohlen. GESTOHLEN!\n\nDiese Ho-zen von Uuna haben anscheinend jede Menge Ärger unten an den Docks gemacht, und sie haben all das Bräu in ihre Höhle in Uuna Kagu an der Küste verschleppt.\n\nMit so einer Trockenperiode kann ich nicht leben. Ein Leben ohne Bräu ist nicht lebenswert!\n\nJemand muss hingehen und das Bräu retten!", progress = "Ist das Bräu schon zurück? Ich... ich halte das nicht mehr lange aus...", completion = "Oh, den Sturmbräus sei Dank! Ihr seid ein wahrer Held", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31714] = {title = "Die Schlangen retten", objective = "Sammelt 10 gerettete Schlangen.", description = "Diese Uuna-Ho-zen sind diesmal eindeutig zu weit gegangen.\n\nWisst Ihr, was sie mit den wilden Wolkenschlangen anstellen? Jungtiere, die sie gefangen haben, müssen in ihren Gruben gegeneinander kämpfen - und das nur zum Vergnügen der Uuna!\n\nBarbaren!\n\nWenn die Jungtiere bereits in diesem Alter solch aggressives Verhalten beigebracht bekommen, werden sie gewalttätig und verderbt, sobald sie ausgewachsen sind. Eine bösartige Wolkenschlange ist nichts, womit wir zu tun bekommen wollen.\n\nWir müssen die Jungtiere retten.", progress = "Der Orden der Wolkenschlange hat über Jahrhunderte hinweg darauf hingearbeitet, aus wilden Wolkenschlangen treue Gefährten zu machen. Unsere Güte bringt das Beste in ihnen zum Vorschein.\n\nUnglücklicherweise können Gewalt und Zorn sie sehr schnell in zerstörerische Monster verwandeln.", completion = "Ah, ja - diese Jungtiere sehen in der Tat müde aus. Sie haben Schlimmes durchgestanden, aber dank Euch sind sie jetzt in Sicherheit.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31715] = {title = "Uuna-bittlich", objective = "Tötet Fürst Uuna.", description = "Der Anführer der Ho-zen von Uuna ist ein Brigant namens Fürst Uuna.\n\nIch habe fürchterlichte Geschichten über diesen marodierenden Kapitän und seine Mannschaft gehört. Wo auch immer er mit seinem Stamm aufkreuzt, folgt Zerstörung auf dem Fuße.\n\nDie Uuna landen mit ihren Booten auf fruchtbarem Boden, brandschatzen die Dörfer in der Nähe und lassen das Land leerbluten, bevor sie sich zu ihrer nächsten Eroberung aufmachen.\n\nWir werden nicht zulassen, dass das an unserer Küste passiert, nicht, während ich noch das Sagen habe.\n\nJemand muss gehen und ihn sofort auslöschen.", progress = nil, completion = "Ihr Anführer ist also tot? Gut. Vielleicht lassen die Ho-zen die Dorfbewohner jetzt in Frieden.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31716] = {title = "Ein Häufchen gemacht", objective = "Sammelt 5 große Beutel mit Häufchen.", description = "<Als Ihr auf den Pferch zuschreitet, huscht die Schlange in eine der Ecken und versteckt sich.>\n\nSo, wie sie Euch mit verschämten Augen ansieht, wird Euch klar, dass jemand aus seinem Pferch ausgebüxt ist und einen kleinen... Unfall gehabt hat.\n\nNun ja, bei solch einem Hunger war abzusehen, dass es irgendwann am anderen Ende wieder herauskommen musste.\n\nIhr solltet lieber die Häufchen Eurer Schlange finden und aufsammeln, bevor die Schlangenmeister davon erfahren.", progress = "<Die Schlange sieht Euch amüsiert zu.>", completion = "Die Wolkenschlange spielt zufrieden vor sich hin und ist sich Eurer Anstrengungen gar nicht bewusst. Seufz… Manchmal ist das Leben eines Schlangenausbilders wirklich undankbar.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nReset Faction Change\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31717] = {title = "Herausforderung des Trainers: Flitze Langpranke", objective = "Sprecht mit Flitze Langpranke und besiegt ihn.", description = "Ihr steigt in der Rangfolge unserer Schüler auf, <Name>.\n\nSo wie ein Schwert im Feuer geschmiedet werden muss, müssen sich unsere Schüler gegeneinander beweisen.\n\nHeute kämpft Ihr gegen einen unserer klügsten Schüler, Flitze Langpranke. Um ihn zu besiegen, müsst Ihr auf Eure Verteidigungskünste zurückgreifen.\n\nSprecht ihn im Trainingsring an, um mit der Herausforderung zu beginnen. Viel Glück.", progress = nil, completion = "Gut gemacht, &lt;Klasse&gt;. Das Schwert das gehämmert und gefaltet wird erhält eine scharfe Klinge.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31718] = {title = "Herausforderung des Trainers: Bao der Große", objective = "Sprecht mit Bao dem Großen und besiegt ihn.", description = "Seid Ihr bereit für eine weitere Lektion, <Name>?\n\nHeute werdet Ihr mit Bao dem Großen trainieren. Er hat einen großen Körper, aber auch ein großes Herz und er wird nicht aufgeben, bevor er nicht vollständig besiegt ist.\n\nFalls Ihr ihn besiegen wollt, werdet Ihr Durchhaltevermögen beweisen müssen.\n\nSprecht ihn im Trainingsring an, um die Herausforderung anzunehmen. Viel Glück.", progress = nil, completion = "Ihr habt beide bis zum Ende durchgehalten. Gut gemacht.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31719] = {title = "Herausforderung des Trainers: Ningna Dunkelrad", objective = "Sprecht mit Ningna Dunkelrad und besiegt sie.", description = "Ihr seid vielversprechend, <Name>. Talent ohne Disziplin und Demut ist jedoch nichts wert.\n\nHeute werdet Ihr Ningna Dunkelrad gegenübertreten. Ihre angeborene Stärke macht sie zu einer unserer talentiertesten Schülerinnen.\n\nWenn Ihr sie besiegen wollt, müsst Ihr höchste Selbstkontrolle beweisen.\n\nSprecht sie im Trainingsring an, um mit der Herausforderung zu beginnen. Viel Glück.", progress = nil, completion = "Ein Kampf gegen Ningna zeigt die eigenen Stärken und Schwächen ganz genau. Gut gemacht.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31720] = {title = "Herausforderung des Trainers: Suchi die Süße", objective = "Sprecht mit Suchi der Süßen und besiegt sie.", description = "Heute steht Ihr Suchi der Süßen im Ring gegenüber. Trotz ihres süßen Aussehens ist sie ein harter Gegner.\n\nSie greift schnell und mit sicherer Hand an, aber mit der Zeit können solch starke Angriffe ermüden.\n\nWenn Ihr sie besiegen wollt, müsst Ihr Euren Schaden auf die Momente konzentrieren, in denen sie geschwächt ist.\n\nSprecht mit Suchi, um mit dem Duell anzufangen. Viel Glück.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31721] = {title = "Herausforderung des Trainers: Qua-Ro Weißstirn", objective = "Sprecht mit Qua-Ro Weißstirn und besiegt ihn.", description = "Qua-Ro Weißstirn gilt als einer der besten Schüler des Ordens.\n\nEr scheint keine Schwachstelle zu haben. Er ist von regem Geist und starkem Arm, arbeitet hart und ist talentiert.\n\nWenn Ihr ihm im Ring gegenübersteht, werdet Ihr Euch an unserem Besten messen.\n\nSprecht mit ihm, um das Duell zu starten. Was immer das Ergebnis sein wird, ihr werdet viel daraus lernen, ihn herauszufordern.", progress = nil, completion = "Euer Können ist erstaunlich, &lt;Name&gt;. Wenn ich so vielversprechende Schüler wie Euch sehe, weiß ich, dass der Orden in gute Hände kommen wird.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31723] = {title = "Das Tal der Vier Winde", objective = "Sprecht mit dem Gefreiten Tim P. Orär im Tal der Vier Winde.", description = "Yarr, der Jadewald wird gerade mit Hochdruck umgebaut, aber das Tal der Vier Winde ist reif zum Entdecken. Ich kann Euch hinbringen, wenn Ihr es erkunden wollt. Seht Euch meine Waren an, wenn Ihr Ausrüstung braucht, die Euch auf Eurer Reise hilft.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAuf Stufe 86 aufsteigen"}
MultiLanguageQuestData['de'][31724] = {title = "Mac Donald", objective = "Besiegt Mac Donald in einem Haustierkampf.", description = "Einzig und allein anzufangen demonstriert, wie zäh Ihr seid!\n\nMac Donald hat mir alles beigebracht, was ich über das Kämpfen weiß. Ich glaube, ein Kampf gegen ihn wäre eine großartige Lernerfahrung für Euch!\n\nIhr findet ihn direkt auf der anderen Seite der Brücke nach Westfall. Lasst Euch von seinem Alter nicht täuschen, er hat bereits einige aufstrebende Nachwuchslehrer wie Euch geschlagen.", progress = "Ihr glaubt wohl, Ihr wärt ein echtes Ass, nicht wahr?", completion = "Tja, gegen diese Ergebnisse kann man nichts einwenden. Ihr habt eine echte Gabe, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31725] = {title = "Lindsay", objective = "Besiegt Lindsay in einem Haustierkampf.", description = "Wollt Ihr zeigen, was Ihr drauf habt? Im Rotkammgebirge oben gibt es ein kleines Mädchen, das in der Kampfszene Furore gemacht hat.\n\nFindet Lindsay beim Dock im Immerruhlager. Sie ist zwar jung, aber über ihre beeindruckenden Leistungen müsst Ihr Euch nicht lustig machen!", progress = "Wer hat Euch das Kämpfen beigebracht, mein Herr?", completion = "Ihr seid gemein! Warum hat Ihr mich nicht gewinnen lassen? Die anderen lassen mich immer gewinnen!", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31726] = {title = "Eric Davidson", objective = "Besiegt Eric Davidson in einem Haustierkampf.", description = "All meine Freunde reden von einem Furcht einflößenden Worgen namens Eric Davidson im Dämmerwald, den niemand mit seinen Haustieren zu bekämpfen wagt.\n\nWenn Ihr ihn findet und bezwingt, möchte ich wetten, dass nicht mehr sein Name sondern vielmehr Eurer in aller Munde sein wird!", progress = "Habt Ihr etwa Angst, <Volk>?", completion = "Nicht nur habt Ihr weder mich noch meine Heimat gefürchtet, Ihr habt mich ehrenhaft besiegt. Ich bin beeindruckt.", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31727] = {title = "Riskantes Spiel", objective = "Sprecht in der Schreckensöde mit Deckoffizierin Arie bei Tropfs Wagnis.", description = "Wenn wir diesen Krieg gewinnen wollen, dürfen wir nichts aus den Augen verlieren, <Fremder/Fremde>.\n\nAn der Küste gibt es Störungen, die untersucht werden müssen. Was immer dort anwesend ist gehört nicht zu uns und ist für uns wertlos. Die Vorräte dort könnten sich jedoch als sehr wertvoll erweisen.\n\nWenn es dort etwas Nützliches gibt, müssen wir es vor der Kaiserin erreichen.", progress = nil, completion = "Die Käfer haben also Interesse an uns entwickelt, was? Nun, wenn sie etwas von uns wollen, müssen sie schon herkommen und es sich verdienen!\n\nHier erarbeitet man sich alles, was man bekommt. Das gilt auch für Euch!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31728] = {title = "Bill Schildbuckel", objective = "Besiegt Bill den Piraten in einem Haustierkampf.", description = "Mein langjähriger Freund, Trainerkollege und berüchtigter Trunkenbold Bill Schildbuckel vom Schlingendornkap hat eine allen hinreichend vorbereiteten Trainern offen stehende Herausforderung proklamiert!\n\nIhr solltet seinem Aufruf folgen und Eure Fertigkeiten auf die Probe stellen. Er wandert häufig auf den Straßen des südlichen Kaps umher.", progress = "Scho hart im Nehmen scheid Ihr auch nicht... hick!", completion = "Ich verlange eine Wiederholung... hick! Dasch war unfair! Ihr hattet Euren Zwilling dabei!", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31729] = {title = "Steven Lisbane", objective = "Besiegt Steven Lisbane in einem Haustierkampf.", description = "Wenn Ihr findet, dass ich zäh war, wappnet Euch lieber. Ab hier wird es noch schwieriger.\n\nFindet Steven Lisbane, der die Straßen im Südteil des Nördlichen Schlingendornentals durchstreift. Sucht ihn und findet heraus, wer hier der bessere Zähmer ist!", progress = "Wo habt Ihr bloß dieses faszinierende Team gefunden?", completion = "Was für eine Vorstellung! Ein wahrlich vortreffliches Scharmützel.", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31730] = {title = "Ein wenig freundlicher Auftrag", objective = "Sprecht im Braugarten in der Schreckensöde mit Saftmeister Vu.", description = "Späher haben von der Anwesenheit von Nichtmantis bei Kor'vess berichtet. Ihr Eindringen und ihre Berndiebstähle würden normalerweise schnell unterbunden werden, aber unsere Truppen werden anderswo gebraucht.\n\nDiese Aufgabe scheint zu Euch zu passen, <Erwecker/Erweckerin>. Ihr werdet sie dazu bringen, dieses Land zu verlassen, oder Ihr werdet sie im Namen der Klaxxi'va vernichten.", progress = nil, completion = "Sie wollen also, dass wir gehen, was? Wie selbstsüchtig von ihnen! Wir nehmen uns nur von einem Baum Bern.\n\nIch gehe jedenfalls nirgendwohin! Ich habe zu brauen.\n\nWenn Ihr uns helft, können wir vielleicht zu einer Übereinkunft gelangen, die beiden Seiten hilft. Ich gebe ihnen etwas Bräu, und sie hören auf zu versuchen, uns umzubringen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31732] = {title = "Die Hölle entfesseln", objective = "Benutzt einen Himmelsfeuer-Gyrokopter, um 60 Soldaten der Garrosh'ar zu töten, 8 Schredder der Garrosh'ar zu zerstören und anschließend die Klingenfaustschneide und die Höllennarbe zu versenken.", description = "Ich werde NICHT zulassen, dass die Horde vor uns in diesen Gefilden Fuß fasst! Wenn Ihr Euch ins Gefecht stürzen wollt, nehmt den Gyrokopter am Ende der Startbahn. Ein Angriffsvektor ist bereits einprogrammiert, also könnt Ihr Euch auf die Rolle des Bordschützen konzentrieren.\n\nSorgt dafür, dass über diesen Orcs die Hölle losbricht!", progress = nil, completion = "Ein angemessener Empfang für die Horde in diesem neuen Land!", rewards = "Sullys kurzschließendes MesserScharfschützengewehr des LuftmarinesoldatenKnüppel des BarrikadenbrechersNebelschnittstabStab der HimmelmagiMystischer Perpetuum-Mobile-StreitkolbenSanitäterstab der HimmelsfeuerKriegsaxt des SchocksoldatenKapitän Rogers' höflicher AnklopfstockSoldatenkolben der HimmelsfeuerIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31733] = {title = "Sichere Landung", objective = "Springt mit einem Fallschirm der Himmelsfeuer über Garrosh'ar ab und sprecht mit Sully \"der Gurke\" McLeary.", description = "Ihre Stadt brennt und ihre Männer sind versprengt und gebrochen. Ich brauche JETZT alle verfügbaren Männer vor Ort, um sie zu erledigen.\n\nGreift Euch einen der Fallschirme am Rand des Schiffes und runter mit Euch!", progress = nil, completion = "War Zeit, dass Ihr auftaucht, Kumpel! Richten wir etwas Schaden an!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31734] = {title = "Böllerwagen", objective = "Zerstört mit Sullys Leuchtpistole 5 Kriegswagen der Horde.", description = "Habt Ihr gesehen, wie groß diese Kriegswagen sind? Sie transportieren so viel Sprengstoff, dass ich nicht weiß, ob die Horde hier ist, um diesen Kontinent zu erobern oder ihn einfach nur ins Meer hinauszujagen!\n\nWir müssen die Wagen unschädlich machen, ehe sie Garrosh'ar verlassen.\n\nHier, nehmt meine Taschenleuchtfeuer. Schießt damit auf einen Wagen und genießt das Feuerwerk!", progress = "Schickt Euch \"Die Gurke\" mit einer Mission?", completion = "Da die Wagen nun unbrauchbar sind, können wir unsere Aufmerksamkeit dem Kommandanten zuwenden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31735] = {title = "Das richtige Werkzeug zur Hand", objective = "Räumt mit Sullys Leuchtpistole die Barrikaden und konfrontiert Ga'trul am Ende des Docks.", description = "Ich habe die Umgebung abgesucht und keine Spur vom Prinzen oder von Admiral Taylor gefunden. Wir müssen diese Basis schnell neutralisieren und unsere Suche anderswo fortsetzen.\n\nDie Einsätze hier werden von Ga'trul, einem Hexenmeister der Orcs, geleitet. Er hat das Dock verbarrikadiert und versucht, durch einen dämonischen Zirkel zu entkommen.\n\nSetzt diese Leuchtpistole wieder ein und jagt die Barrikaden in die Luft! Ich werde Euch den Rücken freihalten und vorrücken, wenn Ihr Ga'trul erreicht.", progress = "Wir werden unsere Mission abschließen, doch jetzt ist dieser <Klasse> unsere oberste Priorität!", completion = "Wir werden ihn wieder einholen. Da bin ich ganz sicher.", rewards = "Ledertunika des bedeutenden LandgutsKettenrüstung des bedeutenden LandgutsSeidene Robe des bedeutenden LandgutsSatinrobe des bedeutenden LandgutsBalgtunika des bedeutenden LandgutsRingpanzerrüstung des bedeutenden LandgutsBrünierter Brustschutz des bedeutenden LandgutsGepanzerter Brustharnisch des bedeutenden LandgutsSchwerer Brustharnisch des bedeutenden LandgutsDer folgende Zauber wird auf euch gewirkt:\n\nCut Scene - Naval Finale\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31736] = {title = "Gesandter der Allianz", objective = "Spürt den Anführer von Pel'zin auf und trefft Euch mit ihm.", description = "Nördlich dieser Basis gibt es einen Kirschblütenhain, hinter dem sich ein Dörfchen versteckt. Dort wollen wir unser Lager aufschlagen und uns um unsere Verletzten kümmern, während wir unseren nächsten Schachzug planen.\n\nMacht Euch ins Dorf auf und nehmt Kontakt mit dem Anführer der Eingeborenen auf. Agent Mishka und ich werden dort zu Euch stoßen.\n\nUnd seid höflich, <Name>! Ich autorisiere Euch hiermit, die gesamte Allianz vor Ort zu vertreten.\n\nIch zähle darauf, dass der Anblick eines Allianzhelden von Eurem Format etwas Eindruck schinden wird.", progress = nil, completion = "Als sich die Nebel senkten, wussten wir, dass es nur eine Frage der Zeit war, bis sich Besuch einstellt.\n\nDass es zu so etwas kommen würde, hätten wir nicht vorausahnen können.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nEnvoy of the Alliance: Completion Event\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31737] = {title = "Der Preis des Krieges", objective = "Tötet 15 Sha-Heimsuchungen und 5 Sha-Herolde bei Garrosh'ar.", description = "Der ganze Ort geht in Flammen auf und die Himmelsfeuer meldet, dass weitere von diesen... Schatten aus dem Erdboden hervorkriechen. Wir müssen unsere Leute da herausholen.\n\nRäumt auf Eurem Weg nach Norden einen Pfad durch die Basis und nehmt Kurs auf die Stadt. Ich werde dort zu Euch stoßen.", progress = nil, completion = "Ich bin froh, dass Ihr die Verantwortung für Eure Taten übernommen habt. Wenn ihnen nicht Einhalt geboten wird, können negative Emotionen einen Einzelnen sehr schnell überwältigen - so, wie es demjenigen, den Ihr \"Rell\" nennt, widerfahren ist.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nThe Cost of War: Summon Rell\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31738] = {title = "Plündernde Peons", objective = "Tötet 12 Zuchtmeister oder Peons von Zwillingsfels.", description = "Wie ist aus meinem Dorf nur ein Schlachtfeld geworden?\n\nIm Westen haben Eure Feinde von der Horde unseren kostbaren Obstgarten niedergemäht. Ohne unsere Apfelbäume gibt es keine Ernte, keine Nahrung und keinen Lebensunterhalt.\n\nWenn Ihr wirklich anders seid als die Horde, beweist es uns! Helft uns, unseren Hain zu beschützen, und tötet diejenigen, die das Land schänden.", progress = nil, completion = "Unser Obstgarten ist einer der größten Schätze des Dorfes. Wir sind Euch wirklich dankbar, dass Ihr unsere Ernte gerettet habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31739] = {title = "Prioritäten!", objective = "Sammelt 6 Fässer Apfelblütenwein.", description = "Diese \"Orcs\" haben die Brauerei geplündert und sich mit Fässern unseres besten Apfelweins davongemacht!\n\nIch weiß, dass da draußen ein Krieg tobt, aber ich bin nicht die Sorte Braumeister, die untätig zusieht, wie sein bester Jahrgang gestohlen wird, damit es den Durst Unwürdiger löscht.\n\nDiese \"Horde\" wird das mit Sicherheit nicht tatenlos über sich ergehen lassen. Warum macht Ihr Euch mit Eurer Waffe nicht nützlich und helft mir, meinen Apfelwein zurückzuholen?", progress = nil, completion = "Wie ich sehe, wart Ihr fleißig! Danke, dass Ihr unsere Fässer zurückgebracht habt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31740] = {title = "Kaukaus Randale", objective = "Tötet Kaukau.", description = "Wir haben mehr Sorgen als nur unsere Kellerei.\n\nKaukau, unser geliebtes Mushan, ist verrückt geworden! Schaut ihn Euch nur an!\n\nIch habe alles versucht: locken und bitten, schreien und beruhigen. Nichts hat geholfen.\n\nEr hat den Verstand verloren. Es gibt nur einen Weg, ihn und unsere Brauerei zu retten.\n\nMacht kurzen Prozess. Er wird nichts spüren.", progress = nil, completion = "Ihr habt gut daran getan, den Brauern zu helfen und mir von den Ereignissen zu berichten.\n\nNach dem, was Ihr mir erzählt habt, befürchte ich, dass Kaukau von dunkler Energie besessen war. Könnte es etwa...?\n\nNein. Das wäre unmöglich.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31741] = {title = "Burg Zwillingsfels", objective = "Tötet 15 Gefolgsleute der Horde in der Burg Zwillingsfels.", description = "Ich traue dieser Horde nicht. Sie wirken üble Magie und ihre Absichten sind offensichtlich bösartiger Natur. Wir können ihre Präsenz in Burg Zwillingsfels nicht länger hinnehmen - nicht so kurz vor den Toren von Pel'zin.\n\nIch bitte Euch, <Fremder/Fremde>: Dünnt ihre Reihen aus, bevor sie etwas Schreckliches mit unserem Dorf anstellen!", progress = nil, completion = "Ihr habt dort unten ja ein ziemliches Chaos angerichtet, Kleiner.\n\nGute Arbeit.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31742] = {title = "Fragmentierte Fraktion", objective = "Tötet Dalgan und Bellandra Teufelssturm.", description = "Die Horde hat uns die Arbeit erleichtert. Ihre Flügelkämpfe und die Fragmentierung ihrer eigenen Reihen hat ihr Lager in zwei Parteien gespalten: die Orcs im Westen und die Untoten im Osten.\n\nDie Orcs gehorchen den Befehlen ihres Kommandanten Dalgan, während die Untoten Bellandra Teufelssturm, einer mächtigen Hexenmeisterin, folgen. Hoffentlich ist dieses interne Gerangel Ablenkung genug, damit Ihr Euch einschleichen und beide töten könnt. Sully hat die Ruinen bereits infiltriert - meldet Euch bei ihm, wenn Ihr fertig seid.", progress = nil, completion = "So was nenn' ich töten mit Stil, &lt;Klasse&gt;.\n\nJetzt, wo die beiden erledigt sind, muss nur noch der Riesenkerl dort hinter mir in der Halle dran glauben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31743] = {title = "Vor Feuer kommt Rauch", objective = "Fordert mit dem Rauchsignal der Allianz einen Luftangriff auf den Munitionshaufen, die Demolierer von Zwillingsfels, die Wildwichtel und Xhu'daggab an.", description = "Sully hat die Einrichtung der Horde im Norden ausgekundschaftet und berichtet, einen großen Haufen Sprengstoff und ein kleines Kontingent Demolierer gesehen zu haben - von den Dämonen, die von ihren Hexenmeistern beschworen worden sind, ganz zu schweigen.\n\nZum Glück sind wir vorbereitet. Wir haben Unterstützung von der Himmelsfeuer. Wir müssen unseren Piloten nur zeigen, wo sie zuschlagen sollen.\n\n<Mit einem wissenden Nicken drückt Euch Rell ein Rauchsignal in die Hand.>", progress = nil, completion = "Meine Burschen im Himmel oben heizen ordentlich ein, stimmt's? Ha ha ha!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31744] = {title = "Unfairer Handel", objective = "Befreit 8 gefangene Pandarenkinder aus der Burg Zwillingsfels, indem Ihr die dämonischen Augen tötet, von denen sie bewacht werden.", description = "Wir sind uns zwar gerade erst begegnet, doch wir haben einen gemeinsamen Feind: die Gruppierung, die die \"Horde\" genannt wird.\n\nVor ein paar Tagen hat uns ihr Anführer einen Handel vorgeschlagen. Als wir ablehnten, haben seine Diener mehrere unserer Kinder als Druckmittel entführt.\n\nWir haben zwar versucht, die Shado-Pan herbeizurufen, um zu helfen, aber sie befinden sich am Kun-Lai-Gipfel, mehrere Tagesreisen von hier entfernt. Könnt Ihr uns womöglich helfen?", progress = nil, completion = "Ja, ich hab die Kleinen auch gesehen. Hab auf dem Weg hierher ein paar von ihnen in Sicherheit gebracht.\n\nGute Arbeit, Kleiner. Die Kinners werden vielleicht ein paar üble Alpträume haben, Euch verdanken sie aber, dass sie eine Zukunft haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31745] = {title = "Vorwärts ins Landesinnere", objective = "Erstattet Himmelsadmiralin Rogers in Pel'zin im Jadewald Bericht.", description = "\"Sha\"-Energie also, hm? Seid vorsichtig, <Name> - irgendetwas Dunkles verbirgt sich auf diesem Kontinent.\n\nWir bleiben zurück, um mit dem Rest der Horde fertigzuwerden, aber Ihr müsst mit der eigentlichen Mission fortfahren: der Rettung von Kapitän Taylor und der Suche nach Prinz Anduin.\n\nUnsere Luftaufklärer haben etwas nahe des Dorfs Pel'zin gesichtet, das das Wrack des Flaggschiffs sein muss. Begebt Euch dorthin und meldet Euch bei Admiralin Rogers für weitere Instruktionen.\n\nUnd ja, Ihr dürft meinen Gyrokopter benutzen.", progress = nil, completion = "Ausgezeichnete Arbeit, &lt;Klasse&gt;. Jetzt verstehe ich, warum Ihr so nachdrücklich empfohlen wurdet.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nTaran Zhu beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31752] = {title = "Blingtron 4000", objective = "Es freut mich sehr, Euch dieses Geschenk überreichen zu dürfen, <Volk>. Laut meinen Berechnungen sollte es Gefühle der Freude und Dankbarkeit hervorrufen.\n\nEinen schönen Tag noch.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBlingtron-4000-Geschenkpaket"}
MultiLanguageQuestData['de'][31754] = {title = "Kanonenfeuer", objective = "Zerstört 7 Kanonen der Shao-Tien.", description = "Diese Mogukanonen oben auf der Goldenen Treppe bombardieren uns aus der Distanz. Wäre nicht schlecht, wenn die irgendwie ganz spontan kaputtgehen würden, nicht wahr?", progress = nil, completion = "Es ist da draußen schon ein wenig ruhiger. Meine rauschenden Ohren sind für Eure harte Arbeit dankbar.\n\nVielen Dank!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31755] = {title = "Grausamkeiten", objective = "Rettet 5 Wachposten des Goldenen Lotus oder Dorfbewohner von Nebelhauch.", description = "Ich kann die Schreie der gefangenen Soldaten und Dorfbewohner oben auf der Goldenen Treppe hören. Sie werden gefoltert!\n\nBitte, bitte, Ihr müsst sie retten!", progress = "Niemand verdient die Qualen, denen die Mogu uns aussetzen...", completion = "Ich fühle mich etwas besser, jetzt da ich weiß, was Ihr getan habt.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31756] = {title = "Hohe Regenwahrscheinlichkeit", objective = "Zerstört die Sturmruferstäbe.", description = "Die Mogu beschwören auf der Goldenen Treppe irgendeine Art finsteren Sturm. Im Allgemeinen sind Mogu und Blitze keine besonders angenehme Mischung. Ich würde sagen, wir halten sie auf.\n\nIhr solltet ihre Sturmruferstäbe ohne größere Probleme finden, wenn man bedenkt, was für gigantische Blitze aus ihnen aufsteigen. Wollt ihr ein paar davon für mich umstürzen oder sie zerstören oder sowas? Ich würde auf jeden Fall besser schlafen.", progress = nil, completion = "Es ist schon viel heller draußen! Und nicht nur wegen Eures strahlenden Lächelns.\n\nGut gemacht!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31757] = {title = "Entfesselte Geister", objective = "Tötet 12 entfesselte Geister.", description = "Die Shao-Tien haben die von ihnen gefangen gehaltenen gequälten Geister auf uns gehetzt. Schier endlos kommen sie die Goldene Treppe herab.\n\nTötet so viele dieser entfesselten Geister, wie Ihr könnt. Sie sind schwach, aber wenn Ihr nicht aufpasst, könnten sie Euch leicht überrennen.\n\nViel Glück.", progress = nil, completion = "Es kommen noch immer Geister die Treppe hinab, aber unsere Wachen können sie aufhalten. Die Shao-Tien werden diesen Angriff nicht ewig fortsetzen können.\n\nIch danke Euch, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31758] = {title = "Laosige Arbeit", objective = "Rettet Lao Samtfuß.", description = "Lao Samtfuß hat sich schon wieder oben auf der Goldenen Treppe gefangennehmen lassen. Ich will ihn nicht verteidigen, er ist einfach ein lausiger Schurke.\n\nAber wir sollten ihn vielleicht nicht einfach dort lassen. Könntet Ihr ihn bitte finden?", progress = nil, completion = "Ihr habt ein großes Herz, diesem albernen Schurken mehr zu helfen, als er verdient hat.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31760] = {title = "Erstschlag", objective = "Verhindert, dass das Ungetüm der Shao-Tien an Macht gewinnt.", description = "Die Mogu verleihen oben auf der Goldenen Treppe einer riesigen Steinmonstrosität Macht. Sie wollen sie ganz bestimmt gegen uns einsetzen.\n\nWas haltet Ihr davon, ihnen zu verdeutlichen, was wir von der Sache halten? Stellt sicher, dass sie es auch wirklich verstehen.", progress = nil, completion = "Nun, war die Diplomatie erfolgreich? Ich hoffe, Ihr habt Euch nicht zurückgehalten.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31762] = {title = "Bröckelndes Ungetüm", objective = "Zerstört das Ungetüm der Shao-Tien.", description = "Die Mogu haben es geschafft, eine riesige Steinstatue zu erwecken, in der Absicht, sie auf uns zu hetzen.\n\nAls Antwort darauf würde ich gern Euch auf sie hetzen.\n\nSie kommt von der Goldenen Treppe her auf uns zu. Zwingt sie in die Knie...", progress = nil, completion = "Großartig. Sie werden lernen, uns zu fürchten.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31765] = {title = "Rot und tot!", objective = "Benutzt ein Kanonenbootgeschütz, um 80 Gefolgsleute von Donnerwehr zu töten und 9 Kanonen von Donnerwehr zu zerstören.", description = "Sie haben unseren Antrieb kaputtgeschossen und wir sind hierher getrieben - HIERHER! Direkt in die Schusslinie des Feindes!\n\nIhr wisst, was zu tun ist, <Name>. Geht unter Deck und bemannt die Geschütze!\n\nZeigt diesen Dreckskerlen, dass sie in UNSERER Schusslinie sind!", progress = "Worauf wartet Ihr denn?! An die Geschütze!", completion = "Überlegene Feuerkraft der Horde vom Feinsten!\n\n...und Ihr habt Euch wohl auch recht gut geschlagen.", rewards = "FallschirmseiltrennerErsatzkanone eines KanonenbootsKeule des LanderoberersStab des NebelnavigatorsStab des rollenden DonnersKriegskeule des SturmrufersFeldsanitäterstabKampfaxt von Garroshs VorhutGroßaxt aus dem KanonenbootarsenalIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31766] = {title = "Sichere Landung", objective = "Benutzt einen Abseilstrick, um nach unten zu gelangen.", description = "Nazgrim befehligt den Bodenangriff und ersucht, dass Ihr unverzüglich losgeschickt werdet, um Euch mit ihm zu treffen.\n\nWir haben mehrere Kletterseile neben den Kanonen eingerichtet. Ihr werdet feststellen, dass Ihr damit am schnellsten nach unten gelangt, es sei denn, es endet böse.", progress = "Was?", completion = "Da seid Ihr ja!\n\nIch habe mir schon Sorgen gemacht, dass wir losstürmen und uns ohne Euch amüsieren müssen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31767] = {title = "Macht sie kalt!", objective = "Tötet 15 Truppen von Donnerwehr.", description = "Wir haben sie weichgeklopft. Und jetzt wird es Zeit, sie zu erledigen!\n\nDie Allianz muss in dieser Festung ausgemerzt werden, und wir haben keinen Platz für Gefangene.\n\n<Der Anflug eines Lächelns huscht über Nazgrims Gesicht.>\n\nIhr wisst, was zu tun ist, <Name>. Diese Feiglinge werden fliehen, sobald sie Gelegenheit dazu haben.\n\nSeht zu, dass es nicht soweit kommt!", progress = nil, completion = "Gute Arbeit, &lt;Klasse&gt;! Damit haben sie nicht gerechnet!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31768] = {title = "Feuer ist immer die richtige Antwort", objective = "Zerstört 10 Stapel Munition von Donnerwehr.", description = "Es ist nicht genug damit, dass wir ihre Streitkräfte vernichten. Nichts, was sie sich zunutze machen könnten, darf zurückbleiben!\n\nNehmt diese Leuchtpistole und feuert damit auf ihre Munitionsvorräte. Lasst nichts für sie übrig!", progress = nil, completion = "Haha! Gute Arbeit, &lt;Name&gt;.\n\nLasst nichts für sie übrig!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31769] = {title = "Der letzte Schlag!", objective = "Tötet Hauptmann Doren in Donnerwehr.", description = "Der Kapitän hat sich über uns verschanzt.\n\nDer Feigling hat seine Truppen verrecken lassen, während er sich vor unserer Wut versteckt hat! Typisch Allianz! Egal. Er kann sein Los nicht länger hinauszögern.\n\nIch werde mit meinen Marinesoldaten über die Mauern klettern, während Ihr einen Frontalangriff die Rampen hoch leitet. Setzt Eure Leuchtpistole bei der Munition neben den Barrikaden ein, um den Weg freizusprengen.\n\nWir werden uns oben wieder treffen und gemeinsam diesen Waschlappen von einem Kapitän ausschalten!", progress = nil, completion = "Ein Luftstützpunkt - sie hatten die ganze Zeit über einen geheimen Stützpunkt! Wenn ich das gewusst hätte, hätte ich die Geschütze stärker bemannt - waahh -\n\n&lt;Nazgrim wird blass und sein Körper verströmt eine mysteriöse dunkle Energie.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAirship Crash 2\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31770] = {title = "Ihr seid entweder auf unserer Seite oder...", objective = "Versucht, die Hilfe von Bürgermeister Honigtau in Honigtau zu gewinnen.", description = "Die Unterstützung des Dorfes in der Nähe ist eine Notwendigkeit geworden, $p.\n\nWir brauchen das Dorf, um uns neu zu formieren und unsere Verletzten zu versorgen.\n\nVielleicht schließen sich die Dorfbewohner ja unserer Sache an, wenn sie die Brutalität der Allianz zu sehen bekommen.\n\nIhr werdet als <Gesandter/Gesandte> der Horde handeln. Versichert Euch der Kooperation ihres Anführers. Enttäuscht mich nicht!", progress = nil, completion = "Eure Kämpfe haben in unserem kleinen Dorf große Verwüstung angerichtet!\n\nWir sind nicht an Eurem Krieg interessiert, werden Eure Verletzten aber nicht abweisen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31771] = {title = "Im Angesicht der Konsequenzen", objective = "Tötet 20 Shaheimsuchungen und 7 Sha-Herolde.", description = "Weder kenne ich die Geschichte des Krieges, den Ihr kämpft, noch interessiert sie mich besonders. Dieses Land zahlt negative Energie mit gleicher Münze heim. Der Hass, die Zweifel und die Gewalt, die Ihr hier gesät habt, sickern nun aus Pandaria hervor wie das Blut aus einer offenen Wunde.\n\nEure Taten haben überall in diesen Ruinen Unheil gestiftet! Räumt hinter Euch auf und trefft mich unten im Dorf - ich werde mein Bestes tun, zu erklären, was hier vor sich geht.", progress = nil, completion = "Ich bin froh, dass Ihr die Verantwortung für Euer Handeln übernehmt. Unkontrolliert können negative Gefühle hier schnell Besitz von einem ergreifen; genau wie es bei dem, den Ihr \"Nazgrim\" nennt, geschehen ist.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nPing Taran Zhu Completion Event\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31772] = {title = "Prioritäten!", objective = "Findet 6 Fässer mit Honigbräu auf der Honigtaulichtung.", description = "Seht Euch bloß diese Sauerei an! Das ganze Bräu ist verdorben!\n\nTaran Zhu hat uns davor gewarnt mit Euch Außenseitern zu sprechen, ich nehme aber jede Hilfe an, die ich bekommen kann.\n\nWir waren nach Morgenblüte unterwegs, als der Kampf ausbrach. Und jetzt ist unser ganzes Bräu dahin!\n\nWollt Ihr es wiedergutmachen? Vielleicht findet Ihr ja ein paar Fässer mit Honigbräu, die nicht kaputt sind. Dann wäre nicht alles verloren.", progress = nil, completion = "Es ist nicht so viel wie ich gehofft hatte, doch es wird schon reichen. Hat wohl keinen Sinn, verschüttetem Bräu nachzutrauern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31773] = {title = "Pirscherschwierigkeiten", objective = "Tötet 10 Sha-verseuchte Pirscher auf der Honigtaulichtung.", description = "Die Tiere spielen alle verrückt!\n\nNormalerweise meiden die Pirscher das Dorf, doch jetzt scheinen wir sie nicht mehr fernhalten zu können. So habe ich sie noch nie gesehen!\n\nDer Bürgermeister hat die Shado-Pan gerufen, sie sind aber noch nicht alle da. Könnt Ihr Euch um die Pirscher kümmern, ehe sie einen von unseren Bauern in Stücke reißen?", progress = nil, completion = "Euer Konflikt bei den Ruinen fängt also an, die einheimische Tierwelt zu verschmutzen? Das ist ausgesprochen beunruhigend - eine so intensive Reaktion habe ich noch nie beobachtet.\n\nDanke, dass Ihr das Dorf beschützt habt, obwohl es eine Tragödie ist, dass die armen Tiere sterben mussten.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nPing Taran Zhu Completion Event\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31774] = {title = "Die Suche nach Zin'Jun", objective = "Findet Zin'jun irgendwo im Aufstieg der Wirbelnden Winde.", description = "Nieti behauptet gesehen zu haben, wie Zin'Jun mit den restlichen Überlebenden das Schiff verlassen hat. Das heißt, er ist noch immer irgendwo da draußen.\n\nWir dürfen ihn nicht zurücklassen. Er könnte verletzt oder gar gefangen genommen worden sein!\n\nFindet Zin'Jun und bringt ihn zurück.", progress = nil, completion = "&lt;Zin'Jun ist schwer verletzt, spürt aber, dass Ihr freundlich seid.&gt;\n\nAffendinger! Überall diese Affendinger!", rewards = "Lederstiefel der LandungKettenstiefel der LandungSeidene Treter der LandungSatintreter der LandungMokassins der LandungSabatons der LandungBrünierte Schienbeinschützer der LandungKriegsstiefel der LandungPlattenstiefel der LandungDer folgende Zauber wird auf euch gewirkt:\n\nHozen Faction Set, Hated\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31775] = {title = "Angriff auf den Flugplatz", objective = "Tötet 15 Starkarmsoldaten auf dem Starkarmflugplatz.", description = "Ich habe ihren geheimen Flugplatz gefunden, <Name>: den Starkarmflugplatz. Schwer war es nicht, denn es wimmelt dort nur so vor Truppen der Allianz.\n\n<Nazgrim spuckt auf den Boden.>\n\nSie denken, sie hätten uns ausgelöscht, aber wir sind die Horde! Wir kämpfen, bis zum Tod... und womöglich darüber hinaus. Lassen wir sie unseren Stahl kosten!", progress = nil, completion = "Was das Beste daran ist, die Allianz in Pandaria zu töten? Es wird Monate dauern, bevor sie Verstärkung erhalten.\n\nDies Land wird der Horde gehören, &lt;Klasse&gt;. Wir sind beinahe fertig.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31776] = {title = "Starkarmtaktiken", objective = "Tötet Korporal Jackson Silver, Morgus Grimmbeil, Meisteringenieur Ritzelschwung und Gyromechanikerin Lavendelol.", description = "Die Späherberichte vom Starkarmflugplatz liegen jetzt vor und ich habe einige Ziele hoher Priorität markiert.\n\nZwei gnomische Mechaniker sorgen dafür, dass die Allianz ständig Gyrokopter in der Luft hat. Schaltet die Mechaniker aus und die Anzahl der Gyrokopter wird zurückgehen.\n\nEin zwergischer Todesritter patrouilliert um die Basis. Er ist ein Abenteurer, genau wie Ihr, und höchst gefährlich.\n\nUnd dann noch ein Name, der mir bekannt ist: Korporal Jackson Silver. Er ist ein Held der Allianz und tödlich im Umgang mit der Armbrust.\n\nViel Glück, <Name>.", progress = nil, completion = "Blut und Donner, &lt;Name&gt;. Blut und Donner.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31777] = {title = "Runter kommen sie alle", objective = "Beschafft Euch auf dem Starkarmflugplatz Zugriff auf requirierte Feuerwerkszünder und setzt diese gegen 12 Starkarmgyrokopter ein.", description = "Ich habe hier drüben ein paar schultermontierte Raketenwerfer entdeckt.\n\nVielleicht waren's auch Feuerwerkskörper. Keine Ahnung. Ich gehe erst mal davon aus, dass es schultermontierte Raketenwerfer sind, bis das Gegenteil erwiesen ist.\n\nWas ich damit sagen will, ist, dass jemand mit Euren Fertigkeiten als <Klasse> damit vermutlich sogar einen Hubschrauber aus der Luft schießen könnte. Wenn Ihr welche findet, zielt damit auf diese armselig konstruierten Gyrokopter.", progress = nil, completion = "Ich hoffe, diese Ding-Dongs hatten Spaß bei der Party, die Ihr für sie geschmissen habt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31778] = {title = "Unverlässliche Verbündete", objective = "Bringt 12 Pandarenfreiwillige dazu, den Starkarmflugplatz zu verlassen.", description = "Zu Anfang haben wir die Allianz als Freunde willkommen geheißen. Viele unserer Dorfbewohner haben sich freiwillig gemeldet, um ihnen beim Bau eines Flugplatzes zu helfen. Aber vor Kurzem ist uns klargeworden, dass sie eine Militärbasis errichten - nur einen Katzensprung von unserem Dorf entfernt.\n\nUnd was noch schlimmer ist: Ich befürchte, dass einige Dorfbewohner dort gegen ihren Willen festgehalten werden. Falls Ihr sie findet, <Klasse>, dann lasst sie wissen, dass es an der Zeit ist, nach Hause zu kommen.", progress = nil, completion = "Auch wenn ich nicht verstehen kann, wieso Ihr Euren Krieg in unser Land tragt, sehe ich doch deutlich, welche der beiden am Konflikt beteiligten Parteien sich tugendhafter verhält.\n\nIch danke Euch für Eure Hilfe, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31779] = {title = "Das dunkle Innere", objective = "Tötet Hauptmann Doren.", description = "Ihr seid da draußen nicht zufällig Hauptmann Doren begegnet, oder?\n\nDieser schleimige Allianzanführer muss sich hier irgendwo versteckt halten. Auch, wenn er nicht in dieser Luftbasis war - weit kann er nicht sein. Durchkämmt das Gelände - und versucht, die Höhle südwestlich des Hauptflugplatzes zu durchsuchen. Ich will, dass die Allianz von hier verschwindet!", progress = "Dann nichts wie ab mit Euch, <Name>.", completion = "Die Allianztruppen wurden besiegt. Ihr, Nazgrim, Kiryn, Gorrok, Shokia und Nieti braucht eine Operationsbasis.\n\nDiese Flaggen müssen ausgetauscht werden.\n\nFür die Horde!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSwitch Flags\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31780] = {title = "Mac Donald", objective = "Besiegt Mac Donald in einem Haustierkampf.", description = "Dieses Mal werdet Ihr mich nicht so leicht besiegen!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31781] = {title = "Lindsay", objective = "Besiegt Lindsay in einem Haustierkampf.", description = "Ihr wollt es also noch mal mit mir aufnehmen? Ich nehme jede Herausforderung an!", progress = nil, completion = "Das hat überhaupt keinen Spaß gemacht!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31782] = {title = "Umsturz", objective = "Sprecht mit Klaxxi'va Ik in Klaxxi'vess.", description = "Der Rat ist im Einklang, <Erwecker/Erweckerin>.\n\nUnser Ritual wird den Niedergang der Kaiserin herbeiführen und dazu beitragen, dass die Zukunft unseres großen Reichs gesichert ist.\n\nErlebt die Macht der Klaxxi!", progress = nil, completion = "Wir sind... geschlagen, Erwecker.\n\nEure Anstrengungen scheinen für unsere Sache unerlässlich geworden zu sein.\n\nIm Namen der verbleibenden Ratsmitglieder bitte ich Euch um Eure fortwährende Unterstützung.", rewards = "MuttersaatkordelSaftfliegengürtelVerdorrter HolztaillenschutzKlarheitsschnallengürtelSchreckensspinnerkordelGeisterfuchsgürtelWindschnittertaillenschutzGurt des KlingenverschriebenenKältebissgurtIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31784] = {title = "Onyxquisit", objective = "Was habt Ihr da, <Name>?", description = nil, progress = "Was habt Ihr da, <Name>?", completion = "Es war die richtige Entscheidung, dieses Ei zu mir zu bringen. Wir werden gut darauf aufpassen, &lt;Name&gt;.", rewards = nil}
MultiLanguageQuestData['de'][31785] = {title = "Stufenaufstieg", objective = "Lasst ein Haustier auf Stufe 3 aufsteigen.", description = "Gut, gut. Es ist wichtig, dass Ihr Eure Haustiere bei guter Gesundheit und kampfbereit haltet!\n\nAls nächstes möchte ich, dass Ihr mehrere Kämpfe bestreitet und ein Haustier auf Stufe 3 bringt. Danach kehrt Ihr zu mir zurück und wir überlegen, wie Ihr Eure eigenen Haustiere fangen könnt!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31786] = {title = "Makellose Fesseln der Rebellion", objective = "Stellt das Artefakt zur Schau.", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Das wird den Lehrensuchern und Archäologen dabei helfen, die Geschichte von Pandaria zu verstehen.", rewards = "Ihr bekommt:\n\nRestauriertes ArtefaktBruchstück einer Mogustatue"}
MultiLanguageQuestData['de'][31787] = {title = "Makelloser Runenstein der Mogu", objective = "Stellt das Artefakt zur Schau.", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Dieses Artefakt wird Lehrensuchern und Archäologen helfen, Pandarias Geschichte besser zu verstehen.", rewards = "Ihr bekommt:\n\nRestauriertes ArtefaktBruchstück einer Mogustatue"}
