MultiLanguageQuestData['de'][31804] = {title = "Makellose Standarte von Niuzao", objective = "Stellt das Artefakt zur Schau.", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Dieses Artefakt wird Lehrensuchern und Archäologen helfen, Pandarias Geschichte besser zu verstehen.", rewards = "Ihr bekommt:\n\nRestauriertes ArtefaktPandarische Tonscherbe"}
MultiLanguageQuestData['de'][31805] = {title = "Makelloses Kassenbuch eines Architekten", objective = "Stellt das Artefakt zur Schau.", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Dieses Artefakt wird Lehrensuchern und Archäologen helfen, Pandarias Geschichte besser zu verstehen.", rewards = "Ihr bekommt:\n\nRestauriertes ArtefaktBruchstück einer Mogustatue"}
MultiLanguageQuestData['de'][31806] = {title = "Test Quest", objective = "Stellt das Artefakt zur Schau.", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nJuwelendanioTigerguramiGoldkarpfenRiffkrakeRiesige MantisgarneleKaiserlachs"}
MultiLanguageQuestData['de'][31808] = {title = "Hiebe sind für alle da", objective = "Tötet 200 Mantis, während Ihr Kovok in der Schneise kontrolliert.", description = "Kovok hat erstaunliche Fortschritte gemacht. Vielleicht haben die vielen Jahre des Winterschlafs sein Wachstum beeinflusst...\n\nWas immer auch dahinterstecken mag, es hätte zu keinem günstigeren Zeitpunkt passieren können. Ich glaube, es ist an der Zeit, seine Fähigkeiten auf die Probe zu stellen.\n\nDa Ihr so viel zu seiner Ausbildung beigetragen habt, finde ich es passend, dass Ihr ihm in seinem ersten Kampf zur Seite steht.\n\nIch habe ihn bereits an den Rand der Schneise geschickt. Sucht ihn auf und vernichtet die Armee der Shek'zeer!", progress = nil, completion = "Durch Euren Geist konnte ich einige Szenen von der Schlacht sehen. Es schien mir ein echtes Massaker zu sein! Gut gemacht!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31809] = {title = "Überbleibsel des Zorns", objective = "Bringt die Klaue des Zorns zu Ban Bärenherz bei der Shado-Pan-Garnison in der Tonlongsteppe.", description = "Während Ihr die abgetrennte Klaue des besiegten Sha des Zorns betrachtet, kommt Euch der Gedanke, dass Ban Bärenherz, Kommandant der Shado-Pan in der Tonlongsteppe, bestimmt über Euren Sieg informiert werden möchte.", progress = "<Ban schaut Euch eindringlich an.>\n\n Irgendetwas an Euch ist... anders. Verändert.", completion = "&lt;Als Ihr Ban die Klaue überreicht, reißt er vor Erstaunen über Eure Leistung die Augen auf.&gt;\n\nJetzt verstehe ich, welche Veränderung in Euch stattgefunden hat.\n\nIhr habt das Unmögliche vollbracht. Solange die Shado-Pan über dieses Land wachen, werden wir Euren Namen in Ehren halten.", rewards = "Treter der inbrünstigen FeindschaftStiefel des unauslöschlichen SchattensZerstampfende ZorntreterUnbeherrschte GroßstiefelFußharnisch des GeistfeuersWutherztreterZorngeschmiedete StampferSchattensandalenStiefel des WutschleiersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31810] = {title = "Am Himmel reiten", objective = "Schließt Euch dem Orden der Wolkenschlange an.", description = "Ich kann Euch nichts mehr beibringen, <Name>.\n\nIhr habt Euch Eurer Schlange als würdig erwiesen.\n\nHeute werdet Ihr in unseren Orden aufgenommen. Seid Ihr bereit?", progress = nil, completion = "Heute verbrüdern wir uns.\n\nHerzlichen Glückwunsch zur Aufnahme in den Orden der Wolkenschlange. Reiten wir zusammen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZügel der Azurwolkenschlange\n\nIhr erlernt außerdem:\n\nWolkenschlangenreiten\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][31811] = {title = "Am Himmel reiten", objective = "Schließt Euch dem Orden der Wolkenschlange an.", description = "Ich kann Euch nichts mehr beibringen, <Name>.\n\nIhr habt Euch Eurer Schlange als würdig erwiesen.\n\nHeute werdet Ihr in unseren Orden aufgenommen. Seid Ihr bereit?", progress = nil, completion = "Heute verbrüdern wir uns.\n\nHerzlichen Glückwunsch zur Aufnahme in den Orden der Wolkenschlange. Reiten wir zusammen!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nZügel der Goldwolkenschlange\n\nIhr erlernt außerdem:\n\nWolkenschlangenreiten\n\nDer folgende Zauber wird auf euch gewirkt:\n\nWolkenschlangenreiten\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][31812] = {title = "Zunta, der Tierzähmer", objective = "Besiegt Zunta in einem Haustierkampf.", description = "Wie ich sehe, habt Ihr Eure Fertigkeiten im Haustierkampf verbessert, <Name>. Ich glaube, Ihr seid reif für eine echte Herausforderung.\n\nIhr findet Zunta nahe Tor'krens Hof, südlich von Orgrimmar. Er ist ein aufstrebender Wildtierzähmer und ich finde, Ihr solltet Euch mit ihm im Kampf messen!", progress = nil, completion = "Ach, Varzok. Ja, ich kenne ihn gut. Euch hierher zu schicken, war kein Fehler.", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31813] = {title = "Dagra die Grimmige", objective = "Besiegt Dagra die Grimmige in einem Haustierkampf.", description = "Da unten gibt's noch 'ne Trainerin, der Ihr einen Kampf liefern solltet, um Euer Können auf die Probe zu stellen.\n\nDagra die Grimmige erwartet Euch am Nordhang des Dornenhügels östlich des Wegekreuzes. Wenn Ihr sie schlagt, habt Ihr womöglich drauf, was es braucht.", progress = nil, completion = "Ihr kämpft mit der Entschlossenheit von jemandem, der die Niederlage weder fürchtet noch duldet. Ihr werdet es weit bringen.", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31814] = {title = "Analynn", objective = "Besiegt Analynn in einem Haustierkampf.", description = "Ohne eine echte Herausforderung ist jede Entschlossenheit ohne Wert.\n\nSucht die Straßen des westlichen Eschentals nach Analynn ab. Sie mag ein wenig... exzentrisch... erscheinen, aber eine gute Trainerin ist sie dennoch! Euch im Kampf gegen sie zu erproben, wird Eure Mannschaft stählen.", progress = nil, completion = "Ihr versteht nicht. Ich habe keine Niederlage erlitten sondern lediglich einen kleinen Rückschlag.", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31815] = {title = "Zonya die Sadistin", objective = "Besiegt Zonya die Sadistin in einem Haustierkampf.", description = "<Name>, es hat sich eine seltene Gelegenheit ergeben, und ich glaube, Ihr werdet Interesse daran finden.\n\nZonya die Sadistin aus dem südlichen Steinkrallengebirge ist in die Kampfszene zurückgekehrt. Ich muss einfach vorschlagen, dass Ihr sie herausfordert, um Eure Fähigkeiten als <Zähmer/Zähmerin> weiter zu vervollkommnen.", progress = nil, completion = "Hat Euch der Sieg geschmeckt? Es war Euer letzter. Ab hier wird es nicht leichter.", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31816] = {title = "Gluk der Verräter", objective = "Besiegt Bill den Piraten in einem Haustierkampf.", description = "Seid Ihr bereit für ein Abenteuer? Bill der Pirat, der Star unter den örtlichen Tierzähmern am Schlingendornkap, hat eine offene Herausforderung an alle vorbereiteten Trainer herausgegeben!\n\nIhr könnt Bill den Piraten im südlichen Schlingendornkap finden, wo er die örtlichen Straßen auf der Suche nach potenziellen Kämpfen bereist.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31817] = {title = "Merda Starkhuf", objective = "Besiegt Merda Starkhuf in einem Haustierkampf.", description = "Seid Ihr für einen echten Beweis Eures Könnens bereit, <Volk>?\n\nMerda Starkhuf hat ihr Lager an dem Ort aufgeschlagen, den sie in der Cenariuswildnis von Desolace Karnums Lichtung nennen. Gegen eine so starke Trainerin anzutreten, wird Eure Fertigkeiten auf den Prüfstand stellen, hm?", progress = nil, completion = "Der Widerstand von Desolace hält Eurem Wunsch zu wachsen nicht stand. Ich weiß Eure Mühe zu würdigen.", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31818] = {title = "Zunta", objective = "Besiegt Zunta in einem Haustierkampf.", description = "Ihr wollt es also noch mal mit mir aufnehmen?", progress = nil, completion = "Hört auf! Genug! Ihr gewinnt!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31819] = {title = "Dagra die Grimmige", objective = "Besiegt Dagra die Grimmige in einem Haustierkampf.", description = "Ihr seid diesen Berg erneut bestiegen, nur, um Eurem eigenen Untergang beizuwohnen.", progress = nil, completion = "Unmöglich!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31820] = {title = "Ein Geschenk für den Lehrer", objective = "Nehmt Nomis Geschenk an.Ich habe jetzt mit den anderen Kindern aufgeholt, obwohl ich erst so spät angefangen habe. Endlich kann ich am planmäßigen Unterricht teilnehmen!\n\nIch habe Euch eine Schürze gemacht, um mich für all das zu bedanken, was Ihr für mich getan habt. Ich hoffe, sie gefällt Euch.Auf Euch wartet eine dieser Belohnungen:\n\n", description = "Ich habe jetzt mit den anderen Kindern aufgeholt, obwohl ich erst so spät angefangen habe. Endlich kann ich am planmäßigen Unterricht teilnehmen!\n\nIch habe Euch eine Schürze gemacht, um mich für all das zu bedanken, was Ihr für mich getan habt. Ich hoffe, sie gefällt Euch.Auf Euch wartet eine dieser Belohnungen:\n\n", progress = nil, completion = nil, rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nHundert Jahre alte SojasoßeReismehlSchwarzer Pfeffer\n\nIhr bekommt außerdem:\n\nSchürze"}
MultiLanguageQuestData['de'][31821] = {title = "Stufenaufstieg", objective = "Lasst ein Haustier auf Stufe 3 aufsteigen.", description = "Gut, gut. Es ist wichtig, dass Ihr Eure Haustiere bei guter Gesundheit und kampfbereit haltet!\n\nAls nächstes möchte ich, dass Ihr mehrere Kämpfe bestreitet und ein Haustier auf Stufe 3 bringt. Danach kehrt Ihr zu mir zurück und wir überlegen, wie Ihr Eure eigenen Haustiere fangen könnt!", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Als Nächstes müsst Ihr lernen, Eure eigenen Kampfhaustiere zu fangen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31822] = {title = "Stufenaufstieg", objective = "Lasst ein Haustier auf Stufe 3 aufsteigen.", description = "Gut, gut. Es ist wichtig, dass Ihr Eure Haustiere bei guter Gesundheit und kampfbereit haltet!\n\nAls nächstes möchte ich, dass Ihr mehrere Kämpfe bestreitet und ein Haustier auf Stufe 3 bringt. Danach kehrt Ihr zu mir zurück und wir überlegen, wie Ihr Eure eigenen Haustiere fangen könnt!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
