MultiLanguageQuestData['de'][31833] = {title = "Die Ausbildung fortsetzen: Meisterin Woo", objective = "Sprecht mit Meisterin Woo auf dem Gipfel der Ruhe und schließt Eure Ausbildung mit ihr ab.", description = "Willkommen zurück, <Name>. Die Zeit ist gekommen, den nächsten Abschnitt Eurer Ausbildung zu absolvieren. Sprecht mit Meisterin Woo unten auf dem Ausbildungsgelände, um Eure nächste Lektion zu erhalten.", progress = nil, completion = "Meisterin Woo hat mir berichtet, dass Eure Ausbildung erfolgreich verlaufen ist. Kehrt zurück, wenn Ihr sie zukünftig fortsetzen wollt.", rewards = "Schneidender gelber GürtelFormidabler gelber GürtelGelassener gelber GürtelIhr erlernt:\n\nErleuchtung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][31834] = {title = "Die Ausbildung beginnt: Meister Cheng", objective = "Sprecht mit Meister Cheng auf dem Ausbildungsgelände und schließt Eure Ausbildung mit ihm ab.", description = "Seid gegrüßt, <Name>. Willkommen auf dem Gipfel der Ruhe. Dies ist der Ort, an dem wir Mönche trainieren und unsere Fertigkeiten in der Kampfkunst perfektionieren. Es ist an der Zeit, dass Ihr Eure Ausbildung antretet. Sprecht mit Meister Cheng auf dem Ausbildungsgelände unter uns, um zu beginnen.", progress = nil, completion = "Meister Cheng hat mir berichtet, dass Eure Ausbildung erfolgreich verlaufen ist. Kehrt zurück, wenn Ihr sie zukünftig fortsetzen wollt.", rewards = "Harmonischer Stab des AspirantenAnmutiger Stab des AspirantenIhr erlernt:\n\nErleuchtung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][31835] = {title = "Die Ausbildung fortsetzen: Meisterin Kistane", objective = "Sprecht mit Meisterin Kistane auf dem Gipfel der Ruhe und schließt Eure Ausbildung mit ihr ab.", description = "Willkommen zurück, <Name>. Die Zeit ist gekommen, den nächsten Abschnitt Eurer Ausbildung zu absolvieren. Sprecht mit Meisterin Kistane unten auf dem Ausbildungsgelände, um Eure nächste Lektion zu erhalten.", progress = nil, completion = "Meisterin Kistane hat mir berichtet, dass Eure Ausbildung erfolgreich verlaufen ist. Kehrt zurück, wenn Ihr sie zukünftig fortsetzen wollt.", rewards = "Grüner Gürtel des stillen VerstehensGrüner Gürtel der geflüsterten WeisheitIhr erlernt:\n\nErleuchtung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][31836] = {title = "Die Ausbildung fortsetzen: Meister Yoon", objective = "Sprecht mit Meister Yoon auf dem Gipfel der Ruhe und schließt Eure Ausbildung mit ihm ab.", description = "Willkommen zurück, <Name>. Die Zeit ist gekommen, den nächsten Abschnitt Eurer Ausbildung zu absolvieren. Sprecht mit Meister Yoon unten auf dem Ausbildungsgelände, um Eure nächste Lektion zu erhalten.", progress = nil, completion = "Meister Yoon hat mir berichtet, dass Eure Ausbildung erfolgreich verlaufen ist. Kehrt zurück, wenn Ihr sie zukünftig fortsetzen wollt.", rewards = "Stirnband des springenden TigersStirnband des anstürmenden OchsenStirnband der zusammengerollten SchlangeIhr erlernt:\n\nErleuchtung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][31837] = {title = "Die Ausbildung fortsetzen: Meisterin Cheng", objective = "Sprecht mit Meisterin Cheng auf dem Gipfel der Ruhe und schließt Eure Ausbildung mit ihr ab.", description = "Willkommen zurück, <Name>. Die Zeit ist gekommen, den nächsten Abschnitt Eurer Ausbildung zu absolvieren. Sprecht mit Meisterin Cheng unten auf dem Ausbildungsgelände, um Eure nächste Lektion zu erhalten.", progress = nil, completion = "Meisterin Cheng hat mir berichtet, dass Eure Ausbildung erfolgreich verlaufen ist. Kehrt zurück, wenn Ihr sie zukünftig fortsetzen wollt.", rewards = "Roter Gürtel der sanften ÜberredungRoter Gürtel der wortlosen WarnungIhr erlernt:\n\nErleuchtung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][31838] = {title = "Die Ausbildung fortsetzen: Meister Tsang", objective = "Sprecht mit Meister Tsang auf dem Gipfel der Ruhe und schließt Eure Ausbildung mit ihm ab.", description = "Willkommen zurück, <Name>. Die Zeit ist gekommen, den nächsten Abschnitt Eurer Ausbildung zu absolvieren. Sprecht mit Meister Tsang unten auf dem Ausbildungsgelände, um Eure nächste Lektion zu erhalten.", progress = nil, completion = "Meister Tsang hat mir berichtet, dass Eure Ausbildung erfolgreich verlaufen ist. Kehrt zurück, wenn Ihr sie zukünftig fortsetzen wollt.", rewards = "Brauner Gürtel des labilen GleichgewichtsBrauner Gürtel der erniedrigenden SchwerkraftIhr erlernt:\n\nErleuchtung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][31839] = {title = "Die Ausbildung fortsetzen: Meister Hsu", objective = "Sprecht mit Meister Hsu auf dem Gipfel der Ruhe und schließt Eure Ausbildung mit ihm ab.", description = "Willkommen zurück, <Name>. Die Zeit ist gekommen, den nächsten Abschnitt Eurer Ausbildung zu absolvieren. Sprecht mit Meister Hsu unten auf dem Ausbildungsgelände, um Eure nächste Lektion zu erhalten.", progress = nil, completion = "Meister Hsu hat mir berichtet, dass Eure Ausbildung erfolgreich verlaufen ist. Kehrt zurück, wenn Ihr sie zukünftig fortsetzen wollt.", rewards = "Klingenstab des gefrorenen BergsKlingenstab der GipfelbriseKlingenstab des schallenden GongsIhr erlernt:\n\nErleuchtung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][31840] = {title = "Übung macht den Meister: Meister Cheng", objective = "Sprecht mit Meister Cheng auf dem Gipfel der Ruhe und messt Euch mit ihm.", description = "Schön, dass Ihr wieder da seid, <Name>. Ich sehe, Ihr seid zurückgekommen, um Eure Fertigkeiten zu verbessern. Sprecht mit Meister Cheng auf dem Ausbildungsgelände unter uns, um einen Übungskampf einzulegen.", progress = nil, completion = "Meister Cheng hat mir berichtet, dass Eure Ausbildung erfolgreich verlaufen ist. Kehrt zurück, wenn Ihr sie zukünftig fortsetzen wollt.", rewards = "Ihr erlernt:\n\nErleuchtung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][31841] = {title = "Übung macht den Meister: Meisterin Woo", objective = "Sprecht mit Meisterin Woo auf dem Gipfel der Ruhe und schließt Eure Ausbildung mit ihr ab.", description = "Schön, dass Ihr wieder da seid, <Name>. Ich sehe, Ihr seid zurückgekommen, um Eure Fertigkeiten zu verbessern. Sprecht mit Meisterin Woo auf dem Ausbildungsgelände unter uns, um einen Übungskampf einzulegen.", progress = "Schließt Eure Ausbildung mit Meisterin Woo ab.", completion = "Meisterin Woo hat mir berichtet, dass Eure Ausbildung erfolgreich verlaufen ist. Kehrt zurück, wenn Ihr sie zukünftig fortsetzen wollt.", rewards = "Ihr erlernt:\n\nErleuchtung\n\nIhr bekommt außerdem:\n\n"}
