MultiLanguageQuestData['de'][31846] = {title = "Übung macht den Meister: Meister Hsu", objective = "Sprecht mit Meister Hsu auf dem Gipfel der Ruhe und schließt Eure Ausbildung mit ihm ab.", description = "Schön, dass Ihr wieder da seid, <Name>. Ich sehe, Ihr seid zurückgekommen, um Eure Fertigkeiten zu verbessern. Sprecht mit Meister Hsu auf dem Ausbildungsgelände unter uns, um einen Übungskampf einzulegen.", progress = nil, completion = "Ich höre von Meister Hsu, dass Eure Ausbildung zufriedenstellend verläuft. Kommt in Zukunft wieder zu mir, um Eure Ausbildung fortzusetzen.", rewards = "Ihr erlernt:\n\nErleuchtung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][31847] = {title = "Lieber ein Ende mit Schrecken als die Schreckensöde", objective = "Sprecht mit Bogenmeisterin Li auf dem Schlangenrücken.", description = "Ich bin mir sicher, dass viele unserer Verbündeten nach Eurem Sieg hier Eure Dienste in Anspruch nehmen wollen. Doch ich habe einen Hilferuf unserer Verteidiger an der Grenzmauer zur Schreckensöde erhalten.\n\nFalls Ihr ihnen helfen wollt, nehmt einen Drachen und meldet Euch bei Bogenmeisterin Li.", progress = nil, completion = "Ein Freiwilliger für den Dienst in der Schreckensöde? Da dürftet Ihr der erste sein.\n\nFreut mich, Euch kennenzulernen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31850] = {title = "Eric Davidson", objective = "Besiegt Eric Davidson in einem Haustierkampf.", description = "Aha, Ihr habt Euch also erneut in den Wald gewagt, um es im Kampf mit mir aufzunehmen. Ich nehme Eure dreiste Herausforderung meiner teuflischen Brut an.", progress = nil, completion = "Euer Mut zum Risiko wurde belohnt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31851] = {title = "Bill Schildbuckel", objective = "Besiegt Bill Schildbuckel in einem Haustierkampf.", description = "Ihr scheid wohl für die nächste Runde da, wasch?\n\nIch werd' Euch schon scheigen, warum man mich den Schrecken desch Talsch nennt!", progress = nil, completion = "Heut mögt Ihr geschiegt haben, Kumpel, aber näschtesch Mal lasch ich Euch nicht scho ungeschoren davonkommen, jawoll!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31852] = {title = "Steven Lisbane", objective = "Besiegt Steven Lisbane in einem Haustierkampf.", description = "Ihr wagt es, mich erneut herauszufordern? Diesmal glaube ich, dass unser Kampf zu meinen Gunsten ausgehen wird!", progress = nil, completion = "Ein spannender Kampf! Grandios! Wirklich gut gemacht!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31853] = {title = "Alle Mann an Bord!", objective = "Sprecht mit General Nazgrim an Bord von Höllschreis Faust.", description = "Habt Ihr gehört, <Name>? Ich muss eine kampferprobte Mannschaft für eine gefährliche Mission zusammenstellen – es gibt Allianzler zu töten.\n\nIhr werdet mich begleiten!\n\nWir kehren nicht eher zurück, als unsere Aufgabe erfüllt ist, also packt Eure Sachen und macht Euch bereit.\n\nIhr findet mich an Bord eines neu in Dienst gestellten Luftschiffs über der Messerbucht.\n\nLasst mich ja nicht warten!", progress = nil, completion = "Willkommen an Bord von Höllschreis Faust, &lt;Name&gt;!\n\nDas hier ist ihre Jungfernfahrt. Ist sie nicht eine Schönheit?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31854] = {title = "Analynn", objective = "Besiegt Analynn in einem Haustierkampf.", description = "Ich sehe, Ihr habt mich schon wieder gefunden. Ich nehme an, Ihr möchtet einen weiteren Kampf? So sei es.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31855] = {title = "Der Gipfel der Ruhe - Setzt Eure Ausbildung fort", objective = "Reist mithilfe der Zenpilgerfahrt zum Gipfel der Ruhe. Sprecht bei Eurer Ankunft mit Meister Hight am Schrein des Ochsen.", description = "Es ist Zeit, dass Ihr zum Gipfel der Ruhe zurückkehrt, um Eure Ausbildung fortzusetzen. Kehrt mithilfe der Zenpilgerfahrt dorthin zurück und sprecht bei Eurer Ankunft mit Meister Hight.", progress = nil, completion = "Willkommen, &lt;Name&gt;. Es ist Zeit, Eure Ausbildung fortzusetzen.", rewards = nil}
MultiLanguageQuestData['de'][31856] = {title = "Der Gipfel der Ruhe - Beginnt Eure Ausbildung", objective = "Reist mithilfe der Zenpilgerfahrt zum Gipfel der Ruhe. Sprecht bei Eurer Ankunft mit Meister Hight am Schrein des Ochsen.", description = "Es ist Zeit, dass Ihr zum Gipfel der Ruhe aufbrecht und Euch dort im Weg des Mönchs ausbilden lasst. Begebt Euch mithilfe der Zenpilgerfahrt dorthin und sprecht bei Eurer Ankunft mit Meister Hight.", progress = nil, completion = "Willkommen, &lt;Name&gt;. Es ist Zeit, mit Eurer Ausbildung zu beginnen.", rewards = nil}
MultiLanguageQuestData['de'][31857] = {title = "Der Gipfel der Ruhe - Setzt Eure Ausbildung fort", objective = "Reist mithilfe der Zenpilgerfahrt zum Gipfel der Ruhe. Sprecht bei Eurer Ankunft mit Meister Hight am Schrein des Ochsen.", description = "Es ist Zeit, dass Ihr zum Gipfel der Ruhe zurückkehrt, um Eure Ausbildung fortzusetzen. Kehrt mithilfe der Zenpilgerfahrt dorthin zurück und sprecht bei Eurer Ankunft mit Meister Hight.", progress = nil, completion = "Willkommen, &lt;Name&gt;. Es ist Zeit, Eure Ausbildung fortzusetzen.", rewards = nil}
