MultiLanguageQuestData['de'][31861] = {title = "Der Gipfel der Ruhe - Setzt Eure Ausbildung fort", objective = "Reist mithilfe der Zenpilgerfahrt zum Gipfel der Ruhe. Sprecht bei Eurer Ankunft mit Meister Hight am Schrein des Ochsen.", description = "Es ist Zeit, dass Ihr zum Gipfel der Ruhe zurückkehrt, um Eure Ausbildung fortzusetzen. Kehrt mithilfe der Zenpilgerfahrt dorthin zurück und sprecht bei Eurer Ankunft mit Meister Hight.", progress = nil, completion = "Willkommen, &lt;Name&gt;. Es ist Zeit, Eure Ausbildung fortzusetzen.", rewards = nil}
MultiLanguageQuestData['de'][31862] = {title = "Zonya die Sadistin", objective = "Besiegt Zonya die Sadistin in einem Haustierkampf.", description = "Die Beute läuft in das Revier des Raubtiers, ohne sich der Gefahr bewusst zu sein, in der sie sich befindet. Diesmal werdet Ihr Zonya keine Schwierigkeiten bereiten.", progress = nil, completion = "Ihr glaubt, Ihr hättet gesiegt, ich werde jedoch mit jeder Niederlage stärker.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31870] = {title = "Kassandra Kabumm", objective = "Besiegt Kassandra Kabumm in einem Haustierkampf.", description = "Kassandra Kabumm ist eine gefürchtete Zähmerin, die vor allem für ihre mechanischen Haustiere bekannt ist. Sie wird die nächste Hürde auf Eurem Weg zum Ruhm darstellen.\n\nFindet sie im Südlichen Brachland in der Nähe von Frazzelcraz' Hauptader und fordert sie heraus. Wenn Ihr Kassandra besiegt, wird das Varzoks Meinung über Euch sicherlich zum Positiven ändern.\n\nViel Glück!", progress = nil, completion = "Woah! Ihr habt's echt drauf!", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31871] = {title = "Gluk der Verräter", objective = "Besiegt Gluk den Verräter in einem Haustierkampf.", description = "Ihr habt Gluk schon einmal geschlagen, aber jetzt verpasst Gluk <Volk> eine Niederlage, weil Ihr so mickrig seid!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31872] = {title = "Merda Starkhuf", objective = "Besiegt Merda Starkhuf in einem Haustierkampf.", description = "Genau wie das Land, das immer weiterwächst, ist auch mein Team stärker als je zuvor. Seid Ihr sicher, dass Ihr gegen mich antreten möchtet? Wenn Ihr Euch jetzt geschlagen gebt, ist das keine Schande.", progress = nil, completion = "Euer Sieg ist wohlverdient. Eure Fertigkeiten sind meinen überlegen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31876] = {title = "Die Tintenmeister des Arboretums", objective = "Sprecht mit Tintenmeister Wei im Arboretum im Jadewald.", description = "Ich habe gehört, dass die Tintenmeister im Arboretum die Hilfe eines Schreibers mit den besten Fähigkeiten benötigen. Unterhaltet Euch mit Tintenmeister Wei, wenn Ihr helfen wollt.", progress = nil, completion = "Ah, ein Schreiber mit den besten Fähigkeiten. Einige von uns könnten Eure Hilfe gut gebrauchen.", rewards = "Ihr bekommt:\n\nEisentatzmarke"}
MultiLanguageQuestData['de'][31877] = {title = "Die Tintenmeister des Arboretums", objective = "Sprecht mit Tintenmeister Wei im Arboretum im Jadewald.Ich habe gehört, dass die Tintenmeister im Arboretum die Hilfe eines Schreibers mit den besten Fähigkeiten benötigen. Unterhaltet Euch mit Tintenmeister Wei, wenn Ihr helfen wollt.Ihr bekommt:\n\n", description = "Ich habe gehört, dass die Tintenmeister im Arboretum die Hilfe eines Schreibers mit den besten Fähigkeiten benötigen. Unterhaltet Euch mit Tintenmeister Wei, wenn Ihr helfen wollt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nEisentatzmarke"}
MultiLanguageQuestData['de'][31878] = {title = "Marlene Trichdie", objective = "Meldet Euch bei Marlene Trichdie in Sturmwind.Ich kann Euch nichts mehr beibringen, <Name>. Eure Trainerkarriere jedoch hat gerade erst begonnen!\n\nSucht Marlene Trichdie in Sturmwind auf. Sie steht mit der Elite unter Azeroths Trainern in Verbindung und wird Eurer Entwicklung förderlich sein.Ihr bekommt:\n\n", description = "Ich kann Euch nichts mehr beibringen, <Name>. Eure Trainerkarriere jedoch hat gerade erst begonnen!\n\nSucht Marlene Trichdie in Sturmwind auf. Sie steht mit der Elite unter Azeroths Trainern in Verbindung und wird Eurer Entwicklung förderlich sein.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
