MultiLanguageQuestData['de'][31882] = {title = "Varzok", objective = "Meldet Euch bei Varzok in Orgrimmar.Ich fürchte, es gibt nichts mehr, was ich Euch noch beibringen könnte, <Name>. Eure Reise als <Trainer/Trainerin> ist jedoch noch lange nicht zu Ende!\n\nMeldet Euch bei Varzok in Orgrimmar. Er hat Verbindungen zu vielen der besten Trainer von Azeroth und wird Euch dabei helfen, weiter zu wachsen.Ihr bekommt:\n\n", description = "Ich fürchte, es gibt nichts mehr, was ich Euch noch beibringen könnte, <Name>. Eure Reise als <Trainer/Trainerin> ist jedoch noch lange nicht zu Ende!\n\nMeldet Euch bei Varzok in Orgrimmar. Er hat Verbindungen zu vielen der besten Trainer von Azeroth und wird Euch dabei helfen, weiter zu wachsen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
