MultiLanguageQuestData['de'][31885] = {title = "Varzok", objective = "Meldet Euch bei Varzok in Orgrimmar.Ich fürchte, es gibt nichts mehr, was ich Euch noch beibringen könnte, <Name>. Eure Reise als <Trainer/Trainerin> ist jedoch noch lange nicht zu Ende!\n\nMeldet Euch bei Varzok in Orgrimmar. Er hat Verbindungen zu vielen der besten Trainer von Azeroth und wird Euch dabei helfen, weiter zu wachsen.Ihr bekommt:\n\n", description = "Ich fürchte, es gibt nichts mehr, was ich Euch noch beibringen könnte, <Name>. Eure Reise als <Trainer/Trainerin> ist jedoch noch lange nicht zu Ende!\n\nMeldet Euch bei Varzok in Orgrimmar. Er hat Verbindungen zu vielen der besten Trainer von Azeroth und wird Euch dabei helfen, weiter zu wachsen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31886] = {title = "Schreckensort", objective = "Sprecht mit Bogenmeisterin Li auf dem Schlangenrücken.", description = "Shado-Pan-Bogenschützen halten kontinuierlich Wache über die Schreckensöde, von der Spitze des Schlangenrückens aus. Sie würden die Hilfe von jemand so Fähigem wie Euch, <Klasse>, sicher willkommen heißen.\n\nNehmt einen Drachen und meldet Euch bei Bogenmeisterin Li.", progress = nil, completion = "Ein Freiwilliger für den Dienst in der Schreckensöde? Da dürftet Ihr der erste sein.\n\nFreut mich, Euch kennenzulernen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31889] = {title = "Kampfhaustierzähmer: Kalimdor", objective = "Besiegt Gluk den Verräter, Grazzel den Großen, Kela Grimmtotem, Zoltan und Elena Flatterflug in Haustierkämpfen.", description = "Jetzt, da Ihr Gelegenheit hattet, Euren Fertigkeiten den letzten Schliff zu verleihen, steht Euch die Welt der Haustierkämpfe uneingeschränkt offen.\n\nIn Kalimdor gibt es fünf Zähmer, die Ihr für mich besiegen sollt: Gluk den Verräter in Feralas, Grazzel den Großen in den Düstermarschen, Kela Grimmtotem in Tausend Nadeln, Zoltan im Teufelswald und Elena Flatterflug in der Mondlichtung.\n\nWenn Ihr sie bezwingen könnt, seid Ihr bereit, voranzuschreiten.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31891] = {title = "Kampfhaustierzähmer: Kalimdor", objective = "Besiegt Gluk den Verräter, Grazzel den Großen, Kela Grimmtotem, Zoltan und Elena Flatterflug in Haustierkämpfen.", description = "Jetzt, da Ihr Gelegenheit hattet, Euren Fertigkeiten den letzten Schliff zu verleihen, steht Euch die Welt der Haustierkämpfe uneingeschränkt offen.\n\nIn Kalimdor gibt es fünf Zähmer, die Ihr für mich besiegen sollt: Gluk den Verräter in Feralas, Grazzel den Großen in den Düstermarschen, Kela Grimmtotem in Tausend Nadeln, Zoltan im Teufelswald und Elena Flatterflug in der Mondlichtung.\n\nWenn Ihr sie bezwingen könnt, seid Ihr bereit, voranzuschreiten.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31894] = {title = "Ein empfindliches Gleichgewicht", objective = "Sprecht mit Orbiss in den Sumpfbinsen.", description = "Zum Shado-Pan berufen zu werden bedeutet, dass man sich dem Schutz des Gleichgewichts und der Harmonie dieses Landes verschreibt. Es ist unsere Pflicht, dieses Gleichgewicht aufrechtzuerhalten, <Name>.\n\nDie Aktivitäten der Yaungol in Tonlong jedoch gefährden dieses Gleichgewicht und müssen aufgehalten werden, bevor es zu spät ist.\n\nWir haben Yaungol in den Sumpfbinsen gesichtet. Berichten zufolge sollen sie die Nebellauerer in der Gegend angreifen. Findet heraus warum, und setzt dem ein Ende!", progress = nil, completion = "&lt;Orbiss stöhnt unter Qualen.&gt;\n\nSo so, die Shado-Pan haben Euch ausgesandt, um nachzusehen, was die Yaungol treiben? Nun, seht Ihr es jetzt?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31895] = {title = "Lieber Schrecken als verrecken", objective = "Sprecht mit Bogenmeisterin Li auf dem Schlangenrücken.", description = "Es ist an der Zeit, den Ursprung zu suchen, <Name>!\n\nDie Schützen der Shado-Pan halten von der Spitze des Schlangenrückens aus ohne Unterlass Wache über die Schreckensöde. Sie würden die Hilfe von jemandem mit Euren Fähigkeiten als <Klasse> ganz sicher begrüßen.\n\nSucht Bogenmeisterin Li auf dem Schlangenrücken an der Grenze zur Schreckensöde auf.", progress = nil, completion = "Ein Freiwilliger für den Dienst in der Schreckensöde? Da dürftet Ihr der erste sein.\n\nFreut mich, Euch kennenzulernen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31897] = {title = "Großmeisterin Trixxy", objective = "Besiegt die eiskalte Trixxy in einem Haustierkampf.", description = "Wenn man nach den Meisterzähmern Kalimdors geht, seid Ihr der neue Star der Szene. Warum kommt Ihr nicht bei meinem Ausbildungsgelände in den Eisdistelbergen in Winterquell vorbei, damit ich Euch zeigen kann, wie es wirklich gemacht wird?", progress = nil, completion = "Ihr habt wohl wirklich Starpotenzial, oder? Nächstes Mal wird Euch das Glück weniger hold sein!", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31902] = {title = "Kampfhaustierzähmer: Östliche Königreiche", objective = "Besiegt David Kosse, Deiza Seuchenhorn, Kortas Düsterhammer, Everessa und Durin Düsterhammer in Haustierkämpfen.", description = "Jetzt, da Ihr Gelegenheit hattet, Euren Fertigkeiten den letzten Schliff zu verleihen, steht Euch die Welt der Haustierkämpfe uneingeschränkt offen.\n\nIn den Östlichen Königreichen gibt es fünf Zähmer, die Ihr für mich besiegen sollt: David Kosse im Hinterland, Deiza Seuchenhorn in den Östlichen Pestländern, Kortas Düsterhammer in der Sengenden Schlucht, Everessa in den Sümpfen des Elends und Kortas' Bruder Durin Düsterhammer in der Brennenden Steppe.\n\nWenn Ihr sie bezwingen könnt, seid Ihr bereit für den nächsten Schritt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31903] = {title = "Kampfhaustierzähmer: Östliche Königreiche", objective = "Besiegt David Kosse, Deiza Seuchenhorn, Kortas Düsterhammer, Everessa und Durin Düsterhammer in Haustierkämpfen.", description = "Jetzt, da Ihr Gelegenheit hattet, Euren Fertigkeiten den letzten Schliff zu verleihen, steht Euch die Welt der Haustierkämpfe uneingeschränkt offen.\n\nIn den Östlichen Königreichen gibt es fünf Zähmer, die Ihr für mich besiegen sollt: David Kosse im Hinterland, Deiza Seuchenhorn in den Östlichen Pestländern, Kortas Düsterhammer in der Sengenden Schlucht, Everessa in den Sümpfen des Elends und Kortas' Bruder Durin Düsterhammer in der Brennenden Steppe.\n\nWenn Ihr sie bezwingen könnt, seid Ihr bereit für den nächsten Schritt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31904] = {title = "Kassandra Kabumm", objective = "Besiegt Kassandra Kabumm in einem Haustierkampf.", description = "Ich habe meine Haustiere mit neuen gyrotechnischen Ausbildungsmodulen geladen. Ihr seid erledigt!", progress = nil, completion = "Ich muss irgendwo eine Zeile falsch umgewandelt haben...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31905] = {title = "Grazzel der Große", objective = "Besiegt Grazzel den Großen in einem Haustierkampf.", description = "Ihr seid zurück?! Ihr wollt wohl von einem schwarzen Drachen gefressen werden!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31906] = {title = "Kela Grimmtotem", objective = "Besiegt Kela Grimmtotem in einem Haustierkampf.", description = "Ihr besitzt die Kühnheit, ein Mal mehr Fuß ins Land derer von Grimmtotem zu setzen, um mich herauszufordern? Ihr werdet Euren Entschluss bereuen!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31907] = {title = "Zoltan", objective = "Besiegt Zoltan in einem Haustierkampf.", description = "Ich werde von Tag zu Tag stärker. Widerstand ist zwecklos.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31908] = {title = "Elena Flatterflug", objective = "Besiegt Elena Flatterflug in einem Haustierkampf.", description = "Ich sehe schon, Ihr seid bereit für ein weiteres Kräftemessen in den Lüften. Fliegen wir los!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31909] = {title = "Großmeisterin Trixxy", objective = "Besiegt die eiskalte Trixxy in einem Haustierkampf.", description = "Halt! Eure letzte Begegnung hat Euch wohl endlich aufgewärmt, was? Das soll sich ändern.", progress = nil, completion = "Ihr seid wirklich krass drauf!", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31910] = {title = "David Kosse", objective = "Besiegt David Kosse in einem Haustierkampf.", description = "Meine Forschungen haben sich für meine Trainingsmethoden als äußerst nützlich erwiesen. Dieses Mal werde ich Euch besiegen.", progress = nil, completion = "Womöglich ist meine Forschung doch noch nicht so ausgereift, wie ich angenommen hatte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31911] = {title = "Deiza Seuchenhorn", objective = "Besiegt Deiza Seuchenhorn in einem Haustierkampf.", description = "Noch habt Ihr den wahren Pfad der Untoten nicht eingeschlagen. Vielleicht wird Euch ein weiterer Kampf die Richtung weisen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31912] = {title = "Kortas Düsterhammer", objective = "Besiegt Kortas Düsterhammer in einem Haustierkampf.", description = "Ich habe gehört, dass Ihr gegen meinen Bruder, diesen Narren, gekämpft habt. Er hat wohl verloren, was?\n\nDann darf ich wohl jetzt zeigen, was ich draufhabe!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31913] = {title = "Everessa", objective = "Besiegt Everessa in einem Haustierkampf.", description = "Ich glaube, ich komme langsam hinter die Geheimnisse dieses Orts... Bald schon werde ich nicht mehr aufzuhalten sein!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31914] = {title = "Durin Düsterhammer", objective = "Besiegt Durin Düsterhammer in einem Haustierkampf.", description = "Seit meiner Zeit im Dienst des Feuerlords bin ich für alles gewappnet. Nichts, was Ihr mir entgegenschleudert, könnte mich erschüttern!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31915] = {title = "Großmeisterin Lydia Accoste", objective = "Besiegt Lydia Accoste in einem Haustierkampf.", description = "Die Meisterzähmer in der Umgebung der Östlichen Königreiche reden schon von Euch. Ihr glaubt, Ihr seid nicht aufzuhalten? Ihr glaubt, dass Ihr <der wahre Großmeister/die wahre Großmeisterin> seid?\n\nDann kommt nur, <Name>. Ich erwarte Euch am Gebirgspass der Totenwinde. Kommt, und Ihr werdet die vernichtende Niederlage erleben, die Euch von jeher gebührt.", progress = nil, completion = "Ich habe eine Ewigkeit, um zu trainieren. Ich werde Euch bezwingen!", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31916] = {title = "Großmeisterin Lydia Accoste", objective = "Besiegt Lydia Accoste in einem Haustierkampf.", description = "Ihr möchtet mir noch einmal von Angesicht zu Angesicht gegenüberstehen? Diese Entscheidung werdet Ihr bereuen!", progress = nil, completion = "Eure Strategie wird mir immer klarer. Am Ende ist Euch die Niederlage gewiss.", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31917] = {title = "Heimkehr des Zähmers", objective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", description = "Ihr könnt Euch jetzt kopfüber in waschechte Haustierkämpfe stürz'n. Kehrt zu Eurer Trainerin Marlene Trichdie nach Sturmwind zurück und macht Euch für das Abenteuer Eures Lebens bereit!", progress = nil, completion = "Ich bin ja so stolz auf Euch, &lt;Name&gt;. Ihr seid zu Großem bereit!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31918] = {title = "Heimkehr des Zähmers", objective = "Meldet Euch bei Varzok in Orgrimmar.", description = "Wenn Ihr mich schlagen könnt, dann seid Ihr bereit für die ganz große Bühne! Sprecht mit Varzok in Orgrimmar.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Jetzt könnt Ihr Euch wirklich als Zähmer bezeichnen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31919] = {title = "Kampfhaustierzähmer: Scherbenwelt", objective = "Besiegt Nicki Mikrotech, Ras'an, Narrok und Morulu den Älteren in Haustierkämpfen.", description = "Ihr habt die Meisterzähmer Kalimdors und der Östlichen Königreiche bezwungen, doch Eure nächste Herausforderung wird Euch auf eine sehr viel härtere Probe stellen.\n\nIn der Scherbenwelt gibt es vier Zähmer, die Ihr jetzt besiegen müsst: Nicki Mikrotech auf der Höllenfeuerhalbinsel, Ras'an in den Zangarmarschen, Narrok in Nagrand und Morulu den Älteren in Shattrath.\n\nBesiegt sie, wenn Ihr den Pfad zu wahrer Größe beschreiten wollt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31920] = {title = "Großmeister Antari", objective = "Besiegt Blutritter Antari in einem Haustierkampf.", description = "Leute wie Euch kenne ich zur Genüge: junge, naive Zähmer, die glauben, dass sie es verdienen, die Siegeslorbeeren auf dem Silbertablett gereicht zu bekommen.\n\nAber nicht mit mir! In mir habt Ihr Euren Meister gefunden, <Klasse>. Ich, Blutritter Antari des Schattenmondtals, kann es kaum erwarten, Euch zu zeigen, wie es sich anfühlt, im Kampf ausgelöscht zu werden.", progress = nil, completion = "Unmöglich! Ich kann nicht verlieren!", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31921] = {title = "Kampfhaustierzähmer: Scherbenwelt", objective = "Besiegt Nicki Mikrotech, Ras'an, Narrok und Morulu den Älteren in Haustierkämpfen.", description = "Ihr habt die Meisterzähmer Kalimdors und der Östlichen Königreiche bezwungen, doch Eure nächste Herausforderung wird Euch auf eine sehr viel härtere Probe stellen.\n\nIn der Scherbenwelt gibt es vier Zähmer, die Ihr jetzt besiegen müsst: Nicki Mikrotech auf der Höllenfeuerhalbinsel, Ras'an in den Zangarmarschen, Narrok in Nagrand und Morulu den Älteren in Shattrath.\n\nBesiegt sie, wenn Ihr den Pfad zu wahrer Größe beschreiten wollt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31922] = {title = "Nicki Mikrotech", objective = "Besiegt Nicki Mikrotech in einem Haustierkampf.", description = "Meinen Berechnungen zufolge habe ich eine 32,333%-ige Chance zu siegen. Ich werde sie nutzen!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31923] = {title = "Ras'an", objective = "Besiegt Ras'an in einem Haustierkampf.", description = "Ihr wollt wieder kämpfen? Ich glaube, ich bin besser geworden!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31924] = {title = "Narrok", objective = "Besiegt Narrok in einem Haustierkampf.", description = "Ich möchte noch einmal kämpfen. Diese Grünschnäbel müssen stärker werden.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31925] = {title = "Morulu der Ältere", objective = "Besiegt Morulu den Älteren in einem Haustierkampf.", description = "Seit unserem letzten Aufeinandertreffen habe ich viel gelernt. Wollt Ihr Euer Können erneut auf die Probe stellen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31926] = {title = "Großmeister Antari", objective = "Besiegt Blutritter Antari in einem Haustierkampf.", description = "Beim letzten Mal habt Ihr aus meinen Fehlern Kapital geschlagen, um den Sieg davonzutragen. Dieses Mal jedoch werdet Ihr weniger Glück haben, <Volk>.", progress = nil, completion = "Ihr seid töricht, wenn Ihr glaubt, dass Ihr mir überlegen seid. Ich werde Euch zermalmen, das schwöre ich!", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31927] = {title = "Kampfhaustierzähmer: Nordend", objective = "Besiegt Beegli Lunte, den fast kopflosen Jakob, Okrut Drachenwüste und Darmwürger in Haustierkämpfen.", description = "Die Besten der Scherbenwelt sind Euren Fertigkeiten zum Opfer gefallen, doch jetzt wartet Nordend auf Euch!\n\nVier Zähmer gilt es zu besiegen: Beegli Lunte im Heulenden Fjord, den fast kopflosen Jakob im Kristallsangwald, Okrut Drachenwüste in der Drachenöde und Darmwürger in Zul'drak.\n\nWenn Ihr über sie alle triumphiert, wird der Großmeister Nordends mit seiner Herausforderung nicht lange auf sich warten lassen!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31928] = {title = "Großmeister Payne", objective = "Besiegt Major Payne in einem Haustierkampf.", description = "Wenn Ihr mich fragt, haben meine Kollegen bei Eurer Ausbildung viel zu viel Nachsicht walten lassen.\n\nWenn man Haustiere wirklich zähmen will, ist militärische Disziplin gefordert. Ihr werdet die Ehre haben, selbst <Zeuge/Zeugin> dessen zu werden, was solche Disziplin bewirken kann.\n\nKommt zum Argentumturnierplatz in Eiskrone und seht selbst, was Ihr erreichen könntet!", progress = nil, completion = "Ich habe mich in Euch geirrt, &lt;Name&gt;. Ihr seid einer der nobelsten Gegner, gegen die ich je die Ehre hatte zu kämpfen. Aber glaubt ja nicht, dass ich Euch beim nächsten Mal auch mit dem Sieg davonkommen lasse!", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31929] = {title = "Kampfhaustierzähmer: Nordend", objective = "Besiegt Beegli Lunte, den fast kopflosen Jakob, Okrut Drachenwüste und Darmwürger in Haustierkämpfen.", description = "Die Besten der Scherbenwelt sind Euren Fertigkeiten zum Opfer gefallen, doch jetzt wartet Nordend auf Euch!\n\nVier Zähmer gilt es zu besiegen: Beegli Lunte im Heulenden Fjord, den fast kopflosen Jakob im Kristallsangwald, Okrut Drachenwüste in der Drachenöde und Darmwürger in Zul'drak.\n\nWenn Ihr über sie alle triumphiert, wird der Großmeister Nordends mit seiner Herausforderung nicht lange auf sich warten lassen!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31930] = {title = "Kampfhaustierzähmer: Pandaria", objective = "Besiegt Hyuna von den Schreinen, Bäuerin Nishi, Mo'ruk, Yon den Mutigen, Sucher Zusshi und Ödniswandler Shu in Haustierkämpfen.", description = "Jetzt müsst Ihr den zähesten Zähmern in ganz Azeroth gegenübertreten, <Name>. Sie haben sich in Pandaria niedergelassen, der Heimat der Großmeister.\n\nSechs Großmeister gibt es noch zu besiegen: Hyuna von den Schreinen im Jadewald, Bäuerin Nishi im Tal der Vier Winde, Mo'ruk in der Krasarangwildnis, den mutigen Yon am Kun-Lai-Gipfel, Sucher Zusshi in der Tonlongsteppe und Ödniswandler Shu in der Schreckensöde.\n\nWenn Ihr glaubt, dass Ihr bereit seid, stellt Euch diesen Meistern ihres Fachs und beweist Euer Können!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31931] = {title = "Beegli Lunte", objective = "Besiegt Beegli Lunte in einem Haustierkampf.", description = "Eins von meinen Hühnern ist gestern ganz kurz geflogen. Ich schwör's. Endlich kommen wir ganz groß raus!\n\nAch, Ihr wollt schon wieder kämpfen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31932] = {title = "Fast kopfloser Jakob", objective = "Besiegt den fast kopflosen Jakob in einem Haustierkampf.", description = "Ihr widersetzt Euch meiner Weisheit immer wieder. Was führt Euch in diese Wälder zurück?\n\nAch, Ihr wollt noch einmal kämpfen. Also gut.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31933] = {title = "Okrut Drachenwüste", objective = "Besiegt Okrut Drachenwüste in einem Haustierkampf.", description = "Ihr wagt es, unsere Arbeit zu unterbrechen? Dann müsst Ihr erneut gegen mich kämpfen! Holt Eure Haustiere heraus, dann werde ich Euch Höllschreis Zorn schmecken lassen!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31934] = {title = "Darmwürger", objective = "Besiegt Darmwürger in einem Haustierkampf.", description = "Ich Euch gerne bekämpfen. Ihr nicht so einfach wie andere. Wir nochmal kämpfen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31935] = {title = "Großmeister Payne", objective = "Besiegt Major Payne in einem Haustierkampf.", description = "<Dieser/Diese:c> rebellische <Klasse> ist also wieder da, um <seine/ihre> Kräfte mit denen des Großmeisters zu messen. Dieses Mal wird Eure Kühnheit Euer Verderben sein!", progress = nil, completion = "Ich applaudiere Eurer Taktik, doch ich verachte Euren Sieg. Gut gemacht, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31936] = {title = "Das Bewässerungssystem \"Jinyuprinzessin\"", objective = "Bringt das Bewässerungssystem \"Jinyuprinzessin\" zu Bauer Yoon auf dem Gehöft Sonnensang oder dem Halbhügelmarkt.\n\nBereitgestellter Gegenstand: \n", description = "<Auf der Rückseite der Kiste ist die Karikatur einer Jinyuprinzessin abgebildet, die vom folgenden Werbetext umrahmt wird:>\n\n\"Hallo, grüner Daumen! Knatschig über krass vertrocknete Kürbisse? Klagen über krustigen Kohl? Ist Euer Lauch lahm und sind Eure Melonen melancholisch?\n\nDann ist die Zeit gekommen, die Jinyuprinzessin nach Hause zu bringen! Sie wird Euren Garten wie feiner Frühlingsregen bewässern und die Dürre mit einem soliden Schluck...\"\n\n<Und so geht es sechs Absätze lang weiter.>", progress = nil, completion = "Ein Bewässerungssystem? Für den Hof? Danke, &lt;Name&gt;! Wir können es anstatt der alten Gießkanne verwenden.\n\nDie \"Jinyuprinzessin\"? Was hat es damit auf sich?\n\n\n\nNa gut, ich will es gar nicht wissen. Ich werde es sofort aufstellen lassen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31937] = {title = "Ungezieferschutz \"Donnerkönig\"", objective = "Bringt den Ungezieferschutz \"Donnerkönig\" zu Bauer Yoon auf dem Gehöft Sonnensang oder dem Halbhügelmarkt.\n\nBereitgestellter Gegenstand: \n", description = "<Das Ehrfurcht gebietende Konterfei eines Mogu prangt auf dieser Kiste; sein Blick ist auf die fein säuberlich darunter angeordneten fett gedruckten Zeilen gerichtet.>\n\n\"LASST EUCH EURE ERNTE NICHT DURCH SCHWACHE, EKEL ERREGENDE INSEKTEN VERDERBEN. WERDET IHRER DANK DER MACHT DES DONNERKÖNIGS HERR UND SCHÜTZT EUER ERBE.\"\n\n<Die übrige Fläche ist mit Karikaturen wehklagender oder verschreckt fliehender Insekten bedeckt.>", progress = nil, completion = "Schädlingsbekämpfungsmittel! Ihr seid genial, &lt;Name&gt;! Endlich müssen wir uns nicht mehr mit diesem altmodischen Insektenvernichtungsmittel abgeben.\n\n\n\nOh ja, der Donnerkönig! So habe ich mir das vorgestellt!\n\nIch werde mich sofort damit an die Arbeit machen - diese Viecher werden nicht wissen, wie ihnen geschieht!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31938] = {title = "Der \"Erdschlitzer\"-Meisterpflug", objective = "Bringt den \"Erdschlitzer\"-Meisterpflug zu Bauer Yoon auf dem Gehöft Sonnensang oder dem Halbhügelmarkt.\n\nBereitgestellter Gegenstand: \n", description = "<Auf der Kiste ist ein Pandarenbauer mit einer unglaublichen Figur abgebildet, der voller Stolz mit gespreizten Beinen über einem breiter werdenden Riss im Boden steht und einen gewaltigen Pflug umklammert. Verspielte Junge tummeln sich auf seinen Schultern und baumeln von seinen muskulösen Armen.\n\nAn seiner Seite balanciert ein stoisches weibliches Wesen - mit ebenso unglaublicher Figur - ein gigantisches überschäumendes Füllhorn anmutig auf dem Kopf, während sie einem Shed-Ling einen Tritt ins Gesicht verpasst.>\n\n\"Der Erdschlitzer. Beherrscht das Land. Beherrscht Euer Leben.\"", progress = nil, completion = "Ein Erdschlitzer-Meisterpflug! Ich... ich hätte nie gedacht, dass ich jemals einen davon in die Hände bekommen würde. Ist Euch klar, wie viel Zeit wir damit sparen werden?!\n\nIch habe gehört, wenn Ihr mit dem Erdschlitzer zwanzig Meter solides Gestein durchpflügt, bekommt Ihr eine Sandkiste und eine Vorladung von den Shado-Pan für das Auslösen einer Erdbebenwarnung!\n\nDas wird der reine WAHNSINN.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31941] = {title = "Vierundsiebzig-elf: Kürbisch Wasser", objective = "Pflanzt einen Jadekürbis auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", description = "Großvater hat oft gesagt: \"Ein Kürbis pro Woche hilft, dass man nicht roche\".\n\n<Yoon schnüffelt fast unmerklich.>\n\nJawohl. Ich glaube, es ist ungefähr eine Woche her. Würdet Ihr mir helfen einen Jadekürbis zu pflanzen?", progress = nil, completion = "Gut gepflanzt, &lt;Name&gt;.\n\nUnd jetzt warten wir ab...", rewards = "Ihr bekommt:\n\nGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31942] = {title = "Melonensaison", objective = "Pflanzt eine Streifenmelone auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", description = "<Bauer Yoon schaut gen Himmel und schnuppert die Luft.>\n\nHmm...\n\n<Er leckt sich die Pfote und hält sie in die Brise, gräbt eine Zehe in den Boden und prüft dann die Länge seines Schattens.>\n\nJa. Die Melonensaison bricht an.\n\nKönntet Ihr mir ein paar Samen besorgen, damit ich Streifenmelonen anbauen kann?", progress = "Beeilt Euch! Die Melonensaison dauert nicht ewig!", completion = "Das war knapp. Fast hätten wir die Melonensaison verpasst.", rewards = "Ihr bekommt:\n\nGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31943] = {title = "Häh? Beeren? Hexenbeeren.", objective = "Pflanzt Hexenbeeren auf dem Gehöft Sonnensang an. Ihr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben.", description = "Der Junge dort drüben, Andi, wird irgendwann zu einem tollen Bauern heranwachsen. Das sehe ich auf einen Blick.\n\nIch glaube, ich werde ein paar Hexenbeeren für ihn pflanzen. Kinder lieben Hexenbeeren. Das wird eine nette Überraschung.", progress = "Das Geheimnis einer guten Hexenbeerenernte besteht darin zu warten, bis sie süß sind.\n\nDas ist nicht so einfach wie es klingt. Ich kann mich erinnern, wie ich als Kind bei Hexenbeeren, die noch nicht einmal halb reif waren, das Gesicht verzogen habe, weil ich zu ungeduldig war und einfach nicht auf meinen Opa hören wollte.", completion = "Hurra, Hexenbeeren! Ich kann es gar nicht erwarten!\n\nMuss ich aber.", rewards = "Ihr bekommt:\n\nGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31944] = {title = "Die Ausbildung abschließen: Die letzte Prüfung", objective = "Begebt Euch zum Ausbildungsgelände am Gipfel der Ruhe und legt Eure letzte Prüfung ab.", description = "Willkommen zurück, <Name>. Die Zeit ist gekommen, die letzte Phase Eurer Ausbildung zu absolvieren. Auf zum Ausbildungsgelände, damit Ihr Eure letzte Prüfung ablegen könnt.", progress = nil, completion = "Gute Arbeit, &lt;Name&gt;. Eure Ausbildung ist nun abgeschlossen. Kommt gerne auch in Zukunft wieder, um Eure Kräfte mit den Meistern hier zu messen und zu üben, was Ihr gelernt habt.", rewards = "Stab des KranichtänzersStab des weißen TigerfürstenStab des OchsenhufdonnersIhr erlernt:\n\nErleuchtung\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][31945] = {title = "Lernen und Wachsen VI: Ginas Stimme", objective = "Pflanzt 1 Frühlingszwiebel, erntet sie und bringt dann 5 Frühlingszwiebeln zu Gina Lehmkrall.\n\nFrühlingszwiebelsamen gibt es beim Händler Grünfeld auf dem Halbhügelmarkt zu kaufen. Nachdem Ihr Eure Pflanzen gepflanzt und gehegt habt, müsst Ihr bis zum nächsten Tag warten, um reife Frühlingszwiebeln ernten zu können.", description = "Mein Geschäft ist dem Untergang geweiht! Seht Ihr all die Eisentatzen an ihren Kochstellen?\n\nIhre leckeren Gerichte locken viel Kundschaft zu diesem Markt, jetzt sind ihnen aber die Frühlingszwiebeln ausgegangen!\n\nSo unscheinbar sie sein mögen, Frühlingszwiebeln sind eine unentbehrliche Zutat beim Kochen. Ohne sie sind Gerichte weniger pikant, haben weniger Geschmack und weniger Aroma.\n\nEs ist eine Katastrophe. Und die nächste Lieferung Frühlingszwiebeln kommt erst nächste Woche!\n\nMoment mal. Ihr seid doch <Bauer/Bäuerin>, oder? Könnt Ihr mir vielleicht helfen?", progress = "Überseht die Frühlingszwiebel nicht. Sie mag klein und unscheinbar sein, doch sie schmeckt wahrlich phänomenal.", completion = "Ich fasse es nicht! Ich habe zwar schon größere Frühlingszwiebeln gesehen, die hier reichen aber völlig. Ihr habt gerade unsere Haut gerettet, &lt;Name&gt;!", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nGina Lehmkrall beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][31946] = {title = "Mung-Mungs Stimme III: Die große Karottenkomödie", objective = "Pflanzt 2 saftigleckere Karotten, erntet sie und bringt dann 10 saftigleckere Karotten zu Mung-Mung.\n\nSaftigleckere Karottensamen gibt es beim Händler Grünfeld auf dem Halbhügelmarkt zu kaufen. Nachdem Ihr Eure Pflanzen gepflanzt und gehegt habt, müsst Ihr bis zum nächsten Tag warten, um reife saftigleckere Karotten ernten zu können.", description = "Mung-Mung ist egal, wer Karotten stiehlt. Kümmert ihn nur, was Herr Lehmkrall armem Mung-Mung antut, wenn er sieht, dass seine Ernte ruiniert ist!\n\n<Mung-Mung kratzt sich gedankenverloren am Kinn.>\n\nHalt! Mung-Mung hat schlaue Idee. Geh und zieh wachsende saftigleckere Karotten. Dann nehmen wir Karotten und tun so, als wären es die von Herrn Lehmkrall.\n\nJawohl!", progress = "Shed-Ling lieben Karotten, aber sie hassen Rüben. Ich hasse Rüben auch.", completion = "Boah, diese Karotten sehen knackig und saftig aus, &lt;Name&gt;! Mung-Mung hatte keine Ahnung, dass du so einen grünen Daumen hast.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31947] = {title = "Bauer Fungs Stimme III: Zum Wohl mit Kohl", objective = "Pflanzt und erntet 3 Grünkohle und bringt dann 15 Grünkohle zu Bauer Fung.\n\nIhr könnt die Samen von Händler Grünfeld auf dem Halbhügelmarkt erwerben. Nach dem Beackern und Pflegen Eurer Pflanze müsst Ihr bis zum nächsten Tag warten, um den reifen Grünkohl zu ernten.", description = "<Bauer Fung strahlt mit einem breiten Lächeln.>\n\nDank Euch habe ich meine kostbaren Yaks wieder! Leider musste ich feststellen, dass die Zeit in freier Wildbahn sie sehr ausgezehrt hat.\n\nAuch, wenn sie ganz ausgehungert sein müssen, kann ich nicht einfach gewöhnliches Gras an meine preisgekrönten Yaks verfüttern.\n\nNicht doch - sie fressen ausschließlich den üppigsten Grünkohl, der hier im Tal gedeiht.\n\nMeine Bestände gehen zur Neige. Wenn Ihr mir etwas Grünkohl für meine Yaks bringen könntet, werde ich Euch fürstlich belohnen.", progress = "Ich habe Kosenamen für all meine Yaks. Da gibt es Pelzi, und Wolly; Flauschie und Kuschli und...", completion = "Ich habe Kohl erwartet, aber keinen Kohl dieser Güteklasse! Grundgütiger!\n\nPerfekte runde Form; große, speckige Blätter; herrlich changierende smaragdgrüne Farbe...\n\n&lt;Bauer Fung beißt herzhaft in den Kohl.&gt;\n\nMmm, und dieser süße, frische Geschmack! Das ist ein herrlicher Kohl, &lt;Name&gt;. Meine Yaks werden diesen Leckerbissen zu schätzen wissen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31948] = {title = "Nanas Stimme II: Die Heiligen Quellen", objective = "Benutzt den leeren Krug am Goldfächer, um tausend Jahre altes Wasser zu sammeln.", description = "Ihr kommt genau richtig, <Name>. Ich will unbedingt frischen Hexenbeeren-Julep machen.\n\nHabt Ihr schon einmal von diesem wundersamen Gebräu gehört?\n\nJeder einzelne Schluck verjüngt Euer Gesicht um zehn Jahre! Was glaubt Ihr, warum ich noch so gut aussehe?\n\nWie dem auch sei, ich brauche eine besondere Zutat - tausend Jahre altes Wasser -, das an der Mündung des Wasserfalls im Norden besorgt werden kann.\n\nIch fürchte, für eine alte Dame wie mich ist die Reise zu beschwerlich, wenn Ihr allerdings einen Krug in die Hände bekommt, werde ich mein Gebräu mit Euch teilen.", progress = "Das Wasser in diesem Tal stammt aus dem Tal der Ewigen Blüten im Norden. Angeblich hat das Wasser hier wundersame, magische Eigenschaften.", completion = "Ihr habt die Fälle also gefunden? Oh ja, ich sehe, dass Ihr das Wasser gefunden habt. Großartig!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31949] = {title = "Nanas Stimme III: Hexenbeeren-Julep", objective = "Pflanzt 3 Hexenbeeren, erntet sie und bringt dann 15 Hexenbeeren zu Nana Lehmkrall.\n\nHexenbeerensamen gibt es beim Händler Grünfeld auf dem Halbhügelmarkt zu kaufen. Nachdem Ihr Eure Pflanzen gepflanzt und gehegt habt, müsst Ihr bis zum nächsten Tag warten, um reife Hexenbeeren ernten zu können.", description = "Jetzt, wo ich das Wasser habe, kann ich den eiskalten Hexenbeeren-Julep fast schon schmecken!\n\nJetzt müssen wir nur noch ein paar süße Hexenbeeren finden.\n\nDie Beeren meines Enkels waren dieses Jahr völlig unbrauchbar, deshalb muss ich anderswo nach einer vernünftigen Ernte suchen.\n\nIhr habt dieses Jahr nicht zufällig Hexenbeeren angebaut? Wie wär's denn, wenn Ihr mir welche von Eurem Hof bringen würdet?\n\nWenn Eure Beeren den Anforderungen entsprechen, stellen wir eine ganze Ladung von dem alten Gesöff her!", progress = "Beeilt Euch gefälligst! Ich bin eine alte Frau. Mir bleibt nicht viel Zeit und ich möchte die Soße noch einmal kosten, bevor ich abkratze!", completion = "&lt;Nana Lehmkrall prüft eine dunkle Hexenbeere eingehend und steckt sie dann in den Mund. Ihr Gesicht erhellt sich.&gt;\n\nDas Land lebt! Ich habe schon seit Jahren keine Hexenbeere mehr gegessen, die so süß und saftig war! Der einzige, der solche Beeren angebaut hat, war... der alte Yoon, der Großvater Eures Freundes.\n\n&lt;Nana Lehmkrall wird rot.&gt;\n\nOh, der Mann war vielleicht ein Schlingel! Ich kann mich noch an die Sommertage erinnern, als wir jung und unbeschwert waren und diese Beeren scheffelweise gegessen haben.\n\nDanke, dass Ihr mich an einen alten Freund erinnert habt, &lt;Name&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31951] = {title = "Großmeisterin Aki", objective = "Besiegt Aki die Auserwählte in einem Haustierkampf.", description = "Ihr habt Euch gegen die Lehrer von Azeroth gut geschlagen. Selbst die Großmeister sind Eurer raffinierten Taktik zum Opfer gefallen.\n\nIch erwarte Euch jetzt im Tal der Ewigen Blüten, denn Ihr habt Euch das Privileg verdient, im Kampf gegen mich anzutreten. Los, <Name>, zeigt, ob Ihr das Zeug habt, mich zu bezwingen.", progress = nil, completion = "Ihr habt gesiegt. Setzt Eure Ausbildung fort und sucht bei anderen Lehrern wie Euch selbst nach Herausforderungen. Die Reise geht nie wirklich zu Ende.", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31952] = {title = "Kampfhaustierzähmer: Pandaria", objective = "Besiegt Hyuna von den Schreinen, Bäuerin Nishi, Mo'ruk, Yon den Mutigen, Sucher Zusshi und Ödniswandler Shu in Haustierkämpfen.", description = "Jetzt müsst Ihr den zähesten Zähmern in ganz Azeroth gegenübertreten, <Name>. Sie haben sich in Pandaria niedergelassen, der Heimat der Großmeister.\n\nSechs Großmeister gibt es noch zu besiegen: Hyuna von den Schreinen im Jadewald, Bäuerin Nishi im Tal der Vier Winde, Mo'ruk in der Krasarangwildnis, den mutigen Yon am Kun-Lai-Gipfel, Sucher Zusshi in der Tonlongsteppe und Ödniswandler Shu in der Schreckensöde.\n\nWenn Ihr glaubt, dass Ihr bereit seid, stellt Euch diesen Meistern ihres Fachs und beweist Euer Können!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31953] = {title = "Großmeisterin Hyuna", objective = "Besiegt Hyuna von den Schreinen in einem Haustierkampf.", description = "Ihr möchtet erneut einen Kampf wagen? Nun gut. Er wird mich stärker machen, damit ich die geheiligten Stätten meines Volkes noch besser schützen kann.", progress = nil, completion = "Ihr seid wahrlich stark. Werdet Ihr Eure Fertigkeiten meinen Bemühungen verschreiben?", rewards = "Ihr bekommt:\n\nBeutel mit HaustierbedarfTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31954] = {title = "Großmeister Mo'ruk", objective = "Besiegt Mo'ruk in einem Haustierkampf.", description = "Diesmal bin ich mit Gewinnen an der Reihe! Wartet's bloß ab!", progress = nil, completion = "Nächstes Mal verliert Ihr. Ich werd Euch schlagen!", rewards = "Ihr bekommt:\n\nBeutel mit HaustierbedarfTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31955] = {title = "Großmeisterin Nishi", objective = "Besiegt Bäuerin Nishi in einem Haustierkampf.", description = "Die Stärke meiner Haustiere nimmt dank des fruchtbaren Landes, auf dem wir trainieren, immer weiter zu. Ihr habt keine Chance!", progress = nil, completion = "Wow! Ich habe wohl nicht alleine trainiert!", rewards = "Ihr bekommt:\n\nBeutel mit HaustierbedarfGeringes Amulett des GlücksTapferkeitspunkte"}
MultiLanguageQuestData['de'][31956] = {title = "Großmeister Yon", objective = "Besiegt Yon den Mutigen in einem Haustierkampf.", description = "Wenn Ihr glaubt, dass ich Euch einfach so mit einem anderen Sieg davonkommen lasse, seid Ihr auf dem Holzweg. Dieses Mal werde ich mich als der bessere Trainer erweisen!", progress = nil, completion = "Schön. Ihr siegt also noch einmal. Jetzt ab mit Euch, ich habe vor unserem nächsten Zusammentreffen einiges an Vorbereitungen zu treffen.", rewards = "Ihr bekommt:\n\nBeutel mit HaustierbedarfTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31957] = {title = "Großmeister Shu", objective = "Besiegt Ödniswandler Shu in einem Haustierkampf.", description = "Ihr wagt Euch also erneut in die Tiefen der Wüste vor, um Euch mir zu stellen - nur werdet Ihr dieses Mal durch die Hand eines wahren Großmeisters zu Boden gestreckt werden. Edelmütig, aber töricht.", progress = nil, completion = "In all meinen Jahren als Großmeister habe ich noch nie jemandem mit Eurer Entschlossenheit gegenübergestanden. Die anderen hatten recht, was Euch angeht. Ihr seid eine Größe, mit der man rechnen muss.", rewards = "Ihr bekommt:\n\nBeutel mit HaustierbedarfGeringes Amulett des GlücksTapferkeitspunkte"}
MultiLanguageQuestData['de'][31958] = {title = "Großmeisterin Aki", objective = "Besiegt Aki die Auserwählte in einem Haustierkampf.", description = "Ihr wollt Euch erneut an mir messen? Nun gut, lasst uns kämpfen.", progress = nil, completion = "Ihr seid stärker und Eure Fertigkeiten sind besser ausgeprägt. Eure Reise geht weiter.", rewards = "Ihr bekommt:\n\nBeutel mit HaustierbedarfTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][31959] = {title = "Der Trick der Kaiserin", objective = "Meldet Euch bei Malik dem Unversehrten vor dem Herzen der Angst.", description = "Großkaiserin Shek'zeer hat endgültig ihre Geduld mit uns verloren. Wir haben soeben erfahren, dass eine gewaltige Armee sich in den Schatten des Herzens der Angst zusammenzieht, mit dem Befehl, Klaxxi'vess zu vernichten.\n\nWir haben Glück gehabt, dass wir so lange ausgehalten haben, aber gegen eine Belagerung dieses Ausmaßes können wir nichts ausrichten.\n\n<Erwecker/Erweckerin>, Ihr wart von unschätzbarem Wert für uns. Geht, nehmt Euren Platz auf dem Schlachtfeld neben den Getreuen ein.\n\nIch sehe Euch dann auf dem Schlachtfeld!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31966] = {title = "Kampfhaustierzähmer: Cataclysm", objective = "Besiegt Brok, Bordin Ruhigfaust und Goz Unheilsfuror in Haustierkämpfen.", description = "Ihr habt die besten Zähmer von Nordend bezwungen, doch bevor Ihr es mit den Großmeistern Pandarias aufnehmen könnt, bedarf es weiterer Vorbereitungen. Macht Euch bereit und perfektioniert Eure Fertigkeiten weiter, indem Ihr folgende Zähmer besiegt: Brok in Hyjal, Bordin Ruhigfaust in Tiefenheim und Goz Unheilsfuror im Schattenhochland.\n\nWenn Ihr über sie triumphiert, seid Ihr bereit, die Reise nach Pandaria und Eurer ultimativen Herausforderung entgegen anzutreten.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31967] = {title = "Kampfhaustierzähmer: Cataclysm", objective = "Besiegt Brok, Bordin Ruhigfaust und Goz Unheilsfuror in Haustierkämpfen.", description = "Nordend hat sich Euch beugen müssen, doch noch seid Ihr nicht bereit, es mit den Großmeistern Pandarias aufzunehmen. Bezwingt folgende Zähmer, um Euren Willen für die vor Euch liegenden Herausforderungen zu stählen: Brok in Hyjal, Bordin Ruhigfaust in Tiefenheim und Goz Unheilsfuror im Schattenhochland.\n\nErst wenn Ihr sie bezwungen habt, seid Ihr bereit, nach Pandaria aufzubrechen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31970] = {title = "Großmeister Obalis", objective = "Besiegt Obalis in einem Haustierkampf.", description = "Ihr glaubt, Ihr seid bereit, Pandaria herauszufordern? Ihr glaubt wirklich, dass Ihr die mächtigsten Zähmer ganz Azeroths bezwingen könnt?\n\nÜberlasst das Urteil darüber nur mir, <Volk>. Stellt Euch mir auf dem Vir'naaldamm in Uldum, und es wird sich zeigen, ob Ihr wirklich bereit seid.", progress = nil, completion = "Ich wurde eines Besseren belehrt. Ihr seid bereit, Euch meinen Meistern zu stellen.", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31971] = {title = "Großmeister Obalis", objective = "Besiegt Obalis in einem Haustierkampf.", description = "Siehe da - <der triumphierende Zähmer/die triumphierende Zähmerin> will <seine/ihre> Kräfte mit den meinen messen. So sei es. Ich nehme die Herausforderung an.", progress = nil, completion = "Durch jede meiner Niederlagen gewinne ich an Stärke. Nehmt Euch bei unserer nächsten Begegnung lieber in Acht.", rewards = "Ihr bekommt:\n\nBeutel mit Haustierbedarf"}
MultiLanguageQuestData['de'][31972] = {title = "Brok", objective = "Besiegt Brok in einem Haustierkampf.", description = "Noch verstehe ich die Not dieser Geschöpfe nicht genug, um ihnen angemessen Hilfe leisten zu können. Ob ein weiterer Kampf unseren Bund wohl stärken könnte?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31973] = {title = "Bordin Ruhigfaust", objective = "Besiegt Bordin Ruhigfaust in einem Haustierkampf.", description = "Die Eingeborenen haben mich die Kraft der Erde gelehrt. Ich weiß um ihre unerschöpfliche Beständigkeit. Lasst uns ein Mal mehr kämpfen, und Ihr werdet sehen, dass ich zäher bin als je zuvor!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31974] = {title = "Goz Unheilsfuror", objective = "Besiegt Goz Unheilsfuror in einem Haustierkampf.", description = "Die Macht des Zwielichts durchdringt mich. Ich bin ein Gott! Ihr habt keine Chance, mich zu besiegen!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31975] = {title = "Die Rückkehr des Champions", objective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", description = "Wenn Ihr mich fragt, gehört Ihr in die Scherbenwelt, zusammen mit den anderen Hitzköpfen. Warum geht Ihr nicht wieder zu Marlene Trichdie in Sturmwind und findet heraus, was Eure neue Karriere als <Zähmer/Zähmerin> als Nächstes bereithält?", progress = nil, completion = "Dann wollen wir sehen... wohin wir Euch als Nächstes senden...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31976] = {title = "Die Rückkehr des Champions", objective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", description = "Die Kunde von Eurem Können verbreitet sich. Ich schlage vor, Ihr kehrt für weitere Unterweisung zu Eurer Trainerin Marlene Trichdie zurück.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31977] = {title = "Die Rückkehr des Champions", objective = "Meldet Euch bei Varzok in Orgrimmar.", description = "Wenn Ihr mich fragt, gehört Ihr in die Scherbenwelt, zusammen mit den anderen Hitzköpfen. Warum kehrt Ihr nicht zu Varzok in Orgrimmar zurück und findet heraus, was Eure neue Karriere als <Zähmer/Zähmerin> als Nächstes bereithält?", progress = nil, completion = "Ich habe Eure nächsten Herausforderungen vorbereitet, &lt;Name&gt;. Zeigt uns, ob Ihr auf sie vorbereitet seid...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31978] = {title = "Prioritäten!", objective = "Findet 6 Fässer mit Honigbräu auf der Honigtaulichtung.", description = "Seht Euch bloß diese Sauerei an! Das ganze Bräu ist verdorben!\n\nTaran Zhu hat uns davor gewarnt mit Euch Außenseitern zu sprechen, ich nehme aber jede Hilfe an, die ich bekommen kann.\n\nWir waren nach Morgenblüte unterwegs, um unser Bräu abzuliefern, als der Kampf ausbrach. Und jetzt ist unser ganzes Bräu dahin!\n\nWollt Ihr es wiedergutmachen? Vielleicht findet Ihr ja ein paar Fässer mit Honigbräu, die nicht kaputt sind. Dann wäre nicht alles verloren.", progress = nil, completion = "Es ist nicht so viel wie ich gehofft hatte, doch es wird schon reichen. Hat wohl keinen Sinn, verschüttetem Bräu nachzutrauern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31980] = {title = "Die Rückkehr des Champions", objective = "Meldet Euch bei Varzok in Orgrimmar.", description = "Die Kunde von Eurem Können verbreitet sich. Ich schlage vor, Ihr kehrt für weitere Unterweisung zu Eurem Trainer Varzok zurück.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31981] = {title = "Übertroffene Erwartungen", objective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", description = "Ab mit Euch zu Eurer Trainerin Marlene Trichdie in Sturmwind. Vielleicht hat sie ein paar... lohnende... Herausforderungen in petto für Euch.", progress = nil, completion = "Ihr habt wirklich Großmeister Antari bezwungen? Wow! Ich werde ein paar wirklich hartgesottene Zähmer finden müssen, die es mit Euch aufnehmen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31982] = {title = "Übertroffene Erwartungen", objective = "Meldet Euch bei Varzok in Orgrimmar.", description = "Ab mit Euch zu Eurem Trainer Varzok in Orgrimmar. Vielleicht hat er ein paar... lohnende... Herausforderungen in petto für Euch.", progress = nil, completion = "Es gibt nur einen Ort, an dem Eure nächste Prüfung stattfinden könnte.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31983] = {title = "Ein kurzer Aufschub", objective = "Meldet Euch bei Varzok in Orgrimmar.", description = "Nicht schlecht, wenn man bedenkt, dass Ihr <ein/eine:r> <Volk> seid. Und jetzt zurück nach Orgrimmar. Sprecht mit diesem Grobian Varzok. Hoffentlich schickt er Euch an irgendeinen Ort, der sich möglichst weit von meiner Familie entfernt befindet.", progress = nil, completion = "Ich glaube, ich weiß, was Ihr als Nächstes unternehmen solltet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31984] = {title = "Ein kurzer Aufschub", objective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", description = "Gute Arbeit, wirklich gute Arbeit! Könntet Ihr wohl Fräulein Marlene Trichdie in Sturmwind darüber berichten?\n\nOh, und bestellt Ihr schöne Grüße von mir. Eine schöne junge Dame wie sie könnte von der Begleitung eines erfahrenen Kämpfers wie mir wirklich profitieren.", progress = nil, completion = "Payne hat Euch gebeten, Euch für ihn an mich heranzumachen, stimmt's? Wann begreift er es endlich?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31985] = {title = "Die triumphale Rückkehr", objective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", description = "Ihr seid jetzt so vorbereitet, wie Eure Trainerin das wollte. Kehrt nach Sturmwind zurück und sprecht mit Marlene Trichdie. Sie wird Euch weiter unterweisen.", progress = nil, completion = "Ihr habt also Obalis kennengelernt? Unter seiner rauen Schale ist er ein toller Bursche.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31986] = {title = "Die triumphale Rückkehr", objective = "Meldet Euch bei Varzok in Orgrimmar.", description = "Ihr seid jetzt so vorbereitet, wie Euer Trainer das wollte. Kehrt nach Orgrimmar zurück und sprecht mit Varzok. Er wird Euch weiter unterweisen.", progress = nil, completion = "Ihr seid jetzt auf eine echte Prüfung Eures Könnens im Kampf vorbereitet. Seid Ihr soweit?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][31987] = {title = "Theramore", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKriegsbeute von TheramoreGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][31988] = {title = "Tägliche Szenarioauswahl", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][31989] = {title = "Der Gipfel der Ruhe - Schließt Eure Ausbildung ab", objective = "Reist mithilfe der Zenpilgerfahrt zum Gipfel der Ruhe. Sprecht bei Eurer Ankunft mit Meister Hight am Schrein des Ochsen.", description = "Es ist Zeit, dass Ihr zum Gipfel der Ruhe zurückkehrt, um Eure Ausbildung abzuschließen. Kehrt mithilfe der Zenpilgerfahrt dorthin zurück und sprecht bei Eurer Ankunft mit Meister Hight.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][31991] = {title = "Großmeister Zusshi", objective = "Besiegt Sucher Zusshi in einem Haustierkampf.", description = "Ich wusste, dass Ihr zurückkommen würdet, um noch einmal gegen mich anzutreten. Dann wollen wir sehen, wer im Kampf weiser ist.", progress = nil, completion = "Ihr seid tatsächlich überlegen. Wenn Ihr mich entschuldigen würdet - ich muss den See um Rat zu meiner Niederlage bitten.", rewards = "Ihr bekommt:\n\nBeutel mit HaustierbedarfGeringes Amulett des GlücksTapferkeitspunkte"}
MultiLanguageQuestData['de'][31998] = {title = "Eine würdige Herausforderung: Sha des Zweifels", objective = "Schließt den Tempel der Jadeschlange im Herausforderungsmodus ab.", description = "<Name>, Ihr müsst eine beherzte Gruppe zusammenstellen und sie in den Tempel der Jadeschlange führen. Aktiviert die Kugel des Herausforderers und vernichtet das Sha des Zweifels.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][31999] = {title = "Nazgrims Befehl", objective = "Meldet Euch bei General Nazgrim auf dem Starkarmflugplatz im Jadewald.", description = "Ihr habt hier eine schöne Basis. Von der Allianz ist weit und breit nichts zu sehen, und dazu habt Ihr noch einige Veteranen der Horde zur Seite. Ich würde sagen, es ist an der Zeit, diesen Kontinent rot zu färben.\n\nGeneral Nazgrim wird wissen, wie unser erster Schritt aussieht.", progress = nil, completion = "Wir mögen zwar die Schlacht gegen die Allianz gewonnen haben, aber das bringt uns mit den ganzen Plapperaffen in unserem Gebiet auch nicht weiter.\n\nDie Ho-zen sind unser nächstes Ziel.", rewards = "Lederhelm des FriedensbrechersRingpanzerhelm des FriedensbrechersBalghelm des FriedensbrechersSatingugel des FriedensbrechersSeidene Gugel des FriedensbrechersKettenhelm des FriedensbrechersBrünierte Kopfbedeckung des FriedensbrechersGepanzerter Helm des FriedensbrechersSchwerer Helm des FriedensbrechersIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][32000] = {title = "Eine würdige Herausforderung: Yan-Zhu der Dekantierte", objective = "Schließt die Brauerei Sturmbräu im Herausforderungsmodus ab.", description = "<Name>, Ihr müsst eine beherzte Gruppe zusammenstellen und sie in die Brauerei Sturmbräu führen. Aktiviert die Kugel des Herausforderers und helft Yan-Zhu dem Dekantierten, sich zu verdünnisieren.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][32001] = {title = "Eine würdige Herausforderung: Sha des Hasses", objective = "Schließt das Shado-Pan-Kloster im Herausforderungsmodus ab.", description = "<Name>, Ihr müsst eine abgeklärte Gruppe zusammenstellen und sie ins Shado-Pan-Kloster führen. Aktiviert die Kugel des Herausforderers und rettet Taran Zhu vor dem Sha des Hasses.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][32002] = {title = "Eine würdige Herausforderung: Xin der Waffenmeister", objective = "Schließt den Mogu'shanpalast im Herausforderungsmodus ab.", description = "<Name>, Ihr müsst eine geschickte Gruppe zusammenstellen und sie in den Mogu'shanpalast führen. Aktiviert die Kugel des Herausforderers und bereitet Xin dem Waffenmeister ein Ende.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][32003] = {title = "Eine würdige Herausforderung: Raigonn", objective = "Schließt das Tor der Untergehenden Sonne im Herausforderungsmodus ab.", description = "<Name>, Ihr müsst eine entschlossene Gruppe zusammenstellen und sie zum Tor der Untergehenden Sonne führen. Aktiviert die Kugel des Herausforderers und vernichtet Raigonn.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][32004] = {title = "Eine würdige Herausforderung: Schwadronsführer Ner'onok", objective = "Schließt den Niuzaotempel im Herausforderungsmodus ab.", description = "<Name>, Ihr müsst eine scharfsichtige Gruppe zusammenstellen und sie zur Belagerung des Niuzaotempels führen. Aktiviert die Kugel des Herausforderers und bringt Schwadronsführer Ner'onok zu Boden.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][32005] = {title = "Eine würdige Herausforderung: Durand", objective = "Schließt das Scharlachrote Kloster im Herausforderungsmodus ab.", description = "<Name>, Ihr müsst eine tapfere Gruppe zusammenstellen und sie in das Scharlachrote Kloster führen. Aktiviert die Kugel des Herausforderers und zerschmettert Durand mit gerechtem Zorn.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][32006] = {title = "Eine würdige Herausforderung: Flammenwirker Koegler", objective = "Schließt die Scharlachroten Hallen im Herausforderungsmodus ab.", description = "<Name>, Ihr müsst eine gewitzte Gruppe zusammenstellen und sie in die Tiefen der Scharlachroten Hallen führen. Aktiviert die Kugel des Herausforderers und setzt dem bücherverbrennenden Treiben von Flammenwirker Koegler ein Ende.", progress = nil, completion = "Hervorragende Leistung, &lt;Name&gt;. Allein der Gedanke daran, wie er die schöne Bibliothek niederbrennt, jagt mir einen kalten Schauer den Rücken hinab. Eure Freunde werden beeindruckt sein, wie schnell Ihr ihn ausgeschaltet habt.", rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][32007] = {title = "Eine würdige Herausforderung: Dunkelmeister Gandling", objective = "Schließt Scholomance im Herausforderungsmodus ab.", description = "<Name>, Ihr müsst eine furchtlose Gruppe zusammenstellen und sie in die Tiefen von Scholomance führen. Aktiviert die Kugel des Herausforderers und reinigt Scholomance von der finsteren Präsenz von Dunkelmeister Gandling.\n\nKehrt zu mir zurück, wenn Ihr diese Herausforderung bestanden habt, und ich werde Euch fürstlich belohnen.", progress = nil, completion = "&lt;Name&gt;, Ihr habt uns einen großen Dienst erwiesen. Hoffen wir, dass die Gebeine der Toten endlich in Frieden ruhen können, nun, da Gandling sie nicht mehr stören wird.", rewards = "Ihr bekommt:\n\nTapferkeitspunkte"}
MultiLanguageQuestData['de'][32008] = {title = "Marlene Trichdie", objective = "Meldet Euch bei Marlene Trichdie in Sturmwind.", description = "Seid gegrüßt, <Name>! Ich bin Marlene Trichdie. Man hört in letzter Zeit ziemlich viel von Euch. Ihr scheint zu <einem hervorragenden Zähmer/einer hervorragenden Zähmerin> heranzureifen!\n\nIhr solltet Euch mit mir in Sturmwind auf ein Gespräch treffen. Ich stehe mit den besten Zähmern in ganz Azeroth in Verbindung und kann Euch helfen, noch besser zu werden!", progress = nil, completion = "Ach, Ihr seid &lt;Name&gt;. Wunderbar! Dann machen wir uns gleich an die Arbeit, ja?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32009] = {title = "Varzok", objective = "Meldet Euch bei Varzok in Orgrimmar.", description = "Lok'tar, <Name>. Mein Name ist Varzok, und ich habe in letzter Zeit viel von Euren Leistungen als <Zähmer/Zähmerin> gehört. Ich möchte Euch gerne Trainern in ganz Azeroth vorstellen, damit Ihr Eure Fertigkeiten weiter verbessern könnt.\n\nBitte trefft Euch auf ein Gespräch mit mir in Orgrimmar, auf dass wir alles in die Wege leiten können.", progress = nil, completion = "Ihr müsst &lt;Name&gt; sein. Schön, Eure Bekanntschaft zu machen. Ich bin Varzok.\n\nIch werde von nun an Eure Kontaktperson sein.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32010] = {title = "Eine himmlische Aufgabe", objective = "Einen respektvollen Ruf beim Goldenen Lotus erlangt.", description = "Kennt Ihr die Himmlischen Erhabenen? Yu'lon, Chi-Ji, Xuen und Niuzao wachen über die vier Regionen Pandarias.\n\nAuch über Euch.\n\nIhr Wissen ist uralt und von großer Macht. Jenen, die sie für würdig erachten, vermögen sie ungeheure Macht zu verleihen.\n\nIhr mögt danach streben, ihr Vertrauen zu gewinnen, doch sie brauchen Euch für eine weitaus wichtigere Aufgabe.\n\nDas Tal der ewigen Blüten ist in Gefahr. Zuerst müssen wir es verteidigen. Dann richten wir unseren Blick auf die Himmlischen selbst.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32011] = {title = "Eine himmlische Aufgabe", objective = "Einen respektvollen Ruf beim Goldenen Lotus erlangt.", description = "Kennt Ihr die Himmlischen Erhabenen? Yu'lon, Chi-Ji, Xuen und Niuzao wachen über die vier Regionen Pandarias.\n\nAuch über Euch.\n\nIhr Wissen ist uralt und von großer Macht. Jenen, die sie für würdig erachten, vermögen sie ungeheure Macht zu verleihen.\n\nIhr mögt danach streben, ihr Vertrauen zu gewinnen, doch sie brauchen Euch für eine weitaus wichtigere Aufgabe.\n\nDas Tal der Ewigen Blüten ist in Gefahr. Zuerst müssen wir es verteidigen. Dann richten wir unseren Blick auf die Himmlischen selbst.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32016] = {title = "Ehrwürdige Amulette des Glücks", objective = "Sammelt 50 geringe Amulette des Glücks.", description = "Seid gegrüßt, <Name>. Ich habe die große Ehre, Euch eine hervorragende Geschäftsmöglichkeit präsentieren zu dürfen. Über viele Jahrhunderte hinweg haben wir eine Methode entwickelt, mit der die Gesetze des Glücks ausgehebelt werden können. Mit einem ehrwürdigen Amulett des Glücks werden wertvolle Artefakte sehr viel häufiger in Euren Besitz gelangen.", progress = "Mögen diese Talismane Euch Glück bringen, <Name>.", completion = "Mögen die Sterne mit einem Lächeln auf Euch herabblicken, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWährung hinzufügen\n\nIhr bekommt:\n\nEhrwürdiges Amulett des Glücks"}
MultiLanguageQuestData['de'][32017] = {title = "Ehrwürdige Amulette des Glücks", objective = "Sammelt 50 geringe Amulette des Glücks.", description = "Seid gegrüßt, <Name>. Ich habe die große Ehre, Euch eine hervorragende Geschäftsmöglichkeit präsentieren zu dürfen. Über viele Jahrhunderte hinweg haben wir eine Methode entwickelt, mit der die Gesetze des Glücks ausgehebelt werden können. Mit einem ehrwürdigen Amulett des Glücks werden wertvolle Artefakte sehr viel häufiger in Euren Besitz gelangen.", progress = "Mögen diese Talismane Euch Glück bringen, <Name>.", completion = "Mögen die Sterne mit einem Lächeln auf Euch herabblicken, &lt;Name&gt;.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nWährung hinzufügen\n\nIhr bekommt:\n\nEhrwürdiges Amulett des Glücks"}
MultiLanguageQuestData['de'][32018] = {title = "Sein Name war Sturmbräu", objective = "Sprecht mit Chen Sturmbräu auf den Donnerfußfeldern im Tal der Vier Winde.", description = "Ein außergewöhnlicher Pandaren machte vor einigen Tagen Zwischenstation in der Stadt. Er erzählte bessere Geschichten als Pan, trank doppelt so viel wie Li und hat mich zum Abschluss noch vor der Taverne verprügelt. Und nebenher hat sich seine kleine Nichte über uns lustig gemacht.\n\nEs war einfach toll.\n\nSie sagten, dass sie ins Tal der Vier Winde reisen wollten. Ihr solltet ihn kennenlernen! Hütet Euch nur vor seinem rechten Haken.", progress = nil, completion = "Ha ha! Bolo hat Euch geschickt? Der \"Fassflüsterer\", stimmt's? Aus dem Betrunkenen Ho-zen?\n\nWie geht es seinem Auge? Und ist sein Freund immer noch verkatert?\n\nAch, das war mal ein schöner Abend.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32019] = {title = "Sie nennen ihn Sturmbräu", objective = "Sprecht mit Chen Sturmbräu auf den Donnerfußfeldern im Tal der Vier Winde.", description = "Die Lage war nicht immer so, <Volk>. Oh nein, sie war sogar noch viel schlimmer. Vor gerade einmal drei Wochen wurden wir von Saurokbanditen belagert. Sie haben unsere Jade gestohlen, unsere Nahrungsmittelvorräte besudelt und unsere Jungen terrorisiert.\n\nWir brauchten einen Helden, und der sollte auch kommen.\n\nEr schlug ihre Streitkräfte zurück, besiegte ihren Anführer und brachte uns die gestohlene Jade zurück. Und zum Dank wollte er nichts weiter als einen Schlangenritt für seine Nichte.\n\nIch hatte nie die Gelegenheit, ihm richtig zu danken. Wenn Ihr ins Tal der Vier Winde geht, könntet Ihr ihm unseren Dank ausrichten?", progress = nil, completion = "Ihr kommt vom Tempel der Jadeschlange? Ren-Zhu lässt seinen Dank ausrichten?\n\nNun, äh... es war wirklich nichts. Ich hätte diesen Saurok besiegen können, ohne einen Tropfen Bräu zu verschütten.\n\nIch glaube, das habe ich sogar.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32020] = {title = "Eimer mit Süßigkeiten", objective = "Der folgende Zauber wird auf euch gewirkt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSüßes oder Saures\n\nIhr bekommt:\n\nEine Handvoll Süßigkeiten"}
