MultiLanguageQuestData['de'][32030] = {title = "Einmal in hundert Lebzeiten", objective = "Sprecht mit Klaxxi'va Ik in Klaxxi'vess.", description = "Die Zeit ist gekommen, <Erwecker/Erweckerin>.\n\nMit der vereinten Macht des Rates werden wir dieser verderbten Kaiserin ein Ende bereiten.\n\nDieses Ritual wurde schon seit hunderten Lebzeiten Eurer Art nicht mehr gesehen - und noch nie zuvor von einem Außenstehenden.\n\nIm Gegenzug für die Dienste, die Ihr uns erwiesen habt, lade ich Euch nun ein, diesen wichtigen Augenblick unserer Geschichte mitzuerleben.", progress = nil, completion = "Der Zeitpunkt Eurer Ankunft ist gut gewählt, Erwecker.\n\nUnser Ritual hat begonnen.", rewards = "Ihr bekommt:\n\n"}
