MultiLanguageQuestData['de'][32035] = {title = "Die Seide macht's!", objective = "Meldet Euch bei Seidenmeister Tsai auf den Seidenfeldern im Tal der Vier Winde.", description = "Von den Seidenfeldern hört man merkwürdige Geräusche.\n\nUnd auch seltsame Gerüche ziehen von dort herüber.\n\n<Ein abgebrannter/Eine abgebrannte:c> <Klasse> wie Ihr könnte ihnen vielleicht etwas aushelfen und sich dabei ein paar Goldstücke verdienen.\n\n... Oder auch nicht.", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;. Willkommen in den Seidenfeldern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32036] = {title = "Eimer mit Süßigkeiten", objective = "Der folgende Zauber wird auf euch gewirkt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSüßes oder Saures\n\nIhr bekommt:\n\nEine Handvoll Süßigkeiten"}
