MultiLanguageQuestData['de'][32038] = {title = "Hirschmeister", objective = "Tötet 10 Wildlandhirsche.", description = "Für eine schöne Hirschjagd bin ich immer zu haben. Es sind zähe und schnelle Tiere, die ihr Revier verteidigen.\n\nSie mögen zwar Pflanzenfresser sein, doch können sie selbst den erfahrensten Jäger in die Flucht schlagen.\n\nÖstlich von hier ist ein ganzes Rudel Wildlandhirsche, das nur darauf wartet von <einem Jäger/einer Jägerin> wie Euch etwas aufgescheucht zu werden.\n\nGute Jagd!", progress = nil, completion = "Eine so gute Hirschjagd habe ich seit dem Eschental nicht gesehen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32039] = {title = "Eimer mit Süßigkeiten", objective = "Der folgende Zauber wird auf euch gewirkt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSüßes oder Saures\n\nIhr bekommt:\n\nEine Handvoll Süßigkeiten"}
