MultiLanguageQuestData['de'][32045] = {title = "Kinder des Wassers", objective = "Tötet Krakor, Donnerkieme und Sukkula.", description = "Hier im Tal der Vier Winde sind wir alle Kinder des Wassers. Es nährt uns, es lässt unser Gemüse sprießen und es schenkt uns das Leben.\n\nManche Kreaturen trinken jedoch zu viel vom Wasser des Tals. Sie werden zu groß und müssen beseitigt werden, bevor sie jene in ihrer Nähe noch verletzen.\n\nIch bin nur ein einfacher Steinmeißler, aber Ihr...", progress = nil, completion = "Lasst Euch das eine Lektion sein: Trinkt nicht zu viel Wasser.\n\nWas meint Ihr, warum wir so eine große Brauerei haben?", rewards = "Ihr bekommt:\n\n"}
