MultiLanguageQuestData['de'][32105] = {title = "Makelloses Kassenbuch eines Architekten", objective = "Stellt das Artefakt zur Schau.", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRestauriertes Artefakt"}
MultiLanguageQuestData['de'][32106] = {title = "Ein Winterhauchgeschenk", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWinterhauchgeschenk"}
MultiLanguageQuestData['de'][32107] = {title = "Fliegender Tigergurami", objective = "Bringt den fliegenden Tigergurami zu Nat Pagle an der Anlegestelle der Angler.", description = "Ihr habt einen einzigartigen Fisch gefangen... mit Flügeln. Vielleicht solltet Ihr Nat Pagle bei der Anlegestelle der Angler nach seiner Expertenmeinung fragen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32108] = {title = "Herrschaftsfeste", objective = "Zündet das Signalfeuer am Strand der Landezone der Horde an, um der Flotte ein Zeichen zu senden.", description = "Jetzt ist es an der Zeit, diesem neuen Land die wahre Stärke der Horde zu zeigen.\n\nKehrt zur Landestelle zurück und setzt das verbleibende Signalfeuer in Brand. Unsere Flotte wartet.", progress = nil, completion = "&lt;Dieses Feuer wird der gesamten Invasionsflotte der Horde das Signal geben, an diesem Strand an Land zu gehen und Garroshs Feldzug in Pandaria zu beginnen.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nDomination Point: Horde Landing Cinematic\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][32109] = {title = "Löwenlandung", objective = "Signalisiert der Flotte der Allianz in der Krasarangbucht mit einem Abschussgerät für Leuchtfeuer.", description = "Die Horde darf schon viel zu lange frei in Azeroth herumlaufen. Ich lasse nicht zu, dass dieses neue Land von irgendeinem barbarischen \"Kriegshäuptling\" erobert wird.\n\nSeid Ihr bereit, Pandaria die Gerechtigkeit der Allianz zu bringen?\n\nKehren wir zur Landezone zurück. Benutzt den Raketenzünder, um die Flotte richtig an Land zu bringen und leitet Operation Schildwall ein.", progress = nil, completion = "&lt;Blaue Segel, die am Horizont kaum sichtbar sind – die gesamte Macht der Allianzflotte, die auf ein letztes Signal wartet.&gt;", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nLion's Landing: Cinematic Aura\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][32114] = {title = "Du willst also tägliche Quests ausprobieren?", objective = "Du willst tägliche Quests ausprobieren? In Ordnung.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Du willst tägliche Quests ausprobieren? In Ordnung.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][32115] = {title = "Fesseln der Vergangenheit", objective = "Befreit 14 aufgewühlte Sklavengeister.", description = "Die Mogu sind ein Haufen Dreckskerle!\n\nSie haben die Pandaren, die in diesen Höhlen arbeiteten, selbst nach ihrem Tod noch versklavt. Befreit ihre Geister! Es ist einfach nicht gerecht.\n\nSeid aber vorsichtig... sie sind so traumatisiert, dass sie Freund und Feind nicht voneinander unterscheiden können. Also werden sie sich vermutlich wehren.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32116] = {title = "Prioritäten vonnöten!", objective = "Trefft Euch mit Hilda Hornsturz bei den Ruinen von Ogudei in der Krasarangwildnis.Als ich die Grabung des Tunnels nach Nordwesten anordnete, dachte ich, wir würden etwas Nützliches finden. Gold, Eisen... irgendwas!\n\nStattdessen fanden wir Moguartefakte und ich darf einen Haufen Zwerge von der Forscherliga hüten.\n\nWie ich von den Soldaten höre, gibt es in den Minen Probleme. Ich habe Befehl von Wrynn, die Forscherliga zu unterstützen, habe aber keine Soldaten übrig. Würdet Ihr hinuntergehen und herausfinden, was da los ist?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Als ich die Grabung des Tunnels nach Nordwesten anordnete, dachte ich, wir würden etwas Nützliches finden. Gold, Eisen... irgendwas!\n\nStattdessen fanden wir Moguartefakte und ich darf einen Haufen Zwerge von der Forscherliga hüten.\n\nWie ich von den Soldaten höre, gibt es in den Minen Probleme. Ich habe Befehl von Wrynn, die Forscherliga zu unterstützen, habe aber keine Soldaten übrig. Würdet Ihr hinuntergehen und herausfinden, was da los ist?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32118] = {title = "Den Vorteil nutzen", objective = "Benutzt das Portal im Außenposten Zündmine, um Euch bei den Ruinen von Ogudei in der Krasarangwildnis mit Kaelis Segelstrahl zu treffen.Die Dummköpfe von der Forscherliga haben im Nordosten eine antike Moguruine ausgegraben. Und in ihrer Tollpatschigkeit – natürlich – die Geister der Mogu in ihrem Inneren aufgebracht.\n\nWir werden uns ihre Unfähigkeit zunutze machen. Nehmt dieses Portal und trefft Euch mit Kaelis Segelstrahl, meinem Kontakt in den Ruinen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Die Dummköpfe von der Forscherliga haben im Nordosten eine antike Moguruine ausgegraben. Und in ihrer Tollpatschigkeit – natürlich – die Geister der Mogu in ihrem Inneren aufgebracht.\n\nWir werden uns ihre Unfähigkeit zunutze machen. Nehmt dieses Portal und trefft Euch mit Kaelis Segelstrahl, meinem Kontakt in den Ruinen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32120] = {title = "Das Vermächtnis von Ogudei", objective = "Sammelt 5 uralte Moguessenzen.", description = "Die Ruinen, die wir besetzen, wurden von Ogudei errichtet – einem Moguherrscher der Antike. Wir wissen kaum etwas über ihn, doch die Zunahme der Geister in diesem Gebiet deutet darauf hin, dass ein Zusammenhang mit der Geisterbindung besteht.\n\nWenn Ihr diese Geister vernichtet, bleibt ein kleiner Rückstand ihrer Essenz in dieser Welt zurück. Bringt uns diesen – wir werden ihn analysieren und hoffentlich mehr über Ogudeis Geschichte und seine Macht herausfinden.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32121] = {title = "Die Geisterfalle", objective = "Zerstört 3 Geisterfallen.", description = "In der Ruine gibt's 'ne Menge richtig widerlicher blauer Kristalle. Schaut sie falsch an, dann rennen Euch ein paar verflucht wütende Geister hinterher.\n\nIhr müsst für mich hineingeh'n und ein paar von ihnen loswerden, damit wir die Leute wieder hierher zum Arbeiten zurückbringen können.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32122] = {title = "Ogudeis Leutnants", objective = "Tötet Meng-do, die Stärke des Berges und Gen-li, Verdreher von Worten.", description = "Nachdem wir uns zu einem alten Abschnitt der Moguruinen durchgegraben hatten, fing diese üble Geschichte an – das war auch der Zeitpunkt, als die zwei schlimmsten Geister auftauchten.\n\nSie müssen verschwinden, <mein Freund/meine Beste>.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32123] = {title = "Tod auf zwei Beinen", objective = "Besiegt 10 Soldaten der Allianz in der Herrschaftsfeste.", description = "Die Allianz hat das Festland erreicht. Wenn wir sie hier nicht besiegen, ist jegliche Hoffnung auf eine Präsenz der Horde auf diesem Kontinent verloren.\n\nBegebt Euch zu dem Schlachtfeld südlich von hier und tötet alle Mitglieder der Allianz, die Ihr findet.\n\nZeigt ihnen, dass jedes Mitglied der Horde, das noch aufrecht auf zwei Beinen steht, zehn Allianzler erledigen kann!", progress = nil, completion = "Gut gemacht, &lt;Name&gt;. Wie ich sehe, hat Euch der Aufenthalt in diesem Land in Eurem Vorsatz bestärkt und Eure Fertigkeiten verbessert.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32126] = {title = "Zeigt, was Ihr könnt", objective = "Zerstört 8 Versorgungsgüter der Allianz.", description = "Die Allianz mag zwar feige sein, dumm ist sie aber nicht. Gegen schwächere Wesen gerichtet wäre ihr Angriff furchtbar.\n\nUm die Belagerung weiterzuführen und Druck auf unsere Truppen auszuüben, wirft sie zur Unterstützung ihrer Bodentruppen Vorräte aus der Luft ab.\n\nSucht die Strände und Docks im Süden nach abgeworfenen Vorräten ab und zerstört sie.\n\nDie Allianz soll sehen, wie ihre Nahrungs- und Munitionsvorräte vor ihren Augen vernichtet werden, und verzweifeln.", progress = nil, completion = "Denkt daran, dass die Waffe Eurer Wahl nicht immer die Waffe mit der größten Reichweite oder dem meisten verursachten Schaden ist. Im Endeffekt ist die beste Waffe diejenige, die jedes Mal funktioniert.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32127] = {title = "Tot, alle tot", objective = "Besiegt Kapitän Brent der Schwarze und Kapitän Mulkey.", description = "Unser Kriegshäuptling hat mich an diese Küste entsandt, damit ich mich um diese jämmerliche Bedrohung durch die Allianz kümmere.\n\nDiese Menschen und ihre Verbündeten haben sich als ausgesprochen abhängig von ihren Anführern erwiesen. Keinerlei Eigeninitiative.\n\nWenn Ihr heute das Schlachtfeld überquert, seht Euch die Schiffe der Allianz vor unserer Südküste an. Findet ihre Kapitäne.\n\nTötet sie.\n\nFür die Horde!", progress = nil, completion = "Die Allianz ihrer Anführer zu berauben reicht nicht. Wir müssen jene, die nach der Führung trachten, vor dem Preis eines solchen Ansinnens warnen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32128] = {title = "Schon wieder beißt einer ins Gras", objective = "Jagt die explosive Ladung der Kühnheit und der Klinge der Tapferkeit in die Luft.", description = "Die Allianz hat sich vor unserer Südküste breitgemacht und beschießt unsere Bodentruppen kontinuierlich mit Kanonenfeuer. Sehen wir doch, wie toll ihre Belagerung ohne diese Unterstützung ist.\n\nBegebt Euch an Bord der feindlichen Schiffe und zerstört ihre Munitionsreserven. Das wird ihnen die Zähne ziehen.", progress = nil, completion = "Ah! Seht Euch an, wie sie brennen. Um diese neuen Schiffe der Allianz dauerhaft zu zerstören, ist allerdings mehr nötig. Ich bin mir sicher, dass sie die Feuer in ein, zwei Tagen gelöscht haben werden.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32129] = {title = "Tägliche Verteidigung 06", objective = "Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32130] = {title = "Viel Glück, viel Spaß", objective = "Sammelt 10 besonders schmalzige Allianzohren in der Löwenlandung in der Krasarangwildnis.", description = "Ich habe da ein paar Kunden, die gute, altmodische Ohren sammeln möchten. Nicht einfach irgendwelche Ohren. Sie sind nur an Ohren mit der absolut größten Menge Ohrenschmalz interessiert, die es für Geld zu kaufen gibt! \n\nSie glauben wohl, das würde Glück bringen oder so.\n\nJedenfalls möchte ich, dass Ihr welche für mich besorgt. Ich will aber nicht, dass Ihr Tiere quält, deshalb sollt Ihr sie von der Allianz in der Löwenlandung drüben besorgen.\n\nAmüsiert Euch gut – und vergesst nicht, mir nur die schmalzigsten zu bringen!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32131] = {title = "Wir brauchen mehr Mineralien", objective = "Besorgt 20 Brocken belebbaren Steins aus dem Steinbruch der Löwenlandung. Ihr findet sie bei Ingenieuren der Löwenlandung, die sie tragen, oder Ihr könnt Steinplatten mithilfe von Kollateralschaden in tragbare Brocken sprengen.", description = "Die Gnome graben einen Steinbruch im Nordosten.\n\nSie verwenden das Material für den Bau!\n\n<Zazzix verdreht die Augen.>\n\nSie sind zu dumm, dabei zu merken, dass es spezieller Mogustein zur Herstellung belebter Statuen ist. \n\nWIR können ihn mit etwas magischem Goblinsaft mixen und richtig große Explosionen damit bewirken!\n\nDie Teile sind aber schwer. Sie benutzen zum Ausgraben der Steine ein paar von ihren dummen Bombenbots. Wenn Ihr die in der Nähe von Steinplatten in die Luft jagt, bekommt Ihr Stücke, die klein genug zum Tragen sind. \n\nOder tötet sie einfach und greift sie euch. Was auch immer besser funktioniert.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32132] = {title = "Arbeiterschikane", objective = "Tötet 30 Arbeiter der Löwenlandung.", description = "Unseren Goblinfreunden fehlt leider das erforderliche Strategieverständnis zum Gewinnen eines langwierigen Konflikts.\n\nDer Schlüssel bei der Eliminierung einer ständigen Präsenz liegt darin, ihre Fähigkeit zum Aufstocken und Wiederaufbau ihrer Truppen zu attackieren.\n\nIn diesem Fall bedeutet das, ihre Arbeiter auszuschalten. Tötet sie und schwächt das Fundament. Dann wird der Rest der Festung verfallen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32133] = {title = "Wächterschutz", objective = "Stellt auf den Docks, im Rathaus und im zweiten Geschoss der Kaserne in der Löwenlandung Wächterschutze auf.", description = "Wir haben über ihrer Basis schwere Luftunterstützung in der Gestalt von viel zu vielen Zwergen auf viel zu vielen Greifen entdeckt. Das bedeutet, wir können keinen Überblick von oben über das Gebiet bekommen.\n\nEin Troll... ein Freund von mir hat uns einen Satz Wächterschutze gegeben, mit denen wir ihre Basis ausspionieren und uns einen Überblick darüber verschaffen können, was da drinnen abläuft.\n\nSchlechte Nachrichten, <mein Freund/meine Liebe> – das Vergnügen da hineinzugehen gebührt Euch.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32134] = {title = "Hart gekontert", objective = "Tötet 8 Mörserteamingenieure der Löwenlandung und zerstört 2 Mörserrohre der Löwenlandung.", description = "Es ist uns gelungen, ein paar Verwüster an den Strand zu bekommen. Diese idiotischen Zwerge mit ihren idiotischen Mörserrohren sind aber auch dort draußen und hindern die Verwüster am Vorstoßen und daran, die Festung selbst anzugreifen!\n\nGeht da raus, tötet ein paar Zwerge und jagt ein paar Mörserrohre in die Luft.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32135] = {title = "Heldenmörder", objective = "Tötet einen Helden der Allianz an der Löwenlandung in der Krasarangwildnis.", description = "Es gibt Situationen, in denen einen von ihren Soldaten auszuschalten wichtiger ist als Hunderte zu töten.\n\nSie haben einige ihrer Helden auf dem Schlachtfeld aufmarschieren lassen, damit sie ihre Verteidiger unterstützen. Sie zu töten wird nicht nur ihre Verteidigung aufweichen sondern sich auch auf ihre Moral niederschlagen.\n\nBrecht also auf und zieht einen für mich aus dem Gefecht. Ihr schafft das.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32138] = {title = "Arbeitsauftrag: Holz", objective = "Findet Zino \"den Schredder\" Blitzbeil auf dem Holzhof.Jeden Tag dasselbe! \"Das ist uns ausgegangen!\", \"Wir brauchen mehr davon!\", \"Warum rührt Ihr nie einen Finger?!\"\n\nIch arbeite! Ich erledige Dinge! Sie können so verletzend sein! Ich gebe hier unten mein Bestes!\n\nAch ja, wir brauchen mehr Holz! Geht hinunter und richtet diesem Nichtsnutz Zino aus, dass er seine Schredder anwerfen soll!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Jeden Tag dasselbe! \"Das ist uns ausgegangen!\", \"Wir brauchen mehr davon!\", \"Warum rührt Ihr nie einen Finger?!\"\n\nIch arbeite! Ich erledige Dinge! Sie können so verletzend sein! Ich gebe hier unten mein Bestes!\n\nAch ja, wir brauchen mehr Holz! Geht hinunter und richtet diesem Nichtsnutz Zino aus, dass er seine Schredder anwerfen soll!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32139] = {title = "Gestapelt!", objective = "Sammelt 9 Stücke Bauholz der Herrschaftsfeste auf dem Holzhof.", description = "Wir haben erst heute Morgen eine Bestellung abgewickelt. Sie können doch unmöglich schon mehr brauchen?!\n\nMein Team hat Doppelschichten gearbeitet, um diese Bäume zu fällen und zu verarbeiten.\n\nDas Problem ist, dass wir es hier unten mit einer Plage von Truppen aus der Löwenlandung zu tun haben. Ich habe heute schon einmal Kopf und Kragen riskiert und bin nicht bereit, noch einmal da rauszugehen!\n\nGoob wird Euch begleiten und mit dem Auftrag helfen. Er ist zwar nicht der Hellste, dafür kann er schwer heben.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\n\"Stack 'Em High\" - Completion Trigger\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32140] = {title = "Arbeitsauftrag: Eisen", objective = "Findet Daxil \"Klunker\" Erzschleif bei Erzschleifs Grabung.", description = "Als sie sagten, sie hätten ein paar unglaubliche Gesteinsbrocken in der Mine gefunden, habe ich mir Diamanten vorgestellt. Jedes Kind weiß doch, dass alle Minen voller Diamanten sind, Dummchen! Oder zumindest Rubine!\n\nStattdessen habe ich nur dieses komische Eisen bekommen. Was soll ich denn damit anfangen?\n\nTja, keiner hat je behauptet, dass diese Arbeit glamourös wäre. Ich tue, was ich kann, um ihr ein wenig Klasse zu verleihen.\n\nWir haben gerade einen neuen Arbeitsauftrag für Eisen erhalten. Sucht Daxil vor Erzschleifs Grabung auf und erledigt ihn, pronto!", progress = nil, completion = "Beschwert sie sich noch immer über Diamanten und Rubine? Wir haben hier unten etwas Besseres als Diamanten gefunden!\n\nDieses Erz ist etwas Besonderes. Es hat Potenz!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32141] = {title = "Energetisches Metall", objective = "Besorgt 7 aufgeladene Eisenerzklumpen aus Erzschleifs Grabung.", description = "<Daxil kneift ihre Augen zusammen und spricht mit gedämpfter Stimme.>\n\nManchmal graben wir zu tief, <Klasse>. Manchmal fördern wir etwas so Grauenhaftes zutage, dass wir uns wünschen, wir hätten mit dem Graben nie angefangen...\n\nIch mache nur Spaß! Also, versteht mich nicht falsch, wir haben tatsächlich etwas Unerwartetes gefunden. Das Erz, das wir dort unten finden, ist nicht Euer normales Nullachtfünfzehn-Eisen.\n\nEs gibt dabei nur ein Problem: Schieferspinnen! Wir haben große Mühe, diesen Bestellungen nachzukommen.\n\nKönnt Ihr vielleicht mit anpacken?", progress = "Habt Ihr vielleicht etwas Funkelndes dort unten gefunden?", completion = "Haben sie dort unten etwas Brauchbares gefunden? Vielleicht einen Smaragd oder einen Opal? Ist es zu viel verlangt, ein bisschen Einsatz zu fordern?!\n\nWie dem auch sei! Ich werde dafür sorgen, dass diese Lieferung ihren Bestimmungsort erreicht.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32142] = {title = "Bis zum felsigen Ende", objective = "Tötet 10 Orcs an der Herrschaftsfeste.", description = "Die Orcs dürfen auf GAR KEINEN Fall in diesem Land Fuß fassen. Sie werden es genau so verderben wie Kalimdor.\n\n$p, ich brauche Leute vor Ort und die Horde in ihren Gräbern. Macht Euch zur Küste auf und sorgt dafür, dass sich die Wut der Allianz über ihre Köpfe ergießt!\n\nTötet alle Orcs, die Ihr findet. Nehmt ihnen den Wind aus den Segeln.\n\nFür den König!", progress = nil, completion = "Gut gemacht, Soldat. Das sollte dabei helfen, die Horde in Schach zu halten.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32143] = {title = "Erkund-o-magie", objective = "Findet die drei Erkund-o-meter in der Herrschaftsfeste.", description = "Seid gegrüßt, $p! Ich habe schon viel über Euren Erfolg im Einsatz gehört. Ich würde Eure Dienste gern in Anspruch nehmen, um das jüngste Modell meines \"Belager-o-matik\" zu testen, ein Gerät mit grauenhaftem und vielseitigem Potenzial.\n\nIch verspreche Euch, dass es für den Anwender vorwiegend unbedenklich ist.\n\nWenn Ihr in der Gegend der Herrschaftsfeste seid, haltet nach meinen Erkund-o-metern Ausschau. Sie wurden losgeschickt, um gute Angriffsziele ausfindig zu machen. Wenn ihr eins findet, aktiviert es und ich werde einen Belager-o-matik an Euren Aufenthaltsort steuern.\n\nWir sehen uns im Einsatz... wie man so sagt.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32144] = {title = "Mit Hochdruck", objective = "Zerstört 8 Vorratskisten der Horde.", description = "Die Horde ist über alle Maßen stolz und wird bedenkenlos bis zum Tod kämpfen.\n\nWir müssen ihren Willen brechen, ohne dabei selbst riesige Verluste zu erleiden.\n\nSucht an der Küste und in der Nähe ihrer Schiffe nach ihren Vorräten. Zerstört sie.\n\nNichts bricht den Willen eines Verteidigers schneller als mit anzusehen, wie seine Hoffnung auf Nahrung sich in Rauch auflöst.\n\nWenn Ihr damit fertig seid, sucht Sully hinter den feindlichen Linien auf. Er hat den nächsten Auftrag für Euch.", progress = nil, completion = "Dank Eurer Aktionen weiß die Horde, dass sie ihre Truppen nicht ernähren kann.\n\nDie Dauer, die sie einer Belagerung standhalten kann, ist erheblich reduziert, und bald wird ihre Moral darunter leiden.\n\nWir dürfen nicht aufhören, Druck auszuüben.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32145] = {title = "Kopfgeld", objective = "Besiegt Steingardistin Ruk'ra, Bombentechniker Klickefritz und Or'Dac.", description = "Meine Sonden haben drei sehr gefährliche Ziele im Hof des Herrschaftsturms entdeckt.\n\nEs handelt sich um einen Abgesandten der Oger, einen Offizier der Kor'kron und einen geistesgestörten Goblin-Bombenbauer.\n\nMeine Belager-o-matiks sind nicht für den Kampf Mann gegen Mann konzipiert, die Eliminierung der Ziele ist also Eure Aufgabe.\n\nViel Glück! Erstattet mir anschließend auf der Himmelsfeuer Bericht.", progress = nil, completion = "Gute Arbeit! Es tut mir leid, gute Soldaten Gefahren auszusetzen, doch mein Auto-Verwüst-o-mat V2 ist noch nicht funktionstüchtig.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32146] = {title = "Schwere Hämmer", objective = "Tötet 5 schwere Schergen.", description = "Die Horde scheint zu glauben, sie könne sich hinter ihren schlagkräftigen Schergen verstecken.\n\nDie Schergen sind zäh, stark und dümmer als ein verkaterter Oger.\n\nBegebt Euch dort hinunter und lasst den Hammer des Zorns der Allianz auf sie niedergehen!", progress = nil, completion = "Ich danke Euch, Soldat. Das sollte die Horde lehren, dass mehr als ein paar Schergen nötig sind, um uns zu verjagen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32147] = {title = "Täglicher Angriff 06", objective = "Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32148] = {title = "Angriff! Bewegung!", objective = "Tötet 12 Schamanen oder Räuber der Herrschaftsoffensive.", description = "Klar, sie haben jede Menge Grunzer da draußen, die an unsere Tür hämmern und nur darauf warten, uns die Köpfe abzuschneiden.\n\nAber die Grunzer bereiten mir keine Sorgen. Sie verfügen auch über Schamanen und Räuber. Die Schamanen stärken mit ihrer Magie die Grunzer, die Räuber sind schnell und auf das Ausschalten unserer Gebäude spezialisiert.\n\nIch möchte, dass Ihr da rausgeht und ein paar von den Schamanen und Räubern erledigt.\n\nLos! Angriff! Bewegung!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32149] = {title = "Ressourcen sammeln", objective = "Besorgt 12 Stücke Bauholz der Löwenlandung, die Ihr von den Stapeln fluchtartig aufgegebenen Bauholzes bergt.", description = "Ach, die armen Arbeiter...\n\nJa, natürlich sind sie Feiglinge. Sie wissen aber nicht, wie man kämpft, und sie ziehen los, um Holz für uns zu sammeln... die Horde attackiert sie... Es ist einfach furchtbar!\n\nWir brauchen das Holz aber, wenn wir durchhalten wollen. Geht los und sammelt sämtliches Holz, das sie fallengelassen haben.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32150] = {title = "Versorgungsblockade", objective = "Zerstört 8 Versorgungskarren der Herrschaftsfeste.", description = "Die Horde hat beschlossen, Goblins die Verantwortung für ihre Logistik zu übertragen. Und wo es Goblins gibt, da gibt es auch achtlos platzierten Sprengstoff.\n\nSpäher berichten, dass ihre Vorräte in Karren sind, die außerdem auch noch Verwüstermunition enthalten. Seht diese Kisten nur schief an und sie fliegen in die Luft. \n\nWenn wir genügend Ressourcen der Horde zerstören, können wir ihren Angriff verkürzen und dadurch Leben retten. Geht also los und zieht diese Karren aus dem Verkehr!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32151] = {title = "Turmverteidigung", objective = "Besorgt 20 Brocken belebbaren Steins aus dem Steinbruch der Löwenlandung von Bilgewässer Goblins oder indem Ihr Steinplatten mit Kollateralschaden zerstört.", description = "Die Gnome betreiben unseren Steinbruch im Nordwesten. Der Fels ist besonders hart – den Gnomen zufolge bauten die Mogu damit ihre Konstrukte. \n\nOb das stimmt, weiß ich nicht. Ich weiß allerdings, dass wir mit diesem Stein unsere Türme bauen und dass die Horde die Bilgewässer-Goblins angewiesen hat, ihn uns zu stehlen.\n\nMacht Euch auf und holt etwas davon zurück. Übrigens, Kollateralschaden bricht möglicherweise die Steinplatten in Stücke. Nehmt in diesem Fall die Stücke auch mit.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32152] = {title = "Belagerungsschaden", objective = "Findet eine Bilgewässer Sprengkapsel bei einem Bilgewässer Pionier und platziert sie bei einem Verwüster der Herrschaftsfeste.", description = "Die Horde hatte den genialen Einfall, die Bilgewässer Goblins unseren Steinbruch angreifen zu lassen.\n\nSie verwenden schweren Sprengstoff – schweren Sprengstoff, der mit der Munition in ihren Verwüstern reagieren wird.\n\nTötet Bilgewässer Goblins, bis Ihr Sprengstoff findet, platziert ihn an einem der Verwüster... und BUMM! Belagerung beendet.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32153] = {title = "Heldenmörder", objective = "Tötet einen Helden der Horde.", description = "Also, Ihr seid zäh. Zäher als die anderen Männer und Frauen hier. Das bedeutet, dass ich Euch für eine Sondermission brauche.\n\nDie Horde setzt ihre Besten gegen uns ein. Die Helden ihrer Armee – Klingenmeister, Taurenhäuptlinge, alles Mögliche.\n\nIch will, dass Ihr einen von ihnen außer Gefecht setzt. Das wird ein schwerer Schlag sein, und zwar nicht nur für ihre Angriffsstärke sondern auch für ihre Moral.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32154] = {title = "Ausgebrannt!", objective = "Verwendet den instabilen Sprengstoff, um den nordöstlichen Treibstoffbehälter, den nördlichen Treibstoffbehälter und den nordwestlichen Treibstoffbehälter zu zerstören.", description = "Die Goblins nehmen überhand! Zuerst machen sie den Wald dem Erdboden gleich und stellen diesen scheußlichen Bohrturm auf. Dann werfen sie ihre Ölfässer in die Bucht!\n\nWir müssen diesem Wahnsinn ein Ende setzen! Allerwenigstens müssen wir ihnen eine Schlappe verpassen.\n\nWir müssen ihren Treibstoffvorrat vernichten! Vielleicht gehen dabei auch noch ein paar Goblins mit drauf!", progress = nil, completion = "Ich wäre zu gern dort gewesen und hätte dabei zugesehen, wie ihr Treibstoff in Flammen aufgeht! War vermutlich ein ziemlicher Anblick.\n\nDas habt Ihr gut gemacht, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32156] = {title = "Das gehört sich so", objective = "Bergt 7 Erkennungsmarken von den gefallenen Soldaten der Operation Schildwall am Bilgewasserstrand.", description = "Das ist ein barbarischer Krieg, <Klasse>! Wir haben so viele verloren, die versucht haben, zu verhindern, dass sich der Bilgewasser-Betrieb weiter ausbreitet.\n\nDiese gefallenen Soldaten kämpften ehrenhaft und verdienten es, ihre Sterbesakramente zu bekommen. Zumindest müssen wir in der Lage sein, ihre nächsten Verwandten zu benachrichtigen.\n\nVielleicht könnt Ihr ja ihre Erkennungsmarken einsammeln, damit wir ihnen zumindest in einem kleinen Rahmen Ehre erweisen können.", progress = "Selbst im Krieg sollte es ein gewisses Maß an Anstand geben.", completion = "Ihr habt diesen Soldaten einen großen Dienst erwiesen, &lt;Name&gt;. Jetzt müssen wir nur noch dafür sorgen, dass sie nicht umsonst ihr Leben gelassen haben.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32157] = {title = "...ist ein guter Goblin.", objective = "Tötet 10 Bilgewässer Goblins beim Bilgewasserstrand.", description = "Die Zerstörung in Krasarang ist unverzeihlich, <Klasse>. Die einzige Methode, ihr ein Ende zu bereiten, besteht darin, die Bilgewasser-Operation gewaltsam zu stoppen.\n\nDies ist zum übergeordneten Wohl von Pandaria und der Allianz. Geht zum Bilgewasserstrand, und macht sie dem Erdboden gleich! Die Horde wird ihnen zweifelsohne Hilfe leisten.\n\nVernichtet sie!", progress = nil, completion = "Ausgezeichnet, &lt;Klasse&gt;! Irgendwann werden wir die Horde vollständig von diesem Kontinent vertreiben.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32158] = {title = "Programm in zwei Schritten", objective = "Zerstört Schreddermeister Packle in Blitzbeils Holzhof.", description = "Schreddermeister Packle ist zum Großteil für die Verwüstungen hier unten verantwortlich, <Klasse>.\n\nEs wird gemunkelt, dass er die Schredder umgebaut hat, damit sie schneller arbeiten, ohne Rücksicht auf den Schaden, den sie dadurch verursachen können.\n\nStellt Euch vor, wie schlimm es für die Bäume war, so zugesetzt zu bekommen. Sich von solch einem Ausmaß der Zerstörung wieder zu erholen, wird sehr schwierig sein.\n\nDer erste Schritt besteht darin, anzuerkennen, dass ein Problem besteht. Der zweite Schritt besteht darin, das Problem zu beseitigen.", progress = nil, completion = "Gut gemacht, &lt;Name&gt;! Nun kann der Wald sich wieder erholen. Aus dem Tod kommt stets neues Leben und eine neue Gelegenheit, es zu schützen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32161] = {title = "Jagd des Bestienmeisters: Der Kranich", objective = "Besorgt 5 makellose goldene Kronenfedern und 1 makellose schwarze Kronenfeder.", description = "Gemeinsam mit der Schlinge erhaltet Ihr Ratschläge zur Kranichjagd:\n\nDie größten Kraniche der Krasarangwildnis lassen sich nicht mit simplen Dingen wie Futter ködern. Ihr müsst an die Gefühle der Geschöpfe appellieren, wenn Ihr sie aus ihren Verstecken im Dschungel hervorlocken wollt.\n\nSowohl in Chi-Jis Wiege als auch bei den Narsongtürmen östlich von hier wimmelt es nur so von Kranichen. Rupft ihnen die Federn aus und platziert sie gut sichtbar am Kranichtempel. Eure Beute wird Euch zulaufen.", progress = "Das ist der Ort, in der Nähe des Kranichtempel.", completion = "Ihr steckt die Federn in den Boden und blickt dann in Richtung Tempel...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUralten Blutkronenkranich beschwören\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32162] = {title = "Jagd des Bestienmeisters: Der Tiger", objective = "Besorgt 25 unbeschädigte Yakkeulen.", description = "Gemeinsam mit der Falle erhaltet Ihr Ratschläge zur Tigerjagd:\n\nTiger sind gefräßige Kreaturen, und in diesem Dschungel ist Großwild selten. Wenn Ihr die ältesten Katzen aus ihren Verstecken hervorlocken wollt, könnt Ihr das mit einer Mahlzeit versuchen.\n\nAuf der anderen Seite des Schlangenrückens findet Ihr eine Yakherde. Erlegt sie, bringt ihr Fleisch an den Rand des Dschungels, stellt Eure Falle auf und wartet.", progress = "Das scheint mir ein idealer Ort für eine Tigerfalle zu sein.", completion = "Ihr legt das Fleisch oben auf die Falle und wendet den Blick dann in Richtung Dschungel...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAlten Krasaritiger beschwören\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32163] = {title = "Jagd des Bestienmeisters: Die Krabbe", objective = "Besorgt 30 müffelnde verrottete Fische von Ungadorfbewohnern in Unga Ingu.", description = "Gemeinsam mit der Kiste erhaltet Ihr Ratschläge zur Krabbenjagd:\n\nKrabben sind merkwürdige Urwesen mit völlig anderen Beweggründen als Ihr und ich.\n\nKleine Krabben sind leicht zu finden und zu fangen, die großen verbergen sich aber unter dem Sand, abseits der Gefahren und unerreichbar. Um sie hervorzulocken, machen wir uns ihren Geruchssinn zunutze.\n\nDie Ungadorfbewohner im Südosten lassen den Fisch, den sie fangen, vor dem Verzehr fermentieren. Sammelt genügend verrotteten Fisch und Ihr werdet eine kolossale Krabbe fangen.", progress = "Das sieht nach einem geeigneten Ort aus, um eine Krabbe zu fangen.", completion = "Ihr verteilt den verrottenden Fisch, bereitet die Kiste vor und blickt dann in Richtung Strand...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKolossale Zwingzange beschwören\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32164] = {title = "Jagd des Bestienmeisters: Der Kranich", objective = "Besorgt 5 makellose goldene Kronenfedern und 1 makellose schwarze Kronenfeder.", description = "Gemeinsam mit der Schlinge erhaltet Ihr Ratschläge zur Kranichjagd:\n\nDen größten Kranichen der Krasarangwildnis sind simple Dinge wie Futter egal. Ihr müsst an die Gefühle der Geschöpfe appellieren, wenn Ihr sie aus dem Dschungel hervorlocken wollt.\n\nSowohl in Chi-Jis Wiege als auch bei den Narsongtürmen westlich von hier sind Kraniche sehr zahlreich. Rupft einigen von ihnen die Federn aus und platziert sie gut sichtbar am Kranichtempel. Eure Beute wird Euch zulaufen.", progress = "Das ist der Ort, in der Nähe des Kranichtempel.", completion = "Ihr steckt die Federn in den Boden und blickt dann in Richtung Tempel...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nUralten Blutkronenkranich beschwören\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32165] = {title = "Jagd des Bestienmeisters: Der Tiger", objective = "Besorgt 25 unbeschädigte Yakkeulen.", description = "Gemeinsam mit der Falle erhaltet Ihr Ratschläge zur Tigerjagd:\n\nTiger sind Vielfraße, und in diesem Dschungel ist Großwild selten. Wenn Ihr vorhabt, die ältesten Katzen aus ihren Verstecken hervorzulocken, braucht Ihr eine verlockende Mahlzeit.\n\nAuf der anderen Seite des Schlangenrückens befindet sich eine Yakherde. Tötet sie, bringt ihr Fleisch an den Rand des Dschungels, stellt Eure Falle auf und wartet.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nAlten Krasaritiger beschwören\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32166] = {title = "Jagd des Bestienmeisters: Die Krabbe", objective = "Besorgt 30 müffelnde verrottete Fische von Ungadorfbewohnern in Unga Ingu.", description = "Gemeinsam mit der Kiste erhaltet Ihr Ratschläge zur Krabbenjagd:\n\nKrabben sind merkwürdige alte Geschöpfe mit völlig anderen Beweggründen als wir.\n\nKleine Krabben sind leicht zu finden und zu fangen, die größeren Exemplare verbergen sich aber unter dem Sand, abseits von Gefahren und unerreichbar. Um sie hervorzulocken, machen wir uns ihren Geruchssinn zunutze.\n\nDie Ungadorfbewohner im Südwesten lassen den Fisch, den sie fangen, vor dem Verzehr fermentieren. Sammelt genügend verrotteten Fisch und Ihr werdet eine kolossale Krabbe fangen.", progress = "Das sieht nach einem geeigneten Ort aus, um eine Krabbe zu fangen.", completion = "Ihr verteilt den verrottenden Fisch, bereitet die Kiste vor und blickt dann in Richtung Strand...", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nKolossale Zwingzange beschwören\n\nIhr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
