MultiLanguageQuestData['de'][32175] = {title = "Haustierkampf des Dunkelmonds!", objective = "Besiegt Jeremy Feasel in einem Haustierkampf.", description = "Seid Ihr bereit, den Mut Eurer Haustiere auf die Probe zu stellen...?", progress = nil, completion = "Ich muss schon sagen – tolle Show.", rewards = "Ihr bekommt:\n\nDunkelmond-HaustierbedarfGeringes Amulett des GlücksTapferkeitspunkte"}
MultiLanguageQuestData['de'][32181] = {title = "Beute des Bestienmeisters: Der Kranich", objective = "Bringt den uralten Blutkronenkranich zu Jorn Himmelsdeuter.", description = "Der uralte Kranich lebt, ist aber betäubt.\n\nIhr solltet ihn zu Jorn Himmelsdeuter bringen, bevor er aufwacht.", progress = "Willkommen zurück, <Name>.", completion = "Zum Einfangen der Bestie war nur einer nötig, um sie wahrhaftig zu bezwingen, sind viele erforderlich.\n\nSprecht wieder mit mir, wenn Ihr genug Verbündete zusammengetrommelt habt. Wir werden die Anmut des Kranichs an der Macht der Horde testen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32182] = {title = "Beute des Bestienmeisters: Der Tiger", objective = "Bringt den Krasariältesten zu Jorn Himmelsdeuter.", description = "Der Katzen-Älteste lebt, ist aber betäubt.\n\nIhr solltet ihn zu Jorn Himmelsdeuter bringen, bevor er aufwacht.", progress = "Willkommen zurück, <Name>.", completion = "Zum Einfangen der Bestie war nur einer nötig, um sie wahrhaftig zu bezwingen, sind viele erforderlich.\n\nSprecht wieder mit mir, wenn Ihr genug Verbündete zusammengetrommelt habt. Wir werden die Wildheit des Tigers an der Macht der Horde testen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32183] = {title = "Beute des Bestienmeisters: Die Krabbe", objective = "Bringt die kolossale Zwingzange zu Jorn Himmelsdeuter.", description = "Die kolossale Krabbe lebt, ist aber betäubt.\n\nIhr solltet sie zu Jorn Himmelsdeuter bringen, bevor sie aufwacht.", progress = "Willkommen zurück, <Name>.", completion = "Zum Einfangen der Bestie war nur einer nötig, um sie wahrhaftig zu bezwingen, sind viele erforderlich.\n\nSprecht wieder mit mir, wenn Ihr genug Verbündete zusammengetrommelt habt. Wir werden die Widerstandsfähigkeit der Krabbe an der Macht der Horde testen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32184] = {title = "Beute des Bestienmeisters: Der Kranich", objective = "Bringt den uralten Blutkronenkranich zu Jäger Blake.", description = "Der uralte Kranich lebt, ist aber betäubt.\n\nIhr solltet ihn zu Jäger Blake bringen, bevor er aufwacht.", progress = "Willkommen zurück, <Name>.", completion = "Zum Ergreifen der Bestie war zwar nur ein &lt;Volk&gt; erforderlich, um sie zu erlegen aber werden viele mehr nötig sein.\n\nRuft ein paar Freunde zusammen und kommt dann wieder zu mir. Wir werden die Anmut des Kranichs gegen den Ruhm der Allianz antreten lassen!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32185] = {title = "Beute des Bestienmeisters: Der Tiger", objective = "Bringt den Krasariältesten zu Jäger Blake.", description = "Der Katzen-Älteste lebt, ist aber betäubt.\n\nIhr solltet ihn zu Jäger Blake bringen, bevor er aufwacht.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32186] = {title = "Beute des Bestienmeisters: Die Krabbe", objective = "Bringt die kolossale Zwingzange zu Jäger Blake.", description = "Die kolossale Krabbe lebt, ist aber betäubt.\n\nIhr solltet sie zu Jäger Blake bringen, bevor sie aufwacht.", progress = "Willkommen zurück, <Name>.", completion = "Zum Ergreifen der Bestie war zwar nur ein &lt;Volk&gt; erforderlich, um sie zu erlegen aber werden viele mehr nötig sein.\n\nRuft ein paar Freunde zusammen und kommt dann wieder zu mir. Wir werden die Ausdauer der Krabbe gegen den Ruhm der Allianz antreten lassen!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32190] = {title = "Nach Mogujia", objective = "Findet Lordregent Lor'themar Theron bei Mogujia. Sprecht mit Tak-Tak bei der Herrschaftsfeste bezüglich einer Transportmöglichkeit.", description = "Throm-ka, <Klasse>. Während wir damit beschäftigt waren, unsere Stellung hier zu verteidigen, hat Lordregent Lor'themar Theron eine Forschungsexpedition zum Kun-Lai-Gipfel im Norden geführt.\n\nLeider sieht es so aus, als wäre sie in Schwierigkeiten geraten.\n\nKriegshäuptling Garrosh Höllschrei ist bereits zu Hilfe geeilt, wir brauchen aber weitere Verstärkung.\n\nBrecht nach Norden zum Kun-Lai-Gipfel auf. Sprecht mit Tak-Tak bezüglich einer Transportmöglichkeit.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32191] = {title = "Uralte Wächter", objective = "Tötet 5 Wächter der Korun.", description = "Ehe die Mogu unseren Spähtrupp überwältigten, haben wir Relikte gefunden, die in den Ruinen im Norden verstreut waren.\n\nIch würde gern ein paar Proben davon einsammeln, mit den Terrakotta-Wachhunden der Mogu werden wir aber nicht fertig.\n\nWenn Ihr die Umgebung von ihnen säubern könntet, werden wir unsere Arbeit fortsetzen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32192] = {title = "Blutlinie", objective = "Befreit 6 Magier der Herrschaftsoffensive indem Ihr Hüter der Korun tötet.", description = "Wir konnten die Wächter der Mogu und ihre Hunde zurückschlagen, etliche Blutelfen aus dem Spähtrupp hatten allerdings nicht so viel Glück.\n\nViele von meinen Leuten sitzen in den Ruinen im Norden fest. Wir arbeiten an einer Lösung, um sie herauszuholen, ich glaube aber, dass es eine unkompliziertere Vorgehensweise gibt.\n\nBegebt Euch zu den Ruinen und tötet alle Wächter, die einen Gefangenen bewachen. Wenn meine Eingebung mich nicht trügt, können wir so unsere Kameraden befreien.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32193] = {title = "Nach Mogujia", objective = "Sprecht mit Brann Bronzebart in Mogujia am Kun-Lai-Gipfel. Sprecht mit Fennie Hornsturz in der Löwenlandung für einen Transport.", description = "Die Forscherliga hat vor ein paar Tagen eine Expedition nach Norden entsandt.\n\nSeither haben wir nicht mehr von ihr gehört und ich würde nachts besser schlafen, wenn ich wüsste, dass unsere Leute nicht in Schwierigkeiten stecken.\n\nMeinen letzten Informationen zufolge war Brann Bronzebart nach Mogujia am Kun-Lai-Gipfel unterwegs.\n\nFindet ihn und erstattet Bericht über ihre Lage. Fennie dort drüben kann Euch hinbringen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32194] = {title = "Böses Blut", objective = "Erlangt 5 Artefakte der Korun von Runensuchern von Silbermond oder von Magiern oder Rittern der Herrschaftsoffensive.", description = "Die Forscherliga ist hier, um die Ruinen auszugraben und meine Aufgabe ist es, sie zu beschützen.\n\nAls wir hier ankamen, wimmelte es nur so von Blutelfen. Die Horde scheint genauso großes Interesse an den Mogu zu haben wie wir.\n\nDas ist eine gute Gelegenheit für uns, einige von ihnen aus dem Weg zu schaffen und gleichzeitig ihre Ergebnisse zu stehlen.\n\nTötet die Blutelfen, die Ihr in den Ruinen antrefft, und nehmt ihnen ab, was sie ausgegraben haben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32195] = {title = "Aufgestauter Zorn", objective = "Tötet 27 Zornlinge.", description = "Wie es aussieht, wimmelt es hier nur so von verbleibender Sha-Energie.\n\nIhr wisst, was Ihr zu tun habt, <Name>. Vernichtet auch die letzten Überbleibsel.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32197] = {title = "Eigenartiger Braten", objective = "Besorgt 7 Stücke eigenartiges Fleisch von den wilden Tieren aus der Gegend.", description = "Wir kriegen von überall her Beschwerden, dass die Chefin das ganze gute Essen bekommt und den anderen nur die Reste überlässt.\n\nGanz unter uns, da kann etwas dran sein. Selbst ich bekomme kein so gutes Essen wie sie!\n\nWir brauchen etwas, von dem Sezik eine Menge machen kann, um wenigstens darüber hinwegzutäuschen, wie ungenießbar das Essen hier ist...\n\nIch hab's! Eigenartiger Braten!", progress = "Was habt Ihr für mich?", completion = "Ich habe Maßstäbe, müsst Ihr wissen! Ich bin Koch, kein Zauberkünstler!\n\nDas richtig Eigenartige hier ist, wie Duke das schaffen will, alle reinzulegen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32210] = {title = "Moguboss für Schlüssel töten, Objekt hinter Sprungpuzzle benutzen", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBelohnung der Sonnenhäscher"}
MultiLanguageQuestData['de'][32221] = {title = "Erstürmung des Strandes", objective = "Tötet 10 beliebige Angreifer der 7. Legion.", description = "Unsere Holzvorräte sind durch ständige Angriffe aus der Löwenlandung gefährdet.\n\nBisher konnten wir die Angreifer in Schach halten, es wird aber Zeit, dass wir die Muskeln spielen lassen!\n\nBrecht zur Küste auf und spaltet ein paar Schädel!", progress = "Ist der Holzhof sicher?", completion = "Ausgezeichnete Arbeit dort unten, &lt;Name&gt;! Das sollte sie uns eine Zeit lang vom Leib halten!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32223] = {title = "Gesucht: Leutnant Ethan Jacobson", objective = "Tötet Leutnant Ethan Jacobson auf den Südlichen Inseln im Süden von Blitzbeils Holzhof.", description = "Wegen Verbrechen an den Truppen der Herrschaftsfeste gesucht!\n\nLeutnant Ethan Jacobson ist für die Ausführung mehrerer Bodenangriffe gegen den Holzbetrieb von Bilgewasser verantwortlich.\n\nEr wurde zuletzt auf einer Insel im Süden von Blitzbeils Holzhof gesichtet.", progress = nil, completion = "Jeder Tag, an dem ein weiterer Anführer der Löwenlandung fällt, ist ein guter Tag, &lt;Klasse&gt;! Gute Arbeit!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32229] = {title = "Marodierenden Trollkampftrupp töten", objective = "Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32235] = {title = "Explosiver Cocktail!", objective = "Verwendet den Bilgewässer Molotowcocktail, um 6 Gyrokopter X2 der Himmelsfeuer zu zerstören.", description = "Die Gnome haben ihre Fluggeräte mitgebracht. Ich will, dass mein Himmel FREI bleibt!\n\nEgal, welches Reittier Ihr bei Euch habt – hinauf mit Euch und zerstört diese erbärmlichen Geräte.\n\nIhr könnt diesen Grog verwenden, den ich von einem unserer Goblinverbündeten \"besorgt\" habe. Ihr wärt besser damit bedient, mit ihm Gyrokopter aus der Luft zu holen, als ihn in den Gurgeln dieser kleinen grünen Unholde versickern zu lassen.", progress = nil, completion = "Ha! Primitive mechanische Spielzeuge können es mit einer gezielt geworfenen Flasche Grog nicht aufnehmen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32236] = {title = "Kratz-Ab!", objective = "Sprüht 5 Aufgebrachte Schieferspinnen mit dem \"Kratz-Ab\"-Spray ein und beseitigt 12 Schiefersplitter.", description = "In dieser Höhle wimmelt's nur so vor fiesen Schieferspinnen! Wie soll man denn seine Arbeit erledigen, wenn sie die Minenarbeiter UND das Erz auffressen?!\n\nDas wäre eine gute Gelegenheit, meine neue Erfindung einzusetzen: Kratz-Ab! Man muss einfach nur die Schieferspinnen mit diesem Zeug einsprühen. Das mögen die gar nicht, und für die Minenarbeiter scheint es kaum längerfristige Nebenwirkungen zu haben!\n\nWas kann da schon schiefgehen?\n\nNehmt diesen praktischen Sprüher mit und macht Euch an die Arbeit.", progress = "Schieferspinnen. Ich hasse Schieferspinnen.", completion = "Na das hört man gerne! Ich wette, diese Spinnen werden es sich jetzt zweimal überlegen, bevor sie sich wieder in eine Bilgewasseroperation einmischen!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32238] = {title = "Universalfernsteuerungsexplosion", objective = "Zerstört 9 Mecha-Stampfer des Schildwalls in und um Blitzbeils Holzhof.", description = "Die Mecha-Stampfer machen uns hier wirklich das Leben schwer, doch ich glaube, ich habe die Lösung!\n\nIch habe mir diese Universalfernsteuerung gebaut, aber scheinbar arbeitet sie auf einer bestimmten Frequenz, die eine nützliche Wirkung hat!\n\nEs scheint ganz so, als schwäche diese Frequenz ihre Rüstung!\n\nBenutzt die Fernsteuerung, um sie von ihrem hohen Ross zu holen und ihnen dann die Visage zu polieren!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32242] = {title = "Vergrabene Geheimnisse", objective = "Sprecht mit Fanlyr Silberdorn bei der Ahnenhöhe im Tal der Ewigen Blüten.", description = "Ich habe gehört, dass die Mogu einst Hunderte verborgener Waffenkammern voller erderschütternder Waffen ihr Eigen nannten.\n\nWenn sich eine Moguarmee für den Krieg rüstete, erfüllte sie die Herzen ihrer Feinde mit Furcht und Schrecken.\n\nDas ist GENAU die Art Wissen, die ich hier in Pandaria suche!\n\nIch habe eine Expedition entsandt, um ein paar Ruinen im Westen zu erforschen, aber ihre Arbeitsmoral ist die schwachsinniger Peons!\n\nGeht hin und sprecht mit Fanlyr Silberdorn, ihrem Anführer. Sagt ihm, dass ich Resultate sehen will, und zwar sofort.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32243] = {title = "Die Machtquelle der Korun", objective = "Nehmt dem Spruchwirker der Korun eine Sha-berührte Klaue ab.", description = "Nah halli-hallo! Habt Ihr schon mal so was geseh'n wie die alten Statuen hier? Faszinierend!\n\nAls ich vorhin die Ruinen da oben ausgekundschaftet hab', ist mir auf dem höchsten Punkt oben was Interessantes aufgefall'n.\n\nIch kam nicht nah genug ran, aber ich glaub', es könnte eine von diesen Mogustatuen sein... außer, dass sie sich bewegt hat!\n\nIch schaff's nicht durch diese ganzen fiesen Blutelf'n, aber Ihr seht aus, als hättet Ihr das Zeug dazu.\n\nWürd' es Euch was ausmachen, da hochzuklettern und mir zu bringen, was immer von Interesse sein könnte?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32244] = {title = "Die Korun", objective = "Nehmt dem Spruchwirker der Korun einen Korunkodex ab.", description = "Diese Terrakottawächter sind beängstigend, aber nicht annähernd so furchterregend wie die Geschöpfe, die uns ganz oben in den Ruinen begegnet sind.\n\nEinige Überlebende unter unseren Spähern wollen eine Art Spruchwirker der Mogu auf der höchsten Erhebung im Norden gesehen haben.\n\nEr praktiziert eine Magie, wie wir sie noch nie erlebt haben.\n\nWir müssen möglichst viel über diese Kreatur erfahren. Tötet ihn und bringt mir alles, was Ihr findet.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32246] = {title = "Treffen mit der Späherin", objective = "Sprecht mit Späherin Lynna in der Krasarangbucht in der Krasarangwildnis.", description = "Es ist zwei Monate her, seitdem sich die Nebel gelichtet haben. Späher der Allianz, die nach einem geeigneten Ankerplatz für ihre Flotte suchen, haben die Streitmächte der Horde an einem Strand in der Krasarangwildnis in ein Gefecht verwickelt.\n\nTrefft Euch mit Späherin Lynna, um bei der Eroberung des Landeplatzes zu helfen.", progress = nil, completion = "Ihr kommt gerade rechtzeitig, &lt;Klasse&gt;. König Wrynn wird gleich hier sein, und die volle Kampfkraft unserer Flotte wird schon bald folgen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMeet the Scout: Varian Lands\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][32247] = {title = "Ein König unter den Menschen", objective = "Tötet 25 Mitglieder der Horde und begleitet König Varian Wrynn, um Marschall Trottmann und Hilda Hornsturz zu finden.", description = "Es ist höchste Zeit, wir müssen Trottmann finden und den Strand sichern.\n\nAußerdem sollten wir nach den Zwergen sehen - die Forscherliga ist zäh, ihre Mitglieder sind aber keine Soldaten. Sie sollten sich an der Klippe nördlich von hier aufhalten.\n\nReiten wir los, <Klasse>. Für unsere Freunde. Für die Allianz.", progress = "Die Allianz wird der Schild sein, der Pandaria vor der Horde schützt.", completion = "Ich bin zufrieden mit dieser Stelle. Zeit, die Flotte an Land kommen zu lassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32248] = {title = "Ein wenig Geduld", objective = "Betretet das Szenario Ein wenig Geduld und meldet Euch bei König Varian Wrynn.", description = "König Varian braucht entschlusskräftige Abenteurer, um ihm beim Entscheidungskampf zwischen Tyrande Wisperwind und einer Einheit Hordenkrieger, die sich im Tempel des Roten Kranichs verschanzt haben, zu helfen.\n\nMeldet Euch unverzüglich bei ihm!", progress = nil, completion = "Schön, Euch wiederzusehen, &lt;Name&gt;.\n\nWir haben es hier mit einer heiklen Situation zu tun. Wir müssen unsere nächsten Schritte vorsichtig planen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32249] = {title = "Treffen mit der Späherin", objective = "Sprecht mit Späherin Rokla bei der Landezone der Horde in der Krasarangwildnis.", description = "Es ist zwei Monate her, seitdem sich die Nebel gelichtet haben. Späher der Horde, die nach einem geeigneten Ankerplatz für ihre Flotte suchen, haben die Streitmächte der Allianz auf einer kleinen Insel vor der Küste der Krasarangwildnis in ein Gefecht verwickelt.\n\nTrefft Euch mit Späherin Rokla, um bei der Eroberung des Landeplatzes zu helfen.", progress = nil, completion = "Ihr kommt gerade rechtzeitig. Der Kriegshäupling wird gleich eintreffen. Wenn dieser Ort seiner Inspektion standhält, wird die Flotte folgen.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nMeet the Scout: Garrosh Lands\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][32250] = {title = "Die Macht des Kriegshäuptlings", objective = "Begleitet Garrosh Höllschrei, sucht Blutwache Gro'tash und Grizzle Radflutsch und tötet 25 Mitglieder der Allianz.", description = "Kommt, <Klasse>! Ich möchte diese Insel erkunden und sicherstellen, dass mein Landungstrupp seine Arbeit gemacht hat.\n\nBlutwache Gro'tash sollte irgendwo auf der Nordseite der Insel nach einem geeigneten Ort zur Errichtung unserer Festung suchen. Das Untersuchungsteam der Goblins wird auf der Suche nach Öl zur Ostküste gegangen sein.\n\nMachen wir diesem lächerlichen Schauspiel ein Ende - dieses Land soll der Horde gehören!", progress = "Blutschrei dürstet nach dem Blut der Allianz.", completion = "Gute Arbeit. Niemand kann unsere Präsenz hier verhindern!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32251] = {title = "Ein Dolch im Dunkel", objective = "Betretet das Szenario Ein Dolch im Dunkel und meldet Euch bei Vol'jin.", description = "Schattenjäger Vol'jin hat sich einer Spähergruppe der Kor'kron bei einer wichtigen Mission für den Kriegshäuptling angeschlossen.\n\nEin stolzes Mitglied der Horde wie Ihr kann natürlich gern mitkommen, seid aber gewarnt - es könnte unangenehm werden.", progress = nil, completion = "Schön, dich zu seh'n, Mann. Für diese Mission brauch ich echte Verbündete an meiner Seite.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32256] = {title = "Der Aufstieg eines Reichs", objective = "Findet Kriegshäuptling Höllschrei beim Schrein der Zwei Monde. Sprecht mit Tak-Tak bei der Herrschaftsfeste bezüglich einer Transportmöglichkeit.", description = "Kriegshäuptling Garrosh Höllschrei ist mit einem Trupp seiner besten Elitesoldaten gen Norden ausgeschwärmt.\n\nErstattet ihm von unserer Siegesserie im Kampf gegen die Allianz Bericht.\n\nSprecht mit Tak-Tak bezüglich einer Transportmöglichkeit.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32257] = {title = "Stimme der Götter", objective = "Untersucht den Quecksilberwächter und besorgt die uralte Tafel der Korun.", description = "Zu langsam!? Wir arbeiten für den Kriegshäuptling, so schnell wir nur können!\n\nWir müssen vorsichtig bei den Ausgrabungen vorgehen, jeden Fund einzeln katalogisieren und natürlich auch die Sicherheitsvorschriften befolgen. Das muss er schon verstehen!\n\nNun, möglicherweise haben wir ihm schon bald etwas zu zeigen. Seht Ihr diese Steinstatue im Westen?\n\nWir vermuten, dass es sich bei ihr um ein antikes Steinspeicherbehältnis handelt. Jetzt müssen wir nur noch einen Weg finden, es zu öffnen.\n\nWenn Ihr uns bei unseren Ausgrabungen helfen möchtet, geht bitte vorsichtig vor.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32284] = {title = "Jemand, den Ihr treffen solltet", objective = "Findet Chen Sturmbräu in Binan. Sprecht mit Tak-Tak bei der Herrschaftsfeste bezüglich einer Transportmöglichkeit.", description = "$p? Welch ein Glück, Euch zu finden.\n\nChen Sturmbräu trug mir auf, Euch dies zu überbringen und Euch zu bitten, ihn in Binan am Kun-Lai-Gipfel aufzusuchen.\n\nEr hat einen Freund von Euch gefunden, der einer großen Portion Glück bedarf, um zu genesen.\n\nChen sagt, Ihr sollt mit Tak-Tak sprechen, wenn Ihr schnell reisen wollt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32286] = {title = "Blutsucher der Mogu töten (wandernde Zweirgruppen, die Späher aktiv bekämpfen und Rituale an Leichen durchführen)", objective = "Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32318] = {title = "Regeneration will Weile haben", objective = "Sammelt 10 starke Nadeln.", description = "Vol'jin wäre tot, wenn er kein Troll wäre. Seine Regenerationsfähigkeit ist beeindruckend, aber sie wird durch ein Gift behindert.\n\nWir müssen dieses Gift eliminieren, damit er den Schaden regenerieren kann.\n\nErhebt Euch in die Lüfte und brecht gen Südosten auf. Auf den Gipfeln des Versteckten Horsts werdet Ihr Nadelgeister antreffen. Bringt mir die härtesten ihrer Nadeln, die Ihr finden könnt.\n\nMit ihnen kann ich eine Akupunkturtechnik versuchen, die seinen Körper von dem Gift reinigen und seine Regeneration beschleunigen sollte.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32319] = {title = "Sucht Thrall!", objective = "Spürt Thrall mithilfe von Vol'jins Ruhestein auf.", description = "<Vol'jin öffnet halb ein Auge und bewegt die Lippen, als setze er zu sprechen an. Obwohl er keinen Ton herausbringt, versteht Ihr zwei Worte.>\n\nSucht Thrall.\n\n<Mit Anstrengung drückt Vol'jin Euch einen Ruhestein in die Hände, bevor er ohnmächtig wird.>Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32320] = {title = "Die Horde ist wie eine Familie", objective = "Eskortiert Thrall zu den Echoinseln.", description = "Dieser Ruhestein war Teil einer Übereinkunft, die Vol'jin und ich vor langer Zeit trafen.\n\nEr glaubt, dass sein Volk in Gefahr ist. Ich weiß nicht, was sich in meiner Abwesenheit zugetragen hat, doch dies ist das Mindeste, was ich für einen Freund tun kann.\n\nKommt, $p, begleitet mich zu den Echoinseln. Wir müssen sicherstellen, dass die Dunkelspeere keiner unmittelbaren Bedrohung ausgesetzt sind.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32331] = {title = "Die Kirin Tor", objective = "Tretet durch das Portal zum Purpursalon in der Löwenlandung und trefft Euch mit Anduin Wrynn.", description = "$p, König Varian hat darum gebeten, dass Ihr seinem Sohn nach Dalaran folgt. Er glaubt, dass Ihr dabei helfen könnt, den Rückzug der Blutelfen auszuhandeln.\n\nDiese \"Sonnenhäscher\" sind Teil der Horde und stellen eine große Bedrohung für die Kriegsanstrengungen dar.\n\nJetzt, da unsere Verbündete Jaina Prachtmeer für die Kirin Tor verantwortlich zeichnet, sollte es ein Leichtes sein, sie davon zu überzeugen, die Bedrohung ihrer Stadt durch die Horde zu eliminieren.\n\nBenutzt das Portal hier in der Löwenlandung, um zum Purpursalon zu gelangen, und sichert Prinz Anduin Eure Hilfe zu.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32342] = {title = "Die Geisterfalle", objective = "Sammelt 3 Geisterfallen.", description = "Wir haben mehrere mächtige Artefakte der Mogu in den Ruinen identifizieren können. In ihnen haben sie Geister eingefangen, die sie vermutlich bei einem Ritual oder einer Beschwörung einzusetzen beabsichtigten.\n\nEs handelt sich hier um ein Gerät, das wir bislang nicht identifizieren konnten und dringend erforschen müssen – die Artefakte könnten uns weiteren Aufschluss über die Geistbindungstechniken der Mogu geben. \n\nGeht und sucht ein paar Proben für uns, damit wir sie richtig untersuchen können.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32343] = {title = "Ogudeis Leutnants", objective = "Sammelt Meng-dos Essenz und Gen-lis Essenz in den Ruinen von Ogudei.", description = "Es gibt zwei extrem mächtige Mogugeister, welche die Allianz in ihrem Dilettantismus entfesselt hat.\n\nSie sind die idealen Ziele für uns, <Klasse>. Wenn Ihr sie tötet und die Essenzen beider an Euch nehmt, könnte dies einen großen Fortschritt bei der Entschlüsselung der Geschichte dieser sonderbaren Ruine bedeuten.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32345] = {title = "Wir sind keine Monster!", objective = "Befreit 14 aufgewühlte Sklavengeister.", description = "Die Archäologische Akademie mag in der Vergangenheit einen schlechten Ruf gehabt haben, aber wir sind keine Monster. Wir vertreten lediglich andere Ansichten über die Archäologie als die Forscherliga.\n\nAb und zu widmen wir uns ganz der Vollbringung von Heldentaten. Also geht und befreit ein paar der Sklavengeister der Pandaren in den Ruinen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32346] = {title = "Ich hab' keine Angst vor Gespenstern!", objective = "Tötet 12 geistgebundene Mogu.", description = "Schaut, wir haben hier ein übles Problem, und der alte Trottmann drüben in der Löwenlandung schmeißt uns glatt raus, wenn wir hier nicht bald alles unter Kontrolle kriegen.\n\nHelft uns doch bitte!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32347] = {title = "Räumungsklage", objective = "Tötet 10 beliebige Anhänger der Archäologischen Akademie in den Ruinen von Ogudei.", description = "Diese verdammte Archäologische Akademie hat sich in die Ruinen geschlichen. Sie haben sich im unteren Bereich festgesetzt und treiben da unten allerhand magischen Schabernack.\n\nZeit, dass wir ihnen 'ne Räumungsklage an den Hals hängen, und zwar in Form eines Stiefels im Hinterteil!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32348] = {title = "Tretet sie, wenn sie am Boden liegen", objective = "Tötet 12 Militäreinheiten der Löwenlandung.", description = "Dass sie ihre Basis in solcher Nähe eingerichtet hat, legt nahe, dass die Allianz denkt, sie habe die Ruinen fest in ihrem Würgegriff.\n\nDiese Fehleinschätzung werden wir ihr schon noch austreiben. Los, schaltet ein paar ihrer Wachen aus.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32351] = {title = "Echo des Donners", objective = "Findet Oberhäuptling Baine Bluthuf beim Schrein der Zwei Monde. Sprecht mit Tak-Tak bei der Herrschaftsfeste bezüglich einer Transportmöglichkeit.", description = "Ah, <Name>, so sieht man sich wieder. Ich habe erstaunliche Nachrichten.\n\nOberhäuptling Baine Bluthuf der Tauren ist in Pandaria eingetroffen.\n\nEr ist zu einem Treffen mit Kriegshäuptling Garrosh Höllschrei und dem Lordregenten Lor'themar Theron am Schrein der Zwei Monde im Tal der Ewigen Blüten unterwegs.\n\nEr sandte mir eine seltsame Bitte – ich soll ihm einen treuen Verfechter der Horde schicken, der des Kampfes fähig ist... und der Diskretion.\n\nIch kann mir niemand Besseren als Euch dafür vorstellen. Sprecht mit Tak-Tak, wenn Ihr eine Transportmöglichkeit sucht.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32352] = {title = "Ein Sturm zieht auf", objective = "Nehmt es mit 6 Sha-berührten Grunzern auf.", description = "Wenn General Nazgrim Euch schickt, vertraue ich auf Eure Diskretion.\n\nAls ich hier ankam... experimentierte... Garrosh mit uralter Macht, die er in den Bergen im Norden gefunden hatte.\n\nEr glaubt, dass dieses \"Sha\" unsere Soldaten stärken kann.\n\nLeider legen die Resultate bislang die gegenteilige Wirkung nahe.\n\nUnsere Truppen scheinen ohne Sinn und Verstand gewalttätig zu werden. Geht und verhört sie. Verteidigt Euch, falls sie Euch bedrohen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32362] = {title = "Dalarans Schicksal", objective = "Sprecht mit Jaina Prachtmeer und hört Euch ihre Geschichte an.", description = "Jaina weigert sich, mir zuzuhören. Vater hatte gehofft, ich könnte sie irgendwie beeinflussen, ich glaube jedoch, sie sieht mich immer noch als Kind.\n\nIhr seid aber <ein Held/eine Heldin> der Allianz und ich weiß, dass sie respektiert, was Ihr tut.\n\nGibt es etwas, das Ihr sagen könntet, um sie davon zu überzeugen, dass wir ihre Hilfe brauchen?Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32369] = {title = "Geheimnisse der Vergangenheit", objective = "Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32372] = {title = "Un-Unterwerfung", objective = "Tötet 10 Aufseher der Kor'kron, 5 Unterwerfer der Kor'kron und Gul'tar den Unterwerfer.", description = "Die Kor'kron sind die besten und treuesten Soldaten des Kriegshäuptlings. Ihre Anwesenheit hier bedeutet, dass Garrosh einen Aufstand befürchtet.\n\nVol'jin und sein Volk sind genauso Teil der Horde wie jeder Orc.\n\nWir müssen die Belagerung beenden und die Trolle befreien. Es schmerzt mich, dies zu sagen, aber Ihr müsst so viele der Kor'kron töten, dass die Trolle ihre Stadt zurückerobern können. Danach trefft mich in der Dunkelspeerfeste und wir fordern ihren Offizier direkt heraus.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nSummon Conversation Stalker 2\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][32373] = {title = "Was den Anführer ausmacht", objective = "Sprecht mit Furorion in der Taverne im Nebel.", description = "Die Pandarenkampagne ist inzwischen fortgeschritten. Die Allianz ist mit der versammelten Macht Ihrer Marine an der Küste gelandet. Euer König möchte der Hordeaggression in diesem neuen Land Einhalt gebieten.\n\nGarrosh Höllschrei treibt die Horde geradeheraus in den Kampf, aber König Varian Wrynn kann ich nicht so leicht durchschauen. Habt Ihr einen Augenblick Zeit? Ich würde gern über diesen Anführer von Euch sprechen.", progress = nil, completion = "Ich bin gespannt darauf, zu sehen, wie König Wrynn auf die Situation reagiert.\n\nNoch neugieriger bin ich allerdings darauf, zu erfahren, wozu IHR in der Lage seid. Lasst es uns herausfinden...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32374] = {title = "Prinzliches Anliegen", objective = "Tötet Hordetruppen entlang der südlichen Küsten der Krasarangwildnis bis Ihr beim Schwarzen Prinz einen respektvollen Status erreicht.", description = "Mein Ziel ist das schnelle Ende dieses kostspieligen Krieges. Beweist mir, dass die Allianz es verdient, zu gewinnen. Zeigt mir Euer Können auf dem Schlachtfeld.\n\nIhr werdet nicht gegen eine abstrakte Macht wie das Sha kämpfen, sondern Euren Gegnern direkt gegenüberstehen.\n\nWerdet Ihr siegen?", progress = nil, completion = "Hervorragend! Selbst im Chaos des Kampfes habt Ihr bewiesen, dass jede einzelne Person einen Unterschied machen kann. Die Horde hat lernen müssen, dass ihre Taten in Pandaria auf Widerstand treffen werden.\n\nIch glaube, es ist an der Zeit für eine anspruchsvollere Aufgabe...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32376] = {title = "Auf ins Tal!", objective = "Findet Euren \"Freund aus Silbermond\" im Tal der Kaiser. Sprecht mit Tak-Tak bei der Herrschaftsfeste bezüglich einer Transportmöglichkeit.", description = "Diese versiegelte Nachricht wurde für Euch geschickt, zusammen mit dem dringenden Befehl, ins Tal der Kaiser auf dem Kun-Lai zu reisen.\n\nEs scheint ernst zu sein. Ich an Eurer Stelle würde nicht zögern.\n\nSprecht mit Tak-Tak bezüglich einer Transportmöglichkeit.Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nBegin Day E Questing"}
MultiLanguageQuestData['de'][32378] = {title = "Den Weg bereiten", objective = "Tötet 10 Korunmogu.", description = "Eins nach dem anderen. Wenn wir den Anführer gefangen nehmen wollen, müssen wir die Zahl seiner Agenten verringern.\n\nSeid vorsichtig. Diese Mogu sind besonders gefährlich – es scheint, als ob sie das Sha in einer uns bisher unbekannten Weise beeinflussen können.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][32379] = {title = "Das Erbe der Korun", objective = "Findet das Dokument 'Das Vermächtnis der Korun' im Tal der Kaiser und besorgt das versiegelte Artefakt der Korun und die Korunbefehle von den Mogu der Korun.", description = "Ich bin nicht bereit, noch mehr unseres Volkes im Kampf gegen einen Feind, den wir weder kennen noch verstehen, zu opfern.\n\nSchaut bitte, ob ihr in diesem Gebiet irgendwelche Hinweise findet, die besagen, wer diese \"Korunmogu\" sind. Nur für den Fall, dass der Einsatz nicht wie geplant abläuft.Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][32380] = {title = "Der Beste hier", objective = "Meldet Euch bei Geheimagentin Townsley in Bizmos Boxbar auf der Sturmwindseite der Tiefenbahn.", description = "Wir werden Hilfe benötigen, wenn wir herausfinden wollen, was Garrosh mit Pandaria vorhat.\n\nIch denke da an jemand Bestimmten, aber er wird nicht leicht zu überzeugen sein.\n\nAgent Connelly glaubt zwar, er sei im Ruhestand, aber den SI:7 verlässt man nicht einfach so. Schon seit Monaten folgt ihm einer unserer Geheimagenten.\n\nMomentan tarnt er sich als ein Profiglücksspieler in Bizmos Boxbar. Hat irgendetwas mit der Begleichung einer alten Rechnung zu tun.\n\nTrefft Euch mit unserem Geheimagenten in der Kampfgilde.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32381] = {title = "Wie man einen Spion fängt", objective = "Bringt das rosarote Murmeltier, die Mogumelonenüberraschung und den rostigen Dolch zu den richtigen Gästen.", description = "Nun, ich könnte Euch sagen, wer Connelly ist, aber das wäre zu einfach! Um einen Spion zu erwischen, müsst Ihr wie ein Spion denken.\n\nZunächst müsst Ihr den Test bestehen!\n\nDie kleinsten Dinge können viel über eine Person aussagen. Der Teufel steckt im Detail.\n\nIch werde Euch ein Getränk geben, das Ihr serviert. Ich werde Euch ein kleines Detail darüber verraten, was der Empfänger trägt. Alles andere liegt an Euch.\n\nSeid vorsichtig, wem Ihr etwas zu trinken gebt. Die Leute hier können ziemlich ungehalten werden, wenn Ihr ihnen das falsche Getränk hinstellt!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32382] = {title = "Perfekt getarnt", objective = "Trefft Connelly auf dem Kun-Lai-Gipfel. Sprecht mit Fennie Hornsturz in der Löwenlandung bezüglich einer Transportmöglichkeit.", description = "Agent Connelly konnte Garroshs Lager auf dem Kun-Lai-Gipfel infiltrieren und beobachtet alles, was dort vor sich geht! \n\nEr hat spezifisch nach Euch gefragt, um ihm bei der Beschaffung wichtiger Informationen zu helfen.\n\nEr hat eine Tarnung für Euch geschickt. Vergesst nicht, sie anzulegen, bevor Ihr Euch dem Lager nähert! Es wird ganz gewiss schwer bewacht.\n\nEr ist sich sicher, dass Ihr ihn erkennen werdet, wenn Ihr ihn seht. Sagte, Ihr hättet ein scharfes Auge fürs Detail...\n\nSprecht mit Fennie dort drüben und sie bringt Euch hin.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32383] = {title = "Verwanzt", objective = "Verwanzt das große Zelt in der Nähe der kleinen Zelte sowie die Vorräte mit clever getarnten Wanzen.", description = "Ich habe einige Wanzen im Lager verteilt, aber mehr schaden nie.\n\nIch habe sie so getarnt, dass sie wie Statuen aussehen. Zwischen all den anderen Artefakten fallen sie überhaupt nicht auf.\n\nEure Tarnung sollte es Euch ermöglichen, Euch frei im Lager zu bewegen. Bleibt nur dem Hund fern und haltet Euch nicht in Garroshs Nähe auf! Nero und Garrosh werden Eure Tarnung durchschauen!\n\nIch kann Euch nicht helfen, wenn Ihr erwischt werdet. Ich darf die Mission nicht gefährden!Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nTrigger Connelly Farewell\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][32384] = {title = "Den Anführer gefangen nehmen", objective = "Schwächt und ergreift Shan Kien am Grab der Schatten am Kun-Lai-Gipfel.", description = "Gut, es ist an der Zeit, zuzuschlagen. Geht zum Grab der Schatten, schwächt ihn und nehmt ihn gefangen.\n\nIch bleibe hier, falls Garrosh eintrifft. Ich werde versuchen, ihn aufzuhalten, sodass wir unsere Beute an uns nehmen können, bevor er sie zerstört.\n\nBeeilt Euch!Bei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][32388] = {title = "Führungswechsel", objective = "Tötet Kriegsfürst Blutheft in der Herrschaftsfeste in der Krasarangwildnis. Ihr werdet eine Gruppe benötigen.", description = "Es gibt einen General der Orcs, den ich schon länger beobachte. Kriegsfürst Blutheft hat sich bei Garrosh Höllschrei eingeschmeichelt, indem er einen Vorstoß der Allianz im Südlichen Brachland zurückgeschlagen hat. Jetzt hat er sich in der Herrschaftsfeste verschanzt.\n\nIch bezweifle, dass die Allianz ihn besiegen kann. Aber... Ihr habt mich schon einmal eines Besseren belehrt.\n\nWenn Ihr ihn ausschalten wollt, bringt Freunde mit. Viele Freunde.", progress = nil, completion = "&lt;Furorion grinst.&gt;\n\nIhr wurdet auf die Probe gestellt, &lt;Klasse&gt;. Ich wusste, dass Ihr allein große Dinge bewerkstelligen könnt.\n\nAber jetzt habt Ihr mir bewiesen, dass Ihr ein wahrer Anführer seid, der inmitten eines Schlachtfelds eine Gruppe von Fremden zu leiten vermag.\n\nDie Allianz kann sich glücklich schätzen, Euch zu haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32389] = {title = "Der Löwe brüllt", objective = "Gewinnt Kämpfe im Tempel von Katmogu und in der Silberbruchmine.", description = "Dies ist ein weltweiter Krieg, <Name>. Er ist bis nach Pandaria gelangt und hat Krisenherde in Kalimdor und den Östlichen Königreichen in Brand gesetzt. Wie verhaltet Ihr Euch in einem organisierten Kampf? Das würde ich gern selbst sehen.\n\nIch erwarte Euren Bericht von der Front.", progress = nil, completion = "&lt;Furorions Augen leuchten glühend rot während er gierig den Berichten Eurer Heldentaten auf den Schlachtfeldern lauscht.&gt;\n\nOhh... oh! Unglaublich! Im Schlachtgetümmel zeigt sich das wahre Herz eines Kämpfers.\n\nIhr enttäuscht nicht, &lt;Name&gt;.\n\nGenauso wenig wie die Allianz.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32390] = {title = "Der Ruf des Rudelführers", objective = "Sprecht mit Furorion.", description = "<Klasse>, durch Eure Augen konnte ich die Kämpfe entlang der Küste und den epischen Verlauf der Gefechte in der ganzen Welt verfolgen. Ihr wart sehr geduldig... und habt mir viele Informationen geliefert.\n\nAußerdem habe ich Euren König im Auge behalten. Wollt Ihr wissen, was ich erfahren habe?", progress = nil, completion = "&lt;Ein seltsamer Apparat befindet sich in einer mit Seide ausgekleideten Truhe. Es scheint, als ob man ihn als zusätzliche Verbesserung an Eurer Sha-berührten Waffe befestigen kann. Der leere Sockel ist beunruhigend – es fühlt sich an, als ob er Euch anstarren würde. Ein einzelnes, hohles, wertendes Auge...&gt;", rewards = "Ihr bekommt:\n\nAuge des Schwarzen Prinzen"}
MultiLanguageQuestData['de'][32397] = {title = "Es wird ihm gar nicht auffallen", objective = "Sorgt für eine Ablenkung im Lager und stehlt das verwitterte Tagebuch.", description = "Ich habe beobachtet, wie Garrosh und dieser Blutelf von der Archäologischen Akademie eine Art Tagebuch mit sich herumtragen.\n\nDas Tagebuch ist immer in Reichweite. Es muss wichtig sein!\n\nWenn Ihr es schafft, für eine entsprechende Ablenkung zu sorgen, könnt Ihr das Tagebuch vielleicht vom Tisch stehlen.\n\nDiese Yaks könnten die Lösung sein: Gebt einem von ihnen einen Klaps und den Rest machen sie dann schon allein.\n\nIhr müsst nur bereit sein, schnell zu handeln!Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nTrigger Connelly Farewell\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][32411] = {title = "Die verbleibenden Sonnenhäscher", objective = "Wendet die Träne der Sin'dorei auf Uda das Biest, den Hocharkanisten Savor, Magister Hathorel, Magister Surdiel und Magistrix Vesara an.", description = "Es werden noch immer einige wichtige Vertreter der Sonnenhäscher vermisst. Es wäre gut möglich, dass man sie in Sonnenhäschers Zuflucht überrascht hat.\n\n<Rommath überreicht Euch ein offensichtlich von Blutelfenhand gefertigtes Artefakt.>\n\nDort wimmelt es nur so vor Truppen des Silberbunds. Ihr müsst Euch Zutritt verschaffen, die Träne benutzen, um diese wichtigen Persönlichkeiten zu evakuieren, und dann fliehen.\n\nBleibt am Leben, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32426] = {title = "Gerührt, nicht geschüttelt", objective = "Findet Professor Kilt in der V.I.P.-Lounge von Bizmos Boxbar.", description = "Also gut, ich werde Euch sagen, wie Ihr Connelly findet.\n\nAgent Connelly gibt sich derzeit als der Profiglücksspieler Professor Kilt aus. Er verbringt die meiste Zeit in Bizmos V.I.P.-Lounge. Man sagt, dass er wegen eines längst vergessenen Verrats hinter einem der Kämpfer her ist.\n\nLeider wird man nur auf Einladung in diesen Raum eingelassen. Doch wie es der Zufall so will, habe ich eine solche.\n\nVersucht, nicht unnötig Aufmerksamkeit zu erregen, wenn Ihr die Türsteher passiert. Falls man Euch schnappt... diese Einladung kommt nicht von mir.\n\nWas mich betrifft, haben wir uns überhaupt nie getroffen!Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nConnelly beschwören\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][32427] = {title = "Was den Anführer ausmacht", objective = "Sprecht mit Furorion in der Taverne im Nebel.", description = "Jetzt beginnt ein neuer Teil des Pandarenfeldzugs für uns. Euer Kriegshäuptling plant, die Pandaren mit der ganzen Macht des Heers der Horde zu beeindrucken. Er wird seinen Anspruch auf die Ressourcen dieses Landes erheben, sei es mit der Hilfe der Pandaren oder ohne sie.\n\nIch verstehe die Ziele Eures Anführers, aber ich möchte gern den Kriegshäuptling selbst verstehen. Was treibt ihn an? Und was will die Horde letztendlich wirklich erreichen? Ich würde mich gern mit Euch über Euren Anführer unterhalten.", progress = nil, completion = "Wie alle großen Anführer hat auch Garrosh sich hohe Ziele gesteckt. Doch wozu ist er letztendlich in der Lage?\n\nWichtiger noch, wozu seid IHR in der Lage? Das jüngste Blutvergießen an der Küste wird uns Gelegenheit geben, genau das herauszufinden...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32428] = {title = "Pandarischer Geisterzähmer", objective = "Besiegt sämtliche Pandarengeister in einem Haustierkampf.", description = "Die Sagen erzählen von legendären Pandarengeistern, die Pandaria durchstreifen. Spürt sie auf und besiegt sie in einem Haustierkampf.", progress = nil, completion = "Ich kann nicht fassen, dass Ihr diese Geister ausgeschaltet habt!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nPandarischer LuftgeistPandarischer ErdgeistPandarischer FeuergeistPandarischer Wassergeist\n\nIhr bekommt außerdem:\n\nGeringes Amulett des GlücksTapferkeitspunkte"}
MultiLanguageQuestData['de'][32429] = {title = "Prinzliches Anliegen", objective = "Tötet Allianztruppen entlang der südlichen Küsten der Krasarangwildnis bis Ihr beim Schwarzen Prinz einen respektvollen Status erreicht.", description = "Mein Ziel ist ein schnelles Ende dieses kostspieligen Krieges. Beweist mir, dass die Horde den Sieg verdient. Demonstriert mir Euer Können auf dem Schlachtfeld.\n\nIhr habt es hier nicht mit einer abstrakten Macht wie dem Sha zu tun: Ihr steht Eurem Feind Angesicht zu Angesicht gegenüber.\n\nWerdet Ihr triumphieren?", progress = nil, completion = "Wunderbar! Ihr habt bewiesen, dass selbst in der Hitze des Gefechts jeder Einzelne einen Unterschied machen kann. Die Allianz gerät angesichts der Macht der Horde ins Wanken, doch ihr König bleibt standhaft.\n\nIch glaube, es ist Zeit für eine anspruchsvollere Herausforderung...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32430] = {title = "Führungswechsel", objective = "Tötet Hochmarschall Doppelzopf in der Löwenlandung in der Krasarangwildnis. Ihr werdet dafür eine Gruppe brauchen.", description = "Es gibt da einen Zwerg der Allianz, den ich beobachtet habe. Hochmarschall Doppelzopf hat sich im Südlichen Brachland als Ärgernis erwiesen, als er sich nach dem Verlust von Bael Modan gegen die Horde zur Wehr setzte. Jetzt hat er sich in der Festung der Allianz in der Löwenlandung verschanzt und hilft dabei, die Krasaranggegenoffensive zu orchestrieren.\n\nNur eine Gruppe legendärer Helden der Horde kann ihn besiegen.\n\nWenn Ihr ihn aus dem Weg schaffen wollt, bringt Freunde mit. Jede Menge Freunde.", progress = nil, completion = "&lt;Furorion grinst.&gt;\n\nMan hat Euch auf die Probe gestellt, &lt;Klasse&gt;. Ich wusste, dass Ihr allein in der Lage zu großen Taten seid.\n\nDoch dass Ihr Euch inmitten der tobenden Schlacht die Unterstützung einer Gruppe von Fremden sichern konntet, soll mir als Beweis für Eure herausragenden Führungsqualitäten gelten.\n\nDie Horde kann sich glücklich schätzen, Euch zu haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32431] = {title = "Ruhm der Horde", objective = "Gewinnt Kämpfe beim Tempel von Katmogu und in der Silberbruchmine.", description = "Dies ist ein weltweiter Krieg, <Name>. Er ist bis nach Pandaria gelangt und hat Krisenherde in Kalimdor und den Östlichen Königreichen in Brand gesetzt. Wie verhaltet Ihr Euch in einem organisierten Kampf? Das würde ich gern selbst sehen.\n\nIch erwarte Euren Bericht von der Front.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32432] = {title = "Die Seele der Horde", objective = "Sprecht mit Furorion.", description = "<Klasse>, durch Eure Augen wurde ich Zeuge der Kämpfe an der Küste und der epischen Schlachten überall auf der Welt. Ihr habt Euch als sehr geduldig... und äußerst informativ erwiesen.\n\nAuch Garrosh Höllschrei habe ich fest im Auge behalten. Würdet Ihr gerne hören, was ich dabei erfahren habe?Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAuge des Schwarzen Prinzen"}
MultiLanguageQuestData['de'][32434] = {title = "Brennender Pandarengeist", objective = "Besiegt den brennenden Pandarengeist in einem Haustierkampf.", description = "Ihr seid zurück! Wollt Ihr noch einmal gegen mich antreten?", progress = nil, completion = "Nächstes Mal werde ich Euch besiegen.", rewards = "Ihr bekommt:\n\nPandarischer Geisterbeutel mit HaustierbedarfTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32435] = {title = "Zweiter Platz", objective = "Heute gibt es einen Wettbewerb für Extremangler! Seid eine der ERSTEN DREI PERSONEN, die mir 40 Leckerfische aus den Fischschwärmen der Gewässer des Schlingendorntals bringen und Ihr gewinnt einen Preis!\n\nFalls Ihr nicht einer der ersten drei seid, die mir 40 Fische bringen, wird Euch mein Lehrling hier dennoch mit Geld für jeden Stapel von 5 Leckerfischen belohnen.\n\nOh und beeilt Euch, Leckerfische werden schnell schlecht!", description = nil, progress = "Heute gibt es einen Wettbewerb für Extremangler! Seid eine der ERSTEN DREI PERSONEN, die mir 40 Leckerfische aus den Fischschwärmen der Gewässer des Schlingendorntals bringen und Ihr gewinnt einen Preis!\n\nFalls Ihr nicht einer der ersten drei seid, die mir 40 Fische bringen, wird Euch mein Lehrling hier dennoch mit Geld für jeden Stapel von 5 Leckerfischen belohnen.\n\nOh und beeilt Euch, Leckerfische werden schnell schlecht!", completion = "Beeilt Euch und reicht die Fische ein, wenn Ihr Zweiter werden wollt! Ich stehe hier schon seit STUNDEN ohne etwas zu essen! Gebt mir die Viecher schon her!", rewards = "Auf Euch wartet eine dieser Belohnungen:\n\nSchreckenspiratenringStiefel der BuchtExtremgetestete Eterniumangelschnur\n\nIhr bekommt außerdem:\n\n"}
MultiLanguageQuestData['de'][32436] = {title = "Dritter Platz", objective = "Heute gibt es einen Wettbewerb für Extremangler! Seid eine der ERSTEN DREI PERSONEN, die mir 40 Leckerfische aus den Fischschwärmen der Gewässer des Schlingendorntals bringen und Ihr gewinnt einen Preis!\n\nFalls Ihr nicht einer der ersten drei seid, die mir 40 Fische bringen, wird Euch mein Lehrling hier dennoch mit Geld für jeden Stapel von 5 Leckerfischen belohnen.\n\nOh und beeilt Euch, Leckerfische werden schnell schlecht!", description = nil, progress = "Heute gibt es einen Wettbewerb für Extremangler! Seid eine der ERSTEN DREI PERSONEN, die mir 40 Leckerfische aus den Fischschwärmen der Gewässer des Schlingendorntals bringen und Ihr gewinnt einen Preis!\n\nFalls Ihr nicht einer der ersten drei seid, die mir 40 Fische bringen, wird Euch mein Lehrling hier dennoch mit Geld für jeden Stapel von 5 Leckerfischen belohnen.\n\nOh und beeilt Euch, Leckerfische werden schnell schlecht!", completion = "Beeilt Euch und reicht die Fische ein, wenn Ihr den dritten und letzten Preis ergattern wollt! Ich stehe hier schon seit STUNDEN ohne etwas zu essen! Gebt mir die Viecher schon her!", rewards = "Ihr bekommt:\n\nExtremgetestete Eterniumangelschnur"}
MultiLanguageQuestData['de'][32439] = {title = "Fließender Pandarengeist", objective = "Besiegt den fließenden Pandarengeist in einem Haustierkampf.", description = "Ihr seid zurück! Wollt Ihr noch einmal gegen mich antreten?Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nPandarischer Geisterbeutel mit HaustierbedarfGeringes Amulett des GlücksTapferkeitspunkte"}
MultiLanguageQuestData['de'][32440] = {title = "Flüsternder Pandarengeist", objective = "Besiegt den flüsternden Pandarengeist in einem Haustierkampf.", description = "Ihr seid zurück! Wollt Ihr noch einmal gegen mich antreten?", progress = nil, completion = "Nächstes Mal werde ich Euch besiegen.", rewards = "Ihr bekommt:\n\nPandarischer Geisterbeutel mit HaustierbedarfTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32441] = {title = "Bebender Pandarengeist", objective = "Besiegt den bebenden Pandarengeist in einem Haustierkampf.", description = "Ihr seid zurück! Wollt Ihr noch einmal gegen mich antreten?", progress = nil, completion = "Nächstes Mal werde ich Euch besiegen.", rewards = "Ihr bekommt:\n\nPandarischer Geisterbeutel mit HaustierbedarfGeringes Amulett des GlücksTapferkeitspunkte"}
MultiLanguageQuestData['de'][32446] = {title = "Bitte auseinandernehmen", objective = "Zerstört mit der rekonfigurierten Fernsteuerung die Dschungelschredder und sammelt dann 6 Stücke Metallschrott.", description = "Die Schredder werden dort unten zu einem Problem, <Klasse>.\n\nWir haben die Mecha-Stampfer geschickt, aber das reicht leider nicht aus. Sie werden schneller beschädigt, als wir sie reparieren können!\n\nIch habe zufällig während einer Aufklärungsmission diese seltsame Fernbedienung gefunden. Ich glaube, wir können sie gebrauchen, wenn die Einstellungen ein wenig geändert werden.\n\nSetzt sie versuchsweise gegen die Dschungelschredder ein. Hoffentlich können sie damit zerstört werden. Wenn ja, bringt mir bitte das Altmetall mit.", progress = "Wie genau funktioniert die Fernsteuerung?", completion = "Von Goblins konstruierte Geräte lassen zu Wünschen übrig, aber es muss ausreichen. Gute Arbeit, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32449] = {title = "Die Ruinen von Ogudei", objective = "Meldet Euch bei Bellok Leuchtklinge im Außenposten Zündmine.Unsere Späher am Außenposten Zündmine haben neue Aktivitäten in der Nähe eines Gebiets gemeldet, das die Ruinen von Ogudei genannt wird.\n\nWir müssen Informationen darüber sammeln, was die Allianz tut und - wichtiger noch - was sie gefunden hat. Wir können uns keine unbekannten Faktoren leisten.\n\nTrefft Euch mit Bellok Leuchtklinge im Außenposten Zündmine und findet heraus, was er weiß.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Unsere Späher am Außenposten Zündmine haben neue Aktivitäten in der Nähe eines Gebiets gemeldet, das die Ruinen von Ogudei genannt wird.\n\nWir müssen Informationen darüber sammeln, was die Allianz tut und - wichtiger noch - was sie gefunden hat. Wir können uns keine unbekannten Faktoren leisten.\n\nTrefft Euch mit Bellok Leuchtklinge im Außenposten Zündmine und findet heraus, was er weiß.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32450] = {title = "Jetzt oder nie!", objective = "Meldet Euch bei Schattenmeisterin Kiryn im Außenposten Zündmine.Jetzt greifen wir sie an, <Klasse>!\n\nMeldet Euch bei Schattenmeisterin Kiryn im Außenposten Zündmine. Sie wird Euch Eure Befehle erteilen.\n\nJetzt wird sich zeigen, wie sie damit umgehen, wenn die Horde mit ganzer Macht ihre kostbare Festung stürmt!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Jetzt greifen wir sie an, <Klasse>!\n\nMeldet Euch bei Schattenmeisterin Kiryn im Außenposten Zündmine. Sie wird Euch Eure Befehle erteilen.\n\nJetzt wird sich zeigen, wie sie damit umgehen, wenn die Horde mit ganzer Macht ihre kostbare Festung stürmt!Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32451] = {title = "Eine Nachricht senden", objective = "Meldet Euch bei Himmelsadmiralin Rogers an Bord der Himmelsfeuer in der Krasarangwildnis.", description = "Zeit, dass wir diesen Mistkerlen von der Horde die ganze Stärke der Allianz zeigen! Heute bringen wir den Kampf an ihre Tore.\n\nMeldet Euch bei Admiralin Rogers an Bord der Himmelsfeuer. Sie wird Euch weitere Anweisungen erteilen.\n\nViel Glück da draußen, <Klasse>. Macht der Allianz Ehre!", progress = nil, completion = "Die Schlacht hat bereits begonnen, &lt;Klasse&gt;. Begeben wir uns hinaus!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32452] = {title = "Und dann gab's Goblins", objective = "Meldet Euch bei Himmelsadmiralin Rogers an Bord der Himmelsfeuer in der Krasarangwildnis.", description = "Wir führen Krieg an allen Fronten, <Klasse>. Sogar Pandaria selbst braucht unseren Schutz.\n\nDie Bilgewässer Goblins zerstören Land, das nicht ihnen gehört. Sie müssen aufgehalten werden!\n\nMeldet Euch bei Himmelsadmiralin Rogers auf der Himmelsfeuer. Ihr Aussichtspunkt sollte ihr einen besseren Überblick darüber verschaffen, wo die Schwachstellen sind.", progress = nil, completion = "War auch Zeit, dass wir uns um dieses Ärgernis gekümmert haben. Jemand muss diesen Bilgewässer Kümmerlingen eine Lektion erteilen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32457] = {title = "Der Donnerkönig", objective = "Kontaktiert Furorion im zweiten Stock der Taverne im Nebel an der Verhüllten Treppe.", description = "Wisst Ihr, was sich am Kun-Lai-Gipfel ereignet hat? Die Zandalari sind in Scharen an der Nordküste gelandet und haben mit dem Erneuern alter Bündnisse begonnen. Zu diesem Zweck haben sie den Donnerkönig wiederbelebt.\n\nSelbst bei den Mogu ruft der Name des ersten Herrschers Angst und Schrecken hervor. Der Donnerkönig errichtete ein riesiges Reich der Sklaverei und des Leidens... doch auch der Macht, des Reichtums und der Pracht.\n\nWir werden ihm bald im Kampf gegenüberstehen. Kommt zu mir, wenn Eure Fraktion ihren nächsten Zug macht.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32458] = {title = "Mit dem Segen des Windes...", objective = "Sammelt Amulette des Glücks.", description = "<Eine dringende Bitte kommt Euch zu Ohren.>\n\n<Name>! Die Flotte meines Vaters ist nach Pandaria unterwegs. Bei gutem Wind könnte sie jeden Augenblick eintreffen.\n\nDie Pandaren haben einen Segen, der uns Glück mit dem Wetter gewähren und die Reise unserer Schiffe zu diesen Gefilden beschleunigen wird. Damit uns das Glück hold ist, müssen wir nichts weiter als Amulette des Glücks sammeln.\n\nJe näher unsere Schiffe der Insel kommen, umso weniger Amulette werden nötig sein. Doch wenn Ihr genug davon habt, können wir sie direkt hierher bringen...", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][32459] = {title = "Mit dem Segen des Windes...", objective = "Sammelt Amulette des Glücks.", description = "<Eine dringende Bitte kommt Euch zu Ohren.>\n\n<Name>! Die Flotte der Horde ist nach Pandaria unterwegs. Bei gutem Wind könnte sie jeden Augenblick landen.\n\nDie Pandaren haben einen Segen, der uns Glück mit dem Wetter gewähren und die Reise unserer Brüder und Schwestern zu diesen Gefilden beschleunigen wird. Damit uns das Glück hold ist, müssen wir nichts weiter als Amulette des Glücks sammeln.\n\nJe näher unsere Schiffe der Insel kommen, umso weniger Amulette werden nötig sein. Doch wenn Ihr genug davon habt, können wir sie direkt hierher bringen...", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][32461] = {title = "Der Orden der Wolkenschlange", objective = "Sprecht mit Ausbilder Himmelsdorn im Arboretum im Jadewald.", description = "Ahhh, Ihr seid jetzt also <stolzer Besitzer/stolze Besitzerin> einer majestätischen Wolkenschlange.\n\nEhe Ihr Euch auf dem Rücken dieser mächtigen Kreatur in die Lüfte erheben könnt, müsst Ihr die Fertigkeit sie zu reiten erwerben.\n\nDer Orden der Wolkenschlange kann Euch das gewünschte Wissen lehren.\n\nWenn Ihr unserem Weg zu folgen wünscht, sprecht mit Ausbilder Himmelsdorn im Arboretum im Jadewald.\n\nIch wünsche Euch Glück, <Volk>.", progress = nil, completion = "Ah, Ihr möchtet Euch unserem Orden anschließen?", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32474] = {title = "Tapferkeitsbeweis", objective = "Erlangt den Erfolg \"Tapferkeitsbeweis\", indem Ihr insgesamt 1600 Tapferkeitspunkte verdient.", description = "<Ohne Vorwarnung schneidet sich Furorion in den Daumen und drückt ihn an Eure Stirn. Sein Blut brennt bei der Berührung, verschwindet jedoch schnell in Eurer Haut.>\n\nSo! Mein Auge wacht nun über Euch, <Klasse>. Ich beobachte Euch.\n\nDie Pandaren wissen das Konzept der \"Tapferkeit\" genauso zu schätzen wie die Allianz. Auf diesem Kontinent gibt es viele Möglichkeiten, Euch würdig zu erweisen - von alltäglichen Aufgaben bis hin zum Bezwingen heroischer Gegner in ihrem Versteck. Ich überlasse es Euch, Euren eigenen Weg zu wählen.\n\nBeweist mir Euren Mut, <Name>!", progress = nil, completion = "&lt;Furorion nickt langsam.&gt;\n\nJa. &lt;Name&gt;. Ich habe Eure Taten verfolgt und war höchst beeindruckt.\n\nIhr seid wahrlich ein Bote der Änderung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32476] = {title = "Tapferkeitsbeweis", objective = "Erlangt den Erfolg \"Tapferkeitsbeweis\", indem Ihr insgesamt 1600 Tapferkeitspunkte verdient.", description = "<Ohne Vorwarnung schneidet sich Furorion in den Daumen und drückt ihn an Eure Stirn. Sein Blut brennt bei der Berührung, verschwindet jedoch schnell in Eurer Haut.>\n\nSo! Mein Auge wacht nun über Euch, <Klasse>. Ich beobachte Euch.\n\nDie Pandaren wissen das Konzept der \"Tapferkeit\" genauso zu schätzen wie die Horde. Auf diesem Kontinent gibt es viele Möglichkeiten, Euch würdig zu erweisen - von alltäglichen Aufgaben bis hin zum Bezwingen heroischer Gegner in ihrem Versteck. Ich überlasse es Euch, Euren eigenen Weg zu wählen.\n\nBeweist mir Euren Mut, <Name>!", progress = nil, completion = "&lt;Furorion nickt langsam.&gt;\n\nJa. &lt;Name&gt;. Ich habe Eure Taten verfolgt und war höchst beeindruckt.\n\nIhr seid wahrlich ein Bote der Änderung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32496] = {title = "Entweiht dieses Feuer!", objective = "Der folgende Zauber wird auf euch gewirkt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nFreudenfeuer ausstampfen\n\nIhr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][32497] = {title = "Ehrt die Flamme", objective = "Ehrt das Sonnenwendfreudenfeuer in der Schreckensöde.", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, <Name>?Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVerehrung der Flamme\n\nIhr bekommt:\n\nBrandblüte"}
MultiLanguageQuestData['de'][32498] = {title = "Ehrt die Flamme", objective = "Ehrt das Sonnenwendfreudenfeuer im Jadewald.", description = "Das Sonnenwendfest ist eine Zeit, um die Elemente zu ehren. Das Element des Feuers entfacht die Leidenschaft in uns allen. Oft schlagen diese Leidenschaften in Aggressivität um. Aber hier in diesem Land setzen wir unsere Leidenschaft in Ehrerbietung um.\n\nWir werden die Flamme ehren, wie es die Tradition verlangt. Werdet Ihr die Flamme mit uns ehren, <Name>?Der folgende Zauber wird auf euch gewirkt:\n\n", progress = nil, completion = nil, rewards = "Der folgende Zauber wird auf euch gewirkt:\n\nVerehrung der Flamme\n\nIhr bekommt:\n\nBrandblüte"}
