MultiLanguageQuestData['de'][32603] = {title = "Fabelhafte Wesen", objective = "Besiegt die Elite-Kampfhaustiere der pandarischen Fabelwelt.", description = "Habt Ihr je das große Buch der pandarischen Fabeln gelesen? Die Pandaren reichen diese Geschichten an ihre Kinder weiter – die Geschichte von der Grille und dem Falken, oder der langsamen Schildkröte – um sie Lektionen zu lehren, die ihnen in ihrem späteren Leben von Nutzen sein werden. Was nur wenige Kinder wissen ist, dass es diese Kreaturen wirklich gibt, hier in Pandaria! Obwohl die Geschichten ihrer Reisen erfunden sind, sind sie doch mächtige Bewohner dieser Welt. Solltet Ihr ihnen auf Euren Reisen begegnen, könnt Ihr die Macht Eurer Haustiere gegen diese sagenumwobenen Gestalten auf die Probe stellen.", progress = nil, completion = "Ihr habt sie alle gefunden? Unglaublich! Die Geschichten sind also doch wahr! Vielleicht werdet Ihr ja die nächste große pandarische Fabel schreiben, über Eure eigene unglaubliche Reise!", rewards = "Ihr bekommt:\n\nRoter PandaTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32604] = {title = "Fabelhafte Wesen, Buch I", objective = "Besiegt Ka'wi den Schlinger, Nitun, Kafi und Dos-Ryga.", description = "Die Geschichten von Ka'wi dem Schlinger, Nitun, Kafi und Dos-Ryga werden in diesem Land immer präsent bleiben. Möchtet Ihr ihnen noch einmal im Kampf begegnen?", progress = nil, completion = "Ich verneige mich vor Euch, die weiterhin auf den Spuren der großen pandarischen Fabeln wandelt.", rewards = "Ihr bekommt:\n\nBerühmter pandarischer HaustierbedarfGeringes Amulett des GlücksTapferkeitspunkte"}
MultiLanguageQuestData['de'][32618] = {title = "Lernt Reiten", objective = "Findet Randal Weidmann.", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Randal Weidmann im Holzfällerlager des Osttals im Wald von Elwynn. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", progress = nil, completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt Katie Weidmann hier im Lager finden.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32661] = {title = "Lernt Reiten", objective = "Findet Aalun.", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Aalun am Eingang zur Exodar auf der Azurmythosinsel. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", progress = nil, completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Torallius ist gleich dort drüben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32662] = {title = "Lernt Reiten", objective = "Findet Ultham Eisenhorn.", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Ultham am Gehöft Bernruh in Dun Morogh, an der östlichen Straße aus Eisenschmiede heraus. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", progress = nil, completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Veron Bernruh steht direkt vorm Tor des Gehöfts.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32663] = {title = "Lernt Reiten", objective = "Findet Binjy Federpfiff.", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Binjy Federpfiff bei Stahlrosts Depot in Dun Morogh. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", progress = nil, completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Milli befindet sich gleich dort drüben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32664] = {title = "Lernt Reiten", objective = "Findet Jartsam.", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Jartsam in der Enklave des Cenarius in Darnassus. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", progress = nil, completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es direkt hier bei Lelanai erwerben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32665] = {title = "Lernt Reiten", objective = "Findet Mei Lin.", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Mei Lin nördlich des Zwergenviertels in Sturmwind. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", progress = nil, completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es direkt hier beim alten Weißnase erwerben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32667] = {title = "Lernt Reiten", objective = "Findet Sanftpfote.", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Sanftpfote im Tal der Ehre in Orgrimmar. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", progress = nil, completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es direkt hier bei Schildkrötenmeisterin Odai erwerben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32668] = {title = "Lernt Reiten", objective = "Findet Perascamin.", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Perascamin bei Thurons Aufzucht, südöstlich vom Hirtentor von Silbermond aus. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", progress = nil, completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es direkt draußen bei Winaestra erwerben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32669] = {title = "Lernt Reiten", objective = "Findet Kildar.", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Kildar im Tal der Ehre in Orgrimmar. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", progress = nil, completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es drüben bei Ogunaro erwerben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32670] = {title = "Lernt Reiten", objective = "Findet Kar Sturmsang.", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Kar Sturmsang im Dorf der Bluthufe in Mulgore. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", progress = nil, completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es drüben bei Harb Klauenhuf erwerben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32671] = {title = "Lernt Reiten", objective = "Findet Xar'Ti.", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Xar'Ti in Sen'jin im südlichen Durotar. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", progress = nil, completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es drüben bei Zjolnir erwerben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32672] = {title = "Lernt Reiten", objective = "Findet Velma Warnam.", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Velma Warnam in Brill in Tirisfal. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!", progress = nil, completion = "Vergesst nicht, Euer Reittier zu kaufen, während Ihr hier seid! Ihr könnt es direkt hier bei Zachariah Post erwerben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32673] = {title = "Lernt Reiten", objective = "Findet Levi Ladestock.", description = "Es wird Zeit, dass Ihr das Reiten erlernt! Besucht Levi Ladestock im Tal der Geister in Orgrimmar. Vergesst nicht, ein Reittier zu erwerben, wenn Ihr dort seid!Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32674] = {title = "Nur Fliegen ist leichter", objective = "Findet Maztha.", description = "Der Himmel ruft Euch! Es ist Zeit, Fliegen zu lernen!\n\nBesucht Maztha die Fluglehrerin am Himmelspfad in Orgrimmar.\n\nUnd vergesst nicht, ein Flugreittier zu erwerben!", progress = nil, completion = "Ah, gut Euch zu sehen. Ihr seht aus, als wärt Ihr bereit, Euch in die Lüfte zu schwingen!\n\nDenkt daran, Ihr könnt ein Flugreittier von Drakma hinter mir kaufen.", rewards = nil}
MultiLanguageQuestData['de'][32675] = {title = "Nur Fliegen ist leichter", objective = "Findet Bralla Wolkenflug.", description = "Der Himmel ruft Euch! Es ist Zeit, Fliegen zu lernen!\n\nBesucht die Fluglehrerin Bralla Wolkenflug am Greifenhorst in Sturmwind.\n\nUnd vergesst nicht, ein Flugreittier zu erwerben!", progress = nil, completion = "Ah, gut Euch zu sehen. Ihr seht aus, als wärt Ihr bereit, Euch in die Lüfte zu schwingen!\n\nDenkt daran, Ihr könnt ein Flugreittier von Tannec Steinschnabel da drüben kaufen.", rewards = nil}
MultiLanguageQuestData['de'][32682] = {title = "Die gute Erde", objective = "Sprecht mit Bauer Yoon.", description = "Wie Ihr wisst, <Name>, werde ich nicht jünger. Man kann nicht für immer ein drahtiger junger Pandaren bleiben, wisst Ihr.\n\nIch suche jemanden, der meine Pflichten hier im Bund der Ackerbauern übernimmt, und niemand wäre geeigneter als Bauer Yoon.\n\nEr hat noch viel zu lernen, aber er hat einen brauchbaren Kopf auf den Schultern und, was wichtiger ist, ein großzügiges Herz.\n\nGlaubt Ihr, er könnte Interesse haben?", progress = nil, completion = "Ich wusste doch, dass Ihr ihn überzeugen würdet, &lt;Name&gt;. Ihr habt mein Herz beruhigt, nun da ich weiß, dass die Ackerbauern in guten Händen sind.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32686] = {title = "Makelloses Banner des Mantisreiches", objective = "Stellt das Artefakt zur Schau.", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Das wird den Lehrensuchern und Archäologen dabei helfen, die Geschichte von Pandaria zu verstehen.", rewards = "Ihr bekommt:\n\nRestauriertes ArtefaktMantis-Bernsplitter"}
MultiLanguageQuestData['de'][32687] = {title = "Makelloser uralter Harzspender", objective = "Stellt das Artefakt zur Schau.", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Das wird den Lehrensuchern und Archäologen dabei helfen, die Geschichte von Pandaria zu verstehen.", rewards = "Ihr bekommt:\n\nRestauriertes ArtefaktMantis-Bernsplitter"}
MultiLanguageQuestData['de'][32688] = {title = "Makellose alte Gottesanbeterin", objective = "Stellt das Artefakt zur Schau.", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Das wird den Lehrensuchern und Archäologen dabei helfen, die Geschichte von Pandaria zu verstehen.", rewards = "Ihr bekommt:\n\nRestauriertes ArtefaktMantis-Bernsplitter"}
MultiLanguageQuestData['de'][32689] = {title = "Makelloser Schallsignalgeber", objective = "Stellt das Artefakt zur Schau.", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Das wird den Lehrensuchern und Archäologen dabei helfen, die Geschichte von Pandaria zu verstehen.", rewards = "Ihr bekommt:\n\nRestauriertes ArtefaktMantis-Bernsplitter"}
MultiLanguageQuestData['de'][32690] = {title = "Makellose Überreste eines Getreuen", objective = "Stellt das Artefakt zur Schau.", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Das wird den Lehrensuchern und Archäologen dabei helfen, die Geschichte von Pandaria zu verstehen.", rewards = "Ihr bekommt:\n\nRestauriertes ArtefaktMantis-Bernsplitter"}
MultiLanguageQuestData['de'][32691] = {title = "Makellose Mantislampe", objective = "Stellt das Artefakt zur Schau.", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Das wird den Lehrensuchern und Archäologen dabei helfen, die Geschichte von Pandaria zu verstehen.", rewards = "Ihr bekommt:\n\nRestauriertes ArtefaktMantis-Bernsplitter"}
MultiLanguageQuestData['de'][32692] = {title = "Makelloser Pollensammler", objective = "Stellt das Artefakt zur Schau.", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nRestauriertes ArtefaktMantis-Bernsplitter"}
MultiLanguageQuestData['de'][32693] = {title = "Makelloser Kypariharzbehälter", objective = "Stellt das Artefakt zur Schau.", description = "Dieses Artefakt ist in einen erstaunlich exzellenten Zustand zurückversetzt worden. Vielleicht solltet Ihr es im Heim des Wissens ausstellen, damit Lehrensucher und Archäologen es untersuchen können.", progress = "Beseitigt das Durcheinander und stellt das Artefakt zur Schau.", completion = "Das wird den Lehrensuchern und Archäologen dabei helfen, die Geschichte von Pandaria zu verstehen.", rewards = "Ihr bekommt:\n\nRestauriertes ArtefaktMantis-Bernsplitter"}
MultiLanguageQuestData['de'][32723] = {title = "recycelt mich", objective = "Tötet den Meister der Schmiede und sammelt ein Kodexfragment vom Mogutorhüter auf der Insel des Donners ein.", description = "Ihr habt noch mehr zu tun. \n\nTötet Itoka, den Meister der Schmiede, und findet ein Kodexfragment bei Fleischschmied Hoku, dem Torhüter des Donnerkönigs.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nArkaner Schatz"}
MultiLanguageQuestData['de'][32836] = {title = "Eine billige Brummelflüte", objective = "Bringt die billige Brummelflüte zu einem Mitglied der Kampfgilde Eurer Fraktion.", description = "Die \"Brummelflüte\" wurde unsorgfältig aus einer Baumwurzel geschnitzt und die Abstände zwischen den Löchern sind unregelmäßig.\n\nBei genauerem Hinschauen entdeckt Ihr auf der Unterseite eingeritzte Wörter:\n\nZUR KAMPFGILDE ZURÜCKBRINGENIhr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32838] = {title = "Eine Fabel von Liebe und Edelmut", objective = "Bringt \"Der Bär und die Jungfrau hehr\" zu einem Mitglied der Kampfgilde Eurer Fraktion.", description = "Ein kleines Kinderbuch. Es ist gebunden und in ziemlich gutem Zustand.\n\nAuf dem hinteren Buchdeckel entdeckt Ihr neben dem Buchrücken in kursiver Handschrift folgende Aufschrift:\n\nZUR KAMPFGILDE ZURÜCKBRINGENIhr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32840] = {title = "Don-Dons Lunte", objective = "Bringt Don-Dons Lunte zu einem Mitglied der Kampfgilde Eurer Fraktion.", description = "Inmitten der Fleisch- und Fellstückchen von Ho-zen, die wild um Kota Kons zerstörerische Sphäre wirbeln, scheint Ihr eine kurze Lunte erwischt zu haben.\n\nSie besteht ausschließlich aus verwobenen und verfilzten Ho-zen-Haaren und riecht stark.\n\nAm einen Ende der Zündschnur entdeckt Ihr ein kleines Papieretikett mit folgender Aufschrift:\n\nZUR KAMPFGILDE ZURÜCKBRINGENIhr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32842] = {title = "Zähne wie Messer", objective = "Bringt den ausgesprochen scharfen Zahn zu einem Mitglied der Kampfgilde Eurer Fraktion.", description = "Der Zahn spitzt sich zu einer scharfen Kante zu, fast wie wenn er geschärft worden wäre. Er gehörte offensichtlich einer wilden Bestie.\n\nWährend Ihr ihn behutsam in der Hand haltet, fällt Euch eine gekonnt eingravierte Inschrift auf:\n\nZUR KAMPFGILDE ZURÜCKBRINGENIhr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32844] = {title = "Geheimnis des Schleims", objective = "Bringt die Phiole mit rötlichem Schleim zu einem Mitglied der Kampfgilde Eurer Fraktion.", description = "Der Inhalt der Phiole wirbelt und schäumt wild, was sie in Eurer Hand zittern lässt. Als Ihr hineinschaut, glaubt Ihr, kurz einen Blick auf ein wütendes lebendes Gesicht zu erhaschen.\n\nDer Pfropfen der Flasche passt genau. An seinem Rand entdeckt Ihr eine geschickt eingeschnitzte Inschrift:\n\nZUR KAMPFGILDE ZURÜCKBRINGENIhr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32846] = {title = "Modifizierter Mampfapparat", objective = "Bringt den modifizierten Mampfapparat zu einem Mitglied der Kampfgilde Eurer Fraktion.", description = "Ihr hättet diesen modifizierten Mampfapparat vielleicht gar nicht als solchen erkannt, wenn jemand nicht groß \"MODIFIZIERTER MAMPFAPPARAT\" darauf gekritzelt hätte.\n\nGleich unter der schludrig gemalten Aufschrift seht Ihr eine kleinere, in leuchtend roter Tinte und viel schöner geschrieben:\n\nZUR KAMPFGILDE ZURÜCKBRINGENIhr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32848] = {title = "Frostige Eierschale", objective = "Bringt die frostige Eierschale zu einem Mitglied der Kampfgilde Eurer Fraktion.", description = "Ein Stück einer Eierschale, wahrscheinlich von einem Pinguin. Die Ränder sind mit Raureif bedeckt und die Krümmung zeigt, dass das intakte Ei ziemlich groß gewesen sein muss.\n\nKomischerweise steht im Inneren der Eierschale mit jadegrüner Tinte eine Nachricht geschrieben:\n\nZUR KAMPFGILDE ZURÜCKBRINGENIhr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32850] = {title = "Modell vom letzten Jahr", objective = "Bringt den staubigen alten Roboter zu einem Mitglied der Kampfgilde Eurer Fraktion.", description = "Dieser Roboter ist in einem schlechten Zustand. Er hat mehrere eingebaute Sockel, die wahrscheinlich wie beim Blingtron 4000 einst Edelsteine enthielten, jetzt aber leer sind.\n\nAuf der sonst staubbedeckten Hinterseite des Roboters seht Ihr ein glänzendes kleines Metallschild mit folgender geprägter Inschrift:\n\nZUR KAMPFGILDE ZURÜCKBRINGENIhr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32852] = {title = "Der Erdschneider des Grabungsmeisters", objective = "Bringt den Erdschneider des Grabungsmeisters zu einem Mitglied der Kampfgilde Eurer Fraktion.", description = "Dem Aussehen nach ein ganz gewöhnlicher Spaten. Am Griff ist in Kursivschrift \"Der Erdschneider des Grabungsmeisters\" eingeschnitzt.\n\nAuf der anderen Seite des Griffs entdeckt Ihr jedoch ein kleineres Etikett in einfacher Schrift:\n\nZUR KAMPFGILDE ZURÜCKBRINGENIhr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32854] = {title = "Abgetragene Augenbinde", objective = "Bringt die abgetragene Augenbinde zu einem Mitglied der Kampfgilde Eurer Fraktion.", description = "Ein Stück Stoff, das um einen menschlichen Kopf passen würde. Der Stoff ist schlicht und schmucklos, abgesehen von einem kleinen Etikett am einen Ende mit folgender Aufschrift:\n\nZUR KAMPFGILDE ZURÜCKBRINGENIhr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32856] = {title = "Mit Papier umwickelter Stein", objective = "Bringt den mit Papier umwickelten Stein zu einem Mitglied der Kampfgilde Eurer Fraktion.", description = "Eine seltsame Kombination. Das Papier umschließt den Stein vollständig, der im Vergleich dazu kaum größer als ein Kiesel ist.\n\nWenn Ihr das Papier gegen das Licht haltet, seht Ihr ein deutliches Wasserzeichen mit folgendem Text:\n\nZUR KAMPFGILDE ZURÜCKBRINGENIhr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32857] = {title = "Ro-Shambo", objective = "Besiegt Ro-Shambo, indem Ihr seine Herausforderungskarte erwerbt und ihn in der Kampfgilde herausfordert.", description = "Mit der Herausforderungskarte, die Ihr freigeschaltet habt, dürft Ihr Ro-Shambo herausfordern, eine esoterische Kreatur aus unbekannten Gefilden.\n\nPasst auf. Wie ich höre, hat er einige Tricks auf Lager.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nPapierhemdÜbervoller Sack MünzenTapferkeitspunkte"}
MultiLanguageQuestData['de'][32858] = {title = "Raptorbalgboxhandschuhe", objective = "Bringt die Raptorbalgboxhandschuhe zu einem Mitglied der Kampfgilde Eurer Fraktion.", description = "Die Handschuhe sind mit groben Stichen genäht und wurden nach dem Geruch zu urteilen mit Kriechersekret behandelt. Sie erscheinen dennoch strapazierfähig und funktionstüchtig.\n\nIhr seid nicht sehr erstaunt, als Ihr im Innensaum folgende Aufschrift entdeckt:\n\nZUR KAMPFGILDE ZURÜCKBRINGENIhr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32863] = {title = "Wofür wir trainiert haben", objective = "Besiegt 10 Spieler über 'Kampf finden' mit einer Gruppe aus Haustieren auf Stufe 25.", description = "Seid Ihr bereit, Eure Haustiere einer Prüfung zu unterziehen? Die Kampfhaustierarena ist kein Platz für niedrigstufige Angsthasen. Besser, Ihr habt einen Raketenbot dabei und seid auf alles gefasst. Wenn Ihr über drei vollständig ausgebildete Haustiere verfügt, dann sucht Kämpfe gegen Trainer mit ähnlichen Fähigkeiten und zeigt der Welt, was Ihr drauf habt. Die Anweisungen dazu findet Ihr in Eurem Wildtierführer.", progress = nil, completion = "Ich hörte Geschichten über einige Eurer Kämpfe. Offensichtlich waren sie vielen ein unvergessliches Erlebnis! Ich glaube, dass Ihr Euch diese Belohnung verdient habt. Glückwunsch, Trainer, und leistet weiterhin so gute Arbeit.", rewards = "Ihr bekommt:\n\nKampfhaustierbedarfTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32868] = {title = "Fabelhafte Wesen, Buch II", objective = "Besiegt Glückspilz Yi, Grauhuf und Huscher Xi'a.", description = "Die Geschichten von Glückspilz Yi, Grauhuf und Huscher Xi'a werden in diesem Land immer präsent bleiben. Möchtet Ihr ihnen noch einmal im Kampf begegnen?", progress = nil, completion = "Ich verneige mich vor Euch, die weiterhin auf den Spuren der großen pandarischen Fabeln wandelt.", rewards = "Ihr bekommt:\n\nBerühmter pandarischer HaustierbedarfTapferkeitspunkteGeringes Amulett des Glücks"}
MultiLanguageQuestData['de'][32869] = {title = "Fabelhafte Wesen, Buch III", objective = "Besiegt No-No, Ti'un den Wanderer und Blutstachel.", description = "Die Geschichten von No-No, Ti'un dem Wanderer und Blutstachel werden in diesem Land immer präsent bleiben. Möchtet Ihr ihnen noch einmal im Kampf begegnen?", progress = nil, completion = "Ich verneige mich vor Euch, die weiterhin auf den Spuren der großen pandarischen Fabeln wandelt.", rewards = "Ihr bekommt:\n\nBerühmter pandarischer HaustierbedarfGeringes Amulett des GlücksTapferkeitspunkte"}
