MultiLanguageQuestData['de'][32910] = {title = "recycelt mich", objective = "Tötet den Meister der Schmiede und sammelt ein Kodexfragment vom Mogutorhüter auf der Insel des Donners ein.", description = "Ihr habt noch mehr zu tun. \n\nTötet Itoka, den Meister der Schmiede, und findet ein Kodexfragment bei Fleischschmied Hoku, dem Torhüter des Donnerkönigs.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nArkaner Schatz"}
MultiLanguageQuestData['de'][32995] = {title = "Blutverkrustete Schriftrolle", objective = "[TEMP TEXT] Bringt die Schriftrolle des Waffenmeisters zu Gauros Erdspalter in der Shlae'gararena von Orgrimmar.", description = "[TEMP TEXT] Diese Schriftrolle sieht sehr alt aus. Unter Staub und dunklen Blutflecken verborgen könnt Ihr einige wenige Passagen über die \"Meisterschaft der Waffen\" erkennen.\n\nDas könnte für Euer Training sehr wertvoll sein.\n\nVielleicht gibt es irgendwo einen erfahrenen Krieger, der Euch mehr über diese Schriftrolle erzählen kann.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][32996] = {title = "Kriegsgestählte Relikte", objective = "[TEMP TEXT] Besorgt 100 kriegsgestählte Relikte von den Bossen aus xxx.", description = "[TEMP TEXT] Ich habe schon von Euch gehört, <Name>. Viele Male. Ihr seid - und wart lange - <einer/eine> der geschicktesten <Krieger/Kriegerinnen> der Horde.\n\nDennoch, wir sind uns fremd. Ich muss wissen, wie fähig Ihr wirklich seid, bevor ich Euch mit der Schriftrolle helfen kann.\n\nDie xxx haben vor Kurzem xxx entdeckt. Beweist Euer Können, indem Ihr mir Beute aus diesen Dungeons bringt.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][33000] = {title = "Saurfang, Krieger", objective = "Meldet Euch bei Hochfürst Saurfang in Klingenhügel in Durotar.[TEMP TEXT] Jeder Krieger, der der Rede wert ist, verfügt zu gleichen Teilen über Stärke und Führungsqualitäten: Stärke, um über seine Feinde zu siegen, und Führungsqualitäten, um Verbündete um sich zu scharen. Dem Krieger, auf den Ihr gleich treffen werdet, mangelt es an keiner dieser Eigenschaften.\n\nHochfürst Saurfang wartet in Klingenhügel. Vor langer Zeit hat er mir eine Menge von dem beigebracht, was ich heute weiß. Er kann Euch mit dieser Schriftrolle helfen.\n\nIch habe bereits eine Nachricht vorausgeschickt. Saurfang erwartet Eure Ankunft, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "[TEMP TEXT] Jeder Krieger, der der Rede wert ist, verfügt zu gleichen Teilen über Stärke und Führungsqualitäten: Stärke, um über seine Feinde zu siegen, und Führungsqualitäten, um Verbündete um sich zu scharen. Dem Krieger, auf den Ihr gleich treffen werdet, mangelt es an keiner dieser Eigenschaften.\n\nHochfürst Saurfang wartet in Klingenhügel. Vor langer Zeit hat er mir eine Menge von dem beigebracht, was ich heute weiß. Er kann Euch mit dieser Schriftrolle helfen.\n\nIch habe bereits eine Nachricht vorausgeschickt. Saurfang erwartet Eure Ankunft, <Name>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][33001] = {title = "Die Waffenmeister", objective = "[TEMP TEXT]", description = "[TEMP TEXT] Diese Schriftrolle beschreibt die Technik des Waffenmeisters - eine Technik, die ich seit Jahren bei niemandem gesehen habe. Ich kann die leeren Stellen der Schriftrolle für Euch füllen, aber ohne Erfahrung ist diese Rolle nichts als Wörter auf Papier.\n\nZu meiner Zeit bin ich auf viele Feinde gestoßen, einige wenige waren wahre Meister ihrer Waffen. Diese Waffenmeister sind bereits lange Zeit tot, aber mithilfe der xxx könnt auch Ihr gegen sie kämpfen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][33002] = {title = "Schreiber Wie Wu", objective = "[TEMP TEXT] Sprecht mit Schreiber Wie Wu im Heim des Wissens im Tal der Ewigen Blüten.[TEMP TEXT] Ich habe mein Wissen benutzt, um die leeren und unleserlichen Stellen Eurer Schriftrolle auszubessern, <Name>. Ich bin allerdings kein Schreiber. Ein solches Dokument sollte erfasst und archiviert werden.\n\nDie Schreiber von Pandaria legen Wert darauf, alte Texte wie Euren zu archivieren. Bringt ihn zum Schreiber im Heim des Wissens.\n\nLebt wohl, <Krieger/Kriegerin>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "[TEMP TEXT] Ich habe mein Wissen benutzt, um die leeren und unleserlichen Stellen Eurer Schriftrolle auszubessern, <Name>. Ich bin allerdings kein Schreiber. Ein solches Dokument sollte erfasst und archiviert werden.\n\nDie Schreiber von Pandaria legen Wert darauf, alte Texte wie Euren zu archivieren. Bringt ihn zum Schreiber im Heim des Wissens.\n\nLebt wohl, <Krieger/Kriegerin>.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][33003] = {title = "Glyphe des Waffenmeisters", objective = "[TEMP TEXT] Besorgt das scharlachrote Blut von Oban Oju, das pechschwarze Sekret von Kak'charrik und das azurblaue Blut von Blitzpelz.", description = "[TEMP TEXT] Ich verstehe - Ihr benötigt eine korrekt beschriebene Schriftrolle. Ich habe das Pergament, aber ein Text wie dieser verdient kräftige Farben - Farben, die ihren Preis haben. Standardtinten werden nicht ausreichen.\n\nHier im Tal gibt es Bestien... legendäre Bestien, die über die Farben verfügen, die ich benötige. Ich kann Euch sagen, wo Ihr sie findet.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][33007] = {title = "Feuerprobe", objective = "[TEMP TEXT] Schließt eine [PROVING GROUNDS TRIAL] ab.", description = "[TEMP TEXT] Gauros mag Euch auf die Probe gestellt haben, aber ich glaube, Ihr seid zu mehr fähig, <Name>. Ich weiß zwar, was Krieger wie Ihr durchgemacht haben, aber ein paar Missionen im Feld sind wirklich nichts Besonderes.\n\nEure wahre Prüfung wird in [PROVING GROUNDS TOWN] stattfinden. Sprecht mit [ZEITLOSEM SCHORSCH] in [PROVING GROUNDS TOWN] und besteht eine seiner Prüfungen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][33008] = {title = "In das Tal", objective = "Sprecht mit Madame Vee Luo im Schrein der Zwei Monde im Tal der Ewigen Blüten.Ah, ich habe auf Eure Ankunft gewartet, <Reisender/Reisende>.\n\nIch wünschte, wir könnten uns unter besseren Umständen treffen, aber leider ist die derzeitige Situation im Tal alles andere als erfreulich.\n\nAber lasst uns im Moment nicht darüber sprechen. Besucht Madame Vee Luo im Schrein der Zwei Monde.\n\nSie wird Euch dabei helfen, Euch einzuleben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Ah, ich habe auf Eure Ankunft gewartet, <Reisender/Reisende>.\n\nIch wünschte, wir könnten uns unter besseren Umständen treffen, aber leider ist die derzeitige Situation im Tal alles andere als erfreulich.\n\nAber lasst uns im Moment nicht darüber sprechen. Besucht Madame Vee Luo im Schrein der Zwei Monde.\n\nSie wird Euch dabei helfen, Euch einzuleben.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][33110] = {title = "Der Thronräuber", objective = "Erhaltet Eure Belohnung dafür, dass Ihr Garrosh Höllschrei als Kriegshäuptling der Horde abgesetzt habt.", description = "Dieses Fragment des Herzens von Y'Shaarj ist vollkommen erstarrt. Ihr solltet es den verbleibenden Mitgliedern des Goldenen Lotus übergeben – als Beweis dafür, dass Garrosh besiegt wurde.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSichtloser MantelGigantischer Sack MünzenTapferkeitspunkte"}
MultiLanguageQuestData['de'][33248] = {title = "Feuerprobe", objective = "Sprecht mit Prüfungsmeister Rotun im Tempel des Weißen Tigers und betretet dann die Feuerprobe.", description = "He, Ihr da! <Name>, richtig? Seid gegrüßt. Ich bin Taijing.\n\n<Taijing mustert Euch von Kopf bis Fuß.>\n\nIhr seht stark aus. Ich habe Euch schon ein paar Mal hier im Tal gesehen, aber noch nicht im Kampf erlebt. Ich frage mich, ob Ihr so stark seid, wie Ihr ausseht.\n\nSolltet Ihr daran interessiert sein, Euch zu beweisen, sprecht mit Prüfungsmeister Rotun im Tempel des Weißen Tigers, am Kun-Lai-Gipfel. Er wird Euch einer Prüfung unterziehen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][33249] = {title = "Feuerprobe", objective = "Sprecht mit Prüfungsmeister Rotun im Tempel des Weißen Tigers und betretet dann die Feuerprobe.", description = "He, Ihr da! <Name>, richtig? Seid gegrüßt. Ich bin Jinho.\n\n<Jinho mustert Euch von Kopf bis Fuß.>\n\nIhr seht stark aus. Ich habe Euch schon ein paar Mal hier im Tal gesehen, aber noch nicht im Kampf erlebt. Ich frage mich, ob Ihr so stark seid, wie Ihr ausseht.\n\nSolltet Ihr daran interessiert sein, Euch zu beweisen, sprecht mit Prüfungsmeister Rotun im Tempel des Weißen Tigers, am Kun-Lai-Gipfel. Er wird Euch einer Prüfung unterziehen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][33252] = {title = "Ein Winterhauchgeschenk", objective = "Ihr bekommt:\n\n", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWinterhauchgeschenk"}
MultiLanguageQuestData['de'][33354] = {title = "Der Niedergang der Höhlenmutter", objective = "Bringt Mondfangs Pelz zu Yebb Nabetand auf dem Dunkelmond-Jahrmarkt auf der Dunkelmond-Insel.", description = "Dies ist der Pelz der monströsen Höhlenmutter der Dunkelmond-Insel.\n\nYebb Nabetand, Bestienmeister der Dunkelmond-Insel, wird erfreut sein zu erfahren, dass die geisterhafte Wölfin und ihre Jungen seine Menagerie nicht mehr terrorisieren werden… zumindest vorerst nicht. Bringt ihm den Pelz.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGewinnlos des Dunkelmond-Jahrmarkts"}
MultiLanguageQuestData['de'][33634] = {title = "Maldo's Test Quest", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['de'][63448] = {title = "Eine Deluxelieferung", objective = "Grüße, <Name>, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch diese Gegenstände auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals einen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWiedererwachter PhasenjägerDunkles PortalIllidans Pfad"}
MultiLanguageQuestData['de'][63450] = {title = "Eine Deluxelieferung", objective = "Ah, ja. Bin ich froh, dass Ihr endlich aufgetaucht seid, um mir dieses Paket abzunehmen.\n\nUnsere gemeinsamen Freunde wollten, dass Ihr diese Belohnungen im Gegenzug für einen Kauf Eurerseits erhaltet. Mehr will ich aber gar nicht wissen. Ich bin hier nur der Botenjunge.\n\nSolltet Ihr diese Gegenstände jemals verlieren, kommt zu mir zurück, und ich ersetze sie Euch kostenlos.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWiedererwachter PhasenjägerDunkles PortalIllidans Pfad"}
MultiLanguageQuestData['de'][63767] = {title = "Wichtel in der Kugel", objective = "Grüße, <Klasse>, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch etwas auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals diesen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWichtel in der Kugel"}
MultiLanguageQuestData['de'][63768] = {title = "Wichtel in der Kugel", objective = "Ah, ja. Bin ich froh, dass Ihr endlich aufgetaucht seid, um mir dieses Paket abzunehmen.\n\nUnsere gemeinsamen Freunde wollten, dass Ihr diese Belohnung im Gegenzug für einen Kauf Eurerseits erhaltet. Mehr will ich aber gar nicht wissen. Ich bin hier nur der Botenjunge.\n\nSolltet Ihr diesen Gegenstand jemals verlieren, kommt zu mir zurück, und ich ersetze ihn Euch kostenlos.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWichtel in der Kugel"}
MultiLanguageQuestData['de'][63770] = {title = "Ein besonderer Dank", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nNetherwelpenhalsband"}
MultiLanguageQuestData['de'][63865] = {title = "Ein besonderer Dank", objective = "Grüße, <Name>,\n\nHier ist ein besonderes Geschenk für Euch als passionierten Sammler! Wir möchten Euch diesen kleinen aber aufgeweckten Freund überreichen. Möge er Euch zu neuen Abenteuern auf der anderen Seite des Dunklen Portals in der Scherbenwelt führen!", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nNetherwelpenhalsbandLurkys Ei"}
MultiLanguageQuestData['de'][63866] = {title = "Die Beherrschung des Lichts", objective = "Füllt das schimmernde Gefäß bei M'uru und kehrt anschließend zu Ritterfürst Heldenblut in Silbermond zurück.", description = "Nehmt dieses Gefäß, <Name>. Seine Magie wird es Euch erlauben, die Macht dieser Kreatur an Euch zu nehmen. Mit ihr werdet Ihr in der Lage sein, Euren gefallenen Kameraden wieder zum Leben zu erwecken.\n\nManche werden sagen, dass unser Handeln falsch ist, aber vieles von dem, was uns widerfahren ist, ist auch falsch. Sollen wir denn solch ein Geschenk wegwerfen?\n\nSie behalten ihre Kritik für sich, wenn unsere Macht die weitere Zerstörung Silbermonds verhindert. Doch sobald sie sich in teuer erkaufter Sicherheit ihren magischen Süchten hingeben können, erheben sie ihre Einsprüche.", progress = "Habt Ihr schon mit Magister Astalor Blutschwur gesprochen?", completion = "Gut gemacht, &lt;Name&gt;. Die vom Licht gewährten Kräfte sind niemals auf 'natürlichem' Wege zu den Blutrittern gekommen, aber wir sind nicht so willensschwach, um unseren Weg von der Natur diktieren zu lassen.\n\nUnsere Beherrschung des Arkanen hat uns einen Pfad durch diese rauen Zeiten eröffnet. Die Kräfte fließen nicht mehr frei in diesen Hallen, doch sie sind da, für die hartnäckigen und willensstarken. Nur wenige sind heutzutage mutig genug, oder verfügen über die Begabung, sie zu meistern, aber ich weiß, dass Ihr den Orden nicht enttäuschen werdet.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64028] = {title = "Ein Neuanfang", objective = "Besucht einen Trainer in Sturmwind, der Euch als <Klasse> ausbilden kann.", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Sturmwind, Hauptstadt der Allianz!\n\n<Ein/Eine:c> <Klasse> wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", progress = nil, completion = "Bereit für Eure Ausbildung, &lt;Volk&gt;?", rewards = "Ihr bekommt:\n\nAzerothüberlebenspaket"}
MultiLanguageQuestData['de'][64031] = {title = "Das Zeug zum Überleben", objective = "Öffnet das Überlebenspaket und legt eine Waffe an.", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", progress = "Ich habe ein Überlebenspaket für Eure Abenteuer zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Macht guten Gebrauch davon.", completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64034] = {title = "Kampftraining", objective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als <Klasse> ausbilden kann.", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als <Klasse> wachsen.\n\nIhr könnt überall in Azeroth, sowie in Hauptstädten wie Sturmwind, Darnassus oder Eisenschmiede Trainer finden.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber dieses eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", progress = "Wenn Ihr bereit seid, sprecht mich an, um Eure Fähigkeiten zu trainieren.", completion = "Ihr seht jetzt schon stärker aus, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64035] = {title = "Talentiert", objective = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.", progress = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", completion = "Ihr seid bereit für den Kampf, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64037] = {title = "Östliche Pestländer", objective = "Reist in die Östlichen Pestländer und macht Leonidas Bartholomäus ausfindig. Er wartet in der Kapelle des Hoffnungsvollen Lichts.", description = "Auf Anweisung von Hochlord Bolvar Fordragon ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Lord Bartholomäus in der Kapelle des Hoffnungsvollen Lichts zu melden.\n\nDie Argentumdämmerung benötigt Eure Hilfe dabei, die Östlichen Pestländer von der Geißel zu befreien.\n\nUm in die Östlichen Pestländer zu gelangen, sprecht mit dem Greifenmeister Dungar Trinkfest. Seine Greifen können Euch schneller als jedes Pferd dorthin bringen.\n\nFür Ruhm und Ehre der Allianz!", progress = nil, completion = "Vielleicht könnt Ihr helfen, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64038] = {title = "Das Dunkle Portal", objective = "Macht Wachkommandant Reldorn Netherschwund in den Verwüsteten Landen ausfindig. Er erwartet Eure Ankunft vor dem Dunklen Portal.", description = "Es existiert ein höllisches Tor, das jahrelang geruht hat. Jetzt ruht es nicht mehr.\n\nAuf Anweisung von Hochlord Bolvar Fordragon ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend in den Verwüsteten Landen zu melden. Sprecht mit Dungar Trinkfest, um einen Flug dorthin zu arrangieren.\n\nSobald Ihr angekommen seid, meldet Euch umgehend bei Wachkommandant Reldorn Netherschwund. Er erwartet Euch vor dem Dunklen Portal...", progress = nil, completion = "Willkommen zum Alptraum!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64046] = {title = "Ein Neuanfang", objective = "Besucht einen Trainer in Orgrimmar, der Euch als <Klasse> ausbilden kann.", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Orgrimmar, Hauptstadt der Horde!\n\n<Ein/Eine:c> <Klasse> wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", progress = nil, completion = "Bereit für Eure Ausbildung, &lt;Volk&gt;?", rewards = "Ihr bekommt:\n\nAzerothüberlebenspaket"}
MultiLanguageQuestData['de'][64047] = {title = "Ein Neuanfang", objective = "Besucht einen Trainer in Donnerfels, der Euch als <Klasse> ausbilden kann.", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Donnerfels, Hauptstadt der Tauren!\n\n<Ein/Eine:c> <Klasse> wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", progress = nil, completion = "Bereit für Eure Ausbildung?", rewards = "Ihr bekommt:\n\nAzerothüberlebenspaket"}
MultiLanguageQuestData['de'][64048] = {title = "Das Zeug zum Überleben", objective = "Öffnet das Überlebenspaket und legt eine Waffe an.", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", progress = nil, completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64049] = {title = "Das Zeug zum Überleben", objective = "Öffnet das Überlebenspaket und legt eine Waffe an.", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", progress = nil, completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64050] = {title = "Kampftraining", objective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als <Klasse> ausbilden kann.", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als <Klasse> wachsen.\n\nIhr könnt überall in Azeroth, sowie in Hauptstädten wie Orgrimmar, Donnerfels oder der Unterstadt Trainer finden.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber dieses eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", progress = "Wenn Ihr bereit seid, sprecht mich an, um Eure Fähigkeiten zu trainieren.", completion = "Ihr seht jetzt schon stärker aus, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64051] = {title = "Kampftraining", objective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als <Klasse> ausbilden kann.", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als <Klasse> wachsen.\n\nIhr könnt überall in Azeroth, sowie in Hauptstädten wie Donnerfels, Orgrimmar oder der Unterstadt Trainer finden.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber dieses eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", progress = "Wenn Ihr bereit seid, sprecht mich an, um Eure Fähigkeiten zu trainieren.", completion = "Ihr seht jetzt schon stärker aus, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64052] = {title = "Talentiert", objective = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.", progress = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", completion = "Ihr seid bereit für den Kampf, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64053] = {title = "Talentiert", objective = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.", progress = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", completion = "Ihr seid fast bereit für den Kampf, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64063] = {title = "Das Dunkle Portal", objective = "Macht Kriegsherr Dar'toon ausfindig. Er erwartet Eure Ankunft vor dem Dunklen Portal.", description = "Es existiert ein höllisches Tor, das jahrelang geruht hat. Jetzt ruht es nicht mehr.\n\nAlle tauglichen Mitglieder der Horde sind hiermit angewiesen, sich in den Verwüsteten Landen zu melden. Begebt Euch zum Zeppelinmeister vor den Toren Orgrimmars und fliegt zum Basislager Grom'gol. Sprecht dort mit Thysta, um einen Flug nach Steinard zu erhalten.\n\nMeldet Euch umgehend bei Kriegsherr Dar'toon. Er erwartet Euch vor dem Dunklen Portal...", progress = nil, completion = "Willkommen zum Alptraum!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64064] = {title = "Östliche Pestländer", objective = "Reist in die Östlichen Pestländer und macht Leonidas Bartholomäus ausfindig. Er erwartet Eure Ankunft in der Kapelle des Hoffnungsvollen Lichts.", description = "Alle tauglichen Mitglieder der Horde sind hiermit angewiesen, sich bei Leonidas Bartholomäus in der Kapelle des Hoffnungsvollen Lichts zu melden.\n\nDie Argentumdämmerung hat ihre Position in den Pestländern gefestigt und benötigt Eure Hilfe, um ihre Siege zu konsolidieren.\n\nBesucht Zeppelinmeister Frezza vor dem Haupttor und reist zur Unterstadt. Reist von dort aus zur Kapelle des Hoffnungsvollen Lichts in den Östlichen Pestländern.\n\nDas Schicksal wartet!", progress = nil, completion = "Vielleicht könnt Ihr helfen, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64128] = {title = "Östliche Pestländer", objective = "Reist in die Östlichen Pestländer und macht Leonidas Bartholomäus ausfindig. Er wartet in der Kapelle des Hoffnungsvollen Lichts.", description = "Alle tauglichen Mitglieder der Horde sind hiermit angewiesen, sich bei Leonidas Bartholomäus in der Kapelle des Hoffnungsvollen Lichts zu melden.\n\nDie Argentumdämmerung hat ihre Position in den Pestländern gefestigt und benötigt Eure Hilfe, um ihre Siege zu konsolidieren.\n\nSprecht mit Tal, unserem Windreitermeister, um nach Orgrimmar zu fliegen. Von dort bringt Euch Zeppelinmeister Frezza vor dem Haupttor zur Unterstadt. Ihr könnt von dort aus in die Östlichen Pestländer gelangen.\n\nDas Schicksal wartet!", progress = nil, completion = "Vielleicht könnt Ihr helfen, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64139] = {title = "Eine Vorladung von Lady Liadrin", objective = "Sprecht mit Lady Liadrin in Silbermond.", description = "Eure Aufopferung für den Orden und Euer rascher Aufstieg innerhalb seiner Ränge sind nicht unbeachtet geblieben. Tatsächlich erbittet Lady Liadrin Eure Gegenwart.\n\nDas ist eine seltene Ehre, <Name>. Normalerweise überlässt Lady Liadrin mir die Verwaltung des Ordens und das damit verbundene Tagesgeschäft, doch scheint sie ein besonderes Interesse an Euch zu haben. Wartet nicht zu lange, <Name>.", progress = nil, completion = "Wir werden den Grund Eures Besuchs noch früh genug besprechen. Doch zunächst muss ich feststellen, dass mich Eure bisherigen Leistungen und Euer Geschick in der Beherrschung des Lichts sehr beeindruckt haben.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64140] = {title = "Der Pfad des Meisters", objective = "Sprecht erneut mit Lady Liadrin, um ihr Angebot, für Euch zu sprechen, anzunehmen.", description = "Innerhalb unseres Ordens existiert ein eingeschworener Zirkel von Eliterittern. Die Mitglieder des Zirkels repräsentieren die Hingebungsvollsten, Fähigsten und Vertrauenswürdigsten aller Blutritter, allesamt handverlesen und vereidigt durch die Ordensführung. Diese Meister sind leicht an ihrem thalassischen Schlachtross zu erkennen.\n\nJeder Kandidat, der sich um die Aufnahme in diese erlesene Gemeinschaft bewirbt, benötigt einen Fürsprecher aus den Reihen des Zirkels und muss seine Hingabe für die zentralen Grundsätze des Ordens unter Beweis stellen.\n\nIch habe beschlossen, Euch als Fürsprecher zur Seite zu stehen, sollte es Euer Wunsch sein, in die Reihen der Meister der Blutritter aufgenommen zu werden.", progress = nil, completion = "Dass Ihr Euch entschlossen habt, mein Angebot zu akzeptieren, spricht für Euch, &lt;Name&gt;. Ich wünsche Euch viel Glück, bei den von mir festzulegenden Prüfungen, doch bin ich zuversichtlich, dass Ihr sie alle meistern werdet.\n\nIch werde Euch die Aufgaben in der Reihenfolge ihrer Schwierigkeit, von der Leichtesten bis zur Schwersten, erteilen. Wir können beginnen, sobald Ihr bereit seid.", rewards = nil}
MultiLanguageQuestData['de'][64141] = {title = "Eine Geste der Hingabe", objective = "Bringt 40 Einheiten Runenstoff, 6 Arkanitbarren, 10 Einheiten Sonnengras, 5 Dunkelrunen und 150 Goldstücke zu Lady Liadrin in Silbermond.", description = "Die Loyalität eines Blutritters endet nicht an der Spitze seiner Klinge, <Name>. Der Orden verlangt mehr von seinen Mitgliedern, als schiere Ausbildung und Kampf. Ein wahrer Ritter trägt zu allen Aktivitäten des Ordens etwas bei, selbst zu denen, die nicht offensichtlich Ruhm verheißen.\n\nDiese erste Aufgabe fordert weder Eure Kampfeskunst, noch ist sie besonders ruhmreich, doch ohne solche Tätigkeiten würde der Orden auseinander fallen. Ich werde Euch eine Liste mit Gegenständen geben, die Magister Astalor Blutschwurs Männer benötigen, um uns mit Lichtenergie für unsere Magie zu versorgen.", progress = "Habt Ihr die von Magister Astalor benötigten Materialien bei Euch?", completion = "Hervorragend. Es sieht so aus, als sei alles da.\n\nKeine Sorge, im Laufe Eurer nächsten Aufgabe habt Ihr noch oft genug die Möglichkeit, von Eurer Waffe Gebrauch zu machen, versprochen!\n\nIch werde einen Initianden losschicken, um alles zu Magister Astalor zu bringen. Es wäre Verschwendung, Euch mit einem solch trivialen Botengang zu betrauen, wenn wesentlich wichtigere Dinge auf ihre Erledigung warten.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64142] = {title = "Eine Demonstration Eurer Loyalität", objective = "Lady Liadrin in Silbermond möchte, dass Ihr 3 Fleischwagen der Geißel zerstört und 15 Belagerungsingenieure der Geißel tötet.", description = "Wir Blutritter haben geschworen, Quel'Thalas zu verteidigen, <Name>. Dies ist ein zentraler Teil unserer Ausbildung. Unsere Feinde sind wild und unbeugsam. Einzig unsere Anstrengungen und die Unterstützung unserer Verbündeten sind der Garant für die Freiheit eines jeden Bürgers von Silbermond.\n\nIch habe einige beunruhigende Berichte über die verstärkte Präsenz der Geißel, südöstlich unserer Grenze zu den östlichen Pestländern, erhalten. Eine Kompanie Belagerungsingenieure der Geißel, mitsamt Belagerungsgerät, scheinen sich dort für einen Angriff auf die Geisterlande zu sammeln. Auf keinen Fall dürfen sie Erfolg haben.", progress = "Willkommen zurück, <Name>. Habt Ihr die Geißel und ihre Fleischwagen zurückgeschlagen?", completion = "Ihr habt Loyalität gegenüber Eurer Heimat und Eure Aufopferungsbereitschaft für die Ziele des Ordens bewiesen, &lt;Name&gt;.  Ich habe noch eine letzte Aufgabe für Euch, bevor Ihr den Titel eines Meisters für Euch beanspruchen dürft.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64143] = {title = "Wahre Meister des Lichts", objective = "Bringt Lady Liadrin in Silbermond eine Phiole Weihwasser von Tyrs Hand.", description = "Ein Meister der Blutritter besitzt unglaubliche Fähigkeiten das Licht auf eine Art zu nutzen und zu formen, wie es die sogenannten anderen 'Paladine' nie verstehen werden. Das hält sie jedoch nicht davon ab, uns dafür zu ächten, wie wir das wahre Potential des Lichts entfesseln.\n\nWir müssen ihnen klar machen, dass man mit Unseresgleichen keine Spielchen spielt. Was ich mir vorgestellt habe, ist keine schnelle Angelegenheit und auch nicht einfach, doch wenn Ihr Euch dieser Aufgabe verpflichtet, wird es Euer erstes Ziel sein, den Bibliotheksflügel der Abtei von Tyrs Hand zu infiltrieren und eine Phiole heiligen Wassers von Tyrs Hand an Euch zu bringen.", progress = "Habt Ihr das Wasser bekommen?", completion = "Hmm... das ist eine recht kleine Menge, doch wenn wir vorsichtig vorgehen, sollte es ausreichen. Seht Ihr, der Scharlachrote Kreuzzug behauptet von sich noch immer, dem Licht zu dienen. Ich nehme an, dass sie das auch auf eine recht verdrehte Art und Weise noch immer tun, und genau diesen Umstand möchte ich ausnutzen.\n\nIhr fehlgeleiteter Eifer hat selbst den Segen dieses Wassers korrumpiert und das macht es ideal für meine Zwecke.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64144] = {title = "Wahre Meister des Lichts", objective = "Bringt Lady Liadrin in Silbermond 1 arkanen Katalysator, 1 Einheit krepuskulares Pulver, 1 azerothischen Diamanten und 1 makellosen schwarzen Diamanten.", description = "Jetzt, da wir das Wasser haben, benötigen wir eine Reihe von Zutaten in genau abgestimmten Mengen. Einige dieser Substanzen sind äußerst selten und wertvoll, <Name>, doch ich habe Quellen für zwei von ihnen ausfindig gemacht.\n\n Ihr solltet einige arkane Katalysatoren bei Zalle, dem Reagenzienverkäufer in einem der Geschäfte auf dem Platz nahe der Todesschneise, bekommen. Darlia, die Giftlieferantin nahe der Schurkenausbilder in der Mördergasse, sollte über einen Vorrat an krepuskularem Pulver verfügen.\n\nUm meine Mixtur zu vervollständigen, benötige ich außerdem noch einen azerothischen Diamanten und einen makellosen schwarzen Diamanten.", progress = "Habt Ihr die von mir benötigten Zutaten bekommen?", completion = "Jetzt, wo wir über alle Zutaten verfügen, kann ich die Mixtur vorbereiten.\n\n&lt;Ein Lächeln breitet sich langsam über Lady Liadrins Gesicht aus.&gt;\n\nAlles entwickelt sich perfekt, &lt;Name&gt;. Sobald ich hier fertig bin, werde ich Euch unseren letzten Schritt ausführlich erläutern.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64217] = {title = "Das Dunkle Portal", objective = "Macht Kriegsherr Dar'toon ausfindig. Er erwartet Eure Ankunft vor dem Dunklen Portal.", description = "Es existiert ein höllisches Tor, das jahrelang geruht hat. Jetzt ruht es nicht mehr.\n\nAlle tauglichen Mitglieder der Horde sind hiermit angewiesen, sich in den Verwüsteten Landen zu melden. Begebt Euch zum Zeppelinmeister vor den Toren Orgrimmars und fliegt zum Basislager Grom'gol. Sprecht dort mit Thysta, um einen Flug nach Steinard zu erhalten.\n\nMeldet Euch umgehend bei Kriegsherr Dar'toon. Er erwartet Euch vor dem Dunklen Portal...", progress = nil, completion = "Willkommen zum Alptraum!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64319] = {title = "Eine Studie der Macht", objective = "Sprecht mit Magister Astalor Blutschwur in der Geheimen Kammer unter dem Hauptquartier der Blutelfen.", description = "Haltet mich nicht für übermäßig grausam, <Name>. Stillstreich hat sehr wohl gewusst, worauf er sich einlässt. Er verstand und akzeptierte seine Pflicht und wurde so ein leuchtendes Vorbild für alle aufstrebenden Blutritter.\n\nMeine Worte sind nicht als Grabesrede gedacht, <Name>. Stillstreichs Dienste für uns gehören noch lange nicht der Vergangenheit an und Ihr werdet das Instrument seiner Wiederauferstehung sein.\n\nEure Ausbildung in der Verwendung des Lichts hat sich bisher auf einfache Zauber und Tricks beschränkt. Es wird Zeit, dass Ihr die wahre Natur und Tiefe unserer Macht kennen lernt. Sucht Magister Astalor Blutschwur auf.", progress = nil, completion = "Willkommen junger &lt;Klasse&gt;.\n\nBlutritter beziehen ihre Kraft von einem Wesen immenser Macht.\n\n\n\nIst es nicht glorreich? Es war ein Geschenk von unserem geliebten Prinz Kael'thas und ist die Grundlage der Macht der Blutritter über das Licht. Diese Kreatur möchte uns diese Macht vorenthalten, also haben wir eine Methode erfunden, sie ihr zu nehmen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][64845] = {title = "Kriegsvorbereitungen der Allianz", objective = "Gewinnt eine Schlacht und meldet Euch anschließend bei einem Brigadegeneral der Allianz in einer der Hauptstädte oder in Shattrath.", description = "Ein Krieg steht uns bevor und die Allianz braucht mehr Kämpfer, um die Horde zu besiegen!\n\nUnsere Mission lautet, ihre Einsätze auf allen Schlachtfeldern zu vereiteln.\n\nIhr wollt Euch den Soldaten anschließen, oder?", progress = "Wie ist die Lage, <Name>? Gibt es Neuigkeiten von der Front?", completion = "Das sind gute Neuigkeiten, &lt;Klasse&gt;! Wenn Eure taktischen Einsätze weiterhin so erfolgreich verlaufen, wird die Horde sich wohl bald völlig zurückziehen müssen!", rewards = "Ihr bekommt:\n\nEinberufungsbonus"}
MultiLanguageQuestData['de'][65221] = {title = "1 instabiles Fläschchen des Zauberhexers für 10 Apexissplitter erwerben", objective = "Der Funkelmat 5200 erwacht hin und her schlingernd zum Leben. Innen wird der hilflose Schmutz, der das eingelegte Objekt verkrustet hat, vom Gnomenlösungsmittel der Maschine pulverisiert.\n\nDer Funkelmat 5200 kommt zum Stillstand, angekündigt durch ein vertrautes \"Ding!\". Der Aufnahmebehälter der Maschine springt auf und offenbart eine ordentlich eingewickelte Schachtel.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nInstabiles Fläschchen des Zauberers"}
MultiLanguageQuestData['de'][65223] = {title = "1 instabiles Fläschchen der Bestie für 10 Apexissplitter erwerben", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nInstabiles Fläschchen der Bestie"}
MultiLanguageQuestData['de'][65284] = {title = "Goblin-Gumbokessel", objective = "Grüße, <Klasse>, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch etwas auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals diesen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Booty Bay abholen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKessel mit Goblingumbo"}
MultiLanguageQuestData['de'][65285] = {title = "Goblin-Gumbokessel", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nKessel mit Goblingumbo"}
MultiLanguageQuestData['de'][65561] = {title = "Wappenrock der Flamme", objective = "Grüße, <Klasse>, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch etwas auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals diesen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWappenrock der Flamme"}
MultiLanguageQuestData['de'][65562] = {title = "Wappenrock der Flamme", objective = "Ah, ja. Bin ich froh, dass Ihr endlich aufgetaucht seid, um mir dieses Paket abzunehmen.\n\nUnsere gemeinsamen Freunde wollten, dass Ihr diese Belohnung im Gegenzug für einen Kauf Eurerseits erhaltet. Mehr will ich aber gar nicht wissen. Ich bin hier nur der Botenjunge.\n\nSolltet Ihr diesen Gegenstand jemals verlieren, kommt zu mir zurück, und ich ersetze ihn Euch kostenlos.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nWappenrock der Flamme"}
MultiLanguageQuestData['de'][65593] = {title = "Herzen der Liebenden", objective = "Bringt die Herzen von Avelina Lilly und Isaac Pearson zu Carendin Halgar im Tempel der Verdammten.", description = "Ein Inkubus wird von den Herzen Liebender angelockt. Die sehnlichste Liebe erschafft einen unwiderstehlichen Köder.\n\nMeine Wahrsagung hat mir zwei Personen gezeigt, die ganz besonders geeignet sein sollten.\n\nIm Silberwald bietet Avelina Lilly den gefallenen Magiern von Mühlenbern ihre Dienste als Schneiderin an. Im Brachland hofft Isaac Pearson, sich im Küstendorf Ratschet einen Namen zu machen.\n\nSie arbeiten an entgegengesetzten Enden der Welt, doch ihre Herzen sehnen sich nur nach einander. Bringt ihre Herzen zu Carendin.", progress = "Ah, <Name>, Ihr seid zurückgekehrt. Konntet Ihr die Herzen der Liebenden beschaffen?", completion = "Hervorragend gemacht, wie erwartet, &lt;Name&gt;.\n\n\n\nTrottel.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][65597] = {title = "Die Bindung", objective = "Beschwört mit den Herzen der Liebenden einen Inkubus, unterwerft ihn und bringt die Herzen der Liebenden dann zu Carendin Halgar im Magieviertel von Unterstadt zurück.", description = "Endlich ist es so weit. Bringt die Herzen zum Beschwörungskreis dort unten. Legt sie in die Mitte und ruft den Inkubus herbei.\n\nDer Dämon wird wenig erfreut sein, wenn er merkt, dass Ihr ihn in eine Falle gelockt habt. Lasst Euch nicht von ihm bezaubern, <Name>. Ihr müsst ihn vollständig unterwerfen.\n\nErst dann kann ich Euch den Zauber lehren, mit dem Ihr ihn an Euren Willen bindet.Ihr erlernt:\n\n", progress = nil, completion = nil, rewards = "Ihr erlernt:\n\nInkubus beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\n'Inkubus beschwören' lehren\n\nIhr bekommt außerdem:\n\nKleiner Seelenbeutel"}
MultiLanguageQuestData['de'][65601] = {title = "Liebe kann schmerzhaft sein", objective = "Sprecht mit Magar in Orgrimmar.", description = "Einen männlichen Sayaad nennt man einen Inkubus. Eine äußerst boshafte Kreatur, die nur eines im Sinn hat.\n\nDer Dämon muss mit einem Köder in unsere Welt gelockt werden, mit einem Gegenstand, der starke Liebe und Hingabe verkörpert.\n\nWenn Ihr Euch von einem Blinden führen lassen möchtet, <Name>, dann hört zu. Östlich von der Kluft der Schatten, in der Gasse von Orgrimmar, lebt Magar. Er wartet darauf, dass sein Lebensgefährte Krilge zurückkehrt.\n\nGeht zu ihm. Er wird Euch bitten, etwas Wertvolles zu suchen. Dies wird der Schlüssel sein, den Ihr dann Gan'rul bringen müsst.", progress = nil, completion = "Wer hat Euch von Krilge erzählt? Habt Ihr Neuigkeiten? Ihr treibt hoffentlich keine Spielchen mit mir...", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][65602] = {title = "Alles aus Liebe", objective = "Beschafft die Holzstatuette und bringt sie zu Gakin dem Dunkelbinder im Magierviertel von Sturmwind.", description = "Ihr werdet ein mächtiges Reagenz brauchen, um einen Inkubus anzulocken. Ein Objekt, das große Hingabe und Liebe verkörpert.\n\nDurch Wahrsagung habe ich eine kleine Statuette ausfindig gemacht, die für Euer Ritual geeignet sein sollte.\n\nVor Jahrtausenden gehörte die Figur einem jungen Paar. Die ursprünglichen Eigentümer sind verstorben, doch dieses Andenken besteht bis heute.\n\nFolgt der Straße nach Norden in das Eschental, dann Richtung Westen und an Maestras Posten vorbei. Ihr werdet ein Haus zwischen den Bäumen sehen. Dort findet Ihr, was Ihr sucht.", progress = "Ihr seid zurück. Darf ich davon ausgehen, dass Ihr Erfolg hattet?", completion = "&lt;Gakin dreht und wendet die Holzstatuette in seiner Hand.&gt;\n\nIch kann die Energie der Emotionen in diesem Artefakt spüren. Die Zeit konnte ihm nichts anhaben. Es wird den Inkubus anlocken wie eine Blüte die Biene.\n\nAuf Takar kann man sich verlassen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][65603] = {title = "Die Bindung", objective = "Beschwört mit Hilfe der Holzstatuette einen Inkubus, unterwerft ihn und bringt dann die Holzstatuette zu Gakin dem Dunkelbinder im geschlachteten Lamm zurück.", description = "Es ist so weit. Nehmt die Statuette und steigt in die Gruft hinab. Ein Beschwörungskreis ist bereits vorbereitet. Ihr müsst die Statuette in der Mitte platzieren.\n\nDann wird sich das Tor öffnen und der Inkubus wird in unsere Welt kommen.\n\nIhr dürft einen Sayaad nicht unterschätzen. Der Dämon wird Euch angreifen, sobald er Eure Täuschung bemerkt. Ihr müsst alles einsetzen, was Ihr gelernt habt, um ihn zu besiegen.\n\nWenn Ihr Erfolg habt, kehrt zu mir zurück und ich unterwerfe die Kreatur Eurem Willen. Wenn Ihr versagt, ist Eure Seele verwirkt.", progress = "Der Inkubus wird versuchen, Euch zu betören, zu täuschen und so zu überrumpeln. Der Dämon weiß genau, wie er die Herzen Sterblicher für sich gewinnt.\n\nDenkt daran, dass alle seine Versprechen Lügen sind. Für diesen Dämon seid Ihr nichts als Beute.", completion = "Nicht übel, &lt;Name&gt;. Ihr habt das Scheusal bezwungen und Euer Wille blieb ungebrochen.\n\nManch ein Hexenmeister hielt sich schon für stark genug, einen Sayaad an sich zu binden, und endete stattdessen als nächste Mahlzeit des Dämons. Es freut mich, dass Ihr nicht so töricht seid.\n\nSeht genau zu, dann lehre ich Euch die Anrufung, mit der Ihr Euren jetzt unterworfenen Inkubus beschwört.", rewards = "Ihr erlernt:\n\nInkubus beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\n'Inkubus beschwören' lehren\n\nIhr bekommt außerdem:\n\nKleiner Seelenbeutel"}
MultiLanguageQuestData['de'][65604] = {title = "Die Bindung", objective = "Beschwört mithilfe des abgetragenen Schals einen Inkubus, unterwerft ihn und bringt dann den abgetragenen Schal zu Gan'rul Blutauge in Orgrimmar zurück.", description = "Ja... verstehe. Ich kann die verbleibenden Emotionen spüren, die in diesem Stoff enthalten sind. Er ist mit Liebe verwoben. Dem wird der Inkubus nicht widerstehen können.\n\nBringt dies zum Beschwörungskreis in Neerus Zelt, <Name>. Beschwört einen boshaften Inkubus und zeigt ihm, dass Ihr Eure Fähigkeiten gemeistert habt. Rechnet damit, dass er sich nicht still und leise unterwerfen lässt. Haltet Eure Magie bereit und macht Euch auf einen Kampf gefasst. Schon so mancher Hexenmeister hat seinen letzten Fehler begangen, indem er einen Dämon unterschätzt hat.\n\nBringt den Stoff zu mir zurück, sobald Ihr ihn bezwungen habt. Ich werde Magar sagen, was Ihr herausgefunden habt.", progress = "Die Sayaad unterwerfen den Verstand und quälen Seelen. Ihr Antlitz erfreut das Herz, sodass Ihr wehrlos seid, wenn sie mit Peitschen und Klauen in Euer Fleisch reißen.\n\nLasst Euch vom Inkubus nicht betören, <Name>. Tötet ihn schnell und bringt es zu Ende.", completion = "Ha! Siegreich, wie ich es erwartet hatte!\n\nDer Inkubus wurde bezwungen, und ich werde Euch mit Freuden lehren, wie man den Dämon beschwört. Ihr werdet stärker und steht zweifelsohne davor, noch größere Macht zu erschließen.\n\nIch werde Magar den Schal zurückbringen. Ich kenne diesen Orc schon seit vielen Jahren und hätte nie gedacht, dass ihm einmal jemand so wie Krilge am Herzen liegen würde.\n\nDas erinnert uns daran, was uns von den Dämonen unterscheidet. Wir nutzen ihre Dunkelheit, lassen uns aber niemals von ihnen nutzen.", rewards = "Ihr erlernt:\n\nInkubus beschwören\n\nDer folgende Zauber wird auf euch gewirkt:\n\n'Inkubus beschwören' lehren\n\nIhr bekommt außerdem:\n\nKleiner Seelenbeutel"}
MultiLanguageQuestData['de'][65610] = {title = "Irgendwo anders", objective = "Untersucht den Himmelssturzsee im Eschental und erstattet Gan'rul Blutauge in Orgrimmar Bericht.", description = "Ich habe Krilge bei der Herstellung von Mondstoff im Eschental kennengelernt. Er war dort stationiert, um Zivilisten vor Gefahren zu beschützen, bis er dann verschwand...\n\nSie haben die Suche aufgegeben und sehen ihn als Deserteur, aber das glaube ich nicht.\n\nWir haben uns oft am Himmelssturzsee getroffen, bevor der von diesen aggressiven Sumpfmonstern überrannt wurde.\n\nIch bitte nur ungern andere um Gefallen, aber wenn Ihr ins Eschental gehen und nach ihm Ausschau halten könntet, wäre ich Euch dankbar.", progress = "Ja, was gibt's?", completion = "Was habt Ihr da, &lt;Name&gt;? Einen Schal aus... Mondstoff? Ihr wollt mich doch hoffentlich nicht bezirzen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][70354] = {title = "Nordendexpeditionsvorräte", objective = "Grüße, <Name>, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch diese Gegenstände auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals einen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nPebbles' KieselchenGlücksköder des Fischsprechers"}
MultiLanguageQuestData['de'][70395] = {title = "Ein Neuanfang", objective = "Besucht einen Trainer in Sturmwind, der Euch als <Klasse> ausbilden kann.", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Sturmwind, Hauptstadt der Allianz!\n\n<Ein/Eine:c> <Klasse> wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", progress = nil, completion = "Bereit für Eure Ausbildung, &lt;Volk&gt;?", rewards = "Ihr bekommt:\n\nAzerothüberlebenspaket"}
MultiLanguageQuestData['de'][70396] = {title = "Ein Neuanfang", objective = "Besucht einen Trainer in Orgrimmar, der Euch als <Klasse> ausbilden kann.", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Orgrimmar, Hauptstadt der Horde!\n\n<Ein/Eine:c> <Klasse> wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", progress = nil, completion = "Bereit für Eure Ausbildung, &lt;Volk&gt;?", rewards = "Ihr bekommt:\n\nAzerothüberlebenspaket"}
MultiLanguageQuestData['de'][70397] = {title = "Das Zeug zum Überleben", objective = "Öffnet das Überlebenspaket und legt eine Waffe an.", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", progress = "Ich habe ein Überlebenspaket für Eure Abenteuer zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Macht guten Gebrauch davon.", completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][70398] = {title = "Kampftraining", objective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als <Klasse> ausbilden kann.", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als <Klasse> wachsen.\n\nIhr könnt überall in Azeroth, sowie in Hauptstädten wie Sturmwind, Darnassus oder Eisenschmiede Trainer finden.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber diese eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", progress = "Wenn Ihr bereit seid, sprecht mich an, um Eure Fähigkeiten zu trainieren.", completion = "Ihr seht jetzt schon stärker aus, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][70401] = {title = "Talentiert", objective = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.", progress = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", completion = "Ihr seid bereit für den Kampf, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nTeleportrolle: Hafen von SturmwindTeleportrolle: Hafen von Menethil"}
MultiLanguageQuestData['de'][70411] = {title = "Zum Dockmeister", objective = "Benutzt die Schriftrolle der Teleportation, um den Hafen zu erreichen, und sprecht dort mit dem Dockmeister.", description = "Der Lichkönig muss für die Gräueltaten büßen, die er in unseren Landen angerichtet hat!\n\nAuf Anweisung von König Varian Wrynn wurdet Ihr gerufen, die Waffen zu ergreifen und den Schlachtzug der Allianz zur Erschaffung eines Stützpunkts auf dem heimtückischen Kontinent Nordend zu unterstützen.", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;. Ein Schiff nach Nordend wird bald dort am Ende des Docks anlegen. Schwingt Euch hinauf und die Mannschaft wird Euch wohlbehütet in dieses eisige, grausige Land transportieren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][70448] = {title = "Elitenordendexpeditionsvorräte", objective = "Grüße, <Name>, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch diese Gegenstände auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals einen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nPebbles' KieselchenGlücksköder des FischsprechersWalknochengleiter der Kalu'ak"}
MultiLanguageQuestData['de'][70449] = {title = "Elitenordendexpeditionsvorräte", objective = "Ah, ja. Bin ich froh, dass Ihr endlich aufgetaucht seid, um mir dieses Paket abzunehmen.\n\nUnsere gemeinsamen Freunde wollten, dass Ihr diese Belohnungen im Gegenzug für einen Kauf Eurerseits erhaltet. Mehr will ich aber gar nicht wissen. Ich bin hier nur der Botenjunge.\n\nSolltet Ihr diese Gegenstände jemals verlieren, kommt zu mir zurück, und ich ersetze sie Euch kostenlos.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nPebbles' KieselchenGlücksköder des FischsprechersWalknochengleiter der Kalu'ak"}
MultiLanguageQuestData['de'][70734] = {title = "Das Zeug zum Überleben", objective = "Öffnet das Überlebenspaket und legt eine Waffe an.", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", progress = "Ich habe ein Überlebenspaket für Eure Abenteuer zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Macht guten Gebrauch davon.", completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][70735] = {title = "Kampftraining", objective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als <Klasse> ausbilden kann.", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als <Klasse> wachsen.\n\nIhr könnt überall in Azeroth, sowie in Hauptstädten wie Orgrimmar, Donnerfels oder der Unterstadt Trainer finden.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber diese eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", progress = "Wenn Ihr bereit seid, sprecht mich an, um Eure Fähigkeiten zu trainieren.", completion = "Ihr seht jetzt schon stärker aus, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][70736] = {title = "Talentiert", objective = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.", progress = nil, completion = "Ihr seid bereit für den Kampf, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nTeleportrolle: Zeppelinturm von OrgrimmarTeleportrolle: Zeppelinturm von Unterstadt"}
MultiLanguageQuestData['de'][70737] = {title = "Zum Zeppelinmeister", objective = "Benutzt die Schriftrolle der Teleportation, um den Zeppelinturm zu erreichen, und sprecht dort mit dem Zeppelinmeister.", description = "Der Lichkönig muss für die Gräueltaten büßen, die er in unseren Landen angerichtet hat!\n\nAuf Anweisung von Kriegshäuptling Thrall wurdet Ihr gerufen, die Waffen zu ergreifen und den Schlachtzug der Horde zur Erschaffung eines Stützpunkts auf dem heimtückischen Kontinent Nordend zu unterstützen.", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;. Ein Zeppelin nach Nordend wird bald dort am Ende der Plattform landen. Schwingt Euch hinauf und die Mannschaft wird Euch wohlbehütet in dieses eisige, grausige Land transportieren!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][70761] = {title = "Das Zeug zum Überleben", objective = "Öffnet das Überlebenspaket und legt eine Waffe an.Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][70762] = {title = "Ein Neuanfang", objective = "Besucht einen Trainer in Donnerfels, der Euch als <Klasse> ausbilden kann.", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Donnerfels, Hauptstadt der Tauren!\n\n<Ein/Eine:c> <Klasse> wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", progress = nil, completion = "Bereit für Eure Ausbildung?", rewards = "Ihr bekommt:\n\nAzerothüberlebenspaket"}
