MultiLanguageQuestData['de'][70865] = {title = "Nach Shattrath", objective = "Benutzt eine Schriftrolle der Teleportation aus Eurem Inventar, um Shattrath zu erreichen, und sprecht dort mit dem mysteriösen hageren Kriegsveteran.", description = "Ihr habt eine mysteriöse Nachricht erhalten, die Euch in ein Land fern von Azeroth beordert.\n\nFolgt dem Aufruf und findet heraus, was es in diesen neuen Landen zu entdecken gibt.", progress = nil, completion = "Seid gegrüßt, &lt;Klasse&gt;. Danke, dass Ihr meinem Ruf gefolgt seid.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][70868] = {title = "Talentiert", objective = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTeleportrolle: Shattrath"}
