MultiLanguageQuestData['de'][70998] = {title = "Frosti", objective = "Grüße, <Name>, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch diese Gegenstände auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals einen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFrostis Halsband"}
MultiLanguageQuestData['de'][70999] = {title = "Frosti", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nFrostis Halsband"}
MultiLanguageQuestData['de'][72522] = {title = "Schwärender Smaragddrache", objective = "Grüße, <Name>, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch diese Gegenstände auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals einen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSchwärender Smaragddrache"}
MultiLanguageQuestData['de'][72523] = {title = "Schwärender Smaragddrache", objective = "Ah, ja. Bin ich froh, dass Ihr endlich aufgetaucht seid, um mir dieses Paket abzunehmen.\n\nUnsere gemeinsamen Freunde wollten, dass Ihr diese Belohnungen im Gegenzug für einen Kauf Eurerseits erhaltet. Mehr will ich aber gar nicht wissen. Ich bin hier nur der Botenjunge.\n\nSolltet Ihr diese Gegenstände jemals verlieren, kommt zu mir zurück, und ich ersetze sie Euch kostenlos.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nSchwärender Smaragddrache"}
MultiLanguageQuestData['de'][74940] = {title = "Flurky", objective = "Grüße, <Name>, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch diese Gegenstände auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals einen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBlau-goldenes Murlocei"}
MultiLanguageQuestData['de'][74941] = {title = "Flurky", objective = nil, description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nBlau-goldenes Murlocei"}
MultiLanguageQuestData['de'][75491] = {title = "Glub", objective = "Grüße, <Name>, ich habe Euch schon erwartet. Ein Bekannter von mir hat mich gebeten, Euch diese Gegenstände auszuhändigen, wenn Ihr vorbeikommt. Er hat von einer Belohnung gesprochen, die Euch für einen Kauf von gemeinsamen Freunden zusteht.\n\nVielleicht wisst Ihr ja, was er meinte?\n\nWie dem auch sei, hier ist Eure Belohnung. Oh, und noch etwas. Mein Bekannter, Landro Fernblick, meinte, falls Ihr jemals einen Gegenstand verliert, könnt Ihr Euch Ersatz bei ihm an den Docks von Beutebucht abholen.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGlub"}
MultiLanguageQuestData['de'][75492] = {title = "Glub", objective = "Ah, ja. Bin ich froh, dass Ihr endlich aufgetaucht seid, um mir dieses Paket abzunehmen.\n\nUnsere gemeinsamen Freunde wollten, dass Ihr diese Belohnungen im Gegenzug für einen Kauf Eurerseits erhaltet. Mehr will ich aber gar nicht wissen. Ich bin hier nur der Botenjunge.\n\nSolltet Ihr diese Gegenstände jemals verlieren, kommt zu mir zurück, und ich ersetze sie Euch kostenlos.", description = nil, progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nGlub"}
MultiLanguageQuestData['de'][78136] = {title = "Ein Neuanfang", objective = "Besucht einen Trainer in Sturmwind, der Euch als <Klasse> ausbilden kann.", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Sturmwind, Hauptstadt der Allianz!\n\n<Ein/Eine:c> <Klasse> wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", progress = nil, completion = "Bereit für Eure Ausbildung, &lt;Volk&gt;?", rewards = "Ihr bekommt:\n\nAzerothüberlebenspaket"}
MultiLanguageQuestData['de'][78137] = {title = "Ein Neuanfang", objective = "Besucht einen Trainer in Orgrimmar, der Euch als <Klasse> ausbilden kann.", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Orgrimmar, Hauptstadt der Horde!\n\n<Ein/Eine:c> <Klasse> wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", progress = nil, completion = "Bereit für Eure Ausbildung, &lt;Volk&gt;?", rewards = "Ihr bekommt:\n\nAzerothüberlebenspaket"}
MultiLanguageQuestData['de'][78138] = {title = "Ein Neuanfang", objective = "Besucht einen Trainer in Donnerfels, der Euch als <Klasse> ausbilden kann.", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Donnerfels, Hauptstadt der Tauren!\n\n<Ein/Eine:c> <Klasse> wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", progress = nil, completion = "Bereit für Eure Ausbildung?", rewards = "Ihr bekommt:\n\nAzerothüberlebenspaket"}
MultiLanguageQuestData['de'][78140] = {title = "Das Zeug zum Überleben", objective = "Öffnet das Überlebenspaket und legt eine Waffe an.", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", progress = nil, completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][78151] = {title = "Das Zeug zum Überleben", objective = "Öffnet das Überlebenspaket und legt eine Waffe an.", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", progress = "Ich habe ein Überlebenspaket für Eure Abenteuer zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Macht guten Gebrauch davon.", completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][78157] = {title = "Kampftraining", objective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als <Klasse> ausbilden kann.", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als <Klasse> wachsen.\n\nIhr könnt überall in Azeroth, sowie in Hauptstädten wie Sturmwind, Darnassus oder Eisenschmiede Trainer finden.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber dieses eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", progress = nil, completion = "Ihr seht jetzt schon stärker aus, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][78158] = {title = "Kampftraining", objective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als <Klasse> ausbilden kann.", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als <Klasse> wachsen.\n\nIhr könnt überall in Azeroth, sowie in Hauptstädten wie Orgrimmar, Donnerfels oder der Unterstadt Trainer finden.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber dieses eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", progress = "Wenn Ihr bereit seid, sprecht mich an, um Eure Fähigkeiten zu trainieren.", completion = "Ihr seht jetzt schon stärker aus, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][78164] = {title = "Talentiert", objective = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.", progress = nil, completion = "Ihr seid bereit für den Kampf, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nTeleportrolle: Nordend"}
MultiLanguageQuestData['de'][78165] = {title = "Talentiert", objective = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.Ihr bekommt:\n\n", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTeleportrolle: Zeppelinturm von OrgrimmarTeleportrolle: Zeppelinturm von Unterstadt"}
MultiLanguageQuestData['de'][78166] = {title = "Nach Nordend", objective = "Benutzt eine Schriftrolle der Teleportation aus Eurem Inventar, um Nordend zu erreichen, und sprecht dort mit dem Abbild der Erzmagierin Modera.", description = "Der Lichkönig muss für die Gräueltaten büßen, die er in unseren Landen angerichtet hat!\n\nAuf Anweisung von König Varian Wrynn wurdet Ihr gerufen, die Waffen zu ergreifen und den Schlachtzug der Allianz beim Sieg über den Lichkönig zu unterstützen.", progress = nil, completion = "Grüße, &lt;Klasse&gt;, und willkommen in den frostigen Landen von Nordend. Ihr kommt gerade rechtzeitig. Wir haben viel zu besprechen, vor allem wie wir Euch in die schwebende Stadt Dalaran schaffen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][78167] = {title = "Talentiert", objective = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.", progress = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", completion = "Ihr seid bereit für den Kampf, &lt;Name&gt;!", rewards = "Ihr bekommt:\n\nTeleportrolle: Nordend"}
MultiLanguageQuestData['de'][78168] = {title = "Nach Nordend", objective = "Benutzt eine Schriftrolle der Teleportation aus Eurem Inventar, um Nordend zu erreichen, und sprecht dort mit dem Abbild des Erzmagiers Aethas Sonnenhäscher.", description = "Der Lichkönig muss für die Gräueltaten büßen, die er in unseren Landen angerichtet hat!\n\nAuf Anweisung von Kriegshäuptling Thrall wurdet Ihr gerufen, die Waffen zu ergreifen und den Schlachtzug der Horde beim Sieg über den Lichkönig zu unterstützen.", progress = nil, completion = "Grüße, &lt;Klasse&gt;, und willkommen in den frostigen Landen von Nordend. Ihr kommt gerade rechtzeitig. Wir haben viel zu besprechen, vor allem wie wir Euch in die schwebende Stadt Dalaran schaffen!", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][78219] = {title = "Ein Neuanfang", objective = "Besucht einen Trainer in Acherus, der Schwarzen Festung, der Euch als <Klasse> ausbilden kann.", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Acherus, der Schwarzen Festung, Zuflucht für alle Todesritter, die dem Lichkönig entsagen!\n\n<Ein/Eine:c> <Klasse> wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", progress = nil, completion = "Bereit für Eure Ausbildung, &lt;Volk&gt;?", rewards = "Ihr bekommt:\n\nAzerothüberlebenspaket"}
MultiLanguageQuestData['de'][78220] = {title = "Das Zeug zum Überleben", objective = "Öffnet das Überlebenspaket und legt eine Waffe an.", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.", progress = nil, completion = "Ihr seht bereit aus! Schreiten wir zur ersten Lektion der Kampfausbildung.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][78221] = {title = "Kampftraining", objective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als <Klasse> ausbilden kann.", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als <Klasse> wachsen.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber dieses eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", progress = nil, completion = "Ihr seht jetzt schon stärker aus, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][78223] = {title = "Nach Nordend", objective = "Benutzt eine Schriftrolle der Teleportation aus Eurem Inventar, um Nordend zu erreichen, und sprecht dort mit dem Abbild der Erzmagierin Modera.", description = "Der Lichkönig muss für die Gräueltaten büßen, die er in unseren Landen angerichtet hat!\n\nAuf Anweisung der Ritter der Schwarzen Klinge wurdet Ihr gerufen, die Waffen zu ergreifen und den Schlachtzug der Allianz beim Sieg über den Lichkönig zu unterstützen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][78225] = {title = "Nach Nordend", objective = "Benutzt eine Schriftrolle der Teleportation aus Eurem Inventar, um Nordend zu erreichen, und sprecht dort mit dem Abbild des Erzmagiers Aethas Sonnenhäscher.", description = "Der Lichkönig muss für die Gräueltaten büßen, die er in unseren Landen angerichtet hat!\n\nAuf Anweisung der Ritter der Schwarzen Klinge wurdet Ihr gerufen, die Waffen zu ergreifen und den Schlachtzug der Horde beim Sieg über den Lichkönig zu unterstützen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][78752] = {title = "Todesbeweise: Titanenrune mit Protokoll Gamma", objective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr ihm ein Medaillon der Entweihten von einem beliebigen, finalen Dungeonboss bringt.\n\nDiese Quest kann nur in einem Titanenrunendungeon mit aktivem Protokoll Gamma abgeschlossen werden.", description = "Die Präsenz des Lichkönigs darf sich nicht weiter ausbreiten!\n\nDer Rat der Sechs hat erlassen, dass alle, die stark genug sind, zu den Waffen greifen und dabei helfen sollen, Azeroth zu bewahren!", progress = "Wir sprechen uns erneut, <Name>. Bedeutet das, dass Ihr in der Erfüllung Eurer Pflichten erfolgreich wart?", completion = "Welch Übel sich darin verbirgt!\n\nIch werde es für weitere Untersuchungen zurück zum Rat der Sechs bringen.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][78753] = {title = "Todesbeweise: Bedrohungen für Azeroth", objective = "Erzmagier Lan'dalock in Dalaran möchte, dass Ihr ihm ein geheimnisvolles Artefakt von einem beliebigen, finalen Dungeonboss bringt.\n\nDiese Quest kann nur in einem heroischen Dungeon abgeschlossen werden.", description = "Wir müssen den Druck an allen Fronten weiter aufrechthalten!\n\nDer Rat der Sechs hat erlassen, dass alle gewillten Kämpfer zu den Waffen greifen und dabei helfen sollen, Azeroth zu bewahren!", progress = "Wo liegt das Problem? Warum habt Ihr noch keine dieser Bedrohungen beseitigt?", completion = "Was für ein interessanter Fund!\n\nIch werde ihn für weitere Untersuchungen zurück zum Rat der Sechs bringen.", rewards = "Ihr bekommt:\n\nGerechtigkeitspunkte"}
MultiLanguageQuestData['de'][82948] = {title = "Heldenruftafel", objective = "Begebt Euch in den Handelsdistrikt in Sturmwind und sprecht mit Melris Malagan.", description = "Auf Befehl von König Varian Wrynn habe ich die Aufgabe, alle Vertreterinnen und Vertreter der Klasse '<Klasse>' zu den Waffen zu rufen, auf dass sie bei den Feldzügen der Allianz in ganz Azeroth helfen mögen!\n\n\n Ihr seid bereit, $p.", progress = nil, completion = "Seid gegrüßt, &lt;Volk&gt;. Ich sehe, dass Ihr König Wrynns Ruf gefolgt seid.\n\nNeben mir befindet sich die Heldenruftafel, auf der Ihr eine Liste mit aktuellen Aufträgen seht. Schaut sie Euch an und entscheidet, welchen Ihr übernehmen wollt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\n[DNT] Cancel Level 80 Character Boost Dummy Aura\n\nIhr bekommt:\n\n"}
MultiLanguageQuestData['de'][82949] = {title = "Befehlstafel des Kriegshäuptlings", objective = "Begebt Euch ins Tal der Stärke in Orgrimmar und sprecht mit dem Herold des Kriegshäuptlings.", description = "Auf Befehl von Kriegshäuptling Garrosh Höllschrei habe ich die Aufgabe, alle Vertreterinnen und Vertreter der Klasse '<Klasse>' zu den Waffen zu rufen, auf dass sie bei den Feldzügen der Horde in ganz Azeroth helfen mögen!\n\n\n Ihr seid bereit, $p.", progress = nil, completion = "Lok'tar, &lt;Volk&gt;. Ich sehe, dass Ihr dem Ruf des Kriegshäuptlings gefolgt seid.\n\nNeben mir befindet sich die Befehlstafel des Kriegshäuptlings, auf der Ihr eine Liste mit aktuellen Aufträgen seht. Schaut sie Euch an und entscheidet, welchen Ihr übernehmen wollt.", rewards = "Der folgende Zauber wird auf euch gewirkt:\n\n[DNT] Cancel Level 80 Character Boost Dummy Aura\n\nIhr bekommt:\n\n"}
