MultiLanguageQuestData['de'][82985] = {title = "Befehlstafel des Kriegshäuptlings", objective = "Nutzt eine Schriftrolle der Teleportation aus Eurem Inventar, um Orgrimmar zu erreichen, und sprecht dort mit dem Herold des Kriegshäuptlings.", description = "Kriegshäuptling Garrosh Höllschrei hat die Ritter der Schwarzen Klinge gebeten, alle Vertreterinnen und Vertreter der Klasse '<Klasse>' zu den Waffen zu rufen, auf dass sie bei den Feldzügen der Horde in ganz Azeroth helfen mögen!\n\nIhr seid bereit, $p.", progress = nil, completion = "Lok'tar, &lt;Volk&gt;. Ich sehe, dass Ihr dem Ruf des Kriegshäuptlings gefolgt seid.\n\nNeben mir befindet sich die Befehlstafel des Kriegshäuptlings, auf der Ihr eine Liste mit aktuellen Aufträgen seht. Schaut sie Euch an und entscheidet, welchen Ihr übernehmen wollt.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][82987] = {title = "Talentiert", objective = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTeleportrolle: Orgrimmar"}
MultiLanguageQuestData['de'][82988] = {title = "Talentiert", objective = "Öffnet das Talentfenster und verteilt 5 Talentpunkte.", description = "Es gibt verschiedene Wege, Fähigkeiten und Talente einzusetzen. Unsere persönlichen Interessen und Neigungen unterscheiden uns voneinander.\n\nEure Macht wird zweifellos wachsen und mit ihr einher gehen Talente, mit denen Ihr Eure Fähigkeiten verbessern und spezialisieren könnt. Dafür braucht Ihr nicht die Hilfe eines Trainers.\n\nSolltet Ihr Eure Meinung zu Euren Talenten ändern, könnt Ihr sie bei einem Trainer für Eure Klasse zurücksetzen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTeleportrolle: Orgrimmar"}
MultiLanguageQuestData['de'][82989] = {title = "Befehlstafel des Kriegshäuptlings", objective = "Nutzt eine Schriftrolle der Teleportation aus Eurem Inventar, um Orgrimmar zu erreichen, und sprecht dort mit dem Herold des Kriegshäuptlings.", description = "Auf Befehl von Kriegshäuptling Garrosh Höllschrei habe ich die Aufgabe, alle Vertreterinnen und Vertreter der Klasse '<Klasse>' zu den Waffen zu rufen, auf dass sie bei den Feldzügen der Horde in ganz Azeroth helfen mögen!\n\n\n Ihr seid bereit, $p.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][88776] = {title = "Ein Neuanfang", objective = "Besucht einen Trainer in Sturmwind, der Euch als <Klasse> ausbilden kann.", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Sturmwind, Hauptstadt der Allianz!\n\n<Ein/Eine:c> <Klasse> wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"", progress = nil, completion = "Bereit für Eure Ausbildung, &lt;Volk&gt;?", rewards = "Ihr bekommt:\n\nAzerothüberlebenspaket"}
MultiLanguageQuestData['de'][88777] = {title = "Ein Neuanfang", objective = "Besucht einen Trainer in Acherus, der Schwarzen Festung, der Euch als <Klasse> ausbilden kann.", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Acherus, der Schwarzen Festung, Zuflucht für alle Todesritter, die dem Lichkönig entsagen!\n\n<Ein/Eine:c> <Klasse> wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAzerothüberlebenspaket"}
MultiLanguageQuestData['de'][88778] = {title = "Ein Neuanfang", objective = "Besucht einen Trainer in Orgrimmar, der Euch als <Klasse> ausbilden kann.", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Orgrimmar, Hauptstadt der Horde!\n\n<Ein/Eine:c> <Klasse> wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAzerothüberlebenspaket"}
MultiLanguageQuestData['de'][88779] = {title = "Ein Neuanfang", objective = "Besucht einen Trainer in Donnerfels, der Euch als <Klasse> ausbilden kann.", description = "Ein Brief erscheint auf magische Weise im Futter Eurer Rüstung. In ihm steht:\n\n\"Willkommen in Donnerfels, Hauptstadt der Tauren!\n\n<Ein/Eine:c> <Klasse> wie Ihr sollte sich an einen unserer Ausbilder wenden, um mit dem Training zu beginnen. Sie werden Euch auf Eure Reisen durch Azeroth und darüber hinaus vorbereiten.\"Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nAzerothüberlebenspaket"}
MultiLanguageQuestData['de'][88780] = {title = "Das Zeug zum Überleben", objective = "Öffnet das Überlebenspaket und legt eine Waffe an.", description = "Bevor wir beginnen, müsst Ihr mit den richtigen Waffen und Rüstungsteilen für Eure Fähigkeiten ausgestattet werden. Das Abenteurerleben ist nie langweilig und man weiß nie, was einen erwartet!\n\nIch habe Euch ein Überlebenspaket zusammengestellt. Es enthält zusätzliche Waffen, Rüstung und Proviant. Ich denke, Ihr werdet guten Gebrauch davon machen.Ihr bekommt:\n\nBei Abschluss dieser Quest erhaltet Ihr:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\n"}
