MultiLanguageQuestData['de'][88783] = {title = "Kampftraining", objective = "Erlernt eine Fähigkeit, indem Ihr mit einem Trainer sprecht, der Euch als <Klasse> ausbilden kann.", description = "Mit Eurer Macht werden auch Eure Fähigkeiten als <Klasse> wachsen.\n\nIhr könnt überall in Azeroth, sowie in Hauptstädten wie Sturmwind, Darnassus oder Eisenschmiede Trainer finden.\n\nDieses Wissen hat für gewöhnlich seinen Preis, aber dieses eine Mal erstatte ich ihn Euch. Wenn Ihr bereit seid, sucht mich wieder auf, um Eure Fähigkeiten zu trainieren.", progress = nil, completion = "Ihr seht jetzt schon stärker aus, &lt;Volk&gt;.", rewards = "Ihr bekommt:\n\n"}
