MultiLanguageQuestData['de'][91701] = {title = "Eine erhabene Herausforderung: Dunkelmeister Gandling", objective = "Schließt den Dungeon von Scholomance auf erhabener Schwierigkeitsstufe ab.", description = "<Name>, die Erhabenen brauchen Eure Hilfe. Stellt eine furchtlose Gruppe zusammen und führt sie in die Tiefen von Scholomance. Reinigt Scholomance von der finsteren Präsenz von Dunkelmeister Gandling.\n\nKehrt zu mir zurück, wenn Ihr diese erhabene Aufgabe erledigt habt, und ich werde Euch fürstlich belohnen.", progress = nil, completion = "&lt;Name&gt;, Ihr habt uns einen großen Dienst erwiesen. Hoffen wir, dass die Gebeine der Toten endlich in Frieden ruhen können, nun, da Gandling sie nicht mehr stören wird.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteHimmelssteinfragment"}
MultiLanguageQuestData['de'][91702] = {title = "Eine erhabene Herausforderung: Dunkelmeister Gandling", objective = "Schließt den Dungeon von Scholomance auf erhabener Schwierigkeitsstufe ab.", description = "<Name>, die Erhabenen brauchen Eure Hilfe. Stellt eine furchtlose Gruppe zusammen und führt sie in die Tiefen von Scholomance. Reinigt Scholomance von der finsteren Präsenz von Dunkelmeister Gandling.\n\nKehrt zu mir zurück, wenn Ihr diese erhabene Aufgabe erledigt habt, und ich werde Euch fürstlich belohnen.", progress = nil, completion = "&lt;Name&gt;, Ihr habt uns einen großen Dienst erwiesen. Hoffen wir, dass die Gebeine der Toten endlich in Frieden ruhen können, nun, da Gandling sie nicht mehr stören wird.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteHimmelssteinfragment"}
MultiLanguageQuestData['de'][91703] = {title = "Eine erhabene Herausforderung: Flammenwirker Koegler", objective = "Schließt den Dungeon der Scharlachroten Hallen auf erhabener Schwierigkeitsstufe ab.", description = "<Name>, die Erhabenen brauchen Eure Hilfe. Stellt eine gewitzte Gruppe zusammen und führt sie in die Tiefen der Scharlachroten Hallen. Beschwört die Macht der Erhabenen und setzt dem bücherverbrennenden Treiben von Flammenwirker Koegler ein Ende.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteHimmelssteinfragment"}
MultiLanguageQuestData['de'][91704] = {title = "Eine erhabene Herausforderung: Flammenwirker Koegler", objective = "Schließt den Dungeon der Scharlachroten Hallen auf erhabener Schwierigkeitsstufe ab.", description = "<Name>, die Erhabenen brauchen Eure Hilfe. Stellt eine gewitzte Gruppe zusammen und führt sie in die Tiefen der Scharlachroten Hallen. Beschwört die Macht der Erhabenen und setzt dem bücherverbrennenden Treiben von Flammenwirker Koegler ein Ende.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteHimmelssteinfragment"}
MultiLanguageQuestData['de'][91705] = {title = "Eine erhabene Herausforderung: Durand", objective = "Schließt das Scharlachrote Kloster auf erhabener Schwierigkeitsstufe ab.", description = "<Name>, die Erhabenen brauchen Eure Hilfe. Stellt eine tapfere Gruppe zusammen und führt sie ins Scharlachrote Kloster. Beschwört die Macht der Erhabenen und zerschmettert Durand mit gerechtem Zorn.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", progress = nil, completion = "&lt;Name&gt;, Ihr seid ein tapferer &lt;Klasse&gt;. Eure Freunde und Eure Gilde werden über die Geschwindigkeit und Wildheit staunen, mit der Ihr das Scharlachrote Kloster erobert habt.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteHimmelssteinfragment"}
MultiLanguageQuestData['de'][91706] = {title = "Eine erhabene Herausforderung: Durand", objective = "Schließt das Scharlachrote Kloster auf erhabener Schwierigkeitsstufe ab.", description = "<Name>, die Erhabenen brauchen Eure Hilfe. Stellt eine tapfere Gruppe zusammen und führt sie ins Scharlachrote Kloster. Beschwört die Macht der Erhabenen und zerschmettert Durand mit gerechtem Zorn.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", progress = nil, completion = "&lt;Name&gt;, Ihr seid ein tapferer &lt;Klasse&gt;. Eure Freunde und Eure Gilde werden über die Geschwindigkeit und Wildheit staunen, mit der Ihr das Scharlachrote Kloster erobert habt.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteHimmelssteinfragment"}
MultiLanguageQuestData['de'][91707] = {title = "Eine erhabene Herausforderung: Schwadronsführer Ner'onok", objective = "Schließt die Belagerung des Niuzaotempels auf erhabener Schwierigkeitsstufe ab.", description = "<Name>, die Erhabenen brauchen Eure Hilfe. Stellt eine scharfsichtige Gruppe zusammen und führt sie zur Belagerung des Niuzaotempels. Beschwört die Macht der Erhabenen und bringt Schwadronsführer Ner'onok zu Boden.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", progress = nil, completion = "&lt;Name&gt;, das war unglaublich. Ner'onok ist ein Meistertaktiker, doch Ihr habt ihm eine schmerzliche Lektion erteilt.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteHimmelssteinfragment"}
MultiLanguageQuestData['de'][91708] = {title = "Eine erhabene Herausforderung: Schwadronsführer Ner'onok", objective = "Schließt die Belagerung des Niuzaotempels auf erhabener Schwierigkeitsstufe ab.", description = "<Name>, die Erhabenen brauchen Eure Hilfe. Stellt eine scharfsichtige Gruppe zusammen und führt sie zur Belagerung des Niuzaotempels. Beschwört die Macht der Erhabenen und bringt Schwadronsführer Ner'onok zu Boden.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", progress = nil, completion = "&lt;Name&gt;, das war unglaublich. Ner'onok ist ein Meistertaktiker, doch Ihr habt ihm eine schmerzliche Lektion erteilt.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteHimmelssteinfragment"}
MultiLanguageQuestData['de'][91709] = {title = "Eine erhabene Herausforderung: Raigonn", objective = "Schließt das Tor der Untergehenden Sonne auf erhabener Schwierigkeitsstufe ab.", description = "<Name>, die Erhabenen brauchen Eure Hilfe. Stellt eine erstklassige Gruppe zusammen und führt sie zum Tor der Untergehenden Sonne. Beschwört die Macht der Erhabenen und vernichtet Raigonn.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.Ihr bekommt:\n\n", progress = nil, completion = nil, rewards = "Ihr bekommt:\n\nTapferkeitspunkteHimmelssteinfragment"}
MultiLanguageQuestData['de'][91710] = {title = "Eine erhabene Herausforderung: Raigonn", objective = "Schließt das Tor der Untergehenden Sonne auf erhabener Schwierigkeitsstufe ab.", description = "<Name>, die Erhabenen brauchen Eure Hilfe. Stellt eine erstklassige Gruppe zusammen und führt sie zum Tor der Untergehenden Sonne. Beschwört die Macht der Erhabenen und vernichtet Raigonn.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", progress = nil, completion = "Das war ein wahres Meisterstück, &lt;Name&gt;. Ich habe noch nie jemanden so schnell einen Riesen zu Fall bringen sehen, &lt;Klasse&gt;.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteHimmelssteinfragment"}
MultiLanguageQuestData['de'][91711] = {title = "Eine erhabene Herausforderung: Xin der Waffenmeister", objective = "Schließt den Mogu'shanpalast auf erhabener Schwierigkeitsstufe ab.", description = "<Name>, die Erhabenen brauchen Eure Hilfe. Stellt eine flinke Gruppe zusammen und führt sie zum Mogu'shanpalast. Beschwört die Macht der Erhabenen und macht Xin dem Waffenmeister ein Ende.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", progress = nil, completion = "Vielen Dank, &lt;Name&gt;. Eure Kampfkunst sucht ihresgleichen, und Eure Eilfertigkeit wird die Herzen Eurer Widersacher mit Furcht erfüllen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteHimmelssteinfragment"}
MultiLanguageQuestData['de'][91712] = {title = "Eine erhabene Herausforderung: Xin der Waffenmeister", objective = "Schließt den Mogu'shanpalast auf erhabener Schwierigkeitsstufe ab.", description = "<Name>, die Erhabenen brauchen Eure Hilfe. Stellt eine flinke Gruppe zusammen und führt sie zum Mogu'shanpalast. Beschwört die Macht der Erhabenen und macht Xin dem Waffenmeister ein Ende.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", progress = nil, completion = "Vielen Dank, &lt;Name&gt;. Eure Kampfkunst sucht ihresgleichen, und Eure Eilfertigkeit wird die Herzen Eurer Widersacher mit Furcht erfüllen.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteHimmelssteinfragment"}
MultiLanguageQuestData['de'][91713] = {title = "Eine erhabene Herausforderung: Sha des Hasses", objective = "Schließt das Shado-Pan-Kloster auf erhabener Schwierigkeitsstufe ab.", description = "<Name>, die Erhabenen brauchen Eure Hilfe. Stellt eine ruhige Gruppe zusammen und führt sie zum Shado-Pan-Kloster. Beschwört die Macht der Erhabenen und rettet Taran Zhu vor dem Sha des Hasses.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", progress = nil, completion = "Seid reich gesegnet, &lt;Name&gt;. Diese Welt so schnell vom Hass zu befreien, ist eine Leistung, die großzügig belohnt werden sollte.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteHimmelssteinfragment"}
MultiLanguageQuestData['de'][91714] = {title = "Eine erhabene Herausforderung: Sha des Hasses", objective = "Schließt das Shado-Pan-Kloster auf erhabener Schwierigkeitsstufe ab.", description = "<Name>, die Erhabenen brauchen Eure Hilfe. Stellt eine ruhige Gruppe zusammen und führt sie zum Shado-Pan-Kloster. Beschwört die Macht der Erhabenen und rettet Taran Zhu vor dem Sha des Hasses.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", progress = nil, completion = "Seid reich gesegnet, &lt;Name&gt;. Diese Welt so schnell vom Hass zu befreien, ist eine Leistung, die großzügig belohnt werden sollte.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteHimmelssteinfragment"}
MultiLanguageQuestData['de'][91715] = {title = "Eine erhabene Herausforderung: Yan-Zhu der Dekantierte", objective = "Schließt die Brauerei Sturmbräu auf erhabener Schwierigkeitsstufe ab.", description = "<Name>, die Erhabenen brauchen Eure Hilfe. Stellt eine beherzte Gruppe zusammen und führt sie zur Brauerei Sturmbräu. Beschwört die Macht der Erhabenen und helft Yan-Zhu dem Dekantierten, sich zu verdünnisieren.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", progress = nil, completion = "Meinen aufrichtigen Dank, &lt;Name&gt;. Wenn es kein Sturmbräu gäbe, um die Sorgen nach einem harten Tag hinunterzuspülen, wäre die Welt ein wahrlich trister Ort.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteHimmelssteinfragment"}
MultiLanguageQuestData['de'][91716] = {title = "Eine erhabene Herausforderung: Yan-Zhu der Dekantierte", objective = "Schließt die Brauerei Sturmbräu auf erhabener Schwierigkeitsstufe ab.", description = "<Name>, die Erhabenen brauchen Eure Hilfe. Stellt eine beherzte Gruppe zusammen und führt sie zur Brauerei Sturmbräu. Beschwört die Macht der Erhabenen und helft Yan-Zhu dem Dekantierten, sich zu verdünnisieren.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", progress = nil, completion = "Meinen aufrichtigen Dank, &lt;Name&gt;. Wenn es kein Sturmbräu gäbe, um die Sorgen nach einem harten Tag hinunterzuspülen, wäre die Welt ein wahrlich trister Ort.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteHimmelssteinfragment"}
MultiLanguageQuestData['de'][91717] = {title = "Eine erhabene Herausforderung: Sha des Zweifels", objective = "Schließt den Tempel der Jadeschlange auf erhabener Schwierigkeitsstufe ab.", description = "<Name>, die Erhabenen brauchen Eure Hilfe. Stellt eine beherzte Gruppe zusammen und führt sie zum Tempel der Jadeschlange. Beschwört die Macht der Erhabenen und vernichtet das Sha des Zweifels.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", progress = nil, completion = "Mein Dank ist Euch gewiss, &lt;Name&gt;. Ihr habt heute großen Mut an den Tag gelegt und die Herausforderung in Windeseile bewältigt. Eure Freunde werden beeindruckt und Eure Gegner verängstigt sein.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteHimmelssteinfragment"}
MultiLanguageQuestData['de'][91718] = {title = "Eine erhabene Herausforderung: Sha des Zweifels", objective = "Schließt den Tempel der Jadeschlange auf erhabener Schwierigkeitsstufe ab.", description = "<Name>, die Erhabenen brauchen Eure Hilfe. Stellt eine beherzte Gruppe zusammen und führt sie zum Tempel der Jadeschlange. Beschwört die Macht der Erhabenen und vernichtet das Sha des Zweifels.\n\nKehrt zu mir zurück, wenn Ihr diese Aufgabe abgeschlossen habt, und ich werde Euch fürstlich belohnen.", progress = nil, completion = "Mein Dank ist Euch gewiss, &lt;Name&gt;. Ihr habt heute großen Mut an den Tag gelegt und die Herausforderung in Windeseile bewältigt. Eure Freunde werden beeindruckt und Eure Gegner verängstigt sein.", rewards = "Ihr bekommt:\n\nTapferkeitspunkteHimmelssteinfragment"}
MultiLanguageQuestData['de'][91786] = {title = "Wenn der Zweifel nagt", objective = "Bezwingt das Sha des Zweifels im Tempel der Jadeschlange auf erhabener Schwierigkeitsstufe und holt Euch die Schimäre des Zweifels.", description = "Während meiner Zeit hier habe ich die eine oder andere Pandarenweisheit aufgeschnappt. Ganz besonders gefällt mir diese hier:\n\n\"Die Zaghaften zweifeln, bevor es Probleme gibt, die Feiglinge zweifeln, wenn es Probleme gibt. Die Tapfersten unter uns aber zweifeln erst, wenn alle Probleme überstanden sind.\"\n\nOb das wirklich stimmt, wage ich zu bezweifeln, aber ich zähle mich nicht zu den Zaghaften.\n\nDas Sha des Zweifels ist in den Tempel der Jadeschlange geflohen. Verfolgt es, besiegt es, und reißt ihm den Geist heraus. Dafür werdet Ihr die Hilfe der Erhabenen benötigen.", progress = "Noch eine pandarische Weisheit: \"Nicht das Scheitern fürchten wir, sondern den Zweifel selbst.\" Indem wir uns unseren Zweifeln stellen, gewinnen wir große Stärke.\n\nHabt Ihr Euch Euren Zweifeln gestellt, <Name>?", completion = "Ihr habt es geschafft!\n\nManche mögen ja auf Magie oder Stahl vertrauen, doch nach meiner Erfahrung ist der Zweifel die mächtigste Waffe, die man gegen seine Feinde führen kann. Setzt sie gekonnt ein, und Eure Gegner werden gar nicht erst gegen Euch kämpfen.", rewards = "Ihr bekommt:\n\n"}
MultiLanguageQuestData['de'][92336] = {title = "Meister der Tränke", objective = "Bringt eine große Anzahl Tränke zu einem Alchemielehrer in einer beliebigen Hauptstadt.", description = "Tränke, Tränke, Tränke. Was ich Euch alles über Tränke beibringen könnte!\n\nBringt mir Proben Eurer Arbeit, damit ich weiß, dass Ihr bereit dazu seid.\n\nVergesst nicht, <Name>, dass Ihr nur EINE Spezialisierung erlernen könnt. Wenn Ihr die Tränkebeherrschung abgeschlossen habt, werden Euch Spezialisierungen für Tränke und Transmutationen nicht mehr angeboten.", progress = "Habt Ihr die Tränke?", completion = "Hervorragend!", rewards = "Ihr erlernt:\n\nMeister der Tränke\n\nDer folgende Zauber wird auf euch gewirkt:\n\nMeister der Tränke"}
MultiLanguageQuestData['de'][92337] = {title = "Meister der Elixiere", objective = "Bringt eine Reihe verschiedener Fläschchen zu einem Alchemielehrer in einer beliebigen Hauptstadt.", description = "Bei Elixieren geht es nur um Stärke! Ich kann Euch zum Meister der Elixiere ausbilden, wenn Ihr das wünscht.\n\nDas ist nichts für jeden und ich verlange einen Beweis für Eure Ernsthaftigkeit, bevor wir fortfahren können. Mit einigen Fläschchen könnt Ihr mir Eure Entschlossenheit zeigen.\n\nVergesst nicht, <Name>, dass Ihr nur EINE Spezialisierung erlernen könnt. Wenn Ihr die Elixierbeherrschung abgeschlossen habt, werden Euch Spezialisierungen für Tränke und Transmutationen nicht mehr angeboten.", progress = "Habt Ihr die Fläschchen?", completion = "Sehr gut!", rewards = "Ihr erlernt:\n\nMeister der Elixiere\n\nDer folgende Zauber wird auf euch gewirkt:\n\nMeister der Elixiere"}
MultiLanguageQuestData['de'][92338] = {title = "Meister der Transmutation", objective = "Bringt die verlangten Materialien zu einem Alchemielehrer in einer beliebigen Hauptstadt.", description = "Eisen zu Gold, Wasser zu Feuer... Ich kann Euch helfen, wenn Ihr die Transmutation meistern wollt.\n\nDie Ausbildung ist sehr teuer, also müsst Ihr mir einige der besten transmutierten Materialien der Welt bringen.\n\nVergesst nicht, <Name>, dass Ihr nur EINE Spezialisierung erlernen könnt. Wenn Ihr die Transmutationsbeherrschung abgeschlossen habt, werden Euch Spezialisierungen für Tränke und Transmutationen nicht mehr angeboten.", progress = "Habt Ihr die Materialien?", completion = "Sehr gut!", rewards = "Ihr erlernt:\n\nMeister der Transmutation\n\nDer folgende Zauber wird auf euch gewirkt:\n\nMeister der Transmutation"}
